func (checker staticOperatorChecker) checkReduceTypes(ctx context.Context, form reduceForm) (staticOperand, error) {
	source, err := checker.check(ctx, form.list)
	if err != nil {
		return staticOperand{}, err
	}
	if source.excludes(isListTypeName) {
		return staticOperand{}, operandMismatch(source, "List<T>")
	}
	initial, err := checker.check(ctx, form.initial)
	if err != nil {
		return staticOperand{}, err
	}
	types := typeScopeOf(checker.scope)
	types[form.variable] = source.elementOperand()
	types[form.accumulator] = reduceAccumulatorOperand(initial)
	nested := staticOperatorChecker{scope: types.static(checker.scope.cypher25), params: checker.params}
	nested.scope.complete = checker.scope.complete
	nested.scope.params = checker.scope.params
	var step staticOperand
	for index, text := range []string{form.step, form.predicate} {
		if text == "" {
			continue
		}
		operand, err := nested.checkScoped(ctx, text)
		if err != nil {
			return staticOperand{}, err
		}
		if index == 0 {
			step = operand
		}
		if index == 1 {
			if err := requireBooleanOperand(operand); err != nil {
				return staticOperand{}, err
			}
		}
	}
	if form.all {
		return provenOperand("Boolean"), nil
	}
	// The step gives the accumulator's next value: Neo4j requires one of its
	// initial value's types (reduce(t = '', x IN [1] | x) is "Type mismatch:
	// accumulator is String but expression has type Integer", whatever reads
	// the result).
	if initial.typeName() != "" && step.typeName() != "" && composable(initial) && step.excludes(accumulatorAccepts(initial)) {
		return staticOperand{}, newSemanticError("Neo.ClientError.Statement.SyntaxError", "InvalidArgumentType",
			fmt.Sprintf("Type mismatch: accumulator is %s but expression has type %s", initial.typeName(), step.typeName()))
	}
	// Neo4j types reduce as its accumulator (reduceAccumulatorOperand); the
	// step only has to fit it: reduce(a = 1, x IN [n.k] | a + x) is an
	// Integer, reduce(t = CASE … 1 … 'a' END, x IN l | t) "Any, Integer or
	// String", reduce(a = null, …) of no known type.
	return reduceAccumulatorOperand(initial), nil
}

func checkReduceForm(ctx context.Context, function, text string, open int, check func(staticArgumentType, string, int) error) error {
	closing := findMatchingDelimiter(text, open, '(', ')')
	if closing < 0 {
		return nil
	}
	form, ok := parseReduceForm(function, text[open+1:closing])
	if !ok {
		entry := reduceFormEntries[lowerASCII(function)]
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidSyntax", localization.CypherCoreReduceFormInvalidSyntax(entry.name, entry.signature))
	}
	if err := check(staticArgumentType{expected: "List<T>", options: []string{"List<T>"}}, form.list, open+1); err != nil || !form.all {
		return err
	}
	return check(staticArgumentType{expected: "Boolean", options: []string{"Boolean"}}, form.predicate, closing) // inside the scope of acc and the element
}

func checkStaticLiteralArguments(function string, arguments []string) error {
	switch {
	case strings.EqualFold(function, "percentileCont") || strings.EqualFold(function, "percentileDisc"):
		if len(arguments) < 2 {
			return nil
		}
		text := strings.TrimSpace(arguments[1])
		value, literal := parseLiteralValueFromComputedRow(text)
		number, numeric := toFloat64(value)
		// A null literal is no percentile either (Neo4j 5.26: "Invalid
		// input 'NULL' is not a valid argument"); a null reaching it through
		// a variable or parameter is checked when it runs.
		if literal && (value == nil || numeric && (number < 0 || number > 1)) {
			return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidArgument",
				localization.CypherCorePercentileOutOfRange(text))
		}
	case strings.EqualFold(function, "point"):
		if len(arguments) != 1 {
			return nil
		}
		var x, y, latitude, longitude bool
		isMap := visitStaticMapLiteralKeys(arguments[0], func(key string) {
			switch key {
			case "x":
				x = true
			case "y":
				y = true
			case "latitude":
				latitude = true
			case "longitude":
				longitude = true
			}
		})
		if !isMap || x && y || latitude && longitude {
			return nil
		}
		keys, _ := staticMapLiteralKeys(arguments[0])
		quoted := make([]string, 0, len(keys))
		for key := range keys {
			quoted = append(quoted, "'"+key+"'")
		}
		sort.Strings(quoted)
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidPoint",
			localization.CypherCorePointMapKeysInvalid(strings.Join(quoted, ", ")))
	}
	return nil
}

func operandMismatch(operand staticOperand, expected string) error {
	if operand.parameter != "" {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidArgumentType",
			fmt.Sprintf("Type mismatch for parameter '%s': expected %s but was %s", operand.parameter, expected, operand.display),
		)
	}
	return typeNameMismatchError(expected, operand.display)
}

func requireBooleanOperand(operand staticOperand) error {
	switch {
	case operand.list():
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidArgumentType", localization.CypherCoreListCoercionToBoolean())
	case operand.excludes(isBooleanOrListTypeName):
		// A union with a list alternative passes the type check; only a
		// value that is a list on every alternative is the coercion error.
		return operandMismatch(operand, "Boolean")
	}
	return nil
}

func (checker staticOperatorChecker) derive(ctx context.Context, expression string) (staticOperand, error) {
	expression = strings.TrimSpace(expression)
	if expression == "" {
		return staticOperand{}, nil
	}
	if receiver, projected := staticMapProjectionReceiver(expression); projected && receiver != "" {
		if _, _, projection := staticMapProjectionSplit(expression); !projection {
			return staticOperand{}, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidSyntax",
				localization.CypherCoreMapProjectionReceiver(receiver))
		}
	}
	if _, isList := stripEnclosingRowDelimiter(expression, '[', ']'); isList {
		return checker.checkAtom(ctx, expression)
	}
	if expression[0] == '{' && findMatchingDelimiter(expression, 0, '{', '}') == len(expression)-1 {
		return checker.checkAtom(ctx, expression)
	}
	if _, _, projection := checker.mapProjection(expression); projection {
		return checker.checkAtom(ctx, expression)
	}
	// A map projection is an operand: an expression around one (s{.a} IS
	// NULL, toString(s{.a})) is typed like any other.
	if !isOperatorExpressionText(checker.maskMapProjections(expression)) {
		// A function call or subquery expression over a pattern still has
		// its result type (size([(n)-->() | 1]) is an Integer).
		return staticPatternExpressionType(expression), nil
	}
	if inner, enclosed := stripEnclosingExpressionParentheses(expression); enclosed {
		return checker.check(ctx, inner)
	}
	if startsWithKeywordFold(expression, "CASE") {
		end := leadingCaseExpressionEnd(expression)
		if isCaseExpression(expression) && end == len(expression) {
			if parsed, err := parseCaseExpression(expression); err == nil {
				return checker.checkCase(ctx, parsed)
			}
			return staticOperand{}, nil
		}
		if end <= 0 || end >= len(expression) {
			return staticOperand{}, nil
		}
		// A CASE is an operand of the operators after it (CASE … END + 1).
	}
	// The expression's own operators are found outside its CASE blocks
	// ([x] + CASE WHEN a OR b = c THEN [] END is a list, not a Boolean).
	scan := maskCaseBlocks(expression)
	for _, keyword := range []string{"OR", "XOR", "AND"} {
		if index := infixKeywordIndex(scan, keyword); index > 0 {
			for _, side := range [2]string{expression[:index], expression[keywordEndAt(expression, index, keyword):]} {
				operand, err := checker.check(ctx, side)
				if err != nil {
					return staticOperand{}, err
				}
				if err := requireBooleanOperand(operand); err != nil {
					return staticOperand{}, err
				}
			}
			return provenOperand("Boolean"), nil
		}
	}
	// A bare NOT is a variable named not (WITH [1] AS not ... x IN not).
	if startsWithKeywordFold(expression, "NOT") && strings.TrimSpace(expression[len("NOT"):]) != "" {
		operand, err := checker.check(ctx, expression[len("NOT"):])
		if err != nil {
			return staticOperand{}, err
		}
		if err := requireBooleanOperand(operand); err != nil {
			return staticOperand{}, err
		}
		return provenOperand("Boolean"), nil
	}
	// A type or normalization predicate (x IS :: LIST<INTEGER>, x IS NOT
	// TYPED STRING, x IS NFC NORMALIZED) is a Boolean; its type text isn't
	// an expression.
	if index := topLevelKeywordIndex(scan, "IS"); index > 0 {
		rest := strings.TrimSpace(expression[index+len("IS"):])
		if !startsWithKeywordFold(rest, "NULL") && !startsWithKeywordFold(strings.TrimSpace(strings.TrimPrefix(strings.ToUpper(rest), "NOT")), "NULL") {
			if _, err := checker.check(ctx, expression[:index]); err != nil {
				return staticOperand{}, err
			}
			return provenOperand("Boolean"), nil
		}
	}
	for _, keyword := range staticComparisonKeywords {
		if index := topLevelKeywordIndex(scan, keyword); index > 0 {
			if _, err := checker.check(ctx, expression[:index]); err != nil {
				return staticOperand{}, err
			}
			right, err := checker.check(ctx, expression[keywordEndAt(expression, index, keyword):])
			if err != nil {
				return staticOperand{}, err
			}
			if keyword == "IN" && right.excludes(isListTypeName) {
				return staticOperand{}, operandMismatch(right, "List<T>")
			}
			return provenOperand("Boolean"), nil
		}
	}
	for _, operator := range staticComparisonOperators {
		if left, right, found := splitAtOperator(expression, operator, findTopLevelOperator(scan, operator, false, true)); found && left != "" && right != "" {
			for _, side := range [2]string{left, right} {
				operand, err := checker.check(ctx, side)
				if err != nil {
					return staticOperand{}, err
				}
				if operator == "=~" && operand.excludes(isStringTypeName) {
					return staticOperand{}, operandMismatch(operand, "String")
				}
			}
			return provenOperand("Boolean"), nil
		}
	}
	for _, tier := range []string{"+-", "*/%", "^"} {
		left, right, operator, arithmetic := splitRowArithmeticTier(scan, tier)
		if !arithmetic {
			continue
		}
		// CASE bodies are atomic to the enclosing expression. Use the masked
		// boundary, then derive operands from their original source.
		position := len(left) + strings.IndexByte(scan[len(left):], operator)
		left, right = strings.TrimSpace(expression[:position]), strings.TrimSpace(expression[position+1:])
		if !staticArithmeticOperandText(left) || !staticArithmeticOperandText(right) {
			return staticOperand{}, nil
		}
		leftType, err := checker.check(ctx, left)
		if err != nil {
			return staticOperand{}, err
		}
		rightType, err := checker.check(ctx, right)
		if err != nil {
			return staticOperand{}, err
		}
		return checkOperator(operator, leftType, rightType, checker.scope.cypher25)
	}
	if (expression[0] == '-' || expression[0] == '+') && len(expression) > 1 {
		operand, err := checker.check(ctx, expression[1:])
		if err != nil {
			return staticOperand{}, err
		}
		// Unary minus takes a number. Neo4j 5.26's plus also takes a
		// temporal value or a duration; Neo4j 2026.09, which runs Cypher
		// 25, only a number.
		accepts := isNumericTypeName
		if expression[0] == '+' && !checker.scope.cypher25 {
			accepts = func(typeName string) bool {
				return isNumericTypeName(typeName) || isTemporalTypeName(typeName) || typeName == "Duration"
			}
		}
		if operand.excludes(accepts) {
			return staticOperand{}, operandMismatch(operand, "Float or Integer")
		}
		return unaryOperand(operand), nil
	}
	return checker.checkAtom(ctx, expression)
}

func (checker staticOperatorChecker) checkPostfix(ctx context.Context, receiverText, inner string, subscript bool) (staticOperand, error) {
	receiver, err := checker.check(ctx, receiverText)
	if err != nil {
		return staticOperand{}, err
	}
	if !subscript {
		if receiver.excludes(acceptsPropertyAccess) {
			return staticOperand{}, operandMismatch(receiver, "Map, Node, Relationship, Point, Duration, Date, Time, LocalTime, LocalDateTime or DateTime")
		}
		if member, found := receiver.staticMapMember(symbolicNameValue(strings.TrimSpace(inner))); found {
			return member, nil
		}
		if receiver.is("Node") || receiver.is("Relationship") {
			// A node's or relationship's property may hold any property type.
			return typedOperand(staticPropertyValueType).proved(), nil
		}
		return staticOperand{}, nil
	}
	if from, to, slice := staticSliceBounds(inner); slice {
		for _, bound := range [2]string{from, to} {
			operand, err := checker.check(ctx, bound)
			if err != nil {
				return staticOperand{}, err
			}
			if operand.excludes(isIntegerOrNumberTypeName) {
				return staticOperand{}, operandMismatch(operand, "Integer")
			}
		}
		if receiver.excludes(isListTypeName) {
			return staticOperand{}, operandMismatch(receiver, "List<T>")
		}
		if list := receiver.listPart(); list.typeName() != "" {
			return list, nil
		}
		// A slice is a list at compile time, whatever its receiver
		// (WHERE n.x[1..] is a list coercion error in Neo4j).
		return provenOperand("List<T>"), nil
	}
	key, err := checker.check(ctx, inner)
	if err != nil {
		return staticOperand{}, err
	}
	keyKnown := key.known() && !key.is("Null")
	invalidIntegerKey := key.excludes(isIntegerOrNumberTypeName)
	invalidStringKey := key.excludes(isStringTypeName)
	const syntaxError, detail = "Neo.ClientError.Statement.SyntaxError", "InvalidArgumentType"
	if receiver.union && !receiver.list() && !receiver.is("Map") {
		// A union of different kinds takes the key when one of its
		// alternatives does: reject one no alternative can be subscripted
		// as. A union of lists or maps is subscripted as that kind below.
		if receiver.excludes(func(typeName string) bool {
			return typeName == "Any" || isListTypeName(typeName) && !invalidIntegerKey || acceptsStringKey(typeName, checker.scope.cypher25) && !invalidStringKey
		}) {
			return staticOperand{}, operandMismatch(receiver, "List<T>, Map, Node or Relationship")
		}
		if receiver.hasAnyAlternative() {
			// Any may be subscripted; the row decides ((reduce(a = CASE …
			// [1] … true END, x IN l | a))[0] is any type to Neo4j).
			return staticOperand{}, nil
		}
		if element := receiver.elementOperand(); element.typeName() != "" && !invalidIntegerKey && !key.is("String") {
			return element, nil
		}
		return staticOperand{}, nil
	}
	switch {
	case receiver.is("Any"):
		// Any may be subscripted; the row decides.
	case !receiver.known():
		// A node's or relationship's property can't be a map, so it takes
		// only a list index (#882).
		if base, _, property := rowPropertyChainShape(receiverText); property && invalidIntegerKey {
			if kind := checker.scope.typeOf(base); kind == "Node" || kind == "Relationship" {
				return staticOperand{}, operandMismatch(key, "Integer")
			}
		}
	case receiver.is("Null"):
	case receiver.list():
		if invalidIntegerKey {
			return staticOperand{}, localizedStatusError(syntaxError, detail, localization.CypherCoreListIndexTypeMismatch(key.display))
		}
		return receiver.elementOperand(), nil
	case receiver.is("Map") || receiver.is("Map, Node or Relationship"):
		if invalidStringKey {
			return staticOperand{}, localizedStatusError(syntaxError, detail, localization.CypherCoreMapKeyTypeMismatch(key.display))
		}
		// A string literal key reads a known member (m['a']); a key from
		// a variable is read at run time, as in Neo4j 2026.09.
		if text, literal := decodeCypherQuotedString(strings.TrimSpace(inner)); literal {
			if member, found := receiver.staticMapMember(text); found {
				return member, nil
			}
		}
	case receiver.is("Node") || receiver.is("Relationship"):
		if invalidStringKey {
			return staticOperand{}, localizedStatusError(syntaxError, detail, localization.CypherCoreEntityPropertyKeyTypeMismatch(key.display))
		}
	case key.is("String"):
		// In Neo4j 5.26 a temporal value or duration takes a string key at
		// compile time (reading a field it doesn't have is a runtime error);
		// Neo4j 2026.09, which runs Cypher 25, takes none.
		if !receiver.temporal() && !receiver.duration() || checker.scope.cypher25 {
			return staticOperand{}, operandMismatch(receiver, "Map, Node or Relationship")
		}
	case key.is("Integer"):
		return staticOperand{}, operandMismatch(receiver, "List<T>")
	case !keyKnown && (!receiver.temporal() && !receiver.duration() || checker.scope.cypher25):
		return staticOperand{}, operandMismatch(receiver, "List<T>, Map, Node or Relationship")
	}
	return staticOperand{}, nil
}

func cypher5ImportGrouping(body string, imports map[string]interface{}) (string, error) {
	if len(imports) == 0 || !containsAggregateFunc(body) {
		return body, nil
	}
	words := projectionWords(body)
	type insertion struct {
		at   int
		text string
	}
	var insertions []insertion
	for index, word := range words {
		if word.depth != 0 || word.upper != "WITH" && word.upper != "RETURN" || precededByWord(body, word.start, "STARTS", "ENDS") {
			continue
		}
		itemsStart := skipASCIISpaces(body, word.end, len(body))
		if matchKeywordAt(body, itemsStart, "DISTINCT") {
			itemsStart = skipASCIISpaces(body, itemsStart+len("DISTINCT"), len(body))
		}
		itemsEnd := len(body)
		for _, next := range words[index+1:] {
			if next.depth == 0 && groupByKeysEnd(next.upper, "WITH") {
				itemsEnd = next.start
				break
			}
		}
		items := splitTopLevelComma(body[itemsStart:itemsEnd])
		aggregating := false
		projected := map[string]bool{}
		for _, item := range items {
			expression, alias := projectionItemAlias(item)
			projected[alias] = true
			spans := findAggregateSpans(expression)
			if len(spans) == 0 {
				continue
			}
			aggregating = true
			outside := expression
			for i := len(spans) - 1; i >= 0; i-- {
				outside = outside[:spans[i].start] + " " + outside[spans[i].end:]
			}
			for _, name := range expressionVariables(outside) {
				if _, imported := imports[name]; imported {
					return "", localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidSyntax",
						localization.CypherCoreGroupByImplicitGroupingKey(name))
				}
			}
		}
		if !aggregating || word.upper != "WITH" {
			continue
		}
		var keys []string
		for _, name := range expressionVariables(body[itemsEnd:]) {
			if _, imported := imports[name]; imported && !projected[name] {
				keys = append(keys, name)
			}
		}
		if len(keys) > 0 {
			insertions = append(insertions, insertion{at: itemsStart, text: strings.Join(keys, ", ") + ", "})
		}
	}
	for i := len(insertions) - 1; i >= 0; i-- {
		body = body[:insertions[i].at] + insertions[i].text + body[insertions[i].at:]
	}
	return body, nil
}

func validateExpressionOperandCompleteness(expression string) error {
	expression = strings.TrimSpace(expression)
	for {
		inner, enclosed := stripEnclosingExpressionParentheses(expression)
		if !enclosed {
			break
		}
		expression = strings.TrimSpace(inner)
	}
	last := len(expression) - 1
	if expression == "" || (expression != "*" && strings.ContainsAny(expression[last:], "+-*/%^") && !labelWildcardAt(expression, last)) {
		return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "syntax error: expected an expression after operator")
	}
	return nil
}

func validateProjectionSemantics(ctx context.Context, cypher string) error {
	clauses, ok := splitPipelineClauses(ctx, cypher)
	if !ok {
		return ctx.Err()
	}
	// Preserve statement admission order: every WITH alias/aggregation check
	// precedes projection-tail scope checks, even on an earlier RETURN.
	for _, clause := range clauses {
		if clause.kind != pipelineClauseWith {
			continue
		}
		body := projectionSemanticBody(clause.text, "WITH")
		if err := validateReturnAggregationSemantics(ctx, body); err != nil {
			return err
		}
		seen := make(map[string]struct{})
		for _, raw := range splitTopLevelComma(body) {
			item := strings.TrimSpace(raw)
			if item == "" || item == "{}" {
				continue
			}
			expression, alias := parseProjectionExprAlias(ctx, item)
			if err := validateExpressionOperandCompleteness(expression); err != nil {
				return err
			}
			explicitAlias := projectionAliasIndex(ctx, item) > 0
			// true, false and null are literals, not variables, even when a
			// variable of that name was declared (isLiteralKeyword).
			if !explicitAlias && expression != "*" && (simpleSemanticIdentifier(expression) == "" || isLiteralKeyword(expression)) {
				if containsMalformedCreateClauseToken(expression) {
					continue
				}
				return newSemanticError(
					"Neo.ClientError.Statement.SyntaxError",
					"NoExpressionAlias",
					"expressions in WITH must be explicitly aliased",
				)
			}
			name := normalizeProjectionColumnName(alias)
			if name == "*" {
				continue
			}
			if _, duplicate := seen[name]; duplicate {
				return newSemanticError(
					"Neo.ClientError.Statement.SyntaxError",
					"ColumnNameConflict",
					"multiple WITH items project the same column name: "+name,
				)
			}
			seen[name] = struct{}{}
		}
	}
	for _, clause := range clauses {
		keyword := ""
		switch clause.kind {
		case pipelineClauseWith:
			keyword = "WITH"
		case pipelineClauseReturn:
			keyword = "RETURN"
		default:
			continue
		}
		if err := aggregatingProjectionScopeError(ctx, strings.TrimSpace(clause.text), keyword); err != nil {
			return err
		}
	}
	return nil
}

func aggregatingProjectionScopeError(ctx context.Context, clause, keyword string) error {
	body, tail := projectionSemanticBodyAndTail(clause, keyword)
	_, distinct := cutDistinct(clause[len(keyword):])
	tail = strings.TrimSpace(tail)
	if tail == "" {
		return nil
	}
	items := splitTopLevelComma(body)
	aliases := make(map[string]struct{}, len(items)+1)
	aliases[projectedExpressionPlaceholder] = struct{}{}
	expressions := make([]string, 0, len(items))
	aggregates := false
	for _, item := range items {
		expression, alias := parseProjectionExprAlias(ctx, strings.TrimSpace(item))
		expression = strings.TrimSpace(expression)
		if expression == "*" {
			return nil
		}
		aggregates = aggregates || containsAggregateFunc(expression)
		aliases[normalizeProjectionColumnName(alias)] = struct{}{}
		expressions = append(expressions, strings.Join(strings.Fields(expression), " "))
	}
	if !aggregates && !distinct {
		return nil
	}
	// Longest first, so a projected x + 1 is masked whole before a
	// projected x inside it.
	sort.Slice(expressions, func(i, j int) bool { return len(expressions[i]) > len(expressions[j]) })
	// An aggregate call spelled otherwise (COUNT(distinct n) for a
	// projected count(DISTINCT n)) is the projected one.
	var spellings map[string]string
	spelled := false
	for _, part := range aggregatingProjectionTailExpressions(tail) {
		masked := strings.Join(strings.Fields(part), " ")
		if containsAggregateFunc(masked) {
			if !spelled {
				spellings, spelled = aggregateCallSpellings(expressions), true
			}
			masked = respellAggregateCalls(masked, spellings)
		}
		for _, expression := range expressions {
			masked = maskProjectedExpression(masked, expression)
		}
		for _, reference := range semanticFreeReferences(masked) {
			base := strings.SplitN(reference, ".", 2)[0]
			if _, projected := aliases[normalizeProjectionColumnName(base)]; projected {
				continue
			}
			return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UndefinedVariable",
				localization.CypherMatchingAggregationScopeVariable(base))
		}
	}
	return nil
}

func parseCaseExpression(expr string) (*caseExpression, error) {
	expr = strings.TrimSpace(expr)
	upper := upperASCII(expr)

	// Remove CASE and END keywords
	if !strings.HasPrefix(upper, "CASE") || !strings.HasSuffix(upper, "END") {
		return nil, localizedError(localization.CypherCoreCaseEnvelopeInvalid(), nil)
	}

	// Extract the content between CASE and END
	inner := expr[4 : len(expr)-3]
	content := strings.TrimSpace(inner)
	// Keywords are found in the whole expression, so the keyword reader sees
	// the CASE and END around the body (CASE case WHEN 1 THEN case END, where
	// case is the test; #1162); indices are content's.
	contentStart := 4 + len(inner) - len(strings.TrimLeftFunc(inner, unicode.IsSpace))
	findAtLevel := func(from int, keyword string) int {
		index := findCaseKeywordAtLevel(expr, contentStart+from, keyword)
		if index < 0 || index >= contentStart+len(content) {
			return -1
		}
		return index - contentStart
	}

	ce := &caseExpression{
		whenClauses: []caseWhenClause{},
	}

	// Only keywords at the current CASE level delimit the outer expression.
	// A plain string search incorrectly treats WHEN/ELSE from a nested CASE as
	// belonging to its parent.
	firstWhenIdx := findAtLevel(0, "WHEN")
	if firstWhenIdx == -1 {
		return nil, localizedError(localization.CypherCoreCaseWhenRequired(), nil)
	}

	beforeFirstWhen := strings.TrimSpace(content[:firstWhenIdx])
	if beforeFirstWhen != "" {
		// Simple CASE: CASE expression WHEN value THEN result ...
		ce.isSimple = true
		ce.testExpression = beforeFirstWhen
	}

	for cursor := firstWhenIdx; cursor < len(content); {
		conditionStart := cursor + len("WHEN")
		thenIndex := findAtLevel(conditionStart, "THEN")
		if thenIndex < 0 {
			return nil, localizedError(localization.CypherCoreCaseThenRequired(content[cursor:]), nil)
		}
		condition := strings.TrimSpace(content[conditionStart:thenIndex])
		resultStart := thenIndex + len("THEN")
		nextWhen := findAtLevel(resultStart, "WHEN")
		nextElse := findAtLevel(resultStart, "ELSE")
		resultEnd := len(content)
		next := len(content)
		if nextWhen >= 0 && nextWhen < resultEnd {
			resultEnd, next = nextWhen, nextWhen
		}
		if nextElse >= 0 && nextElse < resultEnd {
			resultEnd, next = nextElse, nextElse
		}
		result := strings.TrimSpace(content[resultStart:resultEnd])
		if condition == "" || result == "" {
			return nil, localizedError(localization.CypherCoreCaseThenRequired(content[cursor:]), nil)
		}
		clause := caseWhenClause{result: result}
		if ce.isSimple {
			clause.value = condition
		} else {
			clause.condition = condition
		}
		ce.whenClauses = append(ce.whenClauses, clause)

		if next == len(content) {
			break
		}
		if next == nextElse {
			ce.elseResult = strings.TrimSpace(content[nextElse+len("ELSE"):])
			break
		}
		cursor = nextWhen
	}

	if len(ce.whenClauses) == 0 {
		return nil, localizedError(localization.CypherCoreCaseWhenRequired(), nil)
	}

	return ce, nil
}

func validateUnwindAlias(clause string) error {
	_, alias, ok := parsePipelineIteration(clause)
	if !ok {
		return sharedClauseSyntaxError("iteration requires a variable and an expression")
	}
	_, next, identifier := scanIdentifierToken(alias, 0)
	if !identifier {
		return nil
	}
	if rest := strings.TrimSpace(alias[next:]); rest != "" {
		token := strings.Fields(rest)[0]
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			localization.CypherCoreInvalidInput(token))
	}
	return nil
}

func createUndefinedVariableError(variable string) error {
	message := localization.CypherAdminVariableNotDefined(variable)
	// Preserve the semantic error in the chain for callers that inspect its
	// detail, while the client-visible text uses the localized constructor.
	semantic := newSemanticError("Neo.ClientError.Statement.SyntaxError", "UndefinedVariable", message.Fallback)
	return &classifiedCypherError{
		cause:  localizedError(message, semantic),
		code:   "Neo.ClientError.Statement.SyntaxError",
		detail: "UndefinedVariable",
	}
}

func staticLabelTargetError(variable string, scope staticTypeScope) error {
	if operand := scope.operandOf(variable); operand.excludes(isNodeTypeName) {
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidArgumentType", localization.CypherCoreLabelTargetTypeMismatch(operand.typeName()))
	}
	return nil
}

func staticDynamicTokenError(expression string, scope staticTypeScope, use dynamicTokenUse) error {
	expression = strings.TrimSpace(expression)
	for {
		inner, wrapped := stripEnclosingExpressionParentheses(expression)
		if !wrapped {
			break
		}
		expression = strings.TrimSpace(inner)
	}
	literals := []string{expression}
	if inner, isList := stripEnclosingRowDelimiter(expression, '[', ']'); isList && use == dynamicTokenLabel {
		literals = splitTopLevelComma(inner)
	}
	for _, literal := range literals {
		literal = strings.TrimSpace(literal)
		if strings.EqualFold(literal, "null") {
			return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidArgumentType", localization.CypherCoreTokenNameNull())
		}
		if value, ok := parseLiteralValueFromComputedRow(literal); ok {
			if text, isText := value.(string); isText && text == "" {
				return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidArgumentType", localization.CypherCoreTokenNameInvalid(""))
			}
		}
	}
	operand := scope.operandOf(expression)
	if use == dynamicTokenLabel {
		if operand.excludes(isLabelTokenTypeName) {
			return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidArgumentType", localization.CypherCoreDynamicLabelTypeMismatch(operand.typeName()))
		}
		return nil
	}
	if operand.excludes(isKeyTokenTypeName) {
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidArgumentType", localization.CypherCoreEntityPropertyKeyTypeMismatch(operand.typeName()))
	}
	return nil
}

func branchSyntaxImports(branch queryBodyBranch, outer func(string) bool, collectNames bool) (names []string, importing bool, err error) {
	if len(branch.clauses) == 0 || branch.clauses[0].kind != pipelineClauseWith {
		return nil, false, nil
	}
	plan := projectionPlanFromSyntax(branch.clauses[0].syntax)
	importing = plan.star
	if plan.star {
		plan = plan.withStarExpanded(nil)
	}
	for _, item := range plan.projections {
		if collectNames {
			names = append(names, item.alias)
		}
		for _, name := range expressionFreeVariables(item.expr) {
			if outer(name) {
				importing = true
			}
		}
	}
	if !importing {
		return nil, false, nil
	}
	if len(branch.clauses) == 1 && branch.useStart < 0 && !branch.finished {
		return names, true, localizedError(localization.CypherSubqueriesWithQueryClauseRequired(), nil)
	}
	return names, true, nil
}

func staticListOperandTypeError(text string, scope staticTypeScope) error {
	if len(scope.kinds) == 0 && len(scope.values) == 0 {
		return nil
	}
	return forEachListOperand(text, func(start, in int) error {
		end := start
		for end < len(text) && isIdentByte(text[end]) {
			end++
		}
		if end == start || !wholeListOperand(text, end) {
			return nil
		}
		name := text[start:end]
		typeName := scope.typeOf(name)
		if typeName == "" || mayBeListType(typeName) {
			return nil
		}
		if foreachDeclaration(text, in) || forIterationDeclaration(text, in) || localVariableShadowsAt(text, start, name) {
			return nil
		}
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidArgumentType", localization.CypherCoreListOperandTypeMismatch(typeName))
	})
}

func validateChainLabel(name string, quoted bool) error {
	if name == "" || (!quoted && !isValidIdentifier(name)) {
		return localizedError(localization.CypherMutationsInvalidLabelName(name), nil)
	}
	if !quoted && containsReservedKeyword(name) {
		return localizedError(localization.CypherMutationsInvalidLabelReserved(name), nil)
	}
	return nil
}

func setLabelChainItems(chain string) ([]labelChainItem, error) {
	items := make([]labelChainItem, 0, strings.Count(chain, ":")+1)
	var labelErr error
	wellFormed := eachChainItem(chain, func(text string, quoted, dynamic bool) {
		switch {
		case dynamic:
			items = append(items, labelChainItem{expression: text})
			if text == "" && labelErr == nil {
				labelErr = localizedError(localization.CypherMutationsInvalidLabelName("$()"), nil)
			}
			return
		case text == "" && !quoted:
			return
		case text != "":
			items = append(items, labelChainItem{name: text})
		}
		if labelErr == nil {
			labelErr = validateChainLabel(text, quoted)
		}
	})
	if labelErr == nil && (!wellFormed || len(items) == 0) {
		labelErr = localizedError(localization.CypherMutationsInvalidLabelName(chain), nil)
	}
	if labelErr != nil {
		return nil, &classifiedCypherError{
			cause:  labelErr,
			code:   "Neo.ClientError.Statement.SyntaxError",
			detail: "InvalidLabel",
		}
	}
	return items, nil
}

func localizedStatusError(code, detail string, message localization.Message) error {
	return &classifiedCypherError{cause: localizedError(message, nil), code: code, detail: detail}
}

func callBodyReturnStarError(ctx context.Context, scope matchSemanticScope, clause string, enclosing subqueryScope) error {
	if enclosing.outer || enclosing.visible == nil {
		return nil
	}
	if !returnsStar(ctx, clause) {
		return nil
	}
	for name := range scope {
		if _, imported := enclosing.visible[name]; !imported {
			return nil
		}
	}
	return &classifiedCypherError{
		cause:  localizedError(localization.CypherMatchingReturnStarNoVariables(), nil),
		code:   "Neo.ClientError.Statement.SyntaxError",
		detail: "NoVariablesInScope",
	}
}

func (enclosing subqueryScope) redeclarationError(name string) error {
	if !enclosing.outer {
		return nil
	}
	if _, visible := enclosing.visible[name]; !visible {
		return nil
	}
	return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound",
		localization.CypherCoreVariableDeclaredInOuterScope(name))
}

func (e *StorageExecutor) semanticScopeWalk(ctx context.Context, clauses []pipelineClause, types typeScope, cypher25 bool, enclosing subqueryScope) (typeScope, bool, error) {
	var scope matchSemanticScope
	// valueTypes holds the static types of variables bound to a literal by
	// WITH … AS or UNWIND, for the function argument checks.
	var valueTypes map[string]string
	// valueMembers holds the member types of variables a WITH bound to a
	// map literal, in a Cypher 25 statement (projectStaticValueMembers);
	// every other binding of a name drops its entry.
	var valueMembers map[string]map[string]staticOperand
	returnSeen := false
	// unwound names the typed variables whose type came from UNWIND, which
	// Neo4j checks against a procedure's parameters only when the call runs.
	var unwound map[string]struct{}
	// view is the static view of types; stale after a clause changes them.
	var view staticTypeScope
	stale := true
	for _, clause := range clauses {
		if err := expressionSubqueryClauseBindingError(ctx, clause, enclosing); err != nil {
			return types, false, err
		}
		if returnSeen {
			// RETURN is the terminal clause: a clause after it is never a
			// legal statement (RETURN 1 AS x RETURN 2 AS y is Neo4j's
			// "Invalid input 'RETURN'").
			token := strings.Fields(clause.text)[0]
			return types, false, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
				localization.CypherCoreInvalidInput(token))
		}
		if clause.kind == pipelineClauseReturn {
			returnSeen = true
		}
		if stale {
			view = types.static(cypher25)
		}
		scope, valueTypes, valueMembers = view.kinds, view.values, view.members
		// Every clause but RETURN and DELETE may change types.
		stale = true
		if clause.kind != pipelineClauseMatch && clause.kind != pipelineClauseOptionalMatch {
			if err := validateShortestCallBindings(clause.text, scope); err != nil {
				return types, false, err
			}
		}
		var projectedTypes typeScope
		if clause.kind == pipelineClauseWith {
			projectedTypes = projectTypeScopeIn(ctx, types, view, clause.text)
			// The projection reads the incoming variables; WITH … WHERE
			// reads the projected ones.
			projection := clause.text
			if where := topLevelKeywordIndex(clause.text, "WHERE"); where >= 0 {
				projection = clause.text[:where]
				if err := graphListOperandTypeError(clause.text[where:], projectedTypes.kinds()); err != nil {
					return types, false, err
				}
			}
			if err := graphListOperandTypeError(projection, scope); err != nil {
				return types, false, err
			}
		}
		// A clause's EXISTS / COUNT / COLLECT subqueries see its variables, and
		// a WITH's or RETURN's projected ones (WITH i.n AS k WHERE COUNT { … k … });
		// MATCH and procedure CALL are checked once their outputs bind;
		// a CALL subquery's body starts from its imports.
		if clause.kind != pipelineClauseMatch && clause.kind != pipelineClauseOptionalMatch && clause.kind != pipelineClauseCall && clause.kind != pipelineClauseCallSubquery && (mayContainSubqueryExpression(clause.text) || containsRelationshipPattern(clause.text)) {
			if err := e.validateClauseSubqueries(ctx, clause, types, view, projectedTypes, cypher25); err != nil {
				return types, false, err
			}
		}
		switch clause.kind {
		case pipelineClauseLet, pipelineClauseFilter:
			if err := e.validateSharedClause(ctx, scope, valueTypes, clause, cypher25); err != nil {
				return types, false, err
			}
			if clause.kind == pipelineClauseLet {
				projections, err := parsePipelineLet(clause.text)
				if err != nil {
					return types, false, err
				}
				for _, projection := range projections {
					if _, exists := scope[projection.alias]; exists {
						return types, false, newSemanticError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound",
							fmt.Sprintf("variable %s is already declared", projection.alias))
					}
					input := types.static(cypher25)
					input.complete = false
					types[projection.alias] = projectedOperand(types, input, projection.expression)
					scope[projection.alias] = types[projection.alias].bindingKind()
				}
			}
		case pipelineClauseCallSubquery:
			body, _, _, _ := e.parseCallSubquery(ctx, clause.text)
			branches := []string{body}
			if unionBranches, _, _, union := parseTopLevelUnionBranches(ctx, body); union && len(unionBranches) > 0 {
				branches = unionBranches
			}
			// The body is a query of its own, walked from the variables it
			// imports; its subqueries see its scope.
			returned, err := e.callSubqueryReturnTypes(ctx, clause.text, branches, types, cypher25)
			if err != nil {
				return types, false, err
			}
			if returnIndex := topLevelKeywordIndex(branches[0], "RETURN"); returnIndex >= 0 {
				columns := pipelineReturnSourceColumns(ctx, branches[0][returnIndex:])
				if columns == nil || slices.Contains(columns, "*") {
					// RETURN * (which names no column of its own) returns
					// every variable of the body. When the
					// body's variables are typed, the statement goes on
					// with them; otherwise, as after YIELD *, the rest of
					// it isn't checked (#907: CALL { UNWIND [2] AS b
					// RETURN * } RETURN b).
					if returned == nil {
						return types, false, nil
					}
					for name, operand := range returned {
						if _, bound := scope[name]; !bound {
							types[name] = operand
							scope[name] = operand.bindingKind()
						}
					}
					continue
				}
				for _, name := range columns {
					// A returned column is a new variable of the enclosing
					// query: one it already binds is declared twice
					// (Neo4j 5.26.30's VariableAlreadyBound), unless every
					// branch returns that outer variable itself, unchanged
					// (callSubqueryReturnsOuterUnchanged).
					if _, bound := scope[name]; bound && !callSubqueryReturnsOuterUnchanged(ctx, branches, name) {
						return types, false, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound",
							localization.CypherCoreVariableDeclaredInOuterScope(name))
					}
					types[name] = returned[name]
					scope[name] = types[name].bindingKind()
				}
			}
		case pipelineClauseCall:
			// CALL proc() YIELD x: a yielded name must be new (Neo4j:
			// VariableAlreadyBound). YIELD * names nothing statically, so
			// the rest of the statement isn't checked.
			if err := staticProcedureArgumentTypeError(ctx, clause.text, staticTypeScope{kinds: scope, values: valueTypes, derived: view.derived, complete: true}, unwound); err != nil {
				return types, false, err
			}
			yield := parseYieldClause(ctx, clause.text)
			if yield == nil || yield.yieldAll {
				if mayContainSubqueryExpression(clause.text) || containsRelationshipPattern(clause.text) {
					if err := e.validateClauseSubqueries(ctx, clause, types, view, nil, cypher25); err != nil {
						return types, false, err
					}
				}
				return types, false, nil
			}
			outputTypes := procedureOutputTypes(ctx, clause.text)
			for _, item := range yield.items {
				name := item.column()
				if _, bound := types[name]; bound {
					return types, false, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound",
						localization.CypherCoreProcedureOutputShadowsVariable(name))
				}
				types[name] = staticOperand{}
				if typeName := outputTypes[item.name]; typeName != "" {
					// A procedure's declared output type.
					types[name] = provenOperand(typeName)
				}
			}
			// Like WITH, the invocation reads the incoming scope and the
			// predicate reads it extended by the projected (yielded) names.
			if mayContainSubqueryExpression(clause.text) || containsRelationshipPattern(clause.text) {
				if err := e.validateClauseSubqueries(ctx, clause, types, view, types, cypher25); err != nil {
					return types, false, err
				}
			}
			if err := e.validateStaticClauseTypes(ctx, clause, types.static(cypher25)); err != nil {
				return types, false, err
			}
		case pipelineClauseMatch, pipelineClauseOptionalMatch:
			if err := e.validateMatchClauseBindings(scope, clause.text); err != nil {
				return types, false, err
			}
			// A quantified group's predicates see one iteration's node and
			// relationship; every check after them reads the clause without
			// them, where the group's variables are lists.
			masked, err := e.validateQuantifiedGroupPredicates(ctx, clause.text, staticTypeScope{kinds: scope, values: valueTypes, members: valueMembers, derived: view.derived, complete: true, cypher25: cypher25})
			if err != nil {
				return types, false, err
			}
			clause.text = masked
			// The clause's WHERE subqueries see its own bindings.
			if err := e.validateSubqueryPatternBindings(ctx, staticTypeScope{kinds: scope, values: valueTypes, members: valueMembers, derived: view.derived, complete: true, cypher25: cypher25}, clause.text); err != nil {
				return types, false, err
			}
			types.adoptKinds(scope)
			if err := e.validateStaticClauseTypes(ctx, clause, staticTypeScope{kinds: scope, values: valueTypes, members: valueMembers, derived: view.derived, complete: true, cypher25: cypher25}); err != nil {
				return types, false, err
			}
		case pipelineClauseWith:
			if containsMalformedCreateClauseToken(clause.text) {
				return types, false, nil
			}
			if err := validateWithOrderBySemanticScope(ctx, scope, clause.text, enclosing.visible); err != nil {
				return types, false, err
			}
			// The WHERE after WITH reads the projected scope merged over the
			// incoming one, as at runtime (aliases shadow same-named inputs).
			if where := topLevelKeywordIndex(clause.text, "WHERE"); where >= 0 {
				projected := projectedTypes.kinds()
				whereScope := make(matchSemanticScope, len(scope)+len(projected))
				for name, kind := range scope {
					whereScope[name] = kind
				}
				for name, kind := range projected {
					whereScope[name] = kind
				}
				if err := e.validateMatchWhereSimpleOperands(whereScope, clause.text[where+len("WHERE"):]); err != nil {
					return types, false, err
				}
			}
			// The projection sees the incoming variables; WHERE / ORDER BY
			// after it see the projected ones.
			projection, rest := splitWithProjection(clause.text)
			projectionBody, _ := cutDistinct(strings.TrimSpace(projection[len("WITH"):]))
			for _, raw := range splitTopLevelComma(projectionBody) {
				expression, _ := parseProjectionExprAlias(ctx, strings.TrimSpace(raw))
				if err := projectionItemTermError(expression); err != nil {
					return types, false, err
				}
				if err := projectionAliasError(ctx, raw); err != nil {
					return types, false, err
				}
				if expression != "*" {
					if err := undefinedExpressionVariable(scope, expression); err != nil {
						return types, false, err
					}
				}
			}
			input := staticTypeScope{kinds: scope, values: valueTypes, members: valueMembers, derived: view.derived, complete: true, cypher25: cypher25}
			if err := validateStaticFunctionVariables(projection, input); err != nil {
				return types, false, err
			}
			if err := e.validateStaticOperatorTypes(ctx, clause, input, func() staticTypeScope { return projectionAliasScope(ctx, input, clause.text) }, nil); err != nil {
				return types, false, err
			}
			// Retain each import's current operand after a rebinding, using
			// the same rule that carries runtime values across WITH.
			var empty typeScope
			if len(enclosing.visible) > 0 && pipelineProjectionHasOnlyAggregates(returnProjectionPlanFor(ctx, "RETURN "+projectionBody).projections) {
				empty = maps.Clone(projectedTypes)
				carrySubqueryImports(empty, nil, enclosing.visible)
			}
			carrySubqueryImports(projectedTypes, types, enclosing.visible)
			for name, operand := range empty {
				projectedTypes[name] = joinedOperand(projectedTypes[name], operand)
			}
			types = projectedTypes
			unwound = projectUnwoundValues(ctx, unwound, clause.text)
			projected := types.static(cypher25)
			scope, valueTypes, valueMembers = projected.kinds, projected.values, projected.members
			view, stale = projected, false
			if err := forEachProjectedTailExpression(ctx, projection, rest, func(expression string) error {
				return validateStaticFunctionVariables(expression, projected)
			}); err != nil {
				return types, false, err
			}
		case pipelineClauseUnwind:
			if err := validateUnwindAlias(clause.text); err != nil {
				return types, false, err
			}
			if err := undefinedExpressionVariable(scope, unwindSourceExpression(clause.text)); err != nil {
				return types, false, err
			}
			if err := e.validateStaticClauseTypes(ctx, clause, staticTypeScope{kinds: scope, values: valueTypes, members: valueMembers, derived: view.derived, complete: true, cypher25: cypher25}); err != nil {
				return types, false, err
			}
			if alias := unwindBindingName(clause.text); alias != "" {
				// FOR is new syntax: unlike the pre-existing permissive UNWIND,
				// it must not redeclare an already-bound variable, as in Neo4j.
				if startsWithKeywordFold(clause.text, "FOR") {
					if _, bound := scope[alias]; bound {
						return types, false, newSemanticError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound",
							fmt.Sprintf("variable %s is already declared", alias))
					}
				}
				input := view
				input.complete = false
				// Neo4j types an element of a list UNWIND binds only when a
				// procedure call runs; UNWIND 5 binds 5 statically.
				source := projectedOperand(types, input, unwindSourceExpression(clause.text))
				types[alias] = unwoundOperand(types, input, clause.text)
				scope[alias] = types[alias].bindingKind()
				delete(unwound, alias)
				if types[alias].typeName() != "" && !source.excludes(isListTypeName) {
					if unwound == nil {
						unwound = make(map[string]struct{})
					}
					unwound[alias] = struct{}{}
				}
			}
		case pipelineClauseReturn:
			stale = false
			if err := validateReturnSemanticScopeIn(ctx, scope, clause.text, enclosing.visible); err != nil {
				return types, false, err
			}
			if err := callBodyReturnStarError(ctx, scope, clause.text, enclosing); err != nil {
				return types, false, err
			}
			if err := e.validateStaticClauseTypes(ctx, clause, staticTypeScope{kinds: scope, values: valueTypes, members: valueMembers, derived: view.derived, complete: true, cypher25: cypher25}); err != nil {
				return types, false, err
			}
		case pipelineClauseDelete:
			stale = false
			if err := deleteTargetTypeError(clause.text, scope); err != nil {
				return types, false, err
			}
			if err := e.validateStaticClauseTypes(ctx, clause, staticTypeScope{kinds: scope, values: valueTypes, members: valueMembers, derived: view.derived, complete: true, cypher25: cypher25}); err != nil {
				return types, false, err
			}
		case pipelineClauseCreate, pipelineClauseMerge:
			addMatchPatternBindingKinds(scope, clause.text)
			types.adoptKinds(scope)
			if err := e.validateStaticClauseTypes(ctx, clause, staticTypeScope{kinds: scope, values: valueTypes, members: valueMembers, derived: view.derived, complete: true, cypher25: cypher25}); err != nil {
				return types, false, err
			}
		default:
			if err := e.validateStaticClauseTypes(ctx, clause, staticTypeScope{kinds: scope, values: valueTypes, members: valueMembers, derived: view.derived, complete: true, cypher25: cypher25}); err != nil {
				return types, false, err
			}
		}
		if clause.kind != pipelineClauseWith {
			// Every other clause reads its own and the incoming bindings.
			if err := graphListOperandTypeError(clause.text, types.kinds()); err != nil {
				return types, false, err
			}
		}
	}
	return types, true, nil
}

func validateWithOrderBySemanticScope(ctx context.Context, input matchSemanticScope, clause string, retained typeScope) error {
	body := strings.TrimSpace(clause[len("WITH"):])
	orderIndex := topLevelKeywordIndex(body, "ORDER BY")
	if orderIndex < 0 {
		return nil
	}
	orderBody := strings.TrimSpace(body[keywordEndAt(body, orderIndex, "ORDER BY"):])
	projectionBody := strings.TrimSpace(body[:orderIndex])
	hasProjectionAggregate := false
	for _, item := range splitTopLevelComma(projectionBody) {
		expression, _ := parseProjectionExprAlias(ctx, strings.TrimSpace(item))
		if containsAggregateFunc(expression) {
			hasProjectionAggregate = true
			break
		}
	}
	if err := validateReturnOrderBySemanticScopeIn(ctx, "RETURN "+body, retained); err != nil {
		return err
	}
	for _, term := range parseOrderByClause(orderBody) {
		if containsAggregateFunc(term.column) && !hasProjectionAggregate {
			return newSemanticError(
				"Neo.ClientError.Statement.SyntaxError",
				"InvalidAggregation",
				"ORDER BY cannot introduce an aggregate after a non-aggregating WITH",
			)
		}
	}
	return validateOrderByReferences(input, projectMatchSemanticScope(ctx, input, clause), orderBody)
}

func validateReturnSemanticScopeIn(ctx context.Context, scope matchSemanticScope, clause string, outer typeScope) error {
	if err := validateReturnOrderBySemanticScopeIn(ctx, clause, outer); err != nil {
		return err
	}
	body := strings.TrimSpace(clause[len("RETURN"):])
	if err := validateReturnAggregationSemanticsIn(ctx, body, outer); err != nil {
		return err
	}
	// A dangling modifier keyword (RETURN 1 ORDER BY / SKIP / LIMIT) and an
	// empty projection (RETURN, WITH 1 AS x RETURN) are Neo4j syntax errors.
	// The clause is scanned with its keyword, which tells a keyword-named
	// first item from a clause (RETURN skip[0], #894).
	clauseText := strings.TrimSpace(clause)
	projectionEnd := len(clauseText)
	for _, keyword := range []string{"ORDER BY", "SKIP", "LIMIT"} {
		index := topLevelKeywordIndex(clauseText, keyword)
		if index < len("RETURN") || index >= projectionEnd {
			continue
		}
		if strings.TrimSpace(clauseText[index+len(keyword):]) == "" {
			return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
				localization.CypherCoreInvalidInputExpectedExpression(""))
		}
		projectionEnd = index
	}
	projectionText := strings.TrimSpace(clauseText[len("RETURN"):projectionEnd])
	body, _ = cutDistinct(projectionText)
	if body == "" {
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			localization.CypherMatchingReturnExpressionRequired())
	}
	if orderIndex := topLevelKeywordIndex(clauseText, "ORDER BY"); orderIndex >= len("RETURN") {
		projection := strings.TrimSpace(clauseText[len("RETURN"):orderIndex])
		if err := validateOrderByReferences(scope, projectMatchSemanticScope(ctx, scope, "WITH "+projection), strings.TrimSpace(clauseText[keywordEndAt(clauseText, orderIndex, "ORDER BY"):])); err != nil {
			return err
		}
	}
	for _, raw := range splitTopLevelComma(body) {
		expression, _ := parseProjectionExprAlias(ctx, strings.TrimSpace(raw))
		if err := projectionItemTermError(expression); err != nil {
			return err
		}
		if err := undefinedExpressionVariable(scope, expression); err != nil {
			return err
		}
		if expression == "*" {
			if len(scope) == 0 {
				return &classifiedCypherError{
					cause:  localizedError(localization.CypherMatchingReturnStarNoVariables(), nil),
					code:   "Neo.ClientError.Statement.SyntaxError",
					detail: "NoVariablesInScope",
				}
			}
			continue
		}
		if _, literal := parseLiteralValueFromComputedRow(expression); literal {
			continue
		}
		variable := simpleSemanticIdentifier(expression)
		if variable == "" {
			// m.val: the property chain's variable must be bound.
			if base, _, chain := rowPropertyChainShape(expression); chain {
				variable = base
			}
		}
		// null.a is a property of null (null), not of a variable.
		if variable != "" && !isLiteralKeyword(variable) {
			if _, found := scope[variable]; !found {
				return createUndefinedVariableError(variable)
			}
		}
	}
	return nil
}

func (e *StorageExecutor) validateMatchClauseBindings(scope matchSemanticScope, clause string) error {
	pattern := strings.TrimSpace(clause)
	for _, keyword := range []string{"OPTIONAL MATCH", "MATCH"} {
		if startsWithKeywordFold(pattern, keyword) {
			pattern = strings.TrimSpace(pattern[len(keyword):])
			break
		}
	}
	whereClause := ""
	// A WHERE inside parentheses is a quantified path pattern's own.
	if where := topLevelKeywordIndex(pattern, "WHERE"); where >= 0 {
		whereClause = strings.TrimSpace(pattern[where+len("WHERE"):])
	}
	// A quantified group's WHERE is an expression, not pattern structure.
	pattern = strings.TrimSpace(matchPatternStructure(pattern))
	if mergePatternUsesParameterPredicate(pattern) {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidParameterUse",
			"MATCH pattern predicates must use a property map, not a parameter map",
		)
	}
	if invalidRelationshipPattern(pattern) {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidRelationshipPattern",
			"invalid variable-length relationship pattern",
		)
	}

	variableLengthRelationships := variableLengthRelationshipVariableSet(pattern)
	groupNodes, groupRelationships := quantifiedGroupVariables(pattern)
	for variable := range groupNodes {
		if _, bound := scope[variable]; bound {
			return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", localization.CypherMatchingQuantifiedPathVariableBound(variable))
		}
	}
	for variable := range groupRelationships {
		if _, bound := scope[variable]; bound {
			return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", localization.CypherMatchingQuantifiedPathVariableBound(variable))
		}
	}
	for _, patternPart := range splitTopLevelComma(pattern) {
		patternPart = strings.TrimSpace(patternPart)
		pathVariable := extractPathAssignmentVariable(patternPart)
		entityPattern := patternPart
		if pathVariable != "" {
			if equals := strings.Index(patternPart, "="); equals >= 0 {
				entityPattern = strings.TrimSpace(patternPart[equals+1:])
			}
			if _, alreadyBound := scope[pathVariable]; alreadyBound {
				return newSemanticError(
					"Neo.ClientError.Statement.SyntaxError",
					"VariableAlreadyBound",
					fmt.Sprintf("path variable %s is already bound", pathVariable),
				)
			}
			scope[pathVariable] = matchBindingPath
		}

		if _, _, _, selected := splitPathSelectorTerm(whereClause); !selected {
			if err := validateShortestCallBindings(entityPattern, scope); err != nil {
				return err
			}
		}
		for _, variable := range extractNodeVariables(entityPattern) {
			if variable == pathVariable {
				return newSemanticError(
					"Neo.ClientError.Statement.SyntaxError",
					"VariableAlreadyBound",
					fmt.Sprintf("path variable %s is already bound", pathVariable),
				)
			}
			kind := matchBindingNode
			if _, grouped := groupNodes[variable]; grouped {
				kind = matchBindingNodeList
			}
			if err := bindMatchSemanticKind(scope, variable, kind); err != nil {
				return err
			}
		}
		for _, variable := range extractRelationshipVariables(entityPattern) {
			if variable == pathVariable {
				return newSemanticError(
					"Neo.ClientError.Statement.SyntaxError",
					"VariableAlreadyBound",
					fmt.Sprintf("path variable %s is already bound", pathVariable),
				)
			}
			kind := matchBindingRelationship
			if _, variableLength := variableLengthRelationships[variable]; variableLength {
				kind = matchBindingRelationshipList
			}
			if _, grouped := groupRelationships[variable]; grouped {
				kind = matchBindingRelationshipList
			}
			if err := bindMatchSemanticKind(scope, variable, kind); err != nil {
				return err
			}
		}

	}
	return e.validateMatchWhereSimpleOperands(scope, whereClause)
}

func (e *StorageExecutor) validateMatchWhereSimpleOperands(scope matchSemanticScope, whereClause string) error {
	whereClause = strings.TrimSpace(maskSubqueryBodies(whereClause))
	if whereClause == "" {
		return nil
	}
	switch whereClause[0] {
	case '=', '<', '>', '~':
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			localization.CypherCoreInvalidInputExpectedExpression(string(whereClause[0])))
	case '!':
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			localization.CypherCoreInvalidInputExpectedExpression("!"))
	}
	// A clause keyword read as a variable followed by another term with no
	// operator between them is Neo4j's Invalid input error (WHERE RETURN n:
	// return is the variable, n is invalid — the #740 reading).
	if err := projectionItemTermError(whereClause); err != nil {
		return err
	}
	if containsAggregateFunc(whereClause) {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidAggregation",
			"aggregate expressions are not allowed in WHERE",
		)
	}
	for _, operator := range []string{" OR ", " XOR ", " AND "} {
		if left, right, found := splitByOperatorOutsideCase(whereClause, operator, true, true); found {
			if err := e.validateMatchWhereSimpleOperands(scope, left); err != nil {
				return err
			}
			return e.validateMatchWhereSimpleOperands(scope, right)
		}
	}
	if err := e.validateWherePatternExpressionScope(scope, whereClause); err != nil {
		return err
	}
	if operands, _, comparison := splitComparisonChain(whereClause); comparison {
		for _, operand := range operands {
			operand = strings.TrimSpace(operand)
			// A clause keyword read as a variable followed by another term with
			// no operator between them is Neo4j's Invalid input error
			// (WHERE n.x = RETURN n: return is the variable, n is invalid).
			if err := projectionItemTermError(operand); err != nil {
				return err
			}
			if variable, _, propertyAccess := parseVarPropertyRef(operand); propertyAccess {
				switch scope[normalizeProjectionColumnName(variable)] {
				case matchBindingPath, matchBindingRelationshipList, matchBindingNodeList:
					return newSemanticError(
						"Neo.ClientError.Statement.SyntaxError",
						"InvalidArgumentType",
						fmt.Sprintf("property access is not supported on %s", variable),
					)
				}
			}
			if _, literal := parseLiteralValueFromComputedRow(operand); literal {
				continue
			}
			identifier := simpleSemanticIdentifier(operand)
			if identifier == "" {
				continue
			}
			_, inScope := scope[identifier]
			_, externallyBound := e.fabricRecordBindings[identifier]
			if !inScope && !externallyBound {
				return createUndefinedVariableError(identifier)
			}
		}
	}
	for _, operator := range []string{" STARTS WITH ", " ENDS WITH ", " CONTAINS ", " NOT IN ", " IN ", "=~"} {
		left, right, found := splitByOperatorOutsideCase(whereClause, operator, true, true)
		if !found {
			continue
		}
		left = strings.TrimSpace(left)
		// A clause keyword read as a variable on the operator's right followed
		// by another term is Invalid input (WHERE n.x IN RETURN n).
		if err := projectionItemTermError(strings.TrimSpace(right)); err != nil {
			return err
		}
		if simpleSemanticIdentifier(left) == left {
			if _, exists := scope[left]; !exists {
				return createUndefinedVariableError(left)
			}
		}
	}
	return nil
}

func (e *StorageExecutor) validateWherePatternExpressionScope(scope matchSemanticScope, expression string) error {
	expression = strings.TrimSpace(expression)
	if inner, enclosed := stripEnclosingExpressionParentheses(expression); enclosed {
		// (true), (false) and (null) are parenthesised literals, not node
		// patterns (#878 writes an element's own predicate in parentheses).
		if variable := simpleSemanticIdentifier(inner); variable != "" && !isLiteralKeyword(variable) {
			if _, inScope := scope[variable]; !inScope {
				if _, externallyBound := e.fabricRecordBindings[variable]; !externallyBound {
					return createUndefinedVariableError(variable)
				}
			}
			return newSemanticError(
				"Neo.ClientError.Statement.SyntaxError",
				"InvalidArgumentType",
				"a node pattern is not a boolean predicate",
			)
		}
	}
	// A pattern comprehension binds its own variables (#1109); only a
	// pattern expression may not.
	expression = maskPatternComprehensions(expression)
	if !containsRelationshipPattern(expression) {
		return nil
	}
	for _, variable := range append(extractNodeVariables(expression), extractRelationshipVariables(expression)...) {
		if _, inScope := scope[variable]; inScope {
			continue
		}
		if _, externallyBound := e.fabricRecordBindings[variable]; externallyBound {
			continue
		}
		return createUndefinedVariableError(variable)
	}
	return nil
}

func (e *StorageExecutor) validateSubqueryPatternBindings(ctx context.Context, scope staticTypeScope, text string) error {
	if err := validateExpressionPatternBindings(scope, text); err != nil {
		return err
	}
	if !mayContainSubqueryExpression(text) {
		return nil
	}
	for _, subquery := range findSubqueryExpressions(text) {
		local := withPatternComprehensionBindings(withLocalTypes(scope, text, subquery.start), text, subquery.start)
		for name := range expressionLocalBindings(maskNestedScopeBodies(subquery.body)) {
			if local.bound(name) {
				return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound",
					localization.CypherCoreVariableDeclaredInOuterScope(name))
			}
		}
		body := strings.TrimSpace(subquery.body)
		if strings.HasPrefix(body, "(") {
			body = "MATCH " + body
		}
		// Each UNION branch is a query of its own.
		branches := []string{body}
		if unionBranches, _, _, union := parseTopLevelUnionBranches(ctx, body); union && len(unionBranches) > 0 {
			branches = unionBranches
		}
		visible := typeScopeOf(local)
		for _, branch := range branches {
			clauses, ok := splitPipelineClausesAllowingProcedureCalls(ctx, branch)
			if !ok {
				continue
			}
			if _, _, err := e.semanticScopeWalk(ctx, clauses, maps.Clone(visible), scope.cypher25, subqueryScope{visible: visible, outer: true}); err != nil {
				return err
			}
		}
	}
	return nil
}

func bindMatchSemanticKind(scope matchSemanticScope, variable string, kind matchBindingKind) error {
	variable = normalizeProjectionColumnName(strings.TrimSpace(variable))
	if variable == "" {
		return nil
	}
	if existing, found := scope[variable]; found && existing != matchBindingUnknown && existing != kind {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"VariableTypeConflict",
			fmt.Sprintf("variable %s is already bound to a different entity type", variable),
		)
	}
	scope[variable] = kind
	return nil
}

func projectionItemTermError(expression string) error {
	expression = strings.TrimSpace(expression)
	name, next, ok := scanIdentifierToken(expression, 0)
	if !ok || !isNameableClauseKeyword(name) {
		return nil
	}
	rest := strings.TrimSpace(expression[next:])
	if rest == "" || rest == expression[next:] {
		return nil // the name alone, or followed directly by an operator
	}
	if c := rest[0]; isIdentByte(c) || isCypherQuoteByte(c) || c == '$' {
		token, _, _ := scanIdentifierToken(rest, 0)
		if token == "" {
			token = rest[:1]
		}
		if !isExpressionContinuationWord(token) {
			return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
				localization.CypherCoreInvalidInputExpectedExpression(token))
		}
	}
	return nil
}

func projectionAliasError(ctx context.Context, item string) error {
	// The alias follows the item's own AS (projectionAliasIndex), so an alias
	// named as is a name (WITH n AS as, #894).
	as := projectionAliasIndex(ctx, item)
	if as < 0 {
		return nil
	}
	alias := strings.TrimSpace(item[as+len("AS"):])
	if alias == "" {
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			localization.CypherCoreInvalidInput(""))
	}
	_, next, ok := scanSymbolicName(alias, 0)
	if !ok || next == len(alias) {
		return nil
	}
	rest := strings.TrimSpace(alias[next:])
	token, _, _ := scanIdentifierToken(rest, 0)
	if token == "" {
		token = rest[:1]
	}
	return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
		localization.CypherCoreInvalidInputExpectedExpression(token))
}

func sharedClauseSyntaxError(message string) error {
	return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", message)
}

func validateProcedureArgumentCount(spec ProcedureSpec, count int) error {
	if spec.MinArgs > 0 && count < spec.MinArgs {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidNumberOfArguments",
			fmt.Sprintf("procedure %s requires at least %d arguments, got %d", spec.Name, spec.MinArgs, count),
		)
	}
	if spec.MaxArgs >= 0 && count > spec.MaxArgs {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidNumberOfArguments",
			fmt.Sprintf("procedure %s accepts at most %d arguments, got %d", spec.Name, spec.MaxArgs, count),
		)
	}
	return nil
}

func validateProcedureYieldBindings(yield *yieldClause, hasTail bool) error {
	if yield == nil {
		return nil
	}
	if yield.yieldAll && hasTail {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"UnexpectedSyntax",
			"YIELD * is only valid for a standalone procedure call",
		)
	}

	bindings := make(map[string]struct{}, len(yield.items))
	for _, item := range yield.items {
		binding := item.column()
		binding = normalizeProjectionColumnName(binding)
		if _, exists := bindings[binding]; exists {
			return newSemanticError(
				"Neo.ClientError.Statement.SyntaxError",
				"VariableAlreadyBound",
				fmt.Sprintf("variable %s is already bound by this YIELD clause", binding),
			)
		}
		bindings[binding] = struct{}{}
	}
	return nil
}

func parseRemoveItems(body string) ([]removeItem, error) {
	parts := splitTopLevelComma(body)
	items := make([]removeItem, 0, len(parts))
	for _, part := range parts {
		item := strings.TrimSpace(part)
		if item == "" {
			continue
		}
		if variable, chain, hasLabels := splitNodeHead(item); hasLabels && isValidIdentifier(variable) {
			labels, err := setLabelChainItems(chain)
			if err != nil {
				return nil, err
			}
			items = append(items, removeItem{variable: variable, labels: labels})
			continue
		}
		receiver, inner, subscript, ok := staticPostfixSplit(item)
		variable := ""
		if ok {
			variable, _, _ = parseSetAssignmentTarget(receiver)
		}
		if !isValidIdentifier(variable) || (subscript && strings.TrimSpace(inner) == "") {
			return nil, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidSyntax", localization.CypherMutationsRemoveItemInvalid(item))
		}
		if subscript {
			items = append(items, removeItem{variable: variable, key: strings.TrimSpace(inner)})
			continue
		}
		items = append(items, removeItem{variable: variable, property: normalizePropertyKey(inner)})
	}
	return items, nil
}

func validateReturnOrderBySemanticScopeIn(ctx context.Context, clause string, retained typeScope) error {
	body := strings.TrimSpace(clause[len("RETURN"):])
	orderIndex := topLevelKeywordIndex(body, "ORDER BY")
	if orderIndex < 0 {
		return nil
	}
	projectionBody := strings.TrimSpace(body[:orderIndex])
	orderBody := strings.TrimSpace(body[keywordEndAt(body, orderIndex, "ORDER BY"):])
	for _, keyword := range []string{"SKIP", "LIMIT"} {
		if index := topLevelKeywordIndex(orderBody, keyword); index >= 0 {
			orderBody = strings.TrimSpace(orderBody[:index])
		}
	}
	projectionBody, distinct := cutDistinct(projectionBody)

	aliases := make(map[string]struct{})
	directExpressions := make(map[string]struct{})
	complexReferences := make(map[string]struct{})
	projectedAggregates := make(map[string]struct{})
	hasProjectionAggregate := false
	// star: a * item projects every variable in scope, so ORDER BY may use
	// any of them (RETURN DISTINCT *, x AS y ORDER BY z, #883).
	star := false
	for _, item := range splitTopLevelComma(projectionBody) {
		expression, alias := parseProjectionExprAlias(ctx, strings.TrimSpace(item))
		if expression == "*" {
			star = true
			continue
		}
		if alias != "" && alias != expression {
			aliases[normalizeProjectionColumnName(alias)] = struct{}{}
		}
		if containsAggregateFunc(expression) {
			hasProjectionAggregate = true
			for _, call := range semanticAggregateCalls(expression) {
				projectedAggregates[canonicalSemanticExpression(call)] = struct{}{}
			}
			continue
		}
		if reference := directSemanticReference(expression); reference != "" {
			directExpressions[reference] = struct{}{}
			continue
		}
		for _, reference := range semanticFreeReferences(expression) {
			complexReferences[reference] = struct{}{}
		}
	}

	for _, term := range parseOrderByClause(orderBody) {
		expression := term.column
		hasOrderAggregate := containsAggregateFunc(expression)
		if hasOrderAggregate && !hasProjectionAggregate {
			return newSemanticError(
				"Neo.ClientError.Statement.SyntaxError",
				"InvalidAggregation",
				"ORDER BY cannot introduce an aggregate after a non-aggregating RETURN",
			)
		}
		if !distinct && !hasOrderAggregate {
			continue
		}
		if hasOrderAggregate {
			for _, call := range semanticAggregateCalls(expression) {
				if _, projected := projectedAggregates[canonicalSemanticExpression(call)]; projected {
					continue
				}
				references := semanticFreeReferences(call)
				if len(references) > 0 {
					return createUndefinedVariableError(strings.SplitN(references[0], ".", 2)[0])
				}
				return newSemanticError(
					"Neo.ClientError.Statement.SyntaxError",
					"InvalidAggregation",
					"ORDER BY aggregate must be projected by the same horizon",
				)
			}
		}
		scalarExpression := expression
		if hasOrderAggregate {
			scalarExpression = removeAggregateCalls(expression)
		}
		for _, reference := range semanticFreeReferencesIn(expression, scalarExpression) {
			if _, projectedAlias := aliases[reference]; projectedAlias {
				continue
			}
			if _, projectedDirectly := directExpressions[reference]; projectedDirectly {
				continue
			}
			baseReference := strings.SplitN(reference, ".", 2)[0]
			if _, global := retained[baseReference]; global {
				continue
			}
			if _, projectedEntity := directExpressions[baseReference]; projectedEntity || star {
				continue
			}
			if hasOrderAggregate {
				if _, partOfComplexProjection := complexReferences[reference]; partOfComplexProjection {
					return newSemanticError(
						"Neo.ClientError.Statement.SyntaxError",
						"AmbiguousAggregationExpression",
						"ORDER BY mixes aggregation with a non-grouping subexpression",
					)
				}
			}
			return createUndefinedVariableError(baseReference)
		}
	}
	return nil
}

func validateReturnAggregationSemanticsIn(ctx context.Context, body string, outer typeScope) error {
	end := len(body)
	for _, keyword := range []string{"ORDER BY", "SKIP", "LIMIT"} {
		if index := topLevelKeywordIndex(body, keyword); index >= 0 && index < end {
			end = index
		}
	}
	body = strings.TrimSpace(body[:end])
	body, _ = cutDistinct(body)
	directExpressions := make(map[string]struct{})
	aliases := make(map[string]struct{})
	expressions := make([]string, 0)
	for _, item := range splitTopLevelComma(body) {
		expression, alias := parseProjectionExprAlias(ctx, strings.TrimSpace(item))
		expressions = append(expressions, expression)
		if alias != "" && alias != expression {
			aliases[normalizeProjectionColumnName(alias)] = struct{}{}
		}
		if !containsAggregateFunc(expression) {
			if reference := directSemanticReference(expression); reference != "" {
				directExpressions[reference] = struct{}{}
			}
		}
	}
	for _, expression := range expressions {
		if !containsAggregateFunc(expression) {
			continue
		}
		if aggregateContains(expression, containsAggregateFunc) {
			return newSemanticError(
				"Neo.ClientError.Statement.SyntaxError",
				"NestedAggregation",
				"aggregate functions cannot contain aggregate functions",
			)
		}
		if aggregateContains(expression, func(inner string) bool {
			return containsFunctionCallNamed(inner, "rand")
		}) {
			return newSemanticError(
				"Neo.ClientError.Statement.SyntaxError",
				"NonConstantExpression",
				"non-deterministic expressions cannot be arguments to aggregate functions",
			)
		}
		// What the projection reads outside its aggregates: removeAggregateCalls
		// blanks them in place, so a local's scope is read where it is
		// (x + size(collect([x IN l | x])) reads the outer x).
		for _, reference := range semanticFreeReferencesIn(expression, removeAggregateCalls(expression)) {
			if _, constant := outer[strings.SplitN(reference, ".", 2)[0]]; constant {
				continue
			}
			if _, projected := directExpressions[reference]; projected {
				continue
			}
			if _, projectedAlias := aliases[reference]; projectedAlias {
				continue
			}
			return newSemanticError(
				"Neo.ClientError.Statement.SyntaxError",
				"AmbiguousAggregationExpression",
				"aggregate expression contains an implicit grouping expression",
			)
		}
	}
	return nil
}

