package cypher

import (
	"context"
	"sort"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
)

// validateProjectionSemantics checks WITH projection aliases first, then
// Neo4j's rule for a WITH or RETURN
// with DISTINCT or an aggregation (#907): its WHERE and ORDER BY see only
// what the projection carries. A variable there must be one of the
// projection's names, or sit inside an expression the projection projects
// (RETURN x + 1 AS y, count(*) ORDER BY x + 1; RETURN count(*) AS c ORDER BY
// count(*)). Anything else read from before the clause (ORDER BY x after
// RETURN x + 1 AS y, count(*); ORDER BY sum(x) after RETURN count(*)) is a
// SyntaxError. A projection with * carries every variable.
func validateProjectionSemantics(ctx context.Context, cypher string) error {
	clauses, ok := splitPipelineClauses(ctx, cypher)
	if !ok {
		return ctx.Err()
	}
	// Preserve statement admission order: every WITH alias/aggregation check
	// precedes projection-tail scope checks, even on an earlier RETURN.
	for _, clause := range clauses {
		if clause.kind != pipelineClauseWith {
			continue
		}
		body := projectionSemanticBody(clause.text, "WITH")
		if err := validateReturnAggregationSemantics(ctx, body); err != nil {
			return err
		}
		seen := make(map[string]struct{})
		for _, raw := range splitTopLevelComma(body) {
			item := strings.TrimSpace(raw)
			if item == "" || item == "{}" {
				continue
			}
			expression, alias := parseProjectionExprAlias(ctx, item)
			if err := validateExpressionOperandCompleteness(expression); err != nil {
				return err
			}
			explicitAlias := projectionAliasIndex(ctx, item) > 0
			// true, false and null are literals, not variables, even when a
			// variable of that name was declared (isLiteralKeyword).
			if !explicitAlias && expression != "*" && !projectionHasVariableIdentity(ctx, expression) {
				if containsMalformedCreateClauseToken(expression) {
					continue
				}
				return newSemanticError(
					"Neo.ClientError.Statement.SyntaxError",
					"NoExpressionAlias",
					"expressions in WITH must be explicitly aliased",
				)
			}
			name := normalizeProjectionColumnName(alias)
			if name == "*" {
				continue
			}
			if _, duplicate := seen[name]; duplicate {
				return newSemanticError(
					"Neo.ClientError.Statement.SyntaxError",
					"ColumnNameConflict",
					"multiple WITH items project the same column name: "+name,
				)
			}
			seen[name] = struct{}{}
		}
	}
	for _, clause := range clauses {
		keyword := ""
		switch clause.kind {
		case pipelineClauseWith:
			keyword = "WITH"
		case pipelineClauseReturn:
			keyword = "RETURN"
		default:
			continue
		}
		if err := aggregatingProjectionScopeError(ctx, strings.TrimSpace(clause.text), keyword); err != nil {
			return err
		}
	}
	return nil
}

// aggregatingProjectionScopeError checks one WITH or RETURN clause
// (validateProjectionSemantics).
func aggregatingProjectionScopeError(ctx context.Context, clause, keyword string) error {
	body, tail := projectionSemanticBodyAndTail(clause, keyword)
	_, distinct := cutDistinct(clause[len(keyword):])
	tail = strings.TrimSpace(tail)
	if tail == "" {
		return nil
	}
	items := splitTopLevelComma(body)
	aliases := make(map[string]struct{}, len(items)+1)
	aliases[projectedExpressionPlaceholder] = struct{}{}
	expressions := make([]string, 0, len(items))
	aggregates := false
	for _, item := range items {
		expression, alias := parseProjectionExprAlias(ctx, strings.TrimSpace(item))
		expression = strings.TrimSpace(expression)
		if expression == "*" {
			return nil
		}
		aggregates = aggregates || containsAggregateFunc(expression)
		aliases[normalizeProjectionColumnName(alias)] = struct{}{}
		expressions = append(expressions, strings.Join(strings.Fields(expression), " "))
	}
	if !aggregates && !distinct {
		return nil
	}
	// Longest first, so a projected x + 1 is masked whole before a
	// projected x inside it.
	sort.Slice(expressions, func(i, j int) bool { return len(expressions[i]) > len(expressions[j]) })
	// An aggregate call spelled otherwise (COUNT(distinct n) for a
	// projected count(DISTINCT n)) is the projected one.
	var spellings map[string]string
	spelled := false
	for _, part := range aggregatingProjectionTailExpressions(tail) {
		masked := strings.Join(strings.Fields(part), " ")
		if containsAggregateFunc(masked) {
			if !spelled {
				spellings, spelled = aggregateCallSpellings(expressions), true
			}
			masked = respellAggregateCalls(masked, spellings)
		}
		for _, expression := range expressions {
			masked = maskProjectedExpression(masked, expression)
		}
		for _, reference := range semanticFreeReferences(masked) {
			base := strings.SplitN(reference, ".", 2)[0]
			if _, projected := aliases[normalizeProjectionColumnName(base)]; projected {
				continue
			}
			return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UndefinedVariable",
				localization.CypherMatchingAggregationScopeVariable(base))
		}
	}
	return nil
}

// aggregatingProjectionTailExpressions are the expressions of a projection's
// WHERE and ORDER BY terms, in whichever order the clause has them (WITH x
// ORDER BY x LIMIT 1 WHERE x > 0); SKIP and LIMIT read no variables.
func aggregatingProjectionTailExpressions(tail string) []string {
	keywords := []string{"WHERE", "ORDER BY", "SKIP", "LIMIT"}
	starts := make([]int, len(keywords))
	for i, keyword := range keywords {
		starts[i] = topLevelKeywordIndex(tail, keyword)
	}
	segment := func(i int) string {
		if starts[i] < 0 {
			return ""
		}
		begin := starts[i] + len(keywords[i])
		end := len(tail)
		for _, other := range starts {
			if other > starts[i] && other < end {
				end = other
			}
		}
		return tail[begin:end]
	}
	var parts []string
	if where := segment(0); strings.TrimSpace(where) != "" {
		parts = append(parts, where)
	}
	for _, term := range parseOrderByClause(segment(1)) {
		parts = append(parts, term.column)
	}
	return parts
}

// projectedExpressionPlaceholder stands for a projected expression in a
// masked WHERE or ORDER BY (maskProjectedExpression).
const projectedExpressionPlaceholder = "__nornic_projected"

// maskProjectedExpression replaces each whole occurrence of a projected
// expression in text, outside quotes, with projectedExpressionPlaceholder,
// a name the check counts as projected, so the variables inside it (and a
// property read on it: m.a after a projected m) don't count as read from
// before the projection. An occurrence
// is whole when the text around it doesn't continue an identifier or a
// property access (x is not inside n.x or xy).
func maskProjectedExpression(text, expression string) string {
	if expression == "" || !strings.Contains(text, expression) {
		return text
	}
	var out strings.Builder
	for index := 0; index < len(text); {
		if end, quoted := skipCypherLexicalToken(text, index); quoted {
			out.WriteString(text[index:end])
			index = end
			continue
		}
		c := text[index]
		end := index + len(expression)
		if strings.HasPrefix(text[index:], expression) &&
			(index == 0 || !(isIdentByte(text[index-1]) || text[index-1] == '.' || text[index-1] == '$')) &&
			(end == len(text) || !isIdentByte(text[end])) {
			out.WriteString(projectedExpressionPlaceholder)
			index = end
			continue
		}
		out.WriteByte(c)
		index++
	}
	return out.String()
}

package cypher

import "github.com/orneryd/nornicdb/pkg/storage"

// readAlgorithmGraph is the call contract and relationship reader shared by the
// six whole-graph APOC extension algorithms. Existing (nodes, config) calls keep
// their configuration; (nodes, types, config) adds the documented type filter.
// Omitted/null types and ["*"] select all types; [] selects no relationships.
func (e *StorageExecutor) readAlgorithmGraph(procedure string, args []interface{}) (*StorageExecutor, []*storage.Node, map[string]interface{}, error) {
	var config map[string]interface{}
	var types map[string]struct{}
	second := procedureArgument(args, 1)
	if supplied, ok := second.(map[string]interface{}); ok {
		config = supplied
		if len(args) > 2 {
			return nil, nil, nil, procedureArgumentTypeError(procedure, "relationshipTypes", "LIST<STRING> or null before config", second)
		}
	} else if second != nil {
		items, list := cypherListValue(second)
		if !list {
			return nil, nil, nil, procedureArgumentTypeError(procedure, "relationshipTypes", "LIST<STRING> or MAP", second)
		}
		types = make(map[string]struct{}, len(items))
		all := false
		for _, item := range items {
			name, ok := item.(string)
			if !ok {
				return nil, nil, nil, procedureArgumentTypeError(procedure, "relationshipTypes", "LIST<STRING>", second)
			}
			if name == "*" {
				all = true
			}
			types[name] = struct{}{}
		}
		if all {
			types = nil
		}
	}
	if len(args) > 2 && args[2] != nil {
		var ok bool
		config, ok = args[2].(map[string]interface{})
		if !ok {
			return nil, nil, nil, procedureArgumentTypeError(procedure, "config", "MAP", args[2])
		}
	}
	graph, nodes, err := e.algorithmIdentityInput(procedure, args)
	if err != nil {
		return nil, nil, nil, err
	}
	if types == nil {
		return graph, nodes, config, nil
	}
	return graph.cloneWithStorage(&algorithmRelationshipReader{Engine: graph.storage, types: types}), nodes, config, nil
}

// Filter each adjacency read at the shared storage boundary, keeping direction,
// multiplicity and relationship properties for the consuming algorithm. Never
// mutate a storage-owned slice or retain a graph-sized cross-read identity set.
type algorithmRelationshipReader struct {
	storage.Engine
	types map[string]struct{}
}

func (r *algorithmRelationshipReader) selectEdges(edges []*storage.Edge, err error) ([]*storage.Edge, error) {
	if err != nil {
		return nil, err
	}
	selected := make([]*storage.Edge, 0, len(edges))
	for _, edge := range edges {
		if _, allowed := r.types[edge.Type]; allowed {
			selected = append(selected, edge)
		}
	}
	return selected, nil
}

func (r *algorithmRelationshipReader) GetOutgoingEdges(id storage.NodeID) ([]*storage.Edge, error) {
	return r.selectEdges(r.Engine.GetOutgoingEdges(id))
}

func (r *algorithmRelationshipReader) GetIncomingEdges(id storage.NodeID) ([]*storage.Edge, error) {
	return r.selectEdges(r.Engine.GetIncomingEdges(id))
}

// SubscribeEvents preserves storage event delivery through the relationship
// filter. Algorithm reads filter adjacency only; storage events remain intact.
func (r *algorithmRelationshipReader) SubscribeEvents(handlers storage.EventHandlers) error {
	return storage.SubscribeEvents(r.Engine, handlers)
}

var _ storage.EventSubscriber = (*algorithmRelationshipReader)(nil)

// Package cypher implements APOC graph algorithms for Neo4j compatibility.
package cypher

import (
	"container/heap"
	"context"
	"fmt"
	math "github.com/orneryd/nornicdb/pkg/math/libm"
	"sort"

	"github.com/orneryd/nornicdb/pkg/storage"
)

// Priority Queue for Dijkstra/A*
type pathItem struct {
	nodeID storage.NodeID
	cost   float64
	path   []storage.NodeID
	index  int
}

type priorityQueue []*pathItem

func (pq priorityQueue) Len() int           { return len(pq) }
func (pq priorityQueue) Less(i, j int) bool { return pq[i].cost < pq[j].cost }
func (pq priorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
	pq[i].index = i
	pq[j].index = j
}
func (pq *priorityQueue) Push(x interface{}) {
	item := x.(*pathItem)
	item.index = len(*pq)
	*pq = append(*pq, item)
}
func (pq *priorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	*pq = old[0 : n-1]
	return item
}

// getNodeEdges returns all edges for a node.
func (e *StorageExecutor) getNodeEdges(nodeID storage.NodeID) []*storage.Edge {
	var result []*storage.Edge
	outgoing, _ := e.storage.GetOutgoingEdges(nodeID)
	incoming, _ := e.storage.GetIncomingEdges(nodeID)
	result = append(result, outgoing...)
	result = append(result, incoming...)
	return result
}

// callApocAlgoDijkstra implements Dijkstra's shortest path.
func (e *StorageExecutor) callApocAlgoDijkstra(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	e, args = e.graphReadArguments(ctx, args, 2)
	const procedure = "apoc.algo.dijkstra"
	startID, endID, steps, err := pathAlgorithmArguments(procedure, args)
	if err != nil {
		return nil, err
	}
	weightProp, err := optionalProcedureString(procedure, args, 3, "weightPropertyName", "")
	if err != nil {
		return nil, err
	}
	// Keep the legacy omitted fallback; an explicitly supplied fifth argument
	// selects the cost of relationships without the requested weight property.
	defaultWeight := 1.0
	if value := procedureArgument(args, 4); value != nil {
		var numeric bool
		defaultWeight, numeric = strictNumericValue(value)
		if !numeric {
			return nil, procedureArgumentTypeError(procedure, "defaultWeight", "FLOAT", value)
		}
	}
	path, weight := e.dijkstra(startID, endID, steps, weightProp, defaultWeight)
	if path == nil {
		return &ExecuteResult{Columns: []string{"path", "weight"}, Rows: [][]interface{}{}}, nil
	}
	return &ExecuteResult{Columns: []string{"path", "weight"}, Rows: [][]interface{}{{e.storage.(*graphIdentityStorage).outputPath(path), weight}}}, nil
}

func (e *StorageExecutor) dijkstra(startID, endID storage.NodeID, steps []apocRelationshipStep, weightProp string, defaultWeight float64) ([]storage.NodeID, float64) {
	dist := make(map[storage.NodeID]float64)
	dist[startID] = 0
	pq := &priorityQueue{}
	heap.Init(pq)
	heap.Push(pq, &pathItem{nodeID: startID, cost: 0, path: []storage.NodeID{startID}})
	visited := make(map[storage.NodeID]bool)

	for pq.Len() > 0 {
		current := heap.Pop(pq).(*pathItem)
		if visited[current.nodeID] {
			continue
		}
		visited[current.nodeID] = true
		if current.nodeID == endID {
			return current.path, current.cost
		}
		for _, edge := range e.apocSteps(current.nodeID, steps) {
			neighbor := otherEnd(edge, current.nodeID)
			if visited[neighbor] {
				continue
			}
			weight := defaultWeight
			if weightProp != "" {
				if w, ok := edge.Properties[weightProp]; ok {
					if wf, ok := toFloat64(w); ok {
						weight = wf
					}
				}
			}
			newDist := dist[current.nodeID] + weight
			if oldDist, exists := dist[neighbor]; !exists || newDist < oldDist {
				dist[neighbor] = newDist
				newPath := append([]storage.NodeID{}, current.path...)
				newPath = append(newPath, neighbor)
				heap.Push(pq, &pathItem{nodeID: neighbor, cost: newDist, path: newPath})
			}
		}
	}
	return nil, 0
}

// callApocAlgoAStar implements A* pathfinding.
func (e *StorageExecutor) callApocAlgoAStar(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	e, args = e.graphReadArguments(ctx, args, 2)
	const procedure = "apoc.algo.aStar"
	startID, endID, steps, err := pathAlgorithmArguments(procedure, args)
	if err != nil {
		return nil, err
	}
	weightProp, err := optionalProcedureString(procedure, args, 3, "weightPropertyName", "")
	if err != nil {
		return nil, err
	}
	latProp, err := optionalProcedureString(procedure, args, 4, "latPropertyName", "lat")
	if err != nil {
		return nil, err
	}
	lonProp, err := optionalProcedureString(procedure, args, 5, "lonPropertyName", "lon")
	if err != nil {
		return nil, err
	}
	path, weight := e.astar(startID, endID, steps, weightProp, latProp, lonProp)
	if path == nil {
		return &ExecuteResult{Columns: []string{"path", "weight"}, Rows: [][]interface{}{}}, nil
	}
	return &ExecuteResult{Columns: []string{"path", "weight"}, Rows: [][]interface{}{{e.storage.(*graphIdentityStorage).outputPath(path), weight}}}, nil
}

func (e *StorageExecutor) astar(startID, endID storage.NodeID, steps []apocRelationshipStep, weightProp, latProp, lonProp string) ([]storage.NodeID, float64) {
	endNode, err := e.getQueryNode(e.storage, endID)
	if err != nil {
		return nil, 0
	}
	endLat, endLon := 0.0, 0.0
	if lat, ok := endNode.Properties[latProp]; ok {
		if f, ok := toFloat64(lat); ok {
			endLat = f
		}
	}
	if lon, ok := endNode.Properties[lonProp]; ok {
		if f, ok := toFloat64(lon); ok {
			endLon = f
		}
	}
	heuristic := func(nodeID storage.NodeID) float64 {
		node, err := e.getQueryNode(e.storage, nodeID)
		if err != nil {
			return 0
		}
		lat, lon := 0.0, 0.0
		if l, ok := node.Properties[latProp]; ok {
			if f, ok := toFloat64(l); ok {
				lat = f
			}
		}
		if l, ok := node.Properties[lonProp]; ok {
			if f, ok := toFloat64(l); ok {
				lon = f
			}
		}
		return math.Sqrt((lat-endLat)*(lat-endLat) + (lon-endLon)*(lon-endLon))
	}
	gScore := make(map[storage.NodeID]float64)
	gScore[startID] = 0
	pq := &priorityQueue{}
	heap.Init(pq)
	heap.Push(pq, &pathItem{nodeID: startID, cost: heuristic(startID), path: []storage.NodeID{startID}})
	visited := make(map[storage.NodeID]bool)

	for pq.Len() > 0 {
		current := heap.Pop(pq).(*pathItem)
		if current.nodeID == endID {
			return current.path, gScore[endID]
		}
		if visited[current.nodeID] {
			continue
		}
		visited[current.nodeID] = true
		for _, edge := range e.apocSteps(current.nodeID, steps) {
			neighbor := otherEnd(edge, current.nodeID)
			if visited[neighbor] {
				continue
			}
			weight := 1.0
			if weightProp != "" {
				if w, ok := edge.Properties[weightProp]; ok {
					if wf, ok := toFloat64(w); ok {
						weight = wf
					}
				}
			}
			tentativeG := gScore[current.nodeID] + weight
			if oldG, exists := gScore[neighbor]; !exists || tentativeG < oldG {
				gScore[neighbor] = tentativeG
				newPath := append([]storage.NodeID{}, current.path...)
				newPath = append(newPath, neighbor)
				heap.Push(pq, &pathItem{nodeID: neighbor, cost: tentativeG + heuristic(neighbor), path: newPath})
			}
		}
	}
	return nil, 0
}

// callApocAlgoAllSimplePaths finds all simple paths of at most maxNodes
// relationships, as in APOC (#1185): below 1, none.
func (e *StorageExecutor) callApocAlgoAllSimplePaths(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	e, args = e.graphReadArguments(ctx, args, 2)
	const procedure = "apoc.algo.allSimplePaths"
	startID, endID, steps, err := pathAlgorithmArguments(procedure, args)
	if err != nil {
		return nil, err
	}
	maxNodes, err := requiredProcedureInteger(procedure, args, 3, "maxNodes")
	if err != nil {
		return nil, err
	}
	var paths [][]storage.NodeID
	if maxNodes > 0 {
		paths = e.findAllSimplePaths(startID, endID, steps, int(maxNodes))
	}
	rows := make([][]interface{}, len(paths))
	for i, path := range paths {
		rows[i] = []interface{}{e.storage.(*graphIdentityStorage).outputPath(path)}
	}
	return &ExecuteResult{Columns: []string{"path"}, Rows: rows}, nil
}

func (e *StorageExecutor) findAllSimplePaths(startID, endID storage.NodeID, steps []apocRelationshipStep, maxDepth int) [][]storage.NodeID {
	var result [][]storage.NodeID
	visited := make(map[storage.NodeID]bool)
	var dfs func(current storage.NodeID, path []storage.NodeID, depth int)
	dfs = func(current storage.NodeID, path []storage.NodeID, depth int) {
		if depth > maxDepth {
			return
		}
		if current == endID {
			pathCopy := make([]storage.NodeID, len(path))
			copy(pathCopy, path)
			result = append(result, pathCopy)
			return
		}
		visited[current] = true
		defer func() { visited[current] = false }()
		for _, edge := range e.apocSteps(current, steps) {
			neighbor := otherEnd(edge, current)
			if visited[neighbor] {
				continue
			}
			dfs(neighbor, append(path, neighbor), depth+1)
		}
	}
	dfs(startID, []storage.NodeID{startID}, 0)
	return result
}

// callApocAlgoPageRank computes PageRank.
func (e *StorageExecutor) callApocAlgoPageRank(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	const procedure = "apoc.algo.pageRank"
	graph, nodes, config, err := e.readAlgorithmGraph(procedure, args)
	if err != nil {
		return nil, err
	}
	// The config map: iterations (default 20) and dampingFactor (0.85).
	iterations, damping := 20, 0.85
	if n, ok := fastRPConfigInt(config["iterations"]); ok && n > 0 {
		iterations = n
	}
	if d, ok := toFloat64(config["dampingFactor"]); ok && d > 0 && d < 1 {
		damping = d
	}
	scores := graph.computePageRank(nodes, damping, iterations)
	rows := graphAlgorithmRows(nodes, scores)
	return &ExecuteResult{Columns: []string{"node", "score"}, Rows: rows}, nil
}

// computePageRank ranks the given nodes over the relationships between
// them: a relationship to a node outside the set carries no score, and no
// outside node is ranked (#1164).
func (e *StorageExecutor) computePageRank(nodes []*storage.Node, damping float64, iterations int) map[storage.NodeID]float64 {
	if len(nodes) == 0 {
		return map[storage.NodeID]float64{}
	}
	n := float64(len(nodes))
	scores := make(map[storage.NodeID]float64, len(nodes))
	newScores := make(map[storage.NodeID]float64, len(nodes))
	for _, node := range nodes {
		scores[node.ID] = 1.0 / n
	}
	targets := make(map[storage.NodeID][]storage.NodeID, len(nodes))
	for _, node := range nodes {
		edges, _ := e.storage.GetOutgoingEdges(node.ID)
		for _, edge := range edges {
			if _, inSet := scores[edge.EndNode]; inSet {
				targets[node.ID] = append(targets[node.ID], edge.EndNode)
			}
		}
	}
	for i := 0; i < iterations; i++ {
		for _, node := range nodes {
			newScores[node.ID] = (1.0 - damping) / n
		}
		for _, node := range nodes {
			if len(targets[node.ID]) == 0 {
				share := damping * scores[node.ID] / n
				for _, other := range nodes {
					newScores[other.ID] += share
				}
				continue
			}
			share := damping * scores[node.ID] / float64(len(targets[node.ID]))
			for _, target := range targets[node.ID] {
				newScores[target] += share
			}
		}
		scores, newScores = newScores, scores
	}
	return scores
}

// callApocAlgoBetweenness computes betweenness centrality.
func (e *StorageExecutor) callApocAlgoBetweenness(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	graph, nodes, _, err := e.readAlgorithmGraph("apoc.algo.betweenness", args)
	if err != nil {
		return nil, err
	}
	scores := graph.computeBetweenness(nodes)
	rows := graphAlgorithmRows(nodes, scores)
	return &ExecuteResult{Columns: []string{"node", "score"}, Rows: rows}, nil
}

func (e *StorageExecutor) computeBetweenness(nodes []*storage.Node) map[storage.NodeID]float64 {
	scores := make(map[storage.NodeID]float64)
	for _, node := range nodes {
		scores[node.ID] = 0
	}
	for _, s := range nodes {
		stack := []storage.NodeID{}
		pred := make(map[storage.NodeID][]storage.NodeID)
		sigma := make(map[storage.NodeID]float64)
		dist := make(map[storage.NodeID]int)
		for _, node := range nodes {
			pred[node.ID] = []storage.NodeID{}
			sigma[node.ID] = 0
			dist[node.ID] = -1
		}
		sigma[s.ID] = 1
		dist[s.ID] = 0
		queue := []storage.NodeID{s.ID}
		for len(queue) > 0 {
			v := queue[0]
			queue = queue[1:]
			stack = append(stack, v)
			edges, _ := e.storage.GetOutgoingEdges(v)
			for _, edge := range edges {
				w := edge.EndNode
				if dist[w] < 0 {
					queue = append(queue, w)
					dist[w] = dist[v] + 1
				}
				if dist[w] == dist[v]+1 {
					sigma[w] += sigma[v]
					pred[w] = append(pred[w], v)
				}
			}
		}
		delta := make(map[storage.NodeID]float64)
		for _, node := range nodes {
			delta[node.ID] = 0
		}
		for len(stack) > 0 {
			w := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			for _, v := range pred[w] {
				delta[v] += (sigma[v] / sigma[w]) * (1 + delta[w])
			}
			if w != s.ID {
				scores[w] += delta[w]
			}
		}
	}
	n := float64(len(nodes))
	if n > 2 {
		norm := 2.0 / ((n - 1) * (n - 2))
		for id := range scores {
			scores[id] *= norm
		}
	}
	return scores
}

// callApocAlgoCloseness computes closeness centrality.
func (e *StorageExecutor) callApocAlgoCloseness(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	graph, nodes, _, err := e.readAlgorithmGraph("apoc.algo.closeness", args)
	if err != nil {
		return nil, err
	}
	scores := graph.computeCloseness(nodes)
	rows := graphAlgorithmRows(nodes, scores)
	return &ExecuteResult{Columns: []string{"node", "score"}, Rows: rows}, nil
}

func (e *StorageExecutor) computeCloseness(nodes []*storage.Node) map[storage.NodeID]float64 {
	scores := make(map[storage.NodeID]float64)
	n := len(nodes)
	for _, source := range nodes {
		dist := make(map[storage.NodeID]int)
		for _, node := range nodes {
			dist[node.ID] = -1
		}
		dist[source.ID] = 0
		queue := []storage.NodeID{source.ID}
		totalDist := 0
		reachable := 0
		for len(queue) > 0 {
			current := queue[0]
			queue = queue[1:]
			edges := e.getNodeEdges(current)
			for _, edge := range edges {
				neighbor := edge.EndNode
				if edge.StartNode != current {
					neighbor = edge.StartNode
				}
				if dist[neighbor] < 0 {
					dist[neighbor] = dist[current] + 1
					totalDist += dist[neighbor]
					reachable++
					queue = append(queue, neighbor)
				}
			}
		}
		if reachable > 0 && totalDist > 0 {
			scores[source.ID] = float64(reachable*reachable) / (float64(totalDist) * float64(n-1))
		} else {
			scores[source.ID] = 0
		}
	}
	return scores
}

// callApocNeighborsTohop gets neighbors up to N hops.
func (e *StorageExecutor) callApocNeighborsTohop(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	e, args = e.graphReadArguments(ctx, args, 1)
	startID, relType, maxHops, err := parseNeighborArguments(args)
	if err != nil {
		return nil, err
	}
	neighbors, err := e.getNeighborsByhop(ctx, startID, relType, maxHops)
	if err != nil {
		return nil, err
	}
	rows := make([][]interface{}, 0)
	for _, group := range neighbors {
		for _, nodeID := range group {
			if nodeID == startID {
				continue
			}
			node, err := e.getQueryNode(e.storage, nodeID)
			if err != nil {
				return nil, err
			}
			rows = append(rows, []interface{}{graphIdentityNodeValue(node)})
		}
	}
	return &ExecuteResult{Columns: []string{"node"}, Rows: rows}, nil
}

func (e *StorageExecutor) getNeighborsByhop(ctx context.Context, startID storage.NodeID, relType string, maxHops int) ([][]storage.NodeID, error) {
	if relType == "" || maxHops < 1 {
		return nil, nil
	}
	filters := parseApocRelationshipFilter(relType)
	store := e.getStorage(ctx)
	if view, ok := e.storage.(*graphIdentityStorage); ok {
		store = view
	}
	visited := make(map[storage.NodeID]bool)
	visited[startID] = true
	current := []storage.NodeID{startID}
	var result [][]storage.NodeID
	for hop := 0; hop < maxHops && len(current) > 0; hop++ {
		var next []storage.NodeID
		includeStart := false
		for _, nodeID := range current {
			if err := ctx.Err(); err != nil {
				return nil, err
			}
			outgoing, err := store.GetOutgoingEdges(nodeID)
			if err != nil {
				return nil, err
			}
			incoming, err := store.GetIncomingEdges(nodeID)
			if err != nil {
				return nil, err
			}
			edges := make([]*storage.Edge, 0, len(outgoing)+len(incoming))
			edges = append(edges, outgoing...)
			edges = append(edges, incoming...)
			for _, edge := range edges {
				allowed := false
				for _, filter := range filters {
					if filter.follows(edge, nodeID) {
						allowed = true
						break
					}
				}
				if !allowed {
					continue
				}
				neighbor := edge.EndNode
				if edge.StartNode != nodeID {
					neighbor = edge.StartNode
				}
				if neighbor == startID && hop == 0 {
					includeStart = true
				}
				if !visited[neighbor] {
					visited[neighbor] = true
					next = append(next, neighbor)
				}
			}
		}
		group := next
		if includeStart {
			group = append(group, startID)
		}
		result = append(result, group)
		current = next
	}
	return result, nil
}

// callApocNeighborsByhop gets neighbors grouped by hop.
func (e *StorageExecutor) callApocNeighborsByhop(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	e, args = e.graphReadArguments(ctx, args, 1)
	startID, relType, maxHops, err := parseNeighborArguments(args)
	if err != nil {
		return nil, err
	}
	neighborsByHop, err := e.getNeighborsByhop(ctx, startID, relType, maxHops)
	if err != nil {
		return nil, err
	}
	rows := make([][]interface{}, 0)
	if relType == "" {
		return &ExecuteResult{Columns: []string{"nodes"}, Rows: rows}, nil
	}
	for depth := 0; depth < maxHops; depth++ {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		var nodeIDs []storage.NodeID
		if depth < len(neighborsByHop) {
			nodeIDs = neighborsByHop[depth]
		}
		nodesList := make([]interface{}, 0, len(nodeIDs))
		for _, nodeID := range nodeIDs {
			node, err := e.getQueryNode(e.storage, nodeID)
			if err != nil {
				return nil, err
			}
			nodesList = append(nodesList, graphIdentityNodeValue(node))
		}
		rows = append(rows, []interface{}{nodesList})
	}
	return &ExecuteResult{Columns: []string{"nodes"}, Rows: rows}, nil
}

func parseNeighborArguments(args []interface{}) (storage.NodeID, string, int, error) {
	if len(args) < 1 || len(args) > 3 {
		return "", "", 0, fmt.Errorf("neighbor procedures require between one and three arguments")
	}
	start, ok := args[0].(*storage.Node)
	if !ok || start == nil {
		return "", "", 0, fmt.Errorf("neighbor procedures require a node")
	}
	filter := ""
	if len(args) > 1 && args[1] != nil {
		filter, ok = args[1].(string)
		if !ok {
			return "", "", 0, fmt.Errorf("neighbor procedures require a relationship filter string")
		}
	}
	maxHops := 1
	if len(args) > 2 {
		if !isIntegerProcedureValue(args[2]) {
			return "", "", 0, fmt.Errorf("neighbor procedures require an integer distance")
		}
		maxHops = int(toInt64(args[2]))
	}
	return start.ID, filter, maxHops, nil
}

// pathAlgorithmArguments reads the arguments every path algorithm starts
// with: (startNode, endNode[, relTypesAndDirections]). A node may also be
// given by its id, NornicDB's kept form. relTypesAndDirections is APOC's
// "TYPE>|<TYPE|TYPE" (#1185), read as apoc.path's relationshipFilter: a type
// without a direction, and an empty filter, follow both directions.
func pathAlgorithmArguments(procedure string, args []interface{}) (start, end storage.NodeID, steps []apocRelationshipStep, err error) {
	if start, err = requiredProcedureNodeID(procedure, args, 0, "startNode"); err != nil {
		return "", "", nil, err
	}
	if end, err = requiredProcedureNodeID(procedure, args, 1, "endNode"); err != nil {
		return "", "", nil, err
	}
	filter, err := optionalProcedureString(procedure, args, 2, "relTypesAndDirections", "")
	if err != nil {
		return "", "", nil, err
	}
	return start, end, parseApocRelationshipFilter(filter), nil
}

// algorithmRows are a whole-graph algorithm's rows, {node, value}, one per
// given node that has a value, in the given nodes' order (a node listed twice
// once), so the same call on the same graph gives the same rows (#1183).
func algorithmRows[T any](nodes []*storage.Node, values map[storage.NodeID]T) [][]interface{} {
	rows := make([][]interface{}, 0, len(values))
	seen := make(map[storage.NodeID]struct{}, len(values))
	for _, node := range nodes {
		value, ok := values[node.ID]
		if _, listed := seen[node.ID]; !ok || listed {
			continue
		}
		seen[node.ID] = struct{}{}
		rows = append(rows, []interface{}{node, value})
	}
	return rows
}

// renumberInNodeOrder numbers communities 0, 1, … by their first node in the
// given nodes' order, so community IDs don't depend on map order (#1183).
func renumberInNodeOrder(nodes []*storage.Node, communities map[storage.NodeID]int) map[storage.NodeID]int {
	numbers := make(map[int]int)
	result := make(map[storage.NodeID]int, len(communities))
	for _, node := range nodes {
		community, ok := communities[node.ID]
		if !ok {
			continue
		}
		number, numbered := numbers[community]
		if !numbered {
			number = len(numbers)
			numbers[community] = number
		}
		result[node.ID] = number
	}
	return result
}

// algorithmNodes reads the nodes a whole-graph algorithm runs over from its
// first argument: a LIST<NODE> (APOC's form: MATCH (n:L) WITH collect(n) AS
// nodes CALL apoc.algo.pageRank(nodes)), a label (a STRING, or a list of
// one), or none, null, an empty string or an empty list for every node.
func (e *StorageExecutor) algorithmNodes(procedure string, args []interface{}) ([]*storage.Node, error) {
	value := procedureArgument(args, 0)
	typeError := func() error {
		return procedureArgumentTypeError(procedure, "nodes", "LIST<NODE> or STRING", procedureArgument(args, 0))
	}
	if items, isList := cypherListValue(value); isList {
		if len(items) == 0 {
			return nodesInIDOrder(e.storage.GetAllNodes()), nil
		}
		if _, isNode := items[0].(*storage.Node); isNode {
			nodes := make([]*storage.Node, 0, len(items))
			for _, item := range items {
				node, isNode := item.(*storage.Node)
				if !isNode || node == nil {
					return nil, typeError()
				}
				nodes = append(nodes, node)
			}
			return nodes, nil
		}
		if len(items) != 1 {
			return nil, typeError()
		}
		value = items[0]
	}
	switch label := value.(type) {
	case nil:
		return nodesInIDOrder(e.storage.GetAllNodes()), nil
	case string:
		if label == "" {
			return nodesInIDOrder(e.storage.GetAllNodes()), nil
		}
		nodes, _ := e.storage.GetNodesByLabel(label)
		return nodesInIDOrder(nodes), nil
	default:
		return nil, typeError()
	}
}

// nodesInIDOrder sorts the nodes an algorithm reads from storage by ID, so
// the same graph gives the same order on every engine (#1183); a node list
// the caller passes keeps its order. It sorts a copy: storage may share the
// slice it returns.
func nodesInIDOrder(nodes []*storage.Node) []*storage.Node {
	sorted := append([]*storage.Node(nil), nodes...)
	sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].ID < sorted[j].ID })
	return sorted
}

// Package cypher implements APOC community detection algorithms.
package cypher

import (
	"context"

	"github.com/orneryd/nornicdb/pkg/louvain"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// =============================================================================
// apoc.algo.louvain - Louvain Community Detection
// =============================================================================

// callApocAlgoLouvain implements the Louvain community detection algorithm.
// Syntax: CALL apoc.algo.louvain(['Label'], {write: false, weightProperty: 'weight'}) YIELD node, community
//
// The Louvain method is a greedy optimization method for community detection that
// maximizes modularity. It works in two phases:
// 1. Local optimization: Each node is moved to the community that yields the best modularity gain
// 2. Network aggregation: Communities are aggregated into super-nodes
// These phases repeat until no further improvement is possible.
func (e *StorageExecutor) callApocAlgoLouvain(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	graph, nodes, config, err := e.readAlgorithmGraph("apoc.algo.louvain", args)
	if err != nil {
		return nil, err
	}
	// The config map may name the relationship weight property.
	weightProp, _ := config["weightProperty"].(string)

	// Run Louvain algorithm
	communities := graph.computeLouvain(nodes, weightProp)

	// Build result
	rows := graphAlgorithmRows(nodes, communities)

	return &ExecuteResult{
		Columns: []string{"node", "community"},
		Rows:    rows,
	}, nil
}

// computeLouvain is Louvain community detection (#1184), as GDS's
// gds.louvain computes it over an undirected graph: the relationships
// between the given nodes, preserving parallel arcs (weightProp's
// value, 1 without it). Each level moves nodes, in the given order, to the
// neighbouring community with the best modularity gain until no move
// helps, then merges each community into one node; levels repeat until a
// level moves nothing (louvain.Run, louvain.DefaultOptions). Communities are
// numbered by their first node.
func (e *StorageExecutor) computeLouvain(nodes []*storage.Node, weightProp string) map[storage.NodeID]int {
	if len(nodes) == 0 {
		return map[storage.NodeID]int{}
	}
	index := make(map[storage.NodeID]int, len(nodes))
	unique := make([]*storage.Node, 0, len(nodes))
	for _, node := range nodes {
		if _, listed := index[node.ID]; !listed {
			index[node.ID] = len(unique)
			unique = append(unique, node)
		}
	}
	var relationships []*storage.Edge
	for _, node := range unique {
		// Enumerate physical relationships once. Undirected expansion and
		// degree/weight accounting belong to louvain.RunUndirected;
		// outgoing+incoming incidence lists repeat a physical self-loop.
		edges, _ := e.storage.GetOutgoingEdges(node.ID)
		relationships = append(relationships, edges...)
	}
	membership := louvain.Final(louvain.RunUndirected(len(unique), len(relationships), func(i int) (int, int, float64, bool) {
		edge := relationships[i]
		source, sourceFound := index[edge.StartNode]
		target, targetFound := index[edge.EndNode]
		weight := 1.0
		if weightProp != "" {
			if w, ok := toFloat64(edge.Properties[weightProp]); ok {
				weight = w
			}
		}
		return source, target, weight, sourceFound && targetFound
	}, louvain.DefaultOptions()))
	result := make(map[storage.NodeID]int, len(unique))
	for i, node := range unique {
		result[node.ID] = membership[i]
	}
	return result
}

// =============================================================================
// apoc.algo.labelPropagation - Label Propagation Community Detection
// =============================================================================

// callApocAlgoLabelPropagation implements label propagation community detection.
// Syntax: CALL apoc.algo.labelPropagation(['Label']) YIELD node, community
//
// Label propagation is a simpler community detection algorithm where each node
// adopts the label that most of its neighbors have.
func (e *StorageExecutor) callApocAlgoLabelPropagation(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	graph, nodes, _, err := e.readAlgorithmGraph("apoc.algo.labelPropagation", args)
	if err != nil {
		return nil, err
	}

	communities := graph.computeLabelPropagation(nodes)

	rows := graphAlgorithmRows(nodes, communities)

	return &ExecuteResult{
		Columns: []string{"node", "community"},
		Rows:    rows,
	}, nil
}

func (e *StorageExecutor) computeLabelPropagation(nodes []*storage.Node) map[storage.NodeID]int {

	if len(nodes) == 0 {
		return map[storage.NodeID]int{}
	}

	// Initialize: each node gets its own label
	labels := make(map[storage.NodeID]int)
	for i, node := range nodes {
		labels[node.ID] = i
	}

	// Iterate until convergence
	maxIterations := 20
	for iter := 0; iter < maxIterations; iter++ {
		changed := false

		for _, node := range nodes {
			// Count neighbor labels
			labelCount := make(map[int]int)
			edges := e.getNodeEdges(node.ID)

			for _, edge := range edges {
				neighbor := edge.EndNode
				if edge.StartNode != node.ID {
					neighbor = edge.StartNode
				}
				if neighborLabel, ok := labels[neighbor]; ok {
					labelCount[neighborLabel]++
				}
			}

			if len(labelCount) == 0 {
				continue
			}

			// Find most common label
			maxCount := 0
			bestLabel := labels[node.ID]
			for l, count := range labelCount {
				if count > maxCount || (count == maxCount && l < bestLabel) {
					maxCount = count
					bestLabel = l
				}
			}

			if bestLabel != labels[node.ID] {
				labels[node.ID] = bestLabel
				changed = true
			}
		}

		if !changed {
			break
		}
	}

	// Communities numbered by their first node in the given order (#1183).
	return renumberInNodeOrder(nodes, labels)
}

// =============================================================================
// apoc.algo.wcc - Weakly Connected Components
// =============================================================================

// callApocAlgoWCC implements Weakly Connected Components detection.
// Syntax: CALL apoc.algo.wcc(['Label']) YIELD node, componentId
func (e *StorageExecutor) callApocAlgoWCC(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	graph, nodes, _, err := e.readAlgorithmGraph("apoc.algo.wcc", args)
	if err != nil {
		return nil, err
	}

	components := graph.computeWCC(nodes)

	rows := graphAlgorithmRows(nodes, components)

	return &ExecuteResult{
		Columns: []string{"node", "componentId"},
		Rows:    rows,
	}, nil
}

func (e *StorageExecutor) computeWCC(nodes []*storage.Node) map[storage.NodeID]int {

	if len(nodes) == 0 {
		return map[storage.NodeID]int{}
	}

	// Union-Find structure
	parent := make(map[storage.NodeID]storage.NodeID)
	rank := make(map[storage.NodeID]int)

	for _, node := range nodes {
		parent[node.ID] = node.ID
		rank[node.ID] = 0
	}

	// Find with path compression
	var find func(x storage.NodeID) storage.NodeID
	find = func(x storage.NodeID) storage.NodeID {
		if parent[x] != x {
			parent[x] = find(parent[x])
		}
		return parent[x]
	}

	// Union by rank
	union := func(x, y storage.NodeID) {
		px, py := find(x), find(y)
		if px == py {
			return
		}
		if rank[px] < rank[py] {
			parent[px] = py
		} else if rank[px] > rank[py] {
			parent[py] = px
		} else {
			parent[py] = px
			rank[px]++
		}
	}

	// Process all edges
	for _, node := range nodes {
		edges := e.getNodeEdges(node.ID)
		for _, edge := range edges {
			neighbor := edge.EndNode
			if edge.StartNode != node.ID {
				neighbor = edge.StartNode
			}
			if _, exists := parent[neighbor]; exists {
				union(node.ID, neighbor)
			}
		}
	}

	// Assign component IDs
	componentMap := make(map[storage.NodeID]int)
	nextID := 0
	result := make(map[storage.NodeID]int)

	for _, node := range nodes {
		root := find(node.ID)
		if id, exists := componentMap[root]; exists {
			result[node.ID] = id
		} else {
			componentMap[root] = nextID
			result[node.ID] = nextID
			nextID++
		}
	}

	return result
}

package cypher

import (
	"context"
	"encoding/base64"
	"strings"
	"time"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/util"
)

// apocCustomPrefix is the namespace APOC gives a custom procedure: one
// installed as walk is called as custom.walk (#1066).
const apocCustomPrefix = "custom."

// customSignature is a parsed apoc.custom signature,
// name(argument [= default] :: TYPE, ...) :: (output :: TYPE, ...).
type customSignature struct {
	name     string
	args     []string
	types    []string
	defaults []string
	outputs  []ProcedureColumn
}

// parseCustomSignature parses an apoc.custom signature. A default may come
// before or after the type (depth = 2 :: INTEGER, depth :: INTEGER = 2); the
// outputs may be omitted or VOID.
func parseCustomSignature(signature string) (customSignature, bool) {
	signature = strings.TrimSpace(signature)
	open := strings.IndexByte(signature, '(')
	if open <= 0 {
		return customSignature{}, false
	}
	closing := findMatchingParen(signature, open)
	if closing < 0 {
		return customSignature{}, false
	}
	parsed := customSignature{name: strings.TrimPrefix(strings.TrimSpace(signature[:open]), apocCustomPrefix)}
	for _, part := range strings.Split(parsed.name, ".") {
		if !isValidIdentifier(part) {
			return customSignature{}, false
		}
	}
	seen := map[string]bool{}
	for _, part := range splitTopLevelComma(signature[open+1 : closing]) {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		name, typeName, defaultLiteral := part, "ANY", ""
		if separator := strings.Index(part, "::"); separator >= 0 {
			name, typeName = strings.TrimSpace(part[:separator]), strings.TrimSpace(part[separator+2:])
			if equals := strings.Index(typeName, "="); equals >= 0 {
				defaultLiteral, typeName = strings.TrimSpace(typeName[equals+1:]), strings.TrimSpace(typeName[:equals])
			}
		}
		if equals := strings.Index(name, "="); equals >= 0 {
			defaultLiteral, name = strings.TrimSpace(name[equals+1:]), strings.TrimSpace(name[:equals])
		}
		name = strings.TrimPrefix(name, "$")
		if !isValidIdentifier(name) || seen[name] || typeName == "" {
			return customSignature{}, false
		}
		if defaultLiteral == "" && len(parsed.defaults) > 0 && parsed.defaults[len(parsed.defaults)-1] != "" {
			return customSignature{}, false // a required argument after an optional one
		}
		seen[name] = true
		parsed.args = append(parsed.args, name)
		parsed.types = append(parsed.types, upperASCII(typeName))
		parsed.defaults = append(parsed.defaults, defaultLiteral)
	}
	rest := strings.TrimSpace(signature[closing+1:])
	if rest == "" {
		return parsed, true
	}
	if !strings.HasPrefix(rest, "::") {
		return customSignature{}, false
	}
	rest = strings.TrimSpace(rest[2:])
	if strings.EqualFold(rest, "VOID") {
		return parsed, true
	}
	inner, ok := stripEnclosingRowDelimiter(rest, '(', ')')
	if !ok {
		return customSignature{}, false
	}
	for _, part := range splitTopLevelComma(inner) {
		name, typeName, found := strings.Cut(part, "::")
		name, typeName = strings.TrimSpace(name), strings.TrimSpace(typeName)
		if !found || !isValidIdentifier(name) || typeName == "" {
			return customSignature{}, false
		}
		parsed.outputs = append(parsed.outputs, ProcedureColumn{Name: name, Type: upperASCII(typeName)})
	}
	return parsed, true
}

// text renders the signature as the registry lists it.
func (s customSignature) text() string {
	args := make([]string, len(s.args))
	for i, arg := range s.args {
		args[i] = arg + " :: " + s.types[i]
		if s.defaults[i] != "" {
			args[i] = arg + " = " + s.defaults[i] + " :: " + s.types[i]
		}
	}
	out := apocCustomPrefix + s.name + "(" + strings.Join(args, ", ") + ")"
	if len(s.outputs) == 0 {
		return out + " :: VOID"
	}
	outputs := make([]string, len(s.outputs))
	for i, column := range s.outputs {
		outputs[i] = column.Name + " :: " + column.Type
	}
	return out + " :: (" + strings.Join(outputs, ", ") + ")"
}

// customStringArgument reads args[index] as a STRING, fallback when absent
// or null.
func customStringArgument(procedure string, args []interface{}, index int, name, fallback string) (string, error) {
	if index >= len(args) || args[index] == nil {
		return fallback, nil
	}
	text, ok := args[index].(string)
	if !ok {
		return "", localizedError(localization.CypherProceduresCustomArgumentType(procedure, name, "STRING"), nil)
	}
	return text, nil
}

// callApocCustomInstall installs a custom procedure from its signature and
// statement, replacing one of the same name, as APOC does. installProcedure
// takes (signature, statement, databaseName, mode, description) and
// declareProcedure (signature, statement, mode, description); the procedure
// is installed in the current database.
func (e *StorageExecutor) callApocCustomInstall(ctx context.Context, procedure string, args []interface{}, hasDatabaseName bool) (*ExecuteResult, error) {
	if e.txContext != nil && e.txContext.active {
		return nil, localizedError(localization.CypherProceduresCreateInTransaction(), nil)
	}
	signatureText, err := customStringArgument(procedure, args, 0, "signature", "")
	if err != nil {
		return nil, err
	}
	statement, err := customStringArgument(procedure, args, 1, "statement", "")
	if err != nil {
		return nil, err
	}
	next := 2
	if hasDatabaseName {
		if _, err := customStringArgument(procedure, args, next, "databaseName", "neo4j"); err != nil {
			return nil, err
		}
		next++
	}
	mode, err := customStringArgument(procedure, args, next, "mode", "read")
	if err != nil {
		return nil, err
	}
	description, err := customStringArgument(procedure, args, next+1, "description", "")
	if err != nil {
		return nil, err
	}
	signature, ok := parseCustomSignature(signatureText)
	if !ok {
		return nil, localizedError(localization.CypherProceduresCustomSignatureInvalid(signatureText), nil)
	}
	if strings.TrimSpace(statement) == "" {
		return nil, localizedError(localization.CypherProceduresBodyRequired(), nil)
	}
	minArgs := 0
	for minArgs < len(signature.defaults) && signature.defaults[minArgs] == "" {
		minArgs++
	}
	err = e.installPersistedProcedure(ctx, persistedProcedureRecord{
		Name:        apocCustomPrefix + signature.name,
		ArgNames:    signature.args,
		Mode:        upperASCII(strings.TrimSpace(mode)),
		Body:        strings.TrimSpace(statement),
		Signature:   signature.text(),
		Description: description,
		MinArgs:     minArgs,
		MaxArgs:     len(signature.args),
		UpdatedAt:   time.Now().UTC().Unix(),
		ArgTypes:    signature.types,
		ArgDefaults: signature.defaults,
		Outputs:     signature.outputs,
	}, true)
	if err != nil {
		return nil, err
	}
	return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
}

// callApocCustomDrop drops a custom procedure installed in the current
// database: apoc.custom.dropProcedure(name, databaseName).
func (e *StorageExecutor) callApocCustomDrop(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	const procedure = "apoc.custom.dropProcedure"
	if e.txContext != nil && e.txContext.active {
		return nil, localizedError(localization.CypherProceduresDropInTransaction(), nil)
	}
	name, err := customStringArgument(procedure, args, 0, "name", "")
	if err != nil {
		return nil, err
	}
	if _, err := customStringArgument(procedure, args, 1, "databaseName", "neo4j"); err != nil {
		return nil, err
	}
	if err := e.dropPersistedProcedure(ctx, apocCustomPrefix+strings.TrimPrefix(strings.TrimSpace(name), apocCustomPrefix)); err != nil {
		return nil, err
	}
	return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
}

// callApocCustomList lists the custom procedures installed in the current
// database, in APOC's columns: apoc.custom.list() and apoc.custom.show().
func (e *StorageExecutor) callApocCustomList(ctx context.Context) (*ExecuteResult, error) {
	result := &ExecuteResult{Columns: []string{"type", "name", "description", "mode", "statement", "inputs", "outputs", "forceSingle"}, Rows: [][]interface{}{}}
	nodes, err := e.getStorage(ctx).GetNodesByLabel(procedureCatalogLabel)
	if err != nil {
		return nil, localizedError(localization.CypherProceduresCatalogReadFailed(err), err)
	}
	for _, node := range nodes {
		encoded, _ := node.Properties["record"].(string)
		payload, err := base64.StdEncoding.DecodeString(encoded)
		if err != nil {
			continue
		}
		var record persistedProcedureRecord
		if util.DecodeMsgpackBytes(payload, &record) != nil || !strings.HasPrefix(record.Name, apocCustomPrefix) {
			continue
		}
		inputs := make([]interface{}, len(record.ArgNames))
		for i, arg := range record.ArgNames {
			input := []interface{}{arg, "ANY"}
			if i < len(record.ArgTypes) {
				input[1] = lowerASCII(record.ArgTypes[i])
			}
			if i < len(record.ArgDefaults) && record.ArgDefaults[i] != "" {
				input = append(input, record.ArgDefaults[i])
			}
			inputs[i] = input
		}
		outputs := make([]interface{}, len(record.Outputs))
		for i, column := range record.Outputs {
			outputs[i] = []interface{}{column.Name, lowerASCII(column.Type)}
		}
		result.Rows = append(result.Rows, []interface{}{
			"procedure", strings.TrimPrefix(record.Name, apocCustomPrefix), record.Description,
			lowerASCII(record.Mode), record.Body, inputs, outputs, false,
		})
	}
	return result, nil
}

