)

var (
	errAPOCLocalImportFileAccessDisabled = errors.New("local APOC import file access is disabled")
	errAPOCLocalExportFileAccessDisabled = errors.New("local APOC export file access is disabled")
	errAPOCRemoteURLAccessDisabled       = errors.New("remote APOC URL access is disabled")
	errAPOCRemoteURLHostNotAllowed       = errors.New("APOC remote URL host is not allowlisted")
	errAPOCFileAuthorityNotAllowed       = errors.New("file URL may not contain an authority section (i.e. it should be 'file:///')")
	errAPOCFileQueryNotAllowed           = errors.New("file URL may not contain a query component")
	errAPOCFileFragmentNotAllowed        = errors.New("file URL may not contain a fragment component")
)

var defaultAPOCRemoteHTTPClient = &http.Client{
	Timeout: 10 * time.Second,
	CheckRedirect: func(req *http.Request, via []*http.Request) error {
		return http.ErrUseLastResponse
	},
	Transport: &http.Transport{
		Proxy: nil,
	},
}

type apocHostResolver func(context.Context, string) ([]net.IPAddr, error)

func (e *StorageExecutor) apocHTTPClient() *http.Client {
	if e != nil && e.apocRemoteHTTPClient != nil {
		return e.apocRemoteHTTPClient
	}
	return defaultAPOCRemoteHTTPClient
}

func (e *StorageExecutor) resolveAPOCHost(ctx context.Context, hostname string) ([]net.IPAddr, error) {
	if e != nil && e.apocRemoteHostResolver != nil {
		return e.apocRemoteHostResolver(ctx, hostname)
	}
	return net.DefaultResolver.LookupIPAddr(ctx, hostname)
}

func isHTTPSource(path string) bool {
	return strings.HasPrefix(path, "http://") || strings.HasPrefix(path, "https://")
}

func (e *StorageExecutor) ensureLocalAPOCImportFileAccessAllowed() error {
	if e != nil && e.allowLocalAPOCImportFileAccess {
		return nil
	}
	return errAPOCLocalImportFileAccessDisabled

}

func (e *StorageExecutor) ensureLocalAPOCExportFileAccessAllowed() error {
	if e != nil && e.allowLocalAPOCExportFileAccess {
		return nil
	}
	return errAPOCLocalExportFileAccessDisabled

}

func (e *StorageExecutor) ensureRemoteAPOCURLAccessAllowed() error {
	if e != nil && e.allowRemoteAPOCURLAccess {
		return nil
	}
	return errAPOCRemoteURLAccessDisabled
}

func normalizeAPOCRemoteURLAllowlist(hosts []string) []string {
	out := make([]string, 0, len(hosts))
	seen := make(map[string]struct{}, len(hosts))
	for _, host := range hosts {
		normalized := lowerASCII(strings.TrimSpace(host))
		if normalized == "" {
			continue
		}
		if _, ok := seen[normalized]; ok {
			continue
		}
		seen[normalized] = struct{}{}
		out = append(out, normalized)
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

func apocRemoteHostAllowed(hostname string, allowlist []string) bool {
	hostname = lowerASCII(strings.TrimSpace(hostname))
	if hostname == "" || len(allowlist) == 0 {
		return false
	}
	for _, entry := range allowlist {
		if entry == hostname {
			return true
		}
		if strings.HasPrefix(entry, "*.") {
			suffix := strings.TrimPrefix(entry, "*")
			if strings.HasSuffix(hostname, suffix) && hostname != strings.TrimPrefix(suffix, ".") {
				return true
			}
		}
	}
	return false
}

func (e *StorageExecutor) resolveAPOCLocalImportFilePath(source string) (string, error) {
	return e.resolveAPOCLocalFilePath(source, e.ensureLocalAPOCImportFileAccessAllowed)
}

func (e *StorageExecutor) resolveAPOCLocalExportFilePath(source string) (string, error) {
	return e.resolveAPOCLocalFilePath(source, e.ensureLocalAPOCExportFileAccessAllowed)
}

func (e *StorageExecutor) resolveAPOCLocalFilePath(source string, ensureAllowed func() error) (string, error) {
	if err := ensureAllowed(); err != nil {
		return "", err
	}

	// A native Windows drive path is a local path, not a URL scheme.
	if filepath.IsAbs(source) && filepath.VolumeName(source) != "" {
		return e.rebaseAPOCImportPath(source)
	}

	parsed, err := url.Parse(source)
	if err == nil && parsed.Scheme != "" {
		switch lowerASCII(parsed.Scheme) {
		case "file":
			if err := validateAPOCFileURL(parsed); err != nil {
				return "", err
			}
			localPath := parsed.Path
			if localPath == "" {
				localPath = parsed.Opaque
			}
			return e.rebaseAPOCImportPath(localPath)
		case "http", "https":
			return "", fmt.Errorf("expected local APOC file source, got remote URL")
		default:
			return "", fmt.Errorf("unsupported APOC file URL scheme %q", parsed.Scheme)
		}
	}

	return e.rebaseAPOCImportPath(source)
}

func validateAPOCFileURL(uri *url.URL) error {
	if uri.Host != "" {
		return errAPOCFileAuthorityNotAllowed
	}
	if uri.RawQuery != "" {
		return errAPOCFileQueryNotAllowed
	}
	if uri.Fragment != "" {
		return errAPOCFileFragmentNotAllowed
	}
	return nil
}

func (e *StorageExecutor) rebaseAPOCImportPath(localPath string) (string, error) {
	root := strings.TrimSpace(e.apocLocalFileAccessRoot)
	if root == "" {
		return filepath.Clean(localPath), nil
	}

	absRoot, err := filepath.Abs(root)
	if err != nil {
		return "", fmt.Errorf("resolve APOC import root: %w", err)
	}

	relativePath := normalizeAPOCImportRelativePath(localPath)
	target := absRoot
	if relativePath != "" {
		target = filepath.Join(absRoot, filepath.FromSlash(relativePath))
	}
	target, err = filepath.Abs(target)
	if err != nil {
		return "", fmt.Errorf("resolve APOC local file path: %w", err)
	}
	if target != absRoot && !strings.HasPrefix(target, absRoot+string(os.PathSeparator)) {
		return "", fmt.Errorf("file URL points outside configured import directory")
	}
	return target, nil
}

func normalizeAPOCImportRelativePath(localPath string) string {
	slashPath := strings.ReplaceAll(localPath, "\\", "/")
	cleaned := pathpkg.Clean("/" + strings.TrimLeft(slashPath, "/"))
	return strings.TrimPrefix(cleaned, "/")
}

func (e *StorageExecutor) validateAPOCRemoteURL(rawURL string, allowlist []string) (*url.URL, error) {
	if err := securitypkg.ValidateURL(rawURL, securitypkg.URLPolicy{}); err != nil {
		return nil, fmt.Errorf("invalid APOC remote URL: %w", err)
	}
	parsed, err := url.Parse(rawURL)
	if err != nil {
		return nil, fmt.Errorf("invalid APOC remote URL: %w", err)
	}
	if !strings.EqualFold(parsed.Scheme, "http") && !strings.EqualFold(parsed.Scheme, "https") {
		return nil, fmt.Errorf("unsupported APOC remote URL scheme %q", parsed.Scheme)
	}
	if parsed.Host == "" {
		return nil, fmt.Errorf("APOC remote URL host is required")
	}
	if parsed.User != nil {
		return nil, fmt.Errorf("APOC remote URLs may not contain userinfo")
	}
	if parsed.Fragment != "" {
		return nil, fmt.Errorf("APOC remote URLs may not contain fragments")
	}
	hostname := parsed.Hostname()
	if hostname == "" {
		return nil, fmt.Errorf("APOC remote URL host is required")
	}
	if !apocRemoteHostAllowed(hostname, allowlist) {
		return nil, errAPOCRemoteURLHostNotAllowed
	}
	ipList, err := e.resolveAPOCHost(context.Background(), hostname)
	if err != nil {
		return nil, fmt.Errorf("resolve APOC remote host: %w", err)
	}
	for _, ipAddr := range ipList {
		if ip := ipAddr.IP; ip != nil {
			if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsMulticast() || ip.IsUnspecified() {
				return nil, fmt.Errorf("APOC remote URL host resolves to a disallowed address")
			}
		}
	}
	return parsed, nil
}

func (e *StorageExecutor) newAPOCRemoteRequest(ctx context.Context, rawURL string) (*http.Request, error) {
	if err := e.ensureRemoteAPOCURLAccessAllowed(); err != nil {
		return nil, err
	}
	parsed, err := e.validateAPOCRemoteURL(rawURL, e.apocRemoteURLAllowlist)
	if err != nil {
		return nil, err
	}
	return http.NewRequestWithContext(ctx, http.MethodGet, parsed.String(), nil)
}

// =============================================================================
// apoc.load.json - Load JSON data
// =============================================================================

// callApocLoadJson loads JSON data from a URL or file path.
// Syntax: CALL apoc.load.json(urlOrFile) YIELD value
func (e *StorageExecutor) callApocLoadJson(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	// The URL or file path is the call's evaluated first argument.
	urlOrFile, err := requiredProcedureString("apoc.load.json", args, 0, "urlOrKeyOrBinary")
	if err != nil {
		return nil, err
	}

	var data interface{}

	// Check if it's a URL or file path
	if isHTTPSource(urlOrFile) {
		data, err = e.loadJsonFromURL(urlOrFile)
	} else {
		data, err = e.loadJsonFromFile(urlOrFile)
	}

	if err != nil {
		return nil, fmt.Errorf("failed to load JSON: %w", err)
	}

	// Return the data
	rows := [][]interface{}{}

	switch v := data.(type) {
	case []interface{}:
		// Array of items - return each as a row
		for _, item := range v {
			rows = append(rows, []interface{}{item})
		}
	case map[string]interface{}:
		// Single object
		rows = append(rows, []interface{}{v})
	default:
		rows = append(rows, []interface{}{data})
	}

	return &ExecuteResult{
		Columns: []string{"value"},
		Rows:    rows,
	}, nil
}

func (e *StorageExecutor) loadJsonFromURL(url string) (interface{}, error) {
	req, err := e.newAPOCRemoteRequest(context.Background(), url)
	if err != nil {
		return nil, err
	}
	resp, err := e.apocHTTPClient().Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("HTTP error: %s", resp.Status)
	}

	var data interface{}
	if err := json.NewDecoder(resp.Body).Decode(&data); err != nil {
		return nil, err
	}

	return data, nil
}

func (e *StorageExecutor) loadJsonFromFile(path string) (interface{}, error) {
	resolvedPath, err := e.resolveAPOCLocalImportFilePath(path)
	if err != nil {
		return nil, err
	}
	file, err := securitypkg.OpenRootedFile(resolvedPath, os.O_RDONLY, 0)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	var data interface{}
	if err := json.NewDecoder(file).Decode(&data); err != nil {
		return nil, err
	}

	return data, nil
}

// =============================================================================
// apoc.load.csv - Load CSV data
// =============================================================================

// callApocLoadCsv loads CSV data from a URL or file path.
// Syntax: CALL apoc.load.csv(urlOrFile, {sep: ',', header: true}) YIELD lineNo, list, map
func (e *StorageExecutor) callApocLoadCsv(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	const procedure = "apoc.load.csv"
	urlOrFile, err := requiredProcedureString(procedure, args, 0, "urlOrBinary")
	if err != nil {
		return nil, err
	}
	// Options from the config map: header (default true) and sep (its
	// first character, default ',').
	config, err := optionalProcedureMap(procedure, args, 1, "config")
	if err != nil {
		return nil, err
	}
	hasHeader := true
	if header, ok := config["header"].(bool); ok {
		hasHeader = header
	}
	separator := ','
	if sep, ok := config["sep"].(string); ok && sep != "" {
		separator = []rune(sep)[0]
	}

	var reader *csv.Reader
	var closer io.Closer

	// Load from URL or file
	if isHTTPSource(urlOrFile) {
		req, err := e.newAPOCRemoteRequest(ctx, urlOrFile)
		if err != nil {
			return nil, err
		}
		resp, err := e.apocHTTPClient().Do(req)
		if err != nil {
			return nil, fmt.Errorf("failed to fetch CSV: %w", err)
		}
		closer = resp.Body
		reader = csv.NewReader(resp.Body)
	} else {
		resolvedPath, err := e.resolveAPOCLocalImportFilePath(urlOrFile)
		if err != nil {
			return nil, err
		}
		file, err := securitypkg.OpenRootedFile(resolvedPath, os.O_RDONLY, 0)
		if err != nil {
			return nil, fmt.Errorf("failed to open CSV: %w", err)
		}
		closer = file
		reader = csv.NewReader(file)
	}
	defer closer.Close()

	reader.Comma = separator
	reader.LazyQuotes = true

	// Read all records
	records, err := reader.ReadAll()
	if err != nil {
		return nil, fmt.Errorf("failed to parse CSV: %w", err)
	}

	if len(records) == 0 {
		return &ExecuteResult{
			Columns: []string{"lineNo", "list", "map"},
			Rows:    [][]interface{}{},
		}, nil
	}

	// Build result
	rows := [][]interface{}{}
	var headers []string

	startRow := 0
	if hasHeader && len(records) > 0 {
		headers = records[0]
		startRow = 1
	}

	for i := startRow; i < len(records); i++ {
		record := records[i]
		lineNo := i + 1

		// Build map if we have headers
		recordMap := make(map[string]interface{})
		if hasHeader && headers != nil {
			for j, header := range headers {
				if j < len(record) {
					recordMap[header] = record[j]
				}
			}
		}

		// Convert record to interface slice
		list := make([]interface{}, len(record))
		for j, v := range record {
			list[j] = v
		}

		rows = append(rows, []interface{}{lineNo, list, recordMap})
	}

	return &ExecuteResult{
		Columns: []string{"lineNo", "list", "map"},
		Rows:    rows,
	}, nil
}

// =============================================================================
// apoc.export.json - Export to JSON
// =============================================================================

// callApocExportJson exports graph data to JSON.
// Syntax: CALL apoc.export.json.all(file, config) YIELD file, nodes, relationships
func (e *StorageExecutor) callApocExportJsonAll(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	// No file (or '') returns the export instead of writing it.
	filePath, err := optionalProcedureString("apoc.export.json.all", args, 0, "file", "")
	if err != nil {
		return nil, err
	}
	resolvedPath := ""
	if filePath != "" {
		var err error
		resolvedPath, err = e.resolveAPOCLocalExportFilePath(filePath)
		if err != nil {
			return nil, err
		}
	}

	nodes := e.storage.GetAllNodes()
	edges, _ := e.storage.AllEdges()

	export := map[string]interface{}{
		"nodes":         e.nodesToExportFormat(nodes),
		"relationships": e.edgesToExportFormat(edges),
	}

	jsonData, err := json.MarshalIndent(export, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("failed to marshal JSON: %w", err)
	}

	// Write to file if path provided
	if resolvedPath != "" {
		if err := securitypkg.EnsureRootedParent(resolvedPath, 0o755); err != nil {
			return nil, fmt.Errorf("failed to create directory: %w", err)
		}
		if err := securitypkg.WriteRootedFile(resolvedPath, jsonData, 0o644); err != nil {
			return nil, fmt.Errorf("failed to write file: %w", err)
		}
	}

	return &ExecuteResult{
		Columns: legacyProcedureColumns("apoc.export.json.all"),
		Rows: [][]interface{}{{
			filePath,
			len(nodes),
			len(edges),
			e.countProperties(nodes, edges),
			string(jsonData),
		}},
	}, nil
}

// callApocExportJsonQuery exports query results to JSON.
// Syntax: CALL apoc.export.json.query(query, file, config)
func (e *StorageExecutor) callApocExportJsonQuery(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	const procedure = "apoc.export.json.query"
	query, err := requiredProcedureString(procedure, args, 0, "query")
	if err != nil {
		return nil, err
	}
	filePath, err := optionalProcedureString(procedure, args, 1, "file", "")
	if err != nil {
		return nil, err
	}
	resolvedPath := ""
	if filePath != "" {
		var err error
		resolvedPath, err = e.resolveAPOCLocalExportFilePath(filePath)
		if err != nil {
			return nil, err
		}
	}

	// Execute the query
	result, err := e.executeUserStatement(ctx, query, nil)
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}

	// Convert to JSON
	export := map[string]interface{}{
		"columns": result.Columns,
		"data":    result.Rows,
	}

	jsonData, err := json.MarshalIndent(export, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("failed to marshal JSON: %w", err)
	}

	// Write to file if path provided
	if resolvedPath != "" {
		if err := securitypkg.WriteRootedFile(resolvedPath, jsonData, 0o644); err != nil {
			return nil, fmt.Errorf("failed to write file: %w", err)
		}
	}

	return &ExecuteResult{
		Columns: legacyProcedureColumns("apoc.export.json.query"),
		Rows: [][]interface{}{{
			filePath,
			len(result.Rows),
			string(jsonData),
		}},
	}, nil
}

// =============================================================================
// apoc.export.csv - Export to CSV
// =============================================================================

// callApocExportCsvAll exports all data to CSV.
// Syntax: CALL apoc.export.csv.all(file, config) YIELD file, nodes, relationships
func (e *StorageExecutor) callApocExportCsvAll(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	// No file (or '') returns the export instead of writing it.
	filePath, err := optionalProcedureString("apoc.export.csv.all", args, 0, "file", "")
	if err != nil {
		return nil, err
	}
	resolvedPath := ""
	if filePath != "" {
		var err error
		resolvedPath, err = e.resolveAPOCLocalExportFilePath(filePath)
		if err != nil {
			return nil, err
		}
	}

	nodes := e.storage.GetAllNodes()
	edges, _ := e.storage.AllEdges()

	// Build CSV content
	var csvContent strings.Builder

	// Nodes section
	csvContent.WriteString("# Nodes\n")
	csvContent.WriteString("_id,_labels,properties\n")
	for _, node := range nodes {
		props, _ := json.Marshal(node.Properties)
		csvContent.WriteString(fmt.Sprintf("%s,\"%s\",\"%s\"\n",
			node.ID,
			strings.Join(node.Labels, ";"),
			strings.ReplaceAll(string(props), "\"", "\"\"")))
	}

	csvContent.WriteString("\n# Relationships\n")
	csvContent.WriteString("_id,_type,_start,_end,properties\n")
	for _, edge := range edges {
		props, _ := json.Marshal(edge.Properties)
		csvContent.WriteString(fmt.Sprintf("%s,%s,%s,%s,\"%s\"\n",
			edge.ID,
			edge.Type,
			edge.StartNode,
			edge.EndNode,
			strings.ReplaceAll(string(props), "\"", "\"\"")))
	}

	content := csvContent.String()

	// Write to file if path provided
	if resolvedPath != "" {
		if err := securitypkg.EnsureRootedParent(resolvedPath, 0o755); err != nil {
			return nil, fmt.Errorf("failed to create directory: %w", err)
		}
		if err := securitypkg.WriteRootedFile(resolvedPath, []byte(content), 0o644); err != nil {
			return nil, fmt.Errorf("failed to write file: %w", err)
		}
	}

	return &ExecuteResult{
		Columns: legacyProcedureColumns("apoc.export.csv.all"),
		Rows: [][]interface{}{{
			filePath,
			len(nodes),
			len(edges),
			len(nodes) + len(edges),
		}},
	}, nil
}

// callApocExportCsvQuery exports query results to CSV.
// Syntax: CALL apoc.export.csv.query(query, file, config)
func (e *StorageExecutor) callApocExportCsvQuery(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	const procedure = "apoc.export.csv.query"
	query, err := requiredProcedureString(procedure, args, 0, "query")
	if err != nil {
		return nil, err
	}
	filePath, err := optionalProcedureString(procedure, args, 1, "file", "")
	if err != nil {
		return nil, err
	}
	resolvedPath := ""
	if filePath != "" {
		var err error
		resolvedPath, err = e.resolveAPOCLocalExportFilePath(filePath)
		if err != nil {
			return nil, err
		}
	}

	// Execute the query
	result, err := e.executeUserStatement(ctx, query, nil)
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}

	// Build CSV
	var csvContent strings.Builder

	// Header
	csvContent.WriteString(strings.Join(result.Columns, ","))
	csvContent.WriteByte('\n')

	// Data rows
	for _, row := range result.Rows {
		values := make([]string, len(row))
		for i, val := range row {
			switch v := val.(type) {
			case string:
				values[i] = fmt.Sprintf("\"%s\"", strings.ReplaceAll(v, "\"", "\"\""))
			case nil:
				values[i] = ""
			default:
				jsonVal, _ := json.Marshal(v)
				values[i] = fmt.Sprintf("\"%s\"", strings.ReplaceAll(string(jsonVal), "\"", "\"\""))
			}
		}
		csvContent.WriteString(strings.Join(values, ","))
		csvContent.WriteByte('\n')
	}

	content := csvContent.String()

	// Write to file if path provided
	if resolvedPath != "" {
		if err := securitypkg.WriteRootedFile(resolvedPath, []byte(content), 0o644); err != nil {
			return nil, fmt.Errorf("failed to write file: %w", err)
		}
	}

	return &ExecuteResult{
		Columns: legacyProcedureColumns("apoc.export.csv.query"),
		Rows: [][]interface{}{{
			filePath,
			len(result.Rows),
			content,
		}},
	}, nil
}

// =============================================================================
// Helper functions
// =============================================================================

func (e *StorageExecutor) nodesToExportFormat(nodes []*storage.Node) []map[string]interface{} {
	result := make([]map[string]interface{}, len(nodes))
	for i, node := range nodes {
		result[i] = map[string]interface{}{
			"id":         string(node.ID),
			"labels":     node.Labels,
			"properties": node.Properties,
		}
	}
	return result
}

func (e *StorageExecutor) edgesToExportFormat(edges []*storage.Edge) []map[string]interface{} {
	result := make([]map[string]interface{}, len(edges))
	for i, edge := range edges {
		result[i] = map[string]interface{}{
			"id":         string(edge.ID),
			"type":       edge.Type,
			"startNode":  string(edge.StartNode),
			"endNode":    string(edge.EndNode),
			"properties": edge.Properties,
		}
	}
	return result
}

func (e *StorageExecutor) countProperties(nodes []*storage.Node, edges []*storage.Edge) int {
	count := 0
	for _, node := range nodes {
		count += len(node.Properties)
	}
	for _, edge := range edges {
		count += len(edge.Properties)
	}
	return count
}

// =============================================================================
// apoc.load.jsonArray - Load JSON array with path
// =============================================================================

// callApocLoadJsonArray loads a JSON array from a specific path.
// Syntax: CALL apoc.load.jsonArray(urlOrFile, path) YIELD value
func (e *StorageExecutor) callApocLoadJsonArray(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	urlOrFile, err := requiredProcedureString("apoc.load.jsonArray", args, 0, "urlOrKeyOrBinary")
	if err != nil {
		return nil, err
	}

	var data interface{}

	if isHTTPSource(urlOrFile) {
		data, err = e.loadJsonFromURL(urlOrFile)
	} else {
		data, err = e.loadJsonFromFile(urlOrFile)
	}

	if err != nil {
		return nil, fmt.Errorf("failed to load JSON: %w", err)
	}

	// Extract array
	rows := [][]interface{}{}
	switch v := data.(type) {
	case []interface{}:
		for _, item := range v {
			rows = append(rows, []interface{}{item})
		}
	default:
		rows = append(rows, []interface{}{data})
	}

	return &ExecuteResult{
		Columns: []string{"value"},
		Rows:    rows,
	}, nil
}

// =============================================================================
// apoc.import.json - Import JSON directly into graph
// =============================================================================

// callApocImportJson imports JSON graph data directly.
// Syntax: CALL apoc.import.json(urlOrFile) YIELD nodes, relationships
func (e *StorageExecutor) callApocImportJson(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	store := e.getStorage(ctx)
	// The storage owner qualifies local IDs through transaction/admission
	// wrappers too. Keep the import's supplied IDs local when it does so;
	// pre-prefixing here would make that namespace part of the imported ID.
	prefixIDs := storage.QualifiedEntityID(store, "") == ""
	dbName := GetUseDatabaseFromContext(ctx)
	if dbName == "" {
		dbName = "nornic"
	}
	ensureNodeID := func(id string) storage.NodeID {
		if id == "" {
			return ""
		}
		if !prefixIDs {
			return storage.NodeID(id)
		}
		return storage.NodeID(storage.EnsureDatabasePrefix(dbName, id))
	}
	ensureEdgeID := func(id string) storage.EdgeID {
		if id == "" {
			return ""
		}
		if !prefixIDs {
			return storage.EdgeID(id)
		}
		return storage.EdgeID(storage.EnsureDatabasePrefix(dbName, id))
	}
	urlOrFile, err := requiredProcedureString("apoc.import.json", args, 0, "url")
	if err != nil {
		return nil, err
	}

	if urlOrFile == "" {
		return nil, fmt.Errorf("apoc.import.json requires a URL or file path")
	}

	var data interface{}

	if isHTTPSource(urlOrFile) {
		data, err = e.loadJsonFromURL(urlOrFile)
	} else {
		data, err = e.loadJsonFromFile(urlOrFile)
	}

	if err != nil {
		return nil, fmt.Errorf("failed to load JSON: %w", err)
	}

	// Import the data
	nodesImported := 0
	relsImported := 0

	if dataMap, ok := data.(map[string]interface{}); ok {
		// Import nodes
		if nodes, ok := dataMap["nodes"].([]interface{}); ok {
			for _, nodeData := range nodes {
				if nodeMap, ok := nodeData.(map[string]interface{}); ok {
					node := &storage.Node{
						Properties: make(map[string]interface{}),
					}

					if id, ok := nodeMap["id"].(string); ok {
						node.ID = ensureNodeID(id)
					}
					if labels, ok := nodeMap["labels"].([]interface{}); ok {
						for _, l := range labels {
							if ls, ok := l.(string); ok {
								node.Labels = append(node.Labels, ls)
							}
						}
					}
					if props, ok := nodeMap["properties"].(map[string]interface{}); ok {
						node.Properties = props
					}

					if node.ID != "" {
						if _, err := store.CreateNode(node); err == nil {
							nodesImported++
						}
					}
				}
			}
		}

		// Import relationships
		if rels, ok := dataMap["relationships"].([]interface{}); ok {
			for _, relData := range rels {
				if relMap, ok := relData.(map[string]interface{}); ok {
					edge := &storage.Edge{
						Properties: make(map[string]interface{}),
					}

					if id, ok := relMap["id"].(string); ok {
						edge.ID = ensureEdgeID(id)
					}
					if t, ok := relMap["type"].(string); ok {
						edge.Type = t
					}
					if start, ok := relMap["startNode"].(string); ok {
						edge.StartNode = ensureNodeID(start)
					}
					if end, ok := relMap["endNode"].(string); ok {
						edge.EndNode = ensureNodeID(end)
					}
					if props, ok := relMap["properties"].(map[string]interface{}); ok {
						edge.Properties = props
					}

					if edge.ID != "" && edge.StartNode != "" && edge.EndNode != "" {
						if err := store.CreateEdge(edge); err == nil {
							relsImported++
						}
					}
				}
			}
		}
	}

	return &ExecuteResult{
		Columns: []string{"source", "nodes", "relationships"},
		Rows: [][]interface{}{{
			urlOrFile,
			nodesImported,
			relsImported,
		}},
	}, nil
}

// Make strconv available for any numeric conversions
var _ = strconv.Itoa

package cypher

import (
	"context"
	"fmt"
	"strings"

	cypherantlr "github.com/orneryd/nornicdb/pkg/cypher/antlr"
	"github.com/orneryd/nornicdb/pkg/cypher/resultmetadata"
)

// boundTypeValues enriches an already admitted program. The only mutable
// namespace here is BindingID -> operand. Name maps passed to existing operand
// rules are detached selections of frozen horizons, never transfer state.
type boundTypeValues struct {
	executor          *StorageExecutor
	program           *boundStatementProgram
	values            map[statementBindingID]staticOperand
	cypher25          bool
	params            map[string]interface{}
	parameterOperands bool
	unwound           map[statementBindingID]bool
	done              map[*boundBody]bool
}

func (e *StorageExecutor) enrichBoundTypes(ctx context.Context, source string, initial typeScope, parent *semanticBodyScope, scalar string, cypher25 bool, parameterOperands ...bool) (*boundTypeValues, *semanticQueryScope, error) {
	ensureBuiltInProceduresRegistered()
	var facts *projectedScopeFacts
	if scalar == "" {
		if admitted, _ := ctx.Value(boundStatementProgramKey{}).(*boundStatementProgram); admitted != nil && admitted.syntax.Source() == source {
			facts = admitted.root.program
		} else if schema := e.participantSchemaForStatement(ctx, source); schema != nil {
			compiler := projectionCompilation{executor: e, source: source, cypher25: cypher25, bindings: parent, schema: schema}
			facts = compiler.root(ctx, projectedMapNames(bindingNames(initial)), resultmetadata.Known(nil))
		} else {
			var retained []string
			for name := range pipelineImports(ctx) {
				retained = append(retained, name)
			}
			facts = e.projectedStatementScope(ctx, source, projectedMapNames(bindingNames(initial)), resultmetadata.Known(retained), cypher25, parent)
		}
	} else {
		compiler := projectionCompilation{executor: e, source: source, cypher25: cypher25, bindings: parent, scalarKind: scalar}
		facts = compiler.root(ctx, projectedMapNames(bindingNames(initial)), resultmetadata.Known(nil))
	}
	if facts.err != nil {
		return nil, nil, facts.err
	}
	if facts.statement != nil && facts.statement.Command != nil {
		return nil, &semanticQueryScope{complete: true, columns: canonicalColumns(facts.statement.Columns)}, nil
	}
	if facts.bound == nil || facts.statement == nil {
		return nil, nil, unresolvedStatementError()
	}
	state := &boundTypeValues{parameterOperands: len(parameterOperands) > 0 && parameterOperands[0], params: getParamsFromContext(ctx), executor: e, program: facts.bound, values: make(map[statementBindingID]staticOperand), cypher25: cypher25, unwound: make(map[statementBindingID]bool), done: make(map[*boundBody]bool)}
	for _, branch := range facts.bound.root.branches {
		for name, identity := range branch.input.ids {
			state.values[identity] = initial[name]
		}
	}
	if err := state.body(ctx, facts.bound.root); err != nil {
		return state, nil, err
	}
	return state, state.model(facts.bound.root), nil
}

func (types *boundTypeValues) selectValues(scope resultmetadata.Scope) typeScope {
	values := make(typeScope)
	scope.Visit(func(names []string) {
		for _, name := range names {
			if identity, known := scope.Binding(name); known {
				values[name] = types.values[identity]
			}
		}
	}, func() {})
	return values
}

func (types *boundTypeValues) view(scope resultmetadata.Scope, frame *semanticBodyScope) staticTypeScope {
	view := types.selectValues(scope).static(types.cypher25)
	view.params = types.params
	view.admitted = types
	// These membership maps are immutable constructor snapshots. Type rules
	// may observe their retained/scalar flags, but cannot transition them.
	view.bindings = frame
	return view
}

func (types *boundTypeValues) model(body *boundBody) *semanticQueryScope {
	statement := body.program.statement
	model := &semanticQueryScope{query: types.program.syntax.Source()[statement.Start:statement.End], complete: true, stableNames: true, proof: body.dependencies, returned: types.columnValues(statement), imports: types.selectValues(statement.Incoming)}
	statement.Columns.Visit(func(names []string) { model.columns = names }, func() { model.complete = false })
	for _, branch := range body.branches {
		part := &semanticQueryScope{query: types.program.syntax.Source()[branch.statement.Start:branch.statement.End], complete: true, stableNames: true, bindings: branch.input.frame, proof: branch.dependencies, returned: types.columnValues(&branch.statement), imports: types.selectValues(branch.statement.Incoming)}
		branch.statement.Columns.Visit(func(names []string) { part.columns = names }, func() { part.complete = false })
		for _, source := range branch.shape.clauses {
			clause := source.pipelineClause
			clause.bindings = types.program.bodies[source.syntax.ID()]
			part.clauses = append(part.clauses, clause)
			if plan := types.program.projections[source.syntax.ID()]; plan != nil && plan.star {
				part.wildcard = true
			}
		}
		model.wildcard = model.wildcard || part.wildcard
		model.branches = append(model.branches, part)
	}
	if body.expressionKind != "" {
		model.imports = types.selectValues(statement.Entry.Dependencies)
	}
	if len(model.branches) == 1 {
		model.clauses = model.branches[0].clauses
		model.bindings = model.branches[0].bindings
	}
	return model
}

func (types *boundTypeValues) body(ctx context.Context, body *boundBody) error {
	if types.done[body] {
		return nil
	}
	types.done[body] = true
	for _, branch := range body.branches {
		for _, source := range branch.shape.clauses {
			if err := ctx.Err(); err != nil {
				return err
			}
			clause := types.program.clauses[source.syntax.ID()]
			if err := types.clause(ctx, clause); err != nil {
				return err
			}
		}
	}
	// UNION owns the output IDs. Join operand values at those declared IDs;
	// never derive another import context or output header from the branches.
	if len(body.branches) > 1 {
		for _, name := range scopeValues(body.program.statement.After) {
			var joined staticOperand
			for index, branch := range body.branches {
				identity, _ := branch.statement.After.Binding(name)
				if index == 0 {
					joined = types.values[identity]
				} else {
					joined = joinedOperand(joined, types.values[identity])
				}
			}
			identity, _ := body.program.statement.After.Binding(name)
			types.values[identity] = joined
		}
	}
	return nil
}

func (types *boundTypeValues) clause(ctx context.Context, clause *boundClause) error {
	source, step := clause.source.pipelineClause, clause.step
	frame := types.program.bodies[clause.source.syntax.ID()]
	before := types.view(step.Before, frame)
	beforeRead := types.selectValues(step.Before)
	if source.kind == pipelineClauseMatch || source.kind == pipelineClauseOptionalMatch || source.kind == pipelineClauseCreate || source.kind == pipelineClauseMerge {
		// Pattern kinds are operand constraints. The set and identity of every
		// name have already been decided, including fresh weak shadows.
		kinds := beforeRead.kinds()
		if source.kind == pipelineClauseMatch || source.kind == pipelineClauseOptionalMatch {
			if err := types.executor.validateMatchClauseBindings(kinds, source.text); err != nil {
				return err
			}
		}
		declared := make(matchSemanticScope)
		addMatchPatternBindingKinds(ctx, declared, source.text[:patternPartEnd(source)])
		for name, kind := range declared {
			if identity, known := step.After.Binding(name); known {
				old := types.values[identity]
				if old.bindingKind() == matchBindingUnknown {
					types.values[identity] = operandOfKind(kind)
				}
			}
		}
	}
	switch source.kind {
	case pipelineClauseCallSubquery:
		if err := types.body(ctx, clause.body); err != nil {
			return err
		}
	case pipelineClauseForeach:
		list := source.syntax.ChildRule(cypherantlr.CypherParserRULE_expression)
		operand, err := types.expression(ctx, list)
		if err != nil {
			return err
		}
		name := syntaxSymbolName(source.syntax.ChildRule(cypherantlr.CypherParserRULE_symbol))
		for _, branch := range clause.body.branches {
			if identity, known := branch.statement.Incoming.Binding(name); known {
				types.values[identity] = operand.elementOperand()
			}
		}
		return types.body(ctx, clause.body)
	case pipelineClauseLet:
		for index := 0; index < source.syntax.ChildCount(); index++ {
			item := source.syntax.Child(index)
			if item.Rule() != cypherantlr.CypherParserRULE_letItem {
				continue
			}
			operand, err := types.expression(ctx, item.ChildRule(cypherantlr.CypherParserRULE_expression))
			if err != nil {
				return err
			}
			identity := types.declaration(item.ChildRule(cypherantlr.CypherParserRULE_symbol))
			types.values[identity] = bindingOperand(operand)
		}
	case pipelineClauseUnwind:
		operand, err := types.expression(ctx, source.syntax.ChildRule(cypherantlr.CypherParserRULE_expression))
		if err != nil {
			return err
		}
		name := syntaxSymbolName(source.syntax.ChildRule(cypherantlr.CypherParserRULE_symbol))
		identity, _ := step.After.Binding(name)
		if operand.union || !operand.known() || operand.list() {
			types.values[identity] = bindingOperand(operand.elementOperand())
		} else {
			types.values[identity] = bindingOperand(operand)
		}
		types.unwound[identity] = types.values[identity].typeName() != "" && !operand.excludes(isListTypeName)
	case pipelineClauseCall:
		var unwound map[string]struct{}
		for _, name := range scopeValues(step.Before) {
			identity, _ := step.Before.Binding(name)
			if types.unwound[identity] {
				if unwound == nil {
					unwound = make(map[string]struct{})
				}
				unwound[name] = struct{}{}
			}
		}
		if err := staticProcedureArgumentTypeError(ctx, source.text, before, unwound); err != nil {
			return err
		}
		outputs := procedureOutputTypes(ctx, source.text)
		if yield := yieldFromSyntax(source.syntax); yield != nil && !yield.yieldAll {
			for _, item := range yield.items {
				identity, _ := step.After.Binding(item.column())
				if value := outputs[item.name]; value != "" {
					types.values[identity] = provenOperand(value)
				}
			}
		}
	case pipelineClauseWith, pipelineClauseReturn:
		for _, item := range clause.plan.projections {
			var operand staticOperand
			if item.direct {
				identity, _ := step.Before.Binding(item.variable)
				operand = types.values[identity]
			} else {
				var err error
				operand, err = types.expression(ctx, item.syntax)
				if err != nil {
					return err
				}
			}
			identity, _ := step.After.Binding(item.alias)
			types.values[identity] = bindingOperand(operand)
		}
	}
	// Lower lexical/scalar constructs to type-only parameter atoms. Existing
	// operator/function rules see no query-local namespace to reconstruct.
	text, atoms, err := types.expressionText(ctx, source.syntax)
	if err != nil {
		return err
	}
	checking := source
	checking.text = text
	current := step.Entry.Readable
	if source.kind == pipelineClauseMatch || source.kind == pipelineClauseOptionalMatch || source.kind == pipelineClauseCreate || source.kind == pipelineClauseMerge || source.kind == pipelineClauseCall {
		current = step.After
	}
	view := types.view(current, frame)
	view.typeParameters = atoms
	projected := types.view(step.Exit.Readable, frame)
	projected.typeParameters = atoms
	view.projected = &projected
	if source.kind == pipelineClauseWith {
		if err := validateWithOrderBySemanticScope(ctx, view.kinds, checking.text, types.selectValues(step.Entry.Retained), projected.kinds); err != nil {
			return err
		}
	}
	if source.kind == pipelineClauseDelete {
		if err := deleteTargetTypeError(checking.text, view.kinds); err != nil {
			return err
		}
	}
	if source.kind == pipelineClauseFilter {
		if err := types.executor.validateSharedClause(ctx, view.kinds, view.values, checking, types.cypher25); err != nil {
			return err
		}
	}
	if err := types.executor.validateStaticClauseTypes(ctx, checking, view); err != nil {
		return err
	}
	return graphListOperandTypeError(checking.text, view.kinds)
}

func (types *boundTypeValues) declaration(symbol cypherantlr.SyntaxNode) statementBindingID {
	start, end := symbol.Span()
	for _, binding := range types.program.bindings {
		if binding.start == start && binding.end == end {
			return binding.id
		}
	}
	return 0
}

func (types *boundTypeValues) expression(ctx context.Context, node cypherantlr.SyntaxNode) (staticOperand, error) {
	if !node.Valid() {
		return staticOperand{}, nil
	}
	if types.local(node) {
		return types.localOperand(ctx, node)
	}
	text, atoms, err := types.expressionText(ctx, node)
	if err != nil {
		return staticOperand{}, err
	}
	view := types.expressionView(node)
	view.typeParameters = atoms
	checker := staticOperatorChecker{scope: view}
	if types.parameterOperands {
		checker.params = types.params
	}
	operand, err := checker.checkScoped(ctx, text)
	if err != nil {
		return staticOperand{}, err
	}
	// Retained grammar identifies invocations even when their name is a
	// keyword the legacy whole-statement scanner must skip as clause syntax.
	var failure error
	node.Walk(func(call cypherantlr.SyntaxNode) func() {
		if failure == nil && call.Rule() == cypherantlr.CypherParserRULE_functionInvocation {
			name := call.ChildRule(cypherantlr.CypherParserRULE_invocationName).QualifiedName()
			if name != "" {
				failure = knownFunctionCallError(name, lowerASCII(name))
			}
		}
		return nil
	})
	return operand, failure
}

func (types *boundTypeValues) local(node cypherantlr.SyntaxNode) bool {
	return types.program.nested[node.ID()] != nil || len(expressionLocalSyntax(node)) != 0
}

func (types *boundTypeValues) expressionText(ctx context.Context, node cypherantlr.SyntaxNode) (string, map[string]staticOperand, error) {
	text := node.Text()
	start, _ := node.Span()
	atoms := make(map[string]staticOperand)
	type edit struct {
		first, last int
		value       string
	}
	var edits []edit
	var visit func(cypherantlr.SyntaxNode) error
	visit = func(child cypherantlr.SyntaxNode) error {
		if child.ID() != node.ID() && types.local(child) {
			operand, err := types.localOperand(ctx, child)
			if err != nil {
				return err
			}
			name := fmt.Sprintf("__nornic_type_%d", child.ID())
			for strings.Contains(text, "$"+name) {
				name += "_"
			}
			atoms["$"+name] = operand
			first, last := child.Span()
			edits = append(edits, edit{first - start, last - start, "$" + name})
			return nil
		}
		for index := 0; index < child.ChildCount(); index++ {
			if err := visit(child.Child(index)); err != nil {
				return err
			}
		}
		return nil
	}
	if err := visit(node); err != nil {
		return "", nil, err
	}
	for index := len(edits) - 1; index >= 0; index-- {
		change := edits[index]
		text = text[:change.first] + change.value + text[change.last:]
	}
	return text, atoms, nil
}

func syntaxExpressions(node cypherantlr.SyntaxNode) []cypherantlr.SyntaxNode {
	var result []cypherantlr.SyntaxNode
	for index := 0; index < node.ChildCount(); index++ {
		child := node.Child(index)
		if child.Rule() == cypherantlr.CypherParserRULE_expression {
			result = append(result, child)
		}
	}
	return result
}

func (types *boundTypeValues) localOperand(ctx context.Context, node cypherantlr.SyntaxNode) (staticOperand, error) {
	if body := types.program.nested[node.ID()]; body != nil {
		if err := types.body(ctx, body); err != nil {
			return staticOperand{}, err
		}
		switch body.expressionKind {
		case "EXISTS":
			return provenOperand("Boolean"), nil
		case "COUNT":
			return provenOperand("Integer"), nil
		case "COLLECT":
			names := canonicalColumns(body.program.statement.Columns)
			if len(names) != 1 {
				return staticOperand{}, unresolvedStatementError()
			}
			identity, _ := body.program.statement.After.Binding(names[0])
			element := types.values[identity]
			if element.typeName() != "" && composable(element) {
				return typedOperand(listOfType(element.typeName())).proved(), nil
			}
			return provenOperand("List<T>"), nil
		}
	}
	locals := expressionLocalSyntax(node)
	switch node.Rule() {
	case cypherantlr.CypherParserRULE_listComprehension, cypherantlr.CypherParserRULE_filterWith:
		filter := node.ChildRule(cypherantlr.CypherParserRULE_filterExpression)
		source, err := types.expression(ctx, filter.ChildRule(cypherantlr.CypherParserRULE_expression))
		if err != nil {
			return staticOperand{}, err
		}
		if source.excludes(isListTypeName) {
			return staticOperand{}, operandMismatch(source, "List<T>")
		}
		types.values[types.declaration(locals[0].symbol)] = source.elementOperand()
		if where := filter.ChildRule(cypherantlr.CypherParserRULE_where); where.Valid() {
			predicate, err := types.expression(ctx, where.ChildRule(cypherantlr.CypherParserRULE_expression))
			if err != nil {
				return staticOperand{}, err
			}
			if err := requireBooleanOperand(predicate); err != nil {
				return staticOperand{}, err
			}
		}
		if node.Rule() == cypherantlr.CypherParserRULE_filterWith {
			return provenOperand("Boolean"), nil
		}
		projection := node.ChildRule(cypherantlr.CypherParserRULE_expression)
		if !projection.Valid() {
			return source, nil
		}
		element, err := types.expression(ctx, projection)
		if err != nil {
			return staticOperand{}, err
		}
		if element.typeName() != "" && composable(element) {
			return typedOperand(listOfType(element.typeName())).proved(), nil
		}
		return provenOperand("List<T>"), nil
	case cypherantlr.CypherParserRULE_reduceExpression, cypherantlr.CypherParserRULE_allReduceExpression:
		expressions := syntaxExpressions(node)
		initial, err := types.expression(ctx, expressions[0])
		if err != nil {
			return staticOperand{}, err
		}
		source, err := types.expression(ctx, expressions[1])
		if err != nil {
			return staticOperand{}, err
		}
		if source.excludes(isListTypeName) {
			return staticOperand{}, operandMismatch(source, "List<T>")
		}
		types.values[types.declaration(locals[0].symbol)] = reduceAccumulatorOperand(initial)
		types.values[types.declaration(locals[1].symbol)] = source.elementOperand()
		step, err := types.expression(ctx, expressions[2])
		if err != nil {
			return staticOperand{}, err
		}
		if len(expressions) > 3 {
			predicate, err := types.expression(ctx, expressions[3])
			if err != nil {
				return staticOperand{}, err
			}
			if err := requireBooleanOperand(predicate); err != nil {
				return staticOperand{}, err
			}
		}
		if node.Rule() == cypherantlr.CypherParserRULE_allReduceExpression {
			return provenOperand("Boolean"), nil
		}
		if initial.typeName() != "" && step.typeName() != "" && composable(initial) && step.excludes(accumulatorAccepts(initial)) {
			return staticOperand{}, newSemanticError("Neo.ClientError.Statement.SyntaxError", "InvalidArgumentType", fmt.Sprintf("Type mismatch: accumulator is %s but expression has type %s", initial.typeName(), step.typeName()))
		}
		return reduceAccumulatorOperand(initial), nil
	case cypherantlr.CypherParserRULE_patternComprehension:
		for _, local := range locals {
			identity := types.declaration(local.symbol)
			if identity != 0 && types.values[identity].bindingKind() == matchBindingUnknown {
				kind := matchBindingNode
				if parent, ok := local.symbol.Parent(); ok && parent.Rule() == cypherantlr.CypherParserRULE_relationDetail {
					kind = matchBindingRelationship
				}
				if !local.reuse {
					kind = matchBindingPath
				}
				types.values[identity] = operandOfKind(kind)
			}
		}
		if where := node.ChildRule(cypherantlr.CypherParserRULE_where); where.Valid() {
			predicate, err := types.expression(ctx, where.ChildRule(cypherantlr.CypherParserRULE_expression))
			if err != nil {
				return staticOperand{}, err
			}
			if err := requireBooleanOperand(predicate); err != nil {
				return staticOperand{}, err
			}
		}
		element, err := types.expression(ctx, node.ChildRule(cypherantlr.CypherParserRULE_expression))
		if err != nil {
			return staticOperand{}, err
		}
		if element.typeName() != "" && composable(element) {
			return typedOperand(listOfType(element.typeName())).proved(), nil
		}
		return provenOperand("List<T>"), nil
	}
	return staticOperand{}, nil
}

func canonicalColumns(columns resultmetadata.Columns) (names []string) {
	columns.Visit(func(values []string) { names = values }, func() {})
	return names
}

// columnValues selects the declared result, not the body's full readable scope.
func (types *boundTypeValues) columnValues(statement *resultmetadata.Statement) typeScope {
	selected := make(typeScope)
	for _, name := range canonicalColumns(statement.Columns) {
		if identity, ok := statement.After.Binding(name); ok {
			selected[name] = types.values[identity]
		}
	}
	return selected
}

// Standalone operand callers also enter the constructor; they do not install
// lexical names themselves. The offset selects an original retained syntax span.
func typeExpressionSource(source string) string {
	trimmed := strings.TrimSpace(source)
	for _, keyword := range []string{"RETURN", "WITH", "MATCH", "OPTIONAL MATCH", "UNWIND", "FOR", "LET", "CALL", "CREATE", "MERGE", "SET", "DELETE", "REMOVE", "FOREACH", "FILTER", "USE", "CYPHER"} {
		if startsWithKeywordFold(trimmed, keyword) {
			return source
		}
	}
	return "RETURN " + source
}
func boundExpressionTypeView(ctx context.Context, scope staticTypeScope, text string, at int) staticTypeScope {
	if scope.admitted != nil {
		return scope
	}
	source := typeExpressionSource(text)
	offset := len(source) - len(text) + at
	executor := &StorageExecutor{}
	input := typeScopeOf(scope)
	if !scope.complete {
		for _, name := range expressionFreeVariables(ctx, text) {
			if _, known := input[name]; !known {
				input[name] = staticOperand{}
			}
		}
	}
	values, _, err := executor.enrichBoundTypes(ctx, source, input, scope.bindings, "", scope.cypher25)
	if values == nil {
		scope.typeFailure = err
		return scope
	}
	values.params = scope.params
	width := len(source) + 1
	var selected resultmetadata.Scope
	found := false
	for id, node := range values.program.nodes {
		first, last := node.Span()
		if first <= offset && offset < last && last-first < width {
			if frozen, ok := values.program.expressions[id]; ok {
				width = last - first
				selected = frozen
				found = true
			}
		}
	}
	if !found {
		return scope
	}
	view := values.view(selected, scope.bindings)
	view.complete = scope.complete
	view.params = scope.params
	view.typeFailure = err
	return view
}

// checkClauseOperandHandles visits retained expression operands at their exact
// admitted lexical/projection horizon. No text scan chooses their namespace.
func (types *boundTypeValues) checkClauseOperandHandles(ctx context.Context, source pipelineClause, view staticTypeScope) error {
	var failure error
	depth := 0
	source.syntax.Walk(func(node cypherantlr.SyntaxNode) func() {
		if failure != nil {
			return nil
		}
		if node.ID() != source.syntax.ID() {
			if nested := types.program.clauses[node.ID()]; nested != nil {
				return nil
			}
		}
		if node.Rule() != cypherantlr.CypherParserRULE_expression {
			return nil
		}
		depth++
		if depth == 1 {
			operand, err := types.expression(ctx, node)
			if err != nil {
				failure = err
			} else if parent, ok := node.Parent(); ok && parent.Rule() == cypherantlr.CypherParserRULE_where {
				if owner, ok := parent.Parent(); ok && owner.ID() == source.syntax.ID() {
					failure = requireBooleanOperand(operand)
				}
			}
		}
		return func() { depth-- }
	})
	if failure != nil {
		return failure
	}
	if source.kind == pipelineClauseDelete {
		return staticDeleteTargetTypeError(ctx, source.text, view)
	}
	return staticWriteTokenError(ctx, source, view)
}

func (types *boundTypeValues) expressionView(node cypherantlr.SyntaxNode) staticTypeScope {
	frozen := types.program.expressions[node.ID()]
	selected := types.selectValues(frozen)
	// A quantified group reads one element inside its predicate. These are type
	// refinements of admitted IDs; an absent name can never be installed here.
	at, _ := node.Span()
	for parent, ok := node.Parent(); ok; parent, ok = parent.Parent() {
		if clause := types.program.clauses[parent.ID()]; clause != nil {
			start, _ := parent.Span()
			for _, group := range quantifiedGroups(parent.Text()) {
				if at < start+group.open || at >= start+group.close {
					continue
				}
				for _, name := range group.nodes {
					if identity, known := frozen.Binding(name); known {
						groupID, _ := clause.step.After.Binding(name)
						if identity == groupID {
							selected[name] = operandOfKind(matchBindingNode)
						}
					}
				}
				for _, name := range group.relationships {
					if identity, known := frozen.Binding(name); known {
						groupID, _ := clause.step.After.Binding(name)
						if identity == groupID {
							selected[name] = operandOfKind(matchBindingRelationship)
						}
					}
				}
			}
			break
		}
	}
	view := selected.static(types.cypher25)
	view.admitted = types
	view.params = types.params
	return view
}

// A declared variable retains its operand constraints, not a parameter's
// diagnostic name. Direct parameter operands continue to name the parameter.
func bindingOperand(operand staticOperand) staticOperand { operand.parameter = ""; return operand }

// CALL procedure implementations for NornicDB.
// This file contains all CALL procedures for Neo4j compatibility and NornicDB extensions.
//
// Core procedure implementation.
// =======================================
//
// Critical Neo4j-compatible procedures:
//   - db.index.vector.queryNodes - Vector similarity search with cosine/euclidean
//   - db.index.fulltext.queryNodes - Full-text search with BM25-like scoring
//   - apoc.path.subgraphNodes - Graph traversal with depth/filter control
//   - apoc.path.expand - Path expansion with relationship filters
//
// These procedures are essential for:
//   - Semantic search (vector similarity)
//   - Text search (full-text indexing)
//   - Knowledge graph traversal
//   - Memory relationship discovery

package cypher

import (
	"context"
	"fmt"
	"github.com/orneryd/nornicdb/internal/collection"
	cypherantlr "github.com/orneryd/nornicdb/pkg/cypher/antlr"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"sync"

	"github.com/orneryd/nornicdb/pkg/buildinfo"
	"github.com/orneryd/nornicdb/pkg/convert"
	"github.com/orneryd/nornicdb/pkg/cypher/resultmetadata"
	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
	"github.com/orneryd/nornicdb/pkg/util"
)

// toFloat32Slice is a package-level alias to convert.ToFloat32Slice for internal use.
func toFloat32Slice(v interface{}) []float32 {
	return convert.ToFloat32Slice(v)
}

// yieldClause is a procedure call's YIELD: the yielded columns with their
// aliases, and the WHERE, ORDER BY, SKIP and LIMIT that may follow them, in
// that order (YIELD items [WHERE p] [ORDER BY o] [SKIP s] [LIMIT l]). They
// see the aliases, as a WITH's do. A RETURN after the YIELD isn't part of it:
// it starts the query's tail.
type yieldClause struct {
	items    []yieldItem // List of yielded items (possibly with aliases)
	yieldAll bool        // YIELD * - return all columns
	where    string      // WHERE predicate, "" when absent
	orderBy  string      // ORDER BY items, "" when absent
	skip     string      // SKIP expression, "" when absent
	limit    string      // LIMIT expression, "" when absent
	// misplacedWhere is a WHERE after ORDER BY / SKIP / LIMIT, which Cypher
	// rejects.
	misplacedWhere bool
}

// hasModifiers reports whether the YIELD filters, orders or pages its rows.
func (y *yieldClause) hasModifiers() bool {
	return y.where != "" || y.orderBy != "" || y.skip != "" || y.limit != ""
}

// yieldItem represents a single item in a YIELD clause
type yieldItem struct {
	name    string // Original column name from procedure
	alias   string // Decoded alias, which may be empty
	aliased bool   // An AS clause is present, independently of its value
}

type callSplit struct {
	callOnly string
	tail     string
}

func splitCallAndTail(ctx context.Context, source string) callSplit {
	clause, ok := canonicalQueryClause(ctx, source)
	if !ok {
		return callSplit{callOnly: source}
	}
	if clause.Rule() != cypherantlr.CypherParserRULE_queryCallSt && clause.Rule() != cypherantlr.CypherParserRULE_standaloneCall && clause.Rule() != cypherantlr.CypherParserRULE_callSubquery {
		return callSplit{callOnly: source}
	}
	start, end := clause.Span()
	return callSplit{callOnly: source[start:end], tail: strings.TrimSpace(source[end:])}
}
func buildCallTailPredicateInjection(tail string, predicates []string) string {
	if len(predicates) == 0 {
		return strings.TrimSpace(tail)
	}
	injected := strings.Join(predicates, " AND ")
	trimmed := strings.TrimSpace(tail)

	whereIdx := findKeywordIndexInContext(trimmed, "WHERE")
	if whereIdx != -1 {
		endIdx := len(trimmed)
		for _, kw := range []string{"WITH", "RETURN", "ORDER", "SKIP", "LIMIT", "UNWIND", "SET", "REMOVE", "DELETE", "DETACH", "MERGE", "CREATE"} {
			if idx := findKeywordIndexInContext(trimmed, kw); idx != -1 && idx > whereIdx && idx < endIdx {
				endIdx = idx
			}
		}
		left := strings.TrimSpace(trimmed[:endIdx])
		right := strings.TrimSpace(trimmed[endIdx:])
		if right == "" {
			return left + " AND " + injected
		}
		return left + " AND " + injected + " " + right
	}

	insertIdx := len(trimmed)
	for _, kw := range []string{"WITH", "RETURN", "ORDER", "SKIP", "LIMIT", "UNWIND", "SET", "REMOVE", "DELETE", "DETACH", "MERGE", "CREATE"} {
		if idx := findKeywordIndexInContext(trimmed, kw); idx != -1 && idx < insertIdx {
			insertIdx = idx
		}
	}
	if insertIdx >= len(trimmed) {
		return trimmed + " WHERE " + injected
	}
	left := strings.TrimSpace(trimmed[:insertIdx])
	right := strings.TrimSpace(trimmed[insertIdx:])
	return left + " WHERE " + injected + " " + right
}

func tailStartsWithMatchClause(tail string) bool {
	trimmed := upperASCII(strings.TrimSpace(tail))
	return strings.HasPrefix(trimmed, "MATCH ") || strings.HasPrefix(trimmed, "OPTIONAL MATCH ")
}

func (e *StorageExecutor) executeCallTail(ctx context.Context, seed *ExecuteResult, tail string) (result *ExecuteResult, err error) {
	// Every tail route consumes the same seed once, including projections,
	// empty row sets and write tails. Pass-through results already own its stats.
	defer func() {
		if err == nil && result != nil && seed != nil && result != seed && result.Stats != seed.Stats {
			if result.Stats == nil || *result.Stats == (QueryStats{}) {
				result.Stats = seed.Stats
			} else {
				result.Stats = mergeQueryStats(result.Stats, seed.Stats)
			}
		}
	}()
	if seed == nil {
		return nil, localizedError(localization.CypherCommandRoutingCallTailSeedRequired(), nil)
	}
	if strings.TrimSpace(tail) == "" {
		return seed, nil
	}
	if _, all, _, union := parseTopLevelUnionBranches(ctx, tail); union {
		first := true
		return e.executeUnion(ctx, tail, all, func(branch string) (*ExecuteResult, error) {
			if first {
				first = false
				return e.executeCallTail(ctx, seed, branch)
			}
			return e.executeInternal(ctx, branch, nil)
		})
	}
	if projected, ok, err := e.projectCallTailReturnAll(ctx, seed, tail); ok || err != nil {
		return projected, err
	}
	// A tail that doesn't start with MATCH (WITH, UNWIND, RETURN, a chained
	// CALL, …) runs as one pipeline over every yielded row, so aggregation,
	// ORDER BY and SKIP / LIMIT see all of them. MATCH tails keep their fused
	// operators below and reach the pipeline before the per-row fallback.
	if !tailStartsWithMatchClause(tail) && !isPotentialWriteTail(tail) {
		// WITH … [WHERE] RETURN … projections keep their compiled row
		// projection, which declines aggregation, DISTINCT and SKIP / LIMIT
		// expressions.
		if projected, ok, err := e.tryExecuteCallTailProjectionFilter(ctx, seed, tail, nil); ok || err != nil {
			return projected, err
		}
		if pipelined, ok, err := e.executeCallTailPipeline(ctx, seed, tail); ok || err != nil {
			return pipelined, err
		}
	}
	if pipelined, ok, err := e.tryExecuteCallTailProcedurePipeline(ctx, seed, tail); ok || err != nil {
		return pipelined, err
	}
	if len(seed.Rows) == 0 {
		// Empty input still runs projection operators: their declared fields
		// and aggregate rows are available without a metadata analysis pass.
		if projected, ok, err := e.executeCallTailPipeline(ctx, seed, tail); ok || err != nil {
			return projected, err
		}
		columns, err := e.ResultColumns(ctx, tail, resultmetadata.KnownScope(seed.Columns), cypherVersionFromContext(ctx) == "25")
		if err != nil {
			return nil, err
		}
		return &ExecuteResult{Columns: columns, Rows: [][]interface{}{}}, nil
	}

	expectedCols := knownResultColumns(e.CachedResultColumns(ctx, tail, seed.Columns))
	usedCols := make([]int, 0, len(seed.Columns))
	for i, col := range seed.Columns {
		if isIdentifierReferenced(tail, col) {
			usedCols = append(usedCols, i)
		}
	}

	// Fast path: execute the full tail once with all seed rows bound via UNWIND
	// or batched IN. This avoids per-row tail re-execution and preserves global
	// ORDER/LIMIT scope. Write tails (SET/CREATE/DELETE/MERGE/REMOVE) must use
	// the per-row path to preserve transactional write-per-row semantics.
	if !isPotentialWriteTail(tail) {
		if projected, ok, err := e.tryExecuteCallTailRelationshipMatchProjection(ctx, seed, tail, expectedCols); ok || err != nil {
			return projected, err
		}
		if projected, ok, err := e.tryExecuteCallTailProjectionFilter(ctx, seed, tail, expectedCols); ok || err != nil {
			return projected, err
		}
	}
	if !isPotentialWriteTail(tail) {
		if pipelined, ok, err := e.executeCallTailPipeline(ctx, seed, tail); ok || err != nil {
			return pipelined, err
		}
	}
	// Fallback fast path for read-only tails the pipeline declines: execute
	// per-row tails concurrently. It runs the tail once per yielded row, so it
	// can't aggregate across rows.
	if len(seed.Rows) > 1 && !isPotentialWriteTail(tail) {
		if parallel, ok, err := e.executeCallTailParallel(ctx, seed, tail, usedCols, expectedCols); ok || err != nil {
			return parallel, err
		}
	}

	results := make([]callTailRowResult, len(seed.Rows))
	for i, row := range seed.Rows {
		res, err := e.executeCallTailSingleRow(ctx, seed.Columns, row, tail, usedCols, expectedCols)
		results[i] = callTailRowResult{idx: i, res: res, err: err}
		if err != nil {
			break
		}
	}
	return combineCallTailRowResults(results, expectedCols)
}

// executeCallTailPipeline runs the clauses after CALL … YIELD as one pipeline
// (runPipelineClauses) whose input rows are the procedure's yielded rows. It
// declines (ok false) when a tail clause isn't a pipeline clause.
func (e *StorageExecutor) executeCallTailPipeline(ctx context.Context, seed *ExecuteResult, tail string) (*ExecuteResult, bool, error) {
	clauses, ok := pipelineClausesFor(ctx, tail)
	if !ok || len(clauses) == 0 {
		return nil, false, nil
	}
	rows := make([]pipelineRow, 0, len(seed.Rows))
	for _, row := range seed.Rows {
		rows = append(rows, callTailRow(ctx, seed, row))
	}
	scope := make(map[string]struct{}, len(seed.Columns))
	for _, column := range seed.Columns {
		scope[column] = struct{}{}
	}
	result, ok, err := e.runPipelineClauseRows(ctx, rows, scope, clauses, clauses, nil)
	if ok {
		e.markCallTailPipelineUsed()
	}
	return result, ok, err
}

func (e *StorageExecutor) tryExecuteCallTailProcedurePipeline(
	ctx context.Context,
	seed *ExecuteResult,
	tail string,
) (*ExecuteResult, bool, error) {
	callIndex := findKeywordIndexInContext(tail, "CALL")
	if callIndex <= 0 {
		return nil, false, nil
	}
	prefix := strings.TrimSpace(tail[:callIndex])
	if !hasPrefixFoldASCII(prefix, "WITH ") {
		return nil, false, nil
	}

	rows := make([]pipelineRow, 0, len(seed.Rows))
	for _, row := range seed.Rows {
		rows = append(rows, callTailRow(ctx, seed, row))
	}
	projected, ok := e.pipelineApplyWith(ctx, rows, prefix)
	if !ok {
		return nil, false, nil
	}
	prefixColumns, ok := callTailWithProjectionColumns(ctx, prefix)
	if !ok {
		return nil, false, nil
	}

	callParts := splitChainedProcedureCall(ctx, strings.TrimSpace(tail[callIndex:]))
	if strings.TrimSpace(callParts.tail) == "" {
		return nil, false, nil
	}
	combined := &ExecuteResult{Columns: append([]string(nil), prefixColumns...)}
	for _, bindings := range projected {
		procedureResult, err := e.executeProcedureCall(ctx, callParts.callOnly, true)
		if err != nil {
			return nil, true, err
		}
		combined.Stats = mergeQueryStats(combined.Stats, procedureResult.Stats)
		if len(combined.Columns) == len(prefixColumns) {
			combined.Columns = append(combined.Columns, procedureResult.Columns...)
		}
		for _, procedureRow := range procedureResult.Rows {
			row := make([]interface{}, 0, len(prefixColumns)+len(procedureRow))
			for _, column := range prefixColumns {
				row = append(row, bindings[column])
			}
			row = append(row, procedureRow...)
			combined.Rows = append(combined.Rows, row)
		}
	}

	result, err := e.executeCallTail(ctx, combined, callParts.tail)
	return result, true, err
}

func splitChainedProcedureCall(ctx context.Context, source string) callSplit {
	return splitCallAndTail(ctx, source)
}
func (e *StorageExecutor) projectCallTailReturnAll(ctx context.Context, seed *ExecuteResult, tail string) (*ExecuteResult, bool, error) {

	node, valid := canonicalQueryClause(ctx, tail)
	if !valid || node.Rule() != cypherantlr.CypherParserRULE_returnSt {
		return nil, false, nil
	}
	_, end := node.Span()
	if strings.TrimSpace(strings.TrimSuffix(strings.TrimSpace(tail[end:]), ";")) != "" {
		return nil, false, nil
	}
	plan := projectionPlanFromSyntax(node)
	if !plan.valid || !plan.star || plan.distinct || len(plan.starProjections) != 0 {
		return nil, false, nil
	}
	columns := append([]string{}, seed.Columns...)
	sort.Strings(columns)
	expanded := plan.withStarExpanded(columns)
	positions := make(map[string]int, len(seed.Columns))
	for index, name := range seed.Columns {
		positions[name] = index
	}
	result := &ExecuteResult{Columns: expanded.columns, Rows: make([][]interface{}, len(seed.Rows)), Stats: seed.Stats}
	for index, row := range seed.Rows {
		projected := make([]interface{}, len(columns))
		for target, name := range columns {
			if position := positions[name]; position < len(row) {
				projected[target] = row[position]
			}
		}
		result.Rows[index] = projected
	}
	if plan.modifiers == "" {
		return result, true, nil
	}
	result, err := e.applyResultModifiers(ctx, result, plan.modifiers)
	return result, true, err
}

type callTailRowResult struct {
	idx int
	res *ExecuteResult
	err error
}

func (e *StorageExecutor) executeCallTailParallel(
	ctx context.Context,
	seed *ExecuteResult,
	tail string,
	usedCols []int,
	expectedCols []string,
) (*ExecuteResult, bool, error) {
	if len(usedCols) == 0 || len(seed.Rows) <= 1 {
		return nil, false, nil
	}
	workers := runtime.GOMAXPROCS(0)
	if workers < 2 {
		workers = 2
	}
	if workers > 8 {
		workers = 8
	}
	if workers > len(seed.Rows) {
		workers = len(seed.Rows)
	}
	type job struct {
		idx int
		row []interface{}
	}
	jobs := make(chan job, len(seed.Rows))
	results := make(chan callTailRowResult, len(seed.Rows))
	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := range jobs {
				res, err := e.executeCallTailSingleRow(ctx, seed.Columns, j.row, tail, usedCols, expectedCols)
				results <- callTailRowResult{idx: j.idx, res: res, err: err}
			}
		}()
	}
	for i, row := range seed.Rows {
		jobs <- job{idx: i, row: row}
	}
	close(jobs)
	wg.Wait()
	close(results)

	ordered := make([]callTailRowResult, len(seed.Rows))
	for rr := range results {
		ordered[rr.idx] = rr
	}
	combined, err := combineCallTailRowResults(ordered, expectedCols)
	return combined, true, err
}

// combineCallTailRowResults concatenates per-row CALL-tail results in row
// order, for the sequential and the parallel per-row paths alike (#547): the
// first failing row's error (in row order, so the parallel path reports the
// same one), and the tail's columns when no row produced any.
func combineCallTailRowResults(results []callTailRowResult, expectedCols []string) (*ExecuteResult, error) {
	var combined *ExecuteResult
	for _, result := range results {
		if result.err != nil {
			return nil, result.err
		}
		if result.res == nil {
			continue
		}
		if combined == nil {
			combined = &ExecuteResult{
				Columns: append([]string{}, result.res.Columns...),
				Rows:    make([][]interface{}, 0, len(result.res.Rows)),
			}
		}
		combined.Stats = mergeQueryStats(combined.Stats, result.res.Stats)
		combined.Rows = append(combined.Rows, result.res.Rows...)
	}
	if combined == nil {
		return &ExecuteResult{Columns: append([]string{}, expectedCols...), Rows: [][]interface{}{}}, nil
	}
	return combined, nil
}

func (e *StorageExecutor) executeCallTailSingleRow(
	ctx context.Context,
	seedCols []string,
	row []interface{},
	tail string,
	usedCols []int,
	expectedCols []string,
) (*ExecuteResult, error) {
	params := map[string]interface{}{}
	prefix := make([]string, 0, len(usedCols)+2)
	withBindings := make([]string, 0, len(usedCols))
	predicates := make([]string, 0, len(usedCols))
	tailIsMatch := tailStartsWithMatchClause(tail)

	for _, i := range usedCols {
		if i >= len(row) {
			continue
		}
		col := seedCols[i]
		val := row[i]
		if node, ok := val.(*storage.Node); ok {
			pname := "seed_id_" + col
			if node != nil {
				params[pname] = string(node.ID)
			} else {
				params[pname] = nil
			}
			if tailIsMatch {
				predicates = append(predicates, fmt.Sprintf("id(%s) = $%s", col, pname))
			} else {
				prefix = append(prefix, fmt.Sprintf("MATCH (%s) WHERE id(%s) = $%s", col, col, pname))
				withBindings = append(withBindings, col)
			}
			continue
		}
		pname := "seed_" + col
		params[pname] = val
		withBindings = append(withBindings, fmt.Sprintf("$%s AS %s", pname, col))
	}

	query := buildCallTailPredicateInjection(tail, predicates)
	if len(withBindings) > 0 {
		prefix = append(prefix, "WITH "+strings.Join(withBindings, ", "))
	}
	if len(prefix) > 0 {
		query = strings.Join(prefix, " ") + " " + query
	}

	inner, err := e.executeInternal(ctx, query, params)
	if err != nil {
		return nil, err
	}
	if len(expectedCols) > 0 && len(expectedCols) == len(inner.Columns) {
		inner.Columns = append([]string{}, expectedCols...)
	}
	return inner, nil
}

func isPotentialWriteTail(tail string) bool {
	t := upperASCII(strings.TrimSpace(tail))
	return findKeywordIndexInContext(t, "CREATE") >= 0 ||
		findKeywordIndexInContext(t, "MERGE") >= 0 ||
		findKeywordIndexInContext(t, "DELETE") >= 0 ||
		findKeywordIndexInContext(t, "SET") >= 0 ||
		findKeywordIndexInContext(t, "REMOVE") >= 0
}

// callTailProjectionPlan is a CALL tail that is exactly WITH … [WHERE …]
// RETURN …, run over the yielded rows by the pipeline's WITH and RETURN
// appliers without the general pipeline's routing.
type callTailProjectionPlan struct {
	// relationship is the optional MATCH admission that precedes WITH.
	relationship *callTailRelationshipMatchPlan
	withClause   string
	returnClause string
	// limitToken / skipToken are the RETURN's LIMIT / SKIP, a literal or a
	// parameter, checked per execution (the parameter's value can change).
	limitToken string
	skipToken  string
	// passThroughWith is a WITH whose items are all row variables under
	// their own names, with no ORDER BY / SKIP / LIMIT / DISTINCT: it only
	// filters (withWhere). The plan then filters the rows with the pipeline's
	// row filter instead of rebuilding each one; the RETURN (never *) reads
	// only the variables the WITH keeps.
	passThroughWith bool
	withWhere       string
}

// Parsed CALL-tail plans, cached by tail text: a nil plan (a tail the plan
// doesn't cover) is cached too.
var (
	callTailProjectionPlans        = newBoundedCache[string, *callTailProjectionPlan](1024, boundedCacheStringShardIndex)
	callTailRelationshipMatchPlans = newBoundedCache[string, *callTailProjectionPlan](1024, boundedCacheStringShardIndex)
)

// callTailRelationshipMatchPlan is a CALL tail MATCH (a)-[r:T {key: y.p}]->(b)
// [WHERE …] WITH … RETURN … over a yielded relationship y: r is bound to y
// itself when its type and key property match, and a and b to its end nodes.
type callTailRelationshipMatchPlan struct {
	startVar       string
	startLabel     string
	relVar         string
	relType        string
	propertyKey    string
	propertyExpr   string
	propertySource string
	endVar         string
	endLabel       string
	whereClause    string
}

type callTailRelationshipPatternParts struct {
	startVar     string
	startLabel   string
	relVar       string
	relType      string
	propertyKey  string
	propertyExpr string
	endVar       string
	endLabel     string
	rest         string
}

func (e *StorageExecutor) tryExecuteCallTailProjectionFilter(
	ctx context.Context,
	seed *ExecuteResult,
	tail string,
	expectedCols []string,
) (*ExecuteResult, bool, error) {
	plan, ok := e.parseCallTailProjectionPlan(ctx, tail)
	if !ok || plan.relationship != nil {
		return nil, false, nil
	}
	rows := make([]pipelineRow, 0, len(seed.Rows))
	for _, seedRow := range seed.Rows {
		rows = append(rows, callTailRow(ctx, seed, seedRow))
	}
	result, ok := e.executeCallTailProjectionPlan(ctx, plan, rows, expectedCols)
	if !ok {
		return nil, false, nil
	}
	e.markCallTailProjectionFastPathUsed()
	return result, true, nil
}

// executeCallTailProjectionPlan applies the plan's WITH (and its WHERE), then
// its RETURN with ORDER BY / SKIP / LIMIT, with the pipeline's appliers. ok is
// false when an applier declines; nothing has been written then.
func (e *StorageExecutor) executeCallTailProjectionPlan(
	ctx context.Context,
	plan *callTailProjectionPlan,
	rows []pipelineRow,
	expectedCols []string,
) (*ExecuteResult, bool) {
	var projected []pipelineRow
	if plan.passThroughWith {
		projected = e.filterPipelineRows(ctx, rows, plan.withWhere)
	} else {
		var ok bool
		projected, ok = e.pipelineApplyWith(ctx, rows, plan.withClause)
		if !ok {
			return nil, false
		}
	}
	result, ok := e.pipelineApplyReturn(ctx, projected, plan.returnClause)
	if !ok {
		return nil, false
	}
	if len(expectedCols) > 0 && len(expectedCols) == len(result.Columns) {
		result.Columns = append([]string{}, expectedCols...)
	}
	return result, true
}

func (e *StorageExecutor) tryExecuteCallTailRelationshipMatchProjection(
	ctx context.Context,
	seed *ExecuteResult,
	tail string,
	expectedCols []string,
) (*ExecuteResult, bool, error) {
	projection, ok := e.parseCallTailProjectionPlan(ctx, tail)
	if !ok || projection.relationship == nil {
		return nil, false, nil
	}
	plan := projection.relationship
	rows := make([]pipelineRow, 0, len(seed.Rows))
	nodes := make(map[storage.NodeID]*storage.Node)
	getNode := func(id storage.NodeID) (*storage.Node, error) {
		if node := nodes[id]; node != nil {
			return node, nil
		}
		node, err := e.getQueryNode(e.storage, id)
		if err == nil && node != nil {
			nodes[id] = node
		}
		return node, err
	}
	for _, seedRow := range seed.Rows {
		values := callTailRow(ctx, seed, seedRow)
		relationship, ok := values[plan.propertySource].(*storage.Edge)
		if !ok || relationship == nil {
			continue
		}
		if plan.relType != "" && relationship.Type != plan.relType {
			continue
		}
		expected, _ := e.evaluateRowExpressionWithContext(ctx, plan.propertyExpr, values)
		if expected == nil || !e.compareEqual(relationship.Properties[plan.propertyKey], expected) {
			continue
		}
		startNode, err := getNode(relationship.StartNode)
		if err != nil || startNode == nil {
			continue
		}
		endNode, err := getNode(relationship.EndNode)
		if err != nil || endNode == nil {
			continue
		}
		if plan.startLabel != "" && !containsString(startNode.Labels, plan.startLabel) {
			continue
		}
		if plan.endLabel != "" && !containsString(endNode.Labels, plan.endLabel) {
			continue
		}
		matched := make(pipelineRow, util.SafePreallocSum(len(values), 3))
		for key, value := range values {
			matched[key] = value
		}
		matched[plan.startVar] = startNode
		matched[plan.relVar] = relationship
		matched[plan.endVar] = endNode
		if plan.whereClause != "" && !e.evaluateRowPredicate(ctx, plan.whereClause, matched) {
			continue
		}
		rows = append(rows, matched)
	}
	result, ok := e.executeCallTailProjectionPlan(ctx, projection, rows, expectedCols)
	if !ok {
		return nil, false, nil
	}
	e.markCallTailProjectionFastPathUsed()
	return result, true, nil
}

func parseCallTailRelationshipPattern(tail string) (callTailRelationshipPatternParts, bool) {
	var parts callTailRelationshipPatternParts
	rest := strings.TrimSpace(tail)
	if !hasPrefixFoldASCII(rest, "MATCH") {
		return parts, false
	}
	rest = strings.TrimSpace(rest[len("MATCH"):])
	startVar, startLabel, rest, ok := parseCallTailNodeToken(rest)
	if !ok {
		return parts, false
	}
	rest = strings.TrimLeftFunc(rest, func(r rune) bool { return r == ' ' || r == '\t' || r == '\n' || r == '\r' })
	if !strings.HasPrefix(rest, "-") {
		return parts, false
	}
	rest = strings.TrimSpace(rest[1:])
	relInside, rest, ok := parseCallTailDelimited(rest, '[', ']')
	if !ok {
		return parts, false
	}
	relVar, relType, propertyKey, propertyExpr, ok := parseCallTailRelationshipToken(relInside)
	if !ok {
		return parts, false
	}
	rest = strings.TrimSpace(rest)
	if !strings.HasPrefix(rest, "->") {
		return parts, false
	}
	rest = strings.TrimSpace(rest[2:])
	endVar, endLabel, rest, ok := parseCallTailNodeToken(rest)
	if !ok {
		return parts, false
	}
	parts.startVar = startVar
	parts.startLabel = startLabel
	parts.relVar = relVar
	parts.relType = relType
	parts.propertyKey = propertyKey
	parts.propertyExpr = propertyExpr
	parts.endVar = endVar
	parts.endLabel = endLabel
	parts.rest = rest
	return parts, true
}

func parseCallTailNodeToken(input string) (variable, label, rest string, ok bool) {
	inside, rest, ok := parseCallTailDelimited(strings.TrimSpace(input), '(', ')')
	if !ok {
		return "", "", "", false
	}
	variable, label, ok = parseCallTailIdentifierAndOptionalType(inside)
	if !ok || variable == "" {
		return "", "", "", false
	}
	return variable, label, rest, true
}

func parseCallTailRelationshipToken(input string) (variable, relType, propertyKey, propertyExpr string, ok bool) {
	rest := strings.TrimSpace(input)
	variable, rest, ok = parseCallTailIdentifier(rest)
	if !ok || variable == "" {
		return "", "", "", "", false
	}
	rest = strings.TrimSpace(rest)
	if strings.HasPrefix(rest, ":") {
		rest = strings.TrimSpace(rest[1:])
		relType, rest, ok = parseCallTailIdentifier(rest)
		if !ok || relType == "" {
			return "", "", "", "", false
		}
		rest = strings.TrimSpace(rest)
	}
	if rest == "" {
		return variable, relType, "", "", true
	}
	if !strings.HasPrefix(rest, "{") {
		return "", "", "", "", false
	}
	propertyKey, propertyExpr, rest, ok = parseCallTailSinglePropertyMap(rest)
	if !ok || strings.TrimSpace(rest) != "" {
		return "", "", "", "", false
	}
	return variable, relType, propertyKey, propertyExpr, true
}

func parseCallTailIdentifierAndOptionalType(input string) (variable, label string, ok bool) {
	rest := strings.TrimSpace(input)
	variable, rest, ok = parseCallTailIdentifier(rest)
	if !ok || variable == "" {
		return "", "", false
	}
	rest = strings.TrimSpace(rest)
	if rest == "" {
		return variable, "", true
	}
	if !strings.HasPrefix(rest, ":") {
		return "", "", false
	}
	rest = strings.TrimSpace(rest[1:])
	label, rest, ok = parseCallTailIdentifier(rest)
	if !ok || label == "" || strings.TrimSpace(rest) != "" {
		return "", "", false
	}
	return variable, label, true
}

func parseCallTailIdentifier(input string) (string, string, bool) {
	return parseIdentifierToken(input)
}

func parseCallTailDelimited(input string, open, close byte) (inside, rest string, ok bool) {
	return extractDelimitedSection(strings.TrimSpace(input), rune(open), rune(close))
}

func parseCallTailSinglePropertyMap(input string) (key, expr, rest string, ok bool) {
	inside, rest, ok := parseCallTailDelimited(input, '{', '}')
	if !ok {
		return "", "", "", false
	}
	parts := splitTopLevelComma(inside)
	if len(parts) != 1 {
		return "", "", "", false
	}
	inside = parts[0]
	colonIdx := findTopLevelMapKeyValueSeparator(inside)
	if colonIdx <= 0 {
		return "", "", "", false
	}
	key = strings.TrimSpace(inside[:colonIdx])
	expr = strings.TrimSpace(inside[colonIdx+1:])
	if !isValidIdentifier(key) || expr == "" {
		return "", "", "", false
	}
	return key, expr, rest, true
}

func resolveOptionalIntLiteralOrParam(ctx context.Context, raw string) (int, bool) {
	if strings.TrimSpace(raw) == "" {
		return -1, true
	}
	return resolveIntLiteralOrParam(ctx, raw)
}

func resolveIntLiteralOrParam(ctx context.Context, raw string) (int, bool) {
	raw = strings.TrimSpace(raw)
	if strings.HasPrefix(raw, "$") {
		value, ok := getParamsFromContext(ctx)[strings.TrimPrefix(raw, "$")]
		if !ok {
			return 0, false
		}
		return convert.ToInt(value, convert.IntegerFloat)
	}
	integer, err := strconv.Atoi(raw)
	return integer, err == nil
}

// callTailPlanClauseKeywords start the clauses that can follow a CALL's (or
// a SHOW command's) YIELD, ending its YIELD items and segments; a compiled
// CALL-tail projection plan can't hold them between its WITH and RETURN.
var callTailPlanClauseKeywords = []string{
	"MATCH", "OPTIONAL", "UNWIND", "CALL", "WITH", "CREATE", "MERGE",
	"SET", "DELETE", "DETACH", "REMOVE", "FOREACH", "LOAD", "UNION",
	// Cypher 25's clauses (#907).
	"FILTER", "LET", "FOR", "FINISH", "INSERT",
}

// parseCallTailProjectionPlan returns the tail's projection plan, parsed once
// per tail text, when its LIMIT / SKIP resolve to integers for this execution.
func (e *StorageExecutor) parseCallTailProjectionPlan(ctx context.Context, tail string) (*callTailProjectionPlan, bool) {
	cache := callTailProjectionPlans
	if hasPrefixFoldASCII(strings.TrimSpace(tail), "MATCH ") {
		cache = callTailRelationshipMatchPlans
	}
	plan, cached := cache.get(tail)
	if !cached {
		plan = e.planCallTailProjection(ctx, tail)
		cache.put(tail, plan)
	}
	if plan == nil || !callTailPlanTokensResolve(ctx, plan) {
		return nil, false
	}
	return plan, true
}

// callTailPlanTokensResolve reports whether the plan's LIMIT and SKIP are a
// literal or a bound integer parameter; other forms are the pipeline's.
func callTailPlanTokensResolve(ctx context.Context, plan *callTailProjectionPlan) bool {
	if _, ok := resolveOptionalIntLiteralOrParam(ctx, plan.limitToken); !ok {
		return false
	}
	_, ok := resolveOptionalIntLiteralOrParam(ctx, plan.skipToken)
	return ok
}

// planCallTailProjection parses WITH … [WHERE …] RETURN …, optionally
// preceded by a relationship MATCH over a yielded relationship, or returns nil.
func (e *StorageExecutor) planCallTailProjection(ctx context.Context, tail string) *callTailProjectionPlan {
	trimmed := strings.TrimSpace(tail)
	if hasPrefixFoldASCII(trimmed, "MATCH ") && !isPotentialWriteTail(trimmed) {
		parts, ok := parseCallTailRelationshipPattern(trimmed)
		if !ok {
			return nil
		}
		rest := strings.TrimSpace(parts.rest)
		withIdx := topLevelKeywordIndex(rest, "WITH")
		if withIdx < 0 {
			return nil
		}
		whereClause := strings.TrimSpace(rest[:withIdx])
		if whereClause != "" {
			if !hasPrefixFoldASCII(whereClause, "WHERE ") {
				return nil
			}
			whereClause = strings.TrimSpace(whereClause[len("WHERE "):])
		}
		projection := e.planCallTailProjection(ctx, strings.TrimSpace(rest[withIdx:]))
		if projection == nil {
			return nil
		}
		propertyExpr := strings.TrimSpace(parts.propertyExpr)
		propertySource := ""
		if dotIdx := strings.Index(propertyExpr, "."); dotIdx > 0 {
			propertySource = strings.TrimSpace(propertyExpr[:dotIdx])
		}
		if parts.propertyKey == "" || propertySource == "" {
			return nil
		}
		projection.relationship = &callTailRelationshipMatchPlan{
			startVar:       parts.startVar,
			startLabel:     parts.startLabel,
			relVar:         parts.relVar,
			relType:        parts.relType,
			propertyKey:    parts.propertyKey,
			propertyExpr:   propertyExpr,
			propertySource: propertySource,
			endVar:         parts.endVar,
			endLabel:       parts.endLabel,
			whereClause:    whereClause,
		}
		return projection
	}
	if !hasPrefixFoldASCII(trimmed, "WITH ") || isPotentialWriteTail(trimmed) {
		return nil
	}
	withIdx := len("WITH ")
	returnIdx := topLevelKeywordIndex(trimmed, "RETURN")
	if returnIdx < 0 {
		return nil
	}
	beforeReturn := strings.TrimSpace(trimmed[withIdx:returnIdx])
	returnAndModifiers := strings.TrimSpace(trimmed[returnIdx+len("RETURN"):])
	if beforeReturn == "" || returnAndModifiers == "" {
		return nil
	}
	// The plan covers exactly WITH … [WHERE …] RETURN …; a tail with another
	// clause between them (WITH label MATCH (n) RETURN …) is the pipeline's.
	for _, keyword := range callTailPlanClauseKeywords {
		if topLevelKeywordIndex(beforeReturn, keyword) >= 0 {
			return nil
		}
	}

	withProjection := beforeReturn
	if whereIdx := topLevelKeywordIndex(beforeReturn, "WHERE"); whereIdx >= 0 {
		withProjection = strings.TrimSpace(beforeReturn[:whereIdx])
	}
	if withProjection == "" {
		return nil
	}
	returnProjection, orderBy, limitToken, skipToken := splitCallTailProjectionModifiers(returnAndModifiers)
	if returnProjection == "" {
		return nil
	}
	// The plan projects row by row: aggregation, DISTINCT and SKIP / LIMIT
	// expressions (LIMIT 0 + 1) are the pipeline's (executeCallTailPipeline).
	if startsWithDistinct(withProjection) || startsWithDistinct(returnProjection) ||
		containsAggregateFunc(withProjection) || containsAggregateFunc(returnProjection) || containsAggregateFunc(orderBy) {
		return nil
	}
	withItems := e.parseReturnItems(ctx, withProjection)
	returnItems := e.parseReturnItems(ctx, returnProjection)
	if len(withItems) == 0 || len(returnItems) == 0 || hasStarReturnItem(withItems) || hasStarReturnItem(returnItems) {
		return nil
	}
	plan := &callTailProjectionPlan{
		withClause:   "WITH " + beforeReturn,
		returnClause: "RETURN " + returnAndModifiers,
		limitToken:   limitToken,
		skipToken:    skipToken,
	}
	plan.passThroughWith = true
	for _, keyword := range []string{"ORDER BY", "SKIP", "LIMIT"} {
		if topLevelKeywordIndex(beforeReturn, keyword) >= 0 {
			plan.passThroughWith = false
		}
	}
	for _, item := range withItems {
		if !isValidIdentifier(item.expr) || item.alias != item.expr {
			plan.passThroughWith = false
		}
	}
	if whereIdx := topLevelKeywordIndex(beforeReturn, "WHERE"); whereIdx >= 0 {
		plan.withWhere = strings.TrimSpace(beforeReturn[whereIdx+len("WHERE"):])
	}
	return plan
}

func cloneStringInterfaceMap(values map[string]interface{}) map[string]interface{} {
	out := make(map[string]interface{}, len(values))
	for key, value := range values {
		out[key] = value
	}
	return out
}

func hasStarReturnItem(items []returnItem) bool {
	for _, item := range items {
		if strings.TrimSpace(item.expr) == "*" {
			return true
		}
	}
	return false
}

func splitCallTailProjectionModifiers(returnAndModifiers string) (projection, orderBy, limitToken, skipToken string) {
	projection = strings.TrimSpace(returnAndModifiers)
	modifierStart := len(projection)
	for _, kw := range []string{"ORDER BY", "SKIP", "LIMIT"} {
		if idx := topLevelKeywordIndex(projection, kw); idx >= 0 && idx < modifierStart {
			modifierStart = idx
		}
	}
	modifiers := ""
	if modifierStart < len(projection) {
		modifiers = strings.TrimSpace(projection[modifierStart:])
		projection = strings.TrimSpace(projection[:modifierStart])
	}
	if modifiers == "" {
		return projection, "", "", ""
	}
	if orderIdx := topLevelKeywordIndex(modifiers, "ORDER BY"); orderIdx >= 0 {
		end := len(modifiers)
		for _, kw := range []string{"SKIP", "LIMIT"} {
			if idx := topLevelKeywordIndex(modifiers[orderIdx:], kw); idx >= 0 {
				abs := orderIdx + idx
				if abs > orderIdx && abs < end {
					end = abs
				}
			}
		}
		orderBy = strings.TrimSpace(modifiers[orderIdx:end])
	}
	limitToken = extractCallTailModifierToken(modifiers, "LIMIT")
	skipToken = extractCallTailModifierToken(modifiers, "SKIP")
	return projection, orderBy, limitToken, skipToken
}

// extractCallTailModifierToken returns the whole value of keyword (SKIP or
// LIMIT) in modifiers, up to the next modifier: an expression such as
// LIMIT 0 + 1 stays whole, so the projection plan declines it instead of
// reading LIMIT 0 (#572).
func extractCallTailModifierToken(modifiers, keyword string) string {
	idx := topLevelKeywordIndex(modifiers, keyword)
	if idx < 0 {
		return ""
	}
	rest := modifiers[idx+len(keyword):]
	end := len(rest)
	for _, next := range []string{"ORDER BY", "SKIP", "LIMIT"} {
		if nextIdx := topLevelKeywordIndex(rest, next); nextIdx >= 0 && nextIdx < end {
			end = nextIdx
		}
	}
	return strings.TrimSpace(rest[:end])
}

func callTailHasRelationshipTypeConstraint(tail string) bool {
	for from := 0; from < len(tail); {
		open, close := nextRelationshipBracket(tail, from)
		if open < 0 {
			return false
		}
		if findTopLevelOperator(tail[open+1:close], ":", false, true) >= 0 {
			return true
		}
		from = close + 1
	}
	return false
}

// callTailRow returns a yielded row as a pipeline row, with the statement's
// parameters bound as "$name" the way the statement pipeline binds them, so a
// typed parameter (a list or map the text substitution keeps typed) resolves
// in a CALL tail's WHERE and projections.
func callTailRow(ctx context.Context, seed *ExecuteResult, row []interface{}) pipelineRow {
	params := getParamsFromContext(ctx)
	values := make(pipelineRow, len(seed.Columns)+len(params))
	for i, col := range seed.Columns {
		if i < len(row) {
			values[col] = row[i]
		} else {
			values[col] = nil
		}
	}
	bindParameterRow(ctx, values)
	return values
}

func splitPathAssignment(patternPart string) (string, string, bool) {
	eqIdx := strings.Index(patternPart, "=")
	if eqIdx == -1 {
		return "", "", false
	}
	left := strings.TrimSpace(patternPart[:eqIdx])
	right := strings.TrimSpace(patternPart[eqIdx+1:])
	if left == "" || right == "" {
		return "", "", false
	}
	return left, right, true
}

// isIdentifierReferenced compares identifier tokens with a binding's decoded
// name. scanIdentifierToken owns identifier decoding, including doubled
// backticks; matching raw query bytes loses those imported bindings.
// This is a conservative name check, not a scope or variable-role analysis.
func isIdentifierReferenced(query, identifier string) bool {
	if strings.TrimSpace(identifier) == "" {
		return false
	}
	for index := 0; index < len(query); {
		if isCypherStringQuoteByte(query[index]) {
			index = skipCypherQuotedText(query, index, query[index])
			continue
		}
		if end := queryCommentEnd(query, index); end > index {
			index = end
			continue
		}
		name, end, ok := scanIdentifierToken(query, index)
		if !ok || (!isCypherBacktickByte(query[index]) && index > 0 && isIdentByte(query[index-1])) {
			index++
			continue
		}
		if name == identifier {
			return true
		}
		index = end
	}
	return false
}

// findKeywordIndexInContext returns the index of keyword's first occurrence
// at the top level of s, or -1: topLevelKeywordIndex, the one scanner. A
// keyword inside parentheses, a list or braces (a function call's or list
// comprehension's WHERE, a subquery body) isn't the clause's; nor is one in a
// string, a quoted name or a comment, the WITH of STARTS WITH / ENDS WITH, or
// a clause keyword used as a name.
func findKeywordIndexInContext(s, keyword string) int {
	return topLevelKeywordIndex(s, keyword)
}

// applyYieldFilter applies a procedure call's YIELD to the procedure's rows.
// It selects and aliases the yielded columns, then filters the rows with the
// YIELD's WHERE and orders / pages them with its ORDER BY / SKIP / LIMIT the
// way a WITH does: through the pipeline, over the aliased rows, so the
// predicate sees the aliases and evaluates like any other WHERE (#530).
func (e *StorageExecutor) applyYieldFilter(ctx context.Context, result *ExecuteResult, yield *yieldClause) (*ExecuteResult, error) {
	if yield == nil {
		return result, nil
	}
	if err := validateYieldColumnsExist(result.Columns, yield); err != nil {
		return nil, err
	}

	// Apply column selection and aliasing (if not YIELD *)
	if !yield.yieldAll && len(yield.items) > 0 {
		colIndex := make(map[string]int, len(result.Columns))
		for i, col := range result.Columns {
			colIndex[col] = i
		}
		newColumns := make([]string, 0, len(yield.items))
		for _, item := range yield.items {
			newColumns = append(newColumns, item.column())
		}
		newRows := make([][]interface{}, 0, len(result.Rows))
		for _, row := range result.Rows {
			newRow := make([]interface{}, len(yield.items))
			for i, item := range yield.items {
				if idx, ok := colIndex[item.name]; ok && idx < len(row) {
					newRow[i] = row[idx]
				}
			}
			newRows = append(newRows, newRow)
		}
		result.Columns = newColumns
		result.Rows = newRows
	}
	if !yield.hasModifiers() {
		return result, nil
	}

	rows := make([]pipelineRow, 0, len(result.Rows))
	for _, row := range result.Rows {
		rows = append(rows, callTailRow(ctx, result, row))
	}
	rows = e.filterPipelineRows(ctx, rows, yield.where)
	if yield.orderBy != "" || yield.skip != "" || yield.limit != "" {
		var with strings.Builder
		with.WriteString("WITH *")
		if yield.orderBy != "" {
			with.WriteString(" ORDER BY " + yield.orderBy)
		}
		if yield.skip != "" {
			with.WriteString(" SKIP " + yield.skip)
		}
		if yield.limit != "" {
			with.WriteString(" LIMIT " + yield.limit)
		}
		ordered, ok := e.pipelineApplyWith(ctx, rows, with.String())
		if !ok {
			// SKIP / LIMIT passed the compile-time checks (validateYieldModifiers),
			// so only a parameter can make them invalid here.
			return nil, localizedStatusError("Neo.ClientError.Statement.ArgumentError", "InvalidArgumentType",
				localization.CypherCoreYieldPaginationInvalid())
		}
		rows = ordered
	}
	result.Rows = make([][]interface{}, 0, len(rows))
	for _, row := range rows {
		values := make([]interface{}, len(result.Columns))
		for i, column := range result.Columns {
			values[i] = row[column]
		}
		result.Rows = append(result.Rows, values)
	}
	return result, nil
}

func (e *StorageExecutor) executeCall(ctx context.Context, cypher string) (*ExecuteResult, error) {
	return e.executeProcedureCall(ctx, cypher, false)
}

// executeProcedureCall runs a procedure call and the tail after it. inQuery is
// true when the call is part of a larger query whose other clauses the caller
// runs (MATCH … CALL, a CALL in a tail): its YIELD may then filter, order and
// page, which a standalone call can't (validateYieldModifiers).
func (e *StorageExecutor) executeProcedureCall(ctx context.Context, cypher string, inQuery bool) (*ExecuteResult, error) {
	// A RETURN right after YIELD is the start of the tail, like any other
	// clause, so it runs over all yielded rows (executeCallTail): an aggregate
	// in it groups the rows, and ORDER BY / SKIP / LIMIT apply to all of them.
	parts := splitChainedProcedureCall(ctx, cypher)
	callCypher := parts.callOnly
	tailCypher := parts.tail

	// Parse YIELD clause for post-processing
	yield := parseYieldClause(ctx, callCypher)
	if err := e.validateYieldModifiers(ctx, yield, inQuery || strings.TrimSpace(tailCypher) != "" || endsInFinish(ctx, cypher)); err != nil {
		return nil, err
	}

	// Registry-first path: canonical procedure contract for built-ins and UDFs.
	ensureBuiltInProceduresRegistered()
	procName := extractProcedureName(ctx, callCypher)
	if proc, found := globalProcedureRegistry.Get(procName); found {
		hasTail := strings.TrimSpace(tailCypher) != ""
		if err := validateProcedureArgumentPassingMode(ctx, proc.Spec, callCypher, hasTail); err != nil {
			return nil, err
		}
		if err := validateProcedureYieldBindings(yield, hasTail); err != nil {
			return nil, err
		}
		args, err := e.extractBoundProcedureInvocationArguments(ctx, proc.Spec, callCypher)
		if err != nil {
			return nil, err
		}
		if yield == nil && strings.TrimSpace(tailCypher) != "" && len(proc.Spec.Returns) > 0 {
			for _, column := range proc.Spec.Returns {
				if referencesVariable(tailCypher, column.Name) {
					return nil, newSemanticError(
						"Neo.ClientError.Statement.SyntaxError",
						"UndefinedVariable",
						fmt.Sprintf("procedure output %s must be introduced with YIELD", column.Name),
					)
				}
			}
		}
		procedureCtx, procedureExec := e.systemProcedureScope(ctx)
		if proc.Spec.OwnsTransactions {
			if err := procedureExec.checkPeriodicTransactionScope(procedureCtx, procName); err != nil {
				return nil, err
			}
		}
		result, err := procedureExec.executeProcedureHandler(procedureCtx, proc, callCypher, args)
		if err != nil {
			return nil, procedureRuntimeError(procName, err)
		}
		if proc.User {
			result = runtimeProcedureResult(result)
		}
		if yield != nil {
			result, err = e.applyYieldFilter(ctx, result, yield)
			if err != nil {
				return nil, err
			}
		}
		if strings.TrimSpace(tailCypher) != "" {
			if yield == nil && len(proc.Spec.Returns) == 0 {
				// A void procedure leaves the row it was called for as it
				// is: the clauses after it run once, as after any other
				// leading clause.
				seed := &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{{}}}
				if result != nil {
					seed.Stats = result.Stats
				}
				result = seed
			}
			return e.executeCallTail(ctx, result, tailCypher)
		}
		return result, nil
	}

	// Terminal chokepoint of the converged procedure router: every built-in
	// procedure is registered, so an unrecognized name is rejected here.
	return nil, unknownProcedureError(procName)
}

func (e *StorageExecutor) callDbLabels() (*ExecuteResult, error) {
	nodes, err := e.storage.AllNodes()
	if err != nil {
