// dropIndexOfKind backs the db.index.<kind>.drop compatibility procedures: it
// drops the named index through dropIndexByName (the DROP INDEX path) only when
// an index of that kind exists under the name, and otherwise fails with
// Neo.ClientError.Schema.IndexDropFailed, so a procedure never reports a drop
// that did not happen and never drops an index of another kind.
func (e *StorageExecutor) dropIndexOfKind(name, kind string, exists func(*storage.SchemaManager) bool) error {
	if isCompositeRoot(e.storage) {
		return localizedError(localization.CypherSchemaCompositeDDLNotAllowed(), nil)
	}
	return e.mutateSchema(context.Background(), func(schema *storage.SchemaManager) error {
		if schema == nil || !exists(schema) {
			return newSemanticError("Neo.ClientError.Schema.IndexDropFailed", "MissingIndex",
				fmt.Sprintf("there is no %s index named %q", kind, name))
		}
		return e.dropIndexByName(name, false)
	})
}

// callDbCreateSetNodeVectorProperty sets a vector property on a node - Neo4j db.create.setNodeVectorProperty()
// Syntax: CALL db.create.setNodeVectorProperty(node, propertyKey, vector)
func (e *StorageExecutor) callDbCreateSetNodeVectorProperty(ctx context.Context, cypher string) (*ExecuteResult, error) {
	arguments, err := extractProcedureInvocationArguments(ctx, ProcedureSpec{Name: "db.create.setNodeVectorProperty", MinArgs: 3, MaxArgs: 3}, cypher)
	if err != nil {
		return nil, err
	}
	return e.callSetVectorProperty(ctx, arguments, false)
}

// callDbCreateSetRelationshipVectorProperty sets a vector property on a relationship - Neo4j db.create.setRelationshipVectorProperty()
// Syntax: CALL db.create.setRelationshipVectorProperty(relationship, propertyKey, vector)
func (e *StorageExecutor) callDbCreateSetRelationshipVectorProperty(ctx context.Context, cypher string) (*ExecuteResult, error) {
	arguments, err := extractProcedureInvocationArguments(ctx, ProcedureSpec{Name: "db.create.setRelationshipVectorProperty", MinArgs: 3, MaxArgs: 3}, cypher)
	if err != nil {
		return nil, err
	}
	return e.callSetVectorProperty(ctx, arguments, true)
}

func (e *StorageExecutor) callSetVectorProperty(ctx context.Context, arguments []interface{}, relationship bool) (*ExecuteResult, error) {
	if len(arguments) != 3 {
		return nil, newSemanticError("Neo.ClientError.Statement.SyntaxError", "InvalidNumberOfArguments", "vector property setter requires three arguments")
	}
	identifier, validID := arguments[0].(string)
	switch entity := arguments[0].(type) {
	case *storage.Node:
		if !relationship && entity != nil {
			identifier, validID = string(entity.ID), true
		}
	case *storage.Edge:
		if relationship && entity != nil {
			identifier, validID = string(entity.ID), true
		}
	}
	propertyKey, validKey := arguments[1].(string)
	if expression, raw := arguments[2].(string); raw && strings.HasPrefix(strings.TrimSpace(expression), "[") {
		arguments[2] = e.evaluateExpressionWithContext(ctx, expression, nil, nil)
	}
	vector, validVector := toFloat64Slice(arguments[2])
	if !validID || !validKey || !validVector {
		return nil, newSemanticError("Neo.ClientError.Statement.TypeError", "InvalidArgumentType", "vector property setter requires an entity, a STRING property key, and a numeric vector")
	}
	store := e.getStorage(ctx)
	if relationship {
		edge, err := store.GetEdge(storage.EdgeID(identifier))
		if err != nil {
			return nil, localizedError(localization.CypherProceduresRelationshipNotFound(identifier), nil)
		}
		if current, ok := toFloat64Slice(edge.Properties[propertyKey]); !ok || !slices.Equal(current, vector) {
			edge.Properties[propertyKey] = vector
			if err := updateMutatedEdge(store, edge); err != nil {
				return nil, localizedError(localization.CypherProceduresUpdateRelationshipFailed(err), err)
			}
			e.notifyEdgeMutated(string(edge.ID))
		}
		if entity, ok := arguments[0].(*storage.Edge); ok {
			entity.Properties = edge.Properties
			entity.UpdatedAt = edge.UpdatedAt
		}
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	}
	node, err := store.GetNode(storage.NodeID(identifier))
	if err != nil {
		return nil, localizedError(localization.CypherProceduresNodeNotFound(identifier), nil)
	}
	if current, ok := toFloat64Slice(node.Properties[propertyKey]); !ok || !slices.Equal(current, vector) {
		node.Properties[propertyKey] = vector
		if err := updateMutatedNode(store, node); err != nil {
			return nil, localizedError(localization.CypherProceduresUpdateNodeFailed(err), err)
		}
		e.notifyNodeMutated(string(node.ID))
	}
	if entity, ok := arguments[0].(*storage.Node); ok {
		entity.Properties = node.Properties
		entity.UpdatedAt = node.UpdatedAt
	}
	return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
}

// callTxSetMetadata sets transaction metadata - Neo4j tx.setMetaData()
//
// This procedure is used to attach metadata to transactions for logging/debugging.
// Syntax: CALL tx.setMetaData({key: value})
//
// Uses the active explicit transaction or the statement's implicit transaction.
// Metadata is stored with the transaction for logging, debugging, or audit trails.
func (e *StorageExecutor) callTxSetMetadata(ctx context.Context, arguments []interface{}) (*ExecuteResult, error) {
	var tx *storage.BadgerTransaction
	if e.txContext != nil && e.txContext.active {
		var supported bool
		tx, supported = e.txContext.tx.(*storage.BadgerTransaction)
		if !supported {
			return nil, localizedError(localization.CypherProceduresMetadataTransactionUnsupported(), nil)
		}
	} else if wrapper, ok := e.getStorage(ctx).(*transactionStorageWrapper); ok {
		tx = wrapper.tx
	}
	if tx == nil {
		return nil, localizedError(localization.CypherProceduresMetadataActiveTransactionRequired(), nil)
	}

	if len(arguments) != 1 {
		return nil, localizedError(localization.CypherProceduresMetadataObjectRequired(), nil)
	}

	metadata, valid := toStringAnyMap(arguments[0])
	if expression, raw := arguments[0].(string); raw {
		metadata, valid = toStringAnyMap(e.evaluateExpressionWithContext(ctx, expression, nil, nil))
	}
	if !valid {
		return nil, newSemanticError("Neo.ClientError.Statement.TypeError", "InvalidArgumentType", "tx.setMetaData requires a MAP")
	}

	err := tx.SetMetadata(metadata)
	if err != nil {
		return nil, localizedError(localization.CypherProceduresSetMetadataFailed(err), err)
	}

	return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
}

package cypher

import (
	"context"
	"fmt"
	"github.com/orneryd/nornicdb/internal/collection"
	"runtime"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

type queryStatisticsCollector struct {
	registry   *queryStatisticsRegistry
	active     atomic.Bool
	mu         sync.Mutex
	generation uint64
	deadline   time.Time
	queries    map[string]*queryStatisticsRecord
	order      []string
}

type queryStatisticsRegistry struct {
	mu         sync.Mutex
	collectors map[string]*queryStatisticsCollector
}

func (registry *queryStatisticsRegistry) forDatabase(name string) *queryStatisticsCollector {
	registry.mu.Lock()
	defer registry.mu.Unlock()
	if registry.collectors == nil {
		registry.collectors = make(map[string]*queryStatisticsCollector)
	}
	if collector := registry.collectors[name]; collector != nil {
		return collector
	}
	// Query collection is on from the start, as in Neo4j 5.26: a fresh
	// database reports "collecting" and records every query until
	// db.stats.stop('QUERIES').
	collector := &queryStatisticsCollector{registry: registry, generation: 1}
	collector.active.Store(true)
	registry.collectors[name] = collector
	return collector
}

type queryStatisticsRecord struct {
	invocations                    []queryStatisticsInvocation
	count, total, minimum, maximum int64
}

// queryStatisticsInvocation is one recorded execution; db.stats.retrieve
// renders it as an invocation map.
type queryStatisticsInvocation struct {
	elapsedUs, startMillis int64
}

// ShareQueryStatisticsFrom shares a database's collector with a fresh executor.
// Configure this before executing queries; transaction state remains independent.
// For example, a protocol transaction executor can share its cached database
// executor's collector while keeping a separate storage transaction.
//
//	transactionExecutor := NewStorageExecutor(databaseStorage)
//	transactionExecutor.ShareQueryStatisticsFrom(databaseExecutor)
func (e *StorageExecutor) ShareQueryStatisticsFrom(source *StorageExecutor) {
	if source == nil {
		return
	}
	e.queryStatistics = source.queryStatistics
	if source.queryStatistics != nil && source.queryStatistics.registry != nil {
		e.queryStatistics = source.queryStatistics.registry.forDatabase(e.currentDatabaseName())
	}
}

func (collector *queryStatisticsCollector) start(query string, now time.Time) uint64 {
	if collector == nil || !collector.active.Load() || len(query) > 65536 || containsFold(query, "db.stats.") {
		return 0
	}
	collector.mu.Lock()
	defer collector.mu.Unlock()
	if !collector.deadline.IsZero() && !now.Before(collector.deadline) {
		collector.active.Store(false)
	}
	if !collector.active.Load() {
		return 0
	}
	return collector.generation
}

func (collector *queryStatisticsCollector) record(generation uint64, query string, started time.Time, duration time.Duration, success bool) {
	if collector == nil || generation == 0 || !success {
		return
	}
	collector.mu.Lock()
	defer collector.mu.Unlock()
	if generation != collector.generation {
		return
	}
	if collector.queries == nil {
		collector.queries = make(map[string]*queryStatisticsRecord)
	}
	if _, exists := collector.queries[query]; !exists {
		if len(collector.order) == 1000 {
			delete(collector.queries, collector.order[0])
			collector.order[0] = ""
			collector.order = collector.order[1:]
		}
		collector.order = append(collector.order, query)
		collector.queries[query] = &queryStatisticsRecord{}
	}
	record := collector.queries[query]
	elapsed := duration.Microseconds()
	record.count++
	record.total += elapsed
	if record.count == 1 || elapsed < record.minimum {
		record.minimum = elapsed
	}
	if elapsed > record.maximum {
		record.maximum = elapsed
	}
	invocations := record.invocations
	if len(invocations) == 100 {
		invocations = invocations[1:]
	}
	record.invocations = append(invocations, queryStatisticsInvocation{elapsedUs: elapsed, startMillis: started.UnixMilli()})
}

func (e *StorageExecutor) callQueryStatistics(ctx context.Context, action string, arguments []interface{}) (*ExecuteResult, error) {
	collector := e.queryStatistics
	if collector == nil {
		return nil, newSemanticError("Neo.ClientError.Procedure.ProcedureCallFailed", "StatisticsUnavailable", "query statistics collector is unavailable")
	}
	section := "QUERIES"
	if len(arguments) > 0 {
		var valid bool
		section, valid = arguments[0].(string)
		if !valid {
			return nil, newSemanticError("Neo.ClientError.Statement.TypeError", "InvalidArgumentType", "statistics section must be a STRING")
		}
		section = strings.ToUpper(section)
	}
	if section == "ALL" && action != "retrieve" {
		section = "QUERIES"
	}
	configuration := map[string]interface{}{}
	if len(arguments) > 1 {
		var valid bool
		configuration, valid = toStringAnyMap(arguments[1])
		if expression, raw := arguments[1].(string); raw {
			configuration, valid = toStringAnyMap(e.evaluateExpressionWithContext(ctx, expression, nil, nil))
		}
		if !valid {
			return nil, newSemanticError("Neo.ClientError.Statement.TypeError", "InvalidArgumentType", "statistics configuration must be a MAP")
		}
	}
	if section != "QUERIES" {
		if action == "retrieve" && (section == "GRAPH COUNTS" || section == "TOKENS" || section == "META" || section == "ALL") {
			return e.retrieveGraphStatistics(ctx, section)
		}
		message := fmt.Sprintf("Unknown section '%s', known sections are [GRAPH COUNTS, TOKENS, QUERIES]", section)
		if section == "GRAPH COUNTS" || section == "TOKENS" {
			message = fmt.Sprintf("Section '%s' does not have to be explicitly collected, it can always be directly retrieved.", section)
		}
		return nil, newSemanticError("Neo.ClientError.General.InvalidArguments", "InvalidArgument", message)
	}
	collector.mu.Lock()
	defer collector.mu.Unlock()
	if !collector.deadline.IsZero() && !time.Now().Before(collector.deadline) {
		collector.active.Store(false)
	}
	result := &ExecuteResult{Columns: []string{"section", "success", "message"}, Rows: [][]interface{}{}}
	switch action {
	case "collect":
		durationSeconds := int64(-1)
		if value, exists := configuration["durationSeconds"]; exists {
			if !isIntegerProcedureValue(value) || toInt64(value) < -1 || toInt64(value) > int64((1<<63-1)/time.Second) {
				return nil, newSemanticError("Neo.ClientError.General.InvalidArguments", "InvalidArgument", "durationSeconds must be an INTEGER >= -1")
			}
			durationSeconds = toInt64(value)
		}
		if collector.active.Load() {
			result.Rows = [][]interface{}{{section, true, "Collection is already ongoing."}}
			return result, nil
		}
		collector.generation++
		collector.deadline = time.Time{}
		if durationSeconds > 0 {
			collector.deadline = time.Now().Add(time.Duration(durationSeconds) * time.Second)
		}
		collector.active.Store(true)
		result.Rows = [][]interface{}{{section, true, "Collection started."}}
	case "stop":
		collector.active.Store(false)
		result.Rows = [][]interface{}{{section, true, "Collection stopped."}}
	case "clear":
		if collector.active.Load() {
			result.Rows = [][]interface{}{{section, false, "Collected data cannot be cleared while collecting."}}
			return result, nil
		}
		collector.generation++
		collector.queries = nil
		collector.order = nil
		result.Rows = [][]interface{}{{section, true, "Data cleared."}}
	case "status":
		status := "idle"
		if collector.active.Load() {
			status = "collecting"
		}
		result.Columns = []string{"section", "status", "data"}
		result.Rows = [][]interface{}{{section, status, map[string]interface{}{}}}
	case "retrieve":
		maximum := int64(100)
		if value, exists := configuration["maxInvocations"]; exists {
			if !isIntegerProcedureValue(value) || toInt64(value) < 0 {
				return nil, newSemanticError("Neo.ClientError.General.InvalidArguments", "InvalidArgument", "maxInvocations must be a nonnegative INTEGER")
			}
			maximum = toInt64(value)
		}
		result.Columns = []string{"section", "data"}
		for _, query := range collector.order {
			record := collector.queries[query]
			invocations := record.invocations
			copies := make([]interface{}, 0)
			for _, invocation := range invocations {
				if int64(len(copies)) < maximum {
					copies = append(copies, map[string]interface{}{
						"elapsedCompileTimeInUs":   nil,
						"elapsedExecutionTimeInUs": invocation.elapsedUs,
						"startTimestampMillis":     invocation.startMillis,
					})
				}
			}
			result.Rows = append(result.Rows, []interface{}{section, map[string]interface{}{
				// Keep the original collector key for accounting, but publish
				// diagnostic text through the same literal policy as query logs.
				"query":              e.redactForLog(ctx, query),
				"queryExecutionPlan": nil,
				"estimatedRows":      nil,
				"invocations":        copies,
				"invocationSummary": map[string]interface{}{
					"invocationCount":   record.count,
					"compileTimeInUs":   nil,
					"executionTimeInUs": map[string]interface{}{"min": record.minimum, "max": record.maximum, "avg": record.total / record.count},
				},
			}})
		}
	}
	return result, nil
}

func (e *StorageExecutor) retrieveGraphStatistics(ctx context.Context, section string) (*ExecuteResult, error) {
	store := e.getStorage(ctx)
	nodes, err := store.AllNodes()
	if err != nil {
		return nil, err
	}
	edges, err := store.AllEdges()
	if err != nil {
		return nil, err
	}
	labels, relationships, properties := map[string]bool{}, map[string]bool{}, map[string]bool{}
	labelCounts, typeCounts := map[string]int64{}, map[string]int64{}
	for _, node := range nodes {
		for _, label := range node.Labels {
			labels[label] = true
			labelCounts[label]++
		}
		for key := range node.Properties {
			properties[key] = true
		}
	}
	for _, edge := range edges {
		relationships[edge.Type] = true
		typeCounts[edge.Type]++
		for key := range edge.Properties {
			properties[key] = true
		}
	}
	orderedLabels := store.GetSchema().OrderTokens(collection.SortedKeys(labels), false)
	orderedRelationships := store.GetSchema().OrderTokens(collection.SortedKeys(relationships), true)
	tokens := map[string]interface{}{"labels": orderedLabels, "relationshipTypes": orderedRelationships, "propertyKeys": collection.SortedKeys(properties)}
	result := &ExecuteResult{Columns: legacyProcedureColumns("db.stats.retrieveAllAnTheStats"), Rows: [][]interface{}{}}
	if section == "GRAPH COUNTS" || section == "ALL" {
		nodeRows := []interface{}{map[string]interface{}{"count": int64(len(nodes))}}
		for _, label := range orderedLabels {
			nodeRows = append(nodeRows, map[string]interface{}{"label": label, "count": labelCounts[label]})
		}
		edgeRows := []interface{}{map[string]interface{}{"count": int64(len(edges))}}
		for _, relationship := range orderedRelationships {
			edgeRows = append(edgeRows, map[string]interface{}{"relationshipType": relationship, "count": typeCounts[relationship]})
		}
		scoped := e.cloneWithStorage(store)
		constraints, err := scoped.executeShowConstraints(ctx, "SHOW CONSTRAINTS YIELD *")
		if err != nil {
			return nil, err
		}
		constraintRows := make([]interface{}, 0, len(constraints.Rows))
		for _, row := range constraints.Rows {
			values := make(map[string]interface{}, len(constraints.Columns))
			for index, column := range constraints.Columns {
				values[column] = row[index]
			}
			constraintRows = append(constraintRows, values)
		}
		result.Rows = append(result.Rows, []interface{}{"GRAPH COUNTS", map[string]interface{}{"nodes": nodeRows, "relationships": edgeRows, "indexes": store.GetSchema().GetIndexes(), "constraints": constraintRows, "nodeCount": int64(len(nodes)), "relationshipCount": int64(len(edges))}})
	}
	if section == "TOKENS" || section == "ALL" {
		result.Rows = append(result.Rows, []interface{}{"TOKENS", tokens})
	}
	if section == "META" || section == "ALL" {
		result.Rows = append(result.Rows, []interface{}{"META", map[string]interface{}{
			"labelCount": int64(len(labels)), "relationshipTypeCount": int64(len(relationships)), "propertyKeyCount": int64(len(properties)),
			"retrieveTime": time.Now().UTC(), "graphToken": nil,
			"system": map[string]interface{}{"runtime": runtime.Version(), "osName": runtime.GOOS, "osArch": runtime.GOARCH, "availableProcessors": int64(runtime.NumCPU())},
		}})
	}
	if section == "ALL" {
		queries, err := e.callQueryStatistics(ctx, "retrieve", []interface{}{"QUERIES"})
		if err != nil {
			return nil, err
		}
		result.Rows = append(result.Rows, queries.Rows...)
	}
	return result, nil
}

package cypher

import (
	"context"
	"github.com/orneryd/nornicdb/internal/collection"
	"slices"
	"strconv"
	"strings"

	"github.com/orneryd/nornicdb/pkg/storage"
)

func (e *StorageExecutor) callDbSchemaVisualizationWithContext(ctx context.Context) (*ExecuteResult, error) {
	store := e.getStorage(ctx)
	nodes, err := store.AllNodes()
	if err != nil {
		return nil, err
	}
	edges, err := store.AllEdges()
	if err != nil {
		return nil, err
	}
	labels := make(map[string]bool)
	nodesByID := make(map[string]*storage.Node, len(nodes))
	for _, node := range nodes {
		nodesByID[node.IdentityKey()] = node
		for _, label := range node.Labels {
			labels[label] = true
		}
	}
	virtualNodes := make([]*storage.Node, 0, len(labels))
	virtualByLabel := make(map[string]*storage.Node, len(labels))
	for _, label := range collection.SortedKeys(labels) {
		indexes, constraints := schemaVisualizationLabelMetadata(store.GetSchema(), label)
		node := &storage.Node{
			Database:   e.executionDatabaseName(ctx),
			ID:         storage.NodeID("-" + strconv.Itoa(len(virtualNodes)+1)),
			Labels:     []string{label},
			Properties: map[string]interface{}{"name": label, "indexes": indexes, "constraints": constraints},
		}
		virtualNodes = append(virtualNodes, node)
		virtualByLabel[label] = node
	}
	startLabels := make(map[string]map[string]bool)
	endLabels := make(map[string]map[string]bool)
	types := make(map[string]bool)
	for _, edge := range edges {
		types[edge.Type] = true
		if startLabels[edge.Type] == nil {
			startLabels[edge.Type] = make(map[string]bool)
			endLabels[edge.Type] = make(map[string]bool)
		}
		if node := nodesByID[storage.EntityIdentityKey(edge.Database, string(edge.StartNode))]; node != nil {
			for _, label := range node.Labels {
				startLabels[edge.Type][label] = true
			}
		}
		if node := nodesByID[storage.EntityIdentityKey(edge.Database, string(edge.EndNode))]; node != nil {
			for _, label := range node.Labels {
				endLabels[edge.Type][label] = true
			}
		}
	}
	virtualEdges := make([]*storage.Edge, 0)
	for _, relationshipType := range collection.SortedKeys(types) {
		for _, start := range collection.SortedKeys(startLabels[relationshipType]) {
			for _, end := range collection.SortedKeys(endLabels[relationshipType]) {
				virtualEdges = append(virtualEdges, &storage.Edge{
					Database:   e.executionDatabaseName(ctx),
					ID:         storage.EdgeID("-" + strconv.Itoa(len(virtualNodes)+len(virtualEdges)+1)),
					StartNode:  virtualByLabel[start].ID,
					EndNode:    virtualByLabel[end].ID,
					Type:       relationshipType,
					Properties: map[string]interface{}{"name": relationshipType},
				})
			}
		}
	}
	return &ExecuteResult{
		Columns: []string{"nodes", "relationships"},
		Rows:    [][]interface{}{{virtualNodes, virtualEdges}},
	}, nil
}

func schemaVisualizationLabelMetadata(schema *storage.SchemaManager, label string) ([]string, []string) {
	indexes := []string{}
	constraints := []string{}
	ownedIndexes := make(map[string]bool)
	for _, constraint := range schema.GetConstraintsForLabels([]string{label}) {
		if constraint.EffectiveEntityType() != storage.ConstraintEntityNode {
			continue
		}
		if statement, ok := showConstraintCreateStatement(constraint).(string); ok {
			constraints = append(constraints, statement)
		}
		ownedIndexes[constraint.OwnedIndex] = true
	}
	for _, raw := range schema.GetIndexes() {
		index, ok := raw.(map[string]interface{})
		if !ok || index["entityType"] == string(storage.ConstraintEntityRelationship) {
			continue
		}
		name, _ := index["name"].(string)
		if ownedIndexes[name] {
			continue
		}
		labels, _ := index["labels"].([]string)
		if index["label"] != label && !slices.Contains(labels, label) {
			continue
		}
		properties, _ := index["properties"].([]string)
		if property, ok := index["property"].(string); ok {
			properties = []string{property}
		}
		if len(properties) > 0 {
			indexes = append(indexes, strings.Join(properties, ","))
		}
	}
	slices.Sort(indexes)
	slices.Sort(constraints)
	return indexes, constraints
}

package cypher

import (
	"context"
	"fmt"
	valueconvert "github.com/orneryd/nornicdb/pkg/convert"
	"reflect"
	"strings"
	"time"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// ========================================
// Temporal Helper Procedures
// ========================================

// callDbTemporalAssertNoOverlap implements db.temporal.assertNoOverlap
// Syntax:
//
//	CALL db.temporal.assertNoOverlap(label, keyProp, validFromProp, validToProp, keyValue, newValidFrom, newValidTo [, systemTime [, systemSequence]])
//
// This returns ok=true if no overlaps are detected, otherwise returns an error.
// newValidTo can be null to indicate an open-ended interval.
//
// args are the call's evaluated arguments, so a bound is any temporal value
// (datetime(), date(), localdatetime()), an ISO string, Unix seconds, a
// parameter or an expression, read as the TEMPORAL NO OVERLAP constraint
// reads it.
//
// The registry checks the argument count (7 to 9) before the call.
func (e *StorageExecutor) callDbTemporalAssertNoOverlap(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	label, err := coerceStringArg(args[0], "label")
	if err != nil {
		return nil, err
	}
	keyProp, err := coerceStringArg(args[1], "keyProp")
	if err != nil {
		return nil, err
	}
	validFromProp, err := coerceStringArg(args[2], "validFromProp")
	if err != nil {
		return nil, err
	}
	validToProp, err := coerceStringArg(args[3], "validToProp")
	if err != nil {
		return nil, err
	}

	keyValue := args[4]
	newStart, ok := storage.CoerceTemporalTime(args[5])
	if !ok {
		return nil, localizedError(localization.CypherSpecializedCallsDateTimeRequired("newValidFrom"), nil)
	}
	newEnd, newHasEnd := coerceDateTimeOptional(args[6])
	snapshotVersion, hasSnapshot, err := coerceOptionalMVCCVersion(args[7:])
	if err != nil {
		return nil, err
	}

	nodes, err := temporalNodesByLabel(e.storage, label, snapshotVersion, hasSnapshot)
	if err != nil {
		return nil, localizedError(localization.CypherSpecializedCallsTemporalReadNodesFailed(label, err), err)
	}

	for _, node := range nodes {
		if node == nil {
			continue
		}
		if !valuesEqual(node.Properties[keyProp], keyValue) {
			continue
		}

		existingStart, ok := storage.CoerceTemporalTime(node.Properties[validFromProp])
		if !ok {
			continue
		}
		existingEnd, existingHasEnd := coerceDateTimeOptional(node.Properties[validToProp])

		if storage.TemporalIntervalsOverlap(newStart, newEnd, newHasEnd, existingStart, existingEnd, existingHasEnd) {
			return nil, localizedError(localization.CypherSpecializedCallsTemporalOverlap(keyProp, keyValue), nil)
		}
	}

	return &ExecuteResult{
		Columns: []string{"ok"},
		Rows:    [][]interface{}{{true}},
	}, nil
}

// callDbTemporalAsOf implements db.temporal.asOf
// Syntax:
//
//	CALL db.temporal.asOf(label, keyProp, keyValue, validFromProp, validToProp, asOf [, systemTime [, systemSequence]]) YIELD node
//
// Returns the most recent node whose [valid_from, valid_to) covers asOf.
//
// args are the call's evaluated arguments: asOf and the stored bounds are
// read as the TEMPORAL NO OVERLAP constraint reads them
// (storage.CoerceTemporalTime), so datetime(), date() and localdatetime()
// values match as ISO strings do.
//
// The registry checks the argument count (6 to 8) before the call.
func (e *StorageExecutor) callDbTemporalAsOf(ctx context.Context, args []interface{}) (*ExecuteResult, error) {
	label, err := coerceStringArg(args[0], "label")
	if err != nil {
		return nil, err
	}
	keyProp, err := coerceStringArg(args[1], "keyProp")
	if err != nil {
		return nil, err
	}
	keyValue := args[2]
	validFromProp, err := coerceStringArg(args[3], "validFromProp")
	if err != nil {
		return nil, err
	}
	validToProp, err := coerceStringArg(args[4], "validToProp")
	if err != nil {
		return nil, err
	}
	asOf, ok := storage.CoerceTemporalTime(args[5])
	if !ok {
		return nil, localizedError(localization.CypherSpecializedCallsDateTimeRequired("asOf"), nil)
	}
	snapshotVersion, hasSnapshot, err := coerceOptionalMVCCVersion(args[6:])
	if err != nil {
		return nil, err
	}

	if temporalLookup, ok := e.storage.(storage.TemporalLookupEngine); ok && !hasSnapshot {
		node, err := temporalLookup.GetTemporalNodeAsOf(label, keyProp, keyValue, validFromProp, validToProp, asOf)
		if err != nil {
			return nil, localizedError(localization.CypherSpecializedCallsTemporalLookupFailed(label, err), err)
		}
		if node != nil {
			return &ExecuteResult{
				Columns: []string{"node"},
				Rows:    [][]interface{}{{node}},
			}, nil
		}
	}

	nodes, err := temporalNodesByLabel(e.storage, label, snapshotVersion, hasSnapshot)
	if err != nil {
		return nil, localizedError(localization.CypherSpecializedCallsTemporalReadNodesFailed(label, err), err)
	}

	var bestNode interface{}
	var bestStart time.Time
	for _, node := range nodes {
		if node == nil {
			continue
		}
		if !valuesEqual(node.Properties[keyProp], keyValue) {
			continue
		}

		start, ok := storage.CoerceTemporalTime(node.Properties[validFromProp])
		if !ok {
			continue
		}
		end, hasEnd := coerceDateTimeOptional(node.Properties[validToProp])

		if asOf.Before(start) {
			continue
		}
		if hasEnd && !asOf.Before(end) {
			continue
		}

		if bestNode == nil || start.After(bestStart) {
			bestNode = node
			bestStart = start
		}
	}

	if bestNode == nil {
		return &ExecuteResult{
			Columns: []string{"node"},
			Rows:    [][]interface{}{},
		}, nil
	}

	return &ExecuteResult{
		Columns: []string{"node"},
		Rows:    [][]interface{}{{bestNode}},
	}, nil
}

func coerceStringArg(val interface{}, name string) (string, error) {
	if val == nil {
		return "", localizedError(localization.CypherSpecializedCallsArgumentRequired(name), nil)
	}
	switch v := val.(type) {
	case string:
		if strings.TrimSpace(v) == "" {
			return "", localizedError(localization.CypherSpecializedCallsArgumentEmpty(name), nil)
		}
		return v, nil
	default:
		return fmt.Sprint(val), nil
	}
}

func coerceDateTimeOptional(val interface{}) (time.Time, bool) {
	if val == nil {
		return time.Time{}, false
	}
	return storage.CoerceTemporalTime(val)
}

func coerceOptionalMVCCVersion(args []interface{}) (storage.MVCCVersion, bool, error) {
	if len(args) == 0 {
		return storage.MVCCVersion{}, false, nil
	}
	commitTime, ok := storage.CoerceTemporalTime(args[0])
	if !ok {
		return storage.MVCCVersion{}, false, localizedError(localization.CypherSpecializedCallsDateTimeRequired("systemTime"), nil)
	}
	version := storage.MVCCVersion{CommitTimestamp: commitTime.UTC(), CommitSequence: ^uint64(0)}
	if len(args) > 1 {
		seq, err := coerceUint64Arg(args[1], "systemSequence")
		if err != nil {
			return storage.MVCCVersion{}, false, err
		}
		version.CommitSequence = seq
	}
	return version, true, nil
}

func coerceUint64Arg(val interface{}, name string) (uint64, error) {
	if unsigned, ok := valueconvert.ToUint64(val, valueconvert.IntegerFloat|valueconvert.IntegerWholeFloat|valueconvert.IntegerStrings|valueconvert.IntegerTrimStrings); ok {
		return unsigned, nil
	}
	if number, numeric := valueconvert.ReadNumber(val); numeric {
		if number.Kind() == valueconvert.FloatNumber {
			return 0, localizedError(localization.CypherSpecializedCallsUnsignedWholeNonNegative(name), nil)
		}
		if signed, ok := number.Signed(); ok && signed < 0 {
			return 0, localizedError(localization.CypherSpecializedCallsUnsignedNonNegative(name), nil)
		}
	}
	return 0, localizedError(localization.CypherSpecializedCallsUnsignedValid(name), nil)
}

func temporalNodesByLabel(engine storage.Engine, label string, version storage.MVCCVersion, hasSnapshot bool) ([]*storage.Node, error) {
	if !hasSnapshot {
		return engine.GetNodesByLabel(label)
	}
	if provider, ok := engine.(storage.MVCCIndexedVisibilityEngine); ok {
		return provider.GetNodesByLabelVisibleAt(label, version)
	}
	return nil, storage.ErrNotImplemented
}

func valuesEqual(a, b interface{}) bool {
	if reflect.DeepEqual(a, b) {
		return true
	}
	return fmt.Sprint(a) == fmt.Sprint(b)
}

package cypher

import (
	"context"
	"strings"

	"github.com/orneryd/nornicdb/pkg/storage"
)

// Counts answered from the store's counters: the one owner of the shapes
// Neo4j answers from its count store (NodeCountFromCountStore,
// RelationshipCountFromCountStore). count(*) or count(<variable>) over
//   - one node pattern with one label and no property map, or
//   - one fixed-length relationship pattern with no property map, at most
//     one labelled endpoint (one label), a type when an endpoint is labelled,
//     and no repeated endpoint variable.
//
// The routes that recognise a plain count (the pipeline's simple read plans,
// the traversal route) check only what their parse knows (no WHERE, no path
// variable, one RETURN item) and call nodeCountFromStore or
// relationshipCountFromStore; ok=false sends the statement to the general
// path (#1076).

// countStoreDescribesReads reports whether the counters count what a read
// sees: not with decay filtering, which hides entities the counters include,
// nor in a temporal viewport, which reads another version.
func countStoreDescribesReads(ctx context.Context, store storage.Engine) bool {
	if storageHasDecayFiltering(store) {
		return false
	}
	if viewport, ok := TemporalViewportFromContext(ctx); ok && viewport.Enabled() {
		return false
	}
	return true
}

// countsRows reports whether item is count(*) or count(<one of variables>),
// which count the pattern's rows: none of the variables is null in a MATCH.
func countsRows(item returnItem, variables ...string) bool {
	if !isAggregateFuncName(item.expr, "count") {
		return false
	}
	inner := strings.TrimSpace(extractFuncInner(item.expr))
	if inner == "*" {
		return true
	}
	for _, variable := range variables {
		if variable != "" && inner == variable {
			return true
		}
	}
	return false
}

// nodeCountFromStore answers count over a one-label node pattern from the
// label counter.
func (e *StorageExecutor) nodeCountFromStore(ctx context.Context, node nodePatternInfo, item returnItem) (int64, bool, error) {
	if len(node.labels) != 1 || len(node.properties) > 0 || !countsRows(item, node.variable) {
		return 0, false, nil
	}
	store := e.getStorage(ctx)
	if !countStoreDescribesReads(ctx, store) {
		return 0, false, nil
	}
	counter, ok := store.(interface{ NodeCountByLabel(string) (int64, error) })
	if !ok {
		return 0, false, nil
	}
	count, err := counter.NodeCountByLabel(node.labels[0])
	return count, true, err
}

// relationshipCountFromStore answers count over a single relationship
// pattern from the relationship counters: the total, the per-type counters,
// or, with one labelled endpoint, the positional (label, type) counters.
func (e *StorageExecutor) relationshipCountFromStore(ctx context.Context, matches *TraversalMatch, item returnItem) (int64, bool, error) {
	if matches == nil || matches.IsChained || matches.PathVariable != "" ||
		matches.Relationship.MinHops != 1 || matches.Relationship.MaxHops != 1 ||
		len(matches.Relationship.Properties) > 0 ||
		len(matches.StartNode.properties) > 0 || len(matches.EndNode.properties) > 0 ||
		!countsRows(item, matches.Relationship.Variable) {
		return 0, false, nil
	}
	// A repeated endpoint variable requires self-loops only, which the
	// counters can't express.
	if matches.StartNode.variable != "" && matches.StartNode.variable == matches.EndNode.variable {
		return 0, false, nil
	}
	start, end := matches.StartNode.labels, matches.EndNode.labels
	// A counter holds one label: two labelled endpoints, or an endpoint with
	// two labels, would count the relationships of one label whatever the
	// other (#1076).
	if len(start) > 1 || len(end) > 1 || (len(start) > 0 && len(end) > 0) {
		return 0, false, nil
	}
	store := e.getStorage(ctx)
	if !countStoreDescribesReads(ctx, store) {
		return 0, false, nil
	}
	types := matches.Relationship.Types
	direction := matches.Relationship.Direction

	if len(start) > 0 || len(end) > 0 {
		if direction == "both" || len(types) == 0 {
			return 0, false, nil
		}
		// The labelled endpoint is the relationship's start node when it is
		// the source of an outgoing pattern or the target of an incoming one.
		label, startTier := "", false
		switch {
		case len(start) == 1:
			label, startTier = start[0], direction == "outgoing"
		default:
			label, startTier = end[0], direction == "incoming"
		}
		var total int64
		for _, edgeType := range types {
			var n int64
			var err error
			if startTier {
				n, err = store.EdgeCountByStartLabel(label, edgeType)
			} else {
				n, err = store.EdgeCountByEndLabel(label, edgeType)
			}
			if err != nil {
				return 0, true, err
			}
			total += n
		}
		return total, true, nil
	}

	if direction == "both" {
		return countUndirectedRelationshipMatches(store, types)
	}
	if len(types) == 0 {
		n, err := store.EdgeCount()
		return n, true, err
	}
	// Every engine keeps a per-type counter (#638): typed counts are point
	// reads.
	var total int64
	for _, edgeType := range types {
		n, err := store.EdgeCountByType(edgeType)
		if err != nil {
			return 0, true, err
		}
		total += n
	}
	return total, true, nil
}

// countUndirectedRelationshipMatches is an undirected pattern's cardinality,
// not the number of relationships: a relationship matches once from each
// endpoint, a self-loop once.
func countUndirectedRelationshipMatches(store storage.Engine, types []string) (int64, bool, error) {
	var candidates []*storage.Edge
	if len(types) == 0 {
		edges, err := store.AllEdges()
		if err != nil {
			return 0, true, err
		}
		candidates = edges
	} else {
		seen := make(map[storage.EntityIdentity]struct{})
		for _, relationshipType := range types {
			edges, err := store.GetEdgesByType(relationshipType)
			if err != nil {
				return 0, true, err
			}
			for _, edge := range edges {
				if edge == nil {
					continue
				}
				if _, exists := seen[edge.Identity()]; exists {
					continue
				}
				seen[edge.Identity()] = struct{}{}
				candidates = append(candidates, edge)
			}
		}
	}
	var count int64
	for _, edge := range candidates {
		if edge == nil {
			continue
		}
		count++
		if edge.StartNode != edge.EndNode {
			count++
		}
	}
	return count, true, nil
}

// CREATE clause implementation for NornicDB.
// This file contains CREATE execution for nodes and relationships.

package cypher

import (
	"context"
	"strings"
	"sync"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
	"github.com/orneryd/nornicdb/pkg/util"
)

// createOutcome is what one CREATE pattern produced.
type createOutcome struct {
	result    *ExecuteResult
	nodes     map[string]*storage.Node
	edges     map[string]*storage.Edge
	paths     map[string]PathResult
	cypher    string // the statement after parameter substitution
	returnIdx int    // index of RETURN in cypher, or -1
}

// createPlan is what one CREATE clause writes: every node and relationship,
// fully parsed, evaluated and validated, in creation order.
type createPlan struct {
	nodes        []*storage.Node
	edges        []*storage.Edge
	nodeBindings map[string]*storage.Node
	edgeBindings map[string]*storage.Edge
}

// createPlanPool recycles plans so planning a CREATE allocates nothing in
// steady state. Storage bulk writes don't retain the slices they are given.
var createPlanPool = sync.Pool{New: func() any { return &createPlan{} }}

func acquireCreatePlan() *createPlan {
	return createPlanPool.Get().(*createPlan)
}

// release clears the plan's references and returns it to the pool; plans
// that grew unusually large are dropped instead of being kept alive.
func (p *createPlan) release() {
	if cap(p.nodes) > 256 || cap(p.edges) > 256 || len(p.nodeBindings) > 64 || len(p.edgeBindings) > 64 {
		return
	}
	clear(p.nodes[:cap(p.nodes)])
	clear(p.edges[:cap(p.edges)])
	clear(p.nodeBindings)
	clear(p.edgeBindings)
	p.nodes = p.nodes[:0]
	p.edges = p.edges[:0]
	createPlanPool.Put(p)
}

// createPatternsInScope is the single CREATE executor for pattern text (the
// part after CREATE, comma-separated patterns). nodes and edges hold the
// variables already in scope (from MATCH, WITH, UNWIND or an earlier CREATE);
// relationship endpoints that name a bound variable reuse it, and every
// created node / relationship is bound into them. Nodes - standalone and
// inline endpoints - go through planCreateNode, so every route validates
// labels and properties and resolves property references the same way. Stats
// go to result. It returns the named paths (p = ...).
//
// The clause is planned completely (planCreatePatterns) before anything is
// written: a property expression that fails (1 / 0, recorded in ctx), a
// rejected property value or pattern anywhere in the clause returns the error
// with nothing written. The plan is then written by applyCreatePlan with one
// bulk node write and one bulk relationship write, so a storage-level
// rejection (a unique constraint) also writes nothing. This keeps CREATE
// atomic on routes that write without a transaction (the async auto-commit
// route, #628) as well as inside one.
func (e *StorageExecutor) pipelineCreateSource(ctx context.Context, source pipelineRowSource, clauses []pipelineClause) ([]pipelineRow, *ExecuteResult, bool, error) {
	plan := acquireCreatePlan()
	defer plan.release()
	var out []pipelineRow
	var planningError error
	completed := source(func(row pipelineRow) bool {
		if planningError = ctx.Err(); planningError != nil {
			return false
		}
		clear(plan.nodeBindings)
		clear(plan.edgeBindings)
		var newRow pipelineRow
		newRow, planningError = e.pipelinePlanCreateRow(ctx, row, clauses, plan)
		if planningError != nil {
			return false
		}
		out = append(out, newRow)
		return true
	})
	if failure := getExpressionFailure(ctx); failure != nil {
		return nil, nil, true, failure
	}
	if planningError != nil {
		return nil, nil, true, planningError
	}
	if !completed {
		return nil, nil, false, nil
	}
	if err := ctx.Err(); err != nil {
		return nil, nil, true, err
	}
	created := &ExecuteResult{Stats: &QueryStats{}}
	if err := e.applyCreatePlan(ctx, plan, created); err != nil {
		return nil, nil, true, localizedError(localization.CypherInvariantsPipelineCreateFailed(err), err)
	}
	// The batch is one atomic apply: a cancellation that lands while it
	// writes cannot roll it back, but the statement still reports the
	// cancellation so the client knows the outcome is uncertain.
	if err := ctx.Err(); err != nil {
		return nil, nil, true, err
	}
	return out, created, true, nil
}

// planCreatePatterns plans one CREATE clause into plan without writing:
// every node and relationship is parsed, evaluated and validated, and bound
// into createdNodes / createdEdges for later patterns and clauses. Adjacent
// pipeline CREATE clauses share one plan and are published atomically.
func (e *StorageExecutor) planCreatePatterns(ctx context.Context, pattern string, createdNodes map[string]*storage.Node, createdEdges map[string]*storage.Edge, plan *createPlan, publication ...*ExecuteResult) (map[string]PathResult, error) {
	if plan == nil {
		plan = acquireCreatePlan()
		defer plan.release()
	}
	for _, fragment := range splitTopLevelComma(pattern) {
		_, body := parseCreatePathAssignment(strings.TrimSpace(fragment))
		if !strings.HasPrefix(body, "(") || !strings.HasSuffix(strings.TrimSpace(body), ")") {
			return nil, newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "Invalid CREATE pattern")
		}
	}
	patterns := e.createPatternSplitFor(pattern)

	// First, create all nodes
	var createdPaths map[string]PathResult
	for _, nodePatternStr := range patterns.nodes {
		nodePatternStr = strings.TrimSpace(nodePatternStr)
		if nodePatternStr == "" {
			continue
		}
		if _, err := e.planCreateNode(ctx, nodePatternStr, createdNodes, createdEdges, plan); err != nil {
			return nil, err
		}
	}

	// Then, create all relationships using variable references or inline node definitions
	for _, relPatternStr := range patterns.relationships {
		relPatternStr = strings.TrimSpace(relPatternStr)
		if relPatternStr == "" {
			continue
		}

		// Process relationship chains - keep going until no remainder
		pathVar, currentPattern := parseCreatePathAssignment(relPatternStr)
		var pathNodes []*storage.Node
		var pathEdges []*storage.Edge
		var chainedSourceNode *storage.Node
		for currentPattern != "" {
			// Parse the relationship pattern: (varA)-[:TYPE {props}]->(varB)
			sourceContent, relStr, targetContent, isReverse, remainder, err := e.parseCreateRelPatternWithVars(currentPattern)
			if err != nil {
				return nil, err
			}

			// The relationship is parsed and validated before its endpoints
			// are created, so a rejected pattern writes nothing.
			// Parse relationship type and properties
			relType, relProps, err := e.parseRelationshipTypeAndProps(ctx, relStr, entityRow(ctx, createdNodes, createdEdges))
			if err != nil {
				return nil, err
			}

			// The relationship variable ("r:TYPE" -> "r").
			if rest, _, ok := splitPatternParameterMap(relStr); ok {
				relStr = rest
			}
			relVar := relationshipDeclarationOf(relStr).variable

			// CREATE needs exactly one relationship type.
			if relType == "" {
				return nil, localizedError(localization.CypherMergeRelationshipTypeRequired(), nil)
			}

			// Property keys follow the map-key rule (a symbolic name, or a
			// backtick-quoted name holding any character).
			if err := validateCreatePropertyKeys("["+relStr+"]", relProps); err != nil {
				return nil, err
			}

			if err := validatePropertyValues(relProps); err != nil {
				return nil, err
			}

			// Endpoints: a bound variable is reused; anything else is planned
			// through the shared node planner.
			sourceNode := chainedSourceNode
			if sourceNode == nil {
				sourceNode, err = e.planCreateEndpoint(ctx, sourceContent, createdNodes, createdEdges, plan)
				if err != nil {
					return nil, err
				}
			}
			targetNode, err := e.planCreateEndpoint(ctx, targetContent, createdNodes, createdEdges, plan)
			if err != nil {
				return nil, err
			}

			// Handle reverse direction
			startNode, endNode := sourceNode, targetNode
			if isReverse {
				startNode, endNode = targetNode, sourceNode
			}

			// Create relationship
			edge := &storage.Edge{
				ID:         storage.EdgeID(e.generateID()),
				StartNode:  startNode.ID,
				EndNode:    endNode.ID,
				Type:       relType,
				Properties: relProps,
			}
			if err := edge.SetEndpoints(startNode, endNode); err != nil {
				return nil, err
			}
			plan.edges = append(plan.edges, edge)
			if relVar != "" {
				createdEdges[relVar] = edge
			}
			if pathVar != "" {
				if len(pathNodes) == 0 {
					pathNodes = append(pathNodes, startNode)
				}
				pathEdges = append(pathEdges, edge)
				pathNodes = append(pathNodes, endNode)
			}
			// If there's more chain to process, continue with target as new source
			if remainder != "" && (strings.HasPrefix(remainder, "-[") || strings.HasPrefix(remainder, "<-[")) {
				// Build the next pattern: (targetContent) + remainder
				chainedSourceNode = targetNode
				currentPattern = "(" + targetContent + ")" + remainder
			} else {
				currentPattern = ""
			}
		}

		if pathVar != "" {
			if createdPaths == nil {
				createdPaths = make(map[string]PathResult)
			}
			createdPaths[pathVar] = PathResult{
				Nodes:         pathNodes,
				Relationships: pathEdges,
				Length:        len(pathEdges),
			}
		}
	}
	if len(publication) > 0 {
		if err := e.applyCreatePlan(ctx, plan, publication[0]); err != nil {
			return nil, err
		}
	}
	return createdPaths, nil
}

// applyCreatePlan writes a planned CREATE clause. A property expression that
// failed while the clause was planned (recorded in ctx) aborts it before any
// write. Nodes are written before relationships, each set in one bulk call,
// so storage rejects a clause as a whole; stats, optimistic IDs and mutation
// notifications are recorded only for what was written. A set of exactly one
// node or one relationship has nothing to keep together and is written with
// the single create, which every engine implements most directly. When the
// relationships are rejected after the nodes were written, the nodes are
// removed again, so the clause is all-or-nothing without a transaction too.
func (e *StorageExecutor) applyCreatePlan(ctx context.Context, plan *createPlan, result *ExecuteResult) error {
	if failure := getExpressionFailure(ctx); failure != nil {
		return failure
	}
	store := e.getStorage(ctx)
	for _, node := range plan.nodes {
		if node.Database == "" {
			node.Database = storage.DatabaseOf(store)
		}
	}
	for _, edge := range plan.edges {
		if edge.Database == "" {
			edge.Database = storage.DatabaseOf(store)
		}
	}
	// Every ID a create plan writes was minted for it (generateID).
	switch len(plan.nodes) {
	case 0:
	case 1:
		node := plan.nodes[0]
		actualID, err := createMintedNode(store, node)
		if err != nil {
			return localizedError(localization.CypherMutationsCreateNodeFailed(err), err)
		}
		if actualID != "" {
			node.ID = actualID
		}
	default:
		if err := bulkCreateMintedNodes(store, plan.nodes); err != nil {
			return localizedError(localization.CypherMutationsCreateNodeFailed(err), err)
		}
	}
	var edgeErr error
	switch len(plan.edges) {
	case 0:
	case 1:
		edgeErr = createMintedEdge(store, plan.edges[0])
	default:
		edgeErr = bulkCreateMintedEdges(store, plan.edges)
	}
	if edgeErr != nil {
		// The clause's nodes are already written; remove them so the clause
		// leaves nothing behind on a route without a transaction.
		if len(plan.nodes) > 0 {
			ids := make([]storage.NodeID, len(plan.nodes))
			for i, node := range plan.nodes {
				ids[i] = node.ID
			}
			_ = store.BulkDeleteNodes(ids)
		}
		return localizedError(localization.CypherMutationsCreateRelationshipFailed(edgeErr), edgeErr)
	}
	for _, node := range plan.nodes {
		e.notifyNodeMutated(string(node.ID))
		addOptimisticNodeID(result, node.ID)
		countCreatedEntity(result.Stats, node.Labels, node.Properties)
	}
	result.Stats.NodesCreated += len(plan.nodes)
	for _, edge := range plan.edges {
		e.notifyEdgeMutated(string(edge.ID))
		addOptimisticRelationshipID(result, edge.ID)
		countCreatedEntity(result.Stats, nil, edge.Properties)
	}
	result.Stats.RelationshipsCreated += len(plan.edges)
	return nil
}

// planCreateNode plans one node from a CREATE node pattern through
// prepareCreateNodePattern (validation, property references), adds it to plan
// and binds its variable in nodes.
func (e *StorageExecutor) planCreateNode(ctx context.Context, pattern string, nodes map[string]*storage.Node, edges map[string]*storage.Edge, plan *createPlan) (*storage.Node, error) {
	nodePattern, err := e.prepareCreateNodePattern(ctx, pattern, nodes, edges)
	if err != nil {
		return nil, err
	}
	if nodePattern.properties == nil {
		nodePattern.properties = make(map[string]interface{})
	}
	node := &storage.Node{
		ID:         storage.NodeID(e.generateID()),
		Labels:     nodePattern.labels,
		Properties: nodePattern.properties,
	}
	plan.nodes = append(plan.nodes, node)
	if nodePattern.variable != "" {
		nodes[nodePattern.variable] = node
	}
	return node, nil
}

// planCreateEndpoint resolves a relationship endpoint in a CREATE pattern:
// a variable already bound in nodes is reused, anything else is planned with
// planCreateNode.
func (e *StorageExecutor) planCreateEndpoint(ctx context.Context, content string, nodes map[string]*storage.Node, edges map[string]*storage.Edge, plan *createPlan) (*storage.Node, error) {
	content = strings.TrimSpace(content)
	variable := content
	if end := strings.IndexAny(content, ":{ "); end >= 0 {
		variable = strings.TrimSpace(content[:end])
	}
	if node := nodes[variable]; variable != "" && node != nil {
		return node, nil
	}
	if missingRelationshipEndpoint(valueBindingsFromContext(ctx), variable) {
		return nil, relationshipEndpointMissingError(variable)
	}
	return e.planCreateNode(ctx, "("+content+")", nodes, edges, plan)
}

// projectCreateReturn fills out.result with the RETURN row of a CREATE
// statement, if it has one, through the canonical RETURN operator.
func (e *StorageExecutor) projectCreateReturn(ctx context.Context, out *createOutcome) error {
	if out.returnIdx <= 0 {
		return nil
	}
	row := e.mergeBindingRow(ctx, out.nodes, out.edges)
	for name, path := range out.paths {
		row[name] = e.pathToMap(path)
	}
	projected, err := e.projectMergeReturn(ctx, []pipelineRow{row}, out.cypher[out.returnIdx:])
	if err != nil {
		return err
	}
	out.result.Columns = projected.Columns
	out.result.Rows = projected.Rows
	return nil
}

// prepareCreateNodePattern parses and validates one CREATE node pattern. It is
// shared by every CREATE route (createFromPattern and the auto-commit bulk fast
// path executeWithImplicitTransaction) so they reject the same patterns: malformed
// property maps, an empty label after ':', invalid or reserved labels, invalid
// property keys and values. Property values that reference variables created
// earlier in the statement (b {name: a.name}) are resolved against nodes and
// relationships.
func (e *StorageExecutor) prepareCreateNodePattern(ctx context.Context, pattern string, nodes map[string]*storage.Node, relationships map[string]*storage.Edge) (nodePatternInfo, error) {
	var parameterProperties map[string]interface{}
	if head, props := splitNodePatternProperties(pattern); props == "" {
		if rest, parameter, ok := splitPatternParameterMap(head); ok {
			properties, err := createParameterProperties(ctx, parameter)
			if err != nil {
				return nodePatternInfo{}, err
			}
			parameterProperties = properties
			pattern = "(" + strings.TrimSpace(rest) + ")"
		}
	}
	if err := e.validateCreatePatternPropertyMap(ctx, pattern); err != nil {
		return nodePatternInfo{}, err
	}
	head, propertyText := splitNodePatternProperties(pattern)
	variable, labels, labelErr := parseNodeHead(head)
	properties, err := e.materializePropertyMap(ctx, propertyText, entityRow(ctx, nodes, relationships), false, false)
	if err != nil {
		return nodePatternInfo{}, err
	}
	nodePattern := nodePatternInfo{variable: variable, labels: labels, labelErr: labelErr, properties: properties}
	if parameterProperties != nil {
		nodePattern.properties = parameterProperties
	}
	for key, value := range nodePattern.properties {
		if value == nil {
			delete(nodePattern.properties, key)
		}
	}

	// An empty label (e.g. "n:" or ":") - only check before properties.
	head, _ = splitNodePatternProperties(pattern)
	if indexByteOutsideBackticks(head, ':') >= 0 && len(nodePattern.labels) == 0 {
		return nodePatternInfo{}, localizedError(localization.CypherResidualEmptyLabelAfterColon(pattern), nil)
	}
	// SECURITY: labels follow the label rules (quoted labels may hold any
	// character; unquoted labels are identifiers, not reserved words).
	if nodePattern.labelErr != nil {
		return nodePatternInfo{}, nodePattern.labelErr
	}
	// SECURITY: Validate property keys and values. Keys follow the map-key
	// rule (a symbolic name, or a backtick-quoted name holding any
	// character).
	if err := validateCreatePropertyKeys(pattern, nodePattern.properties); err != nil {
		return nodePatternInfo{}, err
	}
	for key, val := range nodePattern.properties {
		if _, ok := val.(invalidPropertyValue); ok {
			return nodePatternInfo{}, localizedError(localization.CypherMutationsInvalidPropertyValue(key), nil)
		}
	}
	if err := validatePropertyValues(nodePattern.properties); err != nil {
		return nodePatternInfo{}, err
	}

	return nodePattern, nil
}

// namedPathAssignmentPrefix reports whether pattern begins a named-path
// assignment, `p = (` (spaces optional).
func namedPathAssignmentPrefix(pattern string) bool {
	i := indexByteOutsideBackticks(pattern, '=')
	if i <= 0 {
		return false
	}
	name := strings.TrimSpace(pattern[:i])
	_, end, ok := scanIdentifierToken(name, 0)
	if !ok || end != len(name) {
		return false
	}
	return strings.TrimSpace(pattern[i+1:]) != ""
}

func (e *StorageExecutor) validateCreatePatternPropertyMap(ctx context.Context, pattern string) error {
	_, props := splitNodePatternProperties(pattern)
	if props == "" {
		return nil
	}
	propsEnd := strings.LastIndex(props, "}")
	if propsEnd < 0 {
		return localizedError(localization.CypherResidualPropertyMapSyntaxInvalid(pattern), nil)
	}
	propsLiteral := strings.TrimSpace(props[:propsEnd+1])
	// Syntax only: the values are parsed by parseNodePattern.
	if err := validateMapLiteralSyntax(propsLiteral); err != nil {
		return localizedError(localization.CypherMutationsInvalidPropertyMapCause(err), err)
	}
	return nil
}

func parseCreatePathAssignment(pattern string) (string, string) {
	if name, _, start, ok := namedPathDeclaration(pattern, 0); ok {
		return name, strings.TrimSpace(pattern[start:])
	}
	return "", pattern
}

// splitCreatePatterns splits a CREATE pattern into individual patterns (nodes and relationships)
// respecting parentheses depth, string literals, and handling relationship syntax.
// IMPORTANT: This properly handles content inside string literals (single/double quotes)
// so that Cypher-like content inside strings is not parsed as relationship patterns.
func (e *StorageExecutor) splitCreatePatterns(pattern string) []string {
	return e.createPatternSplitFor(pattern).all
}

func (e *StorageExecutor) scanCreatePatterns(pattern string) []string {
	var patterns []string
	var current strings.Builder
	depth := 0
	inRelationship := false
	braceDepth := 0

	for i := 0; i < len(pattern); i++ {
		c := pattern[i]

		if isCypherQuoteByte(c) {
			end := skipCypherQuotedText(pattern, i, c)
			current.WriteString(pattern[i:end])
			i = end - 1
			continue
		}
		if c == '/' {
			if end := queryCommentEnd(pattern, i); end >= 0 {
				current.WriteString(pattern[i:end])
				i = end - 1
				continue
			}
		}

		if c == '$' && dynamicLabelStartsAt(pattern, i) {
			// $(e): a dynamic label's or type's expression, not a node.
			if end := findMatchingDelimiter(pattern, i+strings.IndexByte(pattern[i:], '('), '(', ')'); end >= 0 {
				current.WriteString(pattern[i : end+1])
				i = end
				continue
			}
		}

		// Normal parsing outside string literals
		switch c {
		case '{':
			braceDepth++
			current.WriteByte(c)
		case '}':
			if braceDepth > 0 {
				braceDepth--
			}
			current.WriteByte(c)
		case '(':
			if braceDepth == 0 {
				depth++
				current.WriteByte(c)
			} else {
				current.WriteByte(c)
			}
		case ')':
			if braceDepth == 0 {
				depth--
				current.WriteByte(c)
				if depth == 0 {
					// Check if next non-whitespace is a relationship operator
					j := i + 1
					for j < len(pattern) && (pattern[j] == ' ' || pattern[j] == '\t' || pattern[j] == '\n' || pattern[j] == '\r') {
						j++
					}
					if j < len(pattern) && (pattern[j] == '-' || pattern[j] == '<') {
						// This is part of a relationship pattern, continue accumulating
						inRelationship = true
					} else if !inRelationship {
						// End of a standalone node pattern
						patterns = append(patterns, current.String())
						current.Reset()
					} else {
						// End of a relationship pattern
						patterns = append(patterns, current.String())
						current.Reset()
						inRelationship = false
					}
				}
			} else {
				current.WriteByte(c)
			}
		case ',':
			if depth == 0 && !inRelationship {
				// Skip comma between patterns
				continue
			}
			current.WriteByte(c)
		case ' ', '\t', '\n', '\r':
			if depth > 0 || inRelationship {
				// Only keep whitespace inside patterns
				current.WriteByte(c)
			}
		default:
			if depth > 0 || inRelationship || c == '-' || c == '<' || c == '[' || c == ']' || c == '>' || c == ':' {
				current.WriteByte(c)
				if c == '-' || c == '<' {
					inRelationship = true
				}
				continue
			}
			// Preserve path assignment prefixes like "p=(:A)-[:R]->(:B)".
			// We drop whitespace, but keep identifiers and "=" before the first "(".
			if depth == 0 && !inRelationship {
				if isIdentByte(byte(c)) || c == '=' {
					current.WriteByte(c)
				}
			}
		}
	}

	// Handle any remaining content
	if current.Len() > 0 {
		patterns = append(patterns, current.String())
	}

	return patterns
}

// splitNodePatterns splits a CREATE pattern into individual node patterns
// (Used for simple node-only patterns and by other parts of the system)
// isSingleNodePattern reports whether pattern is one node pattern: no
// relationship pattern (containsRelationshipPattern, which skips strings
// and reads bare and spaced arrows) and a single node.
func (e *StorageExecutor) isSingleNodePattern(pattern string) bool {
	return !containsRelationshipPattern(pattern) && len(e.splitNodePatterns(pattern)) == 1
}

func (e *StorageExecutor) splitNodePatterns(pattern string) []string {
	var patterns []string
	var current strings.Builder
	depth := 0
	braceDepth := 0

	for i := 0; i < len(pattern); i++ {
		c := pattern[i]
		if isCypherQuoteByte(c) {
			end := skipCypherQuotedText(pattern, i, c)
			if depth > 0 {
				current.WriteString(pattern[i:end])
			}
			i = end - 1
			continue
		}
		if c == '/' {
			if end := queryCommentEnd(pattern, i); end >= 0 {
				if depth > 0 {
					current.WriteString(pattern[i:end])
				}
				i = end - 1
				continue
			}
		}
		if c == '$' && dynamicLabelStartsAt(pattern, i) {
			// $(e): a dynamic label's or type's expression, not a node.
			if end := findMatchingDelimiter(pattern, i+strings.IndexByte(pattern[i:], '('), '(', ')'); end >= 0 {
				if depth > 0 {
					current.WriteString(pattern[i : end+1])
				}
				i = end
				continue
			}
		}
		switch c {
		case '{':
			if depth > 0 {
				braceDepth++
				current.WriteByte(c)
			}
		case '}':
			if depth > 0 {
				if braceDepth > 0 {
					braceDepth--
				}
				current.WriteByte(c)
			}
		case '(':
			if braceDepth == 0 {
				depth++
				current.WriteByte(c)
			} else {
				current.WriteByte(c)
			}
		case ')':
			if braceDepth == 0 {
				depth--
				current.WriteByte(c)
				if depth == 0 {
					patterns = append(patterns, current.String())
					current.Reset()
				}
			} else {
				current.WriteByte(c)
			}
		case ',':
			if depth == 0 {
				// Skip comma between patterns
				continue
			}
			current.WriteByte(c)
		default:
			if depth > 0 {
				current.WriteByte(c)
			}
		}
	}

	// Handle any remaining content
	if current.Len() > 0 {
		patterns = append(patterns, current.String())
	}

	return patterns
}

// parseRelationshipTypeAndProps parses "r:TYPE {props}", ":`A TYPE` {props}"
// or "r:TYPE $props" into the type (unquoted) and the properties map. A
// pattern with no type ("r", ":") yields an empty type. The type's shape
// (one type, a quoted or identifier name) is checked before, by
// validateSingleRelationshipDeclaration.
func (e *StorageExecutor) parseRelationshipTypeAndProps(ctx context.Context, relStr string, row pipelineRow) (string, map[string]interface{}, error) {
	relStr = strings.TrimSpace(relStr)
	relType := ""
	var relProps map[string]interface{}

	// A property map given as a parameter ([r:R $props]).
	if rest, parameter, ok := splitPatternParameterMap(relStr); ok {
		properties, err := createParameterProperties(ctx, parameter)
		if err != nil {
			return "", nil, err
		}
		relProps, relStr = properties, strings.TrimSpace(rest)
	}

	// The type and property map, read outside backticks: a quoted type
	// may hold any character (relationshipDeclarationOf). No colon ("r")
	// or nothing after it (":") leaves the type empty; the CREATE core
	// rejects a relationship without exactly one type.
	declaration := relationshipDeclarationOf(relStr)
	if declaration.properties != "" {
		if propsEnd := findMatchingDelimiter(declaration.properties, 0, '{', '}'); propsEnd > 0 {
			var err error
			relProps, err = e.materializePropertyMap(ctx, declaration.properties[:propsEnd+1], row, false, false)
			if err != nil {
				return "", nil, err
			}
		}
	}
	relType = declaration.singleType()

	if relProps == nil {
		relProps = make(map[string]interface{})
	}

	return relType, relProps, nil
}

// splitPatternParameterMap splits a node's or a relationship's inside at a
// trailing $name, its property map given as a parameter ((n:L $props),
// [r:R $props], ($props)): rest is the text before it. The $ starts the
// inside or follows whitespace; after a name's character it is part of the
// name, as in Neo4j.
func splitPatternParameterMap(text string) (rest, parameter string, ok bool) {
	trimmed := strings.TrimRight(text, " \t\r\n")
	// The trailing token holds its own $s: $a$b is the parameter a$b.
	start := len(trimmed)
	for start > 0 && isIdentByte(trimmed[start-1]) {
		start--
	}
	if start+1 >= len(trimmed) || trimmed[start] != '$' || start > 0 && !isASCIIWhitespace(trimmed[start-1]) {
		return text, "", false
	}
	return trimmed[:start], trimmed[start:], true
}

// createParameterProperties is the property map a CREATE pattern's $name
// gives: a copy of the parameter's map, or Neo4j's SyntaxError ("Type
// mismatch for parameter 'p': expected Map, Node or Relationship but was
// Integer") when it isn't a map.
func createParameterProperties(ctx context.Context, parameter string) (map[string]interface{}, error) {
	value, resolved := resolveDirectParamRef(ctx, parameter)
	if err := getExpressionFailure(ctx); err != nil {
		return nil, err
	}
	var evalErr error
	value, evalErr = checkedPropertyResult(ctx, parameter, value, resolved, nil)
	if evalErr != nil {
		return nil, evalErr
	}
	if resolved && value == nil {
		return nil, newSemanticError("Neo.ClientError.Statement.TypeError", "InvalidArgumentType", "Expected a map but was Null")
	}
	properties, isMap := toStringAnyMap(value)
	if !resolved || !isMap {
		return nil, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidArgumentType",
			localization.CypherCoreParameterTypeMismatch(parameter[1:], "Map, Node or Relationship", staticParameterOperand(value).display))
	}
	return cloneNodePropertiesMap(properties), nil
}

// findAllKeywordPositions finds all positions of a keyword in the query
func findAllKeywordPositions(cypher string, keyword string) []int {
	var positions []int
	keywordLen := len(keyword)

	for i := 0; i <= len(cypher)-keywordLen; i++ {
		// Check if keyword matches at this position (case insensitive)
		if strings.EqualFold(cypher[i:i+keywordLen], keyword) {
			// Check word boundary before
			if i > 0 {
				prevChar := cypher[i-1]
				if isIdentByte(prevChar) {
					continue // Part of another word
				}
			}
			// Check word boundary after
			if i+keywordLen < len(cypher) {
				nextChar := cypher[i+keywordLen]
				if isIdentByte(nextChar) {
					continue // Part of another word
				}
			}
			positions = append(positions, i)
		}
	}

	// Handle nested MATCH in strings - check if position is inside quotes
	var validPositions []int
	for _, pos := range positions {
		if !isInsideQuotes(cypher, pos) {
			validPositions = append(validPositions, pos)
		}
	}

	return validPositions
}

// isInsideQuotes checks if a position is inside quotes
func isInsideQuotes(s string, pos int) bool {
	for index := 0; index < pos && index < len(s); index++ {
		if !isCypherQuoteByte(s[index]) {
			continue
		}
		end := skipCypherQuotedText(s, index, s[index])
		if end > pos {
			return true
		}
		index = end - 1
	}
	return false
}

// parseCreateRelationshipContent splits a relationship's inside ("r:TYPE
// {k: v}") into its variable, its one type (backtick-quoted ones unquoted,
// relationshipDeclarationOf) and its property map text. A property map
// followed by other text is an error.
func parseCreateRelationshipContent(content string) (relVar string, relType string, relPropsStr string, err error) {
	declaration := relationshipDeclarationOf(content)
	if declaration.properties != "" {
		braceEnd := strings.LastIndex(declaration.properties, "}")
		if braceEnd < 0 || strings.TrimSpace(declaration.properties[braceEnd+1:]) != "" {
			return "", "", "", localizedError(localization.CypherMutationsRelationshipPropertiesInvalid(), nil)
		}
		relPropsStr = declaration.properties
	}
	return declaration.variable, declaration.singleType(), relPropsStr, nil
}

// isSimpleVariable checks if content is just a variable name (alphanumeric + underscore)
func isSimpleVariable(content string) bool {
	if content == "" {
		return false
	}
	for _, r := range content {
		if !isIdentRune(r) {
			return false
		}
	}
	return true
}

// getKeys returns the keys of a map as a slice
func getKeys(m map[string]*storage.Node) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	return keys
}

// resolveSetMergeSourceFromParams resolves identifier or dotted-path map sources from params.
// Supported forms:
//   - row
//   - row.properties
func resolveSetMergeSourceFromParams(params map[string]interface{}, source string) (interface{}, bool) {
	if params == nil {
		return nil, false
	}
	source = strings.TrimSpace(source)
	if source == "" {
		return nil, false
	}
	parts, ok := parseParamPathParts(source)
	if !ok || len(parts) == 0 {
		return nil, false
	}

	current, ok := params[parts[0]]
	if !ok {
		return nil, false
	}
	for _, part := range parts[1:] {
		switch m := current.(type) {
		case map[string]interface{}:
			next, exists := m[part]
			if !exists {
				return nil, false
			}
			current = next
		case map[interface{}]interface{}:
			next, exists := m[part]
			if !exists {
				return nil, false
			}
			current = next
		default:
			return nil, false
		}
	}
	return current, true
}

// parseParamPathParts parses dotted and bracketed map access paths.
// Supported forms:
//   - row
//   - row.props
//   - row['props']
//   - row["props"]
//   - row.meta['inner'].value
func parseParamPathParts(source string) ([]string, bool) {
	source = strings.TrimSpace(source)
	if source == "" {
		return nil, false
	}

	parts := make([]string, 0, 4)
	i := 0
	readIdent := func(start int) (string, int, bool) {
		if start >= len(source) {
			return "", start, false
		}
		ch := source[start]
		if !isIdentStartByte(ch) {
			return "", start, false
		}
		j := start + 1
		for j < len(source) {
			c := source[j]
			if !isIdentByte(c) {
				break
			}
			j++
		}
		return source[start:j], j, true
	}

	root, next, ok := readIdent(i)
	if !ok {
		return nil, false
	}
	parts = append(parts, root)
	i = next

	for i < len(source) {
		switch source[i] {
		case '.':
			i++
			part, j, ok := readIdent(i)
			if !ok {
				return nil, false
			}
			parts = append(parts, part)
			i = j
		case '[':
			i++
			for i < len(source) && isWhitespace(source[i]) {
				i++
			}
			if i >= len(source) {
				return nil, false
			}
			if !isCypherStringQuoteByte(source[i]) {
				return nil, false
			}
			end, closed := scanCypherQuotedText(source, i, source[i])
			if !closed {
				return nil, false
			}
			key, quoted := decodeCypherQuotedString(source[i:end])
			if !quoted {
				return nil, false
			}
			i = end
			for i < len(source) && isWhitespace(source[i]) {
				i++
			}
			if i >= len(source) || source[i] != ']' {
				return nil, false
			}
			i++ // close bracket
			if key == "" {
				return nil, false
			}
			parts = append(parts, key)
		default:
			return nil, false
		}
	}
	return parts, true
}

func (e *StorageExecutor) buildCombinationsUsingWhereJoin(
	patternMatches []struct {
		variable string
		nodes    []*storage.Node
	},
	whereClause string,
) ([]map[string]*storage.Node, bool) {
	if len(patternMatches) < 2 || strings.TrimSpace(whereClause) == "" {
		return nil, false
	}
	varOrder := make([]string, 0, len(patternMatches))
	varToNodes := make(map[string][]*storage.Node, len(patternMatches))
	for _, pm := range patternMatches {
		if pm.variable == "" {
			return nil, false
		}
		if _, exists := varToNodes[pm.variable]; exists {
			return nil, false
		}
		varOrder = append(varOrder, pm.variable)
		varToNodes[pm.variable] = pm.nodes
	}

	eqConstraints := make([]cartesianEqConstraint, 0, 4)
	for _, term := range splitTopLevelAndConjuncts(whereClause) {
		term = strings.TrimSpace(term)
		if term == "" {
			continue
		}
		lv, lp, rv, rp, offset, ok := parseCartesianVarPropEqualityTerm(term)
		if !ok {
			continue
		}
		if _, lok := varToNodes[lv]; !lok {
			continue
		}
		if _, rok := varToNodes[rv]; !rok {
			continue
		}
		eqConstraints = append(eqConstraints, cartesianEqConstraint{
			leftVar:   lv,
			leftProp:  lp,
			rightVar:  rv,
			rightProp: rp,
			offset:    offset,
		})
	}
	if len(eqConstraints) == 0 {
		return nil, false
	}

	parent := make(map[string]string, len(varOrder))
	for _, v := range varOrder {
		parent[v] = v
	}
	var find func(string) string
	find = func(v string) string {
		p := parent[v]
		if p != v {
			parent[v] = find(p)
		}
		return parent[v]
	}
	union := func(a, b string) {
		ra := find(a)
		rb := find(b)
		if ra != rb {
			parent[rb] = ra
		}
	}
	for _, c := range eqConstraints {
		union(c.leftVar, c.rightVar)
	}

	components := make(map[string][]string, len(varOrder))
	componentOrder := make([]string, 0, len(varOrder))
	for _, v := range varOrder {
		root := find(v)
		if _, exists := components[root]; !exists {
			componentOrder = append(componentOrder, root)
		}
		components[root] = append(components[root], v)
	}

	constraintsByRoot := make(map[string][]cartesianEqConstraint, len(componentOrder))
	for _, c := range eqConstraints {
		root := find(c.leftVar)
		constraintsByRoot[root] = append(constraintsByRoot[root], c)
	}

	indexCache := map[string]map[string][]*storage.Node{}
	buildIndex := func(variable, prop string) map[string][]*storage.Node {
		cacheKey := variable + "|" + prop
		if idx, exists := indexCache[cacheKey]; exists {
			return idx
		}
		nodes := varToNodes[variable]
		idx := make(map[string][]*storage.Node, len(nodes))
		for _, n := range nodes {
			if n == nil || n.Properties == nil {
				continue
			}
			v, ok := n.Properties[prop]
			if !ok {
				continue
			}
			k := cypherValueKey(v, cypherValueEqualityContract)
			idx[k] = append(idx[k], n)
		}
		indexCache[cacheKey] = idx
		return idx
	}

	buildComponentRows := func(vars []string, constraints []cartesianEqConstraint) []map[string]*storage.Node {
		if len(vars) == 0 {
			return []map[string]*storage.Node{{}}
		}
		if len(vars) == 1 {
			v := vars[0]
			rows := make([]map[string]*storage.Node, 0, len(varToNodes[v]))
			for _, n := range varToNodes[v] {
				rows = append(rows, map[string]*storage.Node{v: n})
			}
			return rows
		}

		seed := vars[0]
		rows := make([]map[string]*storage.Node, 0, len(varToNodes[seed]))
		for _, n := range varToNodes[seed] {
			rows = append(rows, map[string]*storage.Node{seed: n})
		}
		added := map[string]struct{}{seed: {}}

		for len(added) < len(vars) {
			progressed := false
			for _, c := range constraints {
				baseVar := ""
				baseProp := ""
				newVar := ""
				newProp := ""
				// leftVar.leftProp = rightVar.rightProp + offset. Expanding
				// from a base variable to a new variable needs the new
				// variable's value expressed through the base's: from left to
				// right it is left - offset, from right to left it is
				// right + offset.
				lookupOffset := int64(0)
				if _, ok := added[c.leftVar]; ok {
					if _, seen := added[c.rightVar]; !seen {
						baseVar, baseProp = c.leftVar, c.leftProp
						newVar, newProp = c.rightVar, c.rightProp
						lookupOffset = -c.offset
					}
				}
				if baseVar == "" {
					if _, ok := added[c.rightVar]; ok {
						if _, seen := added[c.leftVar]; !seen {
							baseVar, baseProp = c.rightVar, c.rightProp
							newVar, newProp = c.leftVar, c.leftProp
							lookupOffset = c.offset
						}
					}
				}
				if baseVar == "" {
					continue
				}

				idx := buildIndex(newVar, newProp)
				nextRows := make([]map[string]*storage.Node, 0, len(rows))
				for _, row := range rows {
					baseNode := row[baseVar]
					if baseNode == nil || baseNode.Properties == nil {
						continue
					}
					baseVal, ok := baseNode.Properties[baseProp]
					if !ok {
						continue
					}
					lookupKey := cypherValueKey(baseVal, cypherValueEqualityContract)
					if lookupOffset != 0 {
						// Shift the value exactly: integer offsets use integer
						// arithmetic (no float64 rounding above 2^53, #692).
						// Floats keep their float keys so float offset joins
						// still find their index entries.
						if key, ok := cartesianShiftValueKey(baseVal, lookupOffset, cypherValueEqualityContract); ok {
							lookupKey = key
						} else if baseNum, numeric := toFloat64(baseVal); numeric {
							lookupKey = cypherValueKey(baseNum+float64(lookupOffset), cypherValueEqualityContract)
						} else {
							continue
						}
					}
					for _, matchNode := range idx[lookupKey] {
						joined := make(map[string]*storage.Node, util.SafePreallocSum(len(row), 1))
						for k, v := range row {
							joined[k] = v
						}
						joined[newVar] = matchNode
						nextRows = append(nextRows, joined)
					}
				}
				rows = nextRows
				added[newVar] = struct{}{}
				progressed = true
			}
			if !progressed {
				return nil
			}
		}

		filtered := make([]map[string]*storage.Node, 0, len(rows))
		for _, row := range rows {
			keep := true
			for _, c := range constraints {
				ln := row[c.leftVar]
				rn := row[c.rightVar]
				if ln == nil || rn == nil || ln.Properties == nil || rn.Properties == nil {
					keep = false
					break
				}
				lv, lok := ln.Properties[c.leftProp]
				rv, rok := rn.Properties[c.rightProp]
				if !lok || !rok {
					keep = false
					break
				}
				if c.offset == 0 {
					if cypherValueKey(lv, cypherValueEqualityContract) != cypherValueKey(rv, cypherValueEqualityContract) {
						keep = false
						break
					}
					continue
				}
				// lv must equal rv + offset exactly (#692): integer values
				// compare through integer arithmetic, others through float64.
				if !cartesianOffsetValuesEqual(lv, rv, c.offset) {
					keep = false
					break
				}
			}
			if keep {
				filtered = append(filtered, row)
			}
		}
		return filtered
	}

	componentRows := make([][]map[string]*storage.Node, 0, len(componentOrder))
	for _, root := range componentOrder {
		rows := buildComponentRows(components[root], constraintsByRoot[root])
		if rows == nil {
			return nil, false
		}
		componentRows = append(componentRows, rows)
	}

	out := []map[string]*storage.Node{{}}
	for _, rows := range componentRows {
		if len(rows) == 0 {
			return []map[string]*storage.Node{}, true
		}
		next := make([]map[string]*storage.Node, 0, util.SafePreallocProduct(len(out), len(rows)))
		for _, base := range out {
			for _, row := range rows {
				merged := make(map[string]*storage.Node, util.SafePreallocSum(len(base), len(row)))
				for k, v := range base {
					merged[k] = v
				}
				for k, v := range row {
					merged[k] = v
				}
				next = append(next, merged)
			}
		}
		out = next
	}
	return out, true
}

// tryResolveMatchNodesByIDFromWhere attempts to resolve all MATCH pattern
// variables via direct ID lookup from WHERE elementId(var) = $param or
// id(var) = $param predicates. This is the relationship-create hot path:
// it avoids label scans when both endpoints are identified by ID.
//
// It collects all WHERE clauses across MATCH segments, splits on top-level
// AND, and tries to parse each conjunct as an ID equality predicate. If
// every pattern variable can be resolved this way, it returns a single
// combination map. Otherwise it returns (nil, false) and the caller falls
// through to the generic label-scan path.
func (e *StorageExecutor) tryResolveMatchNodesByIDFromWhere(
	ctx context.Context,
	matchClauses []string,
	params map[string]interface{},
) (map[string]*storage.Node, bool) {
	if len(matchClauses) == 0 {
		return nil, false
	}

	// Collect all pattern variables and their label constraints, plus all
	// WHERE conjuncts across segments.
	type varInfo struct {
		labels     []string
		properties map[string]interface{}
	}
	variables := make(map[string]*varInfo)
	var allWhereTerms []string

	for _, clause := range matchClauses {
		whereForClause := ""
		patternPart := clause
		if whereIdx := findKeywordIndex(clause, "WHERE"); whereIdx > 0 {
			whereForClause = strings.TrimSpace(clause[whereIdx+5:])
			patternPart = strings.TrimSpace(clause[:whereIdx])
		}

		// Extract pattern variables from comma-separated node patterns.
		patterns := e.splitNodePatterns(patternPart)
		for _, p := range patterns {
			p = strings.TrimSpace(p)
			if p == "" {
				continue
			}
			// Skip relationship patterns — they contain arrows.
			if patternHasRelationship(p) {
				return nil, false
			}
			info, parseErr := e.parseNodePattern(ctx, p)
			if parseErr != nil {
				recordExpressionFailure(ctx, parseErr)
				return nil, false
			}
			if info.variable == "" {
				continue
			}
			variables[info.variable] = &varInfo{
				labels:     info.labels,
				properties: info.properties,
			}
		}

		if whereForClause != "" {
			for _, term := range splitTopLevelAndConjuncts(whereForClause) {
				term = strings.TrimSpace(term)
				if term != "" {
					allWhereTerms = append(allWhereTerms, term)
				}
			}
		}
	}

	if len(variables) == 0 || len(allWhereTerms) == 0 {
		return nil, false
	}

	// Try to resolve each variable from an ID equality predicate.
	resolved := make(map[string]*storage.Node, len(variables))
	for _, term := range allWhereTerms {
		varName, node := e.resolveNodeFromIDEqualityTerm(term, params)
		if varName == "" || node == nil {
			continue
		}
		if _, known := variables[varName]; !known {
			continue
		}
		resolved[varName] = node
	}

	// All variables must be resolved for the fast path to apply.
	if len(resolved) != len(variables) {
		return nil, false
	}

	// Validate label and property constraints from the patterns.
	for varName, info := range variables {
		node := resolved[varName]
		if len(info.labels) > 0 && !nodeHasAnyLabel(node, info.labels) {
			return nil, false
		}
		for k, v := range info.properties {
			if node.Properties[k] != v {
				return nil, false
			}
		}
	}

	return resolved, true
}

// resolveNodeFromIDEqualityTerm parses a single WHERE conjunct of the form
// elementId(<var>) = <value> or id(<var>) = <value> and resolves the node.
// Returns the variable name and resolved node, or ("", nil) if the term
// doesn't match the expected shape.
func (e *StorageExecutor) resolveNodeFromIDEqualityTerm(
	term string,
	params map[string]interface{},
) (string, *storage.Node) {
	term = strings.TrimSpace(term)
	if term == "" {
		return "", nil
	}

	eqIdx := strings.Index(term, "=")
	if eqIdx <= 0 || eqIdx >= len(term)-1 {
		return "", nil
	}
	// Reject !=, <=, >=, ==
	if eqIdx > 0 && (term[eqIdx-1] == '!' || term[eqIdx-1] == '<' || term[eqIdx-1] == '>') {
		return "", nil
	}
	if eqIdx+1 < len(term) && term[eqIdx+1] == '=' {
		return "", nil
	}

	left := strings.TrimSpace(term[:eqIdx])
	right := strings.TrimSpace(term[eqIdx+1:])
	if left == "" || right == "" {
		return "", nil
	}

	// LHS must be id(var) or elementId(var).
	kind := ""
	varName := ""
	lowerLeft := lowerASCII(left)
	switch {
	case strings.HasPrefix(lowerLeft, "id(") && strings.HasSuffix(left, ")"):
		kind = "id"
		varName = strings.TrimSpace(left[3 : len(left)-1])
	case strings.HasPrefix(lowerLeft, "elementid(") && strings.HasSuffix(left, ")"):
		kind = "elementId"
		varName = strings.TrimSpace(left[10 : len(left)-1])
	default:
		return "", nil
	}
	if varName == "" {
		return "", nil
	}

	// Resolve the RHS value.
	var idValue string
	if strings.HasPrefix(right, "$") {
		// Parameter reference.
		if params == nil {
			return "", nil
		}
		paramName := strings.TrimSpace(right[1:])
		raw, ok := params[paramName]
		if !ok {
			return "", nil
		}
		s, ok := raw.(string)
		if !ok || strings.TrimSpace(s) == "" {
			return "", nil
		}
		idValue = strings.TrimSpace(s)
	} else {
		// Literal value — strip surrounding quotes.
		idValue = strings.TrimSpace(right)
		if decoded, quoted := decodeCypherQuotedString(idValue); quoted {
			idValue = decoded
		}
		if idValue == "" {
			return "", nil
		}
	}

	// Endpoint seeks use the same source selection as ordinary MATCH seeks.
	// Ambiguous composite raw IDs stay on the normal predicate path.
	lookupID, found, applicable := e.entitySeekLookup(idValue, "4", kind)
	if !applicable || !found {
		return "", nil
	}

	node, err := e.getQueryNode(e.storage, storage.NodeID(lookupID))
	if err != nil || node == nil {
		return "", nil
	}

	return varName, node
}

// validateCreatePropertyKeys checks a CREATE pattern's property keys against
// the map-key rule: a key is a symbolic name, or a backtick-quoted name
// (holding any character) in the pattern text. Only a key that is neither
// is checked on the text by validateStaticMapKeys, which reports it, so a
// pattern with plain keys isn't scanned again.
func validateCreatePropertyKeys(text string, properties map[string]interface{}) error {
	for key := range properties {
		if isValidIdentifier(key) || strings.Contains(text, "`"+strings.ReplaceAll(key, "`", "``")+"`") {
			continue
		}
		if err := validateStaticMapKeys(text); err != nil {
			return err
		}
		return localizedError(localization.CypherMutationsInvalidPropertyKey(key), nil)
	}
	return nil
}

package cypher

import (
	"fmt"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

func (plan *createPlan) bindings() (map[string]*storage.Node, map[string]*storage.Edge) {
	if plan.nodeBindings == nil {
		plan.nodeBindings = make(map[string]*storage.Node)
	}
	if plan.edgeBindings == nil {
		plan.edgeBindings = make(map[string]*storage.Edge)
	}
	return plan.nodeBindings, plan.edgeBindings
}

// containsString checks if a slice contains a string.
func containsString(slice []string, s string) bool {
	for _, item := range slice {
		if item == s {
			return true
		}
	}
	return false
}

// validateSetAssignments pre-validates SET clause assignments before executing CREATE
// This ensures we fail fast on invalid function calls, preventing orphaned nodes
func (e *StorageExecutor) validateSetAssignments(assignments []string) error {
	// Known Cypher functions
	knownFunctions := map[string]bool{
		"COALESCE": true, "TOSTRING": true, "TOINT": true, "TOFLOAT": true,
		"TOBOOLEAN": true, "TOLOWER": true, "TOUPPER": true, "TRIM": true,
		"SIZE": true, "LENGTH": true, "ABS": true, "CEIL": true, "FLOOR": true,
		"ROUND": true, "RAND": true, "SQRT": true, "SIGN": true, "LOG": true,
		"LOG10": true, "EXP": true, "SIN": true, "COS": true, "TAN": true,
		"DATE": true, "DATETIME": true, "TIME": true, "TIMESTAMP": true,
		"DURATION": true, "LOCALDATETIME": true, "LOCALTIME": true,
		"HEAD": true, "LAST": true, "TAIL": true, "KEYS": true, "LABELS": true,
		"TYPE": true, "ID": true, "ELEMENTID": true, "PROPERTIES": true,
		"POINT": true, "DISTANCE": true, "REPLACE": true, "SUBSTRING": true,
		"LEFT": true, "RIGHT": true, "SPLIT": true, "REVERSE": true,
		"LTRIM": true, "RTRIM": true, "COLLECT": true, "RANGE": true,
	}

	for _, assignment := range assignments {
		assignment = strings.TrimSpace(assignment)
		if assignment == "" {
			continue
		}

		// Parse assignment: var.property = value or var:Label
		eqIdx := strings.Index(assignment, "=")
		if eqIdx == -1 {
			// Could be a label assignment like "n:Label" - these are valid
			continue
		}

		rightSide := strings.TrimSpace(assignment[eqIdx+1:])

		// Check if right side looks like a function call
		if strings.Contains(rightSide, "(") && strings.HasSuffix(strings.TrimSpace(rightSide), ")") {
			// Extract function name (before first parenthesis)
			parenIdx := strings.Index(rightSide, "(")
			funcName := upperASCII(strings.TrimSpace(rightSide[:parenIdx]))
			if !knownFunctions[funcName] {
				return localizedError(localization.CypherMergeUnknownFunction(funcName), nil)
			}
		}
	}
	return nil
}

// extractCreateVariableRefs returns variable names used as simple refs in CREATE relationship patterns
// (e.g. (o)-[:R]->(pharmacy) yields ["o", "pharmacy"]). Used to know which bindings the pipeline must return.
func extractCreateVariableRefs(createPart string) []string {
	seen := make(map[string]bool)
	exec := &StorageExecutor{}
	createClauses := SplitByCreate(createPart)
	for _, clause := range createClauses {
		clause = strings.TrimSpace(clause)
		if clause == "" {
			continue
		}
		for _, pattern := range exec.splitCreatePatterns(clause) {
			pattern = strings.TrimSpace(pattern)
			if pattern == "" {
				continue
			}
			_, pattern = parseCreatePathAssignment(pattern)
			src, _, tgt, _, remainder, err := exec.parseCreateRelPatternWithVars(pattern)
			if err != nil || strings.TrimSpace(remainder) != "" {
				continue
			}
			if isSimpleVariable(src) {
				seen[src] = true
			}
			if isSimpleVariable(tgt) {
				seen[tgt] = true
			}
		}
	}
	out := make([]string, 0, len(seen))
	for k := range seen {
		out = append(out, k)
	}
	return out
}

func sortNodesByProperty(nodes []*storage.Node, prop string) {
	// Simple sort by property value (string comparison)
	// OrderStatus by orderId, Pharmacy by id
	for i := 0; i < len(nodes); i++ {
		for j := i + 1; j < len(nodes); j++ {
			vi := fmt.Sprint(getNodeProp(nodes[i], prop))
			vj := fmt.Sprint(getNodeProp(nodes[j], prop))
			if vi > vj {
				nodes[i], nodes[j] = nodes[j], nodes[i]
			}
		}
	}
}

type createPatternSplit struct {
	all           []string
	nodes         []string
	relationships []string
}

var createPatternSplits = newBoundedCache[string, createPatternSplit](4096, boundedCacheStringShardIndex)

func (e *StorageExecutor) createPatternSplitFor(pattern string) createPatternSplit {
	if split, cached := createPatternSplits.get(pattern); cached {
		return split
	}
	split := createPatternSplit{all: e.scanCreatePatterns(pattern)}
	for _, fragment := range split.all {
		fragment = strings.TrimSpace(fragment)
		if fragment == "" {
			continue
		}
		if patternHasRelationship(fragment) {
			split.relationships = append(split.relationships, fragment)
		} else {
			split.nodes = append(split.nodes, fragment)
		}
	}
	createPatternSplits.put(pattern, split)
	return split
}

type createRelationshipSyntax struct {
	source, relationship, target, remainder string
	reverse                                 bool
	err                                     error
}

var createRelationshipSyntaxPlans = newBoundedCache[string, createRelationshipSyntax](4096, boundedCacheStringShardIndex)

func getNodeProp(n *storage.Node, prop string) interface{} {
	if n == nil || n.Properties == nil {
		return nil
	}
	return n.Properties[prop]
}

// parseCreateRelPatternWithVars parses patterns like (varA)-[r:TYPE {props}]->(varB)
// where varA and varB are variable references (not full node definitions)
// Returns: sourceVar, relContent, targetVar, isReverse, remainder, error
// remainder is any content after the target node (for chained patterns)
func (e *StorageExecutor) parseCreateRelPatternWithVars(pattern string) (string, string, string, bool, string, error) {
	pattern = strings.TrimSpace(pattern)
	if plan, cached := createRelationshipSyntaxPlans.get(pattern); cached {
		return plan.source, plan.relationship, plan.target, plan.reverse, plan.remainder, plan.err
	}
	source, relationship, target, reverse, remainder, err := e.scanCreateRelPatternWithVars(pattern)
	createRelationshipSyntaxPlans.put(pattern, createRelationshipSyntax{source, relationship, target, remainder, reverse, err})
	return source, relationship, target, reverse, remainder, err
}

func (e *StorageExecutor) scanCreateRelPatternWithVars(pattern string) (string, string, string, bool, string, error) {
	pattern = strings.TrimSpace(pattern)
	findNodeEnd := findMatchingParen

	// Find the first node: (varA)
	if !strings.HasPrefix(pattern, "(") {
		return "", "", "", false, "", localizedError(localization.CypherMutationsRelationshipPatternMustStartNode(), nil)
	}

	// Find end of first node
	firstNodeEnd := findNodeEnd(pattern, 0)
	if firstNodeEnd < 0 {
		return "", "", "", false, "", localizedError(localization.CypherMutationsRelationshipPatternUnmatchedParen(), nil)
	}

	sourceVar := strings.TrimSpace(pattern[1:firstNodeEnd])
	rest := pattern[firstNodeEnd+1:]
	rest = strings.TrimSpace(rest) // Remove any whitespace before -[ or <-[

	// Detect direction and find relationship bracket
	isReverse := false
	var relStart int

	if strings.HasPrefix(rest, "-[") {
		relStart = 2 // Skip "-["
	} else if strings.HasPrefix(rest, "<-[") {
		isReverse = true
		relStart = 3 // Skip "<-["
	} else {
		return "", "", "", false, "", localizedError(localization.CypherResidualRelationshipConnectorExpected(rest[:min(20, len(rest))]), nil)
	}

	// Find matching ] considering nested brackets in properties
	relEnd := findMatchingBracket(rest, relStart-1)
	if relEnd < 0 {
		return "", "", "", false, "", localizedError(localization.CypherMutationsRelationshipPatternUnmatchedBracket(), nil)
	}

	relContent := rest[relStart:relEnd]
	afterRel := strings.TrimSpace(rest[relEnd+1:])

	// Now find the second node
	var secondNodeStart int
	if isReverse {
		if !strings.HasPrefix(afterRel, "-(") {
			return "", "", "", false, "", localizedError(localization.CypherMutationsRelationshipPatternForwardExpected(), nil)
		}
		secondNodeStart = 2
	} else {
		if !strings.HasPrefix(afterRel, "->(") {
			return "", "", "", false, "", localizedError(localization.CypherMutationsRelationshipPatternArrowExpected(), nil)
		}
		secondNodeStart = 3
	}

	// Find end of second node
	secondNodeEnd := findNodeEnd(afterRel, secondNodeStart-1)
	if secondNodeEnd < 0 {
		return "", "", "", false, "", localizedError(localization.CypherMutationsRelationshipPatternSecondUnmatched(), nil)
	}

	targetVar := strings.TrimSpace(afterRel[secondNodeStart:secondNodeEnd])
	remainder := strings.TrimSpace(afterRel[secondNodeEnd+1:])

	return sourceVar, relContent, targetVar, isReverse, remainder, nil
}

package cypher

import (
	"context"
	"fmt"
	"strconv"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
)

// bindingScope is the shared compile-time name set used while validating
// clause composition. Runtime values deliberately do not live here: semantic
// validation must finish before a mutation handler can produce effects.
type semanticBindingScope struct {
	names map[string]struct{}
}

func newSemanticBindingScope() *semanticBindingScope {
	return &semanticBindingScope{names: make(map[string]struct{})}
}

func (s *semanticBindingScope) bind(name string) {
	name = normalizeProjectionColumnName(strings.TrimSpace(name))
	if name != "" {
		s.names[name] = struct{}{}
	}
}

func (s *semanticBindingScope) contains(name string) bool {
	_, exists := s.names[normalizeProjectionColumnName(strings.TrimSpace(name))]
	return exists
}

// validateCreateSemanticScopes applies one symbol contract before routing to
// any of the specialized CREATE executors. It intentionally consumes the same
// top-level clause decomposition as the semantic pipeline so fast paths cannot
// disagree about whether a name is new, bound, or undefined.
func (e *StorageExecutor) validateCreateSemanticScopes(ctx context.Context, cypher string, cypher25 bool) error {
	if findKeywordIndexInContext(cypher, "CREATE") < 0 || isCreateSchemaOrAdministrationCommand(cypher) {
		return nil
	}
	clauses, err := e.boundMutationClauses(ctx, cypher, cypher25)
	if err != nil {
		return err
	}
	for _, clause := range clauses {
		if clause.kind == pipelineClauseCreate {
			if err := e.validateCreateClauseBindings(ctx, clauseBindingScope(clause, nil), clause.text, cypher25); err != nil {
				return err
			}
		}
	}
	return nil
}

func isCreateSchemaOrAdministrationCommand(cypher string) bool {
	return isSystemCommandNoGraph(cypher) || isCreateProcedureCommand(cypher) ||
		startsWithKeywords(cypher, "CREATE", "DECAY PROFILE") ||
		startsWithKeywords(cypher, "CREATE", "PROMOTION PROFILE") ||
		startsWithKeywords(cypher, "CREATE", "PROMOTION POLICY") ||
		startsWithKeywords(cypher, "CREATE", "CONSTRAINT") ||
		startsWithKeywords(cypher, "CREATE", "INDEX") ||
		startsWithKeywords(cypher, "CREATE", "RANGE INDEX") ||
		startsWithKeywords(cypher, "CREATE", "FULLTEXT INDEX") ||
		startsWithKeywords(cypher, "CREATE", "VECTOR INDEX") ||
		startsWithKeywords(cypher, "CREATE", "TEXT INDEX") ||
		startsWithKeywords(cypher, "CREATE", "POINT INDEX") ||
		startsWithKeywords(cypher, "CREATE", "LOOKUP INDEX")
}

func projectedBindingScope(ctx context.Context, input *semanticBindingScope, clause string) *semanticBindingScope {
	projection, _ := projectionSemanticBodyAndTail(clause, "WITH")
	plan := returnProjectionPlanFor(ctx, "RETURN "+projection)
	return &semanticBindingScope{names: projectionPlanScope(plan, input.names)}
}

// validateUnwindAlias rejects an UNWIND clause whose alias isn't exactly one
// variable, as Neo4j does: UNWIND takes no WHERE, so "UNWIND l AS x WHERE …"
// and "UNWIND l AS x y" are SyntaxErrors (Invalid input 'WHERE').
func validateUnwindAlias(clause string) error {
	_, alias, ok := parsePipelineIteration(clause)
	if !ok {
		return sharedClauseSyntaxError("iteration requires a variable and an expression")
	}
	_, next, identifier := scanIdentifierToken(alias, 0)
	if !identifier {
		return nil
	}
	if rest := strings.TrimSpace(alias[next:]); rest != "" {
		token := strings.Fields(rest)[0]
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			localization.CypherCoreInvalidInput(token))
	}
	return nil
}

// unwindBindingName is the variable an UNWIND clause binds (splitUnwindBody).
func unwindBindingName(clause string) string {
	if _, alias, ok := parsePipelineIteration(clause); ok {
		if name, _, symbolic := scanSymbolicName(alias, 0); symbolic {
			return normalizeProjectionColumnName(name)
		}
	}
	return ""
}

func (e *StorageExecutor) validateCreateClauseBindings(ctx context.Context, scope *semanticBindingScope, clause string, cypher25 bool) error {
	body := strings.TrimSpace(clause[len("CREATE"):])
	created := make(map[string]string)
	for _, pattern := range e.splitCreatePatterns(body) {
		if !cypher25 {
			clear(created)
		}
		pattern = strings.TrimSpace(pattern)
		if pattern == "" {
			continue
		}
		isRelationshipPattern := patternHasRelationship(pattern)
		relationshipVariables := extractRelationshipVariables(pattern)
		for _, variable := range relationshipVariables {
			if scope.contains(variable) {
				return createVariableAlreadyBoundError(variable)
			}
		}
		if isRelationshipPattern {
			if err := validateCreateRelationshipShape(pattern); err != nil {
				return err
			}
		}

		if err := e.validateCreateSamePatternReferences(ctx, scope, pattern, relationshipVariables, created, "CREATE"); err != nil {
			return err
		}

		for _, nodePattern := range e.splitNodePatterns(pattern) {
			variable := createNodePatternVariable(nodePattern)
			if err := e.validateCreatePatternExpressions(scope, nodePattern); err != nil {
				return err
			}
			if variable == "" {
				continue
			}
			if scope.contains(variable) {
				if !isRelationshipPattern || createNodePatternHasDecoration(nodePattern) {
					return createVariableAlreadyBoundError(variable)
				}
				continue
			}
			scope.bind(variable)
		}

		if err := e.validateCreateRelationshipExpressions(scope, pattern); err != nil {
			return err
		}
		for _, variable := range relationshipVariables {
			scope.bind(variable)
		}
	}
	return nil
}

func validateCreateRelationshipShape(pattern string) error {
	open, close := firstRelationshipBracket(pattern)
	if open < 0 || close < 0 {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"NoSingleRelationshipType",
			"CREATE relationships require exactly one relationship type",
		)
	}

	left := strings.TrimSpace(pattern[:open])
	right := strings.TrimSpace(pattern[close+1:])
	leftDirected := strings.HasSuffix(left, "<-")
	rightDirected := strings.HasPrefix(right, "->")
	if leftDirected == rightDirected {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"RequiresDirectedRelationship",
			"CREATE relationships require exactly one direction",
		)
	}

	return validateSingleRelationshipDeclaration("CREATE", "created", pattern[open+1:close])
}

// validateSingleRelationshipDeclaration applies CREATE's and MERGE's rules to
// a relationship's inside (relationshipDeclarationOf), read outside
// backticks: no variable length (verb is the clause's action, "created" or
// "merged"), and exactly one type, unless the type is dynamic ($(e), whose
// types are counted per row by resolveRowDynamicTokens). Alternatives
// ([:R|S]) are Neo4j's NoSingleRelationshipType error naming the clause.
func validateSingleRelationshipDeclaration(clause, verb, content string) error {
	declaration := relationshipDeclarationOf(content)
	if declaration.hasLength {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"CreatingVarLength",
			"variable-length relationships cannot be "+verb,
		)
	}
	if declaration.hasColon && hasDynamicToken(declaration.typeText) {
		return nil
	}
	if declaration.hasColon && indexByteOutsideBackticks(declaration.typeText, '|') >= 0 {
		return singleRelationshipTypeError(clause)
	}
	if declaration.invalidType != "" {
		return &classifiedCypherError{
			cause:  localizedError(localization.CypherMutationsInvalidRelationshipType(declaration.invalidType), nil),
			code:   "Neo.ClientError.Statement.SyntaxError",
			detail: "InvalidRelationshipType",
		}
	}
	if len(declaration.types) != 1 {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"NoSingleRelationshipType",
			clause+" relationships require exactly one relationship type",
		)
	}
	return nil
}

func createNodePatternVariable(pattern string) string {
	trimmed := strings.TrimSpace(pattern)
	if strings.HasPrefix(trimmed, "(") {
		trimmed = strings.TrimSpace(trimmed[1:])
	}
	name, _, ok := scanIdentifierToken(trimmed, 0)
	if !ok {
		return ""
	}
	return name
}

func createNodePatternHasDecoration(pattern string) bool {
	trimmed := strings.TrimSpace(pattern)
	if strings.HasPrefix(trimmed, "(") {
		trimmed = strings.TrimSpace(trimmed[1:])
	}
	_, next, ok := scanIdentifierToken(trimmed, 0)
	if !ok {
		return false
	}
	remainder := strings.TrimSpace(trimmed[next:])
	return strings.HasPrefix(remainder, ":") || strings.HasPrefix(remainder, "{")
}

func createVariableAlreadyBoundError(variable string) error {
	return newSemanticError(
		"Neo.ClientError.Statement.SyntaxError",
		"VariableAlreadyBound",
		fmt.Sprintf("variable %s is already bound and cannot be redeclared by CREATE", variable),
	)
}

func createUndefinedVariableError(variable string) error {
	message := localization.CypherAdminVariableNotDefined(variable)
	// Preserve the semantic error in the chain for callers that inspect its
	// detail, while the client-visible text uses the localized constructor.
	semantic := newSemanticError("Neo.ClientError.Statement.SyntaxError", "UndefinedVariable", message.Fallback)
	return &classifiedCypherError{
		cause:  localizedError(message, semantic),
		code:   "Neo.ClientError.Statement.SyntaxError",
		detail: "UndefinedVariable",
	}
}

func (e *StorageExecutor) validateCreatePatternExpressions(scope *semanticBindingScope, pattern string) error {
	properties, ok := createPropertyMapBody(pattern)
	if !ok {
		return nil
	}
	return e.validateCreatePropertyExpressions(scope, properties)
}

func (e *StorageExecutor) validateCreateRelationshipExpressions(scope *semanticBindingScope, pattern string) error {
	for _, properties := range createRelationshipPropertyMapBodies(pattern) {
		if err := e.validateCreatePropertyExpressions(scope, properties); err != nil {
			return err
		}
	}
	return nil
}

// createPropertyMapBody returns the text between the braces of a node (or
// relationship) pattern's property map.
func createPropertyMapBody(pattern string) (string, bool) {
	open := indexByteOutsideBackticks(pattern, '{')
	close := strings.LastIndex(pattern, "}")
	if open < 0 || close <= open {
		return "", false
	}
	return pattern[open+1 : close], true
}

// createRelationshipPropertyMapBodies returns the property map text of every
// relationship ([...]) in a CREATE path pattern.
func createRelationshipPropertyMapBodies(pattern string) []string {
	var bodies []string
	for offset := 0; offset < len(pattern); {
		open := strings.Index(pattern[offset:], "[")
		if open < 0 {
			break
		}
		open += offset
		close := findMatchingBracket(pattern, open)
		if close < 0 {
			break
		}
		if properties, ok := createPropertyMapBody(pattern[open+1 : close]); ok {
			bodies = append(bodies, properties)
		}
		offset = close + 1
	}
	return bodies
}

// validateCreateSamePatternReferences rejects a property value that reads a
// node or relationship created by the same CREATE path pattern, including a
// node's own map ((a {x: a.y})), as Neo4j does: the entity does not exist yet
// when its pattern's properties are evaluated. In a Cypher 5 statement a
// later comma-separated pattern may read it; names bound inside the
// expression (list comprehension iterators, reduce / all / any / none /
// single) are not references.
//
// created holds the clause's entities already read (and receives this
// pattern's): a fresh map per pattern for a Cypher 5 statement, one map per
// clause for a Cypher 25 statement, where a pattern may not read an entity an
// earlier pattern of the same CREATE creates either (Neo4j 2026.09).
func (e *StorageExecutor) validateCreateSamePatternReferences(ctx context.Context, scope *semanticBindingScope, pattern string, relationshipVariables []string, created map[string]string, clause string) error {
	nodePatterns := e.splitNodePatterns(pattern)
	for _, nodePattern := range nodePatterns {
		if variable := createNodePatternVariable(nodePattern); variable != "" && !scope.contains(variable) {
			created[variable] = "Node"
		}
	}
	for _, variable := range relationshipVariables {
		created[variable] = "Relationship"
	}
	if len(created) == 0 {
		return nil
	}
	maps := createRelationshipPropertyMapBodies(pattern)
	for _, nodePattern := range nodePatterns {
		if properties, ok := createPropertyMapBody(nodePattern); ok {
			maps = append(maps, properties)
		}
	}
	for _, properties := range maps {
		for _, pair := range splitTopLevelComma(properties) {
			separator := findTopLevelMapKeyValueSeparator(pair)
			if separator <= 0 {
				continue
			}
			for _, variable := range expressionFreeVariables(ctx, pair[separator+1:]) {
				if kind, ok := created[variable]; ok {
					return createSamePatternReferenceError(variable, kind, clause)
				}
			}
		}
	}
	return nil
}

func createSamePatternReferenceError(variable, kind, clause string) error {
	return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "VariableCreatedInSameClause",
		localization.CypherCoreEntityReferencedInSameClause(kind, variable, clause))
}

func (e *StorageExecutor) validateCreatePropertyExpressions(scope *semanticBindingScope, properties string) error {
	for _, pair := range splitTopLevelComma(properties) {
		separator := findTopLevelMapKeyValueSeparator(pair)
		if separator <= 0 {
			continue
		}
		expression := strings.TrimSpace(pair[separator+1:])
		if err := validateExpressionOperandCompleteness(expression); err != nil {
			return err
		}
		variable, isReference := simpleCreatePropertyReference(expression)
		if isReference && !scope.contains(variable) {
			return createUndefinedVariableError(variable)
		}
	}
	return nil
}

func simpleCreatePropertyReference(expression string) (string, bool) {
	expression = strings.TrimSpace(expression)
	if expression == "" || strings.HasPrefix(expression, "$") ||
		strings.HasPrefix(expression, "'") || strings.HasPrefix(expression, "\"") ||
		strings.HasPrefix(expression, "[") || strings.HasPrefix(expression, "{") ||
		looksLikeFunctionCall(expression) {
		return "", false
	}
	if strings.EqualFold(expression, "null") || strings.EqualFold(expression, "true") || strings.EqualFold(expression, "false") {
		return "", false
	}
	if _, err := strconv.ParseInt(expression, 10, 64); err == nil {
		return "", false
	}
	if _, err := strconv.ParseFloat(expression, 64); err == nil {
		return "", false
	}
	root, next, ok := scanIdentifierToken(expression, 0)
	if !ok {
		return "", false
	}
	// A qualified call can be followed by a property/subscript access. Its
	// namespace is not a variable, as in the shared free-reference reader.
	if _, call := qualifiedFunctionNameEnd(expression, next); call {
		return "", false
	}
	remainder := strings.TrimSpace(expression[next:])
	if remainder == "" || strings.HasPrefix(remainder, ".") || strings.HasPrefix(remainder, "[") {
		return root, true
	}
	return "", false
}

// singleRelationshipTypeError is Neo4j's error for alternative types
// ([:R|S]) in a CREATE or MERGE relationship.
func singleRelationshipTypeError(clause string) error {
	message := localization.CypherMatchingSingleRelationshipTypeRequired(clause)
	return localizedError(message, newSemanticError("Neo.ClientError.Statement.SyntaxError", "NoSingleRelationshipType", message.Fallback))
}

package cypher

import (
	"fmt"
	"time"

	"github.com/orneryd/nornicdb/pkg/multidb"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// DatabaseStorageResolver resolves the storage view selected by a protocol.
type DatabaseStorageResolver interface {
	GetStorage(name string) (storage.Engine, error)
}

type authenticatedDatabaseStorageResolver interface {
	GetStorageWithAuth(name, authToken string) (storage.Engine, error)
}

// DatabaseScopedExecutorOptions identifies the common executor lifetime and
// database selection shared by HTTP and Bolt. Protocol-specific configuration
// remains with the caller and runs before the executor is published.
type DatabaseScopedExecutorOptions struct {
	Name                    string
	Storage                 DatabaseStorageResolver
	AuthToken               string
	UseAuthenticatedStorage bool
	QueryCachePolicy        bool
	QueryCacheMaxEntries    int
	QueryCacheTTL           time.Duration
	StatementCacheManager   *multidb.DatabaseManager
	FallbackStatementCaches *StatementCaches
	LocalizationRenderer    ProcedureMetadataRenderer
	BaseExecutor            *StorageExecutor
	Configure               func(*StorageExecutor, storage.Engine)
}

// NewDatabaseScopedExecutor builds the one database-scoped execution view used
// by protocol adapters. It binds canonical statement caches before publication.
func NewDatabaseScopedExecutor(options DatabaseScopedExecutorOptions) (*StorageExecutor, error) {
	var (
		engine storage.Engine
		err    error
	)
	if options.UseAuthenticatedStorage {
		if resolver, ok := options.Storage.(authenticatedDatabaseStorageResolver); ok {
			engine, err = resolver.GetStorageWithAuth(options.Name, options.AuthToken)
		} else {
			return nil, fmt.Errorf("database storage resolver does not support authenticated access for %q", options.Name)
		}
	} else {
		engine, err = options.Storage.GetStorage(options.Name)
	}
	if err != nil {
		return nil, err
	}

	var executor *StorageExecutor
	if options.QueryCachePolicy {
		executor = NewStorageExecutor(engine, QueryCachePolicy{MaxEntries: options.QueryCacheMaxEntries, TTL: options.QueryCacheTTL})
	} else {
		executor = NewStorageExecutor(engine)
	}
	if options.StatementCacheManager != nil {
		if err := executor.UseDatabaseStatementCaches(options.StatementCacheManager, options.Name); err != nil {
			return nil, err
		}
	} else if options.FallbackStatementCaches != nil {
		executor.UseStatementCaches(options.FallbackStatementCaches)
	}
	if options.LocalizationRenderer != nil {
		executor.SetLocalizationRenderer(options.LocalizationRenderer)
	}
	if options.BaseExecutor != nil {
		executor.ShareEmbedderFrom(options.BaseExecutor)
	}
	if options.Configure != nil {
		options.Configure(executor, engine)
	}
	return executor, nil
}

// Package cypher provides Neo4j-compatible Cypher query execution for NornicDB.
//
// This package implements a Cypher query parser and executor that supports
// the core Neo4j Cypher query language features. It enables NornicDB to be
// compatible with existing Neo4j applications and tools.
//
// Supported Cypher Features:
//   - MATCH: Pattern matching with node and relationship patterns
//   - CREATE: Creating nodes and relationships
//   - MERGE: Upsert operations with ON CREATE/ON MATCH clauses
//   - DELETE/DETACH DELETE: Removing nodes and relationships
//   - SET: Updating node and relationship properties
//   - REMOVE: Removing properties and labels
//   - RETURN: Returning query results
//   - WHERE: Filtering with conditions
//   - WITH: Passing results between query parts
//   - OPTIONAL MATCH: Left outer joins
//   - CALL: Procedure calls
//   - UNWIND: List expansion
//
// Example Usage:
//
//	// Create executor with storage backend
//	storage := storage.NewMemoryEngine()
//	executor := cypher.NewStorageExecutor(storage)
//
//	// Execute Cypher queries
//	result, err := executor.Execute(ctx, "CREATE (n:Person {name: 'Alice', age: 30})", nil)
//	if err != nil {
//		log.Fatal(err)
//	}
//
//	// Query with parameters
//	params := map[string]interface{}{
//		"name": "Alice",
//		"minAge": 25,
//	}
//	result, err = executor.Execute(ctx,
//		"MATCH (n:Person {name: $name}) WHERE n.age >= $minAge RETURN n", params)
//
//	// Complex query with relationships
//	result, err = executor.Execute(ctx, `
//		MATCH (a:Person)-[r:KNOWS]->(b:Person)
//		WHERE a.age > 25
//		RETURN a.name, r.since, b.name
//		ORDER BY a.age DESC
//		LIMIT 10
//	`, nil)
//
//	// Process results
//	for _, row := range result.Rows {
//		// process row (e.g. emit "Row: %v" via the configured logger)
//	}
//
// Neo4j Compatibility:
//
// The executor aims for high compatibility with Neo4j Cypher:
//   - Same syntax and semantics for core operations
//   - Parameter substitution with $param syntax
//   - Neo4j-style error messages and codes
//   - Compatible result format for drivers
//   - Support for Neo4j built-in functions
//
// Query Processing Pipeline:
//
// 1. **Parsing**: Query is parsed into an AST (Abstract Syntax Tree)
// 2. **Validation**: Syntax and semantic validation
// 3. **Parameter Substitution**: Replace $param with actual values
// 4. **Execution Planning**: Determine optimal execution strategy
// 5. **Execution**: Execute against storage backend
// 6. **Result Formatting**: Format results for Neo4j compatibility
//
// Performance Considerations:
//
//   - Pattern matching is optimized for common cases
//   - Indexes are used automatically when available
//   - Query planning chooses efficient execution paths
//   - Bulk operations are optimized for large datasets
//
// Limitations:
//
// Current limitations compared to full Neo4j:
//   - No user-defined procedures (CALL is limited to built-ins)
//   - No complex path expressions
//   - No graph algorithms (shortest path, etc.)
//   - No schema constraints (handled by storage layer)
//   - No transactions (single-query atomicity only)
//
// ELI12 (Explain Like I'm 12):
//
// Think of Cypher like asking questions about a social network:
//
//  1. **MATCH**: "Find all people named Alice" - like searching through
//     a phone book for everyone with a specific name.
//
//  2. **CREATE**: "Add a new person named Bob" - like writing a new
//     entry in the phone book.
//
//  3. **Relationships**: "Find who Alice knows" - like following the
//     lines between people on a friendship map.
//
//  4. **WHERE**: "Find people older than 25" - like adding a filter
//     to only show certain results.
//
//  5. **RETURN**: "Show me their names and ages" - like deciding which
//     information to display from your search.
//
// The Cypher executor is like a smart assistant that understands these
// questions and knows how to find the answers in your data!
package cypher

import (
	"context"
	"errors"
	"io"
	"log/slog"
	"net/http"
	"strings"
	"sync"
	"sync/atomic"
	"time"
	"unicode"

	apoccfg "github.com/orneryd/nornicdb/apoc"
	"github.com/orneryd/nornicdb/internal/cyphertext"
	"github.com/orneryd/nornicdb/pkg/config"
	"github.com/orneryd/nornicdb/pkg/embeddingutil"
	nornicerrors "github.com/orneryd/nornicdb/pkg/errors"
	"github.com/orneryd/nornicdb/pkg/fabric"
	"github.com/orneryd/nornicdb/pkg/heimdall"
	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/multidb"
	"github.com/orneryd/nornicdb/pkg/observability"
	"github.com/orneryd/nornicdb/pkg/search"
	"github.com/orneryd/nornicdb/pkg/storage"
