// ClearQueryCaches clears executor-local caches that can retain stale read results.
func (e *StorageExecutor) ClearQueryCaches() {
	if e.cache != nil {
		e.cache.Invalidate()
	}
	if e.planCache != nil {
		e.planCache.Clear()
	}
	if e.analyzer != nil {
		e.analyzer.ClearCache()
	}
	cacheMu := e.nodeLookupCacheLock()
	cacheMu.Lock()
	if e.nodeLookupCache != nil {
		clear(e.nodeLookupCache)
	} else {
		e.nodeLookupCache = make(map[string]*storage.Node)
	}
	cacheMu.Unlock()
}

// InvalidateCommittedWriteCaches evicts cached graph state after a write was
// committed by another executor sharing the same storage engine. Transaction-
// scoped Bolt executors use this to keep the long-lived read executor coherent
// without discarding its immutable analysis and plan caches.
func (e *StorageExecutor) InvalidateCommittedWriteCaches() {
	if e.cache != nil {
		e.cache.Invalidate()
	}
	e.invalidateNodeLookupCache()
}

// InvalidateEntityCaches evicts targeted cache entries affected by a specific entity state change.
func (e *StorageExecutor) InvalidateEntityCaches(entityID string, tokens []string) {
	if e.cache != nil && len(tokens) > 0 {
		e.cache.InvalidateLabels(tokens)
	}
	e.invalidateNodeLookupCacheForEntityID(storage.NodeID(entityID))
}

func (e *StorageExecutor) invalidateNodeLookupCacheForEntityID(entityID storage.NodeID) {
	if entityID == "" {
		return
	}
	cacheMu := e.nodeLookupCacheLock()
	cacheMu.Lock()
	for key, node := range e.nodeLookupCache {
		if node != nil && node.ID == entityID {
			delete(e.nodeLookupCache, key)
		}
	}
	cacheMu.Unlock()
}

// SetLogger installs the structured slog.Logger used for slow-query and
// operational records. D-01 non-breaking: NewStorageExecutor's signature is
// unchanged; callers (cmd/nornicdb/main.go) call SetLogger after construction
// so the *slog.Logger from observability.NewLogger flows through.
//
// Discard-fallback: passing nil installs a slog.Logger backed by io.Discard
// so subsequent log emissions cannot panic. The "component" attribute is
// pre-bound here (not per-call) to honor the RESEARCH "Per-call .With()
// allocation" anti-pattern.
func (e *StorageExecutor) SetLogger(logger *slog.Logger) {
	if logger == nil {
		logger = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	e.log.Store(logger.With("component", "cypher"))
}

// SetSlowQueryThreshold configures the D-04c slow-query emission gate.
// Zero or negative durations disable slow-query logging entirely. Threaded
// from cfg.Logging.SlowQueryThreshold at the bootstrap site.
func (e *StorageExecutor) SetSlowQueryThreshold(d time.Duration) {
	e.slowQueryThreshold = d
}

// SetSharedExecutor marks an executor as the cached, per-database executor
// that every auto-commit client of its database runs on. A shared executor
// rejects bare BEGIN/COMMIT/ROLLBACK statements: a statement must never
// leave the cached executor inside a transaction. Protocol transaction
// owners (Bolt/HTTP sessions) use their own per-session executors and are
// never marked shared. See the sharedExecutor field.
func (e *StorageExecutor) SetSharedExecutor(shared bool) {
	e.sharedExecutor = shared
}

// Logger returns the bound *slog.Logger. Exposed so transient executors
// (e.g., per-transaction sessions cloned from a base) can inherit the
// configured logger without re-threading from main.
func (e *StorageExecutor) Logger() *slog.Logger { return e.logger() }

// SlowQueryThreshold returns the configured slow-query emission gate.
// Exposed so cloned executors inherit the threshold from their base.
func (e *StorageExecutor) SlowQueryThreshold() time.Duration { return e.slowQueryThreshold }

// SetCypherMetrics installs the Plan 04-03 CypherMetrics typed bag (MET-08)
// and the database label value passed on tenant-tagged families when D-08
// tenantLabelsEnabled=true. Mirrors the SetLogger / SetSlowQueryThreshold
// non-breaking pattern (D-01 non-breaking ctor).
//
// Also propagates the bag into the executor's owned planCache so the
// planner_cache_{hits,misses,size} families fire from QueryPlanCache.Get/Put
// without callers having to reach into private fields.
//
// Nil-safe: passing m=nil leaves observation as a no-op so tests and
// alternate constructors that don't wire metrics don't have to. The three
// observation chokepoints in Execute() guard on m == nil.
//
// Cloned executors inherit metrics + database via cloneWithStorage so the
// bag flows through per-query / per-tx scoped clones.
func (e *StorageExecutor) SetCypherMetrics(m *observability.CypherMetrics, database string) {
	e.metrics = m
	e.database = database
	// D-12a planner cache wiring: propagate into the owned planCache so
	// the cypher subsystem's planner_cache_{hits,misses,size} families
	// observe automatically.
	if e.planCache != nil {
		e.planCache.SetCypherMetrics(m)
	}
}

// SetCacheMetrics installs the Plan 04-01 cross-cutting CacheMetrics bag
// for D-12a query-result cache observation. Routes the bag into the owned
// SmartQueryCache so cache_hits_total{cache="query_result"} +
// cache_misses_total + cache_evictions_total emit on every Get/Put/Evict.
//
// Nil-safe; mirrors SetCypherMetrics shape.
func (e *StorageExecutor) SetCacheMetrics(m *observability.CacheMetrics) {
	if e.cache != nil {
		e.cache.SetCacheMetrics(m)
	}
}

// CypherMetrics returns the injected metrics bag (or nil if unset). Exposed
// so cloned executors can re-inject when constructed via newTxScopedExecutor
// outside the cloneWithStorage pathway.
func (e *StorageExecutor) CypherMetrics() *observability.CypherMetrics { return e.metrics }

// Database returns the configured database label value used for tenant-tagged
// Cypher metric observations (D-08).
func (e *StorageExecutor) Database() string { return e.database }

// observeQuery is the single Cypher-side observation helper. Called at the
// three RISK-1 corrected chokepoints in Execute():
//
//	Site 1 — admin dispatch       (op_type="admin",       observeDuration=true)
//	Site 2 — parse-error          (op_type="parse_error", observeDuration=false)
//	Site 3 — normal-path-after-Analyze (op_type from classifyOpType, observeDuration=true)
//
// Nil-safe: no-ops when e.metrics is nil. Hot-path-cheap: per-call Bind via
// the bag's BindQueryDuration helper (one WithLabelValues lookup); future
// optimization can hoist Bind into struct fields cached at SetCypherMetrics
// time per MET-25 — see RowsReturned for the precedent. The current shape
// keeps SetCypherMetrics simple while still emitting via the typed bag.
func (e *StorageExecutor) observeQuery(opType string, observeDuration bool, start time.Time) {
	if e.metrics == nil {
		return
	}
	e.metrics.BindQueries(opType, e.database).Inc()
	if observeDuration {
		e.metrics.BindQueryDuration(opType, e.database).Observe(context.Background(), time.Since(start).Seconds())
	}
}

// observeTransactionConflict is the D-16 chokepoint helper: storage detects
// (returns storage.ErrConflict from the engine), Cypher counts (here, in the
// transaction-wrapper site that surfaces ErrConflict to the caller). Storage
// layer never imports observability — preserves AGENTS.md §8 separation.
//
// Nil-safe: no-ops when e.metrics is nil OR err is not ErrConflict OR err is
// nil. Defensive: errors.Is check rather than equality so wrapped errors
// (fmt.Errorf("...: %w", storage.ErrConflict)) still classify correctly.
func (e *StorageExecutor) observeTransactionConflict(err error) {
	if e.metrics == nil || err == nil {
		return
	}
	if !errors.Is(err, storage.ErrConflict) {
		return
	}
	e.metrics.BindTransactionConflicts(e.database).Inc()
}

// observeTransactionBegin increments the active_transactions gauge. Pair
// with observeTransactionEnd at every Commit/Rollback site so the gauge
// balances to 0 across normal, abort, and panic paths.
func (e *StorageExecutor) observeTransactionBegin() {
	if e.metrics == nil {
		return
	}
	e.metrics.ActiveTransactions.Inc()
}

// observeTransactionEnd decrements the active_transactions gauge. See
// observeTransactionBegin.
func (e *StorageExecutor) observeTransactionEnd() {
	if e.metrics == nil {
		return
	}
	e.metrics.ActiveTransactions.Dec()
}

// observeSlowQueryIfThresholded increments the slow_queries counter when
// duration meets the configured slowQueryThreshold (matches the Phase 2
// D-04c emitSlowQueryLog gate semantics: zero or negative threshold
// disables emission entirely).
func (e *StorageExecutor) observeSlowQueryIfThresholded(duration time.Duration) {
	if e.metrics == nil {
		return
	}
	if e.slowQueryThreshold <= 0 || duration < e.slowQueryThreshold {
		return
	}
	e.metrics.BindSlowQueries(e.database).Inc()
}

// logger returns the bound logger, lazily installing a discard fallback if
// SetLogger was never called. Internal — every emission site must read the
// logger via this helper, never via the stdlib package-level default
// (LOG-09 forbids that path).
func (e *StorageExecutor) logger() *slog.Logger {
	if logger := e.log.Load(); logger != nil {
		return logger
	}
	fallback := slog.New(slog.NewTextHandler(io.Discard, nil)).With("component", "cypher")
	e.log.CompareAndSwap(nil, fallback)
	return e.log.Load()
}

// emitSlowQueryLog writes a single WARN record matching the LOG-07 schema
// when duration meets the configured threshold. RedactLiterals runs BEFORE
// truncation per D-04c so partial literals never leak via the truncation seam.
//
// Schema (D-04c):
//
//	level=WARN
//	msg="slow query"
//	event="slow_query"
//	plan_hash=<16-char hex; PlanHash(plan) when a plan tree is available,
//	           else StatementShapeHash of the redacted statement (NornicDB
//	           issue #563 defect 2 — see StatementShapeHash's doc comment: it is
//	           a statement-shape fingerprint, not a plan fingerprint)>
//	cypher.duration_ms=<int64 millisecond delta>
//	query=<RedactLiterals(query) truncated to 500 chars>
//
// Performance: PlanHash/StatementShapeHash + RedactLiterals only fire when
// this method is called, i.e., only when the executor's measured duration
// exceeded the configured threshold. The hot path (Execute fast return)
// never enters this method.
func (e *StorageExecutor) emitSlowQueryLog(ctx context.Context, query string, plan *ExecutionPlan, duration time.Duration) {
	if e.slowQueryThreshold <= 0 || duration < e.slowQueryThreshold {
		return
	}
	redacted := e.redactForLog(ctx, query)
	hash := PlanHash(plan)
	if plan == nil || plan.Root == nil {
		// The normal (non-EXPLAIN/PROFILE) Execute() path never builds an
		// ExecutionPlan tree, so PlanHash would otherwise always collapse to
		// the zero placeholder here. Hash on statement shape instead so
		// distinct query shapes are still distinguishable in the log.
		hash = StatementShapeHash(redacted)
	}
	if len(redacted) > 500 {
		redacted = truncateRuneSafe(redacted, 500)
	}
	e.logEvent(slog.LevelWarn, localization.CypherSlowQueryEvent(
		hash,
		duration.Milliseconds(),
		redacted,
	))
}

// SetDatabaseManager sets the database manager for system commands.
// When set, enables CREATE DATABASE, DROP DATABASE, and SHOW DATABASES commands.
//
// Example:
//
//	executor := cypher.NewStorageExecutor(storage)
//	executor.SetDatabaseManager(dbManager)
//	// Now CREATE DATABASE, DROP DATABASE, SHOW DATABASES work
func (e *StorageExecutor) SetDatabaseManager(dbManager DatabaseManagerInterface) {
	e.dbManager = dbManager
}

// SetEmbedder sets the query embedder for server-side embedding.
// When set, db.index.vector.queryNodes can accept string queries
// which are automatically embedded before search.
//
// Example:
//
//	executor := cypher.NewStorageExecutor(storage)
//	executor.SetEmbedder(embedder)
//
//	// Now vector search accepts both:
//	// CALL db.index.vector.queryNodes('idx', 10, [0.1, 0.2, ...])  // Vector
//	// CALL db.index.vector.queryNodes('idx', 10, 'search query')   // String (auto-embedded)
func (e *StorageExecutor) SetEmbedder(embedder QueryEmbedder) {
	if e.queryEmbedder == nil {
		e.queryEmbedder = &QueryEmbedderBinding{}
	}
	e.queryEmbedder.Store(embedder)
}

// SetSearchService sets the unified search service used by Cypher procedures.
// When set, db.index.vector.queryNodes will delegate to search.Service.
func (e *StorageExecutor) SetSearchService(svc *search.Service) {
	e.searchService = svc
}

// SearchServiceResolver returns a database's current search service, or nil
// when it has none.
type SearchServiceResolver func(database string) *search.Service

// SetSearchServiceResolver has the executor resolve database's search service
// on each use instead of keeping one (SetSearchService). Executors it is
// cloned into for another database (USE, composite constituents) resolve that
// database's service.
func (e *StorageExecutor) SetSearchServiceResolver(database string, resolve SearchServiceResolver) {
	e.searchResolver = resolve
	e.searchDatabase = database
}

// search returns the search service for this statement's database.
func (e *StorageExecutor) search() *search.Service {
	if e.searchResolver != nil {
		return e.searchResolver(e.searchDatabase)
	}
	return e.searchService
}

// keepUnmanagedSearchService keeps a service a procedure created because the
// executor had none. An executor no database wired (no resolver) keeps it for
// its later statements, as there is no owner to reset it. One whose database
// has no search does not: it never shares a service the database's owner
// cannot reach, and the service (which starts no worker until it is built)
// lives for this statement only.
func (e *StorageExecutor) keepUnmanagedSearchService(svc *search.Service) {
	if e.searchResolver == nil {
		e.SetSearchService(svc)
	}
}

// shareSearchFor gives target the search of database: the resolver, for the
// named database, when this executor resolves; otherwise this executor's
// service, as before resolvers.
func (e *StorageExecutor) shareSearchFor(target *StorageExecutor, database string) {
	if e.searchResolver != nil && database != "" {
		target.searchResolver = e.searchResolver
		target.searchDatabase = database
		return
	}
	target.searchService = e.searchService
	target.searchResolver = e.searchResolver
	target.searchDatabase = e.searchDatabase
}

// SetInferenceManager sets the inference manager used by db.infer.
func (e *StorageExecutor) SetInferenceManager(mgr InferenceManager) {
	e.inferenceManager = mgr
}

// GetInferenceManager returns the configured inference manager.
func (e *StorageExecutor) GetInferenceManager() InferenceManager {
	return e.inferenceManager
}

// SetVectorRegistry allows wiring a shared index registry (e.g., per database).
// Defaults to an internal registry when not set.
func (e *StorageExecutor) SetVectorRegistry(reg *vectorspace.IndexRegistry) {
	if reg == nil {
		reg = vectorspace.NewIndexRegistry()
	}
	e.vectorRegistry = reg
}

// GetVectorRegistry exposes the current registry (for tests and adapters).
func (e *StorageExecutor) GetVectorRegistry() *vectorspace.IndexRegistry {
	return e.vectorRegistry
}

// GetEmbedder returns the current query embedder, or nil during startup.
// Scoped executors should use ShareEmbedderFrom to observe later readiness.
func (e *StorageExecutor) GetEmbedder() QueryEmbedder {
	if state := e.currentQueryEmbedder(); state != nil {
		return state.embedder
	}
	return nil
}

// SetNodeMutatedCallback sets a callback that is invoked when nodes are created
// or mutated (CREATE, MERGE, SET, REMOVE, or procedures that update nodes).
// This allows the embed queue to be notified so embeddings can be (re)generated.
//
// Example:
//
//	executor := cypher.NewStorageExecutor(storage)
//	executor.SetNodeMutatedCallback(func(nodeID string) {
//	    embedQueue.Enqueue(nodeID)
//	})
func (e *StorageExecutor) SetNodeMutatedCallback(cb NodeMutatedCallback) {
	e.onNodeMutated = cb
}

// SetDefaultEmbeddingDimensions sets the default dimensions for vector indexes.
// This is used when CREATE VECTOR INDEX doesn't specify dimensions in OPTIONS.
func (e *StorageExecutor) SetDefaultEmbeddingDimensions(dims int) {
	e.defaultEmbeddingDimensions = dims
}

// GetDefaultEmbeddingDimensions returns the configured default embedding dimensions.
// Returns 1024 as fallback if not configured.
func (e *StorageExecutor) GetDefaultEmbeddingDimensions() int {
	return e.defaultEmbeddingDimensions
}

// notifyNodeMutated updates live search metadata and calls the onNodeMutated
// callback if set. Call after any node creation or mutation (CREATE, MERGE,
// SET, REMOVE) so search sees client-supplied vectors immediately and the
// embed queue can re-process.
//
// Search reads the node itself after reserving the refresh, so a later write or
// delete that commits first is not overwritten by this notification.
func (e *StorageExecutor) notifyNodeMutated(nodeID string) {
	e.refreshSearch(storage.NodeID(nodeID), "")
	if e.onNodeMutated != nil {
		e.onNodeMutated(nodeID)
	}
}

// notifyEdgeMutated updates live search metadata after a relationship create or
// mutation so relationship vector queries can use client-supplied vectors before
// a full search warmup/build has run. Call it after deleting one too, so its
// vectors leave search.
func (e *StorageExecutor) notifyEdgeMutated(edgeID string) {
	e.refreshSearch("", storage.EdgeID(edgeID))
}

// refreshSearch has search read a node or relationship this statement changed.
// Inside a transaction the change is not visible yet: the transaction keeps
// it until its commit (refreshSearchAfterCommit), and drops it on rollback.
func (e *StorageExecutor) refreshSearch(node storage.NodeID, edge storage.EdgeID) {
	if node == "" && edge == "" {
		return
	}
	if tx, ok := e.storage.(*transactionStorageWrapper); ok {
		if e.searchResolver != nil || e.searchService != nil {
			tx.deferSearchRefresh(node, edge)
		}
		return
	}
	svc := e.search()
	if svc == nil {
		return
	}
	if node != "" {
		_ = svc.RefreshNode(node)
	}
	if edge != "" {
		_ = svc.RefreshEdge(edge)
	}
}

// refreshSearchAfterCommit refreshes what the committed transaction changed.
func (e *StorageExecutor) refreshSearchAfterCommit(tx *transactionStorageWrapper) {
	nodes, edges := tx.takeSearchRefreshes()
	svc := e.search()
	if svc == nil {
		return
	}
	for id := range nodes {
		_ = svc.RefreshNode(id)
	}
	for id := range edges {
		_ = svc.RefreshEdge(id)
	}
}

// removeNodeFromSearch refreshes a deleted node in the search service (vector/fulltext
// indexes), which removes it. Call after successfully deleting a node via Cypher so
// embeddings are not left orphaned.
// nodeID may be prefixed (e.g. "nornic:xyz") or local ("xyz"); the search service expects local ID.
func (e *StorageExecutor) removeNodeFromSearch(nodeID string) {
	localID := nodeID
	if _, unprefixed, ok := storage.ParseDatabasePrefix(nodeID); ok {
		localID = unprefixed
	}
	e.refreshSearch(storage.NodeID(localID), "")
}

// Flush persists all pending writes to storage.
// This implements FlushableExecutor for Bolt-level deferred commits.
// Writes are committed synchronously by their transactions; there is no
// buffered write cache to flush.
func (e *StorageExecutor) Flush() error {
	return nil
}

// SetDeferFlush enables/disables deferred flush mode.
// When enabled, writes are not auto-flushed - the Bolt layer calls Flush().
func (e *StorageExecutor) SetDeferFlush(enabled bool) {
	e.deferFlush = enabled
}

// queryDeletesNodes returns true if the query deletes nodes.
// Returns false for relationship-only deletes (CREATE rel...DELETE rel pattern).
func queryDeletesNodes(query string) bool {
	// DETACH DELETE always deletes nodes
	if strings.Contains(upperASCII(query), "DETACH DELETE") {
		return true
	}
	// Relationship pattern (has -[...]-> or <-[...]-) with CREATE+DELETE = relationship delete only
	if strings.Contains(query, "]->(") || strings.Contains(query, ")<-[") {
		return false
	}
	return true
}

// trimTrailingStatementDelimiters removes one optional trailing Cypher statement
// delimiter (';') and whitespace, leaving any additional semicolon for validation.
// This mirrors Neo4j-compatible client behavior where a final semicolon is optional.
func trimTrailingStatementDelimiters(query string) string {
	s := strings.TrimSpace(query)
	if strings.HasSuffix(s, ";") {
		s = strings.TrimSpace(strings.TrimSuffix(s, ";"))
	}
	return s
}

func normalizeCypherSyntaxConfusables(query string) string {
	if query == "" {
		return query
	}
	// Fast path: common ASCII-only Cypher text has no confusables to normalize.
	if isLikelyPlainASCIICypher(query) {
		return query
	}

	runes := []rune(query)
	var builder strings.Builder
	builder.Grow(len(query) + 8)
	changed := false
	for i := 0; i < len(runes); i++ {
		if end, quoted := cyphertext.SkipTokenRunes(runes, i); quoted {
			for _, character := range runes[i:end] {
				builder.WriteRune(character)
			}
			i = end - 1
			continue
		}
		r := runes[i]

		if replacement, ok := cypherArrowReplacement(runes, i); ok {
			builder.WriteByte(replacement)
			changed = true
			continue
		}

		if replacement, ok := cypherSyntaxConfusableReplacement(r); ok {
			builder.WriteString(replacement)
			changed = changed || replacement != string(r)
			continue
		}

		if replacement, ok := cypherWhitespaceReplacement(r); ok {
			builder.WriteRune(replacement)
			changed = changed || replacement != r
			continue
		}

		if isIgnorableCypherFormatRune(r) {
			changed = true
			continue
		}

		builder.WriteRune(r)
	}

	if !changed {
		return query
	}

	return builder.String()
}

func isLikelyPlainASCIICypher(query string) bool {
	for i := 0; i < len(query); i++ {
		if query[i] >= 0x80 {
			return false
		}
	}
	return true
}

// ensureUpperQueryCache lazily installs the upper-query cache pointer with
// sync.Once so concurrent CALL { ... } subqueries cannot race on the
// pointer assignment. The cache itself is mutex-guarded for entry access.
func (e *StorageExecutor) ensureUpperQueryCache() *upperQueryCache {
	e.upperQueryCacheOnce.Do(func() {
		if e.upperQueryCache == nil {
			e.upperQueryCache = newUpperQueryCache()
		}
	})
	return e.upperQueryCache
}

func cypherSyntaxConfusableReplacement(r rune) (string, bool) {
	switch r {
	case '→':
		return "->", true
	case '←':
		return "<-", true
	case '（':
		return "(", true
	case '）':
		return ")", true
	case '［':
		return "[", true
	case '］':
		return "]", true
	case '｛':
		return "{", true
	case '｝':
		return "}", true
	case '，':
		return ",", true
	case '：':
		return ":", true
	case '；':
		return ";", true
	case '．':
		return ".", true
	case '＝':
		return "=", true
	case '＜':
		return "<", true
	case '＞':
		return ">", true
	case '＄':
		return "$", true
	default:
		return "", false
	}
}

// cypherArrowReplacement is the ASCII form of runes[i] when it is a Unicode
// dash or arrowhead in a relationship arrow, as Neo4j's lexer reads them:
// ‐ ‑ ‒ – — ― ﹘ ﹣ － and the soft hyphen as -, ⟨ 〈 ﹤ before a dash as <,
// ⟩ 〉 ﹥ after one as >. A dash is in an arrow when it follows a node, a
// relationship, a head or another dash and precedes one of those:
// (a)—[r]—>(b), (a)<—(b). Elsewhere they aren't operators (RETURN 2—1 is
// rejected by validateUnicodeOperators) and the soft hyphen is part of a
// name.
func cypherArrowReplacement(runes []rune, i int) (byte, bool) {
	neighbour := func(step int) rune {
		for j := i + step; j >= 0 && j < len(runes); j += step {
			if !unicode.IsSpace(runes[j]) {
				return runes[j]
			}
		}
		return 0
	}
	switch r := runes[i]; {
	case isArrowDashRune(r):
		previous, next := neighbour(-1), neighbour(1)
		before := previous == ')' || previous == ']' || previous == '<' || previous == '-' || isArrowDashRune(previous) || isArrowLeftHeadRune(previous)
		after := next == '(' || next == '[' || next == '>' || next == '-' || isArrowDashRune(next) || isArrowRightHeadRune(next)
		return '-', before && after
	case isArrowLeftHeadRune(r):
		next := neighbour(1)
		return '<', next == '-' || isArrowDashRune(next)
	case isArrowRightHeadRune(r):
		previous := neighbour(-1)
		return '>', previous == '-' || isArrowDashRune(previous)
	}
	return 0, false
}

func isArrowDashRune(r rune) bool {
	switch r {
	case '\u00AD', '‐', '‑', '‒', '–', '—', '―', '﹘', '﹣', '－':
		return true
	}
	return false
}

func isArrowLeftHeadRune(r rune) bool {
	return r == '⟨' || r == '〈' || r == '﹤' || r == '＜'
}

func isArrowRightHeadRune(r rune) bool {
	return r == '⟩' || r == '〉' || r == '﹥' || r == '＞'
}

func cypherWhitespaceReplacement(r rune) (rune, bool) {
	switch r {
	case '\u0085', '\u2028', '\u2029':
		return '\n', true
	case ' ', '\t', '\n', '\r':
		return 0, false
	default:
		if unicode.IsSpace(r) {
			return ' ', true
		}
		return 0, false
	}
}

func isIgnorableCypherFormatRune(r rune) bool {
	switch r {
	case '\u200B', '\u200C', '\u200D', '\u2060', '\uFEFF':
		return true
	default:
		return false
	}
}

// TransactionCapableEngine is an engine that supports ACID transactions.
// Used for type assertion to wrap implicit writes in rollback-capable transactions.
type TransactionCapableEngine interface {
	BeginTransaction() (*storage.BadgerTransaction, error)
}

type implicitTxEngines struct {
	txEngine  TransactionCapableEngine
	namespace string
}

func (e *StorageExecutor) resolveImplicitTxEngines() implicitTxEngines {
	engine := e.storage
	visited := make(map[storage.Engine]bool)
	out := implicitTxEngines{}

	for engine != nil && !visited[engine] {
		visited[engine] = true

		if out.namespace == "" {
			if ns, ok := engine.(interface{ Namespace() string }); ok {
				out.namespace = ns.Namespace()
			}
		}
		if out.txEngine == nil {
			if tc, ok := engine.(TransactionCapableEngine); ok {
				out.txEngine = tc
			}
		}

		switch wrapper := engine.(type) {
		case storage.EngineUnwrapper:
			engine = wrapper.GetInnerEngine()
		default:
			engine = nil
		}
	}

	return out
}

// executeImplicitAsync executes a single query using implicit transactions for writes.
// For write operations, wraps execution in an implicit transaction that can be
// rolled back on error, preventing partial data corruption from failed queries.
// For strict ACID guarantees with durability, use explicit BEGIN/COMMIT transactions.
func (e *StorageExecutor) executeImplicitAsync(ctx context.Context, cypher string, upperQuery string) (*ExecuteResult, error) {
	// A public procedure callback may re-enter Execute with the statement's
	// transaction in its executor, context, or both. Reuse that owner rather
	// than committing a nested implicit transaction independently.
	if statementStorage, ok := e.getStorage(ctx).(*transactionStorageWrapper); ok {
		statementExec := e
		if e.storage != statementStorage {
			statementExec = e.cloneWithStorage(statementStorage)
		}
		return statementExec.executeWithoutTransaction(ctx, cypher, upperQuery)
	}
	// Check if this is a write operation using cached analysis
	info := e.analyzer.Analyze(ctx, cypher)
	needsTransaction, err := statementNeedsTransaction(ctx, cypher)
	if err != nil {
		return nil, err
	}
	// Fabric owns this statement's lifetime. Actual writes have already passed
	// the resolved execution gate; conditional reads must not open a second tx.
	if _, fabricOwned := ctx.Value(dynamicWriteAdmissionKey{}).(dynamicWriteAdmission); fabricOwned {
		return e.executeWithoutTransaction(ctx, cypher, upperQuery)
	}

	// For write operations, use implicit transaction for atomicity
	// This ensures partial writes are rolled back on error
	if needsTransaction {
		return e.executeWithImplicitTransaction(ctx, cypher, upperQuery)
	}

	// Read-only operations don't need transaction wrapping. One that cannot
	// write reads its row nodes without vectors, on a clone so concurrent
	// statements of this executor keep their own reads.
	if e.readsQueryNodesWithoutVectors(info) {
		readExec := e.cloneWithStorage(e.storage)
		readExec.readOnlyQueryNodes = true
		return readExec.executeWithoutTransaction(ctx, cypher, upperQuery)
	}
	return e.executeWithoutTransaction(ctx, cypher, upperQuery)
}

// statementNeedsTransaction keeps write clauses and registered WRITE procedures
// under the same statement rollback owner. tx.setMetaData also needs a transaction.
func statementNeedsTransaction(ctx context.Context, cypher string) (bool, error) {
	contract, err := readStatementExecutionContract(ctx, cypher)
	return contract.transaction, err
}

// executeWithImplicitTransaction wraps a write query in a single implicit
// transaction. Commit-time conflicts are returned to the caller; retry-aware
// clients own any replay decision because NornicDB does not know whether a
// conflict is recoverable for the application.
func (e *StorageExecutor) executeWithImplicitTransaction(ctx context.Context, cypher string, upperQuery string) (*ExecuteResult, error) {
	executionCypher, executionUpperQuery := cypher, upperQuery
	if parsedCypher, inlineEmbeddingEnabled := stripWithEmbeddingSuffix(cypher); inlineEmbeddingEnabled {
		executionCypher = parsedCypher
		executionUpperQuery = upperASCII(parsedCypher)
	}
	return e.executeWithImplicitTransactionCallback(ctx, cypher, upperQuery, func(txCtx context.Context, txExec *StorageExecutor) (*ExecuteResult, error) {
		return txExec.executeWithoutTransaction(txCtx, executionCypher, executionUpperQuery)
	})
}

func (e *StorageExecutor) executeWithImplicitTransactionCallback(ctx context.Context, cypher string, upperQuery string, execute func(context.Context, *StorageExecutor) (*ExecuteResult, error)) (result *ExecuteResult, retErr error) {
	parsedCypher, inlineEmbeddingEnabled := stripWithEmbeddingSuffix(cypher)
	if inlineEmbeddingEnabled {
		cypher = parsedCypher
		upperQuery = upperASCII(cypher)
	}

	// Try to get a transaction-capable engine and async wrapper (if present)
	engines := e.resolveImplicitTxEngines()
	if engines.namespace == "" {
		if dbName := strings.TrimSpace(GetUseDatabaseFromContext(ctx)); dbName != "" {
			engines.namespace = dbName
		} else if _, dbName := e.resolveWALAndDatabase(); strings.TrimSpace(dbName) != "" {
			engines.namespace = strings.TrimSpace(dbName)
		}
	}
	txEngine := engines.txEngine

	// If no transaction support, fall back to direct execution (legacy mode)
	// This is less safe but maintains backward compatibility
	if txEngine == nil {
		if inlineEmbeddingEnabled {
			return nil, localizedError(localization.CypherCoreEmbeddingTransactionStorageRequired(), nil)
		}
		result, err := execute(ctx, e)
		if err == nil {
			// Legacy engines apply writes directly; successful execution is
			// their publication boundary, with no pending transaction.
			e.publishDirectStatementCommit(ctx, cypher)
		}
		return result, err
	}

	// Start implicit transaction
	if engines.namespace != "" {
		if primer, ok := txEngine.(interface{ EnsureNamespaceMVCC(string) error }); ok {
			if err := primer.EnsureNamespaceMVCC(engines.namespace); err != nil {
				return nil, localizedError(localization.CypherCoreImplicitTransactionPrimeFailed(err), err)
			}
		}
	}
	tx, err := beginTransactionSnapshot(txEngine)
	if err != nil {
		return nil, localizedError(localization.CypherCoreImplicitTransactionStartFailed(err), err)
	}
	if engines.namespace != "" {
		if err := tx.SetNamespace(engines.namespace); err != nil {
			_ = tx.Rollback()
			return nil, localizedError(localization.CypherCoreImplicitTransactionPinFailed(err), err)
		}
	}
	if err := applyTransactionMetadata(ctx, tx); err != nil {
		_ = tx.Rollback()
		return nil, err
	}

	// Defer constraint validation to commit for implicit transactions.
	// This avoids duplicate per-operation checks and improves write throughput.
	if err := tx.SetDeferredConstraintValidation(true); err != nil {
		_ = tx.Rollback()
		return nil, localizedError(localization.CypherCoreImplicitTransactionConfigureFailed(err), err)
	}
	if err := tx.SetSkipCreateExistenceCheck(true); err != nil {
		_ = tx.Rollback()
		return nil, localizedError(localization.CypherCoreImplicitTransactionConfigureFailed(err), err)
	}
	// Skip the per-commit engine.Sync(). The Bolt session's end-of-session
	// Flush and the async engine's ticker-driven flush coalesce durability
	// for implicit writes; forcing an Msync per UNWIND batch turned every
	// batch into a 300µs syscall for no user-visible benefit.
	if err := tx.SetImplicit(true); err != nil {
		_ = tx.Rollback()
		return nil, localizedError(localization.CypherCoreImplicitTransactionConfigureFailed(err), err)
	}

	// Optional WAL transaction markers for receipts.
	var wal *storage.WAL
	var walSeqStart uint64
	txID := tx.ID
	var dbName string
	if txID != "" {
		wal, dbName = e.resolveWALAndDatabase()
		if wal != nil {
			walSeqStart, err = wal.AppendTxBegin(dbName, txID, nil)
			if err != nil {
				_ = tx.Rollback()
				return nil, localizedError(localization.CypherCoreImplicitTransactionWALBeginFailed(err), err)
			}
		}
	}

	// Create a transactional wrapper that routes writes through the transaction
	// CRITICAL: We pass the wrapper through context instead of modifying e.storage
	// because e.storage modification is NOT thread-safe for concurrent executions.
	separator := ":"
	if engines.namespace == "" {
		separator = ""
	}
	txWrapper := &transactionStorageWrapper{
		tx:             tx,
		underlying:     e.storage,
		namespace:      engines.namespace,
		separator:      separator,
		mutatedNodeIDs: make(map[string]struct{}),
	}
	txWrapper.initNamespacePrefix()

	ctx, statsScope := beginProcedureStatementStatsScope(ctx)
	defer func() {
		if retErr == nil {
			var batchStats *QueryStats
			if result != nil {
				batchStats = result.Stats
			}
			statsScope.commit(batchStats)
		} else {
			statsScope.discard()
		}
	}()

	// Execute with transaction wrapper via context
	txCtx := context.WithValue(ctx, ctxKeyTxStorage, txWrapper)
	txExec := e.cloneWithStorage(txWrapper)

	// Execute the query
	result, execErr := execute(txCtx, txExec)
	// An expression error recorded while the statement ran is its error, so
	// nothing it wrote is committed.
	if execErr == nil {
		execErr = getExpressionFailure(txCtx)
	}
	// So is a memory limit it went over, whichever route ignored the
	// cancellation that caused (#1343).
	if execErr == nil {
		execErr = memoryFailureFromContext(txCtx)
	}

	// Handle result
	if execErr != nil {
		// Rollback on any error - prevents partial data corruption
		tx.Rollback()
		txExec.invalidateNodeLookupCache()
		if wal != nil && walSeqStart > 0 {
			_, _ = wal.AppendTxAbort(dbName, txID, execErr.Error())
		}
		return result, execErr
	}

	// A write-shaped query can legitimately match no mutation targets. Committing
	// an empty Badger transaction still performs store-wide validation work, so
	// roll it back after the match has completed instead.
	if tx.OperationCount() == 0 && !tx.HasKnowledgePolicyChanges() && !tx.RequiresCommitValidation() {
		_ = tx.Rollback()
		if wal != nil && walSeqStart > 0 {
			_, _ = wal.AppendTxAbort(dbName, txID, "no mutations")
		}
		return result, nil
	}

	if inlineEmbeddingEnabled {
		if err := txExec.applyInlineEmbeddingMutations(txCtx, txWrapper.snapshotMutatedNodeIDs()); err != nil {
			tx.Rollback()
			txExec.invalidateNodeLookupCache()
			if wal != nil && walSeqStart > 0 {
				_, _ = wal.AppendTxAbort(dbName, txID, err.Error())
			}
			return nil, err
		}
	}

	// A statement TERMINATE TRANSACTIONS ended doesn't commit (#718).
	if running, ok := ctx.Value(ctxKeyRunningTransaction{}).(*runningTransaction); ok && running.terminated.Load() {
		tx.Rollback()
		txExec.invalidateNodeLookupCache()
		if wal != nil && walSeqStart > 0 {
			_, _ = wal.AppendTxAbort(dbName, txID, "terminated")
		}
		return nil, transactionTerminatedError()
	}

	// Commit successful transaction. The statement's context makes commit-time
	// validation stop when the statement is terminated or its client goes away
	// (#1115); the deferred handler in Execute reports Transaction.Terminated.
	if err := e.commitStorageTransaction(ctx, tx); err != nil {
		txExec.invalidateNodeLookupCache()
		if wal != nil && walSeqStart > 0 {
			_, _ = wal.AppendTxAbort(dbName, txID, err.Error())
		}
		if info := e.analyzer.Analyze(ctx, cypher); IsRetrySafeMergeCommitQuery(info) && MergeUniqueConflictIsRetrySafe([]CommitStatement{{Query: cypher, Params: getParamsFromContext(ctx)}}, err) {
			err = nornicerrors.MarkMergeCommitTimeUniqueConflict(err)
		}
		// Wire contract: substring "commit failed" is matched by downstream Bolt classifiers.
		// See docs/plans/consumer-pinned-error-contract-plan.md §2.1.
		// The implicit-autocommit path was historically wrapped with "failed to commit
		// implicit transaction: ..." which broke the consumer-pinned classifier; aligned
		// with pkg/cypher/transaction.go:181 so the explicit and implicit paths produce the
		// same wire shape.
		return nil, localizedError(localization.CypherCoreImplicitTransactionCommitFailed(err), err)
	}
	txExec.refreshSearchAfterCommit(txWrapper)

	// Attach receipt metadata if WAL markers were recorded. Receipts are
	// attached exactly as on the durable path: the write-behind ACK carries
	// the same information (its commit markers are appended before the ACK
	// per the buffer design). The eventual marker below is how the HTTP
	// layer tells an acknowledged buffered commit from a durable one.
	if wal != nil && walSeqStart > 0 {
		opCount := tx.OperationCount()
		if commitSeq, walErr := wal.AppendTxCommit(dbName, txID, opCount); walErr == nil {
			if receipt, recErr := storage.NewReceipt(txID, walSeqStart, commitSeq, dbName, time.Now().UTC()); recErr == nil {
				if result.Metadata == nil {
					result.Metadata = make(map[string]interface{})
				}
				result.Metadata["receipt"] = receipt
			}
		}
	}

	// Mark commits that were acknowledged through the write-behind buffer.
	// Every eligible write buffers when the engine has it enabled; this
	// marker is what makes the server answer 202 Accepted instead of 200.
	if tx.AcknowledgedBuffered() {
		if result.Metadata == nil {
			result.Metadata = make(map[string]interface{})
		}
		result.Metadata["eventual"] = true
	}

	// Promote the tx-scoped MERGE lookup cache into the parent so
	// subsequent Execute calls still benefit from the cross-query
	// speedup. Tx isolation is preserved because each in-flight tx had
	// its own clone; only post-commit entries graduate to the parent.
	txExec.promoteNodeLookupCacheTo(e)

	return result, nil
}

// ctxKeyTxStorage is the context key for transaction storage wrapper.
type ctxKeyTxStorageType struct{}

var ctxKeyTxStorage = ctxKeyTxStorageType{}

func (e *StorageExecutor) applyInlineEmbeddingMutations(ctx context.Context, ids map[string]struct{}) error {
	if len(ids) == 0 {
		return nil
	}
	ctx, finish, err := e.queryEmbedder.BeginUse(ctx)
	if err != nil {
		return err
	}
	defer finish()
	embedder := e.queryEmbedderForStatement(ctx)
	if embedder == nil {
		return localizedError(localization.CypherCoreEmbeddingConfiguredRequired(), nil)
	}
	store := e.getStorage(ctx)
	typedEmbedder, hasTypedEmbedder := embedder.(typedQueryEmbedder)
	for id := range ids {
		node, err := store.GetNode(storage.NodeID(id))
		if err != nil {
			if err == storage.ErrNotFound {
				continue
			}
			return err
		}
		if node == nil {
			continue
		}
		source := embeddingutil.BuildEmbedText(node.Properties, node.Labels, e.inlineEmbeddingTextOptions)
		text := source.Text
		chunks, err := embedder.ChunkText(text, e.inlineEmbeddingChunkSize, e.inlineEmbeddingChunkOverlap)
		if err != nil {
			return localizedError(localization.CypherCoreEmbeddingChunkFailed(id, err), err)
		}
		if len(chunks) == 0 {
			chunks = []string{text}
		}
		embeddings := make([][]float32, 0, len(chunks))
		for _, chunk := range chunks {
			var emb []float32
			var err error
			if hasTypedEmbedder {
				emb, err = typedEmbedder.EmbedWithInputType(ctx, chunk, "document")
			} else {
				emb, err = embedder.Embed(ctx, chunk)
			}
			if err != nil {
				return localizedError(localization.CypherCoreEmbeddingNodeFailed(id, err), err)
			}
			if len(emb) == 0 {
				return localizedError(localization.CypherCoreEmbeddingEmptyVector(id), nil)
			}
			embeddings = append(embeddings, emb)
		}
		model := "inline-cypher"
		dimensions := len(embeddings[0])
		if named, ok := embedder.(interface{ Model() string }); ok {
			if v := strings.TrimSpace(named.Model()); v != "" {
				model = v
			}
		}
		if d, ok := embedder.(interface{ Dimensions() int }); ok {
			if v := d.Dimensions(); v > 0 {
				dimensions = v
			}
		}
		embeddingutil.ApplyManagedEmbedding(node, embeddings, model, dimensions, time.Now())
		embeddingutil.RecordChunkSpans(node, source, chunks)
		if err := store.UpdateNode(node); err != nil {
			return err
		}
	}
	return nil
}

func stripWithEmbeddingSuffix(cypher string) (string, bool) {
	idx := findKeywordIndex(cypher, "WITH EMBEDDING")
	if idx < 0 {
		return cypher, false
	}
	before := strings.TrimSpace(cypher[:idx])
	after := strings.TrimSpace(cypher[idx+len("WITH EMBEDDING"):])
	if before == "" {
		return cypher, false
	}
	if after == "" {
		return before, true
	}
	return strings.TrimSpace(before + " " + after), true
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

// ctxKeyUseDatabase is the context key for :USE database switching.
// When :USE database_name is detected, the database name is stored in context
// so the server can switch to that database before executing the query.
type ctxKeyUseDatabaseType struct{}

var ctxKeyUseDatabase = ctxKeyUseDatabaseType{}

// ctxKeyAuthToken carries an Authorization header value for remote/OIDC forwarding.
type ctxKeyAuthTokenType struct{}

var ctxKeyAuthToken = ctxKeyAuthTokenType{}

type ctxKeyAuthenticatedPrincipalType struct{}

var ctxKeyAuthenticatedPrincipal = ctxKeyAuthenticatedPrincipalType{}

// GetUseDatabaseFromContext extracts the database name from :USE command if present in context.
// Returns empty string if no :USE command was found.
func GetUseDatabaseFromContext(ctx context.Context) string {
	if dbName, ok := ctx.Value(ctxKeyUseDatabase).(string); ok {
		return dbName
	}
	return ""
}

// WithAuthToken stores an Authorization header token on context for execution paths
// that need to forward caller identity across remote constituents.
func WithAuthToken(ctx context.Context, authToken string) context.Context {
	if strings.TrimSpace(authToken) == "" {
		return ctx
	}
	return context.WithValue(ctx, ctxKeyAuthToken, authToken)
}

// GetAuthTokenFromContext extracts forwarded Authorization token from context.
func GetAuthTokenFromContext(ctx context.Context) string {
	if v, ok := ctx.Value(ctxKeyAuthToken).(string); ok {
		return v
	}
	return ""
}

// WithAuthenticatedPrincipal attaches an identity produced by successful authentication.
func WithAuthenticatedPrincipal(ctx context.Context, principal string) context.Context {
	if strings.TrimSpace(principal) == "" {
		return ctx
	}
	return context.WithValue(ctx, ctxKeyAuthenticatedPrincipal, principal)
}

// GetAuthenticatedPrincipalFromContext returns the trusted caller identity.
func GetAuthenticatedPrincipalFromContext(ctx context.Context) string {
	if value, ok := ctx.Value(ctxKeyAuthenticatedPrincipal).(string); ok {
		return value
	}
	return ""
}

// getStorage returns the storage to use for the current execution.
// If a transaction wrapper is present in context, it uses that; otherwise uses e.storage.
func (e *StorageExecutor) getStorage(ctx context.Context) storage.Engine {
	if txWrapper, ok := ctx.Value(ctxKeyTxStorage).(*transactionStorageWrapper); ok {
		return txWrapper
	}
	return e.storage
}

// resolveWALAndDatabase attempts to find a WAL instance and database name
// by unwrapping common storage wrappers (namespaced, async, WAL engines).
func (e *StorageExecutor) resolveWALAndDatabase() (*storage.WAL, string) {
	engine := e.storage
	var dbName string
	// Wrapper chains are short (a handful of decorators); a depth cap makes
	// the cycle guard unnecessary and keeps this hot path allocation-free.
	const maxDepth = 16
	for depth := 0; engine != nil && depth < maxDepth; depth++ {
		if ns, ok := engine.(interface{ Namespace() string }); ok && dbName == "" {
			dbName = ns.Namespace()
		}
		if walProvider, ok := engine.(interface{ GetWAL() *storage.WAL }); ok {
			return walProvider.GetWAL(), dbName
		}
		switch wrapper := engine.(type) {
		case storage.EngineUnwrapper:
			engine = wrapper.GetInnerEngine()
		default:
			return nil, dbName
		}
	}

	return nil, dbName
}

// statementAccessesGraph reports whether a statement reads or writes graph
// data: a pattern clause (MATCH, CREATE, MERGE, …), a write clause, a
// procedure call or LOAD CSV. A statement of only UNWIND / WITH / RETURN
// over values doesn't.
func statementAccessesGraph(info *QueryInfo) bool {
	return info.HasMatch || info.HasOptionalMatch || info.HasCreate || info.HasMerge ||
		info.HasDelete || info.HasDetachDelete || info.HasSet || info.HasRemove ||
		info.HasForeach || info.HasLoadCSV || info.HasShortestPath || info.HasCall ||
		info.HasShow || info.HasSchema
}

// statementAccessesGraphText conservatively reports whether a statement reads
// or writes graph data, scanning the text itself with the shared keyword
// scanner. The composite-root guard uses it instead of the caching analyzer:
// the analyzer's clause flags missed pattern comprehensions
// (`[(n)-->(m) | …]`) and pattern subqueries (`COUNT { }`, `EXISTS { }`,
// `EXISTS((n)-->(m))`), which read constituent data on a composite root. The
// direction is safe by construction: a false positive only forces the caller
// to target a constituent (and pass its authorization), while a false
// negative would read denied data.
func statementAccessesGraphText(cypher string) bool {
	opts := defaultKeywordScanOpts()
	for _, keyword := range []string{
		"MATCH", "OPTIONAL MATCH", "CREATE", "MERGE", "DELETE", "DETACH DELETE",
		"SET", "REMOVE", "FOREACH", "LOAD CSV", "CALL", "SHOW", "CREATE INDEX",
		"CREATE RANGE INDEX", "CREATE FULLTEXT INDEX", "CREATE VECTOR INDEX",
		"CREATE CONSTRAINT", "DROP INDEX", "DROP CONSTRAINT",
	} {
		if keywordIndexFrom(cypher, keyword, 0, opts) >= 0 {
			return true
		}
	}
	return expressionReadsGraphText(cypher)
}

// expressionReadsGraphText reports whether cypher holds an expression that
// reads the graph (graphReadingExpression). statementAccessesGraphText,
// statementReadsGraphText and the system database's statement policy read
// expressions through it.
func expressionReadsGraphText(cypher string) bool {
	return graphReadingExpression(cypher) != ""
}

// Kinds of graph-reading expression graphReadingExpression reports.
const (
	graphReadingPatternComprehension = "pattern comprehension"
	graphReadingPattern              = "pattern"
	graphReadingPatternPredicate     = "pattern predicate"
)

// graphReadingExpression is the one reader of the expressions in cypher
// that read the graph, at any depth (inside function calls, lists, maps and
// subqueries): it returns the first one's kind, or "" for none. A COUNT { },
// EXISTS { } or COLLECT { } subquery is "COUNT", "EXISTS" or "COLLECT"; a
// pattern comprehension ([(a)-->(b) | …], or the single-node form [(n) | …])
// graphReadingPatternComprehension; EXISTS((a)-->()) and shortestPath /
// allShortestPaths graphReadingPattern; and a bare relationship pattern
// ((a)-->() in an expression) graphReadingPatternPredicate, reported only
// when there is nothing else. Clause patterns, literals and comments don't count.
func graphReadingExpression(cypher string) string {
	opts := defaultKeywordScanOpts()
	opts.SkipParens = false
	opts.SkipBrackets = false
	opts.SkipBraces = false
	for _, keyword := range []string{"COUNT", "EXISTS", "COLLECT"} {
		for from := 0; ; {
			index := keywordIndexFrom(cypher, keyword, from, opts)
			if index < 0 {
				break
			}
			end := index + len(keyword)
			open := queryGapEnd(cypher, end)
			if open < len(cypher) && cypher[open] == '{' {
				return keyword
			}
			// EXISTS((n)-->(m)): a pattern between the parentheses.
			if keyword == "EXISTS" && open < len(cypher) && cypher[open] == '(' {
				if close := findMatchingDelimiter(cypher, open, '(', ')'); close > open {
					inner := strings.TrimSpace(cypher[open+1 : close])
					if strings.ContainsAny(inner, "-><") || strings.HasPrefix(inner, "(") {
						return graphReadingPattern
					}
				}
			}
			from = end
		}
	}
	for _, keyword := range []string{"shortestPath", "allShortestPaths"} {
		for from := 0; from < len(cypher); {
			at := keywordIndexFrom(cypher, keyword, from, opts)
			if at < 0 {
				break
			}
			open := queryGapEnd(cypher, at+len(keyword))
			if open < len(cypher) && cypher[open] == '(' {
				return graphReadingPattern
			}
			from = at + len(keyword)
		}
	}
	if comprehension, _ := classifyPatternComprehensions(cypher); comprehension {
		return graphReadingPatternComprehension
	}
	pattern := ""
	for i := 0; i < len(cypher); i++ {
		switch cypherLexicalByte(cypher[i]) {
		case cypherQuoteClass:
			i = skipCypherQuotedText(cypher, i, cypher[i]) - 1
			continue
		case '/':
			if end := queryCommentEnd(cypher, i); end >= 0 {
				i = end - 1
				continue
			}
		case ')':
			// A relationship pattern after a node pattern: (a)-->, (a)--,
			// (a)-[, (a)->, (a)<--, (a)<-[ (a subtraction such as (x) - 1
			// or a comparison such as (x) <-1 is none).
			if pattern == "" && relationshipPatternFollows(cypher, i+1) && !inPatternClause(cypher, i+1) {
				pattern = graphReadingPatternPredicate
			}
			continue
		}
	}
	return pattern
}

// statementReadsGraphText reports whether cypher reads the graph: a MATCH,
// a MERGE (which matches before it creates), a procedure call, a SHOW or a
// graph-reading expression (graphReadingExpression), at any depth. CALL
// subquery bodies and WHERE expressions are examined for those operations.
// A statement that only
// creates, and sets, removes or deletes what it created, reads nothing:
// QueryPermissionRequirements then needs write but not read, as Neo4j lets
// a principal with WRITE but no READ privilege run CREATE.
func statementReadsGraphText(cypher string) bool {
	opts := defaultKeywordScanOpts()
	opts.SkipParens = false
	opts.SkipBrackets = false
	opts.SkipBraces = false
	for _, keyword := range []string{"MATCH", "MERGE", "SHOW"} {
		if keywordIndexFrom(cypher, keyword, 0, opts) >= 0 {
			return true
		}
	}
	for from := 0; from < len(cypher); {
		at := keywordIndexFrom(cypher, "CALL", from, opts)
		if at < 0 {
			break
		}
		from = at + len("CALL")
		if _, procedure := procedureNameAt(cypher, queryGapEnd(cypher, from)); procedure {
			return true
		}
	}
	return expressionReadsGraphText(cypher)
}

// statementParametersError is Neo4j's ParameterMissing for a statement that
// references a parameter it wasn't given ("Expected parameter(s): p"), or nil.
// Neo4j reports it after the statement compiles, so a statement that is also
// a syntax or semantic error reports that error (Execute calls this after
// validateSyntax and validateSemanticScopes; the Fabric route after it plans
// the statement). EXPLAIN runs nothing and needs no
// values; in a procedure definition, $name is the procedure's argument.
// Parameter names are reported as the statement wrote them (#734).
func (e *StorageExecutor) statementParametersError(ctx context.Context, cypher string, params map[string]interface{}) error {
	if strings.IndexByte(cypher, '$') < 0 || (isExplainOrProfile(cypher) && !startsWithKeywordFold(strings.TrimSpace(cypher), "PROFILE")) || isCreateProcedureCommand(cypher) {
		return nil
	}
	shellParams := e.mergeShellParams(ctx, params)
	inherited := getParamsFromContext(ctx)
	missing := statementMissingParameters(cypher, func(name string) bool {
		if _, ok := shellParams[name]; ok {
			return true
		}
		_, ok := inherited[name]
		return ok
	})
	if len(missing) == 0 {
		return nil
	}
	names := quotedVariableNamesFor(ctx, cypher)
	for i, name := range missing {
		missing[i] = names.parameterName(name)
	}
	return parameterMissingError(missing)
}

package cypher

import (
	"context"
	"fmt"
	"strconv"
	"strings"
	"time"

	"github.com/orneryd/nornicdb/pkg/config"
	nornicerrors "github.com/orneryd/nornicdb/pkg/errors"
	"github.com/orneryd/nornicdb/pkg/fabric"
	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/search"
	"github.com/orneryd/nornicdb/pkg/storage"
	"go.opentelemetry.io/otel/attribute"
)

// Execute parses and executes a Cypher query with optional parameters.
//
// This is the main entry point for Cypher query execution. The method handles
// the complete query lifecycle: parsing, validation, parameter substitution,
// execution planning, and result formatting.
//
// Parameters:
//   - ctx: Context for cancellation and timeouts
//   - cypher: Cypher query string
//   - params: Optional parameters for $param substitution
//
// Returns:
//   - ExecuteResult with columns and rows
//   - Error if query parsing or execution fails
//
// Example:
//
//	// Simple query without parameters
//	result, err := executor.Execute(ctx, "MATCH (n:Person) RETURN n.name", nil)
//	if err != nil {
//		log.Fatal(err)
//	}
//
//	// Parameterized query
//	params := map[string]interface{}{
//		"name": "Alice",
//		"minAge": 25,
//	}
//	result, err = executor.Execute(ctx, `
//		MATCH (n:Person {name: $name})
//		WHERE n.age >= $minAge
//		RETURN n.name, n.age
//	`, params)
//
//	// Process results
//	// emit "Columns: %v" via the configured logger
//	for _, row := range result.Rows {
//		// process row (e.g. emit "Row: %v" via the configured logger)
//	}
//
// Supported Query Types:
//
//	Core Clauses:
//	- MATCH: Pattern matching and traversal
//	- OPTIONAL MATCH: Left outer joins (returns nulls for no matches)
//	- CREATE: Node and relationship creation
//	- MERGE: Upsert operations with ON CREATE SET / ON MATCH SET
//	- DELETE / DETACH DELETE: Node and relationship deletion
//	- SET: Property updates
//	- REMOVE: Property and label removal
//
//	Projection & Chaining:
//	- RETURN: Result projection with expressions, aliases, aggregations
//	- WITH: Query chaining and intermediate aggregation
//	- UNWIND: List expansion into rows
//
//	Filtering & Ordering:
//	- WHERE: Filtering conditions (=, <>, <, >, <=, >=, IS NULL, IS NOT NULL, IN, CONTAINS, STARTS WITH, ENDS WITH, AND, OR, NOT)
//	- ORDER BY: Result sorting (ASC/DESC)
//	- SKIP / LIMIT: Pagination
//
//	Aggregation Functions:
//	- COUNT, SUM, AVG, MIN, MAX, COLLECT
//
//	Procedures & Functions:
//	- CALL: Procedure invocation (db.labels, db.propertyKeys, db.index.vector.*, etc.)
//	- CALL {}: Subquery execution with UNION support
//
//	Advanced:
//	- UNION / UNION ALL: Query composition
//	- FOREACH: Iterative updates
//	- LOAD CSV: Data import
//	- EXPLAIN / PROFILE: Query analysis
//	- SHOW: Schema introspection
//
//	Path Functions:
//	- shortestPath / allShortestPaths
//
// Error Handling:
//
//	Returns detailed error messages for syntax errors, type mismatches,
//	and execution failures with Neo4j-compatible error codes.
func (e *StorageExecutor) Execute(ctx context.Context, cypher string, params map[string]interface{}) (result *ExecuteResult, retErr error) {
	return e.execute(ctx, cypher, params, nil, true)
}

// executeRouted continues the same semantic statement through a transparent
// dispatcher. Public Execute, including independent reentrant calls made by
// consumers, always starts a fresh outcome instead.
func (e *StorageExecutor) executeRouted(ctx context.Context, cypher string, params map[string]interface{}) (*ExecuteResult, error) {
	var outcome *statementOutcome
	if statement, ok := ctx.Value(queryEmbeddingStatementKey{}).(*statementExecutionContext); ok {
		outcome = statement.outcome
	}
	return e.execute(ctx, cypher, params, outcome, false)
}

func (e *StorageExecutor) execute(ctx context.Context, cypher string, params map[string]interface{}, outcome *statementOutcome, clientText bool) (result *ExecuteResult, retErr error) {
	// The statement's context (deadlineCtx, once the database's query limits
	// apply) ends at the first of its deadlines, and its cause names that
	// deadline's owner: a Bolt client's tx_timeout, the server's statement
	// timeout, the database's query time limit. A deadline error the
	// statement returns is that owner's transaction timeout (#1339); a
	// deadline no owner installed (a caller's own budget, a dependency's
	// timeout) keeps its error as it is.
	deadlineCtx := ctx
	defer func() {
		if retErr != nil {
			retErr = nornicerrors.MarkStatementTimeout(retErr, context.Cause(deadlineCtx))
		}
	}()
	// Every rejection of the caller's statement fails its explicit transaction,
	// including errors before parsing, routing or the system statement policy.
	if e.txContext != nil && e.txContext.active && ctx.Value(ctxKeyTxStorage) == nil {
		defer func() { e.failTransaction(ctx, retErr) }()
	}
	defer func() {
		if result != nil && retErr == nil && result.MapKeyOrders == nil {
			if orders := snapshotMapKeyOrders(ctx); len(orders) > 0 {
				result.MapKeyOrders = orders
			}
		}
	}()
	// A result stream the caller passed is for this statement only, not for
	// the statements it runs on its behalf (#939).
	stream, ctx := takeResultStream(ctx)
	e.resetHotPathTrace()
	// A result served from the result cache that returns no node or
	// relationship has no access to record (resultHasMaterializedEntities).
	recordAccess := true
	defer func() {
		if recordAccess && retErr == nil && result != nil {
			e.recordMaterializedResultAccess(result)
		}
	}()

	// TRC-15: top-level cypher execute span. Started before timing so the
	// span duration matches the metric observation window exactly. The span
	// is ended in the same defer that emits the slow-query log.
	ctx, execSpan := e.startExecuteSpan(ctx, "", cypher)

	// TRC-17: propagate span context to the storage layer so storage spans
	// nest as children of the cypher execute span.
	if te, ok := e.storage.(*storage.TracedEngine); ok {
		te.SetContext(ctx)
	}

	// D-04c slow-query log timing. Captured at the top so the threshold check
	// covers every Execute return path (early-out, fabric, normal). Pre-bind
	// the original query text — by the time the deferred emission fires,
	// `cypher` has been normalized; we want to log what the client submitted.
	slowStart := time.Now()
	elapsed := e.executionElapsed
	if elapsed == nil {
		elapsed = time.Since
	}
	statement := e.newStatementExecutionContext(ctx, slowStart.UTC(), outcome)
	embeddingState := statement.state
	var embeddingGeneration uint64
	if embeddingState != nil {
		embeddingGeneration = embeddingState.generation
	}
	ctx = statement
	// Logging is part of the statement's deadline. Release registry and query
	// limit contexts after its deferred emission, so normal completion does
	// not look like cancellation to the redactor.
	originalCypher := cypher
	collectionGeneration := e.queryStatistics.start(originalCypher, slowStart)
	var executionDuration time.Duration
	var running runningStatement
	var queryLimitCancel context.CancelFunc
	defer func() {
		statementErr := ctx.Err()
		if retErr == nil && running.tx != nil && !running.autoCommit && e.txContext != nil && e.txContext.active {
			if tracker := running.tx.memory.Load(); tracker != nil {
				if storageTx, ok := e.txContext.tx.(*storage.BadgerTransaction); ok {
					if err := tracker.settleStaged(storageTx.StagedMemoryBytes()); err != nil {
						result, retErr = nil, err
					}
				}
			}
		}
		if err := running.memoryFailure(); err != nil && !statement.outcome.committed.Load() {
			if statementErr != nil && (statementErr == context.Canceled || statementErr == context.DeadlineExceeded) {
				result, retErr = nil, statementErr
			} else {
				result, retErr = nil, err
			}
		} else if retErr == nil && result != nil && running.memory != nil && !statement.outcome.committed.Load() {
			// A nested execution hands its retained rows to its parent scope.
			if err := running.memory.handOver(running.memoryMark, result.Rows); err != nil {
				result, retErr = nil, err
			}
			running.memory = nil
		}
		terminated := running.done()
		if !statement.outcome.committed.Load() {
			if terminated {
				result, retErr = nil, transactionTerminatedError()
			} else if retErr == nil && statementErr != nil {
				result, retErr = nil, statementErr
			}
		}
		e.queryStatistics.record(collectionGeneration, originalCypher, slowStart, executionDuration, retErr == nil)
		e.observeSlowQueryIfThresholded(executionDuration)
		recordSpanError(execSpan, retErr)
		execSpan.End()
		if queryLimitCancel != nil {
			queryLimitCancel()
		}
	}()
	defer func() {
		executionDuration = elapsed(slowStart)
		dur := executionDuration
		e.emitRejectionReport(ctx, originalCypher, retErr)
		// Plan is unavailable for non-EXPLAIN/PROFILE queries; pass nil and
		// rely on PlanHash's zero-placeholder behavior. Phase 6 (TRC-04) will
		// thread the planned tree here once cypher EXPLAIN refactoring is in.
		e.emitSlowQueryLog(ctx, originalCypher, nil, dur)

	}()
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	// Normalize query: trim BOM (some clients send it) then whitespace
	cypher = trimBOM(cypher)
	cypher = normalizeCypherSyntaxConfusables(cypher)
	// The statement as the client sent it may not call NornicDB's internal
	// functions; the rewrites below produce them (#1105).
	// Transparent routing continues already-admitted text, including generated
	// functions. A public reentrant call still admits its own client text.
	if clientText {
		if err := internalFunctionCallError(cypher); err != nil {
			return nil, err
		}
	}
	// Comments and keyword spacing are canonical from here on; what the
	// client sees (column names, messages, plans) is the text it sent (#740).
	// NORNICDB_CYPHER_QUERY_NORMALIZATION=false skips the pass: the
	// statement runs as sent.
	canonical, rewrite := cypher, (*queryRewrite)(nil)
	if config.IsCypherQueryNormalizationEnabled() {
		var err error
		canonical, rewrite, err = normalizeQueryText(ctx, cypher)
		if err != nil {
			return nil, err
		}
	}
	if rewrite != nil {
		cypher = canonical
		defer func() { result, retErr = rewrite.restore(result, retErr) }()
	}
	// Digit-grouping underscores (1_000) go here, on every route; columns
	// and messages keep the client's text (#907).
	if grouped, numericRewrite := canonicalizeNumericLiterals(cypher); numericRewrite != nil {
		cypher = grouped
		defer func() { result, retErr = numericRewrite.restore(result, retErr) }()
	}
	// GQL function aliases (collect_list, ln, …) call the function they
	// name; columns and messages keep the client's text.
	if !rewriteFree(rewriteFreeFunctionAliases, false, cypher) {
		if aliased, aliasRewrite := canonicalizeFunctionAliases(cypher); aliasRewrite != nil {
			cypher = aliased
			defer func() { result, retErr = aliasRewrite.restore(result, retErr) }()
		} else {
			markRewriteFree(rewriteFreeFunctionAliases, false, cypher)
		}
	}
	cypher = strings.TrimSpace(cypher)
	cypher = trimTrailingStatementDelimiters(cypher)
	ctx = withCypherVersion(ctx, cypher)
	if err := validateCypherPreamble(cypher); err != nil {
		return nil, err
	}
	if config.IsANTLRParser() {
		body, _ := stripCypherPreamble(cypher)
		if cypherGrammarVersion(cypher) != "25" && usesSharedGrammarClauses(ctx, body) {
			return nil, sharedClauseSyntaxError("LET, FILTER and FOR require CYPHER 25 with the ANTLR parser")
		}
	}
	// Neo4j 5 statement framing: leading CYPHER [version] [option=value …]
	// groups run the statement they precede, and a trailing FINISH (on every
	// UNION branch) runs it and returns no rows.
	cypher, _ = stripCypherPreamble(cypher)
	cypher = strings.TrimSpace(cypher)
	// Cypher 25 expression forms (RETURN ALL, s"…{x}…", map comprehensions)
	// become the expressions they stand for, once, here (#907).
	cypher25 := cypherVersionFromContext(ctx) == "25"
	// In Cypher 25 a '$' after a name starts a parameter (L$props is
	// L $props); Cypher 5 reads a$b as one name.
	if cypher25 {
		if separated, separateRewrite := separateCypher25Parameters(cypher); separateRewrite != nil {
			cypher = separated
			defer func() { result, retErr = separateRewrite.restore(result, retErr) }()
		}
	}
	if !rewriteFree(rewriteFreeCypher25Expressions, cypher25, cypher) {
		expanded, expressionRewrites, err := desugarCypher25Expressions(cypher, cypher25)
		if err != nil {
			return nil, err
		}
		if len(expressionRewrites) > 0 {
			cypher = expanded
			// One defer, not one per pass: a defer in a loop would make every
			// statement pay for heap-allocated defers. Restored last pass first.
			defer func() {
				for index := len(expressionRewrites) - 1; index >= 0; index-- {
					result, retErr = expressionRewrites[index].restore(withoutGeneratedColumns(result), retErr)
				}
			}()
		} else {
			markRewriteFree(rewriteFreeCypher25Expressions, cypher25, cypher)
		}
	}
	// Cypher 25 composition (NEXT, WHEN, braced query parts) becomes the
	// CALL subqueries and UNIONs it stands for, once, here; columns and
	// errors are mapped back (#907).
	if !rewriteFree(rewriteFreeQueryStructure, false, cypher) {
		if composed, structureRewrite, err := desugarQueryStructure(ctx, cypher, e); err != nil {
			return nil, err
		} else if structureRewrite != nil {
			cypher = composed
			defer func() { result, retErr = structureRewrite.restore(withoutGeneratedColumns(result), retErr) }()
		} else if !mayUseQueryStructure(cypher) {
			// Only the quick check's verdict is the text's alone.
			markRewriteFree(rewriteFreeQueryStructure, false, cypher)
		}
	}
	if err := e.validateStatementFraming(ctx, cypher); err != nil {
		return nil, err
	}
	finishTerminated := false
	if stripped, ok := stripUnionBranchFinishes(ctx, cypher); ok {
		cypher = strings.TrimSpace(stripped)
		finishTerminated = true
		ctx = withFinishedStatement(ctx, cypher)
	}
	if cypher == "" {
		if finishTerminated {
			return &ExecuteResult{}, nil
		}
		return nil, localizedError(localization.CypherCoreEmptyQuery(), nil)
	}
	// Knowledge-policy DDL that cannot be parsed (a missing profile or policy
	// name, a missing OPTIONS block) is a syntax error on every route, the
	// auto-commit and HTTP routes included (#514).
	if isKnowledgePolicyDDLStatement(cypher) {
		if _, _, err := ParseKnowledgePolicyDDL(cypher); err != nil {
			return nil, &classifiedCypherError{
				cause:  err,
				code:   "Neo.ClientError.Statement.SyntaxError",
				detail: "UnexpectedSyntax",
			}
		}
	}
	if finishTerminated {
		defer func() {
			completeFinishedResult(result)
		}()
	}

	// Typed Go maps and slices become Cypher maps and lists here, once, for
	// every route (#712).
	params = normalizeQueryParameters(params)

	// Handle Neo4j shell/browser commands like :USE and :param before validation.
	useBefore := GetUseDatabaseFromContext(ctx)
	processedQuery, processedCtx, shellResult, err := e.preprocessShellCommands(ctx, cypher, params)
	if err != nil {
		return nil, err
	}
	ctx = processedCtx
	cypher = processedQuery
	if cypher == "" {
		return shellResult, nil
	}
	if err := clientTransactionCommand(ctx, cypher); err != nil {
		return nil, err
	}
	// Only BEGIN can start a script; avoid its allocating classifier for
	// ordinary statements while admitting them through the same owner.
	if bareTransactionCommand(cypher) == "" && (!startsWithKeywordFold(cypher, "BEGIN") || !transactionScriptShape(cypher)) {
		// Neo4j parses a statement before it checks it against its
		// transaction, so a rejected USE clause (USE before an
		// administration command among them) is the SyntaxError in an
		// explicit transaction too.
		if startsWithKeywordFold(cypher, "USE") {
			if _, _, _, err := parseUseClause(cypher, false); err != nil {
				return nil, err
			}
		}
		if err := e.admitTransactionStatement(ctx, cypher); err != nil {
			return nil, err
		}
		routed, err := e.routeAdministrationStatement(ctx, cypher)
		if err != nil {
			return nil, err
		}
		if routed != e {
			return routed.executeRouted(ctx, cypher, params)
		}
	}
	// A cached per-database executor is shared by every auto-commit client of
	// its database. A bare transaction command must not open a transaction on
	// it: any later statement (or one-statement script) would then run inside
	// another caller's transaction, and COMMIT/ROLLBACK would end writes the
	// caller never issued. Neo4j clients cannot send Cypher transaction
	// statements either; embedded callers that want explicit transactions
	// create their own session executor.
	if e.sharedExecutor && (e.txContext == nil || !e.txContext.active) {
		if word := bareTransactionCommand(cypher); word != "" {
			message := localization.CypherTransactionsCommandNotStatement(word)
			return nil, localizedError(message, newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", message.Fallback))
		}
	}
	// A query after :USE <db> runs on that database, like one after a USE
	// clause (#738).
	if useDB := GetUseDatabaseFromContext(ctx); useDB != "" && useDB != useBefore {
		return e.executeOnDatabase(ctx, useDB, cypher, params, false)
	}

	// The quoted-variable and label-expression rewrites map the finished
	// result's rows back, so a statement with either doesn't stream.
	rowsRewritten := false
	// Backtick-quoted variables become plain identifiers here, once, for
	// every route; the result's columns and errors are mapped back (#734).
	if canonical, names := canonicalizeQuotedVariables(ctx, cypher); names != nil {
		cypher = canonical
		params = names.parameterValues(params)
		ctx = withQuotedVariableNames(ctx, names)
		rowsRewritten = true
		defer func() {
			result, retErr = names.restore(result, retErr, func(text string) []returnItem { return e.parseReturnItems(ctx, text) })
		}()
	}

	// ORDER BY, SKIP / OFFSET and LIMIT as clauses of their own become the
	// WITH * they stand for, once, here; errors are mapped back (#907).
	if desugared, orderRewrite := desugarStandaloneOrderClauses(cypher); orderRewrite != nil {
		cypher = desugared
		defer func() { result, retErr = orderRewrite.restore(result, retErr) }()
	}

	// Route multi-graph CALL { USE ... } queries through the Fabric planner/executor
	// so subquery decomposition and cross-graph routing use a single deterministic path.
	if e.shouldUseFabricPlanner(cypher) {
		mergedParams := e.mergeShellParams(ctx, mergeInheritedQueryParams(ctx, params))
		ctx = withQueryParams(ctx, mergedParams)
		mode, modeQuery := parseExecutionMode(cypher)
		if finishTerminated {
			ctx = withFinishedStatement(ctx, modeQuery)
		}
		if mode != ModeNormal {
			if err := e.validateSyntax(ctx, modeQuery, cypherVersionFromContext(ctx) == "25"); err != nil {
				return nil, err
			}
			if err := e.validateSemanticScopes(ctx, fabricSingleGraphStatement(ctx, modeQuery)); err != nil {
				return nil, err
			}
			if err := e.statementParametersError(ctx, cypher, params); err != nil {
				return nil, err
			}
			if mode == ModeExplain {
				return e.executeExplain(ctx, modeQuery)
			}
			return e.executeProfile(ctx, modeQuery)
		}
		info := e.analyzer.Analyze(ctx, cypher)
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		// Plan 04-03 Site 3 (fabric branch): isFabric=true → op_type="fabric"
		// per RISK-1 corrected classifier. Observation pre-execute so the
		// counter reflects intent regardless of execution outcome (errors
		// still bucket by intended op_type, matching how queries_total works
		// in the reference catalogs).
		e.observeQuery(classifyOpType(info, true /* isFabric */, false), true, slowStart)
		execSpan.SetAttributes(attribute.String("cypher.op_type", "fabric"))
		inExplicitTx := e.txContext != nil && e.txContext.active
		// As on one database, and as Neo4j compiles a statement, its
		// variable scopes are checked before it plans, enlists a participant
		// or runs any part: a CALL scope clause naming a variable the query
		// doesn't define is rejected here. A missing parameter is reported
		// after both, so these syntax errors come first.
		if err := e.validateSemanticScopes(ctx, fabricSingleGraphStatement(ctx, cypher)); err != nil {
			return nil, err
		}
		preparedFabric, err := e.prepareFabricExecution(ctx, cypher)
		if err != nil {
			return nil, err
		}
		if err := e.statementParametersError(ctx, cypher, params); err != nil {
			return nil, err
		}
		ctx = context.WithValue(ctx, fabricPreparedExecKey{}, preparedFabric)
		allowResultCache := !preparedFabric.hasRemote
		fabricResultCacheKey := ""

		// Mirror normal query-cache policy for Fabric reads (autocommit only).
		// A cached result is served only to a caller the statement is
		// authorized for (fabricResultCacheKey).
		if allowResultCache && e.canUseResultCache(ctx, info, cypher) {
			if key, cacheable := e.fabricResultCacheKey(ctx, preparedFabric, cypher, mergedParams); cacheable {
				fabricResultCacheKey = key
				if cached, _, _, found := e.cache.getWithTraceForEmbedding(fabricResultCacheKey, embeddingGeneration); found {
					return cached, nil
				}
			}
		}

		var result *ExecuteResult
		var execErr error
		// When an explicit transaction is active on a composite route, execute through
		// the same FabricTransaction so many-read/one-write constraints are enforced
		// across all statements in the session.
		if inExplicitTx {
			if ftx, ok := e.txContext.tx.(*fabric.FabricTransaction); ok {
				result, execErr = e.executeViaFabricWithTx(ctx, cypher, mergedParams, ftx, false, preparedFabric)
			} else {
				result, execErr = e.executeViaFabricWithTx(ctx, cypher, mergedParams, nil, true)
			}
		} else {
			result, execErr = e.executeViaFabricWithTx(ctx, cypher, mergedParams, nil, true)
		}
		if execErr != nil {
			return nil, execErr
		}

		if fabricResultCacheKey != "" {
			e.cache.putWithLabelsAndTraceForEmbedding(fabricResultCacheKey, result, e.queryCacheTTL, extractLabelsFromQuery(cypher), HotPathTrace{}, embeddingGeneration)
		}

		e.invalidateResultCacheForQuery(info)

		return result, nil
	}

	// EXPLAIN / PROFILE USE <graph> …: the graph is resolved as for the
	// statement itself (Neo4j's DatabaseNotFound for a missing one, #744),
	// and the plan is the target database's.
	if mode, inner := parseExecutionMode(cypher); mode != ModeNormal {
		if use, remaining, hasUse, err := parseUseClause(inner, false); hasUse || err != nil {
			if err != nil {
				return nil, err
			}
			if err := e.dynamicUseError(use); err != nil {
				return nil, err
			}
			keyword := "EXPLAIN "
			if mode == ModeProfile {
				keyword = "PROFILE "
			}
			return e.executeOnDatabase(ctx, use.Name, keyword+remaining, params, false)
		}
	}
	// Handle leading Cypher USE clause (openCypher multi-graph syntax).
	if use, remaining, hasUse, err := parseUseClause(cypher, false); hasUse || err != nil {
		if err != nil {
			return nil, err
		}
		if err := e.dynamicUseError(use); err != nil {
			return nil, err
		}
		return e.executeOnDatabase(ctx, use.Name, remaining, params, false)
	}
	// Label expressions in patterns become the label forms and WHERE
	// predicates the local evaluator reads. Route source Cypher first: remote
	// evaluators do not implement our internal functions. The result's columns and
	// errors are mapped back (#860).
	desugared, labelRewrite, err := desugarLabelExpressions(ctx, cypher, params, cypherVersionFromContext(ctx) == "25")
	if err != nil {
		return nil, err
	}
	if labelRewrite != nil {
		rowsRewritten = true
		cypher = desugared
		defer func() { result, retErr = labelRewrite.restore(withoutGeneratedColumns(result), retErr) }()
	}
	if err := e.authorizeSelectedDatabase(ctx, "", cypher); err != nil {
		return nil, err
	}
	e.statementAdmitted(ctx)
	if err := e.systemDatabaseWriteError(ctx, cypher); err != nil {
		return nil, err
	}

	// Reject data queries on composite root — callers must USE a constituent.
	// System/admin commands (SHOW DATABASES, CREATE/DROP DATABASE, ALTER, SHOW COMPOSITE,
	// SHOW CONSTITUENTS, SHOW ALIASES, SHOW LIMITS, BEGIN, COMMIT, ROLLBACK) are allowed,
	// and so is a statement that reads or writes no graph (RETURN 1,
	// UNWIND graph.names() AS g RETURN g), which runs on the composite
	// itself, as in Neo4j.
	if isCompositeRoot(e.storage) && !isCompositeAllowedCommand(cypher) && statementAccessesGraphText(cypher) {
		return nil, localizedError(localization.CypherCoreCompositeTargetRequired(), nil)
	}

	// Merge session-scoped shell parameters with per-call parameters.
	// Explicit params win over shell params to preserve HTTP/Bolt semantics.
	params = mergeInheritedQueryParams(ctx, params)
	params = e.mergeShellParams(ctx, params)

	// Check for transaction control statements and transaction scripts FIRST.
	// These are Nornic extensions and must bypass strict ANTLR validation.
	// A one-statement script opens and closes its own transaction; it runs on
	// a private executor so a client statement can never leave the shared
	// per-database executor inside a transaction — concurrent auto-commit
	// statements would otherwise observe and collide with the script's
	// transaction state (acknowledged-write loss, mid-run panics). An
	// embedded caller that already owns an active transaction keeps running
	// the script on itself, where handleBegin fails as before.
	if transactionScriptShape(cypher) {
		if e.txContext != nil && e.txContext.active {
			if result, err := e.executeTransactionScript(ctx, cypher); result != nil || err != nil {
				return result, err
			}
		} else {
			scriptExec := e.cloneForStorage(e.storage)
			scriptExec.txContext = nil
			if result, err := scriptExec.executeTransactionScript(ctx, cypher); result != nil || err != nil {
				return result, err
			}
		}
	} else if result, err := e.executeTransactionScript(ctx, cypher); result != nil || err != nil {
		return result, err
	}
	if result, err := e.parseTransactionStatement(ctx, cypher); result != nil || err != nil {
		if err == nil && e.txContext != nil && e.txContext.active {
			e.txContext.coordinatorOwned = e.txContext.coordinatorOwned || storage.CoordinatorOwnsTransaction(ctx)
			// BEGIN: the client's transaction metadata (WithTransactionMetadata).
			if tx, ok := e.txContext.tx.(*storage.BadgerTransaction); ok {
				if metadataErr := applyTransactionMetadata(ctx, tx); metadataErr != nil {
					_, _ = e.handleRollback()
					return nil, metadataErr
				}
			}
		}
		if err == nil && e.txContext != nil && e.txContext.active && e.txContext.running == nil {
			e.txContext.running = runningTransactions.begin(ctx, e.currentDatabaseName())
		}
		return result, err
	}
	// A statement that fails in an explicit transaction marks it failed, as in
	// Neo4j (#683): later statements are refused, COMMIT rolls it back and
	// ROLLBACK discards everything it wrote. Only the caller's own statement
	// counts: executions nested inside a statement (they carry the
	// transaction's storage wrapper) handle their own errors.
	if tx := e.txContext; tx != nil && tx.active && ctx.Value(ctxKeyTxStorage) == nil {
		if tx.failed != nil {
			return nil, queryOnFailedTransactionError(tx.failed)
		}
	}
	// SHOW TRANSACTIONS lists the statement while it runs; TERMINATE
	// TRANSACTIONS cancels it (#718). A statement of an explicit
	// transaction is registered here, so a terminated transaction refuses
	// it before anything else; an auto-commit statement after the result
	// cache, since a statement served from the cache runs nothing that
	// could be listed or terminated.
	// A statement whose transaction TERMINATE TRANSACTIONS terminated while
	// it ran fails with Neo4j's Neo.ClientError.Transaction.Terminated,
	// whichever layer noticed the cancellation (a storage call, the
	// checked write path, the row loop) and whether it read or wrote;
	// only an auto-commit statement that had already committed keeps its
	// result (#751).
	registerStatement := func() error {
		statementCtx, statement, err := e.withRunningStatement(ctx, originalCypher)
		if err != nil {
			return err
		}
		running, ctx = statement, statementCtx
		return nil
	}
	if e.txContext != nil && e.txContext.active {
		if runErr := registerStatement(); runErr != nil {
			_, _ = e.handleRollback()
			return nil, runErr
		}
	}

	// Validate basic syntax
	if err := e.validateSyntax(ctx, cypher, cypherVersionFromContext(ctx) == "25"); err != nil {
		// Plan 04-03 Site 2 (parse-error chokepoint): emit op_type="parse_error"
		// per D-04b sixth enum value. No duration observation — parse cost is
		// sub-microsecond and not meaningful to bucket. The queries_total
		// counter still increments so the SRE can alert on parse-error rate.
		e.observeQuery("parse_error", false /* observeDuration */, slowStart)
		execSpan.SetAttributes(attribute.String("cypher.op_type", "parse_error"))
		return nil, err
	}
	// A statement whose last clause is a reading clause (UNWIND, MATCH,
	// OPTIONAL MATCH, WITH) has nothing after it — Neo4j rejects it. This is
	// a whole-statement rule that runs after syntax validation, so malformed
	// text keeps the parser's own syntax error; fabric fragments legitimately
	// end in UNWIND when the surrounding statement continues in another
	// fragment, and a FINISH terminator is itself the clause that follows, so
	// both are exempt.
	if !finishTerminated {
		last := lastTopLevelClauseWord(cypher)
		// `WITH EMBEDDING` is a NornicDB execution option, not a WITH
		// projection: a statement that ends with it is complete. Only exempt
		// it when the text before the trailer is itself a complete statement.
		if last == "WITH" {
			if scope, ok := stripWithEmbeddingSuffix(cypher); ok {
				switch lastTopLevelClauseWord(scope) {
				case "", "UNWIND", "MATCH", "OPTIONAL", "WITH", "CALL", "LET", "FILTER", "FOR":
				default:
					last = ""
				}
			}
		}
		switch last {
		case "UNWIND", "MATCH", "OPTIONAL", "WITH", "LET", "FILTER", "FOR":
			return nil, newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
				fmt.Sprintf("Invalid input: %s must be followed by a clause", last))
		}
		// A bare CALL has no procedure or subquery after it; the statement is
		// incomplete, not a lookup of a procedure named 'CALL' (#514).
		if strings.EqualFold(cypher, "CALL") {
			return nil, newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
				"Invalid input: CALL must be followed by a procedure name or subquery")
		}
	}
	// WITH EMBEDDING is an execution option, not a WITH projection: the
	// scopes are those of the statement without it. EXPLAIN and PROFILE
	// check the statement they plan, as Neo4j compiles it.
	_, scopeText := parseExecutionMode(cypher)
	scopeText, _ = stripWithEmbeddingSuffix(scopeText)
	if finishTerminated {
		scopeText += " FINISH"
	}
	if err := e.validateSemanticScopes(ctx, scopeText); err != nil {
		return nil, err
	}
	admission, admissionErr := e.admitBoundStatement(ctx, scopeText)
	if admissionErr != nil {
		return nil, admissionErr
	}
	if admission.program != nil {
		ctx = withBoundStatementProgram(ctx, admission.program)
	}
	defer func() {
		if finishTerminated {
			completeFinishedResult(result)
		}
		if retErr == nil && result != nil {
			retErr = admission.verifyColumns(result.Columns)
		}
	}()
	if err := e.statementParametersError(ctx, cypher, params); err != nil {
		return nil, err
	}

	// IMPORTANT: Do NOT substitute parameters before routing!
	// We need to route the query based on the ORIGINAL query structure,
	// not the substituted one. Otherwise, keywords inside parameter values
	// (like 'MATCH (n) SET n.x = 1' stored as content) will be incorrectly
	// detected as Cypher clauses.
	//
	// Parameter substitution happens AFTER routing, inside each handler.
	// This matches Neo4j's architecture where params are kept separate.

	// Store params in context for handlers to use
	ctx = withQueryParams(ctx, params)
	if err := e.validateBoundParameterExpressions(ctx, cypher, params); err != nil {
		return nil, err
	}

	// Check query limits if storage engine supports it
	// Uses interface{} to avoid importing multidb package (prevents circular dependencies)
	if namespacedEngine, ok := e.storage.(interface {
		GetQueryLimitChecker() interface {
			CheckQueryRate() error
			CheckQueryLimits(context.Context) (context.Context, context.CancelFunc, error)
			GetQueryLimits() interface{}
		}
	}); ok {
		if qlc := namespacedEngine.GetQueryLimitChecker(); qlc != nil {
			// Check query rate limit
			if err := qlc.CheckQueryRate(); err != nil {
				return nil, err
			}

			// Check write rate limit for write queries
			// We need to check this early, but we don't know if it's a write query yet
			// So we'll check it in the write handlers too

			// Apply query timeout and concurrent query limits
			var err error
			ctx, queryLimitCancel, err = qlc.CheckQueryLimits(ctx)
			if err != nil {
				return nil, err
			}
			deadlineCtx = ctx
		}
	}

	// TRC-15: plan span wraps the analysis/classification phase.
	_, planSpan := startPlanSpan(ctx)
	// Analyze query - uses cached analysis if available
	// This extracts query metadata (HasMatch, IsReadOnly, Labels, etc.) once
	// and caches it for repeated queries, avoiding redundant string parsing
	info := e.analyzer.Analyze(ctx, cypher)
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	ctx, finishMode, modeErr := e.observeResolvedStatementMode(ctx, cypher)
	if modeErr != nil {
		return nil, modeErr
	}
	if finishMode != nil {
		defer func() {
			if retErr == nil {
				result = finishMode(result)
			}
		}()
	}
	if err := e.admitResolvedStatementWrite(ctx, cypher); err != nil {
		return nil, err
	}

	// Plan 04-03 Sites 1 + 3 (RISK-1 corrected): classify ONCE post-Analyze.
	// isFabric=false here because the fabric branch returns at line ~963
	// before reaching this code path. isAdmin=true overrides the QueryInfo-
	// derived classification (e.g., SHOW DATABASES would otherwise classify
	// as "schema" via HasShow → IsSchemaQuery; D-04a says system/admin
	// commands bucket as "admin" instead). Single observation point covers
	// cache-hit early-return AND every downstream execution path so the
	// counter reflects intent regardless of how the query resolves.
	opType := classifyOpType(info, false /* isFabric */, isSystemCommandNoGraph(cypher))
	e.observeQuery(opType, true /* observeDuration */, slowStart)
	planSpan.SetAttributes(attribute.String("cypher.op_type", opType))
	planSpan.End()
	// Update the execute span with the resolved op_type.
	execSpan.SetAttributes(attribute.String("cypher.op_type", opType))

	// For routing, we still need upperQuery for some handlers
	// TODO: Migrate handlers to use QueryInfo directly
	upperQuery := e.cachedUpperQuery(cypher)

	// Capture the storage and search-index revisions before execution so
	// mutations performed outside this executor cannot leave a stale cached
	// result behind. The search index is updated after the graph (a node's
	// vector is indexed after its embedding is saved), so a search procedure
	// that ran in between would otherwise keep its result until the TTL
	// (#945). The key carries a language version other than the default 5:
	// the same text can mean different things in Cypher 5 and Cypher 25
	// (#907); a Cypher 5 key pays for no version text.
	resultCacheKey := ""
	if e.canUseResultCache(ctx, info, cypher) {
		resultCacheKey = resultCacheEntryKey(ctx, cypher, params)
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		if version := cypherVersionFromContext(ctx); version != "5" {
			resultCacheKey += ":cypher:" + version
		}
		if provider, ok := e.storage.(storage.GraphMutationVersionProvider); ok {
			if version, supported := provider.GraphMutationVersion(); supported {
				resultCacheKey += ":graph:" + strconv.FormatUint(version, 10)
			}
		}
		if svc := e.search(); svc != nil {
			resultCacheKey += searchCacheKey(svc)
		}
		if cached, trace, entities, found := e.cache.getWithTraceForEmbedding(resultCacheKey, embeddingGeneration); found {
			e.restoreHotPathTrace(trace)
			recordAccess = entities
			return cached, nil
		}
	}
	if running.tx == nil && running.memory == nil {
		// Registering an auto-commit statement can't fail: only a
		// terminated explicit transaction refuses a statement, and a
		// statement of one is registered above.
		_ = registerStatement()
	}

	// Prefix consumption and dispatch share one reader, including comments
	// and EOF. A classifier flag must never re-enter the unchanged statement.
	if info.HasExplain || info.HasProfile {
		mode, innerQuery := parseExecutionMode(cypher)
		if finishTerminated {
			ctx = withFinishedStatement(ctx, innerQuery)
		}
		if mode == ModeExplain {
			return e.executeExplain(ctx, innerQuery)
		}
		if mode == ModeProfile {
			return e.executeProfile(ctx, innerQuery)
		}
	}

	// If in explicit transaction, execute within it
	if e.txContext != nil && e.txContext.active {
		ctx = withExpressionFailureSlot(ctx)
		ctx = withStatementClausePlans(ctx, cypher)
		result, err := e.executeInTransaction(ctx, cypher, upperQuery)
		if failure := getExpressionFailure(ctx); failure != nil {
			return result, failure
		}
		return result, err
	}

	// System commands (CREATE/DROP DATABASE, SHOW DATABASES, etc.) must not use
	// implicit transactions: they operate on dbManager/metadata, not graph
	// storage. Routing them through executeWithoutTransaction directly ensures
	// correct handling and avoids the write path.
	if isSystemCommandNoGraph(cypher) || isOrdinarySchemaDDL(cypher) {
		result, err := e.executeWithoutTransaction(ctx, cypher, upperQuery)
		if err != nil {
			return nil, err
		}
		// This owner executes metadata/schema effects directly, with no
		// implicit transaction to publish their completed outcome.
		if !info.IsReadOnly && !e.inTransaction(ctx) {
			publishStatementCommit(ctx)
		}
		return result, nil
	}

	// An auto-commit read hands its rows to the caller's result stream as it
	// produces them (#939). The result-limit truncation and the restores of
	// rewritten rows below need the whole result, so a statement with
	// either keeps it. A streamed result is not cached.
	if stream != nil && info.IsReadOnly && !rowsRewritten && !finishTerminated && e.maxResults() == 0 {
		ctx = armResultStream(ctx, stream, cypher, func(columns []string) []string {
			restored, _ := rewrite.restore(&ExecuteResult{Columns: columns}, nil)
			return restored.Columns
		}, func(rows [][]interface{}) {
			e.recordMaterializedResultAccess(&ExecuteResult{Rows: rows})
		})
	}

	// Auto-commit single query through the implicit-transaction write path.
	ctx = withExpressionFailureSlot(ctx)
	ctx = withStatementClausePlans(ctx, cypher)
	result, err = e.executeImplicitAsync(ctx, cypher, upperQuery)
	if result != nil && err == nil {
		if orders := snapshotMapKeyOrders(ctx); len(orders) > 0 {
			result.MapKeyOrders = orders
		}
	}
	// An expression error recorded while the statement ran is its error,
	// whichever route ran it: no route's result stands in for it.
	if err == nil {
		if failure := getExpressionFailure(ctx); failure != nil {
			return nil, failure
		}
	}

	// Apply result limit if set
	if err == nil && result != nil {
		if maxResults := e.maxResults(); maxResults > 0 && int64(len(result.Rows)) > maxResults {
			result.Rows = result.Rows[:maxResults]
		}
	}

	// Retain the revision captured before execution. A read overlapping a
	// mutation must not publish its stale result under the newer revision.
	if err == nil && resultCacheKey != "" && !stream.streamed() {
		if finishMode != nil {
			result = finishMode(result)
		}
		e.cache.putWithLabelsAndTraceForEmbedding(resultCacheKey, result, e.queryCacheTTL, extractLabelsFromQuery(cypher), e.LastHotPathTrace(), embeddingGeneration)
	}

	e.invalidateCachesForQuery(info, cypher)

	return result, err
}

// maxResults is the database's result-row limit (0 for none): the result of
// a statement is cut to it.
func (e *StorageExecutor) maxResults() int64 {
	namespacedEngine, ok := e.storage.(interface {
		GetQueryLimitChecker() interface {
			CheckQueryRate() error
			CheckQueryLimits(context.Context) (context.Context, context.CancelFunc, error)
			GetQueryLimits() interface{}
		}
	})
	if !ok {
		return 0
	}
	qlc := namespacedEngine.GetQueryLimitChecker()
	if qlc == nil {
		return 0
	}
	queryLimits := qlc.GetQueryLimits()
	if queryLimits == nil {
		return 0
	}
	limits, ok := queryLimits.(interface{ GetMaxResults() int64 })
	if !ok {
		return 0
	}
	return limits.GetMaxResults()
}

// searchCacheKey is the part of a result-cache key that depends on the search
// service: its revision, and its instance, which tells a replacement service
// (a reset or restore of the database's search) from the one it replaced,
// whose revisions it would otherwise repeat.
func searchCacheKey(svc *search.Service) string {
	return ":search:" + strconv.FormatUint(svc.Instance(), 10) + ":" + strconv.FormatUint(svc.IndexRevision(), 10)
}

package cypher

import (
	"context"
	"encoding/binary"
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/orneryd/nornicdb/pkg/cypher/resultmetadata"
	"github.com/orneryd/nornicdb/pkg/fabric"
	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/multidb"
	"github.com/orneryd/nornicdb/pkg/storage"
)

type fabricPreparedExecKey struct{}

// participantSchemaForStatement is the participant schema boundary shared by
// statement metadata consumers and Fabric planning. The Fabric integration
// supplies the resolver; without it, participant-owned implicit signatures are
// deliberately unresolved before execution.
func (e *StorageExecutor) participantSchemaForStatement(ctx context.Context, query string) resultmetadata.ParticipantSchema {
	return nil
}

func (e *StorageExecutor) shouldUseFabricPlanner(cypher string) bool {
	if e.dbManager == nil {
		return false
	}
	// Engage Fabric only when a parsed USE target references a composite scope:
	//   - USE <composite>
	//   - USE <composite>.<constituent>
	// Word presence alone is insufficient (e.g., "USE" inside string payloads).
	opts := defaultKeywordScanOpts()
	searchFrom := 0
	for {
		useIdx := keywordIndexFrom(cypher, "USE", searchFrom, opts)
		if useIdx < 0 {
			break
		}
		use, _, hasUse, err := fabric.ParseUseClause(cypher[useIdx:], true)
		if hasUse && err == nil && (e.useTargetRequiresFabric(use.Name) || (use.IsDynamic() && e.sessionIsComposite())) {
			return true
		}
		searchFrom = useIdx + len("USE")
	}
	return false
}

func (e *StorageExecutor) useTargetRequiresFabric(target string) bool {
	target = strings.TrimSpace(target)
	if target == "" || e.dbManager == nil {
		return false
	}
	if e.dbManager.IsCompositeDatabase(target) {
		return true
	}
	if dot := strings.IndexByte(target, '.'); dot > 0 {
		base := strings.TrimSpace(target[:dot])
		if base != "" && e.dbManager.IsCompositeDatabase(base) {
			return true
		}
	}
	return false
}

func (e *StorageExecutor) executeViaFabricWithTx(ctx context.Context, cypher string, params map[string]interface{}, tx *fabric.FabricTransaction, autoCommit bool, preparation ...*fabricPreparedExec) (*ExecuteResult, error) {
	if tx == nil {
		tx = fabric.NewFabricTransaction(fmt.Sprintf("fab-%d", time.Now().UnixNano()))
	}
	var prepared *fabricPreparedExec
	if len(preparation) > 0 {
		prepared = preparation[0]
	} else {
		var err error
		prepared, err = e.preparedFabricFromContext(ctx)
		if err != nil {
			return nil, err
		}
		if prepared == nil {
			prepared, err = e.prepareFabricExecution(ctx, cypher)
			if err != nil {
				return nil, err
			}
		}
	}
	if prepared == nil {
		return nil, localizedError(localization.CypherCommandRoutingFabricNotPrepared(), nil)
	}
	contract, err := readStatementExecutionContract(ctx, cypher)
	if err != nil {
		return nil, err
	}
	fragment, err := e.fabricProcedureWritePlan(ctx, prepared.fragment)
	if err != nil {
		return nil, err
	}
	if hasCallInTransactions(ctx, cypher) {
		return nil, transactionalCallContextError("transactional CALL on composite targets is not supported")
	}
	catalog := prepared.catalog

	authToken := GetAuthTokenFromContext(ctx)
	localExec := fabric.NewLocalFragmentExecutor(&cypherFabricExecutor{
		base:        e,
		authToken:   authToken,
		autoCommit:  autoCommit,
		transaction: tx,
	}, func(dbName string) (storage.Engine, error) {
		if e.dbManager != nil {
			engineIface, err := e.dbManager.GetStorageForUse(dbName, authToken)
			if err == nil {
				if engine, ok := engineIface.(storage.Engine); ok {
					return engine, nil
				}
				return nil, localizedError(localization.CypherCommandRoutingFabricStorageTypeInvalid(dbName), nil)
			}
		}
		scoped, _, err := e.scopedExecutorForUse(dbName, authToken)
		if err != nil {
			return nil, err
		}
		return scoped.storage, nil
	})
	var remoteExec *fabric.RemoteFragmentExecutor
	if !autoCommit && e.txContext != nil && e.txContext.active {
		if cached := e.txContext.fabricRemoteExe; cached != nil {
			remoteExec = cached
		} else {
			remoteExec = fabric.NewRemoteFragmentExecutor()
			e.txContext.fabricRemoteExe = remoteExec
		}
	} else {
		remoteExec = fabric.NewRemoteFragmentExecutor()
		defer func() { _ = remoteExec.Close() }()
	}

	statsAcc := &queryStatsAccumulator{}
	ctx = context.WithValue(ctx, queryStatsAccumulatorKey{}, statsAcc)
	fabricTrace := &fabric.HotPathTrace{}
	ctx = fabric.WithHotPathTrace(ctx, fabricTrace)
	fabricExecutor := fabric.NewFabricExecutor(catalog, localExec, remoteExec)
	fabricExecutor.SetUnionContract(fabricUnionContract)
	fabricExecutor.SetRemoteValueCodec(fabricRemoteValueCodec)
	fabricExecutor.SetConcurrentExecution(autoCommit && !contract.dynamic)
	fabricExecutor.SetGraphArgumentEvaluator(e.evaluateGraphArguments)
	fabricExecutor.SetRemoteModeUncertainty(func(query string) bool {
		contract, err := readStatementExecutionContract(ctx, query)
		return err != nil || contract.calls
	})
	fabricExecutor.SetGraphAuthorizer(func(ctx context.Context, database, query string) error {
		if err := e.authorizeSelectedDatabase(ctx, database, query); err != nil {
			return err
		}
		return e.recordStatementReference(cypher, database)
	})
	stream, err := fabricExecutor.Execute(ctx, tx, fragment, params, authToken)
	if err != nil {
		// In explicit transactions (autoCommit=false), preserve transaction lifecycle
		// for client-issued COMMIT/ROLLBACK. In autocommit mode, rollback immediately.
		if autoCommit {
			_ = tx.Rollback(nil)
		}
		return nil, fabricGraphReferenceError(err)
	}
	e.setFabricBatchedApplyRowsUsed(fabricTrace.ApplyBatchedLookupRows.Load())
	if autoCommit {
		if err := tx.Commit(nil, nil); err != nil {
			return nil, err
		}
		if tx.WriteShard() != "" {
			publishStatementCommit(ctx)
		}
	}
	if stream == nil {
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	}
	// Schema commands have a void result established by their command executor.
	// USE selects the participant; it does not turn DDL into a graph projection.
	_, command, _, useErr := parseUseClause(cypher, false)
	if useErr != nil {
		return nil, useErr
	}
	if len(stream.Columns) == 0 && !isSchemaCommandStatement(command) {
		columns, err := e.ResultColumns(ctx, cypher, e.resultIncomingScope(), cypherVersionFromContext(ctx) == "25")
		if err != nil {
			return nil, err
		}
		stream.Columns = columns
	}
	if err := e.normalizeFabricRowWrapper(ctx, cypher, stream); err != nil {
		return nil, err
	}
	s := statsAcc.snapshot()
	return resolvedStatementModeResult(&ExecuteResult{
		Columns: stream.Columns,
		Rows:    stream.Rows,
		Stats:   &s,
	}, tx.WriteShard() != ""), nil
}

type fabricPreparedExec struct {
	catalog   *fabric.Catalog
	sessionDB string
	fragment  fabric.Fragment
	hasRemote bool
}

// fabricResultCacheKey binds each local target's identity, catalog generation
// and graph revision in sorted order. Equal numeric revisions on different
// targets, or on a recreated selection, must never reuse the same result.
func (e *StorageExecutor) fabricResultCacheKey(ctx context.Context, prepared *fabricPreparedExec, cypher string, params map[string]interface{}) (string, bool) {
	selections, local := e.fabricLocalSelections(ctx, prepared)
	if !local || !e.StatementCacheSelectionValid() {
		return "", false
	}
	if len(selections) == 0 && e.authorizeSelectedDatabase(ctx, "", cypher) != nil {
		return "", false
	}
	resolver, ok := e.dbManager.(statementCacheScopeResolver)
	if !ok {
		return "", false
	}
	key := cacheKeyBuilder{}
	var scratch [binary.MaxVarintLen64 + 1]byte
	writeCacheKeyString(&key, &scratch, resultCacheEntryKey(ctx, cypher, params))
	key.buf = binary.AppendUvarint(key.buf, e.statementCacheScope.Generation())
	scopes := make([]*multidb.StatementCacheScope, 0, len(selections))
	for _, selection := range selections {
		scope, err := resolver.StatementCacheScope(selection.name)
		if err != nil || !scope.Valid() {
			return "", false
		}
		engine, err := e.dbManager.GetStorageForUse(selection.database, GetAuthTokenFromContext(ctx))
		if err != nil {
			return "", false
		}
		provider, ok := engine.(storage.GraphMutationVersionProvider)
		if !ok {
			return "", false
		}
		revision, supported := provider.GraphMutationVersion()
		if !supported {
			return "", false
		}
		writeCacheKeyString(&key, &scratch, selection.name)
		writeCacheKeyString(&key, &scratch, selection.database)
		key.buf = binary.AppendUvarint(key.buf, scope.Generation())
		key.buf = binary.AppendUvarint(key.buf, revision)
		scopes = append(scopes, scope)
	}
	if !e.StatementCacheSelectionValid() || !statementScopesValid(scopes) {
		return "", false
	}
	return string(key.buf), true
}

type fabricLocalSelection struct{ name, database string }

// Authorization and current catalog resolution precede every result lookup.
// Dynamic and remote targets keep executing through dispatch without caching.
func (e *StorageExecutor) fabricLocalSelections(ctx context.Context, prepared *fabricPreparedExec) (selections []fabricLocalSelection, local bool) {
	if prepared == nil || prepared.catalog == nil || prepared.fragment == nil {
		return nil, false
	}
	seen := make(map[fabricLocalSelection]struct{})
	var collect func(fabric.Fragment) bool
	collect = func(fragment fabric.Fragment) bool {
		switch current := fragment.(type) {
		case *fabric.FragmentExec:
			if current.Graph != nil && current.Graph.IsDynamic() || e.authorizeSelectedDatabase(ctx, current.GraphName, current.Query) != nil {
				return false
			}
			location, err := prepared.catalog.Resolve(current.GraphName)
			if err != nil {
				return false
			}
			target, ok := location.(*fabric.LocationLocal)
			if !ok {
				return false
			}
			name := current.GraphName
			if name == "" {
				name = target.DBName
			}
			selection := fabricLocalSelection{name: name, database: target.DBName}
			if _, listed := seen[selection]; !listed {
				seen[selection] = struct{}{}
				selections = append(selections, selection)
			}
			return collect(current.Input)
		case *fabric.FragmentApply:
			return collect(current.Input) && collect(current.Inner)
		case *fabric.FragmentUnion:
			return collect(current.LHS) && collect(current.RHS)
		case *fabric.FragmentLeaf:
			return collect(current.Input)
		case *fabric.FragmentInit:
			return true
		default:
			return false
		}
	}
	if !collect(prepared.fragment) {
		return nil, false
	}
	sort.Slice(selections, func(i, j int) bool {
		if selections[i].name != selections[j].name {
			return selections[i].name < selections[j].name
		}
		return selections[i].database < selections[j].database
	})
	return selections, true
}
func (e *StorageExecutor) prepareFabricExecution(ctx context.Context, cypher string) (*fabricPreparedExec, error) {
	catalog, err := e.buildFabricCatalog()
	if err != nil {
		return nil, err
	}
	sessionDB := e.currentDatabaseName()
	if dbFromCtx := GetUseDatabaseFromContext(ctx); strings.TrimSpace(dbFromCtx) != "" {
		sessionDB = dbFromCtx
	}
	fragment, err := e.planFabricQuery(ctx, catalog, cypher, sessionDB)
	if err != nil {
		return nil, fabricGraphReferenceError(err)
	}
	return &fabricPreparedExec{
		catalog:   catalog,
		sessionDB: sessionDB,
		fragment:  fragment,
		hasRemote: fabricFragmentHasRemoteTarget(catalog, fragment),
	}, nil
}

func (e *StorageExecutor) preparedFabricFromContext(ctx context.Context) (*fabricPreparedExec, error) {
	if ctx == nil {
		return nil, nil
	}
	v := ctx.Value(fabricPreparedExecKey{})
	if v == nil {
		return nil, nil
	}
	prepared, ok := v.(*fabricPreparedExec)
	if !ok {
		return nil, localizedError(localization.CypherCommandRoutingFabricPreparedContextInvalid(), nil)
	}
	return prepared, nil
}

func fabricFragmentHasRemoteTarget(catalog *fabric.Catalog, f fabric.Fragment) bool {
	if catalog == nil || f == nil {
		return false
	}
	switch frag := f.(type) {
	case *fabric.FragmentExec:
		loc, err := catalog.Resolve(frag.GraphName)
		if err != nil {
			return false
		}
		_, isRemote := loc.(*fabric.LocationRemote)
		return isRemote
	case *fabric.FragmentApply:
		return fabricFragmentHasRemoteTarget(catalog, frag.Input) || fabricFragmentHasRemoteTarget(catalog, frag.Inner)
	case *fabric.FragmentUnion:
		return fabricFragmentHasRemoteTarget(catalog, frag.LHS) || fabricFragmentHasRemoteTarget(catalog, frag.RHS)
	case *fabric.FragmentLeaf:
		return fabricFragmentHasRemoteTarget(catalog, frag.Input)
	case *fabric.FragmentInit:
		return false
	default:
		return false
	}
}

// fabricUnionContract gives the UNION branches Fabric combines the semantics
// executeUnion gives a UNION on one graph.
var fabricUnionContract = fabric.UnionContract{
	ColumnOrder:  unionColumnOrder,
	ColumnsError: unionColumnsError,
	NewDistinct: func() func(row []interface{}) bool {
		seen := make(map[string]bool)
		return func(row []interface{}) bool {
			key := cypherValueKey(row, cypherEquivalenceContract)
			if seen[key] {
				return true
			}
			seen[key] = true
			return false
		}
	},
}

// fabricSingleGraphStatement is cypher without the USE clauses the Fabric
// planner reads (FabricPlanner.SingleGraphStatement): the one statement whose
// variable scopes are checked, as Neo4j checks a composite statement's, before
// any part of it plans or runs. A statement the planner can't read is checked
// as it is, and planning reports the error.
func fabricSingleGraphStatement(ctx context.Context, cypher string) string {
	planner := fabric.NewFabricPlanner(nil)
	planner.SetClauseKeywordNameReader(clauseKeywordUsedAsName)
	planner.SetCallImportReader(func(scope string, scoped bool, body string) ([]string, error) {
		return callSubqueryImportedVariables(ctx, scope, scoped, body)
	})
	statement, err := planner.SingleGraphStatement(cypher)
	if err != nil {
		return cypher
	}
	return statement
}

func (e *StorageExecutor) planFabricQuery(ctx context.Context, catalog *fabric.Catalog, cypher, sessionDB string) (fabric.Fragment, error) {
	if e.fabricPlanCache != nil {
		if cached, found := e.fabricPlanCache.Get(cypher, sessionDB); found && cached != nil {
			return cached, nil
		}
	}

	planner := fabric.NewFabricPlanner(catalog)
	// A name spelled UNION, OPTIONAL or RETURN is read as ordinary statements read it.
	planner.SetClauseKeywordNameReader(clauseKeywordUsedAsName)
	planner.SetCallImportReader(func(scope string, scoped bool, body string) ([]string, error) {
		return callSubqueryImportedVariables(ctx, scope, scoped, body)
	})
	fragment, err := planner.Plan(cypher, sessionDB)
	if err != nil {
		return nil, err
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if e.fabricPlanCache != nil {
		e.fabricPlanCache.Put(cypher, sessionDB, fragment)
	}
	return fragment, nil
}

// fabricProcedureWritePlan resolves the registered CALL contract at statement
// admission, just as the native transaction route does. Cached structural plans
// stay immutable and do not retain an obsolete procedure mode after registration.
// The existing Fabric participant owner then handles writes and their rollback.
func (e *StorageExecutor) fabricProcedureWritePlan(ctx context.Context, fragment fabric.Fragment) (fabric.Fragment, error) {
	switch current := fragment.(type) {
	case *fabric.FragmentExec:
		input, err := e.fabricProcedureWritePlan(ctx, current.Input)
		if err != nil {
			return nil, err
		}
		contract, err := readStatementExecutionContract(ctx, current.Query)
		if err != nil {
			return nil, err
		}
		write := contract.writes
		if e.dbManager != nil && e.dbManager.IsCompositeDatabase(current.GraphName) {
			write = false
		}
		if input == current.Input && write == current.IsWrite {
			return current, nil
		}
		copy := *current
		copy.Input, copy.IsWrite = input, write
		return &copy, nil
	case *fabric.FragmentApply:
		input, err := e.fabricProcedureWritePlan(ctx, current.Input)
		if err != nil {
			return nil, err
		}
		inner, err := e.fabricProcedureWritePlan(ctx, current.Inner)
		if err != nil {
			return nil, err
		}
		if input == current.Input && inner == current.Inner {
			return current, nil
		}
		copy := *current
		copy.Input, copy.Inner = input, inner
		return &copy, nil
	case *fabric.FragmentUnion:
		left, err := e.fabricProcedureWritePlan(ctx, current.LHS)
		if err != nil {
			return nil, err
		}
		right, err := e.fabricProcedureWritePlan(ctx, current.RHS)
		if err != nil {
			return nil, err
		}
		if left == current.LHS && right == current.RHS {
			return current, nil
		}
		copy := *current
		copy.LHS, copy.RHS = left, right
		return &copy, nil
	case *fabric.FragmentLeaf:
		input, err := e.fabricProcedureWritePlan(ctx, current.Input)
		if err != nil {
			return nil, err
		}
		if input == current.Input {
			return current, nil
		}
		copy := *current
		copy.Input = input
		return &copy, nil
	default:
		return fragment, nil
	}
}

func (e *StorageExecutor) normalizeFabricRowWrapper(ctx context.Context, cypher string, stream *fabric.ResultStream) error {
	if stream == nil || !stream.RowWrapper || len(stream.Columns) != 1 || len(stream.Rows) == 0 {
		return nil
	}
	inferred, err := e.ResultColumns(ctx, cypher, e.resultIncomingScope(), cypherGrammarVersion(cypher) == "25")
	if err != nil {
		return err
	}
	if len(inferred) == 0 {
		return nil
	}
	projectedRows := make([][]interface{}, 0, len(stream.Rows))
	for _, row := range stream.Rows {
		if len(row) == 0 {
			continue
		}
		m, ok := normalizeFabricRowMap(row[0])
		if !ok {
			continue
		}
		out := make([]interface{}, len(inferred))
		sourceID, _ := m["sourceId"]
		for i, col := range inferred {
			if v, ok := m[col]; ok {
				out[i] = v
				continue
			}
			if sourceID != nil {
				if v, ok := lookupColumnBySourceIDInRows(m["rows"], sourceID, col); ok {
					out[i] = v
				}
			}
		}
		projectedRows = append(projectedRows, out)
	}
	if len(projectedRows) == 0 {
		return nil
	}
	stream.Columns = inferred
	stream.Rows = projectedRows
	return nil
}

func normalizeFabricRowMap(v interface{}) (map[string]interface{}, bool) {
	switch m := v.(type) {
	case map[string]interface{}:
		return m, true
	case map[interface{}]interface{}:
		out := make(map[string]interface{}, len(m))
		for k, val := range m {
			out[fmt.Sprint(k)] = val
		}
		return out, true
	default:
		return nil, false
	}
}

func lookupColumnBySourceIDInRows(rowsAny interface{}, sourceID interface{}, col string) (interface{}, bool) {
	switch rows := rowsAny.(type) {
	case []interface{}:
		for _, item := range rows {
			m, ok := item.(map[string]interface{})
			if !ok {
				continue
			}
			if sameSourceID(m["sourceId"], sourceID) {
				v, exists := m[col]
				return v, exists
			}
		}
	case []map[string]interface{}:
		for _, m := range rows {
			if sameSourceID(m["sourceId"], sourceID) {
				v, exists := m[col]
				return v, exists
			}
		}
	}
	return nil, false
}

func sameSourceID(a interface{}, b interface{}) bool {
	normalize := func(v interface{}) string {
		s := strings.TrimSpace(fmt.Sprint(v))
		return strings.Trim(s, `"`)
	}
	return normalize(a) == normalize(b)
}

func (e *StorageExecutor) currentDatabaseName() string {
	if composite, ok := e.storage.(interface{ CompositeName() string }); ok {
		if name := strings.TrimSpace(composite.CompositeName()); name != "" {
			return name
		}
	}
	if ns, ok := e.storage.(interface{ Namespace() string }); ok {
		if name := strings.TrimSpace(ns.Namespace()); name != "" {
			return name
		}
	}
	return "nornic"
}

func (e *StorageExecutor) buildFabricCatalog() (*fabric.Catalog, error) {
	catalog := fabric.NewCatalog()
	for _, db := range e.dbManager.ListDatabases() {
		dbName := strings.TrimSpace(db.Name())
		if dbName == "" {
			continue
		}
		catalog.Register(dbName, &fabric.LocationLocal{DBName: dbName})
		for alias := range e.dbManager.ListAliases(dbName) {
			alias = strings.TrimSpace(alias)
			if alias != "" {
				catalog.Register(alias, &fabric.LocationLocal{DBName: dbName})
			}
		}

		if db.Type() != "composite" {
			continue
		}
		constituents, err := e.dbManager.GetCompositeConstituents(dbName)
		if err != nil {
			return nil, localizedError(localization.CypherCommandRoutingFabricConstituentsFailed(dbName, err), err)
		}
		for _, raw := range constituents {
			ref, ok := toConstituentRef(raw)
			if !ok || strings.TrimSpace(ref.Alias) == "" {
				continue
			}
			qualified := dbName + "." + ref.Alias
			if strings.EqualFold(strings.TrimSpace(ref.Type), "remote") {
				catalog.Register(qualified, &fabric.LocationRemote{
					DBName:   ref.DatabaseName,
					URI:      ref.URI,
					AuthMode: strings.TrimSpace(ref.AuthMode),
					User:     ref.User,
					Password: ref.Password,
				})
				continue
			}
			catalog.Register(qualified, &fabric.LocationLocal{DBName: ref.DatabaseName})
		}
	}
	return catalog, nil
}

func toConstituentRef(raw interface{}) (multidb.ConstituentRef, bool) {
	if ref, ok := raw.(multidb.ConstituentRef); ok {
		return ref, true
	}
	m, ok := raw.(map[string]interface{})
	if !ok {
		return multidb.ConstituentRef{}, false
	}
	return multidb.ConstituentRef{
		Alias:        mapString(m, "alias"),
		DatabaseName: mapString(m, "database_name"),
		Type:         mapString(m, "type"),
		AccessMode:   mapString(m, "access_mode"),
		URI:          mapString(m, "uri"),
		SecretRef:    mapString(m, "secret_ref"),
		AuthMode:     mapString(m, "auth_mode"),
		User:         mapString(m, "user"),
		Password:     mapString(m, "password"),
	}, true
}

func mapString(m map[string]interface{}, key string) string {
	if v, ok := m[key]; ok {
		if s, ok := v.(string); ok {
			return s
		}
	}
	return ""
}

type cypherFabricExecutor struct {
	base            *StorageExecutor
	authToken       string
	autoCommit      bool
	transaction     *fabric.FabricTransaction
	localDispatchMu sync.Mutex

	mu sync.Mutex
	// localTxExecBySub holds the sub-transaction executors of a statement
	// run outside an explicit transaction; an explicit transaction keeps
	// them in its TransactionContext (localShardTxExecutors).
	localTxExecBySub map[string]*StorageExecutor
}

// localShardTxExecutors is the map of sub-transaction executors by shard
// name: the explicit transaction's, so its statements share one
// sub-transaction per constituent, or else this statement's own.
func (c *cypherFabricExecutor) localShardTxExecutors() map[string]*StorageExecutor {
	if c.base != nil && c.base.txContext != nil && c.base.txContext.active {
		if c.base.txContext.fabricLocalTxExec == nil {
			c.base.txContext.fabricLocalTxExec = make(map[string]*StorageExecutor)
		}
		return c.base.txContext.fabricLocalTxExec
	}
	if c.localTxExecBySub == nil {
		c.localTxExecBySub = make(map[string]*StorageExecutor)
	}
	return c.localTxExecBySub
}

func (c *cypherFabricExecutor) ExecuteQuery(ctx context.Context, dbName string, engine storage.Engine, query string, params map[string]interface{}) ([]string, [][]interface{}, error) {
	return c.ExecuteQueryWithRecord(ctx, dbName, engine, query, params, nil)
}

func (c *cypherFabricExecutor) ExecuteRecordQuery(ctx context.Context, dbName, query string, params, recordBindings map[string]interface{}) ([]string, [][]interface{}, bool, error) {
	clauses, supported := canExecuteAsPipeline(ctx, query)
	if !supported || containsRelationshipPattern(query) {
		return nil, nil, false, nil
	}
	for _, clause := range clauses {
		if clause.kind != pipelineClauseWith && clause.kind != pipelineClauseUnwind && clause.kind != pipelineClauseReturn {
			return nil, nil, false, nil
		}
	}
	keywords := queryKeywords(query)
	if keywords["MATCH"] || keywords["STARTNODE"] || keywords["ENDNODE"] || keywords["SHORTESTPATH"] {
		return nil, nil, false, nil
	}
	engine := c.base.storage
	executor := c.base.cloneForStorage(engine)
	if err := executor.bindFabricStatementCacheScope(ctx, dbName); err != nil {
		return nil, nil, true, err
	}
	executor.fabricRecordBindings = recordBindings
	ctx = withExecutionDatabase(WithAuthToken(ctx, c.authToken), dbName)
	columns, rows, err := c.executeFragmentQuery(ctx, executor, query, params)
	return columns, rows, true, err
}

func (c *cypherFabricExecutor) ExecuteQueryWithRecord(ctx context.Context, dbName string, engine storage.Engine, query string, params map[string]interface{}, recordBindings map[string]interface{}) ([]string, [][]interface{}, error) {
	ctx = WithAuthToken(ctx, c.authToken)
	base := c.base
	composite, compositeRoot := engine.(*storage.CompositeEngine)
	ctx = context.WithValue(ctx, dynamicWriteAdmissionKey{}, dynamicWriteAdmission(func(callCtx context.Context, caller *StorageExecutor, statement string) error {
		if compositeRoot {
			return nil
		} // The actual mutation selects its physical owner below.
		return c.promoteResolvedStatement(callCtx, caller, dbName, engine, statement)
	}))
	if compositeRoot {
		c.localDispatchMu.Lock()
		defer c.localDispatchMu.Unlock()
		engine = composite.WithConstituentAccess(func(database string, physical storage.Engine, write bool) (storage.Engine, error) {
			return c.compositeParticipantStorage(ctx, database, physical, write)
		})
	} else if sub, ok := fabric.SubTransactionFromContext(ctx); ok {
		if !c.autoCommit || c.transaction != nil && c.transaction.WriteShard() == sub.ShardName {
			// Fabric has one write participant. Its local fragments share one
			// transactional executor until the coordinator admits COMMIT.
			// Concurrent read-only participants keep their independent path.
			if c.autoCommit {
				c.localDispatchMu.Lock()
				defer c.localDispatchMu.Unlock()
			}
			txExec, err := c.ensureLocalShardTxExecutor(ctx, sub, dbName, engine)
			if err != nil {
				return nil, nil, err
			}
			base = txExec
			engine = txExec.storage
		}
	}
	// A fragment view owns its removable catalog selection while the retained
	// shard executor keeps the underlying database transaction's lifetime.
	exec := base.cloneForStorage(engine)
	if err := exec.bindFabricStatementCacheScope(ctx, dbName); err != nil {
		return nil, nil, err
	}
	if len(recordBindings) > 0 {
		exec.fabricRecordBindings = recordBindings
		query = stripLeadingWithImportsForFabricRecord(query, recordBindings)
	}
	ctx = withExecutionDatabase(ctx, dbName)
	return c.executeFragmentQuery(ctx, exec, query, params)
}

func (c *cypherFabricExecutor) executeFragmentQuery(ctx context.Context, exec *StorageExecutor, query string, params map[string]interface{}) ([]string, [][]interface{}, error) {
	previousIdentityScope := exec.graphIdentityScope
	var catalog *fabric.Catalog
	if prepared, err := exec.preparedFabricFromContext(ctx); err == nil && prepared != nil {
		catalog = prepared.catalog
	}
	exec.graphIdentityScope = newGraphIdentityScope(catalog, exec.executionDatabaseName(ctx), exec.dbManager, c.authToken)
	defer func() { exec.graphIdentityScope = previousIdentityScope }()
	// Local fragments bypass implicit execution's decision. Classify this
	// fragment itself: writes and procedures must retain full node reads.
	exec.readOnlyQueryNodes = exec.readsQueryNodesWithoutVectors(exec.analyzer.Analyze(ctx, query))
	result, err := exec.executeInternal(ctx, query, params)
	if err != nil {
		return nil, nil, err
	}
	if result == nil {
		return []string{}, [][]interface{}{}, nil
	}
	if acc := queryStatsAccumulatorFromContext(ctx); acc != nil {
		acc.add(result.Stats)
	}
	return result.Columns, result.Rows, nil
}

func stripLeadingWithImportsForFabricRecord(query string, recordBindings map[string]interface{}) string {
	if len(recordBindings) == 0 {
		return query
	}
	trimmed := strings.TrimSpace(query)
	if !strings.HasPrefix(upperASCII(trimmed), "WITH ") {
		return query
	}
	withEnd := findLeadingWithEndLocal(trimmed)
	if withEnd <= 0 || withEnd >= len(trimmed) {
		return query
	}
	withClause := strings.TrimSpace(trimmed[len("WITH "):withEnd])
	rest := strings.TrimSpace(trimmed[withEnd:])
	if rest == "" {
		return query
	}
	// Stripping is safe for simple imported bindings when the next clause is a
	// top-level read/projection/pipeline clause that can resolve identifiers from
	// Fabric record bindings.
	if !(startsWithKeywordFold(rest, "MATCH") ||
		startsWithKeywordFold(rest, "OPTIONAL MATCH") ||
		startsWithKeywordFold(rest, "RETURN") ||
		startsWithKeywordFold(rest, "UNWIND") ||
		startsWithKeywordFold(rest, "USE")) {
		return query
	}
	imports := splitTopLevelComma(withClause)
	if len(imports) == 0 {
		return query
	}
	for _, item := range imports {
		name := strings.TrimSpace(item)
		if name == "" || strings.Contains(name, " ") {
			return query
		}
		if _, ok := recordBindings[name]; !ok {
			return query
		}
	}
	rewritten := rest
	local := localOccurrences{text: rest}
	for _, item := range imports {
		name := strings.TrimSpace(item)
		rewritten = replaceIdentifierOutsideQuotesUnless(rewritten, name, "$"+name, &local)
	}
	return rewritten
}

func findLeadingWithEndLocal(query string) int {
	const prefix = "WITH "
	if len(query) <= len(prefix) {
		return -1
	}
	body := query[len(prefix):]
	end := -1
	for _, keyword := range [...]string{
		"MATCH", "OPTIONAL MATCH", "RETURN", "WHERE", "USE", "WITH", "CALL",
		"CREATE", "MERGE", "UNWIND", "SET", "DELETE", "DETACH DELETE",
	} {
		if index := topLevelKeywordIndex(body, keyword); index >= 0 && (end < 0 || index < end) {
			end = index
		}
	}
	if end < 0 {
		return -1
	}
	return len(prefix) + end
}
func (c *cypherFabricExecutor) ensureLocalShardTxExecutor(ctx context.Context, sub *fabric.SubTransaction, dbName string, engine storage.Engine) (*StorageExecutor, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	executors := c.localShardTxExecutors()
	if existing := executors[sub.ShardName]; existing != nil {
		return existing, nil
	}

	txExec := NewStorageExecutor(engine)
	txExec.ShareStatementCachesFrom(c.base)
	txExec.deferFlush = c.base.deferFlush
	txExec.ShareEmbedderFrom(c.base)
	c.base.shareSearchFor(txExec, storageDatabaseName(engine))
	txExec.inferenceManager = c.base.inferenceManager
	txExec.onNodeMutated = c.base.onNodeMutated
	txExec.defaultEmbeddingDimensions = c.base.defaultEmbeddingDimensions
	txExec.dbManager = c.base.dbManager
	if err := txExec.bindStatementCacheScope(dbName); err != nil {
		return nil, err
	}
	txExec.vectorRegistry = c.base.vectorRegistry
	txExec.vectorIndexSpaces = c.base.vectorIndexSpaces

	beginCtx := WithTransactionControl(WithAuthToken(ctx, c.authToken))
	if _, err := txExec.Execute(beginCtx, "BEGIN", nil); err != nil {
		return nil, localizedError(localization.CypherCommandRoutingFabricShardTransactionFailed(dbName, err), err)
	}

	terminalCtx := context.WithoutCancel(beginCtx)
	commitFn := func(_ *fabric.SubTransaction) error {
		_, err := txExec.Execute(terminalCtx, "COMMIT", nil)
		return err
	}
	rollbackFn := func(_ *fabric.SubTransaction) error {
		_, err := txExec.Execute(terminalCtx, "ROLLBACK", nil)
		return err
	}
	if tx := c.fabricTransaction(); tx != nil {
		if err := tx.BindParticipantCallbacks(sub.ShardName, commitFn, rollbackFn); err != nil {
			return nil, err
		}
	}

	executors[sub.ShardName] = txExec
	return txExec, nil
}

// evaluateGraphArguments evaluates a dynamic graph reference's arguments
// (USE graph.byName(g)) for Fabric: values holds the statement's
// parameters and the current row's variables.
func (e *StorageExecutor) evaluateGraphArguments(ctx context.Context, expressions []string, values map[string]interface{}) ([]string, error) {
	ctx = withQueryParams(ctx, values)
	out := make([]string, len(expressions))
	for i, expression := range expressions {
		value, ok := e.evaluateRowExpressionWithContext(ctx, expression, pipelineRow(values))
		if !ok {
			if err, undefined := undefinedVariableError(expression); undefined {
				return nil, err
			}
			return nil, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
				localization.CypherCommandRoutingGraphFunctionArgumentInvalid(expression))
		}
		text, isString := value.(string)
		if !isString {
			// Neo4j: "Expected <argument> to be a STRING, but it was an INTEGER".
			return nil, localizedStatusError("Neo.ClientError.Statement.TypeError", "TypeError",
				localization.CypherCommandRoutingGraphFunctionArgumentType(expression, cypherTypeSystemNameWithArticle(value)))
		}
		out[i] = text
	}
	return out, nil
}

// fabricGraphReferenceError reports a dynamic graph reference Fabric could
// not resolve with its Neo4j status: a graph that doesn't exist is
// DatabaseNotFound "Graph not found: <name>".
func fabricGraphReferenceError(err error) error {
	if errors.Is(err, fabric.ErrMixedUnion) {
		return unionMixedError()
	}
	var notFound *fabric.GraphNotFoundError
	if errors.As(err, &notFound) {
		return localizedStatusError("Neo.ClientError.Database.DatabaseNotFound", "DatabaseNotFound", localization.CypherCommandRoutingGraphNotFound(notFound.Name))
	}
	var reference *fabric.GraphReferenceError
	if errors.As(err, &reference) {
		return localizedStatusError(reference.Code, "GraphReference", reference.Message)
	}
	var syntax *fabric.UseSyntaxError
	if errors.As(err, &syntax) {
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", syntax.Message)
	}
	return err
}

func (e *cypherFabricExecutor) CachedResultColumns(ctx context.Context, query string, incoming []string) resultmetadata.Names {
	return e.base.CachedResultColumns(ctx, query, incoming)
}

func (e *cypherFabricExecutor) ResultProjection(ctx context.Context, query string, incoming []string) resultmetadata.Projection {
	return e.base.ResultProjection(ctx, query, incoming)
}

func (c *cypherFabricExecutor) fabricTransaction() *fabric.FabricTransaction {
	if c.transaction != nil {
		return c.transaction
	}
	if c.base != nil && c.base.txContext != nil {
		tx, _ := c.base.txContext.tx.(*fabric.FabricTransaction)
		return tx
	}
	return nil
}

package cypher

import (
	"context"
	"strings"

	"github.com/orneryd/nornicdb/pkg/config"
	"github.com/orneryd/nornicdb/pkg/fabric"
	"github.com/orneryd/nornicdb/pkg/localization"
)

// executeInternal executes a Cypher fragment as part of a larger execution flow.
//
// Unlike Execute(), this does NOT:
//   - apply query limits / rate limiting
//   - consult or populate result caches
//   - start implicit transactions for write queries
//
// The key property is that internal subqueries/procedure bodies participate in
// the caller's transaction context (explicit tx or implicit tx wrapper carried
// on ctx), avoiding nested implicit transactions and misrouting.
// executeUserStatement runs statement text a procedure was given to run
// (apoc.cypher.run / runMany, apoc.periodic.iterate / commit,
// apoc.export.*.query): a user's statement, which may not call NornicDB's
// internal functions (#1105). It runs inside the caller's statement, a data
// statement, so an administration command there is refused as after any
// data statement (ForbiddenDueToTransactionType), in auto-commit as in an
// explicit transaction.
func (e *StorageExecutor) executeUserStatement(ctx context.Context, statement string, params map[string]interface{}) (result *ExecuteResult, err error) {
	if totals, ok := ctx.Value(procedureStatementStatsKey{}).(*procedureStatementStats); ok && totals != nil {
		// Every nested procedure installs its own invocation collector. Its
		// completed summary enters this collector only through this result.
		defer func() {
			if err == nil && result != nil {
				totals.record(result.Stats)
			}
		}()
	}
	if err := internalFunctionCallError(statement); err != nil {
		// Refused like any statement of the caller's transaction: it fails
		// an explicit transaction (executeInternal fails it for the rest).
		return nil, e.failTransaction(ctx, err)
	}
	if StatementDatabase("", statement) == "system" {
		var transaction any
		if wrapper, ok := ctx.Value(ctxKeyTxStorage).(*transactionStorageWrapper); ok {
			transaction = wrapper.tx
		} else if e.txContext != nil && e.txContext.active {
			transaction = e.txContext.tx
		}
		return nil, e.failTransaction(ctx, statementTypeError(ctx, statement, "Administration", "Data", transaction))
	}
	return e.executeInternal(ctx, statement, params)
}

func (e *StorageExecutor) executeInternal(ctx context.Context, cypher string, params map[string]interface{}) (result *ExecuteResult, retErr error) {
	if e.txContext != nil && e.txContext.active {
		defer func() { e.failTransaction(ctx, retErr) }()
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	cypher = normalizeCypherSyntaxConfusables(cypher)
	if config.IsCypherQueryNormalizationEnabled() {
		var err error
		cypher, _, err = normalizeQueryText(ctx, cypher)
		if err != nil {
			return nil, err
		}
	}
	cypher, _ = canonicalizeNumericLiterals(cypher)
	cypher, _ = canonicalizeFunctionAliases(cypher)
	if cypherVersionFromContext(ctx) == "25" {
		cypher, _ = separateCypher25Parameters(cypher)
	}
	cypher, _ = desugarStandaloneOrderClauses(cypher)
	cypher = strings.TrimSpace(cypher)
	cypher = trimTrailingStatementDelimiters(cypher)
	if err := e.validateStatementFraming(ctx, cypher); err != nil {
		return nil, err
	}
	finishTerminated := false
	if stripped, ok := stripUnionBranchFinishes(ctx, cypher); ok {
		cypher = strings.TrimSpace(stripped)
		finishTerminated = true
		ctx = withFinishedStatement(ctx, cypher)
	}
	if cypher == "" {
		if finishTerminated {
			return &ExecuteResult{}, nil
		}
		return nil, localizedError(localization.CypherCoreEmptyQuery(), nil)
	}
	if finishTerminated {
		defer func() {
			completeFinishedResult(result)
		}()
	}

	if use, remaining, hasUse, err := parseUseClause(cypher, false); hasUse || err != nil {
		if err != nil {
			return nil, err
		}
		if err := e.dynamicUseError(use); err != nil {
			return nil, err
		}
		return e.executeOnDatabase(ctx, use.Name, remaining, params, true)
	}
	if err := e.admitTransactionStatement(ctx, cypher); err != nil {
		return nil, err
	}
	routed, err := e.routeAdministrationStatement(ctx, cypher)
	if err != nil {
		return nil, err
	}
	if routed != e {
		return routed.executeInternal(ctx, cypher, params)
	}
	if err := e.authorizeSelectedDatabase(ctx, "", cypher); err != nil {
		return nil, err
	}
	e.statementAdmitted(ctx)
	if err := e.systemDatabaseWriteError(ctx, cypher); err != nil {
		return nil, err
	}

	// Local fragments own their lowering and restore generated names before
	// returning to Fabric or their containing expression.
	desugared, labelRewrite, err := desugarLabelExpressions(ctx, cypher, params, cypherVersionFromContext(ctx) == "25")
	if err != nil {
		return nil, err
	}
	if labelRewrite != nil {
		cypher = desugared
		defer func() { result, retErr = labelRewrite.restore(withoutGeneratedColumns(result), retErr) }()
	}

	// Basic syntax validation to preserve existing error behavior.
	if err := e.validateSyntax(ctx, cypher, cypherVersionFromContext(ctx) == "25"); err != nil {
		return nil, err
	}
	if err := e.validateTransactionalCalls(ctx, cypher, nil); err != nil {
		return nil, err
	}
	if err := e.validateDuplicateReturnColumnName(ctx, cypher, quotedVariableNamesFor(ctx, cypher)); err != nil {
		return nil, err
	}
	if err := e.statementParametersError(ctx, cypher, params); err != nil {
		return nil, err
	}

	params = mergeInheritedQueryParams(ctx, params)
	params = normalizeQueryParameters(params)
	ctx = withQueryParams(ctx, params)
	if err := e.validateBoundParameterExpressions(ctx, cypher, params); err != nil {
		return nil, err
	}
	upper := e.cachedUpperQuery(cypher)
	// This is executable, normalized statement text with its actual parameter
	// values installed. Nested dynamic handlers return through this same gate;
	// no admission parser attempts to reconstruct their arguments.
	if err := e.admitResolvedStatementWrite(ctx, cypher); err != nil {
		return nil, err
	}

	// If we're in an explicit transaction, execute within it.
	if e.txContext != nil && e.txContext.active {
		return e.executeInTransaction(ctx, cypher, upper)
	}

	// Otherwise, stay on the caller's execution path (no implicit tx starts here).
	result, retErr = e.executeWithoutTransaction(ctx, cypher, upper)
	if retErr == nil && !e.inTransaction(ctx) {
		// An opaque procedure argument can contain a write even when its
		// caller opened no implicit transaction. Those effects apply directly.
		// A Fabric fragment instead belongs to the coordinator's commit.
		if _, pending := fabric.FabricTransactionFromContext(ctx); !pending {
			e.publishDirectStatementCommit(ctx, cypher)
		}
	}
	return result, retErr
}

func (e *StorageExecutor) validateBoundParameterExpressions(ctx context.Context, cypher string, params map[string]interface{}) error {
	if err := e.validateTransactionalCalls(ctx, cypher, params); err != nil {
		return err
	}
	// Only parse parameterized arithmetic when an operand's actual type can
	// be rejected; ordinary numeric hot paths keep their single cheap scan.
	if len(params) > 0 && parameterMayMismatchOperator(cypher, params) {
		if clauses, ok := splitPipelineClauses(ctx, cypher); ok {
			for _, clause := range clauses {
				if err := e.validateStaticOperatorTypes(ctx, clause, staticTypeScope{cypher25: cypherVersionFromContext(ctx) == "25"}, nil, params); err != nil {
					return err
				}
			}
		}
	}
	if err := validateStaticPropertyAccessParameters(ctx, cypher, params); err != nil {
		return err
	}
	if err := validateStaticFunctionParameters(ctx, cypher, params, cypherVersionFromContext(ctx) == "25"); err != nil {
		return err
	}
	// A transactional CALL commits independently before later runtime
	// pagination opens. Static pagination admission still runs at compilation;
	// its runtime values are checked by the owning pipeline operator.
	if !hasCallInTransactions(ctx, cypher) {
		if err := e.validateRuntimePaginationExpressions(ctx, extractPaginationExpressions(ctx, cypher)...); err != nil {
			return err
		}
	}
	return validateListOperands(ctx, cypher, params)
}

