import (
	"container/heap"
	"context"
	valueconvert "github.com/orneryd/nornicdb/pkg/convert"
	"sort"
	"strconv"
	"strings"

	"github.com/orneryd/nornicdb/pkg/math/vector"
	"github.com/orneryd/nornicdb/pkg/search"
	"github.com/orneryd/nornicdb/pkg/storage"
	"github.com/orneryd/nornicdb/pkg/util"
)

type parsedSimpleMatchRelationshipPattern struct {
	leftVar     string
	leftLabels  []string
	rightVar    string
	rightLabels []string
	relVar      string
	relType     string
	isReverse   bool
}

// tryFastPathMatchVectorCosine handles a strict vector-search shape:
//
//	MATCH (n:Label)
//	RETURN ..., vector.similarity.cosine(n.<prop>, <query>) AS <scoreAlias>, ...
//	ORDER BY <scoreAlias|same_expression> DESC
//	LIMIT <k>
//
// It requires a matching VECTOR index on (Label, prop) using cosine similarity.
// If any requirement is not met, it cleanly falls back to normal Cypher execution.
func (e *StorageExecutor) tryFastPathMatchVectorCosine(ctx context.Context, cypher string, upperQuery string) (*ExecuteResult, bool) {
	trimmed := strings.TrimSpace(cypher)
	if !strings.HasPrefix(strings.TrimSpace(upperQuery), "MATCH") {
		return nil, false
	}

	// Keep this shape intentionally narrow to avoid semantic drift.
	for _, kw := range []string{
		"SKIP", "WITH", "UNWIND", "OPTIONAL MATCH", "CALL",
		"CREATE", "MERGE", "DELETE", "DETACH DELETE", "SET", "REMOVE", "UNION",
	} {
		if topLevelKeywordIndex(trimmed, kw) > 0 {
			return nil, false
		}
	}

	returnIdx := topLevelKeywordIndex(trimmed, "RETURN")
	orderIdx := topLevelKeywordIndex(trimmed, "ORDER BY")
	limitIdx := topLevelKeywordIndex(trimmed, "LIMIT")
	if returnIdx <= 0 || orderIdx <= returnIdx || limitIdx <= orderIdx {
		return nil, false
	}

	matchPart := strings.TrimSpace(trimmed[len("MATCH"):returnIdx])
	preWhereClause := ""
	if preWhereIdx := topLevelKeywordIndex(matchPart, "WHERE"); preWhereIdx > 0 {
		preWhereClause = strings.TrimSpace(matchPart[preWhereIdx+len("WHERE"):])
		matchPart = strings.TrimSpace(matchPart[:preWhereIdx])
		if preWhereClause == "" {
			return nil, false
		}
	}
	if !e.isSingleNodePattern(matchPart) {
		return nil, false
	}
	if !patternMapsAreConstant(matchPart) {
		return nil, false
	}
	var varName string
	var label string
	var matchProps map[string]interface{}
	if strings.Contains(matchPart, "{") {
		nodePattern, shapeErr := readNodePattern(ctx, matchPart, patternPropertyKeys)
		if shapeErr != nil {
			recordExpressionFailure(ctx, shapeErr)
			return nil, true
		}
		varName = strings.TrimSpace(nodePattern.variable)
		if varName == "" || len(nodePattern.labels) != 1 {
			return nil, false
		}
		label = nodePattern.labels[0]
		matchProps = nodePattern.properties
	} else {
		parsedVar, labels, ok := parseSimpleMatchSingleNodePattern(matchPart)
		if !ok || len(labels) != 1 {
			return nil, false
		}
		varName = parsedVar
		label = labels[0]
	}

	returnPart := strings.TrimSpace(trimmed[returnIdx+len("RETURN") : orderIdx])
	returnItems := e.parseReturnItems(ctx, returnPart)
	if len(returnItems) == 0 {
		return nil, false
	}

	cosineIdx, vectorProp, queryExpr, scoreRef, ok := parseCosineReturnShape(returnItems, varName)
	if !ok {
		return nil, false
	}
	preWhereNotNullProp := ""
	if preWhereClause != "" {
		if prop, ok := parseFastPathPropertyNotNullPredicate(preWhereClause, varName); ok {
			preWhereNotNullProp = prop
		}
	}

	orderPart := strings.TrimSpace(trimmed[orderIdx+len("ORDER BY") : limitIdx])
	orderDesc, ok := parseOrderByScoreDirection(orderPart, scoreRef)
	if !ok {
		return nil, false
	}

	limitPart := strings.TrimSpace(trimmed[limitIdx+len("LIMIT"):])
	limit, ok := parseFastPathLimit(ctx, limitPart)
	if !ok || limit < 0 {
		return nil, false
	}
	if limit == 0 {
		columns := make([]string, len(returnItems))
		for i, item := range returnItems {
			columns[i] = item.column()
		}
		e.markCosineVectorIndexFastPathUsed()
		return &ExecuteResult{Columns: columns, Rows: [][]interface{}{}, Stats: &QueryStats{}}, true
	}

	indexName, hasIndex := findCosineVectorIndexName(e.storage.GetSchema(), label, vectorProp, storage.ConstraintEntityNode)
	if !hasIndex {
		return nil, false
	}

	scoreExprIsAlias := make([]bool, len(returnItems))
	scoreExprIsAlias[cosineIdx] = true
	projectedProps, projectionOK := nodeProjectionPropertiesForVectorFastPath(varName, vectorProp, returnItems, scoreExprIsAlias, preWhereClause, preWhereNotNullProp, matchProps)
	if !projectionOK {
		projectedProps = nil
	}
	needsExactCandidates := len(matchProps) > 0 || (preWhereClause != "" && preWhereNotNullProp != vectorProp)
	candidateLimit := chooseVectorCandidateLimit(limit, needsExactCandidates)
	var nodeScores []vectorNodeScore
	if needsExactCandidates {
		nodeScores, ok = e.fetchCosineNodeScoresNoIndexExact(ctx, label, vectorProp, int(^uint(0)>>1), queryExpr, orderDesc)
	} else {
		nodeScores, ok = e.fetchCosineNodeScores(ctx, indexName, candidateLimit, queryExpr, orderDesc, projectedProps)
	}
	if !ok {
		return nil, false
	}

	if len(matchProps) > 0 {
		var propertyErr error
		ctx, matchProps, propertyErr = e.preparePatternNodeProperties(ctx, matchPart)
		if propertyErr != nil {
			recordExpressionFailure(ctx, propertyErr)
			return nil, true
		}
	}
	columns := make([]string, len(returnItems))
	for i, item := range returnItems {
		columns[i] = item.column()
	}

	rows := make([][]interface{}, 0, len(nodeScores))
	nodeCtx := map[string]*storage.Node{varName: nil}
	hasMatchProps := len(matchProps) > 0
	var preWhereFilter func(*storage.Node) bool
	if preWhereClause != "" && preWhereNotNullProp == "" {
		preWhereFilter = e.compileNodeWhereFilter(ctx, varName, preWhereClause)
	}
	for _, hit := range nodeScores {
		if hasMatchProps && !e.nodeMatchesProps(hit.node, matchProps) {
			continue
		}
		if preWhereClause != "" {
			if preWhereNotNullProp != "" {
				if preWhereNotNullProp != vectorProp {
					if value, exists := hit.node.Properties[preWhereNotNullProp]; !exists || value == nil {
						continue
					}
				}
			} else if !preWhereFilter(hit.node) {
				continue
			}
		}
		nodeCtx[varName] = hit.node
		row := make([]interface{}, len(returnItems))
		for i, item := range returnItems {
			if i == cosineIdx {
				row[i] = hit.score
				continue
			}
			row[i] = e.evaluateExpressionWithContext(ctx, item.expr, nodeCtx, nil)
		}
		rows = append(rows, row)
		if len(rows) >= limit {
			break
		}
	}

	e.markCosineVectorIndexFastPathUsed()
	return &ExecuteResult{Columns: columns, Rows: rows, Stats: &QueryStats{}}, true
}

// tryFastPathMatchWithVectorCosineProjection handles Graphiti-style projection shape:
//
//	MATCH (n:Label)
//	WITH [DISTINCT] n, vector.similarity.cosine(n.<prop>, <query>) AS <scoreAlias>
//	[WHERE <scoreAlias> <op> <number|$param>]
//	RETURN ...
//	ORDER BY <scoreAlias> DESC|ASC
//	LIMIT <k>
func (e *StorageExecutor) tryFastPathMatchWithVectorCosineProjection(ctx context.Context, cypher string, upperQuery string) (*ExecuteResult, bool) {
	trimmed := strings.TrimSpace(cypher)
	if !strings.HasPrefix(strings.TrimSpace(upperQuery), "MATCH") {
		return nil, false
	}
	for _, kw := range []string{
		"SKIP", "UNWIND", "OPTIONAL MATCH", "CALL",
		"CREATE", "MERGE", "DELETE", "DETACH DELETE", "SET", "REMOVE", "UNION",
	} {
		if topLevelKeywordIndex(trimmed, kw) > 0 {
			return nil, false
		}
	}

	withIdx := topLevelKeywordIndex(trimmed, "WITH")
	returnIdx := topLevelKeywordIndex(trimmed, "RETURN")
	orderIdx := topLevelKeywordIndex(trimmed, "ORDER BY")
	limitIdx := topLevelKeywordIndex(trimmed, "LIMIT")
	if withIdx <= 0 || returnIdx <= withIdx || orderIdx <= withIdx || limitIdx <= orderIdx {
		return nil, false
	}
	orderBeforeReturn := orderIdx < returnIdx
	if (!orderBeforeReturn && orderIdx <= returnIdx) || (orderBeforeReturn && limitIdx >= returnIdx) {
		return nil, false
	}
	preWithSegment := strings.TrimSpace(trimmed[len("MATCH"):withIdx])
	preWhereClause := ""
	if preWhereIdx := topLevelKeywordIndex(preWithSegment, "WHERE"); preWhereIdx > 0 {
		preWhereClause = strings.TrimSpace(preWithSegment[preWhereIdx+len("WHERE"):])
		preWithSegment = strings.TrimSpace(preWithSegment[:preWhereIdx])
		if preWhereClause == "" {
			return nil, false
		}
	}

	if strings.Count(preWithSegment, "(") != 1 || strings.Count(preWithSegment, ")") != 1 || strings.Contains(preWithSegment, "-") || strings.Contains(preWithSegment, ",") {
		return nil, false
	}
	if !e.isSingleNodePattern(preWithSegment) {
		return nil, false
	}
	if !patternMapsAreConstant(preWithSegment) {
		return nil, false
	}
	var varName string
	var label string
	var matchProps map[string]interface{}
	if strings.Contains(preWithSegment, "{") {
		nodePattern, shapeErr := readNodePattern(ctx, preWithSegment, patternPropertyKeys)
		if shapeErr != nil {
			recordExpressionFailure(ctx, shapeErr)
			return nil, true
		}
		varName = strings.TrimSpace(nodePattern.variable)
		if varName == "" || len(nodePattern.labels) != 1 {
			return nil, false
		}
		label = nodePattern.labels[0]
		matchProps = nodePattern.properties
	} else {
		parsedVar, labels, ok := parseSimpleMatchSingleNodePattern(preWithSegment)
		if !ok || len(labels) != 1 {
			return nil, false
		}
		varName = parsedVar
		label = labels[0]
	}

	withEndIdx := returnIdx
	if orderBeforeReturn {
		withEndIdx = orderIdx
	}
	withToReturn := strings.TrimSpace(trimmed[withIdx+len("WITH") : withEndIdx])
	postWhereClause := ""
	withProjectionRaw := withToReturn
	if postWhereIdx := topLevelKeywordIndex(withToReturn, "WHERE"); postWhereIdx > 0 {
		postWhereClause = strings.TrimSpace(withToReturn[postWhereIdx+len("WHERE"):])
		withProjectionRaw = strings.TrimSpace(withToReturn[:postWhereIdx])
		if postWhereClause == "" {
			return nil, false
		}
	}

	withProjectionEnd := returnIdx
	_ = withProjectionEnd
	withProjection := strings.TrimSpace(withProjectionRaw)
	withProjection, _ = cutDistinct(withProjection)
	withItems := e.parseReturnItems(ctx, withProjection)
	if len(withItems) < 2 {
		return nil, false
	}
	if !withProjectionContainsVariable(withItems, varName) {
		return nil, false
	}

	_, vectorProp, queryExpr, scoreRef, ok := parseCosineReturnShape(withItems, varName)
	if !ok {
		return nil, false
	}
	if scoreRef == "" {
		return nil, false
	}

	scoreOp := ""
	scoreCmp := float64(0)
	if postWhereClause != "" {
		op, cmp, ok := e.parseScoreComparisonPredicate(ctx, postWhereClause, scoreRef)
		if !ok {
			return nil, false
		}
		scoreOp = op
		scoreCmp = cmp
	}
	preWhereNotNullProp := ""
	if preWhereClause != "" {
		if prop, ok := parseFastPathPropertyNotNullPredicate(preWhereClause, varName); ok {
			preWhereNotNullProp = prop
		}
	}

	returnEndIdx := orderIdx
	if orderBeforeReturn {
		returnEndIdx = len(trimmed)
	}
	returnPart := strings.TrimSpace(trimmed[returnIdx+len("RETURN") : returnEndIdx])
	returnItems := e.parseReturnItems(ctx, returnPart)
	if len(returnItems) == 0 {
		return nil, false
	}

	orderPart := strings.TrimSpace(trimmed[orderIdx+len("ORDER BY") : limitIdx])
	orderDesc, ok := parseOrderByScoreDirection(orderPart, scoreRef)
	if !ok {
		return nil, false
	}

	limitPart := strings.TrimSpace(trimmed[limitIdx+len("LIMIT"):])
	limit, ok := parseFastPathLimit(ctx, limitPart)
	if !ok || limit < 0 {
		return nil, false
	}

	columns := make([]string, len(returnItems))
	for i, item := range returnItems {
		columns[i] = item.column()
	}
	if limit == 0 {
		e.markCosineVectorIndexFastPathUsed()
		return &ExecuteResult{Columns: columns, Rows: [][]interface{}{}, Stats: &QueryStats{}}, true
	}

	svc := e.search()
	needsExactCandidates := (svc == nil || svc.IsReady()) &&
		(len(matchProps) > 0 ||
			(preWhereClause != "" && preWhereNotNullProp != vectorProp) ||
			scorePredicateRejectsLeadingResults(orderDesc, scoreOp))
	candidateLimit := chooseVectorCandidateLimit(limit, preWhereClause != "" || len(matchProps) > 0 || scoreOp != "")
	if needsExactCandidates && svc != nil && candidateLimit >= svc.CountPropertyVectorEntries(vectorProp) {
		needsExactCandidates = false
	}
	scoreExprIsAlias := make([]bool, len(returnItems))
	hasMatchProps := len(matchProps) > 0
	for i := range returnItems {
		scoreExprIsAlias[i] = strings.EqualFold(strings.TrimSpace(returnItems[i].expr), scoreRef)
	}
	projectedProps, projectionOK := nodeProjectionPropertiesForVectorFastPath(varName, vectorProp, returnItems, scoreExprIsAlias, preWhereClause, preWhereNotNullProp, matchProps)
	if !projectionOK {
		projectedProps = nil
	}
	indexName, hasIndex := findCosineVectorIndexName(e.storage.GetSchema(), label, vectorProp, storage.ConstraintEntityNode)
	var nodeScores []vectorNodeScore
	if needsExactCandidates {
		if preWhereClause != "" && preWhereNotNullProp == "" {
			preWhereFilter := e.compileNodeWhereFilter(ctx, varName, preWhereClause)
			exactProjectedProps := projectedProps
			if projectionOK {
				exactProjectedProps = appendProjectedProperty(exactProjectedProps, vectorProp)
			}
			nodeScores, ok = e.fetchCosineNodeScoresNoIndexExactFiltered(ctx, label, vectorProp, limit, queryExpr, orderDesc, exactProjectedProps, preWhereFilter)
		} else {
			nodeScores, ok = e.fetchCosineNodeScoresNoIndexExact(ctx, label, vectorProp, int(^uint(0)>>1), queryExpr, orderDesc)
		}
	} else if hasIndex {
		nodeScores, ok = e.fetchCosineNodeScores(ctx, indexName, candidateLimit, queryExpr, orderDesc, projectedProps)
	} else {
		nodeScores, ok = e.fetchCosineNodeScoresNoIndexExact(ctx, label, vectorProp, candidateLimit, queryExpr, orderDesc)
	}
	if !ok {
		return nil, false
	}

	if len(matchProps) > 0 {
		var propertyErr error
		ctx, matchProps, propertyErr = e.preparePatternNodeProperties(ctx, preWithSegment)
		if propertyErr != nil {
			recordExpressionFailure(ctx, propertyErr)
			return nil, true
		}
	}
	rows := make([][]interface{}, 0, util.SafePreallocCap(len(nodeScores)))
	nodeCtx := map[string]*storage.Node{varName: nil}
	var preWhereFilter func(*storage.Node) bool
	if preWhereClause != "" && preWhereNotNullProp == "" {
		preWhereFilter = e.compileNodeWhereFilter(ctx, varName, preWhereClause)
	}
	for _, hit := range nodeScores {
		if hasMatchProps && !e.nodeMatchesProps(hit.node, matchProps) {
			continue
		}
		if preWhereClause != "" {
			if preWhereNotNullProp != "" {
				if preWhereNotNullProp == vectorProp {
					// The vector index only returns nodes that have an indexed
					// value for vectorProp, so this predicate does not require
					// materializing the vector property itself.
				} else if val, exists := hit.node.Properties[preWhereNotNullProp]; !exists || val == nil {
					continue
				}
			} else if !preWhereFilter(hit.node) {
				continue
			}
		}
		if scoreOp != "" && !compareScore(hit.score, scoreOp, scoreCmp) {
			continue
		}
		nodeCtx[varName] = hit.node
		row := make([]interface{}, len(returnItems))
		for i, item := range returnItems {
			if scoreExprIsAlias[i] {
				row[i] = hit.score
				continue
			}
			row[i] = e.evaluateExpressionWithContext(ctx, item.expr, nodeCtx, nil)
		}
		rows = append(rows, row)
		if len(rows) >= limit {
			break
		}
	}

	e.markCosineVectorIndexFastPathUsed()
	return &ExecuteResult{Columns: columns, Rows: rows, Stats: &QueryStats{}}, true
}

func (e *StorageExecutor) fetchCosineNodeScoresNoIndexExact(ctx context.Context, label string, property string, limit int, queryExpr string, orderDesc bool) ([]vectorNodeScore, bool) {
	queryVector, ok := e.resolveCosineQueryVector(ctx, queryExpr)
	if !ok || len(queryVector) == 0 {
		return nil, false
	}
	return e.fetchCosineNodeScoresExact(ctx, label, property, "cosine", limit, queryVector, orderDesc, len(queryVector))
}

func (e *StorageExecutor) fetchCosineNodeScoresNoIndexExactFiltered(ctx context.Context, label string, property string, limit int, queryExpr string, orderDesc bool, projectedProps []string, filter func(*storage.Node) bool) ([]vectorNodeScore, bool) {
	queryVector, ok := e.resolveCosineQueryVector(ctx, queryExpr)
	if !ok || len(queryVector) == 0 {
		return nil, false
	}
	if reader, ok := e.storage.(storage.ProjectedLabelNodeReader); ok {
		return e.fetchCosineNodeScoresProjectedLabel(ctx, reader, label, property, limit, queryVector, orderDesc, projectedProps, filter)
	}
	return e.fetchCosineNodeScoresExactFiltered(ctx, label, property, queryVector, orderDesc, filter)
}

func (e *StorageExecutor) fetchCosineNodeScoresProjectedLabel(ctx context.Context, reader storage.ProjectedLabelNodeReader, label string, property string, limit int, queryVector []float32, orderDesc bool, projectedProps []string, filter func(*storage.Node) bool) ([]vectorNodeScore, bool) {
	if limit <= 0 {
		return []vectorNodeScore{}, true
	}
	candidates := vectorNodeScoreHeap{orderDesc: orderDesc}
	heap.Init(&candidates)
	err := reader.StreamNodesByLabelProjected(label, projectedProps, func(node *storage.Node) error {
		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
		}
		if !filter(node) {
			return nil
		}
		score, ok := scoreNodeVectorForFastPath(node, property, "cosine", queryVector)
		if !ok {
			return nil
		}
		heap.Push(&candidates, vectorNodeScore{node: node, score: score})
		if candidates.Len() > limit {
			heap.Pop(&candidates)
		}
		return nil
	})
	if err != nil {
		return nil, false
	}
	out := candidates.scores
	sort.Slice(out, func(i, j int) bool { return vectorNodeScoreBetter(out[i], out[j], orderDesc) })
	return out, true
}

// tryFastPathMatchRelationshipVectorCosine handles relationship direct-return shape:
//
//	MATCH ()-[e:TYPE]->()
//	RETURN ..., vector.similarity.cosine(e.<prop>, <query>) AS <scoreAlias>, ...
//	ORDER BY <scoreAlias> DESC|ASC
//	LIMIT <k>
func (e *StorageExecutor) tryFastPathMatchRelationshipVectorCosine(ctx context.Context, cypher string, upperQuery string) (*ExecuteResult, bool) {
	trimmed := strings.TrimSpace(cypher)
	if !strings.HasPrefix(strings.TrimSpace(upperQuery), "MATCH") {
		return nil, false
	}
	for _, kw := range []string{
		"SKIP", "WITH", "UNWIND", "OPTIONAL MATCH", "CALL",
		"CREATE", "MERGE", "DELETE", "DETACH DELETE", "SET", "REMOVE", "UNION",
	} {
		if findKeywordIndex(trimmed, kw) > 0 {
			return nil, false
		}
	}

	returnIdx := findKeywordIndex(trimmed, "RETURN")
	orderIdx := findKeywordIndex(trimmed, "ORDER BY")
	limitIdx := findKeywordIndex(trimmed, "LIMIT")
	if returnIdx <= 0 || orderIdx <= returnIdx || limitIdx <= orderIdx {
		return nil, false
	}

	matchSegment := strings.TrimSpace(trimmed[len("MATCH"):returnIdx])
	preWhereClause := ""
	if preWhereIdx := findKeywordIndex(matchSegment, "WHERE"); preWhereIdx > 0 {
		preWhereClause = strings.TrimSpace(matchSegment[preWhereIdx+len("WHERE"):])
		matchSegment = strings.TrimSpace(matchSegment[:preWhereIdx])
		if preWhereClause == "" {
			return nil, false
		}
	}

	pattern, ok := e.parseSimpleMatchRelationshipPattern(matchSegment)
	if !ok || strings.TrimSpace(pattern.relVar) == "" || strings.TrimSpace(pattern.relType) == "" {
		return nil, false
	}

	returnPart := strings.TrimSpace(trimmed[returnIdx+len("RETURN") : orderIdx])
	returnItems := e.parseReturnItems(ctx, returnPart)
	if len(returnItems) == 0 {
		return nil, false
	}

	cosineIdx, vectorProp, queryExpr, scoreRef, ok := parseCosineReturnShape(returnItems, pattern.relVar)
	if !ok {
		return nil, false
	}

	orderPart := strings.TrimSpace(trimmed[orderIdx+len("ORDER BY") : limitIdx])
	orderDesc, ok := parseOrderByScoreDirection(orderPart, scoreRef)
	if !ok {
		return nil, false
	}

	limitPart := strings.TrimSpace(trimmed[limitIdx+len("LIMIT"):])
	limit, ok := parseFastPathLimit(ctx, limitPart)
	if !ok || limit < 0 {
		return nil, false
	}

	columns := make([]string, len(returnItems))
	for i, item := range returnItems {
		columns[i] = item.column()
	}
	if limit == 0 {
		e.markCosineVectorIndexFastPathUsed()
		return &ExecuteResult{Columns: columns, Rows: [][]interface{}{}, Stats: &QueryStats{}}, true
	}

	indexName, hasIndex := findCosineVectorIndexName(e.storage.GetSchema(), pattern.relType, vectorProp, storage.ConstraintEntityRelationship)
	if !hasIndex {
		return nil, false
	}

	candidateLimit := chooseVectorCandidateLimit(limit, preWhereClause != "")
	edgeScores, ok := e.fetchCosineRelationshipScores(ctx, indexName, candidateLimit, queryExpr, orderDesc)
	if !ok {
		return nil, false
	}

	rows := make([][]interface{}, 0, util.SafePreallocCap(len(edgeScores)))
	nodeCtx := make(map[string]*storage.Node, 2)
	edgeCtx := make(map[string]*storage.Edge, 1)
	for _, hit := range edgeScores {
		edge := hit.edge
		if edge == nil && hit.edgeID != "" {
			var err error
			edge, err = e.storage.GetEdge(hit.edgeID)
			if err != nil || edge == nil {
				continue
			}
		}
		if !e.buildRelationshipContextInto(pattern, edge, nodeCtx, edgeCtx) {
			continue
		}
		if preWhereClause != "" && !evaluateExpressionBoolWithContext(e, ctx, preWhereClause, nodeCtx, edgeCtx) {
			continue
		}

		row := make([]interface{}, len(returnItems))
		for i, item := range returnItems {
			if i == cosineIdx {
				row[i] = hit.score
				continue
			}
			row[i] = e.evaluateExpressionWithContext(ctx, item.expr, nodeCtx, edgeCtx)
		}
		rows = append(rows, row)
		if len(rows) >= limit {
			break
		}
	}

	e.markCosineVectorIndexFastPathUsed()
	return &ExecuteResult{Columns: columns, Rows: rows, Stats: &QueryStats{}}, true
}

// tryFastPathMatchWithRelationshipVectorCosineProjection handles Graphiti relationship shape:
//
//	MATCH (n)-[e:TYPE]->(m) [WHERE ...]
//	WITH [DISTINCT] e[, n, m], vector.similarity.cosine(e.<prop>, <query>) AS <scoreAlias>
//	[WHERE <scoreAlias> <op> <number|$param>]
//	RETURN ...
//	ORDER BY <scoreAlias> DESC|ASC
//	LIMIT <k>
func (e *StorageExecutor) tryFastPathMatchWithRelationshipVectorCosineProjection(ctx context.Context, cypher string, upperQuery string) (*ExecuteResult, bool) {
	trimmed := strings.TrimSpace(cypher)
	if !strings.HasPrefix(strings.TrimSpace(upperQuery), "MATCH") {
		return nil, false
	}
	for _, kw := range []string{
		"SKIP", "UNWIND", "OPTIONAL MATCH", "CALL",
		"CREATE", "MERGE", "DELETE", "DETACH DELETE", "SET", "REMOVE", "UNION",
	} {
		if findKeywordIndex(trimmed, kw) > 0 {
			return nil, false
		}
	}

	withIdx := findKeywordIndex(trimmed, "WITH")
	returnIdx := findKeywordIndex(trimmed, "RETURN")
	orderIdx := findKeywordIndex(trimmed, "ORDER BY")
	limitIdx := findKeywordIndex(trimmed, "LIMIT")
	if withIdx <= 0 || returnIdx <= withIdx || orderIdx <= returnIdx || limitIdx <= orderIdx {
		return nil, false
	}

	preWithSegment := strings.TrimSpace(trimmed[len("MATCH"):withIdx])
	preWhereClause := ""
	if preWhereIdx := findKeywordIndex(preWithSegment, "WHERE"); preWhereIdx > 0 {
		preWhereClause = strings.TrimSpace(preWithSegment[preWhereIdx+len("WHERE"):])
		preWithSegment = strings.TrimSpace(preWithSegment[:preWhereIdx])
		if preWhereClause == "" {
			return nil, false
		}
	}

	pattern, ok := e.parseSimpleMatchRelationshipPattern(preWithSegment)
	if !ok || strings.TrimSpace(pattern.relVar) == "" || strings.TrimSpace(pattern.relType) == "" {
		return nil, false
	}

	withToReturn := strings.TrimSpace(trimmed[withIdx+len("WITH") : returnIdx])
	postWhereClause := ""
	withProjectionRaw := withToReturn
	if postWhereIdx := findKeywordIndex(withToReturn, "WHERE"); postWhereIdx > 0 {
		postWhereClause = strings.TrimSpace(withToReturn[postWhereIdx+len("WHERE"):])
		withProjectionRaw = strings.TrimSpace(withToReturn[:postWhereIdx])
		if postWhereClause == "" {
			return nil, false
		}
	}

	withProjection, _ := cutDistinct(withProjectionRaw)
	withItems := e.parseReturnItems(ctx, withProjection)
	if len(withItems) < 2 || !withProjectionContainsVariable(withItems, pattern.relVar) {
		return nil, false
	}

	_, vectorProp, queryExpr, scoreRef, ok := parseCosineReturnShape(withItems, pattern.relVar)
	if !ok || scoreRef == "" {
		return nil, false
	}

	scoreOp := ""
	scoreCmp := float64(0)
	if postWhereClause != "" {
		op, cmp, ok := e.parseScoreComparisonPredicate(ctx, postWhereClause, scoreRef)
		if !ok {
			return nil, false
		}
		scoreOp = op
		scoreCmp = cmp
	}

	returnPart := strings.TrimSpace(trimmed[returnIdx+len("RETURN") : orderIdx])
	returnItems := e.parseReturnItems(ctx, returnPart)
	if len(returnItems) == 0 {
		return nil, false
	}

	orderPart := strings.TrimSpace(trimmed[orderIdx+len("ORDER BY") : limitIdx])
	orderDesc, ok := parseOrderByScoreDirection(orderPart, scoreRef)
	if !ok {
		return nil, false
	}

	limitPart := strings.TrimSpace(trimmed[limitIdx+len("LIMIT"):])
	limit, ok := parseFastPathLimit(ctx, limitPart)
	if !ok || limit < 0 {
		return nil, false
	}

	columns := make([]string, len(returnItems))
	for i, item := range returnItems {
		columns[i] = item.column()
	}
	if limit == 0 {
		e.markCosineVectorIndexFastPathUsed()
		return &ExecuteResult{Columns: columns, Rows: [][]interface{}{}, Stats: &QueryStats{}}, true
	}

	indexName, hasIndex := findCosineVectorIndexName(e.storage.GetSchema(), pattern.relType, vectorProp, storage.ConstraintEntityRelationship)
	if !hasIndex {
		return nil, false
	}

	candidateLimit := chooseVectorCandidateLimit(limit, preWhereClause != "" || scorePredicateRejectsLeadingResults(orderDesc, scoreOp))
	edgeScores, ok := e.fetchCosineRelationshipScores(ctx, indexName, candidateLimit, queryExpr, orderDesc)
	if !ok {
		return nil, false
	}

	rows := make([][]interface{}, 0, util.SafePreallocCap(len(edgeScores)))
	nodeCtx := make(map[string]*storage.Node, 2)
	edgeCtx := make(map[string]*storage.Edge, 1)
	scoreExprIsAlias := make([]bool, len(returnItems))
	for i := range returnItems {
		scoreExprIsAlias[i] = strings.EqualFold(strings.TrimSpace(returnItems[i].expr), scoreRef)
	}
	for _, hit := range edgeScores {
		edge := hit.edge
		if edge == nil && hit.edgeID != "" {
			var err error
			edge, err = e.storage.GetEdge(hit.edgeID)
			if err != nil || edge == nil {
				continue
			}
		}
		if !e.buildRelationshipContextInto(pattern, edge, nodeCtx, edgeCtx) {
			continue
		}
		if preWhereClause != "" && !evaluateExpressionBoolWithContext(e, ctx, preWhereClause, nodeCtx, edgeCtx) {
			continue
		}
		if scoreOp != "" && !compareScore(hit.score, scoreOp, scoreCmp) {
			continue
		}

		row := make([]interface{}, len(returnItems))
		for i, item := range returnItems {
			if scoreExprIsAlias[i] {
				row[i] = hit.score
				continue
			}
			row[i] = e.evaluateExpressionWithContext(ctx, item.expr, nodeCtx, edgeCtx)
		}
		rows = append(rows, row)
		if len(rows) >= limit {
			break
		}
	}

	e.markCosineVectorIndexFastPathUsed()
	return &ExecuteResult{Columns: columns, Rows: rows, Stats: &QueryStats{}}, true
}

type vectorNodeScore struct {
	node  *storage.Node
	score float64
}

type vectorNodeScoreHeap struct {
	scores    []vectorNodeScore
	orderDesc bool
}

func (h vectorNodeScoreHeap) Len() int { return len(h.scores) }

func (h vectorNodeScoreHeap) Less(i, j int) bool {
	return vectorNodeScoreBetter(h.scores[j], h.scores[i], h.orderDesc)
}

func (h vectorNodeScoreHeap) Swap(i, j int) { h.scores[i], h.scores[j] = h.scores[j], h.scores[i] }

func (h *vectorNodeScoreHeap) Push(value any) {
	h.scores = append(h.scores, value.(vectorNodeScore))
}

func (h *vectorNodeScoreHeap) Pop() any {
	last := len(h.scores) - 1
	value := h.scores[last]
	h.scores = h.scores[:last]
	return value
}

func vectorNodeScoreBetter(left, right vectorNodeScore, orderDesc bool) bool {
	if left.score == right.score {
		return string(left.node.ID) < string(right.node.ID)
	}
	if orderDesc {
		return left.score > right.score
	}
	return left.score < right.score
}

type vectorEdgeScore struct {
	edgeID storage.EdgeID
	edge   *storage.Edge
	score  float64
}

func (e *StorageExecutor) fetchCosineNodeScores(ctx context.Context, indexName string, limit int, queryExpr string, orderDesc bool, projectedProps []string) ([]vectorNodeScore, bool) {
	queryVector, ok := e.resolveCosineQueryVector(ctx, queryExpr)
	if !ok || len(queryVector) == 0 {
		return nil, false
	}

	var targetLabel, targetProperty string
	similarityFunc := "cosine"
	wantDims := 0
	if schema := e.storage.GetSchema(); schema != nil {
		if vectorIdx, exists := schema.GetVectorIndex(indexName); exists {
			targetLabel = vectorIdx.Label
			targetProperty = vectorIdx.Property
			similarityFunc = vectorIdx.SimilarityFunc
			if vectorIdx.Dimensions > 0 {
				wantDims = vectorIdx.Dimensions
			}
		}
	}
	if wantDims <= 0 && len(queryVector) > 0 {
		wantDims = len(queryVector)
	}
	if wantDims <= 0 {
		wantDims = search.DefaultVectorDimensions
	}
	if !orderDesc {
		return e.fetchCosineNodeScoresExact(ctx, targetLabel, targetProperty, similarityFunc, limit, queryVector, orderDesc, wantDims)
	}
	svc := e.search()
	if svc != nil && !svc.VectorEnabled() {
		return []vectorNodeScore{}, true
	}
	if svc == nil || svc.VectorIndexDimensions() != wantDims || (!svc.IsReady() && (targetProperty == "" || svc.CountPropertyVectorEntries(targetProperty) == 0)) {
		return e.fetchCosineNodeScoresExact(ctx, targetLabel, targetProperty, similarityFunc, limit, queryVector, orderDesc, wantDims)
	}
	if !svc.VectorEnabled() {
		return []vectorNodeScore{}, true
	}
	hits, err := svc.VectorQueryNodes(ctx, queryVector, search.VectorQuerySpec{
		IndexName:  indexName,
		Label:      targetLabel,
		Property:   targetProperty,
		Similarity: similarityFunc,
		Limit:      limit,
	})
	if err != nil {
		return nil, false
	}

	out := make([]vectorNodeScore, 0, len(hits))
	for _, hit := range hits {
		node, err := e.getNodeForVectorHit(storage.NodeID(hit.ID), projectedProps)
		if err != nil || node == nil {
			continue
		}
		// The index's score is on Neo4j's scale; the node's own vector gives
		// the exact value vector.similarity.* returns for it.
		score := hit.Score
		if exact, ok := scoreNodeVectorForFastPath(node, targetProperty, similarityFunc, queryVector); ok {
			score = exact
		}
		out = append(out, vectorNodeScore{node: node, score: score})
	}
	return out, true
}

func (e *StorageExecutor) getNodeForVectorHit(id storage.NodeID, projectedProps []string) (*storage.Node, error) {
	if projectedProps != nil {
		if reader, ok := e.storage.(storage.ProjectedNodeReader); ok {
			return reader.GetNodeProjected(id, projectedProps)
		}
	}
	return e.storage.GetNode(id)
}

func nodeProjectionPropertiesForVectorFastPath(varName string, vectorProp string, returnItems []returnItem, scoreExprIsAlias []bool, preWhereClause string, preWhereNotNullProp string, matchProps map[string]interface{}) ([]string, bool) {
	props := make(map[string]struct{}, util.SafePreallocSum(len(matchProps), len(returnItems)))
	for prop := range matchProps {
		props[prop] = struct{}{}
	}
	if preWhereNotNullProp != "" {
		if preWhereNotNullProp != vectorProp {
			props[preWhereNotNullProp] = struct{}{}
		}
	} else if preWhereClause != "" {
		if !collectNodePropertyRefsForProjection(varName, preWhereClause, props) {
			return nil, false
		}
	}
	for i, item := range returnItems {
		if i < len(scoreExprIsAlias) && scoreExprIsAlias[i] {
			continue
		}
		if !collectNodePropertyRefsForProjection(varName, item.expr, props) {
			return nil, false
		}
	}

	out := make([]string, 0, len(props))
	for prop := range props {
		out = append(out, prop)
	}
	sort.Strings(out)
	return out, true
}

func appendProjectedProperty(properties []string, property string) []string {
	if property == "" {
		return properties
	}
	for _, existing := range properties {
		if existing == property {
			return properties
		}
	}
	properties = append(properties, property)
	sort.Strings(properties)
	return properties
}

func collectNodePropertyRefsForProjection(varName string, expr string, props map[string]struct{}) bool {
	expr = strings.TrimSpace(expr)
	if expr == "" {
		return true
	}
	if expr == "*" || expr == varName {
		return false
	}
	compact := lowerASCII(strings.ReplaceAll(expr, " ", ""))
	lowerVar := lowerASCII(varName)
	if strings.Contains(compact, "properties("+lowerVar+")") ||
		strings.Contains(compact, "keys("+lowerVar+")") ||
		strings.Contains(compact, lowerVar+"{") ||
		strings.Contains(compact, lowerVar+"[") {
		return false
	}

	offset := 0
	for offset < len(expr) {
		idx := strings.Index(expr[offset:], varName)
		if idx < 0 {
			return true
		}
		start := offset + idx
		end := start + len(varName)
		if (start > 0 && isIdentByte(expr[start-1])) || (end < len(expr) && isIdentByte(expr[end])) {
			offset = end
			continue
		}

		j := end
		for j < len(expr) && (expr[j] == ' ' || expr[j] == '\t' || expr[j] == '\n' || expr[j] == '\r') {
			j++
		}
		if j >= len(expr) || expr[j] != '.' {
			offset = end
			continue
		}
		j++
		for j < len(expr) && (expr[j] == ' ' || expr[j] == '\t' || expr[j] == '\n' || expr[j] == '\r') {
			j++
		}
		if j >= len(expr) {
			return false
		}
		if isCypherBacktickByte(expr[j]) {
			prop, end, ok := scanIdentifierToken(expr, j)
			if !ok || end <= j {
				return false
			}
			if prop == "" {
				return false
			}
			props[prop] = struct{}{}
			offset = end
			continue
		}
		if !isIdentByte(expr[j]) {
			return false
		}
		k := j + 1
		for k < len(expr) && isIdentByte(expr[k]) {
			k++
		}
		props[expr[j:k]] = struct{}{}
		offset = k
	}
	return true
}

func prepareWiredNodeVectorService(ctx context.Context, svc *search.Service, wantDims int) (bool, error) {
	if svc == nil || svc.VectorIndexDimensions() != wantDims {
		return false, nil
	}
	if err := svc.EnsureWarm(ctx); err != nil {
		return false, err
	}
	if !svc.IsReady() {
		return false, nil
	}
	return true, nil
}

func (e *StorageExecutor) fetchCosineNodeScoresExact(ctx context.Context, label string, property string, similarity string, limit int, queryVector []float32, orderDesc bool, wantDims int) ([]vectorNodeScore, bool) {
	if limit <= 0 {
		return []vectorNodeScore{}, true
	}
	if wantDims > 0 && len(queryVector) != wantDims {
		return []vectorNodeScore{}, true
	}
	var nodes []*storage.Node
	var err error
	if label == "" {
		nodes, err = e.storage.AllNodes()
	} else {
		nodes, err = e.storage.GetNodesByLabel(label)
	}
	if err != nil {
		return nil, false
	}
	out := make([]vectorNodeScore, 0, util.SafePreallocCap(len(nodes)))
	for _, node := range nodes {
		select {
		case <-ctx.Done():
			return nil, false
		default:
		}
		score, ok := scoreNodeVectorForFastPath(node, property, similarity, queryVector)
		if !ok {
			continue
		}
		out = append(out, vectorNodeScore{node: node, score: score})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].score == out[j].score {
			return string(out[i].node.ID) < string(out[j].node.ID)
		}
		if orderDesc {
			return out[i].score > out[j].score
		}
		return out[i].score < out[j].score
	})
	if len(out) > limit {
		out = out[:limit]
	}
	return out, true
}

func (e *StorageExecutor) fetchCosineNodeScoresExactFiltered(ctx context.Context, label string, property string, queryVector []float32, orderDesc bool, filter func(*storage.Node) bool) ([]vectorNodeScore, bool) {
	var nodes []*storage.Node
	var err error
	if label == "" {
