const deleteStreamingBatchSize = 500

// ========================================
// WITH Clause
// ========================================

// executeMatch handles MATCH queries.
func (e *StorageExecutor) parseMergePattern(ctx context.Context, pattern string) (string, []string, map[string]interface{}, error) {
	return e.parseMergeNodePattern(ctx, pattern, nil, nil)
}

// nodeToMap converts a storage.Node to a map for result output.
// Filters out internal properties like embeddings which are huge.
// Properties are included at the top level for Neo4j compatibility.
// Embeddings are replaced with a summary showing status and dimensions.

// tryExecuteDeleteWithWithLimitHotPath executes:
//
//	MATCH ... [WHERE ...]
//	WITH <var> LIMIT <n>
//	DETACH DELETE <var>
//	[RETURN ...]
//
// with a streamlined path that avoids generic WITH parsing in delete execution.
func (e *StorageExecutor) tryExecuteDeleteWithWithLimitHotPath(ctx context.Context, cypher string, matchIdx, deleteIdx int, deleteVars string, detach bool, needEdgeStats bool) (*ExecuteResult, bool, error) {
	if !detach || matchIdx < 0 || deleteIdx <= matchIdx {
		return nil, false, nil
	}
	if strings.Contains(deleteVars, ",") {
		return nil, false, nil
	}
	deleteVar := strings.TrimSpace(deleteVars)
	if deleteVar == "" {
		return nil, false, nil
	}

	matchSegment := strings.TrimSpace(cypher[matchIdx:deleteIdx])
	withIdx := findKeywordIndex(matchSegment, "WITH")
	if withIdx <= 0 {
		return nil, false, nil
	}

	// Keep this hot path strict and deterministic.
	for _, blocked := range []string{"ORDER BY", "SKIP", "UNWIND", "CALL", "OPTIONAL MATCH"} {
		if containsKeywordOutsideStrings(matchSegment, blocked) {
			return nil, false, nil
		}
	}

	baseMatch := strings.TrimSpace(matchSegment[:withIdx])
	withPart := strings.TrimSpace(matchSegment[withIdx+4:]) // skip "WITH"
	limitIdx := findKeywordIndex(withPart, "LIMIT")
	if limitIdx <= 0 {
		return nil, false, nil
	}

	withVar := strings.TrimSpace(withPart[:limitIdx])
	if withVar != deleteVar {
		return nil, false, nil
	}
	limitLiteral := strings.TrimSpace(withPart[limitIdx+5:]) // skip "LIMIT"
	if limitLiteral == "" {
		return nil, false, nil
	}
	limitFields := strings.Fields(limitLiteral)
	if len(limitFields) == 0 {
		return nil, false, nil
	}
	limitN, err := strconv.Atoi(limitFields[0])
	if err != nil || limitN <= 0 {
		return nil, false, nil
	}

	result := &ExecuteResult{
		Columns: []string{},
		Rows:    [][]interface{}{},
		Stats:   &QueryStats{},
	}
	store := e.getStorage(ctx)

	candidates, ok, err := e.collectDeleteWithLimitCandidates(ctx, baseMatch, deleteVar, limitN, getParamsFromContext(ctx))
	if err != nil {
		return nil, true, err
	}
	if !ok {
		return nil, false, nil
	}

	deletedNodeIDs := make(map[string]struct{}, len(candidates))
	for _, node := range candidates {
		if node == nil {
			continue
		}
		lookupID, validSource := node.Identity().NodeLookupID(store)
		if !validSource {
			continue
		}
		nodeID := string(lookupID)
		if _, seen := deletedNodeIDs[nodeID]; seen {
			continue
		}
		edgesCount := 0
		if needEdgeStats {
			outgoingEdges, _ := store.GetOutgoingEdges(storage.NodeID(nodeID))
			incomingEdges, _ := store.GetIncomingEdges(storage.NodeID(nodeID))
			edgesCount = len(outgoingEdges) + len(incomingEdges)
		}
		if err := store.DeleteNode(storage.NodeID(nodeID)); err == nil {
			result.Stats.NodesDeleted++
			result.Stats.RelationshipsDeleted += edgesCount
			deletedNodeIDs[nodeID] = struct{}{}
			e.removeNodeFromSearch(nodeID)
		}
	}

	input := &ExecuteResult{Columns: []string{deleteVar}, Rows: make([][]interface{}, 0, len(candidates))}
	for _, node := range candidates {
		input.Rows = append(input.Rows, []interface{}{node})
	}
	e.applyDeleteReturnProjection(result, cypher, deleteVar, deleteProjectionInfo{ctx: ctx, input: input})
	return result, true, getExpressionFailure(ctx)
}

func (e *StorageExecutor) collectDeleteWithLimitCandidates(ctx context.Context, baseMatch, deleteVar string, limitN int, params map[string]interface{}) ([]*storage.Node, bool, error) {
	matchIdx := findKeywordIndex(baseMatch, "MATCH")
	if matchIdx < 0 {
		return nil, false, nil
	}
	whereIdx := findKeywordIndex(baseMatch, "WHERE")
	patternPart := strings.TrimSpace(baseMatch[matchIdx+5:])
	wherePart := ""
	if whereIdx > 0 {
		patternPart = strings.TrimSpace(baseMatch[matchIdx+5 : whereIdx])
		wherePart = strings.TrimSpace(baseMatch[whereIdx+5:])
	}
	if !patternMapsAreConstant(patternPart) || !patternMapsAreConstant(wherePart) {
		return nil, false, nil
	}
	nodePat, parseErr := readNodePattern(ctx, patternPart, patternPropertyKeys)
	if parseErr != nil {
		return nil, true, parseErr
	}
	if strings.TrimSpace(nodePat.variable) != deleteVar {
		return nil, false, nil
	}
	// Admit the WHERE shape and parameter type before reading property values.
	if wherePart != "" {
		equality := deleteWherePropertyEquals.FindStringSubmatch(wherePart)
		membership := deleteWherePropertyInParameter.FindStringSubmatch(wherePart)
		if len(equality) == 4 && strings.EqualFold(equality[1], deleteVar) {
			// The equality path accepts literal and parameter values.
		} else if len(membership) == 4 && strings.EqualFold(membership[1], deleteVar) {
			if raw, exists := params[membership[3]]; exists {
				switch raw.(type) {
				case []interface{}, []string:
				default:
					return nil, false, nil
				}
			}
		} else {
			return nil, false, nil
		}
	}
	rowCtx, prepared, prepareErr := e.preparePatternRow(ctx, patternPart, nil)
	if prepareErr != nil {
		return nil, true, prepareErr
	}
	ctx = rowCtx
	nodePat, parseErr = e.parseNodePattern(ctx, prepared)
	if parseErr != nil {
		return nil, true, parseErr
	}

	var nodes []*storage.Node
	var err error
	usedIndex := false
	if wherePart != "" {
		if candidates, used, idxErr := e.tryCollectNodesFromIDIn(ctx, nodePat, wherePart, params); idxErr == nil && used {
			nodes = candidates
			usedIndex = true
		}
		if !usedIndex {
			if candidates, used, idxErr := e.tryCollectNodesFromPropertyIndexIn(wherePartNodePattern(nodePat, deleteVar), wherePart, params); idxErr == nil && used {
				nodes = candidates
				usedIndex = true
			}
		}
		if !usedIndex {
			if candidates, used, idxErr := e.tryCollectNodesFromPropertyIndexInLiteral(ctx, wherePartNodePattern(nodePat, deleteVar), wherePart); idxErr == nil && used {
				nodes = candidates
				usedIndex = true
			}
		}
		if !usedIndex {
			if candidates, used, idxErr := e.tryCollectNodesFromPropertyIndex(ctx, wherePartNodePattern(nodePat, deleteVar), wherePart); idxErr == nil && used {
				nodes = candidates
				usedIndex = true
			}
		}
	}
	if !usedIndex {
		if len(nodePat.labels) > 0 {
			nodes, err = e.storage.GetNodesByLabel(nodePat.labels[0])
		} else {
			nodes, err = e.storage.AllNodes()
		}
		if err != nil {
			return nil, true, err
		}
	}
	if len(nodePat.properties) > 0 {
		nodes = e.filterNodesByProperties(nodes, nodePat.properties)
	}

	if wherePart != "" {
		// Supported hot-path predicates:
		//   var.prop = $param | 'literal'
		//   var.prop IN $param
		if m := deleteWherePropertyEquals.FindStringSubmatch(wherePart); len(m) == 4 && strings.EqualFold(m[1], deleteVar) {
			prop := m[2]
			rhs := strings.TrimSpace(m[3])
			var expected interface{}
			if strings.HasPrefix(rhs, "$") {
				key := strings.TrimSpace(strings.TrimPrefix(rhs, "$"))
				val, ok := params[key]
				if !ok {
					return []*storage.Node{}, true, nil
				}
				expected = val
			} else {
				expected = strings.Trim(rhs, "'\"")
			}
			filtered := make([]*storage.Node, 0, len(nodes))
			for _, n := range nodes {
				if n == nil {
					continue
				}
				if e.compareEqual(n.Properties[prop], expected) {
					filtered = append(filtered, n)
				}
			}
			nodes = filtered
		} else if m := deleteWherePropertyInParameter.FindStringSubmatch(wherePart); len(m) == 4 && strings.EqualFold(m[1], deleteVar) {
			prop := m[2]
			paramName := m[3]
			raw, ok := params[paramName]
			if !ok {
				return []*storage.Node{}, true, nil
			}
			allowed := map[string]struct{}{}
			switch v := raw.(type) {
			case []interface{}:
				for _, item := range v {
					allowed[fmt.Sprintf("%v", item)] = struct{}{}
				}
			case []string:
				for _, item := range v {
					allowed[item] = struct{}{}
				}
			default:
				return nil, false, nil
			}
			filtered := make([]*storage.Node, 0, len(nodes))
			for _, n := range nodes {
				if n == nil {
					continue
				}
				if _, ok := allowed[fmt.Sprintf("%v", n.Properties[prop])]; ok {
					filtered = append(filtered, n)
				}
			}
			nodes = filtered
		} else {
			return nil, false, nil
		}
	}

	if limitN < len(nodes) {
		nodes = nodes[:limitN]
	}
	return nodes, true, nil
}

func wherePartNodePattern(nodePat nodePatternInfo, variable string) nodePatternInfo {
	if strings.TrimSpace(nodePat.variable) != "" {
		return nodePat
	}
	nodePat.variable = variable
	return nodePat
}

type deleteProjectionKind uint8

const (
	deleteProjectionUnknown deleteProjectionKind = iota
	deleteProjectionNode
	deleteProjectionRelationship
)

type deleteProjectionInfo struct {
	ctx   context.Context
	input *ExecuteResult
}

type deleteTargetValue struct {
	kind   deleteProjectionKind
	nodeID storage.NodeID
	edgeID storage.EdgeID
}

func singleDeleteProjectionInfo(_ string, _ deleteProjectionKind) deleteProjectionInfo {
	return deleteProjectionInfo{}
}

func classifyDeleteTargetValue(val interface{}) deleteTargetValue {
	switch v := val.(type) {
	case map[string]interface{}:
		if id, ok := v["_edgeId"].(string); ok && id != "" {
			return deleteTargetValue{kind: deleteProjectionRelationship, edgeID: storage.EdgeID(id)}
		}
		if id, ok := v["_nodeId"].(string); ok && id != "" {
			return deleteTargetValue{kind: deleteProjectionNode, nodeID: storage.NodeID(id)}
		}
	case *storage.Node:
		if v != nil {
			return deleteTargetValue{kind: deleteProjectionNode, nodeID: v.ID}
		}
	case *storage.Edge:
		if v != nil {
			return deleteTargetValue{kind: deleteProjectionRelationship, edgeID: v.ID}
		}
	case string:
		if v != "" {
			return deleteTargetValue{kind: deleteProjectionNode, nodeID: storage.NodeID(v)}
		}
	}
	return deleteTargetValue{}
}

func (e *StorageExecutor) applyDeleteReturnProjection(result *ExecuteResult, cypher, deleteVars string, info deleteProjectionInfo) {
	if result == nil {
		return
	}
	returnIdx := topLevelKeywordIndex(cypher, "RETURN")
	if returnIdx <= 0 {
		return
	}
	ctx := info.ctx
	if ctx == nil {
		ctx = context.Background()
	}
	rows := []pipelineRow{}
	nodeIDs := []storage.NodeID{}
	edgeIDs := make(map[storage.EdgeID]struct{})
	if info.input != nil {
		store := e.getStorage(ctx)
		seenNodes, seenEdges := map[string]struct{}{}, map[string]struct{}{}
		var targetEdges []storage.EdgeID
		for _, values := range info.input.Rows {
			row := pipelineRow(buildRowValueMap(info.input.Columns, values))
			rows = append(rows, row)
			// An entity the DELETE removed without naming it (a DETACH
			// DELETE's relationships) is gone from storage.
			for _, value := range row {
				switch entity := value.(type) {
				case *storage.Node:
					if entity != nil {
						id, valid := entity.Identity().NodeLookupID(store)
						if _, err := e.getQueryNode(store, id); valid && errors.Is(err, storage.ErrNotFound) {
							nodeIDs = append(nodeIDs, id)
						}
					}
				case *storage.Edge:
					if entity != nil {
						id := deleteEdgeLookupID(store, entity)
						if _, err := store.GetEdge(id); errors.Is(err, storage.ErrNotFound) {
							edgeIDs[id] = struct{}{}
						}
					}
				}
			}
			// The DELETE's targets, as the pipeline DELETE collects them (a
			// path's nodes and relationships, a list's entities).
			for _, target := range splitTopLevelComma(deleteVars) {
				value, ok := e.evaluateRowExpressionWithContext(ctx, strings.TrimSpace(target), row)
				if !ok {
					pipelineItemUnevaluable(ctx, target)
					return
				}
				collectDeleteTargetValue(store, value, seenNodes, seenEdges, &nodeIDs, &targetEdges)
			}
		}
		for _, id := range targetEdges {
			edgeIDs[id] = struct{}{}
		}
	}
	deleted := &deletedEntities{}
	deleted.addFromStorage(e.getStorage(ctx), nodeIDs, edgeIDs)
	if err := validateDeletedEntityReads(rows, cypher[returnIdx:], deleted); err != nil {
		recordExpressionFailure(ctx, err)
		return
	}
	e.replaceDeletedEntityViews(rows, deleted)
	projected, err := e.projectMergeReturn(ctx, rows, cypher[returnIdx:])
	if err != nil {
		return
	}
	result.Columns = projected.Columns
	result.Rows = projected.Rows
}

func (e *StorageExecutor) isDeleteStreamingEligible(matchSegment, deleteVars string, detach bool) bool {
	if !detach {
		return false
	}
	if strings.TrimSpace(matchSegment) == "" {
		return false
	}
	// Keep streaming path conservative to avoid semantic drift.
	for _, blocked := range []string{"WITH", "LIMIT", "SKIP", "ORDER", "CALL", "UNWIND"} {
		if containsKeywordOutsideStrings(matchSegment, blocked) {
			return false
		}
	}
	// Keep variable parsing simple and deterministic for now.
	if strings.Contains(deleteVars, ",") {
		return false
	}
	deleteVars = strings.TrimSpace(deleteVars)
	if deleteVars == "" {
		return false
	}
	// Basic identifier check
	for i, r := range deleteVars {
		if isIdentStartRune(r) || (i > 0 && r >= '0' && r <= '9') {
			continue
		}
		return false
	}
	return true
}

func (e *StorageExecutor) normalizeSetMatchRowsToNodes(matchResult *ExecuteResult, store storage.Engine) {
	if matchResult == nil {
		return
	}
	for rowIdx := range matchResult.Rows {
		row := matchResult.Rows[rowIdx]
		for colIdx, val := range row {
			m, ok := val.(map[string]interface{})
			if !ok {
				continue
			}
			rawID, ok := m["_nodeId"]
			if !ok {
				continue
			}
			nodeID, ok := rawID.(string)
			if !ok || nodeID == "" {
				continue
			}
			node, err := e.getQueryNode(store, storage.NodeID(nodeID))
			if err != nil || node == nil {
				continue
			}
			row[colIdx] = node
		}
	}
}

func (e *StorageExecutor) normalizeSetMatchRowsToEdges(matchResult *ExecuteResult, store storage.Engine) {
	if matchResult == nil {
		return
	}
	for rowIdx := range matchResult.Rows {
		row := matchResult.Rows[rowIdx]
		for colIdx, val := range row {
			m, ok := val.(map[string]interface{})
			if !ok {
				continue
			}
			rawID, ok := m["_edgeId"]
			if !ok {
				continue
			}
			edgeID, ok := rawID.(string)
			if !ok || edgeID == "" {
				continue
			}
			edge, err := store.GetEdge(storage.EdgeID(edgeID))
			if err != nil || edge == nil {
				continue
			}
			row[colIdx] = edge
		}
	}
}

var setScopeVarPattern = regexp.MustCompile(`(?i)\b([A-Za-z_][A-Za-z0-9_]*)\s*(?:\.|\+=|=)`)

// extractScopeVariablesFromSetAndReturn returns variable names referenced in
// SET assignments and RETURN items so the pre-SET MATCH query includes all
// variables needed for mutation and projection.
func extractScopeVariablesFromSetAndReturn(setPart, returnPart string) []string {
	seen := map[string]struct{}{}
	out := make([]string, 0, 4)
	add := func(v string) {
		v = strings.TrimSpace(v)
		if v == "" {
			return
		}
		if !isValidIdentifier(v) {
			return
		}
		if _, ok := seen[v]; ok {
			return
		}
		seen[v] = struct{}{}
		out = append(out, v)
	}

	for _, m := range setScopeVarPattern.FindAllStringSubmatch(setPart, -1) {
		if len(m) > 1 {
			add(m[1])
		}
	}

	if strings.TrimSpace(returnPart) != "" {
		for _, raw := range splitTopLevelCommaKeepEmpty(returnPart) {
			expr := strings.TrimSpace(raw)
			if expr == "" {
				continue
			}
			if asIdx := findKeywordIndex(expr, "AS"); asIdx > 0 {
				expr = strings.TrimSpace(expr[:asIdx])
			}
			add(extractVariableNameFromReturnItem(expr))
		}
	}
	return out
}

// collapseChainedSetClauses rewrites chained SET keywords into comma-separated assignments.
// Example: "n += $props SET n.x = 1 SET n.y = 2" -> "n += $props, n.x = 1, n.y = 2".
// Counting what a SET writes needs the clause boundaries, so the SET
// applicators walk the clauses with nextChainedSetClause instead.
func collapseChainedSetClauses(setPart string) string {
	setPart = strings.TrimSpace(setPart)
	first, next, ok := nextChainedSetClause(setPart, 0)
	if !ok {
		return setPart
	}
	clause, next, ok := nextChainedSetClause(setPart, next)
	if !ok {
		return first
	}
	clauses := []string{first}
	for ; ok; clause, next, ok = nextChainedSetClause(setPart, next) {
		clauses = append(clauses, clause)
	}
	return strings.Join(clauses, ", ")
}

// nextChainedSetClause returns the next non-empty clause at or after start in
// setPart, a SET assignment list that may chain further SET clauses
// ("n += $props SET n.x = 1"), and the index where the clause after it
// starts. ok is false when no clause is left.
func nextChainedSetClause(setPart string, start int) (clause string, next int, ok bool) {
	for start < len(setPart) {
		end, after := len(setPart), len(setPart)
		if idx := keywordIndexFrom(setPart, "SET", start, defaultKeywordScanOpts()); idx >= 0 {
			end, after = idx, idx+len("SET")
		}
		if clause = strings.TrimSpace(setPart[start:end]); clause != "" {
			return clause, after, true
		}
		start = after
	}
	return "", len(setPart), false
}

// firstPostSetClauseIndex returns the first index of a clause keyword that can
// legally follow a SET assignment list. Returns -1 when none are present.
func firstPostSetClauseIndex(setTail string) int {
	opts := defaultKeywordScanOpts()
	first := -1
	for _, kw := range []string{
		"REMOVE", "UNWIND", "WITH", "RETURN",
		"CREATE", "MATCH", "MERGE", "DELETE", "CALL",
		"ORDER BY", "LIMIT", "SKIP",
	} {
		if idx := keywordIndexFrom(setTail, kw, 0, opts); idx >= 0 {
			if first == -1 || idx < first {
				first = idx
			}
		}
	}
	return first
}

func (e *StorageExecutor) resolveUnwindValueFromExpr(ctx context.Context, unwindExpr string, nodeVars map[string]*storage.Node) interface{} {
	expr := normalizeUnwindExpression(unwindExpr)
	if strings.HasPrefix(expr, "$") {
		paramName := strings.TrimSpace(expr[1:])
		if paramName != "" {
			if params := getParamsFromContext(ctx); params != nil {
				if v, ok := params[paramName]; ok {
					return v
				}
			}
		}
	}
	return e.evaluateExpressionWithContext(ctx, expr, nodeVars, nil)
}

// normalizeUnwindExpression removes syntactic wrapper parentheses around a valid
// UNWIND expression, e.g. "($vals)" -> "$vals", while preserving inner
// expression content for evaluation.
func normalizeUnwindExpression(expr string) string {
	trimmed := strings.TrimSpace(expr)
	for hasOuterParens(trimmed) {
		trimmed = strings.TrimSpace(trimmed[1 : len(trimmed)-1])
	}
	return trimmed
}

func hasOuterParens(s string) bool {
	return len(s) >= 2 && s[0] == '(' && findMatchingDelimiter(s, 0, '(', ')') == len(s)-1
}

// coerceToUnwindItems is the one UNWIND coercion, as in Neo4j (#693): null
// unwinds to no rows, a list to its elements (cypherListValue), and any other
// value to one row holding it.
func coerceToUnwindItems(value interface{}) []interface{} {
	if value == nil {
		return nil
	}
	if items, isList := cypherListValue(value); isList {
		return items
	}
	return []interface{}{value}
}

func extractWithAliases(querySegment string) []string {
	matches := withAliasPattern.FindAllStringSubmatch(querySegment, -1)
	aliases := make([]string, 0, len(matches))
	for _, m := range matches {
		if len(m) > 1 {
			aliases = append(aliases, m[1])
		}
	}
	return aliases
}

func dedupeNonEmpty(groups ...[]string) []string {
	seen := make(map[string]struct{})
	out := make([]string, 0)
	for _, group := range groups {
		for _, item := range group {
			item = strings.TrimSpace(item)
			if item == "" {
				continue
			}
			if _, ok := seen[item]; ok {
				continue
			}
			seen[item] = struct{}{}
			out = append(out, item)
		}
	}
	return out
}

func normalizePropsMap(value interface{}, source string) (map[string]interface{}, error) {
	propsMap, ok := value.(map[string]interface{})
	if ok {
		for k, v := range propsMap {
			propsMap[k] = normalizePropValue(v)
		}
		return propsMap, nil
	}
	if genericMap, ok := value.(map[interface{}]interface{}); ok {
		propsMap = make(map[string]interface{}, len(genericMap))
		for k, v := range genericMap {
			keyStr, ok := k.(string)
			if !ok {
				return nil, localizedError(localization.CypherMutationsSetMergeStringKeysRequired(source, fmt.Sprintf("%T", k)), nil)
			}
			propsMap[keyStr] = normalizePropValue(v)
		}
		return propsMap, nil
	}
	return nil, localizedError(localization.CypherMutationsSetMergeMapRequired(source, fmt.Sprintf("%T", value)), nil)
}

func normalizePropValue(value interface{}) interface{} {
	normalized, _ := normalizedPropValue(value)
	return normalized
}

// normalizedPropValue is the one property value normalizer: Go integers
// become int64, float32 float64 and Go times DateTimes, in lists and maps
// too. A container is copied only when a descendant changes; rewritten
// describes a value conversion, independently of a writer's ownership copy.
func normalizedPropValue(value interface{}) (normalized interface{}, rewritten bool) {
	return normalizedCypherValue(value, true)
}

// normalizeExpressionValue admits a runtime value without storage's numeric
// coercion. Both boundaries share container, temporal and null normalization.
func normalizeExpressionValue(value interface{}) interface{} {
	normalized, _ := normalizedCypherValue(value, false)
	return normalized
}

func normalizedCypherValue(value interface{}, property bool) (normalized interface{}, rewritten bool) {
	if value != nil && cypherfn.RuntimeValue(value) == nil {
		return nil, true
	}
	if number, numeric := valueconvert.ReadNumber(value); numeric {
		if !property {
			return value, false
		}
		if number.IsInteger() {
			if integer, fits := number.Int64(valueconvert.IntegerOnly); fits {
				_, canonical := value.(int64)
				return integer, !canonical
			}
		}
		if _, canonical := value.(float64); canonical {
			return value, false
		}
		// Preserve storage's existing unsigned-overflow-to-Double policy;
		// a failed signed conversion must never wrap to a negative Long.
		return number.Float64(), true
	}
	switch v := value.(type) {
	case time.Time:
		return dateTimeFromGoTime(v), true
	case *time.Time:
		if v == nil {
			return nil, true
		}
		return dateTimeFromGoTime(*v), true
	case []interface{}:
		var out []interface{}
		for i, item := range v {
			stored, changed := normalizedCypherValue(item, property)
			if changed && out == nil {
				out = make([]interface{}, len(v))
				copy(out, v)
			}
			if out != nil {
				out[i] = stored
			}
		}
		if out != nil {
			return out, true
		}
		return value, false
	case map[string]interface{}:
		var out map[string]interface{}
		for k, item := range v {
			stored, changed := normalizedCypherValue(item, property)
			if changed && out == nil {
				out = cloneStringAnyMap(v)
			}
			if out != nil {
				out[k] = stored
			}
		}
		if out != nil {
			return out, true
		}
		return value, false
	default:
		return value, false
	}
}

func removeNodeLabels(existing []string, labelsToRemove []string) ([]string, int64) {
	if len(existing) == 0 || len(labelsToRemove) == 0 {
		return existing, 0
	}
	removeSet := make(map[string]struct{}, len(labelsToRemove))
	for _, label := range labelsToRemove {
		removeSet[label] = struct{}{}
	}
	next := make([]string, 0, len(existing))
	var removed int64
	for _, label := range existing {
		if _, ok := removeSet[label]; ok {
			removed++
			continue
		}
		next = append(next, label)
	}
	return next, removed
}

// executeCall handles CALL procedure queries.

// smartSplitReturnItems adapts callers to canonical top-level comma splitting.
func (e *StorageExecutor) smartSplitReturnItems(returnPart string) []string {
	return splitTopLevelComma(returnPart)
}

func (e *StorageExecutor) parseReturnItems(ctx context.Context, returnPart string) []returnItem {
	if strings.TrimSpace(returnPart) == "" {
		returnPart = "*"
	}
	plan := returnProjectionPlanFor(ctx, "RETURN "+returnPart)
	if plan.star {
		items := []returnItem{{expr: "*", alias: "*"}}
		for _, item := range plan.starItems {
			expr, alias := parseProjectionExprAlias(ctx, item)
			items = append(items, returnItem{expr: expr, alias: alias})
		}
		return items
	}
	items := make([]returnItem, 0, len(plan.projections))
	for _, projection := range plan.projections {
		items = append(items, returnItem{expr: projection.expr, alias: projection.alias})
	}
	return items
}

func normalizeProjectionColumnName(raw string) string {
	return symbolicNameValue(strings.TrimSpace(raw))
}

func (e *StorageExecutor) generateID() string {
	// Use UUID for globally unique IDs
	// This prevents ID collisions across server restarts which caused
	// the race condition where CREATE would cancel pending DELETEs
	return uuid.New().String()
}

// Deprecated: Sequential counter replaced with UUID generation
var idCounter int64

func (e *StorageExecutor) idCounter() int64 {
	// Keep for backward compatibility but not used in generateID anymore
	atomic.AddInt64(&idCounter, 1)
	return atomic.LoadInt64(&idCounter)
}

// evaluateRelationshipPatternInWhere evaluates a WHERE clause relationship pattern
// like "(n)-[:SUPERSEDED_BY]->()" and returns true if the node has a matching edge.
// Used when NOT (n)-[:TYPE]->() is evaluated after stripping outer parens to "n)-[:TYPE]->()".
func (e *StorageExecutor) evaluateRelationshipPatternInWhere(node *storage.Node, variable, pattern string) bool {
	if !strings.Contains(pattern, "("+variable+")") && !strings.Contains(pattern, "("+variable+":") {
		return false
	}
	relationshipCount := strings.Count(pattern, "-[")
	if relationshipCount > 1 {
		return e.checkChainedPattern(node, variable, pattern, "")
	}
	_ = e.extractTargetVariable(pattern, variable) // not needed for simple (var)-[]->() pattern
	relPattern := e.parseOptionalRelPattern(context.Background(), pattern)
	targetMatches := func(targetNodeID storage.NodeID) bool {
		if len(relPattern.targetLabels) == 0 && len(relPattern.targetProps) == 0 {
			return true
		}
		targetNode, err := e.getQueryNode(e.storage, targetNodeID)
		if err != nil || targetNode == nil {
			return false
		}
		if len(relPattern.targetLabels) > 0 && !mergeNodeHasLabels(targetNode, relPattern.targetLabels) {
			return false
		}
		for key, expected := range relPattern.targetProps {
			actual, ok := targetNode.Properties[key]
			if !ok || !e.compareEqual(actual, expected) {
				return false
			}
		}
		return true
	}
	var checkIncoming, checkOutgoing bool
	var relTypes []string
	checkIncoming, checkOutgoing, relTypes = e.relationshipExistencePatternDirections(pattern, variable)
	if checkIncoming {
		edges, _ := e.storage.GetIncomingEdges(node.ID)
		for _, edge := range edges {
			if (len(relTypes) == 0 || e.edgeTypeMatches(edge.Type, relTypes)) && targetMatches(edge.StartNode) {
				return true
			}
		}
	}
	if checkOutgoing {
		edges, _ := e.storage.GetOutgoingEdges(node.ID)
		for _, edge := range edges {
			if (len(relTypes) == 0 || e.edgeTypeMatches(edge.Type, relTypes)) && targetMatches(edge.EndNode) {
				return true
			}
		}
	}
	if !checkIncoming && !checkOutgoing {
		incoming, _ := e.storage.GetIncomingEdges(node.ID)
		outgoing, _ := e.storage.GetOutgoingEdges(node.ID)
		return len(incoming) > 0 || len(outgoing) > 0
	}
	return false
}

// checkChainedPattern handles chained relationship patterns like (p)-[:KNOWS]->()-[:KNOWS]->()
func (e *StorageExecutor) checkChainedPattern(node *storage.Node, variable, pattern, innerWhere string) bool {
	// Parse the pattern to extract relationship hops
	// E.g., (p)-[:KNOWS]->()-[:KNOWS]->() has two hops

	// Find the first relationship part
	// Pattern looks like: (variable)-[rel1]->(intermediate)-[rel2]->...

	// Find the start of the first relationship (after the variable node)
	varPattern := "(" + variable + ")"
	if !strings.Contains(pattern, varPattern) {
		// Try with label: (variable:Label)
		idx := strings.Index(pattern, "("+variable+":")
		if idx < 0 {
			return false
		}
	}

	// Extract relationship hops
	hops := e.parseRelationshipHops(pattern, variable)
	if len(hops) == 0 {
		return false
	}

	// Traverse the chain starting from the given node
	return e.traverseChain(node, hops, 0)
}

// relationshipHop represents one step in a chained relationship pattern
type relationshipHop struct {
	relTypes []string
	outgoing bool
}

// parseRelationshipHops extracts relationship hops from a pattern
func (e *StorageExecutor) parseRelationshipHops(pattern, variable string) []relationshipHop {
	var hops []relationshipHop

	// Find all relationship patterns: -[...]->  or  <-[...]-
	remaining := pattern

	for len(remaining) > 0 {
		// Look for outgoing: -[...]->(
		outIdx := strings.Index(remaining, "-[")
		inIdx := strings.Index(remaining, "<-[")

		if outIdx >= 0 && (inIdx < 0 || outIdx < inIdx) {
			// Found outgoing pattern
			relStart := outIdx + 2
			relEnd := strings.Index(remaining[relStart:], "]")
			if relEnd < 0 {
				break
			}
			relEnd += relStart

			relPart := remaining[relStart:relEnd]
			// Extract relationship types
			var relTypes []string
			if strings.HasPrefix(relPart, ":") {
				typePart := relPart[1:]
				// Handle multiple types separated by |
				for _, t := range strings.Split(typePart, "|") {
					if t = strings.TrimSpace(t); t != "" {
						relTypes = append(relTypes, t)
					}
				}
			}

			hops = append(hops, relationshipHop{
				relTypes: relTypes,
				outgoing: true,
			})

			remaining = remaining[relEnd+1:]
		} else if inIdx >= 0 {
			// Found incoming pattern
			relStart := inIdx + 3
			relEnd := strings.Index(remaining[relStart:], "]")
			if relEnd < 0 {
				break
			}
			relEnd += relStart

			relPart := remaining[relStart:relEnd]
			// Extract relationship types
			var relTypes []string
			if strings.HasPrefix(relPart, ":") {
				typePart := relPart[1:]
				for _, t := range strings.Split(typePart, "|") {
					if t = strings.TrimSpace(t); t != "" {
						relTypes = append(relTypes, t)
					}
				}
			}

			hops = append(hops, relationshipHop{
				relTypes: relTypes,
				outgoing: false,
			})

			remaining = remaining[relEnd+1:]
		} else {
			break
		}
	}

	return hops
}

// traverseChain recursively checks if a chain of relationships exists
func (e *StorageExecutor) traverseChain(node *storage.Node, hops []relationshipHop, hopIndex int) bool {
	if hopIndex >= len(hops) {
		return true // All hops matched
	}

	hop := hops[hopIndex]

	if hop.outgoing {
		edges, _ := e.storage.GetOutgoingEdges(node.ID)
		for _, edge := range edges {
			if len(hop.relTypes) == 0 || e.edgeTypeMatches(edge.Type, hop.relTypes) {
				// Get the target node and recurse
				nextNode, err := e.getQueryNode(e.storage, edge.EndNode)
				if err != nil {
					continue
				}
				if e.traverseChain(nextNode, hops, hopIndex+1) {
					return true
				}
			}
		}
	} else {
		edges, _ := e.storage.GetIncomingEdges(node.ID)
		for _, edge := range edges {
			if len(hop.relTypes) == 0 || e.edgeTypeMatches(edge.Type, hop.relTypes) {
				// Get the source node and recurse
				nextNode, err := e.getQueryNode(e.storage, edge.StartNode)
				if err != nil {
					continue
				}
				if e.traverseChain(nextNode, hops, hopIndex+1) {
					return true
				}
			}
		}
	}

	return false
}

// extractVariableNameFromReturnItem extracts the variable name from a return item expression.
// Examples:
//   - "n" -> "n"
//   - "n.name" -> "n"
//   - "id(n)" -> "n"
//   - "n.age + 1" -> "n"
func extractVariableNameFromReturnItem(expr string) string {
	expr = strings.TrimSpace(expr)
	if expr == "" {
		return ""
	}

	// Handle function calls like id(n), elementId(n), etc.
	if strings.Contains(expr, "(") {
		// Extract variable from function call: id(n) -> n
		openParen := strings.Index(expr, "(")
		closeParen := strings.LastIndex(expr, ")")
		if openParen > 0 && closeParen > openParen {
			inner := strings.TrimSpace(expr[openParen+1 : closeParen])
			// If inner contains a dot, it's property access: id(n.name) -> n
			if dotIdx := strings.Index(inner, "."); dotIdx > 0 {
				return strings.TrimSpace(inner[:dotIdx])
			}
			return inner
		}
	}

	// Handle property access: n.name -> n
	if strings.Contains(expr, ".") {
		parts := strings.SplitN(expr, ".", 2)
		return strings.TrimSpace(parts[0])
	}

	// Simple variable name
	return expr
}

// extractTargetVariable extracts the target variable name from a relationship pattern
// e.g., from "(m)-[:MANAGES]->(report)" it extracts "report"
func (e *StorageExecutor) extractTargetVariable(pattern, sourceVar string) string {
	// Look for outgoing pattern: (source)-[...]->(target)
	if arrowIdx := strings.Index(pattern, "]->"); arrowIdx >= 0 {
		rest := pattern[arrowIdx+3:]
		if parenIdx := strings.Index(rest, "("); parenIdx >= 0 {
			rest = rest[parenIdx+1:]
			// Extract variable name (before : or ))
			endIdx := strings.IndexAny(rest, ":)")
			if endIdx > 0 {
				return strings.TrimSpace(rest[:endIdx])
			}
		}
	}

	// Look for incoming pattern: (target)<-[...]-(source)
	if arrowIdx := strings.Index(pattern, "<-["); arrowIdx >= 0 {
		// Target is before the arrow
		before := pattern[:arrowIdx]
		if parenIdx := strings.LastIndex(before, "("); parenIdx >= 0 {
			inner := before[parenIdx+1:]
			endIdx := strings.IndexAny(inner, ":)")
			if endIdx > 0 {
				return strings.TrimSpace(inner[:endIdx])
			}
		}
	}

	return ""
}

// extractRelTypesFromPattern extracts relationship types from a pattern
func (e *StorageExecutor) extractRelTypesFromPattern(pattern, prefix string) []string {
	var types []string

	idx := strings.Index(pattern, prefix)
	if idx < 0 {
		return types
	}

	rest := pattern[idx+len(prefix):]
	endIdx := strings.Index(rest, "]")
	if endIdx < 0 {
		return types
	}

	relPart := rest[:endIdx]

	// Extract type after colon
	if colonIdx := strings.Index(relPart, ":"); colonIdx >= 0 {
		typePart := relPart[colonIdx+1:]
		// Handle multiple types (TYPE1|TYPE2)
		for _, t := range strings.Split(typePart, "|") {
			t = strings.TrimSpace(t)
			if t != "" {
				types = append(types, t)
			}
		}
	}

	return types
}

func (e *StorageExecutor) relationshipExistencePatternDirections(pattern, variable string) (incoming, outgoing bool, relTypes []string) {
	if groupStart := strings.Index(pattern, "("+variable+")"); groupStart >= 0 || strings.Contains(pattern, "("+variable+":") {
		if groupStart < 0 {
			groupStart = strings.Index(pattern, "("+variable+":")
		}
		groupEnd := groupStart + len(variable) + 2
		if strings.HasPrefix(pattern[groupStart:], "("+variable+":") {
			closeRel := strings.Index(pattern[groupStart:], ")")
			if closeRel >= 0 {
				groupEnd = groupStart + closeRel + 1
			}
		}
		before := pattern[:groupStart]
		after := pattern[groupEnd:]

		switch {
		case strings.HasPrefix(after, "<-["):
			incoming = true
			relTypes = e.extractRelTypesFromPattern(pattern, "<-[")
		case strings.HasPrefix(after, "-["):
			relTypes = e.extractRelTypesFromPattern(pattern, "-[")
			if strings.Contains(after, "]->") {
				outgoing = true
			} else if strings.Contains(after, "]-") {
				incoming = true
				outgoing = true
			}
		}

		switch {
		case strings.HasSuffix(before, "]->"):
			incoming = true
			if len(relTypes) == 0 {
				relTypes = e.extractRelTypesFromPattern(pattern, "-[")
			}
		case strings.Contains(before, "<-[") && strings.HasSuffix(before, "]-"):
			outgoing = true
			if len(relTypes) == 0 {
				relTypes = e.extractRelTypesFromPattern(pattern, "<-[")
			}
		case strings.HasSuffix(before, "]-"):
			incoming = true
			outgoing = true
			if len(relTypes) == 0 {
				relTypes = e.extractRelTypesFromPattern(pattern, "-[")
			}
		}
	}

	if !incoming && !outgoing {
		if in, out, ok := bareRelDirection(pattern, variable); ok {
			return in, out, nil
		}
	}
	return incoming, outgoing, relTypes
}

// edgeTypeMatches checks if an edge type matches any of the allowed types
func (e *StorageExecutor) edgeTypeMatches(edgeType string, allowedTypes []string) bool {
	for _, t := range allowedTypes {
		if edgeType == t {
			return true
		}
	}
	return false
}

// validatePolicyOnLabelChange checks RELATIONSHIP_POLICY constraints when a node's labels
// change. It validates all adjacent edges (outgoing and incoming) against the current
// policy constraints to ensure no DISALLOWED pair is formed and any ALLOWED whitelist
// is still satisfied.
func validatePolicyOnLabelChange(store storage.Engine, node *storage.Node, oldLabels []string) error {
	schema := store.GetSchema()
	if schema == nil {
		return nil
	}

	// Collect all policy constraints.
	constraints := schema.GetAllConstraints()
	var policies []storage.Constraint
	for _, c := range constraints {
		if c.Type == storage.ConstraintPolicy {
			policies = append(policies, c)
		}
	}
	if len(policies) == 0 {
		return nil
	}

	// Check outgoing edges (node is the source).
	outgoing, _ := store.GetOutgoingEdges(node.ID)
	for _, edge := range outgoing {
		targetNode, err := store.GetNode(storage.NodeID(edge.EndNode))
		if err != nil || targetNode == nil {
			continue
		}
		if err := checkPolicyForEdge(edge.Type, node.Labels, targetNode.Labels, policies); err != nil {
			return err
		}
	}

	// Check incoming edges (node is the target).
	incoming, _ := store.GetIncomingEdges(node.ID)
	for _, edge := range incoming {
		sourceNode, err := store.GetNode(storage.NodeID(edge.StartNode))
		if err != nil || sourceNode == nil {
			continue
		}
		if err := checkPolicyForEdge(edge.Type, sourceNode.Labels, node.Labels, policies); err != nil {
			return err
		}
	}

	return nil
}

// checkPolicyForEdge validates a single edge against all policy constraints for its type.
// DISALLOWED policies are checked first (they take precedence).
func checkPolicyForEdge(edgeType string, sourceLabels, targetLabels []string, policies []storage.Constraint) error {
	// Gather policies for this edge type.
	var relevantAllowed []storage.Constraint
	for _, p := range policies {
		if p.Label != edgeType {
			continue
		}
		if p.PolicyMode == "DISALLOWED" {
			if sliceContains(sourceLabels, p.SourceLabel) && sliceContains(targetLabels, p.TargetLabel) {
				return localizedError(localization.CypherResidualPolicyDisallowed(p.Name, p.SourceLabel, edgeType, p.TargetLabel), nil)
			}
		} else if p.PolicyMode == "ALLOWED" {
			relevantAllowed = append(relevantAllowed, p)
		}
	}

	// If ALLOWED policies exist for this edge type, at least one must match.
	if len(relevantAllowed) > 0 {
		matched := false
		for _, p := range relevantAllowed {
			if sliceContains(sourceLabels, p.SourceLabel) && sliceContains(targetLabels, p.TargetLabel) {
				matched = true
				break
			}
		}
		if !matched {
			return localizedError(localization.CypherResidualPolicyAllowedRequired(edgeType), nil)
		}
	}

	return nil
}

func sliceContains(slice []string, item string) bool {
	for _, s := range slice {
		if s == item {
			return true
		}
	}
	return false
}

// Patterns compiled once (#591): these helpers run per statement or per row.
var (
	// deleteWherePropertyEquals is the DELETE hot path's
	// "variable.property = value" predicate (the variable is compared by the
	// caller).
	deleteWherePropertyEquals = regexp.MustCompile(`(?i)^\s*([^.\s]+)\.(\w+)\s*=\s*(.+?)\s*$`)
	// deleteWherePropertyInParameter is "variable.property IN $param".
	deleteWherePropertyInParameter = regexp.MustCompile(`(?i)^\s*([^.\s]+)\.(\w+)\s+IN\s+\$(\w+)\s*$`)
	withAliasPattern               = regexp.MustCompile(`(?i)\bAS\s+([A-Za-z_][A-Za-z0-9_]*)\b`)
	subqueryWherePattern           = regexp.MustCompile(`(?i)\s+WHERE\s+`)
)

package cypher

import (
	"context"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// collectDeleteMutationTargets walks matchResult.Rows and classifies every
// projected value into either a node or relationship delete target,
// deduplicating repeats across rows. It performs no storage mutation --
// this is the "collect" phase of DELETE's collect -> validate -> apply
// pipeline (see validateNoResidualRelationships), which must complete
// before any validation or mutation so a multi-row, multi-variable DELETE
// (e.g. "DELETE a, r") can be judged as a whole statement.
func collectDeleteMutationTargets(store storage.Engine, matchResult *ExecuteResult) (nodeIDs []storage.NodeID, edgeIDs []storage.EdgeID) {
	seenNodes := make(map[string]struct{}, len(matchResult.Rows))
	seenEdges := make(map[string]struct{}, len(matchResult.Rows))
	nodeIDs = make([]storage.NodeID, 0, len(matchResult.Rows))
	edgeIDs = make([]storage.EdgeID, 0, len(matchResult.Rows))

	for _, row := range matchResult.Rows {
		for _, val := range row {
			collectDeleteTargetValue(store, val, seenNodes, seenEdges, &nodeIDs, &edgeIDs)
		}
	}

	return nodeIDs, edgeIDs
}

func collectDeleteTargetValue(store storage.Engine, value interface{}, seenNodes, seenEdges map[string]struct{}, nodeIDs *[]storage.NodeID, edgeIDs *[]storage.EdgeID) {
	target := classifyDeleteTargetValue(value)
	switch entity := value.(type) {
	case *storage.Node:
		if entity != nil {
			id, ok := entity.Identity().NodeLookupID(store)
			if !ok {
				return
			}
			target.nodeID = id
		}
	case *storage.Edge:
		if entity != nil {
			id, ok := entity.Identity().LookupID(store, "5")
			if !ok {
				return
			}
			target.edgeID = storage.EdgeID(id)
		}
	}
	switch target.kind {
	case deleteProjectionRelationship:
		key := string(target.edgeID)
		if _, seen := seenEdges[key]; !seen {
			seenEdges[key] = struct{}{}
			*edgeIDs = append(*edgeIDs, target.edgeID)
		}
		return
	case deleteProjectionNode:
		key := string(target.nodeID)
		if _, seen := seenNodes[key]; !seen {
			seenNodes[key] = struct{}{}
			*nodeIDs = append(*nodeIDs, target.nodeID)
		}
		return
	}

	switch typed := value.(type) {
	case PathResult:
		for _, node := range typed.Nodes {
			collectDeleteTargetValue(store, node, seenNodes, seenEdges, nodeIDs, edgeIDs)
		}
		for _, edge := range typed.Relationships {
			collectDeleteTargetValue(store, edge, seenNodes, seenEdges, nodeIDs, edgeIDs)
		}
	case *PathResult:
		if typed != nil {
			collectDeleteTargetValue(store, *typed, seenNodes, seenEdges, nodeIDs, edgeIDs)
		}
	case []interface{}:
		for _, item := range typed {
			collectDeleteTargetValue(store, item, seenNodes, seenEdges, nodeIDs, edgeIDs)
		}
	case map[string]interface{}:
		if path, ok := typed["_pathResult"]; ok {
			collectDeleteTargetValue(store, path, seenNodes, seenEdges, nodeIDs, edgeIDs)
			return
		}
		for _, item := range typed {
			collectDeleteTargetValue(store, item, seenNodes, seenEdges, nodeIDs, edgeIDs)
		}
	}
}

func isDeleteTargetValue(value interface{}) bool {
	// Marker keys in an ordinary Cypher map are user data, not authority to
	// delete an entity. Only the evaluator's actual PathResult carrier is a
	// map-shaped DELETE value; legacy projection classification stays private.
	if object, isMap := value.(map[string]interface{}); isMap {
		_, isPath := cypherPathResultOf(value, object, true)
		return isPath
	}
	if value == nil || classifyDeleteTargetValue(value).kind != deleteProjectionUnknown {
		return true
	}
	switch typed := value.(type) {
	case PathResult:
		return true
	case *PathResult:
		return typed != nil
	case []interface{}:
		for _, item := range typed {
			if !isDeleteTargetValue(item) {
				return false
			}
		}
		return true
	default:
		return false
	}
}

func hasTopLevelDeleteLabelQualifier(expression string) bool {
	expression = strings.TrimSpace(expression)
	depth := 0
	for index := 0; index < len(expression); index++ {
		if end, quoted := skipCypherLexicalToken(expression, index); quoted {
			index = end - 1
			continue
		}
		character := expression[index]
		switch character {
		case '(', '[', '{':
			depth++
		case ')', ']', '}':
			if depth > 0 {
				depth--
			}
		case ':':
			if depth == 0 {
				return true
			}
		}
	}
	return false
}

// deleteExpressionRootIdentifier returns the variable a DELETE target starts
// with (n in n, n.list[0], `n`), "" for a function call or a literal: null,
// true and false are never variables there (DELETE null deletes nothing, as
// in Neo4j, #907).
func deleteExpressionRootIdentifier(expression string) string {
	expression = strings.TrimSpace(expression)
	if expression == "" {
		return ""
	}
	// The name is read by the one identifier rule (scanIdentifierToken):
	// n$ and `a``b` are variables too.
	name, end, ok := scanIdentifierToken(expression, 0)
	if !ok || (end < len(expression) && expression[end] == '(') {
		return ""
	}
	if !strings.HasPrefix(expression, "`") {
		switch lowerASCII(name) {
		case "null", "true", "false":
			return ""
		}
	}
	return name
}

func addPipelinePatternBindings(ctx context.Context, executor *StorageExecutor, scope map[string]struct{}, clause, keyword string) {
	pattern := strings.TrimSpace(clause)
	if len(pattern) >= len(keyword) && strings.EqualFold(pattern[:len(keyword)], keyword) {
		pattern = strings.TrimSpace(pattern[len(keyword):])
	}
	if where := findKeywordIndexInContext(pattern, "WHERE"); where >= 0 {
		pattern = strings.TrimSpace(pattern[:where])
	}
	for _, variable := range executor.extractVariableNamesFromPattern(ctx, pattern) {
		if variable != "" {
			scope[variable] = struct{}{}
		}
	}
	for _, variable := range extractRelationshipVariables(pattern) {
		if variable != "" {
			scope[variable] = struct{}{}
		}
	}
	if variable := extractPathAssignmentVariable(pattern); variable != "" {
		scope[variable] = struct{}{}
	}
}

func extractPathAssignmentVariable(pattern string) string {
	if equals := strings.Index(pattern, "="); equals > 0 {
		candidate := strings.TrimSpace(pattern[:equals])
		right := strings.TrimSpace(pattern[equals+1:])
		if isPatternVariableName(candidate) && (strings.HasPrefix(right, "(") ||
			matchFuncStartAndSuffix(right, "shortestpath") ||
			matchFuncStartAndSuffix(right, "allshortestpaths")) {
			return normalizeProjectionColumnName(candidate)
		}
	}
	return ""
}

func appendUniquePipelineBinding(bindings []string, binding string) []string {
	for _, existing := range bindings {
		if existing == binding {
			return bindings
		}
	}
	return append(bindings, binding)
}

func pipelineUnwindAlias(clause string) string {
	if _, alias, ok := parsePipelineIteration(clause); ok {
		return normalizeProjectionColumnName(alias)
	}
	if index := findKeywordIndexInContext(clause, "AS"); index >= 0 {
		return strings.TrimSpace(clause[index+len("AS"):])
	}
	return ""
}

// validateNoResidualRelationships enforces openCypher/Neo4j DELETE
// semantics: a non-DETACH DELETE of a node that still has relationships is
// an error, not a silent cascade. NornicDB's storage layer
// (BadgerEngine.DeleteNode) cascades every adjacent edge unconditionally,
// so without this check a plain "DELETE n" on a connected node quietly
// deleted its edges too, violating Cypher's connected-node constraint.
//
// This must run BEFORE any node or edge in the plan is mutated: validating
// mid-apply would let a multi-row DELETE partially commit before a later
// row is found to violate the constraint, breaking statement atomicity.
//
// An edge attached to a candidate node does not count as residual if the
// same statement is also deleting that edge (e.g.
// "MATCH (a)-[r]->(b) DELETE a, r"); edgeIDs holds every edge this
// statement is about to remove, so those are subtracted before the check.
func validateNoResidualRelationships(store storage.Engine, nodeIDs []storage.NodeID, edgeIDs []storage.EdgeID) error {
	beingDeleted := deletingEdgeSet(edgeIDs)
	for _, nodeID := range nodeIDs {
		connected, err := nodeHasResidualRelationships(store, nodeID, beingDeleted)
		if err != nil {
			return err
		}
		if connected {
			return residualRelationshipDeleteError(nodeID)
		}
	}
	return nil
}

// connectedDeleteTargets returns the nodes of nodeIDs that relationships
// other than edgeIDs (this DELETE's own) still connect: a non-DETACH DELETE
// deletes them for now, and the transaction's commit fails unless a later
// clause deletes those relationships, as in Neo4j
// (storage.ConnectedNodeDeleter).
func connectedDeleteTargets(store storage.Engine, nodeIDs []storage.NodeID, edgeIDs []storage.EdgeID) (map[storage.NodeID]struct{}, error) {
	beingDeleted := deletingEdgeSet(edgeIDs)
	var connected map[storage.NodeID]struct{}
	for _, nodeID := range nodeIDs {
		residual, err := nodeHasResidualRelationships(store, nodeID, beingDeleted)
		if err != nil {
			return nil, err
		}
		if residual {
			if connected == nil {
				connected = make(map[storage.NodeID]struct{})
			}
			connected[nodeID] = struct{}{}
		}
	}
	return connected, nil
}

func deletingEdgeSet(edgeIDs []storage.EdgeID) map[storage.EdgeID]struct{} {
	beingDeleted := make(map[storage.EdgeID]struct{}, len(edgeIDs))
	for _, id := range edgeIDs {
		beingDeleted[id] = struct{}{}
	}
	return beingDeleted
}

// nodeHasResidualRelationships reports whether a relationship other than
// those beingDeleted connects nodeID (connectingRelationships).
func nodeHasResidualRelationships(store storage.Engine, nodeID storage.NodeID, beingDeleted map[storage.EdgeID]struct{}) (bool, error) {
	connecting, err := connectingRelationships(store, nodeID)
	if err != nil {
		return false, err
	}
	for _, edge := range connecting {
		if _, deleting := beingDeleted[deleteEdgeLookupID(store, edge)]; !deleting {
			return true, nil
		}
	}
	return false, nil
}

// connectingRelationships returns the relationships that connect nodeID for
// a DELETE: those DETACH DELETE removes with the node, and those that keep a
// non-DETACH DELETE from removing it. A store that lists the relationships the
// visibility layer hides (storage.IncidentEdgeLister: a transaction) lists
// them too, since the node's delete removes them all the same; without them a
// non-DETACH DELETE removed a node whose only relationships were hidden, as
// in Neo4j it fails with DeleteConnectedNode for any relationship. Stores run
// without a transaction (composite and remote databases) list what their
// reads return.
func connectingRelationships(store storage.Engine, nodeID storage.NodeID) ([]*storage.Edge, error) {
	if lister, ok := store.(storage.IncidentEdgeLister); ok {
		return lister.IncidentEdges(nodeID)
	}
	return undirectedIncidentEdges(store, nodeID)
}

// residualRelationshipDeleteError builds the error returned when a
// non-DETACH DELETE targets a node that still has relationships. The
// wording mirrors Neo4j's own "still has relationships" DELETE error so
// clients that pattern-match on that message keep working against
// NornicDB.
func residualRelationshipDeleteError(nodeID storage.NodeID) error {
	message := localization.CypherTransactionsDeleteResidualRelationships(string(nodeID))
	return &classifiedCypherError{
		cause:  localizedError(message, nil),
		code:   "Neo.ClientError.Schema.ConstraintValidationFailed",
		detail: "DeleteConnectedNode",
	}
}

// staticDeleteTargetTypeError keeps known non-entity values as compile-time
// errors, while widened UNWIND map elements remain runtime checks. Strings
// and lists retain the existing NornicDB DELETE extensions.
func staticDeleteTargetTypeError(ctx context.Context, clause string, scope staticTypeScope) error {
	targets, _, _ := deleteClauseTargets(clause)
	// Undefined targets retain the existing DELETE scope error owner.
	scope.complete = false
	checker := staticOperatorChecker{scope: scope}
	for _, target := range targets {
		operand, err := checker.check(ctx, strings.TrimSpace(target))
		if err != nil {
			return err
		}
		// A string target is NornicDB's DELETE-by-id extension, and a list
		// deletes its elements: reject a target none of whose types is one.
		if operand.excludes(isDeleteTargetTypeName) {
			return typeNameMismatchError("Node, Path or Relationship", operand.typeName())
		}
	}
	return nil
}

package cypher

import (
	"context"
	"strconv"
	"strings"

	"github.com/orneryd/nornicdb/pkg/storage"
)

func (e *StorageExecutor) tryExecuteBoundRelationshipDelete(
	ctx context.Context,
	matchSegment string,
	cypher string,
	deleteVars string,
	detach bool,
) (*ExecuteResult, bool, error) {
	matchSegment = strings.TrimSpace(matchSegment)
	_, inTransactionWrapper := e.getStorage(ctx).(*transactionStorageWrapper)
	if detach || strings.Contains(deleteVars, ",") {
		return nil, false, nil
	}
	deleteVar := strings.TrimSpace(deleteVars)
	if deleteVar == "" {
		return nil, false, nil
	}
	limit := -1
	baseMatchSegment := matchSegment
	if !isSimpleBoundRelationshipDeleteMatchSegment(matchSegment) {
		limitedSegment, limitedRows, ok := parseBoundRelationshipDeleteWithLimitSegment(matchSegment, deleteVar)
		if !ok {
			return nil, false, nil
		}
		baseMatchSegment = limitedSegment
		limit = limitedRows
	}

	if !patternMapsAreConstant(baseMatchSegment) {
		return nil, false, nil
	}

	pseudo := baseMatchSegment + " RETURN __delete_probe__"
	returnIdx := findKeywordIndex(pseudo, "RETURN")
	if returnIdx <= 0 {
		return nil, false, nil
	}
	whereIdx := lastKeywordIndexBefore(pseudo, "WHERE", returnIdx)
	clauses := splitMatchClauses(pseudo, whereIdx, returnIdx)
	if len(clauses) != 2 {
		return nil, false, nil
	}

	sourcePattern, parseErr := readNodePattern(ctx, clauses[0], patternPropertyKeys)
	if parseErr != nil {
		return nil, true, parseErr
	}
	if sourcePattern.variable == "" {
		return nil, false, nil
	}
	relPatternText := strings.TrimSpace(clauses[1])
	relMatch := e.parseTraversalPatternStructure(ctx, relPatternText)
	if relMatch == nil || relMatch.IsChained {
		return nil, false, nil
	}
	if relMatch.StartNode.variable != sourcePattern.variable {
		return nil, false, nil
	}
	if relMatch.Relationship.Variable != deleteVar {
		return nil, false, nil
	}
	if relMatch.Relationship.MinHops != 1 || relMatch.Relationship.MaxHops != 1 {
		return nil, false, nil
	}
	if relMatch.Relationship.Direction != "outgoing" && relMatch.Relationship.Direction != "incoming" && relMatch.Relationship.Direction != "both" {
		return nil, false, nil
	}

	whereClause := ""
	if whereIdx > 0 && whereIdx < returnIdx {
		whereClause = strings.TrimSpace(pseudo[whereIdx+len("WHERE") : returnIdx])
	}

	rowCtx, sourceText, err := e.preparePatternRow(ctx, clauses[0], nil)
	if err != nil {
		return nil, true, err
	}
	sourcePattern, err = e.parseNodePattern(rowCtx, sourceText)
	if err != nil {
		return nil, true, err
	}
	sources, err := e.collectBoundRelationshipDeleteSources(rowCtx, sourcePattern, inTransactionWrapper)
	if err != nil {
		return nil, true, err
	}
	if len(sources) == 0 {
		result := &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}, Stats: &QueryStats{}}
		e.applyDeleteReturnProjection(result, cypher, deleteVar, singleDeleteProjectionInfo(deleteVar, deleteProjectionRelationship))
		return result, true, nil
	}

	typeSet := buildRelTypeSet(relMatch.Relationship.Types)
	store := e.getStorage(ctx)
	edgeIDs := make([]storage.EdgeID, 0)
	seen := make(map[storage.EdgeID]struct{})
	for _, source := range sources {
		if source == nil {
			continue
		}
		rowCtx, rowPattern, err := e.preparePatternRow(ctx, relPatternText, map[string]interface{}{sourcePattern.variable: source})
		if err != nil {
			return nil, true, err
		}
		rowMatch := e.parseTraversalPattern(rowCtx, rowPattern)
		if failure := getExpressionFailure(rowCtx); failure != nil {
			return nil, true, failure
		}
		if rowMatch == nil || !e.pipelineNodeMatchesPattern(source, rowMatch.StartNode) {
			continue
		}
		candidates, err := e.boundRelationshipDeleteCandidateEdges(store, source.ID, rowMatch.Relationship.Direction)
		if err != nil {
			return nil, true, err
		}
		for _, edge := range candidates {
			if edge == nil || !relationshipTypeAllowed(edge.Type, rowMatch.Relationship.Types, typeSet) {
				continue
			}
			if len(rowMatch.Relationship.Properties) > 0 && !e.edgeMatchesProps(edge, rowMatch.Relationship.Properties) {
				continue
			}
			target, ok, err := e.boundRelationshipDeleteTargetNode(store, source.ID, edge, rowMatch.Relationship.Direction)
			if err != nil {
				return nil, true, err
			}
			if !ok || !e.matchesEndPattern(target, &rowMatch.EndNode) {
				continue
			}
			if whereClause != "" {
				pathCtx := PathContext{
					nodes: map[string]*storage.Node{
						rowMatch.StartNode.variable: source,
					},
					rels: map[string]*storage.Edge{
						deleteVar: edge,
					},
				}
				if rowMatch.EndNode.variable != "" {
					pathCtx.nodes[rowMatch.EndNode.variable] = target
				}
				if !e.evaluateWhereOnPath(rowCtx, whereClause, pathCtx) {
					continue
				}
			}
			if _, exists := seen[edge.ID]; exists {
				continue
			}
			seen[edge.ID] = struct{}{}
			edgeIDs = append(edgeIDs, edge.ID)
			if limit > 0 && len(edgeIDs) >= limit {
				break
			}
		}
		if limit > 0 && len(edgeIDs) >= limit {
			break
		}
	}

	result := &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}, Stats: &QueryStats{}}
	if len(edgeIDs) > 0 {
		if err := store.BulkDeleteEdges(edgeIDs); err != nil {
			return nil, true, err
		}
		result.Stats.RelationshipsDeleted = len(edgeIDs)
		for _, edgeID := range edgeIDs {
			e.notifyEdgeMutated(string(edgeID))
		}
	}
	e.applyDeleteReturnProjection(result, cypher, deleteVar, singleDeleteProjectionInfo(deleteVar, deleteProjectionRelationship))
	return result, true, nil
}

func (e *StorageExecutor) collectBoundRelationshipDeleteSources(ctx context.Context, sourcePattern nodePatternInfo, inTransactionWrapper bool) ([]*storage.Node, error) {
	if !inTransactionWrapper {
		return e.collectNodesWithStreaming(ctx, sourcePattern.labels, sourcePattern.properties, sourcePattern.variable, "", -1)
	}

	store := e.getStorage(ctx)
	if txWrapper, ok := store.(*transactionStorageWrapper); !ok || !txWrapper.tx.HasPendingNodeMutations() {
		return e.collectNodesWithStreaming(ctx, sourcePattern.labels, sourcePattern.properties, sourcePattern.variable, "", -1)
	}

	var nodes []*storage.Node
	var err error
	if len(sourcePattern.labels) > 0 {
		nodes, err = store.GetNodesByLabel(sourcePattern.labels[0])
	} else {
		nodes, err = store.AllNodes()
	}
	if err != nil {
		return nil, err
	}

	filtered := make([]*storage.Node, 0, len(nodes))
	hideSystemNodes := shouldHideSystemNodes(store)
	for _, node := range nodes {
		if node == nil {
			continue
		}
		if hideSystemNodes && isSystemNode(node) {
			continue
		}
		if len(sourcePattern.labels) > 0 && !mergeNodeHasLabels(node, sourcePattern.labels) {
			continue
		}
		if len(sourcePattern.properties) > 0 && !e.nodeMatchesProps(node, sourcePattern.properties) {
			continue
		}
		filtered = append(filtered, node)
	}
	return filtered, nil
}

func (e *StorageExecutor) boundRelationshipDeleteCandidateEdges(store storage.Engine, nodeID storage.NodeID, direction string) ([]*storage.Edge, error) {
	var edges []*storage.Edge
	switch direction {
	case "outgoing":
		outgoing, err := store.GetOutgoingEdges(nodeID)
		if err != nil {
			return nil, err
		}
		edges = append(edges, outgoing...)
	case "incoming":
		incoming, err := store.GetIncomingEdges(nodeID)
		if err != nil {
			return nil, err
		}
		edges = append(edges, incoming...)
	case "both":
		outgoing, err := store.GetOutgoingEdges(nodeID)
		if err != nil {
			return nil, err
		}
		incoming, err := store.GetIncomingEdges(nodeID)
		if err != nil {
			return nil, err
		}
		edges = append(edges, outgoing...)
		edges = append(edges, incoming...)
	}
	return edges, nil
}

func parseBoundRelationshipDeleteWithLimitSegment(matchSegment, deleteVar string) (string, int, bool) {
	for _, blocked := range []string{"ORDER BY", "SKIP", "CALL", "UNWIND", "OPTIONAL MATCH"} {
		if containsKeywordOutsideStrings(matchSegment, blocked) {
			return "", 0, false
		}
	}
	withIdx := findKeywordIndex(matchSegment, "WITH")
	if withIdx <= 0 {
		return "", 0, false
	}
	baseMatch := strings.TrimSpace(matchSegment[:withIdx])
	if !isSimpleBoundRelationshipDeleteMatchSegment(baseMatch) {
		return "", 0, false
	}
	withPart := strings.TrimSpace(matchSegment[withIdx+len("WITH"):])
	limitIdx := findKeywordIndex(withPart, "LIMIT")
	if limitIdx <= 0 {
		return "", 0, false
	}
	withVar := strings.TrimSpace(withPart[:limitIdx])
	if withVar != deleteVar {
		return "", 0, false
	}
	limitLiteral := strings.TrimSpace(withPart[limitIdx+len("LIMIT"):])
	fields := strings.Fields(limitLiteral)
	if len(fields) != 1 {
		return "", 0, false
	}
	limitN, err := strconv.Atoi(fields[0])
	if err != nil || limitN <= 0 {
		return "", 0, false
	}
	return baseMatch, limitN, true
}

func isSimpleBoundRelationshipDeleteMatchSegment(matchSegment string) bool {
	if strings.TrimSpace(matchSegment) == "" {
		return false
	}
	for _, blocked := range []string{"WITH", "LIMIT", "SKIP", "ORDER BY", "CALL", "UNWIND", "OPTIONAL MATCH"} {
		if containsKeywordOutsideStrings(matchSegment, blocked) {
			return false
		}
	}
	return true
}

func (e *StorageExecutor) boundRelationshipDeleteTargetNode(
	store storage.Engine,
	sourceID storage.NodeID,
	edge *storage.Edge,
	direction string,
) (*storage.Node, bool, error) {
	var targetID storage.NodeID
	switch direction {
	case "outgoing":
		if edge.StartNode != sourceID {
			return nil, false, nil
		}
		targetID = edge.EndNode
	case "incoming":
		if edge.EndNode != sourceID {
			return nil, false, nil
		}
		targetID = edge.StartNode
	case "both":
		if edge.StartNode == sourceID {
			targetID = edge.EndNode
		} else if edge.EndNode == sourceID {
			targetID = edge.StartNode
		} else {
			return nil, false, nil
		}
	default:
		return nil, false, nil
	}
	target, err := e.getQueryNode(store, targetID)
	if err != nil || target == nil {
		return nil, false, nil
	}
	return target, true, nil
}

func relationshipTypeAllowed(edgeType string, allowed []string, allowedSet map[string]struct{}) bool {
	if len(allowed) == 0 {
		return true
	}
	if len(allowed) == 1 {
		return edgeType == allowed[0]
	}
	_, ok := allowedSet[edgeType]
	return ok
}

package cypher

import (
	"context"
	"fmt"
	"strings"

	"github.com/orneryd/nornicdb/pkg/config"
	"github.com/orneryd/nornicdb/pkg/cypher/antlr"
	"github.com/orneryd/nornicdb/pkg/localization"
)

// isSystemCommandNoGraph returns true for statements that operate on database metadata
// (CREATE/DROP DATABASE, SHOW DATABASES, etc.) and must not use the async engine or
// implicit transactions. These are routed to executeWithoutTransaction directly.
func isSystemCommandNoGraph(cypher string) bool {
	return startsWithKeywords(cypher, "CREATE", "COMPOSITE DATABASE") ||
		isCreateOrReplaceDatabaseQuery(cypher) ||
		startsWithKeywords(cypher, "CREATE", "DATABASE") ||
		startsWithKeywords(cypher, "CREATE", "ALIAS") ||
		startsWithKeywords(cypher, "DROP", "COMPOSITE DATABASE") ||
		startsWithKeywords(cypher, "DROP", "DATABASE") ||
		startsWithKeywords(cypher, "DROP", "ALIAS") ||
		startsWithKeywords(cypher, "SHOW", "DATABASES") ||
		startsWithKeywords(cypher, "ALTER", "DATABASE") ||
		isPrivilegeAdministrationCommand(cypher)
}

func isShowConstraintContractsCommand(cypher string) bool {
	return startsWithKeywords(cypher, "SHOW", "CONSTRAINT CONTRACTS")
}

// topLevelUnion reports whether cypher composes complete single queries with
// UNION at its top level, and whether it is UNION ALL. Such a statement is a
// UNION before it is anything else: every route sends it to executeUnion
// before a handler for its first clause can take the leading branch for the
// whole statement, including the auto-commit async CREATE fast paths (#781).
// The substring guard keeps other queries off the structural scanner, which
// tells top-level separators from nested subqueries.
func topLevelUnion(ctx context.Context, cypher, upperQuery string) (unionAll, union bool) {
	if !strings.Contains(upperQuery, "UNION") {
		return false, false
	}
	branches, unionAll, _, ok := parseTopLevelUnionBranches(ctx, cypher)
	return unionAll, ok && len(branches) > 1
}

// executeWithoutTransaction executes query without transaction wrapping (original path).
func (e *StorageExecutor) executeWithoutTransaction(ctx context.Context, cypher string, upperQuery string) (result *ExecuteResult, err error) {
	ctx, cleanupReveal, readScopeEngine := setRevealOnEngine(ctx, e.storage, hasRevealCall(cypher))
	defer cleanupReveal()
	if readScopeEngine != nil {
		defer clearRevealScope(ctx, readScopeEngine)
	}
	if scoped := e.withStatementPropertyViews(ctx, cypher); scoped != nil {
		return scoped.executeWithoutTransaction(ctx, cypher, upperQuery)
	}
	if mayContainSubqueryExpression(cypher) && len(findSubqueryExpressions(cypher)) > 0 {
		scope := &expressionStatsContext{Context: ctx}
		ctx = scope
		defer func() {
			if err == nil && result != nil {
				stats := scope.snapshot()
				result.Stats = mergeQueryStats(result.Stats, &stats)
			}
		}()
	}
	defer func() { e.projectQueryResultProperties(result) }()
	defer func() {
		if recorded := getExpressionFailure(ctx); recorded != nil && err == nil {
			result, err = nil, recorded
		}
	}()
	// A top-level UNION composes complete single queries. Route it before any
	// handler can consume the leading MATCH, RETURN, or UNWIND branch.
	if unionAll, union := topLevelUnion(ctx, cypher, upperQuery); union {
		return e.executeUnion(ctx, cypher, unionAll, nil)
	}
	if result, handled, err := e.executeShowStatement(ctx, cypher); handled {
		return result, err
	}
	if strings.Contains(upperQuery, "CALL") {
		if firstTopLevelCallSubquery(ctx, cypher) >= 0 {
			return e.executeRequiredPipeline(ctx, cypher)
		}
	}

	if result, handled := e.tryFastPathSimpleMatchReturnLimit(ctx, cypher, upperQuery); handled {
		return result, nil
	}
	if result, handled := e.tryFastPathMatchVectorCosine(ctx, cypher, upperQuery); handled {
		return result, nil
	}
	if result, handled := e.tryFastPathMatchWithVectorCosineProjection(ctx, cypher, upperQuery); handled {
		return result, nil
	}
	if result, handled := e.tryFastPathMatchRelationshipVectorCosine(ctx, cypher, upperQuery); handled {
		return result, nil
	}
	if result, handled := e.tryFastPathMatchWithRelationshipVectorCosineProjection(ctx, cypher, upperQuery); handled {
		return result, nil
	}

	startsWithMatch := strings.HasPrefix(upperQuery, "MATCH")
	startsWithCreate := strings.HasPrefix(upperQuery, "CREATE")
	startsWithMerge := strings.HasPrefix(upperQuery, "MERGE")

	if startsWithMatch && topLevelKeywordIndex(cypher, "CALL") > 0 {
		return e.executeRequiredPipeline(ctx, cypher)
	}

	if startsWithMerge {
		return e.executeRequiredPipeline(ctx, cypher)
	}

	var mergeIdx, createIdx, withIdx, optionalMatchIdx int = -1, -1, -1, -1

	if startsWithMatch {
		mergeIdx = findKeywordIndex(cypher, "MERGE")
		createIdx = findKeywordIndex(cypher, "CREATE")
		optionalMatchIdx = findMultiWordKeywordIndex(cypher, "OPTIONAL", "MATCH")
	} else if startsWithCreate {
		if !isCreateProcedureCommand(cypher) &&
			!startsWithKeywords(cypher, "CREATE", "DECAY PROFILE") &&
			!startsWithKeywords(cypher, "CREATE", "PROMOTION PROFILE") &&
			!startsWithKeywords(cypher, "CREATE", "PROMOTION POLICY") {
			if _, ok := canExecuteAsPipeline(ctx, cypher); ok {
				return e.executeRequiredPipeline(ctx, cypher)
			}
		}
		withIdx = findKeywordIndex(cypher, "WITH")
	}

	if startsWithMatch && mergeIdx > 0 {
		return e.executeRequiredPipeline(ctx, cypher)
	}
	if startsWithMatch && createIdx > 0 {
		return e.executeRequiredPipeline(ctx, cypher)
	}
	if startsWithCreate && withIdx > 0 {
		return e.executeRequiredPipeline(ctx, cypher)
	}
	if findKeywordIndex(cypher, "UNWIND") == 0 || startsWithKeywordFold(cypher, "FOR") ||
		startsWithKeywordFold(cypher, "LET") || startsWithKeywordFold(cypher, "FILTER") {
		return e.executeRequiredPipeline(ctx, cypher)
	}

	hasDelete := findKeywordIndex(cypher, "DELETE") >= 0
	hasDetachDelete := containsKeywordOutsideStrings(cypher, "DETACH DELETE")
	if hasDelete || hasDetachDelete {
		return e.executeRequiredPipeline(ctx, cypher)
	}

	hasSet := containsKeywordOutsideStrings(cypher, "SET")
	hasOnCreateSet := containsKeywordOutsideStrings(cypher, "ON CREATE SET")
	hasOnMatchSet := containsKeywordOutsideStrings(cypher, "ON MATCH SET")
	if startsWithMatch && hasSet && containsKeywordOutsideStrings(cypher, "REMOVE") {
		return e.executeRequiredPipeline(ctx, cypher)
	}

	if startsWithCreate && hasSet && containsKeywordOutsideStrings(cypher, "REMOVE") {
		return e.executeRequiredPipeline(ctx, cypher)
	}
	if startsWithCreate && !isCreateProcedureCommand(cypher) && hasSet && !hasOnCreateSet && !hasOnMatchSet &&
		!startsWithKeywords(cypher, "CREATE", "DECAY PROFILE") &&
		!startsWithKeywords(cypher, "CREATE", "PROMOTION PROFILE") &&
		!startsWithKeywords(cypher, "CREATE", "PROMOTION POLICY") {
		return e.executeRequiredPipeline(ctx, cypher)
	}

	if startsWithKeywords(cypher, "ALTER", "DATABASE") {
		return e.executeAlterDatabase(ctx, cypher)
	}

	if hasSet && !isCreateProcedureCommand(cypher) && !hasOnCreateSet && !hasOnMatchSet &&
		!startsWithKeywords(cypher, "CREATE", "DECAY PROFILE") &&
		!startsWithKeywords(cypher, "CREATE", "PROMOTION PROFILE") &&
		!startsWithKeywords(cypher, "CREATE", "PROMOTION POLICY") &&
		!startsWithKeywords(cypher, "ALTER", "DECAY PROFILE") &&
		!startsWithKeywords(cypher, "ALTER", "PROMOTION PROFILE") &&
		!startsWithKeywords(cypher, "ALTER", "PROMOTION POLICY") {
		if startsWithMatch || findKeywordIndex(cypher, "SET") == 0 {
			return e.executeRequiredPipeline(ctx, cypher)
		}
	}

	if containsKeywordOutsideStrings(cypher, "REMOVE") {
		return e.executeRequiredPipeline(ctx, cypher)
	}

	if startsWithMatch && optionalMatchIdx > 0 {
		if outcome := e.executePipeline(ctx, cypher); outcome.terminal() {
			return outcome.result, outcome.err
		}
		// The pipeline is the one executor for MATCH … OPTIONAL MATCH: a
		// form it declines is rejected, not run by another handler (#898).
		return nil, unsupportedOptionalMatchShapeError(cypher)
	}

	switch {
	case isProcedurePrivilegeCommand(cypher):
		return e.executeProcedurePrivilegeCommand(ctx, cypher)
	case startsWithKeywordFold(strings.TrimSpace(cypher), "GRANT"), startsWithKeywordFold(strings.TrimSpace(cypher), "REVOKE"),
		startsWithKeywordFold(strings.TrimSpace(cypher), "DENY"):
		// Only procedure execution privileges are supported.
		return nil, unsupportedAdministrationCommandError(cypher)
	case isCreateProcedureCommand(cypher):
		return e.executeCreateProcedure(ctx, cypher)
	case startsWithKeywords(cypher, "CREATE", "DECAY PROFILE"),
		startsWithKeywords(cypher, "CREATE", "PROMOTION PROFILE"),
		startsWithKeywords(cypher, "CREATE", "PROMOTION POLICY"):
		return e.executeKnowledgePolicyDDL(ctx, cypher)
	case startsWithKeywords(cypher, "OPTIONAL", "MATCH"),
		startsWithKeywords(cypher, "OPTIONAL", "CALL"):
		return e.executeRequiredPipeline(ctx, cypher)
	case startsWithMatch:
		return e.executeRequiredPipeline(ctx, cypher)
	case startsWithKeywords(cypher, "CREATE", "CONSTRAINT"),
		startsWithKeywords(cypher, "CREATE", "RANGE INDEX"),
		startsWithKeywords(cypher, "CREATE", "FULLTEXT INDEX"),
		startsWithKeywords(cypher, "CREATE", "VECTOR INDEX"),
		startsWithKeywords(cypher, "CREATE", "TEXT INDEX"),
		startsWithKeywords(cypher, "CREATE", "POINT INDEX"),
		startsWithKeywords(cypher, "CREATE", "LOOKUP INDEX"),
		findKeywordIndex(cypher, "CREATE INDEX") == 0:
		return e.executeSchemaCommand(ctx, cypher)
	case startsWithKeywords(cypher, "CREATE", "COMPOSITE DATABASE"):
		return e.executeCreateCompositeDatabase(ctx, cypher)
	case isCreateOrReplaceDatabaseQuery(cypher):
		return e.executeCreateOrReplaceDatabase(ctx, cypher)
	case startsWithKeywords(cypher, "CREATE", "DATABASE"):
		return e.executeCreateDatabase(ctx, cypher)
	case startsWithKeywords(cypher, "CREATE", "ALIAS"):
		return e.executeCreateAlias(ctx, cypher)
	case startsWithCreate:
		return e.executeRequiredPipeline(ctx, cypher)
	case findKeywordIndex(cypher, "CALL") == 0:
		return e.executeCall(ctx, cypher)
	case findKeywordIndex(cypher, "RETURN") == 0:
		return e.executeReturn(ctx, cypher)
	case startsWithKeywords(cypher, "DROP", "COMPOSITE DATABASE"):
		return e.executeDropCompositeDatabase(ctx, cypher)
	case startsWithKeywords(cypher, "DROP", "DATABASE"):
		return e.executeDropDatabase(ctx, cypher)
	case startsWithKeywords(cypher, "DROP", "ALIAS"):
		return e.executeDropAlias(ctx, cypher)
	case startsWithKeywords(cypher, "DROP", "CONSTRAINT"):
		return e.executeSchemaCommand(ctx, cypher)
	case startsWithKeywords(cypher, "DROP", "DECAY PROFILE"),
		startsWithKeywords(cypher, "DROP", "PROMOTION PROFILE"),
		startsWithKeywords(cypher, "DROP", "PROMOTION POLICY"):
		return e.executeKnowledgePolicyDDL(ctx, cypher)
	case isDropProcedureCommand(cypher):
		return e.executeDropProcedure(ctx, cypher)
	case startsWithKeywords(cypher, "DROP", "INDEX"):
		return e.executeSchemaCommand(ctx, cypher)
	case isDropRoleCommand(cypher):
		return nil, localizedStatusError("Neo.ClientError.Statement.UnsupportedAdministrationCommand", "UnsupportedAdministrationCommand",
			localization.CypherAdminUnsupportedAdministrationCommand(strings.TrimSpace(cypher)))
	case findKeywordIndex(cypher, "DROP") == 0:
		return nil, newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "invalid DROP clause: "+truncateQuery(cypher, 80))
	case findKeywordIndex(cypher, "WITH") == 0:
		return e.executeRequiredPipeline(ctx, cypher)
	case findKeywordIndex(cypher, "UNWIND") == 0:
		return e.executeRequiredPipeline(ctx, cypher)
	case findKeywordIndex(cypher, "FOREACH") == 0:
		return e.executeRequiredPipeline(ctx, cypher)
	case findKeywordIndex(cypher, "LOAD CSV") == 0:
		return e.executeLoadCSV(ctx, cypher)
	case startsWithKeywords(cypher, "ALTER", "COMPOSITE DATABASE"):
		return e.executeAlterCompositeDatabase(ctx, cypher)
	case startsWithKeywords(cypher, "ALTER", "DECAY PROFILE"),
		startsWithKeywords(cypher, "ALTER", "PROMOTION PROFILE"),
		startsWithKeywords(cypher, "ALTER", "PROMOTION POLICY"):
		return e.executeKnowledgePolicyDDL(ctx, cypher)
	default:
		// Terminal chokepoint of the converged router: a statement that passed
		// syntax validation but matches no handler is rejected here — never a
		// silent success, alternate text executor, or re-dispatch. Neo4j
		// reports unrecognized statements as syntax errors, so the localized
		// message keeps its text while Bolt carries the proper status code.
		firstWord := strings.Split(upperQuery, " ")[0]
		err := localizedError(localization.CypherTransactionsQueryTypeUnsupported(firstWord), nil)
		return nil, &classifiedCypherError{
			cause:  err,
			code:   "Neo.ClientError.Statement.SyntaxError",
			detail: "UnexpectedSyntax",
		}
	}
}

func (e *StorageExecutor) executeRequiredPipeline(ctx context.Context, cypher string) (*ExecuteResult, error) {
	if outcome := e.executePipeline(ctx, cypher); outcome.terminal() {
		return outcome.result, outcome.err
	}
	return nil, newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "query could not be planned as a clause pipeline")
}

// executeReturn runs a statement that is only a RETURN (RETURN 1, RETURN
// DISTINCT $p AS x, RETURN count(*) AS c SKIP 1). The projection is the
// shared RETURN projection (pipelineApplyReturn) over one row holding the
// parameters and bound values, so DISTINCT, aggregation, ORDER BY, SKIP and
// LIMIT behave as after any other clause (#713).
func (e *StorageExecutor) executeReturn(ctx context.Context, cypher string) (*ExecuteResult, error) {
	// Parameters are row values ($name), not text: a substituted value would
	// read as a literal (RETURN $a / $b with a = 1.0, b = 0 would fold like
	// RETURN 1.0 / 0).
	params := getParamsFromContext(ctx)
	row := make(pipelineRow, len(e.fabricRecordBindings)+len(params))
	for name, value := range e.fabricRecordBindings {
		row[name] = value
	}
	bindParameterRow(ctx, row)
	// Bound child contexts (§6.2): UNION/CALL branches may reference values
	// that travel in the value scope; the innermost bindings shadow params.
	if bindings := valueBindingsFromContext(ctx); bindings != nil {
		for name, value := range bindings {
			row[name] = value
		}
	}

	returnIdx := findKeywordIndex(cypher, "RETURN")
	if returnIdx == -1 {
		return nil, localizedError(localization.CypherTransactionsReturnClauseNotFound(truncateQuery(cypher, 80)), nil)
	}

	body := strings.TrimSpace(cypher[returnIdx+len("RETURN"):])
	items := body
	if cut := firstTopLevelModifierIndex(items); cut >= 0 {
		items = strings.TrimSpace(items[:cut])
	}
	items, _ = cutDistinct(items)
	parts := splitTopLevelComma(items)
	for index, part := range parts {
		// Same alias parsing as every projection (parseProjectionExprAlias).
		part, _ = parseProjectionExprAlias(ctx, strings.TrimSpace(part))
		parts[index] = part
		if err := e.validateStaticBooleanOperands(ctx, part); err != nil {
			return nil, err
		}
		if err := e.validateRangeCalls(part, pipelineRow{}); err != nil {
			return nil, err
		}
		if err := e.validateRowSubscriptTypes(part, pipelineRow{}); err != nil {
			return nil, err
		}

		if variable := undefinedStandaloneMapValue(part); variable != "" {
			return nil, newSemanticError(
				"Neo.ClientError.Statement.SyntaxError",
				"UndefinedVariable",
				"variable is not defined: "+variable,
			)
		}
	}

	if result, ok := e.pipelineApplyReturn(ctx, []pipelineRow{row}, "RETURN "+body); ok {
		return result, nil
	}
	if failure := getExpressionFailure(ctx); failure != nil {
		return nil, failure
	}
	unparsed := body
	for _, part := range parts {
		if _, defined := e.evaluateRowExpressionWithContext(ctx, part, row); !defined {
			unparsed = part
			break
		}
	}
	return nil, unresolvedReturnItemError(ctx, unparsed)
}

// firstTopLevelModifierIndex is the position of a projection's first
// top-level ORDER BY, SKIP or LIMIT, or -1. The shared RETURN projection and
// standalone RETURN both use it.
func firstTopLevelModifierIndex(clause string) int {
	cut := -1
	for _, kw := range []string{"ORDER BY", "SKIP", "LIMIT"} {
		// The keyword scan is costly; most projections have no modifier.
		if !containsFold(clause, kw[:4]) {
			continue
		}
		if idx := topLevelKeywordIndex(clause, kw); idx >= 0 && (cut == -1 || idx < cut) {
			cut = idx
		}
	}
	return cut
}

// splitReturnExpressions splits RETURN expressions by comma while preserving
// nested parentheses, lists, and map literals.
func splitReturnExpressions(clause string) []string {
	return splitTopLevelComma(clause)
}

// validateSyntax performs syntax validation.
// When NORNICDB_PARSER=antlr, uses ANTLR for strict OpenCypher grammar validation.
// When NORNICDB_PARSER=nornic (default), uses fast inline validation.
// cypher25 is the statement's language version (its scope checks differ).
func (e *StorageExecutor) validateSyntax(ctx context.Context, cypher string, cypher25 bool) error {
	// A text the selected validator accepted passed every check below (it
	// is marked valid only then), so a repeated query skips them all (#823):
	// under NORNICDB_PARSER=antlr too, where every repeat was parsed again
	// (#911).
	validator := activeSyntaxValidator()
	if e.hasCachedValidSyntax(cypher, validator) {
		return nil
	}
	if err := validateUnicodeOperators(cypher); err != nil {
		return err
	}
	if err := validateUnicodeStringLiterals(cypher); err != nil {
		return err
	}
	if err := validateStaticMapKeys(cypher); err != nil {
		return err
	}
	if err := validateNumericLiterals(cypher); err != nil {
		return err
	}
	if err := validateArrowOperators(cypher); err != nil {
		return err
	}
	if err := validatePlaceholderOperands(cypher); err != nil {
		return err
	}
	if config.IsANTLRParser() {
		return e.validateSyntaxANTLR(ctx, cypher, cypher25)
	}
	return e.validateSyntaxNornic(cypher)
}

// validateSyntaxANTLR uses ANTLR for strict OpenCypher grammar validation.
// Provides detailed error messages with line/column information.
func (e *StorageExecutor) validateSyntaxANTLR(ctx context.Context, cypher string, cypher25 bool) error {
	if isNornicExtensionStatement(cypher) {
		if err := e.validateSyntaxNornic(cypher); err != nil {
			return err
		}
		e.markCachedValidSyntax(cypher, syntaxValidANTLR)
		return nil
	}
	parserError := antlr.ValidateContext(ctx, cypher)
	if err := ctx.Err(); err != nil {
		return err
	}
	if parserError == nil {
		e.markCachedValidSyntax(cypher, syntaxValidANTLR|syntaxGrammarAccepted)
		return nil
	}
	if err := e.validateSyntaxNornic(cypher); err != nil {
		return err
	}
	if err := e.validateMatchSemanticScopes(ctx, cypher, cypher25); err != nil {
		return err
	}
	if err := validateKnownFunctions(cypher); err != nil {
		return err
	}
	return syntaxAdmissionError(cypher, parserError)
}

// isNornicExtensionStatement reports whether cypher is a statement outside
// the ANTLR grammar, which the Nornic validator checks instead under
// NORNICDB_PARSER=antlr (#957): NornicDB's own knowledge-policy DDL,
// procedure DDL (CREATE [OR REPLACE] PROCEDURE, DROP PROCEDURE) and database
// limits (ALTER DATABASE … SET LIMIT, SHOW LIMITS), and the database options
// the grammar doesn't model yet (CREATE DATABASE … OPTIONS, ALTER DATABASE …
// SET / REMOVE OPTION, #937).
func isNornicExtensionStatement(cypher string) bool {
	// EXPLAIN / PROFILE of one is one too, so both parsers treat EXPLAIN
	// GRANT … as the default parser does.
	_, cypher = parseExecutionMode(cypher)
	cypher = strings.TrimSpace(cypher)
	return isKnowledgePolicyDDLStatement(cypher) || isCreateProcedureCommand(cypher) || isDropProcedureCommand(cypher) ||
		isPrivilegeAdministrationCommand(cypher) || isDropRoleCommand(cypher) ||
		startsWithKeywords(cypher, "SHOW", "LIMITS") ||
		(startsWithKeywords(cypher, "ALTER", "DATABASE") && (findKeywordIndex(cypher, "SET LIMIT") >= 0 ||
			findKeywordIndex(cypher, "SET OPTION") >= 0 || findKeywordIndex(cypher, "REMOVE OPTION") >= 0)) ||
		((startsWithKeywords(cypher, "CREATE", "DATABASE") || startsWithKeywords(cypher, "CREATE", "OR")) &&
			findKeywordIndex(cypher, "DATABASE") >= 0 && findKeywordIndex(cypher, "OPTIONS") >= 0)
}

// isDropRoleCommand reports DROP ROLE, which Neo4j parses and Neo4j
// Community refuses as an unsupported administration command; NornicDB
// does the same on both parsers. Roles are deleted through the HTTP role
// API, whose owner also updates the server's loaded role caches.
func isDropRoleCommand(cypher string) bool {
	return startsWithKeywords(cypher, "DROP", "ROLE")
}

// validateSyntaxNornic performs fast inline syntax validation.
func (e *StorageExecutor) validateSyntaxNornic(cypher string) error {
	if e.hasCachedValidSyntax(cypher, syntaxValidNornic) {
		return nil
	}
	// Grammar checks consume code from the same lexical expression reader as
	// projections. Comments cannot introduce operands, quotes or delimiters;
	// keep the original statement as the validation-cache key.
	original := cypher
	cypher = lexicalExpressionText(cypher)
	if containsNotInOperator(cypher) {
		return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			"Invalid input 'NOT': NOT IN is not a Cypher operator; write NOT x IN [list]")
	}
	if containsTrailingListComma(cypher) {
		return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			"Invalid input ']': expected an expression")
	}
	if singleNodePatternComprehension(cypher) {
		// [(n) | …]: a pattern comprehension needs a relationship, as the
		// ANTLR parser and Neo4j require ("Invalid input '|'").
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			localization.CypherCoreInvalidInputExpectedExpression("|"))
	}
	if hasAdjacentStringLiterals(cypher) {
		return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			"Invalid input: adjacent string literals require an operator between them")
	}
	if explainProfileConflict(cypher) {
		return executionModeConflictError()
	}
	if _, ok := trailingBareFinish(cypher); ok {
		// FINISH can't follow RETURN, as in Neo4j; every valid trailing
		// FINISH was stripped before validation.
		return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "RETURN can only be used at the end of the query")
	}
	if !hasValidStartKeyword(cypher) {
		// Neo4j reports an unrecognized statement as a syntax error; classify
		// the localized terminal so Bolt carries the proper status code.
		return &classifiedCypherError{
			cause:  localizedError(localization.CypherTransactionsSyntaxStartInvalid(), nil),
			code:   "Neo.ClientError.Statement.SyntaxError",
			detail: "UnexpectedSyntax",
		}
	}
	if err := validateLeadingNodePatternTransition(cypher); err != nil {
		return err
	}

	if isGraphQueryStatement(cypher) && hasAdjacentOperands(cypher) {
		return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "syntax error: an expression is followed by another expression without an operator")
	}

	parenCount := 0
	bracketCount := 0
	braceCount := 0

	for i := 0; i < len(cypher); i++ {
		c := cypher[i]
		if isCypherQuoteByte(c) {
			end, closed := scanCypherQuotedText(cypher, i, c)
			if !closed {
				return &classifiedCypherError{cause: localizedError(localization.CypherTransactionsSyntaxUnclosedQuote(), nil), code: "Neo.ClientError.Statement.SyntaxError", detail: "UnexpectedSyntax"}
			}
			i = end - 1
			continue
		}
		if c == '/' {
			if end := queryCommentEnd(cypher, i); end >= 0 {
				i = end - 1
				continue
			}
		}
		if c == '.' && i+1 < len(cypher) && cypher[i+1] == '.' && bracketCount == 0 {
			return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "syntax error: malformed expression")
		}
		if c == '.' && (i == 0 || cypher[i-1] != '.') && (i+1 == len(cypher) || cypher[i+1] != '.') {
			// A dot other than a range's (1..2) starts a property key (n.k,
			// n.`k`), a map projection's all-properties (.*) or a number's
			// digits: RETURN n. is Neo4j's "expected an identifier".
			if next := queryGapEnd(cypher, i+1); next == len(cypher) || (!isIdentByte(cypher[next]) || cypher[next] == '$') && !isCypherBacktickByte(cypher[next]) && cypher[next] != '*' {
				token := ""
				if next < len(cypher) {
					token = cypher[next : next+1]
				}
				return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
					localization.CypherCoreInvalidInputExpectedIdentifier(token))
			}
		}
		if c == '+' {
			next := skipSpaces(cypher, i+1)
			if next < len(cypher) && cypher[next] == '*' {
				return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "syntax error: malformed expression")
			}
		}

		switch c {
		case '(':
			parenCount++
		case ')':
			parenCount--
		case '[':
			bracketCount++
		case ']':
			bracketCount--
		case '{':
			braceCount++
		case '}':
			braceCount--
		}

		if parenCount < 0 || bracketCount < 0 || braceCount < 0 {
			return newSemanticError(
				"Neo.ClientError.Statement.SyntaxError",
				"UnexpectedSyntax",
				fmt.Sprintf("syntax error: unbalanced delimiter at position %d", i),
			)
		}
	}

	if parenCount != 0 {
		return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "syntax error: unbalanced parentheses")
	}
	if bracketCount != 0 {
		return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "syntax error: unbalanced square brackets")
	}
	if braceCount != 0 {
		return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "syntax error: unbalanced curly braces")
	}
	e.markCachedValidSyntax(original, syntaxValidNornic)
	return nil
}

// hasAdjacentOperands reports two operands with no operator between them,
// such as n.name 'x', (a =~ 'T.*')'T.*', 5 'x', [1] 'x' or n.a n.b, which
// Neo4j rejects as a syntax error in every expression (RETURN, WITH, WHERE,
// ORDER BY, SET, property maps). An operand ends with a string or number
// literal, ')' , ']' or a property access (x.name); the next token may not
// start another literal, $parameter or property access. A bare word followed
// by a literal is a variable next to an operand (n 'x') unless it is one of
// the keywords a literal may follow (literalLeadingKeywords); otherwise a bare
// word resets the check.
// It applies to graph queries only (isGraphQueryStatement): schema,
// administration and knowledge-policy statements have their own grammars,
// e.g. constraint contract blocks separate predicates by line breaks.
func hasAdjacentOperands(cypher string) bool {
	operandEnded := false
	for index := 0; index < len(cypher); {
		c := cypher[index]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			index++
		case isCypherStringQuoteByte(c):
			if operandEnded {
				return true
			}
			end, _ := scanCypherQuotedText(cypher, index, c)
			index = end
			operandEnded = true
		case isCypherBacktickByte(c):
			end, closed := scanCypherQuotedText(cypher, index, c)
			if !closed {
				return false
			}
			property := index > 0 && cypher[index-1] == '.'
			index = end
			operandEnded = property
		case c >= '0' && c <= '9':
			if operandEnded {
				return true
			}
			index++
			for index < len(cypher) && (isIdentByte(cypher[index]) ||
				(cypher[index] == '.' && index+1 < len(cypher) && cypher[index+1] >= '0' && cypher[index+1] <= '9')) {
				index++
			}
			operandEnded = true
		case c == '$':
			if operandEnded {
				return true
			}
			index++
			for index < len(cypher) && isIdentByte(cypher[index]) {
				index++
			}
			operandEnded = true
		case isIdentByte(c):
			start := index
			for index < len(cypher) && isIdentByte(cypher[index]) {
				index++
			}
			startsProperty := index < len(cypher) && cypher[index] == '.' &&
				(index+1 >= len(cypher) || cypher[index+1] != '.')
			if operandEnded && startsProperty {
				return true
			}
			property := start > 0 && cypher[start-1] == '.' && (start < 2 || cypher[start-2] != '.')
			if operandEnded && !property && !startsProperty && !isSyntaxBoundaryKeyword(cypher[start:index]) {
				return true
			}
			if !property && !startsProperty && bareWordBeforeLiteral(cypher, start, index) {
				return true
			}
			operandEnded = property
		case c == ')' || c == ']':
			index++
			operandEnded = true
		default:
			index++
			operandEnded = false
		}
	}
	return false
}

func isSyntaxBoundaryKeyword(word string) bool {
	if _, allowed := literalLeadingKeywords[upperASCII(word)]; allowed {
		return true
	}
	switch upperASCII(word) {
	case "AS", "END", "STARTS", "ENDS", "MATCH", "OPTIONAL", "CREATE", "MERGE", "SET", "REMOVE", "DETACH", "FOREACH", "CALL", "ON", "ORDER", "ASC", "DESC", "ASCENDING", "DESCENDING", "NULL", "ROWS", "ROW", "TRANSACTIONS", "TRANSACTION", "REPORT", "STATUS", "BREAK", "CONTINUE", "FAIL", "ERROR", "UNION", "FINISH", "USING", "INDEX", "JOIN", "SCAN", "LET", "FILTER", "FOR":
		return true
	}
	return false
}

// literalLeadingKeywords are the words a string / number literal or a
// $parameter may directly follow in a graph query (RETURN 'x', LIMIT 5,
// n.name CONTAINS 'x', STARTS WITH $p, CASE 'a' WHEN 'a' THEN 1 ELSE 2,
// ORDER BY 1, LOAD CSV FROM 'url' ... FIELDTERMINATOR ';', IN TRANSACTIONS
// OF 10 ROWS, USING PERIODIC COMMIT 500, SHORTEST 2, ...).
var literalLeadingKeywords = map[string]struct{}{
	"RETURN": {}, "WITH": {}, "WHERE": {}, "AND": {}, "OR": {}, "XOR": {}, "NOT": {},
	"IN": {}, "IS": {}, "CASE": {}, "WHEN": {}, "THEN": {}, "ELSE": {}, "CONTAINS": {},
	"SKIP": {}, "LIMIT": {}, "UNWIND": {}, "FROM": {}, "FIELDTERMINATOR": {}, "OF": {},
	"DISTINCT": {}, "BY": {}, "YIELD": {}, "SHORTEST": {}, "ANY": {}, "ALL": {},
	"COMMIT": {}, "USE": {}, "OFFSET": {}, "DELETE": {},
	// trim([LEADING | TRAILING | BOTH] 'x' FROM s)
	"BOTH": {}, "LEADING": {}, "TRAILING": {},
}

// bareWordBeforeLiteral reports whether the word cypher[start:end] (not a
// property name) is followed by a string or number literal and
// is not one of literalLeadingKeywords, i.e. a variable directly followed by
// another operand. A word followed by '(' (a function call) or ':' (a map key
// or label) is never such a variable.
func bareWordBeforeLiteral(cypher string, start, end int) bool {
	next := skipSpaces(cypher, end)
	if next == end || next >= len(cypher) {
		return false
	}
	switch c := cypher[next]; {
	case isCypherStringQuoteByte(c) || (c >= '0' && c <= '9'):
	case c == '$':
		// A $parameter after a node or relationship pattern's variable or
		// label is its property map ((n:Label $props), [r $props]);
		// elsewhere it is an operand after an operand (RETURN a $b) or a
		// parameter where a name must be (UNWIND [1] AS $x), Neo4j's
		// "Invalid input '$'".
		before := start
		for before > 0 && isASCIIWhitespace(cypher[before-1]) {
			before--
		}
		if before > 0 && strings.IndexByte("([:|&!", cypher[before-1]) >= 0 {
			return false
		}
	default:
		return false
	}
	if c := cypher[start]; c >= '0' && c <= '9' {
		return false
	}
	_, keyword := literalLeadingKeywords[upperASCII(cypher[start:end])]
	return !keyword
}

// isGraphQueryStatement reports whether a statement is a Cypher graph query:
// it starts (after EXPLAIN / PROFILE) with MATCH, OPTIONAL MATCH, WITH,
// RETURN, UNWIND, MERGE, CALL, FOREACH, LOAD CSV, UNION or USE, or with
// CREATE followed by a pattern ("CREATE (" or "CREATE p = "). CREATE INDEX /
// CONSTRAINT / DATABASE / USER and the other CREATE ... definitions are not.
func isGraphQueryStatement(cypher string) bool {
	query := strings.TrimSpace(cypher)
	for _, prefix := range []string{"EXPLAIN", "PROFILE"} {
		if matchKeywordAt(query, 0, prefix) {
			query = strings.TrimSpace(query[len(prefix):])
		}
	}
	for _, keyword := range []string{"MATCH", "OPTIONAL", "WITH", "RETURN", "UNWIND", "MERGE", "CALL", "FOREACH", "LOAD", "UNION", "USE"} {
		if matchKeywordAt(query, 0, keyword) {
			return true
		}
	}
	if !matchKeywordAt(query, 0, "CREATE") {
		return false
	}
	rest := strings.TrimSpace(query[len("CREATE"):])
	if strings.HasPrefix(rest, "(") {
		return true
	}
	name, next, ok := scanIdentifierToken(rest, 0)
	return ok && name != "" && strings.HasPrefix(strings.TrimSpace(rest[next:]), "=")
}

func validateLeadingNodePatternTransition(cypher string) error {
	query := strings.TrimSpace(cypher)
	keyword := ""
	if matchKeywordAt(query, 0, "MATCH") {
		keyword = "MATCH"
	} else if matchKeywordAt(query, 0, "CREATE") {
		keyword = "CREATE"
	} else {
		return nil
	}
	open := skipSpaces(query, len(keyword))
	if open >= len(query) || query[open] != '(' {
		return nil
	}
	if groupOpen, _, _, grouped := nextQuantifiedGroup(query, open); grouped && groupOpen == open {
		// A pattern may start with a quantified path pattern: ((x)-->(y))+.
		return nil
	}
	close := findMatchingParen(query, open)
	if close < 0 {
		return nil
	}
	remaining := strings.TrimSpace(query[close+1:])
	if remaining == "" || remaining[0] == ',' || remaining[0] == '-' || remaining[0] == '<' || remaining[0] == ';' {
		return nil
	}
	// A quantified path pattern follows its node directly: (a)((x)-->(y))+.
	if open, _, _, ok := nextQuantifiedGroup(remaining, 0); ok && open == 0 && keyword == "MATCH" {
		return nil
	}
	for _, allowed := range []string{"WHERE", "USING", "RETURN", "WITH", "MATCH", "OPTIONAL", "CREATE", "MERGE", "SET", "REMOVE", "DELETE", "UNWIND", "CALL", "FOREACH", "ORDER", "SKIP", "LIMIT", "UNION", "LET", "FILTER", "FOR"} {
		if matchKeywordAt(remaining, 0, allowed) {
			return nil
		}
	}
	if matchKeywordAt(remaining, 0, "DETACH") && matchKeywordAt(strings.TrimSpace(remaining[len("DETACH"):]), 0, "DELETE") {
		return nil
	}
	return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "syntax error: unexpected text after node pattern")
}

var validSyntaxStarts = [...]string{
	"MATCH", "CREATE", "MERGE", "DELETE", "DETACH", "CALL", "RETURN", "WITH",
	"UNWIND", "OPTIONAL", "DROP", "SHOW", "FOREACH", "LOAD", "EXPLAIN",
	"PROFILE", "ALTER", "USE", "BEGIN", "COMMIT", "ROLLBACK", "TERMINATE", "LET", "FILTER", "FOR",
}

func hasValidStartKeyword(cypher string) bool {
	for _, start := range validSyntaxStarts {
		if startsWithKeywordFold(cypher, start) {
			return true
		}
	}
	return isPrivilegeCommandShaped(cypher)
}

// ensureSyntaxValidationCache lazily installs the syntax-validation cache
// pointer using sync.Once so concurrent CALL { ... } subqueries (which fan
// out via executeCallTailParallel) cannot race on the pointer write. The
// underlying cache itself is already mutex-guarded; the race was on the
// initial pointer assignment.
func (e *StorageExecutor) ensureSyntaxValidationCache() *syntaxValidationCache {
	e.syntaxValidationOnce.Do(func() {
		if e.syntaxValidationCache == nil {
			e.syntaxValidationCache = newSyntaxValidationCache()
		}
	})
	return e.syntaxValidationCache
}

// ShareStatementCachesFrom gives a fresh executor the source executor's
// caches that depend only on the statement text: the syntax verdicts and
// the upper-cased text. Configure it before executing queries. Protocol
// transactions (Bolt and HTTP explicit transactions) build a new executor
// per transaction; without the shared verdicts every statement in such a
// transaction was validated again from scratch, which under
// NORNICDB_PARSER=antlr is a full grammar parse of the statement.
//
//	transactionExecutor := NewStorageExecutor(databaseStorage)
//	transactionExecutor.ShareStatementCachesFrom(databaseExecutor)
func (e *StorageExecutor) ShareStatementCachesFrom(source *StorageExecutor) {
	if source == nil || source == e {
		return
	}
	e.UseStatementCaches(source.StatementCaches())
	e.statementCacheScope = source.statementCacheScope
}

// The validators a statement text is cached as valid for: each marks only
// its own acceptance, so the Nornic validator, which also runs when the
// ANTLR parse fails, never marks a text the ANTLR grammar rejected.
const (
	syntaxValidNornic uint8 = 1 << iota
	syntaxValidANTLR
	// syntaxGrammarAccepted marks a text the ANTLR grammar itself accepted.
	// It is not a validator: syntaxValidANTLR also covers NornicDB's
	// extension statements, which the grammar rejects. The log redactor
	// reads it on both parsers (redactForLog).
	syntaxGrammarAccepted
)

// activeSyntaxValidator is the validator the configured parser selects.
func activeSyntaxValidator() uint8 {
	if config.IsANTLRParser() {
		return syntaxValidANTLR
	}
	return syntaxValidNornic
}

func (e *StorageExecutor) hasCachedValidSyntax(cypher string, validator uint8) bool {
	if cypher == "" {
		return false
	}
	accepted := e.cachedSyntaxVerdict(cypher)
	if accepted&validator != 0 {
		return true
	}
	// Redaction reuses only an exact-text grammar verdict. Canonical
	// literal variants remain valid only for the execution validators.
	validator &^= syntaxGrammarAccepted
	if validator == 0 {
		return false
	}
	// Parser acceptance is structural: literal values never change it, so
	// statements that differ only in literals share one cached verdict
	// through the canonical form (PR #1043 #6). The canonical form is only
	// computed on an exact-text miss.
	if canonical, normalized := normalizeLiteralText(cypher); normalized {
		accepted = e.cachedSyntaxVerdict(canonical)
	}
	return accepted&validator != 0
}

func (e *StorageExecutor) markCachedValidSyntax(cypher string, validator uint8) {
	if cypher == "" {
		return
	}
	scopes, cacheable := e.cacheDependencyScopes(cypher)
	if !cacheable {
		return
	}
	add := func(key string, verdict uint8) { e.addSyntaxCacheEntry(key, verdict, scopes) }
	add(cypher, validator)
	if structural := validator &^ syntaxGrammarAccepted; structural != 0 {
		if canonical, normalized := normalizeLiteralText(cypher); normalized {
			add(canonical, structural)
		}
	}
}

// unresolvedReturnItemError is the error of a RETURN item the row evaluator
// could not resolve: the failure it recorded (a division by zero, a runtime
// TypeError, ...), or a SyntaxError for the item. It records the error.
func unresolvedReturnItemError(ctx context.Context, item string) error {
	if failure := getExpressionFailure(ctx); failure != nil {
		return failure
	}
	err := newSemanticError(
		"Neo.ClientError.Statement.SyntaxError",
		"UnexpectedSyntax",
		"could not parse RETURN expression: "+item,
	)
	recordExpressionFailure(ctx, err)
	return err
}

// unsupportedOptionalMatchShapeError is the error for a MATCH … OPTIONAL MATCH
// statement the clause pipeline declines. It carries the router terminal's
// SyntaxError classification: an unhandled shape fails, it never falls back to
// another executor.
func unsupportedOptionalMatchShapeError(cypher string) error {
	return &classifiedCypherError{
		cause:  localizedError(localization.CypherMatchingOptionalMatchShapeUnsupported(truncateQuery(cypher, 80)), nil),
		code:   "Neo.ClientError.Statement.SyntaxError",
		detail: "UnexpectedSyntax",
	}
}

// executeShowStatement runs a SHOW (or TERMINATE TRANSACTIONS) command,
// handled false when cypher is none. It runs before the routes that send a
// statement to the clause pipeline by the clauses it contains: since Cypher 25
// a SHOW command's YIELD may be followed by any clause (CALL { … }, DELETE,
// SET, …), and the command still runs as a SHOW (#907).
func (e *StorageExecutor) executeShowStatement(ctx context.Context, cypher string) (*ExecuteResult, bool, error) {
	// Every statement passes here: one prefix test spares the others the
	// command checks below.
	if !hasPrefixFold(cypher, "SHOW") && !hasPrefixFold(cypher, "TERMINATE") {
		return nil, false, nil
	}
	// SHOW [kind] CONSTRAINTS (showConstraintKindOf).
	if _, isConstraints, err := showConstraintKindOf(cypher, cypherVersionFromContext(ctx) == "25"); isConstraints {
		if err != nil {
			return nil, true, err
		}
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowConstraints)
		return result, true, err
	}
	switch {
	case startsWithKeywords(cypher, "SHOW", "FULLTEXT INDEXES"),
		startsWithKeywords(cypher, "SHOW", "FULLTEXT INDEX"),
		startsWithKeywords(cypher, "SHOW", "RANGE INDEXES"),
		startsWithKeywords(cypher, "SHOW", "RANGE INDEX"),
		startsWithKeywords(cypher, "SHOW", "VECTOR INDEXES"),
		startsWithKeywords(cypher, "SHOW", "VECTOR INDEX"),
		startsWithKeywords(cypher, "SHOW", "LOOKUP INDEXES"),
		startsWithKeywords(cypher, "SHOW", "LOOKUP INDEX"):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowIndexes)
		return result, true, err
	case startsWithKeywords(cypher, "SHOW", "INDEXES"),
		startsWithKeywords(cypher, "SHOW", "INDEX"):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowIndexes)
		return result, true, err
	case startsWithKeywords(cypher, "SHOW", "DECAY PROFILES"),
		startsWithKeywords(cypher, "SHOW", "PROMOTION PROFILES"),
		startsWithKeywords(cypher, "SHOW", "PROMOTION POLICIES"):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeKnowledgePolicyDDL)
		return result, true, err
	case startsWithKeywords(cypher, "SHOW", "PROCEDURES"):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowProcedures)
		return result, true, err
	case findKeywordIndex(cypher, "SHOW FUNCTIONS") == 0:
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowFunctions)
		return result, true, err
	case startsWithKeywords(cypher, "SHOW", "COMPOSITE DATABASES"):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowCompositeDatabases)
		return result, true, err
	case startsWithKeywords(cypher, "SHOW", "CONSTITUENTS"):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowConstituents)
		return result, true, err
	case startsWithKeywords(cypher, "SHOW", "DEFAULT DATABASE"),
		startsWithKeywords(cypher, "SHOW", "HOME DATABASE"):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowDefaultDatabase)
		return result, true, err
	case startsWithKeywords(cypher, "SHOW", "USERS"),
		startsWithKeywords(cypher, "SHOW", "CURRENT USER"):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowUsers)
		return result, true, err
	case startsWithKeywords(cypher, "SHOW", "TRANSACTIONS"),
		startsWithKeywords(cypher, "SHOW", "TRANSACTION"):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowTransactions)
		return result, true, err
	case startsWithKeywords(cypher, "TERMINATE", "TRANSACTIONS"),
		startsWithKeywords(cypher, "TERMINATE", "TRANSACTION"):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeTerminateTransactions)
		return result, true, err
	case isShowPrivilegesCommand(cypher):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowPrivileges)
		return result, true, err
	case startsWithKeywords(cypher, "SHOW", "ROLES"),
		startsWithKeywords(cypher, "SHOW", "ROLE"),
		startsWithKeywords(cypher, "SHOW", "PRIVILEGES"),
		startsWithKeywords(cypher, "SHOW", "USER"),
		startsWithKeywords(cypher, "SHOW", "SERVERS"),
		startsWithKeywords(cypher, "SHOW", "SERVER"):
		return nil, true, unsupportedAdministrationCommandError(cypher)
	case startsWithKeywords(cypher, "SHOW", "DATABASES"):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowDatabases)
		return result, true, err
	case startsWithKeywords(cypher, "SHOW", "DATABASE"):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowDatabase)
		return result, true, err
	case startsWithKeywords(cypher, "SHOW", "ALIASES"):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowAliases)
		return result, true, err
	case startsWithKeywords(cypher, "SHOW", "SETTINGS"),
		startsWithKeywords(cypher, "SHOW", "SETTING"):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowSettings)
		return result, true, err
	case startsWithKeywords(cypher, "SHOW", "LIMITS"):
		result, err := e.executeShowWithTail(ctx, cypher, e.executeShowLimits)
		return result, true, err
	}
	return nil, false, nil
}

package cypher

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	math "github.com/orneryd/nornicdb/pkg/math/libm"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
	"github.com/orneryd/nornicdb/pkg/util"
)

// ===== CALL {} Subquery Support (Neo4j 4.0+) =====

// isCallSubquery detects if a query is a CALL {} subquery vs CALL procedure()
// CALL {} subqueries have "CALL" followed by optional whitespace and "{"
// CALL procedures have "CALL procedure.name()"
func isCallSubquery(ctx context.Context, cypher string) bool {
	// Use regex for flexible whitespace matching: CALL followed by optional whitespace and {
	return hasSubqueryPattern(ctx, cypher, callSubqueryRe)
}

// startsWithCallSubquery reports whether cypher begins with a CALL { } or
// CALL (vars) { } subquery clause (as opposed to a procedure CALL, or a
// subquery later in the statement).
func startsWithCallSubquery(ctx context.Context, cypher string) bool {
	return callSubqueryAt(ctx, strings.TrimSpace(cypher), 0)
}

func appendCorrelatedBinding(result *ExecuteResult, name string, value interface{}) *ExecuteResult {
	if result == nil || name == "" {
		return result
	}
	for _, column := range result.Columns {
		if strings.EqualFold(strings.TrimSpace(column), name) {
			return result
		}
	}
	result.Columns = append(result.Columns, name)
	for index := range result.Rows {
		result.Rows[index] = append(result.Rows[index], value)
	}
	return result
}

func (e *StorageExecutor) resolveCorrelatedImportValue(ctx context.Context, outerPart, seedVar, seedID, importVar string, cache map[string]map[string]interface{}) (interface{}, bool, error) {
	if cache != nil {
		if byVar, ok := cache[seedID]; ok {
			if val, exists := byVar[importVar]; exists {
				return val, true, nil
			}
		}
	}

	outerQuery := strings.TrimSpace(outerPart) + " RETURN " + seedVar + ", " + importVar
	outerResult, err := e.executeInternal(ctx, outerQuery, nil)
	if err != nil {
		return nil, false, localizedError(localization.CypherSubqueriesCorrelatedImportFailed(importVar, err), err)
	}

	seedCol := -1
	importCol := -1
	for i, c := range outerResult.Columns {
		if strings.EqualFold(strings.TrimSpace(c), seedVar) {
			seedCol = i
		}
		if strings.EqualFold(strings.TrimSpace(c), importVar) {
			importCol = i
		}
	}
	if seedCol == -1 || importCol == -1 {
		return nil, false, nil
	}

	for _, row := range outerResult.Rows {
		if seedCol >= len(row) {
			continue
		}
		if !rowMatchesSeedID(row[seedCol], seedID) {
			continue
		}
		var val interface{}
		if importCol < len(row) {
			val = row[importCol]
		}
		if cache != nil {
			byVar, ok := cache[seedID]
			if !ok {
				byVar = make(map[string]interface{}, 4)
				cache[seedID] = byVar
			}
			byVar[importVar] = val
		}
		return val, true, nil
	}
	// Fallback for OPTIONAL MATCH imports: resolve the imported variable using
	// a seed-scoped OPTIONAL MATCH query. This preserves correlated semantics for
	// patterns like:
	//   MATCH (o) ... OPTIONAL MATCH (o)-[:R]->(t:Label {...}) WITH o,t CALL { ... }
	// where `t` can be null/non-null per seed.
	if !strings.EqualFold(importVar, seedVar) {
		if optIdx := findMultiWordKeywordIndex(outerPart, "OPTIONAL", "MATCH"); optIdx >= 0 {
			optionalPart := strings.TrimSpace(outerPart[optIdx:])
			end := len(optionalPart)
			for _, kw := range []string{"WITH", "RETURN", "ORDER BY", "SKIP", "LIMIT"} {
				if idx := findKeywordIndex(optionalPart, kw); idx >= 0 && idx < end {
					end = idx
				}
			}
			optionalPart = strings.TrimSpace(optionalPart[:end])
			if strings.HasPrefix(upperASCII(optionalPart), "OPTIONAL MATCH") {
				requiredPart := optionalPart
				if len(requiredPart) >= len("OPTIONAL MATCH") {
					requiredPart = "MATCH" + requiredPart[len("OPTIONAL MATCH"):]
				}
				seedScoped := fmt.Sprintf("MATCH (%s) WHERE id(%s) = %s %s RETURN %s", seedVar, seedVar, quoteCypherStringLiteral(seedID), requiredPart, importVar)
				fallbackRes, fallbackErr := e.executeInternal(ctx, seedScoped, nil)
				if fallbackErr != nil {
					return nil, false, localizedError(localization.CypherSubqueriesOptionalImportFallbackFailed(importVar, fallbackErr), fallbackErr)
				}
				if fallbackRes != nil && len(fallbackRes.Rows) > 0 {
					importCol := -1
					for i, c := range fallbackRes.Columns {
						if strings.EqualFold(strings.TrimSpace(c), importVar) {
							importCol = i
							break
						}
					}
					if importCol < 0 && len(fallbackRes.Columns) == 1 {
						importCol = 0
					}
					if importCol >= 0 && importCol < len(fallbackRes.Rows[0]) {
						val := fallbackRes.Rows[0][importCol]
						if cache != nil {
							byVar, ok := cache[seedID]
							if !ok {
								byVar = make(map[string]interface{}, 4)
								cache[seedID] = byVar
							}
							byVar[importVar] = val
						}
						return val, true, nil
					}
				}
			}
		}
	}

	return nil, false, nil
}

func rowMatchesSeedID(value interface{}, seedID string) bool {
	switch v := value.(type) {
	case *storage.Node:
		return v != nil && string(v.ID) == seedID
	case storage.Node:
		return string(v.ID) == seedID
	case map[string]interface{}:
		for _, key := range []string{"_nodeId", "id", "_id", "elementId"} {
			if raw, ok := v[key]; ok {
				if s, ok := raw.(string); ok && s != "" {
					if s == seedID {
						return true
					}
					if last := strings.LastIndex(s, ":"); last >= 0 && last+1 < len(s) && s[last+1:] == seedID {
						return true
					}
				}
			}
		}
	case string:
		if v == seedID {
			return true
		}
		if last := strings.LastIndex(v, ":"); last >= 0 && last+1 < len(v) && v[last+1:] == seedID {
			return true
		}
	}
	return false
}

// isCallSubqueryPureReturn checks whether innerBody is a pure RETURN projection
// with no MATCH/CALL/UNWIND/write clauses. Precomputed once per branch to avoid
// repeated keyword scans on every seed row.
func isCallSubqueryPureReturn(innerBody string) bool {
	trimmed := strings.TrimSpace(innerBody)
	// Accept any valid RETURN clause start (space/newline/tab after RETURN),
	// not just a single-space prefix.
	if findKeywordIndex(trimmed, "RETURN") != 0 {
		return false
	}
	return findKeywordIndex(trimmed, "MATCH") < 0 &&
		findKeywordIndex(trimmed, "CALL") < 0 &&
		findKeywordIndex(trimmed, "UNWIND") < 0 &&
		findKeywordIndex(trimmed, "MERGE") < 0 &&
		findKeywordIndex(trimmed, "CREATE") < 0 &&
		findKeywordIndex(trimmed, "DELETE") < 0 &&
		findKeywordIndex(trimmed, "SET") < 0 &&
		findKeywordIndex(trimmed, "REMOVE") < 0 &&
		findKeywordIndex(trimmed, "WITH") < 0 &&
		findKeywordIndex(trimmed, "UNION") < 0
}

// seedNodesFromOuterMatch executes the outer MATCH/WHERE segment through the normal
// execution pipeline (instead of manual scan/filter) so index/hot-path optimizations
// apply before correlated CALL {} expansion.
func (e *StorageExecutor) seedNodesFromOuterMatch(ctx context.Context, outerPart, variable string) ([]*storage.Node, error) {
	variable = strings.TrimSpace(variable)
	if variable == "" {
		return nil, localizedError(localization.CypherSubqueriesCorrelatedVariableEmpty(), nil)
	}

	trimmedOuter := strings.TrimSpace(outerPart)
	hasOuterPipelineClauses := findKeywordIndex(trimmedOuter, "WITH") >= 0 ||
		findKeywordIndex(trimmedOuter, "RETURN") >= 0

	// Fast path for simple seeded MATCH queries without relationship patterns:
	//   MATCH (v[:Label] {props}) [WHERE ...]
	// including ID/property indexed WHERE predicates.
	if findKeywordIndex(trimmedOuter, "MATCH") == 0 &&
		!hasOuterPipelineClauses &&
		!containsRelationshipPattern(trimmedOuter) && patternMapsAreConstant(trimmedOuter) {
		matchBody := strings.TrimSpace(trimmedOuter[len("MATCH"):])
		whereClause := ""
		if whereIdx := findKeywordIndex(matchBody, "WHERE"); whereIdx >= 0 {
			whereClause = strings.TrimSpace(matchBody[whereIdx+len("WHERE"):])
			// Keep WHERE-only predicate text for fast-path parsing. Trailing clauses
			// (WITH/RETURN/ORDER/SKIP/LIMIT) belong to the outer pipeline and must not
			// be interpreted as part of the predicate expression.
			whereEnd := len(whereClause)
			for _, kw := range []string{"WITH", "RETURN", "ORDER BY", "SKIP", "LIMIT"} {
				if idx := findKeywordIndex(whereClause, kw); idx >= 0 && idx < whereEnd {
					whereEnd = idx
				}
			}
			whereClause = strings.TrimSpace(whereClause[:whereEnd])
			matchBody = strings.TrimSpace(matchBody[:whereIdx])
		}

		np, parseErr := readNodePattern(ctx, matchBody, patternPropertyKeys)
		if parseErr != nil {
			return nil, parseErr
		}
		if np.variable != "" && !isIdentifierReferenced(trimmedOuter, variable) {
			return nil, nil
		}
		if strings.EqualFold(strings.TrimSpace(np.variable), variable) {
			rowCtx, prepared, prepareErr := e.preparePatternRow(ctx, matchBody, nil)
			if prepareErr != nil {
				return nil, prepareErr
			}
			ctx, matchBody = rowCtx, prepared
			np, parseErr = e.parseNodePattern(ctx, matchBody)
			if parseErr != nil {
				return nil, parseErr
			}
			if whereClause != "" {
				// O(1) direct ID seek path for: MATCH (v) WHERE id(v)=...
				if nodes, ok, err := e.tryCollectNodesFromIDEquality(ctx, np, whereClause); ok || err != nil {
					return nodes, err
				}
				// O(k) batched ID seek path for: MATCH (v) WHERE id(v) IN $ids
				if params := getParamsFromContext(ctx); params != nil {
					if nodes, ok, err := e.tryCollectNodesFromIDIn(ctx, np, whereClause, params); ok || err != nil {
						return nodes, err
					}
				}
				// Indexed IN-list path for batched correlated lookups.
				if params := getParamsFromContext(ctx); params != nil {
					if nodes, ok, err := e.tryCollectNodesFromPropertyIndexIn(np, whereClause, params); ok || err != nil {
						return nodes, err
					}
				}
				// Indexed equality path.
				if nodes, ok, err := e.tryCollectNodesFromPropertyIndex(ctx, np, whereClause); ok || err != nil {
					return nodes, err
				}
			}

			// Label/property-only fast path.
			nodes, err := e.loadPatternNodes(ctx, np.labels, np.properties)
			if err != nil {
				return nil, err
			}
			if len(np.properties) == 0 {
				// If a non-indexable WHERE exists, defer to generic executor to preserve semantics.
				if whereClause == "" {
					return nodes, nil
				}
				seedQuery := "MATCH " + matchBody + " WHERE " + whereClause + " RETURN " + variable
				outerRes, err := e.executeInternal(ctx, seedQuery, nil)
				if err != nil {
					return nil, err
				}
				return e.extractSeedNodesFromResult(outerRes, variable)
			}
			filtered := make([]*storage.Node, 0, len(nodes))
			for _, n := range nodes {
				if n == nil {
					continue
				}
				if e.nodeMatchesProps(n, np.properties) {
					filtered = append(filtered, n)
				}
			}
			// Same rule: preserve non-indexable WHERE semantics through generic executor.
			if whereClause != "" {
				seedQuery := "MATCH " + matchBody + " WHERE " + whereClause + " RETURN " + variable
				outerRes, err := e.executeInternal(ctx, seedQuery, nil)
				if err != nil {
					return nil, err
				}
				return e.extractSeedNodesFromResult(outerRes, variable)
			}
			return filtered, nil
		}
	}

	seedQuery := trimmedOuter
	if topLevelKeywordIndex(seedQuery, "RETURN") < 0 {
		seedQuery += " RETURN " + variable
	}
	outerRes, err := e.executeInternal(ctx, seedQuery, nil)
	if err != nil {
		return nil, err
	}
	return e.extractSeedNodesFromResult(outerRes, variable)
}

func (e *StorageExecutor) extractSeedNodesFromResult(outerRes *ExecuteResult, variable string) ([]*storage.Node, error) {
	if outerRes == nil || len(outerRes.Rows) == 0 {
		return []*storage.Node{}, nil
	}

	colIdx := -1
	for i, col := range outerRes.Columns {
		if strings.EqualFold(strings.TrimSpace(col), variable) {
			colIdx = i
			break
		}
	}
	if colIdx < 0 {
		return nil, localizedError(localization.CypherSubqueriesOuterMatchProjectionMissing(variable), nil)
	}

	seedNodes := make([]*storage.Node, 0, len(outerRes.Rows))
	for _, row := range outerRes.Rows {
		if colIdx >= len(row) {
			continue
		}
		val := row[colIdx]
		switch v := val.(type) {
		case *storage.Node:
			if v != nil {
				seedNodes = append(seedNodes, v)
			}
		case map[string]interface{}:
			if n := e.seedNodeFromMap(v); n != nil {
				seedNodes = append(seedNodes, n)
			}
		case string:
			if n := e.seedNodeFromIDString(v); n != nil {
				seedNodes = append(seedNodes, n)
			}
		case []interface{}:
			// Defensive: some execution paths can wrap a single projected value.
			if len(v) == 1 {
				switch wrapped := v[0].(type) {
				case *storage.Node:
					if wrapped != nil {
						seedNodes = append(seedNodes, wrapped)
					}
				case map[string]interface{}:
					if n := e.seedNodeFromMap(wrapped); n != nil {
						seedNodes = append(seedNodes, n)
					}
				case string:
					if n := e.seedNodeFromIDString(wrapped); n != nil {
						seedNodes = append(seedNodes, n)
					}
				}
			}
		}
	}
	return seedNodes, nil
}

func (e *StorageExecutor) seedNodeFromMap(m map[string]interface{}) *storage.Node {
	for _, key := range []string{"_nodeId", "id", "_id", "elementId"} {
		if raw, ok := m[key]; ok {
			if id, ok := raw.(string); ok && id != "" {
				if n := e.seedNodeFromIDString(id); n != nil {
					return n
				}
			}
		}
	}
	return nil
}

func (e *StorageExecutor) seedNodeFromIDString(id string) *storage.Node {
	id = strings.TrimSpace(id)
	if id == "" {
		return nil
	}
	// Direct NodeID lookup first.
	if n, err := e.getQueryNode(e.storage, storage.NodeID(id)); err == nil && n != nil {
		return n
	}
	// Handle elementId-style values: "<prefix>:<db>:<id>" -> "<id>"
	if last := strings.LastIndex(id, ":"); last >= 0 && last+1 < len(id) {
		idTail := id[last+1:]
		if n, err := e.getQueryNode(e.storage, storage.NodeID(idTail)); err == nil && n != nil {
			return n
		}
	}
	return nil
}

// parseCallSubquery is the compatibility adapter for body/plan consumers. The
// shared grammar owns the body boundary and the complete transactional spec.
func (e *StorageExecutor) parseCallSubquery(ctx context.Context, cypher string) (body, afterCall string, inTransactions bool, batch *transactionBatchSpec) {
	call, err := readCallClause(ctx, cypher)
	if err != nil {
		return "", "", false, nil
	}
	body = call.Body
	if stripped, finishes := stripUnionBranchFinishes(ctx, body); finishes && strings.TrimSpace(stripped) != "" {
		body = stripped
	}
	return body, call.After, call.Batch != nil, call.Batch
}

// callSubqueryHasScopeClause reports whether a CALL subquery declares its
// imports with a scope clause (CALL () { … }, CALL (x, y) { … }, CALL (*)
// { … }). Its body's leading WITH is then an ordinary projection, never an
// import list (parseLeadingWithImports): CALL () { WITH 1 AS x FINISH } is a
// unit subquery whose body is just that WITH (#907).
func callSubqueryHasScopeClause(ctx context.Context, cypher string) bool {
	return readCallSubqueryScope(ctx, cypher).scoped
}

// parseCallSubqueryImportVariables is the legacy names-only view. Scope and
// result-schema consumers use StatementFacts, which preserves syntax errors.
func parseCallSubqueryImportVariables(ctx context.Context, cypher string) ([]string, error) {
	scope := readCallSubqueryScope(ctx, cypher)
	if scope.invalid {
		return nil, newSemanticError("Neo.ClientError.Statement.SyntaxError", "InvalidVariableImport", "CALL imports must contain only variable names")
	}
	return scope.names, nil
}

// prefixUnionBranches puts prefix before body, or before each branch of a
// UNION / UNION ALL body: every branch of a CALL subquery imports the same
// outer variables.
func prefixUnionBranches(ctx context.Context, prefix, body string) string {
	branches, unionAll, mixed, ok := parseTopLevelUnionBranches(ctx, body)
	if !ok || mixed || len(branches) < 2 {
		return prefix + " " + body
	}
	separator := " UNION "
	if unionAll {
		separator = " UNION ALL "
	}
	for i, branch := range branches {
		branches[i] = prefix + " " + branch
	}
	return strings.Join(branches, separator)
}

// callSeedIsFirstNode reports whether a MATCH … CALL { … } needs only the
// MATCH's first node from the outer row: the pattern is that one node pattern,
// and every variable the subquery imports (CALL (x, …) or a leading WITH x, …)
// is that node's variable.
func callSeedIsFirstNode(pattern, variable string, callImportVars []string, subqueryBody string) bool {
	pattern = strings.TrimSpace(pattern)
	if pattern == "" || pattern[0] != '(' || findMatchingDelimiter(pattern, 0, '(', ')') != len(pattern)-1 {
		return false
	}
	imports := callImportVars
	if withVars, _, hasWith, err := parseLeadingWithImports(subqueryBody); err == nil && hasWith {
		imports = append(append([]string(nil), imports...), withVars...)
	}
	for _, imported := range imports {
		if !strings.EqualFold(strings.TrimSpace(imported), variable) && strings.TrimSpace(imported) != "*" {
			return false
		}
	}
	return true
}

func importsVariable(vars []string, variable string) bool {
	for _, v := range vars {
		if strings.EqualFold(strings.TrimSpace(v), strings.TrimSpace(variable)) {
			return true
		}
	}
	return false
}

// makeSubqueryReadOnly converts a subquery with writes to a read-only version for row counting.
// This is used to determine how many batches we need before executing the actual writes.
// Returns empty string if conversion is not possible.
//
// The count query is the subquery's MATCH with RETURN 1: one row per matched
// row, the rows the batches page through. The subquery's own RETURN can't
// be kept, since it reads variables the dropped write clause binds
// (MATCH (s) CREATE (t) RETURN t.value).
func (e *StorageExecutor) makeSubqueryReadOnly(subquery string) string {
	matchIdx := findKeywordIndex(subquery, "MATCH")
	setIdx := findKeywordIndex(subquery, "SET")
	returnIdx := findKeywordIndex(subquery, "RETURN")

	// MATCH ... SET ... RETURN
	if matchIdx >= 0 && setIdx > matchIdx && returnIdx > setIdx {
		return strings.TrimSpace(subquery[matchIdx:setIdx]) + " RETURN 1"
	}

	// MATCH ... CREATE ... RETURN
	createIdx := findKeywordIndex(subquery, "CREATE")
	if matchIdx >= 0 && createIdx > matchIdx && returnIdx > createIdx {
		return strings.TrimSpace(subquery[matchIdx:createIdx]) + " RETURN 1"
	}

	// If we can't convert, return empty string (caller will use iterative batching)
	return ""
}

// addLimitSkipToSubquery adds LIMIT and SKIP clauses to a subquery for batching.
// For queries with MATCH followed by write operations (SET, CREATE, DELETE, MERGE),
// it adds LIMIT/SKIP after the MATCH clause to limit how many rows are processed.
// For other patterns, it adds LIMIT/SKIP before RETURN.
//
// This ensures that batching limits the number of matched rows processed, not just
// the number of returned rows.
func (e *StorageExecutor) addLimitSkipToSubquery(ctx context.Context, subquery string, limit, skip int) string {
	// Check for MATCH ... SET/CREATE/DELETE/MERGE ... RETURN pattern
	// For these, we want to add LIMIT/SKIP after MATCH to limit how many rows are processed
	matchIdx := findKeywordIndex(subquery, "MATCH")
	if matchIdx >= 0 {
		// Find the first operation after MATCH (SET, CREATE, DELETE, MERGE, or RETURN)
		remaining := subquery[matchIdx+5:] // Skip "MATCH"
		setIdx := findKeywordIndex(remaining, "SET")
		createIdx := findKeywordIndex(remaining, "CREATE")
		deleteIdx := findKeywordIndex(remaining, "DELETE")
		mergeIdx := findKeywordIndex(remaining, "MERGE")
		returnIdx := findKeywordIndex(remaining, "RETURN")

		// Find the earliest operation after MATCH
		firstOpIdx := -1
		var firstOpName string
		if setIdx >= 0 && (firstOpIdx == -1 || setIdx < firstOpIdx) {
			firstOpIdx = setIdx
			firstOpName = "SET"
		}
		if createIdx >= 0 && (firstOpIdx == -1 || createIdx < firstOpIdx) {
			firstOpIdx = createIdx
			firstOpName = "CREATE"
		}
		if deleteIdx >= 0 && (firstOpIdx == -1 || deleteIdx < firstOpIdx) {
			firstOpIdx = deleteIdx
			firstOpName = "DELETE"
		}
		if mergeIdx >= 0 && (firstOpIdx == -1 || mergeIdx < firstOpIdx) {
			firstOpIdx = mergeIdx
			firstOpName = "MERGE"
		}
		if returnIdx >= 0 && (firstOpIdx == -1 || returnIdx < firstOpIdx) {
			firstOpIdx = returnIdx
			firstOpName = "RETURN"
		}

		if firstOpIdx > 0 {
			// We need to find where the MATCH clause ends
			// The MATCH clause can include WHERE, so we need to find the end of the pattern
			matchEnd := matchIdx + 5 + firstOpIdx // End of MATCH pattern, start of first operation

			// Check if there's a WHERE clause between MATCH and the first operation
			whereIdx := findKeywordIndex(subquery[matchIdx+5:matchIdx+5+firstOpIdx], "WHERE")
			if whereIdx >= 0 {
				// Find end of WHERE clause (before first operation)
				whereEnd := findKeywordIndex(subquery[matchIdx+5+whereIdx:matchIdx+5+firstOpIdx], firstOpName)
				if whereEnd > 0 {
					matchEnd = matchIdx + 5 + whereIdx + 5 + whereEnd // After WHERE clause
				}
			}

			// Extract the MATCH part
			matchPart := strings.TrimSpace(subquery[:matchEnd])
			afterOp := subquery[matchEnd:]

			// Extract variable name from MATCH pattern (e.g., "MATCH (s:Source)" -> "s")
			varNames := e.extractVariableNamesFromPattern(ctx, matchPatternStructure(matchPart[5:])) // Skip "MATCH"
			varName := "n"                                                                           // Default fallback
			if len(varNames) > 0 {
				varName = varNames[0]
			}

			// Use WITH clause to apply LIMIT/SKIP (Cypher doesn't allow LIMIT directly after MATCH)
			// Format: MATCH ... WITH var SKIP n LIMIT m CREATE/SET...
			if skip > 0 {
				return matchPart + fmt.Sprintf(" WITH %s SKIP %d LIMIT %d ", varName, skip, limit) + afterOp
			}
			return matchPart + fmt.Sprintf(" WITH %s LIMIT %d ", varName, limit) + afterOp
		}
	}

	// Fallback: Add LIMIT/SKIP before RETURN (or at end if no RETURN)
	returnIdx := findKeywordIndex(subquery, "RETURN")
	if returnIdx == -1 {
		// No RETURN clause - append LIMIT/SKIP at the end
		if skip > 0 {
			return subquery + fmt.Sprintf(" SKIP %d LIMIT %d", skip, limit)
		}
		return subquery + fmt.Sprintf(" LIMIT %d", limit)
	}

	// Find where the RETURN clause starts in the original query
	returnPart := subquery[returnIdx:]

	// Check if LIMIT or SKIP already exists
	if strings.Contains(upperASCII(returnPart), "LIMIT") || strings.Contains(upperASCII(returnPart), "SKIP") {
		// LIMIT/SKIP already present - append (may cause issues but handles common cases)
		if skip > 0 {
			return subquery + fmt.Sprintf(" SKIP %d LIMIT %d", skip, limit)
		}
		return subquery + fmt.Sprintf(" LIMIT %d", limit)
	}

	// Insert SKIP and LIMIT before RETURN
	beforeReturn := strings.TrimSpace(subquery[:returnIdx])
	returnClause := subquery[returnIdx:]

	if skip > 0 {
		return beforeReturn + fmt.Sprintf(" SKIP %d LIMIT %d ", skip, limit) + returnClause
	}
	return beforeReturn + fmt.Sprintf(" LIMIT %d ", limit) + returnClause
}

func detectReferencedCallSubquerySeedColumns(seedResult *ExecuteResult, subqueryBody string) []string {
	if seedResult == nil || len(seedResult.Columns) == 0 {
		return nil
	}
	referenced := make([]string, 0, len(seedResult.Columns))
	for _, col := range seedResult.Columns {
		name := strings.TrimSpace(col)
		if name == "" {
			continue
		}
		if isIdentifierReferenced(subqueryBody, name) {
			referenced = append(referenced, name)
		}
	}
	return referenced
}

// withImportClauseKeywords are the clauses that can follow a subquery's
// importing WITH list (parseLeadingWithImports).
var withImportClauseKeywords = []string{"WHERE", "OPTIONAL MATCH", "MATCH", "UNWIND", "MERGE", "CREATE", "SET", "DETACH DELETE", "DELETE", "REMOVE", "CALL", "RETURN", "WITH"}

// leadingWithClause returns the leading WITH clause of text, which starts
// with WITH (its WHERE, ORDER BY, SKIP and LIMIT included), and whether a
// clause follows it. Unlike splitPipelineClauses it reads no further than
// the next clause, in one pass, and it takes texts with procedure calls
// (WITH p CALL db.x() …).
func leadingWithClause(text string) (clause string, followed bool) {
	depth := 0
	for index := len("WITH"); index < len(text); index++ {
		switch c := text[index]; cypherLexicalByte(c) {
		case cypherQuoteClass:
			index = skipCypherQuotedText(text, index, c) - 1
			continue
		case '(', '[', '{':
			depth++
			continue
		case ')', ']', '}':
			if depth > 0 {
				depth--
			}
			continue
		}
		if depth > 0 || !isIdentStartByte(text[index]) || isIdentByte(text[index-1]) {
			continue
		}
		end := index + 1
		for end < len(text) && isIdentByte(text[end]) {
			end++
		}
		previous := text[index-1]
		if previous != '.' && previous != '$' && previous != ':' && isLeadingWithFollower(text[index:end]) &&
			!(equalFoldASCII(text[index:end], "with") && isOperatorWith(text, index)) {
			return text[:index], true
		}
		index = end - 1
	}
	return text, false
}

// isLeadingWithFollower reports whether word starts a clause that can follow
// a leading WITH.
func isLeadingWithFollower(word string) bool {
	switch len(word) {
	case 3:
		return equalFoldASCII(word, "set") || equalFoldASCII(word, "use")
	case 4:
		return equalFoldASCII(word, "call") || equalFoldASCII(word, "with") || equalFoldASCII(word, "load")
	case 5:
		return equalFoldASCII(word, "match") || equalFoldASCII(word, "merge") || equalFoldASCII(word, "union")
	case 6:
		return equalFoldASCII(word, "unwind") || equalFoldASCII(word, "create") || equalFoldASCII(word, "insert") ||
			equalFoldASCII(word, "delete") || equalFoldASCII(word, "detach") || equalFoldASCII(word, "remove") ||
			equalFoldASCII(word, "return") || equalFoldASCII(word, "finish")
	case 7:
		return equalFoldASCII(word, "foreach")
	case 8:
		return equalFoldASCII(word, "optional") || equalFoldASCII(word, "nodetach")
	}
	return false
}

// wordBefore is the identifier that ends right before index (spaces
// skipped), "" when another character comes first.
func wordBefore(text string, index int) string {
	end := index
	for end > 0 && isASCIISpace(text[end-1]) {
		end--
	}
	start := end
	for start > 0 && isIdentByte(text[start-1]) {
		start--
	}
	return text[start:end]
}

// isPatternClauseKeyword reports whether word is a keyword a pattern
// follows: MATCH, CREATE, MERGE.
func isPatternClauseKeyword(word string) bool {
	return equalFoldASCII(word, "MATCH") || equalFoldASCII(word, "CREATE") || equalFoldASCII(word, "MERGE")
}

func previousNonSpace(text string, index int) byte {
	for index > 0 {
		index--
		if !isASCIISpace(text[index]) {
			return text[index]
		}
	}
	return 0
}

// nextNonSpace is the first non-space byte at or after index, 0 at the end.
func nextNonSpace(text string, index int) byte {
	for ; index < len(text); index++ {
		if !isASCIISpace(text[index]) {
			return text[index]
		}
	}
	return 0
}

func parseLeadingWithImports(subqueryBody string) (withVars []string, innerBody string, hasWith bool, err error) {
	trimmed := strings.TrimSpace(subqueryBody)
	if !hasPrefixFoldASCII(trimmed, "WITH ") {
		return nil, trimmed, false, nil
	}

	afterWith := strings.TrimSpace(trimmed[len("WITH "):])
	// The import list ends at the first clause keyword after it (one scan
	// for all of them); a keyword at the very start is part of the list.
	nextIdx := firstKeywordIndexFromDefault(afterWith, 0, withImportClauseKeywords...)
	if nextIdx == 0 {
		nextIdx = firstKeywordIndexFromDefault(afterWith, 1, withImportClauseKeywords...)
	}
	if nextIdx < 0 {
		nextIdx = len(afterWith)
	}

	if nextIdx == len(afterWith) {
		return nil, "", true, localizedError(localization.CypherSubqueriesWithQueryClauseRequired(), nil)
	}

	withExpr := strings.TrimSpace(afterWith[:nextIdx])
	innerBody = strings.TrimSpace(afterWith[nextIdx:])
	if nextIdx < len(afterWith) && findKeywordIndex(afterWith[nextIdx:], "WHERE") == 0 {
		// Preserve `WITH ... WHERE ...` as part of the inner body so correlated
		// branch semantics remain identical to openCypher behavior.
		innerBody = strings.TrimSpace("WITH " + withExpr + " " + afterWith[nextIdx:])
		if whereExpr, whereRest, ok := splitLeadingWhereNullGuard(innerBody); ok {
			innerBody = strings.TrimSpace("WITH " + withExpr + " WHERE " + whereExpr + " " + whereRest)
		}
	}
	if innerBody == "" {
		return nil, "", true, localizedError(localization.CypherSubqueriesWithBodyEmpty(), nil)
	}

	parts := splitReturnExpressions(withExpr)
	withVars = make([]string, 0, len(parts))
	for _, part := range parts {
		expr := strings.TrimSpace(part)
		if expr == "" {
			continue
		}

		upperExpr := upperASCII(expr)
		if asIdx := strings.Index(upperExpr, " AS "); asIdx >= 0 {
			alias := strings.TrimSpace(expr[asIdx+4:])
			if alias == "" {
				return nil, "", true, localizedError(localization.CypherSubqueriesWithImportExpressionInvalid(expr), nil)
			}
			withVars = append(withVars, alias)
			continue
		}

		withVars = append(withVars, expr)
	}

	if len(withVars) == 0 {
		return nil, "", true, localizedError(localization.CypherSubqueriesWithImportsRequired(), nil)
	}

	return withVars, innerBody, true, nil
}

// splitLeadingWhereNullGuard detects a leading correlated guard shape:
//
//	WITH <imports> WHERE <expr> <write/query-clause...>
//
// and returns (<expr>, <rest-after-where-expr>, true).
// It is intentionally conservative and only used by the correlated write branch
// fallback path in executeMatchWithCallSubquery.
func splitLeadingWhereNullGuard(query string) (whereExpr string, rest string, ok bool) {
	trimmed := strings.TrimSpace(query)
	var afterWhere string
	if strings.HasPrefix(upperASCII(trimmed), "WITH ") {
		afterWith := strings.TrimSpace(trimmed[len("WITH "):])
		whereIdx := findKeywordIndex(afterWith, "WHERE")
		if whereIdx <= 0 {
			return "", "", false
		}
		afterWhere = strings.TrimSpace(afterWith[whereIdx+len("WHERE"):])
	} else if strings.HasPrefix(upperASCII(trimmed), "WHERE ") {
		afterWhere = strings.TrimSpace(trimmed[len("WHERE "):])
	} else {
		return "", "", false
	}
	if afterWhere == "" {
		return "", "", false
	}

	nextIdx := len(afterWhere)
	clauseStarts := []int{
		findKeywordIndex(afterWhere, "SET"),
		findKeywordIndex(afterWhere, "CREATE"),
		findKeywordIndex(afterWhere, "MERGE"),
		findKeywordIndex(afterWhere, "DELETE"),
		findKeywordIndex(afterWhere, "REMOVE"),
		findKeywordIndex(afterWhere, "MATCH"),
		findMultiWordKeywordIndex(afterWhere, "OPTIONAL", "MATCH"),
		findKeywordIndex(afterWhere, "UNWIND"),
		findKeywordIndex(afterWhere, "CALL"),
		findKeywordIndex(afterWhere, "RETURN"),
		findKeywordIndex(afterWhere, "WITH"),
	}
	for _, idx := range clauseStarts {
		if idx > 0 && idx < nextIdx {
			nextIdx = idx
		}
	}
	if nextIdx == len(afterWhere) {
		return "", "", false
	}

	whereExpr = strings.TrimSpace(afterWhere[:nextIdx])
	rest = strings.TrimSpace(afterWhere[nextIdx:])
	if whereExpr == "" || rest == "" {
		return "", "", false
	}
	return whereExpr, rest, true
}

// evalWhereNullGuard evaluates narrow guard expressions used in correlated UNION
// write branches:
//
//	<var> IS NULL
//	<var> IS NOT NULL
//
// Returns (pass, handled). handled=false means expression is outside this narrow
// supported subset and caller should use the generic path.
func evalWhereNullGuard(whereExpr string, vars map[string]interface{}) (pass bool, handled bool) {
	expr := strings.TrimSpace(whereExpr)
	// Accept optional wrapping parentheses.
	for strings.HasPrefix(expr, "(") && strings.HasSuffix(expr, ")") {
		inner := strings.TrimSpace(expr[1 : len(expr)-1])
		if inner == expr {
			break
		}
		expr = inner
	}

	// Case-insensitive single-variable null checks only.
	// Examples:
	//   t IS NULL
	//   t IS NOT NULL
	m := variableNullCheckPattern.FindStringSubmatch(expr)
	if len(m) != 3 {
		return false, false
	}

	varName := m[1]
	_, exists := vars[varName]
	isNull := !exists || vars[varName] == nil
	isNot := strings.TrimSpace(upperASCII(m[2])) == "NOT"
	if isNot {
		return !isNull, true
	}
	return isNull, true
}

// parseTopLevelUnionBranches preserves whether a composition mixes UNION and
// UNION ALL so callers can report the Cypher semantic error rather than
// treating the statement as an unsplittable query.
func parseTopLevelUnionBranches(ctx context.Context, query string) (branches []string, unionAllMode, mixed, ok bool) {
	body := readQueryBody(ctx, query, 0, len(query))
	if body.status == queryBodyDeclined || len(body.branches) < 2 {
		return nil, false, false, false
	}
	unionAllMode = true
	for i, branch := range body.branches {
		branches = append(branches, query[branch.start:branch.end])
		if i > 0 && !branch.unionAll {
			unionAllMode = false
		}
	}
	return branches, unionAllMode, body.status == queryBodyMixedUnion, true
}
func (e *StorageExecutor) refreshCallSeedNodeValues(ctx context.Context, seedRow []interface{}, colMap map[string]int, importVars []string, stats *QueryStats) ([]interface{}, error) {
	if !queryStatsMayContainNodeMutation(stats) {
		return seedRow, nil
	}

	importedNodeIDs := make(map[storage.NodeID]struct{}, len(importVars))
	for _, variable := range importVars {
		index, ok := colMap[variable]
		if !ok || index < 0 || index >= len(seedRow) {
			continue
		}
		if node, ok := seedRow[index].(*storage.Node); ok && node != nil {
			importedNodeIDs[node.ID] = struct{}{}
		}
	}
	if len(importedNodeIDs) == 0 {
		return seedRow, nil
	}

	checkedIDs := make(map[storage.NodeID]struct{}, len(importedNodeIDs))
	updatedNodes := make(map[storage.NodeID]*storage.Node, len(importedNodeIDs))
	var refreshed []interface{}
	for index, value := range seedRow {
		node, ok := value.(*storage.Node)
		if !ok || node == nil {
			continue
		}
		if _, imported := importedNodeIDs[node.ID]; !imported {
			continue
		}
		if _, checked := checkedIDs[node.ID]; !checked {
			checkedIDs[node.ID] = struct{}{}
			current, err := e.refreshCallSeedNodeAfterWrite(ctx, node, stats)
			if err != nil {
				return nil, err
			}
			if current != nil {
				updatedNodes[node.ID] = current
			}
		}
		if current := updatedNodes[node.ID]; current != nil {
			if refreshed == nil {
				refreshed = append([]interface{}(nil), seedRow...)
			}
			refreshed[index] = current
		}
	}
	if refreshed == nil {
		return seedRow, nil
	}
	return refreshed, nil
}

func (e *StorageExecutor) refreshCallSeedNodeAfterWrite(ctx context.Context, node *storage.Node, stats *QueryStats) (*storage.Node, error) {
	if node == nil || !queryStatsMayContainNodeMutation(stats) {
		return node, nil
	}
	current, err := e.getQueryNode(e.getStorage(ctx), node.ID)
	if errors.Is(err, storage.ErrNotFound) {
		return node, nil
	}
	if err != nil {
		return nil, err
	}
	if current == nil {
		return node, nil
	}
	return current, nil
}

func queryStatsMayContainNodeMutation(stats *QueryStats) bool {
	return stats != nil && (stats.PropertiesSet > 0 || stats.LabelsAdded > 0 || stats.LabelsRemoved > 0)
}

func (e *StorageExecutor) tryExecuteCorrelatedBatchedLookup(
	ctx context.Context,
	seedResult *ExecuteResult,
	innerBody string,
	importVars []string,
	colMap map[string]int,
) (*ExecuteResult, bool, error) {
	if seedResult == nil || len(seedResult.Rows) == 0 || len(importVars) != 1 {
		return nil, false, nil
	}

	importCol := strings.TrimSpace(importVars[0])
	if importCol == "" {
		return nil, false, nil
	}
	importIdx, ok := colMap[importCol]
	if !ok {
		return nil, false, nil
	}

	trimmed := strings.TrimSpace(strings.TrimSuffix(strings.TrimSpace(innerBody), ";"))
	if findKeywordIndex(trimmed, "MATCH") != 0 || !containsFold(trimmed, "RETURN ") || callSubqueryQueryIsWrite(trimmed) {
		return nil, false, nil
	}
	if containsFold(trimmed, "OPTIONAL MATCH") {
		return nil, false, nil
	}

	returnIdx := indexTopLevelKeywordCallSubquery(trimmed, "RETURN")
	if returnIdx < 0 {
		return nil, false, nil
	}
	beforeReturn := strings.TrimSpace(trimmed[:returnIdx])
	returnPart := strings.TrimSpace(trimmed[returnIdx+len("RETURN"):])
	if beforeReturn == "" || returnPart == "" {
		return nil, false, nil
	}

	matchPart := beforeReturn
	wherePart := ""
	if whereIdx := indexTopLevelKeywordCallSubquery(beforeReturn, "WHERE"); whereIdx >= 0 {
		matchPart = strings.TrimSpace(beforeReturn[:whereIdx])
		wherePart = strings.TrimSpace(beforeReturn[whereIdx+len("WHERE"):])
	}
	if matchPart == "" || wherePart == "" {
		return nil, false, nil
	}

	matchVar, matchProp, otherWhere, ok := extractCallSubqueryCorrelationWhere(wherePart, importCol)
	if !ok || matchVar == "" || matchProp == "" {
		return nil, false, nil
	}
	if sanitized, ok := sanitizeCallSubqueryOtherWhere(otherWhere, importCol); ok {
		otherWhere = sanitized
	} else {
		return nil, false, nil
	}

	projection, modifiers := splitTopLevelResultModifiersCallSubquery(returnPart)
	projection = strings.TrimSpace(projection)
	if projection == "" {
		return nil, false, nil
	}

	// Collect unique lookup keys from seed rows.
	keys := make([]interface{}, 0, len(seedResult.Rows))
	seenKeys := make(map[string]struct{}, len(seedResult.Rows))
	for _, row := range seedResult.Rows {
		if importIdx < 0 || importIdx >= len(row) {
			continue
		}
		k := row[importIdx]
		ks := callSubqueryLookupKeyString(k)
		if _, exists := seenKeys[ks]; exists {
			continue
		}
		seenKeys[ks] = struct{}{}
		keys = append(keys, k)
	}
	if len(keys) == 0 {
		return &ExecuteResult{
			Columns: append([]string{}, seedResult.Columns...),
			Rows:    [][]interface{}{},
		}, true, nil
	}

	var rewritten strings.Builder
	rewritten.Grow(len(trimmed) + len(projection) + 128)
	rewritten.WriteString(matchPart)
	if strings.TrimSpace(otherWhere) != "" {
		rewritten.WriteString(" WHERE ")
		rewritten.WriteString(otherWhere)
		rewritten.WriteString(" AND ")
	} else {
		rewritten.WriteString(" WHERE ")
	}
	rewritten.WriteString(matchVar)
	rewritten.WriteString(".")
	rewritten.WriteString(matchProp)
	rewritten.WriteString(" IN $__call_subquery_lookup_keys")
	rewritten.WriteString(" RETURN ")
	rewritten.WriteString(matchVar)
	rewritten.WriteString(".")
	rewritten.WriteString(matchProp)
	rewritten.WriteString(" AS __call_subquery_lookup_key, ")
	rewritten.WriteString(projection)
	if strings.TrimSpace(modifiers) != "" {
		rewritten.WriteString(" ")
		rewritten.WriteString(strings.TrimSpace(modifiers))
	}

	params := map[string]interface{}{
		"__call_subquery_lookup_keys": keys,
	}
	innerRes, err := e.executeInternal(ctx, rewritten.String(), params)
	if err != nil {
		return nil, true, localizedError(localization.CypherSubqueriesBatchedLookupFailed(err), err)
	}

	if innerRes == nil {
		return &ExecuteResult{
			Columns: append([]string{}, seedResult.Columns...),
			Rows:    [][]interface{}{},
		}, true, nil
	}
	if len(innerRes.Columns) == 0 || !strings.EqualFold(strings.TrimSpace(innerRes.Columns[0]), "__call_subquery_lookup_key") {
		return nil, true, localizedError(localization.CypherSubqueriesBatchedLookupColumnsUnexpected(fmt.Sprint(innerRes.Columns)), nil)
	}

	// Keep only inner columns not already present in seed columns and not join-key column.
	innerKeepIdx := make([]int, 0, len(innerRes.Columns))
	innerKeepCols := make([]string, 0, len(innerRes.Columns))
	for i, col := range innerRes.Columns {
		if i == 0 {
			continue
		}
		if _, exists := colMap[col]; exists {
			continue
		}
		innerKeepIdx = append(innerKeepIdx, i)
		innerKeepCols = append(innerKeepCols, col)
	}

	grouped := make(map[string][][]interface{}, len(innerRes.Rows))
	for _, r := range innerRes.Rows {
		if len(r) == 0 {
			continue
		}
		k := callSubqueryLookupKeyString(r[0])
		vals := make([]interface{}, 0, len(innerKeepIdx))
		for _, idx := range innerKeepIdx {
			if idx >= 0 && idx < len(r) {
				vals = append(vals, r[idx])
			} else {
				vals = append(vals, nil)
			}
		}
		grouped[k] = append(grouped[k], vals)
	}

	combinedCols := append([]string{}, seedResult.Columns...)
	combinedCols = append(combinedCols, innerKeepCols...)
	combinedRows := make([][]interface{}, 0, len(seedResult.Rows))
	for _, seedRow := range seedResult.Rows {
		if importIdx < 0 || importIdx >= len(seedRow) {
			continue
		}
		matches := grouped[callSubqueryLookupKeyString(seedRow[importIdx])]
		if len(matches) == 0 {
			continue
		}
		for _, m := range matches {
			joined := append([]interface{}{}, seedRow...)
			joined = append(joined, m...)
			combinedRows = append(combinedRows, joined)
		}
	}

	return &ExecuteResult{
		Columns: combinedCols,
		Rows:    combinedRows,
	}, true, nil
}

func callSubqueryLookupKeyString(v interface{}) string {
	switch x := v.(type) {
	case nil:
		return "<nil>"
	case string:
		return "s:" + normalizeCallSubqueryLookupString(x)
	case []byte:
		return "s:" + normalizeCallSubqueryLookupString(string(x))
	case int:
		return fmt.Sprintf("i:%d", x)
	case int64:
		return fmt.Sprintf("i64:%d", x)
	case float64:
		return fmt.Sprintf("f:%g", x)
	case bool:
		if x {
			return "b:1"
		}
		return "b:0"
	default:
		return fmt.Sprintf("%T:%v", v, v)
	}
}

func normalizeCallSubqueryLookupString(s string) string {
	s = strings.TrimSpace(s)
	return strings.Trim(s, `"`)
}

func extractCallSubqueryCorrelationWhere(whereClause, importCol string) (matchVar, matchProp, otherWhere string, ok bool) {
	terms := splitTopLevelAndConjuncts(whereClause)
	if len(terms) == 0 {
		return "", "", "", false
	}
	correlationIdx := -1
	for i, term := range terms {
		lhs, rhs, isEq := splitTopLevelEqualityCallSubquery(term)
		if !isEq {
			continue
		}
		leftVar, leftProp, leftOK := parseCallSubqueryVarProp(lhs)
		rightVar, rightProp, rightOK := parseCallSubqueryVarProp(rhs)
		switch {
		case leftOK && isSimpleIdentifier(strings.TrimSpace(rhs)) && strings.EqualFold(strings.TrimSpace(rhs), importCol):
			matchVar, matchProp = leftVar, leftProp
			correlationIdx = i
		case rightOK && isSimpleIdentifier(strings.TrimSpace(lhs)) && strings.EqualFold(strings.TrimSpace(lhs), importCol):
			matchVar, matchProp = rightVar, rightProp
			correlationIdx = i
		}
		if correlationIdx >= 0 {
			break
		}
	}
	if correlationIdx < 0 || matchVar == "" || matchProp == "" {
		return "", "", "", false
	}
	remaining := make([]string, 0, len(terms)-1)
	for i, term := range terms {
		if i == correlationIdx {
			continue
		}
		t := strings.TrimSpace(term)
		if t != "" {
			remaining = append(remaining, t)
		}
	}
	return matchVar, matchProp, strings.Join(remaining, " AND "), true
}

func parseCallSubqueryVarProp(expr string) (string, string, bool) {
	expr = strings.TrimSpace(expr)
	dot := strings.Index(expr, ".")
	if dot <= 0 || dot >= len(expr)-1 {
		return "", "", false
	}
	v := strings.Trim(expr[:dot], "`")
	p := strings.Trim(expr[dot+1:], "`")
	if !isSimpleIdentifier(v) || !isSimpleIdentifier(p) {
		return "", "", false
	}
	return v, p, true
}

func sanitizeCallSubqueryOtherWhere(otherWhere string, importCol string) (string, bool) {
	if strings.TrimSpace(otherWhere) == "" {
		return "", true
	}
	terms := splitTopLevelAndConjuncts(otherWhere)
	if len(terms) == 0 {
		return "", true
	}
	kept := make([]string, 0, len(terms))
	for _, term := range terms {
		term = strings.TrimSpace(term)
		if term == "" {
			continue
		}
		if isCallSubqueryImportNotNullGuardTerm(term, importCol) {
			continue
		}
		if containsStandaloneIdentifier(term, importCol) {
			return "", false
		}
		kept = append(kept, term)
	}
	if len(kept) == 0 {
		return "", true
	}
	return strings.Join(kept, " AND "), true
}

func isCallSubqueryImportNotNullGuardTerm(term string, importCol string) bool {
	parts := strings.Fields(strings.TrimSpace(term))
	if len(parts) != 4 {
		return false
	}
	left := strings.TrimSpace(parts[0])
	left = strings.Trim(left, "`")
	if !strings.EqualFold(left, strings.TrimSpace(importCol)) {
		return false
	}
	return strings.EqualFold(parts[1], "IS") &&
		strings.EqualFold(parts[2], "NOT") &&
		strings.EqualFold(parts[3], "NULL")
}

func splitTopLevelEqualityCallSubquery(expr string) (lhs, rhs string, ok bool) {
	paren, bracket, brace := 0, 0, 0
	for i := 0; i < len(expr); i++ {
		if end, quoted := skipCypherLexicalToken(expr, i); quoted {
			i = end - 1
			continue
		}
		ch := expr[i]
		switch ch {
		case '(':
			paren++
			continue
		case ')':
			if paren > 0 {
				paren--
			}
			continue
		case '[':
			bracket++
			continue
		case ']':
			if bracket > 0 {
				bracket--
			}
			continue
		case '{':
			brace++
			continue
		case '}':
			if brace > 0 {
				brace--
			}
			continue
		}
		if paren != 0 || bracket != 0 || brace != 0 {
			continue
		}
		if ch == '=' {
			left := strings.TrimSpace(expr[:i])
			right := strings.TrimSpace(expr[i+1:])
			if left == "" || right == "" {
				return "", "", false
			}
			return left, right, true
		}
	}
	return "", "", false
}

func indexTopLevelKeywordCallSubquery(s string, keyword string) int {
	paren, bracket, brace := 0, 0, 0
	for i := 0; i < len(s); i++ {
		if end, quoted := skipCypherLexicalToken(s, i); quoted {
			i = end - 1
			continue
		}
		ch := s[i]
		switch ch {
		case '(':
			paren++
		case ')':
			if paren > 0 {
				paren--
			}
		case '[':
			bracket++
		case ']':
			if bracket > 0 {
				bracket--
			}
		case '{':
			brace++
		case '}':
			if brace > 0 {
				brace--
			}
		}
		if paren != 0 || bracket != 0 || brace != 0 {
			continue
		}
		if findKeywordIndex(s[i:], keyword) == 0 {
			return i
		}
	}
	return -1
}

func splitTopLevelResultModifiersCallSubquery(returnPart string) (projection string, modifiers string) {
	idx := indexTopLevelKeywordCallSubquery(returnPart, "ORDER BY")
	if idx < 0 {
		idx = indexTopLevelKeywordCallSubquery(returnPart, "SKIP")
	}
	if idx < 0 {
		idx = indexTopLevelKeywordCallSubquery(returnPart, "LIMIT")
	}
	if idx < 0 {
		return strings.TrimSpace(returnPart), ""
	}
	return strings.TrimSpace(returnPart[:idx]), strings.TrimSpace(returnPart[idx:])
}

func callSubqueryQueryIsWrite(query string) bool {
	// Single-pass: check each write keyword once with findKeywordIndex from position 0.
	// Previous implementation was O(n*m) — called findKeywordIndex from every byte offset.
	return findKeywordIndex(query, "CREATE") >= 0 ||
		findKeywordIndex(query, "MERGE") >= 0 ||
		findKeywordIndex(query, "DELETE") >= 0 ||
		findKeywordIndex(query, "SET") >= 0 ||
		findKeywordIndex(query, "REMOVE") >= 0
}

func isSimpleIdentifier(s string) bool {
	s = strings.TrimSpace(strings.Trim(s, "`"))
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if i == 0 {
			if !isIdentStartByte(ch) {
				return false
			}
			continue
		}
		if !isIdentByte(ch) {
			return false
		}
	}
	return true
}

func containsStandaloneIdentifier(expr, ident string) bool {
	ident = strings.TrimSpace(strings.Trim(ident, "`"))
	if ident == "" {
		return false
	}
	isWord := func(b byte) bool {
		return isIdentByte(b)
	}
	for i := 0; i < len(expr); i++ {
		if end, quoted := skipCypherLexicalToken(expr, i); quoted {
			i = end - 1
			continue
		}
		if i+len(ident) > len(expr) {
			break
		}
		if !strings.EqualFold(expr[i:i+len(ident)], ident) {
			continue
		}
		if i > 0 {
			prev := expr[i-1]
			if isWord(prev) || prev == '.' {
				continue
			}
		}
		if i+len(ident) < len(expr) {
			next := expr[i+len(ident)]
			if isWord(next) || next == '.' {
				continue
			}
		}
		return true
	}
	return false
}

func crossJoinCallResults(left, right *ExecuteResult) *ExecuteResult {
	if left == nil {
		return right
	}
	if right == nil {
		return left
	}

	colMap := make(map[string]struct{}, len(left.Columns))
	for _, col := range left.Columns {
		colMap[col] = struct{}{}
	}
	combinedCols := append([]string{}, left.Columns...)
	innerUniqueIdx := make([]int, 0, len(right.Columns))
	for i, col := range right.Columns {
		if _, exists := colMap[col]; !exists {
			combinedCols = append(combinedCols, col)
			innerUniqueIdx = append(innerUniqueIdx, i)
		}
	}

	rows := make([][]interface{}, 0, util.SafePreallocProduct(len(left.Rows), len(right.Rows)))
	for _, lrow := range left.Rows {
		for _, rrow := range right.Rows {
			joined := append([]interface{}{}, lrow...)
			for _, idx := range innerUniqueIdx {
				if idx >= 0 && idx < len(rrow) {
					joined = append(joined, rrow[idx])
				} else {
					joined = append(joined, nil)
				}
			}
			rows = append(rows, joined)
		}
	}

	return &ExecuteResult{Columns: combinedCols, Rows: rows}
}

// applyResultModifiers applies ORDER BY, LIMIT, SKIP to a result
func (e *StorageExecutor) applyResultModifiers(ctx context.Context, result *ExecuteResult, modifiers string) (*ExecuteResult, error) {
	skip := 0
	if value, ok := e.parseIntModifier(ctx, modifiers, "SKIP"); ok {
		skip = value
	}
	limit := -1
	if value, ok := e.parseIntModifier(ctx, modifiers, "LIMIT"); ok {
		limit = value
	}
	return e.applyCallResultOrderWindow(ctx, result, parseOrderByTerms(modifiers), skip, limit)
}

// applyOrderByToResult applies ORDER BY to a result set
func (e *StorageExecutor) applyOrderByToResult(result *ExecuteResult, orderByClause string) *ExecuteResult {
	terms := parseOrderByTerms(orderByClause)
	if len(terms) == 0 {
		terms = parseOrderByClause(orderByClause)
	}
	_, _ = e.applyCallResultOrderWindow(context.Background(), result, terms, 0, -1)
	return result
}

func (e *StorageExecutor) applyCallResultOrderWindow(ctx context.Context, result *ExecuteResult, terms []orderByTerm, skip, limit int) (*ExecuteResult, error) {
	rows := make([]pipelineRow, 0, len(result.Rows))
	for _, values := range result.Rows {
		row := make(pipelineRow, len(result.Columns))
		for index, column := range result.Columns {
			if index < len(values) {
				row[column] = values[index]
			} else {
				row[column] = nil
			}
		}
		for _, term := range terms {
			parts := strings.SplitN(term.column, ".", 2)
			if len(parts) != 2 {
				continue
			}
			if value, ok := row[parts[0]].(map[string]interface{}); ok {
				if _, nested := value["properties"].(map[string]interface{}); nested {
					row[term.column] = extractPropertyFromValue(value, parts[1])
				}
			}
		}
		rows = append(rows, row)
	}
	if !e.orderPipelineRows(ctx, rows, terms) {
		if err := getExpressionFailure(ctx); err != nil {
			return nil, err
		}
	}
	rows = applyPipelineWindow(rows, skip, limit)
	result.Rows = make([][]interface{}, 0, len(rows))
	for _, row := range rows {
		values := make([]interface{}, len(result.Columns))
		for index, column := range result.Columns {
			values[index] = row[column]
		}
		result.Rows = append(result.Rows, values)
	}
	return result, nil
}

type orderByTerm struct {
	column     string
	descending bool
}

// parseOrderByTerms parses the ORDER BY of a projection's modifiers. Keywords
// inside braces (COLLECT { … ORDER BY … }, map literals) belong to nested
// expressions, never to the projection (#652, #547).
func parseOrderByTerms(modifiers string) []orderByTerm {
	orderByIndex := topLevelKeywordIndex(modifiers, "ORDER BY")
	if orderByIndex < 0 {
		return nil
	}
	return parseOrderByClause(modifiers[keywordEndAt(modifiers, orderByIndex, "ORDER BY"):])
}

// parseOrderByClause parses the sort items that follow ORDER BY. The list ends
// at SKIP / LIMIT, and at the WHERE that may follow ORDER BY in a WITH clause
// (WITH n ORDER BY n.x WHERE n.y > 0): that WHERE filters the sorted rows and
// is not part of the last sort item. A word at the start is the first sort
// item, even one named like those keywords (ORDER BY skip{.a}).
func parseOrderByClause(clause string) []orderByTerm {
	clause = strings.TrimSpace(clause)
	end := len(clause)
	keywordAfterFirstItem := func(keyword string) int {
		index := topLevelKeywordIndex(clause, keyword)
		if index == 0 {
			opts := defaultKeywordScanOpts()
			opts.SkipBraces = true
			index = keywordIndexFrom(clause, keyword, len(keyword), opts)
		}
		return index
	}
	for _, keyword := range []string{"LIMIT", "SKIP"} {
		if index := keywordAfterFirstItem(keyword); index >= 0 && index < end {
			end = index
		}
	}
	if index := keywordAfterFirstItem("WHERE"); index >= 0 && index < end {
		end = index
	}
	clause = strings.TrimSpace(clause[:end])
	parts := splitTopLevelComma(clause)
	terms := make([]orderByTerm, 0, len(parts))
	for _, part := range parts {
		expression := strings.TrimSpace(part)
		fields := strings.Fields(expression)
		if len(fields) == 0 {
			continue
		}
		term := orderByTerm{column: expression}
		if len(fields) > 1 {
			direction := upperASCII(fields[len(fields)-1])
			switch direction {
			case "DESC", "DESCENDING":
				term.descending = true
				term.column = strings.TrimSpace(expression[:strings.LastIndex(expression, fields[len(fields)-1])])
			case "ASC", "ASCENDING":
				term.column = strings.TrimSpace(expression[:strings.LastIndex(expression, fields[len(fields)-1])])
			}
		}
		terms = append(terms, term)
	}
	return terms
}

// compareValuesForSort compares two values for sorting, returns -1, 0, or 1
// extractPropertyFromValue extracts a named property from a value that may be a node map.
func extractPropertyFromValue(val interface{}, propName string) interface{} {
	property, _ := rowPropertyValue(val, propName)
	return property
}

func compareValuesForSort(a, b interface{}) int {
	if a == nil && b == nil {
		return 0
	}
	if a == nil {
		if cypherValueKindOf(b) == valueKindNull {
			return 0
		}
		return 1
	}
	if b == nil {
		if cypherValueKindOf(a) == valueKindNull {
			return 0
		}
		return -1
	}
	if comparison, temporal := compareTemporalOrdering(a, b); temporal {
		return comparison
	}
	if comparison, points := comparePointOrdering(a, b); points {
		return comparison
	}

	aRank := cypherSortRank(a)
	bRank := cypherSortRank(b)
	if aRank != bRank {
		if aRank < bRank {
			return -1
		}
		return 1
	}
	if left, isDuration := asCypherDuration(a); isDuration {
		if right, bothDurations := asCypherDuration(b); bothDurations {
			return compareDurationOrdering(left, right)
		}
	}

	if aList, ok := cypherSortList(a); ok {
		bList, _ := cypherSortList(b)
		for index := 0; index < len(aList) && index < len(bList); index++ {
			if comparison := compareValuesForSort(aList[index], bList[index]); comparison != 0 {
				return comparison
			}
		}
		return compareOrderedInts(len(aList), len(bList))
	}
	if comparison, exact := compareCypherNumbersExactly(a, b); exact {
		return comparison
	}
	if aNumber, ok := strictNumericValue(a); ok {
		bNumber, _ := strictNumericValue(b)
		if math.IsNaN(aNumber) && math.IsNaN(bNumber) {
			return 0
		}
		if aNumber < bNumber {
			return -1
		}
		if aNumber > bNumber {
			return 1
		}
		// -0.0 orders before 0.0 (Neo4j orders floats as Java's
		// Double.compare does), so max picks 0.0 and min -0.0.
		if _, leftFloat := a.(float64); leftFloat && aNumber == 0 {
			if _, rightFloat := b.(float64); rightFloat && math.Signbit(aNumber) != math.Signbit(bNumber) {
				if math.Signbit(aNumber) {
					return -1
				}
				return 1
			}
		}
		return 0
	}
	switch left := a.(type) {
	case CypherVector:
		return compareVectors(left, b.(CypherVector))
	case CypherUUID:
		return compareUUIDs(left, b.(CypherUUID))
	case string:
		right := b.(string)
		if left < right {
			return -1
		}
		if left > right {
			return 1
		}
		return 0
	case bool:
		right := b.(bool)
		if left == right {
			return 0
		}
		if !left {
			return -1
		}
		return 1
	}

	if comparison, _, structured := compareCypherStructuredValues(a, b, compareSortableValues); structured {
		return comparison
	}
	sa := fmt.Sprintf("%v", a)
	sb := fmt.Sprintf("%v", b)
	if sa < sb {
		return -1
	} else if sa > sb {
		return 1
	}
	return 0
}

func compareOrderedInts(left, right int) int {
	if left < right {
		return -1
	}
	if left > right {
		return 1
	}
	return 0
}

func parseOrderByModifier(modifiers string) (column string, descending bool, ok bool) {
	terms := parseOrderByTerms(modifiers)
	if len(terms) == 0 {
		return "", false, false
	}
	return terms[0].column, terms[0].descending, terms[0].column != ""
}

// parseIntModifier returns the SKIP or LIMIT value in a RETURN/WITH modifier
// tail. A plain integer is read directly; anything else (1 + 1, $s + 1 after
// parameter substitution, toInteger('2')) is evaluated as a constant
// expression through evaluatePipelinePagination, the same evaluation WITH uses,
// so every route applies SKIP/LIMIT expressions instead of ignoring them.
// ok is false when the keyword is absent or the value is not a non-negative
// integer.
func (e *StorageExecutor) parseIntModifier(ctx context.Context, modifiers, keyword string) (value int, ok bool) {
	idx := topLevelKeywordIndex(modifiers, keyword)
	if idx == -1 {
		return 0, false
	}
	kwPart := strings.TrimSpace(modifiers[idx+len(keyword):])
	nextKw := len(kwPart)
	for _, otherKeyword := range []string{"LIMIT", "SKIP", "ORDER BY"} {
		if otherKeyword == keyword {
			continue
		}
		if kidx := topLevelKeywordIndex(kwPart, otherKeyword); kidx != -1 && kidx < nextKw {
			nextKw = kidx
		}
	}
	vs := strings.TrimSpace(kwPart[:nextKw])
	if v, err := strconv.Atoi(vs); err == nil {
		return v, true
	}
	if vs == "" {
		return 0, false
	}
	return e.evaluatePipelinePagination(ctx, vs, nil)
}

func findColumnIndexByName(cols []string, name string) int {
	for i, col := range cols {
		if col == name {
			return i
		}
	}
	return -1
}

type rowRefForOrder struct {
	row []interface{}
	idx int
}

func compareRowRefsForOrder(a, b rowRefForOrder, colIdx int, descending bool) int {
	var av, bv interface{}
	if colIdx >= 0 && colIdx < len(a.row) {
		av = a.row[colIdx]
	}
	if colIdx >= 0 && colIdx < len(b.row) {
		bv = b.row[colIdx]
	}
	cmp := compareValuesForSort(av, bv)
	if descending {
		cmp = -cmp
	}
	if cmp != 0 {
		return cmp
	}
	// Stable tie-breaker by original position.
	if a.idx < b.idx {
		return -1
	}
	if a.idx > b.idx {
		return 1
	}
	return 0
}

type topKRowsHeap struct {
	items      []rowRefForOrder
	colIdx     int
	descending bool
}

func (h topKRowsHeap) Len() int { return len(h.items) }
func (h topKRowsHeap) Less(i, j int) bool {
	// Keep worst row at heap top.
	return compareRowRefsForOrder(h.items[i], h.items[j], h.colIdx, h.descending) > 0
}
func (h topKRowsHeap) Swap(i, j int) { h.items[i], h.items[j] = h.items[j], h.items[i] }
func (h *topKRowsHeap) Push(x interface{}) {
	h.items = append(h.items, x.(rowRefForOrder))
}
func (h *topKRowsHeap) Pop() interface{} {
	n := len(h.items)
	it := h.items[n-1]
	h.items = h.items[:n-1]
	return it
}

func selectTopKRowsForOrder(rows [][]interface{}, colIdx int, descending bool, k int) [][]interface{} {
	if k <= 0 || len(rows) == 0 {
		return [][]interface{}{}
	}
	if k >= len(rows) {
		out := make([][]interface{}, len(rows))
		copy(out, rows)
		sort.SliceStable(out, func(i, j int) bool {
			ri := rowRefForOrder{row: out[i], idx: i}
			rj := rowRefForOrder{row: out[j], idx: j}
			return compareRowRefsForOrder(ri, rj, colIdx, descending) < 0
		})
		return out
	}

	h := &topKRowsHeap{
		items:      make([]rowRefForOrder, 0, k),
		colIdx:     colIdx,
		descending: descending,
	}
	for i, row := range rows {
		ref := rowRefForOrder{row: row, idx: i}
		if h.Len() < k {
			heap.Push(h, ref)
			continue
		}
		// Replace current worst when new row is better.
		if compareRowRefsForOrder(ref, h.items[0], colIdx, descending) < 0 {
			h.items[0] = ref
			heap.Fix(h, 0)
		}
	}

	selected := make([]rowRefForOrder, len(h.items))
	copy(selected, h.items)
	sort.SliceStable(selected, func(i, j int) bool {
		return compareRowRefsForOrder(selected[i], selected[j], colIdx, descending) < 0
	})

	out := make([][]interface{}, 0, len(selected))
	for _, it := range selected {
		out = append(out, it.row)
	}
	return out
}

// Patterns compiled once (#591).
var (
	// callPropertyAccessPattern is a variable.property reference in a CALL.
	callPropertyAccessPattern = regexp.MustCompile(`(\w+)\.(\w+)`)
	// variableNullCheckPattern is "variable IS [NOT] NULL".
	variableNullCheckPattern = regexp.MustCompile(`(?i)^([A-Za-z_][A-Za-z0-9_]*)\s+IS\s+(NOT\s+)?NULL$`)
)

// patternPartEnd is the admitted pattern window, before WHERE or MERGE ON.
func patternPartEnd(clause pipelineClause) int {
	end := len(clause.text)
	for _, keyword := range [...]string{"WHERE", "ON"} {
		if at := topLevelKeywordIndex(clause.text, keyword); at > 0 && at < end {
			end = at
		}
	}
	return end
}

// Package cypher implements EXPLAIN and PROFILE query execution modes.
//
// EXPLAIN shows the query execution plan without executing the query.
// PROFILE executes the query and shows the plan with runtime statistics.
//
// # ELI12 (Explain Like I'm 12)
//
// Imagine you're planning a trip. EXPLAIN is like looking at the map and saying
// "I'll take this road, then that highway" without actually driving.
// PROFILE is like actually driving the route and noting "that road took 10 minutes,
// the highway took 20 minutes, I passed 50 cars."
//
// # Neo4j Compatibility
//
// This implementation matches Neo4j's execution modes:
// - EXPLAIN: Returns plan without execution
// - PROFILE: Returns plan with actual execution statistics
package cypher

import (
	"context"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/orneryd/nornicdb/pkg/localization"
)

// ExecutionMode represents how a query should be executed
type ExecutionMode string

const (
	ModeNormal  ExecutionMode = "normal"
	ModeExplain ExecutionMode = "EXPLAIN"
	ModeProfile ExecutionMode = "PROFILE"
)

// PlanOperator represents a single operator in the execution plan
type PlanOperator struct {
	// Operator type (e.g., "NodeByLabelScan", "Filter", "Expand")
	OperatorType string `json:"operatorType"`

	// Human-readable description
	Description string `json:"description"`

	// Operator-specific arguments
	Arguments map[string]interface{} `json:"arguments,omitempty"`

	// Variables introduced by this operator
	Identifiers []string `json:"identifiers,omitempty"`

	// Child operators (execution flows bottom-up)
	Children []*PlanOperator `json:"children,omitempty"`

	// Cost estimation (for EXPLAIN and PROFILE)
	EstimatedRows int64 `json:"estimatedRows"`

	// Actual statistics (only for PROFILE)
	ActualRows int64         `json:"rows,omitempty"`
	DBHits     int64         `json:"dbHits,omitempty"`
	Time       time.Duration `json:"time,omitempty"`
}

// ExecutionPlan represents the complete query execution plan
type ExecutionPlan struct {
	// Root operator of the plan
	Root *PlanOperator `json:"root"`

	// Query being explained/profiled
	Query string `json:"query"`

	// Execution mode (EXPLAIN or PROFILE)
	Mode ExecutionMode `json:"mode"`

	// Total statistics (only for PROFILE)
	TotalDBHits int64         `json:"totalDbHits,omitempty"`
	TotalTime   time.Duration `json:"totalTime,omitempty"`
	TotalRows   int64         `json:"totalRows,omitempty"`
}

// parseExecutionMode extracts EXPLAIN or PROFILE prefix from a query
func parseExecutionMode(query string) (ExecutionMode, string) {
	mode, statement, _ := readExecutionModes(query, ModeNormal)
	return mode, statement
}

// executeExplain returns the execution plan without executing the query
func (e *StorageExecutor) executeExplain(ctx context.Context, query string) (*ExecuteResult, error) {
	query, err := executionModeStatement(ModeExplain, query)
	if err != nil {
		return nil, err
	}
	if endsInFinish(ctx, query) {
		query += " FINISH"
	}
	if err := validateQueryBodyComposition(ctx, query); err != nil {
		return nil, err
	}
	columns, err := e.StatementResultColumnsContext(ctx, query)
	if err != nil {
		return nil, err
	}
	if indexASCIIFold(query, "shortestpath") >= 0 {
		if err := e.validateMatchSemanticScopes(ctx, query, cypherVersionFromContext(ctx) == "25"); err != nil {
			return nil, err
		}
	}
	plan, err := e.buildExecutionPlan(query)
	if err != nil {
		return nil, localizedError(localization.CypherCoreExecutionPlanBuildFailed(err), err)
	}
	plan.Mode = ModeExplain
	result := &ExecuteResult{
		Columns: columns,
		Rows:    [][]interface{}{},
		Stats:   &QueryStats{},
	}
	return e.attachPlanMetadata(result, plan), nil
}

// executeProfile executes the query and returns the plan with statistics
func (e *StorageExecutor) executeProfile(ctx context.Context, query string) (*ExecuteResult, error) {
	query, err := executionModeStatement(ModeProfile, query)
	if err != nil {
		return nil, err
	}
	if endsInFinish(ctx, query) {
		query += " FINISH"
	}
	// Resolve participant signatures through the same owner as EXPLAIN and
	// planning. Incomplete metadata cannot authorize execution effects.
	columns, err := e.StatementResultColumnsContext(ctx, query)
	if err != nil {
		return nil, err
	}
	// Build the plan first
	plan, err := e.buildExecutionPlan(query)
	if err != nil {
		return nil, localizedError(localization.CypherCoreExecutionPlanBuildFailed(err), err)
	}
	plan.Mode = ModeProfile

	// PROFILE's inner execution must bypass the result cache on both read and
	// write: Neo4j profiles actual execution, and a result object shared with
	// the cache would otherwise be mutated by attachPlanMetadata below,
	// leaking plan metadata into ordinary cached reads of the same query.
	ctx = context.WithValue(ctx, profileExecutionKey{}, true)

	// Execute the actual query to collect statistics
	startTime := time.Now()
	result, execErr := e.executeRouted(ctx, query, nil)
	totalTime := time.Since(startTime)

	// A statement that fails fails its PROFILE too, as in Neo4j: the error
	// is the statement's, not a plan row describing it.
	if execErr != nil {
		return nil, execErr
	}

	// Update plan with actual statistics
	plan.TotalTime = totalTime
	if result != nil {
		plan.TotalRows = int64(len(result.Rows))
		e.updatePlanWithStats(plan.Root, result)
	}

	// Calculate total DB hits (estimate based on operations)
	plan.TotalDBHits = e.estimateDBHits(plan.Root)

	// TRC-16: emit per-operator spans with estimated/actual rows.
	emitOperatorSpans(ctx, plan.Root)

	if result == nil {
		result = &ExecuteResult{
			Columns: []string{},
			Rows:    [][]interface{}{},
			Stats:   &QueryStats{},
		}
	}
	if err := verifyResultColumns(result.Columns, columns); err != nil {
		return nil, err
	}

	return e.attachPlanMetadata(result, plan), nil
}

// buildExecutionPlan creates an execution plan for a query
func (e *StorageExecutor) buildExecutionPlan(query string) (*ExecutionPlan, error) {
	plan := &ExecutionPlan{
		Query: query,
		Mode:  ModeNormal,
	}

	// Analyze query and build operator tree
	root, err := e.analyzeQuery(query)
	if err != nil {
		return nil, err
	}
	plan.Root = root

	return plan, nil
}

// analyzeQuery analyzes a Cypher query and builds the operator tree
func (e *StorageExecutor) analyzeQuery(query string) (*PlanOperator, error) {
	// Build operators in query clause order (Neo4j-style plan chain).
	type plannedClause struct {
		idx int
		op  *PlanOperator
	}
	clauses := make([]plannedClause, 0, 12)

	add := func(idx int, op *PlanOperator) {
		if idx >= 0 && op != nil {
			clauses = append(clauses, plannedClause{idx: idx, op: op})
		}
	}

	if idx := findKeywordIndex(query, "MATCH"); idx >= 0 {
		add(idx, e.analyzeMatchClause(query))
	}
	if idx := findKeywordIndex(query, "CALL"); idx >= 0 {
		add(idx, e.analyzeCallClause(query))
	}
	if idx := findKeywordIndex(query, "WHERE"); idx >= 0 {
		add(idx, e.analyzeWhereClause(query))
	}
	if idx := findKeywordIndex(query, "WITH"); idx >= 0 {
		add(idx, &PlanOperator{
			OperatorType:  "Projection",
			Description:   "Project intermediate results",
			EstimatedRows: 100,
		})
	}
	if idx := findKeywordIndex(query, "CREATE"); idx >= 0 {
		add(idx, &PlanOperator{
			OperatorType:  "Create",
			Description:   "Create nodes and relationships",
			EstimatedRows: 1,
		})
	}
	if idx := findKeywordIndex(query, "MERGE"); idx >= 0 {
		add(idx, &PlanOperator{
			OperatorType:  "Merge",
			Description:   "Merge (create if not exists)",
			EstimatedRows: 1,
		})
	}
	if idx := findKeywordIndex(query, "SET"); idx >= 0 {
		add(idx, &PlanOperator{
			OperatorType:  "Set",
			Description:   "Set properties",
			EstimatedRows: 100,
		})
	}
	if idx := findKeywordIndex(query, "REMOVE"); idx >= 0 {
		add(idx, &PlanOperator{
			OperatorType:  "Remove",
			Description:   "Remove labels/properties",
			EstimatedRows: 100,
		})
	}
	if idx := findKeywordIndex(query, "DETACH DELETE"); idx >= 0 {
		add(idx, e.analyzeDeleteClause(query, true))
	} else if idx := findKeywordIndex(query, "DELETE"); idx >= 0 {
		add(idx, e.analyzeDeleteClause(query, false))
	}
	if idx := findKeywordIndex(query, "ORDER BY"); idx >= 0 {
		add(idx, &PlanOperator{
			OperatorType:  "Sort",
			Description:   "Sort results",
			EstimatedRows: 100,
		})
	}
	if idx := findKeywordIndex(query, "LIMIT"); idx >= 0 {
		add(idx, e.analyzeLimitSkip(query))
	} else if idx := findKeywordIndex(query, "SKIP"); idx >= 0 {
		add(idx, e.analyzeLimitSkip(query))
	}
	if idx := findKeywordIndex(query, "RETURN"); idx >= 0 {
		add(idx, e.analyzeReturnClause(query))
	}

	sort.SliceStable(clauses, func(i, j int) bool {
		return clauses[i].idx < clauses[j].idx
	})

	operators := make([]*PlanOperator, 0, len(clauses))
	for _, c := range clauses {
		operators = append(operators, c.op)
	}

	// Build the operator tree (chain operators bottom-up)
	if len(operators) == 0 {
		return &PlanOperator{
			OperatorType:  "EmptyResult",
			Description:   "No operations",
			EstimatedRows: 0,
		}, nil
	}

	// Chain operators: each operator is a child of the next
	for i := len(operators) - 1; i > 0; i-- {
		operators[i].Children = []*PlanOperator{operators[i-1]}
	}

	return operators[len(operators)-1], nil
}

// analyzeMatchClause analyzes a MATCH clause and returns appropriate operators
func (e *StorageExecutor) analyzeMatchClause(query string) *PlanOperator {
	upper := upperASCII(query)

	// Check for shortestPath
	if strings.Contains(upper, "SHORTESTPATH") {
		return &PlanOperator{
			OperatorType:  "ShortestPath",
			Description:   "Find shortest path using BFS",
			EstimatedRows: 1,
			Arguments: map[string]interface{}{
				"algorithm": "BFS",
			},
		}
	}

	// Check for variable-length path
	if containsVariableLengthPathPattern(query) {
		return &PlanOperator{
			OperatorType:  "VarLengthExpand",
			Description:   "Variable length path expansion",
			EstimatedRows: 100,
		}
	}

	// Check for relationship pattern
	if containsRelationshipPattern(query) {
		return &PlanOperator{
			OperatorType:  "Expand",
			Description:   "Expand relationships",
			EstimatedRows: 100,
			Children: []*PlanOperator{
				e.analyzeNodeScan(query),
			},
		}
	}

	// Simple node scan
	return e.analyzeNodeScan(query)
}

// analyzeNodeScan determines the type of node scan needed.
// When the storage schema is available, it checks for actual index existence
// and reports index usage or rejection reasons in the plan arguments.
func (e *StorageExecutor) analyzeNodeScan(query string) *PlanOperator {
	// Check for label in pattern (n:Label)
	if label, ok := extractFirstNodeLabelFromQuery(query); ok {

		// Check for property filter (n:Label {prop: value})
		if strings.Contains(query, "{") {
			args := map[string]interface{}{
				"label": label,
			}
			// Check actual index availability from schema.
			e.annotateIndexDiagnostics(args, label, query)

			return &PlanOperator{
				OperatorType:  "NodeIndexSeek",
				Description:   fmt.Sprintf("Index seek on :%s", label),
				EstimatedRows: 10,
				Arguments:     args,
				Identifiers:   []string{"n"},
			}
		}

		args := map[string]interface{}{
			"label": label,
		}
		e.annotateIndexDiagnostics(args, label, query)

		return &PlanOperator{
			OperatorType:  "NodeByLabelScan",
			Description:   fmt.Sprintf("Scan all :%s nodes", label),
			EstimatedRows: 1000,
			Arguments:     args,
			Identifiers:   []string{"n"},
		}
	}

	// No label - full scan
	return &PlanOperator{
		OperatorType:  "AllNodesScan",
		Description:   "Scan all nodes",
		EstimatedRows: 10000,
		Identifiers:   []string{"n"},
	}
}

// annotateIndexDiagnostics adds index usage/rejection diagnostics to the plan
// operator arguments. This makes tuning deterministic by exposing whether an
// index was available, which properties are indexed, and why it was rejected.
func (e *StorageExecutor) annotateIndexDiagnostics(args map[string]interface{}, label, query string) {
	schema := e.storage.GetSchema()
	if schema == nil {
		args["indexStatus"] = "no_schema"
		return
	}

	// Collect all indexes for this label.
	indexes := schema.GetIndexes()
	var labelIndexes []string
	for _, raw := range indexes {
		idx, ok := raw.(map[string]interface{})
		if !ok {
			continue
		}
		idxLabel, _ := idx["label"].(string)
		if strings.TrimSpace(idxLabel) != label {
			continue
		}
		prop := ""
		if p, ok := idx["property"].(string); ok {
			prop = p
		}
		if prop == "" {
			if props, ok := idx["properties"].([]string); ok && len(props) > 0 {
				prop = strings.Join(props, ",")
			}
		}
		idxType, _ := idx["type"].(string)
		labelIndexes = append(labelIndexes, fmt.Sprintf("%s(%s)", idxType, prop))
	}

	if len(labelIndexes) == 0 {
		args["indexStatus"] = "no_index_for_label"
		return
	}

	args["indexStatus"] = "available"
	args["availableIndexes"] = labelIndexes

	// Check WHERE clause for predicate shapes that prevent index use.
	upper := upperASCII(query)
	if strings.Contains(upper, "COALESCE(") {
		args["indexRejectionRisk"] = "function_wrapping (coalesce)"
	}
	if strings.Contains(upper, "TOLOWER(") || strings.Contains(upper, "TOUPPER(") {
		args["indexRejectionRisk"] = "function_wrapping (toLower/toUpper)"
	}
}

// analyzeWhereClause analyzes WHERE conditions
func (e *StorageExecutor) analyzeWhereClause(query string) *PlanOperator {
	// Extract WHERE clause
	whereIdx := findKeywordIndex(query, "WHERE")
	if whereIdx < 0 {
		return nil
	}

	// Find end of WHERE clause
	endIdx := len(query)
	for _, keyword := range []string{"RETURN", "ORDER", "LIMIT", "SKIP", "WITH", "CREATE", "SET", "REMOVE", "DETACH DELETE", "DELETE"} {
		if idx := findKeywordIndex(query[whereIdx:], keyword); idx > 0 {
			if whereIdx+idx < endIdx {
				endIdx = whereIdx + idx
			}
		}
	}

	whereClause := strings.TrimSpace(query[whereIdx+5 : endIdx])

	return &PlanOperator{
		OperatorType:  "Filter",
		Description:   fmt.Sprintf("Filter: %s", truncate(whereClause, 50)),
		EstimatedRows: 100,
		Arguments: map[string]interface{}{
			"predicate": whereClause,
		},
	}
}

func (e *StorageExecutor) analyzeDeleteClause(query string, detach bool) *PlanOperator {
	startKeyword := "DELETE"
	operator := "Delete"
	if detach {
		startKeyword = "DETACH DELETE"
		operator = "DetachDelete"
	}
	deleteIdx := findKeywordIndex(query, startKeyword)
	if deleteIdx < 0 {
		return &PlanOperator{
			OperatorType:  operator,
			Description:   "Delete matched entities",
			EstimatedRows: 100,
		}
	}

	endIdx := len(query)
	for _, keyword := range []string{"RETURN", "WITH", "ORDER BY", "LIMIT", "SKIP"} {
		if idx := findKeywordIndex(query[deleteIdx:], keyword); idx > 0 {
			candidate := deleteIdx + idx
			if candidate < endIdx {
				endIdx = candidate
			}
		}
	}

	deleteClause := strings.TrimSpace(query[deleteIdx:endIdx])
	strip := startKeyword + " "
	if strings.HasPrefix(upperASCII(deleteClause), strip) {
		deleteClause = strings.TrimSpace(deleteClause[len(strip):])
	}
	desc := "Delete matched entities"
	if deleteClause != "" {
		desc = fmt.Sprintf("%s %s", operator, truncate(deleteClause, 50))
	}

	return &PlanOperator{
		OperatorType:  operator,
		Description:   desc,
		EstimatedRows: 100,
		Arguments: map[string]interface{}{
			"details": deleteClause,
		},
	}
}

// analyzeReturnClause analyzes the RETURN clause
func (e *StorageExecutor) analyzeReturnClause(query string) *PlanOperator {
	returnIdx := findKeywordIndex(query, "RETURN")
	if returnIdx < 0 {
		return nil
	}

	// Extract RETURN items
	returnClause := query[returnIdx+6:]
	// Trim ORDER BY, LIMIT, etc.
	for _, keyword := range []string{"ORDER BY", "LIMIT", "SKIP"} {
		if idx := findKeywordIndex(returnClause, keyword); idx > 0 {
			returnClause = returnClause[:idx]
		}
	}
	returnClause = strings.TrimSpace(returnClause)

	// Check for aggregations
	hasAggregation := containsAggregateFunc(returnClause)

	if hasAggregation {
		return &PlanOperator{
			OperatorType:  "EagerAggregation",
			Description:   "Aggregate results",
			EstimatedRows: 1,
			Arguments: map[string]interface{}{
				"expressions": returnClause,
			},
		}
	}

	// Check for DISTINCT
	if _, distinct := cutDistinct(returnClause); distinct {
		return &PlanOperator{
			OperatorType:  "Distinct",
			Description:   "Remove duplicates",
			EstimatedRows: 100,
		}
	}

	return &PlanOperator{
		OperatorType:  "ProduceResults",
		Description:   "Return results",
		EstimatedRows: 100,
		Arguments: map[string]interface{}{
			"columns": returnClause,
		},
	}
}

func containsVariableLengthPathPattern(query string) bool {
	for i := 0; i < len(query); i++ {
		if query[i] != '[' {
			continue
		}
		inside, _, ok := extractBracketSection(query[i:])
		if !ok {
			continue
		}
		inner := strings.TrimSpace(inside)
		if !strings.HasPrefix(inner, "*") {
			continue
		}
		rangeExpr := strings.TrimSpace(inner[1:])
		if rangeExpr == "" {
			return true // [*]
		}
		dotIdx := strings.Index(rangeExpr, "..")
		if dotIdx < 0 {
			continue
		}
		left := strings.TrimSpace(rangeExpr[:dotIdx])
		right := strings.TrimSpace(rangeExpr[dotIdx+2:])
		if (left == "" || isAllDigits(left)) && (right == "" || isAllDigits(right)) {
			return true // [*1..3], [*..5], [*1..]
		}
	}
	return false
}

func extractFirstNodeLabelFromQuery(query string) (string, bool) {
	for i := 0; i < len(query); i++ {
		if query[i] != '(' {
			continue
		}
		inside, _, ok := extractParenSection(query[i:])
		if !ok {
			continue
		}
		if label, ok := extractLabelFromNodeSection(inside); ok {
			return label, true
		}
	}
	return "", false
}

func extractLabelFromNodeSection(inside string) (string, bool) {
	s := strings.TrimSpace(inside)
	if s == "" {
		return "", false
	}
	if strings.HasPrefix(s, ":") {
		label, _, ok := parseIdentifierToken(strings.TrimSpace(s[1:]))
		return label, ok
	}
	if varName, rest, ok := parseIdentifierToken(s); ok {
		_ = varName
		rest = strings.TrimSpace(rest)
		if strings.HasPrefix(rest, ":") {
			label, _, ok := parseIdentifierToken(strings.TrimSpace(rest[1:]))
			return label, ok
		}
	}
	return "", false
}

func isAllDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

// analyzeLimitSkip analyzes LIMIT and SKIP clauses
func (e *StorageExecutor) analyzeLimitSkip(query string) *PlanOperator {
	upper := upperASCII(query)

	op := &PlanOperator{
		OperatorType: "Limit",
		Arguments:    make(map[string]interface{}),
	}

	// Extract LIMIT value
	if limit := ExtractLimitString(query); limit != "" {
		op.Arguments["limit"] = limit
		op.Description = fmt.Sprintf("Limit to %s rows", limit)
	}

	// Extract SKIP value
	if skip := ExtractSkipString(query); skip != "" {
		op.Arguments["skip"] = skip
		if op.Description != "" {
			op.Description += fmt.Sprintf(", skip %s", skip)
		} else {
			op.Description = fmt.Sprintf("Skip %s rows", skip)
		}
	}

	// Estimate rows based on limit
	if _, ok := op.Arguments["limit"]; ok {
		op.EstimatedRows = 10 // Use limit as estimate
	} else if strings.Contains(upper, "SKIP") {
		op.EstimatedRows = 100
	}

	return op
}

// analyzeCallClause analyzes CALL procedure invocations
func (e *StorageExecutor) analyzeCallClause(query string) *PlanOperator {
	procName := "unknown"
	if callIdx := keywordIndexFrom(query, "CALL", 0, defaultKeywordScanOpts()); callIdx >= 0 {
		callEnd, ok := keywordSpanAt(query, callIdx, "CALL")
		if ok {
			rest := strings.TrimSpace(query[callEnd:])
			if name, _, ok := parseProcedureNameToken(rest); ok {
				procName = name
			}
		}
	}

	return &PlanOperator{
		OperatorType:  "ProcedureCall",
		Description:   fmt.Sprintf("Call %s", procName),
		EstimatedRows: 100,
		Arguments: map[string]interface{}{
			"procedure": procName,
		},
	}
}

func parseProcedureNameToken(s string) (string, string, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return "", "", false
	}
	start := 0
	for start < len(s) {
		_, rest, ok := parseIdentifierToken(s[start:])
		if !ok {
			return "", "", false
		}
		start = len(s) - len(rest)
		if strings.HasPrefix(rest, ".") {
			start++
			continue
		}
		return s[:start], rest, true
	}
	return "", "", false
}

// updatePlanWithStats updates plan operators with actual execution statistics
func (e *StorageExecutor) updatePlanWithStats(op *PlanOperator, result *ExecuteResult) {
	if op == nil {
		return
	}

	// Update actual rows for leaf operators
	op.ActualRows = int64(len(result.Rows))

	// Recursively update children
	for _, child := range op.Children {
		e.updatePlanWithStats(child, result)
	}
}

// estimateDBHits estimates database hits based on the plan
func (e *StorageExecutor) estimateDBHits(op *PlanOperator) int64 {
	if op == nil {
		return 0
	}

	var hits int64

	// Estimate based on operator type
	switch op.OperatorType {
	case "AllNodesScan":
		hits = op.EstimatedRows * 2 // Read node + properties
	case "NodeByLabelScan":
		hits = op.EstimatedRows * 2
	case "NodeIndexSeek":
		hits = op.EstimatedRows + 1 // Index lookup + node reads
	case "Expand":
		hits = op.EstimatedRows * 3 // Node + relationships + target nodes
	case "Filter":
		hits = op.EstimatedRows // Property access for filter
	case "ShortestPath":
		hits = op.EstimatedRows * 10 // BFS traversal hits
	default:
		hits = op.EstimatedRows
	}

	// Add child hits
	for _, child := range op.Children {
		hits += e.estimateDBHits(child)
	}

	op.DBHits = hits
	return hits
}

// planToResult converts an execution plan to an ExecuteResult
func (e *StorageExecutor) attachPlanMetadata(result *ExecuteResult, plan *ExecutionPlan) *ExecuteResult {
	// Add plan as metadata
	if result.Metadata == nil {
		result.Metadata = make(map[string]interface{})
	}
	result.Metadata["planString"] = formatPlan(plan)
	result.Metadata["plan"] = plan
	result.Metadata["planType"] = string(plan.Mode)

	return result
}

// Neo4jPlanMap renders the plan tree in the shape Neo4j puts in Bolt SUCCESS
// metadata and HTTP results: each node carries operatorType, identifiers,
// args (with EstimatedRows), and children; the profile form adds rows and
// dbHits. Bolt and HTTP both deliver this map so plans reach clients (#744).
func Neo4jPlanMap(plan *ExecutionPlan, profile bool) map[string]any {
	if plan == nil {
		return nil
	}
	return neo4jPlanOperatorMap(plan.Root, profile)
}

// profileExecutionKey marks PROFILE's inner execution so it neither serves nor
// populates the result cache (#744): a cached result object would otherwise be
// mutated by attachPlanMetadata and hand plan metadata to ordinary cached
// reads of the same query.
type profileExecutionKey struct{}

func profileExecutionBypassesCache(ctx context.Context) bool {
	bypass, _ := ctx.Value(profileExecutionKey{}).(bool)
	return bypass
}

func neo4jPlanOperatorMap(op *PlanOperator, profile bool) map[string]any {
	if op == nil {
		return nil
	}
	node := make(map[string]any, 4)
	node["operatorType"] = op.OperatorType
	if len(op.Identifiers) > 0 {
		node["identifiers"] = op.Identifiers
	}
	args := make(map[string]interface{}, len(op.Arguments)+1)
	for key, value := range op.Arguments {
		args[key] = value
	}
	if op.EstimatedRows > 0 {
		args["EstimatedRows"] = op.EstimatedRows
	}
	if len(args) > 0 {
		node["args"] = args
	}
	if len(op.Children) > 0 {
		children := make([]map[string]any, 0, len(op.Children))
		for _, child := range op.Children {
			if childMap := neo4jPlanOperatorMap(child, profile); childMap != nil {
				children = append(children, childMap)
			}
		}
		node["children"] = children
	}
	if profile {
		node["rows"] = op.ActualRows
		node["dbHits"] = op.DBHits
	}
	return node
}

// formatPlan formats the execution plan as a string (tree visualization)
func formatPlan(plan *ExecutionPlan) string {
	var sb strings.Builder

	sb.WriteString(fmt.Sprintf("+-%s-+\n", strings.Repeat("-", 60)))
	sb.WriteString(fmt.Sprintf("| %-60s |\n", fmt.Sprintf("%s %s", plan.Mode, "Query Plan")))
	sb.WriteString(fmt.Sprintf("+-%s-+\n", strings.Repeat("-", 60)))

	if plan.Mode == ModeProfile {
		sb.WriteString(fmt.Sprintf("| Total Time: %-47s |\n", plan.TotalTime.String()))
		sb.WriteString(fmt.Sprintf("| Total Rows: %-47d |\n", plan.TotalRows))
		sb.WriteString(fmt.Sprintf("| Total DB Hits: %-44d |\n", plan.TotalDBHits))
		sb.WriteString(fmt.Sprintf("+-%s-+\n", strings.Repeat("-", 60)))
	}

	formatOperator(&sb, plan.Root, 0, plan.Mode == ModeProfile)

	sb.WriteString(fmt.Sprintf("+-%s-+\n", strings.Repeat("-", 60)))

	return sb.String()
}

// formatOperator formats a single operator in the plan tree
func formatOperator(sb *strings.Builder, op *PlanOperator, depth int, showStats bool) {
	if op == nil {
		return
	}

	indent := strings.Repeat("  ", depth)
	prefix := "+-"
	if depth > 0 {
		prefix = "|" + indent + "+-"
	}

	// Operator line
	line := fmt.Sprintf("%s %s", prefix, op.OperatorType)
	if op.Description != "" && op.Description != op.OperatorType {
		line += fmt.Sprintf(" (%s)", truncate(op.Description, 40))
	}

	sb.WriteString(fmt.Sprintf("| %-60s |\n", line))

	// Statistics line for PROFILE mode
	if showStats {
		statsLine := fmt.Sprintf("%s|   Est: %d, Actual: %d, Hits: %d",
			indent, op.EstimatedRows, op.ActualRows, op.DBHits)
		sb.WriteString(fmt.Sprintf("| %-60s |\n", statsLine))
	} else {
		// Just show estimates for EXPLAIN
		statsLine := fmt.Sprintf("%s|   Estimated Rows: %d", indent, op.EstimatedRows)
		sb.WriteString(fmt.Sprintf("| %-60s |\n", statsLine))
	}

	// Format children
	for _, child := range op.Children {
		formatOperator(sb, child, depth+1, showStats)
	}
}

// truncate truncates a string to maxLen characters
func truncate(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	return s[:maxLen-3] + "..."
}

package cypher

import (
	"context"
	"maps"
	"reflect"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
)

// validateListOperands rejects, before any route executes the statement, a
// list position whose operand has a static type that is not a list, as
// Neo4j's compile-time type check does ("Type mismatch: expected List<T> but
// was Integer"). A list position is the operand after IN: the IN operator,
// all / any / none / single, list comprehensions, reduce and FOREACH. The
// operands checked are a whole literal (number, string, boolean, map) and a
// whole parameter bound to a non-null value that is not a list ("Type
// mismatch for parameter 'p': …"); `$p.list`, `$p[0]`, `'a' + x` and
// variables are expressions whose type is only known per row, where a value
// that isn't a list is a list of that one value (coerceToUnwindItems). Variables
// bound to a node, relationship or path are checked with their scope
// (graphListOperandTypeError).
func validateListOperands(ctx context.Context, cypher string, params map[string]interface{}) error {
	return forEachListOperand(cypher, func(start, in int) error {
		// FOREACH (x IN 5 | …) runs once with x = 5 in Neo4j, not a type error.
		if foreachDeclaration(cypher, in) || forIterationDeclaration(cypher, in) {
			return nil
		}
		end, typeName, parameter := staticListOperand(ctx, cypher, start, params)
		if typeName == "" || !wholeListOperand(cypher, end) {
			return nil
		}
		message := localization.CypherCoreListOperandTypeMismatch(typeName)
		if parameter != "" {
			message = localization.CypherCoreListParameterTypeMismatch(parameter, typeName)
		}
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidArgumentType", message)
	})
}

// forEachListOperand calls visit with the offset of each list-position
// operand in text (the operand after an IN keyword outside quotes) and the
// offset of that IN, stopping at the first error.
func forEachListOperand(text string, visit func(start, in int) error) error {
	for i := 0; i < len(text); i++ {
		if end, quoted := skipCypherLexicalToken(text, i); quoted {
			i = end - 1
			continue
		}
		if (text[i] != 'I' && text[i] != 'i') || i+1 >= len(text) || (text[i+1] != 'N' && text[i+1] != 'n') || (i > 0 && (isIdentByte(text[i-1]) || text[i-1] == ':' || text[i-1] == '.')) ||
			i+2 >= len(text) || isIdentByte(text[i+2]) {
			continue
		}
		if err := visit(queryGapEnd(text, i+2), i); err != nil {
			return err
		}
	}
	return nil
}

// wholeListOperand reports whether the operand ending at end is the whole
// list-position operand, not the start of a longer expression (n.list,
// n[0], x + y).
func wholeListOperand(text string, end int) bool {
	next := queryGapEnd(text, end)
	return next >= len(text) || strings.IndexByte(")],}|", text[next]) >= 0 || isIdentByte(text[next])
}

// graphListOperandTypeError is Neo4j's compile-time SyntaxError for a list
// position given a variable bound to a node, relationship or path ("Type
// mismatch: expected List<T> but was Node"), whatever the data: `1 IN n`,
// `[x IN p | …]`, `any(x IN r WHERE …)`, in projections, WHERE, SET values
// and subquery bodies. FOREACH (x IN n | …) is not a type error in Neo4j (it
// runs once). A list element declaration (`[n IN list | …]`) is not itself
// an operand and cannot change the type of a separate `IN n` operand.
func graphListOperandTypeError(text string, scope matchSemanticScope) error {
	return staticListOperandTypeError(text, staticTypeScope{kinds: scope})
}

func staticListOperandTypeError(text string, scope staticTypeScope) error {
	if len(scope.kinds) == 0 && len(scope.values) == 0 {
		return nil
	}
	return forEachListOperand(text, func(start, in int) error {
		end := start
		for end < len(text) && isIdentByte(text[end]) {
			end++
		}
		if end == start || !wholeListOperand(text, end) {
			return nil
		}
		name := text[start:end]
		typeName := scope.typeOf(name)
		if typeName == "" || mayBeListType(typeName) {
			return nil
		}
		if foreachDeclaration(text, in) || forIterationDeclaration(text, in) || localVariableShadowsAt(text, start, name) {
			return nil
		}
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidArgumentType", localization.CypherCoreListOperandTypeMismatch(typeName))
	})
}

// mayBeListType reports whether a static type is a list or names one among
// its choices (a property value's type may be a List<T>).
func mayBeListType(typeName string) bool {
	// The owner's admission: a null alternative fits too.
	return typeName != "" && !typedOperand(typeName).proved().excludes(isListTypeName)
}

// foreachDeclaration reports whether the IN at offset in is FOREACH's own
// (`FOREACH (x IN …`).
func foreachDeclaration(text string, in int) bool {
	if !containsFold(text[:in], "FOREACH") {
		return false
	}
	opts := defaultKeywordScanOpts()
	opts.SkipParens = false
	opts.SkipBrackets = false
	for from := 0; from < in; {
		start := keywordIndexFrom(text, "FOREACH", from, opts)
		if start < 0 || start >= in {
			return false
		}
		open := queryGapEnd(text, start+len("FOREACH"))
		if open < len(text) && text[open] == '(' {
			_, end, ok := scanIdentifierToken(text, queryGapEnd(text, open+1))
			if ok && queryGapEnd(text, end) == in {
				return true
			}
		}
		from = start + len("FOREACH")
	}
	return false
}

// forIterationDeclaration reports whether the IN at offset in is a FOR
// iteration clause's own (`FOR x IN …`). FOR iterates like UNWIND, coercing a
// non-list operand to a single item, so its operand is not a list type error.
func forIterationDeclaration(text string, in int) bool {
	if !containsFold(text[:in], "FOR") {
		return false
	}
	opts := defaultKeywordScanOpts()
	opts.SkipParens = false
	opts.SkipBrackets = false
	for from := 0; from < in; {
		start := keywordIndexFrom(text, "FOR", from, opts)
		if start < 0 || start >= in {
			return false
		}
		nameStart := queryGapEnd(text, start+len("FOR"))
		if nameStart < in {
			if _, nameEnd, ok := scanIdentifierToken(text, nameStart); ok && queryGapEnd(text, nameEnd) == in {
				return true
			}
		}
		from = start + len("FOR")
	}
	return false
}

// localBinding is an expression that binds variables of its own, closing at
// text[close]: a list comprehension [v IN list WHERE … | …], a named pattern
// comprehension [p = (a)-->(b) WHERE … | …], all / any / none / single /
// filter (v IN list WHERE …) and reduce / allReduce (acc = initial,
// v IN list | step[, predicate]). It declares count names, each at its
// declared offset, visible from scope (the WHERE or | after the list, the
// pattern after a path's =) to close.
type localBinding struct {
	close, scope, count int
	names               [2]string
	declared            [2]int
	// source is the text span that types each name: the list an element
	// iterates (element), reduce's initial value for its accumulator; a
	// named path (path) is a Path.
	source  [2][2]int
	element [2]bool
	path    [2]bool
}

func (binding *localBinding) declare(name string, at, sourceStart, sourceEnd int, element, path bool) {
	index := binding.count
	binding.names[index], binding.declared[index] = name, at
	binding.source[index], binding.element[index], binding.path[index] = [2]int{sourceStart, sourceEnd}, element, path
	binding.count++
}

// localBindingAt reads the local binding that opens at text[open] ('[' or
// the '(' of a binding function), if one does. It is the one reader of
// these declarations: the names an expression binds (expressionLocalBindings)
// and where each is in scope (localVariableShadowsAt) both come from it, so
// x IN[…], x /* … */ IN … and p = (…) read alike everywhere.
func localBindingAt(text string, open int) (localBinding, bool) {
	var binding localBinding
	list := text[open] == '[' // else the '(' of a call: callers pass only these
	function := ""
	if !list {
		if function = bindingFunctionBeforeParen(text, open); function == "" {
			return binding, false
		}
	}
	closing := func() int {
		closeBy := ')'
		if list {
			closeBy = ']'
		}
		if close := findMatchingDelimiter(text, open, rune(text[open]), closeBy); close >= 0 {
			return close
		}
		return len(text)
	}
	if isReduceFormFunction(function) {
		binding.close = closing()
		if binding.close == len(text) {
			return binding, false
		}
		form, ok := parseReduceForm(function, text[open+1:binding.close])
		if !ok {
			return binding, false
		}
		comma := open + 1 + findTopLevelOperator(text[open+1:binding.close], ",", false, true)
		binding.scope = localScopeStart(text, comma+1, binding.close, true, false)
		accumulator := queryGapEnd(text, open+1)
		equals := open + 1 + strings.IndexByte(text[open+1:comma], '=')
		binding.declare(form.accumulator, accumulator, equals+1, comma, false, false)
		_, element, list, _ := bindingDeclaration(text, comma+1)
		binding.declare(form.variable, element, list, binding.scope, true, false)
		return binding, true
	}
	if name, declaration, listStart, declared := bindingDeclaration(text, open+1); declared {
		binding.close = closing()
		binding.scope = localScopeStart(text, listStart, binding.close, list, true)
		binding.declare(name, declaration, listStart, binding.scope, true, false)
		return binding, true
	}
	if !list {
		return binding, false
	}
	// [p = (a)-->(b) …]: a named pattern comprehension.
	if name, declaration, pattern, named := namedPathDeclaration(text, open+1); named {
		binding.close = closing()
		binding.declare(name, declaration, 0, 0, false, true)
		binding.scope = pattern
		return binding, true
	}
	return binding, false
}

// namedPathDeclaration reads a path variable declared at text[from] before
// its pattern: p = (a)-->(b), `p p` = (a)-->(b). It returns the name,
// where it is written and where the pattern starts. It is the one reader of
// a named pattern comprehension's head, for localBindingAt,
// patternComprehensionHead and the quoted-variable classifier.
func namedPathDeclaration(text string, from int) (name string, at, pattern int, ok bool) {
	at = queryGapEnd(text, from)
	name, end, ok := scanIdentifierToken(text, at)
	if !ok {
		return "", 0, 0, false
	}
	next := queryGapEnd(text, end)
	if next+1 >= len(text) || text[next] != '=' || text[next+1] == '~' {
		return "", 0, 0, false
	}
	pattern = queryGapEnd(text, next+1)
	if pattern >= len(text) || text[pattern] != '(' {
		return "", 0, 0, false
	}
	return name, at, pattern, true
}

// bindingDeclaration reads the declaration that opens a binding's arguments
// at text[from]: a name, then IN (x IN l, x IN[1], x /* … */ IN l). It
// returns the name, where it is written and where the list after IN starts.
// It is the one reader of that declaration, for the scope reader
// (localBindingAt) and the evaluators (parseListComprehension,
// parseQuantifierArguments).
func bindingDeclaration(text string, from int) (name string, at, list int, ok bool) {
	at = queryGapEnd(text, from)
	name, end, ok := scanIdentifierToken(text, at)
	if !ok {
		return "", 0, 0, false
	}
	next := queryGapEnd(text, end)
	if next+2 > len(text) || !strings.EqualFold(text[next:next+2], "IN") || next+2 < len(text) && isIdentByte(text[next+2]) {
		return "", 0, 0, false
	}
	return name, at, next + 2, true
}

// localScopeStart is where a binding's names come into scope in
// text[from:close]: its first top-level | (pipe) or WHERE (where), or close
// when it has neither ([v IN l] binds v nowhere).
func localScopeStart(text string, from, close int, pipe, where bool) int {
	depth := 0
	for index := from; index < close; index++ {
		switch c := text[index]; cypherLexicalByte(c) {
		case cypherQuoteClass:
			index = skipCypherQuotedText(text, index, c) - 1
			continue
		case '/':
			if end := queryCommentEnd(text, index); end >= 0 {
				index = end - 1
				continue
			}
		case '(', '[', '{':
			depth++
		case ')', ']', '}':
			depth--
		case '|':
			if pipe && depth == 0 {
				return index
			}
		}
		if where && depth == 0 && index+5 <= close && strings.EqualFold(text[index:index+5], "WHERE") &&
			!isIdentByte(text[index-1]) && (index+5 == len(text) || !isIdentByte(text[index+5])) {
			return index
		}
	}
	return close
}

// localVariableShadowsAt reports whether name, read at offset operand of
// text, is a variable an enclosing expression binds itself rather than the
// clause's (localBindingAt): a list comprehension's element in its WHERE and
// projection ([n IN l WHERE 1 IN n | n[0]]), a named pattern comprehension's
// path ([p = (a)-->(b) | length(p)]), the element of all / any / none /
// single in its predicate (all(n IN l WHERE n[0])), and reduce's
// accumulator and element in its step (reduce(acc = [], n IN l | acc + n)).
// The list a binding iterates and reduce's initial value are read outside
// it: in 1 IN n, [n IN [1] | n] the first n is the clause's. A binding's own
// declaration (the n of n IN, the acc of acc =) is the local too. It is the
// one reader of these scopes for the code that reads raw text: the static
// checks (list operands, subscripts, dynamic labels, function arguments,
// property accesses, subquery patterns; withoutLocalVariables), the
// reference scanners and the writing of a row's values into an expression
// (localOccurrences).
func localVariableShadowsAt(text string, operand int, name string) bool {
	_, _, ok := localBindingOf(text, operand, name)
	return ok
}

// localBindingOf is the innermost local binding that binds name where it is
// read at offset operand of text (localVariableShadowsAt), and the index of
// name among its declarations. A '[' or '(' whose first declared name isn't
// name (and isn't a reduce, which declares two) is passed over without
// being read whole.
func localBindingOf(text string, operand int, name string) (localBinding, int, bool) {
	var found localBinding
	foundIndex, ok := 0, false
	for open := 0; open < operand; {
		if !localBindingStepReads(text[open]) {
			open++
			continue
		}
		next, binding, bound := localBindingStep(text, open, name)
		open = next
		for index := 0; bound && index < binding.count; index++ {
			if binding.names[index] == name && (binding.declared[index] == operand || binding.scope <= operand && operand < binding.close) {
				// A binding opening later inside this one is inner.
				found, foundIndex, ok = binding, index, true
			}
		}
	}
	return found, foundIndex, ok
}

// localBindingStepReads reports whether localBindingStep reads more of text
// than the byte c at its offset; the walks step over any other byte
// themselves.
func localBindingStepReads(c byte) bool {
	return isCypherQuoteByte(c) || c == '/' || c == '[' || c == '('
}

// localBindingStep is one step of the walk that finds the bindings of name
// (localBindingOf, localOccurrences.keeps): the binding that opens at
// text[open] when it may declare name, and the offset the walk goes on
// from (past a quoted name, string or comment). A '[' or '(' whose first
// declared name isn't name (and isn't a reduce, which declares two) is
// passed over without being read whole. It is called only at a byte
// localBindingStepReads reads.
func localBindingStep(text string, open int, name string) (int, localBinding, bool) {
	switch cypherLexicalByte(text[open]) {
	case cypherQuoteClass:
		return skipCypherQuotedText(text, open, text[open]), localBinding{}, false
	case '/':
		if end := queryCommentEnd(text, open); end >= 0 {
			return end, localBinding{}, false
		}
		return open + 1, localBinding{}, false
	}
	// text[open] is '[' or '(': the walks step over the bytes
	// localBindingStepReads doesn't read themselves.
	if declared, _, named := scanIdentifierToken(text, queryGapEnd(text, open+1)); !named || declared != name {
		if text[open] != '(' || !isReduceFormFunction(bindingFunctionBeforeParen(text, open)) {
			return open + 1, localBinding{}, false
		}
	}
	binding, bound := localBindingAt(text, open)
	return open + 1, binding, bound
}

// localBindingOperand is the static type of the local name read at offset
// at of text (localBindingOf): a named path is a Path; an element is its
// list's element (listElementOperand: an Integer of [1], a node of [y]
// for a node y); reduce's accumulator is typed from its initial value as the
// deriver types it (reduceAccumulatorOperand). The
// source is typed in the scope at its own position, with the locals
// around it typed first (withLocalTypes): in
// all(x IN [y] WHERE all(r IN [x] WHERE …)) [x] holds the outer local's
// node. It is unknown when that type isn't known.
func localBindingOperand(ctx context.Context, text string, at int, name string, scope staticTypeScope) staticOperand {
	binding, index, ok := localBindingOf(text, at, name)
	if !ok {
		return staticOperand{}
	}
	if binding.path[index] {
		return provenOperand("Path")
	}
	span := binding.source[index]
	if span[0] <= 0 || span[1] <= span[0] || span[1] > len(text) {
		return staticOperand{}
	}
	source := strings.TrimSpace(text[span[0]:span[1]])
	inner := withLocalTypes(ctx, scope, text, span[0])
	types := typeScopeOf(inner)
	if binding.element[index] {
		return listElementOperand(ctx, types, inner, source)
	}
	// The one other local is reduce's accumulator.
	return reduceAccumulatorOperand(projectedOperand(ctx, types, inner, source))
}

// localBindingKind is localBindingOperand's binding kind.
func localBindingKind(ctx context.Context, text string, at int, name string, scope staticTypeScope) matchBindingKind {
	return localBindingOperand(ctx, text, at, name, scope).bindingKind()
}

// withLocalTypes is scope with each name a local binds around offset at of
// text in place of the outer variable of that name, typed as that local
// (localBindingOperand): in all(r IN [1] WHERE EXISTS { (r)-->() }) the r
// a subquery's pattern reads is an Integer, not the clause's relationship.
// The scope goes through typeScope, the one type of every variable.
func withLocalTypes(ctx context.Context, scope staticTypeScope, text string, at int) staticTypeScope {
	return boundExpressionTypeView(ctx, scope, text, at)
}

// bindingFunctionBeforeParen is the name of the function whose arguments
// open at text[open] when it binds variables of its own (all / any / none /
// single / filter, reduce / allReduce), as written; "" for any other.
func bindingFunctionBeforeParen(text string, open int) string {
	end := open
	for end > 0 && isWhitespace(text[end-1]) {
		end--
	}
	start := end
	for start > 0 && isIdentByte(text[start-1]) {
		start--
	}
	if start == end || start > 0 && isIdentByte(text[start-1]) {
		return ""
	}
	switch strings.ToLower(text[start:end]) {
	case "any", "all", "none", "single", "filter", "reduce", "allreduce":
		return text[start:end]
	default:
		return ""
	}
}

// localBindingNames caches the names a text binds itself
// (expressionLocalBindings), by text, for localOccurrences.
var localBindingNames = newBoundedCache[string, map[string]struct{}](1024, boundedCacheStringShardIndex)

// localOccurrences reads, for writing a row's values into text, which
// occurrences of a name read a variable an enclosing expression binds itself
// (localVariableShadowsAt) and keep their text. It is a value the caller
// keeps on its stack: the names text binds are read once per text
// (localBindingNames), when first asked, and the occurrences of a name in
// one input are read in one walk (keeps), so a row predicate costs one cache
// lookup and no allocation. (Not every binding form has an IN: a named
// pattern comprehension [p = (a)-->(b) | p] declares with =.)
type localOccurrences struct {
	// text is read, never changed: the names it binds are cached by text
	// (localBindingNames), shared and never written to.
	text   string
	read   bool
	locals map[string]struct{}

	// The walk of input for name (keeps): it has read the bindings that
	// open before walked, and holds those of name a later occurrence can
	// still read (scopes, then more once scopes is full).
	input, name string
	bound       bool
	walked      int
	scopes      [8]localOccurrenceScope
	open        int
	more        []localOccurrenceScope
}

// localOccurrenceScope is where one binding's local is read: at its
// declaration, and from scope up to close (localBindingOf).
type localOccurrenceScope struct{ declared, scope, close int }

// keeps reports whether the occurrence of name at offset at of input reads a
// local variable of that name (localVariableShadowsAt), so its text is
// kept. The replacers ask it for each occurrence of input in order: the
// bindings opening before at are read once for them all (localBindingStep),
// and an occurrence before the last one asked, another input or another
// name starts the walk again. A nil localOccurrences keeps nothing.
func (occurrences *localOccurrences) keeps(input, name string, at int) bool {
	if occurrences == nil {
		return false
	}
	if input != occurrences.input || name != occurrences.name || at < occurrences.walked {
		occurrences.input, occurrences.name, occurrences.walked = input, name, 0
		occurrences.open, occurrences.more = 0, occurrences.more[:0]
		occurrences.bound = occurrences.binds(name)
	}
	if !occurrences.bound {
		return false
	}
	for occurrences.walked < at {
		if !localBindingStepReads(input[occurrences.walked]) {
			occurrences.walked++
			continue
		}
		next, binding, bound := localBindingStep(input, occurrences.walked, name)
		occurrences.walked = next
		for index := 0; bound && index < binding.count; index++ {
			if binding.names[index] == name {
				occurrences.hold(localOccurrenceScope{declared: binding.declared[index], scope: binding.scope, close: binding.close})
			}
		}
	}
	// A binding that closes by at closes before every later occurrence
	// too: it is let go.
	kept, held := false, 0
	for _, scope := range occurrences.scopes[:occurrences.open] {
		if scope.close > at {
			kept = kept || scope.declared == at || scope.scope <= at
			occurrences.scopes[held] = scope
			held++
		}
	}
	occurrences.open, held = held, 0
	for _, scope := range occurrences.more {
		if scope.close > at {
			kept = kept || scope.declared == at || scope.scope <= at
			occurrences.more[held] = scope
			held++
		}
	}
	occurrences.more = occurrences.more[:held]
	return kept
}

func (occurrences *localOccurrences) hold(scope localOccurrenceScope) {
	if occurrences.open < len(occurrences.scopes) {
		occurrences.scopes[occurrences.open] = scope
		occurrences.open++
		return
	}
	occurrences.more = append(occurrences.more, scope)
}

// binds reports whether text binds a local named name.
func (occurrences *localOccurrences) binds(name string) bool {
	if !occurrences.read {
		occurrences.read = true
		// A clause's text is the same for every row: its names are read
		// once.
		locals, cached := localBindingNames.get(occurrences.text)
		if !cached {
			locals = expressionLocalBindings(occurrences.text)
			localBindingNames.put(occurrences.text, locals)
		}
		occurrences.locals = locals
	}
	_, bound := occurrences.locals[name]
	return bound
}

// localReader answers localVariableShadowsAt for one text, reading the
// names the text binds once (expressionLocalBindings), so a name no binding
// declares costs a map lookup. The reference scanners
// (semanticFreeReferences, expressionFreeVariables) ask it for each
// occurrence they read.
type localReader struct {
	text  string
	names map[string]struct{}
}

func newLocalReader(text string) localReader {
	return localReader{text: text, names: expressionLocalBindings(text)}
}

// shadows reports whether the occurrence of name at offset at of the text
// reads a local variable of that name.
func (reader localReader) shadows(name string, at int) bool {
	if _, declared := reader.names[name]; !declared {
		return false
	}
	return localVariableShadowsAt(reader.text, at, name)
}

// withoutTypes is types (static type names by variable) without the names
// a local binds around offset at, for a part checked as text of its own (a
// pattern comprehension, a subquery body); types itself when none is.
func (reader localReader) withoutTypes(types map[string]string, at int) map[string]string {
	var inner map[string]string
	for name := range reader.names {
		if _, typed := types[name]; !typed || !localVariableShadowsAt(reader.text, at, name) {
			continue
		}
		if inner == nil {
			inner = maps.Clone(types)
		}
		delete(inner, name)
	}
	if inner == nil {
		return types
	}
	return inner
}

// withoutLocalVariables is scope without the variables an enclosing
// expression binds around offset at of text (localVariableShadowsAt), and
// whether it bound any of scope's: in all(r IN [[true]] WHERE r[0]) the r
// read is the list's element, whatever the clause binds r to. The names
// come from expressionLocalBindings, read only when a check would fail.
func withoutLocalVariables(scope staticTypeScope, text string, at int) (staticTypeScope, bool) {
	var shadowed []string
	for name := range expressionLocalBindings(text) {
		if scope.bound(name) && localVariableShadowsAt(text, at, name) {
			shadowed = append(shadowed, name)
		}
	}
	if len(shadowed) == 0 {
		return scope, false
	}
	local := scope
	local.kinds, local.values, local.members = maps.Clone(scope.kinds), maps.Clone(scope.values), maps.Clone(scope.members)
	local.derived = maps.Clone(scope.derived)
	for _, name := range shadowed {
		delete(local.kinds, name)
		delete(local.values, name)
		delete(local.members, name)
		delete(local.derived, name)
	}
	return local, true
}

// staticListOperand reads the operand of a list position starting at start
// and returns where it ends and, when its type is static and not a list, that
// type's Neo4j name (with the parameter's name for a parameter).
func staticListOperand(ctx context.Context, cypher string, start int, params map[string]interface{}) (end int, typeName, parameter string) {
	if start >= len(cypher) {
		return start, "", ""
	}
	switch c := cypher[start]; {
	case c == '$':
		end = start + 1
		for end < len(cypher) && isIdentByte(cypher[end]) {
			end++
		}
		name := cypher[start+1 : end]
		value, bound := params[name]
		if name == "" || !bound || value == nil || isCypherListParameter(value) {
			return end, "", ""
		}
		typeName = cypherTypeName(value)
		if typeName == "Map" {
			// A map parameter can stand for a node or relationship.
			typeName = "Map, Node or Relationship"
		}
		return end, typeName, name
	case isCypherStringQuoteByte(c):
		end = start + 1
		for end < len(cypher) && (cypher[end] != c || isBackslashEscaped(cypher, end)) {
			end++
		}
		end++
	case c == '{':
		close := findMatchingDelimiter(cypher, start, '{', '}')
		if close < 0 {
			return start, "", ""
		}
		end = close + 1
	default:
		end = start
		for end < len(cypher) && (isIdentByte(cypher[end]) || cypher[end] == '.' || cypher[end] == '-' && end == start) {
			end++
		}
		// A whole call ([x IN vector(…) | x], 1 IN size(l)) is the operand.
		if c != '-' && c != '.' && (c < '0' || c > '9') {
			if open := queryGapEnd(cypher, end); open < len(cypher) && cypher[open] == '(' {
				if close := findMatchingParen(cypher, open); close > open {
					end = close + 1
				}
			}
		}
	}
	// The operator check types the operand (a variable or a property is
	// known per row); a list position rejects a type with no list or null
	// alternative.
	operand := (staticTypeScope{}).operandOf(ctx, cypher[start:end])
	if operand.typeName() == "" || !operand.excludes(isListTypeName) {
		return end, "", ""
	}
	return end, operand.typeName(), ""
}

func isCypherListParameter(value interface{}) bool {
	if _, isBytes := value.([]byte); isBytes {
		return false
	}
	kind := reflect.TypeOf(value).Kind()
	return kind == reflect.Slice || kind == reflect.Array
}

// validateStaticBooleanOperands rejects statically-known non-boolean operands
// before execution. Expressions whose type depends on a row remain subject to
// runtime validation by the row evaluator.
func (e *StorageExecutor) validateStaticBooleanOperands(ctx context.Context, expression string) error {
	expression = strings.TrimSpace(expression)
	if inner, ok := stripEnclosingExpressionParentheses(expression); ok {
		return e.validateStaticBooleanOperands(ctx, inner)
	}
	if hasPrefixFoldASCII(expression, "NOT ") {
		operand := strings.TrimSpace(expression[len("NOT "):])
		if err := e.validateStaticBooleanOperands(ctx, operand); err != nil {
			return err
		}
		value, known := e.staticBooleanOperandValue(ctx, operand)
		if !known || value == nil {
			return nil
		}
		if _, boolean := value.(bool); !boolean {
			return invalidBooleanOperandError(value)
		}
		return nil
	}
	for _, operator := range []string{" OR ", " XOR ", " AND "} {
		// Only the expression's own operators: not those inside a list, a
		// comprehension, a map or a CASE.
		left, right, found := splitByOperatorOutsideCase(expression, operator, true, true)
		if !found {
			continue
		}
		for _, operand := range []string{left, right} {
			if err := e.validateStaticBooleanOperands(ctx, operand); err != nil {
				return err
			}
			value, known := e.staticBooleanOperandValue(ctx, operand)
			if !known || value == nil {
				continue
			}
			if _, boolean := value.(bool); !boolean {
				return invalidBooleanOperandError(value)
			}
		}
		return nil
	}
	return nil
}

func (e *StorageExecutor) staticBooleanOperandValue(ctx context.Context, expression string) (interface{}, bool) {
	expression = strings.TrimSpace(expression)
	if inner, ok := stripEnclosingExpressionParentheses(expression); ok {
		expression = inner
	}
	if value, literal := parseLiteralValueFromComputedRow(expression); literal {
		return value, true
	}
	if len(expressionVariables(expression)) > 0 {
		return nil, false
	}
	if strings.HasPrefix(expression, "{") && strings.HasSuffix(expression, "}") {
		value, err := e.evaluateMapLiteralFromValues(ctx, expression, nil)
		recordExpressionFailure(ctx, err)
		return value, err == nil
	}
	for _, operator := range []string{" OR ", " XOR ", " AND ", "<=", ">=", "<>", "!=", "=", "<", ">"} {
		if _, _, found := splitByOperatorWithOptions(expression, operator, true, true); found {
			return true, true
		}
	}
	upper := upperASCII(expression)
	if strings.HasSuffix(upper, " IS NULL") || strings.HasSuffix(upper, " IS NOT NULL") || strings.HasPrefix(upper, "NOT ") {
		return true, true
	}
	value, defined := e.evaluateExpressionWithContextDefined(ctx, expression, nil, nil)
	if !defined {
		return nil, false
	}
	return value, true
}

// validateListComprehensionVariables rejects a property expression where
// Cypher requires a local iterator name, including nested projections.
func validateListComprehensionVariables(text string) error {
	for index := 0; index < len(text); index++ {
		if isCypherQuoteByte(text[index]) {
			index = skipCypherQuotedText(text, index, text[index]) - 1
			continue
		}
		if text[index] != '[' {
			continue
		}
		close := findMatchingBracket(text, index)
		if close < 0 {
			break
		}
		inner := text[index+1 : close]
		in := findListComprehensionToken(inner, " IN ")
		pipe := findListComprehensionToken(inner, "|")
		_, _, _, declared := bindingDeclaration(inner, 0)
		emptyIterator := matchKeywordAt(inner, queryGapEnd(inner, 0), "IN")
		if pipe >= 0 && (in >= 0 && pipe > in || emptyIterator) && !patternComprehensionHead(inner) && !declared {
			return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "a list comprehension iterator must be a variable")
		}
	}
	return nil
}

package cypher

import (
	"context"
	"fmt"

	"github.com/orneryd/nornicdb/pkg/storage"
)

// graphEntityReference is the sole reader of existing native graph node inputs.
// Its caller supplies the projection/engine ID domain for unscoped text IDs.
func graphEntityReference(value interface{}) (storage.EntityIdentity, bool) {
	switch node := value.(type) {
	case *storage.Node:
		if node != nil {
			return node.Identity(), true
		}
	case string:
		return storage.EntityIdentity{LocalID: node}, true
	default:
		if isIntegerProcedureValue(value) {
			return storage.EntityIdentity{LocalID: fmt.Sprint(value)}, true
		}
	}
	return storage.EntityIdentity{}, false
}

// graphEntityDisplayID renders the public value, before any graph-domain
// canonicalization. Internal keys must never be formatted in client messages.
func graphEntityDisplayID(value interface{}) (storage.NodeID, bool) {
	reference, ok := graphEntityReference(value)
	if !ok {
		return "", false
	}
	return storage.NodeID(reference.InDatabase("")), true
}

// identityGraphEngine preserves nil storage so existing graph builders return
// their established error. Wrapping nil would hide that contract from them.
func identityGraphEngine(engine storage.Engine, scopes ...*graphIdentityScope) storage.Engine {
	if engine == nil {
		return nil
	}
	return graphIdentityView(engine, scopes...)
}

// graphIdentityStorage is a read view for algorithms whose maps accept NodeID.
// Inside that view every node, edge and endpoint uses the canonical identity
// key. Native values are restored at the result boundary; no identity cache or
// graph-sized cross-stream seen set is retained by this adapter.
type graphIdentityStorage struct {
	storage.Engine
	scope *graphIdentityScope
}

func graphIdentityView(engine storage.Engine, scopes ...*graphIdentityScope) *graphIdentityStorage {
	if view, ok := engine.(*graphIdentityStorage); ok {
		return view
	}
	var scope *graphIdentityScope
	if len(scopes) > 0 {
		scope = scopes[0]
	}
	return &graphIdentityStorage{Engine: engine, scope: scope}
}

func (v *graphIdentityStorage) node(node *storage.Node) *storage.Node {
	if node == nil {
		return nil
	}
	copy := *node
	copy.ID = storage.NodeID(node.IdentityKey())
	copy.Database = ""
	return &copy
}

func graphIdentityNodeValue(node *storage.Node) *storage.Node {
	if node == nil {
		return nil
	}
	identity := storage.EntityIdentityFromKey(string(node.ID))
	copy := *node
	copy.ID, copy.Database = storage.NodeID(identity.LocalID), identity.Database
	return &copy
}

func graphIdentityEdgeValue(edge *storage.Edge) *storage.Edge {
	if edge == nil {
		return nil
	}
	identity := storage.EntityIdentityFromKey(string(edge.ID))
	start := storage.EntityIdentityFromKey(string(edge.StartNode))
	end := storage.EntityIdentityFromKey(string(edge.EndNode))
	copy := *edge
	copy.ID, copy.Database = storage.EdgeID(identity.LocalID), identity.Database
	copy.StartNode, copy.EndNode = storage.NodeID(start.LocalID), storage.NodeID(end.LocalID)
	return &copy
}

func graphIdentityPathValue(path PathResult) PathResult {
	copy := path
	copy.Nodes = make([]*storage.Node, len(path.Nodes))
	copy.Relationships = make([]*storage.Edge, len(path.Relationships))
	for i, node := range path.Nodes {
		copy.Nodes[i] = graphIdentityNodeValue(node)
	}
	for i, edge := range path.Relationships {
		copy.Relationships[i] = graphIdentityEdgeValue(edge)
	}
	return copy
}

func (e *StorageExecutor) graphIdentityExecutor(ctx context.Context) *StorageExecutor {
	engine := identityGraphEngine(e.getStorage(ctx), e.graphIdentityScope)
	if engine == nil {
		return e
	}
	return e.cloneForStorage(engine)
}

func (e *StorageExecutor) graphReadArguments(ctx context.Context, args []interface{}, nodeCount int) (*StorageExecutor, []interface{}) {
	graph := e.graphIdentityExecutor(ctx)
	view := graph.storage.(*graphIdentityStorage)
	input := append([]interface{}(nil), args...)
	for i := 0; i < nodeCount && i < len(input); i++ {
		switch value := input[i].(type) {
		case *storage.Node:
			input[i] = view.node(value)
		case string:
			if key, ok := view.inputKey(value); ok {
				input[i] = string(key)
			}
		}
	}
	return graph, input
}

func (v *graphIdentityStorage) outputPath(path []storage.NodeID) []storage.NodeID {
	result := make([]storage.NodeID, len(path))
	for i, id := range path {
		result[i] = storage.NodeID(v.outputID(id))
	}
	return result
}

func (v *graphIdentityStorage) edge(edge *storage.Edge) *storage.Edge {
	if edge == nil {
		return nil
	}
	copy := *edge
	copy.ID = storage.EdgeID(edge.IdentityKey())
	copy.StartNode = storage.NodeID(edge.StartIdentity().Key())
	copy.EndNode = storage.NodeID(edge.EndIdentity().Key())
	copy.Database = ""
	return &copy
}

func (v *graphIdentityStorage) nodes(nodes []*storage.Node) []*storage.Node {
	result := make([]*storage.Node, len(nodes))
	for i, node := range nodes {
		result[i] = v.node(node)
	}
	return result
}

func (v *graphIdentityStorage) edges(edges []*storage.Edge, err error) ([]*storage.Edge, error) {
	if err != nil {
		return nil, err
	}
	result := make([]*storage.Edge, len(edges))
	for i, edge := range edges {
		result[i] = v.edge(edge)
	}
	return result, nil
}

func (v *graphIdentityStorage) GetNode(key storage.NodeID) (*storage.Node, error) {
	id, ok := storage.EntityIdentityFromKey(string(key)).NodeLookupID(v.Engine)
	if !ok {
		return nil, storage.ErrNotFound
	}
	node, err := v.Engine.GetNode(id)
	return v.node(node), err
}

func (v *graphIdentityStorage) BatchGetNodes(keys []storage.NodeID) (map[storage.NodeID]*storage.Node, error) {
	requests := make([]storage.NodeID, 0, len(keys))
	originals := make(map[storage.NodeID][]storage.NodeID, len(keys))
	for _, key := range keys {
		if id, ok := storage.EntityIdentityFromKey(string(key)).NodeLookupID(v.Engine); ok {
			if _, requested := originals[id]; !requested {
				requests = append(requests, id)
			}
			originals[id] = append(originals[id], key)
		}
	}
	nodes, err := v.Engine.BatchGetNodes(requests)
	if err != nil {
		return nil, err
	}
	result := make(map[storage.NodeID]*storage.Node, len(nodes))
	for id, node := range nodes {
		for _, key := range originals[id] {
			result[key] = v.node(node)
		}
	}
	return result, nil
}

