func (v *graphIdentityStorage) inputKey(value interface{}) (storage.NodeID, bool) {
	reference, ok := graphEntityReference(value)
	if !ok {
		return "", false
	}
	if reference.Database == "" {
		if kind, database, local, qualified := storage.ParseElementID(reference.LocalID); qualified {
			if kind != "4" {
				return "", false
			}
			domain := graphIdentityDomain{engine: v.Engine, scope: v.scope}
			if storage.CompositeDatabaseOf(v.Engine) == "" && !domain.foreignQualifier(database) {
				database = storage.DatabaseOf(v.Engine)
			}
			reference.Database, reference.LocalID = database, local
		} else if storage.CompositeDatabaseOf(v.Engine) == "" {
			reference.Database = storage.DatabaseOf(v.Engine)
		} else if node, err := v.Engine.GetNode(storage.NodeID(reference.LocalID)); err == nil && node != nil {
			reference = node.Identity()
		}
	}
	return storage.NodeID(reference.Key()), true
}

// algorithmIdentityInput gives all whole-graph algorithms one key domain for
// native arguments, graph scans, adjacency and their computed maps.
func (e *StorageExecutor) algorithmIdentityInput(procedure string, args []interface{}) (*StorageExecutor, []*storage.Node, error) {
	view := graphIdentityView(e.storage, e.graphIdentityScope)
	graph := e.cloneForStorage(view)
	input := append([]interface{}(nil), args...)
	if len(input) > 0 {
		if items, ok := cypherListValue(input[0]); ok && len(items) > 0 {
			if _, native := items[0].(*storage.Node); native {
				values := append([]interface{}(nil), items...)
				for i, value := range values {
					if node, ok := value.(*storage.Node); ok {
						values[i] = view.node(node)
					}
				}
				input[0] = values
			}
		}
	}
	nodes, err := graph.algorithmNodes(procedure, input)
	return graph, nodes, err
}

func graphAlgorithmRows[T any](nodes []*storage.Node, values map[storage.NodeID]T) [][]interface{} {
	rows := algorithmRows(nodes, values)
	for _, row := range rows {
		if node, ok := row[0].(*storage.Node); ok {
			row[0] = graphIdentityNodeValue(node)
		}
	}
	return rows
}

// bindIdentity converts native/config references only after the graph's key
// domain is known. Projection IDs retain their public catalog domain; stored
// graphs use the same canonical read view as scalar and APOC algorithms.
func (c *linkPredictionConfig) bindIdentity(engine storage.Engine, projection *GraphProjection) {
	c.identityStore = engine
	var read func(interface{}) (storage.NodeID, bool)
	if projection != nil {
		read = func(value interface{}) (storage.NodeID, bool) {
			id, ok := projection.nodeReference(value)
			return storage.NodeID(id), ok
		}
		c.identityOutput = func(id storage.NodeID) string { return string(id) }
	} else {
		view := graphIdentityView(engine)
		read, c.identityStore, c.identityOutput = view.inputKey, identityGraphEngine(engine), view.outputID
	}
	value := c.sourceValue
	if value == nil {
		value = string(c.SourceNode)
	}
	c.SourceNode, _ = read(value)
	if c.TargetNodes != nil {
		values := c.targetValues
		if values == nil {
			for id := range c.TargetNodes {
				values = append(values, string(id))
			}
		}
		c.TargetNodes = make(map[storage.NodeID]bool, len(values))
		for _, value := range values {
			if id, ok := read(value); ok {
				c.TargetNodes[id] = true
			}
		}
	}
}

func (c *linkPredictionConfig) identityRows(result *ExecuteResult) *ExecuteResult {
	if c.identityOutput != nil {
		for _, row := range result.Rows {
			for i := 0; i < 2 && i < len(row); i++ {
				if id, ok := row[i].(string); ok {
					row[i] = c.identityOutput(storage.NodeID(id))
				}
			}
		}
	}
	return result
}

func (v *graphIdentityStorage) outputID(key storage.NodeID) string {
	return storage.EntityIdentityFromKey(string(key)).InDatabase(storageDatabaseName(v.Engine))
}

func (c *linkPredictionConfig) sourceDisplay() string {
	value := c.sourceValue
	if value == nil {
		value = string(c.SourceNode)
	}
	id, _ := graphEntityDisplayID(value)
	return string(id)
}

// graphEntityLookupID is the storage-domain adapter for utility functions.
// Preserve their legacy string coercion without losing native provenance.
func graphEntityLookupID(engine storage.Engine, value interface{}, domains ...graphIdentityDomain) (storage.NodeID, bool) {
	reference, ok := graphEntityReference(value)
	if !ok {
		reference = storage.EntityIdentity{LocalID: fmt.Sprint(value)}
	}
	if _, native := value.(*storage.Node); !native {
		if kind, database, local, qualified := storage.ParseElementID(reference.LocalID); qualified {
			if kind != "4" {
				return "", false
			}
			domain := graphIdentityDomain{engine: engine}
			if len(domains) > 0 {
				domain = domains[0]
			}
			if storage.CompositeDatabaseOf(engine) == "" && !domain.foreignQualifier(database) {
				return storage.NodeID(local), true
			}
			reference = storage.EntityIdentity{Database: database, LocalID: local}
		}
	}
	return reference.NodeLookupID(engine)
}

// SubscribeEvents retains the underlying engine's publication owner through
// the identity read view; the adapter never publishes a second event stream.
func (v *graphIdentityStorage) SubscribeEvents(handlers storage.EventHandlers) error {
	return storage.SubscribeEvents(v.Engine, handlers)
}

// Package cypher provides index hint support for Neo4j-compatible query optimization.
//
// Index hints allow users to specify which indexes should be used during query execution,
// overriding the query planner's automatic index selection.
//
// # Supported Hint Types
//
//   - USING INDEX variable:Label(property) - Force use of a specific property index
//   - USING SCAN variable:Label - Force a label scan instead of index lookup
//   - USING JOIN ON variable - Force specific join strategy (planned)
//
// # Neo4j Compatibility
//
// This implementation follows Neo4j's index hint syntax:
//
//	MATCH (n:Person)
//	USING INDEX n:Person(name)
//	WHERE n.name = 'Alice'
//	RETURN n
//
// Multiple hints can be specified:
//
//	MATCH (a:Person)-[:KNOWS]->(b:Person)
//	USING INDEX a:Person(name)
//	USING INDEX b:Person(email)
//	WHERE a.name = 'Alice' AND b.email = 'bob@example.com'
//	RETURN a, b
//
// # ELI12 (Explain Like I'm 12)
//
// Imagine you have a huge phone book (database). Normally, the database decides
// the fastest way to find someone - maybe by their name index, or by scanning.
// Index hints are like saying "I KNOW the name index is best - use that one!"
// It's like telling a librarian exactly which catalog to use.
package cypher

import (
	"fmt"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// IndexHintType represents the type of index hint.
type IndexHintType int

const (
	// HintIndex forces use of a specific property index.
	HintIndex IndexHintType = iota
	// HintScan forces a label scan instead of index lookup.
	HintScan
	// HintJoin forces a specific join strategy.
	HintJoin
)

// IndexHint represents a parsed index hint from a Cypher query.
//
// Example:
//
//	USING INDEX n:Person(name)
//	→ IndexHint{Type: HintIndex, Variable: "n", Label: "Person", Property: "name"}
type IndexHint struct {
	Type       IndexHintType
	Variable   string   // The variable name (e.g., "n" in "n:Person")
	Label      string   // The label (e.g., "Person")
	Property   string   // The property for index hints (e.g., "name")
	Properties []string // Multiple properties for composite hints
}

// String returns a human-readable representation of the hint.
func (h *IndexHint) String() string {
	switch h.Type {
	case HintIndex:
		if len(h.Properties) > 1 {
			return fmt.Sprintf("USING INDEX %s:%s(%s)", h.Variable, h.Label, strings.Join(h.Properties, ", "))
		}
		return fmt.Sprintf("USING INDEX %s:%s(%s)", h.Variable, h.Label, h.Property)
	case HintScan:
		return fmt.Sprintf("USING SCAN %s:%s", h.Variable, h.Label)
	case HintJoin:
		return fmt.Sprintf("USING JOIN ON %s", h.Variable)
	default:
		return "UNKNOWN HINT"
	}
}

// ParseIndexHints extracts all index hints from a Cypher query.
//
// Parameters:
//   - query: The full Cypher query string
//
// Returns:
//   - Slice of parsed IndexHint structs
//   - The query with hints removed (for further processing)
//
// Example:
//
//	query := "MATCH (n:Person) USING INDEX n:Person(name) WHERE n.name = 'Alice' RETURN n"
//	hints, cleanQuery := ParseIndexHints(query)
//	// hints = [{Type: HintIndex, Variable: "n", Label: "Person", Property: "name"}]
//	// cleanQuery = "MATCH (n:Person)  WHERE n.name = 'Alice' RETURN n"
func ParseIndexHints(query string) ([]IndexHint, string) {
	var hints []IndexHint
	var clean strings.Builder
	pos := 0
	for {
		usingIdx := keywordIndexFrom(query, "USING", pos, defaultKeywordScanOpts())
		if usingIdx < 0 {
			clean.WriteString(query[pos:])
			break
		}

		clean.WriteString(query[pos:usingIdx])
		if hint, end, ok := parseSingleIndexHint(query, usingIdx); ok {
			hints = append(hints, hint)
			pos = end
			continue
		}

		// Not a valid hint form; keep "USING" text and continue scanning.
		clean.WriteString(query[usingIdx : usingIdx+5])
		pos = usingIdx + 5
	}

	return hints, strings.Join(strings.Fields(clean.String()), " ")
}

func parseSingleIndexHint(query string, usingIdx int) (IndexHint, int, bool) {
	usingEnd, ok := keywordSpanAt(query, usingIdx, "USING")
	if !ok {
		return IndexHint{}, usingIdx, false
	}
	rest := strings.TrimSpace(query[usingEnd:])
	restStart := usingEnd + (len(query[usingEnd:]) - len(rest))
	if rest == "" {
		return IndexHint{}, usingIdx, false
	}

	if startsWithKeywordFold(rest, "INDEX") {
		indexEnd, ok := keywordSpanAt(rest, 0, "INDEX")
		if !ok {
			return IndexHint{}, usingIdx, false
		}
		hint, consumed, ok := parseIndexHintSpec(rest[indexEnd:])
		if !ok {
			return IndexHint{}, usingIdx, false
		}
		return hint, restStart + indexEnd + consumed, true
	}

	if startsWithKeywordFold(rest, "SCAN") {
		scanEnd, ok := keywordSpanAt(rest, 0, "SCAN")
		if !ok {
			return IndexHint{}, usingIdx, false
		}
		hint, consumed, ok := parseScanHintSpec(rest[scanEnd:])
		if !ok {
			return IndexHint{}, usingIdx, false
		}
		return hint, restStart + scanEnd + consumed, true
	}

	if startsWithKeywordFold(rest, "JOIN") {
		joinEnd, ok := keywordSpanAt(rest, 0, "JOIN")
		if !ok {
			return IndexHint{}, usingIdx, false
		}
		hint, consumed, ok := parseJoinHintSpec(rest[joinEnd:])
		if !ok {
			return IndexHint{}, usingIdx, false
		}
		return hint, restStart + joinEnd + consumed, true
	}

	return IndexHint{}, usingIdx, false
}

func parseIndexHintSpec(s string) (IndexHint, int, bool) {
	original := s
	s = strings.TrimSpace(s)
	trimmedPrefix := len(original) - len(s)
	variable, rest, ok := parseIdentifierToken(s)
	if !ok {
		return IndexHint{}, 0, false
	}
	rest = strings.TrimSpace(rest)
	if !strings.HasPrefix(rest, ":") {
		return IndexHint{}, 0, false
	}
	label, rest, ok := parseIdentifierToken(strings.TrimSpace(rest[1:]))
	if !ok {
		return IndexHint{}, 0, false
	}
	rest = strings.TrimSpace(rest)
	inside, trailing, ok := extractParenSection(rest)
	if !ok {
		return IndexHint{}, 0, false
	}
	props := splitTopLevelComma(inside)
	parsedProps := make([]string, 0, len(props))
	for _, p := range props {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		if name, _, ok := parseIdentifierToken(p); ok {
			parsedProps = append(parsedProps, name)
		} else {
			return IndexHint{}, 0, false
		}
	}
	if len(parsedProps) == 0 {
		return IndexHint{}, 0, false
	}
	consumed := trimmedPrefix + len(s) - len(trailing)
	return IndexHint{
		Type:       HintIndex,
		Variable:   variable,
		Label:      label,
		Property:   parsedProps[0],
		Properties: parsedProps,
	}, consumed, true
}

func parseScanHintSpec(s string) (IndexHint, int, bool) {
	original := s
	s = strings.TrimSpace(s)
	trimmedPrefix := len(original) - len(s)
	variable, rest, ok := parseIdentifierToken(s)
	if !ok {
		return IndexHint{}, 0, false
	}
	rest = strings.TrimSpace(rest)
	if !strings.HasPrefix(rest, ":") {
		return IndexHint{}, 0, false
	}
	label, rest, ok := parseIdentifierToken(strings.TrimSpace(rest[1:]))
	if !ok {
		return IndexHint{}, 0, false
	}
	consumed := trimmedPrefix + len(s) - len(rest)
	return IndexHint{Type: HintScan, Variable: variable, Label: label}, consumed, true
}

func parseJoinHintSpec(s string) (IndexHint, int, bool) {
	original := s
	s = strings.TrimSpace(s)
	trimmedPrefix := len(original) - len(s)
	onEnd, ok := keywordSpanAt(s, 0, "ON")
	if !ok {
		return IndexHint{}, 0, false
	}
	variable, rest, ok := parseIdentifierToken(strings.TrimSpace(s[onEnd:]))
	if !ok {
		return IndexHint{}, 0, false
	}
	consumed := trimmedPrefix + len(s) - len(rest)
	return IndexHint{Type: HintJoin, Variable: variable}, consumed, true
}

// IndexHintContext holds index hints for a query execution.
type IndexHintContext struct {
	Hints      []IndexHint
	HintsByVar map[string][]IndexHint // Variable -> hints for that variable
}

// NewIndexHintContext creates a new context from parsed hints.
func NewIndexHintContext(hints []IndexHint) *IndexHintContext {
	ctx := &IndexHintContext{
		Hints:      hints,
		HintsByVar: make(map[string][]IndexHint),
	}

	for _, hint := range hints {
		ctx.HintsByVar[hint.Variable] = append(ctx.HintsByVar[hint.Variable], hint)
	}

	return ctx
}

// GetHintsForVariable returns all hints for a specific variable.
func (ctx *IndexHintContext) GetHintsForVariable(variable string) []IndexHint {
	if ctx == nil || ctx.HintsByVar == nil {
		return nil
	}
	return ctx.HintsByVar[variable]
}

// HasIndexHint checks if there's an index hint for a variable/label/property combination.
func (ctx *IndexHintContext) HasIndexHint(variable, label, property string) bool {
	if ctx == nil {
		return false
	}

	hints := ctx.HintsByVar[variable]
	for _, hint := range hints {
		if hint.Type == HintIndex &&
			hint.Label == label &&
			hint.Property == property {
			return true
		}
	}
	return false
}

// ShouldForceScan checks if a label scan should be forced for a variable.
func (ctx *IndexHintContext) ShouldForceScan(variable, label string) bool {
	if ctx == nil {
		return false
	}

	hints := ctx.HintsByVar[variable]
	for _, hint := range hints {
		if hint.Type == HintScan && hint.Label == label {
			return true
		}
	}
	return false
}

// ApplyIndexHint attempts to use the specified index for node lookup.
// Returns nodes matching the index lookup, or nil if index doesn't exist.
//
// Parameters:
//   - storage: The storage engine to query
//   - schema: The schema manager for index lookup
//   - hint: The index hint to apply
//   - propertyValue: The value to look up in the index
//
// Returns:
//   - Matching nodes if index exists and value found
//   - nil, nil if index doesn't exist (fall back to scan)
//   - nil, error if lookup fails
func ApplyIndexHint(store storage.Engine, schema *storage.SchemaManager, hint IndexHint, propertyValue interface{}) ([]*storage.Node, error) {
	if hint.Type != HintIndex {
		return nil, nil // Not an index hint
	}

	// Check if the index exists
	if schema == nil {
		return nil, nil // No schema manager, fall back to scan
	}

	// Try to use the property index for O(1) lookup
	nodeIDs := propertyIndexLookup(store, schema, hint.Label, hint.Property, propertyValue)
	if nodeIDs != nil {
		// Index exists and was used! Get the actual nodes.
		var result []*storage.Node
		for _, nodeID := range nodeIDs {
			node, err := store.GetNode(nodeID)
			if err == nil && node != nil {
				result = append(result, node)
			}
		}
		return result, nil
	}

	// No index found - fall back to label scan with property filter
	nodes, err := store.GetNodesByLabel(hint.Label)
	if err != nil {
		return nil, err
	}

	// Filter by property value
	var result []*storage.Node
	for _, node := range nodes {
		if val, ok := node.Properties[hint.Property]; ok {
			if compareValues(val, propertyValue) {
				result = append(result, node)
			}
		}
	}

	return result, nil
}

// Note: compareValues and toFloat64 are defined in case_expression.go and helpers.go

// ValidateIndexHints checks if all specified index hints can be satisfied.
// Returns an error if any hint references a non-existent index.
//
// Parameters:
//   - schema: The schema manager to validate against
//   - hints: The index hints to validate
//
// Returns:
//   - nil if all hints are valid
//   - Error describing which hint cannot be satisfied
func ValidateIndexHints(schema *storage.SchemaManager, hints []IndexHint) error {
	if schema == nil || len(hints) == 0 {
		return nil
	}

	indexes := schema.GetIndexes()
	indexMap := make(map[string]bool)

	for _, idx := range indexes {
		if m, ok := idx.(map[string]interface{}); ok {
			label, _ := m["label"].(string)
			props, _ := m["properties"].([]string)
			if len(props) > 0 {
				key := fmt.Sprintf("%s:%s", label, props[0])
				indexMap[key] = true
			}
		}
	}

	for _, hint := range hints {
		if hint.Type == HintIndex {
			key := fmt.Sprintf("%s:%s", hint.Label, hint.Property)
			if !indexMap[key] {
				// Neo4j returns a specific error for missing indexes
				return localizedError(localization.CypherCoreIndexHintNotFound(hint.String(), hint.Label, hint.Property), nil)
			}
		}
	}

	return nil
}

package cypher

import (
	"context"
	"fmt"
	"log/slog"
	"strings"

	"github.com/orneryd/nornicdb/pkg/knowledgepolicy"
	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// evaluateKnowledgePolicyFunction dispatches decayScore(), decay(), and policy()
// calls. Returns (result, true) if the expression was handled, (nil, false) otherwise.
func (e *StorageExecutor) evaluateKnowledgePolicyFunction(
	ctx context.Context,
	expr string,
	lowerExpr string,
	nodes map[string]*storage.Node,
	rels map[string]*storage.Edge,
) (interface{}, bool) {
	for _, name := range []string{"decayScore", "decayscore", "decay", "policy"} {
		if matchFuncStartAndSuffix(expr, name) {
			return e.evalKnowledgePolicy(ctx, expr, nodes, rels), true
		}
	}
	return nil, false
}

type resolvedEntity struct {
	entityID       string
	engine         storage.Engine
	labels         []string
	createdAtNanos int64
	versionAtNanos int64
	isEdge         bool
	edgeType       string
}

func (e *StorageExecutor) resolveEntityForDecay(
	ctx context.Context,
	argExpr string,
	nodes map[string]*storage.Node,
	rels map[string]*storage.Edge,
) (resolvedEntity, bool) {
	arg := strings.TrimSpace(argExpr)
	if node, ok := nodes[arg]; ok {
		engine, _, err := e.knowledgePolicyContext(node.Database)
		if err != nil {
			recordExpressionFailure(ctx, err)
			return resolvedEntity{}, false
		}
		return resolvedEntity{
			engine:         engine,
			entityID:       storage.QualifiedEntityID(engine, string(node.ID)),
			labels:         node.Labels,
			createdAtNanos: node.CreatedAt.UnixNano(),
			versionAtNanos: node.UpdatedAt.UnixNano(),
		}, true
	}
	if rel, ok := rels[arg]; ok {
		engine, _, err := e.knowledgePolicyContext(rel.Database)
		if err != nil {
			recordExpressionFailure(ctx, err)
			return resolvedEntity{}, false
		}
		return resolvedEntity{
			engine:         engine,
			entityID:       storage.QualifiedEntityID(engine, string(rel.ID)),
			isEdge:         true,
			edgeType:       rel.Type,
			createdAtNanos: rel.CreatedAt.UnixNano(),
			versionAtNanos: rel.UpdatedAt.UnixNano(),
		}, true
	}
	return resolvedEntity{}, false
}

// score keeps entity-kind and property dispatch identical for decay() and
// decayScore(). Relationship property bindings resolve by type, not labels.
func (ent resolvedEntity) score(scorer *knowledgepolicy.Scorer, accessMeta *knowledgepolicy.AccessMetaEntry, property string, nowNanos int64) knowledgepolicy.ScoringResolution {
	if property != "" {
		if ent.isEdge {
			return scorer.ScoreEdgeProperty(ent.entityID, ent.edgeType, property, accessMeta, ent.createdAtNanos, ent.versionAtNanos, nowNanos)
		}
		return scorer.ScoreProperty(ent.entityID, ent.labels, property, accessMeta, ent.createdAtNanos, ent.versionAtNanos, nowNanos)
	}
	if ent.isEdge {
		return scorer.ScoreEdge(ent.entityID, ent.edgeType, accessMeta, ent.createdAtNanos, ent.versionAtNanos, nowNanos)
	}
	return scorer.ScoreNode(ent.entityID, ent.labels, accessMeta, ent.createdAtNanos, ent.versionAtNanos, nowNanos)
}

// getDecayContext returns the Badger engine that scores decay and the scoring
// time: the statement's clock (the instant datetime.statement() reads), so
// every decay function of one statement scores at one instant (#866). Outside
// a statement it is the current time.
func (e *StorageExecutor) getDecayContext(ctx context.Context, engine storage.Engine) (be *storage.BadgerEngine, nowNanos int64, ok bool) {
	be = unwrapBadgerEngine(engine)
	if be == nil {
		return nil, 0, false
	}
	return be, e.temporalClockTime(ctx, "statement").UnixNano(), true
}

func (e *StorageExecutor) logDecayMismatchOnce() {
	if e.decayMismatchLogged {
		return
	}
	e.decayMismatchLogged = true
	e.logEvent(slog.LevelWarn, localization.CypherDecaySubsystemDisabledEvent())
}

// evalKnowledgePolicy owns source selection, access metadata and scoring for
// policy(), decay() and decayScore(); only their result presentation differs.
func (e *StorageExecutor) evalKnowledgePolicy(ctx context.Context, expr string, nodes map[string]*storage.Node, rels map[string]*storage.Edge) interface{} {
	originalName, _, _ := strings.Cut(expr, "(")
	name := strings.ToLower(strings.TrimSpace(originalName))
	args := e.splitFunctionArgs(extractFuncArgs(expr, strings.TrimSpace(originalName)))
	disabled := func(reason string) interface{} {
		if name == "policy" {
			return minimalPolicyMap("")
		}
		if name == "decayscore" {
			return 1.0
		}
		return decayDisabledMap(reason)
	}
	if len(args) == 0 {
		return disabled(localization.CypherKnowledgePolicyReasonNoEntityArgument().Fallback)
	}
	ent, ok := e.resolveEntityForDecay(ctx, args[0], nodes, rels)
	if !ok {
		return disabled(localization.CypherKnowledgePolicyReasonEntityNotFound().Fallback)
	}
	be, now, available := e.getDecayContext(ctx, ent.engine)
	var meta *knowledgepolicy.AccessMetaEntry
	if available {
		meta, _ = be.GetAccessMeta(ent.entityID)
	}
	if name == "policy" {
		if meta != nil {
			return accessMetaToMap(meta)
		}
		scope := knowledgepolicy.ScopeNode
		if ent.isEdge {
			scope = knowledgepolicy.ScopeEdge
		}
		return map[string]interface{}{"targetId": ent.entityID, "targetScope": string(scope)}
	}
	if !available {
		return disabled(localization.CypherKnowledgePolicyReasonNoBadgerEngine().Fallback)
	}
	if !be.IsDecayEnabled() {
		e.logDecayMismatchOnce()
		return disabled(localization.CypherKnowledgePolicyReasonDecayDisabled().Fallback)
	}
	scorer := be.ScorerForNamespace(storage.ExtractNamespaceFromID(ent.entityID))
	if scorer == nil {
		return disabled(localization.CypherKnowledgePolicyReasonNoDecayProfile().Fallback)
	}
	property := ""
	if len(args) >= 2 {
		var err error
		property, err = validateDecayOptions(ctx, args[1], nodes, rels, e)
		if err != nil {
			return nil
		}
	}
	resolution := ent.score(scorer, meta, property, now)
	if name == "decayscore" {
		return resolution.FinalScore
	}
	return resolutionToMap(resolution)
}

func decayDisabledMap(reason string) map[string]interface{} {
	return map[string]interface{}{
		"score":   1.0,
		"applies": false,
		"reason":  reason,
	}
}

func resolutionToMap(res knowledgepolicy.ScoringResolution) map[string]interface{} {
	applies := !res.NoDecay && res.ResolvedDecayProfileID != ""
	reason := ""
	if res.NoDecay {
		reason = localization.CypherKnowledgePolicyReasonNoDecay().Fallback
	} else if res.ResolvedDecayProfileID == "" {
		reason = localization.CypherKnowledgePolicyReasonNoDecayProfile().Fallback
		applies = false
	}
	return map[string]interface{}{
		"score":               res.FinalScore,
		"policy":              res.ResolvedDecayProfileID,
		"scope":               string(res.TargetScope),
		"function":            string(res.ResolvedDecayFunction),
		"visibilityThreshold": res.EffectiveThreshold,
		"floor":               res.EffectiveFloor,
		"applies":             applies,
		"reason":              reason,
		"scoreFrom":           string(res.ResolvedScoreFrom),
	}
}

func accessMetaToMap(meta *knowledgepolicy.AccessMetaEntry) map[string]interface{} {
	return map[string]interface{}{
		"targetId":       meta.TargetID,
		"targetScope":    string(meta.TargetScope),
		"accessCount":    meta.Fixed.AccessCount,
		"traversalCount": meta.Fixed.TraversalCount,
		"lastAccessedAt": meta.Fixed.LastAccessedAt,
		"lastMutatedAt":  meta.LastMutatedAt,
		"mutationCount":  meta.MutationCount,
	}
}

func minimalPolicyMap(entityID string) map[string]interface{} {
	return map[string]interface{}{
		"targetId":    entityID,
		"targetScope": string(knowledgepolicy.ScopeNode),
	}
}

// validateDecayOptions parses the second argument to decayScore/decay as a
// map literal and extracts the "property" key. Returns an error for unknown keys.
func validateDecayOptions(
	ctx context.Context,
	optExpr string,
	nodes map[string]*storage.Node,
	rels map[string]*storage.Edge,
	e *StorageExecutor,
) (string, error) {
	val := e.evaluateExpressionWithContext(ctx, optExpr, nodes, rels)
	m, ok := val.(map[string]interface{})
	if !ok {
		return "", localizedError(localization.CypherKnowledgePolicyDecayOptionsMapRequired(fmt.Sprintf("%T", val)), nil)
	}
	var property string
	for k, v := range m {
		switch k {
		case "property":
			s, _ := v.(string)
			property = s
		default:
			return "", localizedError(localization.CypherKnowledgePolicyUnknownDecayOption(k), nil)
		}
	}
	return property, nil
}

