func formatDecayBindingApply(binding knowledgepolicy.DecayProfileBinding) string {
	lines := make([]string, 0, 5+len(binding.PropertyRules))
	if binding.ProfileRef != "" {
		lines = append(lines, "DECAY PROFILE "+quoteKnowledgePolicyName(binding.ProfileRef))
	}
	if binding.NoDecay {
		lines = append(lines, "NO DECAY")
	}
	if binding.HalfLifeSeconds != 0 {
		lines = append(lines, "DECAY HALF LIFE "+strconv.FormatInt(binding.HalfLifeSeconds, 10))
	}
	if binding.VisibilityThreshold != nil {
		lines = append(lines, "DECAY VISIBILITY THRESHOLD "+formatKnowledgePolicyFloat(*binding.VisibilityThreshold))
	}
	if binding.ScoreFloor != 0 {
		lines = append(lines, "DECAY FLOOR "+formatKnowledgePolicyFloat(binding.ScoreFloor))
	}

	variable := "n"
	if binding.IsEdge {
		variable = "r"
	}
	for _, rule := range binding.PropertyRules {
		prefix := variable + "." + rule.PropertyPath
		if rule.NoDecay {
			lines = append(lines, prefix+" NO DECAY")
		}
		if rule.ProfileRef != "" {
			lines = append(lines, prefix+" DECAY PROFILE "+quoteKnowledgePolicyName(rule.ProfileRef))
		}
		if rule.HalfLifeSeconds != 0 {
			lines = append(lines, prefix+" DECAY HALF LIFE "+strconv.FormatInt(rule.HalfLifeSeconds, 10))
		}
		if rule.ScoreFloor != 0 {
			lines = append(lines, prefix+" DECAY FLOOR "+formatKnowledgePolicyFloat(rule.ScoreFloor))
		}
	}
	return strings.Join(lines, "\n")
}

func formatPromotionPolicyApply(policy knowledgepolicy.PromotionPolicyDef) string {
	lines := make([]string, 0, len(policy.WhenClauses)+1)
	if policy.OnAccess != nil && len(policy.OnAccess.Mutations) > 0 {
		mutationLines := make([]string, 0, len(policy.OnAccess.Mutations))
		for _, mutation := range policy.OnAccess.Mutations {
			prefix := ""
			if mutation.Kalman != nil {
				config := []string{
					"q: " + formatKnowledgePolicyFloat(mutation.Kalman.Q),
					"varianceScale: " + formatKnowledgePolicyFloat(mutation.Kalman.VarianceScale),
					"windowSize: " + strconv.Itoa(mutation.Kalman.WindowSize),
				}
				if mutation.Kalman.Mode == knowledgepolicy.KalmanModeManual {
					config = append(config, "r: "+formatKnowledgePolicyFloat(mutation.Kalman.R))
				}
				prefix = "WITH KALMAN { " + strings.Join(config, ", ") + " } "
			}
			mutationLines = append(mutationLines, "  "+prefix+"SET "+mutation.Expression)
		}
		lines = append(lines, "ON ACCESS {\n"+strings.Join(mutationLines, "\n")+"\n}")
	}
	for _, clause := range policy.WhenClauses {
		lines = append(lines, "WHEN "+clause.Predicate+" APPLY PROFILE "+quoteKnowledgePolicyName(clause.ProfileRef))
	}
	return strings.Join(lines, "\n")
}

func quoteKnowledgePolicyName(name string) string {
	return "'" + strings.ReplaceAll(name, "'", "\\'") + "'"
}

func formatKnowledgePolicyFloat(value float64) string {
	return strconv.FormatFloat(value, 'g', -1, 64)
}

type knowledgePolicyEntityKind uint8

const (
	knowledgePolicyEntityAny knowledgePolicyEntityKind = iota
	knowledgePolicyEntityNode
	knowledgePolicyEntityEdge
)

func parseKnowledgePolicyEntityID(entityID string) (string, knowledgePolicyEntityKind) {
	parts := strings.SplitN(strings.TrimSpace(entityID), ":", 3)
	if len(parts) != 3 {
		return entityID, knowledgePolicyEntityAny
	}
	switch parts[0] {
	case "4":
		return entityID, knowledgePolicyEntityNode
	case "5":
		return entityID, knowledgePolicyEntityEdge
	default:
		return entityID, knowledgePolicyEntityAny
	}
}

func (e *StorageExecutor) callNornicDbKnowledgePolicyResolve(args []interface{}) (*ExecuteResult, error) {
	entityID, err := optionalStringArg(args, 0)
	if err != nil {
		return nil, err
	}
	labelsCSV, err := optionalStringArg(args, 1)
	if err != nil {
		return nil, err
	}
	edgeType, err := optionalStringArg(args, 2)
	if err != nil {
		return nil, err
	}
	if entityID == "" && labelsCSV == "" && edgeType == "" {
		return nil, localizedError(localization.CypherKnowledgePolicyResolveTargetRequired(), nil)
	}

	schema := e.storage.GetSchema()
	if schema == nil {
		return nil, localizedError(localization.CypherKnowledgePolicySchemaManagerUnavailable(), nil)
	}
	bt := schema.GetBindingTable()
	if bt == nil {
		return nil, localizedError(localization.CypherKnowledgePolicyBindingTableUnavailable(), nil)
	}

	decayEnabled := false
	if be := unwrapBadgerEngine(e.storage); be != nil {
		decayEnabled = be.IsDecayEnabled()
	}
	resolver := knowledgepolicy.NewResolver(bt, nil)
	scorer := knowledgepolicy.NewScorer(resolver, decayEnabled)
	nowNanos := storage.DecayScoringTime()

	var resolution knowledgepolicy.ScoringResolution
	if entityID != "" {
		lookupID, entityKind := parseKnowledgePolicyEntityID(entityID)
		if entityKind != knowledgePolicyEntityAny {
			kind := "4"
			if entityKind == knowledgePolicyEntityEdge {
				kind = "5"
			}
			var found, applicable bool
			lookupID, found, applicable = e.entitySeekLookup(lookupID, kind, "elementId")
			if !found || !applicable {
				return nil, localizedError(localization.CypherKnowledgePolicyEntityNotFound(entityID), nil)
			}
		}
		if node, nodeErr := e.storage.GetNode(storage.NodeID(lookupID)); entityKind != knowledgePolicyEntityEdge && nodeErr == nil && node != nil {
			createdNanos := node.CreatedAt.UnixNano()
			versionNanos := createdNanos
			if !node.UpdatedAt.IsZero() {
				versionNanos = node.UpdatedAt.UnixNano()
			}
			resolution = scorer.ScoreNode(entityID, node.Labels, loadAccessMeta(e.storage, lookupID), createdNanos, versionNanos, nowNanos)
		} else if edge, edgeErr := e.storage.GetEdge(storage.EdgeID(lookupID)); entityKind != knowledgePolicyEntityNode && edgeErr == nil && edge != nil {
			createdNanos := edge.CreatedAt.UnixNano()
			versionNanos := createdNanos
			if !edge.UpdatedAt.IsZero() {
				versionNanos = edge.UpdatedAt.UnixNano()
			}
			resolution = scorer.ScoreEdge(entityID, edge.Type, loadAccessMeta(e.storage, lookupID), createdNanos, versionNanos, nowNanos)
		} else {
			return nil, localizedError(localization.CypherKnowledgePolicyEntityNotFound(entityID), nil)
		}
	} else if edgeType != "" {
		resolution = scorer.ScoreEdge("dry-run", edgeType, nil, nowNanos, nowNanos, nowNanos)
	} else {
		labels := splitCSVLabels(labelsCSV)
		resolution = scorer.ScoreNode("dry-run", labels, nil, nowNanos, nowNanos, nowNanos)
	}

	return &ExecuteResult{
		Columns: []string{"TargetID", "TargetScope", "ResolvedDecayProfileID", "ResolvedScoreFrom", "ResolutionSourceChain", "AppliedDecayProfileNames", "AppliedPromotionPolicyName", "AppliedPromotionProfileName", "EffectiveRate", "EffectiveThreshold", "EffectiveMultiplier", "BaseScore", "FinalScore", "NoDecay", "SuppressionEligible", "Explanation"},
		Rows: [][]interface{}{{
			resolution.TargetID,
			string(resolution.TargetScope),
			resolution.ResolvedDecayProfileID,
			string(resolution.ResolvedScoreFrom),
			resolution.ResolutionSourceChain,
			resolution.AppliedDecayProfileNames,
			resolution.AppliedPromotionPolicyName,
			resolution.AppliedPromotionProfileName,
			resolution.EffectiveRate,
			resolution.EffectiveThreshold,
			resolution.EffectiveMultiplier,
			resolution.BaseScore,
			resolution.FinalScore,
			resolution.NoDecay,
			resolution.SuppressionEligible,
			resolution.Explanation,
		}},
	}, nil
}

func (e *StorageExecutor) callNornicDbKnowledgePolicyDeindexStatus() (*ExecuteResult, error) {
	columns := []string{"pending_count", "supported", "message", "workItemId", "targetId", "targetScope", "enqueuedAt", "status"}
	be := unwrapBadgerEngine(e.storage)
	if be == nil {
		return &ExecuteResult{
			Columns: columns,
			Rows:    [][]interface{}{{0, false, localization.CypherKnowledgePolicyDeindexBadgerRequired().Fallback, "", "", "", nil, ""}},
		}, nil
	}

	items, err := be.ScanPendingDeindexWorkItems()
	if err != nil {
		return nil, err
	}
	if len(items) == 0 {
		return &ExecuteResult{
			Columns: columns,
			Rows:    [][]interface{}{{0, true, "", "", "", "", nil, ""}},
		}, nil
	}

	rows := make([][]interface{}, 0, len(items))
	for _, item := range items {
		rows = append(rows, []interface{}{
			len(items),
			true,
			"",
			item.WorkItemID,
			item.TargetID,
			item.TargetScope,
			item.EnqueuedAt,
			item.Status,
		})
	}
	return &ExecuteResult{Columns: columns, Rows: rows}, nil
}

func optionalStringArg(args []interface{}, idx int) (string, error) {
	if idx >= len(args) || args[idx] == nil {
		return "", nil
	}
	s, ok := args[idx].(string)
	if !ok {
		return "", localizedError(localization.CypherKnowledgePolicyArgumentStringRequired(idx+1), nil)
	}
	return strings.TrimSpace(s), nil
}

func splitCSVLabels(labelsCSV string) []string {
	parts := strings.Split(labelsCSV, ",")
	labels := make([]string, 0, len(parts))
	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed != "" {
			labels = append(labels, trimmed)
		}
	}
	return labels
}

func loadAccessMeta(eng storage.Engine, entityID string) *knowledgepolicy.AccessMetaEntry {
	be := unwrapBadgerEngine(eng)
	if be == nil {
		return nil
	}
	meta, err := be.GetAccessMeta(storage.QualifiedEntityID(eng, entityID))
	if err != nil {
		return nil
	}
	return meta
}

package cypher

import (
	"container/heap"
	"context"
	"sort"
	"strings"

	"github.com/orneryd/nornicdb/pkg/storage"
)

func (e *StorageExecutor) parseIndexedNodeOrderSpecs(orderExpr, variable string) ([]nodeOrderSpec, bool) {
	parts := splitOutsideParens(orderExpr, ',')
	if len(parts) == 0 || variable == "" {
		return nil, false
	}
	prefix := variable + "."
	for _, part := range parts {
		fields := strings.Fields(strings.TrimSpace(part))
		if len(fields) == 0 || !strings.HasPrefix(fields[0], prefix) {
			return nil, false
		}
	}
	specs := e.parseNodeOrderSpecs(orderExpr, variable)
	return specs, len(specs) == len(parts)
}

func (e *StorageExecutor) indexedOrderRequiresNonNull(variable, property, where string) bool {
	for _, term := range splitTopLevelAndConjuncts(unwrapOuterParens(strings.TrimSpace(where))) {
		required, ok := e.parseSimpleIndexedIsNotNull(variable, unwrapOuterParens(strings.TrimSpace(term)))
		if ok && strings.EqualFold(required, property) {
			return true
		}
	}
	return false
}

// indexedOrderHeap retains only the requested window; its root is the worst
// candidate under the complete ORDER BY comparator.
type indexedOrderHeap struct {
	nodes   []*storage.Node
	compare func(*storage.Node, *storage.Node) int
}

func (h indexedOrderHeap) Len() int                { return len(h.nodes) }
func (h indexedOrderHeap) Less(i, j int) bool      { return h.compare(h.nodes[i], h.nodes[j]) > 0 }
func (h indexedOrderHeap) Swap(i, j int)           { h.nodes[i], h.nodes[j] = h.nodes[j], h.nodes[i] }
func (h *indexedOrderHeap) Push(value interface{}) { h.nodes = append(h.nodes, value.(*storage.Node)) }
func (h *indexedOrderHeap) Pop() interface{} {
	last := len(h.nodes) - 1
	value := h.nodes[last]
	h.nodes[last] = nil
	h.nodes = h.nodes[:last]
	return value
}

// collectIndexedOrderWindow applies filtering and all sort keys before
// truncation. A primary-key group may be much larger than the requested page;
// only the best limit nodes are retained while every boundary tie is examined.
// bounds (impliedPropertyBounds) skips the primary-key groups where can't
// match.
func (e *StorageExecutor) collectIndexedOrderWindow(ctx context.Context, pattern nodePatternInfo, where string, specs []nodeOrderSpec, label string, limit int, bounds storage.PropertyIndexBounds) ([]*storage.Node, bool, error) {
	schema := orderedPropertyIndexSchema(e.storage)
	if schema == nil {
		return nil, false, nil
	}
	compareWithinGroup := func(a, b *storage.Node) int {
		if cmp := e.compareNodeOrderSpecs(a, b, specs); cmp != 0 {
			return cmp
		}
		return strings.Compare(string(a.ID), string(b.ID))
	}
	nodes := make([]*storage.Node, 0, limit)
	var filter func(*storage.Node) bool
	if strings.TrimSpace(where) != "" {
		filter = e.compileNodeWhereFilter(ctx, pattern.variable, where)
	}
	var visitErr error
	visited := false
	found := schema.VisitPropertyIndexGroupsInRange(label, specs[0].propName, specs[0].descending, bounds, func(ids []storage.NodeID) bool {
		visited = true
		remaining := limit - len(nodes)
		groupTop := &indexedOrderHeap{
			nodes:   make([]*storage.Node, 0, min(remaining, len(ids))),
			compare: compareWithinGroup,
		}
		for _, id := range ids {
			if err := ctx.Err(); err != nil {
				visitErr = err
				return false
			}
			node, err := e.getQueryNode(e.storage, id)
			if err != nil || node == nil {
				continue
			}
			if (len(pattern.labels) > 0 && !nodeHasAnyLabel(node, pattern.labels)) || !e.nodeMatchesProps(node, pattern.properties) {
				continue
			}
			if filter != nil && !filter(node) {
				continue
			}
			if groupTop.Len() < remaining {
				heap.Push(groupTop, node)
			} else if compareWithinGroup(node, groupTop.nodes[0]) < 0 {
				groupTop.nodes[0] = node
				heap.Fix(groupTop, 0)
			}
		}
		sort.Slice(groupTop.nodes, func(i, j int) bool {
			return compareWithinGroup(groupTop.nodes[i], groupTop.nodes[j]) < 0
		})
		nodes = append(nodes, groupTop.nodes...)
		if len(nodes) == limit {
			return false
		}
		return true
	})
	if visitErr != nil {
		return nil, false, visitErr
	}
	if !found || !visited {
		return nil, false, nil
	}
	return nodes, true, nil
}

package cypher

import (
	"context"
	"fmt"
	"sort"
	"strconv"
	"strings"

	"github.com/orneryd/nornicdb/pkg/storage"
	"github.com/orneryd/nornicdb/pkg/util"
)

// indexSeekConstant evaluates the value side of a predicate an index seek
// answers. The seek may use literals, parameters and values already bound
// in the incoming scope, including functions and property access over them.
// Unbound candidate variables are not constants of that incoming scope.
// Otherwise ok is false and the predicate is left to the row filter. Reading
// the value with the literal parser looked up a function call as its own
// text and returned no rows (#844).
func (e *StorageExecutor) indexSeekConstant(ctx context.Context, expr string) (value interface{}, ok bool) {
	expr = strings.TrimSpace(expr)
	if expr == "" {
		return nil, false
	}
	for _, variable := range expressionFreeVariables(ctx, expr) {
		if _, bound := e.boundValue(ctx, variable); !bound {
			return nil, false
		}
	}
	value, ok = e.evaluateRowExpressionWithContext(ctx, expr, e.fabricRecordBindings)
	if !ok {
		return nil, false
	}
	return normalizePropValue(value), true
}

// idEqualityLookup reads a WHERE that is one id(<variable>) = <value> or
// elementId(<variable>) = <value> comparison: the variable, and the storage
// ID the value names (an element ID's payload; elementKind is "4" for nodes,
// "5" for relationships). empty is true when the value is null, not a string
// or blank, which matches nothing; ok is false for any other WHERE.
func (e *StorageExecutor) idEqualityLookup(ctx context.Context, whereClause, elementKind string) (variable, lookupID string, empty, ok bool) {
	clause := strings.TrimSpace(whereClause)
	if clause == "" {
		return "", "", false, false
	}

	upper := upperASCII(clause)
	if strings.Contains(upper, " AND ") || strings.Contains(upper, " OR ") || strings.Contains(upper, " IN ") {
		return "", "", false, false
	}

	eqIdx := strings.Index(clause, "=")
	if eqIdx <= 0 {
		return "", "", false, false
	}
	// Ignore >=, <=, !=, <>
	if prev := clause[eqIdx-1]; prev == '!' || prev == '<' || prev == '>' {
		return "", "", false, false
	}
	if eqIdx+1 < len(clause) && clause[eqIdx+1] == '=' {
		return "", "", false, false
	}

	left := strings.TrimSpace(clause[:eqIdx])
	right := strings.TrimSpace(clause[eqIdx+1:])
	if left == "" || right == "" {
		return "", "", false, false
	}

	kind := ""
	lowerLeft := lowerASCII(left)
	switch {
	case strings.HasPrefix(lowerLeft, "id(") && strings.HasSuffix(left, ")"):
		kind = "id"
		variable = strings.TrimSpace(left[3 : len(left)-1])
	case strings.HasPrefix(lowerLeft, "elementid(") && strings.HasSuffix(left, ")"):
		kind = "elementId"
		variable = strings.TrimSpace(left[10 : len(left)-1])
	default:
		return "", "", false, false
	}
	if variable == "" {
		return "", "", false, false
	}

	rawVal, constant := e.indexSeekConstant(ctx, right)
	if !constant {
		return "", "", false, false
	}
	idValue, isString := rawVal.(string)
	if !isString || strings.TrimSpace(idValue) == "" {
		return variable, "", true, true
	}
	lookupID = strings.TrimSpace(idValue)
	// Equality and IN consume the same qualified reference as graph readers.
	lookupID, found, applicable := e.entitySeekLookup(lookupID, elementKind, kind)
	if !applicable {
		return "", "", false, false
	}
	if !found {
		return variable, "", true, true
	}
	return variable, lookupID, false, true
}

// entitySeekLookup retains the database until the selected engine accepts it.
// Unqualified strings retain the existing raw-ID extension.
func (e *StorageExecutor) entitySeekLookup(value, kind, function string) (string, bool, bool) {
	actual, database, local, qualified := storage.ParseElementID(value)
	if function != "elementId" && !strings.HasPrefix(value, kind+":") {
		qualified = false
	}
	if !qualified {
		// A raw local ID may match several sources. Leave that kept extension
		// to the normal predicate rather than certifying a single-node seek.
		if storage.CompositeDatabaseOf(e.storage) != "" {
			return "", false, false
		}
		return value, true, true
	}
	if actual != kind {
		return "", false, true
	}
	if storage.CompositeDatabaseOf(e.storage) == "" && e.graphIdentityDomain().foreignQualifier(database) {
		return "", false, true
	}
	if storage.CompositeDatabaseOf(e.storage) == "" {
		return local, true, true
	}
	id, found := (storage.EntityIdentity{Database: database, LocalID: local}).LookupID(e.storage, kind)
	return id, found, true
}

// tryCollectNodesFromIDEquality attempts to satisfy:
//
//	MATCH (n[:Label]) WHERE id(n) = <id>
//	MATCH (n[:Label]) WHERE elementId(n) = <element-id>
//
// via a direct node lookup instead of scanning all nodes.
func (e *StorageExecutor) tryCollectNodesFromIDEquality(ctx context.Context, nodePattern nodePatternInfo, whereClause string) ([]*storage.Node, bool, error) {
	varName, lookupID, empty, ok := e.idEqualityLookup(ctx, whereClause, "4")
	if !ok || varName != nodePattern.variable {
		return nil, false, nil
	}
	if empty {
		return []*storage.Node{}, true, nil
	}

	node, err := e.getQueryNode(e.storage, storage.NodeID(lookupID))
	if err != nil || node == nil {
		return []*storage.Node{}, true, nil
	}

	if len(nodePattern.labels) > 0 && !mergeNodeHasLabels(node, nodePattern.labels) {
		return []*storage.Node{}, true, nil
	}

	if len(nodePattern.properties) > 0 {
		for k, v := range nodePattern.properties {
			if node.Properties[k] != v {
				return []*storage.Node{}, true, nil
			}
		}
	}

	return []*storage.Node{node}, true, nil
}

// tryCollectNodesFromIDEqualityParam attempts to satisfy:
//
//	MATCH (n[:Label]) WHERE id(n) = $param
//	MATCH (n[:Label]) WHERE elementId(n) = $param
//
// via a direct node lookup using the parameter value. This complements
// tryCollectNodesFromIDEquality which only handles literal values on the RHS.
// The parameter-aware variant is critical for app workloads that always pass
// IDs as parameters (e.g., attach/read-by-id paths).
func (e *StorageExecutor) tryCollectNodesFromIDEqualityParam(
	ctx context.Context,
	nodePattern nodePatternInfo,
	whereClause string,
	params map[string]interface{},
) ([]*storage.Node, bool, error) {
	if params == nil || strings.TrimSpace(whereClause) == "" {
		return nil, false, nil
	}
	clause := strings.TrimSpace(whereClause)

	upper := upperASCII(clause)
	if strings.Contains(upper, " AND ") || strings.Contains(upper, " OR ") || strings.Contains(upper, " IN ") {
		return nil, false, nil
	}

	eqIdx := strings.Index(clause, "=")
	if eqIdx <= 0 {
		return nil, false, nil
	}
	if eqIdx > 0 {
		prev := clause[eqIdx-1]
		if prev == '!' || prev == '<' || prev == '>' {
			return nil, false, nil
		}
	}
	if eqIdx+1 < len(clause) {
		next := clause[eqIdx+1]
		if next == '=' {
			return nil, false, nil
		}
	}

	left := strings.TrimSpace(clause[:eqIdx])
	right := strings.TrimSpace(clause[eqIdx+1:])
	if left == "" || right == "" {
		return nil, false, nil
	}

	// RHS must be a parameter reference ($paramName).
	if !strings.HasPrefix(right, "$") {
		return nil, false, nil
	}
	paramName := strings.TrimSpace(right[1:])
	if paramName == "" {
		return nil, false, nil
	}

	kind := ""
	varName := ""
	lowerLeft := lowerASCII(left)
	switch {
	case strings.HasPrefix(lowerLeft, "id(") && strings.HasSuffix(left, ")"):
		kind = "id"
		varName = strings.TrimSpace(left[3 : len(left)-1])
	case strings.HasPrefix(lowerLeft, "elementid(") && strings.HasSuffix(left, ")"):
		kind = "elementId"
		varName = strings.TrimSpace(left[10 : len(left)-1])
	default:
		return nil, false, nil
	}

	if varName == "" || varName != nodePattern.variable {
		return nil, false, nil
	}

	raw, ok := params[paramName]
	if !ok {
		return []*storage.Node{}, true, nil
	}
	idValue, ok := raw.(string)
	if !ok || strings.TrimSpace(idValue) == "" {
		return []*storage.Node{}, true, nil
	}
	idValue = strings.TrimSpace(idValue)

	lookupID, found, applicable := e.entitySeekLookup(idValue, "4", kind)
	if !applicable {
		return nil, false, nil
	}
	if !found {
		return []*storage.Node{}, true, nil
	}

	node, err := e.getQueryNode(e.storage, storage.NodeID(lookupID))
	if err != nil || node == nil {
		return []*storage.Node{}, true, nil
	}

	if len(nodePattern.labels) > 0 && !mergeNodeHasLabels(node, nodePattern.labels) {
		return []*storage.Node{}, true, nil
	}

	if len(nodePattern.properties) > 0 {
		for k, v := range nodePattern.properties {
			if node.Properties[k] != v {
				return []*storage.Node{}, true, nil
			}
		}
	}

	return []*storage.Node{node}, true, nil
}

// tryCollectNodesFromIDEqualityCompound attempts ID/elementId direct seeks from
// simple and compound predicates over a single MATCH variable.
//
// Supported safe forms:
//   - id(n) = '...'
//   - elementId(n) = '...'
//   - id(n) = $param
//   - (... AND id(n) = ...)
//   - (id(n) = ... OR n.id = ... ) where every OR branch is an ID-equality form
//
// For OR predicates, this helper only engages when all disjuncts are recognized
// ID-equality predicates; otherwise it returns (nil, false, nil) to avoid unsafe
// pruning.
func (e *StorageExecutor) tryCollectNodesFromIDEqualityCompound(
	ctx context.Context,
	nodePattern nodePatternInfo,
	whereClause string,
	params map[string]interface{},
) ([]*storage.Node, bool, error) {
	clause := unwrapOuterParens(strings.TrimSpace(whereClause))
	if clause == "" {
		return nil, false, nil
	}

	// 1) Simple clause (literal or param).
	if nodes, used, err := e.tryCollectNodesFromIDEquality(ctx, nodePattern, clause); used || err != nil {
		return nodes, used, err
	}
	if nodes, used, err := e.tryCollectNodesFromIDEqualityParam(ctx, nodePattern, clause, params); used || err != nil {
		return nodes, used, err
	}

	// 2) Conjunction: any recognized id-conjunct is safe to use as a pruning seek.
	if findTopLevelKeyword(clause, " AND ") > 0 {
		for _, raw := range splitTopLevelAndConjuncts(clause) {
			term := unwrapOuterParens(strings.TrimSpace(raw))
			if term == "" {
				continue
			}
			if nodes, used, err := e.tryCollectNodesFromIDEquality(ctx, nodePattern, term); used || err != nil {
				return nodes, used, err
			}
			if nodes, used, err := e.tryCollectNodesFromIDEqualityParam(ctx, nodePattern, term, params); used || err != nil {
				return nodes, used, err
			}
		}
	}

	// 3) Disjunction: only safe when every branch is recognized as an ID seek.
	orTerms := splitTopLevelOrTerms(clause)
	if len(orTerms) > 1 {
		merged := make([]*storage.Node, 0, len(orTerms))
		seen := make(map[storage.NodeID]struct{}, len(orTerms))
		for _, raw := range orTerms {
			term := unwrapOuterParens(strings.TrimSpace(raw))
			if term == "" {
				return nil, false, nil
			}

			nodes, used, err := e.tryCollectNodesFromIDEquality(ctx, nodePattern, term)
			if err != nil {
				return nil, true, err
			}
			if !used {
				nodes, used, err = e.tryCollectNodesFromIDEqualityParam(ctx, nodePattern, term, params)
				if err != nil {
					return nil, true, err
				}
			}
			if !used {
				// At least one OR branch is not a recognized ID-equality predicate.
				// Bail out to preserve semantics.
				return nil, false, nil
			}

			for _, node := range nodes {
				if node == nil {
					continue
				}
				if _, ok := seen[node.ID]; ok {
					continue
				}
				seen[node.ID] = struct{}{}
				merged = append(merged, node)
			}
		}
		return merged, true, nil
	}

	return nil, false, nil
}

// tryCollectNodesFromPropertyIndex attempts to satisfy MATCH node candidates from a schema property index.
// It only applies to simple equality predicates:
//   - <var>.<prop> = <value>
//   - <value> = <var>.<prop>
//
// It returns (nodes, true, nil) when index planning was used (including empty matches),
// and (nil, false, nil) when the predicate is not eligible for index lookup.
func (e *StorageExecutor) tryCollectNodesFromPropertyIndex(ctx context.Context, nodePattern nodePatternInfo, whereClause string) ([]*storage.Node, bool, error) {
	return e.tryCollectNodesFromPropertyIndexAnyOf(ctx, nodePattern, whereClause, nil)
}

// tryCollectNodesFromPropertyIndexAnyOf is tryCollectNodesFromPropertyIndex
// for a node that must carry one of anyOf (a WHERE label disjunction, #858;
// nil when there is none): see seekCandidateLabels.
func (e *StorageExecutor) tryCollectNodesFromPropertyIndexAnyOf(ctx context.Context, nodePattern nodePatternInfo, whereClause string, anyOf []string) ([]*storage.Node, bool, error) {
	property, value, ok := e.parseSimpleIndexedEquality(ctx, nodePattern.variable, whereClause)
	if !ok {
		return nil, false, nil
	}

	schema := e.storage.GetSchema()
	if schema == nil {
		return nil, false, nil
	}

	labels, anyOf := e.seekCandidateLabels(schema, nodePattern.labels, property, anyOf)
	if len(labels) == 0 {
		return nil, false, nil
	}

	idSet := make(map[storage.NodeID]struct{})
	for _, label := range labels {
		for _, id := range propertyIndexLookup(e.storage, schema, label, property, value) {
			idSet[id] = struct{}{}
		}
	}

	if len(idSet) == 0 {
		return []*storage.Node{}, true, nil
	}

	nodes := make([]*storage.Node, 0, len(idSet))
	ids := make([]string, 0, len(idSet))
	for id := range idSet {
		ids = append(ids, string(id))
	}
	sort.Strings(ids)
	for _, id := range ids {
		node, err := e.getQueryNode(e.storage, storage.NodeID(id))
		if err != nil || node == nil {
			continue
		}
		if !seekCandidateHasLabels(node, nodePattern.labels, anyOf) {
			continue
		}
		actual, exists := node.Properties[property]
		if !exists {
			continue
		}
		equal := cypherEquality(actual, value)
		if matched, known := equal.(bool); !known || !matched {
			continue
		}
		nodes = append(nodes, node)
	}

	return nodes, true, nil
}

// tryCollectNodesFromPropertyIndexIn attempts to satisfy simple IN-list predicates:
//
//	<var>.<prop> IN $param
//
// where $param is a list value from params. This path is used heavily by Fabric
// batched correlated APPLY lookups.
func (e *StorageExecutor) tryCollectNodesFromPropertyIndexIn(
	nodePattern nodePatternInfo,
	whereClause string,
	params map[string]interface{},
) ([]*storage.Node, bool, error) {
	return e.tryCollectNodesFromPropertyIndexInAnyOf(nodePattern, whereClause, params, nil)
}

// tryCollectNodesFromPropertyIndexInAnyOf is tryCollectNodesFromPropertyIndexIn
// for a node that must carry one of anyOf (see seekCandidateLabels).
func (e *StorageExecutor) tryCollectNodesFromPropertyIndexInAnyOf(
	nodePattern nodePatternInfo,
	whereClause string,
	params map[string]interface{},
	anyOf []string,
) ([]*storage.Node, bool, error) {
	property, listValues, ok := e.parseSimpleIndexedInParam(nodePattern.variable, whereClause, params)
	if !ok {
		return nil, false, nil
	}

	schema := e.storage.GetSchema()
	if schema == nil {
		return nil, false, nil
	}
	labels, anyOf := e.seekCandidateLabels(schema, nodePattern.labels, property, anyOf)
	if len(labels) == 0 {
		return nil, false, nil
	}

	idSet := make(map[storage.NodeID]struct{}, 256)
	for _, label := range labels {
		for _, value := range listValues {
			for _, id := range propertyIndexLookup(e.storage, schema, label, property, value) {
				idSet[id] = struct{}{}
			}
		}
	}
	if len(idSet) == 0 {
		return []*storage.Node{}, true, nil
	}

	nodes := make([]*storage.Node, 0, len(idSet))
	ids := make([]string, 0, len(idSet))
	for id := range idSet {
		ids = append(ids, string(id))
	}
	sort.Strings(ids)
	for _, id := range ids {
		node, err := e.getQueryNode(e.storage, storage.NodeID(id))
		if err != nil || node == nil {
			continue
		}
		if !seekCandidateHasLabels(node, nodePattern.labels, anyOf) {
			continue
		}
		nodes = append(nodes, node)
	}
	return nodes, true, nil
}

// tryCollectNodesFromPropertyIndexInLiteral attempts to satisfy simple IN-list
