// tryCollectNodesFromPropertyIndexInCompound attempts to satisfy an IN-list
// start-node predicate from a schema property index, including when the
// IN-list conjunct is combined with other predicates via AND — e.g. a
// relationship-pattern traversal's WHERE clause that also filters a bound
// relationship variable, as in `WHERE s.uid IN $u AND rel.evidence_source =
// $e`. Only a single AND conjunct needs to match an indexed property IN-list
// for pruning to be safe: the caller (executeMatchWithRelationshipsWithPath)
// always re-applies the full WHERE clause via filterPathsByWhere afterward,
// so seeding from one recognized conjunct can only over-fetch, never
// under-fetch, and correctness does not depend on this helper understanding
// the rest of the clause.
//
// Mirrors tryCollectNodesFromIDEqualityCompound's AND-conjunct handling
// (match_index_seek.go) for the IN-list case. Tries the param-bound form
// first, then the literal-list form, at both the top level and inside each
// top-level AND conjunct.
func (e *StorageExecutor) tryCollectNodesFromPropertyIndexInCompound(
	ctx context.Context,
	nodePattern nodePatternInfo,
	whereClause string,
	params map[string]interface{},
) ([]*storage.Node, bool, error) {
	clause := unwrapOuterParens(strings.TrimSpace(whereClause))
	if clause == "" {
		return nil, false, nil
	}

	// 1) Simple clause (param or literal list).
	if nodes, used, err := e.tryCollectNodesFromPropertyIndexIn(nodePattern, clause, params); used || err != nil {
		return nodes, used, err
	}
	if nodes, used, err := e.tryCollectNodesFromPropertyIndexInLiteral(ctx, nodePattern, clause); used || err != nil {
		return nodes, used, err
	}

	// 2) Conjunction: any recognized IN-list conjunct is safe to use as a
	// pruning seek (see over-fetch-only argument in the doc comment above).
	// A label disjunction among the conjuncts names the labels a match must
	// carry, for a pattern without labels (#858).
	if findTopLevelKeyword(clause, " AND ") > 0 {
		conjuncts := splitTopLevelAndConjuncts(clause)
		anyOf := whereLabelDisjunctionConjunct(nodePattern.variable, conjuncts)
		for _, raw := range conjuncts {
			term := unwrapOuterParens(strings.TrimSpace(raw))
			if term == "" {
				continue
			}
			if nodes, used, err := e.tryCollectNodesFromPropertyIndexInAnyOf(nodePattern, term, params, anyOf); used || err != nil {
				return nodes, used, err
			}
			if nodes, used, err := e.tryCollectNodesFromPropertyIndexInLiteralAnyOf(ctx, nodePattern, term, anyOf); used || err != nil {
				return nodes, used, err
			}
		}
	}

	return nil, false, nil
}

// tryCollectNodesFromPropertyIndexEqualityCompound attempts to satisfy a
// start-node predicate from a schema property index when an equality on an
// indexed property is combined with other predicates via AND — e.g.
// `WHERE n.repo_id = $repo_id AND n.evidence_source = 'x' AND
// n.generation_id <> $gen`. Only a single AND conjunct needs to match an
// indexed property equality for pruning to be safe: every caller
// re-applies the full WHERE clause afterward, so seeding from one
// recognized conjunct can only over-fetch, never under-fetch, and
// correctness does not depend on this helper understanding the rest of the
// clause.
//
// Mirrors tryCollectNodesFromPropertyIndexInCompound's AND-conjunct handling
// (match_index_seek.go) for the plain-equality case. Tries the whole clause
// first (the simple form), then each top-level AND conjunct in order.
func (e *StorageExecutor) tryCollectNodesFromPropertyIndexEqualityCompound(
	ctx context.Context,
	nodePattern nodePatternInfo,
	whereClause string,
) ([]*storage.Node, bool, error) {
	clause := unwrapOuterParens(strings.TrimSpace(whereClause))
	if clause == "" {
		return nil, false, nil
	}

	// 1) Simple clause (a lone equality, no conjunction).
	if nodes, used, err := e.tryCollectNodesFromPropertyIndex(ctx, nodePattern, clause); used || err != nil {
		return nodes, used, err
	}

	// 2) Conjunction: any equality conjunct on an indexed property is safe
	// to use as a pruning seek (see over-fetch-only argument in the doc
	// comment above). A label disjunction among the conjuncts
	// (n.id = $id AND (n:A OR n:B)) names the labels a match must carry, for
	// a pattern without labels (#858).
	if findTopLevelKeyword(clause, " AND ") > 0 {
		conjuncts := splitTopLevelAndConjuncts(clause)
		anyOf := whereLabelDisjunctionConjunct(nodePattern.variable, conjuncts)
		for _, raw := range conjuncts {
			term := unwrapOuterParens(strings.TrimSpace(raw))
			if term == "" {
				continue
			}
			if nodes, used, err := e.tryCollectNodesFromPropertyIndexAnyOf(ctx, nodePattern, term, anyOf); used || err != nil {
				return nodes, used, err
			}
		}
	}

	return nil, false, nil
}

// tryCollectNodesFromPropertyIndexInOrParam attempts to satisfy OR-combined IN
// predicates backed by indexes, e.g.:
//
//	n.textKey IN $keys OR n.textKey128 IN $keys
//
// This is important for cleanup/read paths that pass large key lists and would
// otherwise full-scan labels.
func (e *StorageExecutor) tryCollectNodesFromPropertyIndexInOrParam(
	nodePattern nodePatternInfo,
	whereClause string,
	params map[string]interface{},
) ([]*storage.Node, bool, error) {
	clause := strings.TrimSpace(whereClause)
	if clause == "" || params == nil {
		return nil, false, nil
	}
	orIdx := findTopLevelKeyword(clause, " OR ")
	if orIdx <= 0 {
		return nil, false, nil
	}
	left := strings.TrimSpace(clause[:orIdx])
	right := strings.TrimSpace(clause[orIdx+4:])
	if left == "" || right == "" {
		return nil, false, nil
	}

	lprop, lvals, lok := e.parseSimpleIndexedInParam(nodePattern.variable, left, params)
	rprop, rvals, rok := e.parseSimpleIndexedInParam(nodePattern.variable, right, params)
	if !lok || !rok {
		return nil, false, nil
	}

	// Merge values (keep deterministic and duplicate-free).
	merged := make([]interface{}, 0, util.SafePreallocSum(len(lvals), len(rvals)))
	seenVals := make(map[string]struct{}, util.SafePreallocSum(len(lvals), len(rvals)))
	for _, v := range append(lvals, rvals...) {
		if v == nil {
			continue
		}
		k := fmt.Sprintf("%T:%v", v, v)
		if _, ok := seenVals[k]; ok {
			continue
		}
		seenVals[k] = struct{}{}
		merged = append(merged, v)
	}

	schema := e.storage.GetSchema()
	if schema == nil {
		return nil, false, nil
	}

	leftLabels := e.indexCandidateLabels(schema, nodePattern.labels, lprop)
	rightLabels := e.indexCandidateLabels(schema, nodePattern.labels, rprop)
	if len(leftLabels) == 0 || len(rightLabels) == 0 {
		return nil, false, nil
	}

	idSet := make(map[storage.NodeID]struct{}, 256)
	for _, label := range leftLabels {
		for _, v := range merged {
			for _, id := range propertyIndexLookup(e.storage, schema, label, lprop, v) {
				idSet[id] = struct{}{}
			}
		}
	}
	for _, label := range rightLabels {
		for _, v := range merged {
			for _, id := range propertyIndexLookup(e.storage, schema, label, rprop, v) {
				idSet[id] = struct{}{}
			}
		}
	}
	if len(idSet) == 0 {
		return []*storage.Node{}, true, nil
	}

	nodes := make([]*storage.Node, 0, len(idSet))
	ids := make([]string, 0, len(idSet))
	for id := range idSet {
		ids = append(ids, string(id))
	}
	sort.Strings(ids)
	for _, id := range ids {
		node, err := e.getQueryNode(e.storage, storage.NodeID(id))
		if err != nil || node == nil {
			continue
		}
		if len(nodePattern.labels) > 0 && !mergeNodeHasLabels(node, nodePattern.labels) {
			continue
		}
		nodes = append(nodes, node)
	}
	return nodes, true, nil
}

// tryCollectNodesFromPropertyIndexOrEquality attempts to satisfy OR-combined
// equality predicates backed by indexes, e.g.:
//
//	a.prop1 = $x OR a.prop2 = $x
//	a.prop1 = 'val1' OR a.prop2 = 'val2'
//
// It splits the OR into two branches, attempts index lookup on each, and merges
// results with deduplication. This removes a major source of slow scans for
// dual-key lookup workloads.
func (e *StorageExecutor) tryCollectNodesFromPropertyIndexOrEquality(
	ctx context.Context,
	nodePattern nodePatternInfo,
	whereClause string,
	params map[string]interface{},
) ([]*storage.Node, bool, error) {
	clause := strings.TrimSpace(whereClause)
	if clause == "" {
		return nil, false, nil
	}
	orIdx := findTopLevelKeyword(clause, " OR ")
	if orIdx <= 0 {
		return nil, false, nil
	}
	left := strings.TrimSpace(clause[:orIdx])
	right := strings.TrimSpace(clause[orIdx+4:])
	if left == "" || right == "" {
		return nil, false, nil
	}

	// Try to parse each branch as a simple indexed equality predicate.
	lprop, lval, lok := e.parseSimpleIndexedEquality(ctx, nodePattern.variable, left)
	rprop, rval, rok := e.parseSimpleIndexedEquality(ctx, nodePattern.variable, right)
	if !lok || !rok {
		return nil, false, nil
	}

	schema := e.storage.GetSchema()
	if schema == nil {
		return nil, false, nil
	}

	leftLabels := e.indexCandidateLabels(schema, nodePattern.labels, lprop)
	rightLabels := e.indexCandidateLabels(schema, nodePattern.labels, rprop)
	if len(leftLabels) == 0 && len(rightLabels) == 0 {
		return nil, false, nil
	}

	idSet := make(map[storage.NodeID]struct{}, 64)
	for _, label := range leftLabels {
		for _, id := range propertyIndexLookup(e.storage, schema, label, lprop, lval) {
			idSet[id] = struct{}{}
		}
	}
	for _, label := range rightLabels {
		for _, id := range propertyIndexLookup(e.storage, schema, label, rprop, rval) {
			idSet[id] = struct{}{}
		}
	}
	if len(idSet) == 0 {
		return []*storage.Node{}, true, nil
	}

	nodes := make([]*storage.Node, 0, len(idSet))
	ids := make([]string, 0, len(idSet))
	for id := range idSet {
		ids = append(ids, string(id))
	}
	sort.Strings(ids)
	for _, id := range ids {
		node, err := e.getQueryNode(e.storage, storage.NodeID(id))
		if err != nil || node == nil {
			continue
		}
		if len(nodePattern.labels) > 0 && !mergeNodeHasLabels(node, nodePattern.labels) {
			continue
		}
		nodes = append(nodes, node)
	}
	return nodes, true, nil
}

// tryCollectNodesFromIDIn attempts to satisfy simple id/elementId IN-list predicates:
//
//	id(<var>) IN $param
//	elementId(<var>) IN $param
//	id(<var>) IN ['id-1', $other, …]
//
// The list is a query parameter, or any constant list: a literal, a list of
// parameters, or a parameter the executor already substituted into the query
// text (#940). A missing or non-list $param selects nothing, as before; a
// constant that isn't a list leaves the predicate to the evaluator. This
// provides direct node seeks for batched correlated lookups and avoids full
// scans.
func (e *StorageExecutor) tryCollectNodesFromIDIn(
	ctx context.Context,
	nodePattern nodePatternInfo,
	whereClause string,
	params map[string]interface{},
) ([]*storage.Node, bool, error) {
	clause := unwrapOuterParens(strings.TrimSpace(whereClause))
	if clause == "" {
		return nil, false, nil
	}
	upper := upperASCII(clause)
	inIdx := strings.Index(upper, " IN ")
	if inIdx <= 0 {
		return nil, false, nil
	}
	// Keep this strict/simple to avoid semantic drift for complex predicates.
	if strings.Contains(upper, " AND ") || strings.Contains(upper, " OR ") {
		return nil, false, nil
	}

	left := strings.TrimSpace(clause[:inIdx])
	right := strings.TrimSpace(clause[inIdx+4:])
	if left == "" || right == "" {
		return nil, false, nil
	}

	kind := ""
	varName := ""
	lowerLeft := lowerASCII(left)
	switch {
	case strings.HasPrefix(lowerLeft, "id(") && strings.HasSuffix(left, ")"):
		kind = "id"
		varName = strings.TrimSpace(left[3 : len(left)-1])
	case strings.HasPrefix(lowerLeft, "elementid(") && strings.HasSuffix(left, ")"):
		kind = "elementId"
		varName = strings.TrimSpace(left[10 : len(left)-1])
	default:
		return nil, false, nil
	}
	if varName == "" || varName != nodePattern.variable {
		return nil, false, nil
	}

	var list []interface{}
	if paramName := strings.TrimPrefix(right, "$"); paramName != right && isValidIdentifier(paramName) {
		if params == nil {
			return nil, false, nil
		}
		raw, ok := params[paramName]
		if !ok {
			return []*storage.Node{}, true, nil
		}
		list = toAnySlice(raw)
	} else {
		value, constant := e.indexSeekConstant(ctx, right)
		if !constant {
			return nil, false, nil
		}
		if value != nil {
			if list = toAnySlice(value); list == nil {
				return nil, false, nil
			}
		}
	}
	if len(list) == 0 {
		return []*storage.Node{}, true, nil
	}

	seen := make(map[string]struct{}, len(list))
	nodes := make([]*storage.Node, 0, len(list))
	for _, item := range list {
		s, ok := item.(string)
		if !ok {
			continue
		}
		lookupID := strings.TrimSpace(s)
		if lookupID == "" {
			continue
		}
		lookupID, found, applicable := e.entitySeekLookup(lookupID, "4", kind)
		if !applicable {
			return nil, false, nil
		}
		if !found {
			continue
		}
		if _, exists := seen[lookupID]; exists {
			continue
		}
		seen[lookupID] = struct{}{}

		node, err := e.getQueryNode(e.storage, storage.NodeID(lookupID))
		if err != nil || node == nil {
			continue
		}
		if len(nodePattern.labels) > 0 && !mergeNodeHasLabels(node, nodePattern.labels) {
			continue
		}
		if len(nodePattern.properties) > 0 && !e.nodeMatchesProps(node, nodePattern.properties) {
			continue
		}
		nodes = append(nodes, node)
	}

	return nodes, true, nil
}

// tryCollectNodesFromPropertyIndexOrderLimit attempts to satisfy ORDER BY + LIMIT
// queries using a property index for sorted iteration, even when the WHERE clause
// is not a simple IS NOT NULL predicate. It filters complete index-key groups
// into a bounded ordered window. This avoids a full label scan and sort when
// the non-null index can fill common pagination requests like:
//
//	MATCH (n:Label) WHERE <filter> ORDER BY n.createdAt DESC LIMIT 30
//
// It only applies when:
//   - The first ORDER BY property with a matching index exists
//   - The node pattern has at least one label
//   - limit > 0
//
// If the ORDER BY has multiple keys, the indexed property is used to fetch
// complete primary-key groups and all keys select the retained top-K window.
func (e *StorageExecutor) tryCollectNodesFromPropertyIndexOrderLimit(
	ctx context.Context,
	nodePattern nodePatternInfo,
	whereClause string,
	orderExpr string,
	limit int,
) ([]*storage.Node, bool, error) {
	if limit <= 0 || len(nodePattern.labels) == 0 {
		return nil, false, nil
	}

	orderSpecs, ok := e.parseIndexedNodeOrderSpecs(orderExpr, nodePattern.variable)
	if !ok {
		return nil, false, nil
	}
	spec := orderSpecs[0]
	// A WHERE that bounds the first sort property (n.t > $last, the keyset
	// form n.t > $t OR (n.t = $t AND n.id > $id)) starts the index scan at
	// the bound, and rules out rows where it is null (#939).
	bounds := impliedPropertyBounds(nodePattern.variable, spec.propName, whereClause, getParamsFromContext(ctx))
	primaryNonNull := bounds.HasLower || bounds.HasUpper || e.indexedOrderRequiresNonNull(nodePattern.variable, spec.propName, whereClause)
	if spec.descending && !primaryNonNull {
		return nil, false, nil
	}

	schema := orderedPropertyIndexSchema(e.storage)
	if schema == nil {
		return nil, false, nil
	}

	labels := e.indexCandidateLabels(schema, nodePattern.labels, spec.propName)
	if len(labels) != 1 {
		return nil, false, nil
	}
	label := labels[0]

	nodes, used, err := e.collectIndexedOrderWindow(ctx, nodePattern, whereClause, orderSpecs, label, limit, bounds)
	if err == nil && used && len(nodes) < limit {
		if primaryNonNull {
			return nodes, true, nil
		}
		// The property index omits null keys. An exhausted partial window is
		// not a complete general MATCH result: let normal selection include
		// qualifying nodes whose first sort property is absent.
		return nil, false, nil
	}
	return nodes, used, err
}

// tryCollectNodesFromPropertyIndexNotNullOrderLimit attempts to satisfy:
//
//	MATCH (n:Label) WHERE n.prop IS NOT NULL RETURN ... ORDER BY n.prop [ASC|DESC] LIMIT K
//
// using the property index directly (top-K by indexed key) without label scan.
func (e *StorageExecutor) tryCollectNodesFromPropertyIndexNotNullOrderLimit(
	ctx context.Context,
	nodePattern nodePatternInfo,
	whereClause string,
	orderExpr string,
	limit int,
) ([]*storage.Node, bool, error) {
	if limit <= 0 || len(nodePattern.labels) == 0 {
		return nil, false, nil
	}

	whereProp, ok := e.parseSimpleIndexedIsNotNull(nodePattern.variable, whereClause)
	if !ok {
		return nil, false, nil
	}

	orderSpecs, ok := e.parseIndexedNodeOrderSpecs(orderExpr, nodePattern.variable)
	if !ok {
		return nil, false, nil
	}
	spec := orderSpecs[0]
	if !strings.EqualFold(strings.TrimSpace(spec.propName), strings.TrimSpace(whereProp)) {
		return nil, false, nil
	}

	schema := orderedPropertyIndexSchema(e.storage)
	if schema == nil {
		return nil, false, nil
	}

	labels := e.indexCandidateLabels(schema, nodePattern.labels, whereProp)
	if len(labels) != 1 {
		// Keep semantics simple/deterministic for now; multi-label merge ordering can be added later.
		return nil, false, nil
	}
	label := labels[0]
	return e.collectIndexedOrderWindow(ctx, nodePattern, whereClause, orderSpecs, label, limit, storage.PropertyIndexBounds{})
}

// tryCollectNodesFromPropertyIndexNotNull attempts to satisfy:
//
//	MATCH (n:Label) WHERE n.prop IS NOT NULL
//
// from schema index entries, avoiding label scans.
func (e *StorageExecutor) tryCollectNodesFromPropertyIndexNotNull(
	nodePattern nodePatternInfo,
	whereClause string,
) ([]*storage.Node, bool, error) {
	if len(nodePattern.labels) == 0 {
		return nil, false, nil
	}
	property, ok := e.parseSimpleIndexedIsNotNull(nodePattern.variable, whereClause)
	if !ok {
		return nil, false, nil
	}

	schema := orderedPropertyIndexSchema(e.storage)
	if schema == nil {
		return nil, false, nil
	}
	nodes, used := e.collectNodesFromIndexedProperty(schema, nodePattern, property, func(label string) ([]storage.NodeID, bool) {
		return schema.PropertyIndexAllNonNil(label, property, false), true
	})
	return nodes, used, nil
}

func (e *StorageExecutor) indexCandidateLabels(schema *storage.SchemaManager, queryLabels []string, property string) []string {
	if len(queryLabels) > 0 {
		out := make([]string, 0, len(queryLabels))
		for _, label := range queryLabels {
			if _, exists := schema.GetPropertyIndex(label, property); exists {
				out = append(out, label)
			}
		}
		return out
	}
	labels := make(map[string]struct{})
	for _, raw := range schema.GetIndexes() {
		idx, ok := raw.(map[string]interface{})
		if !ok {
			continue
		}
		typ, _ := idx["type"].(string)
		if !strings.EqualFold(strings.TrimSpace(typ), "PROPERTY") {
			continue
		}
		label, _ := idx["label"].(string)
		if strings.TrimSpace(label) == "" {
			continue
		}
		prop := ""
		if p, ok := idx["property"].(string); ok {
			prop = p
		}
		if prop == "" {
			if props, ok := idx["properties"].([]string); ok && len(props) == 1 {
				prop = props[0]
			}
			if prop == "" {
				if vals, ok := idx["properties"].([]interface{}); ok && len(vals) == 1 {
					if ps, ok := vals[0].(string); ok {
						prop = ps
					}
				}
			}
		}
		if !strings.EqualFold(strings.TrimSpace(prop), property) {
			continue
		}
		labels[label] = struct{}{}
	}

	out := make([]string, 0, len(labels))
	for label := range labels {
		out = append(out, label)
	}
	sort.Strings(out)
	if !labellessPropertyIndexUsable(e.storage, out...) {
		return nil
	}
	return out
}

// seekCandidateLabels returns the labels whose property indexes on property
// list every node a seek may return, and the label disjunction the candidates
// must satisfy (nil when none applies).
//
// A pattern with labels uses its indexed labels (indexCandidateLabels). A
// pattern without labels whose WHERE requires one of anyOf (n:A OR n:B, #858)
// uses those labels when every one of them has an index on property: any node
// the WHERE can match carries one of them, so the union of their index
// entries lists it, and Neo4j plans the same predicate as one index seek per
// label. When one of them has no index, the indexes can miss a match and the
// label-less route decides (labellessPropertyIndexUsable).
func (e *StorageExecutor) seekCandidateLabels(schema *storage.SchemaManager, patternLabels []string, property string, anyOf []string) ([]string, []string) {
	if len(patternLabels) == 0 && len(anyOf) > 0 {
		indexed := true
		for _, label := range anyOf {
			if _, exists := schema.GetPropertyIndex(label, property); !exists {
				indexed = false
				break
			}
		}
		if indexed {
			return anyOf, anyOf
		}
	}
	return e.indexCandidateLabels(schema, patternLabels, property), nil
}

// seekCandidateHasLabels reports whether a node an index listed still carries
// the pattern's labels and one of anyOf (when set): an index can list a node
// that has since lost the label.
func seekCandidateHasLabels(node *storage.Node, patternLabels, anyOf []string) bool {
	if len(patternLabels) > 0 && !mergeNodeHasLabels(node, patternLabels) {
		return false
	}
	return len(anyOf) == 0 || nodeHasAnyLabel(node, anyOf)
}

// whereLabelDisjunctionConjunct returns the labels of the first conjunct that
// is a label disjunction on variable (whereLabelDisjunction), or nil.
func whereLabelDisjunctionConjunct(variable string, conjuncts []string) []string {
	for _, conjunct := range conjuncts {
		if labels, ok := whereLabelDisjunction(variable, conjunct); ok {
			return labels
		}
	}
	return nil
}

// whereLabelDisjunction parses a WHERE term that requires variable to carry
// one of a set of labels: v:A, v:A OR v:B …, or the label expression v:A|B,
// with labels plain or backtick-quoted. A conjunction of labels (v:A:B) or any
// other term is not one.
func whereLabelDisjunction(variable, term string) ([]string, bool) {
	want, ok := isOneSymbolicName(variable)
	if !ok {
		return nil, false
	}
	var labels []string
	for _, alternative := range splitTopLevelOrTerms(unwrapOuterParens(strings.TrimSpace(term))) {
		alternative = unwrapOuterParens(strings.TrimSpace(alternative))
		written, end, ok := scanSymbolicName(alternative, 0)
		if !ok || symbolicNameValue(written) != want {
			return nil, false
		}
		rest := strings.TrimSpace(alternative[end:])
		if !strings.HasPrefix(rest, ":") {
			return nil, false
		}
		names := strings.TrimSpace(rest[1:])
		for {
			written, end, ok := scanSymbolicName(names, 0)
			if !ok {
				return nil, false
			}
			labels = append(labels, symbolicNameValue(written))
			names = strings.TrimSpace(names[end:])
			if names == "" {
				break
			}
			if names[0] != '|' {
				return nil, false
			}
			names = strings.TrimSpace(names[1:])
		}
	}
	return labels, len(labels) > 0
}

func (e *StorageExecutor) parseSimpleIndexedEquality(ctx context.Context, variable, whereClause string) (property string, value interface{}, ok bool) {
	clause := unwrapOuterParens(whereClause)
	if clause == "" {
		return "", nil, false
	}

	// Only simple predicates are index-eligible: a = 1 XOR true is not an
	// equality with (1 XOR true).
	if hasTopLevelLogicalOperator(clause) {
		return "", nil, false
	}
	for _, kw := range []string{"NOT", " IN ", " IS ", "<>", "!=", ">=", "<=", ">", "<"} {
		if topLevelKeywordIndex(clause, kw) >= 0 {
			return "", nil, false
		}
	}

	scan, comparison := scanComparisonChain(clause)
	if !comparison || scan.count != 1 {
		return "", nil, false
	}
	operator := scan.operator(0)
	if clause[operator.offset:operator.offset+operator.length] != "=" {
		return "", nil, false
	}
	left, right := scan.operand(clause, 0), scan.operand(clause, 1)
	if left == "" || right == "" {
		return "", nil, false
	}

	prop, isLeftVarProp := parseVariableProperty(left, variable)
	if isLeftVarProp {
		value, constant := e.indexSeekConstant(ctx, right)
		return prop, value, constant
	}
	prop, isRightVarProp := parseVariableProperty(right, variable)
	if isRightVarProp {
		value, constant := e.indexSeekConstant(ctx, left)
		return prop, value, constant
	}
	return "", nil, false
}

func (e *StorageExecutor) parseSimpleIndexedInParam(variable, whereClause string, params map[string]interface{}) (property string, values []interface{}, ok bool) {
	clause := strings.TrimSpace(whereClause)
	for strings.HasPrefix(clause, "(") && strings.HasSuffix(clause, ")") && len(clause) >= 2 {
		inner := strings.TrimSpace(clause[1 : len(clause)-1])
		if inner == clause {
			break
		}
		clause = inner
	}
	if clause == "" {
		return "", nil, false
	}
	// Keep this optimization deterministic and safe: only simple standalone IN predicates.
	if containsFold(clause, " AND ") || containsFold(clause, " OR ") {
		return "", nil, false
	}
	inIdx := keywordIndexFrom(clause, "IN", 0, defaultKeywordScanOpts())
	if inIdx <= 0 || inIdx >= len(clause)-2 {
		return "", nil, false
	}
	left := strings.TrimSpace(clause[:inIdx])
	right := strings.TrimSpace(clause[inIdx+2:])
	if !strings.HasPrefix(right, "$") {
		return "", nil, false
	}
	paramName := strings.TrimSpace(strings.TrimPrefix(right, "$"))
	if paramName == "" || params == nil {
		return "", nil, false
	}
	parsedProp, ok := parseVariableProperty(left, variable)
	if !ok {
		return "", nil, false
	}
	raw, exists := params[paramName]
	if !exists || raw == nil {
		return "", nil, false
	}
	list := coerceInterfaceList(raw)
	if len(list) == 0 {
		return "", []interface{}{}, true
	}
	out := make([]interface{}, 0, len(list))
	seen := make(map[string]struct{}, len(list))
	for _, v := range list {
		if v == nil {
			continue
		}
		k := fmt.Sprintf("%T:%v", v, v)
		if _, dup := seen[k]; dup {
			continue
		}
		seen[k] = struct{}{}
		out = append(out, v)
	}
	return parsedProp, out, true
}

func (e *StorageExecutor) parseSimpleIndexedInLiteral(ctx context.Context, variable, whereClause string) (property string, values []interface{}, ok bool) {
	clause := strings.TrimSpace(whereClause)
	for strings.HasPrefix(clause, "(") && strings.HasSuffix(clause, ")") && len(clause) >= 2 {
		inner := strings.TrimSpace(clause[1 : len(clause)-1])
		if inner == clause {
			break
		}
		clause = inner
	}
	if clause == "" {
		return "", nil, false
	}
	// Keep this optimization deterministic and safe: only simple standalone IN predicates.
	if containsFold(clause, " AND ") || containsFold(clause, " OR ") {
		return "", nil, false
	}
	inIdx := keywordIndexFrom(clause, "IN", 0, defaultKeywordScanOpts())
	if inIdx <= 0 || inIdx >= len(clause)-2 {
		return "", nil, false
	}
	left := strings.TrimSpace(clause[:inIdx])
	right := strings.TrimSpace(clause[inIdx+2:])
	if left == "" || right == "" {
		return "", nil, false
	}
	parsedProp, ok := parseVariableProperty(left, variable)
	if !ok {
		return "", nil, false
	}
	if !isListLiteral(right) {
		return "", nil, false
	}
	rawList, constant := e.indexSeekConstant(ctx, right)
	if !constant {
		return "", nil, false
	}
	list := coerceInterfaceList(rawList)
	if len(list) == 0 {
		return parsedProp, []interface{}{}, true
	}
	out := make([]interface{}, 0, len(list))
	seen := make(map[string]struct{}, len(list))
	for _, v := range list {
		if v == nil {
			continue
		}
		k := fmt.Sprintf("%T:%v", v, v)
		if _, dup := seen[k]; dup {
			continue
		}
		seen[k] = struct{}{}
		out = append(out, v)
	}
	return parsedProp, out, true
}

// coerceInterfaceList returns a parameter list's elements as Cypher values
// (cypherListValue), or nil when the value isn't a list; a non-list IN
// parameter is rejected before execution (validateMembershipParameters).
func coerceInterfaceList(v interface{}) []interface{} {
	items, _ := cypherListValue(v)
	return items
}

func (e *StorageExecutor) parseSimpleIndexedIsNotNull(variable, whereClause string) (property string, ok bool) {
	clause := strings.TrimSpace(whereClause)
	clause = unwrapOuterParens(clause)
	if clause == "" {
		return "", false
	}
	parts := splitTopLevelAndConjuncts(clause)
	targetProp := ""
	for _, raw := range parts {
		part := strings.TrimSpace(raw)
		if part == "" {
			continue
		}
		part = unwrapOuterParens(part)
		if p, ok := parseSimpleSingleIndexedIsNotNull(variable, part); ok {
			if targetProp != "" && !strings.EqualFold(targetProp, p) {
				return "", false
			}
			targetProp = p
			continue
		}
		// Allow only constant boolean conjuncts in addition to var.prop IS NOT NULL.
		// This keeps top-K semantics correct while supporting cache-buster style predicates.
		if _, isConst := e.tryEvaluateConstantBooleanConjunct(part); isConst {
			continue
		}
		return "", false
	}
	if targetProp == "" {
		return "", false
	}
	return targetProp, true
}

func parseSimpleSingleIndexedIsNotNull(variable, clause string) (property string, ok bool) {
	upper := upperASCII(strings.TrimSpace(clause))
	sfx := " IS NOT NULL"
	if !strings.HasSuffix(upper, sfx) {
		return "", false
	}
	left := strings.TrimSpace(clause[:len(clause)-len(sfx)])
	if left == "" {
		return "", false
	}
	prop, ok := parseVariableProperty(left, variable)
	if !ok {
		return "", false
	}
	return prop, true
}

func unwrapOuterParens(clause string) string {
	out := lexicalExpressionText(clause)
	// Only a pair that encloses the whole clause: (a) OR (b) starts and ends
	// with a parenthesis, but they don't match each other.
	for strings.HasPrefix(out, "(") && findMatchingDelimiter(out, 0, '(', ')') == len(out)-1 {
		out = strings.TrimSpace(out[1 : len(out)-1])
	}
	return out
}

// splitTopLevelAndConjuncts splits a WHERE clause into its top-level AND
// conjuncts. An AND inside a string, brackets or a CASE … END block (a WHEN
// condition, #699) belongs to its operand. It is the one AND splitter of the
// WHERE planners (index seek, cartesian and CREATE / MERGE filters, CALL
// subquery correlation).
func splitTopLevelAndConjuncts(clause string) []string {
	if topLevelKeywordIndex(clause, "OR") >= 0 || topLevelKeywordIndex(clause, "XOR") >= 0 {
		return []string{strings.TrimSpace(clause)}
	}
	paren, bracket, brace, caseDepth := 0, 0, 0, 0
	parts := make([]string, 0, 2)
	start := 0
	for i := 0; i < len(clause); i++ {
		if end, skipped := skipCypherLexicalToken(clause, i); skipped {
			i = end - 1
			continue
		}
		ch := clause[i]
		switch ch {
		case '(':
			paren++
			continue
		case ')':
			if paren > 0 {
				paren--
			}
			continue
		case '[':
			bracket++
			continue
		case ']':
			if bracket > 0 {
				bracket--
			}
			continue
		case '{':
			brace++
			continue
		case '}':
			if brace > 0 {
				brace--
			}
			continue
		case 'C', 'c':
			if caseKeywordAt(clause, i, "CASE") {
				caseDepth++
				i += len("CASE") - 1
				continue
			}
		case 'E', 'e':
			if caseDepth > 0 && caseKeywordAt(clause, i, "END") {
				caseDepth--
				i += len("END") - 1
				continue
			}
		}
		if paren == 0 && bracket == 0 && brace == 0 && caseDepth == 0 && i+3 <= len(clause) && strings.EqualFold(clause[i:i+3], "AND") {
			prevOK := i == 0 || isWhitespace(clause[i-1]) || clause[i-1] == '('
			nextIdx := i + 3
			nextOK := nextIdx >= len(clause) || isWhitespace(clause[nextIdx]) || clause[nextIdx] == ')'
			if prevOK && nextOK {
				parts = append(parts, strings.TrimSpace(clause[start:i]))
				start = nextIdx
				i = nextIdx - 1
			}
		}
	}
	parts = append(parts, strings.TrimSpace(clause[start:]))
	return parts
}

func (e *StorageExecutor) tryEvaluateConstantBooleanConjunct(clause string) (value bool, ok bool) {
	expr := strings.TrimSpace(clause)
	if expr == "" {
		return false, false
	}
	if strings.EqualFold(expr, "TRUE") {
		return true, true
	}
	if strings.EqualFold(expr, "FALSE") {
		return false, true
	}
	// If expression mentions variables/properties, treat as non-constant.
	if strings.Contains(expr, ".") || strings.Contains(expr, "$") {
		return false, false
	}
	for _, op := range []string{"<>", "!=", ">=", "<=", "=", ">", "<"} {
		if idx := topLevelSymbolIndex(expr, op); idx >= 0 {
			left := strings.TrimSpace(expr[:idx])
			right := strings.TrimSpace(expr[idx+len(op):])
			lv, lok := parseLiteralValue(left)
			rv, rok := parseLiteralValue(right)
			if !lok || !rok {
				return false, false
			}
			return compareLiteralValues(lv, rv, op)
		}
	}
	return false, false
}

func topLevelSymbolIndex(expr, sym string) int {
	return findTopLevelOperator(expr, sym, false, true)
}

func parseLiteralValue(raw string) (interface{}, bool) {
	s := strings.TrimSpace(raw)
	if value, quoted := decodeCypherQuotedString(s); quoted {
		return value, true
	}
	if strings.EqualFold(s, "true") {
		return true, true
	}
	if strings.EqualFold(s, "false") {
		return false, true
	}
	if strings.EqualFold(s, "null") {
		return nil, true
	}
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		return i, true
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f, true
	}
	return nil, false
}

func compareLiteralValues(left, right interface{}, op string) (bool, bool) {
	switch op {
	case "=", "!=", "<>":
		return compareCypherPredicateValues(left, right, op), true
	case ">", "<", ">=", "<=":
		if _, comparable := compareCypherOrderedValues(left, right); !comparable {
			return false, false
		}
		return compareCypherPredicateValues(left, right, op), true
	default:
		return false, false
	}
}

func parseVariableProperty(expr, variable string) (string, bool) {
	dot := strings.IndexByte(expr, '.')
	if dot <= 0 || dot >= len(expr)-1 {
		return "", false
	}
	lhs := strings.TrimSpace(expr[:dot])
	if !strings.EqualFold(lhs, strings.TrimSpace(variable)) {
		return "", false
	}
	prop := normalizePropertyKey(strings.TrimSpace(expr[dot+1:]))
	if prop == "" {
		return "", false
	}
	return prop, true
}

func topLevelEqualsIndex(clause string) int {
	for offset := 0; offset < len(clause); {
		index := findTopLevelOperator(clause[offset:], "=", false, true)
		if index < 0 {
			return -1
		}
		index += offset
		if index > 0 {
			previous := clause[index-1]
			if previous == '!' || previous == '<' || previous == '>' {
				offset = index + 1
				continue
			}
		}
		if index+1 < len(clause) && clause[index+1] == '=' {
			return index + 1
		}
		return index
	}
	return -1
}

func nodeHasAnyLabel(node *storage.Node, labels []string) bool {
	for _, want := range labels {
		for _, have := range node.Labels {
			if strings.EqualFold(strings.TrimSpace(want), strings.TrimSpace(have)) {
				return true
			}
		}
	}
	return false
}

// tryRewriteNullNormalizedPredicate rewrites coalesce-wrapped equality predicates
// into OR-expanded forms that are visible to the index seek cascade and compiled
// WHERE fast-paths.
//
// Rewrites:
//
//	coalesce(var.prop, <default>) = <value>  →  (var.prop = <value> OR var.prop IS NULL)
//	                                            when <value> == <default>
//
//	coalesce(var.prop, <default>) <> <value> →  (var.prop <> <value> AND var.prop IS NOT NULL)
//	                                            when <value> == <default>
//
// This is safe because coalesce(x, d) = d is semantically equivalent to
// (x = d OR x IS NULL).
func tryRewriteNullNormalizedPredicate(whereClause string) string {
	clause := strings.TrimSpace(whereClause)
	if clause == "" {
		return clause
	}

	// Only rewrite simple top-level predicates (no AND/OR at the top level).
	// Nested coalesce inside AND/OR conjuncts would need recursive rewrite
	// which risks semantic drift — keep it strict.
	upper := upperASCII(clause)
	if strings.Contains(upper, " AND ") || strings.Contains(upper, " OR ") {
		return clause
	}

	// Look for coalesce( at the start.
	lowerClause := lowerASCII(clause)
	if !strings.HasPrefix(lowerClause, "coalesce(") {
		return clause
	}

	// Find matching closing paren for coalesce(...).
	depth := 0
	closeIdx := -1
	for i := 9; i < len(clause); i++ { // start after "coalesce("
		switch clause[i] {
		case '(':
			depth++
		case ')':
			if depth == 0 {
				closeIdx = i
				goto found
			}
			depth--
		}
	}
found:
	if closeIdx < 0 {
		return clause
	}

	inner := strings.TrimSpace(clause[9:closeIdx])
	afterCoalesce := strings.TrimSpace(clause[closeIdx+1:])

	// Parse inner: expect "var.prop, <default>"
	commaIdx := strings.Index(inner, ",")
	if commaIdx <= 0 {
		return clause
	}
	varProp := strings.TrimSpace(inner[:commaIdx])
	defaultVal := strings.TrimSpace(inner[commaIdx+1:])
	if varProp == "" || defaultVal == "" {
		return clause
	}
	// varProp must look like variable.property
	if !strings.Contains(varProp, ".") {
		return clause
	}

	// Parse operator and RHS: expect "= <value>" or "<> <value>" or "!= <value>"
	op := ""
	rhs := ""
	if strings.HasPrefix(afterCoalesce, "<>") {
		op = "<>"
		rhs = strings.TrimSpace(afterCoalesce[2:])
	} else if strings.HasPrefix(afterCoalesce, "!=") {
		op = "<>"
		rhs = strings.TrimSpace(afterCoalesce[2:])
	} else if strings.HasPrefix(afterCoalesce, "=") {
		op = "="
		rhs = strings.TrimSpace(afterCoalesce[1:])
	} else {
		return clause
	}

	if rhs == "" {
		return clause
	}

	// Only rewrite when the comparison value matches the default value.
	// coalesce(x, false) = false → rewrite
	// coalesce(x, false) = true  → don't rewrite (different semantics)
	if !strings.EqualFold(rhs, defaultVal) {
		return clause
	}

	if op == "=" {
		return fmt.Sprintf("(%s = %s OR %s IS NULL)", varProp, rhs, varProp)
	}
	// <> case: coalesce(x, d) <> d means x <> d AND x IS NOT NULL
	return fmt.Sprintf("(%s <> %s AND %s IS NOT NULL)", varProp, rhs, varProp)
}

// collectNodesFromIndexedProperty is the shared tail of the index seeks that
// read one indexed property per candidate label: it gathers lookup(label)
// for every label of the pattern that indexes property, de-duplicates the
// IDs in lookup order, and loads the nodes that carry all pattern labels.
// used is false when no candidate label indexes property.
func (e *StorageExecutor) collectNodesFromIndexedProperty(
	schema *storage.SchemaManager,
	nodePattern nodePatternInfo,
	property string,
	lookup func(label string) ([]storage.NodeID, bool),
) (nodes []*storage.Node, used bool) {
	labels := e.indexCandidateLabels(schema, nodePattern.labels, property)
	if len(labels) == 0 {
		return nil, false
	}
	idSet := make(map[storage.NodeID]struct{})
	ordered := make([]storage.NodeID, 0)
	for _, label := range labels {
		ids, ok := lookup(label)
		if !ok {
			return nil, false
		}
		for _, id := range ids {
			if _, exists := idSet[id]; exists {
				continue
			}
			idSet[id] = struct{}{}
			ordered = append(ordered, id)
		}
	}
	nodes = make([]*storage.Node, 0, len(ordered))
	for _, id := range ordered {
		// An ID the index still lists for a node that is gone or lost a
		// pattern label is skipped.
		if node, err := e.getQueryNode(e.storage, id); err == nil && node != nil && mergeNodeHasLabels(node, nodePattern.labels) {
			nodes = append(nodes, node)
		}
	}
	return nodes, true
}

// tryCollectNodesFromPropertyIndexRange seeds a MATCH from a property index
// when its WHERE bounds an indexed property with <, <=, > or >= against a
// number or string literal or parameter (p.age > 30, 18 <= p.age < 65,
// p.name >= $from AND p.name < $to). Only the bounds narrow the seed; the
// caller still evaluates the whole WHERE on every candidate (#820).
func (e *StorageExecutor) tryCollectNodesFromPropertyIndexRange(nodePattern nodePatternInfo, whereClause string, params map[string]interface{}) ([]*storage.Node, bool, error) {
	if len(nodePattern.labels) == 0 {
		return nil, false, nil
	}
	property, bounds, ok := parseIndexedRangeBounds(nodePattern.variable, whereClause, params)
	if !ok {
		return nil, false, nil
	}
	schema := orderedPropertyIndexSchema(e.storage)
	if schema == nil {
		return nil, false, nil
	}
	nodes, used := e.collectNodesFromIndexedProperty(schema, nodePattern, property, func(label string) ([]storage.NodeID, bool) {
		return schema.PropertyIndexRange(label, property, bounds)
	})
	return nodes, used, nil
}

// parseIndexedRangeBounds finds, among the top-level AND conjuncts of a
// WHERE, comparisons of variable.property with a literal or parameter, and
// returns the bounds they place on the first such property.
func parseIndexedRangeBounds(variable, whereClause string, params map[string]interface{}) (property string, bounds storage.PropertyIndexBounds, ok bool) {
	clause := unwrapOuterParens(strings.TrimSpace(whereClause))
	if clause == "" {
		return "", bounds, false
	}
	for _, raw := range splitTopLevelAndConjuncts(clause) {
		operands, operators, isChain := splitComparisonChain(unwrapOuterParens(strings.TrimSpace(raw)))
		if !isChain {
			continue
		}
		for index, operator := range operators {
			left, right := strings.TrimSpace(operands[index]), strings.TrimSpace(operands[index+1])
			if leftProperty, isProperty := parseVariableProperty(left, variable); isProperty {
				if value, resolved := rangeBoundValue(right, params); resolved && (property == "" || property == leftProperty) {
					property = leftProperty
					addIndexedRangeBound(&bounds, operator, value)
				}
				continue
			}
			if rightProperty, isProperty := parseVariableProperty(right, variable); isProperty {
				if value, resolved := rangeBoundValue(left, params); resolved && (property == "" || property == rightProperty) {
					property = rightProperty
					addIndexedRangeBound(&bounds, mirroredComparison(operator), value)
				}
			}
		}
	}
	return property, bounds, property != "" && (bounds.HasLower || bounds.HasUpper)
}

// rangeBoundValue resolves a literal or $parameter operand of a range
// comparison.
func rangeBoundValue(operand string, params map[string]interface{}) (interface{}, bool) {
	if strings.HasPrefix(operand, "$") {
		value, exists := params[strings.TrimPrefix(operand, "$")]
		return value, exists
	}
	value, ok := parseLiteralValue(operand)
	if !ok {
		return nil, false
	}
	return value, true
}

// addIndexedRangeBound records "property operator value". A second bound on
// the same side is not combined: keeping one still selects every match.
func addIndexedRangeBound(bounds *storage.PropertyIndexBounds, operator string, value interface{}) {
	switch operator {
	case ">", ">=":
		if !bounds.HasLower {
			bounds.Lower, bounds.HasLower, bounds.LowerInclusive = value, true, operator == ">="
		}
	case "<", "<=":
		if !bounds.HasUpper {
			bounds.Upper, bounds.HasUpper, bounds.UpperInclusive = value, true, operator == "<="
		}
	}
}

// mirroredComparison is the operator with its operands swapped (5 < p.x is
// p.x > 5); others are returned unchanged and ignored by the caller.
func mirroredComparison(operator string) string {
	switch operator {
	case "<":
		return ">"
	case "<=":
		return ">="
	case ">":
		return "<"
	case ">=":
		return "<="
	}
	return operator
}

// collectPipelineIndexedNodeCandidates is the index half of
// collectPipelineInitialNodeCandidates: the candidates of the first index
// operator that can narrow the MATCH, with used false when none can. Row
// reads and the filtered count (tryStreamPipelineFilteredNodeCount) both seed
// from it, so a lookup that uses an index for rows uses it for count(*) too
// (#820).
func (e *StorageExecutor) collectPipelineIndexedNodeCandidates(ctx context.Context, nodePattern nodePatternInfo, whereClause string, hint pipelineMatchPhysicalHint) (nodes []*storage.Node, whereApplied bool, used bool, err error) {
	params := getParamsFromContext(ctx)
	if hint.limit > 0 && hint.orderExpr != "" {
		orderedPlans := []func() ([]*storage.Node, bool, error){
			func() ([]*storage.Node, bool, error) {
				return e.tryCollectNodesFromPropertyIndexNotNullOrderLimit(ctx, nodePattern, whereClause, hint.orderExpr, hint.limit)
			},
			func() ([]*storage.Node, bool, error) {
				return e.tryCollectNodesFromPropertyIndexOrderLimit(ctx, nodePattern, whereClause, hint.orderExpr, hint.limit)
			},
		}
		for _, plan := range orderedPlans {
			nodes, used, err := plan()
			if err != nil {
				return nil, false, false, err
			}
			if used {
				e.markOuterIndexTopKUsed()
				return nodes, false, true, nil
			}
		}
	}
	if nodes, used, err := e.tryCollectNodesFromIDEqualityCompound(ctx, nodePattern, whereClause, params); err != nil || used {
		return nodes, false, used, err
	}
	// When an id IN list predicate is the whole WHERE, its seek returns
	// exactly the nodes it selects: the caller need not
	// evaluate the WHERE again on each of them. Evaluating it per row checked
	// every node against the whole list: CALL { … } IN TRANSACTIONS batches,
	// which select their rows by id(n) IN $ids, were quadratic in the batch
	// size (#703).
	if nodes, used, err := e.tryCollectNodesFromIDIn(ctx, nodePattern, whereClause, params); err != nil || used {
		return nodes, used, used, err
	}
	// An id IN list among AND conditions seeks the same way; the caller
	// still evaluates the whole WHERE on the nodes it selects.
	if findTopLevelKeyword(whereClause, " AND ") > 0 {
		for _, conjunct := range splitTopLevelAndConjuncts(whereClause) {
			if nodes, used, err := e.tryCollectNodesFromIDIn(ctx, nodePattern, conjunct, params); err != nil || used {
				return nodes, false, used, err
			}
		}
	}
	// inList marks the plan that answers a WHERE that is exactly an IN list.
	indexedPlans := []struct {
		collect func() ([]*storage.Node, bool, error)
		inList  bool
	}{
		{collect: func() ([]*storage.Node, bool, error) {
			return e.tryCollectNodesFromPropertyIndexInOrParam(nodePattern, whereClause, params)
		}},
		{collect: func() ([]*storage.Node, bool, error) {
			return e.tryCollectNodesFromPropertyIndexOrEquality(ctx, nodePattern, whereClause, params)
		}},
		{inList: true, collect: func() ([]*storage.Node, bool, error) {
			return e.tryCollectNodesFromPropertyIndexInCompound(ctx, nodePattern, whereClause, params)
		}},
		{collect: func() ([]*storage.Node, bool, error) {
			return e.tryCollectNodesFromPropertyIndexEqualityCompound(ctx, nodePattern, whereClause)
		}},
		{collect: func() ([]*storage.Node, bool, error) {
			// Inline pattern properties ({id: $id}) on an indexed property.
			nodes, used := e.lookupPatternCandidatesUsingPropertyIndex(nodePattern, e.getStorage(ctx))
			if used {
				e.markMergeSchemaLookupUsed()
			}
			if !used || len(nodePattern.labels) < 2 {
				return nodes, used, nil
			}
			labelled := nodes[:0]
			for _, node := range nodes {
				if mergeNodeHasLabels(node, nodePattern.labels) {
					labelled = append(labelled, node)
				}
			}
			return labelled, true, nil
		}},
		{collect: func() ([]*storage.Node, bool, error) {
			return e.tryCollectNodesFromPropertyIndexRange(nodePattern, whereClause, params)
		}},
		{collect: func() ([]*storage.Node, bool, error) {
			return e.tryCollectNodesFromPropertyIndexNotNull(nodePattern, whereClause)
		}},
	}
	for _, plan := range indexedPlans {
		nodes, used, err := plan.collect()
		if err != nil {
			return nil, false, false, err
		}
		if used {
			if len(nodePattern.properties) > 0 {
				nodes = e.filterNodesByProperties(nodes, nodePattern.properties)
			}
			// A WHERE that is exactly <variable>.<property> IN <list> on an
			// indexed property is answered by the index: one lookup per list
			// value returns exactly the nodes it selects, so the caller
			// doesn't test each of them against the whole list again
			// (quadratic in the list for a list that names every node).
			// Checked only once the index answered, so a read that takes
			// another route doesn't parse its WHERE for it.
			exact := plan.inList && e.whereIsSimpleIndexedIn(ctx, nodePattern.variable, whereClause, params)
			return nodes, exact, true, nil
		}
	}
	return nil, false, false, nil
}

package cypher

import (
	"context"
	"errors"
	"fmt"
	valueconvert "github.com/orneryd/nornicdb/pkg/convert"
	cypherfn "github.com/orneryd/nornicdb/pkg/cypher/fn"
	"strconv"
	"strings"

	"github.com/orneryd/nornicdb/pkg/storage"
	"github.com/orneryd/nornicdb/pkg/util"
)

// countKeywordOccurrences counts how many times a keyword appears in the query
// using word boundary detection. Excludes occurrences inside labels (after ':')
func countKeywordOccurrences(upper, keyword string) int {
	count := 0
	idx := 0
	for {
		found := strings.Index(upper[idx:], keyword)
		if found == -1 {
			break
		}
		// Check word boundary before
		pos := idx + found
		// Must have space/newline/tab before, NOT ':' (which would indicate a label)
		beforeOk := pos == 0 || (upper[pos-1] == ' ' || upper[pos-1] == '\n' || upper[pos-1] == '\t')
		// Check word boundary after
		afterPos := pos + len(keyword)
		afterOk := afterPos >= len(upper) || (upper[afterPos] == ' ' || upper[afterPos] == '(' || upper[afterPos] == '\n' || upper[afterPos] == '\t')

		if beforeOk && afterOk {
			count++
		}
		idx = pos + len(keyword)
	}
	return count
}

// lastKeywordIndexBefore returns the last occurrence of keyword before endIdx.
// It uses keyword-aware scanning and returns -1 when not found.
func lastKeywordIndexBefore(query, keyword string, endIdx int) int {
	if endIdx <= 0 {
		return -1
	}
	if endIdx > len(query) {
		endIdx = len(query)
	}
	segment := query[:endIdx]
	pos := -1
	search := 0
	for {
		rel := findKeywordIndex(segment[search:], keyword)
		if rel < 0 {
			break
		}
		found := search + rel
		pos = found
		search = found + len(keyword)
		if search >= len(segment) {
			break
		}
	}
	return pos
}

// splitMatchClauses splits the query into individual MATCH clause patterns
func splitMatchClauses(cypher string, whereIdx, returnIdx int) []string {
	var clauses []string

	// Find the end of MATCH patterns (before WHERE or RETURN)
	endIdx := returnIdx
	if whereIdx > 0 && whereIdx < returnIdx {
		endIdx = whereIdx
	}

	matchPart := cypher[5:endIdx] // Skip first "MATCH"

	// Split by subsequent MATCH keywords
	parts := strings.Split(upperASCII(matchPart), "MATCH")
	offset := 5 // Start after first MATCH

	for i, p := range parts {
		if strings.TrimSpace(p) == "" {
			continue
		}
		// Find the actual length in original case
		pattern := strings.TrimSpace(cypher[offset : offset+len(p)])
		clauses = append(clauses, pattern)
		offset += len(p)
		if i < len(parts)-1 {
			offset += 5 // Skip "MATCH"
		}
	}

	// Fix: Re-split using findKeywordIndex for accuracy
	clauses = clauses[:0]
	start := 5 // After first MATCH
	searchStart := start
	for {
		nextMatch := findKeywordIndex(cypher[searchStart:], "MATCH")
		if nextMatch == -1 || searchStart+nextMatch >= endIdx {
			// No more MATCH - take everything to end
			clauses = append(clauses, strings.TrimSpace(cypher[start:endIdx]))
			break
		}
		pos := searchStart + nextMatch
		clauses = append(clauses, strings.TrimSpace(cypher[start:pos]))
		start = pos + 5 // Skip "MATCH"
		searchStart = pos + 5
	}

	return clauses
}

// binding represents variable bindings from multiple MATCH clauses.
//
// NOTE: this stays map[string]*storage.Node (node-only) on purpose. A wide
// range of existing tests (binding_where_compile*_test.go,
// coverage_binding_where_test.go, coverage_lift_test.go,
// internal_branch_coverage_boost_test.go, binding_where_benchmark_test.go,
// ...) construct and index `binding{...}` directly, so widening its value
// type would ripple into all of them for no benefit. Relationship variables
// bound by a MATCH clause (e.g. "rel" in `(s)-[rel]->(x)`) are tracked in a
// parallel `map[string]*storage.Edge` — see executeFirstMatch/
// executeChainedMatch below — that travels index-aligned alongside a
// []binding slice rather than living inside binding itself.
type binding map[string]*storage.Node
type relationshipBinding map[string]interface{}

// executeChainedMatch executes a subsequent MATCH against existing bindings.
// existingRelBindings must be index-aligned with existingBindings (as
// returned by executeFirstMatch/executeChainedMatch); it may be nil when no
// relationship variable has been bound by an earlier clause. The returned
// relationship-binding slice is index-aligned with the returned bindings and
// carries forward any relationship bound earlier in the chain plus any
// relationship variable bound by this clause's own pattern.
func (e *StorageExecutor) executeChainedMatch(ctx context.Context, pattern string, existingBindings []binding, existingRelBindings []relationshipBinding) ([]binding, []relationshipBinding) {
	var newBindings []binding
	var newRelBindings []relationshipBinding
	// Bracketed (-[r]->) and bare (-->, <--, --) relationships both make a
	// traversal; only a lone node pattern is matched as a node.
	isRelationshipPattern := containsRelationshipPattern(pattern)

	for idx, existing := range existingBindings {
		var existingRels relationshipBinding
		if idx < len(existingRelBindings) {
			existingRels = existingRelBindings[idx]
		}

		rowScope := valueBindingsLayer(ctx, len(existing)+len(existingRels))
		for name, node := range existing {
			rowScope[name] = node
		}
		for name, relationship := range existingRels {
			rowScope[name] = relationship
		}
		rowCtx, rowPattern, prepareErr := e.preparePatternRow(ctx, pattern, rowScope)
		if prepareErr != nil {
			recordExpressionFailure(ctx, prepareErr)
			return nil, nil
		}
		var matches *TraversalMatch
		if isRelationshipPattern {
			matches = e.parseTraversalPattern(rowCtx, rowPattern)
			if matches == nil {
				return newBindings, newRelBindings
			}
		}
		// Check for relationship pattern
		if isRelationshipPattern {
			// Check if any bound variables are referenced
			boundStartNode := existing[matches.StartNode.variable]
			boundEndNode := existing[matches.EndNode.variable]

			var paths []PathResult
			if boundStartNode != nil {
				if !e.pipelineNodeMatchesPattern(boundStartNode, matches.StartNode) {
					continue
				}
				if matches.IsChained && len(matches.Segments) > 1 {
					paths = e.traverseChainedGraph(rowCtx, matches, []*storage.Node{boundStartNode})
				} else {
					paths = e.traverseFromNode(rowCtx, boundStartNode, matches)
				}
			} else {
				paths = e.traverseGraph(rowCtx, matches)
			}
			for _, path := range paths {
				if len(path.Nodes) == 0 {
					continue
				}
				startNode := path.Nodes[0]
				endNode := path.Nodes[len(path.Nodes)-1]

				// Check if path matches any bound variables
				startMatches := boundStartNode == nil || startNode.Identity() == boundStartNode.Identity()
				endMatches := boundEndNode == nil || endNode.Identity() == boundEndNode.Identity()

				if startMatches && endMatches {
					pathContext := e.buildPathContext(path, matches)
					b, ok := mergeNodeBindingsChecked(existing, pathContext.nodes)
					if !ok {
						continue
					}
					mergedRels, ok := mergeRelationshipBindingsChecked(existingRels, relationshipBindingsFromPathContext(pathContext))
					if !ok {
						continue
					}
					newBindings = append(newBindings, b)
					// Carry forward any relationship bound by an earlier
					// clause plus the relationship variable (if any) bound
					// by this clause's pattern, rejecting rows that would
					// rebind an already-bound relationship variable to a
					// different edge.
					newRelBindings = append(newRelBindings, mergedRels)
				}
			}
		} else {
			// Simple node pattern
			nodePattern, parseErr := e.parseNodePattern(rowCtx, rowPattern)
			if parseErr != nil {
				recordExpressionFailure(ctx, parseErr)
				return nil, nil
			}

			// Check if variable is already bound
			if boundNode := existing[nodePattern.variable]; boundNode != nil {
				if !e.pipelineNodeMatchesPattern(boundNode, nodePattern) {
					continue
				}
				newBindings = append(newBindings, existing)
				newRelBindings = append(newRelBindings, existingRels)
				continue
			}

			nodes, _ := e.loadPatternNodes(rowCtx, nodePattern.labels, nodePattern.properties)

			for _, node := range nodes {
				b := make(binding)
				for k, v := range existing {
					b[k] = v
				}
				b[nodePattern.variable] = node
				newBindings = append(newBindings, b)
				newRelBindings = append(newRelBindings, existingRels)
			}
		}
	}

	return newBindings, newRelBindings
}

func mergeNodeBindingsChecked(existing binding, current map[string]*storage.Node) (binding, bool) {
	merged := make(binding, len(existing)+len(current))
	for name, node := range existing {
		merged[name] = node
	}
	for name, node := range current {
		if previous := merged[name]; previous != nil && node != nil && previous.Identity() != node.Identity() {
			return nil, false
		}
		if merged[name] == nil {
			merged[name] = node
		}
	}
	return merged, true
}

// mergeRelBindingsChecked merges two relationship-binding maps (e.g. one
// carried forward from earlier MATCH clauses and one bound by the current
// clause). Overlapping keys must point at the same edge ID; otherwise the row
// combination is invalid and the merge fails. Returns nil when both are empty
// so callers can treat "no relationship bound yet" and "empty map"
// identically.
func mergeRelBindingsChecked(existing, current map[string]*storage.Edge) (map[string]*storage.Edge, bool) {
	if len(existing) == 0 && len(current) == 0 {
		return nil, true
	}
	merged := make(map[string]*storage.Edge, len(existing)+len(current))
	for k, v := range existing {
		merged[k] = v
	}
	for k, v := range current {
		prev := merged[k]
		if prev != nil && v != nil && prev.Identity() != v.Identity() {
			return nil, false
		}
		if prev == nil {
			merged[k] = v
		}
	}
	return merged, true
}

func relationshipBindingsFromPathContext(pathContext PathContext) relationshipBinding {
	bindings := make(relationshipBinding, len(pathContext.rels)+len(pathContext.paths))
	for name, relationship := range pathContext.rels {
		bindings[name] = relationship
	}
	for name, path := range pathContext.paths {
		if path == nil || path.Nodes != nil {
			continue
		}
		bindings[name] = append([]*storage.Edge{}, path.Relationships...)
	}
	if len(bindings) == 0 {
		return nil
	}
	return bindings
}

func mergeRelationshipBindingsChecked(existing, current relationshipBinding) (relationshipBinding, bool) {
	if len(existing) == 0 && len(current) == 0 {
		return nil, true
	}
	merged := make(relationshipBinding, len(existing)+len(current))
	for name, value := range existing {
		merged[name] = value
	}
	for name, value := range current {
		if previous, exists := merged[name]; exists && !sameRelationshipBinding(previous, value) {
			return nil, false
		}
		merged[name] = value
	}
	return merged, true
}

func sameRelationshipBinding(left, right interface{}) bool {
	leftEdge, leftIsEdge := left.(*storage.Edge)
	rightEdge, rightIsEdge := right.(*storage.Edge)
	if leftIsEdge || rightIsEdge {
		return leftIsEdge && rightIsEdge && leftEdge != nil && rightEdge != nil && leftEdge.ID == rightEdge.ID
	}
	leftList, leftIsList := left.([]*storage.Edge)
	rightList, rightIsList := right.([]*storage.Edge)
	if !leftIsList || !rightIsList || len(leftList) != len(rightList) {
		return false
	}
	for index := range leftList {
		if leftList[index] == nil || rightList[index] == nil || leftList[index].ID != rightList[index].ID {
			return false
		}
	}
	return true
}

func edgeRelationshipBindings(bindings relationshipBinding) map[string]*storage.Edge {
	result := make(map[string]*storage.Edge)
	for name, value := range bindings {
		if relationship, ok := value.(*storage.Edge); ok {
			result[name] = relationship
		}
	}
	return result
}

// filterBindingsByWhere filters bindings based on WHERE clause. Kept
// unchanged (node-only) because several existing tests
// (binding_where_benchmark_test.go, migration_query_shapes_test.go) call it
// directly with plain []binding for queries that bind no relationship
// variable. See filterBindingsByWhereWithRels for the relationship-aware
// variant used by executeMultiMatch.
func (e *StorageExecutor) filterBindingsByWhere(ctx context.Context, bindings []binding, whereClause string, params map[string]interface{}) []binding {
	compiled := e.newBindingFilterPredicate(ctx, whereClause, params)
	result := make([]binding, 0, len(bindings))

	for _, b := range bindings {
		if compiled.matches(b, params) {
			result = append(result, b)
		}
	}

	return result
}

// filterBindingsByWhereWithRels filters (binding, relationship-binding) row
// pairs by a WHERE clause that may reference a relationship variable's
// properties (e.g. "rel.evidence_source = $e"). The returned slices stay
// index-aligned with each other.
//
// This reuses the existing node-only WHERE compiler
// (binding_where_compile.go) unchanged by presenting each bound relationship
// as a read-only property view alongside the row's real node bindings for
// the duration of the WHERE check only — see bindingWithRelView. The real
// *storage.Edge values (needed for RETURN/DELETE) are returned separately
// and never replaced by the view.
func (e *StorageExecutor) filterBindingsByWhereWithRels(ctx context.Context, bindings []binding, relBindings []relationshipBinding, whereClause string, params map[string]interface{}) ([]binding, []relationshipBinding) {
	compiled := e.newBindingFilterPredicate(ctx, whereClause, params)
	resultBindings := make([]binding, 0, len(bindings))
	resultRels := make([]relationshipBinding, 0, len(bindings))

	for i, b := range bindings {
		var rels relationshipBinding
		if i < len(relBindings) {
			rels = relBindings[i]
		}
		if compiled.matchesRelationships(b, rels, params) {
			resultBindings = append(resultBindings, b)
			resultRels = append(resultRels, rels)
		}
	}

	return resultBindings, resultRels
}

// bindingWithRelView returns a binding row for WHERE-clause evaluation that
// additionally exposes each bound relationship variable as a read-only,
// node-shaped property view (ID + Properties only, no labels/edges). The
// binding-where evaluator (binding_where_compile.go) only ever reads
// `.Properties[prop]` or `.ID` off a bound variable via getBindingNodeValue,
// so this view lets relationship property predicates (e.g.
// "rel.evidence_source = $e") evaluate correctly without teaching every
// WHERE-compiler function in binding_where_compile.go about a second
// bound-value kind. Returns b unchanged when there is nothing to add.
func bindingWithRelView(b binding, rels map[string]*storage.Edge) binding {
	if len(rels) == 0 {
		return b
	}
	view := make(binding, len(b)+len(rels))
	for k, v := range b {
		view[k] = v
	}
	for k, edge := range rels {
		if edge == nil {
			continue
		}
		view[k] = &storage.Node{ID: storage.NodeID(edge.ID), Database: edge.Database, Properties: edge.Properties}
	}
	return view
}

// evaluateBindingWhere evaluates WHERE clause against a binding
func (e *StorageExecutor) evaluateBindingWhere(ctx context.Context, b binding, whereClause string, params map[string]interface{}) bool {
	return e.evaluateBindingWhereGeneric(ctx, b, whereClause, params)
}

func (e *StorageExecutor) resolveWhereValue(ctx context.Context, raw string, params map[string]interface{}) interface{} {
	s := strings.TrimSpace(raw)
	if strings.HasPrefix(s, "$") {
		name := strings.TrimSpace(strings.TrimPrefix(s, "$"))
		if params != nil {
			if v, ok := params[name]; ok {
				return v
			}
		}
	}
	value, err := e.parseValue(ctx, s)
	recordExpressionFailure(ctx, err)
	return value
}

// resolveBindingItem resolves a return item against a binding. rels carries
// any relationship variable(s) bound for this specific row (index-aligned
// counterpart produced by executeFirstMatch/executeChainedMatch); pass nil
// when the row binds no relationship variable.
func (e *StorageExecutor) resolveBindingItemWithRelationships(ctx context.Context, item returnItem, b binding, rels relationshipBinding) interface{} {
	expr := strings.TrimSpace(item.expr)
	if expr == "" {
		return nil
	}
	return e.resolveBindingExprWithRelationships(ctx, expr, b, rels)
}

func (e *StorageExecutor) resolveBindingItem(ctx context.Context, item returnItem, b binding, rels map[string]*storage.Edge) interface{} {
	return e.resolveBindingItemWithRelationships(ctx, item, b, relationshipBindingFromEdges(rels))
}

func (e *StorageExecutor) resolveBindingExpr(ctx context.Context, expr string, b binding, rels map[string]*storage.Edge) interface{} {
	return e.resolveBindingExprWithRelationships(ctx, expr, b, relationshipBindingFromEdges(rels))
}

func (e *StorageExecutor) resolveBindingExprWithRelationships(ctx context.Context, expr string, b binding, rels relationshipBinding) interface{} {
	expr = strings.TrimSpace(expr)
	if expr == "" {
		return nil
	}

	// elementId(var) — check node bindings first, then relationship bindings.
	if strings.HasPrefix(lowerASCII(expr), "elementid(") && strings.HasSuffix(expr, ")") {
		inner := strings.TrimSpace(expr[len("elementId(") : len(expr)-1])
		if node := b[inner]; node != nil {
			value, _ := cypherfn.EntityElementID(e.registryFunctionContext(ctx, nil), node)
			return value
		}
		if edge, ok := rels[inner].(*storage.Edge); ok && edge != nil {
			value, _ := cypherfn.EntityElementID(e.registryFunctionContext(ctx, nil), edge)
			return value
		}
		return nil
	}

	// Reuse shared COALESCE evaluator used in MATCH row projection paths.
	if strings.HasPrefix(upperASCII(expr), "COALESCE(") && strings.HasSuffix(expr, ")") {
		return e.evaluateCoalesceInContext(expr, b, edgeRelationshipBindings(rels), nil)
	}

	// Literal value
	if strings.HasPrefix(expr, "'") || strings.HasPrefix(expr, "\"") ||
		strings.EqualFold(expr, "true") || strings.EqualFold(expr, "false") ||
		strings.EqualFold(expr, "null") || isNumericLiteral(expr) {
		value, err := e.parseValue(ctx, expr)
		recordExpressionFailure(ctx, err)
		return value
	}

	// Property access: var.prop — check node bindings first, then
	// relationship bindings (e.g. "rel.evidence_source").
	if dotIdx := strings.Index(expr, "."); dotIdx > 0 && isSimpleIdentifierOrProperty(expr) {
		varName := expr[:dotIdx]
		propName := expr[dotIdx+1:]
		if node := b[varName]; node != nil {
			if val, ok := getBindingNodeValue(e.queryVisibleValue(node).(*storage.Node), propName); ok {
				return val
			}
			return nil
		}
		if edge, ok := rels[varName].(*storage.Edge); ok && edge != nil {
			return e.queryEntityProperties(edge)[propName]
		}
		return nil
	}

	// Node variable
	if node := b[expr]; node != nil {
		return node
	}

	// BUG FIX: relationship variable (e.g. bare "rel" in `RETURN rel` or
	// `DELETE rel`). Previously unreachable — `binding` never stored
	// relationships, so this always fell through to the generic evaluator
	// below with a nil rels map and produced nil. Returning the real
	// *storage.Edge here (rather than a synthetic node) matters because
	// DELETE's classifyDeleteTargetValue and Neo4j-compat RETURN both
	// distinguish edges from nodes by Go type.
	if relationship, exists := rels[expr]; exists {
		return relationship
	}

	// Fallback to the common expression evaluator used in other MATCH/RETURN
	// paths. It already accepts a relationship map (previously always passed
	// nil here), so expressions like count(rel) / collect(rel.prop) resolve
	// correctly once rels is populated.
	if val := e.evaluateExpressionWithContext(ctx, expr, b, edgeRelationshipBindings(rels)); val != nil {
		return val
	}

	return nil
}

func relationshipBindingFromEdges(edges map[string]*storage.Edge) relationshipBinding {
	bindings := make(relationshipBinding, len(edges))
	for name, edge := range edges {
		bindings[name] = edge
	}
	return bindings
}

func isNumericLiteral(s string) bool {
	if s == "" {
		return false
	}
	_, err := strconv.ParseFloat(s, 64)
	return err == nil
}

// collectNodesWithStreaming efficiently collects nodes from storage using streaming when possible.
// This avoids loading all nodes into memory, which is critical for performance with large datasets.
//
// Parameters:
//   - ctx: Context for cancellation
//   - labels: Optional label filter (only nodes with this label)
//   - properties: Optional property filters
//   - limit: Maximum number of nodes to collect (-1 for unlimited)
//
// Returns collected nodes or error.
func (e *StorageExecutor) collectNodesWithStreaming(
	ctx context.Context,
	labels []string,
	properties map[string]interface{},
	whereVariable string,
	whereClause string,
	limit int,
) ([]*storage.Node, error) {
	return e.collectNodesWithStreamingProjection(ctx, labels, properties, whereVariable, whereClause, limit, nil)
}

// collectNodesWithStreamingProjection is collectNodesWithStreaming whose
// label scan reads only the projection's user properties; nil reads whole
// nodes. The caller guarantees nothing else in the statement uses the
// returned nodes' other properties.
func (e *StorageExecutor) collectNodesWithStreamingProjection(
	ctx context.Context,
	labels []string,
	properties map[string]interface{},
	whereVariable string,
	whereClause string,
	limit int,
	projection []string,
) ([]*storage.Node, error) {
	capacity := 0
	if limit > 0 {
		capacity = limit
	}
	collected := make([]*storage.Node, 0, capacity)
	if err := e.visitNodesWithStreamingProjection(ctx, labels, properties, whereVariable, whereClause, limit, projection, &collected, nil); err != nil {
		return nil, err
	}
	return collected, nil
}

// visitNodesWithStreamingProjection is collectNodesWithStreamingProjection
// appending each node to *collected, or handing it to visit when visit is
// set, as the scan reads it, in the same order. visit returning
// storage.ErrIterationStopped ends the scan without error; any other error
// ends it with that error.
func (e *StorageExecutor) visitNodesWithStreamingProjection(
	ctx context.Context,
	labels []string,
	properties map[string]interface{},
	whereVariable string,
	whereClause string,
	limit int,
	projection []string,
	collected *[]*storage.Node,
	visit func(*storage.Node) error,
) error {
	store := e.getStorage(ctx)
	viewport, hasViewport := TemporalViewportFromContext(ctx)
	checker, canCheckViewport := store.(temporalCurrentNodeChecker)
	hideSystemNodes := shouldHideSystemNodes(store)
	visited := 0
	var whereFilter FilterFunc
	if strings.TrimSpace(whereClause) != "" {
		whereFilter = e.compileNodeWhereFilter(ctx, whereVariable, whereClause)
	}
	collect := func(node *storage.Node) error {
		if node == nil || (hideSystemNodes && isSystemNode(node)) {
			return nil
		}
		if len(labels) > 0 && !mergeNodeHasLabels(node, labels) {
			return nil
		}
		if len(properties) > 0 && !e.nodeMatchesProps(node, properties) {
			return nil
		}
		if whereFilter != nil && !whereFilter(node) {
			return nil
		}
		if hasViewport && canCheckViewport {
			visible, err := checker.IsCurrentTemporalNode(node, viewport.AsOf)
			if err != nil {
				return err
			}
			if !visible {
				return nil
			}
		}
		if visit == nil {
			*collected = append(*collected, node)
		} else if err := visit(node); err != nil {
			return err
		}
		visited++
		if limit > 0 && visited >= limit {
			return storage.ErrIterationStopped
		}
		return nil
	}
	// A materialized fallback's nodes go to visit as a list.
	visitAll := func(nodes []*storage.Node) error {
		if visit == nil {
			*collected = append(*collected, nodes...)
			return nil
		}
		return visitNodeList(nodes, visit)
	}
	// Whole query rows use the scan's metadata-only hydration decision. The
	// label body and its sidecar state are read together, once, including in
	// pinned transactions. Stores may ignore the label hint; collect retains
	// every residual label and property check.
	queryReader := e.queryNodeReader(store)
	if projection == nil && queryReader != nil && len(labels) > 0 {
		err := streamQueryNodes(ctx, store, labels, collect)
		if err == storage.ErrIterationStopped {
			return nil
		}
		return err
	}
	// A label-indexed stream is the primary physical scan for every labelled
	// MATCH. It preserves the shared row pipeline while keeping work
	// proportional to the matching label, applies residual predicates before
	// materialising rows, and lets LIMIT stop the storage iterator early.
	if len(labels) > 0 {
		if reader, ok := store.(storage.ProjectedLabelNodeReader); ok {
			err := reader.StreamNodesByLabelProjected(labels[0], projection, collect)
			if err == nil || err == storage.ErrIterationStopped {
				return nil
			}
			return err
		}
	}

	// Compatibility path for stores that expose label IDs but not label-node
	// streaming. This still avoids a full graph scan for bounded simple reads.
	if limit > 0 && len(labels) == 1 && len(properties) == 0 && strings.TrimSpace(whereClause) == "" {
		ids, err := storage.NodeIDsByLabel(store, labels[0], limit)
		if err != nil {
			return err
		}
		filtered := make([]*storage.Node, 0, util.SafePreallocCap(len(ids)))
		for _, id := range ids {
			node, getErr := e.getQueryNode(store, id)
			if getErr != nil {
				return getErr
			}
			if node == nil {
				continue
			}
			if hideSystemNodes && isSystemNode(node) {
				continue
			}
			if hasViewport && canCheckViewport {
				visible, err := checker.IsCurrentTemporalNode(node, viewport.AsOf)
				if err != nil {
					return err
				}
				if !visible {
					continue
				}
			}
			filtered = append(filtered, node)
			if len(filtered) >= limit {
				break
			}
		}
		return visitAll(filtered)
	}

	var nodes []*storage.Node
	var err error

	// A label-less property match reads every node (#824): decode only the
	// properties a match must have, let the engine skip a node that fails them
	// before decoding the rest of it, and read the whole node only for a
	// match. A required string is compared with the stored bytes, so a node
	// without it is skipped undecoded (#857). The node then passes the same
	// filters as on the full scan, including the whole WHERE. The required
	// properties are the pattern's and the WHERE's top-level equalities on
	// the variable (WHERE n.id = $id, #857), which every match satisfies.
	var required map[string]interface{}
	if len(labels) == 0 {
		required = e.labellessScanRequiredProperties(ctx, properties, whereVariable, whereClause)
	}
	if len(required) > 0 {
		keys := make([]string, 0, len(required))
		var stringEquals map[string]string
		for key, value := range required {
			keys = append(keys, key)
			if text, ok := value.(string); ok {
				if stringEquals == nil {
					stringEquals = make(map[string]string, len(required))
				}
				stringEquals[key] = text
			}
		}
		matches := func(props map[string]interface{}) bool {
			return nodePropertiesMatch(&storage.Node{Properties: props}, required)
		}
		err := store.StreamNodesWithOptions(ctx, storage.StreamNodesOptions{Projection: keys, ApplyDecayFilter: true, PropertyFilter: matches, PropertyStringEquals: stringEquals}, func(projected *storage.Node) error {
			if projected == nil || !matches(projected.Properties) {
				return nil
			}
			node, err := e.getQueryNode(store, projected.ID)
			if errors.Is(err, storage.ErrNotFound) {
				return nil
			}
			if err != nil {
				return err
			}
			return collect(node)
		})
		if err != nil && err != storage.ErrIterationStopped {
			return err
		}
		return nil
	}

	// Streaming is the shared scan primitive for the converged executor. Apply
	// every residual filter in the visitor so both bounded and unbounded scans
	// avoid the storage APIs that first materialize the complete population.
	// LIMIT additionally stops storage iteration as soon as enough qualifying
	// nodes have been produced.
	if queryReader != nil {
		if projection == nil {
			err = streamQueryNodes(ctx, store, labels, collect)
		} else {
			err = store.StreamNodesWithOptions(ctx, storage.StreamNodesOptions{Projection: projection, ApplyDecayFilter: true}, collect)
		}
		if err == storage.ErrIterationStopped {
			return nil
		}
		return err
	}
	if streamer, ok := store.(storage.StreamingEngine); ok {
		err = streamer.StreamNodes(ctx, collect)
		if err == storage.ErrIterationStopped {
			err = nil
		}
		return err
	}

	// Compatibility fallback for storage implementations without StreamingEngine.
	if len(labels) > 0 {
		nodes, err = store.GetNodesByLabel(labels[0])
	} else {
		nodes, err = store.AllNodes()
	}
	if err != nil {
		return err
	}

	// Filter out system nodes (labels starting with _)
	filteredNodes := make([]*storage.Node, 0, len(nodes))
	for _, node := range nodes {
		if len(labels) > 0 && !mergeNodeHasLabels(node, labels) {
			continue
		}
		if !hideSystemNodes || !isSystemNode(node) {
			filteredNodes = append(filteredNodes, node)
		}
	}
	nodes = filteredNodes
	if hasViewport && canCheckViewport {
		nodes, err = filterNodesByTemporalViewport(nodes, viewport, checker)
		if err != nil {
			return err
		}
	}

	// Apply property filters
	if len(properties) > 0 {
		nodes = e.filterNodesByProperties(nodes, properties)
	}
	if strings.TrimSpace(whereClause) != "" {
		nodes = e.filterNodes(ctx, nodes, whereVariable, whereClause)
	}
	if limit > 0 && len(nodes) > limit {
		nodes = nodes[:limit]
	}

	return visitAll(nodes)
}

// visitNodeList hands nodes to visit in order. visit returning
// storage.ErrIterationStopped ends the visit without error; any other error
// ends it with that error.
func visitNodeList(nodes []*storage.Node, visit func(*storage.Node) error) error {
	for _, node := range nodes {
		if err := visit(node); err != nil {
			if err == storage.ErrIterationStopped {
				return nil
			}
			return err
		}
	}
	return nil
}

// labellessScanRequiredProperties returns the property values every node a
// label-less scan may match must have: the pattern's properties and the
// WHERE's top-level equalities between variable.property and a constant
// (parameter, literal or bound value; parseSimpleIndexedEquality). Over-
// approximating the WHERE is safe because the caller still evaluates it on
// every node the scan returns.
func (e *StorageExecutor) labellessScanRequiredProperties(ctx context.Context, properties map[string]interface{}, variable, whereClause string) map[string]interface{} {
	clause := unwrapOuterParens(strings.TrimSpace(whereClause))
	if clause == "" || strings.TrimSpace(variable) == "" {
		return properties
	}
	required := make(map[string]interface{}, len(properties)+1)
	for key, value := range properties {
		required[key] = value
	}
	for _, conjunct := range splitTopLevelAndConjuncts(clause) {
		property, value, ok := e.parseSimpleIndexedEquality(ctx, variable, unwrapOuterParens(strings.TrimSpace(conjunct)))
		if !ok {
			continue
		}
		if _, exists := required[property]; !exists {
			required[property] = value
		}
	}
	return required
}

func shouldHideSystemNodes(engine storage.Engine) bool {
	// Allow system nodes to be queried when the active database is system.
	// For all other databases, hide internal nodes (labels starting with "_")
	// to avoid leaking metadata into normal user queries.
	if namespaced, ok := engine.(*storage.NamespacedEngine); ok {
		return namespaced.Namespace() != "system"
	}
	return true
}

func isSystemNode(node *storage.Node) bool {
	if node == nil {
		return false
	}
	for _, label := range node.Labels {
		if strings.HasPrefix(label, "_") {
			return true
		}
	}
	return false
}

type cartesianInConstraint struct {
	prop      string
	allowed   map[string]struct{}
	hasValues bool
}

type cartesianEqConstraint struct {
	leftVar   string
	leftProp  string
	rightVar  string
	rightProp string
	// offset is the integer offset in leftVar.leftProp = rightVar.rightProp
	// + offset, parsed from joins like b.id = a.id + 1 (#692). 0 means a
	// plain property equality.
	offset int64
}

func (e *StorageExecutor) applyCartesianWherePushdown(
	ctx context.Context,
	patternMatches []struct {
		variable string
		nodes    []*storage.Node
	},
	whereClause string,
) []struct {
	variable string
	nodes    []*storage.Node
} {
	if len(patternMatches) < 2 || strings.TrimSpace(whereClause) == "" {
		return patternMatches
	}

	varIndex := make(map[string]int, len(patternMatches))
	for i, pm := range patternMatches {
		if pm.variable != "" {
			varIndex[pm.variable] = i
		}
	}

	inConstraints := map[string]cartesianInConstraint{}
	nullConstraints := map[string]cartesianNullConstraint{}
	eqConstraints := make([]cartesianEqConstraint, 0, 2)
	for _, term := range splitTopLevelAndConjuncts(whereClause) {
		term = strings.TrimSpace(term)
		if term == "" {
			continue
		}
		if v, p, vals, ok := parseCartesianInListTerm(term); ok {
			c := inConstraints[v]
			if c.prop == "" {
				c.prop = p
				c.allowed = make(map[string]struct{}, len(vals))
				for _, raw := range vals {
					c.allowed[cypherValueKey(raw, cypherValueEqualityContract)] = struct{}{}
				}
				c.hasValues = true
			}
			inConstraints[v] = c
			continue
		}
		if v, p, expectNotNull, ok := parseCartesianNullTerm(term); ok {
			key := v + "|" + p
			c := nullConstraints[key]
			if c.hasValue && c.expectNotNull != expectNotNull {
				c.conflict = true
			} else {
				c.expectNotNull = expectNotNull
				c.hasValue = true
			}
			nullConstraints[key] = c
			continue
		}
		if lv, lp, rv, rp, offset, ok := parseCartesianVarPropEqualityTerm(term); ok {
			eqConstraints = append(eqConstraints, cartesianEqConstraint{
				leftVar:   lv,
				leftProp:  lp,
				rightVar:  rv,
				rightProp: rp,
				offset:    offset,
			})
			continue
		}
		if variable, ok := parseCartesianSingleNodeComparisonTerm(term); ok {
			idx, exists := varIndex[variable]
			if !exists {
				continue
			}
			predicate, supported := e.getCompiledSimpleWhere(ctx, variable, term)
			if !supported {
				continue
			}
			filtered := make([]*storage.Node, 0, len(patternMatches[idx].nodes))
			for _, node := range patternMatches[idx].nodes {
				if node != nil && predicate(node) {
					filtered = append(filtered, node)
				}
			}
			patternMatches[idx].nodes = filtered
		}
	}

	applyCartesianNullConstraints(patternMatches, varIndex, nullConstraints)

	// Apply direct IN constraints.
	for v, c := range inConstraints {
		if !c.hasValues {
			continue
		}
		idx, ok := varIndex[v]
		if !ok {
			continue
		}
		patternMatches[idx].nodes = filterNodesByAllowedPropSet(patternMatches[idx].nodes, c.prop, c.allowed, cypherValueEqualityContract)
	}

	// Propagate equality constraints both directions until stable.
	for changed := true; changed; {
		changed = false
		for _, c := range eqConstraints {
			leftIdx, lok := varIndex[c.leftVar]
			rightIdx, rok := varIndex[c.rightVar]
			if !lok || !rok {
				continue
			}
			leftAllowed := collectPropValues(patternMatches[leftIdx].nodes, c.leftProp, cypherValueEqualityContract)
			rightAllowed := collectPropValues(patternMatches[rightIdx].nodes, c.rightProp, cypherValueEqualityContract)
			if len(leftAllowed) == 0 || len(rightAllowed) == 0 {
				continue
			}
			// leftVar.leftProp = rightVar.rightProp + offset:
			//   allowed right values = left values shifted by -offset
			//   allowed left values  = right values shifted by +offset
			rightCandidates := leftAllowed
			leftCandidates := rightAllowed
			if c.offset != 0 {
				rightCandidates = shiftCartesianIntKeySet(leftAllowed, -c.offset, cypherValueEqualityContract)
				leftCandidates = shiftCartesianIntKeySet(rightAllowed, c.offset, cypherValueEqualityContract)
				if len(rightCandidates) == 0 || len(leftCandidates) == 0 {
					continue
				}
			}
			if filtered := filterNodesByAllowedPropSet(patternMatches[rightIdx].nodes, c.rightProp, rightCandidates, cypherValueEqualityContract); len(filtered) != len(patternMatches[rightIdx].nodes) {
				patternMatches[rightIdx].nodes = filtered
				changed = true
			}
			if filtered := filterNodesByAllowedPropSet(patternMatches[leftIdx].nodes, c.leftProp, leftCandidates, cypherValueEqualityContract); len(filtered) != len(patternMatches[leftIdx].nodes) {
				patternMatches[leftIdx].nodes = filtered
				changed = true
			}
		}
	}
	return patternMatches
}

// shiftCartesianIntKeySet shifts the integer values in a cartesian value-key
// set by offset, dropping keys that are not integers. The shifted set names
// the property values that may pair with the original set under an
// lv.lp = rv.rp + offset constraint (#692).
func shiftCartesianIntKeySet(set map[string]struct{}, offset int64, contract cypherComparisonContract) map[string]struct{} {
	out := make(map[string]struct{}, len(set))
	for key := range set {
		var digits string
		switch {
		case strings.HasPrefix(key, "i64:"):
			digits = key[len("i64:"):]
		case strings.HasPrefix(key, "i:"):
			digits = key[len("i:"):]
		default:
			continue
		}
		value, err := strconv.ParseInt(digits, 10, 64)
		if err != nil {
			continue
		}
		out[fmt.Sprintf("i64:%d", value+offset)] = struct{}{}
	}
	return out
}

func applyCartesianNullConstraints(
	patternMatches []struct {
		variable string
		nodes    []*storage.Node
	},
	varIndex map[string]int,
	nullConstraints map[string]cartesianNullConstraint,
) {
	for key, constraint := range nullConstraints {
		parts := strings.SplitN(key, "|", 2)
		if len(parts) != 2 {
			continue
		}
		idx, ok := varIndex[parts[0]]
		if !ok {
			continue
		}
		if constraint.conflict {
			patternMatches[idx].nodes = patternMatches[idx].nodes[:0]
			continue
		}
		patternMatches[idx].nodes = filterNodesByNullConstraint(patternMatches[idx].nodes, parts[1], constraint.expectNotNull)
	}
}

func parseCartesianNullTerm(term string) (string, string, bool, bool) {
	upper := upperASCII(strings.TrimSpace(term))
	if strings.HasSuffix(upper, " IS NOT NULL") {
		expr := strings.TrimSpace(term[:len(term)-len(" IS NOT NULL")])
		v, p, ok := parseCartesianVarProp(expr)
		if !ok {
			return "", "", false, false
		}
		return v, p, true, true
	}
	if strings.HasSuffix(upper, " IS NULL") {
		expr := strings.TrimSpace(term[:len(term)-len(" IS NULL")])
		v, p, ok := parseCartesianVarProp(expr)
		if !ok {
			return "", "", false, false
		}
		return v, p, false, true
	}
	return "", "", false, false
}

func parseCartesianVarProp(expr string) (string, string, bool) {
	expr = strings.TrimSpace(expr)
	dot := strings.IndexByte(expr, '.')
	if dot <= 0 || dot >= len(expr)-1 {
		return "", "", false
	}
	v := strings.TrimSpace(expr[:dot])
	p := strings.TrimSpace(expr[dot+1:])
	property, validProperty := isOneSymbolicName(p)
	if !isSimpleIdentifierCartesian(v) || !validProperty {
		return "", "", false
	}
	return v, property, true
}

func parseCartesianSingleNodeComparisonTerm(term string) (string, bool) {
	clause := strings.TrimSpace(term)
	scan, comparison := scanComparisonChain(clause)
	if !comparison || scan.count != 1 {
		return "", false
	}
	span := scan.operator(0)
	operator := clause[span.offset : span.offset+span.length]
	switch operator {
	case "=", "<>", "!=", ">", ">=", "<", "<=", "=~":
	default:
		return "", false
	}
	variable, _, ok := parseCartesianVarProp(clause[:span.offset])
	if !ok {
		return "", false
	}
	if _, ok := parseLiteralValue(clause[span.offset+span.length:]); !ok {
		return "", false
	}
	return variable, true
}

func parseCartesianInListTerm(term string) (string, string, []interface{}, bool) {
	upper := upperASCII(term)
	idx := strings.Index(upper, " IN ")
	if idx <= 0 || idx+4 >= len(term) {
		return "", "", nil, false
	}
	lhs := strings.TrimSpace(term[:idx])
	rhs := strings.TrimSpace(term[idx+4:])
	v, p, ok := parseCartesianVarProp(lhs)
	if !ok {
		return "", "", nil, false
	}
	if !isListLiteral(rhs) {
		return "", "", nil, false
	}
	inner := strings.TrimSpace(rhs[1 : len(rhs)-1])
	if inner == "" {
		return v, p, []interface{}{}, true
	}
	items := splitTopLevelCommaKeepEmpty(inner)
	values := make([]interface{}, 0, len(items))
	for _, raw := range items {
		lit, ok := parseLiteralValue(strings.TrimSpace(raw))
		if !ok {
			return "", "", nil, false
		}
		values = append(values, lit)
	}
	return v, p, values, true
}

func isSimpleIdentifierCartesian(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if isIdentStartByte(ch) {
			continue
		}
		if i > 0 && ch >= '0' && ch <= '9' {
			continue
		}
		return false
	}
	return true
}

func parseCartesianVarPropEqualityTerm(term string) (string, string, string, string, int64, bool) {
	idx := strings.Index(term, "=")
	if idx <= 0 || idx+1 >= len(term) {
		return "", "", "", "", 0, false
	}
	lhs := strings.TrimSpace(term[:idx])
	rhs := strings.TrimSpace(term[idx+1:])
	if lv, lp, lok := parseCartesianVarProp(lhs); lok {
		if rv, rp, rok := parseCartesianVarProp(rhs); rok {
			return lv, lp, rv, rp, 0, true
		}
		// b.id = a.id + 1: the right side is an offset expression.
		if rv, rp, offset, rok := parseCartesianVarPropOffset(rhs); rok {
			return lv, lp, rv, rp, offset, true
		}
	}
	// a.id + 1 = b.id normalizes to b.id = a.id + 1.
	if lv, lp, offset, lok := parseCartesianVarPropOffset(lhs); lok {
		if rv, rp, rok := parseCartesianVarProp(rhs); rok {
			return rv, rp, lv, lp, offset, true
		}
	}
	return "", "", "", "", 0, false
}

// parseCartesianVarPropOffset parses <var>.<prop> + <int> or
// <var>.<prop> - <int> with an integer literal offset, independent of
// whitespace around the operator (b.id=a.id+1 parses the same as
// b.id = a.id + 1, #692).
func parseCartesianVarPropOffset(expr string) (string, string, int64, bool) {
	expr = strings.TrimSpace(expr)
	for i := 0; i < len(expr); i++ {
		ch := expr[i]
		if ch != '+' && ch != '-' {
			continue
		}
		left := strings.TrimSpace(expr[:i])
		literal := strings.TrimSpace(expr[i+1:])
		variable, prop, ok := parseCartesianVarProp(left)
		if !ok {
			continue
		}
		offset, err := strconv.ParseInt(literal, 10, 64)
		if err != nil {
			return "", "", 0, false
		}
		if ch == '-' {
			offset = -offset
		}
		return variable, prop, offset, true
	}
	return "", "", 0, false
}

// addInt64Offset adds offset to value exactly, reporting false when the sum
// overflows int64.
func addInt64Offset(value, offset int64) (int64, bool) {
	sum := value + offset
	if (offset > 0 && sum < value) || (offset < 0 && sum > value) {
		return 0, false
	}
	return sum, true
}

// cartesianShiftValueKey shifts an integer property value by offset exactly
// (no float64 rounding above 2^53, #692), keeping its stored type in the
// key. It reports false when the value is not an integer or the shift
// overflows.
func cartesianShiftValueKey(v interface{}, offset int64, contract cypherComparisonContract) (string, bool) {
	var base int64
	switch x := v.(type) {
	case int:
		base = int64(x)
	case int64:
		base = x
	default:
		return "", false
	}
	sum, ok := addInt64Offset(base, offset)
	if !ok {
		return "", false
	}
	switch v.(type) {
	case int:
		return cypherValueKey(int(sum), contract), true
	default:
		return cypherValueKey(sum, contract), true
	}
}

// cartesianOffsetValuesEqual reports whether left == right + offset.
// Integer values compare exactly (no float64 rounding above 2^53, #692);
// non-integer values compare through float64, and non-numeric values never
// satisfy an offset join.
func cartesianOffsetValuesEqual(left, right interface{}, offset int64) bool {
	if li, lok := int64OfValue(left); lok {
		if ri, rok := int64OfValue(right); rok {
			sum, ok := addInt64Offset(ri, offset)
			return ok && li == sum
		}
	}
	lNum, lNumeric := toFloat64(left)
	rNum, rNumeric := toFloat64(right)
	return lNumeric && rNumeric && lNum == rNum+float64(offset)
}

// int64OfValue reports an integer value exactly (int or int64).
func int64OfValue(v interface{}) (int64, bool) {
	return valueconvert.IntegerValue(v)
}

// Cartesian keys implement predicate equality for both candidate pushdown
// and indexed MATCH joins (including MATCH ... CREATE). DISTINCT/grouping
// equivalence would discard equal named-zone overlap datetimes here.

func collectPropValues(nodes []*storage.Node, prop string, contract cypherComparisonContract) map[string]struct{} {
	out := make(map[string]struct{}, len(nodes))
	for _, n := range nodes {
		if n == nil || n.Properties == nil {
			continue
		}
		val, ok := n.Properties[prop]
		if !ok {
			continue
		}
		out[cypherValueKey(val, contract)] = struct{}{}
	}
	return out
}

func filterNodesByAllowedPropSet(nodes []*storage.Node, prop string, allowed map[string]struct{}, contract cypherComparisonContract) []*storage.Node {
	if len(nodes) == 0 || len(allowed) == 0 {
		return nodes
	}
	out := make([]*storage.Node, 0, len(nodes))
	for _, n := range nodes {
		if n == nil || n.Properties == nil {
			continue
		}
		val, ok := n.Properties[prop]
		if !ok {
			continue
		}
		if _, keep := allowed[cypherValueKey(val, contract)]; keep {
			out = append(out, n)
		}
	}
	return out
}

type cartesianNullConstraint struct {
	expectNotNull bool
	hasValue      bool
	conflict      bool
}

func filterNodesByNullConstraint(nodes []*storage.Node, prop string, expectNotNull bool) []*storage.Node {
	if len(nodes) == 0 {
		return nodes
	}
	out := make([]*storage.Node, 0, len(nodes))
	for _, n := range nodes {
		if n == nil {
			continue
		}
		val, exists := n.Properties[prop]
		isNull := !exists || val == nil
		if expectNotNull {
			if !isNull {
				out = append(out, n)
			}
			continue
		}
		if isNull {
			out = append(out, n)
		}
	}
	return out
}

// evaluateWhereForContext evaluates a WHERE clause against a node context
func (e *StorageExecutor) evaluateWhereForContext(ctx context.Context, whereClause string, nodes map[string]*storage.Node) bool {
	if strings.TrimSpace(whereClause) == "" {
		return true
	}
	predicate := e.newBindingFilterPredicate(ctx, whereClause, nil)
	return predicate.matches(binding(nodes), nil)
}

// evaluateBoundRelationshipPattern evaluates a WHERE pattern against the
// current bindings using the same parser and traversal implementation as a
// MATCH clause. The second return value distinguishes a valid pattern that did
// not match from an expression that is not a relationship pattern.
func (e *StorageExecutor) evaluateBoundRelationshipPattern(ctx context.Context, clause string, nodes map[string]*storage.Node) (bool, bool) {
	return e.evaluateRowRelationshipPattern(ctx, clause, entityRow(ctx, nodes, nil))
}

// Every predicate adapter passes its complete row here, including scalar,
// relationship and node bindings. Parsing consumes the same prepared values
// as MATCH, instead of evaluating a node-only view during recognition.
func (e *StorageExecutor) evaluateRowRelationshipPattern(ctx context.Context, clause string, values map[string]interface{}) (bool, bool) {
	if !isRelationshipPatternOperand(strings.TrimSpace(clause)) {
		return false, false
	}
	rowCtx, pattern, err := e.preparePatternRow(ctx, strings.TrimSpace(clause), values)
	if err != nil {
		recordExpressionFailure(ctx, err)
		return false, true
	}
	match, recognized := e.parseBoundRelationshipPattern(rowCtx, pattern)
	if !recognized {
		return false, false
	}
	nodes, _ := withWhereValueContext(values)
	return e.evaluateParsedBoundRelationshipPattern(rowCtx, match, nodes), true
}

// parseBoundRelationshipPattern parses clause as a relationship pattern
// predicate ((a)-[:R]->(b)). Only a text that is one whole relationship chain
// (isRelationshipPatternOperand) is a pattern: a parenthesised expression
// whose subqueries hold patterns, (NOT EXISTS { (h)-[:C]->(x) } AND …), is
// not one.
func (e *StorageExecutor) parseBoundRelationshipPattern(ctx context.Context, clause string) (*TraversalMatch, bool) {
	return readBoundRelationshipPattern(ctx, clause, e.parseTraversalPattern)
}

func (e *StorageExecutor) parseBoundRelationshipPatternStructure(ctx context.Context, clause string) (*TraversalMatch, bool) {
	return readBoundRelationshipPattern(ctx, clause, e.parseTraversalPatternStructure)
}

func readBoundRelationshipPattern(ctx context.Context, clause string, read func(context.Context, string) *TraversalMatch) (*TraversalMatch, bool) {
	pattern := strings.TrimSpace(clause)
	if !isRelationshipPatternOperand(pattern) {
		return nil, false
	}

	match := read(ctx, pattern)
	if match == nil || len(match.Segments) == 0 && match.Relationship.MinHops == 0 && !match.Relationship.VariableLength {
		return nil, false
	}
	return match, true
}

func (e *StorageExecutor) evaluateParsedBoundRelationshipPattern(ctx context.Context, match *TraversalMatch, nodes map[string]*storage.Node) bool {
	if match.StartNode.variable != "" && nodes[match.StartNode.variable] == nil ||
		match.EndNode.variable != "" && nodes[match.EndNode.variable] == nil {
		return false
	}
	for _, intermediate := range match.IntermediateNodes {
		if intermediate.variable != "" && nodes[intermediate.variable] == nil {
			return false
		}
	}
	if !match.IsChained && match.Relationship.MinHops == 1 && match.Relationship.MaxHops == 1 {
		return e.evaluateBoundOneHopPattern(ctx, match, nodes)
	}

	var paths []PathResult
	if start := nodes[match.StartNode.variable]; start != nil {
		if match.IsChained && len(match.Segments) > 1 {
			paths = e.traverseChainedGraph(ctx, match, []*storage.Node{start})
		} else {
			paths = e.traverseFromNode(ctx, start, match)
		}
	} else if end := nodes[match.EndNode.variable]; end != nil && !match.IsChained {
		reversed := reverseTraversalMatch(match)
		if reversed == nil {
			return false
		}
		for _, reversedPath := range e.traverseFromNode(ctx, end, reversed) {
			paths = append(paths, reversePathResult(reversedPath))
		}
	} else {
		paths = e.traverseGraph(ctx, match)
	}

	existing := binding(nodes)
	for _, path := range paths {
		pathContext := e.buildPathContext(path, match)
		if _, compatible := mergeNodeBindingsChecked(existing, pathContext.nodes); compatible {
			return true
		}
	}
	return false
}

func (e *StorageExecutor) evaluateBoundOneHopPattern(ctx context.Context, match *TraversalMatch, nodes map[string]*storage.Node) bool {
	start := nodes[match.StartNode.variable]
	if start == nil {
		end := nodes[match.EndNode.variable]
		if end == nil {
			return false
		}
		reversed := reverseTraversalMatch(match)
		return reversed != nil && e.evaluateBoundOneHopPattern(ctx, reversed, nodes)
	}
	if !e.pipelineNodeMatchesPattern(start, match.StartNode) {
		return false
	}
	viewport, _ := TemporalViewportFromContext(ctx)
	checker, _ := e.getStorage(ctx).(temporalCurrentNodeChecker)
	paths := e.traverseGraphSequential(ctx, match, []*storage.Node{start}, viewport, checker)
	end, bound := nodes[match.EndNode.variable]
	for _, path := range paths {
		if len(path.Nodes) == 0 {
			continue
		}
		if !bound || end != nil && path.Nodes[len(path.Nodes)-1].ID == end.ID {
			return true
		}
	}
	return false
}

// executeCreate handles CREATE queries.

package cypher

import (
	"context"
	"fmt"
	"maps"
	"strings"

	cypherantlr "github.com/orneryd/nornicdb/pkg/cypher/antlr"
	"github.com/orneryd/nornicdb/pkg/cypher/resultmetadata"
	"github.com/orneryd/nornicdb/pkg/localization"
)

type matchBindingKind uint8

const (
	matchBindingUnknown matchBindingKind = iota
	matchBindingNode
	matchBindingRelationship
	matchBindingRelationshipList
	matchBindingNodeList
	matchBindingPath
	matchBindingValue
)

type matchSemanticScope map[string]matchBindingKind

// validateMatchSemanticScopes applies entity-type rules before physical query
// routing. MATCH variables may be reused only when their binding kind remains
// stable; a node name cannot already denote a relationship, path, or scalar.
// A statement that passes is cached by its text and language version,
// unless a Fabric APPLY binds variables for it: then the result depends on
// the bound record. cypher25 holds a Cypher 25 statement to Neo4j 2026.09's
// compile-time type rules (staticTypeScope.cypher25).
func (e *StorageExecutor) validateMatchSemanticScopes(ctx context.Context, cypher string, cypher25 bool) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	cacheable := len(e.fabricRecordBindings) == 0
	key := semanticCacheKey(cypher, cypher25)
	if cacheable && e.matchSemanticValidationCache.contains(key) {
		return nil
	}
	if err := checkedWithoutUnaryPlus(ctx, cypher, cypher25, func(text string) error {
		return e.validateMatchSemanticScopesUncached(ctx, text, cypher25)
	}); err != nil {
		return err
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if cacheable {
		e.matchSemanticValidationCache.add(key)
	}
	return nil
}

// semanticCacheKey is a validation cache's key for a statement: its text,
// marked for a Cypher 25 statement, whose checks differ.
func semanticCacheKey(cypher string, cypher25 bool) string {
	if cypher25 {
		return "cypher25:" + cypher
	}
	return cypher
}

func (e *StorageExecutor) validateMatchSemanticScopesUncached(ctx context.Context, source string, cypher25 bool) error {
	if isSchemaCommandStatement(source) || isNornicExtensionStatement(source) || isSystemCommandNoGraph(source) {
		return nil
	}
	initial := make(typeScope, len(e.fabricRecordBindings))
	for name := range e.fabricRecordBindings {
		initial[name] = staticOperand{}
	}
	for name := range valueBindingsFromContext(ctx) {
		initial[name] = staticOperand{}
	}
	_, _, err := e.enrichBoundTypes(ctx, source, initial, semanticBodyFromContext(ctx), "", cypher25)
	return err
}
func validateQueryBodyComposition(ctx context.Context, source string) error {
	admission, err := (&StorageExecutor{}).admitBoundStatement(ctx, source)
	if err != nil {
		return err
	}
	if admission.command {
		return validateCommandBodyComposition(ctx, source)
	}
	return nil
}

// expressionBodyUpdatesMessages is the error for an update in each
// expression container's body.
var expressionBodyUpdatesMessages = map[string]func() localization.Message{
	"EXISTS":  localization.CypherMatchingExistsExpressionUpdates,
	"COUNT":   localization.CypherMatchingCountExpressionUpdates,
	"COLLECT": localization.CypherMatchingCollectExpressionUpdates,
}

// updatingClauses are the clause kinds that update the graph.
var updatingClauses = map[pipelineClauseKind]bool{
	pipelineClauseCreate: true, pipelineClauseMerge: true, pipelineClauseDelete: true,
	pipelineClauseSet: true, pipelineClauseRemove: true, pipelineClauseForeach: true,
}

// queryBodyEndings is how each clause kind ends a query body: the keyword
// Neo4j names when it can't ("Query cannot conclude with MATCH"), or "" when
// it concludes the body (RETURN, an update clause, a procedure call). A CALL
// subquery concludes only as a unit subquery (a direct RETURN in its body).
// Every clause kind is listed (TestQueryBodyEndingsCoverEveryClauseKind).
var queryBodyEndings = map[pipelineClauseKind]string{
	pipelineClauseMatch: "MATCH", pipelineClauseOptionalMatch: "MATCH", pipelineClauseWith: "WITH",
	pipelineClauseUnwind: "UNWIND", pipelineClauseLet: "LET", pipelineClauseFilter: "FILTER",
	pipelineClauseCallSubquery: "CALL",
	pipelineClauseReturn:       "", pipelineClauseCreate: "", pipelineClauseMerge: "", pipelineClauseDelete: "",
	pipelineClauseSet: "", pipelineClauseRemove: "", pipelineClauseForeach: "", pipelineClauseCall: "",
}

func returnsStar(ctx context.Context, clause string) bool {
	node, found := canonicalQueryClause(ctx, clause)
	return found && projectionPlanFromSyntax(node).star
}

func validateWithOrderBySemanticScope(ctx context.Context, input matchSemanticScope, clause string, retained typeScope, admitted ...matchSemanticScope) error {
	body := strings.TrimSpace(clause[len("WITH"):])
	orderIndex := topLevelKeywordIndex(body, "ORDER BY")
	if orderIndex < 0 {
		return nil
	}
	orderBody := strings.TrimSpace(body[keywordEndAt(body, orderIndex, "ORDER BY"):])
	projectionBody := strings.TrimSpace(body[:orderIndex])
	hasProjectionAggregate := false
	for _, item := range splitTopLevelComma(projectionBody) {
		expression, _ := parseProjectionExprAlias(ctx, strings.TrimSpace(item))
		if containsAggregateFunc(expression) {
			hasProjectionAggregate = true
			break
		}
	}
	if err := validateReturnOrderBySemanticScopeIn(ctx, "RETURN "+body, retained); err != nil {
		return err
	}
	for _, term := range parseOrderByClause(orderBody) {
		if containsAggregateFunc(term.column) && !hasProjectionAggregate {
			return newSemanticError(
				"Neo.ClientError.Statement.SyntaxError",
				"InvalidAggregation",
				"ORDER BY cannot introduce an aggregate after a non-aggregating WITH",
			)
		}
	}
	output := matchSemanticScope(nil)
	if len(admitted) > 0 {
		output = admitted[0]
	} else {
		output = projectMatchSemanticScope(ctx, input, clause)
	}
	return validateOrderByReferences(input, output, orderBody)
}

// validateOrderByReferences checks that every variable an ORDER BY of a WITH
// or RETURN reads is in the clause's incoming scope or one it projects, as
// Neo4j does ("Variable `y` not defined"). orderBody is the text after ORDER
// BY; its SKIP / LIMIT are ignored.
func validateOrderByReferences(input, output matchSemanticScope, orderBody string) error {
	for _, keyword := range []string{"SKIP", "LIMIT"} {
		if index := topLevelKeywordIndex(orderBody, keyword); index >= 0 {
			orderBody = strings.TrimSpace(orderBody[:index])
		}
	}
	for _, term := range parseOrderByClause(orderBody) {
		for _, reference := range semanticFreeReferences(term.column) {
			base := strings.SplitN(reference, ".", 2)[0]
			if _, available := input[base]; available {
				continue
			}
			if _, projected := output[base]; projected {
				continue
			}
			return createUndefinedVariableError(base)
		}
	}
	return nil
}

func validateReturnSemanticScope(ctx context.Context, scope matchSemanticScope, clause string) error {
	return validateReturnSemanticScopeIn(ctx, scope, clause, nil)
}

// The body value distinguishes retained ordering inputs from scalar ancestor
// constants. A retained CALL import is not an automatic aggregate grouping key.
func validateReturnSemanticScopeIn(ctx context.Context, scope matchSemanticScope, clause string, bodyScope *semanticBodyScope) error {
	if err := validateReturnOrderBySemanticScopeIn(ctx, clause, bodyScope.orderConstants()); err != nil {
		return err
	}
	body := strings.TrimSpace(clause[len("RETURN"):])
	if err := validateReturnAggregationSemanticsIn(ctx, body, bodyScope.aggregateConstants()); err != nil {
		return err
	}
	// A dangling modifier keyword (RETURN 1 ORDER BY / SKIP / LIMIT) and an
	// empty projection (RETURN, WITH 1 AS x RETURN) are Neo4j syntax errors.
	// The clause is scanned with its keyword, which tells a keyword-named
	// first item from a clause (RETURN skip[0], #894).
	clauseText := strings.TrimSpace(clause)
	projectionEnd := len(clauseText)
	for _, keyword := range []string{"ORDER BY", "SKIP", "LIMIT"} {
		index := topLevelKeywordIndex(clauseText, keyword)
		if index < len("RETURN") || index >= projectionEnd {
			continue
		}
		if strings.TrimSpace(clauseText[index+len(keyword):]) == "" {
			return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
				localization.CypherCoreInvalidInputExpectedExpression(""))
		}
		projectionEnd = index
	}
	projectionText := strings.TrimSpace(clauseText[len("RETURN"):projectionEnd])
	body, _ = cutDistinct(projectionText)
	if body == "" {
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			localization.CypherMatchingReturnExpressionRequired())
	}
	if orderIndex := topLevelKeywordIndex(clauseText, "ORDER BY"); orderIndex >= len("RETURN") {
		projection := strings.TrimSpace(clauseText[len("RETURN"):orderIndex])
		if err := validateOrderByReferences(scope, projectMatchSemanticScope(ctx, scope, "WITH "+projection), strings.TrimSpace(clauseText[keywordEndAt(clauseText, orderIndex, "ORDER BY"):])); err != nil {
			return err
		}
	}
	for _, raw := range splitTopLevelComma(body) {
		expression, _ := parseProjectionExprAlias(ctx, strings.TrimSpace(raw))
		if err := projectionItemTermError(expression); err != nil {
			return err
		}
		if err := undefinedExpressionVariable(ctx, scope, expression); err != nil {
			return err
		}
		if expression == "*" {
			if len(scope) == 0 {
				return &classifiedCypherError{
					cause:  localizedError(localization.CypherMatchingReturnStarNoVariables(), nil),
					code:   "Neo.ClientError.Statement.SyntaxError",
					detail: "NoVariablesInScope",
				}
			}
			continue
		}
		if _, literal := parseLiteralValueFromComputedRow(expression); literal {
			continue
		}
		variable := simpleSemanticIdentifier(expression)
		if variable == "" {
			// m.val: the property chain's variable must be bound.
			if base, _, chain := rowPropertyChainShape(expression); chain {
				variable = base
			}
		}
		// null.a is a property of null (null), not of a variable.
		if variable != "" && !isLiteralKeyword(variable) {
			if _, found := scope[variable]; !found {
				return createUndefinedVariableError(variable)
			}
		}
	}
	return nil
}

// undefinedExpressionVariable is "Variable `x` not defined" for the first
// variable expression reads that scope doesn't bind: anywhere in it,
// inside a CASE, a list, a map projection or a comprehension's WHERE and
// projection included, as in Neo4j (#907). A comprehension's or a
// reduce's own variable is bound inside it (expressionFreeVariables).
func undefinedExpressionVariable(ctx context.Context, scope matchSemanticScope, expression string) error {
	// A literal, a variable or a property chain reads at most its base
	// variable: checked without the scanner.
	if _, literal := parseLiteralValueFromComputedRow(expression); literal {
		return nil
	}
	variable := simpleSemanticIdentifier(expression)
	if variable == "" {
		if base, _, chain := rowPropertyChainShape(expression); chain {
			variable = base
		}
	}
	if variable != "" {
		if _, found := scope[variable]; !found && !isLiteralKeyword(variable) {
			return createUndefinedVariableError(variable)
		}
		return nil
	}
	// expressionFreeVariables leaves out true, false, null and the other
	// literal words.
	for _, name := range expressionFreeVariables(ctx, expression) {
		if _, found := scope[name]; !found {
			return createUndefinedVariableError(name)
		}
	}
	return nil
}

func (e *StorageExecutor) validateMatchClauseBindings(scope matchSemanticScope, clause string) error {
	pattern := strings.TrimSpace(clause)
	for _, keyword := range []string{"OPTIONAL MATCH", "MATCH"} {
		if startsWithKeywordFold(pattern, keyword) {
			pattern = strings.TrimSpace(pattern[len(keyword):])
			break
		}
	}
	whereClause := ""
	// A WHERE inside parentheses is a quantified path pattern's own.
	if where := topLevelKeywordIndex(pattern, "WHERE"); where >= 0 {
		whereClause = strings.TrimSpace(pattern[where+len("WHERE"):])
	}
	// A quantified group's WHERE is an expression, not pattern structure.
	pattern = strings.TrimSpace(matchPatternStructure(pattern))
	if mergePatternUsesParameterPredicate(pattern) {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidParameterUse",
			"MATCH pattern predicates must use a property map, not a parameter map",
		)
	}
	if invalidRelationshipPattern(pattern) {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidRelationshipPattern",
			"invalid variable-length relationship pattern",
		)
	}

	variableLengthRelationships := variableLengthRelationshipVariableSet(pattern)
	groupNodes, groupRelationships := quantifiedGroupVariables(pattern)
	for _, patternPart := range splitTopLevelComma(pattern) {
		patternPart = strings.TrimSpace(patternPart)
		pathVariable := extractPathAssignmentVariable(patternPart)
		entityPattern := patternPart
		if pathVariable != "" {
			if equals := strings.Index(patternPart, "="); equals >= 0 {
				entityPattern = strings.TrimSpace(patternPart[equals+1:])
			}

			scope[pathVariable] = matchBindingPath
		}

		if _, _, _, selected := splitPathSelectorTerm(whereClause); !selected {
			if err := validateShortestCallBindings(entityPattern, scope); err != nil {
				return err
			}
		}
		for _, variable := range extractNodeVariables(entityPattern) {
			kind := matchBindingNode
			if _, grouped := groupNodes[variable]; grouped {
				kind = matchBindingNodeList
			}
			if err := bindMatchSemanticKind(scope, variable, kind); err != nil {
				return err
			}
		}
		for _, variable := range extractRelationshipVariables(entityPattern) {
			kind := matchBindingRelationship
			if _, variableLength := variableLengthRelationships[variable]; variableLength {
				kind = matchBindingRelationshipList
			}
			if _, grouped := groupRelationships[variable]; grouped {
				kind = matchBindingRelationshipList
			}
			if err := bindMatchSemanticKind(scope, variable, kind); err != nil {
				return err
			}
		}

	}
	return e.validateMatchWhereSimpleOperands(scope, whereClause)
}

func (e *StorageExecutor) validateMatchWhereSimpleOperands(scope matchSemanticScope, whereClause string) error {
	whereClause = strings.TrimSpace(maskSubqueryBodies(whereClause))
	if whereClause == "" {
		return nil
	}
	switch whereClause[0] {
	case '=', '<', '>', '~':
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			localization.CypherCoreInvalidInputExpectedExpression(string(whereClause[0])))
	case '!':
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			localization.CypherCoreInvalidInputExpectedExpression("!"))
	}
	// A clause keyword read as a variable followed by another term with no
	// operator between them is Neo4j's Invalid input error (WHERE RETURN n:
	// return is the variable, n is invalid â€” the #740 reading).
	if err := projectionItemTermError(whereClause); err != nil {
		return err
	}
	if containsAggregateFunc(whereClause) {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidAggregation",
			"aggregate expressions are not allowed in WHERE",
		)
	}
	for _, operator := range []string{" OR ", " XOR ", " AND "} {
		if left, right, found := splitByOperatorOutsideCase(whereClause, operator, true, true); found {
			if err := e.validateMatchWhereSimpleOperands(scope, left); err != nil {
				return err
			}
			return e.validateMatchWhereSimpleOperands(scope, right)
		}
	}
	if err := e.validateWherePatternExpressionScope(scope, whereClause); err != nil {
		return err
	}
	if operands, _, comparison := splitComparisonChain(whereClause); comparison {
		for _, operand := range operands {
			operand = strings.TrimSpace(operand)
			// A clause keyword read as a variable followed by another term with
			// no operator between them is Neo4j's Invalid input error
			// (WHERE n.x = RETURN n: return is the variable, n is invalid).
			if err := projectionItemTermError(operand); err != nil {
				return err
			}
			if variable, _, propertyAccess := parseVarPropertyRef(operand); propertyAccess {
				switch scope[normalizeProjectionColumnName(variable)] {
				case matchBindingPath, matchBindingRelationshipList, matchBindingNodeList:
					return newSemanticError(
						"Neo.ClientError.Statement.SyntaxError",
						"InvalidArgumentType",
						fmt.Sprintf("property access is not supported on %s", variable),
					)
				}
			}
			if _, literal := parseLiteralValueFromComputedRow(operand); literal {
				continue
			}
			identifier := simpleSemanticIdentifier(operand)
			if identifier == "" {
				continue
			}
			_, inScope := scope[identifier]
			_, externallyBound := e.fabricRecordBindings[identifier]
			if !inScope && !externallyBound {
				return createUndefinedVariableError(identifier)
			}
		}
	}
	for _, operator := range []string{" STARTS WITH ", " ENDS WITH ", " CONTAINS ", " NOT IN ", " IN ", "=~"} {
		left, right, found := splitByOperatorOutsideCase(whereClause, operator, true, true)
		if !found {
			continue
		}
		left = strings.TrimSpace(left)
		// A clause keyword read as a variable on the operator's right followed
		// by another term is Invalid input (WHERE n.x IN RETURN n).
		if err := projectionItemTermError(strings.TrimSpace(right)); err != nil {
			return err
		}
		if simpleSemanticIdentifier(left) == left {
			if _, exists := scope[left]; !exists {
				return createUndefinedVariableError(left)
			}
		}
	}
	return nil
}

func (e *StorageExecutor) validateWherePatternExpressionScope(scope matchSemanticScope, expression string) error {
	expression = strings.TrimSpace(expression)
	if inner, enclosed := stripEnclosingExpressionParentheses(expression); enclosed {
		// (true), (false) and (null) are parenthesised literals, not node
		// patterns (#878 writes an element's own predicate in parentheses).
		if variable := simpleSemanticIdentifier(inner); variable != "" && !isLiteralKeyword(variable) {
			if _, inScope := scope[variable]; !inScope {
				if _, externallyBound := e.fabricRecordBindings[variable]; !externallyBound {
					return createUndefinedVariableError(variable)
				}
			}
			return newSemanticError(
				"Neo.ClientError.Statement.SyntaxError",
				"InvalidArgumentType",
				"a node pattern is not a boolean predicate",
			)
		}
	}
	// A pattern comprehension binds its own variables (#1109); only a
	// pattern expression may not.
	expression = maskPatternComprehensions(expression)
	if !containsRelationshipPattern(expression) {
		return nil
	}
	for _, variable := range append(extractNodeVariables(expression), extractRelationshipVariables(expression)...) {
		if _, inScope := scope[variable]; inScope {
			continue
		}
		if _, externallyBound := e.fabricRecordBindings[variable]; externallyBound {
			continue
		}
		return createUndefinedVariableError(variable)
	}
	return nil
}

// maskPatternComprehensions blanks, keeping byte offsets, the inside of every
// pattern comprehension in expression ([(a)-->(b) WHERE â€¦ | b.x]), whose
// pattern binds variables of its own. Quoted text and relationship brackets
// (-[r]->) are not comprehensions.
func maskPatternComprehensions(expression string) string {
	if strings.IndexByte(expression, '[') < 0 {
		return expression
	}
	var masked []byte
	for index := 0; index < len(expression); index++ {
		switch character := expression[index]; cypherLexicalByte(character) {
		case cypherQuoteClass:
			index = skipCypherQuotedText(expression, index, character) - 1
			continue
		case '[':
		default:
			continue
		}
		if index > 0 && expression[index-1] == '-' {
			continue
		}
		close := findMatchingBracket(expression, index)
		if close < 0 {
			return expression
		}
		if _, _, comprehension := splitPatternComprehension(expression[index : close+1]); comprehension {
			if masked == nil {
				masked = []byte(expression)
			}
			for position := index + 1; position < close; position++ {
				masked[position] = ' '
			}
			index = close
		}
	}
	if masked == nil {
		return expression
	}
	return string(masked)
}

// maskSubqueryBodies replaces each classified subquery operand with a literal
// of its result kind, preserving byte offsets. Leaving EXISTS/COUNT/COLLECT
// before an erased body makes later readers mistake it for a pattern variable
// or keyword-named map projection. Classify the original body before masking;
// quoted text and actual map projections keep their meaning.
func maskSubqueryBodies(expression string) string {
	subqueries := findSubqueryExpressions(expression)
	if len(subqueries) == 0 {
		return expression
	}
	masked := []byte(expression)
	for _, subquery := range subqueries {
		for position := subquery.start; position < subquery.end; position++ {
			masked[position] = ' '
		}
		literal := "true"
		switch subquery.kind {
		case "COUNT":
			literal = "0"
		case "COLLECT":
			literal = "[]"
		}
		copy(masked[subquery.start:], literal)
	}
	return string(masked)
}

// validateSubqueryPatternBindings checks every EXISTS / COUNT / COLLECT
// subquery in text as a query of its own, walked by the one clause walk
// (semanticScopeWalk) from scope, the variables the subquery sees at its
// position (a local of an enclosing expression typed as that local;
// withLocalTypes). The walk binds the body's MATCH and WITH variables and
// checks its nested subqueries from them in turn: a pattern can't use an
// outer variable as another kind (COUNT { (n)-[s]->() } with s a string is
// Neo4j's "s defined with conflicting type", #1055). A local the body's own
// clauses declare (a comprehension's, a quantifier's, reduce's, a named
// path; not a nested subquery's or CALL's) may not redeclare a variable it
// sees: Neo4j's "is shadowing a variable with the same name from the outer
// scope". At the top level and in CALL { } such a local shadows instead.
func (e *StorageExecutor) validateSubqueryPatternBindings(ctx context.Context, scope staticTypeScope, source string) error {
	if scope.admitted != nil {
		return nil
	}
	if !mayContainSubqueryExpression(source) && !containsRelationshipPattern(source) {
		return nil
	}
	_, _, err := e.enrichBoundTypes(ctx, typeExpressionSource(source), typeScopeOf(scope), scope.bindings, "", scope.cypher25)
	return err
}
func validateExpressionPatternBindings(ctx context.Context, scope staticTypeScope, text string) error {
	if !containsRelationshipPattern(text) {
		return nil
	}
	start := 0
	// MATCH's own pattern was already checked and bound; its predicate
	// contains the expression patterns checked here.
	if startsWithKeywordFold(text, "MATCH") || startsWithKeywordFold(text, "OPTIONAL MATCH") {
		start = topLevelKeywordIndex(text, "WHERE")
		if start < 0 {
			return nil
		}
	}
	structure := maskNestedScopeBodies(text)
	local := func(at int) staticTypeScope {
		return withPatternComprehensionBindings(ctx, withLocalTypes(ctx, scope, text, at), text, at)
	}
	for index := start; index < len(structure); index++ {
		if isCypherQuoteByte(structure[index]) {
			index = skipCypherQuotedText(structure, index, structure[index]) - 1
			continue
		}
		if structure[index] == '[' {
			close := findMatchingBracket(structure, index)
			if close < 0 {
				break
			}
			if pattern, _, comprehension := splitPatternComprehension(structure[index : close+1]); comprehension {
				// The head is checked before its new locals are introduced;
				// enclosing comprehensions still supply their own local types.
				if err := validateBoundPatternKinds(local(index-1).kinds, pattern); err != nil {
					return err
				}
			}
		}
		if structure[index] != '(' {
			continue
		}
		end, chain := relationshipChainEnd(structure, index, len(structure))
		if !chain {
			continue
		}
		if err := validateBoundPatternKinds(local(index).kinds, structure[index:end]); err != nil {
			return err
		}
		index = end - 1
	}
	return nil
}

func validateBoundPatternKinds(scope matchSemanticScope, pattern string) error {
	pattern = matchPatternStructure(pattern)
	kinds := maps.Clone(scope)
	if kinds == nil {
		kinds = make(matchSemanticScope)
	}
	for _, variable := range extractNodeVariables(pattern) {
		variable = normalizeProjectionColumnName(variable)
		if err := bindMatchSemanticKind(kinds, variable, matchBindingNode); err != nil {
			return err
		}
	}
	lists := variableLengthRelationshipVariableSet(pattern)
	for _, variable := range extractRelationshipVariables(pattern) {
		variable = normalizeProjectionColumnName(variable)
		kind := matchBindingRelationship
		if _, list := lists[variable]; list {
			kind = matchBindingRelationshipList
		}
		if err := bindMatchSemanticKind(kinds, variable, kind); err != nil {
			return err
		}
	}
	return nil
}

// maskNestedScopeBodies blanks the bodies of the EXISTS / COUNT / COLLECT
// and CALL subqueries in text, which start scopes of their own.
func maskNestedScopeBodies(text string) string {
	masked := []byte(maskSubqueryBodies(text))
	for index := 0; index < len(text); index++ {
		switch c := text[index]; cypherLexicalByte(c) {
		case cypherQuoteClass:
			index = skipCypherQuotedText(text, index, c) - 1
			continue
		}
		if !matchKeywordAt(text, index, "CALL") {
			continue
		}
		open := skipSpaces(text, index+len("CALL"))
		if open < len(text) && text[open] == '(' {
			if close := findMatchingParen(text, open); close >= 0 {
				open = skipSpaces(text, close+1)
			}
		}
		if open >= len(text) || text[open] != '{' {
			continue
		}
		close := findMatchingDelimiter(text, open, '{', '}')
		if close < 0 {
			break
		}
		for position := open + 1; position < close; position++ {
			masked[position] = ' '
		}
		index = close
	}
	return string(masked)
}

func bindMatchSemanticKind(scope matchSemanticScope, variable string, kind matchBindingKind) error {
	variable = normalizeProjectionColumnName(strings.TrimSpace(variable))
	if variable == "" {
		return nil
	}
	if existing, found := scope[variable]; found && existing != matchBindingUnknown && existing != kind {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"VariableTypeConflict",
			fmt.Sprintf("variable %s is already bound to a different entity type", variable),
		)
	}
	scope[variable] = kind
	return nil
}

// schemaCommandKeywords follow CREATE or DROP in a schema command.
var schemaCommandKeywords = []string{"CONSTRAINT", "INDEX", "FULLTEXT", "VECTOR", "RANGE", "TEXT", "POINT", "LOOKUP", "BTREE", "OR REPLACE"}

// isSchemaCommandStatement reports whether cypher is a schema command
// (CREATE / DROP CONSTRAINT, INDEX, â€¦): its patterns and expressions declare a
// schema rule over a pattern (FOR ()-[r:T]-() REQUIRE â€¦) and bind no clause
// variables.
func isSchemaCommandStatement(cypher string) bool {
	trimmed := strings.TrimSpace(cypher)
	for _, command := range []string{"CREATE", "DROP"} {
		if !startsWithKeywordFold(trimmed, command) {
			continue
		}
		rest := strings.TrimSpace(trimmed[len(command):])
		for _, keyword := range schemaCommandKeywords {
			if startsWithKeywordFold(rest, keyword) {
				return true
			}
		}
	}
	return false
}

// validateStaticClauseTypes applies the compile-time type checks of one
// clause: function arguments (validateStaticFunctionVariables) and operators
// (validateStaticOperatorTypes).
func (e *StorageExecutor) validateStaticClauseTypes(ctx context.Context, clause pipelineClause, scope staticTypeScope) error {
	if scope.admitted != nil {
		return scope.admitted.checkClauseOperandHandles(ctx, clause, scope)
	}
	if err := validateStaticPropertySubscripts(ctx, clause.text, scope); err != nil {
		return err
	}
	if err := staticWriteTokenError(ctx, clause, scope); err != nil {
		return err
	}
	if len(scope.values) > 0 {
		if err := staticListOperandTypeError(clause.text, scope); err != nil {
			return err
		}
	}
	var projectedScope func() staticTypeScope
	if clause.kind == pipelineClauseReturn {
		projection, rest := splitWithProjection(clause.text)
		var projected *staticTypeScope
		projectedScope = func() staticTypeScope {
			if projected == nil {
				built := projectionAliasScope(ctx, scope, clause.text)
				projected = &built
			}
			return *projected
		}
		if err := validateStaticFunctionVariables(ctx, projection, scope); err != nil {
			return err
		}
		if err := forEachProjectedTailExpression(ctx, projection, rest, func(expression string) error {
			return validateStaticFunctionVariablesIn(ctx, expression, projectedScope)
		}); err != nil {
			return err
		}
	} else if err := validateStaticFunctionVariables(ctx, clause.text, scope); err != nil {
		return err
	}
	return e.validateStaticOperatorTypes(ctx, clause, scope, projectedScope, nil)
}

// validateQuantifiedGroupPredicates checks each quantified group's
// predicates (its own WHERE and its elements' inline WHERE) in a MATCH
// clause where the group's variables are one node or relationship each (an
// iteration's), not the lists the group binds after it: in
// (()-[r WHERE m[r.id] IS NULL]->())+ r.id is a relationship's property and
// type(r) takes a relationship. Every expression check a clause's
// expressions get runs on them with that scope: subquery patterns,
// subscripts, dynamic labels and types, list operands, function arguments
// and operators. It returns
// the clause with those predicates blanked, for the checks of the rest of
// the clause.
func (e *StorageExecutor) validateQuantifiedGroupPredicates(ctx context.Context, clause string, scope staticTypeScope) (string, error) {
	groups := quantifiedGroups(clause)
	if len(groups) == 0 {
		return clause, nil
	}
	for _, group := range groups {
		predicates := group.predicateTexts(clause)
		if len(predicates) == 0 {
			continue
		}
		kinds := make(matchSemanticScope, len(scope.kinds)+len(group.nodes)+len(group.relationships))
		for name, kind := range scope.kinds {
			kinds[name] = kind
		}
		for _, variable := range group.nodes {
			kinds[variable] = matchBindingNode
		}
		for _, variable := range group.relationships {
			kinds[variable] = matchBindingRelationship
		}
		iteration := scope
		iteration.kinds = kinds
		for _, predicate := range predicates {
			if err := e.validateSubqueryPatternBindings(ctx, iteration, predicate); err != nil {
				return "", err
			}
			if err := validateStaticPropertySubscripts(ctx, predicate, iteration); err != nil {
				return "", err
			}
			// A dynamic label or type of the group, in its pattern
			// ((x:$(l))) or a predicate (x:$(l)), is a predicate call
			// here (labelExpression.predicate).
			if err := staticPatternTokenError(ctx, pipelineClause{kind: pipelineClauseMatch, text: predicate}, iteration); err != nil {
				return "", err
			}
			if err := staticListOperandTypeError(predicate, iteration); err != nil {
				return "", err
			}
			if err := validateStaticFunctionVariables(ctx, predicate, iteration); err != nil {
				return "", err
			}
			// Neo4j types the operators of a group predicate but doesn't
			// require a boolean result (WHERE r.kind + 1 matches nothing).
			if _, err := (&staticOperatorChecker{scope: iteration}).check(ctx, predicate); err != nil {
				return "", err
			}
		}
	}
	return maskQuantifiedGroupPredicates(clause), nil
}

// projectionAliasScope is the scope of the WHERE / ORDER BY after a RETURN or
// WITH projection: the incoming variables, with each projection alias
// replacing the variable of the same name (RETURN n.num AS n ORDER BY n + 2
// sees n as a number, not the node).
func projectionAliasScope(ctx context.Context, input staticTypeScope, clause string) staticTypeScope {
	if input.projected != nil {
		return *input.projected
	}

	values, _, err := (&StorageExecutor{}).enrichBoundTypes(ctx, clause, typeScopeOf(input), input.bindings, "", input.cypher25)
	if err != nil || values == nil {
		input.typeFailure = err
		return input
	}
	branch := values.program.root.branches[0]
	last := values.program.clauses[branch.shape.clauses[len(branch.shape.clauses)-1].syntax.ID()]
	names, ids := last.combinedBindings()
	return values.view(boundBindingScope(projectedMapNames(names), ids), input.bindings)
}

// projectionItemTermError is Neo4j's SyntaxError for a projection item that
// is a clause-keyword name followed by another term with no operator between
// them (WITH RETURN n: return is a variable, as Neo4j reads it (#740), and n
// is "Invalid input"). Before, the keyword was taken for a clause.
func projectionItemTermError(expression string) error {
	expression = strings.TrimSpace(expression)
	name, next, ok := scanIdentifierToken(expression, 0)
	if !ok || !isNameableClauseKeyword(name) {
		return nil
	}
	rest := strings.TrimSpace(expression[next:])
	if rest == "" || rest == expression[next:] {
		return nil // the name alone, or followed directly by an operator
	}
	if c := rest[0]; isIdentByte(c) || isCypherQuoteByte(c) || c == '$' {
		token, _, _ := scanIdentifierToken(rest, 0)
		if token == "" {
			token = rest[:1]
		}
		if !isExpressionContinuationWord(token) {
			return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
				localization.CypherCoreInvalidInputExpectedExpression(token))
		}
	}
	return nil
}

// projectionAliasError is Neo4j's SyntaxError for a projection item whose
// alias, as written, is not one name (WITH n AS return n: the n after the
// alias is "Invalid input"). A backtick-quoted alias is one name.
func projectionAliasError(ctx context.Context, item string) error {
	// The alias follows the item's own AS (projectionAliasIndex), so an alias
	// named as is a name (WITH n AS as, #894).
	as := projectionAliasIndex(ctx, item)
	if as < 0 {
		return nil
	}
	alias := strings.TrimSpace(item[as+len("AS"):])
	if alias == "" {
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			localization.CypherCoreInvalidInput(""))
	}
	_, next, ok := scanSymbolicName(alias, 0)
	if !ok || next == len(alias) {
		return nil
	}
	rest := strings.TrimSpace(alias[next:])
	token, _, _ := scanIdentifierToken(rest, 0)
	if token == "" {
		token = rest[:1]
	}
	return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
		localization.CypherCoreInvalidInputExpectedExpression(token))
}

// isExpressionContinuationWord reports whether word, after an operand,
// continues the expression (an operator word: AND, IS NULL, STARTS WITH, â€¦).
func isExpressionContinuationWord(word string) bool {
	for _, operator := range [...]string{"AND", "OR", "XOR", "IS", "IN", "STARTS", "ENDS", "CONTAINS", "NOT"} {
		if strings.EqualFold(word, operator) {
			return true
		}
	}
	return false
}

// splitWithProjection splits a WITH clause into its projection and the WHERE /
// ORDER BY / SKIP / LIMIT that follow it.
func splitWithProjection(clause string) (projection, rest string) {
	end := len(clause)
	for _, keyword := range []string{"WHERE", "ORDER BY", "SKIP", "LIMIT"} {
		if index := topLevelKeywordIndex(clause, keyword); index >= 0 && index < end {
			end = index
		}
	}
	return clause[:end], clause[end:]
}

// unwindSourceExpression is the list expression of an UNWIND clause.
func unwindSourceExpression(clause string) string {
	expression, _, _ := parsePipelineIteration(clause)
	return expression
}

func coalesceSemanticKind(expression string, scope matchSemanticScope) (matchBindingKind, bool) {
	name, inner, ok := parseFunctionCallWS(expression)
	if !ok || !strings.EqualFold(name, "coalesce") {
		return matchBindingUnknown, false
	}
	kind := matchBindingUnknown
	for _, argument := range splitTopLevelComma(inner) {
		variable := simpleSemanticIdentifier(argument)
		argumentKind, found := scope[variable]
		if variable == "" || !found || argumentKind == matchBindingUnknown {
			return matchBindingUnknown, false
		}
		if kind != matchBindingUnknown && kind != argumentKind {
			return matchBindingUnknown, false
		}
		kind = argumentKind
	}
	return kind, kind != matchBindingUnknown
}

func variableLengthRelationshipVariableSet(pattern string) map[string]struct{} {
	result := make(map[string]struct{})
	for open, end := nextRelationshipBracket(pattern, 0); open >= 0; open, end = nextRelationshipBracket(pattern, end+1) {
		declaration := relationshipDeclarationHead(pattern[open+1 : end])
		if !declaration.hasLength {
			continue
		}
		if name, _, ok := scanIdentifierToken(declaration.variable, 0); ok {
			result[name] = struct{}{}
		}
	}
	return result
}

// entityListLiteralKind is the kind of a list literal of node variables
// ([a, b] is a List<Node>) or of relationship variables; ok is false for any
// other expression.
func entityListLiteralKind(expression string, scope matchSemanticScope) (matchBindingKind, bool) {
	expression = strings.TrimSpace(expression)
	if !isListLiteral(expression) {
		return matchBindingUnknown, false
	}
	items := splitTopLevelComma(expression[1 : len(expression)-1])
	if len(items) == 0 {
		return matchBindingUnknown, false
	}
	element := matchBindingUnknown
	for _, item := range items {
		name := simpleSemanticIdentifier(item)
		kind := scope[name]
		if name == "" || (kind != matchBindingNode && kind != matchBindingRelationship) || (element != matchBindingUnknown && kind != element) {
			return matchBindingUnknown, false
		}
		element = kind
	}
	if element == matchBindingNode {
		return matchBindingNodeList, true
	}
	return matchBindingRelationshipList, true
}

// invalidRelationshipPattern reports a relationship bracket that is not closed
// or whose range is malformed. Only relationship brackets are read: a '[' in
// a property map ($ids[i * 20 + 1], $ws[0..2]) is a subscript or a slice.
func invalidRelationshipPattern(pattern string) bool {
	for open, end := scanRelationshipBracket(pattern, 0); open >= 0; open, end = scanRelationshipBracket(pattern, end+1) {
		if end < 0 {
			return true
		}
		// Quoted names and values can hold * and .. (#879), and so can
		// property values and dynamic types: the declaration reader skips
		// them.
		if relationshipDeclarationHead(pattern[open+1 : end]).lengthInvalid {
			return true
		}
	}
	return false
}

// simpleSemanticIdentifier returns the variable an expression consists of,
// plain or backtick-quoted (`x y`), unquoted; "" for any other expression.
func simpleSemanticIdentifier(expression string) string {
	expression = lexicalExpressionText(expression)
	// A backtick-quoted variable (`my x`, `$p`) is a variable whatever its
	// characters: it isn't a parameter, and scope checks must see it.
	if isBacktickQuotedName(expression) {
		return normalizeProjectionColumnName(expression)
	}
	name, next, ok := scanSymbolicName(expression, 0)
	if !ok || strings.TrimSpace(expression[next:]) != "" {
		return ""
	}
	return normalizeProjectionColumnName(name)
}

func addMatchPatternBindingKinds(ctx context.Context, scope matchSemanticScope, clause string) {
	forEachMatchPatternBinding(ctx, clause, func(variable string, kind matchBindingKind) {
		if _, found := scope[variable]; !found {
			scope[variable] = kind
		}
	})
}

// forEachMatchPatternBinding is the declaration reader for semantic scope and
// runtime schemas. Property expressions and predicate-only names never declare
// nodes; callers must not recover declarations from expression parentheses.
func forEachMatchPatternBinding(ctx context.Context, clause string, visit func(string, matchBindingKind)) {
	node, ok := canonicalQueryClause(ctx, clause)
	if !ok {
		clause = clause[:patternPartEnd(pipelineClause{text: clause})]
		syntax, err := cypherantlr.ParseSyntax(ctx, clause, cypherantlr.PatternEntry, cypherVersionFromContext(ctx) == "25")
		if err != nil {
			return
		}
		node = syntax.Root()
	}
	syntaxPatternDefinitions(node, func(rule int, symbol cypherantlr.SyntaxNode) {
		kind := matchBindingNode
		switch rule {
		case cypherantlr.CypherParserRULE_relationDetail:
			kind = matchBindingRelationship
		case cypherantlr.CypherParserRULE_patternPart:
			kind = matchBindingPath
		}
		visit(syntaxSymbolName(symbol), kind)
	})
}

// deleteTargetTypeError rejects a DELETE target whose type, known before the
// statement runs, is a property of a node or relationship (n.p, a stored
// value): Neo4j 5.26's "Type mismatch: expected Node, Path or Relationship"
// (#907). DELETE removes entities, and a property is removed with REMOVE;
// NornicDB used to accept the statement and delete nothing. A map's key (m.k)
// has no static type. null is a valid target that deletes nothing.
//
// A list of nodes or relationships (the variable of a variable-length
// relationship, MATCH ()-[x*]->() DELETE x) is a NornicDB extension: Neo4j
// 5.26 rejects it, NornicDB deletes each entity in it, as before (at the
// project owner's direction).
func deleteTargetTypeError(clause string, scope matchSemanticScope) error {
	targets, _, _ := deleteClauseTargets(clause)
	for _, expression := range targets {
		expression = strings.TrimSpace(expression)
		if variable, _, property := parseVarPropertyRef(expression); property && isEntityPropertyAccess(expression, variable) {
			switch scope[normalizeProjectionColumnName(variable)] {
			case matchBindingNode, matchBindingRelationship:
				return typeNameMismatchError("Node, Path or Relationship", "a property value")
			}
		}
	}
	return nil
}

// isEntityPropertyAccess reports whether expression, which parseVarPropertyRef
// read as variable.key, is exactly that, with nothing after the key (no
// subscript or further access).
func isEntityPropertyAccess(expression, variable string) bool {
	rest := strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(expression), variable))
	key := strings.TrimSpace(strings.TrimPrefix(rest, "."))
	return isValidIdentifier(key) || isBacktickQuotedName(key)
}

// callSubqueryReturnsOuterUnchanged reports whether every branch of a CALL
// subquery returns the enclosing query's variable name as itself (RETURN
// name, or name AS name) without declaring name again in its body. Neo4j
// rejects even that as VariableAlreadyBound; NornicDB accepts it as an
// extension, since the column is the outer value and nothing is ambiguous
// (#907; the implicit import is the same kind of extension). A branch that
// rebinds name (WITH â€¦ AS name, UNWIND â€¦ AS name, YIELD name, a nested CALL
// returning it) or returns another value under it is rejected.
func callSubqueryReturnsOuterUnchanged(ctx context.Context, branches []string, name string) bool {
	source := "CALL (" + projectionVariableText(name) + ") { " + strings.Join(branches, " UNION ALL ") + " }"
	facts := (&StorageExecutor{}).statementProjectionProgram(ctx, source, resultmetadata.KnownScope([]string{name}), false, nil)
	if facts.err != nil || facts.statement == nil || len(facts.statement.Clauses) != 1 {
		return false
	}
	original, known := facts.statement.Incoming.Binding(name)
	call := facts.statement.Clauses[0].Call
	if !known || call == nil {
		return false
	}
	output, exists := call.After.Binding(name)
	return exists && original == output
}
func withPatternComprehensionBindings(ctx context.Context, scope staticTypeScope, source string, at int) staticTypeScope {
	if scope.admitted != nil {
		return scope
	}
	return boundExpressionTypeView(ctx, scope, source, at)
}
func (e *StorageExecutor) validateClauseSubqueries(ctx context.Context, clause pipelineClause, _ typeScope, scope staticTypeScope, _ typeScope, cypher25 bool) error {
	if scope.admitted != nil {
		return nil
	}
	_, _, err := e.enrichBoundTypes(ctx, clause.text, typeScopeOf(scope), scope.bindings, "", cypher25)
	return err
}

// MERGE clause implementation for NornicDB.
// This file contains MERGE execution, compound queries, and context-aware operations.

package cypher

import (
	"context"
	"errors"
	"sort"

	"strings"

	"github.com/orneryd/nornicdb/pkg/storage"
)

func mergeNodeHasLabels(node *storage.Node, labels []string) bool {
	for _, label := range labels {
		found := false
		for _, nodeLabel := range node.Labels {
			if nodeLabel == label {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	return true
}

func mergeNodeMatches(node *storage.Node, labels []string, props map[string]interface{}) bool {
	if node == nil {
		return false
	}
	if len(labels) > 0 && !mergeNodeHasLabels(node, labels) {
		return false
	}
	return nodePropertiesMatch(node, props)
}

func mergeCreateConflict(err error) bool {
	if errors.Is(err, storage.ErrAlreadyExists) {
		return true
	}
	return strings.Contains(lowerASCII(err.Error()), "already exists")
}

func mergeLookupCacheKey(labels []string, prop string, val interface{}) string {
	return unwindMergeKey(unwindMergeLabelsKey(labels), map[string]interface{}{prop: val})
}

func cloneNodePropertiesMap(in map[string]interface{}) map[string]interface{} {
	out := make(map[string]interface{}, len(in))
	for k, v := range in {
		out[k] = v
	}
	return out
}

func (e *StorageExecutor) evictMergeNodeCacheEntries(labels []string, props map[string]interface{}, nodeID storage.NodeID) {
	if len(labels) == 0 || len(props) == 0 {
		return
	}
	e.ensureNodeLookupCache()

	cacheMu := e.nodeLookupCacheLock()
	cacheMu.Lock()
	defer cacheMu.Unlock()
	for prop, val := range props {
		key := mergeLookupCacheKey(labels, prop, val)
		cached, ok := e.nodeLookupCache[key]
		if !ok || cached == nil {
			continue
		}
		if nodeID == "" || cached.ID == nodeID {
			delete(e.nodeLookupCache, key)
		}
	}
}

func (e *StorageExecutor) findMergeNodeInCache(store storage.Engine, labels []string, props map[string]interface{}) *storage.Node {
	if len(labels) == 0 || len(props) == 0 {
		return nil
	}
	e.ensureNodeLookupCache()

	var cachedNode *storage.Node
	cacheMu := e.nodeLookupCacheLock()
	cacheMu.RLock()
	for prop, val := range props {
		if cached, ok := e.nodeLookupCache[mergeLookupCacheKey(labels, prop, val)]; ok {
			if mergeNodeMatches(cached, labels, props) {
				cachedNode = cached
				break
			}
		}
	}
	cacheMu.RUnlock()

	if cachedNode == nil {
		return nil
	}
	if store == nil {
		return cachedNode
	}

	liveNode, err := e.getQueryNode(store, cachedNode.ID)
	if err == nil && mergeNodeMatches(liveNode, labels, props) {
		return liveNode
	}

	e.evictMergeNodeCacheEntries(labels, props, cachedNode.ID)
	return nil
}

func (e *StorageExecutor) cacheMergeNode(labels []string, props map[string]interface{}, node *storage.Node) {
	if node == nil || len(labels) == 0 || len(props) == 0 {
		return
	}
	cacheMu := e.nodeLookupCacheLock()
	cacheMu.Lock()
	defer cacheMu.Unlock()
	for prop, val := range props {
		e.nodeLookupCache[mergeLookupCacheKey(labels, prop, val)] = node
	}
}

// prepareMergeKeys readies a transaction for a MERGE lookup of a node with
// labels and props, so concurrent MERGEs of a uniquely constrained key behave
// as in Neo4j: one creates the node and the others wait for it and match it
// (#961). It uses the storage.MergeNodePreparer capability of the statement's
// storage, so every transactional view admits keys the same way. A MERGE whose
// statement writes the node it matches (write) also waits for a concurrent
// writer of the node, then writes on top of its commit
// (PrepareMergeNodeForWrite, NOR-117). Storage without a transaction admits
// nothing.
func prepareMergeKeys(ctx context.Context, store storage.Engine, labels []string, props map[string]interface{}, write bool) error {
	preparer, ok := store.(storage.MergeNodePreparer)
	if !ok || len(labels) == 0 || len(props) == 0 {
		return nil
	}
	if write {
		return preparer.PrepareMergeNodeForWrite(ctx, labels, props)
	}
	return preparer.PrepareMergeNode(ctx, labels, props)
}

func (e *StorageExecutor) loadMergeCandidateNodes(store storage.Engine, ids []storage.NodeID) []*storage.Node {
	if len(ids) == 0 {
		return nil
	}
	out := make([]*storage.Node, 0, len(ids))
	seen := make(map[storage.NodeID]struct{}, len(ids))
	for _, id := range ids {
		if _, exists := seen[id]; exists {
			continue
		}
		seen[id] = struct{}{}
		n, err := e.getQueryNode(store, id)
		if err != nil || n == nil {
			continue
		}
		out = append(out, n)
	}
	return out
}

func mergePropertyNamesSorted(props map[string]interface{}) []string {
	names := make([]string, 0, len(props))
	for prop := range props {
		names = append(names, prop)
	}
	sort.Strings(names)
	return names
}

func mergeIndexMatchesAllProperties(idx *storage.CompositeIndex, props map[string]interface{}) bool {
	if idx == nil || len(idx.Properties) != len(props) {
		return false
	}
	for _, prop := range idx.Properties {
		if _, ok := props[prop]; !ok {
			return false
		}
	}
	return true
}

func compositeLookupValues(idx *storage.CompositeIndex, props map[string]interface{}) []interface{} {
	values := make([]interface{}, 0, len(idx.Properties))
	for _, prop := range idx.Properties {
		values = append(values, props[prop])
	}
	return values
}

func (e *StorageExecutor) findMergeNode(store storage.Engine, labels []string, props map[string]interface{}) (*storage.Node, error) {
	if len(props) == 0 {
		var candidates []*storage.Node
		var err error
		if len(labels) > 0 {
			candidates, err = store.GetNodesByLabel(labels[0])
		} else {
			candidates, err = store.AllNodes()
		}
		if err != nil {
			return nil, err
		}
		for _, node := range candidates {
			if mergeNodeMatches(node, labels, props) {
				return node, nil
			}
		}
		return nil, nil
	}
	if len(labels) == 0 {
		candidates, err := store.AllNodes()
		if err != nil {
			return nil, err
		}
		for _, node := range candidates {
			if mergeNodeMatches(node, labels, props) {
				return node, nil
			}
		}
		return nil, nil
	}

	if cached := e.findMergeNodeInCache(store, labels, props); cached != nil {
		e.markMergeSchemaLookupUsed()
		return cached, nil
	}

	// Schema hot path: prefer exact composite lookups for full-key MERGE patterns,
	// then fall back to the smallest single-property candidate set.
	schema := store.GetSchema()
	schemaLookupUsed := false
	if schema != nil {
		label := labels[0]

		for _, idx := range schema.SeekableCompositeIndexesForLabel(label) {
			if !mergeIndexMatchesAllProperties(idx, props) {
				continue
			}
			schemaLookupUsed = true
			e.markMergeSchemaLookupUsed()
			candidateNodes := e.loadMergeCandidateNodes(store, compositeIndexLookup(store, idx, compositeLookupValues(idx, props), true))
			for _, n := range candidateNodes {
				if mergeNodeMatches(n, labels, props) {
					e.cacheMergeNode(labels, props, n)
					return n, nil
				}
			}
		}

		for _, prop := range mergePropertyNamesSorted(props) {
			val := props[prop]
			nodeID, valueFound, constraintExists, cacheComplete := schema.LookupUniqueConstraintValueForPlanning(label, prop, val)
			if !constraintExists {
				continue
			}
			e.markMergeSchemaLookupUsed()
			if !valueFound {
				if cacheComplete {
					schemaLookupUsed = true
				}
				continue
			}
			for _, n := range e.loadMergeCandidateNodes(store, []storage.NodeID{nodeID}) {
				if mergeNodeMatches(n, labels, props) {
					e.cacheMergeNode(labels, props, n)
					return n, nil
				}
			}
			if cacheComplete {
				schemaLookupUsed = true
			}
		}

		bestIDs := []storage.NodeID(nil)
		bestCount := -1
		for _, prop := range mergePropertyNamesSorted(props) {
			val := props[prop]
			if _, ok := schema.GetPropertyIndex(label, prop); !ok {
				continue
			}
			schemaLookupUsed = true
			e.markMergeSchemaLookupUsed()
			ids := propertyIndexLookup(store, schema, label, prop, val)
			count := len(ids)
			if bestCount == -1 || count < bestCount {
				bestIDs = ids
				bestCount = count
				if count <= 1 {
					break
				}
			}
		}
		for _, n := range e.loadMergeCandidateNodes(store, bestIDs) {
			if mergeNodeMatches(n, labels, props) {
				e.cacheMergeNode(labels, props, n)
				return n, nil
			}
		}
	}
	if schemaLookupUsed {
		return nil, nil
	}
	e.markMergeScanFallbackUsed()

	nodes, err := store.GetNodesByLabel(labels[0])
	if err != nil {
		return nil, err
	}
	for _, node := range nodes {
		if mergeNodeMatches(node, labels, props) {
			e.cacheMergeNode(labels, props, node)
			return node, nil
		}
	}

	// No global AllNodes() fallback (#640, #694): the label index and schema
	// lookups are transactionally maintained and authoritative. Scanning every
	// node in the database for each creating MERGE row made bulk MERGE
	// ingestion quadratic (85 ms per row at 20k nodes) while Neo4j bounds the
	// lookup to the label's own scan. A missed label means no match, exactly
	// as in Neo4j with an out-of-date index.
	return nil, nil
}

// findMergeNodesScanned is findMergeNodes, also reporting whether it read
// the pattern's whole label (or its complete pinned equality population). Only such an
// answer is complete: a node any other lookup (the MERGE cache, a schema
// index) could return carries the label, so a scan that found none means
// there is none. An index answer is not; findMergeNode tries further
// sources after it.
func (e *StorageExecutor) findMergeNodesScanned(store storage.Engine, labels []string, props map[string]interface{}) (matches []*storage.Node, scanned bool, err error) {
	if ids, indexed := e.mergeNodeIndexedCandidateIDs(store, labels, props); indexed {
		matches = make([]*storage.Node, 0, len(ids))
		for _, n := range e.loadMergeCandidateNodes(store, ids) {
			if mergeNodeMatches(n, labels, props) {
				matches = append(matches, n)
			}
		}
		return matches, false, nil
	}
	if lookup, ok := store.(storage.TransactionEqualityLookup); ok && len(labels) > 0 && len(props) > 0 {
		candidates, complete, lookupErr := lookup.LookupNodesByEquality(labels[0], props)
		if lookupErr != nil {
			return nil, false, lookupErr
		}
		if complete {
			e.markMergeScanFallbackUsed()
			for _, candidate := range candidates {
				if mergeNodeMatches(candidate, labels, props) {
					matches = append(matches, candidate)
				}
			}
			return matches, true, nil
		}
	}
	var candidates []*storage.Node
	if len(labels) > 0 && len(props) > 0 {
		e.markMergeScanFallbackUsed()
	}
	if len(labels) > 0 {
		candidates, err = store.GetNodesByLabel(labels[0])
	} else {
		candidates, err = store.AllNodes()
	}
	if err != nil {
		return nil, false, err
	}

	matches = make([]*storage.Node, 0, len(candidates))
	for _, candidate := range candidates {
		if mergeNodeMatches(candidate, labels, props) {
			matches = append(matches, candidate)
		}
	}
	return matches, true, nil
}

// mergeNodeIndexedCandidateIDs returns the candidate node IDs for a MERGE node
// pattern from the schema, and whether the schema answered: a unique
// constraint on one of the pattern's properties (at most one node holds a
// value), a composite index covering every pattern property, or the smallest
// single-property index result. When it answers, every node matching the
// pattern is among the candidates, so findMergeNodes needs no label scan
// (#640, #694). It answers nothing for a pattern without labels or properties.
func (e *StorageExecutor) mergeNodeIndexedCandidateIDs(store storage.Engine, labels []string, props map[string]interface{}) ([]storage.NodeID, bool) {
	if len(labels) == 0 || len(props) == 0 {
		return nil, false
	}
	schema := store.GetSchema()
	if schema == nil {
		return nil, false
	}
	label := labels[0]
	for _, prop := range mergePropertyNamesSorted(props) {
		nodeID, valueFound, constraintExists, cacheComplete := schema.LookupUniqueConstraintValueForPlanning(label, prop, props[prop])
		if !constraintExists {
			continue
		}
		if valueFound {
			e.markMergeSchemaLookupUsed()
			return []storage.NodeID{nodeID}, true
		}
		if cacheComplete {
			e.markMergeSchemaLookupUsed()
			return nil, true
		}
	}
	for _, idx := range schema.SeekableCompositeIndexesForLabel(label) {
		if mergeIndexMatchesAllProperties(idx, props) {
			e.markMergeSchemaLookupUsed()
			return compositeIndexLookup(store, idx, compositeLookupValues(idx, props), true), true
		}
	}
	var best []storage.NodeID
	found := false
	for _, prop := range mergePropertyNamesSorted(props) {
		if _, ok := schema.GetPropertyIndex(label, prop); !ok {
			continue
		}
		ids := propertyIndexLookup(store, schema, label, prop, props[prop])
		if !found || len(ids) < len(best) {
			best, found = ids, true
		}
	}
	if found {
		e.markMergeSchemaLookupUsed()
	}
	return best, found
}

// parseMergePattern parses a MERGE pattern like "(n:Label {prop: value})"

// MERGE clause implementation for NornicDB.
// This file contains MERGE execution, compound queries, and context-aware operations.

package cypher

import (
	"context"

	"strings"

	cypherfn "github.com/orneryd/nornicdb/pkg/cypher/fn"
	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// lookupPatternCandidatesUsingPropertyIndex returns a narrowed node candidate
// set when the pattern carries inline equality on one or more indexed
// properties. It is the pattern-inline counterpart of
// `lookupWhereCandidatesUsingPropertyIndex`: same correctness contract, same
// safety story, but the source of the equality is the parsed `nodeInfo`
// rather than a WHERE-clause string.
//
// Returned `(nodes, true)` means: "use these as the candidate set; you still
// need to apply the full `nodeMatchesProps` filter to enforce residual
// non-indexed predicates". Returned `(nil, false)` means: "no usable index;
// fall back to the existing label-scan / AllNodes path".
//
// The function is shape-agnostic: it works for labelled and labelless
// patterns, single-property and N-property patterns, and any property type
// the index can key (string / int / float / bool — same set
// `indexValueKey` accepts on insert). It deliberately does NOT
// attempt to short-circuit when the residual filter is empty; the caller's
// uniform `nodeMatchesProps` step keeps the post-condition trivially
// correct even when the index narrows partially.
func (e *StorageExecutor) lookupPatternCandidatesUsingPropertyIndex(nodeInfo nodePatternInfo, store storage.Engine) ([]*storage.Node, bool) {
	if len(nodeInfo.properties) == 0 {
		return nil, false
	}
	schema := store.GetSchema()
	if schema == nil {
		return nil, false
	}

	// Collect per-property candidate ID sets, one per inline equality that an
	// index can serve. Each set narrows the result via intersection.
	var idSets []map[storage.NodeID]struct{}
	usedAnyIndex := false

	// Composite indexes answer a whole equality prefix in one lookup, which
	// is far narrower than intersecting one set per property. Use the longest
	// covered leading prefix: all index properties → LookupFull, otherwise
	// the leading k properties → LookupPrefix. The residual nodeMatchesProps
	// step still enforces every non-indexed predicate.
	if len(nodeInfo.labels) > 0 {
		for _, idx := range schema.SeekableCompositeIndexesForLabel(nodeInfo.labels[0]) {
			if idx == nil || len(idx.Properties) < 2 {
				// Arity-1 indexes are served by the per-property loop below,
				// whose authoritative-miss logic handles values an index can't
				// key (lists, maps) without a false negative.
				continue
			}
			covered := 0
			for covered < len(idx.Properties) {
				if _, ok := nodeInfo.properties[idx.Properties[covered]]; !ok {
					break
				}
				covered++
			}
			if covered == 0 {
				continue
			}
			// Every covered value must be a scalar the index files under an
			// equality-exact key; otherwise a miss is not authoritative and
			// the caller's scan must decide.
			authoritative := true
			for i := 0; i < covered; i++ {
				if !propertyIndexMissIsAuthoritative(nodeInfo.properties[idx.Properties[i]]) {
					authoritative = false
					break
				}
			}
			if !authoritative {
				continue
			}
			values := make([]interface{}, covered)
			for i := 0; i < covered; i++ {
				values[i] = nodeInfo.properties[idx.Properties[i]]
			}
			ids := compositeIndexLookup(store, idx, values, covered == len(idx.Properties))
			usedAnyIndex = true
			set := make(map[storage.NodeID]struct{}, len(ids))
			for _, id := range ids {
				set[id] = struct{}{}
			}
			idSets = append(idSets, set)
		}
	}

	for prop, val := range nodeInfo.properties {
		var ids []storage.NodeID
		probed := false
		if len(nodeInfo.labels) > 0 {
			// Labelled: probe the (label, prop) index when one exists.
			if _, ok := schema.GetPropertyIndex(nodeInfo.labels[0], prop); ok {
				ids = propertyIndexLookup(store, schema, nodeInfo.labels[0], prop, val)
				probed = true
			}
		} else {
			labels := e.indexCandidateLabels(schema, nil, prop)
			if labellessPropertyIndexUsable(store, labels...) {
				ids = schema.PropertyIndexLookupAnyLabel(prop, val)
				probed = true
			}
		}
		// Property has no covering index — record nothing for this prop.
		// The residual `nodeMatchesProps` step still enforces it. A probe
		// that finds nothing for a string, boolean or number means no node
		// holds the value (#821); for other values the scan decides.
		if ids == nil && !(probed && propertyIndexMissIsAuthoritative(val)) {
			continue
		}
		usedAnyIndex = true
		set := make(map[storage.NodeID]struct{}, len(ids))
		for _, id := range ids {
			set[id] = struct{}{}
		}
		idSets = append(idSets, set)
	}

	if !usedAnyIndex || len(idSets) == 0 {
		return nil, false
	}

	// Intersect across all indexed-prop sets.
	smallest := 0
	for i, s := range idSets {
		if len(s) < len(idSets[smallest]) {
			smallest = i
		}
	}
	out := make([]*storage.Node, 0, len(idSets[smallest]))
	for id := range idSets[smallest] {
		hit := true
		for i, s := range idSets {
			if i == smallest {
				continue
			}
			if _, ok := s[id]; !ok {
				hit = false
				break
			}
		}
		if !hit {
			continue
		}
		n, err := e.getQueryNode(store, id)
		if err != nil || n == nil {
			continue
		}
		out = append(out, n)
	}
	return out, true
}

// propertyIndexMissIsAuthoritative reports whether a property index lookup
// that finds no node for value proves that no node holds an equal value:
// strings, booleans and numbers are filed under keys that are equal exactly
// when the values are equal in Cypher (1 and 1.0 share a key).
func propertyIndexMissIsAuthoritative(value interface{}) bool {
	switch value.(type) {
	case string, bool, int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64, float32, float64:
		return true
	}
	return false
}

func splitTopLevelOrTerms(expr string) []string {
	expr = strings.TrimSpace(expr)
	if expr == "" {
		return nil
	}
	orIdx := findTopLevelKeyword(expr, " OR ")
	if orIdx < 0 {
		return []string{expr}
	}
	left := strings.TrimSpace(expr[:orIdx])
	right := strings.TrimSpace(expr[orIdx+4:])
	out := make([]string, 0, 4)
	out = append(out, splitTopLevelOrTerms(left)...)
	out = append(out, splitTopLevelOrTerms(right)...)
	return out
}

// extractVariableNamesFromPattern returns the node variables pattern binds,
// each once in order of first appearance: e.g.,
// "(p:Person)<-[:REL]-(poc:POC)-[:BELONGS_TO]->(a:Area)" returns ["p", "poc", "a"].
// The shared node-binding reader reads them from the pattern's structure, so a
// dynamic label's $any(...), a property map, an element WHERE, a call such as
// shortestPath(...) and a parenthesized or quantified path are not nodes.
func (e *StorageExecutor) extractVariableNamesFromPattern(ctx context.Context, pattern string) []string {
	return canonicalPatternVariables(ctx, pattern)
}

// mergeNodeAbsentKey marks a context whose caller has just scanned the
// MERGE node pattern's whole label and found no matching node
// (pipelineApplyMerge, findMergeNodesScanned): the MERGE creates the node
// without scanning the label a second time (#823).
type mergeNodeAbsentKey struct{}

func withMergeNodeAbsent(ctx context.Context) context.Context {
	return context.WithValue(ctx, mergeNodeAbsentKey{}, true)
}

// executeMergeWithContext runs one MERGE pattern, the text "MERGE pattern"
// without ON CREATE / ON MATCH actions (pipelineApplyMerge splits them off and
// applies them), with the row's bound nodes and relationships: it binds what
// it matched or created into nodeContext / relContext. Its stats report what
// it created, which tells the caller whether ON CREATE or ON MATCH applies.
func (e *StorageExecutor) executeMergeWithContext(ctx context.Context, cypher string, nodeContext map[string]*storage.Node, relContext map[string]*storage.Edge) (*ExecuteResult, error) {
	// The caller's finding applies to this MERGE's node pattern only, not to
	// the clauses that follow it.
	nodeKnownAbsent, _ := ctx.Value(mergeNodeAbsentKey{}).(bool)
	if nodeKnownAbsent {
		ctx = context.WithValue(ctx, mergeNodeAbsentKey{}, false)
	}
	result := &ExecuteResult{
		Columns: []string{},
		Rows:    [][]interface{}{},
		Stats:   &QueryStats{},
	}
	store := e.getStorage(ctx)

	mergePattern := strings.TrimSpace(cypher)
	if startsWithKeywordFold(mergePattern, "MERGE") {
		mergePattern = strings.TrimSpace(mergePattern[len("MERGE"):])
	}

	// A relationship pattern: (a)-[r:TYPE]->(b)
	if containsRelationshipPattern(mergePattern) {
		parsedPattern, err := e.parseMergeRelationshipPattern(ctx, mergePattern, nodeContext, relContext)
		if err != nil {
			return nil, err
		}
		if err := validateMergePatternProperties(parsedPattern.startNodePattern.properties, "node"); err != nil {
			return nil, err
		}
		if err := validateMergePatternProperties(parsedPattern.endNodePattern.properties, "node"); err != nil {
			return nil, err
		}
		if err := validateMergePatternProperties(parsedPattern.properties, "relationship"); err != nil {
			return nil, err
		}

		// Both endpoints are bound by earlier clauses: a pattern with an endpoint
		// the row doesn't bind is a whole-path MERGE (pipelineMergePath), which
		// matches every existing path or creates the whole pattern (#509, #640).
		startNode := nodeContext[parsedPattern.startVariable]
		endNode := nodeContext[parsedPattern.endVariable]
		if startNode == nil {
			return nil, localizedError(localization.CypherMergeStartVariableNotBound(parsedPattern.startVariable, getKeys(nodeContext)), nil)
		}
		if endNode == nil {
			return nil, localizedError(localization.CypherMergeEndVariableNotBound(parsedPattern.endVariable, getKeys(nodeContext)), nil)
		}
		var existingEdge *storage.Edge
		mergeStartNode, mergeEndNode := startNode, endNode
		if parsedPattern.direction == mergeRelationshipIncoming {
			mergeStartNode, mergeEndNode = endNode, startNode
		}
		// Cypher relationship properties inside the MERGE pattern are identity
		// fields. Scan the bounded endpoint pair so same-type relationships with
		// different property identities remain distinct.
		if existingEdge == nil {
			existingEdge, err = findRelationshipForMerge(store, mergeStartNode.ID, mergeEndNode.ID, parsedPattern.relType, parsedPattern.properties)
			if err != nil {
				return nil, localizedError(localization.CypherMergeFindRelationshipFailed(err), err)
			}
			if existingEdge == nil && parsedPattern.direction == mergeRelationshipUndirected {
				existingEdge, err = findRelationshipForMerge(store, mergeEndNode.ID, mergeStartNode.ID, parsedPattern.relType, parsedPattern.properties)
				if err != nil {
					return nil, localizedError(localization.CypherMergeFindRelationshipFailed(err), err)
				}
			}
		}

		var edge *storage.Edge
		if existingEdge != nil {
			edge = existingEdge
		} else {
			// Create new relationship
			edge = &storage.Edge{
				Database:   storage.DatabaseOf(store),
				ID:         e.newRelationshipMergeEdgeID(mergeStartNode.ID, mergeEndNode.ID, parsedPattern.relType, parsedPattern.properties),
				Type:       parsedPattern.relType,
				StartNode:  mergeStartNode.ID,
				EndNode:    mergeEndNode.ID,
				Properties: parsedPattern.properties,
			}
			if err := edge.SetEndpoints(mergeStartNode, mergeEndNode); err != nil {
				return nil, err
			}
			createdEdge, created, createErr := createRelationshipForMerge(e, store, edge, parsedPattern.properties)
			if createErr != nil {
				return nil, localizedError(localization.CypherMergeCreateRelationshipFailed(createErr), createErr)
			}
			edge = createdEdge
			if !created {
				if reporter, ok := store.(interface {
					EdgeCreateWasNoOp(storage.EdgeID) bool
				}); ok && reporter.EdgeCreateWasNoOp(edge.ID) {
					result.Stats.relationshipMergeNoOp = true
				}
			}
			if created {
				result.Stats.RelationshipsCreated = 1
				countCreatedEntity(result.Stats, nil, edge.Properties)
				e.notifyEdgeMutated(string(edge.ID))
				e.notifyNodeMutated(string(edge.StartNode))
				if edge.EndNode != edge.StartNode {
					e.notifyNodeMutated(string(edge.EndNode))
				}
			}
		}

		// Store in context
		if parsedPattern.relVariable != "" {
			relContext[parsedPattern.relVariable] = edge
		}
		return result, nil

	}

	// Parse node pattern
	varName, labels, matchProps, err := e.parseMergeNodePattern(ctx, mergePattern, nodeContext, relContext)
	if err != nil {
		return nil, &classifiedCypherError{
			cause:  err,
			code:   "Neo.ClientError.Statement.SyntaxError",
			detail: "UnexpectedSyntax",
		}
	}
	if err := validateMergePatternProperties(matchProps, "node"); err != nil {
		return nil, err
	}

	// Try to find existing node
	var existingNode *storage.Node
	if candidate := nodeContext[varName]; candidate != nil && mergeNodeMatches(candidate, labels, matchProps) {
		existingNode = candidate
	}
	if existingNode == nil && !nodeKnownAbsent {
		if err := prepareMergeKeys(ctx, store, labels, matchProps, mergeNodeWritesFromContext(ctx).writes(varName)); err != nil {
			return nil, err
		}
		existingNode, err = e.findMergeNode(store, labels, matchProps)
		if err != nil {
			return nil, err
		}
	}

	var node *storage.Node
	if existingNode != nil {
		node = existingNode
	} else {
		node = &storage.Node{
			Database:   storage.DatabaseOf(store),
			ID:         storage.NodeID(e.generateID()),
			Labels:     labels,
			Properties: matchProps,
		}
		if err := validatePropertyValues(node.Properties); err != nil {
			return nil, err
		}
		actualID, err := createMintedNode(store, node)
		if err != nil {
			if !mergeCreateConflict(err) {
				return nil, localizedError(localization.CypherMergeCreateNodeFailed(err), err)
			}
			// A concurrent MERGE created it first: this MERGE matched it.
			recoveredNode, findErr := e.findMergeNode(store, labels, matchProps)
			if findErr != nil {
				return nil, findErr
			}
			if recoveredNode == nil {
				return nil, localizedError(localization.CypherMergeCreateNodeFailed(err), err)
			}
			node = recoveredNode
		} else {
			node.ID = actualID
			e.notifyNodeMutated(string(node.ID))
			result.Stats.NodesCreated = 1
			countCreatedEntity(result.Stats, node.Labels, node.Properties)
		}
	}
	e.cacheMergeNode(labels, matchProps, node)

	// Anonymous pattern nodes do not introduce a variable into scope.
	if varName != "" {
		nodeContext[varName] = node
	}
	return result, nil
}

// parseMergeProperties parses a MERGE pattern's property map text
// ("{k: v, …}") with the statement's bound nodes and relationships. A value
// the parser resolves (a literal, a parameter, an evaluated expression) is
// that value: a string literal is a string, whatever it reads. An expression
// the parser leaves as its own text and that reads a bound variable's
// property (a.id) is evaluated against the bound entities. Null values remain
// in the map so the shared MERGE validator rejects them before matching.
func (e *StorageExecutor) parseMergeProperties(ctx context.Context, propsText string, nodeContext map[string]*storage.Node, relContext map[string]*storage.Edge) (map[string]interface{}, error) {
	return e.materializePropertyMap(ctx, propsText, entityRow(ctx, nodeContext, relContext), true, false)
}

// parseMergeNodePattern is parseMergePattern with the property map read by
// parseMergeProperties.
func (e *StorageExecutor) parseMergeNodePattern(ctx context.Context, pattern string, nodeContext map[string]*storage.Node, relContext map[string]*storage.Edge) (string, []string, map[string]interface{}, error) {
	pattern = strings.TrimSpace(pattern)
	if !strings.HasPrefix(pattern, "(") || !strings.HasSuffix(pattern, ")") {
		return "", nil, nil, localizedError(localization.CypherResidualMergePatternInvalid(pattern), nil)
	}
	head, props := splitNodePatternProperties(pattern)
	variable, labels, labelErr := parseNodeHead(head)
	if labelErr != nil {
		return "", nil, nil, labelErr
	}
	properties, err := e.parseMergeProperties(ctx, props, nodeContext, relContext)
	return variable, labels, properties, err
}

// applySetToRelationshipWithContext is the single per-relationship SET
// applicator (pipeline, MERGE, CREATE ... SET). It applies every assignment in
// setClause that targets varName: r = map / entity (replace), r += map / entity
// (merge) and r.p = value. A null value removes the key. setClause may chain
// several SET clauses (a SET b). It returns the number of properties written
// by Neo4j's properties_set rule (setWrites), or an error for a value Cypher
// cannot store (replacing with a non-map, a map or entity as a property value).
func (e *StorageExecutor) applySetToRelationshipWithContext(ctx context.Context, edge *storage.Edge, varName string, setClause string, nodeContext map[string]*storage.Node, relContext map[string]*storage.Edge) (int, error) {
	if edge == nil || varName == "" {
		return 0, nil
	}
	fullRelContext := make(map[string]*storage.Edge)
	for k, v := range relContext {
		fullRelContext[k] = v
	}
	fullRelContext[varName] = edge

	writes := setWrites{known: propertyKeyLookup(e.getStorage(ctx))}
	var run setPropertyRun
	for segment, next, ok := nextChainedSetClause(setClause, 0); ok; segment, next, ok = nextChainedSetClause(setClause, next) {
		run.applyToRelationship(edge, &writes)
		writes.endRun()
		for _, assignment := range splitSetAssignments(segment) {
			assignment = strings.TrimSpace(assignment)
			if assignment == "" {
				continue
			}

			target, propName, operator, right := splitSetAssignment(assignment)
			if target != varName || propName == "" {
				run.applyToRelationship(edge, &writes)
				writes.endRun()
			}
			if target != varName {
				continue
			}
			switch {
			case operator == "=" && propName == "":
				props, err := e.setSourceMap(ctx, right, "=", nodeContext, fullRelContext)
				if err != nil {
					return writes.count, err
				}
				// A source without properties (an empty node) clears them.
				writes.mapEntries(edge.Properties, props, true)
				edge.Properties = setPropertyMap(props)
			case operator == "+=":
				props, err := e.setSourceMap(ctx, right, "+=", nodeContext, fullRelContext)
				if err != nil {
					return writes.count, err
				}
				writes.mapEntries(edge.Properties, props, false)
				for k, v := range props {
					setRelationshipProperty(edge, k, v)
				}
			case operator == "=":
				// Direct $param resolution (in setPropertyValue) preserves declared
				// types (e.g. []string, []float64) end-to-end. The run's values
				// are written together (setPropertyRun).
				value, err := e.setPropertyValue(ctx, right, nodeContext, fullRelContext)
				if err != nil {
					return writes.count, err
				}
				run.add(propName, value)
			case operator == "[]=":
				key, err := e.dynamicPropertyKeyOf(ctx, propName, nodeContext, fullRelContext, false)
				if err != nil {
					return writes.count, err
				}
				value, err := e.setPropertyValue(ctx, right, nodeContext, fullRelContext)
				if err != nil {
					return writes.count, err
				}
				run.add(key, value)
			case operator == ":":
				// Labels belong to nodes (validateSetClauseScope rejects a
				// relationship target it can see statically).
				return writes.count, labelTargetTypeError("Relationship")
			}
		}
	}
	run.applyToRelationship(edge, &writes)
	return writes.count, nil
}

// applySetToNodeWithContext is the single per-node SET applicator used by
// every SET route (MATCH / pipeline, MERGE in all its forms, CREATE ... SET).
// It applies every assignment in setClause that targets varName: n = map /
// entity (replace), n += map / entity (merge), n.p = value and n:L1:L2 labels.
// A null value removes the key. setClause may chain several SET clauses
// (a SET b). It returns the number of properties written by Neo4j's
// properties_set rule (setWrites), or an error for a value Cypher cannot
// store (replacing with a non-map, a map or entity as a property value);
// assignments are validated statically by validatePipelineSetAssignments.
func (e *StorageExecutor) applySetToNodeWithContext(ctx context.Context, node *storage.Node, varName string, setClause string, nodeContext map[string]*storage.Node, relContext map[string]*storage.Edge) (int, error) {
	// Add current node to context for self-references
	fullContext := make(map[string]*storage.Node)
	for k, v := range nodeContext {
		fullContext[k] = v
	}
	fullContext[varName] = node

	writes := setWrites{known: propertyKeyLookup(e.getStorage(ctx))}
	var run setPropertyRun
	for segment, next, ok := nextChainedSetClause(setClause, 0); ok; segment, next, ok = nextChainedSetClause(setClause, next) {
		writes.endRun()
		if err := e.applyNodeSetClause(ctx, node, varName, segment, fullContext, relContext, &writes, &run); err != nil {
			return writes.count, err
		}
	}
	return writes.count, nil
}

// applyNodeSetClause applies the assignments of one SET clause that target
// varName to node (applySetToNodeWithContext), recording what they write.
func (e *StorageExecutor) applyNodeSetClause(ctx context.Context, node *storage.Node, varName string, setClause string, fullContext map[string]*storage.Node, relContext map[string]*storage.Edge, writes *setWrites, run *setPropertyRun) error {
	defer run.applyToNode(node, writes)
	for _, assignment := range splitSetAssignments(setClause) {
		assignment = strings.TrimSpace(assignment)

		target, propName, operator, right := splitSetAssignment(assignment)
		if target != varName || propName == "" {
			run.applyToNode(node, writes)
			writes.endRun()
		}
		if target != varName {
			continue
		}
		switch {
		case operator == "+=":
			if err := e.applySetMapMergeToNode(ctx, node, varName, right, fullContext, relContext, writes); err != nil {
				return err
			}
		case operator == "=" && propName == "":
			props, err := e.setSourceMap(ctx, right, "=", fullContext, relContext)
			if err != nil {
				return err
			}
			// A source without properties (an empty node) clears them.
			writes.mapEntries(node.Properties, props, true)
			node.Properties = setPropertyMap(props)
		case operator == ":":
			items, err := setLabelChainItems(right)
			if err != nil {
				return err
			}
			labels, err := e.chainLabelNames(ctx, items, fullContext, relContext)
			if err != nil {
				return err
			}
			for _, label := range labels {
				if !containsString(node.Labels, label) {
					node.Labels = append(node.Labels, label)
				}
			}
		case operator == "[]=":
			key, err := e.dynamicPropertyKeyOf(ctx, propName, fullContext, relContext, false)
			if err != nil {
				return err
			}
			value, err := e.setPropertyValue(ctx, right, fullContext, relContext)
			if err != nil {
				return err
			}
			run.add(key, value)
		case operator == "=":
			// Direct $param resolution (in setPropertyValue) preserves declared
			// types end-to-end. The run's values are written together
			// (setPropertyRun).
			value, err := e.setPropertyValue(ctx, right, fullContext, relContext)
			if err != nil {
				return err
			}
			run.add(propName, value)
		}
	}
	return nil
}

// setPropertyValue evaluates the right-hand side of SET x.p = <expr>. A direct
// $param keeps its declared Go type. A map, entity or nested list is rejected
// with a TypeError, as in Neo4j (storablePropertyValue).
func (e *StorageExecutor) setPropertyValue(ctx context.Context, expr string, nodes map[string]*storage.Node, rels map[string]*storage.Edge) (interface{}, error) {
	value, err := e.evaluateSetExpressionWithContext(ctx, expr, nodes, rels)
	if err != nil {
		return nil, err
	}
	value, _, err = storablePropertyValue(value)
	return value, err
}

// setSourceMap evaluates the right-hand side of SET x = <expr> or
// SET x += <expr> (operator): a map, or a node / relationship whose
// properties are copied. Any other value, null included, is a TypeError
// (setPropertyMapValue, #907), as is a map holding a value a property cannot
// store. Both operators evaluate their source through the checked boundary;
// every SET route (pipeline, MERGE actions, FOREACH, the UNWIND
// batch routes) calls this.
func (e *StorageExecutor) setSourceMap(ctx context.Context, expr, operator string, nodes map[string]*storage.Node, rels map[string]*storage.Edge) (map[string]interface{}, error) {
	value, err := e.evaluateSetExpressionWithContext(ctx, expr, nodes, rels)
	if err != nil {
		return nil, err
	}
	return setPropertyMapValue(value, operator)
}

// splitSetAssignment splits one SET assignment into its target variable,
// property (for x.p = v), operator ("=", "+=" or ":" for labels) and
// right-hand side. The operator is the first top-level "=" (preceded by "+"
// for +=), so "=" or "+=" inside a value string, or inside a dynamic key's
// brackets, does not change the form. Targets may be parenthesized:
// SET (n).p = v.
//
// A dynamic property key, x[expr] = v (Neo4j 5.26), has operator "[]=" and
// its key expression in property; the key is a property name only once
// evaluated (dynamicPropertyKeyOf), so readers that need the name treat the
// item as writing any key. x[expr] += v is not Cypher. Unrecognized text
// yields an empty operator.
func splitSetAssignment(assignment string) (target, property, operator, right string) {
	assignment = strings.TrimSpace(assignment)
	eq := findTopLevelOperator(assignment, "=", false, true)
	if colon := findTopLevelOperator(assignment, ":", false, true); colon > 0 && (eq < 0 || colon < eq) {
		// Label form x:L1:L2 / x:$(expr); a dynamic label expression may
		// itself contain "=".
		if target := strings.TrimSpace(assignment[:colon]); isValidIdentifier(target) {
			return target, "", ":", strings.TrimSpace(assignment[colon+1:])
		}
	}
	if eq < 0 {
		return "", "", "", ""
	}
	left := assignment[:eq]
	operator = "="
	if eq > 0 && assignment[eq-1] == '+' {
		left = assignment[:eq-1]
		operator = "+="
	}
	right = strings.TrimSpace(assignment[eq+1:])
	if receiver, key, subscript, ok := staticPostfixSplit(strings.TrimSpace(left)); ok && subscript {
		key = strings.TrimSpace(key)
		if operator == "+=" || key == "" {
			return "", "", "", ""
		}
		variable, _, _ := parseSetAssignmentTarget(receiver)
		return variable, key, "[]=", right
	}
	target, property, hasProperty := parseSetAssignmentTarget(left)
	if operator == "+=" && hasProperty {
		return "", "", "", ""
	}
	return target, property, operator, right
}

// requireSetParameter reports a SET value that is a bare $name parameter not
// supplied with the query, as Neo4j does, instead of letting the unresolved
// "$name" text be stored. Other expressions pass through unchanged.
func requireSetParameter(ctx context.Context, expr string) error {
	expr = strings.TrimSpace(expr)
	if !strings.HasPrefix(expr, "$") {
		return nil
	}
	name := expr[1:]
	if !isValidIdentifier(name) {
		return nil
	}
	params := getParamsFromContext(ctx)
	if len(params) == 0 {
		return localizedError(localization.CypherMutationsSetAssignmentParametersRequired(name), nil)
	}
	if _, ok := params[name]; !ok {
		return localizedError(localization.CypherMutationsSetAssignmentParameterNotFound(name), nil)
	}
	return nil
}

// setPropertyMapValue converts a SET x = / x += source value into the property
// map to write: maps as-is, nodes and relationships by their properties
// (propertyMapForSetValue). Anything else is a TypeError, null included (Neo4j
// 5.26: "Expected Null() to be a map", #907), as is a map holding a value a
// property cannot store. The map's values are the values a property stores
// (storablePropertyValue), so a map entry is checked as SET x.p = v checks v;
// the source map is copied only when one of them was rewritten.
func setPropertyMapValue(value interface{}, operator string) (map[string]interface{}, error) {
	value = cypherfn.RuntimeValue(value)
	typeName := "NULL"
	if value != nil {
		typeName = cypherTypeName(value)
	}
	props, ok := propertyMapForSetValue(value)
	if value == nil || !ok {
		return nil, localizedStatusError("Neo.ClientError.Statement.TypeError", "InvalidArgumentType",
			localization.CypherMutationsSetSourceNotMap(operator, typeName))
	}
	var stored map[string]interface{}
	for key, v := range props {
		storedValue, rewritten, err := storablePropertyValue(v)
		if err != nil {
			return nil, err
		}
		if rewritten && stored == nil {
			stored = make(map[string]interface{}, len(props))
			for k, original := range props {
				stored[k] = original
			}
		}
		if stored != nil {
			stored[key] = storedValue
		}
	}
	if stored != nil {
		return stored, nil
	}
	return props, nil
}

// evaluateSetExpressionWithContext evaluates a SET (or MERGE ON CREATE / ON
// MATCH SET) value over the clause's nodes and relationships and the value
// scope of ctx, with the row evaluator RETURN and WITH use: a value written
// is the value the same expression projects ([1 > 2] is [false], n.l[0] + 1
// reads the list). An error the evaluation recorded (a temporal
// constructor's ArgumentError, a division by zero) is returned: it is the
// statement's error, which a check of the value it left (null is not a map,
// a list may not hold null) must not replace.
func (e *StorageExecutor) evaluateSetExpressionWithContext(ctx context.Context, expr string, nodes map[string]*storage.Node, rels map[string]*storage.Edge) (interface{}, error) {
	if err := requireSetParameter(ctx, expr); err != nil {
		return nil, err
	}
	if value, resolved := resolveDirectParamRef(ctx, expr); resolved {
		return checkedPropertyResult(ctx, expr, value, true, nil)
	}
	if value, resolved := resolveContextPathRef(ctx, expr); resolved {
		return checkedPropertyResult(ctx, expr, value, true, nil)
	}
	return e.checkedPropertyExpression(ctx, expr, entityRow(ctx, nodes, rels))
}

// mergeBindingRow is the row a MERGE's RETURN reads: the values bound in
// ctx (fabric record and child-context bindings, such as an UNWIND variable)
// and the MERGE's node and relationship bindings.
func (e *StorageExecutor) mergeBindingRow(ctx context.Context, nodes map[string]*storage.Node, rels map[string]*storage.Edge) pipelineRow {
	bindings := valueBindingsFromContext(ctx)
	row := make(pipelineRow, len(e.fabricRecordBindings)+len(bindings)+len(nodes)+len(rels))
	for name, value := range e.fabricRecordBindings {
		row[name] = value
	}
	for name, value := range bindings {
		row[name] = value
	}
	// An unbound variable (an OPTIONAL MATCH without a match) is null.
	for name, node := range nodes {
		if name == "" {
			continue
		}
		if node == nil {
			row[name] = nil
		} else {
			row[name] = node
		}
	}
	for name, edge := range rels {
		if name == "" {
			continue
		}
		if edge == nil {
			row[name] = nil
		} else {
			row[name] = edge
		}
	}
	return row
}

// projectMergeReturn projects a MERGE statement's binding rows through the
// shared RETURN projection (pipelineApplyReturn), so DISTINCT, aggregation,
// ORDER BY, SKIP and LIMIT apply over all the statement's rows (#640).
// returnClause starts with RETURN.
func (e *StorageExecutor) projectMergeReturn(ctx context.Context, rows []pipelineRow, returnClause string) (*ExecuteResult, error) {
	return e.projectMergeReturnSource(ctx, rows, returnClause, pipelineRowsSource(rows))
}

func (e *StorageExecutor) projectMergeReturnSource(ctx context.Context, rows []pipelineRow, returnClause string, source pipelineRowSource, preparedGroups ...[]*pipelineAggregateGroup) (*ExecuteResult, error) {
	returnClause = strings.TrimSpace(returnClause)
	return e.projectMergeReturnPlan(ctx, rows, returnClause, returnProjectionPlanFor(ctx, returnClause), source, preparedGroups...)
}

func (e *StorageExecutor) projectMergeReturnPlan(ctx context.Context, rows []pipelineRow, returnClause string, plan *returnProjectionPlan, source pipelineRowSource, preparedGroups ...[]*pipelineAggregateGroup) (*ExecuteResult, error) {
	priorFailure := getExpressionFailure(ctx)
	result, handled := e.pipelineApplyReturnPlan(ctx, rows, plan, source, false, preparedGroups...)
	if failure := getExpressionFailure(ctx); failure != nil && (!handled || priorFailure == nil) {
		return nil, failure
	}
	if handled {
		return result, nil
	}
	err := newSemanticError(
		"Neo.ClientError.Statement.SyntaxError",
		"UnexpectedSyntax",
		"could not parse RETURN expression: "+strings.TrimSpace(returnClause[len("RETURN"):]),
	)
	recordExpressionFailure(ctx, err)
	return nil, err
}

package cypher

import (
	"context"
	"fmt"
	valueconvert "github.com/orneryd/nornicdb/pkg/convert"
	"strings"
	"sync"

	math "github.com/orneryd/nornicdb/pkg/math/libm"

	"github.com/orneryd/nornicdb/pkg/localization"
)

type semanticValidationCache struct {
	shards [boundedCacheShardCount]semanticValidationCacheShard
	max    int
}

type semanticValidationCacheShard struct {
	mu      sync.RWMutex
	entries map[string]struct{}
}

func newSemanticValidationCache(max int) *semanticValidationCache {
	c := &semanticValidationCache{max: max}
	shardLimit := max / boundedCacheShardCount
	for i := range c.shards {
		c.shards[i].entries = make(map[string]struct{}, shardLimit/4+1)
	}
	return c
}

func (cache *semanticValidationCache) contains(query string) bool {
	if cache == nil {
		return false
	}
	sh := &cache.shards[boundedCacheStringShardIndex(query)]
	sh.mu.RLock()
	_, exists := sh.entries[query]
	sh.mu.RUnlock()
	return exists
}

func (cache *semanticValidationCache) add(query string) {
	if cache == nil || cache.max <= 0 {
		return
	}
	sh := &cache.shards[boundedCacheStringShardIndex(query)]
	sh.mu.Lock()
	if len(sh.entries) >= cache.max/boundedCacheShardCount {
		clear(sh.entries)
	}
	sh.entries[query] = struct{}{}
	sh.mu.Unlock()
}

// validateMergeSemanticScopes applies the MERGE binding and pattern-value
// contract before routing. Keeping this validation ahead of every physical
// executor prevents optimized and general MERGE paths from accepting different
// syntax or producing effects before a semantic failure.
func (e *StorageExecutor) validateMergeSemanticScopes(ctx context.Context, cypher string, cypher25 bool) error {
	if findKeywordIndexInContext(cypher, "MERGE") < 0 {
		return nil
	}
	// Literal-bearing MERGE statements share one compile verdict through the
	// canonical form (PR #1043 #6), looked up only when the exact text
	// misses; failures are never cached, so a bad statement still reports
	// its own error. Both keys carry the language version (semanticCacheKey).
	key := semanticCacheKey(cypher, cypher25)
	cached := e.mergeSemanticValidationCache.contains(key)
	var canonicalKey string
	var normalized bool
	if !cached {
		var canonical string
		canonical, normalized = normalizeLiteralText(cypher)
		if normalized {
			canonicalKey = semanticCacheKey(canonical, cypher25)
			cached = e.mergeSemanticValidationCache.contains(canonicalKey)
		}
	}
	if cached {
		return nil
	}
	clauses, err := e.boundMutationClauses(ctx, cypher, cypher25)
	if err != nil {
		return err
	}
	for _, clause := range clauses {
		if clause.kind == pipelineClauseMerge {
			if err := e.validateMergeClause(ctx, clauseBindingScope(clause, nil), clause.text, cypher25); err != nil {
				return err
			}
		}
	}
	if normalized {
		e.mergeSemanticValidationCache.add(canonicalKey)
	}
	e.mergeSemanticValidationCache.add(key)
	return nil
}

func addMergePatternBindings(scope *semanticBindingScope, clause string) {
	pattern := strings.TrimSpace(clause)
	for _, keyword := range []string{"OPTIONAL MATCH", "MATCH", "CREATE"} {
		if startsWithKeywordFold(pattern, keyword) {
			pattern = strings.TrimSpace(pattern[len(keyword):])
			break
		}
	}
	for _, name := range extractNodeVariables(pattern) {
		scope.bind(name)
	}
	for _, name := range extractRelationshipVariables(pattern) {
		scope.bind(name)
	}
	if name := extractPathAssignmentVariable(pattern); name != "" {
		scope.bind(name)
	}
}

// cypher25 adds Neo4j 2026.09's rule for a Cypher 25 statement: a property
// value may not read a node or relationship the same MERGE creates
// (MERGE (a {x: 1})-[:T]->(b {x: a.x})).
func (e *StorageExecutor) validateMergeClause(ctx context.Context, scope *semanticBindingScope, clause string, cypher25 bool) error {
	// Neo4j rejects EXISTS / COUNT / COLLECT { … } anywhere in a MERGE clause:
	// its pattern, property maps and ON CREATE / ON MATCH SET actions.
	if mayContainSubqueryExpression(clause) && len(findSubqueryExpressions(clause)) > 0 {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"SubqueryInMerge",
			"Subquery expressions are not allowed in a MERGE clause.",
		)
	}
	pattern := mergeClausePattern(clause)
	if pattern == "" {
		return nil
	}
	if mergePatternUsesParameterPredicate(pattern) {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidParameterUse",
			"MERGE pattern predicates must use a property map, not a parameter map",
		)
	}
	if e.mergePatternContainsNullProperty(pattern) {
		return newSemanticError(
			"Neo.ClientError.Statement.SemanticError",
			"MergeReadOwnWrites",
			"MERGE cannot match or create an entity using a null property value",
		)
	}

	relationshipPattern := patternHasRelationship(pattern)
	relationshipVariables := extractRelationshipVariables(pattern)
	for _, variable := range relationshipVariables {
		if scope.contains(variable) {
			return mergeVariableAlreadyBoundError(variable)
		}
	}
	if cypher25 {
		if err := e.validateCreateSamePatternReferences(ctx, scope, pattern, relationshipVariables, make(map[string]string), "MERGE"); err != nil {
			return err
		}
	}
	if relationshipPattern {
		// Every relationship of a MERGE path (mergePathSegments).
		segments := mergePathSegments(pattern)
		if len(segments) < 2 {
			segments = []string{pattern}
		}
		for _, segment := range segments {
			if err := validateMergeRelationshipShape(segment); err != nil {
				return err
			}
		}
	}
	for _, nodePattern := range e.splitNodePatterns(pattern) {
		variable := createNodePatternVariable(nodePattern)
		if variable == "" {
			continue
		}
		if scope.contains(variable) {
			if !relationshipPattern || createNodePatternHasDecoration(nodePattern) {
				return mergeVariableAlreadyBoundError(variable)
			}
			continue
		}
		scope.bind(variable)
	}
	for _, variable := range relationshipVariables {
		scope.bind(variable)
	}
	if pathVariable := extractPathAssignmentVariable(pattern); pathVariable != "" {
		if scope.contains(pathVariable) {
			return mergeVariableAlreadyBoundError(pathVariable)
		}
		scope.bind(pathVariable)
	}
	if err := e.validateMergeActionScopes(ctx, scope, clause); err != nil {
		return err
	}
	for _, nodePattern := range e.splitNodePatterns(pattern) {
		if err := e.validateCreatePatternExpressions(scope, nodePattern); err != nil {
			return err
		}
	}
	if err := e.validateCreateRelationshipExpressions(scope, pattern); err != nil {
		return err
	}
	return nil
}

func (e *StorageExecutor) validateMergeActionScopes(ctx context.Context, scope *semanticBindingScope, clause string) error {
	parts := splitMergeClauseActions(mergeClauseBody(clause))
	for _, clauses := range [...]mergeActionClauses{parts.onCreate, parts.onMatch} {
		for index := 0; index < clauses.len(); index++ {
			if err := e.validateSetClauseScope(ctx, scope, clauses.set(index)); err != nil {
				return err
			}
		}
	}
	return nil
}

func validateMergeRelationshipShape(pattern string) error {
	open, close := firstRelationshipBracket(pattern)
	if open < 0 || close < 0 {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"NoSingleRelationshipType",
			"MERGE relationships require exactly one relationship type",
		)
	}

	return validateSingleRelationshipDeclaration("MERGE", "merged", pattern[open+1:close])
}

func mergeClausePattern(clause string) string {
	return splitMergeClauseActions(mergeClauseBody(clause)).pattern
}

// mergeClauseBody is a MERGE clause's text after the MERGE keyword.
func mergeClauseBody(clause string) string {
	body := strings.TrimSpace(clause)
	if startsWithKeywordFold(body, "MERGE") {
		body = strings.TrimSpace(body[len("MERGE"):])
	}
	return body
}

func mergePatternUsesParameterPredicate(pattern string) bool {
	for index := 0; index < len(pattern); index++ {
		character := pattern[index]
		switch cypherLexicalByte(character) {
		case cypherQuoteClass:
			index = skipCypherQuotedText(pattern, index, character) - 1
		case '/':
			if end := queryCommentEnd(pattern, index); end >= 0 {
				index = end - 1
			}
		case '{':
			if end := findMatchingDelimiter(pattern, index, '{', '}'); end > index {
				index = end
			}
		case '$':
			if dynamicLabelStartsAt(pattern, index) {
				// A dynamic label or type ($(e), $all(e), $any(e)), not a
				// parameter map.
				if closing := findMatchingDelimiter(pattern, strings.IndexByte(pattern[index:], '(')+index, '(', ')'); closing > 0 {
					index = closing
				}
				continue
			}
			// A $ inside a name (n:L$M) is no parameter.
			if isParameterStart(pattern, index) {
				return true
			}
		}
	}
	return false
}

func (e *StorageExecutor) mergePatternContainsNullProperty(pattern string) bool {
	for cursor := 0; cursor < len(pattern); cursor++ {
		if pattern[cursor] != '{' {
			continue
		}
		end := e.findMatchingBrace(pattern, cursor)
		if end < 0 {
			return false
		}
		for _, entry := range splitTopLevelComma(pattern[cursor+1 : end]) {
			colon := findTopLevelMapKeyValueSeparator(entry)
			if colon >= 0 && strings.EqualFold(strings.TrimSpace(entry[colon+1:]), "null") {
				return true
			}
		}
		cursor = end
	}
	return false
}

// validateMergePatternProperties rejects a MERGE pattern's property whose
// value can't identify an entity (null or NaN) with Neo4j's SemanticError,
// then checks the values are storable (validatePropertyValues). entity
// ("node" or "relationship") names the pattern element in the message.
func validateMergePatternProperties(properties map[string]interface{}, entity string) error {
	for property, value := range properties {
		switch {
		case value == nil:
			return localizedStatusError("Neo.ClientError.Statement.SemanticError", "MergeNullPropertyValue",
				localization.CypherMergePropertyValueNotMergeable(entity, "null", property))
		case isNaNValue(value):
			// NaN equals nothing, itself included, so it can't identify an
			// entity; a NaN inside a list can (Neo4j 5.26, #907).
			return localizedStatusError("Neo.ClientError.Statement.SemanticError", "MergeNaNPropertyValue",
				localization.CypherMergePropertyValueNotMergeable(entity, "NaN", property))
		}
	}
	return validatePropertyValues(properties)
}

func mergeVariableAlreadyBoundError(variable string) error {
	return newSemanticError(
		"Neo.ClientError.Statement.SyntaxError",
		"VariableAlreadyBound",
		fmt.Sprintf("variable %s is already bound and cannot be redeclared by MERGE", variable),
	)
}

// isNaNValue reports whether value is a floating-point NaN.
func isNaNValue(value interface{}) bool {
	floating, ok := valueconvert.FloatValue(value)
	return ok && math.IsNaN(floating)
}

package cypher

import "github.com/orneryd/nornicdb/pkg/storage"

// mintedEntityCreator creates entities whose IDs the executor minted for the
// create (generateID). Such an ID names no stored entity, visible or hidden,
// so a store that would otherwise read storage to rule one out need not.
type mintedEntityCreator interface {
	CreateMintedNode(node *storage.Node) (storage.NodeID, error)
	BulkCreateMintedNodes(nodes []*storage.Node) error
	CreateMintedEdge(edge *storage.Edge) error
	BulkCreateMintedEdges(edges []*storage.Edge) error
}

// createMintedNode creates node, whose ID the executor minted, through
// store's minted create when it has one and its ordinary create otherwise.
func createMintedNode(store storage.Engine, node *storage.Node) (storage.NodeID, error) {
	if creator, ok := store.(mintedEntityCreator); ok {
		return creator.CreateMintedNode(node)
	}
	return store.CreateNode(node)
}

// bulkCreateMintedNodes is createMintedNode for a batch.
func bulkCreateMintedNodes(store storage.Engine, nodes []*storage.Node) error {
	if creator, ok := store.(mintedEntityCreator); ok {
		return creator.BulkCreateMintedNodes(nodes)
	}
	return store.BulkCreateNodes(nodes)
}

// createMintedEdge is createMintedNode for a relationship.
func createMintedEdge(store storage.Engine, edge *storage.Edge) error {
	if creator, ok := store.(mintedEntityCreator); ok {
		return creator.CreateMintedEdge(edge)
	}
	return store.CreateEdge(edge)
}

// bulkCreateMintedEdges is createMintedEdge for a batch.
func bulkCreateMintedEdges(store storage.Engine, edges []*storage.Edge) error {
	if creator, ok := store.(mintedEntityCreator); ok {
		return creator.BulkCreateMintedEdges(edges)
	}
	return store.BulkCreateEdges(edges)
}

package cypher

import (
	"time"

	"github.com/orneryd/nornicdb/pkg/storage"
)

// Cypher owns the time of a user mutation. Storage preserves supplied times so
// imports and recovery can restore historical versions without rewriting them.
// Restore the in-memory time if persistence fails, as with the caller's values.
func updateMutatedNode(store storage.Engine, node *storage.Node) error {
	previous := node.UpdatedAt
	node.UpdatedAt = time.Now()
	if err := store.UpdateNode(node); err != nil {
		node.UpdatedAt = previous
		return err
	}
	return nil
}

func updateMutatedEdge(store storage.Engine, edge *storage.Edge) error {
	previous := edge.UpdatedAt
	edge.UpdatedAt = time.Now()
	if err := store.UpdateEdge(edge); err != nil {
		edge.UpdatedAt = previous
		return err
	}
	return nil
}

package cypher

import (
	"context"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// The search between two bound ends of a uniform pattern (#1212): one
// whose every relationship pattern is the same unconstrained one and whose
// inner nodes are unconstrained, as shortestPath((a)-[:T*]-(b)) is. Any
// walk of such relationships between the ends is a walk of the pattern when
// its length is one the pattern allows, and a shortest walk between two
// distinct nodes repeats no node, so it is a path. The walks are searched
// from both ends over node ids, with the relationship each node was reached
// by; the nodes of the paths found are read in one call, and each path is
// read through the automaton and bound as any other (bindSelectedPath).

// pathSearchWalkHop is how a walk from one end reached a node: from the node
// before it, along edge.
type pathSearchWalkHop struct {
	from storage.NodeID
	edge *storage.Edge
}

// pathSearchWalkReach is a node a walk search reached: the length of the
// shortest walk to it and the last hop of one such walk.
type pathSearchWalkReach struct {
	depth int
	hop   pathSearchWalkHop
}

// pathSearchWalkSide is the walk search from one end: the nodes reached,
// the last hops of their other shortest walks (when every shortest path is
// wanted), and the nodes reached last.
type pathSearchWalkSide struct {
	direction string
	reached   map[storage.NodeID]pathSearchWalkReach
	more      map[storage.NodeID][]pathSearchWalkHop
	frontier  []storage.NodeID
	next      []storage.NodeID
	radius    int
}

// uniformTransition returns the transition every relationship pattern of
// a is, when a is uniform: every transition is the same relationship
// pattern without predicates or a variable an earlier clause may bind,
// every slot but the first and the final takes any node, and a chain from
// the first slot leads to a transition. start is that chain.
func uniformTransition(a *pathSearchAutomaton) (uniform *pathSearchTransition, start int) {
	// Multiple repetitions can decompose the same walk in different ways.
	// The general automaton search already enumerates those bindings.
	if a.repetitions > 1 {
		return nil, -1
	}
	start = -1
	for index, chain := range a.chains[a.initial] {
		if len(a.slots[chain.end].transitions) > 0 {
			start = index
			break
		}
	}
	if start < 0 {
		return nil, -1
	}
	for index := range a.slots {
		slot := &a.slots[index]
		if index != a.initial && index != a.final &&
			(len(slot.labels) > 0 || len(slot.predicates) > 0 || slot.variable != "" && !slot.list) {
			return nil, -1
		}
		for t := range slot.transitions {
			transition := &slot.transitions[t]
			if len(transition.predicates) > 0 || transition.variable != "" && !transition.list {
				return nil, -1
			}
			if uniform == nil {
				uniform = transition
				continue
			}
			if transition.direction != uniform.direction || !equalStrings(transition.types, uniform.types) {
				return nil, -1
			}
		}
	}
	return uniform, start
}

// equalStrings reports whether two lists hold the same strings in order.
func equalStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for index := range a {
		if a[index] != b[index] {
			return false
		}
	}
	return true
}

// uniformPair returns the rows of the shortest path from source to target
// (every one for groups) of a uniform pattern, and ok false when the walk
// search can't answer, which leaves the pair to the general search.
func (s *pathSearch) uniformPair(source, target *storage.Node, groups bool, bind func(pathSearchPath) (pipelineRow, bool)) ([]pipelineRow, bool) {
	a := s.a
	if viewport, ok := TemporalViewportFromContext(s.ctx); a.uniform == nil || source.ID == target.ID || ok && viewport.Enabled() {
		return nil, false
	}
	if !s.chainHolds(a.chains[a.initial][a.uniformStart], source) || !s.slotHolds(a.final, target) {
		return nil, true
	}
	forward := s.newWalkSide(source.ID, a.uniform.direction, groups)
	backward := s.newWalkSide(target.ID, reverseDirection(a.uniform.direction), groups)
	shortest, meets := -1, []storage.NodeID(nil)
	for shortest < 0 && len(forward.frontier) > 0 && len(backward.frontier) > 0 && s.ctx.Err() == nil &&
		(s.maxLength < 0 || forward.radius+backward.radius < s.maxLength) {
		if len(forward.frontier) <= len(backward.frontier) {
			shortest, meets = s.walkLevel(forward, backward, groups)
		} else {
			shortest, meets = s.walkLevel(backward, forward, groups)
		}
		if getExpressionFailure(s.ctx) != nil {
			return nil, true
		}
	}
	if shortest < 0 {
		// No walk, so no path, within the length allowed.
		return nil, true
	}
	if shortest < a.minLength {
		return nil, false
	}
	var walks [][]*storage.Edge
	for _, meet := range meets {
		for _, before := range s.walkHops(forward, meet, groups) {
			for _, after := range s.walkHops(backward, meet, groups) {
				if s.ctx.Err() != nil {
					return nil, true
				}
				// The hops to meet from the start, then from meet to the end:
				// the walk's relationships in order.
				walk := make([]*storage.Edge, 0, shortest)
				for index := len(before) - 1; index >= 0; index-- {
					walk = append(walk, before[index].edge)
				}
				for _, hop := range after {
					walk = append(walk, hop.edge)
				}
				walks = append(walks, walk)
				if !groups {
					break
				}
			}
			if !groups && len(walks) > 0 {
				break
			}
		}
		if !groups && len(walks) > 0 {
			break
		}
	}
	return s.bindWalks(source, target, walks, groups, bind)
}

// newWalkSide starts the walk search from the node id.
func (s *pathSearch) newWalkSide(id storage.NodeID, direction string, groups bool) *pathSearchWalkSide {
	side := &pathSearchWalkSide{direction: direction, reached: map[storage.NodeID]pathSearchWalkReach{id: {}},
		frontier: []storage.NodeID{id}}
	if groups {
		side.more = map[storage.NodeID][]pathSearchWalkHop{}
	}
	return side
}

// walkLevel extends side by one relationship and returns the length of the
// shortest walk through a node both sides reached, and those nodes on the
// side's new level (-1 and nil when there is none yet). Every such node
// gives the same length: a node the other side reached before its last
// level would have met this side earlier. So one shortest walk ends the
// level at the first node met, and every shortest walk needs the level
// whole, for the hops into its nodes.
func (s *pathSearch) walkLevel(side, other *pathSearchWalkSide, groups bool) (int, []storage.NodeID) {
	reached := side.radius + 1
	shortest := -1
	next := side.next[:0]
	for count, id := range side.frontier {
		if count&bfsCancelCheckMask == 0 && s.ctx.Err() != nil {
			return -1, nil
		}
		outgoing, incoming, err := s.walkEdges(id, side.direction)
		if err != nil {
			recordExpressionFailure(s.ctx, err)
			return -1, nil
		}
		// A self-relationship (in both lists) reaches the node itself, which
		// the side has reached.
		for _, edges := range [2][]*storage.Edge{outgoing, incoming} {
			for index, edge := range edges {
				if index&bfsCancelCheckMask == 0 && s.ctx.Err() != nil {
					return -1, nil
				}
				if !walkTypeMatches(s.a.uniform.types, edge.Type) {
					continue
				}
				node := otherEnd(edge, id)
				known, seen := side.reached[node]
				hop := pathSearchWalkHop{from: id, edge: edge}
				switch {
				case !seen:
					side.reached[node] = pathSearchWalkReach{depth: reached, hop: hop}
					next = append(next, node)
					if met, both := other.reached[node]; both && shortest < 0 {
						shortest = reached + met.depth
						if !groups {
							side.frontier, side.radius = nil, reached
							return shortest, []storage.NodeID{node}
						}
					}
				case groups && known.depth == reached:
					side.more[node] = append(side.more[node], hop)
				}
			}
		}
	}
	side.next, side.frontier = side.frontier, next
	side.radius = reached
	if shortest < 0 {
		return -1, nil
	}
	var meets []storage.NodeID
	for _, node := range next {
		if met, both := other.reached[node]; both && reached+met.depth == shortest {
			meets = append(meets, node)
		}
	}
	return shortest, meets
}

// walkEdges lists node's relationships in direction, in two lists.
func (s *pathSearch) walkEdges(node storage.NodeID, direction string) ([]*storage.Edge, []*storage.Edge, error) {
	return incidentEdgeListsContext(s.ctx, s.e.storage, node, direction)
}

// walkTypeMatches reports whether a relationship of the type name takes a
// transition of types (any type when there are none).
func walkTypeMatches(types []string, name string) bool {
	if len(types) == 0 {
		return true
	}
	for _, typeName := range types {
		if typeName == name {
			return true
		}
	}
	return false
}

// walkHops returns the shortest walks from side's end to node, each as its
// hops from node back to the end: one, or all of them for groups.
func (s *pathSearch) walkHops(side *pathSearchWalkSide, node storage.NodeID, groups bool) [][]pathSearchWalkHop {
	if s.ctx.Err() != nil {
		return nil
	}
	known := side.reached[node]
	if !groups {
		hops := make([]pathSearchWalkHop, 0, known.depth)
		for ; known.depth > 0; known = side.reached[known.hop.from] {
			if s.ctx.Err() != nil {
				return nil
			}
			hops = append(hops, known.hop)
		}
		return [][]pathSearchWalkHop{hops}
	}
	if known.depth == 0 {
		return [][]pathSearchWalkHop{nil}
	}
	hops := []pathSearchWalkHop{known.hop}
	if groups {
		hops = append(hops, side.more[node]...)
	}
	var walks [][]pathSearchWalkHop
	for _, hop := range hops {
		for _, rest := range s.walkHops(side, hop.from, groups) {
			if s.ctx.Err() != nil {
				return nil
			}
			walks = append(walks, append([]pathSearchWalkHop{hop}, rest...))
		}
	}
	return walks
}

// bindWalks reads the nodes of walks (each its relationships in order from
// source) in one call and returns the rows of the walks the pattern binds:
// the first one, or all of them for groups. ok is false when a node doesn't
// load or a walk doesn't bind, which leaves the pair to the general search.
func (s *pathSearch) bindWalks(source, target *storage.Node, walks [][]*storage.Edge, groups bool, bind func(pathSearchPath) (pipelineRow, bool)) ([]pipelineRow, bool) {
	if s.ctx.Err() != nil {
		return nil, true
	}
	nodes := map[storage.NodeID]*storage.Node{source.ID: source, target.ID: target}
	var ids []storage.NodeID
	for _, walk := range walks {
		if s.ctx.Err() != nil {
			return nil, true
		}
		for _, edge := range walk {
			if s.ctx.Err() != nil {
				return nil, true
			}
			for _, id := range [2]storage.NodeID{edge.StartNode, edge.EndNode} {
				if _, known := nodes[id]; !known {
					nodes[id] = nil
					ids = append(ids, id)
				}
			}
		}
	}
	if len(ids) > 0 {
		loaded, err := s.e.storage.BatchGetNodes(ids)
		if err != nil {
			return nil, false
		}
		for _, id := range ids {
			if nodes[id] = loaded[id]; nodes[id] == nil {
				return nil, false
			}
		}
	}
	var rows []pipelineRow
	for _, walk := range walks {
		if s.ctx.Err() != nil {
			return nil, true
		}
		steps := make([]pathSearchPathStep, len(walk))
		at := source.ID
		for index, edge := range walk {
			if s.ctx.Err() != nil {
				return nil, true
			}
			at = otherEnd(edge, at)
			steps[index] = pathSearchPathStep{edge: edge, node: nodes[at]}
		}
		path, ok := s.a.walkPathContext(s.ctx, source, steps)
		if !ok {
			return nil, false
		}
		row, holds := bind(path)
		if !holds {
			return nil, false
		}
		rows = append(rows, row)
		if !groups {
			break
		}
	}
	return rows, true
}

// walkPath reads a walk of the uniform pattern from start (steps hold the
// relationships and nodes) through the automaton: the chain it starts with
// and the move of each step. ok is false when the pattern has no such path.
func (a *pathSearchAutomaton) walkPath(start *storage.Node, steps []pathSearchPathStep) (pathSearchPath, bool) {
	return a.walkPathContext(context.Background(), start, steps)
}

func (a *pathSearchAutomaton) walkPathContext(ctx context.Context, start *storage.Node, steps []pathSearchPathStep) (pathSearchPath, bool) {
	type replayKey struct {
		slot, step int
		counts     string
	}
	var failed map[replayKey]bool
	var visit func(slot, step int, counts string) bool
	visit = func(slot, step int, counts string) bool {
		if ctx.Err() != nil {
			return false
		}
		if step == len(steps) {
			return slot == a.final
		}
		if failed[replayKey{slot, step, counts}] {
			return false
		}
		for _, index := range a.from[slot] {
			to := a.moves[index].to
			if (step == len(steps)-1) != (to == a.final) {
				continue
			}
			move := a.moves[index]
			transition := a.slots[move.from].transitions[move.transition]
			next, ok := a.chainCounts(a.chains[transition.to][move.chain], counts)
			if ok && visit(to, step+1, next) {
				steps[step].move = index
				return true
			}
		}
		if failed == nil {
			failed = map[replayKey]bool{}
		}
		failed[replayKey{slot, step, counts}] = true
		return false
	}
	for _, chain := range a.chains[a.initial] {
		counts, valid := a.chainCounts(chain, "")
		if !valid {
			continue
		}
		if len(steps) == 0 && chain.end == a.final || len(steps) > 0 && len(a.slots[chain.end].transitions) > 0 && visit(chain.end, 0, counts) {
			return pathSearchPath{start: start, chain: chain.slots, steps: steps}, true
		}
	}
	return pathSearchPath{}, false
}

package cypher

// Pipeline executor for composite queries of the form
//
//	MATCH ... [WHERE ...]
//	CREATE ... (any number)
//	WITH ... (projection / pass-through)
//	UNWIND <list-expression> AS <var>
//	MATCH ...
//	CREATE ...
//	[RETURN ...]
//
// The existing executeMatchWithClause / executeMatchWithUnwind handlers assume
// the segment between MATCH and WITH is a single node pattern. That makes
// them corrupt any query where CREATE clauses live between MATCH and WITH
// (the classic "invalid property value" error where a generated property key
// swallows the rest of the query, e.g. key="{}UNWIND[{productID").
//
// This file walks the clauses in order and threads a binding context through
// each step so arbitrary compositions work. It reuses the existing primitives
// (executeMatchForContext, executeCreateWithRefs, executeInternal) rather
// than reparsing patterns from scratch.

import (
	"context"
	cypherantlr "github.com/orneryd/nornicdb/pkg/cypher/antlr"
	"reflect"
	"slices"
	"sort"
	"strings"
	"sync"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
	"github.com/orneryd/nornicdb/pkg/util"
)

// pipelineClauseKind enumerates the clause types the pipeline executor
// understands. Anything else causes us to bail and return false so callers
// delegate to specialized executors. OPTIONAL MATCH is supported for bounded,
// single-hop clauses after a WITH horizon.
type pipelineClauseKind int

const (
	pipelineClauseMatch pipelineClauseKind = iota
	pipelineClauseOptionalMatch
	pipelineClauseCreate
	pipelineClauseMerge
	pipelineClauseDelete
	pipelineClauseSet
	pipelineClauseRemove
	pipelineClauseWith
	pipelineClauseUnwind
	pipelineClauseReturn
	pipelineClauseForeach
	pipelineClauseCallSubquery
	// pipelineClauseCall is a procedure call, CALL proc(args) YIELD … [WHERE …].
	pipelineClauseCall
	pipelineClauseLet
	pipelineClauseFilter
)

// pipelineClause is one segment of the pipeline. `text` includes the leading
// keyword (MATCH/CREATE/WITH/UNWIND/RETURN) and the clause body — exactly
// what you would pass to the clause implementation.
type pipelineClause struct {
	bindings        *semanticBodyScope
	validationScope map[string]struct{}
	kind            pipelineClauseKind
	syntax          cypherantlr.SyntaxNode
	text            string
	// optional marks OPTIONAL CALL (kinds pipelineClauseCall and
	// pipelineClauseCallSubquery; text is the CALL itself): an input row the
	// call produces no row for is kept, with null for the call's columns
	// (#907).
	optional bool
}

// pipelineMatchPhysicalHint describes downstream row requirements that a
// MATCH operator may safely push into candidate collection or traversal. The
// logical pipeline remains N-ary; this is an operator property derived by
// walking every remaining clause, not a separate query-shape handler.
type pipelineMatchPhysicalHint struct {
	orderExpr  string
	limit      int
	earlyLimit int
	// readTail holds the clauses after the MATCH when every one of them only
	// reads; nil otherwise. A label scan uses it to read only the properties
	// those clauses use (pipelineLabelScanProjection).
	readTail []string
	// streamScan lets the MATCH hand its candidates on as the scan reads
	// them: the statement only reads and streams its result to the client,
	// and the MATCH runs once (#939).
	streamScan bool
}

// pipelineReadOnlyTail returns the texts of remaining when every clause only
// reads and the last one is a RETURN, and nil otherwise. Clauses that don't
// end in RETURN may be one part of a larger statement whose later clauses can
// use any property. RETURN * and WITH * carry every variable on whole: a CALL
// subquery runs its outer MATCH as MATCH ... RETURN *.
func pipelineReadOnlyTail(remaining []pipelineClause) []string {
	if len(remaining) == 0 || remaining[len(remaining)-1].kind != pipelineClauseReturn {
		return nil
	}
	tail := make([]string, 0, len(remaining))
	for _, clause := range remaining {
		switch clause.kind {
		case pipelineClauseWith, pipelineClauseReturn:
			keyword := "RETURN"
			if clause.kind == pipelineClauseWith {
				keyword = "WITH"
			}
			body, _ := cutDistinct(pipelineClauseBody(clause.text, keyword))
			if strings.HasPrefix(strings.TrimSpace(body), "*") {
				return nil
			}
			tail = append(tail, clause.text)
		case pipelineClauseMatch, pipelineClauseOptionalMatch, pipelineClauseUnwind:
			tail = append(tail, clause.text)
		default:
			return nil
		}
	}
	return tail
}

// pipelineLabelScanProjection returns the properties a label scan for
// nodePattern must read: those its inline map, its WHERE and the read-only
// clauses after it use through the pattern's variable. It reports false, and
// the scan reads whole nodes, when a later clause can write, when the variable
// is used other than as variable.property (returned, passed on, compared,
// used in a later pattern), or when a temporal viewport needs the node's own
// validity properties.
func pipelineLabelScanProjection(ctx context.Context, nodePattern nodePatternInfo, whereClause string, readTail []string) ([]string, bool) {
	if len(nodePattern.labels) == 0 || readTail == nil {
		return nil, false
	}
	if _, viewport := TemporalViewportFromContext(ctx); viewport {
		return nil, false
	}
	properties := pipelineNodePredicateProperties(nodePattern.variable, whereClause, nodePattern.properties)
	if properties == nil {
		return nil, false
	}
	for _, text := range readTail {
		used := pipelineNodePredicateProperties(nodePattern.variable, text, nil)
		if used == nil {
			return nil, false
		}
		properties = append(properties, used...)
	}
	sort.Strings(properties)
	return slices.Compact(properties), true
}

// pipelineRow carries bindings across clauses. Values may be *storage.Node,
// *storage.Edge, or scalars (for WITH projections and UNWIND variables).
type pipelineRow map[string]interface{}

// canExecuteAsPipeline returns true when the query is decomposable into the
// clause kinds this executor understands. Any unsupported clause (CALL
// subquery, etc.) causes a false return so the
// caller can select a specialized physical plan.
func canExecuteAsPipeline(ctx context.Context, cypher string) ([]pipelineClause, bool) {
	clauses, ok := pipelineClausesFor(ctx, cypher)
	if !ok {
		return nil, false
	}
	if len(clauses) > 0 && clauses[0].kind == pipelineClauseCreate {
		body := pipelineClauseBody(clauses[0].text, "CREATE")
		if !strings.HasPrefix(body, "(") && !namedPathAssignmentPrefix(body) {
			return nil, false
		}
	}
	// Single graph reads, writes and CALL subqueries own their seed row. A
	// lone WITH or UNWIND is a whole statement only before FINISH (#907),
	// and runs on the seed row too.
	if len(clauses) < 2 {
		if len(clauses) == 0 {
			return nil, false
		}
		switch clauses[0].kind {
		case pipelineClauseMatch, pipelineClauseCreate, pipelineClauseMerge, pipelineClauseForeach, pipelineClauseCallSubquery,
			pipelineClauseSet, pipelineClauseRemove, pipelineClauseDelete, pipelineClauseWith, pipelineClauseUnwind, pipelineClauseLet, pipelineClauseFilter:
		default:
			return nil, false
		}
	}
	return clauses, true
}

// pipelineClausesFor splits a statement, or the clauses after a CALL …
// YIELD, into pipeline clauses when every clause is one the pipeline runs.
func pipelineClausesFor(ctx context.Context, cypher string) ([]pipelineClause, bool) {
	return splitPipelineClausesAllowingProcedureCalls(ctx, cypher)
}

// splitUnwindBody splits an UNWIND clause's body (after UNWIND) at its
// top-level AS into the list expression and the alias; an AS inside a
// string, list or map belongs to the expression.
func splitUnwindBody(body string) (list, alias string, ok bool) {
	index := topLevelKeywordIndex(body, "AS")
	if index <= 0 {
		return "", "", false
	}
	return strings.TrimSpace(body[:index]), strings.TrimSpace(body[index+len("AS"):]), true
}

// pipelineClauseBody is a clause's text after its keyword, which the
// clause splitter matched in any letter case (Return, rEtUrN).
func pipelineClauseBody(text, keyword string) string {
	text = strings.TrimSpace(text)
	if len(text) >= len(keyword) && strings.EqualFold(text[:len(keyword)], keyword) {
		text = text[len(keyword):]
	}
	return strings.TrimSpace(text)
}

// pipelineClauseSplits caches parsePipelineClauses by statement text: one
// parse serves both splits (with and without procedure calls as clauses). It
// is cleared when it reaches pipelineClauseSplitLimit entries, which bounds
// it for workloads with unbounded distinct texts.
var pipelineClauseSplits = struct {
	sync.RWMutex
	splits map[string]pipelineClauseSplit
}{splits: make(map[string]pipelineClauseSplit)}

// pipelineClauseSplit is a text's split with procedure calls as clauses;
// topLevelCall records whether the text has a CALL of its own, which makes
// the split without procedure calls unsupported.
type pipelineClauseSplit struct {
	clauses      []pipelineClause
	ok           bool
	topLevelCall bool
}

const pipelineClauseSplitLimit = 4096

// splitPipelineClauses cuts a statement into its pipeline clauses (see
// parsePipelineClauses); a CALL makes it unsupported.
func splitPipelineClauses(ctx context.Context, cypher string) ([]pipelineClause, bool) {
	return cachedPipelineClauses(ctx, cypher, false)
}

// splitPipelineClausesAllowingProcedureCalls is splitPipelineClauses that also
// accepts top-level procedure calls (CALL proc(args) YIELD …) as clauses of
// kind pipelineClauseCall, for the pipeline executor and call-aware semantic
// validation. splitPipelineClauses rejects statements with procedure calls.
func splitPipelineClausesAllowingProcedureCalls(ctx context.Context, cypher string) ([]pipelineClause, bool) {
	return cachedPipelineClauses(ctx, cypher, true)
}

// cachedPipelineClauses computes the split of a text once, for both
// callers: without procedure calls as clauses, a text with a CALL of its own
// is unsupported, and any other text splits the same way. Callers get their
// own copy of the clause list.
func cachedPipelineClauses(ctx context.Context, cypher string, procedureCalls bool) ([]pipelineClause, bool) {
	if ctx.Err() != nil {
		return nil, false
	}
	key := semanticCacheKey(cypher, cypherVersionFromContext(ctx) == "25")
	pipelineClauseSplits.RLock()
	split, cached := pipelineClauseSplits.splits[key]
	pipelineClauseSplits.RUnlock()
	if !cached {
		split.clauses, split.ok, split.topLevelCall = parsePipelineClauses(ctx, cypher)
		if ctx.Err() != nil {
			return nil, false
		}
		pipelineClauseSplits.Lock()
		if ctx.Err() != nil {
			pipelineClauseSplits.Unlock()
			return nil, false
		}
		if len(pipelineClauseSplits.splits) >= pipelineClauseSplitLimit {
			pipelineClauseSplits.splits = make(map[string]pipelineClauseSplit)
		}
		pipelineClauseSplits.splits[key] = split
		pipelineClauseSplits.Unlock()
	}
	if split.topLevelCall && !procedureCalls {
		return nil, false
	}
	if split.clauses == nil {
		return nil, split.ok
	}
	return append([]pipelineClause(nil), split.clauses...), split.ok
}

// parsePipelineClauses walks the query from left to right and slices it on
// top-level MATCH/CREATE/WITH/UNWIND/RETURN keywords, with top-level
// procedure calls (CALL proc(args) YIELD …) as clauses. Returns (clauses,
// true) on success. On anything unsupported (e.g. nested MERGE or CALL
// subquery) returns (nil, false) so the caller falls back. topLevelCall
// reports whether the query has a CALL of its own (cachedPipelineClauses).
func parsePipelineClauses(ctx context.Context, source string) (clauses []pipelineClause, ok bool, topLevelCall bool) {
	body := readQueryBody(ctx, source, 0, len(source))
	if body.status != queryBodyRead || len(body.branches) != 1 {
		return nil, false, false
	}
	branch := body.branches[0]
	if branch.useStart >= 0 || branch.finished || len(branch.clauses) == 0 {
		return nil, false, false
	}
	for _, clause := range branch.clauses {
		if clause.kind == pipelineClauseCall || clause.kind == pipelineClauseCallSubquery {
			topLevelCall = true
		}
		item := clause.pipelineClause
		item.syntax = clause.syntax
		clauses = append(clauses, item)
	}
	return clauses, true, topLevelCall
}

// pipelineApplyOptionally runs an OPTIONAL CALL (pipelineClause.optional)
// over rows one row at a time through apply, which returns the call's rows
// for one input row and the call's column names. An input row the call
// produces no row for is kept, with null for each of the call's columns, as
// Neo4j's OPTIONAL CALL does (#907). *ok reports false when apply can't run
// the call.
func pipelineApplyOptionally(rows []pipelineRow, apply func(row []pipelineRow) ([]pipelineRow, []string, bool, error), ok *bool) ([]pipelineRow, error) {
	out := make([]pipelineRow, 0, len(rows))
	for index := range rows {
		produced, columns, handled, err := apply(rows[index : index+1])
		if err != nil {
			return nil, err
		}
		if !handled {
			*ok = false
			return nil, nil
		}
		if len(produced) > 0 {
			out = append(out, produced...)
			continue
		}
		kept := make(pipelineRow, len(rows[index])+len(columns))
		for name, value := range rows[index] {
			kept[name] = value
		}
		for _, name := range columns {
			if _, bound := kept[name]; !bound {
				kept[name] = nil
			}
		}
		out = append(out, kept)
	}
	return out, nil
}

// findAllTopLevelPipelineKeywordPositions returns clause boundaries outside
// strings and every bracketed construct. In particular, MATCH inside
// EXISTS { MATCH ... } belongs to the predicate and must never become a new
// outer pipeline clause.
func findAllTopLevelPipelineKeywordPositions(query, keyword string) []int {
	// Allocated on the first match: most scans find nothing.
	var positions []int
	parenDepth, bracketDepth, braceDepth := 0, 0, 0
	withSearch := isWithKeyword(keyword)
	if keyword == "" {
		return positions
	}
	// Compare the first byte before the case-insensitive keyword match, so
	// most positions cost one byte comparison instead of an EqualFold call.
	first := asciiUpper(keyword[0])
	for i := 0; i < len(query); i++ {
		character := query[i]
		switch cypherLexicalByte(character) {
		case cypherQuoteClass:
			i = skipCypherQuotedText(query, i, character) - 1
			continue
		case '/':
			if end := queryCommentEnd(query, i); end >= 0 {
				i = end - 1
				continue
			}
		}
		if parenDepth == 0 && bracketDepth == 0 && braceDepth == 0 && asciiUpper(character) == first &&
			i+len(keyword) <= len(query) && strings.EqualFold(query[i:i+len(keyword)], keyword) &&
			(i == 0 || !isIdentByte(query[i-1])) &&
			(i+len(keyword) == len(query) || !isIdentByte(query[i+len(keyword)])) {
			if (!withSearch || !isOperatorWith(query, i)) && !clauseKeywordUsedAsName(query, i, i+len(keyword), keyword) {
				if positions == nil {
					positions = make([]int, 0, 4)
				}
				positions = append(positions, i)
			}
			i += len(keyword) - 1
			continue
		}
		switch character {
		case '(':
			parenDepth++
		case ')':
			if parenDepth > 0 {
				parenDepth--
			}
		case '[':
			bracketDepth++
		case ']':
			if bracketDepth > 0 {
				bracketDepth--
			}
		case '{':
			braceDepth++
		case '}':
			if braceDepth > 0 {
				braceDepth--
			}
		}
	}
	return positions
}

func (e *StorageExecutor) executePipeline(ctx context.Context, cypher string) (outcome pipelineDispatchOutcome) {
	statement := cypher
	cypher = e.substituteParams(cypher, getParamsFromContext(ctx))
	ctx = withExpressionFailureSlot(ctx)
	defer func() {
		if recorded := getExpressionFailure(ctx); recorded != nil && outcome.err == nil {
			outcome = newPipelineDispatchOutcome(nil, true, recorded)
		}
	}()
	hasCallSubquery := firstTopLevelCallSubquery(ctx, cypher) >= 0
	if !hasCallSubquery && startsWithKeywordFold(strings.TrimSpace(cypher), "UNWIND") {
		if !pipelineUnwindUsesRange(cypher) {
			plan, err := e.prepareTopLevelUnwind(ctx, cypher)
			if err != nil {
				return newPipelineDispatchOutcome(nil, true, err)
			}
			if result, handled, err := e.executeUnwindBatchOperator(ctx, plan); handled || err != nil {
				return newPipelineDispatchOutcome(result, handled, err)
			}
		}
	}
	clauses, ok := canExecuteAsPipeline(ctx, cypher)
	if !ok {
		return newPipelineDispatchOutcome(nil, false, nil)
	}
	originalClauses := clauses
	if pipelineHasClauseKind(clauses, pipelineClauseSet) {
		cypher = normalizePipelineWhitespace(cypher)
		clauses, ok = canExecuteAsPipeline(ctx, cypher)
		if !ok {
			return newPipelineDispatchOutcome(nil, false, nil)
		}
	}

	// Parameters remain typed bindings through every clause.
	params := getParamsFromContext(ctx)
	// The statement shortcuts read the store as if every variable were
	// unbound, so a correlated body (EXISTS / COUNT / COLLECT over an
	// imported variable) takes the row pipeline, which is seeded with the
	// imports below.
	if !hasCallSubquery && !e.pipelineReadsImportedBinding(ctx, clauses) {
		if result, handled, err := e.tryExecutePipelineSimpleNodeReadPlan(ctx, clauses, params); handled || err != nil {
			return newPipelineDispatchOutcome(result, handled, err)
		}
		if result, handled, err := e.tryExecutePipelineSimpleRelationshipCountPlan(ctx, clauses, params); handled || err != nil {
			return newPipelineDispatchOutcome(result, handled, err)
		}
	}
	if result, handled, err := e.tryExecutePipelineCreatePlan(ctx, clauses, originalClauses); handled || err != nil {
		return newPipelineDispatchOutcome(result, handled, err)
	}
	// Start with one binding row. Parameters retain their typed values under
	// their `$name` expression keys so list/map inputs are not stringified while
	// crossing WITH and UNWIND horizons.
	initialRow := pipelineRow{}
	for name, value := range e.fabricRecordBindings {
		initialRow[name] = value
	}
	if len(clauses) == 0 || clauses[0].kind != pipelineClauseCallSubquery {
		for name, value := range valueBindingsFromContext(ctx) {
			initialRow[name] = value
		}
	}
	bindParameterRow(ctx, initialRow)
	rows := []pipelineRow{initialRow}
	scope := make(map[string]struct{})
	for name := range initialRow {
		if strings.HasPrefix(name, "$") {
			continue
		}
		scope[name] = struct{}{}
	}

	stream, _ := ctx.Value(armedResultStreamKey{}).(*ResultStream)
	stream.bind(statement, clauses)
	result, handled, err := e.runPipelineClauseRows(ctx, rows, scope, clauses, originalClauses, nil)
	return newPipelineDispatchOutcome(result, handled, err)
}

type pipelineRowOutput struct {
	rows  []pipelineRow
	scope map[string]struct{}
	wrote bool
}

func (e *StorageExecutor) runPipelineClauseRows(ctx context.Context, rows []pipelineRow, scope map[string]struct{}, clauses, originalClauses []pipelineClause, output *pipelineRowOutput) (*ExecuteResult, bool, error) {
	stream, _ := ctx.Value(armedResultStreamKey{}).(*ResultStream)
	programClauses := originalClauses
	if len(programClauses) == 0 {
		programClauses = clauses
	}
	var programErr error
	ctx, programErr = e.bindPipelineProgram(ctx, programClauses, scope)
	if programErr != nil {
		return nil, true, programErr
	}
	result := &ExecuteResult{
		Columns: []string{},
		Rows:    [][]interface{}{},
		Stats:   &QueryStats{},
	}
	wrote := false
	if output != nil {
		wrote = output.wrote
	}
	if pipelineClausesMayDelete(clauses) {
		ctx = withDeletedEntities(ctx)
	}
	// A statement's MERGEs learn which of their nodes it writes once, from
	// all its clauses (a row-ordered stretch below sees only part of them);
	// a subquery or FOREACH body adds what its own clauses write.
	if output == nil && (pipelineHasClauseKind(clauses, pipelineClauseMerge) ||
		pipelineHasClauseKind(clauses, pipelineClauseCallSubquery) || pipelineHasClauseKind(clauses, pipelineClauseForeach)) {
		ctx = withMergeNodeWrites(ctx, clauses)
	}
	independentCreate, _ := ctx.Value(pipelineIndependentCreateBatchKey{}).(bool)
	if len(rows) > 1 && !independentCreate {
		prefix, writes := 0, false
		for _, clause := range clauses {
			if clause.kind == pipelineClauseReturn {
				break
			}
			if clause.kind == pipelineClauseWith {
				if _, local := parsePipelineRowWith(ctx, clause.text); !local {
					break
				}
			}
			switch clause.kind {
			case pipelineClauseCreate, pipelineClauseMerge, pipelineClauseSet, pipelineClauseRemove, pipelineClauseDelete, pipelineClauseForeach:
				writes = true
			case pipelineClauseCall:
				if procedure, found := globalProcedureRegistry.Get(extractProcedureName(ctx, clause.text)); found && procedure.Spec.writes() {
					writes = true
				}
			}
			prefix++
		}
		// Row by row only while no clause of the stretch reads what another
		// one writes (pipelineWriteStretchConflicts); otherwise clause by
		// clause, as Neo4j does.
		if writes && !pipelineWriteStretchConflicts(ctx, clauses[:prefix], clauses[prefix:]) {
			var retained []pipelineRow
			for _, row := range rows {
				rowScope := make(map[string]struct{}, len(scope))
				for name := range scope {
					rowScope[name] = struct{}{}
				}
				state := &pipelineRowOutput{wrote: wrote}
				partial, handled, err := e.runPipelineClauseRows(ctx, []pipelineRow{row}, rowScope, clauses[:prefix], originalClauses[:prefix], state)
				if !handled || err != nil {
					return partial, handled, err
				}
				addQueryStats(result.Stats, partial.Stats)
				retained = append(retained, state.rows...)
				wrote = state.wrote
				scope = state.scope
			}
			rows = retained
			clauses = clauses[prefix:]
			originalClauses = originalClauses[prefix:]
		}
	}
	var source pipelineRowSource
	var terminalCallColumns []string
	// The rows a MATCH, OPTIONAL MATCH or WITH builds count against the
	// statement's memory limit (#1343).
	memory := memoryScopeFromContext(ctx)
	var callChain boundCallChain
	callChainEnd := 0
	for idx := 0; idx < len(clauses); idx++ {
		clause := clauses[idx]
		if (clause.kind == pipelineClauseWith || clause.kind == pipelineClauseReturn) && !callChain.pagination[idx] {
			if err := e.validateRuntimePaginationClause(ctx, clause.text); err != nil {
				return result, true, err
			}
		}
		var callBatch *boundTransactionBatch
		if clause.kind == pipelineClauseCallSubquery {
			_, _, inTransactions, _ := e.parseCallSubquery(ctx, clause.text)
			if inTransactions {
				if idx >= callChainEnd {
					maximumRows := len(rows)
					if source != nil {
						maximumRows = -1
					}
					plan, err := e.planPipelineCallChain(ctx, clauses, idx, maximumRows)
					if err != nil {
						return result, true, err
					}
					callChain, err = e.bindTransactionalCallChain(ctx, plan)
					if err != nil {
						return result, true, err
					}
					callChainEnd = plan.end
				}
				callBatch = callChain.batches[idx]
			}
		}
		if source != nil && clause.kind != pipelineClauseMatch && clause.kind != pipelineClauseWith &&
			clause.kind != pipelineClauseLet && clause.kind != pipelineClauseFilter &&
			!(clause.kind == pipelineClauseCreate && independentCreate) &&
			!(clause.kind == pipelineClauseReturn && (pipelineClauseAggregates(ctx, clause) || stream.forClause(ctx, &clauses[idx]) != nil)) {
			var completed bool
			rows, completed = materializePipelineSource(ctx, source)
			source = nil
			if !completed {
				return pipelineDecline(ctx, wrote, clause.text)
			}
		}
		if deleted := deletedEntitiesOf(ctx); !deleted.empty() {
			if err := validateDeletedEntityReads(rows, deletedEntityReadText(clause), deleted); err != nil {
				return nil, true, err
			}
		}
		switch clause.kind {
		case pipelineClauseLet, pipelineClauseFilter:
			input := source
			if input == nil {
				input = pipelineRowsSource(rows)
			}
			transformed, err := e.pipelineSharedClauseSource(ctx, input, clause)
			if err != nil {
				return nil, true, err
			}
			if clause.kind == pipelineClauseLet {
				projections, err := parsePipelineLet(clause.text)
				if err != nil {
					return nil, true, err
				}
				for _, projection := range projections {
					scope[projection.alias] = struct{}{}
				}
			}
			source, rows = transformed, nil
			continue
		case pipelineClauseMatch:
			hint := e.pipelineMatchHint(ctx, clauses[idx+1:])
			hint.streamScan = source == nil && len(rows) == 1 && len(scope) == 0 && stream.streamsScan(clauses)
			input := source
			if input == nil {
				input = pipelineRowsSource(rows)
			}
			matched, supported, err := e.pipelineNodeMatchSourceWithHint(ctx, input, clause.text, hint)
			if err != nil {
				return nil, true, err
			}
			if supported {
				source, rows = matched, nil
				addPipelinePatternBindings(ctx, e, scope, clause.text, "MATCH")
				continue
			}
			if source != nil {
				var completed bool
				rows, completed = materializePipelineSource(ctx, source)
				source = nil
				if !completed {
					return pipelineDecline(ctx, wrote, clause.text)
				}
			}
			newRows, ok, err := e.pipelineApplyMatchWithHint(ctx, rows, clause.text, hint)
			if err != nil {
				return nil, true, err
			}
			if !ok {
				return pipelineDecline(ctx, wrote, clause.text)
			}
			if err := memory.growRows(newRows); err != nil {
				return nil, true, err
			}
			rows = newRows
			addPipelinePatternBindings(ctx, e, scope, clause.text, "MATCH")
		case pipelineClauseOptionalMatch:
			newRows, err := e.pipelineApplyOptionalMatch(ctx, rows, clause.text)
			if err != nil {
				return nil, true, err
			}
			if err := memory.growRows(newRows); err != nil {
				return nil, true, err
			}
			rows = newRows
			addPipelinePatternBindings(ctx, e, scope, clause.text, "OPTIONAL MATCH")
		case pipelineClauseCreate:
			end := idx + 1
			for end < len(clauses) && clauses[end].kind == pipelineClauseCreate {
				// Publish every earlier CREATE row before a later CREATE
				// reads those writes. Only independent clauses share a plan.
				if pipelineWriteStretchConflicts(ctx, clauses[idx:end+1], nil) {
					break
				}
				end++
			}
			var newRows []pipelineRow
			var created *ExecuteResult
			var ok bool
			var err error
			if source != nil && independentCreate {
				newRows, created, ok, err = e.pipelineCreateSource(ctx, source, clauses[idx:end])
				source = nil
			} else {
				newRows, created, ok, err = e.pipelineApplyCreateClauses(ctx, rows, clauses[idx:end])
			}
			if err != nil {
				return nil, true, err
			}
			if !ok {
				return pipelineDecline(ctx, wrote, clause.text)
			}
			rows = newRows
			for _, createClause := range clauses[idx:end] {
				addPipelinePatternBindings(ctx, e, scope, createClause.text, "CREATE")
			}
			addQueryStats(result.Stats, created.Stats)
			if created.Metadata != nil {
				result.Metadata = created.Metadata
			}
			idx = end - 1
			wrote = true
		case pipelineClauseMerge:
			newRows, stats, err := e.pipelineApplyMerge(ctx, rows, clause.text)
			if err != nil {
				return nil, true, err
			}
			rows = newRows
			addPipelinePatternBindings(ctx, e, scope, clause.text, "MERGE")
			if stats != nil {
				addQueryStats(result.Stats, stats)
			}
			wrote = true
			if idx+1 < len(clauses) {
				e.refreshRowEntities(ctx, rows)
			}
		case pipelineClauseDelete:
			stats, ok, err := e.pipelineApplyDelete(ctx, rows, scope, clause.text)
			if err != nil {
				return nil, true, err
			}
			if !ok {
				return pipelineDecline(ctx, wrote, clause.text)
			}
			addQueryStats(result.Stats, stats)
			wrote = true
		case pipelineClauseSet:
			assignment := clause.text
			for idx+1 < len(clauses) && clauses[idx+1].kind == pipelineClauseSet {
				idx++
				assignment += " " + clauses[idx].text
			}
			// Rows that bind one entity through different copies write one
			// entity: each row reads what the rows before it wrote.
			e.refreshRowEntities(ctx, rows)
			stats, ok, err := e.pipelineApplySet(ctx, rows, assignment)
			if err != nil {
				return nil, true, err
			}
			if !ok {
				return pipelineDecline(ctx, wrote, clause.text)
			}
			addQueryStats(result.Stats, stats)
			wrote = true
			if idx+1 < len(clauses) {
				e.refreshRowEntities(ctx, rows)
			}
		case pipelineClauseRemove:
			e.refreshRowEntities(ctx, rows)
			if err := e.pipelineApplyRemove(ctx, rows, clause.text, result); err != nil {
				return nil, true, err
			}
			wrote = true
			if idx+1 < len(clauses) {
				e.refreshRowEntities(ctx, rows)
			}
		case pipelineClauseWith:
			// Carry imports after projection without adding them to DISTINCT/group keys.
			if source != nil {
				if windowed, supported := e.pipelineWithWindowSource(ctx, source, rows, clause.text); supported {
					source = windowed
					scope, programErr = executionClauseScope(ctx, clause, true)
					if programErr != nil {
						return nil, true, programErr
					}
					continue
				}
				if plan, local := parsePipelineRowWith(ctx, clause.text); local {
					source = e.pipelineWithRowSource(ctx, source, plan)
					scope, programErr = executionClauseScope(ctx, clause, true)
					if programErr != nil {
						return nil, true, programErr
					}
					continue
				}
			}
			if source != nil {
				if !pipelineClauseAggregates(ctx, clause) {
					var completed bool
					rows, completed = materializePipelineSource(ctx, source)
					source = nil
					if !completed {
						return pipelineDecline(ctx, wrote, clause.text)
					}
				}
			}
			if err := e.validatePipelineWithRows(ctx, rows, clause.text); err != nil {
				return nil, true, err
			}
			// The rows just validated are the clause's input when no
			// stream feeds it.
			rowsValidated := source == nil
			if source == nil {
				source = pipelineRowsSource(rows)
			}
			newRows, ok := e.pipelineApplyWithSource(ctx, rows, clause.text, source, rowsValidated)
			source = nil
			if !ok {
				return pipelineDecline(ctx, wrote, clause.text)
			}
			if err := memory.growRows(newRows); err != nil {
				return nil, true, err
			}
			rows = newRows
			scope, programErr = executionClauseScope(ctx, clause, true)
			if programErr != nil {
				return nil, true, programErr
			}
		case pipelineClauseUnwind:
			if err := e.validatePipelineRangeArguments(ctx, rows, clause.text, "UNWIND"); err != nil {
				return nil, true, err
			}
			unwound, consumed, ok := e.pipelineUnwindSource(ctx, rows, clauses[idx:])
			if !ok {
				return pipelineDecline(ctx, wrote, clause.text)
			}
			if alias := pipelineUnwindAlias(clause.text); alias != "" {
				scope[alias] = struct{}{}
			}
			for offset := 1; offset <= consumed; offset++ {
				scope, programErr = executionClauseScope(ctx, clauses[idx+offset], true)
				if programErr != nil {
					return nil, true, programErr
				}
			}
			idx += consumed
			if idx+1 < len(clauses) && (pipelineClauseAggregates(ctx, clauses[idx+1]) || stream.forClause(ctx, &clauses[idx+1]) != nil) {
				source = unwound
				rows = nil
				continue
			}
			rows, ok = materializePipelineSource(ctx, unwound)
			if !ok {
				return pipelineDecline(ctx, wrote, clause.text)
			}
			if len(rows) > 1 && idx+1 < len(clauses) {
				state := &pipelineRowOutput{wrote: wrote}
				if output != nil {
					state = output
					state.wrote = wrote
				}
				remaining, handled, err := e.runPipelineClauseRows(ctx, rows, scope, clauses[idx+1:], originalClauses[idx+1:], state)
				if remaining != nil {
					addQueryStats(remaining.Stats, result.Stats)
				}
				return remaining, handled, err
			}
		case pipelineClauseCall:
			var newRows []pipelineRow
			var yielded []string
			ok := true
			var err error
			if clause.optional {
				newRows, err = pipelineApplyOptionally(rows, func(row []pipelineRow) ([]pipelineRow, []string, bool, error) {
					rowsOut, names, handled, err := e.pipelineApplyProcedureCall(ctx, row, clause.text, result.Stats)
					yielded = names
					return rowsOut, names, handled, err
				}, &ok)
			} else {
				newRows, yielded, ok, err = e.pipelineApplyProcedureCall(ctx, rows, clause.text, result.Stats)
			}
			if err != nil {
				return nil, true, err
			}
			if !ok {
				return pipelineDecline(ctx, wrote, clause.text)
			}
			rows = newRows
			for _, name := range yielded {
				scope[name] = struct{}{}
			}
			if procedure, found := globalProcedureRegistry.Get(extractProcedureName(ctx, clause.text)); found && procedure.Spec.writes() {
				wrote = true
			}
		case pipelineClauseCallSubquery:
			original := clause
			if idx < len(originalClauses) {
				original = originalClauses[idx]
			}
			callMetadata := &pipelineCallMetadata{scope: scope, batch: callBatch, call: executionCallFacts(ctx, original)}
			var newRows []pipelineRow
			var stats *QueryStats
			ok := true
			var err error
			if clause.optional && len(rows) > 0 {
				stats = &QueryStats{}
				newRows, err = pipelineApplyOptionally(rows, func(row []pipelineRow) ([]pipelineRow, []string, bool, error) {
					rowsOut, rowStats, handled, err := e.pipelineApplyCallSubqueryWithMetadata(ctx, row, clause.text, callMetadata)
					addQueryStats(stats, rowStats)
					return rowsOut, callMetadata.columns, handled, err
				}, &ok)
			} else {
				newRows, stats, ok, err = e.pipelineApplyCallSubqueryWithMetadata(ctx, rows, clause.text, callMetadata)
			}
			addQueryStats(result.Stats, stats)
			if err != nil {
				return result, true, err
			}
			if !ok {
				return pipelineDecline(ctx, wrote, clause.text)
			}
			rows = newRows
			terminalCallColumns = append(terminalCallColumns[:0], callMetadata.columns...)
			for _, name := range callMetadata.columns {
				scope[name] = struct{}{}
			}
			if callSubqueryQueryIsWrite(clause.text) || callMetadata.batch != nil {
				wrote = true
			}
		case pipelineClauseForeach:
			e.refreshRowEntities(ctx, rows)
			stats, err := e.pipelineApplyForeach(ctx, rows, clause)
			if err != nil {
				return nil, true, err
			}
			addQueryStats(result.Stats, stats)
			wrote = true
			if idx+1 < len(clauses) {
				e.refreshRowEntities(ctx, rows)
			}
		case pipelineClauseReturn:
			if stream.forClause(ctx, &clauses[idx]) != nil {
				columns, streamedRows, handled, err := e.pipelineStreamReturn(ctx, stream.forClause(ctx, &clauses[idx]), rows, source, clauses, originalClauses, idx, scope, wrote)
				if !handled || err != nil {
					return nil, handled, err
				}
				result.Columns, result.Rows = columns, streamedRows
				return result, true, nil
			}
			if err := e.validatePipelinePercentileArguments(ctx, rows, clause.text, "RETURN"); err != nil {
				return nil, true, err
			}
			if err := e.validatePipelineProjectionValues(ctx, rows, clause.text, "RETURN"); err != nil {
				return nil, true, err
			}
			// The rows just validated are the clause's input when no
			// stream feeds it.
			rowsValidated := source == nil
			if source == nil {
				source = pipelineRowsSource(rows)
			}
			// Fused input operators can change clause indexes; each retained
			// syntax node still names its own canonical projection.
			original := clause
			plan := returnProjectionPlanFor(ctx, original.text, original)
			if plan == nil {
				return nil, true, unresolvedStatementError()
			}
			final, ok := e.pipelineApplyReturnPlan(ctx, rows, plan, source, rowsValidated)
			source = nil
			if !ok {
				if failure := getExpressionFailure(ctx); failure != nil && final != nil {

					return final, true, failure
				}
				return pipelineDecline(ctx, wrote, clause.text)
			}

			result.Columns = final.Columns
			result.Rows = final.Rows
			// RETURN is always last.
			return result, true, nil
		}
		_ = idx
	}
	if source != nil {
		var completed bool
		rows, completed = materializePipelineSource(ctx, source)
		if !completed {
			return pipelineDecline(ctx, wrote, "end of pipeline")
		}
	}
	// A statement ending with a write has no columns and no rows, as in
	// Neo4j (#676).
	if output != nil {
		output.rows = rows
		output.scope = scope
		output.wrote = wrote
	}
	if output == nil && len(clauses) > 0 && clauses[len(clauses)-1].kind == pipelineClauseCallSubquery {
		body, _, _, _ := e.parseCallSubquery(ctx, clauses[len(clauses)-1].text)
		if topLevelKeywordIndex(body, "RETURN") >= 0 {
			result = callPipelineResultFromRows(rows, nil, result.Stats, terminalCallColumns)
		}
	}
	return result, true, nil
}

// pipelineItemUnevaluable records that a RETURN, WITH or UNWIND item can't
// be evaluated (neither the row evaluator nor the shared evaluator handles
// it), unless an expression error is already recorded. The statement fails:
// another route would not evaluate the item either, and the older UNWIND and
// WITH routes run only part of a statement the pipeline started. Subquery
// expressions (EXISTS / COUNT / COLLECT { … }) are row values like any other
// (evaluateRowExpressionWithContext), so they have no route of their own.
func pipelineItemUnevaluable(ctx context.Context, expr string) {
	if getExpressionFailure(ctx) != nil {
		return
	}
	recordExpressionFailure(ctx, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
		localization.CypherCoreExpressionUnevaluable(strings.TrimSpace(expr))))
}

// pipelineDecline is the pipeline's "shape unsupported" answer. Before any
// clause has written it hands the statement to the other routes; once a
// clause has written (CREATE, MERGE, DELETE, SET, REMOVE, FOREACH) the
// statement cannot be run again by another route - that would repeat the
// writes - so it is an error instead.
func pipelineDecline(ctx context.Context, wrote bool, clause string) (*ExecuteResult, bool, error) {
	// A clause that stopped on an expression error doesn't decline: the error
	// is the statement's, and no other route runs the statement instead.
	if failure := getExpressionFailure(ctx); failure != nil {
		return nil, true, failure
	}
	if wrote {
		return nil, true, localizedError(localization.CypherInvariantsPipelineDeclinedAfterWrite(clause), nil)
	}
	return nil, false, nil
}

// pipelineReadsImportedBinding reports whether a clause mentions a variable
// the pipeline's first row imports: a correlated subquery body's outer row
// (fabricRecordBindings) or an enclosing value scope. Parameters are not
// imports. It uses isIdentifierReferenced, the reader unscoped CALL imports
// use, so a body that only names its own variables keeps the shortcuts.
func (e *StorageExecutor) pipelineReadsImportedBinding(ctx context.Context, clauses []pipelineClause) bool {
	references := func(name string) bool {
		if strings.HasPrefix(name, "$") {
			return false
		}
		for _, clause := range clauses {
			if isIdentifierReferenced(clause.text, name) {
				return true
			}
		}
		return false
	}
	for name := range e.fabricRecordBindings {
		if references(name) {
			return true
		}
	}
	if len(clauses) == 0 || clauses[0].kind != pipelineClauseCallSubquery {
		for name := range valueBindingsFromContext(ctx) {
			if references(name) {
				return true
			}
		}
	}
	return false
}

// tryExecutePipelineSimpleRelationshipCountPlan is the fused physical form of
// the pipeline's MATCH -> count reduction for relationship patterns (issue
// #638). Without it, the row pipeline binds the relationship variable for
// every match and counts the materialized rows — so
//
//	MATCH ()-[r:T]->() RETURN count(r)
//
// costs O(store size) instead of an O(1) counter read, even though the
// traversal-layer fast path exists. It delegates to relationshipCountFromStore,
// the single owner of counts answered from the counters (count_store.go).
func (e *StorageExecutor) tryExecutePipelineSimpleRelationshipCountPlan(ctx context.Context, clauses []pipelineClause, params map[string]interface{}) (*ExecuteResult, bool, error) {
	if len(clauses) != 2 || clauses[0].kind != pipelineClauseMatch || clauses[1].kind != pipelineClauseReturn {
		return nil, false, nil
	}
	matchBody := strings.TrimSpace(clauses[0].text[len("MATCH"):])
	if topLevelKeywordIndex(matchBody, "WHERE") >= 0 {
		return nil, false, nil
	}
	// This counter plan owns a relationship pattern, never a path assignment
	// or shortestPath call. Decline their syntax before reading any values.
	if !strings.HasPrefix(matchBody, "(") || !containsRelationshipPattern(matchBody) {
		return nil, false, nil
	}
	if len(splitTopLevelComma(matchBody)) != 1 {
		return nil, false, nil
	}
	// A counter owns one projected item. Decline other projections before
	// reading a traversal that this plan cannot consume.
	items := e.parseReturnItems(ctx, strings.TrimSpace(clauses[1].text[len("RETURN"):]))
	if len(items) != 1 {
		return nil, false, nil
	}
	if !patternMapsAreConstant(matchBody) {
		return nil, false, nil
	}
	matches := e.parseTraversalPatternStructure(ctx, matchBody)
	if matches == nil {
		return nil, false, nil
	}
	count, ok, err := e.relationshipCountFromStore(ctx, matches, items[0])
	if err != nil {
		return nil, true, err
	}
	if !ok {
		return nil, false, nil
	}
	column := items[0].column()
	return &ExecuteResult{Columns: []string{column}, Rows: [][]interface{}{{count}}, Stats: &QueryStats{}}, true, nil
}

// tryExecutePipelineSimpleNodeReadPlan applies cardinality and property-index
// operators before row materialization for a single node MATCH. The result is
// still projected by the pipeline, so indexed and scanned inputs share the
// same expression semantics.
func (e *StorageExecutor) tryExecutePipelineSimpleNodeReadPlan(ctx context.Context, clauses []pipelineClause, params map[string]interface{}) (*ExecuteResult, bool, error) {
	stream, _ := ctx.Value(armedResultStreamKey{}).(*ResultStream)
	if len(clauses) != 2 || clauses[0].kind != pipelineClauseMatch || clauses[1].kind != pipelineClauseReturn {
		return nil, false, nil
	}
	matchBody := strings.TrimSpace(clauses[0].text[len("MATCH"):])
	whereClause := ""
	if whereIndex := topLevelKeywordIndex(matchBody, "WHERE"); whereIndex >= 0 {
		whereClause = strings.TrimSpace(matchBody[whereIndex+len("WHERE"):])
		matchBody = strings.TrimSpace(matchBody[:whereIndex])
	}
	// A path assignment (p = (n:L)) is the general route's, which binds the
	// path: read as a node, its variable would be "p = (n".
	if !e.isSingleNodePattern(matchBody) || extractPathAssignmentVariable(matchBody) != "" {
		return nil, false, nil
	}
	if !patternMapsAreConstant(matchBody) || !patternMapsAreConstant(whereClause) || stream.forClause(ctx, &clauses[1]) != nil {
		return nil, false, nil
	}
	nodePattern, parseErr := e.parseNodePattern(ctx, matchBody)
	if parseErr != nil {
		return nil, true, parseErr
	}
	if nodePattern.variable == "" {
		return nil, false, nil
	}

	items := e.parseReturnItems(ctx, strings.TrimSpace(clauses[1].text[len("RETURN"):]))
	if len(items) > 1 && items[0].expr == "*" {
		// RETURN *, items: the general projection writes the * out (#883).
		return nil, false, nil
	}
	hint := e.pipelineMatchHint(ctx, clauses[1:])
	boundedSimpleProjection := whereClause == "" && hint.earlyLimit > 0 && pipelineSimpleNodeProjections(items, nodePattern.variable)
	countColumn, filteredCount := pipelineSingleNodeCountProjection(items, nodePattern.variable)
	if whereClause == "" && len(items) == 1 {
		if count, ok, err := e.nodeCountFromStore(ctx, nodePattern, items[0]); ok {
			if err != nil {
				return nil, true, localizedError(localization.CypherMatchingStorageFailed(err), err)
			}
			return &ExecuteResult{Columns: []string{items[0].column()}, Rows: [][]interface{}{{count}}, Stats: &QueryStats{}}, true, nil
		}
	}

	candidates, usedIndex, err := e.tryCollectNodesFromPropertyIndexInOrParam(nodePattern, whereClause, params)
	if err != nil {
		return nil, true, err
	}
	if !usedIndex {
		if filteredCount && (whereClause != "" || len(nodePattern.properties) > 0) {
			if result, streamed, streamErr := e.tryStreamPipelineFilteredNodeCount(ctx, nodePattern, whereClause, countColumn); streamed || streamErr != nil {
				return result, true, streamErr
			}
		}
		if !boundedSimpleProjection {
			return nil, false, nil
		}
		// boundedSimpleProjection requires an empty WHERE, so no seek can
		// have applied one here.
		candidates, _, err = e.collectPipelineInitialNodeCandidates(ctx, nodePattern, whereClause, hint)
		if err != nil {
			return nil, true, err
		}
	}
	if boundedSimpleProjection {
		if len(candidates) > hint.earlyLimit {
			candidates = candidates[:hint.earlyLimit]
		}
		return e.projectVisiblePipelineNodeRead(candidates, items, nodePattern.variable), true, nil
	}
	rows := make([]pipelineRow, 0, len(candidates))
	for _, node := range candidates {
		row := pipelineNodeRow(ctx, nodePattern.variable, node)
		if whereClause == "" || e.evaluateWithWhereCondition(ctx, whereClause, map[string]interface{}(row)) {
			rows = append(rows, row)
		}
	}
	result, projected := e.pipelineApplyReturn(ctx, rows, clauses[1].text)
	if !projected {
		return nil, false, nil
	}
	return result, true, nil
}

// pipelineNodeRow is the binding row of a single-node pipeline read: the node
// under its variable and every parameter under "$name", as row values
// (parameterRowValues). The row loop and the fused filtered count evaluate
// WHERE on it.
func pipelineNodeRow(ctx context.Context, variable string, node *storage.Node) pipelineRow {
	paramRows := parameterRowValues(ctx)
	row := make(pipelineRow, len(paramRows)+1)
	for name, value := range paramRows {
		row[name] = value
	}
	row[variable] = node
	return row
}

func pipelineSingleNodeCountProjection(items []returnItem, variable string) (string, bool) {
	if len(items) != 1 || variable == "" || !countsRows(items[0], variable) {
		return "", false
	}
	return items[0].column(), true
}

// tryStreamPipelineFilteredNodeCount is the fused physical form of the
// pipeline's MATCH -> filter -> count reduction. It consumes the same
// snapshot-aware label stream as the general row operator but reduces each
// qualifying binding immediately, avoiding a node slice and one map-backed
// pipelineRow per match.
func (e *StorageExecutor) tryStreamPipelineFilteredNodeCount(
	ctx context.Context,
	nodePattern nodePatternInfo,
	whereClause string,
	column string,
) (*ExecuteResult, bool, error) {
	if len(nodePattern.labels) == 0 {
		return nil, false, nil
	}
	store := e.getStorage(ctx)
	reader, ok := store.(storage.ProjectedLabelNodeReader)
	if !ok {
		return nil, false, nil
	}

	predicateRow := pipelineNodeRow(ctx, nodePattern.variable, nil)
	predicatePlan := planRowPredicate(whereClause)
	hasWhere := strings.TrimSpace(whereClause) != ""
	whereFilter := func(node *storage.Node) bool {
		predicateRow[nodePattern.variable] = node
		if !hasWhere {
			return true
		}
		if predicatePlan != nil && predicatePlan.complete {
			return e.evaluateRowPredicatePlan(ctx, predicatePlan, predicateRow)
		}
		return e.evaluateRowPredicate(ctx, whereClause, predicateRow)
	}
	hideSystemNodes := shouldHideSystemNodes(store)
	viewport, hasViewport := TemporalViewportFromContext(ctx)
	checker, canCheckViewport := store.(temporalCurrentNodeChecker)
	var count int64
	countNode := func(node *storage.Node, whereApplied bool) error {
		if node == nil || (hideSystemNodes && isSystemNode(node)) {
			return nil
		}
		if !mergeNodeHasLabels(node, nodePattern.labels) || !e.nodeMatchesProps(node, nodePattern.properties) || (!whereApplied && !whereFilter(node)) {
			return nil
		}
		if hasViewport && canCheckViewport {
			visible, visibleErr := checker.IsCurrentTemporalNode(node, viewport.AsOf)
			if visibleErr != nil {
				return visibleErr
			}
			if !visible {
				return nil
			}
		}
		count++
		return nil
	}
	// A lookup an index can narrow is counted from the same seed the row
	// read uses (#820); only otherwise is the label streamed.
	candidates, whereApplied, indexed, err := e.collectPipelineIndexedNodeCandidates(ctx, nodePattern, whereClause, pipelineMatchPhysicalHint{})
	if err != nil {
		return nil, true, err
	}
	if indexed {
		for _, node := range candidates {
			if err := countNode(node, whereApplied); err != nil {
				return nil, true, localizedError(localization.CypherMatchingStorageFailed(err), err)
			}
		}
		return &ExecuteResult{Columns: []string{column}, Rows: [][]interface{}{{count}}, Stats: &QueryStats{}}, true, nil
	}
	projectedProperties := pipelineNodePredicateProperties(nodePattern.variable, whereClause, nodePattern.properties)
	err = reader.StreamNodesByLabelProjected(nodePattern.labels[0], projectedProperties, func(node *storage.Node) error {
		return countNode(node, false)
	})
	if err != nil {
		return nil, true, localizedError(localization.CypherMatchingStorageFailed(err), err)
	}
	return &ExecuteResult{
		Columns: []string{column},
		Rows:    [][]interface{}{{count}},
		Stats:   &QueryStats{},
	}, true, nil
}

func pipelineNodePredicateProperties(variable, expression string, inline map[string]interface{}) []string {
	properties := make([]string, 0, len(inline)+2)
	seen := make(map[string]struct{}, len(inline)+2)
	for property := range inline {
		seen[property] = struct{}{}
		properties = append(properties, property)
	}
	prefix := normalizeProjectionColumnName(variable) + "."
	for _, reference := range semanticExpressionReferences(expression) {
		if reference == normalizeProjectionColumnName(variable) {
			return nil
		}
		if !strings.HasPrefix(reference, prefix) {
			continue
		}
		property := strings.TrimPrefix(reference, prefix)
		if nested := strings.IndexByte(property, '.'); nested >= 0 {
			property = property[:nested]
		}
		if property == "" {
			return nil
		}
		if _, exists := seen[property]; exists {
			continue
		}
		seen[property] = struct{}{}
		properties = append(properties, property)
	}
	sort.Strings(properties)
	return properties
}

func projectPipelineSimpleNodeRead(nodes []*storage.Node, items []returnItem, variable string) *ExecuteResult {
	result := &ExecuteResult{
		Columns: make([]string, len(items)),
		Rows:    make([][]interface{}, 0, len(nodes)),
		Stats:   &QueryStats{},
	}
	for index, item := range items {
		result.Columns[index] = item.column()
	}
	prefix := variable + "."
	for _, node := range nodes {
		row := make([]interface{}, len(items))
		for index, item := range items {
			expression := strings.TrimSpace(item.expr)
			if expression == variable {
				row[index] = node
				continue
			}
			property := normalizeProjectionColumnName(strings.TrimSpace(expression[len(prefix):]))
			row[index] = node.Properties[property]
		}
		result.Rows = append(result.Rows, row)
	}
	return result
}

func pipelineSimpleNodeProjections(items []returnItem, variable string) bool {
	if len(items) == 0 || variable == "" {
		return false
	}
	for _, item := range items {
		expression := strings.TrimSpace(item.expr)
		if expression == variable {
			continue
		}
		prefix := variable + "."
		if !strings.HasPrefix(expression, prefix) {
			return false
		}
		property := strings.TrimSpace(expression[len(prefix):])
		if property == "" || strings.ContainsAny(property, ".()[]{}+-*/%^<>=, ") {
			return false
		}
	}
	return true
}

func pipelineHasClauseKind(clauses []pipelineClause, kind pipelineClauseKind) bool {
	for _, clause := range clauses {
		if clause.kind == kind {
			return true
		}
	}
	return false
}

func normalizePipelineWhitespace(query string) string {
	if !strings.ContainsAny(query, "\t\n\r") {
		return strings.TrimSpace(query)
	}
	var normalized strings.Builder
	normalized.Grow(len(query))
	spacePending := false
	for index := 0; index < len(query); index++ {
		character := query[index]
		if isCypherQuoteByte(character) {
			if spacePending && normalized.Len() > 0 {
				normalized.WriteByte(' ')
			}
			spacePending = false
			end := skipCypherQuotedText(query, index, character)
			normalized.WriteString(query[index:end])
			index = end - 1
			continue
		}
		if isWhitespace(character) {
			spacePending = normalized.Len() > 0
			continue
		}
		if spacePending {
			normalized.WriteByte(' ')
			spacePending = false
		}
		normalized.WriteByte(character)
	}
	return strings.TrimSpace(normalized.String())
}

// ---- clause appliers ----

func (e *StorageExecutor) pipelineApplyOptionalMatch(ctx context.Context, rows []pipelineRow, clause string) ([]pipelineRow, error) {
	if body, repeatable := stripRepeatableElements(strings.TrimSpace(clause[len("OPTIONAL MATCH"):])); repeatable {
		ctx, clause = withRepeatableElements(ctx), "OPTIONAL MATCH "+body
	}
	if shortest, ok, err := e.parseShortestPathMatch(ctx, strings.TrimSpace(clause[len("OPTIONAL MATCH"):])); ok || err != nil {
		if err != nil {
			return nil, err
		}
		return e.pipelineApplyShortestPathMatch(ctx, rows, shortest, true)
	}
	if err := validateBoundPatternNodes(rows, strings.TrimSpace(clause[len("OPTIONAL MATCH"):])); err != nil {
		return nil, err
	}
	optionalClause := splitOptionalMatchClauses(strings.TrimSpace(clause[len("OPTIONAL MATCH"):]))
	if len(optionalClause) != 1 {
		return nil, localizedError(localization.CypherCoreOptionalMatchRequired(), nil)
	}
	nodeVariables := make(map[string]struct{})
	for _, variable := range extractNodeVariables(matchPatternStructure(clause)) {
		nodeVariables[variable] = struct{}{}
	}
	relationshipVariables := make(map[string]struct{})
	for _, variable := range extractRelationshipVariables(matchPatternStructure(clause)) {
		relationshipVariables[variable] = struct{}{}
	}

	// Convert every row, then left-outer-join the clause in one call: each
	// output row starts from a full copy of its input row, in input order.
	traversalRows := make([]traversalOptRow, 0, len(rows))
	for _, row := range rows {
		traversalRow := traversalOptRow{
			nodes: make(map[string]*storage.Node),
			rels:  make(map[string]*storage.Edge),
		}
		for name, value := range row {
			switch entity := value.(type) {
			case *storage.Node:
				traversalRow.nodes[name] = entity
			case *storage.Edge:
				traversalRow.rels[name] = entity
			default:
				if value == nil {
					if _, isNodeBinding := nodeVariables[name]; isNodeBinding {
						traversalRow.nodes[name] = nil
						continue
					}
					if _, isRelationshipBinding := relationshipVariables[name]; isRelationshipBinding {
						traversalRow.rels[name] = nil
						continue
					}
				}
				if traversalRow.values == nil {
					traversalRow.values = make(map[string]interface{})
				}
				traversalRow.values[name] = value
			}
		}
		traversalRows = append(traversalRows, traversalRow)
	}

	expanded, err := e.applyTraversalOptionalClause(ctx, traversalRows, optionalClause[0])
	if err != nil {
		return nil, err
	}
	out := make([]pipelineRow, 0, len(expanded))
	for _, expandedRow := range expanded {
		joined := make(pipelineRow, len(expandedRow.nodes)+len(expandedRow.rels)+len(expandedRow.values))
		for name, node := range expandedRow.nodes {
			if node == nil {
				joined[name] = nil
			} else {
				joined[name] = node
			}
		}
		for name, relationship := range expandedRow.rels {
			if relationship == nil {
				joined[name] = nil
			} else {
				joined[name] = relationship
			}
		}
		for name, value := range expandedRow.values {
			joined[name] = value
		}
		out = append(out, joined)
	}
	return out, nil
}

// pipelineApplyMatch runs MATCH for each current binding row and expands rows
// by the matched combinations. Returns (newRows, true, nil) on success. If a
// MATCH in the middle of a pipeline binds zero rows, it does NOT fail — it
// just zeros out the pipeline (matches Neo4j semantics for chained MATCH).
func (e *StorageExecutor) pipelineApplyMatch(ctx context.Context, rows []pipelineRow, clause string) ([]pipelineRow, bool, error) {
	return e.pipelineApplyMatchWithHint(ctx, rows, clause, pipelineMatchPhysicalHint{limit: -1, earlyLimit: -1})
}

func (e *StorageExecutor) pipelineApplyMatchWithHint(ctx context.Context, rows []pipelineRow, clause string, hint pipelineMatchPhysicalHint) ([]pipelineRow, bool, error) {
	body := pipelineClauseBody(clause, "MATCH")
	if stripped, repeatable := stripRepeatableElements(body); repeatable {
		ctx, body, clause = withRepeatableElements(ctx), stripped, "MATCH "+stripped
	}
	if err := validateBoundPatternNodes(rows, body); err != nil {
		return nil, true, err
	}
	if shortest, ok, err := e.parseShortestPathMatch(ctx, body); ok || err != nil {
		if err != nil {
			return nil, true, err
		}
		expanded, err := e.pipelineApplyShortestPathMatch(ctx, rows, shortest, false)
		return expanded, true, err
	}
	if quantified, ok, err := parseQuantifiedPathMatch(body); ok || err != nil {
		if err != nil {
			return nil, true, err
		}
		expanded, err := e.pipelineApplyQuantifiedPathMatch(ctx, rows, quantified)
		return expanded, true, err
	}
	patternEnd := len(body)
	if where := topLevelKeywordIndex(body, "WHERE"); where >= 0 {
		patternEnd = where
	}
	parts := splitTopLevelComma(body[:patternEnd])
	if len(parts) > 1 && extractPathAssignmentVariable(parts[len(parts)-1]) != "" {
		nodePrefix := true
		for _, part := range parts[:len(parts)-1] {
			if !strings.HasPrefix(strings.TrimSpace(part), "(") || containsRelationshipPattern(part) {
				nodePrefix = false
				break
			}
		}
		if nodePrefix {
			for index, part := range parts {
				if index == len(parts)-1 {
					part += " " + body[patternEnd:]
				}
				expanded, handled, err := e.pipelineApplyMatch(ctx, rows, "MATCH "+part)
				if !handled || err != nil {
					return expanded, handled, err
				}
				rows = expanded
			}
			return rows, true, nil
		}
	}
	if product, supported, err := e.pipelineNodeProductSource(ctx, rows, clause); supported || err != nil {
		if err != nil {
			return nil, true, err
		}
		expanded, resolved := materializePipelineSource(ctx, product)
		if !resolved {
			return nil, true, getExpressionFailure(ctx)
		}
		return expanded, true, nil
	}
	if len(parts) > 1 || len(parts) == 1 && strings.HasPrefix(strings.TrimSpace(parts[0]), "(") &&
		!containsRelationshipPattern(parts[0]) && nodePatternStructure(parts[0]).variable == "" {
		where := ""
		if patternEnd < len(body) {
			where = strings.TrimSpace(body[patternEnd+len("WHERE"):])
		}
		return e.pipelineApplyMatchProduct(ctx, rows, parts, where)
	}
	if expanded, ok, err := e.pipelineApplyBoundRelationshipListMatch(ctx, rows, clause); ok || err != nil {
		return expanded, ok, err
	}
	if expanded, ok, err := e.pipelineApplyInitialTraversalMatch(ctx, rows, clause, hint); ok || err != nil {
		return expanded, ok, err
	}
	if expanded, ok, err := e.pipelineApplyInitialNodeMatch(ctx, rows, clause, hint); ok || err != nil {
		return expanded, ok, err
	}
	if expanded, ok := e.pipelineApplyChainedMatch(ctx, rows, clause); ok {
		return expanded, true, nil
	}

	return nil, false, nil
}

func pipelineBindingValuesEqual(left, right interface{}) bool {
	switch typed := left.(type) {
	case *storage.Node:
		other, ok := right.(*storage.Node)
		return ok && typed != nil && other != nil && typed.Identity() == other.Identity()
	case *storage.Edge:
		other, ok := right.(*storage.Edge)
		return ok && typed != nil && other != nil && typed.Identity() == other.Identity()
	default:
		return reflect.DeepEqual(left, right)
	}
}

func (e *StorageExecutor) pipelineApplyInitialNodeMatch(ctx context.Context, rows []pipelineRow, clause string, hint pipelineMatchPhysicalHint) ([]pipelineRow, bool, error) {
	if len(rows) == 0 {
		return rows, true, nil
	}
	pattern := strings.TrimSpace(clause[len("MATCH"):])
	whereClause := ""
	if whereIndex := topLevelKeywordIndex(pattern, "WHERE"); whereIndex >= 0 {
		whereClause = normalizePipelineWhitespace(pattern[whereIndex+len("WHERE"):])
		pattern = strings.TrimSpace(pattern[:whereIndex])
	}
	if !e.isSingleNodePattern(pattern) {
		return nil, false, nil
	}
	pathVariable := extractPathAssignmentVariable(pattern)
	if pathVariable != "" {
		// p = (n:L): the node pattern is what follows the assignment. Parsed
		// with the assignment, its variable was "p = (n" and it matched no
		// node.
		_, pattern, _ = splitPathAssignment(pattern)
	}
	basePattern := nodePatternStructure(pattern)
	if basePattern.variable == "" {
		return nil, false, nil
	}
	type initialCandidates struct {
		nodes        []*storage.Node
		whereApplied bool
	}
	candidateCache := make(map[string]initialCandidates)
	template := e.pipelineNodeMatchTemplateFor(clause)
	out := make([]pipelineRow, 0, len(rows))
	for _, row := range rows {
		materializedWhere := whereClause
		// The pattern parsed once and its properties evaluated for the row;
		// the text route for a row the template can't evaluate.
		nodePattern, templated, parseErr := template.node(ctx, e, row)
		if parseErr != nil {
			return nil, true, parseErr
		}
		var cacheKey string
		if templated {
			if propsKey, keyed := pipelinePropertiesKey(nodePattern.properties); keyed {
				cacheKey = "\x03" + propsKey + "\x00" + materializedWhere
			}
		} else {
			rowCtx := withValueBindings(ctx, row)
			materializedPattern := pattern
			nodePattern, parseErr = e.parseNodePattern(rowCtx, materializedPattern)
			if parseErr != nil {
				return nil, true, parseErr
			}
			cacheKey = ""
		}
		if bound, exists := row[nodePattern.variable]; exists {
			node, isNode := bound.(*storage.Node)
			if !isNode || node == nil || !e.pipelineNodeMatchesPattern(node, nodePattern) {
				continue
			}
			// The WHERE sees the path too (WHERE length(p) = 0).
			bound := e.pipelineBindZeroLengthPath(row, pathVariable, node)
			if materializedWhere == "" || e.evaluateMatchWhereCondition(ctx, materializedWhere, map[string]interface{}(bound)) {
				out = append(out, bound)
			}
			continue
		}
		candidateHint := hint
		for name := range row {
			if name != nodePattern.variable && referencesVariable(whereClause, name) {
				cacheKey = ""
				candidateHint.earlyLimit = -1
				break
			}
		}
		// A WHERE that reads the path is tested below, where the path is
		// bound; the candidates are collected without it.
		candidateWhere := materializedWhere
		if pathVariable != "" && referencesVariable(whereClause, pathVariable) {
			candidateWhere = ""
			cacheKey = ""
		}
		candidates, cached := candidateCache[cacheKey]
		if cacheKey == "" || !cached {
			var err error
			candidates.nodes, candidates.whereApplied, err = e.collectPipelineInitialNodeCandidates(withValueBindings(ctx, row), nodePattern, candidateWhere, candidateHint)
			if err != nil {
				return nil, true, err
			}
			if cacheKey != "" {
				candidateCache[cacheKey] = candidates
			}
		}
		if candidates.whereApplied {
			materializedWhere = ""
		}
		// The predicate is tested on one row reused for every candidate; a
		// row is built only for a candidate that passes. A predicate with a
		// complete plan is planned once for the row's candidates.
		var probe pipelineRow
		var plan *rowPredicatePlan
		if materializedWhere != "" {
			if planned := planRowPredicate(materializedWhere); planned != nil && planned.complete {
				plan = planned
			}
		}
		for _, node := range candidates.nodes {
			var path interface{}
			if pathVariable != "" {
				path = e.pathToMap(PathResult{Nodes: []*storage.Node{node}})
			}
			if materializedWhere != "" {
				if probe == nil {
					probe = make(pipelineRow, len(row)+2)
					for name, value := range row {
						probe[name] = value
					}
				}
				probe[nodePattern.variable] = node
				if pathVariable != "" {
					probe[pathVariable] = path
				}
				if plan != nil {
					if !e.evaluateRowPredicatePlan(ctx, plan, map[string]interface{}(probe)) {
						continue
					}
				} else if !e.evaluateMatchWhereCondition(ctx, materializedWhere, map[string]interface{}(probe)) {
					continue
				}
			}
			joined := make(pipelineRow, len(row)+2)
			for name, value := range row {
				joined[name] = value
			}
			joined[nodePattern.variable] = node
			if pathVariable != "" {
				joined[pathVariable] = path
			}
			out = append(out, joined)
		}
	}
	return out, true, nil
}

func (e *StorageExecutor) pipelineBindZeroLengthPath(row pipelineRow, variable string, node *storage.Node) pipelineRow {
	if variable == "" {
		return row
	}
	joined := make(pipelineRow, len(row)+1)
	for name, value := range row {
		joined[name] = value
	}
	joined[variable] = e.pathToMap(PathResult{Nodes: []*storage.Node{node}})
	return joined
}

// replaceQualifiedReferenceOutsideQuotes replaces a complete dotted row
// reference without rewriting string literals, longer identifiers, or a
// property access rooted at the reference. replaceIdentifierOutsideQuotes is
// intentionally token-oriented and therefore cannot match a dotted name.
func replaceQualifiedReferenceOutsideQuotes(input, reference, replacement string) string {
	return replaceQualifiedReferenceOutsideQuotesUnless(input, reference, replacement, nil, "")
}

// replaceQualifiedReferenceOutsideQuotesUnless is
// replaceQualifiedReferenceOutsideQuotes that leaves the occurrences that
// read a local variable named variable, the reference's root (locals.keeps).
func replaceQualifiedReferenceOutsideQuotesUnless(input, reference, replacement string, locals *localOccurrences, variable string) string {
	if reference == "" || !strings.Contains(input, reference) {
		return input
	}
	if locals != nil && !locals.binds(variable) {
		locals = nil
	}
	var output strings.Builder
	output.Grow(len(input) + len(replacement))
	for index := 0; index < len(input); {
		if end, quoted := skipCypherLexicalToken(input, index); quoted {
			output.WriteString(input[index:end])
			index = end
			continue
		}
		character := input[index]
		end := index + len(reference)
		if end <= len(input) && input[index:end] == reference &&
			(index == 0 || (!isIdentByte(input[index-1]) && input[index-1] != '.')) &&
			(end == len(input) || (!isIdentByte(input[end]) && input[end] != '.')) &&
			(locals == nil || !locals.keeps(input, variable, index)) {
			output.WriteString(replacement)
			index = end
			continue
		}
		output.WriteByte(character)
		index++
	}
	return output.String()
}

// whereIsSimpleIndexedIn reports whether a WHERE is exactly
// <variable>.<property> IN <parameter or literal list>, the form the IN-list
// plan answers completely.
func (e *StorageExecutor) whereIsSimpleIndexedIn(ctx context.Context, variable, whereClause string, params map[string]interface{}) bool {
	if _, _, ok := e.parseSimpleIndexedInParam(variable, whereClause, params); ok {
		return true
	}
	_, _, ok := e.parseSimpleIndexedInLiteral(ctx, variable, whereClause)
	return ok
}

// collectPipelineInitialNodeCandidates chooses an indexed seed whenever one
// of the shared property-index operators can safely narrow the MATCH, and
// streams the label otherwise. The complete predicate is still evaluated
// after the join, so these operators only affect the physical seed source and
// never the logical result.
type pipelinePrefetchedNodeCandidatesKey struct{}

func (e *StorageExecutor) collectPipelineInitialNodeCandidates(ctx context.Context, nodePattern nodePatternInfo, whereClause string, hint pipelineMatchPhysicalHint) (nodes []*storage.Node, whereApplied bool, err error) {
	if node := e.prefetchedPipelineCandidate(ctx, nodePattern); node != nil {
		return []*storage.Node{node}, false, nil
	}
	// A property equal to null matches no node ({id: null}, nothing equals
	// null): no index seek or label scan can find one.
	for _, value := range nodePattern.properties {
		if value == nil {
			return nil, false, nil
		}
	}
	nodes, whereApplied, used, err := e.collectPipelineIndexedNodeCandidates(ctx, nodePattern, whereClause, hint)
	if err != nil || used {
		return nodes, whereApplied, err
	}
	properties, streamingWhere, projection := e.pipelineLabelScanArguments(ctx, nodePattern, whereClause, hint)
	nodes, err = e.collectNodesWithStreamingProjection(ctx, nodePattern.labels, properties, nodePattern.variable, streamingWhere, hint.earlyLimit, projection)
	if len(nodePattern.properties) > 0 {
		e.markMergeScanFallbackUsed()
	}
	return nodes, false, err
}

// visitPipelineInitialNodeCandidates is collectPipelineInitialNodeCandidates
// for a MATCH whose rows are consumed as they are made (#939): the
// candidates go to visit as the scan reads them, so the scan advances only
// as far as the rows consumed. An indexed seed is read first, as there.
// visit returning storage.ErrIterationStopped ends the scan without error.
func (e *StorageExecutor) visitPipelineInitialNodeCandidates(ctx context.Context, nodePattern nodePatternInfo, hint pipelineMatchPhysicalHint, visit func(*storage.Node) error) error {
	// A streamed MATCH is the statement's first clause, over one row, so
	// no batch prefetch applies to it (prefetchedPipelineCandidate).
	nodes, _, used, err := e.collectPipelineIndexedNodeCandidates(ctx, nodePattern, "", hint)
	if err != nil {
		return err
	}
	if used {
		return visitNodeList(nodes, visit)
	}
	properties, streamingWhere, projection := e.pipelineLabelScanArguments(ctx, nodePattern, "", hint)
	err = e.visitNodesWithStreamingProjection(ctx, nodePattern.labels, properties, nodePattern.variable, streamingWhere, hint.earlyLimit, projection, nil, visit)
	if len(nodePattern.properties) > 0 {
		e.markMergeScanFallbackUsed()
	}
	return err
}

// prefetchedPipelineCandidate is the node a batch prefetch already found for
// a one-label, one-property pattern, or nil.
func (e *StorageExecutor) prefetchedPipelineCandidate(ctx context.Context, nodePattern nodePatternInfo) *storage.Node {
	prefetched, ok := ctx.Value(pipelinePrefetchedNodeCandidatesKey{}).(map[nodeBatchMatchKey]map[string]*storage.Node)
	if !ok || len(nodePattern.labels) != 1 || len(nodePattern.properties) != 1 {
		return nil
	}
	for property, value := range nodePattern.properties {
		key := nodeBatchMatchKey{label: nodePattern.labels[0], prop: property}
		if node := prefetched[key][propEqKeyBatch(value)]; node != nil && e.pipelineNodeMatchesPattern(node, nodePattern) {
			return node
		}
	}
	return nil
}

// pipelineLabelScanArguments are the filters and projection of the label
// (or label-less) scan that seeds a MATCH no index narrows.
func (e *StorageExecutor) pipelineLabelScanArguments(ctx context.Context, nodePattern nodePatternInfo, whereClause string, hint pipelineMatchPhysicalHint) (properties map[string]interface{}, streamingWhere string, projection []string) {
	if hint.earlyLimit > 0 {
		streamingWhere = whereClause
	}
	properties = nodePattern.properties
	if len(nodePattern.labels) == 0 && streamingWhere == "" {
		// The rows are filtered by the WHERE afterwards; its top-level
		// equalities still let a label-less scan skip the nodes that can't
		// match before decoding them (#857).
		properties = e.labellessScanRequiredProperties(ctx, properties, nodePattern.variable, whereClause)
	}
	projection, projected := pipelineLabelScanProjection(ctx, nodePattern, whereClause, hint.readTail)
	if !projected {
		projection = nil
	}
	return properties, streamingWhere, projection
}

// pipelineApplyChainedMatch expands a MATCH against graph bindings already in
// each row. It is the pipeline adapter around the shared traversal operator:
// node and relationship identity conflicts are rejected during the join, and
// WHERE is evaluated once against the complete joined row.
func (e *StorageExecutor) pipelineApplyChainedMatch(ctx context.Context, rows []pipelineRow, clause string) ([]pipelineRow, bool) {
	if len(rows) == 0 || extractPathAssignmentVariable(clause) != "" {
		return nil, false
	}
	patternBindings := make(map[string]struct{})
	for _, variable := range extractNodeVariables(matchPatternStructure(clause)) {
		patternBindings[variable] = struct{}{}
	}
	for _, variable := range extractRelationshipVariables(matchPatternStructure(clause)) {
		patternBindings[variable] = struct{}{}
	}
	hasGraphBinding := false
	for _, row := range rows {
		for name, value := range row {
			if _, referenced := patternBindings[name]; !referenced {
				continue
			}
			switch value.(type) {
			case *storage.Node, *storage.Edge:
				hasGraphBinding = true
			}
		}
	}
	if !hasGraphBinding {
		return nil, false
	}

	pattern := strings.TrimSpace(clause[len("MATCH"):])
	whereClause := ""
	if whereIndex := topLevelKeywordIndex(pattern, "WHERE"); whereIndex >= 0 {
		whereClause = normalizePipelineWhitespace(pattern[whereIndex+len("WHERE"):])
		pattern = strings.TrimSpace(pattern[:whereIndex])
	}
	// executeChainedMatch runs one pattern part. A MATCH of several parts
	// ((a)-->(x), (b)-->(x)) needs its relationships distinct across the
	// parts, which the MATCH executor below enforces.
	if len(splitTopLevelComma(pattern)) != 1 || !containsRelationshipPattern(pattern) {
		return nil, false
	}
	out := make([]pipelineRow, 0, len(rows))
	for _, row := range rows {
		nodes := make(binding)
		relationships := make(relationshipBinding)
		for name, value := range row {
			switch entity := value.(type) {
			case *storage.Node:
				if entity != nil {
					nodes[name] = entity
				}
			case *storage.Edge:
				if entity != nil {
					relationships[name] = entity
				}
			}
		}
		joinedNodes, joinedRelationships := e.executeChainedMatch(withValueBindings(ctx, row), pattern, []binding{nodes}, []relationshipBinding{relationships})
		for index, nodeBindings := range joinedNodes {
			joined := make(pipelineRow, util.SafePreallocSum(len(row), len(nodeBindings)))
			for name, value := range row {
				joined[name] = value
			}
			for name, node := range nodeBindings {
				joined[name] = node
			}
			if index < len(joinedRelationships) {
				for name, relationship := range joinedRelationships[index] {
					joined[name] = relationship
				}
			}
			if whereClause == "" || e.evaluateWithWhereCondition(ctx, whereClause, map[string]interface{}(joined)) {
				out = append(out, joined)
			}
		}
	}
	return out, true
}

func (e *StorageExecutor) pipelineApplyBoundRelationshipListMatch(ctx context.Context, rows []pipelineRow, clause string) ([]pipelineRow, bool, error) {
	pattern := strings.TrimSpace(clause[len("MATCH"):])
	whereClause := ""
	if whereIndex := topLevelKeywordIndex(pattern, "WHERE"); whereIndex >= 0 {
		whereClause = normalizePipelineWhitespace(pattern[whereIndex+len("WHERE"):])
		pattern = strings.TrimSpace(pattern[:whereIndex])
	}
	open, close := firstRelationshipBracket(pattern)
	if open < 0 || close < 0 {
		return nil, false, nil
	}
	// Admission needs the variable and length, not a type list or normalized
	// traversal. The execution reader checks the complete accepted pattern.
	declaration := relationshipDeclarationHead(pattern[open+1 : close])
	if !declaration.hasLength || declaration.variable == "" {
		return nil, false, nil
	}
	for _, row := range rows {
		if _, exists := row[declaration.variable]; !exists {
			return nil, false, nil
		}
	}
	if hasQuantifiedGroup(pattern) || e.isChainedPattern(normalizeAnonymousTraversalRelationships(pattern)) {
		return nil, false, nil
	}

	store := e.getStorage(ctx)
	out := make([]pipelineRow, 0, len(rows))
	for _, row := range rows {

		relationships, ok := pipelineRelationshipList(row[declaration.variable])
		if !ok || len(relationships) == 0 || !repeatableElements(ctx) && relationshipListReusesEdge(relationships) {
			continue
		}
		rowCtx, prepared, err := e.preparePatternRow(ctx, pattern, row)
		if err != nil {
			return nil, true, err
		}
		match := e.parseTraversalPattern(rowCtx, prepared)
		if match == nil {
			return nil, true, getExpressionFailure(ctx)
		}

		for _, endpoints := range traceRelationshipList(relationships, match.Relationship.Direction) {
			startID, startValid := endpoints[0].NodeLookupID(store)
			endID, endValid := endpoints[1].NodeLookupID(store)
			if !startValid || !endValid {
				continue
			}
			start, startErr := e.getQueryNode(store, startID)
			end, endErr := e.getQueryNode(store, endID)
			if startErr != nil || endErr != nil || start == nil || end == nil ||
				!e.pipelineNodeMatchesPattern(start, match.StartNode) || !e.pipelineNodeMatchesPattern(end, match.EndNode) {
				continue
			}
			if bound, exists := row[match.StartNode.variable]; exists {
				boundNode, isNode := bound.(*storage.Node)
				if !isNode || boundNode == nil || boundNode.Identity() != start.Identity() {
					continue
				}
			}
			if bound, exists := row[match.EndNode.variable]; exists {
				boundNode, isNode := bound.(*storage.Node)
				if !isNode || boundNode == nil || boundNode.Identity() != end.Identity() {
					continue
				}
			}
			expanded := make(pipelineRow, util.SafePreallocSum(len(row), 2))
			for name, value := range row {
				expanded[name] = value
			}
			if match.StartNode.variable != "" {
				expanded[match.StartNode.variable] = start
			}
			if match.EndNode.variable != "" {
				expanded[match.EndNode.variable] = end
			}
			if whereClause != "" && !e.evaluateMatchWhereCondition(ctx, whereClause, map[string]interface{}(expanded)) {
				continue
			}
			out = append(out, expanded)
		}
	}
	if failure := getExpressionFailure(ctx); failure != nil {
		return nil, true, failure
	}
	return out, true, nil
}

func pipelineRelationshipList(value interface{}) ([]*storage.Edge, bool) {
	switch relationships := value.(type) {
	case []*storage.Edge:
		return relationships, true
	case []interface{}:
		result := make([]*storage.Edge, len(relationships))
		for index, value := range relationships {
			relationship, ok := value.(*storage.Edge)
			if !ok || relationship == nil {
				return nil, false
			}
			result[index] = relationship
		}
		return result, true
	default:
		return nil, false
	}
}

func relationshipListReusesEdge(relationships []*storage.Edge) bool {
	seen := make(map[storage.EntityIdentity]struct{}, len(relationships))
	for _, relationship := range relationships {
		if relationship == nil {
			return true
		}
		if _, exists := seen[relationship.Identity()]; exists {
			return true
		}
		seen[relationship.Identity()] = struct{}{}
	}
	return false
}

func traceRelationshipList(relationships []*storage.Edge, direction string) [][2]storage.EntityIdentity {
	if len(relationships) == 0 {
		return nil
	}
	starts := [][2]storage.EntityIdentity{{relationships[0].StartIdentity(), relationships[0].EndIdentity()}}
	if direction == "incoming" {
		starts[0] = [2]storage.EntityIdentity{relationships[0].EndIdentity(), relationships[0].StartIdentity()}
	} else if direction == "both" && relationships[0].StartIdentity() != relationships[0].EndIdentity() {
		starts = append(starts, [2]storage.EntityIdentity{relationships[0].EndIdentity(), relationships[0].StartIdentity()})
	}
	for _, relationship := range relationships[1:] {
		next := starts[:0]
		for _, endpoints := range starts {
			switch direction {
			case "outgoing":
				if endpoints[1] == relationship.StartIdentity() {
					next = append(next, [2]storage.EntityIdentity{endpoints[0], relationship.EndIdentity()})
				}
			case "incoming":
				if endpoints[1] == relationship.EndIdentity() {
					next = append(next, [2]storage.EntityIdentity{endpoints[0], relationship.StartIdentity()})
				}
			default:
				if endpoints[1] == relationship.StartIdentity() {
					next = append(next, [2]storage.EntityIdentity{endpoints[0], relationship.EndIdentity()})
				}
				if endpoints[1] == relationship.EndIdentity() && relationship.StartIdentity() != relationship.EndIdentity() {
					next = append(next, [2]storage.EntityIdentity{endpoints[0], relationship.StartIdentity()})
				}
			}
		}
		starts = next
	}
	return starts
}

func (e *StorageExecutor) pipelineNodeMatchesPattern(node *storage.Node, pattern nodePatternInfo) bool {
	if !mergeNodeHasLabels(node, pattern.labels) {
		return false
	}
	return e.nodeMatchesProps(node, pattern.properties)
}

// precededByOptionalKeyword reports whether the clause keyword at position in
// cypher follows the keyword OPTIONAL (OPTIONAL MATCH, OPTIONAL CALL), not a
// variable named optional. It doesn't allocate.
func precededByOptionalKeyword(cypher string, position int) bool {
	start := keywordsBefore(cypher, position, "OPTIONAL")
	return start >= 0 && !clauseKeywordUsedAsName(cypher, start, start+len("OPTIONAL"), "OPTIONAL")
}

// keywordsBefore returns the index of words' first word when the words, in
// order, end s before position as whole words (case-insensitive; whitespace
// before position and between them is skipped), or -1: MERGE's ON before
// CREATE, MATCH or SET, OPTIONAL before MATCH, DETACH before DELETE. A name
// ending in a word (reason, season, friends, autocommit) doesn't end with
// it. It doesn't allocate.
func keywordsBefore(s string, position int, words ...string) int {
	end := position
	for w := len(words) - 1; w >= 0; w-- {
		end = len(strings.TrimRight(s[:end], " \t\n\r"))
		start := end - len(words[w])
		if start < 0 || !equalFoldASCII(s[start:end], words[w]) || start > 0 && isIdentByte(s[start-1]) {
			return -1
		}
		end = start
	}
	return end
}

package cypher

// Pipeline mutation owns row-scoped DELETE, SET, CREATE, MERGE and FOREACH writes.

import (
	"context"
	"errors"
	"fmt"
	"reflect"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
	"github.com/orneryd/nornicdb/pkg/util"
)

// pipelineApplyDelete collects every entity target before validation and
// mutation, preserving statement atomicity while retaining input rows for
// subsequent WITH and RETURN clauses.
func (e *StorageExecutor) pipelineApplyDelete(ctx context.Context, rows []pipelineRow, scope map[string]struct{}, clause string) (*QueryStats, bool, error) {
	targets, detach, ok := deleteClauseTargets(clause)
	if !ok || len(targets) == 0 {
		return nil, false, nil
	}
	for _, expression := range targets {
		if hasTopLevelDeleteLabelQualifier(expression) {
			return nil, true, newSemanticError(
				"Neo.ClientError.Statement.SyntaxError",
				"InvalidDelete",
				"DELETE accepts nodes, relationships, and paths, not labels or relationship types",
			)
		}
		references := expressionFreeVariables(ctx, expression)
		for _, name := range references {
			if _, bound := scope[name]; !bound {
				return nil, true, deleteUndefinedVariableError(name)
			}
		}
		// A row-dependent target is evaluated with its row below, never with
		// an empty planning scope (id(n) is not a constant).
		if len(references) > 0 {
			continue
		}
		if value, evaluated, err := e.evaluateRowValue(strings.TrimSpace(expression), pipelineRow{}); err != nil {
			return nil, true, err
		} else if evaluated && !isDeleteTargetValue(value) {
			return nil, true, newSemanticError(
				"Neo.ClientError.Statement.SyntaxError",
				"InvalidArgumentType",
				fmt.Sprintf("DELETE expression %q does not evaluate to a node, relationship, or path", strings.TrimSpace(expression)),
			)
		}
	}
	projected := &ExecuteResult{Columns: targets, Rows: make([][]interface{}, 0, len(rows))}
	for _, row := range rows {
		if err := ctx.Err(); err != nil {
			return nil, true, err
		}
		values := make([]interface{}, 0, len(targets))
		for _, expression := range targets {
			value, ok, err := e.evaluateRowValue(strings.TrimSpace(expression), row)
			if err != nil {
				return nil, true, err
			}
			if !ok {
				return nil, true, deleteUndefinedVariableError(expression)
			}
			if !isDeleteTargetValue(value) {
				return nil, true, newSemanticError(
					"Neo.ClientError.Statement.TypeError",
					"InvalidArgumentType",
					fmt.Sprintf("DELETE expression %q does not evaluate to a node, relationship, or path", strings.TrimSpace(expression)),
				)
			}
			values = append(values, value)
		}
		projected.Rows = append(projected.Rows, values)
	}
	store := e.getStorage(ctx)
	nodeIDs, edgeIDs := collectDeleteMutationTargets(store, projected)
	// A node relationships still connect is deleted for now and checked at
	// commit, when the transaction can hold it (connectedNodeDeletes); a
	// store without transactions checks here.
	var connected map[storage.NodeID]struct{}
	if !detach {
		if _, deferred := store.(storage.ConnectedNodeDeleter); deferred {
			var err error
			if connected, err = connectedDeleteTargets(store, nodeIDs, edgeIDs); err != nil {
				return nil, true, err
			}
		} else if err := validateNoResidualRelationships(store, nodeIDs, edgeIDs); err != nil {
			return nil, true, err
		}
	}

	// Rows are deleted as they stream, so an entity an earlier row of the
	// statement deleted reaches storage again: it is already gone
	// (storage.ErrNotFound) and counts once, as in Neo4j (#827).
	deletedEdges := make(map[storage.EdgeID]struct{}, len(edgeIDs))
	for _, edgeID := range edgeIDs {
		if err := store.DeleteEdge(edgeID); err != nil {
			if errors.Is(err, storage.ErrNotFound) {
				continue
			}
			return nil, true, err
		}
		deletedEdges[edgeID] = struct{}{}
	}
	if detach {
		for _, nodeID := range nodeIDs {
			incident, err := connectingRelationships(store, nodeID)
			if err != nil {
				return nil, true, err
			}
			for _, edge := range incident {
				deletedEdges[deleteEdgeLookupID(store, edge)] = struct{}{}
			}
		}
	}
	stats := &QueryStats{RelationshipsDeleted: len(deletedEdges)}
	for _, nodeID := range nodeIDs {
		deleteNode := store.DeleteNode
		if _, stillConnected := connected[nodeID]; stillConnected {
			deleteNode = store.(storage.ConnectedNodeDeleter).DeleteConnectedNode
		}
		if err := deleteNode(nodeID); err != nil {
			if errors.Is(err, storage.ErrNotFound) {
				continue
			}
			return nil, true, err
		}
		stats.NodesDeleted++
		e.removeNodeFromSearch(string(nodeID))
	}
	// Incident relationships of detached nodes were deleted with them.
	for edgeID := range deletedEdges {
		e.notifyEdgeMutated(string(edgeID))
	}
	deleted := deletedEntitiesOf(ctx)
	if deleted == nil {
		deleted = &deletedEntities{}
	}
	deleted.addFromStorage(store, nodeIDs, deletedEdges)
	e.replaceDeletedEntityViews(rows, deleted)
	return stats, true, nil
}

// pipelineApplySet mutates entities already bound in each pipeline row. Scalar
// and map bindings are attached as typed context values so assignments such as
// SET target = row retain their original Go/Cypher types.
func (e *StorageExecutor) pipelineApplySet(ctx context.Context, rows []pipelineRow, clause string) (*QueryStats, bool, error) {
	// body may chain SET clauses (SET a SET b); the applicators keep their
	// boundaries, which properties_set depends on (setWrites).
	body := strings.TrimSpace(clause[len("SET"):])
	assignments := splitSetAssignments(collapseChainedSetClauses(body))
	if body == "" || len(assignments) == 0 {
		return nil, false, nil
	}

	store := e.getStorage(ctx)
	stats := &QueryStats{}
	if err := validatePipelineSetAssignments(assignments); err != nil {
		return nil, true, err
	}
	simpleTarget, simpleProperty, simpleExpression, simplePropertyAssignment := pipelineSimplePropertyAssignment(assignments)
	targets := pipelineSetTargetVariables(assignments)
	var runBuffer [4]setRun
	runs := appendSetClauseRuns(runBuffer[:0], body, assignments)
	var stateBuffer [4]setEntityState
	wrapSetError := func(state setEntityState, err error) error {
		return fmt.Errorf("SET %s: %w", pipelineSetOperation(state.variable, assignments), err)
	}
	if len(targets) == 0 {
		return nil, false, nil
	}
	for _, row := range rows {
		if err := ctx.Err(); err != nil {
			return nil, true, err
		}
		for _, target := range targets {
			value, bound := row[target]
			if !bound || value == nil {
				continue
			}
			switch value.(type) {
			case *storage.Node, *storage.Edge:
			default:
				return nil, true, newSemanticError("Neo.ClientError.Statement.TypeError", "InvalidType", fmt.Sprintf("Type mismatch: expected Node or Relationship but was %s", cypherTypeName(value)))
			}
		}
	}
	for _, row := range rows {
		if err := ctx.Err(); err != nil {
			return nil, true, err
		}
		rowCtx, nodes, rels := e.pipelineRowWriteContext(ctx, row)
		evalNodes := nodes
		if simplePropertyAssignment {
			if node := nodes[simpleTarget]; node != nil {
				value, err := e.setPropertyValue(rowCtx, simpleExpression, evalNodes, rels)
				if err != nil {
					return nil, true, err
				}
				before := cloneStringAnyMap(node.Properties)
				written := simplePropertyWrites(node.Properties, simpleProperty, value)
				setNodeProperty(node, simpleProperty, value)
				if err := e.persistSetEntities(store, []setEntityState{{variable: simpleTarget, node: node, properties: before, labels: node.Labels, written: written}}, stats, wrapSetError); err != nil {
					return nil, true, err
				}
				continue
			}
			if relationship := rels[simpleTarget]; relationship != nil {
				value, err := e.setPropertyValue(rowCtx, simpleExpression, evalNodes, rels)
				if err != nil {
					return nil, true, err
				}
				before := cloneStringAnyMap(relationship.Properties)
				written := simplePropertyWrites(relationship.Properties, simpleProperty, value)
				setRelationshipProperty(relationship, simpleProperty, value)
				if err := e.persistSetEntities(store, []setEntityState{{variable: simpleTarget, relationship: relationship, properties: before, written: written}}, stats, wrapSetError); err != nil {
					return nil, true, err
				}
				continue
			}
		}
		states, handled, err := e.applySetRuns(rowCtx, runs, evalNodes, rels, func(variable string) bool {
			_, bound := row[variable]
			return bound
		}, stateBuffer[:0])
		if !handled || err != nil {
			return nil, handled, err
		}
		if err := e.persistSetEntities(store, states, stats, wrapSetError); err != nil {
			return nil, true, err
		}
	}
	return stats, true, nil
}

// pipelineSimplePropertyAssignment recognizes the single x.p = <expr> SET
// (the common case) so pipelineApplySet can skip re-splitting per row.
func pipelineSimplePropertyAssignment(assignments []string) (target, property, expression string, ok bool) {
	if len(assignments) != 1 {
		return "", "", "", false
	}
	target, property, operator, expression := splitSetAssignment(assignments[0])
	if operator != "=" || property == "" || expression == "" {
		return "", "", "", false
	}
	return target, property, expression, true
}

// validatePipelineSetAssignments statically checks SET assignment shapes for
// every route (it runs from validateSetClauseScope before execution): x = v,
// x.p = v, x[key] = v, x += map and x:L1:$(expr) with a bound-identifier
// target, a non-empty right-hand side, a parseable inline map for += and a
// valid label chain (setLabelChainItems). The source type of x = and x += is checked after the
// variables (setSourceTypeError, validateSetClauseScope). Forms are split by
// splitSetAssignment, the splitter the applicators use.
func validatePipelineSetAssignments(assignments []string) error {
	for _, raw := range assignments {
		assignment := strings.TrimSpace(raw)
		if assignment == "" {
			return localizedError(localization.CypherMutationsSetAssignmentRequired(), nil)
		}
		target, _, operator, right := splitSetAssignment(assignment)
		if operator == "" || !isValidIdentifier(target) || right == "" {
			return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "invalid SET assignment: "+assignment)
		}
		if right == "$" {
			return localizedError(localization.CypherMutationsSetAssignmentParameterNameRequired(), nil)
		}
		switch operator {
		case "+=":
			if strings.HasPrefix(right, "{") {
				if _, err := parseSetMergeMapExpressionsStrict(right); err != nil {
					return localizedError(localization.CypherMutationsSetMergeParseFailed(err), err)
				}
			}
		case ":":
			// Static labels are checked here; a $(expr) item's value is read
			// at run time (chainLabelNames).
			if _, err := setLabelChainItems(right); err != nil {
				return err
			}
		}
	}
	return nil
}

func pipelineSetOperation(variable string, assignments []string) string {
	for _, assignment := range assignments {
		assignment = strings.TrimSpace(assignment)
		if strings.HasPrefix(assignment, variable+" +=") || strings.HasPrefix(assignment, variable+"+=") {
			return variable + " +="
		}
		if strings.HasPrefix(assignment, variable+" =") || strings.HasPrefix(assignment, variable+"=") {
			return variable + " ="
		}
		if strings.HasPrefix(assignment, variable+".") {
			return variable + ".property ="
		}
	}
	return variable
}

func addedLabelCount(before, after []string) int {
	known := make(map[string]struct{}, len(before))
	for _, label := range before {
		known[label] = struct{}{}
	}
	added := 0
	for _, label := range after {
		if _, exists := known[label]; !exists {
			added++
		}
	}
	return added
}

// pipelineSetTargetVariables lists the variables a SET clause writes, in
// first-appearance order, using the shared splitSetAssignment.
func pipelineSetTargetVariables(assignments []string) []string {
	seen := make(map[string]struct{})
	var targets []string
	for _, assignment := range assignments {
		target, _, operator, _ := splitSetAssignment(assignment)
		if operator == "" || !isValidIdentifier(target) {
			continue
		}
		if _, exists := seen[target]; exists {
			continue
		}
		seen[target] = struct{}{}
		targets = append(targets, target)
	}
	return targets
}

// changedPropertyCount is the SET counting rule: the number of properties
// added, replaced with a different value or removed between before and after.
func changedPropertyCount(before, after map[string]interface{}) int {
	changed := 0
	for key, value := range after {
		if old, exists := before[key]; !exists || !samePropertyValue(old, value) {
			changed++
		}
	}
	for key := range before {
		if _, exists := after[key]; !exists {
			changed++
		}
	}
	return changed
}

// samePropertyValue is reflect.DeepEqual for stored property values, with the
// common scalar types compared directly.
func samePropertyValue(a, b interface{}) bool {
	switch av := a.(type) {
	case string:
		bv, ok := b.(string)
		return ok && av == bv
	case int64:
		bv, ok := b.(int64)
		return ok && av == bv
	case float64:
		bv, ok := b.(float64)
		return ok && av == bv
	case bool:
		bv, ok := b.(bool)
		return ok && av == bv
	}
	return reflect.DeepEqual(a, b)
}

func (e *StorageExecutor) tryExecutePipelineCreatePlan(ctx context.Context, clauses, originalClauses []pipelineClause) (*ExecuteResult, bool, error) {
	end := 0
	for end < len(clauses) && clauses[end].kind == pipelineClauseCreate {
		end++
	}
	if end == 0 {
		return nil, false, nil
	}
	for index := end; index < len(clauses); index++ {
		if clauses[index].kind != pipelineClauseSet &&
			!(clauses[index].kind == pipelineClauseReturn && index == len(clauses)-1) {
			return nil, false, nil
		}
	}
	initial := pipelineRow{}
	for name, value := range e.fabricRecordBindings {
		initial[name] = value
	}
	for name, value := range valueBindingsFromContext(ctx) {
		initial[name] = value
	}
	bindParameterRow(ctx, initial)
	rows, result, _, err := e.pipelineApplyCreateClauses(ctx, []pipelineRow{initial}, clauses[:end])
	if err != nil {
		return nil, true, err
	}
	for index := end; index < len(clauses); index++ {
		if clauses[index].kind == pipelineClauseSet {
			stats, _, err := e.pipelineApplySet(ctx, rows, clauses[index].text)
			if err != nil {
				return nil, true, err
			}
			addQueryStats(result.Stats, stats)
			continue
		}
		projected, err := e.projectMergeReturn(ctx, rows, originalClauses[index].text)
		if err != nil {
			return nil, true, err
		}
		result.Columns, result.Rows = projected.Columns, projected.Rows
	}
	return result, true, nil
}

type pipelineIndependentCreateBatchKey struct{}

func (e *StorageExecutor) pipelineApplyCreateClauses(ctx context.Context, rows []pipelineRow, clauses []pipelineClause) ([]pipelineRow, *ExecuteResult, bool, error) {
	created := &ExecuteResult{Stats: &QueryStats{}}
	if independent, _ := ctx.Value(pipelineIndependentCreateBatchKey{}).(bool); len(rows) > 1 && (independent || pipelineWriteStretchConflicts(ctx, clauses, nil)) {
		// Evaluate graph-dependent CREATE inputs for every row before any
		// newly created entity becomes visible to those expressions.
		return e.pipelineCreateSource(ctx, pipelineRowsSource(rows), clauses)
	}
	var out []pipelineRow
	for _, row := range rows {
		if err := ctx.Err(); err != nil {
			return nil, nil, false, err
		}
		newRow, err := e.pipelineCreateRow(ctx, row, clauses, created)
		if err != nil {
			return nil, nil, true, err
		}
		out = append(out, newRow)
	}
	return out, created, true, nil
}

func (e *StorageExecutor) pipelineCreateRow(ctx context.Context, row pipelineRow, clauses []pipelineClause, created *ExecuteResult) (pipelineRow, error) {
	plan := acquireCreatePlan()
	defer plan.release()
	newRow, err := e.pipelinePlanCreateRow(ctx, row, clauses, plan)
	if err != nil {
		return nil, err
	}
	if err := e.applyCreatePlan(ctx, plan, created); err != nil {
		return nil, localizedError(localization.CypherInvariantsPipelineCreateFailed(err), err)
	}
	return newRow, nil
}

func (e *StorageExecutor) pipelinePlanCreateRow(ctx context.Context, row pipelineRow, clauses []pipelineClause, plan *createPlan) (pipelineRow, error) {
	nodes, edges := plan.bindings()
	newRow := make(pipelineRow, len(row))
	for name, value := range row {
		newRow[name] = value
		switch typed := value.(type) {
		case *storage.Node:
			if typed != nil {
				nodes[name] = typed
			}
		case *storage.Edge:
			if typed != nil {
				edges[name] = typed
			}
		}
	}
	for _, clause := range clauses {
		rowCtx := withValueBindings(ctx, newRow)
		pattern := pipelineClauseBody(clause.text, "CREATE")
		dynamic := hasDynamicToken(pattern)
		if dynamic {
			// Labels and types whose values depend on the row.
			resolved, err := e.resolveRowDynamicTokens(rowCtx, pattern, nodes, edges)
			if err != nil {
				return nil, err
			}
			pattern = resolved
		}
		var paths map[string]PathResult
		planned := false
		if !dynamic {
			// Parse-once template: the clause's pattern structure is fixed
			// per statement; only the property expressions are per-row. The
			// template is parsed from the clause text, so a clause with
			// row-dependent dynamic labels or types keeps the general route,
			// which plans the resolved pattern instead.
			if template := e.pipelineCreateTemplateFor(clause.text); template != nil && template.usable {
				var err error
				paths, planned, err = template.plan(ctx, e, newRow, nodes, edges, plan)
				if err != nil {
					if failure := getExpressionFailure(rowCtx); failure != nil {
						return nil, failure
					}
					return nil, localizedError(localization.CypherInvariantsPipelineCreateFailed(err), err)
				}
			}
		}
		if !planned {
			var err error
			paths, err = e.planCreatePatterns(rowCtx, pattern, nodes, edges, plan)
			if err != nil {
				if failure := getExpressionFailure(rowCtx); failure != nil {
					return nil, failure
				}
				return nil, localizedError(localization.CypherInvariantsPipelineCreateFailed(err), err)
			}
		}
		for name, node := range nodes {
			newRow[name] = node
		}
		for name, edge := range edges {
			newRow[name] = edge
		}
		for name, path := range paths {
			newRow[name] = e.pathToMap(path)
		}
	}
	return newRow, nil
}

// pipelineApplyMerge executes one MERGE per input row while retaining the row
// bindings for subsequent clauses. This preserves Cypher's row-at-a-time
// mutation semantics after UNWIND/WITH without duplicating MERGE behavior.
func (e *StorageExecutor) pipelineApplyMerge(ctx context.Context, rows []pipelineRow, clause string) ([]pipelineRow, *QueryStats, error) {
	if body := strings.TrimSpace(clause); hasDynamicToken(body) && startsWithKeywordFold(body, "MERGE") {
		if actions := splitMergeClauseActions(strings.TrimSpace(body[len("MERGE"):])); hasDynamicToken(actions.pattern) {
			pattern := actions.pattern
			stats := &QueryStats{}
			out := make([]pipelineRow, 0, len(rows))
			at := strings.Index(clause, pattern)
			for _, row := range rows {
				rowCtx, nodes, rels := e.pipelineRowWriteContext(ctx, row)
				resolved, err := e.resolveRowDynamicTokens(rowCtx, pattern, nodes, rels)
				if err != nil {
					return nil, nil, err
				}
				produced, rowStats, err := e.pipelineApplyMerge(ctx, []pipelineRow{row}, clause[:at]+resolved+clause[at+len(pattern):])
				if err != nil {
					return nil, nil, err
				}
				addQueryStats(stats, rowStats)
				out = append(out, produced...)
			}
			return out, stats, nil
		}
	}
	stats := &QueryStats{}
	out := make([]pipelineRow, 0, len(rows))
	// The relationship lookups of this MERGE over its rows share one read
	// per endpoint pair (relationshipMergeIdentityCache); one row looks up
	// directly.
	var identities *relationshipMergeIdentityCache
	if len(rows) > 1 {
		identities = newRelationshipMergeIdentityCache()
	}
	template := e.pipelineMergeTemplateFor(clause)
	// The clause's pattern and actions (each action clause a SET of its own,
	// in order) are the same for every row.
	clauseBody := strings.TrimSpace(clause)
	isMerge := startsWithKeywordFold(clauseBody, "MERGE")
	var clausePattern, onCreateSet, onMatchSet string
	multiRelationship := false
	if isMerge {
		parts := splitMergeClauseActions(strings.TrimSpace(clauseBody[len("MERGE"):]))
		clausePattern, onCreateSet, onMatchSet = parts.pattern, parts.onCreate.setText(), parts.onMatch.setText()
		multiRelationship = e.isMultiRelationshipPattern(clausePattern)
	}
	// Templates contain syntax only; row values stay in each prepared context.
	// Reuse the statement template until preparation changes that syntax.
	preparedTemplate, templatePattern := template, clausePattern
	for _, row := range rows {
		if err := ctx.Err(); err != nil {
			return nil, nil, err
		}
		ctx := withValueBindings(ctx, row)
		preparedPattern := clausePattern
		rowTemplate := template
		if isMerge && (!containsRelationshipPattern(clausePattern) || template.usable && pipelineBoundMergeEndpoints(template, row)) {
			var prepareErr error
			ctx, preparedPattern, prepareErr = e.preparePatternRow(ctx, clausePattern, row)
			if prepareErr != nil {
				return nil, nil, prepareErr
			}
			if template.usable {
				if preparedPattern != templatePattern {
					preparedTemplate = e.pipelineMergeTemplateFor("MERGE " + preparedPattern)
					templatePattern = preparedPattern
				}
				rowTemplate = preparedTemplate
			}
		}
		// The clause parsed once: a row whose relationship already exists
		// is its matches, without rendering and parsing the row's text.
		pattern, startNode, endNode, templated, templateErr := rowTemplate.pattern(ctx, e, row)
		if templateErr != nil {
			return nil, nil, templateErr
		}
		if templated {
			matches, findErr := findParsedMergeRelationships(e.getStorage(ctx), identities, pattern, startNode, endNode)
			if findErr != nil {
				return nil, nil, findErr
			}
			if len(matches) > 0 {
				out = append(out, e.mergeRelationshipRows(row, nil, nil, pattern, startNode, endNode, matches)...)
				continue
			}
		}
		nodeContext := make(map[string]*storage.Node)
		relContext := make(map[string]*storage.Edge)
		for name, value := range row {
			switch typed := value.(type) {
			case *storage.Node:
				nodeContext[name] = typed
			case *storage.Edge:
				relContext[name] = typed
			}
		}
		var relationshipPattern *mergeRelationshipPattern
		var nodePathVariable string
		var nodePathBinding string
		mergePattern := clauseBody
		if isMerge {
			mergePattern = preparedPattern
			// A whole-path MERGE: the pattern's matches with the row's
			// bindings, every one a row, or the whole pattern created,
			// reusing the bound nodes, as in Neo4j. Every relationship
			// pattern with an endpoint the row doesn't bind takes it (#509:
			// two matching paths are two rows); one with both endpoints
			// bound keeps the relationship route below.
			mergeWholePath := func() error {
				produced, pathStats, created, err := e.pipelineMergePath(ctx, row, mergePattern, nodeContext, relContext)
				if err != nil {
					return err
				}
				addQueryStats(stats, pathStats)
				actions := onMatchSet
				if created {
					actions = onCreateSet
				}
				if err := e.applyMergeActions(ctx, produced, actions, stats); err != nil {
					return err
				}
				// It may have written between any pair of nodes.
				identities.reset()
				out = append(out, produced...)
				return nil
			}
			if multiRelationship {
				if err := mergeWholePath(); err != nil {
					return nil, nil, err
				}
				continue
			}
			if open, _ := firstRelationshipBracket(mergePattern); open >= 0 {
				shape, shapeErr := e.parseMergeRelationshipShape(mergePattern)
				if shapeErr != nil {
					return nil, nil, shapeErr
				}
				start := nodePatternStructure(shape.startContent).variable
				end := nodePatternStructure(shape.endContent).variable
				for _, variable := range [...]string{start, end} {
					if missingRelationshipEndpoint(row, variable) {
						return nil, nil, relationshipEndpointMissingError(variable)
					}
				}
				if nodeContext[start] == nil || nodeContext[end] == nil {
					if err := mergeWholePath(); err != nil {
						return nil, nil, err
					}
					continue
				}
				var parseErr error
				ctx, mergePattern, parseErr = e.preparePatternRow(ctx, mergePattern, row)
				if parseErr != nil {
					return nil, nil, parseErr
				}
				relationshipPattern, parseErr = e.parseMergeRelationshipPattern(ctx, mergePattern, nodeContext, relContext)
				if parseErr != nil {
					return nil, nil, parseErr
				}
			} else if nodePathVariable = extractPathAssignmentVariable(mergePattern); nodePathVariable != "" {
				mergePattern = strings.TrimSpace(mergePattern[strings.Index(mergePattern, "=")+1:])
				nodePathBinding = e.extractVarName(mergePattern)
			}
		}
		if relationshipPattern == nil {
			nodePattern := mergePattern
			variable, labels, properties, parseErr := e.parseMergeNodePattern(ctx, nodePattern, nodeContext, relContext)
			if parseErr == nil {
				_, alreadyBound := nodeContext[variable]
				if variable == "" || !alreadyBound {
					if err := prepareMergeKeys(ctx, e.getStorage(ctx), labels, properties, mergeNodeWritesFromContext(ctx).writes(variable)); err != nil {
						return nil, nil, err
					}
					matches, scanned, findErr := e.findMergeNodesScanned(e.getStorage(ctx), labels, properties)
					if findErr != nil {
						return nil, nil, findErr
					}
					if len(matches) > 0 {
						matchedRows := make([]pipelineRow, 0, len(matches))
						for _, node := range matches {
							expanded := make(pipelineRow, util.SafePreallocSum(len(row), 2))
							for name, value := range row {
								expanded[name] = value
							}
							if variable != "" {
								expanded[variable] = node
							}
							if nodePathVariable != "" {
								path := PathResult{Nodes: []*storage.Node{node}}
								expanded[nodePathVariable] = e.pathToMap(path)
							}
							matchedRows = append(matchedRows, expanded)
						}
						// ON MATCH SET applies to every matched row, through
						// the shared SET applicator.
						if err := e.applyMergeActions(ctx, matchedRows, onMatchSet, stats); err != nil {
							return nil, nil, err
						}
						out = append(out, matchedRows...)
						continue
					}
					if scanned {
						ctx = withMergeNodeAbsent(ctx)
					}
				}
			}
		}
		if relationshipPattern != nil {
			// Bound endpoints: every existing relationship that matches the
			// pattern is a row, and ON MATCH SET applies to each, as in
			// Neo4j. One lookup decides; only a pattern with no match reaches
			// the create path below.
			startNode := nodeContext[relationshipPattern.startVariable]
			endNode := nodeContext[relationshipPattern.endVariable]
			if startNode != nil && endNode != nil {
				matches, findErr := findParsedMergeRelationships(e.getStorage(ctx), identities, relationshipPattern, startNode, endNode)
				if findErr != nil {
					return nil, nil, findErr
				}
				if len(matches) > 0 {
					matchedRows := e.mergeRelationshipRows(row, nodeContext, relContext, relationshipPattern, startNode, endNode, matches)
					if onMatchSet != "" {
						// It can change identity values.
						identities.reset()
					}
					if err := e.applyMergeActions(ctx, matchedRows, onMatchSet, stats); err != nil {
						return nil, nil, err
					}
					out = append(out, matchedRows...)
					continue
				}
			}
		}
		boundEndpoints := relationshipPattern != nil &&
			nodeContext[relationshipPattern.startVariable] != nil && nodeContext[relationshipPattern.endVariable] != nil
		merged, err := e.executeMergeWithContext(ctx, "MERGE "+mergePattern, nodeContext, relContext)
		if err != nil {
			return nil, nil, err
		}
		if relationshipPattern != nil && !boundEndpoints {
			// The MERGE bound or created endpoints itself: it may have
			// written between any pair.
			identities.reset()
		}
		patternCreated := false
		patternNoOp := false
		if merged != nil && merged.Stats != nil {
			addQueryStats(stats, merged.Stats)
			patternCreated = merged.Stats.NodesCreated > 0 || merged.Stats.RelationshipsCreated > 0
			patternNoOp = merged.Stats.relationshipMergeNoOp
		}
		// The MERGE created its pattern (ON CREATE) or found it (ON MATCH).
		actions := onMatchSet
		actionStats := stats
		if patternCreated {
			actions = onCreateSet
		} else if patternNoOp {
			// Storage found a hidden predecessor, so ON CREATE completes the
			// transaction-visible candidate before the commit owner decides
			// semantic identity. The candidate stages no publication, and an
			// identical final image reports no CREATE/SET work; a different
			// image makes commit return a permanent client error.
			actions = onCreateSet
			actionStats = &QueryStats{}
		}
		var produced []pipelineRow
		newRow := make(pipelineRow, util.SafePreallocSum(len(row), len(nodeContext), len(relContext)))
		for name, value := range row {
			newRow[name] = value
		}
		for name, node := range nodeContext {
			newRow[name] = node
		}
		for name, relationship := range relContext {
			newRow[name] = relationship
		}
		if nodePathVariable != "" {
			if node := nodeContext[nodePathBinding]; node != nil {
				path := PathResult{Nodes: []*storage.Node{node}}
				newRow[nodePathVariable] = e.pathToMap(path)
			}
		}
		if relationshipPattern != nil {
			// The create path made the relationship (and any endpoint the
			// pattern didn't bind): its row carries it.
			startNode := nodeContext[relationshipPattern.startVariable]
			endNode := nodeContext[relationshipPattern.endVariable]
			if startNode != nil && endNode != nil {
				created := relContext[relationshipPattern.relVariable]
				var matches []*storage.Edge
				if created != nil && relationshipPattern.relVariable != "" {
					matches = []*storage.Edge{created}
					if patternNoOp {
						// A hidden candidate is a binding for this MERGE row only,
						// never a visible relationship match for a later row.
						identities.reset()
					} else if onCreateSet == "" {
						identities.created(created)
					} else {
						identities.reset()
					}
				} else {
					identities.reset()
					found, findErr := findParsedMergeRelationships(e.getStorage(ctx), identities, relationshipPattern, startNode, endNode)
					if findErr != nil {
						return nil, nil, findErr
					}
					matches = found
				}
				if len(matches) > 0 {
					produced = e.mergeRelationshipRows(newRow, nil, nil, relationshipPattern, startNode, endNode, matches)
				}
			}
		}
		if produced == nil {
			produced = []pipelineRow{newRow}
		}
		if actions != "" {
			// It can change identity values.
			identities.reset()
		}
		if err := e.applyMergeActions(ctx, produced, actions, actionStats); err != nil {
			return nil, nil, err
		}
		out = append(out, produced...)
	}
	return out, stats, nil
}

// mergeRelationshipRows returns one row per relationship a MERGE matched or
// created: row with the MERGE's node and relationship bindings, the pattern's
// relationship variable and its path variable.
func (e *StorageExecutor) mergeRelationshipRows(row pipelineRow, nodeContext map[string]*storage.Node, relContext map[string]*storage.Edge, pattern *mergeRelationshipPattern, startNode, endNode *storage.Node, relationships []*storage.Edge) []pipelineRow {
	rows := make([]pipelineRow, 0, len(relationships))
	for _, relationship := range relationships {
		expanded := make(pipelineRow, util.SafePreallocSum(len(row), len(nodeContext), len(relContext), 2))
		for name, value := range row {
			expanded[name] = value
		}
		for name, node := range nodeContext {
			expanded[name] = node
		}
		for name, edge := range relContext {
			expanded[name] = edge
		}
		if pattern.relVariable != "" {
			expanded[pattern.relVariable] = relationship
		}
		if pattern.pathVariable != "" {
			path := PathResult{Nodes: []*storage.Node{startNode, endNode}, Relationships: []*storage.Edge{relationship}, Length: 1}
			expanded[pattern.pathVariable] = e.pathToMap(path)
		}
		rows = append(rows, expanded)
	}
	return rows
}

// containsRemoveClauseAnywhere reports a REMOVE keyword outside strings,
// including one nested in a FOREACH body or subquery.
func containsRemoveClauseAnywhere(cypher string) bool {
	opts := defaultKeywordScanOpts()
	opts.SkipParens = false
	opts.SkipBrackets = false
	return keywordIndexFrom(cypher, "REMOVE", 0, opts) >= 0
}

func (e *StorageExecutor) pipelineApplyForeach(ctx context.Context, rows []pipelineRow, clause pipelineClause) (*QueryStats, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	body := queryBodyFromSyntax(clause.syntax)
	if body.status != queryBodyRead || body.foreach == nil {
		return nil, invalidForeachError()
	}
	update := body.foreach
	stats := &QueryStats{}
	for _, row := range rows {
		items, ok := e.evaluateListForPipelineWithContext(ctx, update.listExpression, row)
		if !ok {
			return nil, invalidForeachError()
		}
		for _, item := range items {
			// The loop is a mutation boundary: a cancellation between items
			// stops the remaining writes (the MERGE branch probes too).
			if err := ctx.Err(); err != nil {
				return nil, err
			}
			child := make(pipelineRow, len(row)+1)
			for name, value := range row {
				child[name] = value
			}
			child[update.variable] = item
			scope := make(map[string]struct{}, len(child))
			for name := range child {
				scope[name] = struct{}{}
			}
			result, handled, err := e.runPipelineClauseRows(ctx, []pipelineRow{child}, scope, update.updates, update.updates, nil)
			if err != nil {
				return nil, err
			}
			if !handled {
				return nil, invalidForeachError()
			}
			addQueryStats(stats, result.Stats)
		}
	}
	return stats, nil
}

// setSourceTypeError rejects SET x = <source> and SET x += <source>
// (property "") whose source operand is proven to be no map, node or
// relationship. The shared clause validator passes the source's operand in
// the statement's one type scope (staticSetItemsTokenError), so a CALL,
// UNION or RETURN * result reaches it. Neo4j 5.26 types it before the
// statement runs ("Type mismatch: expected Map, Node or Relationship"). A
// source of unknown type, null included, is checked when the SET runs
// (setPropertyMapValue), as in Neo4j (#907).
func setSourceTypeError(property, operator string, source staticOperand) error {
	if property != "" || (operator != "=" && operator != "+=") {
		return nil
	}
	// The operand owner decides: a union is rejected only when none of its
	// alternatives is a map, node or relationship.
	if !source.excludes(isMapNodeOrRelationshipTypeName) {
		return nil
	}
	return typeNameMismatchError("Map, Node or Relationship", source.display)
}

// setClauseSourceTypeError is setSourceTypeError for the assignments of a
// SET clause with the statement's parameter values (the per-execution
// check, validateStaticPropertyAccessParameters). Literal sources are checked
// with each item's scope check (validateSetClauseScope), in item order, as
// Neo4j reports them.
func setClauseSourceTypeError(ctx context.Context, clause string, types map[string]string, params map[string]interface{}) error {
	body := strings.TrimSpace(clause)
	if startsWithKeywordFold(body, "SET") {
		body = body[len("SET"):]
	}
	for _, assignment := range splitSetAssignments(body) {
		_, property, operator, source := splitSetAssignment(assignment)
		if staticLiteralTypeName(ctx, source) != "" {
			continue
		}
		// Parameter values are the run's facts (the per-execution check).
		var operand staticOperand
		if typeName := propertyAccessExpressionType(ctx, source, types, params); typeName != "" {
			operand = typedOperand(typeName).proved()
		}
		if err := setSourceTypeError(property, operator, operand); err != nil {
			return err
		}
	}
	return nil
}

package cypher

import (
	"context"
	"strings"
)

// pipelineProcedureCallsAreClauses reports whether every CALL in the statement
// is a top-level procedure call. Unknown procedures are admitted so execution
// can report their classified lookup error even when no rows reach the call.
func pipelineProcedureCallsAreClauses(ctx context.Context, cypher string) bool {
	if !containsFold(cypher, "CALL") || hasCallSubqueryPattern(ctx, cypher) {
		return false
	}
	ensureBuiltInProceduresRegistered()
	for _, position := range findAllTopLevelPipelineKeywordPositions(cypher, "CALL") {
		procedure, found := globalProcedureRegistry.Get(extractProcedureName(ctx, cypher[position:]))
		if found && procedure.Spec.Mode != ProcedureModeRead && !procedure.Spec.writes() && procedure.Spec.Mode != ProcedureModeDBMS && !(procedure.User && procedure.Spec.Mode == "") {
			return false
		}
	}
	topLevel := len(findAllTopLevelPipelineKeywordPositions(cypher, "CALL"))
	total := 0
	for offset := 0; offset < len(cypher); {
		index := findKeywordIndex(cypher[offset:], "CALL")
		if index < 0 {
			break
		}
		total++
		offset += index + len("CALL")
	}
	return topLevel > 0 && topLevel == total
}

// pipelineApplyProcedureCall runs CALL proc(args) YIELD items [WHERE p] for
// every input row, as Neo4j does: the arguments are evaluated in the row's
// scope, each yielded record extends a copy of the row with the yielded
// (aliased) columns, and the YIELD's WHERE filters the extended rows, so it
// can compare yielded columns with the row's variables. A row whose call
// yields nothing produces no row. The clauses after the call then see every
// row at once, so aggregation, ORDER BY and SKIP / LIMIT apply to all of
// them.
//
// Void calls without YIELD preserve input rows; non-void calls require YIELD.
// Explicit arguments are evaluated as typed values in the canonical invocation.
func (e *StorageExecutor) pipelineApplyProcedureCall(ctx context.Context, rows []pipelineRow, clause string, totals *QueryStats) ([]pipelineRow, []string, bool, error) {
	yieldIndex := findKeywordIndexInContext(clause, "YIELD")
	invocation := strings.TrimSpace(clause)
	if yieldIndex >= 0 {
		invocation = strings.TrimSpace(clause[:yieldIndex])
	}
	procedure, found := globalProcedureRegistry.Get(extractProcedureName(ctx, invocation))
	if !found {
		return nil, nil, true, newSemanticError("Neo.ClientError.Procedure.ProcedureNotFound", "ProcedureNotFound", "There is no procedure with the name "+extractProcedureName(ctx, invocation)+" registered")
	}
	if yieldIndex < 0 && len(procedure.Spec.Returns) > 0 {
		return nil, nil, true, newSemanticError("Neo.ClientError.Statement.SyntaxError", "InvalidSyntax", "procedure calls inside a query must name results explicitly using YIELD")
	}
	if err := validateProcedureCallArguments(invocation); err != nil {
		return nil, nil, true, err
	}
	yieldBody := ""
	if yieldIndex >= 0 {
		yieldBody = strings.TrimSpace(clause[yieldIndex+len("YIELD"):])
	}
	where := ""
	if whereIndex := topLevelKeywordIndex(yieldBody, "WHERE"); whereIndex >= 0 {
		where = strings.TrimSpace(yieldBody[whereIndex+len("WHERE"):])
		yieldBody = strings.TrimSpace(yieldBody[:whereIndex])
	}
	yieldText := ""
	if yieldIndex >= 0 {
		yieldText = "YIELD " + yieldBody
	}

	arguments := explicitProcedureArgumentTexts(ctx, invocation)
	if arguments != nil {
		if err := validateProcedureArgumentCount(procedure.Spec, len(arguments)); err != nil {
			return nil, nil, true, err
		}
	}
	rowDependent := false
	for _, argument := range arguments {
		if len(rows) > 0 && argumentUsesRowVariable(argument, rows[0]) {
			rowDependent = true
			break
		}
	}

	var yielded []string
	if yieldIndex >= 0 {
		yield := parseYieldClause(ctx, clause)
		if err := validateProcedureYieldBindings(yield, true); err != nil {
			return nil, nil, true, err
		}
		if err := e.validateYieldModifiers(ctx, yield, true); err != nil {
			return nil, nil, true, err
		}
		for _, item := range yield.items {
			yielded = append(yielded, item.column())
		}
		if len(procedure.Spec.Returns) > 0 {
			columns := make([]string, len(procedure.Spec.Returns))
			for index, column := range procedure.Spec.Returns {
				columns[index] = column.Name
			}
			if _, err := e.applyYieldFilter(ctx, &ExecuteResult{Columns: columns, Rows: [][]interface{}{}}, &yieldClause{items: yield.items}); err != nil {
				return nil, nil, true, err
			}
		}
	}
	var shared *ExecuteResult
	out := make([]pipelineRow, 0, len(rows))
	for _, row := range rows {
		if err := ctx.Err(); err != nil {
			return nil, nil, true, err
		}
		result := shared
		if result == nil {
			var err error
			result, err = e.executeProcedureCall(withValueBindings(ctx, row), invocation+" "+yieldText, true)
			if err != nil {
				return nil, nil, true, err
			}
			// Count executions, not yielded rows or shared result reuse.
			if result != nil {
				addQueryStats(totals, result.Stats)
			}
			if !rowDependent && procedure.Spec.Mode == ProcedureModeRead {
				shared = result
			}
		}
		if yieldIndex < 0 {
			out = append(out, row)
			continue
		}
		if result == nil {
			continue
		}
		if yielded == nil {
			yielded = append([]string(nil), result.Columns...)
		}
		extended := make([]pipelineRow, 0, len(result.Rows))
		for _, record := range result.Rows {
			next := make(pipelineRow, len(row)+len(result.Columns))
			for key, value := range row {
				next[key] = value
			}
			for i, column := range result.Columns {
				if i < len(record) {
					next[column] = record[i]
				}
			}
			extended = append(extended, next)
		}
		if where != "" {
			extended = e.filterPipelineRows(ctx, extended, where)
		}
		out = append(out, extended...)
	}
	return out, yielded, true, nil
}

// argumentUsesRowVariable reports whether a procedure argument refers to a
// variable bound in the row (parameters are already substituted).
func argumentUsesRowVariable(argument string, row pipelineRow) bool {
	for _, reference := range semanticExpressionReferences(argument) {
		base := strings.SplitN(reference, ".", 2)[0]
		if _, bound := row[base]; bound {
			return true
		}
	}
	return false
}

package cypher

import (
	"context"
	"strings"
)

func cypherGrammarVersion(query string) string {
	version := "5"
	rest := strings.TrimSpace(query)
	for rest != "" {
		if startsWithKeywordFold(rest, "EXPLAIN") || startsWithKeywordFold(rest, "PROFILE") {
			rest = strings.TrimSpace(rest[len("EXPLAIN"):])
			continue
		}
		if !startsWithKeywordFold(rest, "CYPHER") {
			break
		}
		rest = strings.TrimSpace(rest[len("CYPHER"):])
		if len(rest) > 0 && isDigitByte(rest[0]) {
			end := 0
			for end < len(rest) && isDigitByte(rest[end]) {
				end++
			}
			version = rest[:end]
			rest = strings.TrimSpace(rest[end:])
		}
		for rest != "" && !startsWithClauseKeyword(rest) {
			end := strings.IndexAny(rest, " \t\r\n")
			if end < 0 {
				rest = ""
				break
			}
			rest = strings.TrimSpace(rest[end:])
		}
	}
	return version
}

func usesSharedGrammarClauses(ctx context.Context, query string) bool {
	if isSchemaCommandStatement(query) {
		return false
	}
	clauses, ok := pipelineClausesFor(ctx, query)
	if !ok {
		return false
	}
	for _, clause := range clauses {
		if clause.kind == pipelineClauseLet || clause.kind == pipelineClauseFilter ||
			clause.kind == pipelineClauseUnwind && startsWithKeywordFold(clause.text, "FOR") {
			return true
		}
		if clause.kind == pipelineClauseCallSubquery {
			start, end := strings.Index(clause.text, "{"), strings.LastIndex(clause.text, "}")
			if start >= 0 && end > start && usesSharedGrammarClauses(ctx, clause.text[start+1:end]) {
				return true
			}
		}
	}
	return false
}

func parsePipelineIteration(clause string) (expression, alias string, ok bool) {
	if !startsWithKeywordFold(strings.TrimSpace(clause), "FOR") {
		return splitUnwindBody(pipelineClauseBody(clause, "UNWIND"))
	}
	body := pipelineClauseBody(clause, "FOR")
	name, end, found := scanSymbolicName(body, 0)
	if !found {
		return "", "", false
	}
	rest := strings.TrimSpace(body[end:])
	if !startsWithKeywordFold(rest, "IN") {
		return "", "", false
	}
	expression = strings.TrimSpace(rest[len("IN"):])
	return expression, name, expression != ""
}

func parsePipelineLet(clause string) ([]pipelineRowProjection, error) {
	body := pipelineClauseBody(clause, "LET")
	var projections []pipelineRowProjection
	for _, item := range splitTopLevelComma(body) {
		item = strings.TrimSpace(item)
		name, end, found := scanSymbolicName(item, 0)
		if !found {
			return nil, sharedClauseSyntaxError("LET requires a variable = expression binding")
		}
		rest := strings.TrimSpace(item[end:])
		if len(rest) < 2 || rest[0] != '=' {
			return nil, sharedClauseSyntaxError("LET requires a variable = expression binding")
		}
		expression := strings.TrimSpace(rest[1:])
		if expression == "" || pipelineExpressionContainsAggregate(expression) {
			return nil, sharedClauseSyntaxError("LET requires a non-aggregate expression")
		}
		projections = append(projections, pipelineRowProjection{expression: expression, alias: normalizeProjectionColumnName(name)})
	}
	if len(projections) == 0 {
		return nil, sharedClauseSyntaxError("LET requires at least one binding")
	}
	return projections, nil
}

func pipelineFilterExpression(clause string) string {
	body := pipelineClauseBody(clause, "FILTER")
	if startsWithKeywordFold(body, "WHERE") {
		body = strings.TrimSpace(body[len("WHERE"):])
	}
	return body
}

func sharedClauseSyntaxError(message string) error {
	return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", message)
}

func bindPipelineLet(scope *semanticBindingScope, clause string) error {
	projections, err := parsePipelineLet(clause)
	if err != nil {
		return err
	}
	for _, projection := range projections {
		scope.bind(projection.alias)
	}
	return nil
}

func (e *StorageExecutor) validateSharedClause(ctx context.Context, scope matchSemanticScope, values map[string]string, clause pipelineClause, cypher25 bool) error {
	input := staticTypeScope{kinds: scope, values: values, complete: true, cypher25: cypher25}
	if clause.kind == pipelineClauseFilter {
		expression := pipelineFilterExpression(clause.text)
		if expression == "" {
			return sharedClauseSyntaxError("FILTER requires a predicate")
		}
		if pipelineExpressionContainsAggregate(expression) {
			return sharedClauseSyntaxError("Aggregation is not allowed in FILTER")
		}
		if err := undefinedExpressionVariable(ctx, scope, expression); err != nil {
			return err
		}
		return e.validateStaticClauseTypes(ctx, clause, input)
	}
	projections, err := parsePipelineLet(clause.text)
	if err != nil {
		return err
	}
	for _, projection := range projections {
		if err := projectionItemTermError(projection.expression); err != nil {
			return err
		}
		if err := undefinedExpressionVariable(ctx, scope, projection.expression); err != nil {
			return err
		}
		if err := validateStaticFunctionVariables(ctx, projection.expression, input); err != nil {
			return err
		}
	}
	return e.validateStaticOperatorTypes(ctx, clause, input, nil, nil)
}

func (e *StorageExecutor) pipelineSharedClauseSource(ctx context.Context, input pipelineRowSource, clause pipelineClause) (pipelineRowSource, error) {
	if clause.kind == pipelineClauseFilter {
		expression := pipelineFilterExpression(clause.text)
		if expression == "" {
			return nil, sharedClauseSyntaxError("FILTER requires a predicate")
		}
		return func(yield func(pipelineRow) bool) bool {
			valid := true
			completed := input(func(row pipelineRow) bool {
				if err := ctx.Err(); err != nil {
					recordExpressionFailure(ctx, err)
					valid = false
					return false
				}
				accepted := e.evaluateWithWhereCondition(ctx, expression, row)
				if getExpressionFailure(ctx) != nil {
					valid = false
					return false
				}
				return !accepted || yield(row)
			})
			return completed && valid
		}, nil
	}
	projections, err := parsePipelineLet(clause.text)
	if err != nil {
		return nil, err
	}
	plan := pipelineRowWith{star: true, projections: projections}
	return e.pipelineWithRowSource(ctx, input, plan), nil
}

package cypher

import (
	"context"
	"encoding/base64"
	"errors"
	"slices"
	"strings"

	nerrors "github.com/orneryd/nornicdb/pkg/errors"
	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
	"github.com/orneryd/nornicdb/pkg/util"
)

// decodeProcedureCatalogRecord is shared by loading and mutation-time identity
// resolution; the serialized payload, rather than its historical key, names the procedure.
func decodeProcedureCatalogRecord(node *storage.Node) (persistedProcedureRecord, error) {
	var record persistedProcedureRecord
	invalid := func() (persistedProcedureRecord, error) {
		return record, localizedError(localization.CypherProceduresCatalogRecordDecodeFailed(string(node.ID)), nerrors.ErrProcedureCatalogRecordDecodeFailed)
	}
	var payload []byte
	switch raw := node.Properties["record"].(type) {
	case []byte:
		payload = raw
	case string:
		var err error
		payload, err = base64.StdEncoding.DecodeString(raw)
		if err != nil {
			return invalid()
		}
	default:
		return invalid()
	}
	if err := util.DecodeMsgpackBytes(payload, &record); err != nil {
		return invalid()
	}
	return record, nil
}

// resolveProcedureCatalogIdentity owns exact-name resolution and catalog key
// normalization for both mutation-time lookup and a record already being loaded.
// Existing exact records win; create-before-delete keeps failed moves retryable.
func (e *StorageExecutor) resolveProcedureCatalogIdentity(ctx context.Context, store storage.Engine, name string, supplied ...*storage.Node) (*storage.Node, bool, error) {
	canonical := procedureCatalogNodeID(name)
	nodes := supplied
	if len(supplied) == 0 {
		legacy := procedureCatalogNodeID(lowerASCII(strings.TrimSpace(name)))
		keys := []storage.NodeID{canonical}
		if legacy != canonical {
			keys = append(keys, legacy)
		}
		for _, key := range keys {
			node, err := store.GetNode(key)
			if errors.Is(err, storage.ErrNotFound) {
				continue
			}
			if err != nil {
				return nil, false, localizedError(localization.CypherProceduresPersistCatalogFailed(err), err)
			}
			if node != nil {
				nodes = append(nodes, node)
			}
		}
	}
	superseded := false
	for _, node := range nodes {
		record, err := decodeProcedureCatalogRecord(node)
		if err != nil {
			return nil, false, err
		}
		if _, _, _, err := e.compilePersistedProcedure(ctx, record); err != nil {
			return nil, false, localizedError(localization.CypherProceduresCatalogRecordInvalid(string(node.ID)), nerrors.ErrProcedureCatalogRecordInvalid)
		}
		destinationID := procedureCatalogNodeID(record.Name)
		if node.ID == destinationID || node.ID != storage.NodeID(procedureCatalogPrefix+lowerASCII(strings.TrimSpace(record.Name))) {
			continue
		}
		existing, err := store.GetNode(destinationID)
		if err != nil && !errors.Is(err, storage.ErrNotFound) {
			return nil, false, localizedError(localization.CypherProceduresPersistCatalogFailed(err), err)
		}
		superseded = existing != nil
		if superseded {
			destination, err := decodeProcedureCatalogRecord(existing)
			if err != nil {
				return nil, false, err
			}
			if destination.Name != record.Name || !slices.Contains(existing.Labels, procedureCatalogLabel) {
				return nil, false, localizedError(localization.CypherProceduresCatalogRecordInvalid(string(existing.ID)), nerrors.ErrProcedureCatalogRecordInvalid)
			}
			if _, _, _, err := e.compilePersistedProcedure(ctx, destination); err != nil {
				return nil, false, localizedError(localization.CypherProceduresCatalogRecordInvalid(string(existing.ID)), nerrors.ErrProcedureCatalogRecordInvalid)
			}
		} else {
			migrated := *node
			migrated.ID = destinationID
			if _, err := store.CreateNode(&migrated); err != nil {
				return nil, false, localizedError(localization.CypherProceduresPersistCatalogFailed(err), err)
			}
		}
		if err := store.DeleteNode(node.ID); err != nil {
			return nil, false, localizedError(localization.CypherProceduresDropFailed(record.Name, err), err)
		}
	}
	if len(supplied) != 0 {
		return nil, superseded, nil
	}
	node, err := store.GetNode(canonical)
	if errors.Is(err, storage.ErrNotFound) {
		return nil, false, nil
	}
	if err != nil {
		return nil, false, localizedError(localization.CypherProceduresPersistCatalogFailed(err), err)
	}
	if node == nil {
		return nil, false, nil
	}
	record, err := decodeProcedureCatalogRecord(node)
	if err != nil {
		return nil, false, err
	}
	if record.Name != name {
		return nil, false, localizedError(localization.CypherProceduresCatalogRecordInvalid(string(node.ID)), nerrors.ErrProcedureCatalogRecordInvalid)
	}
	return node, superseded, nil
}

package cypher

import (
	"context"
	"encoding/base64"
	"fmt"
	"regexp"
	"strings"
	"time"

	nerrors "github.com/orneryd/nornicdb/pkg/errors"
	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
	"github.com/vmihailenco/msgpack/v5"
)

const (
	procedureCatalogLabel  = "_ProcedureCatalog"
	procedureCatalogPrefix = "__proc__:"
)

var (
	createProcedurePattern = regexp.MustCompile(`(?is)^CREATE\s+(OR\s+REPLACE\s+)?PROCEDURE\s+([a-zA-Z_][a-zA-Z0-9_\.]*)\s*\((.*?)\)\s+MODE\s+(READ|WRITE|SCHEMA|ADMIN|DBMS)\s+AS\s+(.+)$`)
	dropProcedurePattern   = regexp.MustCompile(`(?is)^DROP\s+PROCEDURE\s+([a-zA-Z_][a-zA-Z0-9_\.]*)\s*$`)
)

type persistedProcedureRecord struct {
	Name        string   `msgpack:"name"`
	ArgNames    []string `msgpack:"args"`
	Mode        string   `msgpack:"mode"`
	Body        string   `msgpack:"body"`
	Signature   string   `msgpack:"sig"`
	Description string   `msgpack:"desc"`
	MinArgs     int      `msgpack:"min"`
	MaxArgs     int      `msgpack:"max"`
	UpdatedAt   int64    `msgpack:"updated_at"`
	// ArgTypes, ArgDefaults and Outputs come from a declared signature
	// (apoc.custom): each argument's type and default literal ("" when
	// required), and the output columns. Empty for CREATE PROCEDURE.
	ArgTypes    []string          `msgpack:"arg_types,omitempty"`
	ArgDefaults []string          `msgpack:"arg_defaults,omitempty"`
	Outputs     []ProcedureColumn `msgpack:"outputs,omitempty"`
}

// isCreateProcedureCommand reports whether cypher is CREATE [OR REPLACE]
// PROCEDURE. It runs on every statement's routing, so it doesn't allocate.
func isCreateProcedureCommand(cypher string) bool {
	rest := strings.TrimSpace(cypher)
	if !startsWithKeywordFold(rest, "CREATE") {
		return false
	}
	rest = strings.TrimSpace(rest[len("CREATE"):])
	if startsWithKeywordFold(rest, "OR") {
		rest = strings.TrimSpace(rest[len("OR"):])
		if !startsWithKeywordFold(rest, "REPLACE") {
			return false
		}
		rest = strings.TrimSpace(rest[len("REPLACE"):])
	}
	return startsWithKeywordFold(rest, "PROCEDURE")
}

func isDropProcedureCommand(cypher string) bool {
	return strings.HasPrefix(upperASCII(strings.TrimSpace(cypher)), "DROP PROCEDURE")
}

func (e *StorageExecutor) executeCreateProcedure(ctx context.Context, cypher string) (*ExecuteResult, error) {
	if e.txContext != nil && e.txContext.active {
		return nil, localizedError(localization.CypherProceduresCreateInTransaction(), nil)
	}
	m := createProcedurePattern.FindStringSubmatch(strings.TrimSpace(cypher))
	if len(m) != 6 {
		return nil, localizedError(localization.CypherProceduresCreateInvalidSyntax(), nil)
	}

	replace := strings.TrimSpace(m[1]) != ""
	name := strings.TrimSpace(m[2])
	argNames, err := parseProcedureArgNames(m[3])
	if err != nil {
		return nil, err
	}
	mode := upperASCII(strings.TrimSpace(m[4]))
	body := strings.TrimSpace(m[5])
	if body == "" {
		return nil, localizedError(localization.CypherProceduresBodyRequired(), nil)
	}

	if err := e.installPersistedProcedure(ctx, persistedProcedureRecord{
		Name:      name,
		ArgNames:  argNames,
		Mode:      mode,
		Body:      body,
		Signature: buildProcedureSignature(name, argNames),
		MinArgs:   len(argNames),
		MaxArgs:   len(argNames),
		UpdatedAt: time.Now().UTC().Unix(),
	}, replace); err != nil {
		return nil, err
	}
	return &ExecuteResult{
		Columns: []string{"name", "mode", "status"},
		Rows:    [][]interface{}{{name, mode, "created"}},
	}, nil
}

// installPersistedProcedure compiles record, writes it to the procedure
// catalog (over an existing one of the same name only when replace is set)
// and registers it. CREATE PROCEDURE and apoc.custom share it.
func (e *StorageExecutor) installPersistedProcedure(ctx context.Context, record persistedProcedureRecord, replace bool) error {
	name := record.Name
	spec, handler, record, err := e.compilePersistedProcedure(ctx, record)
	if err != nil {
		return err
	}

	nodeID := procedureCatalogNodeID(name)
	store := e.getStorage(ctx)
	existing, _, err := e.resolveProcedureCatalogIdentity(ctx, store, name)
	if err != nil {
		return err
	}
	if existing != nil && !replace {
		return localizedError(localization.CypherProceduresAlreadyExists(name), nil)
	}

	blob, err := msgpack.Marshal(record)
	if err != nil {
		return localizedError(localization.CypherProceduresEncodeRecordFailed(err), err)
	}
	props := map[string]interface{}{
		"name":      record.Name,
		"mode":      record.Mode,
		"record":    base64.StdEncoding.EncodeToString(blob),
		"updatedAt": record.UpdatedAt,
	}

	if existing != nil {
		existing.Labels = ensureLabel(existing.Labels, procedureCatalogLabel)
		existing.Properties = props
		if err := store.UpdateNode(existing); err != nil {
			return localizedError(localization.CypherProceduresUpdateCatalogFailed(err), err)
		}
	} else {
		node := &storage.Node{
			ID:         nodeID,
			Labels:     []string{procedureCatalogLabel},
			Properties: props,
		}
		if _, err := store.CreateNode(node); err != nil {
			return localizedError(localization.CypherProceduresPersistCatalogFailed(err), err)
		}
	}
	return RegisterUserProcedure(spec, handler)
}

func (e *StorageExecutor) executeDropProcedure(ctx context.Context, cypher string) (*ExecuteResult, error) {
	if e.txContext != nil && e.txContext.active {
		return nil, localizedError(localization.CypherProceduresDropInTransaction(), nil)
	}
	m := dropProcedurePattern.FindStringSubmatch(strings.TrimSpace(cypher))
	if len(m) != 2 {
		return nil, localizedError(localization.CypherProceduresDropInvalidSyntax(), nil)
	}
	name := strings.TrimSpace(m[1])
	if err := e.dropPersistedProcedure(ctx, name); err != nil {
		return nil, err
	}
	return &ExecuteResult{
		Columns: []string{"name", "status"},
		Rows:    [][]interface{}{{name, "dropped"}},
	}, nil
}

// dropPersistedProcedure removes name from the procedure catalog and reloads
// the user procedures from it.
func (e *StorageExecutor) dropPersistedProcedure(ctx context.Context, name string) error {
	store := e.getStorage(ctx)
	existing, _, err := e.resolveProcedureCatalogIdentity(ctx, store, name)
	if err != nil {
		return err
	}
	if existing == nil {
		return localizedError(localization.CypherProceduresDropFailed(name, storage.ErrNotFound), storage.ErrNotFound)
	}
	if err := store.DeleteNode(existing.ID); err != nil {
		return localizedError(localization.CypherProceduresDropFailed(name, err), err)
	}
	// Keep implementation simple and deterministic: refresh user registry from persisted catalog.
	ClearUserProcedures()
	if err := e.loadPersistedProcedures(ctx); err != nil {
		return localizedError(localization.CypherProceduresRegistryReloadFailed(err), nerrors.ErrProcedureRegistryReloadFailed)
	}
	return nil
}

func parseProcedureArgNames(raw string) ([]string, error) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return []string{}, nil
	}
	parts := splitTopLevelComma(raw)
	args := make([]string, 0, len(parts))
	seen := map[string]struct{}{}
	for _, p := range parts {
		arg := strings.TrimSpace(p)
		if arg == "" {
			continue
		}
		if strings.HasPrefix(arg, "$") {
			arg = strings.TrimSpace(arg[1:])
		}
		if !isValidIdentifier(arg) {
			return nil, localizedError(localization.CypherProceduresInvalidArgumentName(arg), nil)
		}
		if _, exists := seen[arg]; exists {
			return nil, localizedError(localization.CypherProceduresDuplicateArgument(arg), nil)
		}
		seen[arg] = struct{}{}
		args = append(args, arg)
	}
	return args, nil
}

func (e *StorageExecutor) compilePersistedProcedure(ctx context.Context, record persistedProcedureRecord) (ProcedureSpec, ProcedureHandler, persistedProcedureRecord, error) {
	mode := ProcedureMode(upperASCII(record.Mode))
	switch mode {
	case ProcedureModeRead, ProcedureModeWrite, ProcedureModeSchema, ProcedureModeAdmin, ProcedureModeDBMS:
	default:
		return ProcedureSpec{}, nil, record, localizedError(localization.CypherProceduresInvalidMode(record.Mode), nil)
	}

	contract, err := readStatementExecutionContract(ctx, record.Body)
	if err != nil {
		return ProcedureSpec{}, nil, record, err
	}
	if mode == ProcedureModeRead && contract.writes {
		return ProcedureSpec{}, nil, record, localizedError(localization.CypherProceduresReadContainsWrite(), nil)
	}

	argNames := append([]string{}, record.ArgNames...)
	minArgs := len(argNames)
	if len(record.ArgDefaults) == len(argNames) {
		minArgs = record.MinArgs
	}
	spec := ProcedureSpec{
		Name:        record.Name,
		Signature:   record.Signature,
		Description: record.Description,
		Mode:        mode,
		MinArgs:     minArgs,
		MaxArgs:     len(argNames),
		Params:      make([]ProcedureParam, 0, len(argNames)),
		Returns:     append([]ProcedureColumn(nil), record.Outputs...),
		ResultCache: ProcedureResultCache{CypherInputs: []ProcedureCypherInput{{StoredText: record.Body}}},
	}
	for i, arg := range argNames {
		param := ProcedureParam{Name: arg, Type: "ANY", Optional: i >= minArgs}
		if i < len(record.ArgTypes) {
			param.Type = record.ArgTypes[i]
		}
		if i < len(record.ArgDefaults) {
			param.Default = record.ArgDefaults[i]
		}
		spec.Params = append(spec.Params, param)
	}

	handler := func(ctx context.Context, exec *StorageExecutor, cypher string, args []interface{}) (*ExecuteResult, error) {
		if len(args) < minArgs || len(args) > len(argNames) {
			return nil, localizedError(localization.CypherProceduresArgumentCount(record.Name, len(argNames), len(args)), nil)
		}
		params := make(map[string]interface{}, len(argNames))
		for i, arg := range argNames {
			if i < len(args) {
				params[arg] = args[i]
				continue
			}
			// An omitted optional argument takes its declared default.
			params[arg], _ = parseLiteralValueFromComputedRow(record.ArgDefaults[i])
		}
		// The body is a statement the procedure runs, like one
		// apoc.cypher.run runs: through the one route for those, which
		// refuses administration commands and NornicDB's internal functions
		// and keeps the body in the caller's transaction.
		return exec.executeUserStatement(ctx, record.Body, params)
	}
	return spec, handler, record, nil
}

func buildProcedureSignature(name string, args []string) string {
	if len(args) == 0 {
		return fmt.Sprintf("%s() :: (value :: ANY)", name)
	}
	argSpec := make([]string, 0, len(args))
	for _, a := range args {
		argSpec = append(argSpec, fmt.Sprintf("$%s :: ANY", a))
	}
	return fmt.Sprintf("%s(%s) :: (value :: ANY)", name, strings.Join(argSpec, ", "))
}

func procedureCatalogNodeID(name string) storage.NodeID {
	return storage.NodeID(procedureCatalogPrefix + strings.TrimSpace(name))
}

func ensureLabel(labels []string, label string) []string {
	for _, l := range labels {
		if l == label {
			return labels
		}
	}
	return append(labels, label)
}

func (e *StorageExecutor) loadPersistedProcedures(ctx context.Context) error {
	nodes, err := e.storage.GetNodesByLabel(procedureCatalogLabel)
	if err != nil {
		return localizedError(localization.CypherProceduresCatalogReadFailed(err), nerrors.ErrProcedureCatalogReadFailed)
	}
	for _, node := range nodes {
		if _, ok := node.Properties["record"]; !ok {
			continue
		}
		record, err := decodeProcedureCatalogRecord(node)
		if err != nil {
			return err
		}
		spec, handler, _, err := e.compilePersistedProcedure(ctx, record)
		if err != nil {
			return localizedError(localization.CypherProceduresCatalogRecordInvalid(string(node.ID)), nerrors.ErrProcedureCatalogRecordInvalid)
		}
		if _, superseded, err := e.resolveProcedureCatalogIdentity(ctx, e.storage, record.Name, node); err != nil {
			return err
		} else if superseded {
			continue
		}
		if err := RegisterUserProcedure(spec, handler); err != nil {
			return localizedError(localization.CypherProceduresRegistryReloadFailed(err), nerrors.ErrProcedureRegistryReloadFailed)
		}
	}
	return nil
}

package cypher

import (
	"context"
	"fmt"
	"sort"
	"strings"
	"sync"
	"sync/atomic"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/util"
	"golang.org/x/text/language"
)

// ProcedureMode represents Neo4j-compatible procedure execution mode.
type ProcedureMode string

const (
	ProcedureModeRead   ProcedureMode = "READ"
	ProcedureModeWrite  ProcedureMode = "WRITE"
	ProcedureModeSchema ProcedureMode = "SCHEMA"
	ProcedureModeAdmin  ProcedureMode = "ADMIN"
	ProcedureModeDBMS   ProcedureMode = "DBMS"
)

// ProcedureParam defines one procedure argument in canonical metadata.
// Description and IsDeprecated are exposed by SHOW PROCEDURES. Default is
// its display representation, not an argument value; an empty Default omits
// the metadata entry. Optional does not change the procedure's declared arity.
//
// For example, an optional map argument can use:
//
//	ProcedureParam{Name: "options", Type: "MAP", Optional: true,
//		Default: "DefaultParameterValue{value={}, type=MAP}"}
type ProcedureParam struct {
	Name         string
	Type         string
	Optional     bool
	Description  string
	Default      string
	IsDeprecated bool
}

// ProcedureColumn defines one YIELD column in canonical metadata.
// Description and IsDeprecated describe that column in SHOW PROCEDURES.
type ProcedureColumn struct {
	Name         string
	Type         string
	Description  string
	IsDeprecated bool
}

// ProcedureSpec is the canonical contract for built-in and user-defined procedures.
// Admin, IsDeprecated and DeprecatedBy describe the procedure in SHOW PROCEDURES;
// they do not replace handler authorization or change execution behavior.
// An empty DeprecatedBy is exposed as null. For example, a deprecated procedure
// can set IsDeprecated: true and DeprecatedBy: "custom.replacement".
type ProcedureSpec struct {
	Name               string
	Signature          string
	Description        string
	DescriptionMessage localization.Message
	Mode               ProcedureMode
	WorksOnSystem      bool
	Admin              bool
	IsDeprecated       bool
	DeprecatedBy       string
	Params             []ProcedureParam
	Returns            []ProcedureColumn
	// ResultSchemas declares a closed set of headers for a value-dependent procedure.
	// Returns still describes every legal YIELD field; no runtime observation extends it.
	ResultSchemas func() [][]string `json:"-"`
	MinArgs       int
	MaxArgs       int
	// ResultCache declares execution dependencies; an undeclared handler is
	// opaque to the determinism owner and cannot supply cached results.
	ResultCache ProcedureResultCache
	// ExecutesStatements requests a native statement rollback owner. Its
	// handler resolves arguments normally; actual inner writes promote a
	// Fabric participant at the shared execution boundary.
	ExecutesStatements bool
	// OwnsTransactions owns autocommit batch boundaries. Native explicit
	// transactions retain shipped folding; Fabric-managed scopes reject it
	// before invocation because their rollback cannot undo committed batches.
	OwnsTransactions bool
}

// writes reports whether a call of the procedure changes the database: its
// data (WRITE) or its schema (SCHEMA).
func (s ProcedureSpec) writes() bool {
	return s.Mode == ProcedureModeWrite || s.Mode == ProcedureModeSchema
}

// ProcedureMetadataRenderer renders localized procedure metadata for a request context.
type ProcedureMetadataRenderer interface {
	Render(context.Context, localization.Message) (string, language.Tag, error)
}

// ProcedureHandler executes a registered procedure.
type ProcedureHandler func(ctx context.Context, exec *StorageExecutor, cypher string, args []interface{}) (*ExecuteResult, error)

type registeredProcedure struct {
	Spec    ProcedureSpec
	Handler ProcedureHandler
	User    bool
}

// ProcedureRegistry resolves each built-in or user procedure by its exact
// registered name, including namespace and letter case, as Neo4j does.
// For example, "tenant.Report" and "tenant.report" are distinct registrations;
// CALL tenant.REPORT() cannot select either.
type ProcedureRegistry struct {
	mu         sync.RWMutex
	generation atomic.Uint64
	builtins   map[string]registeredProcedure
	user       map[string]registeredProcedure
	userFold   map[string]struct{}
}

func NewProcedureRegistry() *ProcedureRegistry {
	return &ProcedureRegistry{
		builtins: make(map[string]registeredProcedure),
		user:     make(map[string]registeredProcedure),
		userFold: make(map[string]struct{}),
	}
}

func (r *ProcedureRegistry) RegisterBuiltIn(spec ProcedureSpec, handler ProcedureHandler) error {
	if err := validateProcedureSpec(spec); err != nil {
		return err
	}
	if handler == nil {
		return fmt.Errorf("procedure %q: nil handler", spec.Name)
	}
	key := spec.Name
	r.mu.Lock()
	defer r.mu.Unlock()
	r.builtins[key] = registeredProcedure{Spec: spec, Handler: handler}
	r.generation.Add(1)
	return nil
}

func (r *ProcedureRegistry) RegisterUser(spec ProcedureSpec, handler ProcedureHandler) error {
	if err := validateProcedureSpec(spec); err != nil {
		return err
	}
	// A user-defined or plugin procedure declares a mode, not an admin
	// flag: an ADMIN or DBMS one is admin-only.
	if spec.Mode == ProcedureModeAdmin || spec.Mode == ProcedureModeDBMS {
		spec.Admin = true
	}
	if handler == nil {
		return fmt.Errorf("procedure %q: nil handler", spec.Name)
	}
	key := spec.Name
	r.mu.Lock()
	defer r.mu.Unlock()
	r.user[key] = registeredProcedure{Spec: spec, Handler: handler, User: true}
	r.userFold[lowerASCII(spec.Name)] = struct{}{}
	r.generation.Add(1)
	return nil
}

func (r *ProcedureRegistry) Get(name string) (registeredProcedure, bool) {
	key := name
	r.mu.RLock()
	defer r.mu.RUnlock()
	if p, ok := r.user[key]; ok {
		return p, true
	}
	p, ok := r.builtins[key]
	return p, ok
}

// callsUserProcedure reports whether query calls a user-defined procedure:
// a CALL of one anywhere in query, string literals included (a statement
// query hands to apoc.cypher.run). A name matches in any letter case, so
// the answer doesn't depend on how the registry keys a name; erring towards
// "calls one" only skips the cache. It is false at once while none is
// registered.
func (r *ProcedureRegistry) callsUserProcedure(query string) bool {
	r.mu.RLock()
	defer r.mu.RUnlock()
	if len(r.user) == 0 {
		return false
	}
	opts := defaultKeywordScanOpts()
	opts.SkipParens = false
	opts.SkipBrackets = false
	opts.SkipBraces = false
	opts.SkipStrings = false
	for from := 0; from < len(query); {
		at := keywordIndexFrom(query, "CALL", from, opts)
		if at < 0 {
			return false
		}
		from = at + len("CALL")
		if name, ok := procedureNameAt(query, from); ok {
			if _, exists := r.userFold[lowerASCII(name)]; exists {
				return true
			}
		}
	}
	return false
}

func (r *ProcedureRegistry) List() []ProcedureSpec {
	r.mu.RLock()
	defer r.mu.RUnlock()
	out := make([]ProcedureSpec, 0, util.SafePreallocSum(len(r.builtins), len(r.user)))
	for _, p := range r.builtins {
		out = append(out, p.Spec)
	}
	for _, p := range r.user {
		out = append(out, p.Spec)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

func (r *ProcedureRegistry) ListBuiltIns() []ProcedureSpec {
	r.mu.RLock()
	defer r.mu.RUnlock()
	out := make([]ProcedureSpec, 0, len(r.builtins))
	for _, p := range r.builtins {
		out = append(out, p.Spec)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

func (r *ProcedureRegistry) ClearUser() {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.user = make(map[string]registeredProcedure)
	r.userFold = make(map[string]struct{})
	r.generation.Add(1)
}

func validateProcedureSpec(spec ProcedureSpec) error {
	if strings.TrimSpace(spec.Name) == "" {
		return fmt.Errorf("procedure name cannot be empty")
	}
	if spec.MinArgs < 0 {
		spec.MinArgs = 0
	}
	if spec.MaxArgs >= 0 && spec.MaxArgs < spec.MinArgs {
		return fmt.Errorf("procedure %q: MaxArgs(%d) < MinArgs(%d)", spec.Name, spec.MaxArgs, spec.MinArgs)
	}
	return nil
}

func procedureOutputTypes(ctx context.Context, clause string) map[string]string {
	procedure, found := globalProcedureRegistry.Get(extractProcedureName(ctx, clause))
	if !found {
		return nil
	}
	outputs := procedureDeclaredReturns(procedure.Spec)
	result := make(map[string]string, len(outputs))
	for _, output := range outputs {
		if typeName := procedureStaticType(output.Type); typeName != "" {
			result[output.Name] = typeName
		}
	}
	return result
}

// procedureDeclaredReturns is the registry's ordered output declaration,
// shared by static type consumers and result-header analysis.
func procedureDeclaredReturns(spec ProcedureSpec) []ProcedureColumn {
	outputs := spec.Returns
	if len(outputs) == 0 {
		separator := strings.LastIndex(spec.Signature, " :: (")
		if separator < 0 || !strings.HasSuffix(spec.Signature, ")") {
			return nil
		}
		for _, output := range splitTopLevelComma(spec.Signature[separator+5 : len(spec.Signature)-1]) {
			if name, typeName, ok := strings.Cut(output, "::"); ok {
				outputs = append(outputs, ProcedureColumn{Name: strings.TrimSpace(name), Type: typeName})
			}
		}
	}
	return outputs
}

func procedureStaticType(typeName string) string {
	typeName = strings.TrimSuffix(strings.ToUpper(strings.TrimSpace(typeName)), "?")
	if strings.HasPrefix(typeName, "LIST<") && strings.HasSuffix(typeName, ">") {
		element := procedureStaticType(typeName[5 : len(typeName)-1])
		if element == "" {
			element = "Any"
		}
		return "List<" + element + ">"
	}
	switch typeName {
	case "STRING", "INTEGER", "FLOAT", "BOOLEAN", "NODE", "RELATIONSHIP", "PATH", "MAP":
		return typeName[:1] + strings.ToLower(typeName[1:])
	default:
		return ""
	}
}

var globalProcedureRegistry = NewProcedureRegistry()

// RegisterUserProcedure registers a user-defined procedure into the global registry.
func RegisterUserProcedure(spec ProcedureSpec, handler ProcedureHandler) error {
	return globalProcedureRegistry.RegisterUser(spec, handler)
}

// ListRegisteredProcedures returns built-in and user-registered procedures.
func ListRegisteredProcedures() []ProcedureSpec {
	return globalProcedureRegistry.List()
}

// ClearUserProcedures resets user-defined procedures (primarily for tests/reload paths).
func ClearUserProcedures() {
	globalProcedureRegistry.ClearUser()
}

func validateProcedureArgCount(spec ProcedureSpec, args []interface{}) error {
	return validateProcedureArgumentCount(spec, len(args))
}

func validateProcedureArgumentCount(spec ProcedureSpec, count int) error {
	if spec.MinArgs > 0 && count < spec.MinArgs {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidNumberOfArguments",
			fmt.Sprintf("procedure %s requires at least %d arguments, got %d", spec.Name, spec.MinArgs, count),
		)
	}
	if spec.MaxArgs >= 0 && count > spec.MaxArgs {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidNumberOfArguments",
			fmt.Sprintf("procedure %s accepts at most %d arguments, got %d", spec.Name, spec.MaxArgs, count),
		)
	}
	return nil
}

