		return parsedSimplePropertyConstraintDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("prefix"), nil)
	}
	prefixEnd, ok := keywordSpanAt(q, 0, "CREATE CONSTRAINT")
	if !ok {
		return parsedSimplePropertyConstraintDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("prefix"), nil)
	}

	forPos := keywordIndexFrom(q, "FOR", prefixEnd, defaultKeywordScanOpts())
	onPos := keywordIndexFrom(q, "ON", prefixEnd, defaultKeywordScanOpts())

	if forPos >= 0 && (onPos < 0 || forPos < onPos) {
		name, patternSpan, predicateExpr, err := e.parseCreateConstraintForRequireHead(q)
		if err != nil {
			return parsedSimplePropertyConstraintDDL{}, err
		}

		label, relType, isRelationship, err := parseCreateIndexForPattern(patternSpan)
		if err != nil {
			return parsedSimplePropertyConstraintDDL{}, err
		}

		kind, property, ok := parseConstraintPredicate(predicateExpr)
		if !ok {
			return parsedSimplePropertyConstraintDDL{}, localizedError(localization.CypherSchemaUnsupportedPredicate("constraint"), nil)
		}

		out := parsedSimplePropertyConstraintDDL{name: name, property: property, kind: kind, isRelationship: isRelationship}
		if isRelationship {
			out.label = relType
		} else {
			out.label = label
		}
		return out, nil
	}

	if onPos >= 0 {
		onEnd, ok := keywordSpanAt(q, onPos, "ON")
		if !ok {
			return parsedSimplePropertyConstraintDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("ON"), nil)
		}
		assertPos := keywordIndexFrom(q, "ASSERT", onEnd, defaultKeywordScanOpts())
		if assertPos < 0 {
			return parsedSimplePropertyConstraintDDL{}, localizedError(localization.CypherSchemaMissingKeyword("ASSERT"), nil)
		}
		assertEnd, ok := keywordSpanAt(q, assertPos, "ASSERT")
		if !ok {
			return parsedSimplePropertyConstraintDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("ASSERT"), nil)
		}

		name, err := parseOptionalDDLName(q[prefixEnd:onPos])
		if err != nil {
			return parsedSimplePropertyConstraintDDL{}, err
		}

		label, _, isRelationship, err := parseCreateIndexForPattern(q[onEnd:assertPos])
		if err != nil || isRelationship {
			return parsedSimplePropertyConstraintDDL{}, localizedError(localization.CypherSchemaInvalidPattern("ASSERT"), nil)
		}

		predicateExpr, tail := splitDDLOptionsTail(q[assertEnd:])
		if tail != "" && !startsWithKeywordFold(tail, "OPTIONS") {
			return parsedSimplePropertyConstraintDDL{}, localizedError(localization.CypherSchemaInvalidTrailingSyntax(), nil)
		}
		kind, property, ok := parseConstraintPredicate(predicateExpr)
		if !ok {
			return parsedSimplePropertyConstraintDDL{}, localizedError(localization.CypherSchemaUnsupportedPredicate("constraint"), nil)
		}
		return parsedSimplePropertyConstraintDDL{name: name, label: label, property: property, kind: kind, isRelationship: false}, nil
	}

	return parsedSimplePropertyConstraintDDL{}, localizedError(localization.CypherSchemaUnsupportedCreateConstraintShape(), nil)
}

// parseIndexProperties parses property list from index ON clause.
//
// Handles both single and composite property syntax:
//   - "n.property"           -> ["property"]
//   - "n.prop1, n.prop2"     -> ["prop1", "prop2"]
//   - "n.a, n.b, n.c"        -> ["a", "b", "c"]
func (e *StorageExecutor) parseIndexProperties(propertiesStr string) []string {
	return e.parseIndexPropertiesWithMode(propertiesStr, true)
}

// addSchemaConstraint adds constraint and, when it is a single-property
// uniqueness or node key constraint, fills the property index it owns from
// the stored nodes (#875), as addPropertyIndex fills a new index: equality
// and IN seeks then use it inside transactions as they use an index of its
// own. A constraint whose fill fails is dropped again, since a half-filled
// index would make seeks drop rows.
func (e *StorageExecutor) addSchemaConstraint(constraint storage.Constraint, ifNotExists bool) error {
	schema := e.storage.GetSchema()
	_, existed := schema.ConstraintPropertyIndex(constraint.Name)
	registered := schema.HasConstraintNamed(constraint.Name)
	if err := schema.AddConstraint(constraint, ifNotExists); err != nil {
		return err
	}
	// A new temporal constraint's history index is authoritative when its
	// label is empty; over existing nodes it isn't until the next rebuild
	// (#1126). IF NOT EXISTS on an existing constraint changes nothing.
	if !registered && constraint.Type == storage.ConstraintTemporal {
		if err := storage.MarkNewTemporalConstraintsForEngine(e.storage, schema, []storage.Constraint{constraint}); err != nil {
			return err
		}
	}
	index, owned := schema.ConstraintPropertyIndex(constraint.Name)
	if existed || !owned {
		return nil
	}
	if err := e.backfillCompositeIndex(index.Name, index.Label, index.Properties); err != nil {
		_ = schema.DropConstraint(constraint.Name)
		return err
	}
	return nil
}

// addPropertyIndex creates an equality index (arity-1 or composite) and,
// when it didn't exist yet, fills it from the label's nodes. An existing
// index is left as it is: it is already maintained, and filling it again
// would list its nodes twice. A new index whose fill fails is dropped again:
// index lookups trust an index to hold every node with the value, so a
// half-filled one would drop rows.
func (e *StorageExecutor) addPropertyIndex(name, label string, properties []string) error {
	schema := e.storage.GetSchema()
	_, existed := schema.GetCompositeIndex(name)
	if err := schema.AddCompositeIndex(name, label, properties); err != nil {
		return err
	}
	if existed {
		return nil
	}
	if err := e.backfillCompositeIndex(name, label, properties); err != nil {
		_ = schema.DropIndex(name)
		return err
	}
	return nil
}

// backfillCompositeIndex fills a newly created equality index from the
// label's stored nodes, those the visibility layer hides from reads included:
// an index lookup finds them once they are shown again, and a NODE KEY check
// that trusts the index sees their values. A new index whose fill fails is
// dropped by addPropertyIndex / addSchemaConstraint, since index lookups
// trust an index to hold every matching node.
func (e *StorageExecutor) backfillCompositeIndex(name, label string, properties []string) error {
	schema := e.storage.GetSchema()
	if schema == nil {
		return nil
	}
	nodes, err := storage.GetStoredNodesByLabel(e.storage, label)
	if err != nil {
		return localizedError(localization.CypherSchemaBackfillIndexFailed(label, err), err)
	}
	entries := make(map[storage.NodeID]map[string]interface{}, len(nodes))
	for _, node := range nodes {
		if node == nil || node.Properties == nil {
			continue
		}
		entries[storage.EnsureNodeIDDatabasePrefixForEngine(e.storage, node.ID)] = node.Properties
	}
	if err := schema.BackfillCompositeIndex(name, entries); err != nil {
		property := ""
		if len(properties) > 0 {
			property = properties[0]
		}
		return localizedError(localization.CypherSchemaBackfillPropertyIndexFailed(label, property, err), err)
	}
	return nil
}

// qualifiedIndexPropertiesWellFormed reports whether every comma-separated item
// of an index ON clause is a variable.property reference whose two parts are
// identifiers or backtick-quoted names. An empty list is left to the caller's
// "properties required" error.
func qualifiedIndexPropertiesWellFormed(propertiesStr string) bool {
	if strings.TrimSpace(propertiesStr) == "" {
		return true
	}
	for _, part := range splitTopLevelComma(propertiesStr) {
		part = strings.TrimSpace(part)
		variable, property, ok := splitPostfixPropertyAccess(part)
		if !ok || !isPatternVariableName(strings.TrimSpace(variable)) || property == "" {
			return false
		}
	}
	return true
}

func (e *StorageExecutor) parseQualifiedIndexProperties(propertiesStr string) []string {
	return e.parseIndexPropertiesWithMode(propertiesStr, false)
}

func (e *StorageExecutor) parseIndexPropertiesWithMode(propertiesStr string, allowBare bool) []string {
	// Split by comma
	parts := strings.Split(propertiesStr, ",")
	var properties []string

	for _, part := range parts {
		part = strings.TrimSpace(part)
		// Extract property name after dot (e.g., "n.prop" -> "prop")
		if dotIdx := strings.LastIndex(part, "."); dotIdx >= 0 && dotIdx < len(part)-1 {
			propName := normalizeIdentifierToken(part[dotIdx+1:])
			if propName != "" {
				properties = append(properties, propName)
			}
		} else if allowBare {
			// Also support bare property names used by legacy syntax ON :Label(prop)
			propName := normalizeIdentifierToken(part)
			if propName != "" {
				properties = append(properties, propName)
			}
		}
	}

	return properties
}

func (e *StorageExecutor) parseConstraintProperties(propertiesStr string) []string {
	parts := strings.Split(propertiesStr, ",")
	properties := make([]string, 0, len(parts))
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if dotIdx := strings.LastIndex(part, "."); dotIdx >= 0 && dotIdx < len(part)-1 {
			propName := normalizeIdentifierToken(part[dotIdx+1:])
			if propName != "" {
				properties = append(properties, propName)
			}
		}
	}
	return properties
}

// executeCreateFulltextIndex handles CREATE FULLTEXT INDEX commands.
//
// Supported syntax:
//
//	CREATE FULLTEXT INDEX index_name [IF NOT EXISTS]
//	FOR (n:Label) ON EACH [n.prop1, n.prop2]
//
//	CREATE FULLTEXT INDEX index_name [IF NOT EXISTS]
//	FOR ()-[r:RelType]-() ON EACH [r.prop1, r.prop2]
//
// The relationship form binds an index to a relationship type (or
// types — Neo4j allows `:R1|R2`); the runtime then scopes
// db.index.fulltext.queryRelationships to those types instead of
// scanning every edge.
func (e *StorageExecutor) executeCreateFulltextIndex(ctx context.Context, cypher string) (*ExecuteResult, error) {
	schema := e.storage.GetSchema()
	if schema == nil {
		return nil, localizedError(localization.CypherSchemaManagerUnavailable(), nil)
	}

	parsed, err := e.parseCreateFulltextIndexDDL(cypher)
	if err != nil {
		return nil, err
	}

	entityType := storage.ConstraintEntityNode
	targets := parsed.labels
	if parsed.isRelationship {
		entityType = storage.ConstraintEntityRelationship
		targets = parsed.relationshipTypes
	}
	create, err := e.admitIndexCreationForTargets(cypher, parsed.indexName, "FULLTEXT", targets, parsed.properties, entityType)
	if err != nil {
		return nil, err
	}
	if !create {
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	}

	if parsed.isRelationship {
		if err := schema.AddFulltextRelationshipIndex(parsed.indexName, parsed.relationshipTypes, parsed.properties); err != nil {
			return nil, localizedError(localization.CypherSchemaAddFulltextRelationshipIndexFailed(err), err)
		}
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	}

	if err := schema.AddFulltextIndex(parsed.indexName, parsed.labels, parsed.properties); err != nil {
		return nil, localizedError(localization.CypherSchemaAddFulltextIndexFailed(err), err)
	}

	return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
}

// parseDomainValueList parses a comma-separated list of literal values from a domain constraint.
// Supports strings ('value' or "value"), integers, and floats.
func parseDomainValueList(raw string) ([]interface{}, error) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return nil, nil
	}

	var values []interface{}
	for _, item := range splitTopLevelComma(raw) {
		token := strings.TrimSpace(item)
		if token == "" {
			continue
		}
		if value, quoted := decodeCypherQuotedString(token); quoted {
			values = append(values, value)
		} else if isCypherStringQuoteByte(token[0]) {
			return nil, localizedError(localization.CypherSchemaUnterminatedString(token), nil)
		} else {
			// Numeric or boolean literal
			// Try integer
			if intVal, err := strconv.ParseInt(token, 10, 64); err == nil {
				values = append(values, intVal)
			} else if floatVal, err := strconv.ParseFloat(token, 64); err == nil {
				values = append(values, floatVal)
			} else if token == "true" {
				values = append(values, true)
			} else if token == "false" {
				values = append(values, false)
			} else {
				// Treat as bare string
				values = append(values, token)
			}
		}

	}

	return values, nil
}

func parseFulltextRelationshipTypes(raw string) ([]string, error) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return nil, nerrors.ErrInvalidFulltextRelationshipTypes
	}

	types := make([]string, 0, 2)
	var cur strings.Builder

	flush := func() error {
		part := normalizeIdentifierToken(strings.TrimSpace(cur.String()))
		cur.Reset()
		if part == "" {
			return nerrors.ErrInvalidFulltextRelationshipTypes
		}
		types = append(types, part)
		return nil
	}

	for index := 0; index < len(raw); index++ {
		if isCypherBacktickByte(raw[index]) {
			end, closed := scanCypherQuotedText(raw, index, raw[index])
			if !closed {
				return nil, nerrors.ErrInvalidFulltextRelationshipTypes
			}
			cur.WriteString(raw[index:end])
			index = end - 1
			continue
		}
		switch raw[index] {
		case '|':
			if err := flush(); err != nil {
				return nil, err
			}
		default:
			cur.WriteByte(raw[index])
		}
	}
	if err := flush(); err != nil {
		return nil, err
	}
	return types, nil
}

func normalizeIdentifierToken(v string) string {
	s := strings.TrimSpace(v)
	if len(s) >= 2 && strings.HasPrefix(s, "`") && strings.HasSuffix(s, "`") {
		s = s[1 : len(s)-1]
		s = strings.ReplaceAll(s, "``", "`")
	}
	return strings.TrimSpace(s)
}

// executeCreateVectorIndex handles CREATE VECTOR INDEX commands.
//
// Supported syntax:
//
//	CREATE VECTOR INDEX index_name IF NOT EXISTS
//	FOR (n:Label) ON (n.property)
//	OPTIONS {indexConfig: {`vector.dimensions`: 1024, `vector.similarity_function`: 'cosine'}}
func (e *StorageExecutor) executeCreateVectorIndex(ctx context.Context, cypher string) (*ExecuteResult, error) {
	parsed, err := e.parseCreateIndexDDL(cypher, "CREATE VECTOR INDEX")
	if err != nil {
		return nil, localizedError(localization.CypherSchemaInvalidSyntax("CREATE VECTOR INDEX"), nil)
	}
	if len(parsed.properties) != 1 || parsed.indexName == "" ||
		(!parsed.isRelationship && parsed.label == "") ||
		(parsed.isRelationship && parsed.relationshipType == "") {
		return nil, localizedError(localization.CypherSchemaInvalidSyntax("CREATE VECTOR INDEX"), nil)
	}

	indexName := parsed.indexName
	label := parsed.label
	if parsed.isRelationship {
		label = parsed.relationshipType
	}
	property := parsed.properties[0]

	// Parse OPTIONS if present - use configured default dimensions
	dimensions := e.GetDefaultEmbeddingDimensions()
	similarityFunc := "cosine" // Default

	dimensions, similarityFunc = parseVectorOptions(parsed.optionsClause, dimensions, similarityFunc)

	// Add vector index. The schema entry is recorded regardless of the
	// vector master switch so SHOW INDEXES still reflects operator intent
	// and DROP INDEX has something to remove. The actual in-memory vector
	// space is only registered when vector search is enabled — otherwise
	// the operator explicitly turned vector indexing off and we must not
	// allocate or warm any vector backend on their behalf.
	entityType := storage.ConstraintEntityNode
	if parsed.isRelationship {
		entityType = storage.ConstraintEntityRelationship
	}
	create, err := e.admitIndexCreation(cypher, indexName, "VECTOR", label, parsed.properties, entityType)
	if err != nil {
		return nil, err
	}
	if !create {
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	}
	if err := e.storage.GetSchema().AddVectorIndexForEntity(indexName, label, property, dimensions, similarityFunc, entityType); err != nil {
		return nil, err
	}

	// Relationship vector indexes are consumed by relationship vector procedures
	// directly from relationship properties and schema metadata.
	// registerVectorSpace is node-vector specific; keep relationship indexes out.
	if svc := e.search(); !parsed.isRelationship && (svc == nil || svc.VectorEnabled()) {
		e.afterSchemaCommit(ctx, func() {
			e.registerVectorSpace(indexName, label, property, dimensions, similarityFunc)
		})
	}

	return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
}

package cypher

import (
	"context"
	"fmt"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

type parsedCreateConstraintContractDDL struct {
	name        string
	entityType  storage.ConstraintEntityType
	variable    string
	labelOrType string
	body        string
}

func parseConstraintContractForClause(forClause string) (entityType storage.ConstraintEntityType, variable string, labelOrType string, ok bool) {
	forClause = strings.TrimSpace(forClause)
	if forClause == "" {
		return "", "", "", false
	}

	if strings.Contains(forClause, "[") {
		bracketStart := strings.Index(forClause, "[")
		if bracketStart < 0 {
			return "", "", "", false
		}
		inside, rest, ok := extractBracketSection(forClause[bracketStart:])
		if !ok {
			return "", "", "", false
		}
		prefix := strings.TrimSpace(forClause[:bracketStart])
		suffix := strings.TrimSpace(rest)
		if !strings.Contains(prefix, "(") || !strings.Contains(suffix, "(") {
			return "", "", "", false
		}
		colon := strings.Index(inside, ":")
		if colon < 0 {
			return "", "", "", false
		}
		variable = normalizeIdentifierToken(strings.TrimSpace(inside[:colon]))
		labelOrType = normalizeIdentifierToken(strings.TrimSpace(inside[colon+1:]))
		if labelOrType == "" {
			return "", "", "", false
		}
		return storage.ConstraintEntityRelationship, variable, labelOrType, true
	}

	inside, rest, ok := extractParenSection(forClause)
	if !ok || strings.TrimSpace(rest) != "" {
		return "", "", "", false
	}
	colon := strings.Index(inside, ":")
	if colon < 0 {
		return "", "", "", false
	}
	variable = normalizeIdentifierToken(strings.TrimSpace(inside[:colon]))
	labelOrType = normalizeIdentifierToken(strings.TrimSpace(inside[colon+1:]))
	if labelOrType == "" {
		return "", "", "", false
	}
	return storage.ConstraintEntityNode, variable, labelOrType, true
}

func parseCurlySection(s string) (inside string, rest string, ok bool) {
	s = strings.TrimSpace(s)
	if s == "" || s[0] != '{' {
		return "", s, false
	}
	closing := findMatchingDelimiter(s, 0, '{', '}')
	if closing < 0 {
		return "", s, false
	}
	return s[1:closing], strings.TrimSpace(s[closing+1:]), true
}

func (e *StorageExecutor) parseCreateConstraintContractDDL(cypher string) (parsedCreateConstraintContractDDL, error) {
	q := strings.TrimSpace(cypher)
	if q == "" {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaEmptyStatement(), nil)
	}
	prefixPos := keywordIndexFrom(q, "CREATE CONSTRAINT", 0, defaultKeywordScanOpts())
	if prefixPos != 0 {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("prefix"), nil)
	}
	prefixEnd, ok := keywordSpanAt(q, 0, "CREATE CONSTRAINT")
	if !ok {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("prefix"), nil)
	}
	forPos := keywordIndexFrom(q, "FOR", prefixEnd, defaultKeywordScanOpts())
	if forPos < 0 {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaMissingKeyword("FOR"), nil)
	}
	forEnd, ok := keywordSpanAt(q, forPos, "FOR")
	if !ok {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("FOR"), nil)
	}
	reqPos := keywordIndexFrom(q, "REQUIRE", forEnd, defaultKeywordScanOpts())
	if reqPos < 0 {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaMissingKeyword("REQUIRE"), nil)
	}
	reqEnd, ok := keywordSpanAt(q, reqPos, "REQUIRE")
	if !ok {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("REQUIRE"), nil)
	}

	name, err := parseOptionalDDLName(q[prefixEnd:forPos])
	if err != nil {
		return parsedCreateConstraintContractDDL{}, err
	}

	entityType, variable, labelOrType, ok := parseConstraintContractForClause(q[forEnd:reqPos])
	if !ok {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaInvalidPattern("FOR"), nil)
	}

	body, tail, ok := parseCurlySection(q[reqEnd:])
	if !ok || tail != "" {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaInvalidClause("REQUIRE block"), nil)
	}

	if name == "" {
		name = fmt.Sprintf("constraint_%s_contract", labelOrType)
	}
	return parsedCreateConstraintContractDDL{
		name:        name,
		entityType:  entityType,
		variable:    variable,
		labelOrType: labelOrType,
		body:        body,
	}, nil
}

func (e *StorageExecutor) executeCreateConstraintContract(ctx context.Context, cypher string, ifNotExists bool) (*ExecuteResult, bool, error) {
	parsed, err := e.parseCreateConstraintContractDDL(cypher)
	if err != nil {
		return nil, false, nil
	}
	return e.createConstraintContractForTarget(ctx, cypher, parsed.name, parsed.entityType, parsed.variable, parsed.labelOrType, parsed.body, ifNotExists)
}

func (e *StorageExecutor) createConstraintContractForTarget(ctx context.Context, definition, name string, entityType storage.ConstraintEntityType, variable, labelOrType, body string, ifNotExists bool) (*ExecuteResult, bool, error) {
	entriesRaw, err := splitConstraintContractEntries(body)
	if err != nil {
		return nil, true, err
	}
	if len(entriesRaw) == 0 {
		return nil, true, localizedError(localization.CypherSchemaContractEntryRequired(), nil)
	}

	contract := storage.ConstraintContract{
		Name:              name,
		TargetEntityType:  string(entityType),
		TargetLabelOrType: labelOrType,
		Definition:        strings.TrimSpace(definition),
		Entries:           make([]storage.ConstraintContractEntry, 0, len(entriesRaw)),
	}
	compiledConstraints := make([]storage.Constraint, 0)
	compiledTypes := make([]storage.PropertyTypeConstraint, 0)

	for idx, rawEntry := range entriesRaw {
		entry, compiledConstraint, compiledType, err := e.parseConstraintContractEntry(rawEntry, variable, entityType, labelOrType, name, idx)
		if err != nil {
			return nil, true, err
		}
		contract.Entries = append(contract.Entries, entry)
		if compiledConstraint != nil {
			compiledConstraints = append(compiledConstraints, *compiledConstraint)
		}
		if compiledType != nil {
			compiledTypes = append(compiledTypes, *compiledType)
		}
	}

	for _, constraint := range compiledConstraints {
		if err := storage.ValidateConstraintOnCreationForEngine(e.storage, constraint); err != nil {
			return nil, true, err
		}
	}
	for _, constraint := range compiledTypes {
		if err := storage.ValidatePropertyTypeConstraintOnCreationForEngine(e.storage, constraint); err != nil {
			return nil, true, err
		}
	}
	if err := storage.ValidateConstraintContractOnCreationForEngine(e.storage, contract); err != nil {
		return nil, true, err
	}
	schema := e.storage.GetSchema()
	newTemporal := make([]storage.Constraint, 0)
	newNames := make([]string, 0, len(compiledConstraints))
	for _, constraint := range compiledConstraints {
		if schema.HasConstraintNamed(constraint.Name) {
			continue
		}
		newNames = append(newNames, constraint.Name)
		if constraint.Type == storage.ConstraintTemporal {
			newTemporal = append(newTemporal, constraint)
		}
	}
	if err := schema.AddConstraintContractBundle(contract, compiledConstraints, compiledTypes, ifNotExists); err != nil {
		return nil, true, err
	}
	// See addSchemaConstraint: new temporal entries are authoritative on an
	// empty label (#1126).
	if err := storage.MarkNewTemporalConstraintsForEngine(e.storage, schema, newTemporal); err != nil {
		return nil, true, err
	}
	// Fill the equality indexes the contract's UNIQUE / NODE KEY entries own,
	// as a standalone constraint's DDL does (addSchemaConstraint): until an
	// owned index is filled, validation and seeks fall back to scanning the
	// label.
	for _, name := range newNames {
		if index, owned := schema.ConstraintPropertyIndex(name); owned {
			if err := e.backfillCompositeIndex(index.Name, index.Label, index.Properties); err != nil {
				return nil, true, err
			}
		}
	}
	// Like a standalone UNIQUE constraint, a contract's IS UNIQUE entries need
	// their value cache built and marked complete; without it every write to
	// the label falls back to scanning all of its nodes (#1120).
	if err := storage.RefreshUniqueConstraintValuesForConstraintsForEngine(e.storage, schema, compiledConstraints); err != nil {
		return nil, true, err
	}

	return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, true, nil
}

func splitConstraintContractEntries(body string) ([]string, error) {
	entries := make([]string, 0)
	var current strings.Builder
	braceDepth := 0
	bracketDepth := 0
	parenDepth := 0

	flush := func() {
		entry := strings.TrimSpace(current.String())
		if entry != "" {
			entries = append(entries, entry)
		}
		current.Reset()
	}

	for index := 0; index < len(body); index++ {
		if end, skipped := skipCypherLexicalToken(body, index); skipped {
			current.WriteString(body[index:end])
			index = end - 1
			continue
		}
		ch := body[index]
		switch {
		case ch == '{':
			braceDepth++
			current.WriteByte(ch)
		case ch == '}':
			if braceDepth == 0 {
				return nil, localizedError(localization.CypherSchemaMalformedRequireBlock(), nil)
			}
			braceDepth--
			current.WriteByte(ch)
		case ch == '[':
			bracketDepth++
			current.WriteByte(ch)
		case ch == ']':
			if bracketDepth > 0 {
				bracketDepth--
			}
			current.WriteByte(ch)
		case ch == '(':
			parenDepth++
			current.WriteByte(ch)
		case ch == ')':
			if parenDepth > 0 {
				parenDepth--
			}
			current.WriteByte(ch)
		case ch == '\n' || ch == ';':
			if braceDepth == 0 && bracketDepth == 0 && parenDepth == 0 {
				flush()
				continue
			}
			current.WriteByte(ch)
		default:
			current.WriteByte(ch)
		}
	}
	if braceDepth != 0 || bracketDepth != 0 || parenDepth != 0 {
		return nil, localizedError(localization.CypherSchemaMalformedRequireBlock(), nil)
	}
	flush()
	return entries, nil
}

func isNestedConstraintContractEntry(entryText string) bool {
	trimmed := strings.TrimSpace(entryText)
	if !matchKeywordAt(trimmed, 0, "FOR") {
		return false
	}
	return hasKeywordFollowedByBrace(trimmed, "REQUIRE")
}

func nestedConstraintContractEntryError(entryText string) error {
	return localizedError(localization.CypherSchemaNestedContractEntryUnsupported(strings.TrimSpace(entryText)), nil)
}

func (e *StorageExecutor) parseConstraintContractEntry(rawEntry, variable string, entityType storage.ConstraintEntityType, labelOrType, contractName string, index int) (storage.ConstraintContractEntry, *storage.Constraint, *storage.PropertyTypeConstraint, error) {
	entryText := strings.TrimSpace(rawEntry)
	if isNestedConstraintContractEntry(entryText) {
		return storage.ConstraintContractEntry{}, nil, nil, nestedConstraintContractEntryError(entryText)
	}

	entryName := storage.ConstraintContractEntryName(contractName, index)
	if compiledConstraint, contractEntry, ok, err := e.parseConstraintContractPrimitive(entryText, variable, entityType, labelOrType, entryName); ok || err != nil {
		return contractEntry, compiledConstraint, nil, err
	}
	if compiledType, contractEntry, ok, err := e.parseConstraintContractPropertyType(entryText, variable, entityType, labelOrType, entryName); ok || err != nil {
		return contractEntry, nil, compiledType, err
	}

	kind := storage.ConstraintContractKindBooleanNode
	if entityType == storage.ConstraintEntityRelationship {
		kind = storage.ConstraintContractKindBooleanRelationship
	}
	return storage.ConstraintContractEntry{Kind: kind, Expression: entryText}, nil, nil, nil
}

func (e *StorageExecutor) parseConstraintContractPrimitive(entryText, variable string, entityType storage.ConstraintEntityType, labelOrType, entryName string) (*storage.Constraint, storage.ConstraintContractEntry, bool, error) {
	if kind, property, ok := parseConstraintPredicate(entryText); ok {
		if kind == "unique" {
			constraint := &storage.Constraint{Name: entryName, Type: storage.ConstraintUnique, EntityType: entityType, Label: labelOrType, Properties: []string{property}}
			primitiveKind := storage.ConstraintContractKindPrimitiveNode
			if entityType == storage.ConstraintEntityRelationship {
				primitiveKind = storage.ConstraintContractKindPrimitiveRelationship
			}
			return constraint, storage.ConstraintContractEntry{Kind: primitiveKind, PrimitiveType: string(storage.ConstraintUnique), Property: property, Properties: []string{property}, Expression: entryText}, true, nil
		}
		if kind == "exists" {
			constraint := &storage.Constraint{Name: entryName, Type: storage.ConstraintExists, EntityType: entityType, Label: labelOrType, Properties: []string{property}}
			primitiveKind := storage.ConstraintContractKindPrimitiveNode
			if entityType == storage.ConstraintEntityRelationship {
				primitiveKind = storage.ConstraintContractKindPrimitiveRelationship
			}
			return constraint, storage.ConstraintContractEntry{Kind: primitiveKind, PrimitiveType: string(storage.ConstraintExists), Property: property, Properties: []string{property}, Expression: entryText}, true, nil
		}
	}

	if entityType == storage.ConstraintEntityNode {
		if properties, ok := e.parseNodeKeyPropertyList(entryText); ok {
			if len(properties) == 0 {
				return nil, storage.ConstraintContractEntry{}, true, localizedError(localization.CypherSchemaConstraintPropertiesRequired("NODE KEY"), nil)
			}
			constraint := &storage.Constraint{Name: entryName, Type: storage.ConstraintNodeKey, EntityType: entityType, Label: labelOrType, Properties: properties}
			return constraint, storage.ConstraintContractEntry{Kind: storage.ConstraintContractKindPrimitiveNode, PrimitiveType: string(storage.ConstraintNodeKey), Properties: properties, Expression: entryText}, true, nil
		}
		if properties, ok := e.parseTemporalConstraintPredicate(entryText); ok {
			if len(properties) < 3 {
				return nil, storage.ConstraintContractEntry{}, true, localizedError(localization.CypherSchemaTemporalNodeArityRequired(), nil)
			}
			constraint := &storage.Constraint{Name: entryName, Type: storage.ConstraintTemporal, EntityType: entityType, Label: labelOrType, Properties: properties}
			return constraint, storage.ConstraintContractEntry{Kind: storage.ConstraintContractKindPrimitiveNode, PrimitiveType: string(storage.ConstraintTemporal), Properties: properties, Expression: entryText}, true, nil
		}
	}

	if entityType == storage.ConstraintEntityRelationship {
		inside, rest, ok := extractParenSection(strings.TrimSpace(entryText))
		if ok {
			rest = strings.TrimSpace(rest)
			if idx := keywordIndexFrom(rest, "IS RELATIONSHIP KEY", 0, defaultKeywordScanOpts()); idx == 0 {
				end, spanOK := keywordSpanAt(rest, 0, "IS RELATIONSHIP KEY")
				if spanOK && strings.TrimSpace(rest[end:]) == "" {
					properties := e.parseConstraintProperties(inside)
					if len(properties) == 0 {
						return nil, storage.ConstraintContractEntry{}, true, localizedError(localization.CypherSchemaConstraintPropertiesRequired("RELATIONSHIP KEY"), nil)
					}
					constraint := &storage.Constraint{Name: entryName, Type: storage.ConstraintRelationshipKey, EntityType: entityType, Label: labelOrType, Properties: properties}
					return constraint, storage.ConstraintContractEntry{Kind: storage.ConstraintContractKindPrimitiveRelationship, PrimitiveType: string(storage.ConstraintRelationshipKey), Properties: properties, Expression: entryText}, true, nil
				}
			}
		}
	}

	return nil, storage.ConstraintContractEntry{}, false, nil
}

func (e *StorageExecutor) parseConstraintContractPropertyType(entryText, variable string, entityType storage.ConstraintEntityType, labelOrType, entryName string) (*storage.PropertyTypeConstraint, storage.ConstraintContractEntry, bool, error) {
	property, typeName, ok := parseConstraintTypePredicate(entryText)
	if !ok {
		return nil, storage.ConstraintContractEntry{}, false, nil
	}
	expectedType, err := parsePropertyType(typeName)
	if err != nil {
		return nil, storage.ConstraintContractEntry{}, true, err
	}
	kind := storage.ConstraintContractKindPrimitiveNode
	if entityType == storage.ConstraintEntityRelationship {
		kind = storage.ConstraintContractKindPrimitiveRelationship
	}
	constraint := &storage.PropertyTypeConstraint{Name: entryName, EntityType: entityType, Label: labelOrType, Property: property, ExpectedType: expectedType}
	return constraint, storage.ConstraintContractEntry{Kind: kind, PrimitiveType: string(storage.ConstraintPropertyType), Property: property, Properties: []string{property}, ExpectedType: string(expectedType), Expression: entryText}, true, nil
}

package cypher

import (
	"context"

	"github.com/orneryd/nornicdb/pkg/storage"
)

func isOrdinarySchemaDDL(query string) bool {
	for _, command := range []string{"INDEX", "RANGE INDEX", "TEXT INDEX", "POINT INDEX", "VECTOR INDEX", "FULLTEXT INDEX", "LOOKUP INDEX", "CONSTRAINT"} {
		if startsWithKeywords(query, "CREATE", command) {
			return true
		}
	}
	return startsWithKeywords(query, "DROP", "INDEX") || startsWithKeywords(query, "DROP", "CONSTRAINT")
}

func (e *StorageExecutor) prepareSchemaTransaction(ctx context.Context) error {
	wrapper, ok := e.getStorage(ctx).(*transactionStorageWrapper)
	if !ok {
		return nil
	}
	if err := wrapper.tx.SetNamespace(e.currentDatabaseName()); err != nil {
		return err
	}
	view, err := wrapper.tx.Schema()
	if err != nil {
		return err
	}
	wrapper.schema = view
	return nil
}

func (e *StorageExecutor) afterSchemaCommit(ctx context.Context, action func()) {
	if wrapper, ok := e.getStorage(ctx).(*transactionStorageWrapper); ok && wrapper.schema != nil {
		wrapper.schemaCommitActions = append(wrapper.schemaCommitActions, action)
		return
	}
	action()
}

func (e *StorageExecutor) mutateSchema(ctx context.Context, mutation func(*storage.SchemaManager) error) error {
	if err := e.prepareSchemaTransaction(ctx); err != nil {
		return err
	}
	schema := e.getStorage(ctx).GetSchema()
	release := schema.LockSchemaMutation()
	defer release()
	if err := mutation(schema); err != nil {
		return err
	}
	if wrapper, ok := e.getStorage(ctx).(*transactionStorageWrapper); ok {
		return wrapper.tx.StageSchemaChanges()
	}
	return nil
}

package cypher

import (
	"context"
	"github.com/orneryd/nornicdb/internal/collection"
	"sort"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
)

// db.schema.nodeTypeProperties() and db.schema.relTypeProperties() list
// the property schema derived from the data, as Neo4j does: one row per
// node category (its exact label set) or relationship type and property,
// with every type the property has there and whether every node or
// relationship of the category has it. A category whose members have no
// properties gets one row with a null property. Property types are named
// as Neo4j 5.26 names them in a Cypher 5 statement (Long, StringArray) and
// as Neo4j 2026.09 does in a Cypher 25 statement (INTEGER NOT NULL,
// LIST<STRING NOT NULL> NOT NULL). Neo4j's row and type order is its hash
// order; NornicDB sorts both.

func schemaTypePropertiesProcedureSpec(name string, nodes bool) ProcedureSpec {
	description := localization.CypherProcedureMetadata(name)
	spec := ProcedureSpec{
		Name:               name,
		Description:        description.Fallback,
		DescriptionMessage: description,
		Mode:               ProcedureModeRead,
		WorksOnSystem:      true,
	}
	if nodes {
		spec.Signature = name + "() :: (nodeType :: STRING, nodeLabels :: LIST<STRING>, propertyName :: STRING, propertyTypes :: LIST<STRING>, mandatory :: BOOLEAN)"
		spec.Returns = []ProcedureColumn{
			{Name: "nodeType", Type: "STRING", Description: "A name generated from the labels on the node."},
			{Name: "nodeLabels", Type: "LIST<STRING>", Description: "A list containing the labels on a category of node."},
			{Name: "propertyName", Type: "STRING", Description: "A property key on a category of node."},
			{Name: "propertyTypes", Type: "LIST<STRING>", Description: "All types of a property belonging to a node category."},
			{Name: "mandatory", Type: "BOOLEAN", Description: "Whether or not the property is present on all nodes belonging to a node category."},
		}
		return spec
	}
	spec.Signature = name + "() :: (relType :: STRING, propertyName :: STRING, propertyTypes :: LIST<STRING>, mandatory :: BOOLEAN)"
	spec.Returns = []ProcedureColumn{
		{Name: "relType", Type: "STRING", Description: "A name generated from the type on the relationship."},
		{Name: "propertyName", Type: "STRING", Description: "A property key on a category of relationship."},
		{Name: "propertyTypes", Type: "LIST<STRING>", Description: "All types of a property belonging to a relationship category."},
		{Name: "mandatory", Type: "BOOLEAN", Description: "Whether or not the property is present on all relationships belonging to a relationship category."},
	}
	return spec
}

// schemaTypeCategory is one node category or relationship type: how many
// members it has and, per property, how many have it and its type names.
type schemaTypeCategory struct {
	labels     []string
	members    int
	properties map[string]*schemaTypeProperty
}

type schemaTypeProperty struct {
	members int
	types   map[string]bool
}

func (category *schemaTypeCategory) add(properties map[string]interface{}, cypher25 bool) {
	category.members++
	for name, value := range properties {
		property := category.properties[name]
		if property == nil {
			property = &schemaTypeProperty{types: make(map[string]bool, 1)}
			category.properties[name] = property
		}
		property.members++
		property.types[schemaPropertyTypeName(value, cypher25)] = true
	}
}

// callDbSchemaTypeProperties is db.schema.nodeTypeProperties() (nodes) or
// db.schema.relTypeProperties().
func (e *StorageExecutor) callDbSchemaTypeProperties(ctx context.Context, nodes bool) (*ExecuteResult, error) {
	cypher25 := cypherVersionFromContext(ctx) == "25"
	categories := make(map[string]*schemaTypeCategory)
	category := func(key string, labels []string) *schemaTypeCategory {
		found := categories[key]
		if found == nil {
			found = &schemaTypeCategory{labels: labels, properties: make(map[string]*schemaTypeProperty)}
			categories[key] = found
		}
		return found
	}
	if nodes {
		all, err := e.storage.AllNodes()
		if err != nil {
			return nil, err
		}
		for _, node := range all {
			labels := append([]string(nil), node.Labels...)
			sort.Strings(labels)
			category(schemaTypeKey(labels), labels).add(node.Properties, cypher25)
		}
	} else {
		all, err := e.storage.AllEdges()
		if err != nil {
			return nil, err
		}
		for _, edge := range all {
			category(schemaTypeKey([]string{edge.Type}), nil).add(edge.Properties, cypher25)
		}
	}

	keys := make([]string, 0, len(categories))
	for key := range categories {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	result := &ExecuteResult{Columns: []string{"relType", "propertyName", "propertyTypes", "mandatory"}, Rows: [][]interface{}{}}
	if nodes {
		result.Columns = []string{"nodeType", "nodeLabels", "propertyName", "propertyTypes", "mandatory"}
	}
	for _, key := range keys {
		found := categories[key]
		head := []interface{}{key}
		if nodes {
			head = append(head, append([]string{}, found.labels...))
		}
		if len(found.properties) == 0 {
			result.Rows = append(result.Rows, append(head, nil, nil, false))
			continue
		}
		names := make([]string, 0, len(found.properties))
		for name := range found.properties {
			names = append(names, name)
		}
		sort.Strings(names)
		for _, name := range names {
			property := found.properties[name]
			row := append(append([]interface{}(nil), head...), name, collection.SortedKeys(property.types), property.members == found.members)
			result.Rows = append(result.Rows, row)
		}
	}
	return result, nil
}

// schemaTypeKey is a category's name: each label or type backtick-quoted
// after a colon (:`A`:`B`), "" for nodes without labels.
func schemaTypeKey(names []string) string {
	var key strings.Builder
	for _, name := range names {
		key.WriteString(":" + quoteSchemaName(name))
	}
	return key.String()
}

// schemaPropertyTypeName names a stored property value's type as
// db.schema.*TypeProperties lists it: Neo4j 5.26's names in a Cypher 5
// statement (Long, Double, DateTime, LongArray; an empty list is a
// StringArray), Neo4j 2026.09's in a Cypher 25 one (INTEGER NOT NULL,
// ZONED DATETIME NOT NULL, LIST<INTEGER NOT NULL> NOT NULL; an empty list
// is LIST<NOTHING> NOT NULL). A list of integers and floats is a float
// list, as Neo4j stores it.
func schemaPropertyTypeName(value interface{}, cypher25 bool) string {
	kind := cypherValueKindOf(value)
	if kind != valueKindList {
		if cypher25 {
			return valueTypeNames[kind].typeSystem + " NOT NULL"
		}
		return valueTypeNames[kind].runtime
	}
	element, known := valueKindOther, false
	for _, item := range toAnySlice(value) {
		itemKind := cypherValueKindOf(item)
		switch {
		case !known:
			element, known = itemKind, true
		case element == valueKindInteger && itemKind == valueKindFloat:
			element = valueKindFloat
		}
	}
	switch {
	case cypher25 && !known:
		return "LIST<NOTHING> NOT NULL"
	case cypher25:
		return "LIST<" + valueTypeNames[element].typeSystem + " NOT NULL> NOT NULL"
	case !known:
		return "StringArray"
	}
	return valueTypeNames[element].runtime + "Array"
}

package cypher

import (
	"context"
	"fmt"
	"maps"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
)

// semanticBodyScope is the binding value of a CALL/scalar body. entry records
// ordinary body bindings; carried inputs remain readable after WITH. retained
// is the scoped CALL readability fact, separate from current wildcard columns.
// implicit tags #907 fallback imports: readable, but never declarations that
// can conflict with a name introduced by this body. Every declaration producer
// uses declare; consumers must not reconstruct provenance from row keys.
type semanticBodyScope struct {
	entry       typeScope
	carried     typeScope
	retained    typeScope
	original    typeScope
	implicit    typeScope
	caller      typeScope
	headerReads typeScope
	scalar      bool
	bare        bool
	entered     bool
	projected   *semanticBodyScope
	iteration   *semanticBodyScope
}

// A CALL wildcard requires a current body binding. Availability of an unread
// scoped import does not itself supply a wildcard column.
func returnStarScopeError(wildcard bool, columns int) error {
	if !wildcard || columns != 0 {
		return nil
	}
	return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "NoVariablesInScope", localization.CypherMatchingReturnStarNoVariables())
}

func (body *semanticBodyScope) clone(entry typeScope) *semanticBodyScope {
	if body == nil {
		return nil
	}
	return &semanticBodyScope{entry: maps.Clone(entry), carried: maps.Clone(body.carried), retained: maps.Clone(body.retained), original: maps.Clone(body.original), implicit: maps.Clone(body.implicit), caller: maps.Clone(body.caller), headerReads: maps.Clone(body.headerReads), scalar: body.scalar, bare: body.bare, entered: body.entered}
}

// reference records an explicit input read in this body's ordinary scope.
// Readability alone does not contribute columns. Nested scalar reads belong to
// the scalar; #907 weak inputs keep their fallback/declaration contract.
func (body *semanticBodyScope) reference(name string, local typeScope) {
	if body == nil || body.scalar || body.bare {
		return
	}
	if _, current := local[name]; current {
		return
	}
	if operand, imported := body.carried[name]; imported {
		local[name] = operand
	}
}

// A lexical update body adds its iterator without changing the enclosing CALL
// projection or import provenance. Both canonical binding and execution use it.
func (body *semanticBodyScope) localChild(name string) *semanticBodyScope {
	child := body.clone(body.entry)
	if child != nil {
		child.declare(name, child.entry, nil, nil, false)
		child.entry[name] = staticOperand{}
	}
	return child
}

// projection is the current clause membership. Carried scoped imports remain
// readable across WITH but enter this membership only through a direct read.
func (body *semanticBodyScope) projection(local typeScope) typeScope {
	if body == nil {
		return local
	}
	return local
}

// A legacy importing WITH sees the caller's actual projection facts, including
// scoped retained imports, without importing scalar-only readable ancestors.
func (body *semanticBodyScope) legacyCurrent(local typeScope) typeScope {
	return body.projection(local)
}

func (body *semanticBodyScope) visible(local typeScope) typeScope {
	if body == nil {
		return local
	}
	return scopeVisibleTypes(local, body.carried)
}

func (body *semanticBodyScope) strong(local typeScope) typeScope {
	visible := body.visible(local)
	if body == nil || len(body.implicit) == 0 {
		return visible
	}
	strong := maps.Clone(visible)
	for name := range body.implicit {
		delete(strong, name)
	}
	return strong
}

// A scalar expression treats its enclosing values as constants. A CALL is a
// query body: a persistent import remains readable, but is not an implicit
// grouping key in an aggregate projection.
func (body *semanticBodyScope) aggregateConstants() typeScope {
	if body != nil && body.scalar {
		return body.visible(nil)
	}
	return nil
}

// ORDER BY can read a retained scoped import after DISTINCT without making
// that import an implicit grouping key in the aggregate projection itself.
func (body *semanticBodyScope) orderConstants() typeScope {
	if body == nil {
		return nil
	}
	return scopeVisibleTypes(body.aggregateConstants(), body.retained)
}

// declare is the single transition from weak input to a body binding. A prior
// read still requires the outer input at runtime, but cannot make it strong.
// An unscoped CALL declaration is a new local; if WITH drops that local, its
// same-name weak input must not become readable again.
func (body *semanticBodyScope) declare(name string, local typeScope, proof *semanticDependencyScope, result *semanticQueryScope, replaceInput bool) {
	if body != nil {
		if _, weak := body.implicit[name]; weak {
			delete(body.implicit, name)
			delete(body.carried, name)
			delete(body.retained, name)
			delete(body.original, name)
			if replaceInput {
				delete(local, name)
			}

		}
	}
	if proof != nil {
		delete(proof.active, name)
	}
}

// scalarChild preserves strong/weak identity across expression boundaries.
// Its ancestors are readable but do not enter the scalar's RETURN * scope.
func (body *semanticBodyScope) scalarChild(visible typeScope) *semanticBodyScope {
	child := &semanticBodyScope{entry: typeScope{}, carried: maps.Clone(visible), original: maps.Clone(visible), scalar: true}
	if body != nil {
		child.implicit = make(typeScope)
		for name, operand := range body.implicit {
			if _, exists := visible[name]; exists {
				child.implicit[name] = operand
			}
		}
	}
	return child
}

func (body *semanticBodyScope) pattern(name string, kind matchBindingKind, local typeScope, proof *semanticDependencyScope, result *semanticQueryScope) {
	if body != nil {
		if _, weak := body.implicit[name]; weak {
			body.declare(name, local, proof, result, true)
			return
		}
	}
	proof.read(name)
}

func (body *semanticBodyScope) runtimeCurrent(names []string) typeScope {
	if body != nil {
		return maps.Clone(body.entry)
	}
	current := semanticRuntimeInput(names)
	if body != nil && body.scalar {
		for name := range body.carried {
			if _, local := body.entry[name]; !local {
				delete(current, name)
			}
		}
	}
	return current
}

func withSemanticProjectedBody(ctx context.Context) context.Context {
	if body := semanticBodyFromContext(ctx); body != nil && body.projected != nil {
		return withSemanticBodyClause(ctx, body.projected)
	}
	return ctx
}

func (body *semanticBodyScope) project(ctx context.Context, before, after typeScope, clause string) {
	if body == nil {
		return
	}
	visible := body.visible(before)
	carried := maps.Clone(after)
	keyword := "WITH"
	if startsWithKeywordFold(strings.TrimSpace(clause), "RETURN") {
		keyword = "RETURN"
	}
	projection, _ := cutDistinct(projectionSemanticBody(clause, keyword))
	var empty typeScope
	if len(body.original) > 0 && pipelineProjectionHasOnlyAggregates(returnProjectionPlanFor(ctx, "RETURN "+projection).projections) {
		empty = maps.Clone(carried)
		carrySubqueryImports(empty, nil, body.original)
	}
	carrySubqueryImports(carried, visible, body.original)
	for name, operand := range empty {
		carried[name] = joinedOperand(carried[name], operand)
	}
	for name := range body.carried {
		if operand, exists := carried[name]; exists {
			body.carried[name] = operand
			if _, retained := body.retained[name]; retained {
				body.retained[name] = operand
			}
		}
	}
}

func (body *semanticBodyScope) projectionTail(ctx context.Context, merged, projected typeScope, clause string) *semanticBodyScope {
	if body == nil {
		return nil
	}
	tail := body.clone(merged)
	projected.forEachProjectedBinding(ctx, clause, func(name, expression, text string, inherited bool) {
		if !inherited && projectedSourceVariable(expression) != name {
			tail.declare(name, projected, nil, nil, false)
		}
	})
	tail.project(ctx, merged, projected, clause)
	body.projected = tail
	return tail
}

// callBodyScope is the shared import-form constructor for typed validation and
// the canonical statement binder. Neither consumer invents another scope from
// projected columns or runtime row values.
func callBodyScope(names []string, scoped bool, local typeScope, parent *semanticBodyScope, scalarParent bool) (typeScope, *semanticBodyScope, error) {
	outer := parent.visible(local)
	header := outer
	if scalarParent {
		header = local
	}
	imports := make(typeScope)
	if scoped {
		for _, name := range names {
			operand, exists := outer[name]
			if !exists {
				return nil, nil, createUndefinedVariableError(name)
			}
			imports[name] = operand
		}
		if names == nil {
			maps.Copy(imports, header)
		}
	} else {
		// NornicDB extension, diverging from Neo4j: a bare CALL may read
		// outer variables without an import clause. These inputs are weak;
		// a new local declaration shadows one and ordinary WITH can drop it.
		maps.Copy(imports, outer)
	}
	initial := maps.Clone(imports)
	if scoped {
		initial = typeScope{}
	}
	body := &semanticBodyScope{entry: initial, carried: maps.Clone(imports), original: maps.Clone(imports), caller: maps.Clone(parent.legacyCurrent(local)), bare: !scoped}
	if !scoped {
		body.implicit = maps.Clone(imports)
	} else {
		body.retained = maps.Clone(imports)
	}
	return imports, body, nil
}

// branchEntry is the per-import-form transition shared by every UNION branch.
// A leading importing WITH creates ordinary locals; only unselected caller
// locals retain #907 weak fallback. Scalar-only ancestors require a name.
func (body *semanticBodyScope) branchEntry(ctx context.Context, clauses []pipelineClause, branchIndex int, initial typeScope) (typeScope, error) {
	if body == nil || body.entered {
		return initial, nil
	}
	// Clause snapshots already passed this transition. Recompiling a fragment
	// must not reinterpret a later UNION branch as a new first branch.
	body.entered = true
	if !body.bare || len(clauses) == 0 || clauses[0].kind != pipelineClauseWith {
		return initial, nil
	}
	imports, importing := callWithImports(ctx, clauses[0].text, body.caller, initial)
	if !importing {
		return initial, nil
	}
	body.headerReads = maps.Clone(imports)
	projection, tail := projectionSemanticBodyAndTail(clauses[0].text, "WITH")
	if branchIndex == 0 && (strings.TrimSpace(tail) != "" || topLevelKeywordIndex(projection, "AS") >= 0) {
		return nil, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidVariableImport", localization.CypherSubqueriesWithImportExpressionInvalid(projection))
	}
	if len(clauses) == 1 {
		return nil, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", localization.CypherSubqueriesWithQueryClauseRequired())
	}
	for name := range body.carried {
		_, local := body.caller[name]
		_, selected := imports[name]
		if !local || selected {
			delete(body.carried, name)
			delete(body.implicit, name)
		}
	}
	return imports, nil
}

type semanticBodyScopeKey struct{}
type semanticBodyInputKey struct{}

func semanticBodyFromContext(ctx context.Context) *semanticBodyScope {
	body, _ := ctx.Value(semanticBodyScopeKey{}).(*semanticBodyScope)
	return body
}

// Runtime consumes the immutable clause scope produced by the owner. Values
// stay request-local; neither the scope nor any cache stores a row value.
func withSemanticBodyClause(ctx context.Context, body *semanticBodyScope) context.Context {
	if body == nil {
		return ctx
	}
	ctx = context.WithValue(ctx, semanticBodyScopeKey{}, body)
	input, supplied := ctx.Value(semanticBodyInputKey{}).(pipelineRow)
	if !supplied {
		return ctx
	}
	carried := make(pipelineRow, len(body.carried))
	for name := range body.carried {
		if value, exists := input[name]; exists {
			carried[name] = value
		}
	}
	return withPipelineImports(ctx, carried)
}

// These transitions are the only writers of the body's current membership.
func (body *semanticBodyScope) bindCurrent(name string, operand staticOperand) {
	body.entry[name] = operand
}
func (body *semanticBodyScope) replaceCurrent(current typeScope) { body.entry = maps.Clone(current) }

// A nested export that preserves binding identity is a read/pass-through,
// rather than a declaration shadowing the caller's same-name weak candidate.
func (body *semanticBodyScope) export(name string, local typeScope, proof *semanticDependencyScope, result *semanticQueryScope, unchanged bool) {
	if !unchanged {
		body.declare(name, local, proof, result, false)
	}
}

// admitExports is shared by typed enrichment and bound identity construction.
// A strong caller binding may only be exported unchanged by every UNION branch.
func (body *semanticBodyScope) admitExports(local typeScope, columns []string, unchanged func(string) bool) error {
	strong := body.strong(local)
	for _, name := range columns {
		if _, bound := strong[name]; bound && !unchanged(name) {
			return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", localization.CypherCoreVariableDeclaredInOuterScope(name))
		}
	}
	return nil
}

// admitDeclaration is the constructor's declaration legality transition.
// Type checking may reject an operand's kind, never admit a new name itself.
func (body *semanticBodyScope) admitDeclaration(name string, form string) error {
	if body == nil {
		return nil
	}
	_, strong := body.strong(body.entry)[name]
	_, ancestor := body.strong(nil)[name]
	if body.scalar && ancestor {
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", localization.CypherCoreVariableDeclaredInOuterScope(name))
	}
	if form == "FOR" && body.readable(name, body.entry) || form == "LET" && strong {
		return newSemanticError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", "variable "+name+" is already declared")
	}
	if form == "YIELD" && strong {
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", localization.CypherCoreProcedureOutputShadowsVariable(name))
	}
	return nil
}

// Pattern declarations use the same strong/weak admission input as every
// other declaration form. Entity-kind compatibility is a later operand rule.
func (body *semanticBodyScope) admitPatternDeclarations(ctx context.Context, clause pipelineClause) error {
	strong := body.strong(body.entry)
	pattern := strings.TrimSpace(clause.text)
	for _, keyword := range []string{"OPTIONAL MATCH", "MATCH"} {
		if startsWithKeywordFold(pattern, keyword) {
			pattern = strings.TrimSpace(pattern[len(keyword):])
			break
		}
	}
	pattern = matchPatternStructure(pattern)
	nodes, relationships := quantifiedGroupVariables(pattern)
	for _, names := range []map[string]struct{}{nodes, relationships} {
		for name := range names {
			if _, bound := strong[name]; bound {
				return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", localization.CypherMatchingQuantifiedPathVariableBound(name))
			}
		}
	}
	for _, part := range splitTopLevelComma(pattern) {
		path := extractPathAssignmentVariable(strings.TrimSpace(part))
		if path == "" {
			continue
		}
		if _, bound := strong[path]; bound {
			return newSemanticError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", fmt.Sprintf("path variable %s is already bound", path))
		}
		entity := part
		if equals := strings.Index(part, "="); equals >= 0 {
			entity = part[equals+1:]
		}
		for _, name := range append(extractNodeVariables(entity), extractRelationshipVariables(entity)...) {
			if normalizeProjectionColumnName(name) == path {
				return newSemanticError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", fmt.Sprintf("path variable %s is already bound", path))
			}
		}
	}
	return nil
}

package cypher

import (
	"context"

	cypherantlr "github.com/orneryd/nornicdb/pkg/cypher/antlr"
	"github.com/orneryd/nornicdb/pkg/cypher/resultmetadata"
)

// The statement binder observes its retained CST through the same body scope
// value as typed validation. This adapter performs no type walk or execution.
func bindingTypes(names map[string]struct{}) typeScope {
	types := make(typeScope, len(names))
	for name := range names {
		types[name] = staticOperand{}
	}
	return types
}

func bindingNames(types typeScope) map[string]struct{} {
	names := make(map[string]struct{}, len(types))
	for name := range types {
		names[name] = struct{}{}
	}
	return names
}

// Body constructors are immutable inputs; each branch clones them before
// applying transitions. Rewriting consumes the same lexical/tail/LET frame
// that statement binding constructs instead of guessing from keyword text.
func (compilation *boundCompilation) scopeFrame(start int, frame *semanticBodyScope) {
	if compilation.product.frames == nil {
		compilation.product.frames = make(map[int]*semanticBodyScope)
	}
	compilation.product.frames[start] = frame
}

func (compilation *boundCompilation) enterBodyScope(ctx context.Context, branch *boundBranch, index int) error {
	if branch.body.bindings == nil {
		return nil
	}
	branch.bindings = branch.body.bindings.clone(branch.body.bindings.entry)
	branch.dependencies = branch.body.dependencies.nested()
	clauses := make([]pipelineClause, len(branch.shape.clauses))
	for index, clause := range branch.shape.clauses {
		clauses[index] = clause.pipelineClause
	}
	entry, err := branch.bindings.branchEntry(ctx, clauses, index, branch.bindings.entry)
	if err != nil {
		return err
	}
	branch.bindings.replaceCurrent(entry)
	branch.scope = bindingNames(branch.bindings.visible(entry))
	identities := make(map[string]statementBindingID, len(branch.scope))
	for name := range branch.scope {
		if identity, found := branch.seed.ids[name]; found {
			identities[name] = identity
		}
	}
	branch.dependencies.identities = identities
	compilation.scopeFrame(branch.shape.start, branch.bindings.clone(entry))
	branch.input = boundBranchInput{incoming: projectedMapNames(branch.scope), retained: projectedMapNames(bindingNames(branch.bindings.carried)), ids: identities, frame: branch.bindings.clone(entry)}
	return nil
}

func (compilation *boundCompilation) beginBodyClause(ctx context.Context, clause *boundClause) {
	body := clause.branch.bindings
	if body == nil {
		return
	}
	source := clause.source
	switch source.kind {
	case pipelineClauseMatch, pipelineClauseOptionalMatch, pipelineClauseCreate, pipelineClauseMerge:
		clause.fresh = make(map[string]bool)
		syntaxPatternDefinitions(source.syntax, func(_ int, symbol cypherantlr.SyntaxNode) {
			name := syntaxSymbolName(symbol)
			_, weak := body.implicit[name]
			clause.fresh[name] = weak
			body.pattern(name, matchBindingUnknown, body.entry, nil, nil)
		})
	}
	body.readClause(ctx, source.pipelineClause, body.entry, nil)

	clause.branch.scope = bindingNames(body.visible(body.entry))
}

func (compilation *boundCompilation) finishBodyClause(ctx context.Context, clause *boundClause) {
	body := clause.branch.bindings
	if body == nil {
		return
	}
	proof := clause.branch.dependencies
	declare := func(name string) {
		body.declare(name, body.entry, proof, nil, false)
		body.bindCurrent(name, staticOperand{})
	}
	switch clause.source.kind {
	case pipelineClauseWith, pipelineClauseReturn:
		if clause.plan != nil {
			for _, item := range clause.plan.projections {
				if !item.direct || item.variable != item.alias {
					body.declare(item.alias, body.entry, proof, nil, false)
				}
			}
			after := bindingTypes(clause.localProjection)
			body.project(ctx, body.entry, after, clause.source.text)
			body.replaceCurrent(after)
		}
	case pipelineClauseMatch, pipelineClauseOptionalMatch, pipelineClauseCreate, pipelineClauseMerge:
		syntaxPatternDefinitions(clause.source.syntax, func(_ int, symbol cypherantlr.SyntaxNode) {
			body.bindCurrent(syntaxSymbolName(symbol), staticOperand{})
		})
	case pipelineClauseUnwind:
		declare(syntaxSymbolName(clause.source.syntax.ChildRule(cypherantlr.CypherParserRULE_symbol)))
	case pipelineClauseCallSubquery:
		for _, branch := range clause.body.branches {
			for name := range branch.bindings.headerReads {
				body.reference(name, body.entry)
			}
		}
		for name := range projectedNameMap(clause.outputs) {
			body.export(name, body.entry, proof, nil, clause.beforeIDs[name] != 0 && clause.afterIDs[name] == clause.beforeIDs[name])
			body.bindCurrent(name, staticOperand{})
		}
	case pipelineClauseCall:
		for name := range projectedNameMap(clause.outputs) {
			declare(name)
		}
	}
	if clause.source.kind == pipelineClauseReturn {
		clause.after = projectedNameMap(clause.outputs)
	} else {
		clause.after = bindingNames(body.visible(body.entry))
	}
}

func (branch *boundBranch) freezeInput() {
	frame := branch.input.frame
	incoming, retained := bindingNames(frame.visible(frame.entry)), bindingNames(frame.carried)
	if frame.bare {
		for name := range incoming {
			if !branch.dependencies.reads[name] {
				delete(incoming, name)
			}
		}
		for name := range retained {
			if !branch.dependencies.reads[name] {
				delete(retained, name)
			}
		}
	}
	branch.input = boundBranchInput{incoming: projectedMapNames(incoming), retained: projectedMapNames(retained), ids: cloneBindingIDs(branch.input.ids), frame: frame}
	branch.statement.Incoming = boundBindingScope(branch.input.incoming, branch.input.ids)
	branch.statement.Retained = boundBindingScope(branch.input.retained, branch.input.ids)
}

// horizon is a detached projection of the transition owner's state, with the
// identity of the current value kept distinct from an entry dependency.
func (body *semanticBodyScope) horizon(ids, entryIDs map[string]statementBindingID, proof *semanticDependencyScope) *resultmetadata.BindingHorizon {
	dependencies := map[string]struct{}{}
	if proof != nil {
		for name := range proof.reads {
			dependencies[name] = struct{}{}
		}
	}
	return &resultmetadata.BindingHorizon{
		Readable:     boundBindingScope(projectedMapNames(bindingNames(body.visible(body.entry))), ids),
		Current:      boundBindingScope(projectedMapNames(bindingNames(body.entry)), ids),
		Retained:     boundBindingScope(projectedMapNames(bindingNames(body.retained)), ids),
		Weak:         boundBindingScope(projectedMapNames(bindingNames(body.implicit)), ids),
		Dependencies: boundBindingScope(projectedMapNames(dependencies), entryIDs),
	}
}

package cypher

import (
	"fmt"
	"strings"

	nornicerrors "github.com/orneryd/nornicdb/pkg/errors"
)

// SemanticError describes a Cypher validation failure that must retain its
// Neo4j-compatible Bolt classification and conformance detail.
type SemanticError struct {
	Code    string
	Detail  string
	Message string
}

// classifiedCypherError adds Neo4j/TCK classification to an existing typed
// error without changing its localized message or unwrap identity.
type classifiedCypherError struct {
	cause  error
	code   string
	detail string
}

func (e *classifiedCypherError) Error() string           { return e.cause.Error() }
func (e *classifiedCypherError) Unwrap() error           { return e.cause }
func (e *classifiedCypherError) BoltErrorCode() string   { return e.code }
func (e *classifiedCypherError) BoltErrorDetail() string { return e.detail }

// Error formats the error so non-Bolt callers retain the Neo4j status code.
func (e *SemanticError) Error() string {
	if e == nil {
		return "<nil>"
	}
	return fmt.Sprintf("%s: %s", e.Code, e.Message)
}

// BoltErrorCode returns the Neo4j-compatible Bolt error code.
func (e *SemanticError) BoltErrorCode() string { return e.Code }

// BoltErrorDetail returns the openCypher conformance error detail.
func (e *SemanticError) BoltErrorDetail() string { return e.Detail }

func invalidBooleanOperandError(value interface{}) error {
	return &SemanticError{
		Code:    "Neo.ClientError.Statement.SyntaxError",
		Detail:  "InvalidArgumentType",
		Message: fmt.Sprintf("boolean operator requires BOOLEAN or NULL operands, got %T", value),
	}
}

// procedureCallFailedError is Neo4j's Procedure.ProcedureCallFailed: a
// procedure failed while running, with a cause that carries no status of its
// own (#657).
type procedureCallFailedError struct {
	procedure string
	cause     error
}

func (e *procedureCallFailedError) Error() string {
	return fmt.Sprintf("Failed to invoke procedure `%s`: Caused by: %s", e.procedure, e.cause.Error())
}
func (e *procedureCallFailedError) Unwrap() error { return e.cause }
func (e *procedureCallFailedError) BoltErrorCode() string {
	return "Neo.ClientError.Procedure.ProcedureCallFailed"
}

// procedureRuntimeError is the error of procedure failing while running with
// err: ProcedureCallFailed, as in Neo4j, unless err carries its own status
// (a Cypher error of a statement the procedure ran, a transient failure, ...).
// Every CALL dispatch reports procedure failures through it.
func procedureRuntimeError(procedure string, err error) error {
	if nornicerrors.HasNeo4jStatus(err) {
		return err
	}
	return &procedureCallFailedError{procedure: procedure, cause: err}
}

func newSemanticError(code, detail, message string) error {
	return &SemanticError{Code: code, Detail: detail, Message: message}
}

// syntaxAdmissionError retains specific pattern diagnostics at grammar admission.
func syntaxAdmissionError(source string, cause error) error {
	if invalidRelationshipPattern(source) {
		return newSemanticError("Neo.ClientError.Statement.SyntaxError", "InvalidRelationshipPattern", "invalid variable-length relationship pattern")
	}
	message := strings.ReplaceAll(cause.Error(), "mismatched input ", "Invalid input ")
	message = strings.ReplaceAll(message, "extraneous input ", "Invalid input ")
	return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", message)
}

// invalidForeachError classifies malformed updates and invalid runtime list
// operands, returning a fresh mutable SemanticError for each rejected statement.
func invalidForeachError() error {
	return newSemanticError("Neo.ClientError.Statement.SyntaxError", "InvalidForeach", "invalid or unsupported FOREACH update")
}

package cypher

import (
	"context"
	"maps"
)

// Mutation rules consume the admitted clause's incoming bindings. They do not
// maintain another transfer walk that can omit CALL or procedure exports.
func (e *StorageExecutor) boundMutationClauses(ctx context.Context, query string, cypher25 bool) ([]pipelineClause, error) {
	clauses, ok := splitPipelineClausesAllowingProcedureCalls(ctx, query)
	if !ok {
		return nil, nil
	}
	program := e.statementProjectionProgram(ctx, query, e.resultIncomingScope(), cypher25, e.participantSchemaForStatement(ctx, query))
	if !program.complete {
		if program.err != nil {
			return nil, program.err
		}
		return nil, unresolvedStatementError()
	}
	if program.bound == nil {
		return nil, nil
	}
	for index := range clauses {
		if step, exists := program.bound.scopes[clauses[index].syntax.ID()]; exists {
			step.Before.Visit(func(names []string) {
				clauses[index].validationScope = make(map[string]struct{}, len(names))
				for _, name := range names {
					clauses[index].validationScope[name] = struct{}{}
				}
			}, func() {})
		}
	}
	return clauses, nil
}

func clauseBindingScope(clause pipelineClause, fallback *semanticBindingScope) *semanticBindingScope {
	if clause.validationScope != nil {
		return &semanticBindingScope{names: maps.Clone(clause.validationScope)}
	}
	if fallback != nil {
		return fallback
	}
	return newSemanticBindingScope()
}

package cypher

import (
	"context"
	"maps"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
)

// semanticDependencyScope records reads in the canonical constructor. active names
// still denote the input binding; a declaration or a dropping WITH removes
// that provenance. Nested walks share reads, never their mutable local scope.
type semanticDependencyScope struct {
	identities map[string]statementBindingID
	active     map[string]bool
	reads      map[string]bool
	parent     *semanticDependencyScope
	complete   bool
}

func newSemanticDependencies(input typeScope) *semanticDependencyScope {
	proof := &semanticDependencyScope{active: make(map[string]bool, len(input)), reads: make(map[string]bool), complete: true}
	for name := range input {
		proof.active[name] = true
	}
	return proof
}

func (proof *semanticDependencyScope) nested() *semanticDependencyScope {
	if proof == nil {
		return nil
	}
	return &semanticDependencyScope{identities: proof.identities, active: maps.Clone(proof.active), reads: make(map[string]bool), parent: proof, complete: proof.complete}
}

func (proof *semanticDependencyScope) read(name string) {
	if proof == nil {
		return
	}
	proof.readIdentity(name, proof.identities[name])
}

func (proof *semanticDependencyScope) readIdentity(name string, identity statementBindingID) {
	if proof == nil || !proof.active[name] {
		return
	}
	if proof.identities != nil && proof.identities[name] != identity {
		return
	}
	proof.reads[name] = true
	proof.parent.readIdentity(name, identity)
}

func (proof *semanticDependencyScope) expression(ctx context.Context, expression string) {
	if proof == nil {
		return
	}
	for _, name := range expressionFreeVariables(ctx, expression) {
		proof.read(name)
	}
}

func (proof *semanticDependencyScope) incomplete() {
	if proof != nil {
		proof.complete = false
		proof.parent.incomplete()
	}
}

// semanticQueryScope is a read-only typed view of an admitted body. Physical consumers
// use imports and projection clauses from this result; rows do not establish
// which names exist. A partial walk never proves an input can be omitted.
type semanticQueryScope struct {
	query    string
	clauses  []pipelineClause
	branches []*semanticQueryScope
	columns  []string
	returned typeScope
	imports  typeScope
	bindings *semanticBodyScope
	complete bool
	wildcard bool
	proof    *semanticDependencyScope

	// Runtime instantiation uses only these local names, never their types
	// or literal values. stableNames excludes value-named projections from
	// literal-normalized metadata reuse.
	stableNames bool
}

func semanticRuntimeInput(names []string) typeScope {
	input := make(typeScope, len(names))
	for _, name := range names {
		input[name] = staticOperand{}
	}
	return input
}

func scopeVisibleTypes(local, enclosing typeScope) typeScope {
	if len(enclosing) == 0 {
		return local
	}
	visible := maps.Clone(enclosing)
	maps.Copy(visible, local)
	return visible
}

type subqueryScope struct{ bindings *semanticBodyScope }

// walkQueryScope is a compatibility view of the admitted program's type
// enrichment. It schedules no branches, declarations, projections or exports.
func (e *StorageExecutor) walkQueryScope(ctx context.Context, query string, initial typeScope, enclosing subqueryScope, cypher25 bool) (*semanticQueryScope, error) {
	_, model, err := e.enrichBoundTypes(ctx, query, initial, enclosing.bindings, "", cypher25)
	return model, err
}
func (e *StorageExecutor) scalarQueryScope(ctx context.Context, kind, source string, initial typeScope, _ *semanticDependencyScope, parent *semanticBodyScope, cypher25 bool) (*semanticQueryScope, error) {
	if strings.HasPrefix(strings.TrimSpace(source), "(") {
		source = "MATCH " + source
	}
	_, model, err := e.enrichBoundTypes(ctx, source, initial, parent, kind, cypher25)
	return model, err
}

// callWithImports resolves legacy WITH's ordinary locals. Unlike CALL(*), its
// star does not include a CALL frame's global imports. Explicit expressions may
// read named ancestors. A constant-only WITH is the existing implicit-import
// extension, rather than an importing clause.
func callWithImports(ctx context.Context, clause string, local, visible typeScope) (typeScope, bool) {
	imports := make(typeScope)
	importing := local.forEachProjectedBinding(ctx, clause, func(name, expression, text string, inherited bool) {
		if inherited {
			imports[name] = local[name]
			return
		}
		for _, source := range expressionFreeVariables(ctx, expression) {
			if operand, exists := visible[source]; exists {
				imports[source] = operand
			}
		}
	})
	return imports, importing || len(imports) != 0
}

// callQueryScope selects a frozen CALL body and enriches its existing IDs.
func (e *StorageExecutor) callQueryScope(ctx context.Context, source string, initial typeScope, enclosing subqueryScope, cypher25 bool) (*semanticQueryScope, error) {
	values, _, err := e.enrichBoundTypes(ctx, source, initial, enclosing.bindings, "", cypher25)
	if err != nil {
		return nil, err
	}
	if values == nil || values.program == nil {
		return nil, nil
	}
	for _, branch := range values.program.root.branches {
		for _, source := range branch.shape.clauses {
			clause := values.program.clauses[source.syntax.ID()]
			if clause.step.Call != nil {
				return values.model(clause.body), nil
			}
		}
	}
	return nil, nil
}

// readCallScopeClause is the import-header reader for validation, semantic
// scope construction and execution. nil names denotes (*); an empty non-nil
// list denotes (). Unscoped CALL has scoped == false.
func readCallScopeClause(ctx context.Context, call string) (names []string, scoped bool, err error) {
	parsed := readCallSubqueryScope(ctx, call)
	if parsed.invalid {
		return nil, parsed.scoped, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidVariableImport", localization.CypherSubqueriesWithImportExpressionInvalid(parsed.text))
	}
	return parsed.names, parsed.scoped, nil
}

func (proof *semanticDependencyScope) projectionTail(ctx context.Context, values typeScope, clause string) *semanticDependencyScope {
	if proof == nil {
		return nil
	}
	tail := proof.nested()
	values.forEachProjectedBinding(ctx, clause, func(name, expression, text string, inherited bool) {
		if !inherited && projectedSourceVariable(expression) != name {
			delete(tail.active, name)
		}
	})
	return tail
}

package cypher

import (
	"context"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
)

// validateSemanticScopes is the shared compile-time semantic chokepoint used
// by top-level statements and internally executed query branches.
//
// A statement whose backtick-quoted variables were canonicalized is cached
// under the text the client wrote: statements that differ only in quoting
// canonicalize alike but can validate differently (their column names
// differ).
func (e *StorageExecutor) validateSemanticScopes(ctx context.Context, cypher string) (failure error) {
	// Interrupted structural readers may decline their view; preserve the
	// caller cancellation rather than synthesizing a semantic query error.
	defer func() {
		if err := ctx.Err(); err != nil {
			failure = err
		}
	}()
	if err := ctx.Err(); err != nil {
		return err
	}
	if err := e.validateTransactionalCalls(ctx, cypher, nil); err != nil {
		return err
	}
	names := quotedVariableNamesFor(ctx, cypher)
	cypher25 := cypherVersionFromContext(ctx) == "25"
	cacheKey := cypher
	if names != nil {
		cacheKey = names.original
	}
	cacheKey = semanticCacheKey(cacheKey, cypher25)
	// A text cached under its own key passed every check here, the lexical
	// one included, so a repeated query skips them all (#823). A rewritten
	// text cached under its original still gets its own lexical check.
	// Literal-bearing texts share one compile verdict through the canonical
	// form (PR #1043 #6), looked up only when the exact text misses: a
	// canonical hit still runs the lexical check on its own text, then
	// returns.
	cached := e.semanticValidationCache.contains(cacheKey)
	var canonical string
	var normalized bool
	if !cached {
		canonical, normalized = normalizeLiteralText(cacheKey)
		cached = normalized && e.semanticValidationCache.contains(canonical)
	}
	if cached && names == nil && !normalized {
		return nil
	}
	if err := validateExpressionLexicalTokens(cypher); err != nil {
		return err
	}
	if cached {
		// A canonical hit shared the compile verdict with a sibling that
		// differs only in literal values, but SKIP / LIMIT bounds are
		// value-dependent: LIMIT 2-3 and LIMIT 5-1 share one canonical form,
		// yet only the latter is a non-negative integer. Re-evaluate them on
		// this text before returning (monster retest part 3).
		return e.validateStaticPaginationExpressions(ctx, extractPaginationExpressions(ctx, cypher)...)
	}
	// Column names belong to the written statement, before the scope walk
	// compares canonical binding identities or stops at a dynamic YIELD.
	if err := e.validateDuplicateReturnColumnName(ctx, cypher, names); err != nil {
		return err
	}
	if err := e.validateCallSubqueryScopes(ctx, cypher, cypher25); err != nil {
		return err
	}
	if err := validateListComprehensionVariables(cypher); err != nil {
		return err
	}
	if err := validateStaticQuantifierTypes(cypher); err != nil {
		return err
	}
	if err := e.validateStaticPaginationExpressions(ctx, extractPaginationExpressions(ctx, cypher)...); err != nil {
		return err
	}
	if err := validateProjectionSemantics(ctx, cypher); err != nil {
		return err
	}
	if err := validatePatternExpressionPlacement(ctx, cypher); err != nil {
		return err
	}
	trimmed := strings.TrimSpace(strings.TrimSuffix(strings.TrimSpace(cypher), ";"))
	if strings.HasSuffix(trimmed, ",") {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidProjection",
			"RETURN projection cannot end with an empty item",
		)
	}
	if invalidAggregationInListComprehension(cypher) {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidAggregation",
			"aggregate expressions are not allowed inside list-comprehension predicates or projections",
		)
	}
	if clauses, ok := splitPipelineClausesAllowingProcedureCalls(ctx, cypher); ok {
		pendingUpdate := false
		for _, clause := range clauses {
			if pendingUpdate && clause.kind == pipelineClauseCall {
				return newSemanticError("Neo.ClientError.Statement.SyntaxError", "InvalidClauseComposition", "WITH is required between an updating clause and CALL")
			}
			switch clause.kind {
			case pipelineClauseWith:
				pendingUpdate = false
			case pipelineClauseCreate, pipelineClauseMerge, pipelineClauseSet, pipelineClauseRemove, pipelineClauseDelete, pipelineClauseForeach:
				pendingUpdate = true
			}
			// Subquery bodies are checked as their own statements.
			if whereIndex := topLevelKeywordIndex(clause.text, "WHERE"); whereIndex >= 0 &&
				hasUnexpectedIdentifierAfterNumber(maskSubqueryBodies(clause.text[whereIndex+len("WHERE"):])) {
				return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "syntax error: unexpected identifier in WHERE")
			}
			if clause.kind == pipelineClauseWith && withProjectionHasEmptyItem(clause.text) {
				return emptyProjectionItemError("WITH")
			}
			if clause.kind == pipelineClauseReturn {
				body := strings.TrimSpace(clause.text[len("RETURN"):])
				if err := validateReturnAggregationSemantics(ctx, body); err != nil {
					return err
				}
				// The clause is scanned with its keyword, which tells a
				// keyword-named first item from a clause (RETURN union[0], #894).
				clauseText := strings.TrimSpace(clause.text)
				end := len(clauseText)
				for _, keyword := range []string{"ORDER BY", "SKIP", "LIMIT", "UNION"} {
					if index := topLevelKeywordIndex(clauseText, keyword); index >= len("RETURN") && index < end {
						end = index
					}
				}
				items := clauseText[len("RETURN"):end]
				if projectionHasEmptyItem(items) {
					return emptyProjectionItemError("RETURN")
				}
				projectionItems, _ := cutDistinct(strings.TrimSpace(items))
				for _, item := range splitTopLevelComma(projectionItems) {
					expression, _ := parseProjectionExprAlias(ctx, strings.TrimSpace(item))
					if err := validateExpressionOperandCompleteness(expression); err != nil {
						return err
					}
					if aliasIndex := projectionAliasIndex(ctx, item); aliasIndex >= 0 {
						alias := strings.TrimSpace(item[aliasIndex+len("AS"):])
						if simpleSemanticIdentifier(alias) == "" && !(len(alias) >= 2 && isCypherBacktickByte(alias[0]) && isCypherBacktickByte(alias[len(alias)-1])) {
							return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "syntax error: invalid RETURN alias")
						}
					}
				}
			}
		}
	}
	if err := e.validateCreateSemanticScopes(ctx, cypher, cypher25); err != nil {
		return err
	}
	if err := e.validateMergeSemanticScopes(ctx, cypher, cypher25); err != nil {
		return err
	}
	if err := e.validateMatchSemanticScopes(ctx, cypher, cypher25); err != nil {
		return err
	}
	if err := e.validateSetSemanticScopes(ctx, cypher); err != nil {
		return err
	}
	// Every function a statement calls, in any clause, is known (#1166).
	// Neo4j reports the statement's other semantic errors first.
	if err := validateKnownFunctions(cypher); err != nil {
		return err
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if normalized {
		e.semanticValidationCache.add(canonical)
		e.semanticValidationCache.add(cacheKey)
	} else {
		e.semanticValidationCache.add(cacheKey)
	}
	return nil
}

// emptyProjectionItemError is Neo4j's SyntaxError for a RETURN or WITH item
// list with an empty item (RETURN 1,,2 / RETURN , 1 / WITH a,, b).
func emptyProjectionItemError(clause string) error {
	return newSemanticError(
		"Neo.ClientError.Statement.SyntaxError",
		"InvalidProjection",
		clause+" projection cannot contain an empty item",
	)
}

// withProjectionHasEmptyItem reports whether a WITH clause's item list,
// before its WHERE / ORDER BY / SKIP / LIMIT, has an empty item.
func withProjectionHasEmptyItem(clause string) bool {
	body, _ := projectionSemanticBodyAndTail(clause, "WITH")
	return projectionHasEmptyItem(body)
}

// projectionHasEmptyItem reports whether a projection item list has an
// empty item: a leading, trailing or doubled top-level comma.
func projectionHasEmptyItem(items string) bool {
	items = strings.TrimSpace(items)
	if items == "" || strings.HasPrefix(items, ",") || strings.HasSuffix(items, ",") {
		return true
	}
	for _, item := range splitTopLevelComma(items) {
		if strings.TrimSpace(item) == "" {
			return true
		}
	}
	return false
}

// validateDuplicateReturnColumnName rejects a RETURN with two items of the
// same column name. names, when the statement was canonicalized, gives the
// items as the client wrote them, which name the columns.
func (e *StorageExecutor) validateDuplicateReturnColumnName(ctx context.Context, cypher string, names *quotedVariableNames) error {
	if names != nil {
		// Restore once, including nested CALL bodies. Distinct written
		// expressions can canonicalize to the same binding expression.
		cypher = names.restoreStatementText(cypher)
	}
	duplicate, invalidStar := e.duplicateReturnColumnName(ctx, cypher)
	if invalidStar {
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", localization.CypherCoreInvalidInput("*"))
	}
	if duplicate != "" {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"ColumnNameConflict",
			"Multiple RETURN items project the same column name: "+duplicate,
		)
	}
	// Uniqueness is syntax, independent of an inferred row schema. A dynamic
	// YIELD may stop the type walk, but cannot hide a malformed nested RETURN.
	for _, position := range findAllTopLevelPipelineKeywordPositions(cypher, "CALL") {
		if !startsWithCallSubquery(ctx, cypher[position:]) {
			continue
		}
		body, _, _, _ := e.parseCallSubquery(ctx, cypher[position:])
		if body != "" {
			if err := e.validateDuplicateReturnColumnName(ctx, body, nil); err != nil {
				return err
			}
		}
	}
	return nil
}

// validateCallSubqueryScopes uses the shared semantic scope owner for CALL
// imports, nested bodies and mutation clause scopes, before physical routing.
func (e *StorageExecutor) validateCallSubqueryScopes(ctx context.Context, cypher string, cypher25 bool) error {
	if _, err := e.admitBoundStatement(ctx, cypher); err != nil {
		return err
	}
	if !containsFold(cypher, "CALL") {
		return nil
	}
	return e.validateMatchSemanticScopes(ctx, cypher, cypher25)
}
func hasUnexpectedIdentifierAfterNumber(expression string) bool {
	for index := 0; index < len(expression); index++ {
		if end, skipped := skipCypherLexicalToken(expression, index); skipped {
			index = end - 1
			continue
		}
		if expression[index] < '0' || expression[index] > '9' || (index > 0 && isIdentByte(expression[index-1])) {
			continue
		}
		end := index + 1
		for end < len(expression) && (expression[end] >= '0' && expression[end] <= '9' || expression[end] == '.') {
			end++
		}
		next := skipSpaces(expression, end)
		if next > end {
			if name, _, ok := scanIdentifierToken(expression, next); ok {
				switch upperASCII(name) {
				case "AND", "OR", "XOR", "IN", "IS", "THEN", "ELSE", "END", "AS", "STARTS", "ENDS", "CONTAINS", "ORDER", "SKIP", "LIMIT", "UNION":
				default:
					return true
				}
			}
		}
		index = end - 1
	}
	return false
}

func containsMalformedCreateClauseToken(expression string) bool {
	for index := 0; index < len(expression); {
		name, next, ok := scanIdentifierToken(expression, index)
		if !ok {
			index++
			continue
		}
		if strings.EqualFold(name, "CREAT") {
			cursor := skipSpaces(expression, next)
			return cursor < len(expression) && expression[cursor] == '('
		}
		index = next
	}
	return false
}

// validatePatternExpressionPlacement enforces the rule that a pattern
// expression only tests whether its pattern exists: it is valid wherever a
// boolean is expected (maskPredicatePatterns), and never as a value of its
// own in a projection or an updating expression (Neo4j 5.26.30, #907).
func validatePatternExpressionPlacement(ctx context.Context, cypher string) error {
	clauses, ok := splitPipelineClauses(ctx, cypher)
	if !ok {
		return nil
	}
	for _, clause := range clauses {
		switch clause.kind {
		case pipelineClauseReturn, pipelineClauseWith:
			keyword := "RETURN"
			if clause.kind == pipelineClauseWith {
				keyword = "WITH"
			}
			for _, item := range splitTopLevelComma(projectionSemanticBody(clause.text, keyword)) {
				expression, _ := parseProjectionExprAlias(ctx, strings.TrimSpace(item))
				if containsIllegalProjectedPatternExpression(maskPredicatePatterns(expression)) {
					return invalidPatternExpressionPlacementError()
				}
			}
		case pipelineClauseSet:
			if containsIllegalProjectedPatternExpression(maskPredicatePatterns(clause.text)) {
				return invalidPatternExpressionPlacementError()
			}
		}
	}
	return nil
}

// containsIllegalProjectedPatternExpression distinguishes a raw pattern value
// from a legal pattern comprehension. It recursively examines ordinary list
// expressions while treating `[pattern | projection]` as one valid scalar
// expression. Relationship brackets (`-[r]->`) are not list delimiters.
func containsIllegalProjectedPatternExpression(expression string) bool {
	expression = maskSubqueryBodies(expression)
	// shortestPath(...) / allShortestPaths(...) are path functions, not
	// legacy pattern expressions: their pattern argument stays valid in value
	// position (RETURN / WITH / SET projections).
	expression = maskPathFunctionCalls(expression)
	segmentStart := 0
	for index := 0; index < len(expression); index++ {
		if expression[index] != '[' || (index > 0 && expression[index-1] == '-') {
			continue
		}
		close := findMatchingBracket(expression, index)
		if close < 0 {
			continue
		}
		if containsRelationshipPattern(expression[segmentStart:index]) {
			return true
		}
		candidate := expression[index : close+1]
		if _, _, patternComprehension := splitPatternComprehension(candidate); !patternComprehension {
			if containsIllegalProjectedPatternExpression(expression[index+1 : close]) {
				return true
			}
		}
		index = close
		segmentStart = close + 1
	}
	return containsRelationshipPattern(expression[segmentStart:])
}

// maskPathFunctionCalls blanks the argument spans of shortestPath(...) and
// allShortestPaths(...) so pattern scanners do not mistake their relationship
// syntax for a legacy pattern expression. The returned string keeps its byte
// length so every caller index stays valid.
func maskPathFunctionCalls(expression string) string {
	// Zero-allocation fast path: ordinary projections contain neither call.
	if indexASCIIFold(expression, "shortestpath") < 0 && indexASCIIFold(expression, "allshortestpaths") < 0 {
		return expression
	}
	masked := []byte(expression)
	for _, name := range []string{"shortestpath", "allshortestpaths"} {
		searchStart := 0
		for searchStart < len(expression) {
			idx := indexASCIIFold(expression[searchStart:], name)
			if idx < 0 {
				break
			}
			idx += searchStart
			if !functionNameStartsAt(expression, idx) {
				searchStart = idx + 1
				continue
			}
			openParen := skipSpaces(expression, idx+len(name))
			if openParen >= len(expression) || expression[openParen] != '(' {
				searchStart = idx + 1
				continue
			}
			closeParen := findMatchingParen(expression, openParen)
			if closeParen < 0 {
				break
			}
			for position := idx; position <= closeParen; position++ {
				if masked[position] != '\n' && masked[position] != '\r' {
					masked[position] = ' '
				}
			}
			searchStart = closeParen + 1
		}
	}
	return string(masked)
}

// maskPredicatePatterns blanks, keeping byte offsets, every pattern in
// expression that stands where a boolean is expected, which Neo4j allows
// anywhere: the argument of exists(), an operand of NOT, AND, OR or XOR, a
// CASE WHEN condition, or the WHERE of a list comprehension or quantifier.
// A pattern left is a value (RETURN (n)-->() AS x).
func maskPredicatePatterns(expression string) string {
	var masked []byte
	for index := 0; index < len(expression); index++ {
		switch character := expression[index]; cypherLexicalByte(character) {
		case cypherQuoteClass:
			index = skipCypherQuotedText(expression, index, character) - 1
			continue
		case '(':
		default:
			continue
		}
		if index > 0 && expression[index-1] == '[' { // a pattern comprehension
			continue
		}
		chainEnd, chain := relationshipChainEnd(expression, index, len(expression))
		if !chain {
			continue
		}
		if patternInBooleanPosition(expression, index, chainEnd) {
			if masked == nil {
				masked = []byte(expression)
			}
			for position := index; position < chainEnd; position++ {
				masked[position] = ' '
			}
		}
		index = chainEnd - 1
	}
	if masked == nil {
		return expression
	}
	return string(masked)
}

// patternInBooleanPosition reports whether the pattern expression[start:end]
// is a boolean operand: inside exists(...), or between a boolean keyword
// (NOT, AND, OR, XOR, WHEN, WHERE, or the start of the expression) and a
// boolean boundary (AND, OR, XOR, THEN, |, a closing parenthesis, or the
// end), with grouping parentheses around it allowed. A whole projection that
// is only the pattern is a value.
func patternInBooleanPosition(expression string, start, end int) bool {
	before := strings.TrimRight(expression[:start], " \t\r\n")
	after := strings.TrimLeft(expression[end:], " \t\r\n")
	for strings.HasSuffix(before, "(") && strings.HasPrefix(after, ")") {
		call := strings.TrimRight(before[:len(before)-1], " \t\r\n")
		if name := trailingIdentifier(call); name != "" && !isBooleanKeyword(name) {
			return strings.EqualFold(name, "exists")
		}
		before = call
		after = strings.TrimLeft(after[1:], " \t\r\n")
	}
	leftKeyword := ""
	switch name := trailingIdentifier(before); {
	case before == "":
	case isBooleanKeyword(name):
		leftKeyword = name
	default:
		return false
	}
	rightBoundary := after == "" || strings.HasPrefix(after, ")") || strings.HasPrefix(after, "|")
	for _, keyword := range []string{"AND", "OR", "XOR", "THEN"} {
		if matchKeywordAt(after, 0, keyword) {
			rightBoundary = true
		}
	}
	if !rightBoundary {
		return false
	}
	// The pattern alone, with nothing before it, is a projected value unless
	// a boolean operator follows it.
	return leftKeyword != "" || (after != "" && !strings.HasPrefix(after, ")"))
}

// isBooleanKeyword reports whether name introduces a boolean operand: NOT,
// AND, OR, XOR, WHEN or WHERE.
func isBooleanKeyword(name string) bool {
	switch upperASCII(name) {
	case "NOT", "AND", "OR", "XOR", "WHEN", "WHERE":
		return true
	}
	return false
}

// trailingIdentifier is the identifier text ends with, or "".
func trailingIdentifier(text string) string {
	end := len(text)
	start := end
	for start > 0 && isIdentByte(text[start-1]) {
		start--
	}
	return text[start:end]
}

func invalidPatternExpressionPlacementError() error {
	return newSemanticError(
		"Neo.ClientError.Statement.SyntaxError",
		"UnexpectedSyntax",
		"pattern expressions are only valid as predicates in WHERE",
	)
}

func (e *StorageExecutor) duplicateReturnColumnName(ctx context.Context, cypher string) (string, bool) {
	returnPositions := findAllTopLevelPipelineKeywordPositions(cypher, "RETURN")
	unionPositions := append(
		findAllTopLevelPipelineKeywordPositions(cypher, "UNION"),
		findAllTopLevelPipelineKeywordPositions(cypher, "UNION ALL")...,
	)
	for returnIndex, position := range returnPositions {
		end := len(cypher)
		if returnIndex+1 < len(returnPositions) && returnPositions[returnIndex+1] < end {
			end = returnPositions[returnIndex+1]
		}
		for _, unionPosition := range unionPositions {
			if unionPosition > position && unionPosition < end {
				end = unionPosition
			}
		}
		body := strings.TrimSpace(cypher[position+len("RETURN") : end])
		projection, _ := cutDistinct(projectionSemanticBody(cypher[position:end], "RETURN"))
		for index, raw := range splitTopLevelComma(projection) {
			expression, _ := parseProjectionExprAlias(ctx, raw)
			if expression == "*" && (index != 0 || projectionAliasIndex(ctx, raw) >= 0) {
				return "", true
			}
		}
		seen := make(map[string]struct{})
		for _, item := range e.parseReturnItems(ctx, body) {
			name := item.alias
			if name == "" {
				name = strings.TrimSpace(item.expr)
			}
			if name == "" || name == "*" {
				continue
			}
			// Cypher identifiers and projected column names are case-sensitive.
			// Only an exact duplicate is a conflict; for example n.Name and
			// n.name are distinct result columns.
			if _, exists := seen[name]; exists {
				return name, false
			}
			seen[name] = struct{}{}
		}
	}
	return "", false
}

func invalidAggregationInListComprehension(cypher string) bool {
	for start := 0; start < len(cypher); start++ {
		if cypher[start] != '[' {
			continue
		}
		end := findMatchingBracket(cypher, start)
		if end < 0 {
			continue
		}
		_, _, predicate, projection, comprehension := parseListComprehension(cypher[start+1 : end])
		if comprehension && (containsAggregateFunc(predicate) || containsAggregateFunc(projection)) {
			return true
		}
	}
	return false
}

// SET clause helpers for NornicDB Cypher.
//
// This file contains helper functions for processing SET clauses in Cypher queries.
// These functions handle property assignments, expression evaluation, and string
// operations used during SET operations.
//
// # SET Clause Syntax
//
// SET operations modify node and relationship properties:
//
//	SET n.name = 'Alice'           - Single property
//	SET n.name = 'Alice', n.age = 30  - Multiple properties
//	SET n += {name: 'Alice'}       - Map merge
//	SET n:Label                    - Add label
//
// # Expression Evaluation
//
// SET clauses can use various expressions:
//
//	SET n.id = randomUUID()                    - Function call
//	SET n.ts = timestamp()                     - Built-in function
//	SET n.name = 'prefix-' + toString(n.id)   - String concatenation
//	SET n.list = [1, 2, 3]                     - Array literal
//
// # ELI12
//
// Think of SET like filling out a form:
//
//	SET n.name = 'Alice'
//
// You're writing "Alice" in the "name" box on the form. These helper
// functions make sure the value goes in the right format:
//   - Strings stay as strings: 'hello' → "hello"
//   - Numbers become numbers: 42 → 42
//   - Arrays become lists: [1,2] → [1, 2]
//   - Functions run and give results: timestamp() → 1234567890
//
// # Neo4j Compatibility
//
// These helpers ensure SET clauses work identically to Neo4j.

package cypher

import (
	"context"
	"crypto/rand"
	"fmt"
	"strings"

	"github.com/orneryd/nornicdb/pkg/storage"
)

// applySetMapMergeToNode applies SET n += <expr>: every key of the map (or of
// the node / relationship) is written, and a null value removes the key.
// Row bindings from UNWIND / WITH are visible in the value scope.
// Non-map values are an error (setSourceMap).
func (e *StorageExecutor) applySetMapMergeToNode(ctx context.Context, node *storage.Node, varName string, rightExpr string, nodes map[string]*storage.Node, rels map[string]*storage.Edge, writes *setWrites) error {
	if node == nil {
		return nil
	}
	if err := requireSetParameter(ctx, rightExpr); err != nil {
		return err
	}
	props, err := e.setSourceMap(ctx, rightExpr, "+=", nodes, rels)
	if err != nil {
		return err
	}
	writes.mapEntries(node.Properties, props, false)
	for k, v := range props {
		setNodeProperty(node, k, v)
	}
	return nil
}

// setNodeProperty sets a property on a node.
//
// setNodeProperty sets a property on a node.
//
// The "embedding" property is treated like any other property — it is stored in
// node.Properties and indexed normally. Managed embeddings (from WITH EMBEDDING
// or the background worker) are stored separately in node.ChunkEmbeddings via
// ApplyManagedEmbedding; storage keeps or invalidates them when the node is
// updated, by whether the change touches the embedding source (#963).
//
// # Parameters
//
//   - node: The node to update
//   - propName: The property name
//   - value: The value to set
func setNodeProperty(node *storage.Node, propName string, value interface{}) {
	if node.Properties == nil {
		node.Properties = make(map[string]interface{})
	}
	value = copyStoredPropertyValue(value)
	if value == nil {
		delete(node.Properties, propName)
		return
	}
	node.Properties[propName] = value
}

func setRelationshipProperty(relationship *storage.Edge, propName string, value interface{}) {
	if relationship.Properties == nil {
		relationship.Properties = make(map[string]interface{})
	}
	value = copyStoredPropertyValue(value)
	if value == nil {
		delete(relationship.Properties, propName)
		return
	}
	relationship.Properties[propName] = value
}

func setPropertyMap(properties map[string]interface{}) map[string]interface{} {
	result := make(map[string]interface{}, len(properties))
	for key, value := range properties {
		if value != nil {
			result[key] = copyStoredPropertyValue(value)
		}
	}
	return result
}

// copyStoredPropertyValue gives a writer ownership of a generic property list.
// Its elements were already normalized and validated by storablePropertyValue;
// storage copies typed slices at its own boundary, as before.
func copyStoredPropertyValue(value interface{}) interface{} {
	if list, ok := value.([]interface{}); ok {
		copied := make([]interface{}, len(list))
		copy(copied, list)
		return copied
	}
	return value
}

// propertyMapForSetValue implements Cypher's entity-as-property-map semantics
// for SET target = source while keeping general map coercion strict elsewhere.
func propertyMapForSetValue(value interface{}) (map[string]interface{}, bool) {
	switch entity := value.(type) {
	case *storage.Node:
		if entity == nil {
			return nil, false
		}
		return entity.Properties, true
	case *storage.Edge:
		if entity == nil {
			return nil, false
		}
		return entity.Properties, true
	default:
		return toStringAnyMap(value)
	}
}

func parseSetAssignmentTarget(target string) (variable string, property string, hasProperty bool) {
	target = strings.TrimSpace(target)
	if base, prop, ok := splitPostfixPropertyAccess(target); ok {
		for {
			inner, wrapped := stripEnclosingExpressionParentheses(base)
			if !wrapped {
				break
			}
			base = strings.TrimSpace(inner)
		}
		return strings.TrimSpace(base), prop, true
	}
	for {
		inner, wrapped := stripEnclosingExpressionParentheses(target)
		if !wrapped {
			break
		}
		target = strings.TrimSpace(inner)
	}
	return target, "", false
}

// splitSetAssignments splits a SET clause into individual assignments,
// respecting quotes and nesting in (), [] and {} (function calls, list literals
// such as embeddings, and map literals).
//
// # Parameters
//
//   - setClause: The SET clause string (without "SET" keyword)
//
// # Returns
//
//   - Slice of individual assignments
//
// # Example
//
//	splitSetAssignments("n.name = 'Alice', n.age = 30")
//	// Returns: ["n.name = 'Alice'", "n.age = 30"]
//
//	splitSetAssignments("n.name = concat('a', 'b'), n.x = 1")
//	// Returns: ["n.name = concat('a', 'b')", "n.x = 1"]
//
//	splitSetAssignments("n.embedding = [0.1, 0.2], n.dim = 4")
//	// Returns: ["n.embedding = [0.1, 0.2]", "n.dim = 4"]
func splitSetAssignments(setClause string) []string {
	return splitTopLevelCommaKeepEmpty(setClause)
}

// hasConcatOperator checks if the expression has a + operator outside of quotes.
// This prevents infinite recursion when property values contain " + " in text.
//
// # Parameters
//
//   - expr: The expression to check
//
// # Returns
//
//   - true if + operator exists at top level
func (e *StorageExecutor) hasConcatOperator(expr string) bool {
	parenDepth := 0

	for i := 0; i < len(expr); i++ {
		if end, quoted := skipCypherLexicalToken(expr, i); quoted {
			i = end - 1
			continue
		}
		c := rune(expr[i])
		switch {
		case c == '(':
			parenDepth++
		case c == ')':
			parenDepth--
		case c == '+' && parenDepth == 0:
			// Check for space before and after (to avoid matching ++ or += etc)
			hasBefore := i > 0 && expr[i-1] == ' '
			hasAfter := i < len(expr)-1 && expr[i+1] == ' '
			if hasBefore && hasAfter {
				return true
			}
		}
	}
	return false
}

// splitFunctionArgs splits a function call's argument text at its top-level
// commas with the shared splitter (splitTopLevelComma): a comma inside
// quotes, a quoted name or a (), [] or {} group belongs to its argument, so
// a map literal with several keys is one argument. The arguments are
// trimmed; an empty last one is dropped.
func (e *StorageExecutor) splitFunctionArgs(args string) []string {
	return splitTopLevelComma(args)
}

// generateUUID generates a simple UUID-like string.
//
// Uses crypto/rand for cryptographically secure random bytes.
//
// # Returns
//
//   - A UUID-formatted string
func (e *StorageExecutor) generateUUID() string {
	// Use crypto/rand for proper UUID
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:])
}

// persistSetEntities stores the entities a SET clause wrote (applySetRuns)
// and counts what it wrote in stats (which may be nil): every route stores
// SET's writes this one way. An entity the clause left as it was isn't
// stored, though its writes count (Neo4j counts writes, not changes); a
// node whose labels changed is checked against the label policies first.
// On an error the entity is restored and the error is wrapped by its caller
// (wrap).
func (e *StorageExecutor) persistSetEntities(store storage.Engine, states []setEntityState, stats *QueryStats, wrap func(state setEntityState, err error) error) error {
	for index := range states {
		state := &states[index]
		if stats != nil {
			stats.PropertiesSet += state.written
		}
		if node := state.node; node != nil {
			labelsAdded := addedLabelCount(state.labels, node.Labels)
			if labelsAdded == 0 && changedPropertyCount(state.properties, node.Properties) == 0 {
				continue
			}
			restore := func() {
				node.Properties = state.properties
				node.Labels = state.labels
			}
			if labelsAdded > 0 {
				if err := validatePolicyOnLabelChange(store, node, state.labels); err != nil {
					restore()
					return err
				}
			}
			if stats != nil {
				stats.LabelsAdded += labelsAdded
			}
			if err := updateMutatedNode(store, node); err != nil {
				restore()
				return wrap(*state, err)
			}
			e.notifyNodeMutated(string(node.ID))
			continue
		}
		relationship := state.relationship
		if changedPropertyCount(state.properties, relationship.Properties) == 0 {
			continue
		}
		if err := updateMutatedEdge(store, relationship); err != nil {
			relationship.Properties = state.properties
			return wrap(*state, err)
		}
		e.notifyEdgeMutated(string(relationship.ID))
	}
	return nil
}

// setRun is a stretch of a SET clause: its consecutive assignments that
// name one variable (text). The per-entity appliers apply a stretch with
// Neo4j's runs inside it (setPropertyRun); stretches apply in order.
type setRun struct {
	variable string
	text     string
}

// appendSetClauseRuns appends the stretches of a SET body to runs (a
// caller's buffer), in order. Neo4j applies a SET clause's items in order, a
// run of property assignments to one variable at once (setPropertyRun):
// SET n.a = 1, m.b = n.a reads the new n.a, while SET n.a = 1, n.b = n.a
// reads the old one (#907). A chained SET clause (SET a SET b) starts new
// stretches. A stretch's text is a slice of the body. assignments, when not nil, are body's assignments already split
// (splitSetAssignments): they are used when body is one SET clause.
func appendSetClauseRuns(runs []setRun, body string, assignments []string) []setRun {
	for segment, next, ok := nextChainedSetClause(body, 0); ok; segment, next, ok = nextChainedSetClause(body, next) {
		open := false
		start, searchFrom := 0, 0
		items := assignments
		if items == nil || next < len(body) || segment != strings.TrimSpace(body) {
			items = splitSetAssignments(segment)
		}
		for _, assignment := range items {
			assignment = strings.TrimSpace(assignment)
			if assignment == "" {
				continue
			}
			at := searchFrom
			if found := strings.Index(segment[searchFrom:], assignment); found >= 0 {
				at = searchFrom + found
			}
			searchFrom = at + len(assignment)
			target, _, _, _ := splitSetAssignment(assignment)
			if open && runs[len(runs)-1].variable == target {
				runs[len(runs)-1].text = segment[start:searchFrom]
				continue
			}
			runs = append(runs, setRun{variable: target, text: assignment})
			start, open = at, true
		}
	}
	return runs
}

// setEntityState is an entity a SET clause wrote: its properties and
// labels before the clause, and the properties the clause wrote (setWrites).
type setEntityState struct {
	variable     string
	node         *storage.Node
	relationship *storage.Edge
	properties   map[string]interface{}
	labels       []string
	written      int
}

// applySetRuns applies a SET clause's runs (appendSetClauseRuns) in order to the
// nodes and relationships they name, and returns the entities written,
// first written first, appended to states (a caller's buffer). A run on a variable bound to null does nothing; a
// run on a variable that names no entity reports ok false. On an error,
// every entity is restored to its state before the clause.
func (e *StorageExecutor) applySetRuns(ctx context.Context, runs []setRun, nodes map[string]*storage.Node, rels map[string]*storage.Edge, isNull func(variable string) bool, states []setEntityState) ([]setEntityState, bool, error) {
	for _, run := range runs {
		node, relationship := nodes[run.variable], rels[run.variable]
		if node == nil && relationship == nil {
			if isNull(run.variable) {
				continue
			}
			restoreSetEntities(states)
			return nil, false, nil
		}
		target := -1
		for index := range states {
			if states[index].variable == run.variable {
				target = index
				break
			}
		}
		if target < 0 {
			state := setEntityState{variable: run.variable, node: node, relationship: relationship}
			if node != nil {
				state.properties = cloneStringAnyMap(node.Properties)
				state.labels = append([]string(nil), node.Labels...)
			} else {
				state.properties = cloneStringAnyMap(relationship.Properties)
			}
			states = append(states, state)
			target = len(states) - 1
		}
		var written int
		var err error
		if node != nil {
			written, err = e.applySetToNodeWithContext(ctx, node, run.variable, run.text, nodes, rels)
		} else {
			written, err = e.applySetToRelationshipWithContext(ctx, relationship, run.variable, run.text, nodes, rels)
		}
		states[target].written += written
		if err != nil {
			restoreSetEntities(states)
			return nil, true, err
		}
	}
	return states, true, nil
}

// restoreSetEntities puts the entities a SET clause wrote back as they were
// before it.
func restoreSetEntities(states []setEntityState) {
	for _, written := range states {
		if written.node != nil {
			written.node.Properties = written.properties
			written.node.Labels = written.labels
		} else {
			written.relationship.Properties = written.properties
		}
	}
}

package cypher

import (
	"context"
	"fmt"
	"math/bits"
	"reflect"
	"sort"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// validateSetSemanticScopes validates SET expressions against the clause
// horizon before execution. This is deliberately independent of row count:
// an undefined variable is a compile-time error even when MATCH yields no rows.
func (e *StorageExecutor) validateSetSemanticScopes(ctx context.Context, cypher string, imports ...string) error {
	if !containsKeywordOutsideStrings(cypher, "SET") && !containsKeywordOutsideStrings(cypher, "REMOVE") &&
		!containsKeywordOutsideStrings(cypher, "DELETE") && !containsKeywordOutsideStrings(cypher, "FOREACH") {
		return nil
	}
	clauses, err := e.boundMutationClauses(ctx, cypher, cypherGrammarVersion(cypher) == "25")
	if err != nil {
		return err
	}
	return e.validateMutationClauseScopes(ctx, clauses, newSemanticBindingScope(), imports...)
}

func (e *StorageExecutor) validateMutationClauseScopes(ctx context.Context, clauses []pipelineClause, scope *semanticBindingScope, imports ...string) error {
	for _, clause := range clauses {
		scope = clauseBindingScope(clause, scope)
		switch clause.kind {
		case pipelineClauseMatch, pipelineClauseOptionalMatch, pipelineClauseMerge, pipelineClauseCreate:
			for _, name := range extractNodeVariables(clause.text) {
				scope.bind(name)
			}
			for _, name := range extractRelationshipVariables(clause.text) {
				scope.bind(name)
			}
			// Path variables (p = (…)), with the pipeline's own binder.
			patternBindings := make(map[string]struct{})
			addPipelinePatternBindings(ctx, e, patternBindings, clause.text, pipelineClauseKeyword(clause.kind))
			for name := range patternBindings {
				scope.bind(name)
			}
		case pipelineClauseWith:
			scope = projectedBindingScope(ctx, scope, clause.text)
			for _, name := range imports {
				scope.bind(name)
			}
		case pipelineClauseLet:
			if err := bindPipelineLet(scope, clause.text); err != nil {
				return err
			}
		case pipelineClauseUnwind:
			if alias := unwindBindingName(clause.text); alias != "" {
				scope.bind(alias)
			}
		case pipelineClauseSet:
			if err := e.validateSetClauseScope(ctx, scope, clause.text); err != nil {
				return err
			}
		case pipelineClauseForeach:
			body := queryBodyFromSyntax(clause.syntax)
			if body.status != queryBodyRead || body.foreach == nil {
				return invalidForeachError()
			}
			child := newSemanticBindingScope()
			for name := range scope.names {
				child.bind(name)
			}
			child.bind(body.foreach.variable)
			if err := e.validateMutationClauseScopes(ctx, body.foreach.updates, child); err != nil {
				return err
			}
		case pipelineClauseRemove:
			if err := validateRemoveClauseScope(ctx, scope, clause.text); err != nil {
				return err
			}
		case pipelineClauseDelete:
			if err := validateDeleteClauseScope(scope, clause.text); err != nil {
				return err
			}
		}
	}
	return nil
}

// pipelineClauseKeyword is the leading keyword of a pattern clause kind.
func pipelineClauseKeyword(kind pipelineClauseKind) string {
	switch kind {
	case pipelineClauseOptionalMatch:
		return "OPTIONAL MATCH"
	case pipelineClauseMerge:
		return "MERGE"
	case pipelineClauseCreate:
		return "CREATE"
	default:
		return "MATCH"
	}
}

// validateRemoveClauseScope rejects a REMOVE item (m.x, m:L, m[k],
// m:$(e)) whose variable is not bound, as SET does and as Neo4j does
// ("Variable `m` not defined"), and checks the expressions of its dynamic
// keys and labels like a SET value's (validateWriteExpressionScope).
func validateRemoveClauseScope(ctx context.Context, scope *semanticBindingScope, clause string) error {
	items, err := parseRemoveItems(strings.TrimSpace(clause[len("REMOVE"):]))
	if err != nil {
		return err
	}
	for _, item := range items {
		if !scope.contains(item.variable) {
			return createUndefinedVariableError(item.variable)
		}
		expressions := make([]string, 0, len(item.labels)+1)
		if item.key != "" {
			expressions = append(expressions, item.key)
		}
		for _, label := range item.labels {
			if label.expression != "" {
				expressions = append(expressions, label.expression)
			}
		}
		for _, expression := range expressions {
			if err := validateWriteExpressionScope(ctx, expression, scope); err != nil {
				return err
			}
		}
	}
	return nil
}

// validateDeleteClauseScope rejects a DELETE target whose root variable is not
// bound (deleteExpressionRootIdentifier), with the error the pipeline DELETE
// step raises at run time, so a subquery body is checked before it runs.
func validateDeleteClauseScope(scope *semanticBindingScope, clause string) error {
	targets, _, _ := deleteClauseTargets(clause)
	for _, expression := range targets {
		if word, ok := trailingWordAfterOperand(expression); ok {
			// One expression per target: DETACH DELETE n COMMIT is Neo4j
			// 5.26.30's "Invalid input 'COMMIT'"; the root variable was
			// deleted and the rest ignored (#741).
			return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
				localization.CypherCoreInvalidInput(word))
		}
		if root := deleteExpressionRootIdentifier(expression); root != "" && !scope.contains(root) {
			return deleteUndefinedVariableError(expression)
		}
	}
	return nil
}

// trailingWordAfterOperand returns the word that follows a complete operand
// at the top level of expression with no operator between (n COMMIT,
// a.b c), which no expression has; operator keywords (AND, IN, IS, …) are
// not such words.
func trailingWordAfterOperand(expression string) (string, bool) {
	depth := 0
	operandEnded := false
	for i := 0; i < len(expression); {
		c := expression[i]
		switch {
		case isCypherQuoteByte(c):
			i = skipCypherQuotedText(expression, i, c)
			operandEnded = depth == 0
			continue
		case c == '(' || c == '[' || c == '{':
			depth++
			operandEnded = false
		case c == ')' || c == ']' || c == '}':
			depth--
			operandEnded = depth == 0
		case isASCIIWhitespace(c):
		case depth == 0 && isIdentStartByte(c):
			word, end, _ := scanIdentifierToken(expression, i)
			if operandEnded && !isExpressionOperatorWord(word) {
				return word, true
			}
			operandEnded = !isExpressionOperatorWord(word)
			i = end
			continue
		case depth == 0 && c == '.':
			// a property name follows: part of the operand
			operandEnded = false
		case depth == 0 && isDigitByte(c):
			operandEnded = true
		default:
			operandEnded = false
		}
		i++
	}
	return "", false
}

// isExpressionOperatorWord reports whether word is an operator or CASE
// keyword that may follow an operand.
func isExpressionOperatorWord(word string) bool {
	switch upperASCII(word) {
	case "AND", "OR", "XOR", "NOT", "IN", "IS", "CONTAINS", "STARTS", "ENDS", "WITH", "NULL", "AS",
		"CASE", "WHEN", "THEN", "ELSE", "END":
		return true
	}
	return false
}

// deleteClauseTargets splits a [DETACH] DELETE clause into its target
// expressions, for every check and the pipeline step that read them. ok is
// false for text that isn't a DELETE clause.
func deleteClauseTargets(clause string) (targets []string, detach, ok bool) {
	body := strings.TrimSpace(clause)
	if startsWithKeywordFold(body, "DETACH DELETE") {
		detach, body = true, strings.TrimSpace(body[len("DETACH"):])
	}
	if !startsWithKeywordFold(body, "DELETE") {
		return nil, false, false
	}
	return splitTopLevelComma(strings.TrimSpace(body[len("DELETE"):])), detach, true
}

// deleteUndefinedVariableError is the error for a DELETE target that refers to
// an undefined variable, raised by the statement check and the pipeline step.
func deleteUndefinedVariableError(expression string) error {
	return newSemanticError(
		"Neo.ClientError.Statement.SyntaxError",
		"UndefinedVariable",
		fmt.Sprintf("DELETE expression %q refers to an undefined variable", strings.TrimSpace(expression)),
	)
}

// validateSetClauseScope is the statement-level check for one SET clause,
// shared by every route (MATCH, CREATE, MERGE, pipeline, fast paths): the
// assignment shapes (validatePipelineSetAssignments), bound target and value
// variables, and known functions in the assigned values.
func (e *StorageExecutor) validateSetClauseScope(ctx context.Context, scope *semanticBindingScope, clause string) error {
	body := strings.TrimSpace(clause[len("SET"):])
	assignments := splitSetAssignments(body)
	if err := validatePipelineSetAssignments(assignments); err != nil {
		return err
	}
	for _, assignment := range assignments {
		target, property, operator, expression := splitSetAssignment(assignment)
		if operator == ":" {
			// Label assignment `n:Label[:Label2]`: the variable before the
			// first colon must be bound, as for a property assignment, and so
			// must the variables a dynamic label's expression reads.
			if target = normalizeProjectionColumnName(target); isValidIdentifier(target) && !scope.contains(target) {
				return createUndefinedVariableError(target)
			}
			// The chain was read above (validatePipelineSetAssignments).
			items, _ := setLabelChainItems(expression)
			for _, item := range items {
				if item.expression == "" {
					continue
				}
				if err := validateWriteExpressionScope(ctx, item.expression, scope); err != nil {
					return err
				}
			}
			continue
		}
		if operator == "" {
			continue
		}
		if target != "" && !scope.contains(target) {
			return createUndefinedVariableError(target)
		}
		if operator == "[]=" {
			// x[key] = v: the key is an expression too.
			if err := validateWriteExpressionScope(ctx, property, scope); err != nil {
				return err
			}
		}
		if err := validateWriteExpressionScope(ctx, expression, scope); err != nil {
			return err
		}
		// A literal source here, in item order; the shared clause validator
		// checks every source with the statement's types
		// (staticSetItemsTokenError).
		if err := setSourceTypeError(property, operator, (staticTypeScope{}).operandOf(ctx, expression)); err != nil {
			return err
		}
	}
	return nil
}

// validateWriteExpressionScope checks an expression a SET or REMOVE item
// evaluates (a value, a dynamic key or label): complete operands and bound
// variables. Its functions are checked with the statement's.
func validateWriteExpressionScope(ctx context.Context, expression string, scope *semanticBindingScope) error {
	if err := validateExpressionOperandCompleteness(expression); err != nil {
		return err
	}
	if missing := firstUndefinedSetExpressionVariable(ctx, expression, scope); missing != "" {
		return createUndefinedVariableError(missing)
	}
	return nil
}

func firstUndefinedSetExpressionVariable(ctx context.Context, expression string, scope *semanticBindingScope) string {
	for _, name := range expressionFreeVariables(ctx, expression) {
		if _, exists := scope.names[name]; !exists {
			return name
		}
	}
	return ""
}

// expressionFreeVariables returns the variables an expression reads, in order
// of appearance: identifiers outside string literals that are not parameters,
// property or map keys, function names, keywords, type names after :: or TYPED,
// or names the expression binds itself (list comprehension iterators, reduce /
// all / any / none / single).
// It is the one reference scanner for the static SET and CREATE checks.
func expressionFreeVariables(ctx context.Context, expression string) []string {
	expression = maskTypePredicateTypes(maskPathFunctionCalls(expression))
	// Both maskers blank in place: offsets are the expression's.
	locals := newLocalReader(expression)
	var names []string
	delimiters := make([]byte, 0, 8)
	for index := 0; index < len(expression); {
		if end := queryGapEnd(expression, index); end > index {
			index = end
			continue
		}
		character := expression[index]
		if character == '[' {
			if closing := findMatchingBracket(expression, index); closing >= 0 {
				if pattern, projection, comprehension := splitPatternComprehension(expression[index : closing+1]); comprehension {
					bindings := make(matchSemanticScope)
					addMatchPatternBindingKinds(ctx, bindings, pattern)
					if where := topLevelKeywordIndex(pattern, "WHERE"); where >= 0 {
						projection += ", " + pattern[where+len("WHERE"):]
					}
					for _, reference := range expressionFreeVariables(ctx, projection) {
						if _, bound := bindings[reference]; bound {
							continue
						}
						if !locals.shadows(reference, index) {
							names = append(names, reference)
						}
					}
					index = closing + 1
					continue
				}
			}
		}
		if isCypherStringQuoteByte(character) {
			index = skipCypherQuotedText(expression, index, character)
			continue
		}
		if character == '(' {
			// A pattern predicate ((n)-[:R]->(m:L)) reads the variables its
			// nodes and relationships name, never its labels, types or
			// property keys; it can't introduce one (Neo4j: "PatternExpressions
			// are not allowed to introduce new variables").
			if chainEnd, chain := relationshipChainEnd(expression, index, len(expression)); chain {
				bindings := make(matchSemanticScope)
				addMatchPatternBindingKinds(ctx, bindings, expression[index:chainEnd])
				references := make([]string, 0, len(bindings))
				for reference := range bindings {
					references = append(references, reference)
				}
				// A chain's structural names do not cover the values read by
				// its maps or inline predicates. Use the canonical element walk
				// before skipping the chain, so dependency proofs retain them.
				walk := labelExpressionRewriter{query: expression}
				walk.visitElement = func(open, close int, _ bool) error {
					if where := elementWhereIndex(expression, open, close); where >= 0 {
						references = append(references, expressionFreeVariables(ctx, expression[where+len("WHERE"):close])...)
						close = where
					}
					_, properties := splitNodePatternProperties("(" + expression[open+1:close] + ")")
					references = append(references, expressionFreeVariables(ctx, properties)...)
					return nil
				}
				var predicates []string
				_ = walk.patternElements(index, chainEnd, labelPatternMatch, &predicates)
				sort.Strings(references)
				for _, reference := range references {
					if !locals.shadows(reference, index) {
						names = append(names, reference)
					}
				}
				index = chainEnd
				continue
			}
		}
		switch character {
		case '(', '[', '{':
			delimiters = append(delimiters, character)
		case ')', ']', '}':
			if len(delimiters) > 0 {
				delimiters = delimiters[:len(delimiters)-1]
			}
		}
		quotedIdentifier := isCypherBacktickByte(character)
		name, next, ok := scanIdentifierToken(expression, index)
		if !ok {
			index++
			continue
		}
		if index > 0 && expression[index-1] >= '0' && expression[index-1] <= '9' {
			index = next
			continue
		}
		previous := previousSetExpressionByte(expression, index)
		following := nextSetExpressionByte(expression, next)
		upper := upperASCII(name)
		if following == '(' && (upper == "TRIM" || upper == "NORMALIZE") {
			open := skipSpaces(expression, next)
			if closing := findMatchingParen(expression, open); closing >= 0 {
				inner := expression[open+1 : closing]
				parameters, grammar := trimFromArguments(inner)
				if upper == "NORMALIZE" {
					parameters = splitTopLevelComma(inner)
					grammar = false
					if len(parameters) == 2 {
						parameters, grammar = parameters[:1], true
					}
				}
				if grammar {
					for _, parameter := range parameters {
						for _, reference := range expressionFreeVariables(ctx, parameter) {
							if !locals.shadows(reference, open) {
								names = append(names, reference)
							}
						}
					}
					index = closing + 1
					continue
				}
			}
		}
		if functionEnd, call := qualifiedFunctionNameEnd(expression, next); call {
			delimiters = append(delimiters, '(')
			index = functionEnd + 1
			continue
		}
		// A subquery expression (EXISTS / COUNT / COLLECT { … }) binds its own
		// variables and sees the outer ones; its body isn't an expression.
		if _, open, subquery := subqueryExpressionKeywordAt(expression, index); subquery {
			if closing := findMatchingDelimiter(expression, open, '{', '}'); closing > next {
				index = closing + 1
				continue
			}
		}
		mapKey := following == ':' && len(delimiters) > 0 && delimiters[len(delimiters)-1] == '{' && (previous == '{' || previous == ',')
		// x IS NFC NORMALIZED: the normal form names a form, not a variable.
		normalForm := false
		switch upper {
		case "NFC", "NFD", "NFKC", "NFKD":
			form, _, word := scanIdentifierToken(expression, skipSpaces(expression, next))
			normalForm = word && strings.EqualFold(form, "NORMALIZED")
		}
		if quotedIdentifier {
			normalForm = false
		}
		keyword := !quotedIdentifier && setExpressionKeyword(upper)
		// END is also a legal variable, notably the operand in NOT end +
		// another CASE. Preserve the full expression when asking the CASE
		// grammar owner, before evaluation splits it into atomic operands.
		if upper == "END" && !caseKeywordAt(expression, index, "END") {
			keyword = false
		}
		if previous != '$' && previous != '.' && following != '(' && !mapKey && !normalForm && !keyword {
			if !locals.shadows(name, index) {
				names = append(names, name)
			}
		}
		index = next
		if following == ':' && !mapKey {
			// The labels of n:A:B and of a label expression n:A|B&!C or
			// n:%: names of labels, not variables.
			labelStart := skipSpaces(expression, next)
			for labelStart < len(expression) && strings.IndexByte(":|&", expression[labelStart]) >= 0 {
				labelName := skipSpaces(expression, labelStart+1)
				for labelName < len(expression) && expression[labelName] == '!' {
					labelName = skipSpaces(expression, labelName+1)
				}
				labelEnd := labelName + 1
				if labelName >= len(expression) || expression[labelName] != '%' {
					var valid bool
					if _, labelEnd, valid = scanIdentifierToken(expression, labelName); !valid {
						break
					}
				}
				labelStart = skipSpaces(expression, labelEnd)
				index = labelStart
			}
		}
	}
	return names
}

// expressionLocalBindings returns the variables an expression binds itself,
// at any depth: every declaration localBindingAt reads (list and named
// pattern comprehensions, reduce / all / any / none / single / filter). It
// is the names-only view of the one declaration reader, for the caches and
// pre-filters in front of localVariableShadowsAt.
func expressionLocalBindings(expression string) map[string]struct{} {
	locals := make(map[string]struct{})
	for index := 0; index < len(expression); index++ {
		switch c := expression[index]; cypherLexicalByte(c) {
		case cypherQuoteClass:
			index = skipCypherQuotedText(expression, index, c) - 1
		case '/':
			if end := queryCommentEnd(expression, index); end >= 0 {
				index = end - 1
			}
		case '[', '(':
			if binding, ok := localBindingAt(expression, index); ok {
				for declared := 0; declared < binding.count; declared++ {
					locals[binding.names[declared]] = struct{}{}
				}
			}
		}
	}
	return locals
}

func previousSetExpressionByte(text string, index int) byte {
	for index--; index >= 0; index-- {
		if !isWhitespace(text[index]) {
			return text[index]
		}
	}
	return 0
}

func nextSetExpressionByte(text string, index int) byte {
	for index < len(text) {
		if !isWhitespace(text[index]) {
			return text[index]
		}
		index++
	}
	return 0
}

func setExpressionKeyword(token string) bool {
	if isLiteralKeyword(token) {
		return true
	}
	switch token {
	case "CASE", "WHEN", "THEN", "ELSE", "END",
		"IN", "WHERE", "AND", "OR", "XOR", "NOT", "IS", "STARTS", "ENDS",
		"WITH", "CONTAINS", "DISTINCT", "AS", "NORMALIZED":
		return true
	default:
		return false
	}
}

// storablePropertyValue is the value a property write stores, or the
// TypeError of a value a property cannot store: value normalized first
// (normalizedPropValue: Go integers and times become Cypher values, in lists
// too), then checked by the property value rule (validateSetPropertyValue),
// whose int/float list coercion copies only a mixed numeric list. rewritten
// reports whether stored is not value itself. Every SET route checks its
// values here, so a value is storable or not whichever route writes it: a
// map entry as a direct property value (#1055).
func storablePropertyValue(value interface{}) (stored interface{}, rewritten bool, err error) {
	stored, rewritten = normalizedPropValue(value)
	validated, coerced, err := validateSetPropertyValue(stored)
	if err != nil {
		return nil, false, err
	}
	return validated, rewritten || coerced, nil
}

func validateSetPropertyValue(value interface{}) (stored interface{}, rewritten bool, err error) {
	if value == nil {
		return value, false, nil
	}
	if _, invalid := value.(*storage.Node); invalid {
		return nil, false, invalidSetPropertyType(value)
	}
	if _, invalid := value.(*storage.Edge); invalid {
		return nil, false, invalidSetPropertyType(value)
	}
	if _, invalid := value.(*PathResult); invalid {
		return nil, false, invalidSetPropertyType(value)
	}
	switch value.(type) {
	case []float64, []float32, []int64, []int, []int32, []string, []bool:
		return value, false, nil // typed lists of primitives (e.g. embeddings) are valid as-is
	}
	typeOf := reflect.TypeOf(value)
	if typeOf != nil && typeOf.Kind() == reflect.Map {
		return nil, false, invalidSetPropertyType(value)
	}
	items, list := toInterfaceSlice(value)
	if !list {
		return value, false, nil
	}
	if len(items) == 0 {
		return value, false, nil
	}
	// Neo4j's array property rule (#643): elements must share one primitive
	// or temporal kind, null is not storable, and an int/float mix is stored
	// as floats. A mixed numeric list is copied so the coerced
	// floats are stored without changing the caller's list. The kind bitmask
	// keeps homogeneous-list validation allocation-free.
	var kinds uint16
	for _, item := range items {
		if item == nil {
			return nil, false, newSemanticError(
				"Neo.ClientError.Statement.TypeError",
				"InvalidPropertyType",
				"Collections containing null values can not be stored in properties.",
			)
		}
		itemType := reflect.TypeOf(item)
		if itemType != nil && (itemType.Kind() == reflect.Map || itemType.Kind() == reflect.Slice || itemType.Kind() == reflect.Array) {
			return nil, false, invalidSetPropertyType(value)
		}
		if _, invalid := item.(*storage.Node); invalid {
			return nil, false, invalidSetPropertyType(value)
		}
		if _, invalid := item.(*storage.Edge); invalid {
			return nil, false, invalidSetPropertyType(value)
		}
		kinds |= 1 << propertyArrayElementOf(item)
	}
	if kinds&(1<<arrayElemOther) != 0 {
		return nil, false, invalidSetPropertyType(value)
	}
	numIntFloat := uint16(1<<arrayElemInt) | uint16(1<<arrayElemFloat)
	if bits.OnesCount16(kinds) > 2 ||
		(bits.OnesCount16(kinds) == 2 && kinds&numIntFloat != numIntFloat) {
		return nil, false, newSemanticError(
			"Neo.ClientError.Statement.TypeError",
			"InvalidPropertyType",
			"Neo4j only supports a subset of Cypher types for storage as singleton or array properties.",
		)
	}
	if kinds == 1<<arrayElemPoint {
		first, _ := pointValue(items[0])
		for _, item := range items[1:] {
			if point, _ := pointValue(item); point.SRID != first.SRID {
				return nil, false, newSemanticError(
					"Neo.ClientError.Statement.TypeError",
					"InvalidPropertyType",
					"Collections containing point values with different CRS can not be stored in properties.",
				)
			}
		}
	}
	if kinds == numIntFloat {
		items = append([]interface{}(nil), items...)
		for i, item := range items {
			if f, ok := toFloat64(item); ok {
				items[i] = f
			}
		}
		return items, true, nil
	}
	return value, false, nil
}

// propertyArrayElement categorizes an array element for the Neo4j property
// array rule (#643).
type propertyArrayElement uint8

const (
	arrayElemEmpty propertyArrayElement = iota
	arrayElemInt
	arrayElemFloat
	arrayElemString
	arrayElemBool
	arrayElemDate
	arrayElemTime
	arrayElemLocalTime
	arrayElemDateTime
	arrayElemLocalDateTime
	arrayElemDuration
	arrayElemPoint
	arrayElemOther
)

func propertyArrayElementOf(item interface{}) propertyArrayElement {
	switch item.(type) {
	case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
		return arrayElemInt
	case float32, float64:
		return arrayElemFloat
	case string:
		return arrayElemString
	case bool:
		return arrayElemBool
	case CypherDate, *CypherDate:
		return arrayElemDate
	case CypherTime, *CypherTime:
		return arrayElemTime
	case CypherLocalTime, *CypherLocalTime:
		return arrayElemLocalTime
	case CypherDateTime, *CypherDateTime:
		return arrayElemDateTime
	case CypherLocalDateTime, *CypherLocalDateTime:
		return arrayElemLocalDateTime
	case CypherDuration, *CypherDuration:
		return arrayElemDuration
	case CypherPoint, *CypherPoint:
		return arrayElemPoint
	default:
		return arrayElemOther
	}
}

// validatePropertyValues applies the property value rule
// (validateSetPropertyValue: no maps, no nested lists, no entities) to every
// value a CREATE or MERGE is about to store, as SET does (b968c6a2). It runs
// at every CREATE / MERGE write: CREATE node preparation (also the auto-commit
// node fast path) and relationships, MERGE node and relationship creation,
// and the UNWIND batch creators.
func validatePropertyValues(properties map[string]interface{}) error {
	for key, value := range properties {
		stored, _, err := storablePropertyValue(value)
		if err != nil {
			return err
		}
		properties[key] = stored
	}
	return nil
}

func invalidSetPropertyType(value interface{}) error {
	return newSemanticError(
		"Neo.ClientError.Statement.TypeError",
		"InvalidPropertyType",
		fmt.Sprintf("property value has unsupported type %s", cypherTypeName(value)),
	)
}

package cypher

import (
	"context"
	cypherantlr "github.com/orneryd/nornicdb/pkg/cypher/antlr"
	"github.com/orneryd/nornicdb/pkg/fabric"
)

// Statement execution modes come only from grammar-owned clauses and the live
// procedure registry. QueryInfo's substring hints belong to cache optimization;
// neither admission nor resolved execution may consume them.
type statementExecutionContract struct {
	writes, transaction, calls, dynamic bool
}

func readStatementExecutionContract(ctx context.Context, query string) (statementExecutionContract, error) {
	mode, body := parseExecutionMode(query)
	if mode == ModeExplain {
		return statementExecutionContract{}, nil
	}
	if startsWithKeywordFold(body, "SHOW") || isNornicExtensionStatement(body) || isSchemaCommandStatement(body) || bareTransactionCommand(body) != "" {
		return statementExecutionContract{}, nil
	}
	if fabric.IsAdministrationCommand(body) {
		// Administration keeps its existing routing and error owner. CREATE
		// commands not handled by the system router retain the implicit
		// wrapper used before procedure admission was introduced.
		writes := startsWithKeywordFold(body, "CREATE")
		return statementExecutionContract{writes: writes, transaction: writes}, nil
	}
	structure, err := cypherantlr.ParseSyntax(ctx, body, cypherantlr.FragmentEntry, cypherVersionFromContext(ctx) == "25")
	if err := ctx.Err(); err != nil {
		return statementExecutionContract{}, err
	}
	if err != nil {
		return statementExecutionContract{}, syntaxAdmissionError(body, err)
	}
	contract := statementExecutionContract{}
	visitStatementProcedureSyntax(structure, func(node cypherantlr.SyntaxNode) {
		switch node.Rule() {
		case cypherantlr.CypherParserRULE_updatingStatement:
			contract.writes, contract.transaction = true, true
		case cypherantlr.CypherParserRULE_queryCallSt, cypherantlr.CypherParserRULE_standaloneCall:
			contract.calls = true
		}
	}, func(spec ProcedureSpec, _ string) bool {
		// SCHEMA procedures keep their existing schema-transaction owner;
		// this contract admits registered data WRITE procedures.
		fixedWrite := spec.Mode == ProcedureModeWrite
		contract.writes = contract.writes || fixedWrite
		contract.dynamic = contract.dynamic || spec.ExecutesStatements
		contract.transaction = contract.transaction || !spec.OwnsTransactions &&
			(fixedWrite || spec.ExecutesStatements || spec.Name == "tx.setMetaData")
		return false
	})
	return contract, nil
}

package cypher

import (
	"context"
	"fmt"
	"strings"

	nornicerrors "github.com/orneryd/nornicdb/pkg/errors"
	"github.com/orneryd/nornicdb/pkg/localization"
)

func (e *StorageExecutor) validateStatementFraming(ctx context.Context, cypher string) error {
	multiple, unclosed := inspectOutsideStrings(cypher, ";")
	if unclosed >= 0 {
		return unclosedCommentError(cypher, unclosed, ModeNormal)
	}
	if multiple {
		statements := e.splitBySemicolon(cypher)
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			localization.CypherCommandRoutingMultipleStatements(len(statements)))
	}
	mode, body, conflict := statementExecutionModes(cypher)
	if mode != ModeNormal && queryGapEnd(body, 0) == len(body) {
		return emptyStatementError()
	}
	if conflict {
		return executionModeConflictError()
	}
	// Only a statement with the word UNION in it can have UNION branches.
	if findKeywordIndex(cypher, "UNION") < 0 || findKeywordIndex(cypher, "FINISH") < 0 {
		return nil
	}
	if branches, _, _, ok := parseTopLevelUnionBranches(ctx, cypher); ok && len(branches) > 1 {
		hasFinish, hasColumns := false, false
		for _, branch := range branches {
			_, finishes := stripTrailingFinish(branch)
			if finishes {
				hasFinish = true
			} else if e.statementProducesColumns(ctx, branch) {
				hasColumns = true
			}
		}
		if hasFinish && hasColumns {
			return newSemanticError("Neo.ClientError.Statement.SyntaxError", "InvalidProjection",
				"All sub queries in an UNION must have the same return column names")
		}
	}
	return nil
}

// Statement framing helpers: Neo4j 5 statement preamble (CYPHER … groups),
// the FINISH clause terminator, and the EXPLAIN/PROFILE exclusivity rule.

// cypherClauseStarts are the keywords that end a CYPHER preamble group and
// start the actual statement. Matched case-insensitively at a token boundary.
var cypherClauseStarts = [...]string{
	"MATCH", "CREATE", "MERGE", "DELETE", "DETACH", "CALL", "RETURN", "WITH",
	"UNWIND", "OPTIONAL", "DROP", "SHOW", "FOREACH", "LOAD", "EXPLAIN",
	"PROFILE", "ALTER", "USE", "BEGIN", "COMMIT", "ROLLBACK", "TERMINATE",
	"UNION", "CYPHER", "FINISH", "LET", "FILTER", "FOR", "WHEN",
}

// startsWithClauseKeyword reports whether a clause keyword, or a brace that
// opens a query part ({ RETURN 1 } UNION …), starts s.
func startsWithClauseKeyword(s string) bool {
	if strings.HasPrefix(s, "{") {
		return true
	}
	for _, keyword := range cypherClauseStarts {
		if matchKeywordAt(s, 0, keyword) {
			return true
		}
	}
	return false
}

// stripCypherPreamble removes leading CYPHER groups: the keyword CYPHER, an
// optional version number, and option tokens (ident, ident=value, or a quoted
// string) until a clause keyword starts the statement. Neo4j accepts any
// number of such groups (`CYPHER 5 runtime=slotted CYPHER RETURN 1`).
var cypherPreambleOptionValues = map[string]string{
	"runtime":                  "interpreted, legacy, parallel, pipelined, slotted",
	"planner":                  "cost, dp, idp",
	"expressionengine":         "compiled, interpreted, only_when_hot",
	"operatorengine":           "compiled, interpreted",
	"interpretedpipesfallback": "all, disabled, whitelisted_plans_only",
	"replan":                   "force, skip",
	"updatestrategy":           "default, eager",
	"connectcomponentsplanner": "greedy, idp",
	"eageranalyzer":            "ir, lp",
	"inferschemaparts":         "most_selective_label, off",
	"parallelruntimesupport":   "all, disabled",
	"debug":                    "ast, disableexistssubquerycaching, disablepropertycaching, generate_java_source, graphviz, inverse_cost, logcostcomparisons, logicalplan, logicalplanbuilder, mermaid, printcostcomparisons, querygraph, rawcardinalities, renderdistinctness, semanticstate, show_bytecode, show_java_source, tostring, verboseeagernessreasons, visualizepipelines, warnoncompilationerrors",
}

func validateCypherPreamble(query string) error {
	rest := strings.TrimSpace(query)
	restOffset := strings.Index(query, rest)
	argumentError := func(message string) error {
		return nornicerrors.MarkCompileTime(newSemanticError("Neo.ClientError.Statement.ArgumentError", "InvalidArgument", message))
	}
	consumeGap := func(index int) error {
		end, unclosed := readQueryGap(rest, index)
		if unclosed >= 0 {
			return unclosedCommentError(query, restOffset+unclosed, ModeNormal)
		}
		restOffset += end
		rest = rest[end:]
		return nil
	}
	var seenVersion string
	for rest != "" {
		if mode, inner := executionModePrefix(rest); mode != ModeNormal {
			restOffset += len(rest) - len(inner)
			rest = inner
			continue
		}
		if !matchKeywordAt(rest, 0, "CYPHER") {
			return nil
		}
		if err := consumeGap(len("CYPHER")); err != nil {
			return err
		}
		if len(rest) > 0 && rest[0] >= '0' && rest[0] <= '9' {
			end := 0
			for end < len(rest) && ((rest[end] >= '0' && rest[end] <= '9') || rest[end] == '.') {
				end++
			}
			version := rest[:end]
			if version != "5" && version != "25" {
				return argumentError(fmt.Sprintf("%s is not a valid option for cypher version. Valid options are: 5, 25", version))
			}
			if seenVersion != "" && seenVersion != version {
				return argumentError("Can't specify multiple conflicting values for cypher version")
			}
			seenVersion = version
			if err := consumeGap(end); err != nil {
				return err
			}
		}
		// Comments between the preamble and its body are still source text.
		// Admit their terminator while consuming this existing prefix gap,
		// before option parsing can misreport an unfinished comment as syntax.
		if err := consumeGap(0); err != nil {
			return err
		}
		for rest != "" && !startsWithClauseKeyword(rest) {
			end := 0
			for end < len(rest) && isIdentByte(rest[end]) {
				end++
			}
			name := strings.ToLower(rest[:end])
			if err := consumeGap(end); err != nil {
				return err
			}
			if end == 0 || rest == "" || rest[0] != '=' {
				return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "invalid CYPHER option: expected name=value")
			}
			if err := consumeGap(1); err != nil {
				return err
			}
			end = 0
			for end < len(rest) && isIdentByte(rest[end]) {
				end++
			}
			if end == 0 {
				return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "invalid CYPHER option: expected a value")
			}
			value := strings.ToLower(rest[:end])
			if err := consumeGap(end); err != nil {
				return err
			}
			allowed, known := cypherPreambleOptionValues[name]
			if !known {
				return argumentError("Unsupported options: " + name)
			}
			valid := false
			for _, candidate := range strings.Split(allowed, ", ") {
				if value == candidate {
					valid = true
					break
				}
			}
			if !valid {
				return argumentError(fmt.Sprintf("%s is not a valid option for %s. Valid options are: %s", value, name, allowed))
			}
		}
	}
	return nil
}

func stripCypherPreamble(query string) (string, bool) {
	rest := query
	changed := false
	var modes []string
	for {
		trimmed := strings.TrimSpace(rest)
		if mode, inner := executionModePrefix(trimmed); mode != ModeNormal {
			modes = append(modes, string(mode))
			rest = inner
			continue
		}
		if !matchKeywordAt(trimmed, 0, "CYPHER") {
			break
		}
		changed = true
		rest = strings.TrimSpace(trimmed[queryGapEnd(trimmed, len("CYPHER")):])
		// Optional version number (e.g. CYPHER 5, CYPHER 25).
		if len(rest) > 0 && rest[0] >= '0' && rest[0] <= '9' {
			i := 0
			for i < len(rest) && rest[i] >= '0' && rest[i] <= '9' {
				i++
			}
			rest = strings.TrimSpace(rest[queryGapEnd(rest, i):])
		}
		// Option tokens until the next clause keyword starts the statement.
		for rest != "" && !startsWithClauseKeyword(rest) {
			if isCypherStringQuoteByte(rest[0]) {
				end := skipCypherQuotedText(rest, 0, rest[0])
				rest = strings.TrimSpace(rest[queryGapEnd(rest, end):])
				continue
			}
			i := 0
			for i < len(rest) && !isASCIISpace(rest[i]) && queryCommentEnd(rest, i) < 0 {
				i++
			}
			rest = strings.TrimSpace(rest[queryGapEnd(rest, i):])
		}
		if rest == "" {
			break
		}
	}
	if changed {
		if len(modes) > 0 {
			return strings.Join(modes, " ") + " " + strings.TrimSpace(rest), true
		}
		return strings.TrimSpace(rest), true
	}
	return query, false
}

// finishProhibitedClauses are the clause keywords a statement may not end
// with before FINISH. Neo4j 5.26 rejects FINISH only after RETURN ("RETURN can
// only be used at the end of the query"); after WITH or YIELD it ends the
// statement like after any other clause and returns no rows (#907). A
// prohibited trailing FINISH stays in the text so validation rejects it.
var finishProhibitedClauses = map[string]bool{
	"RETURN": true,
}

// trailingBareFinish reports whether the statement ends with a standalone
// FINISH keyword outside quotes and comments. A trailing `finish` where a
// name or an expression is read (RETURN finish, x AS finish, DELETE finish,
// m.finish) is a variable, not the clause: FINISH is not a reserved word in
// Neo4j (#958).
func trailingBareFinish(cypher string) (string, bool) {
	last := lastLiveByte(cypher, len(cypher))
	if last < 0 || !isIdentByte(cypher[last]) {
		return "", false
	}
	end := last + 1
	start := end
	for start > 0 && isIdentByte(cypher[start-1]) {
		start--
	}
	if !strings.EqualFold(cypher[start:end], "FINISH") {
		return "", false
	}
	remainder := strings.TrimSpace(cypher[:start])
	// A FINISH with nothing before it is the whole statement, the clause.
	if remainder != "" && clauseKeywordUsedAsName(cypher, start, end, "FINISH") {
		return "", false
	}
	return remainder, true
}

// stripTrailingFinish removes a trailing FINISH clause terminator (Neo4j 5.19+:
// FINISH ends a query without returning rows). FINISH counts unless the
// preceding top-level clause is RETURN (finishProhibitedClauses); a trailing
// FINISH after RETURN stays in the text so validation rejects it. The
// preceding clause comes from the shared name-aware scanner
// lastTopLevelClauseWord (validator_strictness.go): one clause scanner for
// both the FINISH position and the dangling-UNWIND rule.
func stripTrailingFinish(cypher string) (string, bool) {
	remainder, ok := trailingBareFinish(cypher)
	if !ok {
		return cypher, false
	}
	if finishProhibitedClauses[lastTopLevelClauseWord(remainder)] {
		return cypher, false
	}
	return remainder, true
}

type finishedStatementKey struct{}

// withFinishedStatement records that statement (the text left after its
// trailing FINISH was stripped) ended in FINISH. A CALL … YIELD with WHERE,
// ORDER BY, SKIP or LIMIT that is the whole statement is then not a
// standalone call: FINISH is the clause after it, as in Neo4j (#907).
func withFinishedStatement(ctx context.Context, statement string) context.Context {
	return context.WithValue(ctx, finishedStatementKey{}, strings.Join(strings.Fields(statement), " "))
}

// endsInFinish reports whether statement is the one withFinishedStatement
// recorded, compared with whitespace normalized: a CALL a subquery or a
// procedure runs inside the statement is not.
func endsInFinish(ctx context.Context, statement string) bool {
	finished, _ := ctx.Value(finishedStatementKey{}).(string)
	return finished != "" && finished == strings.Join(strings.Fields(statement), " ")
}

// topLevelUnionCut returns the offset of the first top-level UNION keyword
// (outside quotes, comments and nested delimiters), or -1.
func topLevelUnionCut(s string) int {
	parenDepth, bracketDepth, braceDepth := 0, 0, 0
	for i := 0; i < len(s); i++ {
		if end, quoted := skipCypherLexicalToken(s, i); quoted {
			i = end - 1
			continue
		}
		c := s[i]
		switch c {
		case '(':
			parenDepth++
		case ')':
			parenDepth--
		case '[':
			bracketDepth++
		case ']':
			bracketDepth--
		case '{':
			braceDepth++
		case '}':
			braceDepth--
		}
		if parenDepth == 0 && bracketDepth == 0 && braceDepth == 0 &&
			matchKeywordAt(s, i, "UNION") {
			return i
		}
	}
	return -1
}

// stripUnionBranchFinishes strips a trailing FINISH from each UNION branch of
// the statement. If no branch ends in FINISH the text is unchanged.
func stripUnionBranchFinishes(ctx context.Context, cypher string) (string, bool) {
	cut := topLevelUnionCut(cypher)
	if cut < 0 {
		return stripTrailingFinish(cypher)
	}
	before := strings.TrimSpace(cypher[:cut])
	after := strings.TrimSpace(cypher[cut:])
	// Consume UNION and an optional ALL.
	wordEnd := 0
	for wordEnd < len(after) && !isASCIISpace(after[wordEnd]) {
		wordEnd++
	}
	unionWord := after[:wordEnd]
	tail := strings.TrimSpace(after[wordEnd:])
	if nextWord, ok := firstWordUpper(tail); ok && nextWord == "ALL" {
		unionWord += " ALL"
		tail = strings.TrimSpace(tail[len("ALL"):])
	}
	right, rightStripped := stripUnionBranchFinishes(ctx, tail)
	left, leftStripped := stripTrailingFinish(before)
	if !leftStripped && !rightStripped {
		return cypher, false
	}
	if leftStripped && rightStripped && left == "" && right == "" {
		if _, _, mixed, _ := parseTopLevelUnionBranches(ctx, cypher); !mixed {
			return "", true
		}
		return cypher, false
	}
	return strings.TrimSpace(left + " " + unionWord + " " + right), true
}

func firstWordUpper(s string) (string, bool) {
	i := 0
	for i < len(s) && !isASCIISpace(s[i]) {
		i++
	}
	if i == 0 {
		return "", false
	}
	return upperASCII(s[:i]), true
}

func explainProfileConflict(cypher string) bool {
	_, statement, conflict := statementExecutionModes(cypher)
	return conflict && queryGapEnd(statement, 0) < len(statement)
}

// completeFinishedResult applies FINISH before the declared schema is checked.
// Internal and public execution share this terminal projection.
func completeFinishedResult(result *ExecuteResult) {
	if result != nil {
		result.Columns = nil
		result.Rows = nil
	}
}

package cypher

import (
	"context"
	"slices"
	"strings"
)

// typeScope is the one static type of every variable a clause sees (#1055).
// The match validator's binding kinds (matchSemanticScope) and the static
// checks' value and member types (staticTypeScope) are views of it, so a
// projected expression is typed once, by projectedOperand, for both.
type typeScope map[string]staticOperand

// isEntityTypeName reports a static type the binding kinds hold themselves.
func isEntityTypeName(typeName string) bool {
	switch typeName {
	case "Node", "Relationship", "List<Node>", "List<Relationship>", "Path":
		return true
	}
	return false
}

// kinds is the binding-kind view of types.
func (types typeScope) kinds() matchSemanticScope {
	kinds := make(matchSemanticScope, len(types))
	for name, operand := range types {
		kinds[name] = gateProven(operand).bindingKind()
	}
	return kinds
}

// static is the static checks' view of types: the binding kinds, the types of
// variables that aren't entities, and the member types of maps.
func (types typeScope) static(cypher25 bool) staticTypeScope {
	scope := staticTypeScope{kinds: types.kinds(), complete: true, cypher25: cypher25}
	for name, operand := range types {
		// The views hold only what a verified rule proved.
		operand = gateProven(operand)
		// Every value operand travels whole (its alternatives and its
		// constraints), so a later clause reads exactly what the projection
		// derived; the type-name view below is derived from it.
		if operand.typeName() != "" && !isEntityTypeName(operand.typeName()) || operand.nonEntity {
			if scope.derived == nil {
				scope.derived = make(map[string]staticOperand)
			}
			scope.derived[name] = operand
		}
		if typeName := operand.typeName(); typeName != "" && !isEntityTypeName(typeName) {
			if scope.values == nil {
				scope.values = make(map[string]string)
			}
			scope.values[name] = typeName
		}
		if operand.members != nil {
			if scope.members == nil {
				scope.members = make(map[string]map[string]staticOperand)
			}
			scope.members[name] = operand.members
		}
	}
	return scope
}

// typeScopeOf is the typeScope a staticTypeScope's views describe.
func typeScopeOf(scope staticTypeScope) typeScope {
	types := make(typeScope, len(scope.kinds)+len(scope.values))
	for name, kind := range scope.kinds {
		types[name] = operandOfKind(kind)
	}
	for name, typeName := range scope.values {
		if isEntityTypeName(types[name].typeName()) {
			continue
		}
		types[name] = typedOperand(typeName).proved()
	}
	for name, members := range scope.members {
		operand := types[name]
		operand.members = members
		types[name] = operand
	}
	for name, operand := range scope.derived {
		types[name] = operand
	}
	return types
}

// projectTypeScope is the typeScope a WITH clause projects from types: each
// item's operand by its alias, every variable for WITH *.
func projectTypeScope(ctx context.Context, types typeScope, cypher25 bool, clause string) typeScope {
	return projectTypeScopeIn(ctx, types, types.static(cypher25), clause)
}

// projectTypeScopeIn is projectTypeScope for a caller that holds types'
// static view (input) already.
func projectTypeScopeIn(ctx context.Context, types typeScope, input staticTypeScope, clause string) typeScope {
	return projectLocalTypeScope(ctx, types, types, input, clause)
}

func projectLocalTypeScope(ctx context.Context, types, named typeScope, input staticTypeScope, clause string) typeScope {
	if input.projected != nil {
		return typeScopeOf(*input.projected)
	}
	values, _, err := (&StorageExecutor{}).enrichBoundTypes(ctx, clause, types, input.bindings, "", input.cypher25)
	if err != nil || values == nil {
		return nil
	}
	statement := values.program.root.program.statement
	return values.selectValues(statement.After)
}

// forEachProjectedBinding supplies projection grammar to constructor read
// events and importing-WITH. Admitted type enrichment never calls it. A proof need not allocate or infer
// another type scope just to observe which incoming bindings a * consumes.
func (types typeScope) forEachProjectedBinding(ctx context.Context, clause string, visit func(name, expression, text string, inherited bool)) (wildcard bool) {
	plan := returnProjectionPlanFor(ctx, clause)
	if !plan.valid {
		return false
	}
	wildcard = plan.star
	if wildcard {
		names := make([]string, 0, len(types))
		for name := range types {
			names = append(names, name)
		}
		slices.Sort(names)
		plan = plan.withStarExpanded(names)
	}
	for _, item := range plan.projections {
		inherited := wildcard && item.definitionStart == -1 && item.direct
		text := item.expr + " AS " + projectionVariableText(item.alias)
		visit(item.alias, item.expr, text, inherited)
	}
	return wildcard
}

// projectedSourceVariable distinguishes a variable's identity from a literal
// with the same spelling. Quoted true/null remain variables; their unquoted
// spellings are values. Projection types and import provenance share this fact.
func projectedSourceVariable(expression string) string {
	expression = unwrapOuterParens(strings.TrimSpace(StripComments(expression)))
	name := simpleSemanticIdentifier(expression)
	if name != "" && (isBacktickQuotedName(expression) || !isLiteralKeyword(name)) {
		return name
	}
	return ""
}

// projectedOperand is the static type of a projected expression, as Neo4j
// types it before the statement runs: a bare variable's own; null a Null
// (open to any kind); coalesce of variables of one kind and a list of nodes or of
// relationships that kind; collect of nodes or relationships their list, a
// count an Integer, any other aggregate a value; a node's or relationship's
// property a value of unknown type; a map member unknown in Cypher 5; and
// any other expression the type the static operator check gives it (a
// literal, arithmetic, a function's result, CASE, a comparison, a map
// projection, a comprehension, a subscript or slice of a typed list).
func projectedOperand(ctx context.Context, types typeScope, input staticTypeScope, expression string) staticOperand {
	expression = strings.TrimSpace(expression)
	if strings.EqualFold(expression, "null") {
		// Null, as written in place (+z of WITH null AS z is a number); it
		// fits every position and binds as any kind (bindingKind).
		return provenOperand("Null")
	}
	if source := projectedSourceVariable(expression); source != "" {
		return types[source]
	}
	if kind, ok := entityListLiteralKind(expression, input.kinds); ok {
		return operandOfKind(kind)
	}
	// Every other expression has the one static type its scope derives.
	return input.operandOf(ctx, expression)
}

// unwoundOperand is the static type of the variable UNWIND binds from list:
// a list's element type (a node of a List<Node>, an Integer of a
// List<Integer>), a known non-list value itself (UNWIND 5), unknown for a
// list of unknown elements.
func unwoundOperand(ctx context.Context, types typeScope, input staticTypeScope, clause string) staticOperand {
	return listElementOperand(ctx, types, input, unwindSourceExpression(clause))
}

// listElementOperand is the static type of an element of list (UNWIND's
// variable, a comprehension's or quantifier's local; localBindingKind).
func listElementOperand(ctx context.Context, types typeScope, input staticTypeScope, list string) staticOperand {
	operand := projectedOperand(ctx, types, input, list)
	if !operand.union && operand.known() && !operand.list() {
		return operand // UNWIND 5 binds 5
	}
	if unwound := operand.unwoundOperand(); unwound.typeName() != "" {
		return unwound
	}
	// The deriver typed the list; its elements are what it derived, or
	// unknown.
	return staticOperand{}
}

// projectMatchSemanticScope is the binding-kind view of the variables a WITH
// clause projects (projectTypeScope).
func projectMatchSemanticScope(ctx context.Context, input matchSemanticScope, clause string) matchSemanticScope {
	scope := staticTypeScope{kinds: input}
	return projectTypeScopeIn(ctx, typeScopeOf(scope), scope, clause).kinds()
}

// projectStaticValueTypes is the value-type view of the variables a WITH
// clause projects (projectTypeScope).
func projectStaticValueTypes(ctx context.Context, scope staticTypeScope, clause string) map[string]string {
	return projectTypeScopeIn(ctx, typeScopeOf(scope), scope, clause).static(scope.cypher25).values
}

// projectStaticValueMembers is, in a Cypher 25 statement, the member-type
// view of the variables a WITH clause projects (projectTypeScope).
func projectStaticValueMembers(ctx context.Context, scope staticTypeScope, clause string) map[string]map[string]staticOperand {
	if !scope.cypher25 {
		return nil
	}
	return projectTypeScopeIn(ctx, typeScopeOf(scope), scope, clause).static(true).members
}

// callSubqueryReturnTypes walks a CALL subquery's body, each UNION branch
// as a query of its own, with the one clause walk (semanticScopeWalk) from
// the variables resolved by callQueryScope, and returns the static
// type of each column a one-branch body returns. Its expression subqueries
// see the body's scope, not the enclosing query's. A CALL (a, b) body sees
// its imports through the whole body, after a WITH in it too, and may
// declare them again (subqueryScope). A body whose walk stops early, or that
// doesn't end in RETURN, gives no types; a scoped body's walk error is the
// statement's.
func (e *StorageExecutor) callSubqueryReturnTypes(ctx context.Context, callText string, branches []string, outer typeScope, cypher25 bool) (typeScope, error) {
	model, err := e.callQueryScope(ctx, callText, outer, subqueryScope{}, cypher25)
	if err != nil || model == nil {
		return nil, err
	}
	return model.returned, nil
}

package cypher

import (
	"context"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
)

// cypherVersionKey carries the statement's Cypher language version ("5" or
// "25") to the subquery bodies it evaluates.
type cypherVersionKey struct{}

// withCypherVersion records the language version of the statement that
// starts here. A nested statement (a subquery body run on its own, with no
// CYPHER prefix) keeps its parent's version. Cypher 5, the default, isn't
// recorded: a nested statement under a Cypher 5 one reads 5 either way, and
// the common statement costs no allocation.
func withCypherVersion(ctx context.Context, query string) context.Context {
	if _, ok := ctx.Value(cypherVersionKey{}).(string); ok {
		return ctx
	}
	switch version := cypherGrammarVersion(query); version {
	case "5":
		return ctx
	case "25":
		return context.WithValue(ctx, cypherVersionKey{}, "25")
	default:
		return context.WithValue(ctx, cypherVersionKey{}, version)
	}
}

// cypherVersionFromContext is the statement's language version, "5" by
// default.
func cypherVersionFromContext(ctx context.Context) string {
	if version, ok := ctx.Value(cypherVersionKey{}).(string); ok {
		return version
	}
	return "5"
}

// cypher5ImportGrouping applies Cypher 5's scoping of an EXISTS / COUNT /
// COLLECT { … } body's imported variables (the outer row's names) to the
// body's aggregating projections. In Cypher 5 the imports stay in scope
// through every clause, so:
//
//   - an aggregating WITH groups by the imports read after it: over no rows
//     it has no row, where Cypher 25 has one (WITH count(*) AS c RETURN c + g
//     is [] in Cypher 5, [1] in Cypher 25);
//   - a projected item that aggregates and reads an import outside its
//     aggregates is Neo4j 5's implicit-grouping error (RETURN count(*) + g).
//
// Cypher 25 aggregates over the body's rows alone, as the body runs.
func cypher5ImportGrouping(body string, imports map[string]interface{}) (string, error) {
	if len(imports) == 0 || !containsAggregateFunc(body) {
		return body, nil
	}
	words := projectionWords(body)
	type insertion struct {
		at   int
		text string
	}
	var insertions []insertion
	for index, word := range words {
		if word.depth != 0 || word.upper != "WITH" && word.upper != "RETURN" || precededByWord(body, word.start, "STARTS", "ENDS") {
			continue
		}
		itemsStart := skipASCIISpaces(body, word.end, len(body))
		if matchKeywordAt(body, itemsStart, "DISTINCT") {
			itemsStart = skipASCIISpaces(body, itemsStart+len("DISTINCT"), len(body))
		}
		itemsEnd := len(body)
		for _, next := range words[index+1:] {
			if next.depth == 0 && groupByKeysEnd(next.upper, "WITH") {
				itemsEnd = next.start
				break
			}
		}
		items := splitTopLevelComma(body[itemsStart:itemsEnd])
		aggregating := false
		projected := map[string]bool{}
		for _, item := range items {
			expression, alias := projectionItemAlias(item)
			projected[alias] = true
			spans := findAggregateSpans(expression)
			if len(spans) == 0 {
				continue
			}
			aggregating = true
			outside := expression
			for i := len(spans) - 1; i >= 0; i-- {
				outside = outside[:spans[i].start] + " " + outside[spans[i].end:]
			}
			for _, name := range expressionVariables(outside) {
				if _, imported := imports[name]; imported {
					return "", localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidSyntax",
						localization.CypherCoreGroupByImplicitGroupingKey(name))
				}
			}
		}
		if !aggregating || word.upper != "WITH" {
			continue
		}
		var keys []string
		for _, name := range expressionVariables(body[itemsEnd:]) {
			if _, imported := imports[name]; imported && !projected[name] {
				keys = append(keys, name)
			}
		}
		if len(keys) > 0 {
			insertions = append(insertions, insertion{at: itemsStart, text: strings.Join(keys, ", ") + ", "})
		}
	}
	for i := len(insertions) - 1; i >= 0; i-- {
		body = body[:insertions[i].at] + insertions[i].text + body[insertions[i].at:]
	}
	return body, nil
}

package cypher

import (
	"context"
	"fmt"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// A subquery expression (EXISTS { … }, COUNT { … }, COLLECT { … }) is a value
// like any other: it may appear inside list and map literals, arithmetic,
// comparisons, CASE, list-comprehension filters and function arguments, and
// as a SET / CREATE / MERGE property value. The row evaluator evaluates
// each one where it stands (evaluateRowSubqueryAtom), with the variables
// bound at that point and the statement context the row carries (#1055).

// subqueryExpression is one EXISTS / COUNT / COLLECT { body } occurrence.
type subqueryExpression struct {
	kind       string // EXISTS, COUNT or COLLECT
	start, end int    // expression text [start, end)
	body       string
}

var subqueryExpressionKeywords = [...]string{"EXISTS", "COUNT", "COLLECT"}

// mayContainSubqueryExpression is the cheap precheck the evaluators run on
// every expression: a subquery expression needs a brace and one of the
// keywords.
func mayContainSubqueryExpression(expr string) bool {
	if strings.IndexByte(expr, '{') < 0 {
		return false
	}
	for _, keyword := range subqueryExpressionKeywords {
		if containsFold(expr, keyword) {
			return true
		}
	}
	return false
}

// findSubqueryExpressions returns the outermost subquery expressions in expr,
// outside string literals and quoted names.
func findSubqueryExpressions(expr string) []subqueryExpression {
	var found []subqueryExpression
	for i := 0; i < len(expr); {
		if end, skipped := skipCypherLexicalToken(expr, i); skipped {
			i = end
			continue
		}
		keyword, open, isSubquery := subqueryExpressionKeywordAt(expr, i)
		if !isSubquery {
			i++
			continue
		}
		closing := findMatchingDelimiter(expr, open, '{', '}')
		if closing < 0 {
			return found
		}
		found = append(found, subqueryExpression{
			kind:  keyword,
			start: i,
			end:   closing + 1,
			body:  strings.TrimSpace(expr[open+1 : closing]),
		})
		i = closing + 1
	}
	return found
}

// subqueryExpressionKeywordAt reports whether an EXISTS / COUNT / COLLECT
// subquery expression starts at expr[i]: the keyword, then its body's '{'
// (at open). It is the one reader of where a subquery expression starts.
func subqueryExpressionKeywordAt(expr string, i int) (keyword string, open int, ok bool) {
	for _, keyword := range subqueryExpressionKeywords {
		if !matchKeywordAt(expr, i, keyword) {
			continue
		}
		if open := queryGapEnd(expr, i+len(keyword)); open < len(expr) && expr[open] == '{' && subqueryExpressionKeywordBeforeBrace(expr, i, i+len(keyword), open) {
			return keyword, open, true
		}
	}
	return "", 0, false
}

// nestedSubqueryExpressions returns the subquery expressions of expr when
// there is at least one and expr isn't a single subquery expression.
func nestedSubqueryExpressions(expr string) []subqueryExpression {
	if !mayContainSubqueryExpression(expr) {
		return nil
	}
	found := findSubqueryExpressions(expr)
	if len(found) == 0 || (len(found) == 1 && found[0].start == 0 && found[0].end == len(expr)) {
		return nil
	}
	return found
}

// standaloneSubqueryExpression returns expr's subquery expression when expr is
// exactly one EXISTS / COUNT / COLLECT { … }.
func standaloneSubqueryExpression(expr string) (subqueryExpression, bool) {
	expr = strings.TrimSpace(expr)
	if !mayContainSubqueryExpression(expr) {
		return subqueryExpression{}, false
	}
	found := findSubqueryExpressions(expr)
	if len(found) != 1 || found[0].start != 0 || found[0].end != len(expr) {
		return subqueryExpression{}, false
	}
	return found[0], true
}

// rowSubqueryPlan is the shape of a predicate holding subquery expressions,
// read once per predicate text: the subqueries, and the predicate with each
// one masked by a name (__subquery_value_N), on which logical and
// integerComparison are read. logical is true when the predicate has a
// top-level AND / OR / XOR, which splits it before its subqueries run, so each
// side's subquery only runs when its value is needed.
type rowSubqueryPlan struct {
	found     []subqueryExpression
	names     []string
	rewritten string
	logical   bool
	// integerComparison is set when the rewritten predicate is exactly
	// __subquery_value_0 <op> <integer literal> (COUNT { … } > 1): the
	// comparison is parsed once and applied to an integer value directly.
	integerComparison *integerComparison
}

// integerComparison is a comparison with an integer literal, parsed once.
type integerComparison struct {
	operator string
	literal  int64
}

// parseIntegerComparison parses "<op> <integer literal>".
func parseIntegerComparison(comparison string) (*integerComparison, bool) {
	comparison = strings.TrimSpace(comparison)
	for _, operator := range [...]string{"<>", "!=", "<=", ">=", "=", "<", ">"} {
		if !strings.HasPrefix(comparison, operator) {
			continue
		}
		literal, err := strconv.ParseInt(strings.TrimSpace(comparison[len(operator):]), 10, 64)
		if err != nil {
			return nil, false
		}
		return &integerComparison{operator: operator, literal: literal}, true
	}
	return nil, false
}

// holds compares value with the literal, as the comparison evaluator does for
// two integers.
func (c *integerComparison) holds(value int64) bool {
	matched, _ := compareCypherPredicateValue(value, c.literal, c.operator).(bool)
	return matched
}

// rowSubqueryPlans caches row subquery plans by expression text: an
// expression is planned once, not once per row. A nil plan (no subquery in a
// larger expression) is cached too.
var rowSubqueryPlans = newBoundedCache[string, *rowSubqueryPlan](1024, boundedCacheStringShardIndex)

// planRowSubqueries returns expr's plan when it holds subquery expressions
// inside a larger expression (nestedSubqueryExpressions), and nil otherwise.
func planRowSubqueries(expr string) *rowSubqueryPlan {
	if !mayContainSubqueryExpression(expr) {
		return nil
	}
	plan, cached := rowSubqueryPlans.get(expr)
	if cached {
		return plan
	}
	if found := nestedSubqueryExpressions(expr); found != nil {
		plan = &rowSubqueryPlan{found: found, names: make([]string, len(found))}
		var rewritten strings.Builder
		cursor := 0
		for index, subquery := range found {
			plan.names[index] = "__subquery_value_" + strconv.Itoa(index)
			rewritten.WriteString(expr[cursor:subquery.start])
			rewritten.WriteString(plan.names[index])
			cursor = subquery.end
		}
		rewritten.WriteString(expr[cursor:])
		plan.rewritten = rewritten.String()
		for _, operator := range []string{" AND ", " OR ", " XOR "} {
			if _, _, split := splitByOperatorWithOptions(plan.rewritten, operator, true, true); split {
				plan.logical = true
				break
			}
		}
		if !plan.logical && len(found) == 1 && strings.HasPrefix(plan.rewritten, plan.names[0]) {
			plan.integerComparison, _ = parseIntegerComparison(plan.rewritten[len(plan.names[0]):])
		}
	}
	rowSubqueryPlans.put(expr, plan)
	return plan
}

// correlatedSubqueryExecutor returns an executor whose pipeline sees the row's
// values as outer bindings (fabricRecordBindings), for a subquery body that
// refers to them.
func (e *StorageExecutor) correlatedSubqueryExecutor(ctx context.Context, values map[string]interface{}) *StorageExecutor {
	correlated := e.cloneWithStorage(e.getStorage(ctx))
	correlated.fabricRecordBindings = make(map[string]interface{}, len(e.fabricRecordBindings)+len(values))
	for name, value := range e.fabricRecordBindings {
		correlated.fabricRecordBindings[name] = value
	}
	for name, value := range values {
		if strings.HasPrefix(name, "\x00") {
			continue // the evaluator's own keys (rowStatementContextKey) aren't variables
		}
		correlated.fabricRecordBindings[name] = value
	}
	return correlated
}

// rowSubqueryAtom reads an expression that is one EXISTS / COUNT / COLLECT
// { … } subquery: its keyword and the position of its {. The one reader of
// the form, for evaluateRowSubqueryAtom and the compiled row programs.
func rowSubqueryAtom(expr string) (kind string, open int, ok bool) {
	if expr == "" {
		return "", 0, false
	}
	switch expr[0] {
	case 'E', 'e', 'C', 'c':
	default:
		return "", 0, false
	}
	kind, open, ok = subqueryExpressionKeywordAt(expr, 0)
	if !ok || findMatchingDelimiter(expr, open, '{', '}') != len(expr)-1 {
		return "", 0, false
	}
	return kind, open, true
}

// evaluateRowSubqueryAtom evaluates an expression that is one EXISTS / COUNT /
// COLLECT { … } subquery for the row evaluator, with the row's variables, in
// the statement context the row carries (rowStatementContextKey). Nested in
// a larger expression, the subquery is reached by the row evaluator's own
// recursion, so it sees the variables bound at that point (a quantifier's, a
// comprehension's, reduce's). matched is false for any other expression and
// when the row carries no statement context.
func (e *StorageExecutor) evaluateRowSubqueryAtom(expr string, values map[string]interface{}) (interface{}, bool, error) {
	kind, open, ok := rowSubqueryAtom(expr)
	if !ok {
		return nil, false, nil
	}
	ctx := rowStatementContext(values)
	if ctx == nil {
		return nil, false, nil
	}
	value, resolved, err := e.rowSubqueryValue(ctx, kind, strings.TrimSpace(expr[open+1:len(expr)-1]), values)
	if err != nil {
		return nil, true, err
	}
	if !resolved {
		return nil, false, nil
	}
	return value, true, nil
}

// evaluateRowSubqueryValue evaluates EXISTS / COUNT / COLLECT { body } for a
// row, correlated with the row's values: EXISTS is whether the body has a row,
// COUNT how many rows it has, COLLECT the list of its single returned column.
// A body that is only a pattern is matched as MATCH <pattern>.
func (e *StorageExecutor) evaluateRowSubqueryValue(ctx context.Context, kind, body string, values map[string]interface{}) (interface{}, bool) {
	value, ok, err := e.rowSubqueryValue(ctx, kind, body, values)
	if err != nil {
		recordExpressionFailure(ctx, err)
		return nil, false
	}
	return value, ok
}

// rowSubqueryValue is evaluateRowSubqueryValue returning the subquery's error
// instead of recording it. It is the one evaluator of EXISTS / COUNT /
// COLLECT subqueries: the body runs as a pipeline, so its WHERE, ORDER BY,
// SKIP / LIMIT and RETURN all apply.
func (e *StorageExecutor) rowSubqueryValue(ctx context.Context, kind, body string, values map[string]interface{}) (interface{}, bool, error) {
	body = strings.TrimSpace(body)
	if body == "" {
		return nil, false, nil
	}
	// EXISTS is whether the body has a row and COUNT how many: one
	// evaluation, so a body gives EXISTS and COUNT the same rows.
	if kind == "EXISTS" || kind == "COUNT" {
		if count, ok := e.boundNodeLookupCount(ctx, body, values, kind == "EXISTS"); ok {
			return rowCountValue(kind, count), true, nil
		}
		if count, ok := e.boundDegreeCount(ctx, body, values); ok {
			return rowCountValue(kind, count), true, nil
		}
		if count, ok := e.boundChainCount(ctx, body, values, kind == "EXISTS"); ok {
			return rowCountValue(kind, count), true, nil
		}
	}
	if cypherVersionFromContext(ctx) != "25" {
		grouped, err := cypher5ImportGrouping(body, values)
		if err != nil {
			return nil, false, err
		}
		body = grouped
	}
	query := strings.TrimSpace(body)
	patternOnly := strings.HasPrefix(query, "(")
	if patternOnly {
		query = "MATCH " + query
	}
	if topLevelKeywordIndex(query, "RETURN") < 0 {
		switch kind {
		case "COUNT":
			query += " RETURN 1 AS __count"
		case "EXISTS":
			query += " RETURN 1 AS __exists LIMIT 1"
		}
	}
	result, err := e.runCorrelatedSubquery(ctx, query, values)
	if err != nil {
		return nil, false, err
	}
	if result == nil {
		return nil, false, nil
	}
	queryStatsAccumulatorFromContext(ctx).add(result.Stats)
	if kind == "EXISTS" || kind == "COUNT" {
		return rowCountValue(kind, int64(len(result.Rows))), true, nil
	}
	// A COLLECT subquery collects one value per row: its RETURN has
	// exactly one column (Neo4j 5.26 rejects any other RETURN, #907).
	if len(result.Columns) != 1 {
		return nil, false, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidCollectSubquery",
			localization.CypherSubqueriesCollectSingleColumn(len(result.Columns)))
	}
	collected := make([]interface{}, 0, len(result.Rows))
	for _, row := range result.Rows {
		if len(row) > 0 {
			collected = append(collected, row[0])
		}
	}
	return collected, true, nil
}

// rowCountValue is a subquery's value from its number of rows: EXISTS is
// whether it has one, COUNT the number.
func rowCountValue(kind string, rows int64) interface{} {
	if kind == "EXISTS" {
		return rows > 0
	}
	return rows
}

// runCorrelatedSubquery runs a subquery body for a row: as a pipeline
// correlated with the row's values, and through the full executor with those
// values bound when the pipeline declines the body (a CALL subquery or a
// procedure call in it, …). EXISTS, COUNT and COLLECT all run their bodies
// here, so a body gives the same rows whichever of them wraps it.
func (e *StorageExecutor) runCorrelatedSubquery(ctx context.Context, query string, values map[string]interface{}) (*ExecuteResult, error) {
	// Correlated expression imports remain visible across a WITH horizon. The
	// existing context masks them when a nested CALL selects its own imports.
	// Without a WITH there is no dropping horizon and the row already owns them.
	if indexASCIIFold(query, "with") >= 0 {
		imports := pipelineRow(values)
		for name := range values {
			if strings.HasPrefix(name, "$") || strings.HasPrefix(name, "\x00") {
				imports = make(pipelineRow, len(values))
				for variable, value := range values {
					if !strings.HasPrefix(variable, "$") && !strings.HasPrefix(variable, "\x00") {
						imports[variable] = value
					}
				}
				break
			}
		}
		ctx = withPipelineImports(ctx, imports)
	}
	// The expression's current lexical row owns its imports. A traversal's
	// ambient context may still bind the same name to an earlier endpoint;
	// it must not replace a quantifier/comprehension/reduce local in the body.
	// Without an ambient value scope the correlated executor already seeds
	// the pipeline from values, so it needs no additional context allocation.
	if len(valueBindingsFromContext(ctx)) != 0 {
		ctx = withValueBindings(ctx, values)
	}
	// A UNION body: each branch runs for the row, and the shared UNION
	// combiner (executeUnion) joins them, as for a top-level UNION.
	if _, unionAll, _, union := parseTopLevelUnionBranches(ctx, query); union {
		return e.executeUnion(ctx, query, unionAll, func(branch string) (*ExecuteResult, error) {
			return e.runCorrelatedSubquery(ctx, branch, values)
		})
	}
	outcome := e.correlatedSubqueryExecutor(ctx, values).executePipeline(ctx, query)
	if outcome.terminal() {
		return outcome.result, outcome.err
	}
	return e.executeCorrelatedSubqueryBody(ctx, query, values)
}

// executeCorrelatedSubqueryBody runs a subquery body through the full
// executor with the row's values it uses bound the way MATCH … CALL binds a
// correlated subquery's imports: a node as MATCH (v) WHERE id(v) = $p, a
// relationship as MATCH ()-[v]->() WHERE id(v) = $p, any other value as
// WITH $p AS v. Row parameters stay available.
func (e *StorageExecutor) executeCorrelatedSubqueryBody(ctx context.Context, query string, values map[string]interface{}) (*ExecuteResult, error) {
	params := make(map[string]interface{}, len(values))
	for name, value := range getParamsFromContext(ctx) {
		params[name] = value
	}
	names := make([]string, 0, len(values))
	for name := range values {
		if !strings.HasPrefix(name, "$") && containsIdentifierWord(query, name) {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	var prefix strings.Builder
	carried := make([]string, 0, len(names))
	for index, name := range names {
		param := fmt.Sprintf("__subquery_row_%d", index)
		switch value := values[name].(type) {
		case *storage.Node:
			if value == nil {
				params[param] = nil
				carried = append(carried, "$"+param+" AS "+name)
				continue
			}
			params[param] = string(value.ID)
			fmt.Fprintf(&prefix, "MATCH (%s) WHERE id(%s) = $%s ", name, name, param)
			carried = append(carried, name)
		case *storage.Edge:
			if value == nil {
				params[param] = nil
				carried = append(carried, "$"+param+" AS "+name)
				continue
			}
			params[param] = string(value.ID)
			fmt.Fprintf(&prefix, "MATCH ()-[%s]->() WHERE id(%s) = $%s ", name, name, param)
			carried = append(carried, name)
		default:
			params[param] = value
			carried = append(carried, "$"+param+" AS "+name)
		}
	}
	if len(carried) > 0 {
		prefix.WriteString("WITH " + strings.Join(carried, ", ") + " ")
	}
	return e.executeInternal(ctx, prefix.String()+query, params)
}

// boundNodeLookupCount counts the rows of a body that is one labelled node
// pattern with a property map, MATCH (v:L {k: <expression>}) [WHERE …],
// whose variable the row doesn't bind, as Neo4j plans [NOT] EXISTS over it:
// SemiApply over a node index seek. The map's values are evaluated against
// the row, the candidates are the pipeline's own (its index seek, or its
// label scan), each is checked as the pipeline's node match checks it, and
// the WHERE runs on the row with the node, through the predicate plan
// already built for its text. EXISTS stops at the first match. It replaces
// a correlated pipeline run per row, which plans the WHERE's text again for
// every row; ok is false for any other body, a value of the map the row
// can't resolve, and under a temporal viewport. Execution failures are
// recorded and handled: callers must not retry a failed read as a new plan.
func (e *StorageExecutor) boundNodeLookupCount(ctx context.Context, body string, values map[string]interface{}, first bool) (int64, bool) {
	shape := clauseAnalysisFor(ctx, clauseAnalysisBoundNode, body, func(text string) boundNodeShape { return parseBoundNodeShape(ctx, text) })
	if !shape.ok {
		return 0, false
	}
	if viewport, ok := TemporalViewportFromContext(ctx); ok && viewport.Enabled() {
		return 0, false
	}
	if shape.variable != "" {
		if _, bound := values[shape.variable]; bound {
			return 0, false
		}
	}
	properties := make(map[string]interface{}, len(shape.keys))
	for index, key := range shape.keys {
		value, resolved, err := e.evaluateRowValue(shape.values[index], values)
		if err != nil {
			recordExpressionFailure(ctx, err)
			return 0, true
		}
		if !resolved {
			return 0, false
		}
		properties[key] = normalizePropValue(value)
	}
	pattern := nodePatternInfo{variable: shape.variable, labels: shape.labels, properties: properties}
	nodes, _, err := e.collectPipelineInitialNodeCandidates(ctx, pattern, "", pipelineMatchPhysicalHint{})
	if err != nil {
		recordExpressionFailure(ctx, err)
		return 0, true
	}
	// The candidates and the set that drops duplicates count while the
	// semi-join runs (#1343).
	memory := memoryScopeFromContext(ctx)
	mark := memory.mark()
	defer memory.releaseSince(mark)
	if err := memory.grow(int64(len(nodes)) * (entityReferenceBytes + mapEntryBytes + stringHeaderBytes)); err != nil {
		recordExpressionFailure(ctx, err)
		return 0, true
	}
	hideSystemNodes := shouldHideSystemNodes(e.storage)
	seen := make(map[storage.NodeID]struct{}, len(nodes))
	var row map[string]interface{}
	var count int64
	for _, node := range nodes {
		if node == nil || (hideSystemNodes && isSystemNode(node)) {
			continue
		}
		if _, duplicate := seen[node.ID]; duplicate {
			continue
		}
		seen[node.ID] = struct{}{}
		if !mergeNodeHasLabels(node, pattern.labels) || !e.nodeMatchesProps(node, pattern.properties) {
			continue
		}
		if shape.where != "" {
			if row == nil {
				row = make(map[string]interface{}, len(values)+1)
				for name, value := range values {
					row[name] = value
				}
			}
			if shape.variable != "" {
				row[shape.variable] = node
			}
			if !e.evaluateRowPredicate(ctx, shape.where, row) {
				continue
			}
		}
		count++
		if first {
			return count, true
		}
	}
	return count, true
}

// boundNodeShape is the text part of boundNodeLookupCount: the node
// pattern's variable, labels and map (keys and value expressions), and the
// body's WHERE.
type boundNodeShape struct {
	variable string
	labels   []string
	keys     []string
	values   []string
	where    string
	ok       bool
}

func parseBoundNodeShape(ctx context.Context, body string) boundNodeShape {
	pattern := strings.TrimSpace(body)
	if hasPrefixFold(pattern, "MATCH ") {
		pattern = strings.TrimSpace(pattern[len("MATCH"):])
	}
	if clauses, ok := splitPipelineClauses(ctx, "MATCH "+pattern); !ok || len(clauses) != 1 || clauses[0].kind != pipelineClauseMatch {
		return boundNodeShape{}
	}
	where := ""
	if index := topLevelKeywordIndex(pattern, "WHERE"); index >= 0 {
		where = strings.TrimSpace(pattern[index+len("WHERE"):])
		pattern = strings.TrimSpace(pattern[:index])
	}
	if !strings.HasPrefix(pattern, "(") || findMatchingParen(pattern, 0) != len(pattern)-1 || containsRelationshipPattern(pattern) ||
		extractPathAssignmentVariable(pattern) != "" || indexASCIIFold(body, "shortestpath") >= 0 || indexASCIIFold(body, repeatableElementsFunction) >= 0 {
		return boundNodeShape{}
	}
	head, props := splitNodePatternProperties(pattern)
	// Plain labels only: a label expression, a dynamic label or an inline
	// WHERE is the pipeline's.
	if props == "" || strings.ContainsAny(head, "|&!%$()") || indexASCIIFold(head, "WHERE") >= 0 || indexASCIIFold(head, " IS ") >= 0 {
		return boundNodeShape{}
	}
	variable, labels, labelErr := parseNodeHead(head)
	if labelErr != nil || len(labels) == 0 {
		return boundNodeShape{}
	}
	inner, enclosed := stripEnclosingRowDelimiter(strings.TrimSpace(props), '{', '}')
	if !enclosed || strings.TrimSpace(inner) == "" {
		return boundNodeShape{}
	}
	shape := boundNodeShape{variable: variable, labels: labels, where: where, ok: true}
	seen := map[string]bool{}
	for _, pair := range splitTopLevelComma(inner) {
		separator := findTopLevelMapKeyValueSeparator(pair)
		if separator <= 0 {
			return boundNodeShape{}
		}
		key := normalizePropertyKey(strings.TrimSpace(pair[:separator]))
		value := strings.TrimSpace(pair[separator+1:])
		if key == "" || value == "" || seen[key] {
			return boundNodeShape{}
		}
		seen[key] = true
		shape.keys = append(shape.keys, key)
		shape.values = append(shape.values, value)
	}
	return shape
}

// boundChainCount counts the rows of a body that is one relationship chain,
// with an optional WHERE, starting at a node bound in values: it traverses
// from that node and keeps the paths that agree with the row's other nodes
// and relationships and pass the WHERE. With first it stops at the first row
// (EXISTS). ok is false for any other body, which the traversal kernel or
// the correlated pipeline evaluates: a pattern list, a body reading a value
// of the row that isn't a node or relationship, a property map reading the
// row, a shortest path, or no bound start node.
func (e *StorageExecutor) boundChainCount(ctx context.Context, body string, values map[string]interface{}, first bool) (int64, bool) {
	pattern := strings.TrimSpace(body)
	if hasPrefixFold(pattern, "MATCH ") {
		pattern = strings.TrimSpace(pattern[len("MATCH"):])
	}
	// One MATCH clause, its WHERE included: a RETURN or any other clause is
	// the kernel's or the pipeline's.
	if clauses, ok := splitPipelineClauses(ctx, "MATCH "+pattern); !ok || len(clauses) != 1 || clauses[0].kind != pipelineClauseMatch {
		return 0, false
	}
	where := ""
	if index := topLevelKeywordIndex(pattern, "WHERE"); index >= 0 {
		where = strings.TrimSpace(pattern[index+len("WHERE"):])
		pattern = strings.TrimSpace(pattern[:index])
	}
	// A match mode or path selector (REPEATABLE ELEMENTS, ANY SHORTEST)
	// precedes the pattern; only the pipeline's MATCH runs those.
	if !strings.HasPrefix(pattern, "(") || len(splitTopLevelComma(pattern)) != 1 || !containsRelationshipPattern(pattern) ||
		extractPathAssignmentVariable(pattern) != "" || !patternMapsAreConstant(pattern) ||
		indexASCIIFold(body, "shortestpath") >= 0 || indexASCIIFold(body, repeatableElementsFunction) >= 0 {
		return 0, false
	}
	matches := e.parseTraversalPattern(ctx, pattern)
	if matches == nil || !chainVariablesBindEntities(matches, values) {
		return 0, false
	}
	seed, _ := values[matches.StartNode.variable].(*storage.Node)
	if seed == nil {
		return 0, false
	}
	var paths []PathResult
	if matches.IsChained && len(matches.Segments) > 1 {
		paths = e.traverseChainedGraph(ctx, matches, []*storage.Node{seed})
	} else {
		paths = e.traverseFromNode(ctx, seed, matches)
	}
	var count int64
	for _, path := range paths {
		inner := e.buildPathContext(path, matches)
		correlated := true
		for name, node := range inner.nodes {
			if bound, isNode := values[name].(*storage.Node); isNode && (bound == nil || node == nil || bound.ID != node.ID) {
				correlated = false
				break
			}
		}
		for name, relationship := range inner.rels {
			if !correlated {
				break
			}
			if bound, isRel := values[name].(*storage.Edge); isRel && (bound == nil || relationship == nil || bound.ID != relationship.ID) {
				correlated = false
				break
			}
		}
		if !correlated {
			continue
		}
		if where != "" {
			// The WHERE sees the row's values with the path's bindings.
			row := make(map[string]interface{}, len(values)+len(inner.nodes)+len(inner.rels))
			for name, value := range values {
				row[name] = value
			}
			for name, node := range inner.nodes {
				row[name] = node
			}
			for name, relationship := range inner.rels {
				row[name] = relationship
			}
			if !e.evaluateRowPredicate(ctx, where, row) {
				continue
			}
		}
		count++
		if first {
			return count, true
		}
	}
	return count, true
}

// patternMapsAreConstant reports whether every property map in a node or
// relationship pattern of pattern holds only literals and parameters
// ((n {id: 1}), ()-[:R {k: $k}]->()): boundChainCount's traversal matches
// those maps only. A map value that reads a variable ((n {id: r.prop}),
// (n {id: i + 1})) goes to the kernel or the pipeline, which evaluate it.
func patternMapsAreConstant(pattern string) bool {
	// With no map delimiter there is no value phase to classify. Keep this
	// common admission case out of the syntax-plan cache entirely.
	if !strings.Contains(pattern, "{") {
		return true
	}
	if constant, cached := patternMapsConstant.get(pattern); cached {
		return constant
	}
	constant := patternMapsAreConstantText(pattern)
	patternMapsConstant.put(pattern, constant)
	return constant
}

// patternMapsConstant caches patternMapsAreConstant by pattern text: a
// pattern is read once, not once per row.
var patternMapsConstant = newBoundedCache[string, bool](1024, boundedCacheStringShardIndex)

func patternMapsAreConstantText(pattern string) bool {
	depth := 0
	for index := 0; index < len(pattern); index++ {
		switch c := pattern[index]; cypherLexicalByte(c) {
		case cypherQuoteClass:
			index = skipCypherQuotedText(pattern, index, c) - 1
		case '(', '[':
			depth++
		case ')', ']':
			depth--
		case '{':
			if depth <= 0 {
				continue
			}
			close := findMatchingDelimiter(pattern, index, '{', '}')
			if close < 0 {
				return false
			}
			for _, pair := range splitTopLevelComma(pattern[index+1 : close]) {
				separator := findTopLevelMapKeyValueSeparator(pair)
				if separator <= 0 || !isConstantMapValue(pair[separator+1:]) {
					return false
				}
			}
			index = close
		}
	}
	return true
}

// isConstantMapValue reports a property map value that is a literal or a
// parameter.
func isConstantMapValue(value string) bool {
	value = strings.TrimSpace(value)
	if len(value) > 1 && value[0] == '$' && isValidIdentifier(value[1:]) {
		return true
	}
	if inner, list := stripEnclosingRowDelimiter(value, '[', ']'); list {
		if strings.TrimSpace(inner) == "" {
			return true
		}
		for _, item := range splitTopLevelComma(inner) {
			if !isConstantMapValue(item) {
				return false
			}
		}
		return true
	}
	_, literal := parseLiteralValueFromComputedRow(value)
	return literal
}

// chainVariablesBindEntities reports whether every node and relationship
// variable of a parsed chain that the row binds holds an entity of that kind:
// boundChainCount compares the traversal with the row's nodes and
// relationships only.
func chainVariablesBindEntities(matches *TraversalMatch, values map[string]interface{}) bool {
	node := func(info nodePatternInfo) bool {
		if info.variable == "" {
			return true
		}
		value, bound := values[info.variable]
		if !bound {
			return true
		}
		_, isNode := value.(*storage.Node)
		return isNode
	}
	relationship := func(pattern RelationshipPattern) bool {
		if pattern.Variable == "" {
			return true
		}
		value, bound := values[pattern.Variable]
		if !bound {
			return true
		}
		_, isEdge := value.(*storage.Edge)
		return isEdge
	}
	if !node(matches.StartNode) || !node(matches.EndNode) || !relationship(matches.Relationship) {
		return false
	}
	for _, info := range matches.IntermediateNodes {
		if !node(info) {
			return false
		}
	}
	for _, segment := range matches.Segments {
		if !node(segment.FromNode) || !node(segment.ToNode) || !relationship(segment.Relationship) {
			return false
		}
	}
	return true
}

// entityRow is the row an expression evaluated over node and relationship
// bindings sees, as its subqueries see it: the value scope of ctx (the row's
// other values, a comprehension's or quantifier's variable) with the nodes
// and relationships, which shadow it. Every subquery the node and
// relationship evaluator runs reads its row from here.
func entityRow(ctx context.Context, nodes map[string]*storage.Node, rels map[string]*storage.Edge) pipelineRow {
	values := pipelineRow(valueBindingsLayer(ctx, len(nodes)+len(rels)))
	for name, node := range nodes {
		values[name] = node
	}
	for name, relationship := range rels {
		values[name] = relationship
	}
	return values
}

// entityRowWithPaths is entityRow with the path variables bound too, as a
// path is in a pipeline row.
func (e *StorageExecutor) entityRowWithPaths(ctx context.Context, nodes map[string]*storage.Node, rels map[string]*storage.Edge, paths map[string]*PathResult) pipelineRow {
	values := entityRow(ctx, nodes, rels)
	for name, path := range paths {
		if path != nil {
			values[name] = e.pathContextRowValue(path)
		}
	}
	return values
}

// entityBindings splits a row's node and relationship values out of it.
func entityBindings(values map[string]interface{}) (map[string]*storage.Node, map[string]*storage.Edge) {
	nodes := make(map[string]*storage.Node)
	rels := make(map[string]*storage.Edge)
	for name, value := range values {
		switch entity := value.(type) {
		case *storage.Node:
			if entity != nil {
				nodes[name] = entity
			}
		case *storage.Edge:
			if entity != nil {
				rels[name] = entity
			}
		}
	}
	return nodes, rels
}

// containsIdentifierWord reports whether name occurs in text as a whole word.
func containsIdentifierWord(text, name string) bool {
	if name == "" {
		return false
	}
	for from := 0; from < len(text); {
		index := strings.Index(text[from:], name)
		if index < 0 {
			return false
		}
		start := from + index
		end := start + len(name)
		if (start == 0 || !isIdentByte(text[start-1])) && (end == len(text) || !isIdentByte(text[end])) {
			return true
		}
		from = start + 1
	}
	return false
}

// boundDegreePattern is a COUNT body that is one directed hop from a bound
// node to an anonymous, unlabelled node with no properties and no WHERE:
// [MATCH] (v)-[:T|U]->(), (v)<-[:T]-(), ()-[:T]->(v), with the arrows in
// either spelling (-->, -[r]->). Its count is the node's degree, unless the
// relationship variable is bound in the row (boundDegreeCount).
var boundDegreePattern = regexp.MustCompile(`^(?i:MATCH\s+)?(?:\(\s*([A-Za-z_]\w*)\s*\)\s*(<?)-(?:\[\s*([A-Za-z_]\w*)?\s*(?::\s*([A-Za-z_\w|\s` + "`" + `]+?))?\s*\])?-(>?)\s*\(\s*\)|\(\s*\)\s*(<?)-(?:\[\s*([A-Za-z_]\w*)?\s*(?::\s*([A-Za-z_\w|\s` + "`" + `]+?))?\s*\])?-(>?)\s*\(\s*([A-Za-z_]\w*)\s*\))\s*$`)

// boundDegreeShape is a parsed boundDegreePattern body: the bound variable,
// the hop's direction from it and its relationship types. ok is false for any
// other body.
type boundDegreeShape struct {
	variable     string
	relationship string // the hop's relationship variable, or ""
	outgoing     bool
	types        []string
	ok           bool
}

// boundDegreeShapes caches parsed COUNT bodies; a body is parsed once, not
// once per row.
var boundDegreeShapes = newBoundedCache[string, boundDegreeShape](1024, boundedCacheStringShardIndex)

// parseBoundDegreeShape parses body as a boundDegreePattern (cached).
func parseBoundDegreeShape(body string) boundDegreeShape {
	if shape, cached := boundDegreeShapes.get(body); cached {
		return shape
	}
	shape := parseBoundDegreeShapeText(body)
	boundDegreeShapes.put(body, shape)
	return shape
}

func parseBoundDegreeShapeText(body string) boundDegreeShape {
	trimmed := strings.TrimSpace(body)
	if len(trimmed) == 0 || strings.ContainsAny(trimmed, "{*,") {
		return boundDegreeShape{}
	}
	match := boundDegreePattern.FindStringSubmatch(trimmed)
	if match == nil {
		return boundDegreeShape{}
	}
	variable, relationship, types := match[1], match[3], match[4]
	outgoing := match[2] == "" && match[5] == ">"
	incoming := match[2] == "<" && match[5] == ""
	if variable == "" {
		// ()-[:T]->(v) is an incoming hop of v.
		variable, relationship, types = match[10], match[7], match[8]
		outgoing = match[6] == "<" && match[9] == ""
		incoming = match[6] == "" && match[9] == ">"
	}
	if outgoing == incoming {
		return boundDegreeShape{}
	}
	var relTypes []string
	for _, relType := range strings.Split(types, "|") {
		if relType = strings.Trim(strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(relType), ":")), "`"); relType != "" {
			relTypes = append(relTypes, relType)
		}
	}
	return boundDegreeShape{variable: variable, relationship: relationship, outgoing: outgoing, types: relTypes, ok: true}
}

// boundDegreeCount counts COUNT { (v)-[:T]->() } for a node bound in values
// from its adjacency, without the traversal kernel. It takes only the exact
// boundDegreePattern shape: a far end with a label, properties or a WHERE,
// more hops, or an undirected hop go through the kernel, which applies them.
func (e *StorageExecutor) boundDegreeCount(ctx context.Context, body string, values map[string]interface{}) (int64, bool) {
	shape := parseBoundDegreeShape(body)
	if !shape.ok {
		return 0, false
	}
	node, ok := values[shape.variable].(*storage.Node)
	if !ok || node == nil {
		return 0, false
	}
	if shape.relationship != "" {
		// A relationship variable bound in the row restricts the hop to
		// that relationship: not a degree (#1055).
		if _, bound := values[shape.relationship]; bound {
			return 0, false
		}
	}
	return e.nodeDegreeCount(ctx, node, shape), true
}

// nodeDegreeCount is the degree of node along shape's direction and types.
func (e *StorageExecutor) nodeDegreeCount(ctx context.Context, node *storage.Node, shape boundDegreeShape) int64 {
	store := e.getStorage(ctx)
	var edges []*storage.Edge
	var err error
	if shape.outgoing {
		edges, err = store.GetOutgoingEdges(node.ID)
	} else {
		edges, err = store.GetIncomingEdges(node.ID)
	}
	if err != nil {
		recordExpressionFailure(ctx, err)
		return 0
	}
	if len(shape.types) == 0 {
		return int64(len(edges))
	}
	var count int64
	for _, edge := range edges {
		if e.edgeTypeMatches(edge.Type, shape.types) {
			count++
		}
	}
	return count
}

package cypher

import (
	"context"
	"time"

	"github.com/orneryd/nornicdb/pkg/storage"
)

type temporalViewportKeyType struct{}

var temporalViewportKey = temporalViewportKeyType{}

type TemporalViewportMode int

const (
	TemporalViewportLive TemporalViewportMode = iota
	TemporalViewportAsOf
)

type TemporalViewport struct {
	Mode TemporalViewportMode
	AsOf time.Time
}

func CurrentTemporalViewport() TemporalViewport {
	return TemporalViewport{Mode: TemporalViewportLive}
}

func AsOfTemporalViewport(asOf time.Time) TemporalViewport {
	return TemporalViewport{Mode: TemporalViewportAsOf, AsOf: asOf.UTC()}
}

func (v TemporalViewport) Enabled() bool {
	return v.Mode == TemporalViewportAsOf && !v.AsOf.IsZero()
}

func WithTemporalViewport(ctx context.Context, viewport TemporalViewport) context.Context {
	return context.WithValue(ctx, temporalViewportKey, viewport)
}

func TemporalViewportFromContext(ctx context.Context) (TemporalViewport, bool) {
	viewport, ok := ctx.Value(temporalViewportKey).(TemporalViewport)
	return viewport, ok
}

type temporalCurrentNodeChecker interface {
	IsCurrentTemporalNode(node *storage.Node, asOf time.Time) (bool, error)
}

func filterNodesByTemporalViewport(nodes []*storage.Node, viewport TemporalViewport, checker temporalCurrentNodeChecker) ([]*storage.Node, error) {
	if !viewport.Enabled() || checker == nil {
		return nodes, nil
	}
	filtered := make([]*storage.Node, 0, len(nodes))
	for _, node := range nodes {
		if node == nil {
			continue
		}
		visible, err := checker.IsCurrentTemporalNode(node, viewport.AsOf)
		if err != nil {
			return nil, err
		}
		if !visible {
			continue
		}
		filtered = append(filtered, node)
	}
	return filtered, nil
}

func nodeVisibleInTemporalViewport(node *storage.Node, viewport TemporalViewport, checker temporalCurrentNodeChecker) (bool, error) {
	if !viewport.Enabled() || checker == nil || node == nil {
		return true, nil
	}
	return checker.IsCurrentTemporalNode(node, viewport.AsOf)
}

func filterNodesByRequiredLabels(nodes []*storage.Node, labels []string) []*storage.Node {
	if len(labels) <= 1 {
		return nodes
	}
	filtered := make([]*storage.Node, 0, len(nodes))
	for _, node := range nodes {
		if mergeNodeHasLabels(node, labels) {
			filtered = append(filtered, node)
		}
	}
	return filtered
}

func (e *StorageExecutor) loadNodesWithTemporalViewport(ctx context.Context, labels []string) ([]*storage.Node, error) {
	return e.loadPatternNodes(ctx, labels, nil)
}

// loadPatternNodes returns the nodes of a node pattern (labels, inline
// properties) visible in the temporal viewport. Traversal seeds use the same
// label-indexed, viewport-aware streaming collector as node MATCH, which
// avoids a second physical scan path that materialises GetNodesByLabel inside
// explicit transactions. Passing the properties lets a pattern without labels
// take the projected scan instead of decoding every node (#857).
func (e *StorageExecutor) loadPatternNodes(ctx context.Context, labels []string, properties map[string]interface{}) ([]*storage.Node, error) {
	return e.collectNodesWithStreaming(ctx, labels, properties, "", "", -1)
}

// Package cypher - Transaction support for Cypher queries.
//
// Implements BEGIN/COMMIT/ROLLBACK for Neo4j-compatible transaction control.
package cypher

import (
	"context"
	"errors"
	"fmt"
	"regexp"
	"strings"
	"time"
	"unicode"

	nornicerrors "github.com/orneryd/nornicdb/pkg/errors"
	"github.com/orneryd/nornicdb/pkg/fabric"
	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

type transactionStatementOriginKey struct{}

// WithClientStatement marks text supplied as a client statement, not protocol transaction control.
func WithClientStatement(ctx context.Context) context.Context {
	return context.WithValue(ctx, transactionStatementOriginKey{}, true)
}

// WithTransactionControl permits a transaction owner to issue its lifecycle command.
func WithTransactionControl(ctx context.Context) context.Context {
	return context.WithValue(ctx, transactionStatementOriginKey{}, false)
}

// clientTransactionCommand is Neo4j's SyntaxError for a client statement that
// is a bare BEGIN, COMMIT or ROLLBACK (optionally followed by TRANSACTION):
// Cypher has no transaction statements, and a client statement runs on an
// executor the client doesn't own for longer than the statement, so it must
// not leave that executor inside a transaction. The one-statement script form
// (BEGIN … COMMIT in one text) and embedded callers without a client mark keep
// working.
func clientTransactionCommand(ctx context.Context, query string) error {
	if ctx.Value(transactionStatementOriginKey{}) != true {
		return nil
	}
	if word := bareTransactionCommand(query); word != "" {
		message := localization.CypherTransactionsCommandNotStatement(word)
		return localizedError(message, newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", message.Fallback))
	}
	return nil
}

var firstUseGraphPattern = regexp.MustCompile(`(?is)\bUSE\s+([A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)?)`)

// TransactionContext holds the active transaction for a Cypher session.
type TransactionContext struct {
	// Captured at BEGIN, independent of user-editable tx.setMetaData values.
	coordinatorOwned bool
	tx               interface{}    // *storage.BadgerTransaction (MemoryEngine now wraps BadgerEngine)
	engine           storage.Engine // Engine owning this transaction's commit.
	storageWrapper   *transactionStorageWrapper
	active           bool
	wal              *storage.WAL
	walSeqStart      uint64
	database         string
	txID             string
	fabricRemoteExe  *fabric.RemoteFragmentExecutor
	// running is the transaction's SHOW TRANSACTIONS entry (#718).
	running *runningTransaction

	// fabricLocalTxExec holds, per local constituent (shard name), the
	// executor of this transaction's sub-transaction on it. Every statement
	// of the transaction runs there, so it sees earlier statements' writes
	// and COMMIT / ROLLBACK ends all of them.
	fabricLocalTxExec map[string]*StorageExecutor
	// failed is the error of the first statement that failed in the
	// transaction. A failed transaction stays open so ROLLBACK discards what
	// it wrote; any other statement is refused and COMMIT rolls it back, as in
	// Neo4j (#683).
	failed error
	// storageRolledBack records early cleanup after a memory failure. The
	// protocol transaction stays failed until its owner receives COMMIT or
	// ROLLBACK, while staged storage and its budget are released immediately.
	storageRolledBack bool

	// statementKind keeps administration commands apart from data statements.
	statementKind string
}

// failTransaction records err as the active explicit transaction's failure
// and returns err. The first failure wins: it is the cause COMMIT reports. It
// is the one rule for a statement that fails inside a transaction, whether it
// ran through Execute or an inline transaction script (#683). A composite
// transaction's participants end their part with it: each local one fails
// with the same cause, and each remote sub-transaction is rolled back. ctx is
// the failed statement's context, whose deadline bounds the remote rollbacks.
func (e *StorageExecutor) failTransaction(ctx context.Context, err error) error {
	if tx := e.txContext; err != nil && tx != nil && tx.active && tx.failed == nil {
		tx.failed = err
		if code, _ := nornicerrors.Neo4jStatus(err); code == transactionMemoryLimitCode || code == memoryPoolOutOfMemoryCode {
			if storageTx, ok := tx.tx.(*storage.BadgerTransaction); ok {
				if rollbackErr := storageTx.Rollback(); rollbackErr == nil {
					tx.storageRolledBack = true
					if tx.running != nil {
						tx.running.releaseMemory()
					}
				}
			}
		}
		// The transaction can no longer commit: the MERGE key locks it holds,
		// itself or through a participant's sub-transaction, must not keep
		// other transactions' MERGEs of those keys waiting until the client
		// rolls it back. Local keys are released first: they never wait on a
		// remote.
		if releaser, ok := tx.tx.(interface{ ReleaseMergeKeys() }); ok {
			releaser.ReleaseMergeKeys()
		}
		for _, participant := range tx.fabricLocalTxExec {
			participant.failTransaction(ctx, err)
		}
		if tx.fabricRemoteExe != nil {
			// A remote participant records its own rollback error (a
			// deadline included); the transaction keeps reporting err.
			rollbackCtx, cancel := remoteFailureRollbackContext(ctx)
			_ = tx.fabricRemoteExe.RollbackParticipants(rollbackCtx)
			cancel()
		}
	}
	return err
}

// remoteFailureRollbackContext bounds a failed transaction's remote
// rollbacks: by the statement's deadline (its transaction or statement
// timeout), and never longer than the remote client's request timeout. It
// isn't cancelled with the statement, which already failed.
func remoteFailureRollbackContext(ctx context.Context) (context.Context, context.CancelFunc) {
	if ctx == nil {
		ctx = context.Background()
	}
	deadline := time.Now().Add(storage.RemoteRequestTimeout)
	if statementDeadline, ok := ctx.Deadline(); ok && statementDeadline.Before(deadline) {
		deadline = statementDeadline
	}
	return context.WithDeadline(context.WithoutCancel(ctx), deadline)
}

// abortTransaction fails the active transaction with err and ends it: what an
// inline transaction script (BEGIN … COMMIT in one request) does when its
// statement fails, since no later ROLLBACK can reach it. It returns err.
func (e *StorageExecutor) abortTransaction(ctx context.Context, err error) error {
	e.failTransaction(ctx, err)
	_, _ = e.handleRollback()
	return err
}

// queryOnFailedTransactionError is the error of a statement sent to a
// transaction a previous statement failed in.
func queryOnFailedTransactionError(cause error) error {
	return newSemanticError("Neo.TransientError.Transaction.QueryExecutionFailedOnTransaction", "QueryExecutionFailedOnTransaction",
		"The transaction was marked as failed because a query failed: "+cause.Error())
}

// bareTransactionCommand returns the command word, as typed, when cypher is exactly a
// bare transaction command (BEGIN, COMMIT or ROLLBACK, optionally followed by
// TRANSACTION), else "".
func bareTransactionCommand(cypher string) string {
	// Allocation-free: it runs for every client statement.
	text := strings.TrimSpace(cypher)
	word, rest := text, ""
	if i := strings.IndexFunc(text, unicode.IsSpace); i >= 0 {
		word, rest = text[:i], strings.TrimSpace(text[i:])
	}
	if rest != "" && !strings.EqualFold(rest, "TRANSACTION") {
		return ""
	}
	if strings.EqualFold(word, "BEGIN") || strings.EqualFold(word, "COMMIT") || strings.EqualFold(word, "ROLLBACK") {
		// As typed: Neo4j's SyntaxError quotes the input ('begin').
		return word
	}
	return ""
}

// parseTransactionStatement checks if query is BEGIN/COMMIT/ROLLBACK.
func (e *StorageExecutor) parseTransactionStatement(ctx context.Context, cypher string) (*ExecuteResult, error) {
	upper := upperASCII(strings.TrimSpace(cypher))

	switch {
	case upper == "BEGIN" || upper == "BEGIN TRANSACTION":
		return e.handleBegin()
	case upper == "COMMIT" || upper == "COMMIT TRANSACTION":
		return e.handleCommit(ctx)
	case upper == "ROLLBACK" || upper == "ROLLBACK TRANSACTION":
		return e.handleRollback()
	default:
		return nil, nil // Not a transaction statement
	}
}

// handleBegin starts a new explicit transaction.
func (e *StorageExecutor) handleBegin() (*ExecuteResult, error) {
	if e.txContext != nil && e.txContext.active {
		return nil, localizedError(localization.CypherTransactionsAlreadyActive(), nil)
	}

	// Establish the acknowledged-write visibility boundary before opening the
	// underlying snapshot. Writes are committed synchronously by their
	// statements, so a snapshot opened here observes every acknowledged write.

	// Unwrap engine wrappers (WAL/Namespaced) recursively.
	engine := e.storage
	namespaceHint := ""
	visited := map[storage.Engine]bool{}
	for engine != nil && !visited[engine] {
		visited[engine] = true
		if namespacedEngine, ok := engine.(*storage.NamespacedEngine); ok {
			if namespaceHint == "" {
				namespaceHint = namespacedEngine.Namespace()
			}
		}
		if wrapper, ok := engine.(storage.EngineUnwrapper); ok {
			engine = wrapper.GetInnerEngine()
			continue
		}
		break
	}

	// Composite engines use FabricTransaction coordinator semantics.
	// This supports explicit BEGIN/COMMIT/ROLLBACK at API level for composite routes.
	if _, ok := engine.(*storage.CompositeEngine); ok {
		var fabricTx *fabric.FabricTransaction
		openSnapshot := func() error {
			fabricTx = fabric.NewFabricTransaction(fmt.Sprintf("fabtx-%d", time.Now().UnixNano()))
			return nil
		}
		if err := openSnapshot(); err != nil {
			return nil, localizedError(localization.CypherTransactionsStartFailed(err), err)
		}
		e.txContext = &TransactionContext{
			tx:     fabricTx,
			engine: engine,
			active: true,
		}
		return &ExecuteResult{
			Columns: []string{"status"},
			Rows:    [][]interface{}{{"Transaction started"}},
		}, nil
	}

	// Start transaction for any engine that supports BeginTransaction.
	txEngine, ok := engine.(interface {
		BeginTransaction() (*storage.BadgerTransaction, error)
	})
	if !ok {
		return nil, localizedError(localization.CypherTransactionsEngineUnsupported(), nil)
	}
	if namespaceHint != "" {
		if primer, ok := txEngine.(interface{ EnsureNamespaceMVCC(string) error }); ok {
			if err := primer.EnsureNamespaceMVCC(namespaceHint); err != nil {
				return nil, localizedError(localization.CypherTransactionsPrimeNamespaceFailed(err), err)
			}
		}
	}
	// With write-behind buffering, drain acknowledged autocommit writes so
	// the explicit snapshot observes every acknowledged statement.
	if drainer, ok := engine.(interface{ FlushWriteBehind() error }); ok {
		if err := drainer.FlushWriteBehind(); err != nil {
			return nil, localizedError(localization.CypherTransactionsStartFailed(err), err)
		}
	}
	tx, err := beginTransactionSnapshot(txEngine)
	if err != nil {
		return nil, localizedError(localization.CypherTransactionsStartFailed(err), err)
	}
	if namespaceHint != "" {
		if err := tx.SetNamespace(namespaceHint); err != nil {
			_ = tx.Rollback()
			return nil, localizedError(localization.CypherTransactionsPinNamespaceFailed(err), err)
		}
	}
	// An explicit transaction checks each write against the constraints
	// when its statement runs, as Neo4j does: the statement that breaks a
	// constraint fails with ConstraintValidationFailed (and fails the
	// transaction), not the COMMIT (#700). COMMIT checks again under the
	// constraint keys' locks, against what other writers committed since.
	if err := tx.SetDeferredConstraintValidation(false); err != nil {
		_ = tx.Rollback()
		return nil, localizedError(localization.CypherTransactionsConfigureFailed(err), err)
	}
	txCtx := &TransactionContext{
		tx:     tx,
		engine: e.storage,
		active: true,
		txID:   tx.ID,
	}
	if wal, dbName := e.resolveWALAndDatabase(); wal != nil {
		walSeq, walErr := wal.AppendTxBegin(dbName, tx.ID, nil)
		if walErr != nil {
			_ = tx.Rollback()
			return nil, localizedError(localization.CypherTransactionsWALBeginFailed(walErr), walErr)
		}
		txCtx.wal = wal
		txCtx.walSeqStart = walSeq
		txCtx.database = dbName
	}
	e.txContext = txCtx

	return &ExecuteResult{
		Columns: []string{"status"},
		Rows:    [][]interface{}{{"Transaction started"}},
	}, nil
}

// handleCommit commits the active transaction.
func (e *StorageExecutor) handleCommit(ctx context.Context) (*ExecuteResult, error) {
	if e.txContext == nil || !e.txContext.active {
		return nil, localizedError(localization.CypherTransactionsNoActive(), nil)
	}
	// A transaction TERMINATE TRANSACTIONS ended doesn't commit (#718).
	if e.txContext.running != nil && e.txContext.running.terminated.Load() {
		_, _ = e.handleRollback()
		return nil, transactionTerminatedError()
	}
	// A transaction a statement failed in can't commit: it is rolled back.
	if cause := e.txContext.failed; cause != nil {
		if _, err := e.handleRollback(); err != nil {
			return nil, err
		}
		return nil, newSemanticError("Neo.ClientError.Transaction.TransactionMarkedAsFailed", "TransactionMarkedAsFailed",
			"The transaction was rolled back because a statement in it failed: "+cause.Error())
	}
	// Commit based on transaction type
	// All engines now use BadgerTransaction (MemoryEngine wraps BadgerEngine)
	var (
		err     error
		receipt *storage.Receipt
		opCount int
	)
	switch tx := e.txContext.tx.(type) {
	case *storage.BadgerTransaction:
		opCount = tx.OperationCount()
		err = e.commitStorageTransaction(ctx, tx)
	case *fabric.FabricTransaction:
		err = tx.Commit(nil, nil)
		if err == nil {
			publishStatementCommit(ctx)
		}
	default:
		return nil, localizedError(localization.CypherTransactionsUnknownType(), nil)
	}

	wal := e.txContext.wal
	walSeqStart := e.txContext.walSeqStart
	txID := e.txContext.txID
	dbName := e.txContext.database

	if err == nil && wal != nil && walSeqStart > 0 {
		commitSeq, walErr := wal.AppendTxCommit(dbName, txID, opCount)
		if walErr == nil {
			receipt, _ = storage.NewReceipt(
				txID,
				walSeqStart,
				commitSeq,
				dbName,
				time.Now().UTC(),
			)
		}
	}

	if err != nil {
		if wal != nil && walSeqStart > 0 {
			_, _ = wal.AppendTxAbort(dbName, txID, err.Error())
		}
		if e.txContext.fabricRemoteExe != nil {
			_ = e.txContext.fabricRemoteExe.Close()
			e.txContext.fabricRemoteExe = nil
		}
		_, localTx := e.txContext.tx.(*storage.BadgerTransaction)
		e.txContext.active = false
		runningTransactions.end(e.txContext.running)
		e.txContext = nil
		// Wire contract: substring "commit failed" is matched by downstream Bolt classifiers.
		// See docs/plans/consumer-pinned-error-contract-plan.md §2.1.
		failure := localizedError(localization.CypherTransactionsCommitFailed(err), err)
		if commitFailureWroteNothing(localTx, err) {
			failure = nornicerrors.MarkCommitRolledBack(failure)
		}
		return nil, failure
	}
	if e.txContext.storageWrapper != nil {
		txExec := e.cloneWithStorage(e.txContext.storageWrapper)
		txExec.promoteNodeLookupCacheTo(e)
		for _, action := range e.txContext.storageWrapper.schemaCommitActions {
			action()
		}
		txExec.refreshSearchAfterCommit(e.txContext.storageWrapper)
	}

	if e.txContext.fabricRemoteExe != nil {
		_ = e.txContext.fabricRemoteExe.Close()
		e.txContext.fabricRemoteExe = nil
	}
	e.txContext.active = false
	runningTransactions.end(e.txContext.running)
	e.txContext = nil

	result := &ExecuteResult{
		Columns: []string{"status"},
		Rows:    [][]interface{}{{"Transaction committed"}},
	}
	if receipt != nil {
		result.Metadata = map[string]interface{}{
			"receipt": receipt,
		}
	}
	return result, nil
}

// commitFailureWroteNothing reports whether a failed COMMIT left nothing of
// the transaction stored, so its outcome is known (the Bolt session keeps its
// connection). A local transaction (BadgerTransaction.Commit) fails before
// it writes anything on:
//   - a constraint violation, checked before the write;
//   - a transaction over the store's size limit (storage.IsTransactionTooBig),
//     raised while its writes are staged in the one Badger transaction, which
//     is then discarded.
//
// A fabric transaction may fail after some constituents committed, so its
// failures are never marked.
func commitFailureWroteNothing(localTx bool, err error) bool {
	if !localTx {
		return false
	}
	var violation *storage.ConstraintViolationError
	return errors.As(err, &violation) || storage.IsTransactionTooBig(err)
}

// handleRollback rolls back the active transaction.
func (e *StorageExecutor) handleRollback() (*ExecuteResult, error) {
	if e.txContext == nil || !e.txContext.active {
		return nil, localizedError(localization.CypherTransactionsNoActive(), nil)
	}
	// Rollback based on transaction type
	// All engines now use BadgerTransaction (MemoryEngine wraps BadgerEngine)
	var err error
	switch tx := e.txContext.tx.(type) {
	case *storage.BadgerTransaction:
		if !e.txContext.storageRolledBack {
			err = tx.Rollback()
		}
	case *fabric.FabricTransaction:
		// If already rolled back, treat as idempotent rollback success.
		if tx.State() != "open" {
			err = nil
		} else {
			err = tx.Rollback(nil)
		}
	default:
		return nil, localizedError(localization.CypherTransactionsUnknownType(), nil)
	}

	if e.txContext.wal != nil && e.txContext.walSeqStart > 0 {
		_, _ = e.txContext.wal.AppendTxAbort(e.txContext.database, e.txContext.txID, "rollback")
	}
	if e.txContext.fabricRemoteExe != nil {
		_ = e.txContext.fabricRemoteExe.Close()
		e.txContext.fabricRemoteExe = nil
	}

	e.txContext.active = false
	runningTransactions.end(e.txContext.running)
	e.txContext = nil

	if err != nil {
		return nil, localizedError(localization.CypherTransactionsRollbackFailed(err), err)
	}

	return &ExecuteResult{
		Columns: []string{"status"},
		Rows:    [][]interface{}{{"Transaction rolled back"}},
	}, nil
}

// executeInTransaction executes a query within the active transaction.
// Uses the same transactionStorageWrapper pattern as implicit transactions,
// routing writes through the transaction for atomicity and rollback support.
func (e *StorageExecutor) executeInTransaction(ctx context.Context, cypher string, upperQuery string) (*ExecuteResult, error) {
	parsedCypher, inlineEmbeddingEnabled := stripWithEmbeddingSuffix(cypher)
	if inlineEmbeddingEnabled {
		cypher = parsedCypher
		upperQuery = upperASCII(cypher)
	}

	if ftx, ok := e.txContext.tx.(*fabric.FabricTransaction); ok {
		if looksLikeWriteQuery(cypher) {
			if graph := extractFirstUseGraph(cypher); graph != "" {
				if _, err := ftx.GetOrOpen(graph, true); err != nil {
					return nil, err
				}
			}
		}
		// For composite/fabric transactions, route through shared fabric gateway when
		// query has multi-graph CALL { USE ... } patterns so write-shard constraints are
		// enforced across statements within the same explicit transaction.
		params := getParamsFromContext(ctx)
		if e.shouldUseFabricPlanner(cypher) {
			return e.executeViaFabricWithTx(ctx, cypher, params, ftx, false)
		}
		// Non-fabric-shaped queries still run on the scoped engine in explicit tx session.
		return e.executeWithoutTransaction(ctx, cypher, upperQuery)
	}

	// All engines now use BadgerTransaction (MemoryEngine wraps BadgerEngine)
	tx, ok := e.txContext.tx.(*storage.BadgerTransaction)
	if !ok {
		return nil, localizedError(localization.CypherTransactionsUnknownType(), nil)
	}

	// Recursive execution paths, such as UNWIND ... MATCH ... MERGE fallback
	// routing, can re-enter Execute while the transaction wrapper is already in
	// context. Reuse it so database namespace metadata is not lost by wrapping
	// the same Badger transaction a second time. Only reuse the wrapper that
	// belongs to the active explicit transaction; stale wrappers from reused
	// contexts must fall back to a fresh wrapper for the current tx.
	if txWrapper, ok := ctx.Value(ctxKeyTxStorage).(*transactionStorageWrapper); ok &&
		txWrapper != nil &&
		txWrapper.tx == tx {
		txExec := e.cloneWithStorage(txWrapper)
		result, err := txExec.executeQueryAgainstStorage(ctx, cypher, upperQuery)
		if err != nil {
			return result, err
		}
		if inlineEmbeddingEnabled {
			mutated := txWrapper.snapshotMutatedNodeIDs()
			if err := txExec.applyInlineEmbeddingMutations(ctx, mutated); err != nil {
				return nil, err
			}
			txWrapper.clearMutatedNodeIDs(mutated)
		}
		return result, nil
	}

	// Reuse one storage adapter for the explicit transaction lifetime. Besides
	// preserving namespace and mutation state, this prevents every statement
	// (including RETURN literals) from allocating and reseeding a 1000-entry
	// transaction lookup cache.
	txWrapper := e.transactionStorageFor(tx)

	// Pass the wrapper through context (same pattern as implicit transactions)
	// This is thread-safe and allows getStorage() to automatically use the transaction
	txCtx := context.WithValue(ctx, ctxKeyTxStorage, txWrapper)
	txExec := e.cloneWithStorage(txWrapper)

	// Execute the query - getStorage() will automatically use the transaction wrapper
	result, err := txExec.executeQueryAgainstStorage(txCtx, cypher, upperQuery)
	if err != nil {
		return result, err
	}
	if inlineEmbeddingEnabled {
		mutated := txWrapper.snapshotMutatedNodeIDs()
		if err := txExec.applyInlineEmbeddingMutations(txCtx, mutated); err != nil {
			return nil, err
		}
		txWrapper.clearMutatedNodeIDs(mutated)
	}
	return result, nil
}

// transactionStorageFor is the transaction's sole storage-adapter owner.
// Runtime Fabric promotion and ordinary explicit execution reuse this adapter;
// neither creates another transaction or terminal lifecycle.
func (e *StorageExecutor) transactionStorageFor(tx *storage.BadgerTransaction) *transactionStorageWrapper {
	if wrapper := e.txContext.storageWrapper; wrapper != nil && wrapper.tx == tx {
		return wrapper
	}
	engines := e.resolveImplicitTxEngines()
	separator := ":"
	if engines.namespace == "" {
		separator = ""
	}
	wrapper := &transactionStorageWrapper{
		tx: tx, underlying: e.storage, namespace: engines.namespace, separator: separator,
		mutatedNodeIDs: make(map[string]struct{}),
	}
	wrapper.initNamespacePrefix()
	e.txContext.storageWrapper = wrapper
	return wrapper
}

func looksLikeWriteQuery(cypher string) bool {
	upper := upperASCII(classificationText(cypher))
	return strings.Contains(upper, "CREATE") ||
		strings.Contains(upper, "MERGE") ||
		strings.Contains(upper, "DELETE") ||
		strings.Contains(upper, "SET ") ||
		strings.Contains(upper, "REMOVE ")
}

func extractFirstUseGraph(cypher string) string {
	m := firstUseGraphPattern.FindStringSubmatch(cypher)
	if len(m) < 2 {
		return ""
	}
	return strings.TrimSpace(m[1])
}

// executeQueryAgainstStorage executes query with current storage context.
func (e *StorageExecutor) executeQueryAgainstStorage(ctx context.Context, cypher string, upperQuery string) (*ExecuteResult, error) {
	e.decayMismatchLogged = false
	// Single router: the transaction only changes which storage view e.storage is.
	return e.executeWithoutTransaction(ctx, cypher, upperQuery)
}

