// Package cypher provides graph traversal operations for NornicDB.
// This file implements relationship pattern matching, variable-length paths,
// and shortest path algorithms for Neo4j-compatible traversal queries.

package cypher

import (
	"context"
	"sort"
	"strconv"
	"strings"
	"sync"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
	"github.com/orneryd/nornicdb/pkg/util"
)

// VarLengthUnboundedMaxHops is the depth cap applied when a variable-length
// relationship pattern is written without an explicit upper bound — for
// example `[*]`, `[*..]`, or `[*N..]`. The previous defaults (10 and 100) were
// surprising in practice: BFS traversals silently returned no rows on graphs
// whose actual diameter exceeded the cap. This sentinel is large enough that
// it acts effectively unbounded for any realistic graph (BFS terminates when
// the frontier is exhausted) while still keeping the field a plain int so all
// downstream `>=` comparisons stay correct.
const VarLengthUnboundedMaxHops = 1 << 24 // ~16.7M

// PathResult represents a path through the graph
type PathResult struct {
	Nodes          []*storage.Node
	Relationships  []*storage.Edge
	Length         int
	SegmentLengths []int
}

// TraversalContext holds state during graph traversal
type TraversalContext struct {
	startNode        *storage.Node
	endNode          *storage.Node
	relTypes         []string // Allowed relationship types (empty = any)
	relTypeSet       map[string]struct{}
	relProperties    map[string]interface{}
	direction        string // "outgoing", "incoming", "both"
	minHops          int
	maxHops          int
	usedEdges        map[storage.EntityIdentity]bool
	nodeProperties   []string                         // nil requires full entities; otherwise only demanded fields
	nodeCache        map[storage.NodeID]*storage.Node // Cache for batch-fetched nodes
	limit            int                              // OPTIMIZATION: Early termination limit (0 = no limit)
	resultCount      int                              // Count of results found so far
	temporalViewport TemporalViewport
	temporalChecker  temporalCurrentNodeChecker
	// cancelCtx is consulted at DFS entry and sibling expansion so callers can
	// abandon long traversals on client disconnect / server shutdown. It is
	// allowed to be nil for legacy call sites that pass through Background.
	cancelCtx            context.Context
	cancelDone           <-chan struct{}
	cancelParentDone     <-chan struct{}
	cancelInitialized    bool
	cancellationObserved bool
	// memory is the traversal's account in the statement's memory scope,
	// resolved once from cancelCtx (#1343).
	memory         memoryAccount
	memoryResolved bool
	// endNodeID, when set, is the only node a path may end at (a shortestPath
	// pair, #863).
	endNodeID storage.NodeID
	// deepest is the greatest depth the search reached.
	deepest int
	// endpointsNeedOnlyExist is set when nothing in the statement reads the
	// nodes the traversal reaches (traversalEndpointsNeedOnlyExist).
	endpointsNeedOnlyExist bool
	// endpointsNeedOnlyLabels is set when the nodes the traversal reaches
	// need only their labels checked: a labelled, property-less endpoint
	// with no path variable exposing it (traversalEndpointsNeedOnlyLabels).
	// The traversal retains ID + labels after the canonical visibility read.
	endpointsNeedOnlyLabels bool
	// relationshipsNeedOnlyHeaders is set when nothing in the statement reads
	// the relationships' properties (traversalRelationshipsNeedOnlyHeaders).
	relationshipsNeedOnlyHeaders bool
	// repeatable lets a path repeat relationships: a walk, under MATCH
	// REPEATABLE ELEMENTS (repeatable_elements.go).
	repeatable bool
}

// traversalEndpointsNeedOnlyExist reports whether the nodes a traversal
// reaches are needed only to exist and be visible: the end node is anonymous
// with no labels or property map, and no path variable exposes the nodes.
// The traversal checks canonical query visibility before retaining a header.
func traversalEndpointsNeedOnlyExist(match *TraversalMatch) bool {
	if match.IntermediateNode {
		return false
	}
	return !match.IsChained && match.PathVariable == "" && match.EndNode.variable == "" &&
		len(match.EndNode.labels) == 0 && len(match.EndNode.properties) == 0
}

// traversalEndpointsNeedOnlyLabels reports whether the nodes a traversal
// reaches need only their labels checked: a labelled endpoint with no inline
// property map, no path variable exposing the node, and either an anonymous
// endpoint variable or a named one whose properties no later clause reads
// (match.UnusedPropertyVariables). The traversal retains ID + labels after
// checking canonical query visibility (#1110).
func traversalEndpointsNeedOnlyLabels(match *TraversalMatch) bool {
	if match.IntermediateNode {
		return false
	}
	if match.IsChained || match.PathVariable != "" ||
		len(match.EndNode.labels) == 0 || len(match.EndNode.properties) > 0 {
		return false
	}
	if match.EndNode.variable == "" {
		return true
	}
	return match.UnusedPropertyVariables[match.EndNode.variable]
}

// traversalRelationshipsNeedOnlyHeaders reports whether a traversal needs
// its relationships only for their ID, type and endpoints: the relationship
// is anonymous with no property map and no path variable exposes it. The
// traversal then lists them through storage.EdgeHeaderReader, which can
// answer without reading the relationship records.
func traversalRelationshipsNeedOnlyHeaders(match *TraversalMatch) bool {
	return !match.IsChained && match.PathVariable == "" && (match.Relationship.Variable == "" || match.UnusedPropertyVariables[match.Relationship.Variable]) && len(match.Relationship.Properties) == 0
}

// traversalEdges lists the relationships a traversal step expands from node
// in direction ("outgoing" or "incoming"): headers when the statement needs
// no relationship properties and storage can list them, full relationships
// otherwise.
func (e *StorageExecutor) traversalEdges(ctx *TraversalContext, nodeID storage.NodeID, outgoing bool) []*storage.Edge {
	if reader, ok := e.storage.(storage.EdgeHeaderReader); ok && ctx.relationshipsNeedOnlyHeaders {
		var edges []*storage.Edge
		var answered bool
		var err error
		if outgoing {
			edges, answered, err = reader.OutgoingEdgeHeaders(nodeID)
		} else {
			edges, answered, err = reader.IncomingEdgeHeaders(nodeID)
		}
		if err != nil && ctx.cancelCtx != nil {
			recordExpressionFailure(ctx.cancelCtx, err)
			return nil
		}
		if answered {
			return edges
		}
	}
	var edges []*storage.Edge
	var err error
	if outgoing {
		edges, err = e.storage.GetOutgoingEdges(nodeID)
	} else {
		edges, err = e.storage.GetIncomingEdges(nodeID)
	}
	if err != nil && ctx.cancelCtx != nil {
		recordExpressionFailure(ctx.cancelCtx, err)
	}
	return edges
}

func buildRelTypeSet(relTypes []string) map[string]struct{} {
	if len(relTypes) <= 1 {
		return nil
	}
	set := make(map[string]struct{}, len(relTypes))
	for _, relType := range relTypes {
		set[relType] = struct{}{}
	}
	return set
}

// RelationshipPattern represents a parsed relationship pattern
type RelationshipPattern struct {
	Variable       string   // r in [r:TYPE]
	Types          []string // TYPE in [r:TYPE|OTHER]
	Direction      string   // "outgoing" (-[r]->), "incoming" (<-[r]-), "both" (-[r]-)
	MinHops        int      // min in [*min..max]
	MaxHops        int      // max in [*min..max]
	VariableLength bool     // whether the pattern explicitly uses `*`
	Properties     map[string]interface{}
}

// parseRelationshipPattern parses patterns like -[r:TYPE {props}]->
func (e *StorageExecutor) parseRelationshipPattern(ctx context.Context, pattern string) (*RelationshipPattern, error) {
	return readRelationshipPattern(ctx, pattern, e.parsePropertyMap)
}

func readRelationshipPattern(ctx context.Context, pattern string, properties patternPropertyReader) (*RelationshipPattern, error) {
	result := &RelationshipPattern{
		Direction:  "both",
		MinHops:    1,
		MaxHops:    1,
		Properties: make(map[string]interface{}),
	}

	// Determine direction from both ends before trimming either marker. A
	// relationship carrying arrowheads at both ends is traversable in either
	// direction; neither marker may overwrite the other.
	hasIncomingArrow := strings.HasPrefix(pattern, "<-")
	hasOutgoingArrow := strings.HasSuffix(pattern, "->")
	switch {
	case hasIncomingArrow && hasOutgoingArrow:
		result.Direction = "both"
	case hasIncomingArrow:
		result.Direction = "incoming"
	case hasOutgoingArrow:
		result.Direction = "outgoing"
	}
	if hasIncomingArrow {
		pattern = pattern[2:]
	} else if strings.HasPrefix(pattern, "-") {
		pattern = pattern[1:]
	}
	if hasOutgoingArrow {
		pattern = pattern[:len(pattern)-2]
	} else if strings.HasSuffix(pattern, "-") {
		pattern = pattern[:len(pattern)-1]
	}

	// Extract [r:TYPE {props}] part, read outside backticks: a quoted type
	// may hold any character, a * or : included (#879, #907).
	if strings.HasPrefix(pattern, "[") && strings.HasSuffix(pattern, "]") {
		declaration := relationshipDeclarationOf(pattern[1 : len(pattern)-1])

		// Variable length: [*], [*2], [*1..3], [*2..], [*..5].
		if declaration.hasLength {
			result.VariableLength = true
			spec := declaration.length
			hasRange := strings.Contains(spec, "..")
			switch {
			case spec == "":
				// `[*]` — fully unbounded.
				result.MinHops = 1
				result.MaxHops = VarLengthUnboundedMaxHops
			case hasRange:
				parts := strings.SplitN(spec, "..", 2)
				result.MinHops = 1
				if parts[0] != "" {
					result.MinHops, _ = strconv.Atoi(parts[0])
				}
				if parts[1] != "" {
					result.MaxHops, _ = strconv.Atoi(parts[1])
				} else {
					// `[*N..]` — open-ended upper bound.
					result.MaxHops = VarLengthUnboundedMaxHops
				}
			default:
				result.MinHops, _ = strconv.Atoi(spec)
				result.MaxHops = result.MinHops
			}
		}

		// Property maps are valid with or without a relationship type, e.g.
		// [r {name: 'value'}] and [r:TYPE {name: 'value'}].
		if declaration.properties != "" {
			var err error
			result.Properties, err = properties(ctx, declaration.properties, true)
			if err != nil {
				return nil, err
			}
		}
		result.Variable = declaration.variable
		result.Types = declaration.types
	}

	return result, nil
}

// executeMatchWithRelationshipsWithPathSeeded is the single traversal entry
// with an additional endSeedNodes parameter. When a pipeline row already binds
// the pattern's end-node variable (but not its start-node variable), the
// caller passes that node here so the traversal starts from the known
// endpoint and walks backwards, instead of expanding the pattern over every
// relationship in the store and joining the bound value afterward. seedNodes
// (start-side) takes priority when both are supplied.
func (e *StorageExecutor) executeMatchWithRelationshipsWithPathSeeded(ctx context.Context, pattern string, whereClause string, returnItems []returnItem, seedNodes []*storage.Node, endSeedNodes []*storage.Node, pathVariable string, readTail []string, earlyLimit int) (*ExecuteResult, error) {
	result := &ExecuteResult{
		Columns: []string{},
		Rows:    [][]interface{}{},
		Stats:   &QueryStats{},
	}
	collector := newTraversalResultCollector(ctx, result)
	defer collector.close()

	// Parse the pattern: (a:Label)-[r:TYPE]->(b:Label)
	matches := e.parseTraversalPattern(ctx, pattern)
	if matches == nil {
		if err := getExpressionFailure(ctx); err != nil {
			return nil, err
		}
		return result, localizedError(localization.CypherMatchingTraversalPatternInvalid(pattern), nil)
	}
	if !matches.IsChained && len(seedNodes) > 0 && len(endSeedNodes) == 1 {
		matches.boundEndNodeID = storage.NodeID(endSeedNodes[0].IdentityKey())
	}
	returnItems = expandTraversalWildcardReturnItems(returnItems, matches, pathVariable)
	for _, item := range returnItems {
		result.Columns = append(result.Columns, item.column())
	}

	// Store the path variable for path functions (relationships(path), nodes(path), length(path))
	if pathVariable != "" {
		matches.PathVariable = pathVariable
	}
	// Record which pattern node variables' properties no later clause reads,
	// so a named labelled endpoint can load by ID + labels only (#1110). The
	// pipeline supplies the read-only clauses after this MATCH (readTail);
	// direct callers supply the RETURN items themselves.
	if readTail != nil {
		matches.UnusedPropertyVariables = e.traversalUnusedPropertyVariablesForTail(matches, whereClause, readTail)
		if !matches.IsChained && matches.PathVariable == "" {
			matches.endpointProperties = traversalSourceProperties(matches.EndNode, whereClause, readTail, "")
		}
	} else {
		matches.UnusedPropertyVariables = e.traversalUnusedPropertyVariables(matches, returnItems, whereClause)
	}
	if earlyLimit == 0 {
		return result, nil
	}
	if earlyLimit > 0 && whereClause == "" {
		matches.TraversalLimit = earlyLimit
	}

	// A plain relationship count is answered from the counters when they can
	// (relationshipCountFromStore decides), instead of materializing paths.
	if whereClause == "" && pathVariable == "" && len(returnItems) == 1 {
		if count, ok, err := e.relationshipCountFromStore(ctx, matches, returnItems[0]); ok {
			if err != nil {
				return nil, err
			}
			if err := collector.appendRow([]interface{}{count}); err != nil {
				return nil, err
			}
			return result, nil
		}
	}

	// OPTIMIZATION: If WHERE clause filters by id(startNode) = value, filter start nodes before traversal
	// This avoids traversing from all nodes when we only need one specific node
	var optimizedStartNodes []*storage.Node
	usedPropertyIndex := false
	if len(seedNodes) > 0 {
		optimizedStartNodes = seedNodes
		usedPropertyIndex = true
	} else if whereClause != "" {
		// Direct element/id equality seek on start variable:
		// MATCH (o)-[:R]->(t) WHERE elementId(o) = '...'
		// This avoids traversing from all start nodes for single-node lookups.
		if matches.StartNode.variable != "" {
			if nodes, used, idxErr := e.tryCollectNodesFromIDEqualityCompound(ctx, matches.StartNode, whereClause, nil); idxErr == nil && used {
				optimizedStartNodes = nodes
				usedPropertyIndex = true
			}
		}

		// Prefer indexed start-node pruning for simple property predicates.
		if matches.StartNode.variable != "" && len(optimizedStartNodes) == 0 {
			if nodes, used, idxErr := e.tryCollectNodesFromPropertyIndex(ctx, matches.StartNode, whereClause); idxErr == nil && used {
				optimizedStartNodes = nodes
				usedPropertyIndex = true
			}
			if !usedPropertyIndex {
				if nodes, used, idxErr := e.tryCollectNodesFromPropertyIndexNotNull(matches.StartNode, whereClause); idxErr == nil && used {
					optimizedStartNodes = nodes
					usedPropertyIndex = true
				}
			}
			// BUG FIX: a start-node `WHERE var.prop IN [...]` / `IN $param`
			// predicate previously fell through every branch above (none of
			// them recognize IN-lists) straight to the O(all-label-nodes)
			// scan below, even though match.go/clauses.go/executor_mutations.go
			// already use this exact index-seek for plain node MATCH and
			// single-clause DELETE. Reuse it here so a relationship-pattern
			// traversal anchored by an IN-list seeds from the property index
			// instead of scanning every node of the label.
			if !usedPropertyIndex {
				if nodes, used, idxErr := e.tryCollectNodesFromPropertyIndexInCompound(ctx, matches.StartNode, whereClause, getParamsFromContext(ctx)); idxErr == nil && used {
					optimizedStartNodes = nodes
					usedPropertyIndex = true
				}
			}
			// Fallback optimization: even when no property index exists, pre-prune start
			// nodes for simple start-variable predicates before traversing relationships.
			// This preserves semantics while avoiding expensive traversal from irrelevant
			// start nodes in patterns like:
			//   MATCH (n:Label)-[:R]->(m) WHERE n.prop = 'x' RETURN ...
			if !usedPropertyIndex {
				if nodes, used, scanErr := e.tryCollectNodesFromStartPropertyScan(ctx, matches.StartNode, whereClause); scanErr == nil && used {
					optimizedStartNodes = nodes
				}
			}
		}

	}

	// Execute traversal with optimized start nodes if available
	var paths []PathResult
	if endSeededPaths, endSeeded := e.traverseFromEndSeeds(ctx, matches, optimizedStartNodes, endSeedNodes, whereClause); endSeeded {
		// Final even when empty: a bound end node with no qualifying path must
		// not fall through to the store-wide scan below.
		paths = endSeededPaths
	} else if len(optimizedStartNodes) > 0 {
		// Use optimized start nodes for non-chained traversal. Chained traversal uses
		// segment-aware expansion; feeding it through traverseGraphSequential can break
		// semantics because it ignores segment topology.
		if matches.IsChained && len(matches.Segments) > 1 {
			paths = e.traverseChainedGraph(ctx, matches, optimizedStartNodes)
		} else {
			viewport, _ := TemporalViewportFromContext(ctx)
			checker, _ := e.getStorage(ctx).(temporalCurrentNodeChecker)
			paths = e.traverseGraphSequential(ctx, matches, optimizedStartNodes, viewport, checker)
		}
		// Still need to apply WHERE clause filter (in case there are other conditions)
		if whereClause != "" {
			paths = e.filterPathsByWhere(ctx, paths, matches, whereClause, nil)
		}
	} else if matches.TraversalLimit > 0 && !matches.IsChained && len(matches.StartNode.properties) == 0 {
		viewport, _ := TemporalViewportFromContext(ctx)
		checker, _ := e.getStorage(ctx).(temporalCurrentNodeChecker)
		var streamed bool
		var streamErr error
		paths, streamed, streamErr = e.traverseGraphWithStreamingStartNodes(ctx, matches, viewport, checker)
		if streamErr != nil {
			return nil, streamErr
		}
		if !streamed {
			paths = e.traverseGraph(ctx, matches)
		}
	} else {
		// Normal traversal from all matching nodes
		paths = e.traverseGraph(ctx, matches)
		// Apply WHERE clause filter if present
		if whereClause != "" {
			paths = e.filterPathsByWhere(ctx, paths, matches, whereClause, nil)
		}
	}
	if matches.StartNode.variable != "" && matches.StartNode.variable == matches.EndNode.variable {
		filtered := paths[:0]
		for _, path := range paths {
			if len(path.Nodes) > 0 && path.Nodes[0].Identity() == path.Nodes[len(path.Nodes)-1].Identity() {
				filtered = append(filtered, path)
			}
		}
		paths = filtered
	}
	// Aggregates are the row pipeline's: its states (pipelineAggregateState)
	// group by the grouping values and aggregate every item on its own, as
	// every other MATCH ... RETURN does (NOR-70).
	for _, item := range returnItems {
		if containsAggregateFunc(item.expr) {
			rows := make([]traversalOptRow, 0, len(paths))
			for _, path := range paths {
				pathContext := e.buildPathContext(path, matches)
				rows = append(rows, traversalOptRow{values: e.pathContextValues(pathContext)})
			}
			aggregated, err := e.aggregateTraversalOptionalRows(ctx, rows, returnItems)
			if err != nil {
				return nil, err
			}
			if err := collector.appendRows(aggregated); err != nil {
				return nil, err
			}
			return result, nil
		}
	}

	// Build result rows (non-aggregation)
	if err := collector.appendPathRows(e, ctx, paths, matches, returnItems, earlyLimit); err != nil {
		return nil, err
	}

	return result, nil
}

func expandTraversalWildcardReturnItems(items []returnItem, match *TraversalMatch, pathVariable string) []returnItem {
	if len(items) != 1 || strings.TrimSpace(items[0].expr) != "*" || match == nil {
		return items
	}
	names := make(map[string]struct{})
	bind := func(name string) {
		if name = strings.TrimSpace(name); name != "" && !isGeneratedVariable(name) {
			names[name] = struct{}{}
		}
	}
	bind(pathVariable)
	bind(match.StartNode.variable)
	bind(match.EndNode.variable)
	bind(match.Relationship.Variable)
	for _, node := range match.IntermediateNodes {
		bind(node.variable)
	}
	for _, segment := range match.Segments {
		bind(segment.FromNode.variable)
		bind(segment.ToNode.variable)
		bind(segment.Relationship.Variable)
	}
	columns := make([]string, 0, len(names))
	for name := range names {
		columns = append(columns, name)
	}
	sort.Strings(columns)
	expanded := make([]returnItem, len(columns))
	for index, name := range columns {
		expanded[index] = returnItem{expr: name, alias: name}
	}
	return expanded
}

// traversalResultCollector is the one owner for rows returned by every
// traversal route, including count, grouping and the end-seeded fast path.
type traversalResultCollector struct {
	result *ExecuteResult
	memory memoryAccount
}

func newTraversalResultCollector(ctx context.Context, result *ExecuteResult) traversalResultCollector {
	return traversalResultCollector{result: result, memory: memoryAccount{scope: memoryScopeFromContext(ctx)}}
}

func (c *traversalResultCollector) close() { c.memory.close() }

func (c *traversalResultCollector) appendRow(row []interface{}) error {
	if c.memory.scope != nil {
		if err := c.memory.grow(estimateResultRowBytes(row, c.memory.scope.knownLists())); err != nil {
			return err
		}
	}
	c.result.Rows = append(c.result.Rows, row)
	return nil
}

func (c *traversalResultCollector) appendRows(rows [][]interface{}) error {
	for _, row := range rows {
		if err := c.appendRow(row); err != nil {
			return err
		}
	}
	return nil
}

func (c *traversalResultCollector) appendPathRows(e *StorageExecutor, ctx context.Context, paths []PathResult, matches *TraversalMatch, returnItems []returnItem, rowLimit int) error {
	for _, path := range paths {
		if rowLimit >= 0 && len(c.result.Rows) >= rowLimit {
			break
		}
		row := make([]interface{}, len(returnItems))
		context := e.buildPathContext(path, matches)

		for i, item := range returnItems {
			if isLengthPathExpr(item.expr) {
				row[i] = int64(context.pathLength)
			} else {
				row[i] = e.evaluateExpressionWithPathContext(ctx, item.expr, context)
			}
		}
		if err := c.appendRow(row); err != nil {
			return err
		}
	}
	return nil
}

type traversalSeedSide uint8

const (
	traversalStartSeed traversalSeedSide = iota
	traversalEndSeed
)

func (e *StorageExecutor) tryExecuteTraversalSeedOrderLimit(ctx context.Context, pattern string, whereClause string, returnItems []returnItem, pathVariable string, orderExpr string, limit int, seedSide traversalSeedSide) (*ExecuteResult, bool, error) {
	if limit <= 0 || strings.TrimSpace(orderExpr) == "" {
		return nil, false, nil
	}

	matches := e.parseTraversalPattern(ctx, pattern)
	if matches == nil || (seedSide == traversalEndSeed && matches.IsChained) {
		return nil, false, nil
	}
	if pathVariable != "" {
		matches.PathVariable = pathVariable
	}
	if seedSide == traversalStartSeed {
		if !matches.IsChained && strings.TrimSpace(matches.StartNode.variable) == "" {
			return nil, false, nil
		}
		seedNodes, used, err := e.tryCollectTraversalStartSeedOrderNodes(ctx, matches.StartNode, whereClause, orderExpr, limit)
		if err != nil {
			return nil, true, err
		}
		if !used {
			return nil, false, nil
		}
		result, err := e.executeMatchWithRelationshipsWithPathSeeded(ctx, pattern, whereClause, returnItems, seedNodes, nil, pathVariable, nil, -1)
		if err != nil {
			return nil, true, err
		}
		e.markTraversalStartSeedTopKUsed()
		return result, true, nil
	}
	if strings.TrimSpace(matches.EndNode.variable) == "" || len(matches.EndNode.labels) == 0 {
		return nil, false, nil
	}

	orderSpecs := e.parseNodeOrderSpecs(orderExpr, matches.EndNode.variable)
	if len(orderSpecs) == 0 {
		return nil, false, nil
	}

	seedWhere := e.extractTraversalSeedWhereClause(whereClause, matches.EndNode.variable, matches.StartNode.variable)
	if strings.TrimSpace(seedWhere) == "" && strings.TrimSpace(whereClause) != "" {
		return nil, false, nil
	}

	seedLimit := topKSeedLimit(limit)
	seedNodes, used, err := e.tryCollectNodesFromPropertyIndexOrderLimit(ctx, matches.EndNode, seedWhere, orderExpr, seedLimit)
	if err != nil {
		return nil, true, err
	}
	if !used {
		if seedNodes, used, err = e.tryCollectNodesFromPropertyIndexNotNullOrderLimit(ctx, matches.EndNode, seedWhere, orderExpr, seedLimit); err != nil {
			return nil, true, err
		}
		if !used {
			return nil, false, nil
		}
	}

	result := &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}, Stats: &QueryStats{}}
	for _, item := range returnItems {
		result.Columns = append(result.Columns, item.column())
	}
	if len(seedNodes) == 0 {
		e.markTraversalEndSeedTopKUsed()
		return result, true, nil
	}

	reversed := reverseTraversalMatch(matches)
	if reversed == nil {
		return nil, false, nil
	}

	paths := make([]PathResult, 0, util.SafePreallocCap(len(seedNodes)))
	for _, endNode := range seedNodes {
		reversedPaths := e.traverseFromNode(ctx, endNode, reversed)
		for _, reversedPath := range reversedPaths {
			path := reversePathResult(reversedPath)
			if whereClause != "" && !e.evaluateWhereOnPath(ctx, whereClause, e.buildPathContext(path, matches)) {
				continue
			}
			paths = append(paths, path)
			if len(paths) >= limit {
				collector := newTraversalResultCollector(ctx, result)
				defer collector.close()
				if err := collector.appendPathRows(e, ctx, paths, matches, returnItems, limit); err != nil {
					return nil, true, err
				}
				e.markTraversalEndSeedTopKUsed()
				return result, true, nil
			}
		}
	}

	if len(paths) < limit && len(seedNodes) >= seedLimit {
		return nil, false, nil
	}

	collector := newTraversalResultCollector(ctx, result)
	defer collector.close()
	if err := collector.appendPathRows(e, ctx, paths, matches, returnItems, limit); err != nil {
		return nil, true, err
	}
	e.markTraversalEndSeedTopKUsed()
	return result, true, nil
}

func (e *StorageExecutor) extractTraversalSeedWhereClause(whereClause string, seedVar string, blockedVars ...string) string {
	clause := unwrapOuterParens(strings.TrimSpace(whereClause))
	if clause == "" {
		return ""
	}
	parts := splitTopLevelAndConjuncts(clause)
	selected := make([]string, 0, len(parts))
	for _, part := range parts {
		term := unwrapOuterParens(strings.TrimSpace(part))
		if term == "" {
			continue
		}
		if !referencesTraversalVariable(term, seedVar) {
			continue
		}
		blocked := false
		for _, blockedVar := range blockedVars {
			if blockedVar == "" {
				continue
			}
			if referencesTraversalVariable(term, blockedVar) {
				blocked = true
				break
			}
		}
		if blocked {
			continue
		}
		selected = append(selected, term)
	}
	return strings.Join(selected, " AND ")
}

func referencesTraversalVariable(expr string, variable string) bool {
	if variable == "" {
		return false
	}
	trimmed := strings.TrimSpace(expr)
	if strings.Contains(trimmed, variable+".") || strings.Contains(lowerASCII(trimmed), "id("+lowerASCII(variable)+")") || strings.Contains(lowerASCII(trimmed), "elementid("+lowerASCII(variable)+")") {
		return true
	}
	return false
}

// traverseFromEndSeeds walks a non-chained pattern backwards from nodes
// already bound to its end variable, when no start-side seed exists. Rather
// than expanding the pattern over every relationship in the store and joining
// the bound value afterward (O(|E|)), it reverses the pattern, traverses from
// each known endpoint (O(degree)), flips each path back and applies the WHERE
// clause. seeded reports whether this path ran; when it did, the returned
// paths are final even if empty. The caller is responsible for having checked
// the end node's own labels and inline properties.
func (e *StorageExecutor) traverseFromEndSeeds(ctx context.Context, matches *TraversalMatch, startSeedNodes, endSeedNodes []*storage.Node, whereClause string) (paths []PathResult, seeded bool) {
	if len(startSeedNodes) > 0 || len(endSeedNodes) == 0 || matches.IsChained {
		return nil, false
	}
	reversed := reverseTraversalMatch(matches)
	if reversed == nil {
		return nil, false
	}
	paths = make([]PathResult, 0, util.SafePreallocCap(len(endSeedNodes)))
	for _, endNode := range endSeedNodes {
		for _, reversedPath := range e.traverseFromNode(ctx, endNode, reversed) {
			paths = append(paths, reversePathResult(reversedPath))
		}
	}
	if whereClause != "" {
		paths = e.filterPathsByWhere(ctx, paths, matches, whereClause, nil)
	}
	return paths, true
}

func reverseTraversalMatch(match *TraversalMatch) *TraversalMatch {
	if match == nil || match.IsChained {
		return nil
	}
	reversed := *match
	reversed.StartNode = match.EndNode
	reversed.EndNode = match.StartNode
	reversed.Relationship = match.Relationship
	switch match.Relationship.Direction {
	case "outgoing":
		reversed.Relationship.Direction = "incoming"
	case "incoming":
		reversed.Relationship.Direction = "outgoing"
	default:
		reversed.Relationship.Direction = match.Relationship.Direction
	}
	return &reversed
}

func reversePathResult(path PathResult) PathResult {
	reversedNodes := make([]*storage.Node, len(path.Nodes))
	for i := range path.Nodes {
		reversedNodes[len(path.Nodes)-1-i] = path.Nodes[i]
	}
	reversedEdges := make([]*storage.Edge, len(path.Relationships))
	for i := range path.Relationships {
		reversedEdges[len(path.Relationships)-1-i] = path.Relationships[i]
	}
	return PathResult{Nodes: reversedNodes, Relationships: reversedEdges, Length: path.Length}
}

func topKSeedLimit(limit int) int {
	seedLimit, ok := util.SafeIntProduct(limit, 4)
	if !ok {
		seedLimit = int(^uint(0) >> 1)
	}
	if seedLimit < 200 {
		seedLimit = 200
	}
	return seedLimit
}

func (e *StorageExecutor) tryCollectTraversalStartSeedOrderNodes(
	ctx context.Context,
	nodePattern nodePatternInfo,
	whereClause string,
	orderExpr string,
	limit int,
) ([]*storage.Node, bool, error) {
	if limit <= 0 || strings.TrimSpace(orderExpr) == "" || strings.TrimSpace(nodePattern.variable) == "" || len(nodePattern.labels) == 0 {
		return nil, false, nil
	}

	seedNodes, used, err := e.tryCollectNodesFromPropertyIndexOrderLimit(ctx, nodePattern, whereClause, orderExpr, topKSeedLimit(limit))
	if err != nil || !used {
		return nil, used, err
	}

	if len(seedNodes) > limit {
		if topK, ok := e.selectTopKNodesByOrder(seedNodes, nodePattern.variable, orderExpr, limit); ok {
			seedNodes = topK
		}
	}

	return seedNodes, true, nil
}

// tryCollectNodesFromStartPropertyScan applies start-node predicate pruning for
// traversal patterns without requiring an index. It only handles simple predicates
// on the traversal start variable:
//   - <startVar>.<prop> = <value>
//   - <startVar>.<prop> IS NOT NULL
func (e *StorageExecutor) tryCollectNodesFromStartPropertyScan(ctx context.Context, nodePattern nodePatternInfo, whereClause string) ([]*storage.Node, bool, error) {
	if strings.TrimSpace(nodePattern.variable) == "" || strings.TrimSpace(whereClause) == "" {
		return nil, false, nil
	}
	// Variable references alone do not establish a start-node predicate:
	// graph predicates and producers can reference only the start variable,
	// but must run once per matched row, never during seed pruning as well.
	// The shared complete plan admits only simple, side-effect-free operands.
	plan := planRowPredicate(whereClause)
	if plan == nil || !plan.complete {
		return nil, false, nil
	}
	for _, reference := range semanticExpressionReferences(whereClause) {
		if strings.SplitN(reference, ".", 2)[0] != nodePattern.variable {
			return nil, false, nil
		}
	}
	nodes, _, err := e.collectPipelineInitialNodeCandidates(ctx, nodePattern, whereClause, pipelineMatchPhysicalHint{limit: -1, earlyLimit: -1})
	if err != nil {
		return nil, true, err
	}
	values := pipelineNodeRow(ctx, nodePattern.variable, nil)
	filtered := nodes[:0]
	for _, node := range nodes {
		values[nodePattern.variable] = node
		if e.evaluateRowPredicate(ctx, whereClause, values) {
			filtered = append(filtered, node)
		}
	}
	return filtered, true, nil
}

// isLengthPathExpr checks if an expression is length(path) for some path variable
func isLengthPathExpr(expr string) bool {
	return matchFuncStartAndSuffix(expr, "length") && strings.Contains(lowerASCII(expr), "path")
}

// TraversalMatch represents a parsed traversal pattern
type TraversalMatch struct {
	StartNode    nodePatternInfo
	EndNode      nodePatternInfo
	Relationship RelationshipPattern
	// For chained patterns like (a)-[:R1]->(b)-[:R2]->(c), we store intermediate segments
	IntermediateNodes []nodePatternInfo
	Segments          []TraversalSegment // All segments in the chain
	IsChained         bool               // True if this is a multi-segment pattern
	PathVariable      string             // Variable name for path assignment (e.g., "path" in "path = (a)-[r]-(b)")
	TraversalLimit    int                // Early traversal cap for LIMIT-only shapes (0 = disabled)
	// boundEndNodeID filters endpoints before they count toward TraversalLimit.
	boundEndNodeID storage.NodeID
	// UnusedPropertyVariables lists pattern node variables whose properties no
	// later clause (RETURN, WHERE) reads, so the traversal may load a named
	// labelled endpoint by ID + labels alone. nil means "not analysed": every
	// variable is treated as property-read (the safe fallback). Computed by
	// the planner in executeMatchWithRelationshipsWithPathSeeded.
	UnusedPropertyVariables map[string]bool
	// endpointProperties is the read-only tail's projection for a single
	// segment's cached nodes. nil preserves complete entities for unknown
	// tails, path values, writes and intermediate chain bindings.
	endpointProperties []string
	// IntermediateNode marks a chained segment whose end node is an
	// intermediate binding of the chain rather than the pattern's final
	// endpoint. Its properties may be read by a later segment (a zero-length
	// variable relationship binds the next segment's start to it), so the
	// traversal must not load it labels-only or exist-only.
	IntermediateNode bool
}

// TraversalSegment represents one segment in a chained pattern
type TraversalSegment struct {
	FromNode     nodePatternInfo
	ToNode       nodePatternInfo
	Relationship RelationshipPattern
}

// parseTraversalPattern parses (a:Label)-[r:TYPE]->(b:Label) style patterns
// Also handles chained patterns like (a)<-[:R1]-(b)-[:R2]->(c)
// A pattern with a quantified path pattern (((x)-->(y))+) is none: only
// the clause pipeline runs one (quantified_path_pattern.go).
// Uses a state machine instead of regex to properly handle parentheses in property values
func (e *StorageExecutor) parseTraversalPattern(ctx context.Context, pattern string) *TraversalMatch {
	return e.readTraversalPattern(ctx, pattern, e.parsePropertyMap)
}

// Structural admission uses the same string reader without evaluating values.
func (e *StorageExecutor) parseTraversalPatternStructure(ctx context.Context, pattern string) *TraversalMatch {
	return e.readTraversalPattern(ctx, pattern, patternPropertyKeys)
}

func (e *StorageExecutor) readTraversalPattern(ctx context.Context, pattern string, properties patternPropertyReader) *TraversalMatch {
	if hasQuantifiedGroup(pattern) {
		return nil
	}
	pattern = normalizeAnonymousTraversalRelationships(pattern)
	// First check if this is a chained pattern (has multiple relationship segments)
	if e.isChainedPattern(pattern) {
		return e.readChainedTraversalPattern(ctx, pattern, properties)
	}
	return e.readTraversalPatternStateMachine(ctx, pattern, properties)
}

func normalizeAnonymousTraversalRelationships(pattern string) string {
	var normalized strings.Builder
	normalized.Grow(len(pattern) + 8)
	for index := 0; index < len(pattern); {
		if end, quoted := skipCypherLexicalToken(pattern, index); quoted {
			normalized.WriteString(pattern[index:end])
			index = end
			continue
		}
		character := pattern[index]
		switch {
		case strings.HasPrefix(pattern[index:], "<-->"):
			normalized.WriteString("-[]-")
			index += len("<-->")
		case strings.HasPrefix(pattern[index:], "-->"):
			normalized.WriteString("-[]->")
			index += len("-->")
		case strings.HasPrefix(pattern[index:], "<--"):
			normalized.WriteString("<-[]-")
			index += len("<--")
		case strings.HasPrefix(pattern[index:], "--"):
			normalized.WriteString("-[]-")
			index += len("--")
		default:
			normalized.WriteByte(character)
			index++
		}
	}
	return normalized.String()
}

// isChainedPattern checks if a pattern has multiple relationship segments
// e.g., (a)<-[:R1]-(b)-[:R2]->(c) or (a)-[:R1]->(b)-[:R2]->(c)
func (e *StorageExecutor) isChainedPattern(pattern string) bool {
	// Count relationship patterns by counting ]-
	// A chained pattern has at least 2 relationship segments
	count := 0
	// Reverse iteration: order doesn't matter for counting
	for i := len(pattern) - 2; i >= 0; i-- {
		if pattern[i] == ']' && (pattern[i+1] == '-' || pattern[i+1] == '>') {
			count++
		}
	}
	return count >= 2
}

// parseChainedTraversalPattern parses multi-segment patterns like (a)<-[:R1]-(b)-[:R2]->(c)
func (e *StorageExecutor) parseChainedTraversalPattern(ctx context.Context, pattern string) *TraversalMatch {
	return e.readChainedTraversalPattern(ctx, pattern, e.parsePropertyMap)
}

func (e *StorageExecutor) readChainedTraversalPattern(ctx context.Context, pattern string, properties patternPropertyReader) *TraversalMatch {
	result := &TraversalMatch{
		IsChained:         true,
		Segments:          []TraversalSegment{},
		IntermediateNodes: []nodePatternInfo{},
	}

	// Parse segments by splitting on relationship boundaries
	// We need to find each (node)-[rel]->(node) or (node)<-[rel]-(node) segment

	// Use state machine to properly handle nested parens and quotes
	type segmentPart struct {
		nodeStr string
		relStr  string
	}

	var parts []segmentPart
	var currentNode strings.Builder
	var currentRel strings.Builder
	inNode := false
	inRel := false
	parenDepth := 0
	bracketDepth := 0

	for i := 0; i < len(pattern); i++ {
		if end, quoted := skipCypherLexicalToken(pattern, i); quoted {
			if inNode {
				currentNode.WriteString(pattern[i:end])
			} else if inRel {
				currentRel.WriteString(pattern[i:end])
			}
			i = end - 1
			continue
		}
		c := pattern[i]

		switch c {
		case '(':
			if parenDepth == 0 {
				inNode = true
			}
			parenDepth++
			if inNode {
				currentNode.WriteByte(c)
			}
		case ')':
			parenDepth--
			if inNode {
				currentNode.WriteByte(c)
			}
			if parenDepth == 0 {
				inNode = false
			}
		case '[':
			// A bracket inside a node pattern belongs to a property value
			// (list, subscript or slice), not to the next relationship.
			if inNode {
				currentNode.WriteByte(c)
				continue
			}
			if bracketDepth == 0 {
				inRel = true
			}
			bracketDepth++
			if inRel {
				currentRel.WriteByte(c)
			}
		case ']':
			if inNode {
				currentNode.WriteByte(c)
				continue
			}
			if inRel {
				currentRel.WriteByte(c)
			}
			bracketDepth--
			if bracketDepth == 0 {
				inRel = false
				// Capture the direction arrows after ]
				for j := i + 1; j < len(pattern) && (pattern[j] == '-' || pattern[j] == '>'); j++ {
					currentRel.WriteByte(pattern[j])
					i = j
				}
				// Save this part
				parts = append(parts, segmentPart{
					nodeStr: currentNode.String(),
					relStr:  currentRel.String(),
				})
				currentNode.Reset()
				currentRel.Reset()
			}
		case '<', '-':
			if !inNode && !inRel && parenDepth == 0 && bracketDepth == 0 {
				// Direction marker before relationship - add to next rel
				currentRel.WriteByte(c)
			} else if inNode {
				currentNode.WriteByte(c)
			} else if inRel {
				currentRel.WriteByte(c)
			}
		default:
			if inNode {
				currentNode.WriteByte(c)
			} else if inRel {
				currentRel.WriteByte(c)
			}
		}
	}

	// Capture final node if present
	if currentNode.Len() > 0 {
		parts = append(parts, segmentPart{
			nodeStr: currentNode.String(),
			relStr:  "",
		})
	}

	// Now convert parts to segments
	if len(parts) < 2 {
		return nil // Not enough parts for a valid pattern
	}

	// Parse all nodes first
	var allNodes []nodePatternInfo
	for _, part := range parts {
		nodeStr := strings.Trim(part.nodeStr, "()")
		node, err := readNodePattern(ctx, nodeStr, properties)
		if err != nil {
			recordExpressionFailure(ctx, err)
			return nil
		}
		allNodes = append(allNodes, node)
	}

	// Build segments
	for i := 0; i < len(parts)-1; i++ {
		relStr := parts[i].relStr
		if relStr == "" {
			continue
		}

		relationship, err := readRelationshipPattern(ctx, relStr, properties)
		if err != nil {
			recordExpressionFailure(ctx, err)
			return nil
		}
		segment := TraversalSegment{
			FromNode:     allNodes[i],
			ToNode:       allNodes[i+1],
			Relationship: *relationship,
		}
		result.Segments = append(result.Segments, segment)
	}

	// Set start and end nodes
	if len(allNodes) > 0 {
		result.StartNode = allNodes[0]
	}
	if len(allNodes) > 1 {
		result.EndNode = allNodes[len(allNodes)-1]
	}

	// Intermediate nodes are all nodes except first and last
	if len(allNodes) > 2 {
		result.IntermediateNodes = allNodes[1 : len(allNodes)-1]
	}

	// For backward compatibility, set single Relationship to first segment
	if len(result.Segments) > 0 {
		result.Relationship = result.Segments[0].Relationship
	}

	return result
}

// parseTraversalPatternStateMachine parses patterns with a state machine
// to properly handle parentheses and special characters inside quoted property values.
func (e *StorageExecutor) parseTraversalPatternStateMachine(ctx context.Context, pattern string) *TraversalMatch {
	return e.readTraversalPatternStateMachine(ctx, pattern, e.parsePropertyMap)
}

func (e *StorageExecutor) readTraversalPatternStateMachine(ctx context.Context, pattern string, properties patternPropertyReader) *TraversalMatch {
	// Find the boundaries of (startNode), -[rel]->, and (endNode)
	// respecting quotes and nested parentheses

	// Find start node: first balanced parentheses
	startIdx := strings.Index(pattern, "(")
	if startIdx < 0 {
		return nil
	}
	startEnd := findMatchingParen(pattern, startIdx)
	if startEnd < 0 {
		return nil
	}
	startNodeStr := pattern[startIdx+1 : startEnd]

	// Find relationship: -[...]-> or <-[...]-
	relStart := strings.Index(pattern[startEnd:], "[")
	if relStart < 0 {
		return nil
	}
	relStart += startEnd
	relEnd := findMatchingBracket(pattern, relStart)
	if relEnd < 0 {
		return nil
	}

	// Extract full relationship pattern including arrows
	relPatternStart := startEnd + 1
	relPatternEnd := relEnd + 1
	// Include the arrow after ]
	for relPatternEnd < len(pattern) && (pattern[relPatternEnd] == '-' || pattern[relPatternEnd] == '>') {
		relPatternEnd++
	}
	relStr := pattern[relPatternStart:relPatternEnd]

	// Find end node: next balanced parentheses after relationship
	endStart := strings.Index(pattern[relEnd:], "(")
	if endStart < 0 {
		return nil
	}
	endStart += relEnd
	endEnd := findMatchingParen(pattern, endStart)
	if endEnd < 0 {
		return nil
	}
	endNodeStr := pattern[endStart+1 : endEnd]

	start, err := readNodePattern(ctx, startNodeStr, properties)
	if err != nil {
		recordExpressionFailure(ctx, err)
		return nil
	}
	end, err := readNodePattern(ctx, endNodeStr, properties)
	if err != nil {
		recordExpressionFailure(ctx, err)
		return nil
	}
	relationship, err := readRelationshipPattern(ctx, relStr, properties)
	if err != nil {
		recordExpressionFailure(ctx, err)
		return nil
	}
	return &TraversalMatch{StartNode: start, Relationship: *relationship, EndNode: end}
}

func findMatchingBracket(s string, startIdx int) int {
	return findMatchingDelimiter(s, startIdx, '[', ']')
}

// findMatchingParen finds the index of the closing paren that matches the
// opening paren at startIdx. It shares the comment- and quote-aware matcher
// so a ')' inside a string, backtick name or comment never closes early.
func findMatchingParen(s string, startIdx int) int {
	return findMatchingDelimiter(s, startIdx, '(', ')')
}

// parseNodePatternFromString parses n:Label {props} from a string
func (e *StorageExecutor) parseNodePatternFromString(ctx context.Context, s string) (nodePatternInfo, error) {
	return e.parseNodePattern(ctx, s)
}

// traverseGraph executes the traversal and returns all matching paths
func (e *StorageExecutor) traverseGraph(ctx context.Context, match *TraversalMatch) []PathResult {
	viewport, _ := TemporalViewportFromContext(ctx)
	checker, _ := e.getStorage(ctx).(temporalCurrentNodeChecker)
	// Handle chained patterns differently (multi-segment traversal)
	if match.IsChained && len(match.Segments) > 1 {
		return e.traverseChainedGraph(ctx, match, nil)
	}

	startNodes, seeded, err := e.relationshipTypeSeedNodes(ctx, match)
	if !seeded && err == nil {
		startNodes, _, err = e.collectPipelineInitialNodeCandidates(ctx, match.StartNode, "", pipelineMatchPhysicalHint{limit: -1, earlyLimit: -1})
	}
	if err != nil {
		recordExpressionFailure(ctx, err)
		return nil
	}

	// Filter indexed candidates through the shared complete pattern check.
	if len(match.StartNode.properties) > 0 || len(match.StartNode.labels) > 0 {
		var filtered []*storage.Node
		for _, n := range startNodes {
			if e.pipelineNodeMatchesPattern(n, match.StartNode) {
				filtered = append(filtered, n)
			}
		}
		startNodes = filtered
	}

	// OPTIMIZATION: Use parallel traversal for large start node sets
	// Threshold is MinBatchSize (default 200) - goroutine overhead hurts small traversals
	config := GetParallelConfig()
	// Keep traversal single-threaded when early LIMIT short-circuiting is active so
	// we can stop globally once enough paths are found.
	if config.Enabled && len(startNodes) >= config.MinBatchSize && match.TraversalLimit <= 0 {
		return e.traverseGraphParallel(ctx, match, startNodes, config, viewport, checker)
	}

	return e.traverseGraphSequential(ctx, match, startNodes, viewport, checker)
}

// relationshipTypeSeedNodes is the start nodes of a one-hop match whose start
// node has no label or property and whose relationship has types, such as
// ()-[r:T {id: $id}]->(): the endpoints the direction starts from, of the
// relationships of those types, read from the type index. A label-less scan
// would read and decode every node, for a relationship among a few. seeded is
// false for any other match, which collectPipelineInitialNodeCandidates seeds.
// The traversal still checks the whole pattern from each start node.
func (e *StorageExecutor) relationshipTypeSeedNodes(ctx context.Context, match *TraversalMatch) (nodes []*storage.Node, seeded bool, err error) {
	relationship := match.Relationship
	if planTraversalScan(match).access != traversalTypeScan {
		return nil, false, nil
	}
	store := e.getStorage(ctx)
	seen := make(map[storage.NodeID]bool)
	add := func(id storage.NodeID) {
		if seen[id] {
			return
		}
		seen[id] = true
		if node, getErr := e.newRelationshipEndpointReader(store).readRetained(id, nil); getErr == nil && node != nil {
			nodes = append(nodes, node)
		}
	}
	for _, relationshipType := range relationship.Types {
		edges, err := store.GetEdgesByType(relationshipType)
		if err != nil {
			return nil, true, err
		}
		for _, edge := range edges {
			if edge == nil {
				continue
			}
			switch relationship.Direction {
			case "outgoing":
				if id, ok := edge.StartIdentity().NodeLookupID(store); ok {
					add(id)
				}
			case "incoming":
				if id, ok := edge.EndIdentity().NodeLookupID(store); ok {
					add(id)
				}
			default:
				if id, ok := edge.StartIdentity().NodeLookupID(store); ok {
					add(id)
				}
				if id, ok := edge.EndIdentity().NodeLookupID(store); ok {
					add(id)
				}
			}
		}
	}
	return nodes, true, nil
}

func (e *StorageExecutor) traverseGraphWithStreamingStartNodes(
	ctx context.Context,
	match *TraversalMatch,
	viewport TemporalViewport,
	checker temporalCurrentNodeChecker,
) ([]PathResult, bool, error) {
	store := e.getStorage(ctx)
	labels := match.StartNode.labels
	var stream func(func(*storage.Node) error) error
	if e.queryNodeReader(store) != nil {
		stream = func(visit func(*storage.Node) error) error {
			return streamQueryNodes(ctx, store, labels, visit)
		}
	} else if len(labels) > 0 {
		reader, ok := store.(storage.ProjectedLabelNodeReader)
		if !ok {
			return nil, false, nil
		}
		stream = func(visit func(*storage.Node) error) error {
			return reader.StreamNodesByLabelProjected(labels[0], nil, visit)
		}
	} else {
		reader, ok := store.(storage.StreamingEngine)
		if !ok {
			return nil, false, nil
		}
		stream = func(visit func(*storage.Node) error) error {
			return reader.StreamNodes(ctx, visit)
		}
	}

	remaining := match.TraversalLimit
	hideSystemNodes := shouldHideSystemNodes(store)
	var paths []PathResult
	err := stream(func(node *storage.Node) error {
		if node == nil || (hideSystemNodes && isSystemNode(node)) {
			return nil
		}
		if len(labels) > 0 && !mergeNodeHasLabels(node, labels) {
			return nil
		}
		visible, err := nodeVisibleInTemporalViewport(node, viewport, checker)
		if err != nil {
			return err
		}
		if !visible {
			return nil
		}

		limitedMatch := *match
		limitedMatch.TraversalLimit = remaining
		found := e.traverseGraphSequential(ctx, &limitedMatch, []*storage.Node{node}, viewport, checker)
		paths = append(paths, found...)
		remaining -= len(found)
		if remaining <= 0 {
			return storage.ErrIterationStopped
		}
		return nil
	})
	if err != nil && err != storage.ErrIterationStopped {
		return nil, true, err
	}
	return paths, true, nil
}

// traverseGraphSequential performs sequential traversal from start nodes
func (e *StorageExecutor) traverseGraphSequential(ctx context.Context, match *TraversalMatch, startNodes []*storage.Node, viewport TemporalViewport, checker temporalCurrentNodeChecker) []PathResult {
	var results []PathResult
	remaining := -1
	if match.TraversalLimit > 0 {
		remaining = match.TraversalLimit
	}

	for _, startNode := range startNodes {
		if remaining == 0 {
			break
		}
		ctxLimit := 0
		if remaining > 0 {
			ctxLimit = remaining
		}
		traversalCtx := &TraversalContext{
			startNode:                    startNode,
			endNodeID:                    match.boundEndNodeID,
			relTypes:                     match.Relationship.Types,
			relTypeSet:                   buildRelTypeSet(match.Relationship.Types),
			relProperties:                match.Relationship.Properties,
			direction:                    match.Relationship.Direction,
			minHops:                      match.Relationship.MinHops,
			maxHops:                      match.Relationship.MaxHops,
			usedEdges:                    make(map[storage.EntityIdentity]bool),
			nodeCache:                    make(map[storage.NodeID]*storage.Node),
			limit:                        ctxLimit,
			temporalViewport:             viewport,
			temporalChecker:              checker,
			cancelCtx:                    ctx,
			repeatable:                   repeatableElements(ctx),
			endpointsNeedOnlyExist:       traversalEndpointsNeedOnlyExist(match),
			nodeProperties:               match.endpointProperties,
			endpointsNeedOnlyLabels:      traversalEndpointsNeedOnlyLabels(match),
			relationshipsNeedOnlyHeaders: traversalRelationshipsNeedOnlyHeaders(match),
		}

		paths := e.findPaths(traversalCtx, startNode, []*storage.Node{startNode}, []*storage.Edge{}, 0, &match.EndNode)
		traversalCtx.memory.close()
		results = append(results, paths...)
		if remaining > 0 {
			remaining -= len(paths)
		}
		if ctx != nil && ctx.Err() != nil {
			break
		}
	}

	return results
}

// traverseGraphParallel performs parallel traversal from multiple start nodes
// Each goroutine gets its own TraversalContext to avoid data races
func (e *StorageExecutor) traverseGraphParallel(ctx context.Context, match *TraversalMatch, startNodes []*storage.Node, config ParallelConfig, viewport TemporalViewport, checker temporalCurrentNodeChecker) []PathResult {
	numWorkers := config.MaxWorkers
	if numWorkers > len(startNodes) {
		numWorkers = len(startNodes)
	}

	// Channel for collecting results from workers
	type workerResult struct {
		paths []PathResult
	}
	resultsChan := make(chan workerResult, numWorkers)

	// Divide start nodes among workers
	chunkSize := (len(startNodes) + numWorkers - 1) / numWorkers

	var wg sync.WaitGroup
	for i := 0; i < numWorkers; i++ {
		start := i * chunkSize
		end := start + chunkSize
		if start >= len(startNodes) {
			break
		}
		if end > len(startNodes) {
			end = len(startNodes)
		}

		wg.Add(1)
		go func(workerNodes []*storage.Node) {
			defer wg.Done()

			var workerPaths []PathResult
			for _, startNode := range workerNodes {
				if ctx != nil && ctx.Err() != nil {
					break
				}
				// Each goroutine gets its own traversal state (no shared state)
				traversalCtx := &TraversalContext{
					startNode:                    startNode,
					endNodeID:                    match.boundEndNodeID,
					relTypes:                     match.Relationship.Types,
					relTypeSet:                   buildRelTypeSet(match.Relationship.Types),
					relProperties:                match.Relationship.Properties,
					direction:                    match.Relationship.Direction,
					minHops:                      match.Relationship.MinHops,
					maxHops:                      match.Relationship.MaxHops,
					usedEdges:                    make(map[storage.EntityIdentity]bool),
					nodeCache:                    make(map[storage.NodeID]*storage.Node),
					temporalViewport:             viewport,
					temporalChecker:              checker,
					cancelCtx:                    ctx,
					repeatable:                   repeatableElements(ctx),
					endpointsNeedOnlyExist:       traversalEndpointsNeedOnlyExist(match),
					nodeProperties:               match.endpointProperties,
					endpointsNeedOnlyLabels:      traversalEndpointsNeedOnlyLabels(match),
					relationshipsNeedOnlyHeaders: traversalRelationshipsNeedOnlyHeaders(match),
				}

				paths := e.findPaths(traversalCtx, startNode, []*storage.Node{startNode}, []*storage.Edge{}, 0, &match.EndNode)
				workerPaths = append(workerPaths, paths...)
			}

			resultsChan <- workerResult{paths: workerPaths}
		}(startNodes[start:end])
	}

	// Close channel when all workers done
	go func() {
		wg.Wait()
		close(resultsChan)
	}()

	// Collect results
	var allResults []PathResult
	for wr := range resultsChan {
		allResults = append(allResults, wr.paths...)
	}

	return allResults
}

// traverseChainedGraph handles multi-segment patterns like (a)<-[:R1]-(b)-[:R2]->(c)
// It traverses each segment sequentially, joining results where intermediate nodes match
func (e *StorageExecutor) traverseChainedGraph(ctx context.Context, match *TraversalMatch, seedNodes []*storage.Node) []PathResult {
	if len(match.Segments) == 0 {
		return nil
	}

	// Start with first segment
	firstSeg := match.Segments[0]
	simpleMatch := &TraversalMatch{
		StartNode:    firstSeg.FromNode,
		EndNode:      firstSeg.ToNode,
		Relationship: firstSeg.Relationship,
		// A path variable exposes the chain's nodes and relationships, and the
		// planner's per-variable read analysis applies to every segment's
		// endpoint, so propagate both into each segment's traversal flags.
		PathVariable:            match.PathVariable,
		UnusedPropertyVariables: match.UnusedPropertyVariables,
		// The first segment's end node is an intermediate binding: a later
		// zero-length segment can bind it to a named variable whose
		// properties are read, so it must load fully.
		IntermediateNode: true,
	}
	// Get initial paths from first segment
	var currentPaths []PathResult
	if len(seedNodes) > 0 {
		for _, startNode := range seedNodes {
			currentPaths = append(currentPaths, e.traverseFromNode(ctx, startNode, simpleMatch)...)
		}
	} else {
		currentPaths = e.traverseGraph(ctx, simpleMatch)
	}
	repeats := chainRepeatedNodes(match.Segments)
	kept := currentPaths[:0]
	for _, path := range currentPaths {
		path.SegmentLengths = []int{len(path.Relationships)}
		if repeats.consistent(path, 1) {
			kept = append(kept, path)
		}
	}
	currentPaths = kept

	// For each subsequent segment, extend paths
	for segIdx := 1; segIdx < len(match.Segments); segIdx++ {
		seg := match.Segments[segIdx]
		var extendedPaths []PathResult

		for _, path := range currentPaths {
			if len(path.Nodes) == 0 {
				continue
			}

			// The last node in current path should be the start of next segment
			lastNode := path.Nodes[len(path.Nodes)-1]

			// Create a match for this segment starting from the last node
			segMatch := &TraversalMatch{
				StartNode:               seg.FromNode,
				EndNode:                 seg.ToNode,
				Relationship:            seg.Relationship,
				PathVariable:            match.PathVariable,
				UnusedPropertyVariables: match.UnusedPropertyVariables,
				// Only the final segment's end node is the pattern's endpoint;
				// every earlier one is an intermediate binding.
				IntermediateNode: segIdx < len(match.Segments)-1,
			}

			// Traverse from the last node
			segPaths := e.traverseFromNode(ctx, lastNode, segMatch)

			// Join paths: combine current path with each segment path
			for _, segPath := range segPaths {
				if !repeatableElements(ctx) && pathResultsReuseRelationship(path, segPath) {
					continue
				}
				// Create extended path
				extended := PathResult{
					Nodes:          make([]*storage.Node, 0, len(path.Nodes)+len(segPath.Nodes)-1),
					Relationships:  make([]*storage.Edge, 0, len(path.Relationships)+len(segPath.Relationships)),
					Length:         path.Length + segPath.Length,
					SegmentLengths: append(append([]int{}, path.SegmentLengths...), len(segPath.Relationships)),
				}

				// Add all nodes from current path
				extended.Nodes = append(extended.Nodes, path.Nodes...)

				// Add nodes from segment path (skip first node as it's the same as last node of current)
				if len(segPath.Nodes) > 1 {
					extended.Nodes = append(extended.Nodes, segPath.Nodes[1:]...)
				}

				// Add all relationships
				extended.Relationships = append(extended.Relationships, path.Relationships...)
				extended.Relationships = append(extended.Relationships, segPath.Relationships...)

				if repeats.consistent(extended, segIdx+1) {
					extendedPaths = append(extendedPaths, extended)
				}
			}
		}

		currentPaths = extendedPaths
	}

	return currentPaths
}

// chainNodeRepeats lists, for each node position of a chain (position j
// ends segment j-1; position 0 starts the chain), the earlier position that
// names the same variable, or -1. A variable named twice in one chain, as b
// in (a)-[:R]->(b)-[:S]->(b), binds one node: Neo4j matches only the paths
// whose two positions are that node. It is nil when no variable repeats.
type chainNodeRepeats []int

func chainRepeatedNodes(segments []TraversalSegment) chainNodeRepeats {
	variable := func(position int) string {
		if position == 0 {
			return segments[0].FromNode.variable
		}
		return segments[position-1].ToNode.variable
	}
	var repeats chainNodeRepeats
	for position := 1; position <= len(segments); position++ {
		name := variable(position)
		if name == "" {
			continue
		}
		for earlier := 0; earlier < position; earlier++ {
			if variable(earlier) != name {
				continue
			}
			if repeats == nil {
				repeats = make(chainNodeRepeats, len(segments)+1)
				for index := range repeats {
					repeats[index] = -1
				}
			}
			repeats[position] = earlier
			break
		}
	}
	return repeats
}

// consistent reports whether path, which has its first position segments
// (path.SegmentLengths), binds the node at position to the node at the
// earlier position of the same variable.
func (repeats chainNodeRepeats) consistent(path PathResult, position int) bool {
	if repeats == nil || repeats[position] < 0 {
		return true
	}
	return chainPositionNode(path, position).Identity() == chainPositionNode(path, repeats[position]).Identity()
}

func chainPositionNode(path PathResult, position int) *storage.Node {
	offset := 0
	for _, length := range path.SegmentLengths[:position] {
		offset += length
	}
	return path.Nodes[offset]
}

func pathResultsReuseRelationship(left, right PathResult) bool {
	for _, leftRelationship := range left.Relationships {
		for _, rightRelationship := range right.Relationships {
			if leftRelationship != nil && rightRelationship != nil && leftRelationship.Identity() == rightRelationship.Identity() {
				return true
			}
		}
	}
	return false
}

// traverseFromNode traverses from a specific node rather than finding start nodes by label
func (e *StorageExecutor) traverseFromNode(traversalCtx context.Context, startNode *storage.Node, match *TraversalMatch) []PathResult {
	// Verify the start node matches the expected pattern (labels and properties)
	if len(match.StartNode.labels) > 0 {
		found := false
		for _, label := range startNode.Labels {
			for _, requiredLabel := range match.StartNode.labels {
				if label == requiredLabel {
					found = true
					break
				}
			}
			if found {
				break
			}
		}
		if !found {
			return nil
		}
	}

	if len(match.StartNode.properties) > 0 {
		if !e.nodeMatchesProps(startNode, match.StartNode.properties) {
			return nil
		}
	}

	ctx := e.newTraversalContext(traversalCtx, startNode, &match.Relationship)
	ctx.endNodeID = match.boundEndNodeID
	// Single-segment traversals (including each segment of a chain) share the
	// planner's endpoint/relationship read analysis so the header and
	// labels-only fast paths apply to chained patterns too (#1110).
	ctx.endpointsNeedOnlyExist = traversalEndpointsNeedOnlyExist(match)
	ctx.nodeProperties = match.endpointProperties
	ctx.endpointsNeedOnlyLabels = traversalEndpointsNeedOnlyLabels(match)
	ctx.relationshipsNeedOnlyHeaders = traversalRelationshipsNeedOnlyHeaders(match)
	return e.findPaths(ctx, startNode, []*storage.Node{startNode}, []*storage.Edge{}, 0, &match.EndNode)
}

// newTraversalContext is the depth-first search state for relationship
// pattern rel from startNode: its types, properties, direction and length
// bounds, the statement's temporal viewport, and traversalCtx for
// cancellation.
func (e *StorageExecutor) newTraversalContext(traversalCtx context.Context, startNode *storage.Node, rel *RelationshipPattern) *TraversalContext {
	ctx := &TraversalContext{
		startNode:     startNode,
		relTypes:      rel.Types,
		relTypeSet:    buildRelTypeSet(rel.Types),
		relProperties: rel.Properties,
		direction:     rel.Direction,
		minHops:       rel.MinHops,
		maxHops:       rel.MaxHops,
		usedEdges:     make(map[storage.EntityIdentity]bool),
		nodeCache:     make(map[storage.NodeID]*storage.Node),
		cancelCtx:     traversalCtx,
		repeatable:    repeatableElements(traversalCtx),
	}
	if viewport, ok := TemporalViewportFromContext(traversalCtx); ok {
		ctx.temporalViewport = viewport
		if checker, canCheck := e.getStorage(traversalCtx).(temporalCurrentNodeChecker); canCheck {
			ctx.temporalChecker = checker
		}
	}
	return ctx
}

// loadTraversalEndpointNode resolves a traversal endpoint using the same
// tolerance as the existing traversal path: if the adjacency entry points at a
// node that no longer loads, the candidate path is skipped rather than failing
// the whole query. This gives callers one place to share the current dangling-
// edge semantics.
func (e *StorageExecutor) loadTraversalEndpointNode(ctx *TraversalContext, nextNodeID storage.NodeID) (*storage.Node, bool) {
	nextNode := ctx.nodeCache[nextNodeID]
	if nextNode == nil {
		properties := ctx.nodeProperties
		if ctx.temporalViewport.Enabled() {
			properties = nil
		}
		if (ctx.endpointsNeedOnlyLabels || ctx.endpointsNeedOnlyExist) && !ctx.temporalViewport.Enabled() {
			properties = []string{}
		}
		var err error
		nextNode, err = e.newRelationshipEndpointReader(e.storage).readRetained(nextNodeID, properties)
		if err != nil || nextNode == nil {
			return nil, false
		}
		ctx.nodeCache[nextNodeID] = nextNode
	}
	visible, err := nodeVisibleInTemporalViewport(nextNode, ctx.temporalViewport, ctx.temporalChecker)
	if err != nil || !visible {
		return nil, false
	}
	return nextNode, true
}

// findPaths performs DFS to find all paths matching the pattern
func (e *StorageExecutor) findPaths(
	ctx *TraversalContext,
	currentNode *storage.Node,
	pathNodes []*storage.Node,
	pathEdges []*storage.Edge,
	depth int,
	endPattern *nodePatternInfo,
) []PathResult {
	var results []PathResult

	// Every frame and sibling expansion must observe cancellation. Sampling
	// recursive entries alone leaves callers expanding the remaining siblings
	// after a cancelled child returns.
	if ctx.traversalCancelled() {
		return results
	}

	// OPTIMIZATION: Early termination if limit reached
	if ctx.limit > 0 && ctx.resultCount >= ctx.limit {
		return results
	}

	if depth > ctx.deepest {
		ctx.deepest = depth
	}

	// Check if current path meets minimum length and endpoint requirements
	if depth >= ctx.minHops && (ctx.endNodeID == "" || storage.NodeID(currentNode.IdentityKey()) == ctx.endNodeID) {
		if e.matchesEndPattern(currentNode, endPattern) {
			// A path the expansion keeps counts against the statement's
			// memory limit; going over cancels the statement (#1343).
			if err := ctx.memoryAccount().grow(estimatePathResultBytes(len(pathNodes), len(pathEdges))); err != nil {
				return results
			}
			results = append(results, PathResult{
				Nodes:         append([]*storage.Node{}, pathNodes...),
				Relationships: append([]*storage.Edge{}, pathEdges...),
				Length:        depth,
			})
			ctx.resultCount++ // Track for early termination

			// Check again after adding result
			if ctx.limit > 0 && ctx.resultCount >= ctx.limit {
				return results
			}
		}
	}

	// Stop if we've reached max depth
	if depth >= ctx.maxHops {
		return results
	}

	// Translate the native source once at the storage boundary. Local IDs
	// alone cannot select adjacency in a composite with duplicate IDs.
	lookupID, validSource := currentNode.Identity().NodeLookupID(e.storage)
	if !validSource {
		return results
	}
	// Get edges based on direction
	var edges []*storage.Edge
	switch ctx.direction {
	case "outgoing":
		edges = e.traversalEdges(ctx, lookupID, true)
	case "incoming":
		edges = e.traversalEdges(ctx, lookupID, false)
	case "both":
		var err error
		edges, err = undirectedIncidentEdges(e.storage, lookupID)
		if err != nil && ctx.cancelCtx != nil {
			recordExpressionFailure(ctx.cancelCtx, err)
			return results
		}
	}

	// Traverse each edge
	for _, edge := range edges {
		if ctx.traversalCancelled() {
			return results
		}
		// A Cypher path may revisit a node, but it cannot reuse a relationship.
		// This also prevents an undirected expansion from walking the same edge
		// immediately back in the opposite direction.
		if ctx.usedEdges[edge.Identity()] && !ctx.repeatable {
			continue
		}
		// Check relationship type filter
		if len(ctx.relTypes) > 0 {
			if len(ctx.relTypes) == 1 {
				if edge.Type != ctx.relTypes[0] {
					continue
				}
			} else {
				if _, ok := ctx.relTypeSet[edge.Type]; !ok {
					continue
				}
			}
		}
		if len(ctx.relProperties) > 0 && !e.edgeMatchesProps(edge, ctx.relProperties) {
			continue
		}

		// Get next node
		nextIdentity := edge.StartIdentity()
		if ctx.direction == "outgoing" || (ctx.direction == "both" && edge.StartIdentity() == currentNode.Identity()) {
			nextIdentity = edge.EndIdentity()
		}
		nextNodeID, validSource := nextIdentity.NodeLookupID(e.storage)
		if !validSource {
			continue
		}

		nextNode, ok := e.loadTraversalEndpointNode(ctx, nextNodeID)
		if !ok {
			continue
		}

		ctx.usedEdges[edge.Identity()] = true

		// Recurse with optimized path copying (pre-allocate exact size)
		nextNodesLen, ok := util.SafeIntAdd(len(pathNodes), 1)
		if !ok {
			ctx.usedEdges[edge.Identity()] = false
			continue
		}
		newPathNodes := make([]*storage.Node, nextNodesLen)
		copy(newPathNodes, pathNodes)
		newPathNodes[len(pathNodes)] = nextNode

		nextEdgesLen, ok := util.SafeIntAdd(len(pathEdges), 1)
		if !ok {
			ctx.usedEdges[edge.Identity()] = false
			continue
		}
		newPathEdges := make([]*storage.Edge, nextEdgesLen)
		copy(newPathEdges, pathEdges)
		newPathEdges[len(pathEdges)] = edge

		subPaths := e.findPaths(ctx, nextNode, newPathNodes, newPathEdges, depth+1, endPattern)
		results = append(results, subPaths...)

		// Unmark for sibling paths.
		ctx.usedEdges[edge.Identity()] = false
	}

	return results
}

// matchesEndPattern checks if a node matches the end pattern requirements
func (e *StorageExecutor) matchesEndPattern(node *storage.Node, pattern *nodePatternInfo) bool {
	if pattern == nil {
		return true
	}

	// Check labels
	if len(pattern.labels) > 0 {
		for _, reqLabel := range pattern.labels {
			found := false
			for _, nodeLabel := range node.Labels {
				if nodeLabel == reqLabel {
					found = true
					break
				}
			}
			if !found {
				return false
			}
		}
	}

	// Check properties
	return e.nodeMatchesProps(node, pattern.properties)
}

// PathContext holds node/relationship mappings for expression evaluation
type PathContext struct {
	nodes        map[string]*storage.Node
	rels         map[string]*storage.Edge
	pathLength   int                    // Length of the path for length(path) function
	paths        map[string]*PathResult // Full paths by variable name for relationships(path), nodes(path)
	allPathEdges []*storage.Edge        // All edges in the path (for variable-length patterns)
	allPathNodes []*storage.Node        // All nodes in the path
}

// pathContextValues returns the path's variables as row values: nodes and
// relationships as themselves, named paths as the pipeline's path maps.
func (e *StorageExecutor) pathContextValues(pathCtx PathContext) map[string]interface{} {
	values := make(map[string]interface{}, len(pathCtx.nodes)+len(pathCtx.rels)+len(pathCtx.paths))
	for name, node := range pathCtx.nodes {
		if node != nil {
			values[name] = node
		}
	}
	for name, relationship := range pathCtx.rels {
		if relationship != nil {
			values[name] = relationship
		}
	}
	for name, path := range pathCtx.paths {
		if path != nil {
			values[name] = e.pathContextRowValue(path)
		}
	}
	return values
}

// relationshipOnlyPath reports whether a path context entry is a
// variable-length relationship variable: the context keeps it as a
// PathResult holding only the relationships.
func relationshipOnlyPath(path *PathResult) bool {
	return len(path.Nodes) == 0
}

// relationshipListValue is a variable-length relationship variable's Cypher
// value: its relationships in path order.
func relationshipListValue(relationships []*storage.Edge) []interface{} {
	values := make([]interface{}, len(relationships))
	for index, relationship := range relationships {
		values[index] = relationship
	}
	return values
}

// pathContextEntryValue is a path context entry's value for the path-context
// expression evaluator: a variable-length relationship variable is its list
// of relationships, a named path the evaluator's path map.
func pathContextEntryValue(path *PathResult) interface{} {
	if relationshipOnlyPath(path) {
		return relationshipListValue(path.Relationships)
	}
	return map[string]interface{}{
		"_pathResult": path,
		"length":      path.Length,
		"nodes":       path.Nodes,
		"rels":        path.Relationships,
	}
}

// pathContextRowValue is a path context entry's value for the row
// evaluator: a variable-length relationship variable is its list of
// relationships, a named path the pipeline's path map (#882).
func (e *StorageExecutor) pathContextRowValue(path *PathResult) interface{} {
	if relationshipOnlyPath(path) {
		return relationshipListValue(path.Relationships)
	}
	return e.pathToMap(*path)
}

// buildPathContext creates a context for evaluating expressions over a path
func (e *StorageExecutor) buildPathContext(path PathResult, match *TraversalMatch) PathContext {
	ctx := PathContext{
		nodes:        make(map[string]*storage.Node),
		rels:         make(map[string]*storage.Edge),
		paths:        make(map[string]*PathResult),
		pathLength:   path.Length,        // Store path length for length(path) function
		allPathEdges: path.Relationships, // Store all edges for relationships(path)
		allPathNodes: path.Nodes,         // Store all nodes for nodes(path)
	}

	// Map the path variable if present (for path functions like relationships(path), nodes(path))
	if match.PathVariable != "" {
		pathCopy := path // Make a copy to store pointer
		ctx.paths[match.PathVariable] = &pathCopy
	}

	// Map start node
	if match.StartNode.variable != "" && len(path.Nodes) > 0 {
		ctx.nodes[match.StartNode.variable] = path.Nodes[0]
	}

	// Map end node
	if match.EndNode.variable != "" && len(path.Nodes) > 0 {
		ctx.nodes[match.EndNode.variable] = path.Nodes[len(path.Nodes)-1]
	}

	// For chained patterns, map intermediate nodes
	// Path nodes layout: [startNode, intermediate1, intermediate2, ..., endNode]
	// IntermediateNodes layout: [intermediate1, intermediate2, ...]
	if match.IsChained && len(match.IntermediateNodes) > 0 {
		nodeOffset := 0
		for i, intermediateInfo := range match.IntermediateNodes {
			if i < len(path.SegmentLengths) {
				nodeOffset += path.SegmentLengths[i]
			} else {
				nodeOffset++
			}
			if intermediateInfo.variable != "" {
				pathIdx := nodeOffset
				if pathIdx < len(path.Nodes) {
					ctx.nodes[intermediateInfo.variable] = path.Nodes[pathIdx]
				}
			}
		}

		// Also map relationships from each segment
		relationshipOffset := 0
		for i, seg := range match.Segments {
			segmentLength := 1
			if i < len(path.SegmentLengths) {
				segmentLength = path.SegmentLengths[i]
			}
			segmentEnd := relationshipOffset + segmentLength
			if segmentEnd > len(path.Relationships) {
				segmentEnd = len(path.Relationships)
			}
			if seg.Relationship.Variable != "" {
				if seg.Relationship.VariableLength {
					relationships := append([]*storage.Edge{}, path.Relationships[relationshipOffset:segmentEnd]...)
					ctx.paths[seg.Relationship.Variable] = &PathResult{Relationships: relationships}
				} else if relationshipOffset < segmentEnd {
					ctx.rels[seg.Relationship.Variable] = path.Relationships[relationshipOffset]
				}
			}
			relationshipOffset = segmentEnd
		}
	} else {
		// Map relationship (single segment)
		if match.Relationship.Variable != "" {
			if match.Relationship.VariableLength {
				relationships := append([]*storage.Edge{}, path.Relationships...)
				ctx.paths[match.Relationship.Variable] = &PathResult{Relationships: relationships}
			} else if len(path.Relationships) > 0 {
				ctx.rels[match.Relationship.Variable] = path.Relationships[0]
			}
		}
	}

	return ctx
}

// getRelType gets the type of a relationship - used for type(r) function
func (e *StorageExecutor) getRelType(relID storage.EdgeID) string {
	edge, err := e.storage.GetEdge(relID)
	if err != nil || edge == nil {
		return ""
	}
	return edge.Type
}

// filterPathsByWhere filters paths based on a WHERE clause condition.
// This evaluates conditions like "i.name = 'value'" against each path's
// context. extra merges the row's other bindings into the context, so a
// predicate can also reference seed-row variables beyond the path endpoints
// (#581: WHERE length(p) > limit.n).
func (e *StorageExecutor) filterPathsByWhere(ctx context.Context, paths []PathResult, matches *TraversalMatch, whereClause string, extra map[string]interface{}) []PathResult {
	if whereClause == "" {
		return paths
	}

	var filtered []PathResult
	where := prepareRowPredicate(strings.TrimSpace(whereClause))
	for _, path := range paths {
		context := e.buildPathContext(path, matches)
		for name, value := range extra {
			switch v := value.(type) {
			case *storage.Node:
				if v != nil {
					context.nodes[name] = v
				}
			case *storage.Edge:
				if v != nil {
					context.rels[name] = v
				}
			}
		}
		values := e.pathContextValues(context)
		bindParameterRow(ctx, values)
		if where.holds(e, ctx, values) {
			filtered = append(filtered, path)
		}
	}
	return filtered
}

// evaluateWhereOnPath evaluates a WHERE condition against a path context.
// Handles conditions like: i.name = 'value', e.score < 90, etc.
func (e *StorageExecutor) evaluateWhereOnPath(ctx context.Context, whereClause string, pathCtx PathContext) bool {
	values := e.pathContextValues(pathCtx)
	bindParameterRow(ctx, values)
	return e.evaluateRowPredicate(ctx, strings.TrimSpace(whereClause), values)
}

package cypher

// Fast path for bulk-seed UNWIND + multi-MATCH + CREATE queries used by
// seeders (Northwind, fixtures, migrations, etc.).
//
// Shape:
//
//	UNWIND $rows AS row
//	MATCH (a:LabelA {keyA: row.fieldA})     (1..N independent MATCH clauses)
//	MATCH (b:LabelB {keyB: row.fieldB})
//	CREATE (n:LabelN {prop1: row.f1, ...})  (1..N CREATE node clauses)
//	CREATE (n)-[:REL]->(a)                  (0..N CREATE edge clauses
//	CREATE (b)-[:REL2]->(n)                  between bound or new nodes)
//
// No RETURN, no WITH, no WHERE, no nested UNWIND.
//
// The handler parses the mutation body ONCE and then for each row:
//   1. Looks up each MATCH target via the property index when available,
//      falling back to label scan + property filter.
//   2. Constructs storage.Node values for each CREATE-node pattern and
//      calls storage.CreateNode once each.
//   3. Constructs storage.Edge values for each CREATE-edge pattern and
//      calls storage.CreateEdge once each.
//
// This avoids the per-row `replaceVariableInMutationQuery` + `executeInternal`
// cycle that re-parses the Cypher text for every UNWIND item.

import (
	"context"
	"fmt"
	valueconvert "github.com/orneryd/nornicdb/pkg/convert"
	"strings"
)

// unwindMultiMatchCreatePlan is the parsed form of the mutation body.
type unwindMultiMatchCreatePlan struct {
	matches     []matchClauseSpec
	nodeCreates []createNodeSpec
	edgeCreates []createEdgeSpec
}

// matchClauseSpec represents a single simple MATCH clause:
//
//	MATCH (variable:Label {propName: row.fieldName})
type matchClauseSpec struct {
	variable   string
	label      string
	propName   string
	rowField   string // set for the simple row.<field> form used by older batch helpers
	lookupExpr string
	bindingVar string
	byID       bool
}

func (m matchClauseSpec) batchKey() nodeBatchMatchKey {
	if m.byID {
		return nodeBatchMatchKey{label: m.label, prop: "\x00elementId"}
	}
	return nodeBatchMatchKey{label: m.label, prop: m.propName}
}

type unwindBatchRow struct {
	item    interface{}
	itemMap map[string]interface{}
}

// createNodeSpec represents `CREATE (variable:Label {...})`. Properties may
// reference `row.<field>` (rowFieldRefs) or be concrete literals (literals).
type createNodeSpec struct {
	variable     string
	label        string
	rowFieldRefs map[string]string // property name → row field name
	literals     map[string]any    // property name → literal value
}

// createEdgeSpec represents `CREATE (src)-[:TYPE {...}]->(dst)`.
type createEdgeSpec struct {
	startVar     string
	endVar       string
	relType      string
	rowFieldRefs map[string]string
	literals     map[string]any
}

// executeUnwindMultiMatchCreateBatch attempts the fast path. Returns
// (result, true, err) on success, (nil, false, nil) if the shape doesn't
// match (caller falls back), or (nil, true, err) on mid-execution error.
func (e *StorageExecutor) executeUnwindMultiMatchCreateBatch(
	ctx context.Context, unwindVar string, items []interface{}, restQuery string,
) (*ExecuteResult, bool, error) {
	// Bail on shapes we don't handle.
	trimmed := strings.TrimSpace(restQuery)
	if trimmed == "" {
		return nil, false, nil
	}

	mutationPart := trimmed
	returnPart := ""
	if returnIdx := findKeywordIndexInContext(trimmed, "RETURN"); returnIdx >= 0 {
		mutationPart = strings.TrimSpace(trimmed[:returnIdx])
		returnPart = strings.TrimSpace(trimmed[returnIdx:])
		_, ok := parseUnwindBatchCountReturn(ctx, returnPart)
		if !ok {
			return nil, false, nil
		}
	}
	if withIdx := findKeywordIndexInContext(mutationPart, "WITH"); withIdx >= 0 {
		withClause := strings.TrimSpace(mutationPart[withIdx+len("WITH"):])
		if !isSimpleWithPassthroughClause(withClause) {
			return nil, false, nil
		}
		mutationPart = strings.TrimSpace(mutationPart[:withIdx])
	}
	if mutationPart == "" {
		return nil, false, nil
	}

	upper := upperASCII(mutationPart)
	// nested UNWIND / SET / MERGE / DELETE / REMOVE / FOREACH disqualify
	// this fast path. RETURN and a simple passthrough WITH are handled above.
	disqualifiers := []string{"SET", "MERGE", "DELETE", "REMOVE", "FOREACH", "OPTIONAL MATCH"}
	for _, d := range disqualifiers {
		if findKeywordIndex(upper, d) >= 0 {
			return nil, false, nil
		}
	}
	// Nested UNWIND.
	if findKeywordIndex(upper, "UNWIND") >= 0 {
		return nil, false, nil
	}

	plan, ok := parseUnwindMultiMatchCreatePlan(mutationPart, unwindVar)
	if !ok {
		return nil, false, nil
	}

	for _, created := range plan.nodeCreates {
		for _, match := range plan.matches {
			if created.label == match.label {
				return nil, false, nil
			}
		}
	}
	schema := e.getStorage(ctx).GetSchema()
	for _, match := range plan.matches {
		if !match.byID && (schema == nil || !schema.HasPropertyIndex(match.label, match.propName)) {
			return nil, false, nil
		}
	}
	rows := make([]map[string]interface{}, 0, len(items))
	for _, item := range items {
		row, ok := toStringAnyMap(item)
		if !ok {
			rows = nil
			break
		}
		rows = append(rows, row)
	}
	if len(rows) > 0 {
		matches := make([]matchClauseSpec, 0, len(plan.matches))
		for _, match := range plan.matches {
			if !match.byID {
				matches = append(matches, match)
			}
		}
		prefetched, unique, err := e.buildRelationshipBatchNodeMatchIndex(e.getStorage(ctx), rows, matches)
		if err != nil {
			return nil, true, err
		}
		if !unique {
			return nil, false, nil
		}
		ctx = context.WithValue(ctx, pipelinePrefetchedNodeCandidatesKey{}, prefetched)
	}
	ctx = context.WithValue(ctx, pipelineIndependentCreateBatchKey{}, true)
	result, handled, err := e.executeUnwindRowsPipeline(ctx, unwindVar, items, restQuery)
	if handled && err == nil {
		e.markUnwindMultiMatchCreateBatchUsed()
	}
	return result, handled, err
}

func isSimpleWithPassthroughClause(clause string) bool {
	trimmed := strings.TrimSpace(clause)
	if trimmed == "" || strings.HasPrefix(trimmed, ",") || strings.HasSuffix(trimmed, ",") {
		return false
	}
	parts := splitTopLevelComma(clause)
	if len(parts) == 0 {
		return false
	}
	for _, raw := range parts {
		token := strings.TrimSpace(raw)
		if token == "" {
			return false
		}
		asIdx := findKeywordIndexInContext(token, "AS")
		if asIdx >= 0 {
			lhs := strings.TrimSpace(token[:asIdx])
			rhs := strings.TrimSpace(token[asIdx+2:])
			if !isSimpleIdentifier(lhs) || !isSimpleIdentifier(rhs) {
				return false
			}
			continue
		}
		if !isSimpleIdentifier(token) {
			return false
		}
	}
	return true
}

func (e *StorageExecutor) evaluateUnwindBatchLookupExpr(match matchClauseSpec, row unwindBatchRow) (interface{}, bool) {
	return e.evaluateBatchLookupExpr(match, row.item, row.itemMap)
}

func (e *StorageExecutor) evaluateBatchLookupExpr(match matchClauseSpec, bindingValue interface{}, bindingMap map[string]interface{}) (interface{}, bool) {
	if match.rowField != "" && bindingMap != nil {
		if v, ok := bindingMap[match.rowField]; ok {
			return normalizePropValue(v), true
		}
	}
	expr := strings.TrimSpace(match.lookupExpr)
	if expr == "" {
		return nil, false
	}
	if value, ok := e.evaluateBatchLookupExprFast(expr, match.bindingVar, bindingValue, bindingMap); ok {
		return normalizePropValue(value), true
	}

	values := make(map[string]interface{}, 1)
	if match.bindingVar != "" {
		values[match.bindingVar] = bindingValue
	}
	value, resolved, err := e.evaluateExpressionFromValuesResult(rowStatementContextOrBackground(values), expr, values)
	return normalizePropValue(value), resolved && err == nil
}

func (e *StorageExecutor) evaluateBatchLookupExprFast(expr, bindingVar string, bindingValue interface{}, bindingMap map[string]interface{}) (interface{}, bool) {
	if value, ok := evaluateBatchLookupOperand(expr, bindingVar, bindingValue, bindingMap); ok {
		return value, true
	}
	return e.evaluateBatchArithmeticLookupExpr(expr, bindingVar, bindingValue, bindingMap)
}

func (e *StorageExecutor) evaluateBatchArithmeticLookupExpr(expr, bindingVar string, bindingValue interface{}, bindingMap map[string]interface{}) (interface{}, bool) {
	if leftExpr, rightExpr, ok := splitByOperatorWithOptions(expr, " + ", true, false); ok {
		left, leftOK := evaluateBatchLookupOperand(leftExpr, bindingVar, bindingValue, bindingMap)
		right, rightOK := evaluateBatchLookupOperand(rightExpr, bindingVar, bindingValue, bindingMap)
		return e.evaluateArithmeticLookupResult('+', left, leftOK, right, rightOK)
	}
	if leftExpr, rightExpr, ok := splitByOperatorWithOptions(expr, "+", true, false); ok {
		left, leftOK := evaluateBatchLookupOperand(leftExpr, bindingVar, bindingValue, bindingMap)
		right, rightOK := evaluateBatchLookupOperand(rightExpr, bindingVar, bindingValue, bindingMap)
		return e.evaluateArithmeticLookupResult('+', left, leftOK, right, rightOK)
	}
	if leftExpr, rightExpr, ok := splitByOperatorWithOptions(expr, "*", true, false); ok {
		left, leftOK := evaluateBatchLookupOperand(leftExpr, bindingVar, bindingValue, bindingMap)
		right, rightOK := evaluateBatchLookupOperand(rightExpr, bindingVar, bindingValue, bindingMap)
		return e.evaluateArithmeticLookupResult('*', left, leftOK, right, rightOK)
	}
	if leftExpr, rightExpr, ok := splitByOperatorWithOptions(expr, "/", true, false); ok {
		left, leftOK := evaluateBatchLookupOperand(leftExpr, bindingVar, bindingValue, bindingMap)
		right, rightOK := evaluateBatchLookupOperand(rightExpr, bindingVar, bindingValue, bindingMap)
		return e.evaluateArithmeticLookupResult('/', left, leftOK, right, rightOK)
	}
	if leftExpr, rightExpr, ok := splitByOperatorWithOptions(expr, "%", true, false); ok {
		left, leftOK := evaluateBatchLookupOperand(leftExpr, bindingVar, bindingValue, bindingMap)
		right, rightOK := evaluateBatchLookupOperand(rightExpr, bindingVar, bindingValue, bindingMap)
		return e.evaluateArithmeticLookupResult('%', left, leftOK, right, rightOK)
	}
	if leftExpr, rightExpr, ok := splitByOperatorWithOptions(expr, " - ", true, false); ok {
		left, leftOK := evaluateBatchLookupOperand(leftExpr, bindingVar, bindingValue, bindingMap)
		right, rightOK := evaluateBatchLookupOperand(rightExpr, bindingVar, bindingValue, bindingMap)
		return e.evaluateArithmeticLookupResult('-', left, leftOK, right, rightOK)
	}
	if leftExpr, rightExpr, ok := splitByOperatorWithOptions(expr, "-", true, false); ok && strings.TrimSpace(leftExpr) != "" {
		left, leftOK := evaluateBatchLookupOperand(leftExpr, bindingVar, bindingValue, bindingMap)
		right, rightOK := evaluateBatchLookupOperand(rightExpr, bindingVar, bindingValue, bindingMap)
		return e.evaluateArithmeticLookupResult('-', left, leftOK, right, rightOK)
	}
	return nil, false
}

func evaluateBatchLookupOperand(expr, bindingVar string, bindingValue interface{}, bindingMap map[string]interface{}) (interface{}, bool) {
	expr = strings.TrimSpace(expr)
	if expr == "" {
		return nil, false
	}
	if bindingVar != "" && expr == bindingVar {
		return bindingValue, true
	}
	if field, ok := simpleUnwindFieldRef(expr, bindingVar); ok && bindingMap != nil {
		value, found := bindingMap[field]
		return value, found
	}
	if parsed, ok := parseLiteralValueFromComputedRow(expr); ok {
		return parsed, true
	}
	return nil, false
}

// buildPropsFromSpec assembles a property map for a CREATE from a row with
// the same value semantics as the CREATE core: values are normalized
// (normalizePropValue) and a null value leaves the property unset.
func buildPropsFromSpec(row map[string]any, rowRefs map[string]string, literals map[string]any) map[string]any {
	props := make(map[string]any, len(rowRefs)+len(literals))
	put := func(name string, value any) {
		if value = normalizePropValue(value); value != nil {
			props[name] = value
		}
	}
	for propName, rowField := range rowRefs {
		if row != nil {
			if v, ok := row[rowField]; ok {
				put(propName, v)
			}
		}
	}
	for k, v := range literals {
		put(k, v)
	}
	return props
}

// parseUnwindMultiMatchCreatePlan parses the mutation body into structured
// clauses. Returns (plan, true) on success, (empty, false) if the shape is
// unsupported (any ambiguity means fallback).
func parseUnwindMultiMatchCreatePlan(restQuery, unwindVar string) (unwindMultiMatchCreatePlan, bool) {
	plan := unwindMultiMatchCreatePlan{}

	// Split into clauses on MATCH/CREATE boundaries. We use the existing
	// position-finder so word boundaries are respected.
	matchPositions := findAllKeywordPositions(restQuery, "MATCH")
	createPositions := findAllKeywordPositions(restQuery, "CREATE")

	type boundary struct {
		pos  int
		kind int // 0=MATCH, 1=CREATE
	}
	boundaries := make([]boundary, 0, len(matchPositions)+len(createPositions))
	for _, p := range matchPositions {
		boundaries = append(boundaries, boundary{pos: p, kind: 0})
	}
	for _, p := range createPositions {
		boundaries = append(boundaries, boundary{pos: p, kind: 1})
	}
	// Insertion sort by pos.
	for i := 1; i < len(boundaries); i++ {
		j := i
		for j > 0 && boundaries[j-1].pos > boundaries[j].pos {
			boundaries[j-1], boundaries[j] = boundaries[j], boundaries[j-1]
			j--
		}
	}
	if len(boundaries) == 0 {
		return plan, false
	}

	for i, b := range boundaries {
		end := len(restQuery)
		if i+1 < len(boundaries) {
			end = boundaries[i+1].pos
		}
		body := strings.TrimSpace(restQuery[b.pos:end])
		if b.kind == 0 {
			matches, ok := parseSimpleMatchClauseList(body, unwindVar)
			if !ok {
				return unwindMultiMatchCreatePlan{}, false
			}
			plan.matches = append(plan.matches, matches...)
		} else {
			// CREATE — could be node or edge.
			node, edge, kind, ok := parseSimpleCreateClause(body, unwindVar)
			if !ok {
				return unwindMultiMatchCreatePlan{}, false
			}
			switch kind {
			case 'n':
				plan.nodeCreates = append(plan.nodeCreates, node)
			case 'e':
				plan.edgeCreates = append(plan.edgeCreates, edge)
			default:
				return unwindMultiMatchCreatePlan{}, false
			}
		}
	}

	// Must have at least one MATCH and at least one CREATE for this fast
	// path to be worth taking.
	if len(plan.matches) == 0 {
		return unwindMultiMatchCreatePlan{}, false
	}
	if len(plan.nodeCreates) == 0 && len(plan.edgeCreates) == 0 {
		return unwindMultiMatchCreatePlan{}, false
	}
	return plan, true
}

// parseSimpleMatchClause parses `MATCH (var:Label {prop: unwindVar.field})`.
func parseSimpleMatchClause(clause, unwindVar string) (matchClauseSpec, bool) {
	body := strings.TrimSpace(strings.TrimPrefix(clause, "MATCH"))
	body = strings.TrimPrefix(body, "match")
	body = strings.TrimSpace(body)
	if whereIdx := findKeywordIndexInContext(body, "WHERE"); whereIdx >= 0 {
		pattern := strings.TrimSpace(body[:whereIdx])
		whereExpr := strings.TrimSpace(body[whereIdx+len("WHERE"):])
		if !strings.HasPrefix(pattern, "(") || !strings.HasSuffix(pattern, ")") {
			return matchClauseSpec{}, false
		}
		inner := strings.TrimSpace(pattern[1 : len(pattern)-1])
		parts := strings.SplitN(inner, ":", 2)
		varName := strings.TrimSpace(parts[0])
		label := ""
		if len(parts) == 2 {
			label = strings.TrimSpace(parts[1])
		}
		if !isSimpleIdentifier(varName) || (label != "" && !isSimpleIdentifier(label)) {
			return matchClauseSpec{}, false
		}
		equals := strings.SplitN(whereExpr, "=", 2)
		if len(equals) != 2 || !strings.EqualFold(strings.TrimSpace(equals[0]), "elementId("+varName+")") {
			return matchClauseSpec{}, false
		}
		right := strings.TrimSpace(equals[1])
		if !referencesUnwindBinding(right, unwindVar) {
			return matchClauseSpec{}, false
		}
		rowField, _ := simpleUnwindFieldRef(right, unwindVar)
		return matchClauseSpec{variable: varName, label: label, rowField: rowField, lookupExpr: right, bindingVar: unwindVar, byID: true}, true
	}
	return parseSimpleMatchPattern(body, unwindVar)
}

// parseSimpleMatchClauseList parses `MATCH p1, p2, ...`: one or more
// comma-separated property-equality patterns in one MATCH clause (the Pokec
// wiring shape `MATCH (n:L {id: p[0]}), (m:L {id: p[1]})`). A WHERE clause
// only covers the single-pattern elementId form, which is delegated to
// parseSimpleMatchClause.
func parseSimpleMatchClauseList(clause, unwindVar string) ([]matchClauseSpec, bool) {
	body := strings.TrimSpace(strings.TrimPrefix(clause, "MATCH"))
	body = strings.TrimPrefix(body, "match")
	body = strings.TrimSpace(body)
	if whereIdx := findKeywordIndexInContext(body, "WHERE"); whereIdx >= 0 {
		m, ok := parseSimpleMatchClause(clause, unwindVar)
		if !ok {
			return nil, false
		}
		return []matchClauseSpec{m}, true
	}
	patterns := splitTopLevelComma(body)
	if len(patterns) == 0 {
		return nil, false
	}
	matches := make([]matchClauseSpec, 0, len(patterns))
	for _, pattern := range patterns {
		m, ok := parseSimpleMatchPattern(strings.TrimSpace(pattern), unwindVar)
		if !ok {
			return nil, false
		}
		matches = append(matches, m)
	}
	return matches, true
}

// parseSimpleMatchPattern parses one `(var:Label {prop: expr})` pattern,
// the property-equality half of parseSimpleMatchClause.
func parseSimpleMatchPattern(body, unwindVar string) (matchClauseSpec, bool) {
	if !strings.HasPrefix(body, "(") {
		return matchClauseSpec{}, false
	}
	closeIdx := findMatchingParen(body, 0)
	if closeIdx < 0 || closeIdx != len(body)-1 {
		return matchClauseSpec{}, false
	}
	inner := strings.TrimSpace(body[1:closeIdx])
	// Must be `var:Label {prop: var.field}`.
	braceIdx := strings.Index(inner, "{")
	if braceIdx < 0 {
		return matchClauseSpec{}, false
	}
	head := strings.TrimSpace(inner[:braceIdx])
	closeBrace := strings.LastIndex(inner, "}")
	if closeBrace < 0 {
		return matchClauseSpec{}, false
	}
	propsBody := strings.TrimSpace(inner[braceIdx+1 : closeBrace])
	parts := strings.SplitN(head, ":", 2)
	if len(parts) != 2 {
		return matchClauseSpec{}, false
	}
	varName := strings.TrimSpace(parts[0])
	label := strings.TrimSpace(parts[1])
	if !isSimpleIdentifier(varName) || !isSimpleIdentifier(label) {
		return matchClauseSpec{}, false
	}
	// propsBody must be a single `key: var.field` pair (no commas).
	if strings.Contains(propsBody, ",") {
		return matchClauseSpec{}, false
	}
	colonIdx := strings.Index(propsBody, ":")
	if colonIdx <= 0 {
		return matchClauseSpec{}, false
	}
	propName := strings.TrimSpace(propsBody[:colonIdx])
	expr := strings.TrimSpace(propsBody[colonIdx+1:])
	if !isSimpleIdentifier(propName) {
		return matchClauseSpec{}, false
	}
	if !referencesUnwindBinding(expr, unwindVar) {
		return matchClauseSpec{}, false
	}
	field, _ := simpleUnwindFieldRef(expr, unwindVar)
	return matchClauseSpec{
		variable:   varName,
		label:      label,
		propName:   propName,
		rowField:   field,
		lookupExpr: expr,
		bindingVar: unwindVar,
	}, true
}

func simpleUnwindFieldRef(expr, unwindVar string) (string, bool) {
	expr = strings.TrimSpace(expr)
	dot := strings.Index(expr, ".")
	if dot <= 0 {
		return "", false
	}
	base := strings.TrimSpace(expr[:dot])
	field := strings.TrimSpace(expr[dot+1:])
	if base == unwindVar && isSimpleIdentifier(field) {
		return field, true
	}
	return "", false
}

func referencesUnwindBinding(expr, unwindVar string) bool {
	expr = strings.TrimSpace(expr)
	if expr == unwindVar {
		return true
	}
	for i := 0; i < len(expr); {
		ch := expr[i]
		if isIdentStartByte(ch) {
			start := i
			i++
			for i < len(expr) && isIdentByte(expr[i]) {
				i++
			}
			if expr[start:i] == unwindVar {
				return true
			}
			continue
		}
		i++
	}
	return false
}

// parseSimpleCreateClause returns either a node spec or edge spec. kind is
// 'n' for node, 'e' for edge, or 0 if unrecognised.
func parseSimpleCreateClause(clause, unwindVar string) (createNodeSpec, createEdgeSpec, byte, bool) {
	body := strings.TrimSpace(strings.TrimPrefix(clause, "CREATE"))
	body = strings.TrimPrefix(body, "create")
	body = strings.TrimSpace(body)

	// Edge form: (a)-[:TYPE]->(b)  or  (a)-[:TYPE {...}]->(b)
	if isRelationshipPatternOperand(body) {
		edge, ok := parseSimpleCreateEdge(body, unwindVar)
		if !ok {
			return createNodeSpec{}, createEdgeSpec{}, 0, false
		}
		return createNodeSpec{}, edge, 'e', true
	}

	// Node form: (var:Label {props})
	node, ok := parseSimpleCreateNode(body, unwindVar)
	if !ok {
		return createNodeSpec{}, createEdgeSpec{}, 0, false
	}
	return node, createEdgeSpec{}, 'n', true
}

func parseSimpleCreateNode(body, unwindVar string) (createNodeSpec, bool) {
	if !strings.HasPrefix(body, "(") {
		return createNodeSpec{}, false
	}
	closeIdx := findMatchingParen(body, 0)
	if closeIdx < 0 || closeIdx != len(body)-1 {
		return createNodeSpec{}, false
	}
	inner := strings.TrimSpace(body[1:closeIdx])
	braceIdx := strings.Index(inner, "{")
	if braceIdx < 0 {
		return createNodeSpec{}, false
	}
	head := strings.TrimSpace(inner[:braceIdx])
	closeBrace := strings.LastIndex(inner, "}")
	if closeBrace < 0 {
		return createNodeSpec{}, false
	}
	propsBody := strings.TrimSpace(inner[braceIdx+1 : closeBrace])
	parts := strings.SplitN(head, ":", 2)
	if len(parts) != 2 {
		return createNodeSpec{}, false
	}
	varName := strings.TrimSpace(parts[0])
	label := strings.TrimSpace(parts[1])
	if !isSimpleIdentifier(varName) || !isSimpleIdentifier(label) {
		return createNodeSpec{}, false
	}
	rowRefs, literals, ok := parsePropsBodyForUnwindFastPath(propsBody, unwindVar)
	if !ok {
		return createNodeSpec{}, false
	}
	return createNodeSpec{
		variable:     varName,
		label:        label,
		rowFieldRefs: rowRefs,
		literals:     literals,
	}, true
}

func parseSimpleCreateEdge(body, unwindVar string) (createEdgeSpec, bool) {
	// Only handle outgoing arrow form: (start)-[:TYPE [{props}]]->(end).
	arrowIdx := strings.Index(body, "]->")
	if arrowIdx < 0 {
		return createEdgeSpec{}, false
	}
	lBracketIdx := strings.LastIndex(body[:arrowIdx], "-[")
	if lBracketIdx < 0 {
		return createEdgeSpec{}, false
	}
	// Start node: body[0 : lBracketIdx] — must be "(start)".
	startPart := strings.TrimSpace(body[:lBracketIdx])
	if !strings.HasPrefix(startPart, "(") || !strings.HasSuffix(startPart, ")") {
		return createEdgeSpec{}, false
	}
	startVar := strings.TrimSpace(startPart[1 : len(startPart)-1])
	if !isSimpleIdentifier(startVar) {
		return createEdgeSpec{}, false
	}
	// End node: body[arrowIdx+3 :] — must be "(end)".
	endPart := strings.TrimSpace(body[arrowIdx+3:])
	if !strings.HasPrefix(endPart, "(") || !strings.HasSuffix(endPart, ")") {
		return createEdgeSpec{}, false
	}
	endVar := strings.TrimSpace(endPart[1 : len(endPart)-1])
	if !isSimpleIdentifier(endVar) {
		return createEdgeSpec{}, false
	}
	// Relationship: body[lBracketIdx+2 : arrowIdx] — `:TYPE` or `:TYPE {props}`.
	rel := strings.TrimSpace(body[lBracketIdx+2 : arrowIdx])
	if !strings.HasPrefix(rel, ":") {
		return createEdgeSpec{}, false
	}
	rel = strings.TrimSpace(rel[1:])
	relType := rel
	propsBody := ""
	if braceIdx := strings.Index(rel, "{"); braceIdx >= 0 {
		relType = strings.TrimSpace(rel[:braceIdx])
		closeBrace := strings.LastIndex(rel, "}")
		if closeBrace < 0 {
			return createEdgeSpec{}, false
		}
		propsBody = strings.TrimSpace(rel[braceIdx+1 : closeBrace])
	}
	if !isSimpleIdentifier(relType) {
		return createEdgeSpec{}, false
	}
	rowRefs, literals, ok := parsePropsBodyForUnwindFastPath(propsBody, unwindVar)
	if !ok {
		return createEdgeSpec{}, false
	}
	return createEdgeSpec{
		startVar:     startVar,
		endVar:       endVar,
		relType:      relType,
		rowFieldRefs: rowRefs,
		literals:     literals,
	}, true
}

// parsePropsBodyForUnwindFastPath parses `k1: unwindVar.f1, k2: 42, k3: 'str'`.
// Values may be `row.field` references or simple scalars (int / float / string /
// bool / null). If any value doesn't fit these forms, returns ok=false.
func parsePropsBodyForUnwindFastPath(propsBody, unwindVar string) (map[string]string, map[string]any, bool) {
	propsBody = strings.TrimSpace(propsBody)
	if propsBody == "" {
		return map[string]string{}, map[string]any{}, true
	}
	rowRefs := map[string]string{}
	literals := map[string]any{}
	for _, pair := range splitTopLevelComma(propsBody) {
		pair = strings.TrimSpace(pair)
		if pair == "" {
			continue
		}
		colon := findTopLevelMapKeyValueSeparator(pair)
		if colon <= 0 {
			return nil, nil, false
		}
		key := normalizePropertyKey(strings.TrimSpace(pair[:colon]))
		expr := strings.TrimSpace(pair[colon+1:])
		if !isSimpleIdentifier(key) {
			return nil, nil, false
		}
		// row.field reference?
		if dot := strings.Index(expr, "."); dot > 0 {
			base := strings.TrimSpace(expr[:dot])
			field := strings.TrimSpace(expr[dot+1:])
			if base == unwindVar && isSimpleIdentifier(field) {
				rowRefs[key] = field
				continue
			}
		}
		// Scalar literal.
		if v, ok := parseLiteralScalarForPipeline(expr); ok {
			literals[key] = v
			continue
		}
		// Unsupported expression — bail.
		return nil, nil, false
	}
	return rowRefs, literals, true
}

// propEqKeyBatch produces a stable string key used to index the per-batch
// MATCH-prefetch map. It coerces integer and float types so an int64
// coming from a Bolt row and an equivalent float64 stored on a node hash
// to the same key. Strings, bools, and nil get their own unambiguous
// prefixes so they cannot collide with numeric keys.
func propEqKeyBatch(v interface{}) string {
	if v == nil {
		return "n:"
	}
	if i, ok := coerceInt64(v); ok {
		return fmt.Sprintf("i:%d", i)
	}
	if f, ok := coerceFloat64(v); ok {
		// Integer-valued floats hash to the same key as the int form so a
		// Bolt int64 and a Cypher float literal compare equal through the map.
		if f == float64(int64(f)) {
			return fmt.Sprintf("i:%d", int64(f))
		}
		return fmt.Sprintf("f:%g", f)
	}
	if s, ok := v.(string); ok {
		return "s:" + s
	}
	if b, ok := v.(bool); ok {
		return fmt.Sprintf("b:%t", b)
	}
	return fmt.Sprintf("x:%v", v)
}

func coerceInt64(v interface{}) (int64, bool) {
	return valueconvert.IntegerValue(v)
}

func coerceFloat64(v interface{}) (float64, bool) {
	return valueconvert.NumericFloat64(v)
}

package cypher

import (
	"context"
	math "github.com/orneryd/nornicdb/pkg/math/libm"
	"sort"
	"strconv"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
	"github.com/orneryd/nornicdb/pkg/util"
)

type unwindRelationshipMergeBatchPlan struct {
	matches       []matchClauseSpec
	merge         relationshipMergeSpec
	setRelVar     string
	setRowVar     string
	vectorSetters []relationshipVectorSetterSpec
	returns       []rowFieldReturnSpec
}

type relationshipMergeSpec struct {
	startVar     string
	endVar       string
	relVar       string
	relType      string
	rowFieldRefs map[string]string
	literals     map[string]interface{}
	keyProps     []relationshipMergeKeyProp
}

type relationshipMergeKeyProp struct {
	propName   string
	rowField   string
	literal    interface{}
	literalSet bool
}

type relationshipVectorSetterSpec struct {
	relVar   string
	propName string
	rowField string
}

type rowFieldReturnSpec struct {
	rowField string
	alias    string
}

type nodeBatchMatchKey struct {
	label string
	prop  string
}

func (e *StorageExecutor) executeUnwindRelationshipMergeBatch(
	ctx context.Context, unwindVar string, items []interface{}, restQuery string,
) (*ExecuteResult, bool, error) {
	plan, ok := parseUnwindRelationshipMergeBatchPlan(ctx, restQuery, unwindVar)
	if !ok {
		return nil, false, nil
	}
	rows := make([]map[string]interface{}, 0, len(items))
	for _, item := range items {
		row, ok := toStringAnyMap(item)
		if !ok || !relationshipBatchRowHasRequiredFields(row, plan) {
			return nil, false, nil
		}
		properties, storable := normalizeRelationshipBatchRowProperties(row, plan.vectorSetters)
		if !storable || !relationshipBatchPropertiesPreserveMatch(properties, plan.merge, row) || relationshipBatchEdgeKeyFromRow("", "", plan.merge, row) == "" {
			return nil, false, nil
		}
		rows = append(rows, row)
	}
	prefetched, unique, err := e.buildRelationshipBatchNodeMatchIndex(e.getStorage(ctx), rows, plan.matches)
	if err != nil {
		return nil, true, err
	}
	if !unique {
		return nil, false, nil
	}
	ctx = context.WithValue(ctx, pipelinePrefetchedNodeCandidatesKey{}, prefetched)
	result, handled, err := e.executeUnwindRowsPipeline(ctx, unwindVar, items, restQuery)
	if handled && err == nil {
		e.markUnwindRelationshipMergeBatchUsed()
	}
	return result, handled, err
}

func parseUnwindRelationshipMergeBatchPlan(ctx context.Context, restQuery, unwindVar string) (unwindRelationshipMergeBatchPlan, bool) {
	plan := unwindRelationshipMergeBatchPlan{}
	trimmed := strings.TrimSpace(restQuery)
	if trimmed == "" || !startsWithKeywordFold(trimmed, "MATCH") {
		return plan, false
	}

	returnIdx := findKeywordIndexInContext(trimmed, "RETURN")
	if returnIdx < 0 {
		return plan, false
	}
	returns, ok := parseRelationshipBatchReturn(ctx, strings.TrimSpace(trimmed[returnIdx+len("RETURN"):]), unwindVar)
	if !ok {
		return plan, false
	}

	body := strings.TrimSpace(trimmed[:returnIdx])
	withIdx := findKeywordIndexInContext(body, "WITH")
	if withIdx < 0 {
		return plan, false
	}
	vectorSetters, ok := parseRelationshipBatchVectorSetters(strings.TrimSpace(body[withIdx:]), unwindVar)
	if !ok {
		return plan, false
	}
	mutationPart := strings.TrimSpace(body[:withIdx])

	setIdx := findKeywordIndexInContext(mutationPart, "SET")
	if setIdx < 0 {
		return plan, false
	}
	setRelVar, setRowVar, ok := parseRelationshipBatchSetClause(strings.TrimSpace(mutationPart[setIdx+len("SET"):]), unwindVar)
	if !ok {
		return plan, false
	}

	preSet := strings.TrimSpace(mutationPart[:setIdx])
	mergeIdx := findKeywordIndexInContext(preSet, "MERGE")
	if mergeIdx < 0 {
		return plan, false
	}
	merge, ok := parseRelationshipBatchMergeClause(strings.TrimSpace(preSet[mergeIdx:]), unwindVar)
	if !ok {
		return plan, false
	}

	matchClauses := make([]string, 0, 4)
	for _, clause := range SplitByMatch(strings.TrimSpace(preSet[:mergeIdx])) {
		clause = strings.TrimSpace(clause)
		if clause != "" {
			matchClauses = append(matchClauses, "MATCH "+clause)
		}
	}
	if len(matchClauses) == 0 {
		return plan, false
	}
	matches := make([]matchClauseSpec, 0, len(matchClauses))
	vars := make(map[string]struct{}, len(matchClauses))
	for _, clause := range matchClauses {
		match, ok := parseSimpleMatchClause(clause, unwindVar)
		if !ok {
			return plan, false
		}
		if _, exists := vars[match.variable]; exists {
			return plan, false
		}
		vars[match.variable] = struct{}{}
		matches = append(matches, match)
	}
	if _, ok := vars[merge.startVar]; !ok {
		return plan, false
	}
	if _, ok := vars[merge.endVar]; !ok {
		return plan, false
	}
	if setRelVar != merge.relVar || setRowVar != unwindVar {
		return plan, false
	}
	for _, setter := range vectorSetters {
		if setter.relVar != merge.relVar {
			return plan, false
		}
	}

	plan.matches = matches
	plan.merge = merge
	plan.setRelVar = setRelVar
	plan.setRowVar = setRowVar
	plan.vectorSetters = vectorSetters
	plan.returns = returns
	return plan, true
}

func parseRelationshipBatchMergeClause(clause, unwindVar string) (relationshipMergeSpec, bool) {
	spec := relationshipMergeSpec{}
	body := strings.TrimSpace(clause)
	if !startsWithKeywordFold(body, "MERGE") {
		return spec, false
	}
	body = strings.TrimSpace(body[len("MERGE"):])
	arrowIdx := strings.Index(body, "]->")
	if arrowIdx < 0 {
		return spec, false
	}
	lBracketIdx := strings.LastIndex(body[:arrowIdx], "-[")
	if lBracketIdx < 0 {
		return spec, false
	}
	startPart := strings.TrimSpace(body[:lBracketIdx])
	if !strings.HasPrefix(startPart, "(") || !strings.HasSuffix(startPart, ")") {
		return spec, false
	}
	startVar := strings.TrimSpace(startPart[1 : len(startPart)-1])
	if !isSimpleIdentifier(startVar) {
		return spec, false
	}

	endPart := strings.TrimSpace(body[arrowIdx+3:])
	if !strings.HasPrefix(endPart, "(") || !strings.HasSuffix(endPart, ")") {
		return spec, false
	}
	endVar := strings.TrimSpace(endPart[1 : len(endPart)-1])
	if !isSimpleIdentifier(endVar) {
		return spec, false
	}

	rel := strings.TrimSpace(body[lBracketIdx+2 : arrowIdx])
	braceIdx := strings.Index(rel, "{")
	closeBrace := strings.LastIndex(rel, "}")
	if braceIdx <= 0 || closeBrace <= braceIdx || strings.TrimSpace(rel[closeBrace+1:]) != "" {
		return spec, false
	}
	head := strings.TrimSpace(rel[:braceIdx])
	propsBody := strings.TrimSpace(rel[braceIdx+1 : closeBrace])
	headParts := strings.SplitN(head, ":", 2)
	if len(headParts) != 2 {
		return spec, false
	}
	relVar := strings.TrimSpace(headParts[0])
	relType := strings.TrimSpace(headParts[1])
	if !isSimpleIdentifier(relVar) || !isSimpleIdentifier(relType) {
		return spec, false
	}
	rowRefs, literals, ok := parsePropsBodyForUnwindFastPath(propsBody, unwindVar)
	if !ok || len(rowRefs)+len(literals) == 0 {
		return spec, false
	}
	spec.startVar = startVar
	spec.endVar = endVar
	spec.relVar = relVar
	spec.relType = relType
	spec.rowFieldRefs = rowRefs
	spec.literals = literals
	spec.keyProps = relationshipMergeKeyProps(rowRefs, literals)
	return spec, true
}

func relationshipMergeKeyProps(rowRefs map[string]string, literals map[string]interface{}) []relationshipMergeKeyProp {
	props := make([]relationshipMergeKeyProp, 0, len(rowRefs)+len(literals))
	for propName, rowField := range rowRefs {
		props = append(props, relationshipMergeKeyProp{propName: propName, rowField: rowField})
	}
	for propName, literal := range literals {
		props = append(props, relationshipMergeKeyProp{propName: propName, literal: literal, literalSet: true})
	}
	sort.Slice(props, func(i, j int) bool { return props[i].propName < props[j].propName })
	return props
}

func parseRelationshipBatchSetClause(clause, unwindVar string) (relVar, rowVar string, ok bool) {
	parts := strings.SplitN(strings.TrimSpace(clause), "=", 2)
	if len(parts) != 2 {
		return "", "", false
	}
	left := strings.TrimSpace(parts[0])
	right := strings.TrimSpace(parts[1])
	if !isSimpleIdentifier(left) || right != unwindVar {
		return "", "", false
	}
	return left, right, true
}

func parseRelationshipBatchVectorSetters(clause, unwindVar string) ([]relationshipVectorSetterSpec, bool) {
	trimmed := strings.TrimSpace(clause)
	if !startsWithKeywordFold(trimmed, "WITH") {
		return nil, false
	}
	afterWith := strings.TrimSpace(trimmed[len("WITH"):])
	callIdx := findKeywordIndexInContext(afterWith, "CALL")
	if callIdx < 0 {
		return nil, false
	}
	withItems := splitTopLevelComma(strings.TrimSpace(afterWith[:callIdx]))
	if len(withItems) < 2 {
		return nil, false
	}
	relVar := strings.TrimSpace(withItems[0])
	rowVar := strings.TrimSpace(withItems[1])
	if !isSimpleIdentifier(relVar) || rowVar != unwindVar {
		return nil, false
	}
	for _, extra := range withItems[2:] {
		if strings.TrimSpace(extra) != "" {
			return nil, false
		}
	}

	callPart := strings.TrimSpace(afterWith[callIdx+len("CALL"):])
	setters := make([]relationshipVectorSetterSpec, 0, 1)
	for callPart != "" {
		if !strings.HasPrefix(lowerASCII(callPart), "db.create.setrelationshipvectorproperty") {
			return nil, false
		}
		openParen := strings.Index(callPart, "(")
		if openParen < 0 {
			return nil, false
		}
		closeParen := findMatchingParenAt(callPart, openParen)
		if closeParen <= openParen {
			return nil, false
		}
		args := splitTopLevelComma(callPart[openParen+1 : closeParen])
		if len(args) != 3 || strings.TrimSpace(args[0]) != relVar {
			return nil, false
		}
		propName := strings.Trim(strings.TrimSpace(args[1]), "'\"")
		rowField, ok := parseRelationshipBatchRowFieldExpr(strings.TrimSpace(args[2]), unwindVar)
		if !isSimpleIdentifier(propName) || !ok {
			return nil, false
		}
		setters = append(setters, relationshipVectorSetterSpec{relVar: relVar, propName: propName, rowField: rowField})
		callPart = strings.TrimSpace(callPart[closeParen+1:])
		if callPart == "" {
			break
		}
		if !startsWithKeywordFold(callPart, "CALL") {
			return nil, false
		}
		callPart = strings.TrimSpace(callPart[len("CALL"):])
	}
	if len(setters) == 0 {
		return nil, false
	}
	return setters, true
}

func parseRelationshipBatchReturn(ctx context.Context, returnPart, unwindVar string) ([]rowFieldReturnSpec, bool) {
	plan := returnProjectionPlanFor(ctx, "RETURN "+returnPart)
	if !plan.valid || plan.star || plan.distinct || plan.hasAggregate || plan.modifiers != "" {
		return nil, false
	}
	returns := make([]rowFieldReturnSpec, 0, len(plan.projections))
	for index, projection := range plan.projections {
		rowField, ok := parseRelationshipBatchRowFieldExpr(projection.expr, unwindVar)
		if !ok || plan.columns[index] == "" {
			return nil, false
		}
		returns = append(returns, rowFieldReturnSpec{rowField: rowField, alias: plan.columns[index]})
	}
	return returns, true
}

func parseRelationshipBatchRowFieldExpr(expr, unwindVar string) (string, bool) {
	dotIdx := strings.Index(expr, ".")
	if dotIdx <= 0 {
		return "", false
	}
	base := strings.TrimSpace(expr[:dotIdx])
	field := strings.TrimSpace(expr[dotIdx+1:])
	if base != unwindVar || !isSimpleIdentifier(field) {
		return "", false
	}
	return field, true
}

func relationshipBatchRowHasRequiredFields(row map[string]interface{}, plan unwindRelationshipMergeBatchPlan) bool {
	for _, match := range plan.matches {
		if match.rowField == "" {
			continue
		}
		if _, ok := row[match.rowField]; !ok {
			return false
		}
	}
	for _, field := range plan.merge.rowFieldRefs {
		if _, ok := row[field]; !ok {
			return false
		}
	}
	for _, setter := range plan.vectorSetters {
		if _, ok := row[setter.rowField]; !ok {
			return false
		}
	}
	for _, ret := range plan.returns {
		if _, ok := row[ret.rowField]; !ok {
			return false
		}
	}
	return true
}

func (e *StorageExecutor) buildRelationshipBatchNodeMatchIndex(store storage.Engine, rows []map[string]interface{}, matches []matchClauseSpec) (map[nodeBatchMatchKey]map[string]*storage.Node, bool, error) {
	index := make(map[nodeBatchMatchKey]map[string]*storage.Node, len(matches))
	schema := store.GetSchema()
	unique := true
	matchGroups := make(map[nodeBatchMatchKey][]matchClauseSpec, len(matches))
	for _, match := range matches {
		key := nodeBatchMatchKey{label: match.label, prop: match.propName}
		matchGroups[key] = append(matchGroups[key], match)
	}
	for key, group := range matchGroups {
		idx := make(map[string]*storage.Node, len(rows))
		distinct := make(map[string]interface{}, len(rows))
		for _, match := range group {
			for _, row := range rows {
				if value, ok := e.evaluateRelationshipBatchLookupExpr(match, row); ok {
					distinct[propEqKeyBatch(value)] = value
				}
			}
		}
		if schema != nil && schema.HasPropertyIndex(key.label, key.prop) {
			unresolved := make(map[string]interface{})
			for valueKey, value := range distinct {
				ids := propertyIndexLookup(store, schema, key.label, key.prop, value)
				matched := 0
				for _, id := range ids {
					node, err := e.getQueryNode(store, id)
					if err == nil && nodeBatchMatchesValue(node, key, value) {
						matched++
						idx[valueKey] = node
					}
				}
				if matched != 1 {
					delete(idx, valueKey)
					unresolved[valueKey] = value
				}
			}
			if len(unresolved) > 0 {
				scanned, scanUnique, err := buildNodeBatchLabelMatchIndex(store, key, unresolved)
				if err != nil {
					return nil, false, err
				}
				if !scanUnique {
					unique = false
				}
				for valueKey, node := range scanned {
					idx[valueKey] = node
				}
			}
			index[key] = idx
			continue
		}

		scanned, scanUnique, err := buildNodeBatchLabelMatchIndex(store, key, distinct)
		if err != nil {
			return nil, false, err
		}
		if !scanUnique {
			unique = false
		}
		index[key] = scanned
	}
	return index, unique, nil
}

func buildNodeBatchLabelMatchIndex(store storage.Engine, key nodeBatchMatchKey, distinct map[string]interface{}) (map[string]*storage.Node, bool, error) {
	idx := make(map[string]*storage.Node, len(distinct))
	nodes, err := store.GetNodesByLabel(key.label)
	if err != nil {
		return nil, false, localizedError(localization.CypherMergeGetNodesByLabelFailed(key.label, err), err)
	}
	unique := true
	for _, node := range nodes {
		if node == nil || node.Properties == nil {
			continue
		}
		value, ok := node.Properties[key.prop]
		if !ok {
			continue
		}
		valueKey := propEqKeyBatch(value)
		wantedValue, wanted := distinct[valueKey]
		if !wanted || !nodeBatchMatchesValue(node, key, wantedValue) {
			continue
		}
		if _, exists := idx[valueKey]; exists {
			unique = false
			continue
		}
		idx[valueKey] = node
	}
	return idx, unique, nil
}

func nodeBatchMatchesValue(node *storage.Node, key nodeBatchMatchKey, value interface{}) bool {
	if node == nil || node.Properties == nil || !mergeNodeHasLabels(node, []string{key.label}) {
		return false
	}
	nodeValue, ok := node.Properties[key.prop]
	if !ok {
		return false
	}
	return propEqKeyBatch(nodeValue) == propEqKeyBatch(value)
}

func (e *StorageExecutor) lookupRelationshipBatchMatchedNode(index map[nodeBatchMatchKey]map[string]*storage.Node, match matchClauseSpec, row map[string]interface{}) *storage.Node {
	value, ok := e.evaluateRelationshipBatchLookupExpr(match, row)
	if !ok {
		return nil
	}
	return index[nodeBatchMatchKey{label: match.label, prop: match.propName}][propEqKeyBatch(value)]
}

func (e *StorageExecutor) evaluateRelationshipBatchLookupExpr(match matchClauseSpec, row map[string]interface{}) (interface{}, bool) {
	return e.evaluateBatchLookupExpr(match, row, row)
}

// normalizeRelationshipBatchRowProperties builds the property map written by
// SET rel = row (plus the vector setters) with the same semantics as every
// other SET route: null values are left out (setPropertyMap). It returns
// false when the row holds a value a property cannot store, so the caller
// falls back to the row-wise executor, which reports the error.
func normalizeRelationshipBatchRowProperties(row map[string]interface{}, vectorSetters []relationshipVectorSetterSpec) (map[string]interface{}, bool) {
	props := make(map[string]interface{}, util.SafePreallocSum(len(row), len(vectorSetters)))
	for key, value := range row {
		stored, _, err := storablePropertyValue(value)
		if err != nil {
			return nil, false
		}
		if stored != nil {
			props[key] = stored
		}
	}
	for _, setter := range vectorSetters {
		if setter.propName == setter.rowField {
			continue
		}
		// The row's values were checked above: a setter writes a copy of its
		// field's stored value.
		if stored, ok := props[setter.rowField]; ok {
			props[setter.propName] = copyStoredPropertyValue(stored)
		}
	}
	return props, true
}

func relationshipBatchMatchProperties(
	merge relationshipMergeSpec,
	row map[string]interface{},
) map[string]interface{} {
	props := make(map[string]interface{}, len(merge.keyProps))
	for _, prop := range merge.keyProps {
		if prop.literalSet {
			props[prop.propName] = normalizePropValue(prop.literal)
			continue
		}
		props[prop.propName] = normalizePropValue(row[prop.rowField])
	}
	return props
}

func relationshipBatchPropertiesPreserveMatch(
	props map[string]interface{},
	merge relationshipMergeSpec,
	row map[string]interface{},
) bool {
	for _, prop := range merge.keyProps {
		want := prop.literal
		if !prop.literalSet {
			want = row[prop.rowField]
		}
		got, ok := props[prop.propName]
		if !ok || !relationshipMergeValuesEqual(got, want) {
			return false
		}
	}
	return true
}

func buildRelationshipBatchReturnRow(row map[string]interface{}, returns []rowFieldReturnSpec) []interface{} {
	out := make([]interface{}, len(returns))
	for i, ret := range returns {
		out[i] = row[ret.rowField]
	}
	return out
}

func lookupRelationshipBatchExistingEdge(
	store storage.Engine,
	startID storage.NodeID,
	endID storage.NodeID,
	merge relationshipMergeSpec,
	row map[string]interface{},
	edgeKey string,
	existingByKey map[string]*storage.Edge,
	scannedPairs map[string]struct{},
) (*storage.Edge, error) {
	if edge := existingByKey[edgeKey]; edge != nil {
		return edge, nil
	}
	pairKey := string(startID) + "\x00" + string(endID)
	if _, scanned := scannedPairs[pairKey]; scanned {
		return nil, nil
	}
	edges, err := store.GetEdgesBetween(startID, endID)
	if err != nil {
		return nil, localizedError(localization.CypherMergeGetEdgesBetweenFailed(string(startID), string(endID), err), err)
	}
	for _, edge := range edges {
		if edge == nil || edge.Type != merge.relType || edge.Properties == nil {
			continue
		}
		key, ok := relationshipBatchEdgeKeyFromProperties(startID, endID, merge, edge.Properties)
		if ok {
			existingByKey[key] = edge
		}
	}
	scannedPairs[pairKey] = struct{}{}
	return existingByKey[edgeKey], nil
}

func relationshipBatchEdgeKeyFromRow(startID storage.NodeID, endID storage.NodeID, merge relationshipMergeSpec, row map[string]interface{}) string {
	if key, ok := relationshipBatchScalarEdgeKey(startID, endID, merge.relType, merge.keyProps, func(prop relationshipMergeKeyProp) (interface{}, bool) {
		if prop.literalSet {
			return prop.literal, true
		}
		value, ok := row[prop.rowField]
		return value, ok
	}); ok {
		return key
	}
	return relationshipBatchEdgeKey(startID, endID, merge.relType, buildPropsFromSpec(row, merge.rowFieldRefs, merge.literals))
}

func relationshipBatchEdgeKey(startID storage.NodeID, endID storage.NodeID, relType string, mergeProps map[string]interface{}) string {
	normalized := make(map[string]interface{}, len(mergeProps))
	for key, value := range mergeProps {
		normalized[key] = normalizeRelationshipMergeIdentityValue(value)
	}
	return string(startID) + "\x00" + string(endID) + "\x00" + relType + "\x00" + unwindMergeKey("", normalized)
}

func relationshipBatchEdgeKeyFromProperties(startID storage.NodeID, endID storage.NodeID, merge relationshipMergeSpec, edgeProps map[string]interface{}) (string, bool) {
	if key, ok := relationshipBatchScalarEdgeKey(startID, endID, merge.relType, merge.keyProps, func(prop relationshipMergeKeyProp) (interface{}, bool) {
		value, ok := edgeProps[prop.propName]
		return value, ok
	}); ok {
		return key, true
	}

	keyProps := make(map[string]interface{}, len(merge.keyProps))
	for _, prop := range merge.keyProps {
		value, ok := edgeProps[prop.propName]
		if !ok {
			return "", false
		}
		keyProps[prop.propName] = value
	}
	return relationshipBatchEdgeKey(startID, endID, merge.relType, keyProps), true
}

func relationshipBatchScalarEdgeKey(
	startID storage.NodeID,
	endID storage.NodeID,
	relType string,
	keyProps []relationshipMergeKeyProp,
	valueFor func(relationshipMergeKeyProp) (interface{}, bool),
) (string, bool) {
	if len(keyProps) == 0 {
		return "", false
	}
	var b strings.Builder
	b.Grow(len(startID) + len(endID) + len(relType) + len(keyProps)*32)
	b.WriteString(string(startID))
	b.WriteByte('\x00')
	b.WriteString(string(endID))
	b.WriteByte('\x00')
	b.WriteString(relType)
	b.WriteByte('\x00')
	for _, prop := range keyProps {
		value, ok := valueFor(prop)
		if !ok {
			return "", false
		}
		value = normalizeRelationshipMergeIdentityValue(value)
		b.WriteString(strconv.Itoa(len(prop.propName)))
		b.WriteByte(':')
		b.WriteString(prop.propName)
		b.WriteByte('=')
		if !appendRelationshipBatchScalarKeyValue(&b, value) {
			return "", false
		}
		b.WriteByte(';')
	}
	return b.String(), true
}

func appendRelationshipBatchScalarKeyValue(b *strings.Builder, value interface{}) bool {
	switch v := value.(type) {
	case nil:
		b.WriteString("nil")
	case string:
		b.WriteString("string:")
		b.WriteString(strconv.Itoa(len(v)))
		b.WriteByte(':')
		b.WriteString(v)
	case bool:
		b.WriteString("bool:")
		b.WriteString(strconv.FormatBool(v))
	case int:
		b.WriteString("int:")
		b.WriteString(strconv.FormatInt(int64(v), 10))
	case int8:
		b.WriteString("int8:")
		b.WriteString(strconv.FormatInt(int64(v), 10))
	case int16:
		b.WriteString("int16:")
		b.WriteString(strconv.FormatInt(int64(v), 10))
	case int32:
		b.WriteString("int32:")
		b.WriteString(strconv.FormatInt(int64(v), 10))
	case int64:
		b.WriteString("int64:")
		b.WriteString(strconv.FormatInt(v, 10))
	case uint:
		b.WriteString("uint:")
		b.WriteString(strconv.FormatUint(uint64(v), 10))
	case uint8:
		b.WriteString("uint8:")
		b.WriteString(strconv.FormatUint(uint64(v), 10))
	case uint16:
		b.WriteString("uint16:")
		b.WriteString(strconv.FormatUint(uint64(v), 10))
	case uint32:
		b.WriteString("uint32:")
		b.WriteString(strconv.FormatUint(uint64(v), 10))
	case uint64:
		b.WriteString("uint64:")
		b.WriteString(strconv.FormatUint(v, 10))
	case float32:
		b.WriteString("float32:")
		b.WriteString(strconv.FormatFloat(float64(v), 'g', -1, 32))
	case float64:
		if math.IsNaN(v) {
			b.WriteString("float64:NaN")
			return true
		}
		b.WriteString("float64:")
		b.WriteString(strconv.FormatFloat(v, 'g', -1, 64))
	default:
		return false
	}
	return true
}

func findMatchingParenAt(s string, openIdx int) int {
	return findMatchingDelimiter(s, openIdx, '(', ')')
}

package cypher

import (
	"context"
	"errors"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// callKpSuppress hides (suppressed) or shows a node or
// relationship on demand: kp.suppress(entity) /
// kp.unsuppress(entity) (#1064). A hidden entity is left out of
// MATCH, traversal and search, its data kept, and visible under reveal(),
// whether or not decay is enabled. Inside an explicit transaction the change
// is applied when the transaction commits, and not at all if it rolls back.
func (e *StorageExecutor) callKpSuppress(ctx context.Context, procedure string, args []interface{}, suppressed bool) (*ExecuteResult, error) {
	var entity interface{}
	if len(args) > 0 {
		entity = args[0]
	}
	var apply func(storage.ManualSuppressionEngine) error
	switch value := entity.(type) {
	case *storage.Node:
		id := value.ID
		apply = func(engine storage.ManualSuppressionEngine) error {
			if err := engine.SetNodeManuallySuppressed(id, suppressed); err != nil {
				return err
			}
			// Search drops a hidden node now rather than when a search can't
			// load it, which also clears its cached results, and indexes a
			// node shown again here too: the storage update event doesn't
			// reach search while the server's GraphQL handler holds it.
			// Storage hides a suppressed node, so the refresh removes it.
			if svc := e.search(); svc != nil {
				_ = svc.RefreshNode(id)
			}
			return nil
		}
	case *storage.Edge:
		id := value.ID
		apply = func(engine storage.ManualSuppressionEngine) error {
			if err := engine.SetEdgeManuallySuppressed(id, suppressed); err != nil {
				return err
			}
			// As for a node: a hidden relationship leaves search now, so its
			// vector doesn't take a top-k place, and a shown one returns.
			if svc := e.search(); svc != nil {
				_ = svc.RefreshEdge(id)
			}
			return nil
		}
	default:
		return nil, localizedError(localization.CypherKnowledgePolicyVisibilityEntityRequired(procedure), nil)
	}
	engine := manualSuppressionEngine(e.storage)
	if engine == nil {
		return nil, localizedError(localization.CypherKnowledgePolicyVisibilityUnsupported(procedure), nil)
	}
	run := func() error {
		if err := apply(engine); errors.Is(err, storage.ErrNotImplemented) {
			return localizedError(localization.CypherKnowledgePolicyVisibilityUnsupported(procedure), err)
		} else if err != nil {
			return err
		}
		e.InvalidateCommittedWriteCaches()
		return nil
	}
	if e.txContext != nil && e.txContext.active && e.txContext.storageWrapper != nil {
		// An entity the transaction deleted is gone by then; nothing to do.
		e.txContext.storageWrapper.schemaCommitActions = append(e.txContext.storageWrapper.schemaCommitActions, func() { _ = run() })
	} else if err := run(); err != nil {
		return nil, err
	}
	return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
}

// manualSuppressionEngine is the outermost engine under engine that
// suppresses on demand, past a transaction's wrapper: the namespaced engine,
// which maps the entity's ID to the stored one.
func manualSuppressionEngine(engine storage.Engine) storage.ManualSuppressionEngine {
	visited := map[storage.Engine]bool{}
	for engine != nil && !visited[engine] {
		visited[engine] = true
		if _, transactional := engine.(*transactionStorageWrapper); !transactional {
			if suppressor, ok := engine.(storage.ManualSuppressionEngine); ok {
				return suppressor
			}
		}
		unwrapper, ok := engine.(storage.EngineUnwrapper)
		if !ok {
			return nil
		}
		engine = unwrapper.GetInnerEngine()
	}
	return nil
}

