// Execute parses and executes a Cypher query with optional parameters.
//
// This is the main entry point for Cypher query execution. The method handles
// the complete query lifecycle: parsing, validation, parameter substitution,
// execution planning, and result formatting.
//
// Parameters:
//   - ctx: Context for cancellation and timeouts
//   - cypher: Cypher query string
//   - params: Optional parameters for $param substitution
//
// Returns:
//   - ExecuteResult with columns and rows
//   - Error if query parsing or execution fails
//
// Example:
//
//	// Simple query without parameters
//	result, err := executor.Execute(ctx, "MATCH (n:Person) RETURN n.name", nil)
//	if err != nil {
//		log.Fatal(err)
//	}
//
//	// Parameterized query
//	params := map[string]interface{}{
//		"name": "Alice",
//		"minAge": 25,
//	}
//	result, err = executor.Execute(ctx, `
//		MATCH (n:Person {name: $name})
//		WHERE n.age >= $minAge
//		RETURN n.name, n.age
//	`, params)
//
//	// Process results
//	// emit "Columns: %v" via the configured logger
//	for _, row := range result.Rows {
//		// process row (e.g. emit "Row: %v" via the configured logger)
//	}
//
// Supported Query Types:
//
//	Core Clauses:
//	- MATCH: Pattern matching and traversal
//	- OPTIONAL MATCH: Left outer joins (returns nulls for no matches)
//	- CREATE: Node and relationship creation
//	- MERGE: Upsert operations with ON CREATE SET / ON MATCH SET
//	- DELETE / DETACH DELETE: Node and relationship deletion
//	- SET: Property updates
//	- REMOVE: Property and label removal
//
//	Projection & Chaining:
//	- RETURN: Result projection with expressions, aliases, aggregations
//	- WITH: Query chaining and intermediate aggregation
//	- UNWIND: List expansion into rows
//
//	Filtering & Ordering:
//	- WHERE: Filtering conditions (=, <>, <, >, <=, >=, IS NULL, IS NOT NULL, IN, CONTAINS, STARTS WITH, ENDS WITH, AND, OR, NOT)
//	- ORDER BY: Result sorting (ASC/DESC)
//	- SKIP / LIMIT: Pagination
//
//	Aggregation Functions:
//	- COUNT, SUM, AVG, MIN, MAX, COLLECT
//
//	Procedures & Functions:
//	- CALL: Procedure invocation (db.labels, db.propertyKeys, db.index.vector.*, etc.)
//	- CALL {}: Subquery execution with UNION support
//
//	Advanced:
//	- UNION / UNION ALL: Query composition
//	- FOREACH: Iterative updates
//	- LOAD CSV: Data import
//	- EXPLAIN / PROFILE: Query analysis
//	- SHOW: Schema introspection
//
//	Path Functions:
//	- shortestPath / allShortestPaths
//
// Error Handling:
//
//	Returns detailed error messages for syntax errors, type mismatches,
//	and execution failures with Neo4j-compatible error codes.
func (e *StorageExecutor) Execute(ctx context.Context, cypher string, params map[string]interface{}) (result *ExecuteResult, retErr error) {
	return e.execute(ctx, cypher, params, nil, true)
}

// executeRouted continues the same semantic statement through a transparent
// dispatcher. Public Execute, including independent reentrant calls made by
// consumers, always starts a fresh outcome instead.
func (e *StorageExecutor) executeRouted(ctx context.Context, cypher string, params map[string]interface{}) (*ExecuteResult, error) {
	var outcome *statementOutcome
	if statement, ok := ctx.Value(queryEmbeddingStatementKey{}).(*statementExecutionContext); ok {
		outcome = statement.outcome
	}
	return e.execute(ctx, cypher, params, outcome, false)
}

func (e *StorageExecutor) execute(ctx context.Context, cypher string, params map[string]interface{}, outcome *statementOutcome, clientText bool) (result *ExecuteResult, retErr error) {
	// The statement's context (deadlineCtx, once the database's query limits
	// apply) ends at the first of its deadlines, and its cause names that
	// deadline's owner: a Bolt client's tx_timeout, the server's statement
	// timeout, the database's query time limit. A deadline error the
	// statement returns is that owner's transaction timeout (#1339); a
	// deadline no owner installed (a caller's own budget, a dependency's
	// timeout) keeps its error as it is.
	deadlineCtx := ctx
	defer func() {
		if retErr != nil {
			retErr = nornicerrors.MarkStatementTimeout(retErr, context.Cause(deadlineCtx))
		}
	}()
	// Every rejection of the caller's statement fails its explicit transaction,
	// including errors before parsing, routing or the system statement policy.
	if e.txContext != nil && e.txContext.active && ctx.Value(ctxKeyTxStorage) == nil {
		defer func() { e.failTransaction(ctx, retErr) }()
	}
	defer func() {
		if result != nil && retErr == nil && result.MapKeyOrders == nil {
			if orders := snapshotMapKeyOrders(ctx); len(orders) > 0 {
				result.MapKeyOrders = orders
			}
		}
	}()
	// A result stream the caller passed is for this statement only, not for
	// the statements it runs on its behalf (#939).
	stream, ctx := takeResultStream(ctx)
	e.resetHotPathTrace()
	// A result served from the result cache that returns no node or
	// relationship has no access to record (resultHasMaterializedEntities).
	recordAccess := true
	defer func() {
		if recordAccess && retErr == nil && result != nil {
			e.recordMaterializedResultAccess(result)
		}
	}()

	// TRC-15: top-level cypher execute span. Started before timing so the
	// span duration matches the metric observation window exactly. The span
	// is ended in the same defer that emits the slow-query log.
	ctx, execSpan := e.startExecuteSpan(ctx, "", cypher)

	// TRC-17: propagate span context to the storage layer so storage spans
	// nest as children of the cypher execute span.
	if te, ok := e.storage.(*storage.TracedEngine); ok {
		te.SetContext(ctx)
	}

	// D-04c slow-query log timing. Captured at the top so the threshold check
	// covers every Execute return path (early-out, fabric, normal). Pre-bind
	// the original query text — by the time the deferred emission fires,
	// `cypher` has been normalized; we want to log what the client submitted.
	slowStart := time.Now()
	elapsed := e.executionElapsed
	if elapsed == nil {
		elapsed = time.Since
	}
	statement := e.newStatementExecutionContext(ctx, slowStart.UTC(), outcome)
	embeddingState := statement.state
	var embeddingGeneration uint64
	if embeddingState != nil {
		embeddingGeneration = embeddingState.generation
	}
	ctx = statement
	// Logging is part of the statement's deadline. Release registry and query
	// limit contexts after its deferred emission, so normal completion does
	// not look like cancellation to the redactor.
	originalCypher := cypher
	collectionGeneration := e.queryStatistics.start(originalCypher, slowStart)
	var executionDuration time.Duration
	var running runningStatement
	var queryLimitCancel context.CancelFunc
	defer func() {
		statementErr := ctx.Err()
		if retErr == nil && running.tx != nil && !running.autoCommit && e.txContext != nil && e.txContext.active {
			if tracker := running.tx.memory.Load(); tracker != nil {
				if storageTx, ok := e.txContext.tx.(*storage.BadgerTransaction); ok {
					if err := tracker.settleStaged(storageTx.StagedMemoryBytes()); err != nil {
						result, retErr = nil, err
					}
				}
			}
		}
		if err := running.memoryFailure(); err != nil && !statement.outcome.committed.Load() {
			if statementErr != nil && (statementErr == context.Canceled || statementErr == context.DeadlineExceeded) {
				result, retErr = nil, statementErr
			} else {
				result, retErr = nil, err
			}
		} else if retErr == nil && result != nil && running.memory != nil && !statement.outcome.committed.Load() {
			// A nested execution hands its retained rows to its parent scope.
			if err := running.memory.handOver(running.memoryMark, result.Rows); err != nil {
				result, retErr = nil, err
			}
			running.memory = nil
		}
		terminated := running.done()
		if !statement.outcome.committed.Load() {
			if terminated {
				result, retErr = nil, transactionTerminatedError()
			} else if retErr == nil && statementErr != nil {
				result, retErr = nil, statementErr
			}
		}
		e.queryStatistics.record(collectionGeneration, originalCypher, slowStart, executionDuration, retErr == nil)
		e.observeSlowQueryIfThresholded(executionDuration)
		recordSpanError(execSpan, retErr)
		execSpan.End()
		if queryLimitCancel != nil {
			queryLimitCancel()
		}
	}()
	defer func() {
		executionDuration = elapsed(slowStart)
		dur := executionDuration
		e.emitRejectionReport(ctx, originalCypher, retErr)
		// Plan is unavailable for non-EXPLAIN/PROFILE queries; pass nil and
		// rely on PlanHash's zero-placeholder behavior. Phase 6 (TRC-04) will
		// thread the planned tree here once cypher EXPLAIN refactoring is in.
		e.emitSlowQueryLog(ctx, originalCypher, nil, dur)

	}()
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	// Normalize query: trim BOM (some clients send it) then whitespace
	cypher = trimBOM(cypher)
	cypher = normalizeCypherSyntaxConfusables(cypher)
	// The statement as the client sent it may not call NornicDB's internal
	// functions; the rewrites below produce them (#1105).
	// Transparent routing continues already-admitted text, including generated
	// functions. A public reentrant call still admits its own client text.
	if clientText {
		if err := internalFunctionCallError(cypher); err != nil {
			return nil, err
		}
	}
	// Comments and keyword spacing are canonical from here on; what the
	// client sees (column names, messages, plans) is the text it sent (#740).
	// NORNICDB_CYPHER_QUERY_NORMALIZATION=false skips the pass: the
	// statement runs as sent.
	canonical, rewrite := cypher, (*queryRewrite)(nil)
	if config.IsCypherQueryNormalizationEnabled() {
		var err error
		canonical, rewrite, err = normalizeQueryText(ctx, cypher)
		if err != nil {
			return nil, err
		}
	}
	if rewrite != nil {
		cypher = canonical
		defer func() { result, retErr = rewrite.restore(result, retErr) }()
	}
	// Digit-grouping underscores (1_000) go here, on every route; columns
	// and messages keep the client's text (#907).
	if grouped, numericRewrite := canonicalizeNumericLiterals(cypher); numericRewrite != nil {
		cypher = grouped
		defer func() { result, retErr = numericRewrite.restore(result, retErr) }()
	}
	// GQL function aliases (collect_list, ln, …) call the function they
	// name; columns and messages keep the client's text.
	if !rewriteFree(rewriteFreeFunctionAliases, false, cypher) {
		if aliased, aliasRewrite := canonicalizeFunctionAliases(cypher); aliasRewrite != nil {
			cypher = aliased
			defer func() { result, retErr = aliasRewrite.restore(result, retErr) }()
		} else {
			markRewriteFree(rewriteFreeFunctionAliases, false, cypher)
		}
	}
	cypher = strings.TrimSpace(cypher)
	cypher = trimTrailingStatementDelimiters(cypher)
	ctx = withCypherVersion(ctx, cypher)
	if err := validateCypherPreamble(cypher); err != nil {
		return nil, err
	}
	if config.IsANTLRParser() {
		body, _ := stripCypherPreamble(cypher)
		// PROFILE re-enters this path after the header has been consumed.
		// The version owner already transported the admitted language in ctx.
		if cypherVersionFromContext(ctx) != "25" && usesSharedGrammarClauses(ctx, body) {
			return nil, sharedClauseSyntaxError("LET, FILTER and FOR require CYPHER 25 with the ANTLR parser")
		}
	}
	// Neo4j 5 statement framing: leading CYPHER [version] [option=value …]
	// groups run the statement they precede, and a trailing FINISH (on every
	// UNION branch) runs it and returns no rows.
	cypher, _ = stripCypherPreamble(cypher)
	cypher = strings.TrimSpace(cypher)
	// Cypher 25 expression forms (RETURN ALL, s"…{x}…", map comprehensions)
	// become the expressions they stand for, once, here (#907).
	cypher25 := cypherVersionFromContext(ctx) == "25"
	// In Cypher 25 a '$' after a name starts a parameter (L$props is
	// L $props); Cypher 5 reads a$b as one name.
	if cypher25 {
		if separated, separateRewrite := separateCypher25Parameters(cypher); separateRewrite != nil {
			cypher = separated
			defer func() { result, retErr = separateRewrite.restore(result, retErr) }()
		}
	}
	if !rewriteFree(rewriteFreeCypher25Expressions, cypher25, cypher) {
		expanded, expressionRewrites, err := desugarCypher25Expressions(cypher, cypher25)
		if err != nil {
			return nil, err
		}
		if len(expressionRewrites) > 0 {
			cypher = expanded
			// One defer, not one per pass: a defer in a loop would make every
			// statement pay for heap-allocated defers. Restored last pass first.
			defer func() {
				for index := len(expressionRewrites) - 1; index >= 0; index-- {
					result, retErr = expressionRewrites[index].restore(withoutGeneratedColumns(result), retErr)
				}
			}()
		} else {
			markRewriteFree(rewriteFreeCypher25Expressions, cypher25, cypher)
		}
	}
	// Cypher 25 composition (NEXT, WHEN, braced query parts) becomes the
	// CALL subqueries and UNIONs it stands for, once, here; columns and
	// errors are mapped back (#907).
	if !rewriteFree(rewriteFreeQueryStructure, false, cypher) {
		if composed, structureRewrite, err := desugarQueryStructure(ctx, cypher, e); err != nil {
			return nil, err
		} else if structureRewrite != nil {
			cypher = composed
			defer func() { result, retErr = structureRewrite.restore(withoutGeneratedColumns(result), retErr) }()
		} else if !mayUseQueryStructure(cypher) {
			// Only the quick check's verdict is the text's alone.
			markRewriteFree(rewriteFreeQueryStructure, false, cypher)
		}
	}
	if err := e.validateStatementFraming(ctx, cypher); err != nil {
		return nil, err
	}
	finishTerminated := false
	if stripped, ok := stripUnionBranchFinishes(ctx, cypher); ok {
		cypher = strings.TrimSpace(stripped)
		finishTerminated = true
		ctx = withFinishedStatement(ctx, cypher)
	}
	if cypher == "" {
		if finishTerminated {
			return &ExecuteResult{}, nil
		}
		return nil, localizedError(localization.CypherCoreEmptyQuery(), nil)
	}
	// Knowledge-policy DDL that cannot be parsed (a missing profile or policy
	// name, a missing OPTIONS block) is a syntax error on every route, the
	// auto-commit and HTTP routes included (#514).
	if isKnowledgePolicyDDLStatement(cypher) {
		if _, _, err := ParseKnowledgePolicyDDL(cypher); err != nil {
			return nil, &classifiedCypherError{
				cause:  err,
				code:   "Neo.ClientError.Statement.SyntaxError",
				detail: "UnexpectedSyntax",
			}
		}
	}
	if finishTerminated {
		defer func() {
			completeFinishedResult(result)
		}()
	}

	// Typed Go maps and slices become Cypher maps and lists here, once, for
	// every route (#712).
	params = normalizeQueryParameters(params)

	// Handle Neo4j shell/browser commands like :USE and :param before validation.
	useBefore := GetUseDatabaseFromContext(ctx)
	processedQuery, processedCtx, shellResult, err := e.preprocessShellCommands(ctx, cypher, params)
	if err != nil {
		return nil, err
	}
	ctx = processedCtx
	cypher = processedQuery
	if cypher == "" {
		return shellResult, nil
	}
	if err := clientTransactionCommand(ctx, cypher); err != nil {
		return nil, err
	}
	// Only BEGIN can start a script; avoid its allocating classifier for
	// ordinary statements while admitting them through the same owner.
	if bareTransactionCommand(cypher) == "" && (!startsWithKeywordFold(cypher, "BEGIN") || !transactionScriptShape(cypher)) {
		// Neo4j parses a statement before it checks it against its
		// transaction, so a rejected USE clause (USE before an
		// administration command among them) is the SyntaxError in an
		// explicit transaction too.
		if startsWithKeywordFold(cypher, "USE") {
			if _, _, _, err := parseUseClause(cypher, false); err != nil {
				return nil, err
			}
		}
		if err := e.admitTransactionStatement(ctx, cypher); err != nil {
			return nil, err
		}
		routed, err := e.routeAdministrationStatement(ctx, cypher)
		if err != nil {
			return nil, err
		}
		if routed != e {
			return routed.executeRouted(ctx, cypher, params)
		}
	}
	// A cached per-database executor is shared by every auto-commit client of
	// its database. A bare transaction command must not open a transaction on
	// it: any later statement (or one-statement script) would then run inside
	// another caller's transaction, and COMMIT/ROLLBACK would end writes the
	// caller never issued. Neo4j clients cannot send Cypher transaction
	// statements either; embedded callers that want explicit transactions
	// create their own session executor.
	if e.sharedExecutor && (e.txContext == nil || !e.txContext.active) {
		if word := bareTransactionCommand(cypher); word != "" {
			message := localization.CypherTransactionsCommandNotStatement(word)
			return nil, localizedError(message, newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", message.Fallback))
		}
	}
	// A query after :USE <db> runs on that database, like one after a USE
	// clause (#738).
	if useDB := GetUseDatabaseFromContext(ctx); useDB != "" && useDB != useBefore {
		return e.executeOnDatabase(ctx, useDB, cypher, params, false)
	}

	// The quoted-variable and label-expression rewrites map the finished
	// result's rows back, so a statement with either doesn't stream.
	rowsRewritten := false
	// Backtick-quoted variables become plain identifiers here, once, for
	// every route; the result's columns and errors are mapped back (#734).
	if canonical, names := canonicalizeQuotedVariables(ctx, cypher); names != nil {
		cypher = canonical
		params = names.parameterValues(params)
		ctx = withQuotedVariableNames(ctx, names)
		rowsRewritten = true
		defer func() {
			result, retErr = names.restore(result, retErr, func(text string) []returnItem { return e.parseReturnItems(ctx, text) })
		}()
	}

	// ORDER BY, SKIP / OFFSET and LIMIT as clauses of their own become the
	// WITH * they stand for, once, here; errors are mapped back (#907).
	if desugared, orderRewrite := desugarStandaloneOrderClauses(cypher); orderRewrite != nil {
		cypher = desugared
		defer func() { result, retErr = orderRewrite.restore(result, retErr) }()
	}

	// Route multi-graph CALL { USE ... } queries through the Fabric planner/executor
	// so subquery decomposition and cross-graph routing use a single deterministic path.
	if e.shouldUseFabricPlanner(cypher) {
		mergedParams := e.mergeShellParams(ctx, mergeInheritedQueryParams(ctx, params))
		ctx = withQueryParams(ctx, mergedParams)
		mode, modeQuery := parseExecutionMode(cypher)
		if finishTerminated {
			ctx = withFinishedStatement(ctx, modeQuery)
		}
		if mode != ModeNormal {
			if err := e.validateSyntax(ctx, modeQuery, cypherVersionFromContext(ctx) == "25"); err != nil {
				return nil, err
			}
			if err := e.validateSemanticScopes(ctx, fabricSingleGraphStatement(ctx, modeQuery)); err != nil {
				return nil, err
			}
			if err := e.statementParametersError(ctx, cypher, params); err != nil {
				return nil, err
			}
			if mode == ModeExplain {
				return e.executeExplain(ctx, modeQuery)
			}
			return e.executeProfile(ctx, modeQuery)
		}
		info := e.analyzer.Analyze(ctx, cypher)
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		// Plan 04-03 Site 3 (fabric branch): isFabric=true → op_type="fabric"
		// per RISK-1 corrected classifier. Observation pre-execute so the
		// counter reflects intent regardless of execution outcome (errors
		// still bucket by intended op_type, matching how queries_total works
		// in the reference catalogs).
		e.observeQuery(classifyOpType(info, true /* isFabric */, false), true, slowStart)
		execSpan.SetAttributes(attribute.String("cypher.op_type", "fabric"))
		inExplicitTx := e.txContext != nil && e.txContext.active
		// As on one database, and as Neo4j compiles a statement, its
		// variable scopes are checked before it plans, enlists a participant
		// or runs any part: a CALL scope clause naming a variable the query
		// doesn't define is rejected here. A missing parameter is reported
		// after both, so these syntax errors come first.
		if err := e.validateSemanticScopes(ctx, fabricSingleGraphStatement(ctx, cypher)); err != nil {
			return nil, err
		}
		preparedFabric, err := e.prepareFabricExecution(ctx, cypher)
		if err != nil {
			return nil, err
		}
		if err := e.statementParametersError(ctx, cypher, params); err != nil {
			return nil, err
		}
		ctx = context.WithValue(ctx, fabricPreparedExecKey{}, preparedFabric)
		allowResultCache := !preparedFabric.hasRemote
		fabricResultCacheKey := ""

		// Mirror normal query-cache policy for Fabric reads (autocommit only).
		// A cached result is served only to a caller the statement is
		// authorized for (fabricResultCacheKey).
		if allowResultCache && e.canUseResultCache(ctx, info, cypher) {
			if key, cacheable := e.fabricResultCacheKey(ctx, preparedFabric, cypher, mergedParams); cacheable {
				fabricResultCacheKey = key
				if cached, _, _, found := e.cache.getWithTraceForEmbedding(fabricResultCacheKey, embeddingGeneration); found {
					return cached, nil
				}
			}
		}

		var result *ExecuteResult
		var execErr error
		// When an explicit transaction is active on a composite route, execute through
		// the same FabricTransaction so many-read/one-write constraints are enforced
		// across all statements in the session.
		if inExplicitTx {
			if ftx, ok := e.txContext.tx.(*fabric.FabricTransaction); ok {
				result, execErr = e.executeViaFabricWithTx(ctx, cypher, mergedParams, ftx, false, preparedFabric)
			} else {
				result, execErr = e.executeViaFabricWithTx(ctx, cypher, mergedParams, nil, true)
			}
		} else {
			result, execErr = e.executeViaFabricWithTx(ctx, cypher, mergedParams, nil, true)
		}
		if execErr != nil {
			return nil, execErr
		}

		if fabricResultCacheKey != "" {
			e.cache.putWithLabelsAndTraceForEmbedding(fabricResultCacheKey, result, e.queryCacheTTL, extractLabelsFromQuery(cypher), HotPathTrace{}, embeddingGeneration)
		}

		e.invalidateResultCacheForQuery(info)

		return result, nil
	}

	// EXPLAIN / PROFILE USE <graph> …: the graph is resolved as for the
	// statement itself (Neo4j's DatabaseNotFound for a missing one, #744),
	// and the plan is the target database's.
	if mode, inner := parseExecutionMode(cypher); mode != ModeNormal {
		if use, remaining, hasUse, err := parseUseClause(inner, false); hasUse || err != nil {
			if err != nil {
				return nil, err
			}
			if err := e.dynamicUseError(use); err != nil {
				return nil, err
			}
			keyword := "EXPLAIN "
			if mode == ModeProfile {
				keyword = "PROFILE "
			}
			return e.executeOnDatabase(ctx, use.Name, keyword+remaining, params, false)
		}
	}
	// Handle leading Cypher USE clause (openCypher multi-graph syntax).
	if use, remaining, hasUse, err := parseUseClause(cypher, false); hasUse || err != nil {
		if err != nil {
			return nil, err
		}
		if err := e.dynamicUseError(use); err != nil {
			return nil, err
		}
		return e.executeOnDatabase(ctx, use.Name, remaining, params, false)
	}
	// Label expressions in patterns become the label forms and WHERE
	// predicates the local evaluator reads. Route source Cypher first: remote
	// evaluators do not implement our internal functions. The result's columns and
	// errors are mapped back (#860).
	desugared, labelRewrite, err := desugarLabelExpressions(ctx, cypher, params, cypherVersionFromContext(ctx) == "25")
	if err != nil {
		return nil, err
	}
	if labelRewrite != nil {
		rowsRewritten = true
		cypher = desugared
		defer func() { result, retErr = labelRewrite.restore(withoutGeneratedColumns(result), retErr) }()
	}
	if err := e.authorizeSelectedDatabase(ctx, "", cypher); err != nil {
		return nil, err
	}
	e.statementAdmitted(ctx)
	if err := e.systemDatabaseWriteError(ctx, cypher); err != nil {
		return nil, err
	}

	// Reject data queries on composite root — callers must USE a constituent.
	// System/admin commands (SHOW DATABASES, CREATE/DROP DATABASE, ALTER, SHOW COMPOSITE,
	// SHOW CONSTITUENTS, SHOW ALIASES, SHOW LIMITS, BEGIN, COMMIT, ROLLBACK) are allowed,
	// and so is a statement that reads or writes no graph (RETURN 1,
	// UNWIND graph.names() AS g RETURN g), which runs on the composite
	// itself, as in Neo4j.
	if isCompositeRoot(e.storage) && !isCompositeAllowedCommand(cypher) && statementAccessesGraphText(cypher) {
		return nil, localizedError(localization.CypherCoreCompositeTargetRequired(), nil)
	}

	// Merge session-scoped shell parameters with per-call parameters.
	// Explicit params win over shell params to preserve HTTP/Bolt semantics.
	params = mergeInheritedQueryParams(ctx, params)
	params = e.mergeShellParams(ctx, params)

	// Check for transaction control statements and transaction scripts FIRST.
	// These are Nornic extensions and must bypass strict ANTLR validation.
	// A one-statement script opens and closes its own transaction; it runs on
	// a private executor so a client statement can never leave the shared
	// per-database executor inside a transaction — concurrent auto-commit
	// statements would otherwise observe and collide with the script's
	// transaction state (acknowledged-write loss, mid-run panics). An
	// embedded caller that already owns an active transaction keeps running
	// the script on itself, where handleBegin fails as before.
	if transactionScriptShape(cypher) {
		if e.txContext != nil && e.txContext.active {
			if result, err := e.executeTransactionScript(ctx, cypher); result != nil || err != nil {
				return result, err
			}
		} else {
			scriptExec := e.cloneForStorage(e.storage)
			scriptExec.txContext = nil
			if result, err := scriptExec.executeTransactionScript(ctx, cypher); result != nil || err != nil {
				return result, err
			}
		}
	} else if result, err := e.executeTransactionScript(ctx, cypher); result != nil || err != nil {
		return result, err
	}
	if result, err := e.parseTransactionStatement(ctx, cypher); result != nil || err != nil {
		if err == nil && e.txContext != nil && e.txContext.active {
			e.txContext.coordinatorOwned = e.txContext.coordinatorOwned || storage.CoordinatorOwnsTransaction(ctx)
			// BEGIN: the client's transaction metadata (WithTransactionMetadata).
			if tx, ok := e.txContext.tx.(*storage.BadgerTransaction); ok {
				if metadataErr := applyTransactionMetadata(ctx, tx); metadataErr != nil {
					_, _ = e.handleRollback()
					return nil, metadataErr
				}
			}
		}
		if err == nil && e.txContext != nil && e.txContext.active && e.txContext.running == nil {
			e.txContext.running = runningTransactions.begin(ctx, e.currentDatabaseName())
		}
		return result, err
	}
	// A statement that fails in an explicit transaction marks it failed, as in
	// Neo4j (#683): later statements are refused, COMMIT rolls it back and
	// ROLLBACK discards everything it wrote. Only the caller's own statement
	// counts: executions nested inside a statement (they carry the
	// transaction's storage wrapper) handle their own errors.
	if tx := e.txContext; tx != nil && tx.active && ctx.Value(ctxKeyTxStorage) == nil {
		if tx.failed != nil {
			return nil, queryOnFailedTransactionError(tx.failed)
		}
	}
	// SHOW TRANSACTIONS lists the statement while it runs; TERMINATE
	// TRANSACTIONS cancels it (#718). A statement of an explicit
	// transaction is registered here, so a terminated transaction refuses
	// it before anything else; an auto-commit statement after the result
	// cache, since a statement served from the cache runs nothing that
	// could be listed or terminated.
	// A statement whose transaction TERMINATE TRANSACTIONS terminated while
	// it ran fails with Neo4j's Neo.ClientError.Transaction.Terminated,
	// whichever layer noticed the cancellation (a storage call, the
	// checked write path, the row loop) and whether it read or wrote;
	// only an auto-commit statement that had already committed keeps its
	// result (#751).
	registerStatement := func() error {
		statementCtx, statement, err := e.withRunningStatement(ctx, originalCypher)
		if err != nil {
			return err
		}
		running, ctx = statement, statementCtx
		return nil
	}
	if e.txContext != nil && e.txContext.active {
		if runErr := registerStatement(); runErr != nil {
			_, _ = e.handleRollback()
			return nil, runErr
		}
	}

	// Validate basic syntax
	if err := e.validateSyntax(ctx, cypher, cypherVersionFromContext(ctx) == "25"); err != nil {
		// Plan 04-03 Site 2 (parse-error chokepoint): emit op_type="parse_error"
		// per D-04b sixth enum value. No duration observation — parse cost is
		// sub-microsecond and not meaningful to bucket. The queries_total
		// counter still increments so the SRE can alert on parse-error rate.
		e.observeQuery("parse_error", false /* observeDuration */, slowStart)
		execSpan.SetAttributes(attribute.String("cypher.op_type", "parse_error"))
		return nil, err
	}
	// A statement whose last clause is a reading clause (UNWIND, MATCH,
	// OPTIONAL MATCH, WITH) has nothing after it — Neo4j rejects it. This is
	// a whole-statement rule that runs after syntax validation, so malformed
	// text keeps the parser's own syntax error; fabric fragments legitimately
	// end in UNWIND when the surrounding statement continues in another
	// fragment, and a FINISH terminator is itself the clause that follows, so
	// both are exempt.
	if !finishTerminated {
		last := lastTopLevelClauseWord(cypher)
		// `WITH EMBEDDING` is a NornicDB execution option, not a WITH
		// projection: a statement that ends with it is complete. Only exempt
		// it when the text before the trailer is itself a complete statement.
		if last == "WITH" {
			if scope, ok := stripWithEmbeddingSuffix(cypher); ok {
				switch lastTopLevelClauseWord(scope) {
				case "", "UNWIND", "MATCH", "OPTIONAL", "WITH", "CALL", "LET", "FILTER", "FOR":
				default:
					last = ""
				}
			}
		}
		switch last {
		case "UNWIND", "MATCH", "OPTIONAL", "WITH", "LET", "FILTER", "FOR":
			return nil, newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
				fmt.Sprintf("Invalid input: %s must be followed by a clause", last))
		}
		// A bare CALL has no procedure or subquery after it; the statement is
		// incomplete, not a lookup of a procedure named 'CALL' (#514).
		if strings.EqualFold(cypher, "CALL") {
			return nil, newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
				"Invalid input: CALL must be followed by a procedure name or subquery")
		}
	}
	// WITH EMBEDDING is an execution option, not a WITH projection: the
	// scopes are those of the statement without it. EXPLAIN and PROFILE
	// check the statement they plan, as Neo4j compiles it.
	_, scopeText := parseExecutionMode(cypher)
	scopeText, _ = stripWithEmbeddingSuffix(scopeText)
	if finishTerminated {
		scopeText += " FINISH"
	}
	if err := e.validateSemanticScopes(ctx, scopeText); err != nil {
		return nil, err
	}
	admission, admissionErr := e.admitBoundStatement(ctx, scopeText)
	if admissionErr != nil {
		return nil, admissionErr
	}
	if admission.program != nil {
		ctx = withBoundStatementProgram(ctx, admission.program)
	}
	defer func() {
		if finishTerminated {
			completeFinishedResult(result)
		}
		if retErr == nil && result != nil {
			retErr = admission.verifyColumns(result.Columns)
		}
	}()
	if err := e.statementParametersError(ctx, cypher, params); err != nil {
		return nil, err
	}

	// IMPORTANT: Do NOT substitute parameters before routing!
	// We need to route the query based on the ORIGINAL query structure,
	// not the substituted one. Otherwise, keywords inside parameter values
	// (like 'MATCH (n) SET n.x = 1' stored as content) will be incorrectly
	// detected as Cypher clauses.
	//
	// Parameter substitution happens AFTER routing, inside each handler.
	// This matches Neo4j's architecture where params are kept separate.

	// Store params in context for handlers to use
	ctx = withQueryParams(ctx, params)
	if err := e.validateBoundParameterExpressions(ctx, cypher, params); err != nil {
		return nil, err
	}

	// Check query limits if storage engine supports it
	// Uses interface{} to avoid importing multidb package (prevents circular dependencies)
	if namespacedEngine, ok := e.storage.(interface {
		GetQueryLimitChecker() interface {
			CheckQueryRate() error
			CheckQueryLimits(context.Context) (context.Context, context.CancelFunc, error)
			GetQueryLimits() interface{}
		}
	}); ok {
		if qlc := namespacedEngine.GetQueryLimitChecker(); qlc != nil {
			// Check query rate limit
			if err := qlc.CheckQueryRate(); err != nil {
				return nil, err
			}

			// Check write rate limit for write queries
			// We need to check this early, but we don't know if it's a write query yet
			// So we'll check it in the write handlers too

			// Apply query timeout and concurrent query limits
			var err error
			ctx, queryLimitCancel, err = qlc.CheckQueryLimits(ctx)
			if err != nil {
				return nil, err
			}
			deadlineCtx = ctx
		}
	}

	// TRC-15: plan span wraps the analysis/classification phase.
	_, planSpan := startPlanSpan(ctx)
	// Analyze query - uses cached analysis if available
	// This extracts query metadata (HasMatch, IsReadOnly, Labels, etc.) once
	// and caches it for repeated queries, avoiding redundant string parsing
	info := e.analyzer.Analyze(ctx, cypher)
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	ctx, finishMode, modeErr := e.observeResolvedStatementMode(ctx, cypher)
	if modeErr != nil {
		return nil, modeErr
	}
	if finishMode != nil {
		defer func() {
			if retErr == nil {
				result = finishMode(result)
			}
		}()
	}
	if err := e.admitResolvedStatementWrite(ctx, cypher); err != nil {
		return nil, err
	}

	// Plan 04-03 Sites 1 + 3 (RISK-1 corrected): classify ONCE post-Analyze.
	// isFabric=false here because the fabric branch returns at line ~963
	// before reaching this code path. isAdmin=true overrides the QueryInfo-
	// derived classification (e.g., SHOW DATABASES would otherwise classify
	// as "schema" via HasShow → IsSchemaQuery; D-04a says system/admin
	// commands bucket as "admin" instead). Single observation point covers
	// cache-hit early-return AND every downstream execution path so the
	// counter reflects intent regardless of how the query resolves.
	opType := classifyOpType(info, false /* isFabric */, isSystemCommandNoGraph(cypher))
	e.observeQuery(opType, true /* observeDuration */, slowStart)
	planSpan.SetAttributes(attribute.String("cypher.op_type", opType))
	planSpan.End()
	// Update the execute span with the resolved op_type.
	execSpan.SetAttributes(attribute.String("cypher.op_type", opType))

	// For routing, we still need upperQuery for some handlers
	// TODO: Migrate handlers to use QueryInfo directly
	upperQuery := e.cachedUpperQuery(cypher)

	// Capture the storage and search-index revisions before execution so
	// mutations performed outside this executor cannot leave a stale cached
	// result behind. The search index is updated after the graph (a node's
	// vector is indexed after its embedding is saved), so a search procedure
	// that ran in between would otherwise keep its result until the TTL
	// (#945). The key carries a language version other than the default 5:
	// the same text can mean different things in Cypher 5 and Cypher 25
	// (#907); a Cypher 5 key pays for no version text.
	resultCacheKey := ""
	if e.canUseResultCache(ctx, info, cypher) {
		resultCacheKey = resultCacheEntryKey(ctx, cypher, params)
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		if version := cypherVersionFromContext(ctx); version != "5" {
			resultCacheKey += ":cypher:" + version
		}
		if provider, ok := e.storage.(storage.GraphMutationVersionProvider); ok {
			if version, supported := provider.GraphMutationVersion(); supported {
				resultCacheKey += ":graph:" + strconv.FormatUint(version, 10)
			}
		}
		if svc := e.search(); svc != nil {
			resultCacheKey += searchCacheKey(svc)
		}
		if cached, trace, entities, found := e.cache.getWithTraceForEmbedding(resultCacheKey, embeddingGeneration); found {
			e.restoreHotPathTrace(trace)
			recordAccess = entities
			return cached, nil
		}
	}
	if running.tx == nil && running.memory == nil {
		// Registering an auto-commit statement can't fail: only a
		// terminated explicit transaction refuses a statement, and a
		// statement of one is registered above.
		_ = registerStatement()
	}

	// Prefix consumption and dispatch share one reader, including comments
	// and EOF. A classifier flag must never re-enter the unchanged statement.
	if info.HasExplain || info.HasProfile {
		mode, innerQuery := parseExecutionMode(cypher)
		if finishTerminated {
			ctx = withFinishedStatement(ctx, innerQuery)
		}
		if mode == ModeExplain {
			return e.executeExplain(ctx, innerQuery)
		}
		if mode == ModeProfile {
			return e.executeProfile(ctx, innerQuery)
		}
	}

	// If in explicit transaction, execute within it
	if e.txContext != nil && e.txContext.active {
		ctx = withExpressionFailureSlot(ctx)
		ctx = withStatementClausePlans(ctx, cypher)
		result, err := e.executeInTransaction(ctx, cypher, upperQuery)
		if failure := getExpressionFailure(ctx); failure != nil {
			return result, failure
		}
		return result, err
	}

	// System commands (CREATE/DROP DATABASE, SHOW DATABASES, etc.) must not use
	// implicit transactions: they operate on dbManager/metadata, not graph
	// storage. Routing them through executeWithoutTransaction directly ensures
	// correct handling and avoids the write path.
	if isSystemCommandNoGraph(cypher) || isOrdinarySchemaDDL(cypher) {
		result, err := e.executeWithoutTransaction(ctx, cypher, upperQuery)
		if err != nil {
			return nil, err
		}
		// This owner executes metadata/schema effects directly, with no
		// implicit transaction to publish their completed outcome.
		if !info.IsReadOnly && !e.inTransaction(ctx) {
			publishStatementCommit(ctx)
		}
		return result, nil
	}

	// An auto-commit read hands its rows to the caller's result stream as it
	// produces them (#939). The result-limit truncation and the restores of
	// rewritten rows below need the whole result, so a statement with
	// either keeps it. A streamed result is not cached.
	if stream != nil && info.IsReadOnly && !rowsRewritten && !finishTerminated && e.maxResults() == 0 {
		ctx = armResultStream(ctx, stream, cypher, func(columns []string) []string {
			restored, _ := rewrite.restore(&ExecuteResult{Columns: columns}, nil)
			return restored.Columns
		}, func(rows [][]interface{}) {
			e.recordMaterializedResultAccess(&ExecuteResult{Rows: rows})
		})
	}

	// Auto-commit single query through the implicit-transaction write path.
	ctx = withExpressionFailureSlot(ctx)
	ctx = withStatementClausePlans(ctx, cypher)
	result, err = e.executeImplicitAsync(ctx, cypher, upperQuery)
	if result != nil && err == nil {
		if orders := snapshotMapKeyOrders(ctx); len(orders) > 0 {
			result.MapKeyOrders = orders
		}
	}
	// An expression error recorded while the statement ran is its error,
	// whichever route ran it: no route's result stands in for it.
	if err == nil {
		if failure := getExpressionFailure(ctx); failure != nil {
			return nil, failure
		}
	}

	// Apply result limit if set
	if err == nil && result != nil {
		if maxResults := e.maxResults(); maxResults > 0 && int64(len(result.Rows)) > maxResults {
			result.Rows = result.Rows[:maxResults]
		}
	}

	// Retain the revision captured before execution. A read overlapping a
	// mutation must not publish its stale result under the newer revision.
	if err == nil && resultCacheKey != "" && !stream.streamed() {
		if finishMode != nil {
			result = finishMode(result)
		}
		e.cache.putWithLabelsAndTraceForEmbedding(resultCacheKey, result, e.queryCacheTTL, extractLabelsFromQuery(cypher), e.LastHotPathTrace(), embeddingGeneration)
	}

	e.invalidateCachesForQuery(info, cypher)

	return result, err
}

// maxResults is the database's result-row limit (0 for none): the result of
// a statement is cut to it.
func (e *StorageExecutor) maxResults() int64 {
	namespacedEngine, ok := e.storage.(interface {
		GetQueryLimitChecker() interface {
			CheckQueryRate() error
			CheckQueryLimits(context.Context) (context.Context, context.CancelFunc, error)
			GetQueryLimits() interface{}
		}
	})
	if !ok {
		return 0
	}
	qlc := namespacedEngine.GetQueryLimitChecker()
	if qlc == nil {
		return 0
	}
	queryLimits := qlc.GetQueryLimits()
	if queryLimits == nil {
		return 0
	}
	limits, ok := queryLimits.(interface{ GetMaxResults() int64 })
	if !ok {
		return 0
	}
	return limits.GetMaxResults()
}

// searchCacheKey is the part of a result-cache key that depends on the search
// service: its revision, and its instance, which tells a replacement service
// (a reset or restore of the database's search) from the one it replaced,
// whose revisions it would otherwise repeat.
func searchCacheKey(svc *search.Service) string {
	return ":search:" + strconv.FormatUint(svc.Instance(), 10) + ":" + strconv.FormatUint(svc.IndexRevision(), 10)
}

package cypher

import (
	"context"
	"encoding/binary"
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/orneryd/nornicdb/pkg/cypher/resultmetadata"
	"github.com/orneryd/nornicdb/pkg/fabric"
	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/multidb"
	"github.com/orneryd/nornicdb/pkg/storage"
)

type fabricPreparedExecKey struct{}

// participantSchemaForStatement is the participant schema boundary shared by
// statement metadata consumers and Fabric planning. The Fabric integration
// supplies the resolver; without it, participant-owned implicit signatures are
// deliberately unresolved before execution.
func (e *StorageExecutor) participantSchemaForStatement(ctx context.Context, query string) resultmetadata.ParticipantSchema {
	return nil
}

func (e *StorageExecutor) shouldUseFabricPlanner(cypher string) bool {
	if e.dbManager == nil {
		return false
	}
	// Engage Fabric only when a parsed USE target references a composite scope:
	//   - USE <composite>
	//   - USE <composite>.<constituent>
	// Word presence alone is insufficient (e.g., "USE" inside string payloads).
	opts := defaultKeywordScanOpts()
	searchFrom := 0
	for {
		useIdx := keywordIndexFrom(cypher, "USE", searchFrom, opts)
		if useIdx < 0 {
			break
		}
		use, _, hasUse, err := fabric.ParseUseClause(cypher[useIdx:], true)
		if hasUse && err == nil && (e.useTargetRequiresFabric(use.Name) || (use.IsDynamic() && e.sessionIsComposite())) {
			return true
		}
		searchFrom = useIdx + len("USE")
	}
	return false
}

func (e *StorageExecutor) useTargetRequiresFabric(target string) bool {
	target = strings.TrimSpace(target)
	if target == "" || e.dbManager == nil {
		return false
	}
	if e.dbManager.IsCompositeDatabase(target) {
		return true
	}
	if dot := strings.IndexByte(target, '.'); dot > 0 {
		base := strings.TrimSpace(target[:dot])
		if base != "" && e.dbManager.IsCompositeDatabase(base) {
			return true
		}
	}
	return false
}

func (e *StorageExecutor) executeViaFabricWithTx(ctx context.Context, cypher string, params map[string]interface{}, tx *fabric.FabricTransaction, autoCommit bool, preparation ...*fabricPreparedExec) (*ExecuteResult, error) {
	if tx == nil {
		tx = fabric.NewFabricTransaction(fmt.Sprintf("fab-%d", time.Now().UnixNano()))
	}
	var prepared *fabricPreparedExec
	if len(preparation) > 0 {
		prepared = preparation[0]
	} else {
		var err error
		prepared, err = e.preparedFabricFromContext(ctx)
		if err != nil {
			return nil, err
		}
		if prepared == nil {
			prepared, err = e.prepareFabricExecution(ctx, cypher)
			if err != nil {
				return nil, err
			}
		}
	}
	if prepared == nil {
		return nil, localizedError(localization.CypherCommandRoutingFabricNotPrepared(), nil)
	}
	contract, err := readStatementExecutionContract(ctx, cypher)
	if err != nil {
		return nil, err
	}
	fragment, err := e.fabricProcedureWritePlan(ctx, prepared.fragment)
	if err != nil {
		return nil, err
	}
	if hasCallInTransactions(ctx, cypher) {
		return nil, transactionalCallContextError("transactional CALL on composite targets is not supported")
	}
	catalog := prepared.catalog

	authToken := GetAuthTokenFromContext(ctx)
	localExec := fabric.NewLocalFragmentExecutor(&cypherFabricExecutor{
		base:        e,
		authToken:   authToken,
		autoCommit:  autoCommit,
		transaction: tx,
	}, func(dbName string) (storage.Engine, error) {
		if e.dbManager != nil {
			engineIface, err := e.dbManager.GetStorageForUse(dbName, authToken)
			if err == nil {
				if engine, ok := engineIface.(storage.Engine); ok {
					return engine, nil
				}
				return nil, localizedError(localization.CypherCommandRoutingFabricStorageTypeInvalid(dbName), nil)
			}
		}
		scoped, _, err := e.scopedExecutorForUse(dbName, authToken)
		if err != nil {
			return nil, err
		}
		return scoped.storage, nil
	})
	var remoteExec *fabric.RemoteFragmentExecutor
	if !autoCommit && e.txContext != nil && e.txContext.active {
		if cached := e.txContext.fabricRemoteExe; cached != nil {
			remoteExec = cached
		} else {
			remoteExec = fabric.NewRemoteFragmentExecutor()
			e.txContext.fabricRemoteExe = remoteExec
		}
	} else {
		remoteExec = fabric.NewRemoteFragmentExecutor()
		defer func() { _ = remoteExec.Close() }()
	}

	statsAcc := &queryStatsAccumulator{}
	ctx = context.WithValue(ctx, queryStatsAccumulatorKey{}, statsAcc)
	fabricTrace := &fabric.HotPathTrace{}
	ctx = fabric.WithHotPathTrace(ctx, fabricTrace)
	fabricExecutor := fabric.NewFabricExecutor(catalog, localExec, remoteExec)
	fabricExecutor.SetUnionContract(fabricUnionContract)
	fabricExecutor.SetRemoteValueCodec(fabricRemoteValueCodec)
	fabricExecutor.SetConcurrentExecution(autoCommit && !contract.dynamic)
	fabricExecutor.SetGraphArgumentEvaluator(e.evaluateGraphArguments)
	fabricExecutor.SetRemoteModeUncertainty(func(query string) bool {
		contract, err := readStatementExecutionContract(ctx, query)
		return err != nil || contract.calls
	})
	fabricExecutor.SetGraphAuthorizer(func(ctx context.Context, database, query string) error {
		if err := e.authorizeSelectedDatabase(ctx, database, query); err != nil {
			return err
		}
		return e.recordStatementReference(cypher, database)
	})
	stream, err := fabricExecutor.Execute(ctx, tx, fragment, params, authToken)
	if err != nil {
		// In explicit transactions (autoCommit=false), preserve transaction lifecycle
		// for client-issued COMMIT/ROLLBACK. In autocommit mode, rollback immediately.
		if autoCommit {
			_ = tx.Rollback(nil)
		}
		return nil, fabricGraphReferenceError(err)
	}
	e.setFabricBatchedApplyRowsUsed(fabricTrace.ApplyBatchedLookupRows.Load())
	if autoCommit {
		if err := tx.Commit(nil, nil); err != nil {
			return nil, err
		}
		if tx.WriteShard() != "" {
			publishStatementCommit(ctx)
		}
	}
	if stream == nil {
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	}
	// Schema commands have a void result established by their command executor.
	// USE selects the participant; it does not turn DDL into a graph projection.
	_, command, _, useErr := parseUseClause(cypher, false)
	if useErr != nil {
		return nil, useErr
	}
	if len(stream.Columns) == 0 && !isSchemaCommandStatement(command) {
		columns, err := e.ResultColumns(ctx, cypher, e.resultIncomingScope(), cypherVersionFromContext(ctx) == "25")
		if err != nil {
			return nil, err
		}
		stream.Columns = columns
	}
	if err := e.normalizeFabricRowWrapper(ctx, cypher, stream); err != nil {
		return nil, err
	}
	s := statsAcc.snapshot()
	return resolvedStatementModeResult(&ExecuteResult{
		Columns: stream.Columns,
		Rows:    stream.Rows,
		Stats:   &s,
	}, tx.WriteShard() != ""), nil
}

type fabricPreparedExec struct {
	catalog   *fabric.Catalog
	sessionDB string
	fragment  fabric.Fragment
	hasRemote bool
}

// fabricResultCacheKey binds each local target's identity, catalog generation
// and graph revision in sorted order. Equal numeric revisions on different
// targets, or on a recreated selection, must never reuse the same result.
func (e *StorageExecutor) fabricResultCacheKey(ctx context.Context, prepared *fabricPreparedExec, cypher string, params map[string]interface{}) (string, bool) {
	selections, local := e.fabricLocalSelections(ctx, prepared)
	if !local || !e.StatementCacheSelectionValid() {
		return "", false
	}
	if len(selections) == 0 && e.authorizeSelectedDatabase(ctx, "", cypher) != nil {
		return "", false
	}
	resolver, ok := e.dbManager.(statementCacheScopeResolver)
	if !ok {
		return "", false
	}
	key := cacheKeyBuilder{}
	var scratch [binary.MaxVarintLen64 + 1]byte
	writeCacheKeyString(&key, &scratch, resultCacheEntryKey(ctx, cypher, params))
	key.buf = binary.AppendUvarint(key.buf, e.statementCacheScope.Generation())
	scopes := make([]*multidb.StatementCacheScope, 0, len(selections))
	for _, selection := range selections {
		scope, err := resolver.StatementCacheScope(selection.name)
		if err != nil || !scope.Valid() {
			return "", false
		}
		engine, err := e.dbManager.GetStorageForUse(selection.database, GetAuthTokenFromContext(ctx))
		if err != nil {
			return "", false
		}
		provider, ok := engine.(storage.GraphMutationVersionProvider)
		if !ok {
			return "", false
		}
		revision, supported := provider.GraphMutationVersion()
		if !supported {
			return "", false
		}
		writeCacheKeyString(&key, &scratch, selection.name)
		writeCacheKeyString(&key, &scratch, selection.database)
		key.buf = binary.AppendUvarint(key.buf, scope.Generation())
		key.buf = binary.AppendUvarint(key.buf, revision)
		scopes = append(scopes, scope)
	}
	if !e.StatementCacheSelectionValid() || !statementScopesValid(scopes) {
		return "", false
	}
	return string(key.buf), true
}

type fabricLocalSelection struct{ name, database string }

// Authorization and current catalog resolution precede every result lookup.
// Dynamic and remote targets keep executing through dispatch without caching.
func (e *StorageExecutor) fabricLocalSelections(ctx context.Context, prepared *fabricPreparedExec) (selections []fabricLocalSelection, local bool) {
	if prepared == nil || prepared.catalog == nil || prepared.fragment == nil {
		return nil, false
	}
	seen := make(map[fabricLocalSelection]struct{})
	var collect func(fabric.Fragment) bool
	collect = func(fragment fabric.Fragment) bool {
		switch current := fragment.(type) {
		case *fabric.FragmentExec:
			if current.Graph != nil && current.Graph.IsDynamic() || e.authorizeSelectedDatabase(ctx, current.GraphName, current.Query) != nil {
				return false
			}
			location, err := prepared.catalog.Resolve(current.GraphName)
			if err != nil {
				return false
			}
			target, ok := location.(*fabric.LocationLocal)
			if !ok {
				return false
			}
			name := current.GraphName
			if name == "" {
				name = target.DBName
			}
			selection := fabricLocalSelection{name: name, database: target.DBName}
			if _, listed := seen[selection]; !listed {
				seen[selection] = struct{}{}
				selections = append(selections, selection)
			}
			return collect(current.Input)
		case *fabric.FragmentApply:
			return collect(current.Input) && collect(current.Inner)
		case *fabric.FragmentUnion:
			return collect(current.LHS) && collect(current.RHS)
		case *fabric.FragmentLeaf:
			return collect(current.Input)
		case *fabric.FragmentInit:
			return true
		default:
			return false
		}
	}
	if !collect(prepared.fragment) {
		return nil, false
	}
	sort.Slice(selections, func(i, j int) bool {
		if selections[i].name != selections[j].name {
			return selections[i].name < selections[j].name
		}
		return selections[i].database < selections[j].database
	})
	return selections, true
}
func (e *StorageExecutor) prepareFabricExecution(ctx context.Context, cypher string) (*fabricPreparedExec, error) {
	catalog, err := e.buildFabricCatalog()
	if err != nil {
		return nil, err
	}
	sessionDB := e.currentDatabaseName()
	if dbFromCtx := GetUseDatabaseFromContext(ctx); strings.TrimSpace(dbFromCtx) != "" {
		sessionDB = dbFromCtx
	}
	fragment, err := e.planFabricQuery(ctx, catalog, cypher, sessionDB)
	if err != nil {
		return nil, fabricGraphReferenceError(err)
	}
	return &fabricPreparedExec{
		catalog:   catalog,
		sessionDB: sessionDB,
		fragment:  fragment,
		hasRemote: fabricFragmentHasRemoteTarget(catalog, fragment),
	}, nil
}

func (e *StorageExecutor) preparedFabricFromContext(ctx context.Context) (*fabricPreparedExec, error) {
	if ctx == nil {
		return nil, nil
	}
	v := ctx.Value(fabricPreparedExecKey{})
	if v == nil {
		return nil, nil
	}
	prepared, ok := v.(*fabricPreparedExec)
	if !ok {
		return nil, localizedError(localization.CypherCommandRoutingFabricPreparedContextInvalid(), nil)
	}
	return prepared, nil
}

func fabricFragmentHasRemoteTarget(catalog *fabric.Catalog, f fabric.Fragment) bool {
	if catalog == nil || f == nil {
		return false
	}
	switch frag := f.(type) {
	case *fabric.FragmentExec:
		loc, err := catalog.Resolve(frag.GraphName)
		if err != nil {
			return false
		}
		_, isRemote := loc.(*fabric.LocationRemote)
		return isRemote
	case *fabric.FragmentApply:
		return fabricFragmentHasRemoteTarget(catalog, frag.Input) || fabricFragmentHasRemoteTarget(catalog, frag.Inner)
	case *fabric.FragmentUnion:
		return fabricFragmentHasRemoteTarget(catalog, frag.LHS) || fabricFragmentHasRemoteTarget(catalog, frag.RHS)
	case *fabric.FragmentLeaf:
		return fabricFragmentHasRemoteTarget(catalog, frag.Input)
	case *fabric.FragmentInit:
		return false
	default:
		return false
	}
}

// fabricUnionContract gives the UNION branches Fabric combines the semantics
// executeUnion gives a UNION on one graph.
var fabricUnionContract = fabric.UnionContract{
	ColumnOrder:  unionColumnOrder,
	ColumnsError: unionColumnsError,
	NewDistinct: func() func(row []interface{}) bool {
		seen := make(map[string]bool)
		return func(row []interface{}) bool {
			key := cypherValueKey(row, cypherEquivalenceContract)
			if seen[key] {
				return true
			}
			seen[key] = true
			return false
		}
	},
}

// fabricSingleGraphStatement is cypher without the USE clauses the Fabric
// planner reads (FabricPlanner.SingleGraphStatement): the one statement whose
// variable scopes are checked, as Neo4j checks a composite statement's, before
// any part of it plans or runs. A statement the planner can't read is checked
// as it is, and planning reports the error.
func fabricSingleGraphStatement(ctx context.Context, cypher string) string {
	planner := fabric.NewFabricPlanner(nil)
	planner.SetClauseKeywordNameReader(clauseKeywordUsedAsName)
	planner.SetCallImportReader(func(scope string, scoped bool, body string) ([]string, error) {
		return callSubqueryImportedVariables(ctx, scope, scoped, body)
	})
	statement, err := planner.SingleGraphStatement(cypher)
	if err != nil {
		return cypher
	}
	return statement
}

func (e *StorageExecutor) planFabricQuery(ctx context.Context, catalog *fabric.Catalog, cypher, sessionDB string) (fabric.Fragment, error) {
	if e.fabricPlanCache != nil {
		if cached, found := e.fabricPlanCache.Get(cypher, sessionDB); found && cached != nil {
			return cached, nil
		}
	}

	planner := fabric.NewFabricPlanner(catalog)
	// A name spelled UNION, OPTIONAL or RETURN is read as ordinary statements read it.
	planner.SetClauseKeywordNameReader(clauseKeywordUsedAsName)
	planner.SetCallImportReader(func(scope string, scoped bool, body string) ([]string, error) {
		return callSubqueryImportedVariables(ctx, scope, scoped, body)
	})
	fragment, err := planner.Plan(cypher, sessionDB)
	if err != nil {
		return nil, err
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if e.fabricPlanCache != nil {
		e.fabricPlanCache.Put(cypher, sessionDB, fragment)
	}
	return fragment, nil
}

// fabricProcedureWritePlan resolves the registered CALL contract at statement
// admission, just as the native transaction route does. Cached structural plans
// stay immutable and do not retain an obsolete procedure mode after registration.
// The existing Fabric participant owner then handles writes and their rollback.
func (e *StorageExecutor) fabricProcedureWritePlan(ctx context.Context, fragment fabric.Fragment) (fabric.Fragment, error) {
	switch current := fragment.(type) {
	case *fabric.FragmentExec:
		input, err := e.fabricProcedureWritePlan(ctx, current.Input)
		if err != nil {
			return nil, err
		}
		contract, err := readStatementExecutionContract(ctx, current.Query)
		if err != nil {
			return nil, err
		}
		write := contract.writes
		if e.dbManager != nil && e.dbManager.IsCompositeDatabase(current.GraphName) {
			write = false
		}
		if input == current.Input && write == current.IsWrite {
			return current, nil
		}
		copy := *current
		copy.Input, copy.IsWrite = input, write
		return &copy, nil
	case *fabric.FragmentApply:
		input, err := e.fabricProcedureWritePlan(ctx, current.Input)
		if err != nil {
			return nil, err
		}
		inner, err := e.fabricProcedureWritePlan(ctx, current.Inner)
		if err != nil {
			return nil, err
		}
		if input == current.Input && inner == current.Inner {
			return current, nil
		}
		copy := *current
		copy.Input, copy.Inner = input, inner
		return &copy, nil
	case *fabric.FragmentUnion:
		left, err := e.fabricProcedureWritePlan(ctx, current.LHS)
		if err != nil {
			return nil, err
		}
		right, err := e.fabricProcedureWritePlan(ctx, current.RHS)
		if err != nil {
			return nil, err
		}
		if left == current.LHS && right == current.RHS {
			return current, nil
		}
		copy := *current
		copy.LHS, copy.RHS = left, right
		return &copy, nil
	case *fabric.FragmentLeaf:
		input, err := e.fabricProcedureWritePlan(ctx, current.Input)
		if err != nil {
			return nil, err
		}
		if input == current.Input {
			return current, nil
		}
		copy := *current
		copy.Input = input
		return &copy, nil
	default:
		return fragment, nil
	}
}

func (e *StorageExecutor) normalizeFabricRowWrapper(ctx context.Context, cypher string, stream *fabric.ResultStream) error {
	if stream == nil || !stream.RowWrapper || len(stream.Columns) != 1 || len(stream.Rows) == 0 {
		return nil
	}
	inferred, err := e.ResultColumns(ctx, cypher, e.resultIncomingScope(), cypherGrammarVersion(cypher) == "25")
	if err != nil {
		return err
	}
	if len(inferred) == 0 {
		return nil
	}
	projectedRows := make([][]interface{}, 0, len(stream.Rows))
	for _, row := range stream.Rows {
		if len(row) == 0 {
			continue
		}
		m, ok := normalizeFabricRowMap(row[0])
		if !ok {
			continue
		}
		out := make([]interface{}, len(inferred))
		sourceID, _ := m["sourceId"]
		for i, col := range inferred {
			if v, ok := m[col]; ok {
				out[i] = v
				continue
			}
			if sourceID != nil {
				if v, ok := lookupColumnBySourceIDInRows(m["rows"], sourceID, col); ok {
					out[i] = v
				}
			}
		}
		projectedRows = append(projectedRows, out)
	}
	if len(projectedRows) == 0 {
		return nil
	}
	stream.Columns = inferred
	stream.Rows = projectedRows
	return nil
}

func normalizeFabricRowMap(v interface{}) (map[string]interface{}, bool) {
	switch m := v.(type) {
	case map[string]interface{}:
		return m, true
	case map[interface{}]interface{}:
		out := make(map[string]interface{}, len(m))
		for k, val := range m {
			out[fmt.Sprint(k)] = val
		}
		return out, true
	default:
		return nil, false
	}
}

func lookupColumnBySourceIDInRows(rowsAny interface{}, sourceID interface{}, col string) (interface{}, bool) {
	switch rows := rowsAny.(type) {
	case []interface{}:
		for _, item := range rows {
			m, ok := item.(map[string]interface{})
			if !ok {
				continue
			}
			if sameSourceID(m["sourceId"], sourceID) {
				v, exists := m[col]
				return v, exists
			}
		}
	case []map[string]interface{}:
		for _, m := range rows {
			if sameSourceID(m["sourceId"], sourceID) {
				v, exists := m[col]
				return v, exists
			}
		}
	}
	return nil, false
}

func sameSourceID(a interface{}, b interface{}) bool {
	normalize := func(v interface{}) string {
		s := strings.TrimSpace(fmt.Sprint(v))
		return strings.Trim(s, `"`)
	}
	return normalize(a) == normalize(b)
}

func (e *StorageExecutor) currentDatabaseName() string {
	if composite, ok := e.storage.(interface{ CompositeName() string }); ok {
		if name := strings.TrimSpace(composite.CompositeName()); name != "" {
			return name
		}
	}
	if ns, ok := e.storage.(interface{ Namespace() string }); ok {
		if name := strings.TrimSpace(ns.Namespace()); name != "" {
			return name
		}
	}
	return "nornic"
}

func (e *StorageExecutor) buildFabricCatalog() (*fabric.Catalog, error) {
	catalog := fabric.NewCatalog()
	for _, db := range e.dbManager.ListDatabases() {
		dbName := strings.TrimSpace(db.Name())
		if dbName == "" {
			continue
		}
		catalog.Register(dbName, &fabric.LocationLocal{DBName: dbName})
		for alias := range e.dbManager.ListAliases(dbName) {
			alias = strings.TrimSpace(alias)
			if alias != "" {
				catalog.Register(alias, &fabric.LocationLocal{DBName: dbName})
			}
		}

		if db.Type() != "composite" {
			continue
		}
		constituents, err := e.dbManager.GetCompositeConstituents(dbName)
		if err != nil {
			return nil, localizedError(localization.CypherCommandRoutingFabricConstituentsFailed(dbName, err), err)
		}
		for _, raw := range constituents {
			ref, ok := toConstituentRef(raw)
			if !ok || strings.TrimSpace(ref.Alias) == "" {
				continue
			}
			qualified := dbName + "." + ref.Alias
			if strings.EqualFold(strings.TrimSpace(ref.Type), "remote") {
				catalog.Register(qualified, &fabric.LocationRemote{
					DBName:   ref.DatabaseName,
					URI:      ref.URI,
					AuthMode: strings.TrimSpace(ref.AuthMode),
					User:     ref.User,
					Password: ref.Password,
				})
				continue
			}
			catalog.Register(qualified, &fabric.LocationLocal{DBName: ref.DatabaseName})
		}
	}
	return catalog, nil
}

func toConstituentRef(raw interface{}) (multidb.ConstituentRef, bool) {
	if ref, ok := raw.(multidb.ConstituentRef); ok {
		return ref, true
	}
	m, ok := raw.(map[string]interface{})
	if !ok {
		return multidb.ConstituentRef{}, false
	}
	return multidb.ConstituentRef{
		Alias:        mapString(m, "alias"),
		DatabaseName: mapString(m, "database_name"),
		Type:         mapString(m, "type"),
		AccessMode:   mapString(m, "access_mode"),
		URI:          mapString(m, "uri"),
		SecretRef:    mapString(m, "secret_ref"),
		AuthMode:     mapString(m, "auth_mode"),
		User:         mapString(m, "user"),
		Password:     mapString(m, "password"),
	}, true
}

func mapString(m map[string]interface{}, key string) string {
	if v, ok := m[key]; ok {
		if s, ok := v.(string); ok {
			return s
		}
	}
	return ""
}

type cypherFabricExecutor struct {
	base            *StorageExecutor
	authToken       string
	autoCommit      bool
	transaction     *fabric.FabricTransaction
	localDispatchMu sync.Mutex

	mu sync.Mutex
	// localTxExecBySub holds the sub-transaction executors of a statement
	// run outside an explicit transaction; an explicit transaction keeps
	// them in its TransactionContext (localShardTxExecutors).
	localTxExecBySub map[string]*StorageExecutor
}

// localShardTxExecutors is the map of sub-transaction executors by shard
// name: the explicit transaction's, so its statements share one
// sub-transaction per constituent, or else this statement's own.
func (c *cypherFabricExecutor) localShardTxExecutors() map[string]*StorageExecutor {
	if c.base != nil && c.base.txContext != nil && c.base.txContext.active {
		if c.base.txContext.fabricLocalTxExec == nil {
			c.base.txContext.fabricLocalTxExec = make(map[string]*StorageExecutor)
		}
		return c.base.txContext.fabricLocalTxExec
	}
	if c.localTxExecBySub == nil {
		c.localTxExecBySub = make(map[string]*StorageExecutor)
	}
	return c.localTxExecBySub
}

func (c *cypherFabricExecutor) ExecuteQuery(ctx context.Context, dbName string, engine storage.Engine, query string, params map[string]interface{}) ([]string, [][]interface{}, error) {
	return c.ExecuteQueryWithRecord(ctx, dbName, engine, query, params, nil)
}

func (c *cypherFabricExecutor) ExecuteRecordQuery(ctx context.Context, dbName, query string, params, recordBindings map[string]interface{}) ([]string, [][]interface{}, bool, error) {
	clauses, supported := canExecuteAsPipeline(ctx, query)
	if !supported || containsRelationshipPattern(query) {
		return nil, nil, false, nil
	}
	for _, clause := range clauses {
		if clause.kind != pipelineClauseWith && clause.kind != pipelineClauseUnwind && clause.kind != pipelineClauseReturn {
			return nil, nil, false, nil
		}
	}
	keywords := queryKeywords(query)
	if keywords["MATCH"] || keywords["STARTNODE"] || keywords["ENDNODE"] || keywords["SHORTESTPATH"] {
		return nil, nil, false, nil
	}
	engine := c.base.storage
	executor := c.base.cloneForStorage(engine)
	if err := executor.bindFabricStatementCacheScope(ctx, dbName); err != nil {
		return nil, nil, true, err
	}
	executor.fabricRecordBindings = recordBindings
	ctx = withExecutionDatabase(WithAuthToken(ctx, c.authToken), dbName)
	columns, rows, err := c.executeFragmentQuery(ctx, executor, query, params)
	return columns, rows, true, err
}

func (c *cypherFabricExecutor) ExecuteQueryWithRecord(ctx context.Context, dbName string, engine storage.Engine, query string, params map[string]interface{}, recordBindings map[string]interface{}) ([]string, [][]interface{}, error) {
	ctx = WithAuthToken(ctx, c.authToken)
	base := c.base
	composite, compositeRoot := engine.(*storage.CompositeEngine)
	ctx = context.WithValue(ctx, dynamicWriteAdmissionKey{}, dynamicWriteAdmission(func(callCtx context.Context, caller *StorageExecutor, statement string) error {
		if compositeRoot {
			return nil
		} // The actual mutation selects its physical owner below.
		return c.promoteResolvedStatement(callCtx, caller, dbName, engine, statement)
	}))
	if compositeRoot {
		c.localDispatchMu.Lock()
		defer c.localDispatchMu.Unlock()
		engine = composite.WithConstituentAccess(func(database string, physical storage.Engine, write bool) (storage.Engine, error) {
			return c.compositeParticipantStorage(ctx, database, physical, write)
		})
	} else if sub, ok := fabric.SubTransactionFromContext(ctx); ok {
		if !c.autoCommit || c.transaction != nil && c.transaction.WriteShard() == sub.ShardName {
			// Fabric has one write participant. Its local fragments share one
			// transactional executor until the coordinator admits COMMIT.
			// Concurrent read-only participants keep their independent path.
			if c.autoCommit {
				c.localDispatchMu.Lock()
				defer c.localDispatchMu.Unlock()
			}
			txExec, err := c.ensureLocalShardTxExecutor(ctx, sub, dbName, engine)
			if err != nil {
				return nil, nil, err
			}
			base = txExec
			engine = txExec.storage
		}
	}
	// A fragment view owns its removable catalog selection while the retained
	// shard executor keeps the underlying database transaction's lifetime.
	exec := base.cloneForStorage(engine)
	if err := exec.bindFabricStatementCacheScope(ctx, dbName); err != nil {
		return nil, nil, err
	}
	if len(recordBindings) > 0 {
		exec.fabricRecordBindings = recordBindings
		query = stripLeadingWithImportsForFabricRecord(query, recordBindings)
	}
	ctx = withExecutionDatabase(ctx, dbName)
	return c.executeFragmentQuery(ctx, exec, query, params)
}

func (c *cypherFabricExecutor) executeFragmentQuery(ctx context.Context, exec *StorageExecutor, query string, params map[string]interface{}) ([]string, [][]interface{}, error) {
	previousIdentityScope := exec.graphIdentityScope
	var catalog *fabric.Catalog
	if prepared, err := exec.preparedFabricFromContext(ctx); err == nil && prepared != nil {
		catalog = prepared.catalog
	}
	exec.graphIdentityScope = newGraphIdentityScope(catalog, exec.executionDatabaseName(ctx), exec.dbManager, c.authToken)
	defer func() { exec.graphIdentityScope = previousIdentityScope }()
	// Local fragments bypass implicit execution's decision. Classify this
	// fragment itself: writes and procedures must retain full node reads.
	exec.readOnlyQueryNodes = exec.readsQueryNodesWithoutVectors(exec.analyzer.Analyze(ctx, query))
	result, err := exec.executeInternal(ctx, query, params)
	if err != nil {
		return nil, nil, err
	}
	if result == nil {
		return []string{}, [][]interface{}{}, nil
	}
	if acc := queryStatsAccumulatorFromContext(ctx); acc != nil {
		acc.add(result.Stats)
	}
	return result.Columns, result.Rows, nil
}

func stripLeadingWithImportsForFabricRecord(query string, recordBindings map[string]interface{}) string {
	if len(recordBindings) == 0 {
		return query
	}
	trimmed := strings.TrimSpace(query)
	if !strings.HasPrefix(upperASCII(trimmed), "WITH ") {
		return query
	}
	withEnd := findLeadingWithEndLocal(trimmed)
	if withEnd <= 0 || withEnd >= len(trimmed) {
		return query
	}
	withClause := strings.TrimSpace(trimmed[len("WITH "):withEnd])
	rest := strings.TrimSpace(trimmed[withEnd:])
	if rest == "" {
		return query
	}
	// Stripping is safe for simple imported bindings when the next clause is a
	// top-level read/projection/pipeline clause that can resolve identifiers from
	// Fabric record bindings.
	if !(startsWithKeywordFold(rest, "MATCH") ||
		startsWithKeywordFold(rest, "OPTIONAL MATCH") ||
		startsWithKeywordFold(rest, "RETURN") ||
		startsWithKeywordFold(rest, "UNWIND") ||
		startsWithKeywordFold(rest, "USE")) {
		return query
	}
	imports := splitTopLevelComma(withClause)
	if len(imports) == 0 {
		return query
	}
	for _, item := range imports {
		name := strings.TrimSpace(item)
		if name == "" || strings.Contains(name, " ") {
			return query
		}
		if _, ok := recordBindings[name]; !ok {
			return query
		}
	}
	rewritten := rest
	local := localOccurrences{text: rest}
	for _, item := range imports {
		name := strings.TrimSpace(item)
		rewritten = replaceIdentifierOutsideQuotesUnless(rewritten, name, "$"+name, &local)
	}
	return rewritten
}

func findLeadingWithEndLocal(query string) int {
	const prefix = "WITH "
	if len(query) <= len(prefix) {
		return -1
	}
	body := query[len(prefix):]
	end := -1
	for _, keyword := range [...]string{
		"MATCH", "OPTIONAL MATCH", "RETURN", "WHERE", "USE", "WITH", "CALL",
		"CREATE", "MERGE", "UNWIND", "SET", "DELETE", "DETACH DELETE",
	} {
		if index := topLevelKeywordIndex(body, keyword); index >= 0 && (end < 0 || index < end) {
			end = index
		}
	}
	if end < 0 {
		return -1
	}
	return len(prefix) + end
}
func (c *cypherFabricExecutor) ensureLocalShardTxExecutor(ctx context.Context, sub *fabric.SubTransaction, dbName string, engine storage.Engine) (*StorageExecutor, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	executors := c.localShardTxExecutors()
	if existing := executors[sub.ShardName]; existing != nil {
		return existing, nil
	}

	txExec := NewStorageExecutor(engine)
	txExec.ShareStatementCachesFrom(c.base)
	txExec.deferFlush = c.base.deferFlush
	txExec.ShareEmbedderFrom(c.base)
	c.base.shareSearchFor(txExec, storageDatabaseName(engine))
	txExec.inferenceManager = c.base.inferenceManager
	txExec.onNodeMutated = c.base.onNodeMutated
	txExec.defaultEmbeddingDimensions = c.base.defaultEmbeddingDimensions
	txExec.dbManager = c.base.dbManager
	if err := txExec.bindStatementCacheScope(dbName); err != nil {
		return nil, err
	}
	txExec.vectorRegistry = c.base.vectorRegistry
	txExec.vectorIndexSpaces = c.base.vectorIndexSpaces

	beginCtx := WithTransactionControl(WithAuthToken(ctx, c.authToken))
	if _, err := txExec.Execute(beginCtx, "BEGIN", nil); err != nil {
		return nil, localizedError(localization.CypherCommandRoutingFabricShardTransactionFailed(dbName, err), err)
	}

	terminalCtx := context.WithoutCancel(beginCtx)
	commitFn := func(_ *fabric.SubTransaction) error {
		_, err := txExec.Execute(terminalCtx, "COMMIT", nil)
		return err
	}
	rollbackFn := func(_ *fabric.SubTransaction) error {
		_, err := txExec.Execute(terminalCtx, "ROLLBACK", nil)
		return err
	}
	if tx := c.fabricTransaction(); tx != nil {
		if err := tx.BindParticipantCallbacks(sub.ShardName, commitFn, rollbackFn); err != nil {
			return nil, err
		}
	}

	executors[sub.ShardName] = txExec
	return txExec, nil
}

// evaluateGraphArguments evaluates a dynamic graph reference's arguments
// (USE graph.byName(g)) for Fabric: values holds the statement's
// parameters and the current row's variables.
func (e *StorageExecutor) evaluateGraphArguments(ctx context.Context, expressions []string, values map[string]interface{}) ([]string, error) {
	ctx = withQueryParams(ctx, values)
	out := make([]string, len(expressions))
	for i, expression := range expressions {
		value, ok := e.evaluateRowExpressionWithContext(ctx, expression, pipelineRow(values))
		if !ok {
			if err, undefined := undefinedVariableError(expression); undefined {
				return nil, err
			}
			return nil, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
				localization.CypherCommandRoutingGraphFunctionArgumentInvalid(expression))
		}
		text, isString := value.(string)
		if !isString {
			// Neo4j: "Expected <argument> to be a STRING, but it was an INTEGER".
			return nil, localizedStatusError("Neo.ClientError.Statement.TypeError", "TypeError",
				localization.CypherCommandRoutingGraphFunctionArgumentType(expression, cypherTypeSystemNameWithArticle(value)))
		}
		out[i] = text
	}
	return out, nil
}

// fabricGraphReferenceError reports a dynamic graph reference Fabric could
// not resolve with its Neo4j status: a graph that doesn't exist is
// DatabaseNotFound "Graph not found: <name>".
func fabricGraphReferenceError(err error) error {
	if errors.Is(err, fabric.ErrMixedUnion) {
		return unionMixedError()
	}
	var notFound *fabric.GraphNotFoundError
	if errors.As(err, &notFound) {
		return localizedStatusError("Neo.ClientError.Database.DatabaseNotFound", "DatabaseNotFound", localization.CypherCommandRoutingGraphNotFound(notFound.Name))
	}
	var reference *fabric.GraphReferenceError
	if errors.As(err, &reference) {
		return localizedStatusError(reference.Code, "GraphReference", reference.Message)
	}
	var syntax *fabric.UseSyntaxError
	if errors.As(err, &syntax) {
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", syntax.Message)
	}
	return err
}

func (e *cypherFabricExecutor) CachedResultColumns(ctx context.Context, query string, incoming []string) resultmetadata.Names {
	return e.base.CachedResultColumns(ctx, query, incoming)
}

func (e *cypherFabricExecutor) ResultProjection(ctx context.Context, query string, incoming []string) resultmetadata.Projection {
	return e.base.ResultProjection(ctx, query, incoming)
}

func (c *cypherFabricExecutor) fabricTransaction() *fabric.FabricTransaction {
	if c.transaction != nil {
		return c.transaction
	}
	if c.base != nil && c.base.txContext != nil {
		tx, _ := c.base.txContext.tx.(*fabric.FabricTransaction)
		return tx
	}
	return nil
}

package cypher

import (
	"context"
	"strings"

	"github.com/orneryd/nornicdb/pkg/config"
	"github.com/orneryd/nornicdb/pkg/fabric"
	"github.com/orneryd/nornicdb/pkg/localization"
)

// executeInternal executes a Cypher fragment as part of a larger execution flow.
//
// Unlike Execute(), this does NOT:
//   - apply query limits / rate limiting
//   - consult or populate result caches
//   - start implicit transactions for write queries
//
// The key property is that internal subqueries/procedure bodies participate in
// the caller's transaction context (explicit tx or implicit tx wrapper carried
// on ctx), avoiding nested implicit transactions and misrouting.
// executeUserStatement runs statement text a procedure was given to run
// (apoc.cypher.run / runMany, apoc.periodic.iterate / commit,
// apoc.export.*.query): a user's statement, which may not call NornicDB's
// internal functions (#1105). It runs inside the caller's statement, a data
// statement, so an administration command there is refused as after any
// data statement (ForbiddenDueToTransactionType), in auto-commit as in an
// explicit transaction.
func (e *StorageExecutor) executeUserStatement(ctx context.Context, statement string, params map[string]interface{}) (result *ExecuteResult, err error) {
	if totals, ok := ctx.Value(procedureStatementStatsKey{}).(*procedureStatementStats); ok && totals != nil {
		// Every nested procedure installs its own invocation collector. Its
		// completed summary enters this collector only through this result.
		defer func() {
			if err == nil && result != nil {
				totals.record(result.Stats)
			}
		}()
	}
	if err := internalFunctionCallError(statement); err != nil {
		// Refused like any statement of the caller's transaction: it fails
		// an explicit transaction (executeInternal fails it for the rest).
		return nil, e.failTransaction(ctx, err)
	}
	if StatementDatabase("", statement) == "system" {
		var transaction any
		if wrapper, ok := ctx.Value(ctxKeyTxStorage).(*transactionStorageWrapper); ok {
			transaction = wrapper.tx
		} else if e.txContext != nil && e.txContext.active {
			transaction = e.txContext.tx
		}
		return nil, e.failTransaction(ctx, statementTypeError(ctx, statement, "Administration", "Data", transaction))
	}
	return e.executeInternal(ctx, statement, params)
}

func (e *StorageExecutor) executeInternal(ctx context.Context, cypher string, params map[string]interface{}) (result *ExecuteResult, retErr error) {
	if e.txContext != nil && e.txContext.active {
		defer func() { e.failTransaction(ctx, retErr) }()
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	cypher = normalizeCypherSyntaxConfusables(cypher)
	if config.IsCypherQueryNormalizationEnabled() {
		var err error
		cypher, _, err = normalizeQueryText(ctx, cypher)
		if err != nil {
			return nil, err
		}
	}
	cypher, _ = canonicalizeNumericLiterals(cypher)
	cypher, _ = canonicalizeFunctionAliases(cypher)
	if cypherVersionFromContext(ctx) == "25" {
		cypher, _ = separateCypher25Parameters(cypher)
	}
	cypher, _ = desugarStandaloneOrderClauses(cypher)
	cypher = strings.TrimSpace(cypher)
	cypher = trimTrailingStatementDelimiters(cypher)
	if err := e.validateStatementFraming(ctx, cypher); err != nil {
		return nil, err
	}
	finishTerminated := false
	if stripped, ok := stripUnionBranchFinishes(ctx, cypher); ok {
		cypher = strings.TrimSpace(stripped)
		finishTerminated = true
		ctx = withFinishedStatement(ctx, cypher)
	}
	if cypher == "" {
		if finishTerminated {
			return &ExecuteResult{}, nil
		}
		return nil, localizedError(localization.CypherCoreEmptyQuery(), nil)
	}
	if finishTerminated {
		defer func() {
			completeFinishedResult(result)
		}()
	}

	if use, remaining, hasUse, err := parseUseClause(cypher, false); hasUse || err != nil {
		if err != nil {
			return nil, err
		}
		if err := e.dynamicUseError(use); err != nil {
			return nil, err
		}
		return e.executeOnDatabase(ctx, use.Name, remaining, params, true)
	}
	if err := e.admitTransactionStatement(ctx, cypher); err != nil {
		return nil, err
	}
	routed, err := e.routeAdministrationStatement(ctx, cypher)
	if err != nil {
		return nil, err
	}
	if routed != e {
		return routed.executeInternal(ctx, cypher, params)
	}
	if err := e.authorizeSelectedDatabase(ctx, "", cypher); err != nil {
		return nil, err
	}
	e.statementAdmitted(ctx)
	if err := e.systemDatabaseWriteError(ctx, cypher); err != nil {
		return nil, err
	}

	// Local fragments own their lowering and restore generated names before
	// returning to Fabric or their containing expression.
	desugared, labelRewrite, err := desugarLabelExpressions(ctx, cypher, params, cypherVersionFromContext(ctx) == "25")
	if err != nil {
		return nil, err
	}
	if labelRewrite != nil {
		cypher = desugared
		defer func() { result, retErr = labelRewrite.restore(withoutGeneratedColumns(result), retErr) }()
	}

	// Basic syntax validation to preserve existing error behavior.
	if err := e.validateSyntax(ctx, cypher, cypherVersionFromContext(ctx) == "25"); err != nil {
		return nil, err
	}
	if err := e.validateTransactionalCalls(ctx, cypher, nil); err != nil {
		return nil, err
	}
	if _, err := e.admitBoundStatement(ctx, cypher); err != nil {
		return nil, err
	}
	if err := e.statementParametersError(ctx, cypher, params); err != nil {
		return nil, err
	}

	params = mergeInheritedQueryParams(ctx, params)
	params = normalizeQueryParameters(params)
	ctx = withQueryParams(ctx, params)
	if err := e.validateBoundParameterExpressions(ctx, cypher, params); err != nil {
		return nil, err
	}
	upper := e.cachedUpperQuery(cypher)
	// This is executable, normalized statement text with its actual parameter
	// values installed. Nested dynamic handlers return through this same gate;
	// no admission parser attempts to reconstruct their arguments.
	if err := e.admitResolvedStatementWrite(ctx, cypher); err != nil {
		return nil, err
	}

	// If we're in an explicit transaction, execute within it.
	if e.txContext != nil && e.txContext.active {
		return e.executeInTransaction(ctx, cypher, upper)
	}

	// Otherwise, stay on the caller's execution path (no implicit tx starts here).
	result, retErr = e.executeWithoutTransaction(ctx, cypher, upper)
	if retErr == nil && !e.inTransaction(ctx) {
		// An opaque procedure argument can contain a write even when its
		// caller opened no implicit transaction. Those effects apply directly.
		// A Fabric fragment instead belongs to the coordinator's commit.
		if _, pending := fabric.FabricTransactionFromContext(ctx); !pending {
			e.publishDirectStatementCommit(ctx, cypher)
		}
	}
	return result, retErr
}

func (e *StorageExecutor) validateBoundParameterExpressions(ctx context.Context, cypher string, params map[string]interface{}) error {
	if err := e.validateTransactionalCalls(ctx, cypher, params); err != nil {
		return err
	}
	// Only parse parameterized arithmetic when an operand's actual type can
	// be rejected; ordinary numeric hot paths keep their single cheap scan.
	if len(params) > 0 && parameterMayMismatchOperator(cypher, params) {
		if clauses, ok := splitPipelineClauses(ctx, cypher); ok {
			for _, clause := range clauses {
				if err := e.validateStaticOperatorTypes(ctx, clause, staticTypeScope{cypher25: cypherVersionFromContext(ctx) == "25"}, nil, params); err != nil {
					return err
				}
			}
		}
	}
	if err := validateStaticPropertyAccessParameters(ctx, cypher, params); err != nil {
		return err
	}
	if err := validateStaticFunctionParameters(ctx, cypher, params, cypherVersionFromContext(ctx) == "25"); err != nil {
		return err
	}
	// A transactional CALL commits independently before later runtime
	// pagination opens. Static pagination admission still runs at compilation;
	// its runtime values are checked by the owning pipeline operator.
	if !hasCallInTransactions(ctx, cypher) {
		if err := e.validateRuntimePaginationExpressions(ctx, extractPaginationExpressions(ctx, cypher)...); err != nil {
			return err
		}
	}
	return validateListOperands(ctx, cypher, params)
}

package cypher

import (
	"context"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// collectDeleteMutationTargets walks matchResult.Rows and classifies every
// projected value into either a node or relationship delete target,
// deduplicating repeats across rows. It performs no storage mutation --
// this is the "collect" phase of DELETE's collect -> validate -> apply
// pipeline (see validateNoResidualRelationships), which must complete
// before any validation or mutation so a multi-row, multi-variable DELETE
// (e.g. "DELETE a, r") can be judged as a whole statement.
func collectDeleteMutationTargets(store storage.Engine, matchResult *ExecuteResult) (nodeIDs []storage.NodeID, edgeIDs []storage.EdgeID) {
	seenNodes := make(map[string]struct{}, len(matchResult.Rows))
	seenEdges := make(map[string]struct{}, len(matchResult.Rows))
	nodeIDs = make([]storage.NodeID, 0, len(matchResult.Rows))
	edgeIDs = make([]storage.EdgeID, 0, len(matchResult.Rows))

	for _, row := range matchResult.Rows {
		for _, val := range row {
			collectDeleteTargetValue(store, val, seenNodes, seenEdges, &nodeIDs, &edgeIDs)
		}
	}

	return nodeIDs, edgeIDs
}

func collectDeleteTargetValue(store storage.Engine, value interface{}, seenNodes, seenEdges map[string]struct{}, nodeIDs *[]storage.NodeID, edgeIDs *[]storage.EdgeID) {
	target := classifyDeleteTargetValue(value)
	switch entity := value.(type) {
	case *storage.Node:
		if entity != nil {
			id, ok := entity.Identity().NodeLookupID(store)
			if !ok {
				return
			}
			target.nodeID = id
		}
	case *storage.Edge:
		if entity != nil {
			id, ok := entity.Identity().LookupID(store, "5")
			if !ok {
				return
			}
			target.edgeID = storage.EdgeID(id)
		}
	}
	switch target.kind {
	case deleteProjectionRelationship:
		key := string(target.edgeID)
		if _, seen := seenEdges[key]; !seen {
			seenEdges[key] = struct{}{}
			*edgeIDs = append(*edgeIDs, target.edgeID)
		}
		return
	case deleteProjectionNode:
		key := string(target.nodeID)
		if _, seen := seenNodes[key]; !seen {
			seenNodes[key] = struct{}{}
			*nodeIDs = append(*nodeIDs, target.nodeID)
		}
		return
	}

	switch typed := value.(type) {
	case PathResult:
		for _, node := range typed.Nodes {
			collectDeleteTargetValue(store, node, seenNodes, seenEdges, nodeIDs, edgeIDs)
		}
		for _, edge := range typed.Relationships {
			collectDeleteTargetValue(store, edge, seenNodes, seenEdges, nodeIDs, edgeIDs)
		}
	case *PathResult:
		if typed != nil {
			collectDeleteTargetValue(store, *typed, seenNodes, seenEdges, nodeIDs, edgeIDs)
		}
	case []interface{}:
		for _, item := range typed {
			collectDeleteTargetValue(store, item, seenNodes, seenEdges, nodeIDs, edgeIDs)
		}
	case map[string]interface{}:
		if path, ok := typed["_pathResult"]; ok {
			collectDeleteTargetValue(store, path, seenNodes, seenEdges, nodeIDs, edgeIDs)
			return
		}
		for _, item := range typed {
			collectDeleteTargetValue(store, item, seenNodes, seenEdges, nodeIDs, edgeIDs)
		}
	}
}

func isDeleteTargetValue(value interface{}) bool {
	// Marker keys in an ordinary Cypher map are user data, not authority to
	// delete an entity. Only the evaluator's actual PathResult carrier is a
	// map-shaped DELETE value; legacy projection classification stays private.
	if object, isMap := value.(map[string]interface{}); isMap {
		_, isPath := cypherPathResultOf(value, object, true)
		return isPath
	}
	if value == nil || classifyDeleteTargetValue(value).kind != deleteProjectionUnknown {
		return true
	}
	switch typed := value.(type) {
	case PathResult:
		return true
	case *PathResult:
		return typed != nil
	case []interface{}:
		for _, item := range typed {
			if !isDeleteTargetValue(item) {
				return false
			}
		}
		return true
	default:
		return false
	}
}

func hasTopLevelDeleteLabelQualifier(expression string) bool {
	expression = strings.TrimSpace(expression)
	depth := 0
	for index := 0; index < len(expression); index++ {
		if end, quoted := skipCypherLexicalToken(expression, index); quoted {
			index = end - 1
			continue
		}
		character := expression[index]
		switch character {
		case '(', '[', '{':
			depth++
		case ')', ']', '}':
			if depth > 0 {
				depth--
			}
		case ':':
			if depth == 0 {
				return true
			}
		}
	}
	return false
}

// deleteExpressionRootIdentifier returns the variable a DELETE target starts
// with (n in n, n.list[0], `n`), "" for a function call or a literal: null,
// true and false are never variables there (DELETE null deletes nothing, as
// in Neo4j, #907).
func deleteExpressionRootIdentifier(expression string) string {
	expression = strings.TrimSpace(expression)
	if expression == "" {
		return ""
	}
	// The name is read by the one identifier rule (scanIdentifierToken):
	// n$ and `a``b` are variables too.
	name, end, ok := scanIdentifierToken(expression, 0)
	if !ok || (end < len(expression) && expression[end] == '(') {
		return ""
	}
	if !strings.HasPrefix(expression, "`") {
		switch lowerASCII(name) {
		case "null", "true", "false":
			return ""
		}
	}
	return name
}

func addPipelinePatternBindings(ctx context.Context, executor *StorageExecutor, scope map[string]struct{}, clause, keyword string) {
	pattern := strings.TrimSpace(clause)
	if len(pattern) >= len(keyword) && strings.EqualFold(pattern[:len(keyword)], keyword) {
		pattern = strings.TrimSpace(pattern[len(keyword):])
	}
	if where := findKeywordIndexInContext(pattern, "WHERE"); where >= 0 {
		pattern = strings.TrimSpace(pattern[:where])
	}
	for _, variable := range executor.extractVariableNamesFromPattern(ctx, pattern) {
		if variable != "" {
			scope[variable] = struct{}{}
		}
	}
	for _, variable := range extractRelationshipVariables(pattern) {
		if variable != "" {
			scope[variable] = struct{}{}
		}
	}
	if variable := extractPathAssignmentVariable(pattern); variable != "" {
		scope[variable] = struct{}{}
	}
}

func extractPathAssignmentVariable(pattern string) string {
	if equals := strings.Index(pattern, "="); equals > 0 {
		candidate := strings.TrimSpace(pattern[:equals])
		right := strings.TrimSpace(pattern[equals+1:])
		if isPatternVariableName(candidate) && (strings.HasPrefix(right, "(") ||
			matchFuncStartAndSuffix(right, "shortestpath") ||
			matchFuncStartAndSuffix(right, "allshortestpaths")) {
			return normalizeProjectionColumnName(candidate)
		}
	}
	return ""
}

func appendUniquePipelineBinding(bindings []string, binding string) []string {
	for _, existing := range bindings {
		if existing == binding {
			return bindings
		}
	}
	return append(bindings, binding)
}

func pipelineUnwindAlias(clause string) string {
	if _, alias, ok := parsePipelineIteration(clause); ok {
		return normalizeProjectionColumnName(alias)
	}
	if index := findKeywordIndexInContext(clause, "AS"); index >= 0 {
		return strings.TrimSpace(clause[index+len("AS"):])
	}
	return ""
}

// validateNoResidualRelationships enforces openCypher/Neo4j DELETE
// semantics: a non-DETACH DELETE of a node that still has relationships is
// an error, not a silent cascade. NornicDB's storage layer
// (BadgerEngine.DeleteNode) cascades every adjacent edge unconditionally,
// so without this check a plain "DELETE n" on a connected node quietly
// deleted its edges too, violating Cypher's connected-node constraint.
//
// This must run BEFORE any node or edge in the plan is mutated: validating
// mid-apply would let a multi-row DELETE partially commit before a later
// row is found to violate the constraint, breaking statement atomicity.
//
// An edge attached to a candidate node does not count as residual if the
// same statement is also deleting that edge (e.g.
// "MATCH (a)-[r]->(b) DELETE a, r"); edgeIDs holds every edge this
// statement is about to remove, so those are subtracted before the check.
func validateNoResidualRelationships(store storage.Engine, nodeIDs []storage.NodeID, edgeIDs []storage.EdgeID) error {
	beingDeleted := deletingEdgeSet(edgeIDs)
	for _, nodeID := range nodeIDs {
		connected, err := nodeHasResidualRelationships(store, nodeID, beingDeleted)
		if err != nil {
			return err
		}
		if connected {
			return residualRelationshipDeleteError(nodeID)
		}
	}
	return nil
}

// connectedDeleteTargets returns the nodes of nodeIDs that relationships
// other than edgeIDs (this DELETE's own) still connect: a non-DETACH DELETE
// deletes them for now, and the transaction's commit fails unless a later
// clause deletes those relationships, as in Neo4j
// (storage.ConnectedNodeDeleter).
func connectedDeleteTargets(store storage.Engine, nodeIDs []storage.NodeID, edgeIDs []storage.EdgeID) (map[storage.NodeID]struct{}, error) {
	beingDeleted := deletingEdgeSet(edgeIDs)
	var connected map[storage.NodeID]struct{}
	for _, nodeID := range nodeIDs {
		residual, err := nodeHasResidualRelationships(store, nodeID, beingDeleted)
		if err != nil {
			return nil, err
		}
		if residual {
			if connected == nil {
				connected = make(map[storage.NodeID]struct{})
			}
			connected[nodeID] = struct{}{}
		}
	}
	return connected, nil
}

func deletingEdgeSet(edgeIDs []storage.EdgeID) map[storage.EdgeID]struct{} {
	beingDeleted := make(map[storage.EdgeID]struct{}, len(edgeIDs))
	for _, id := range edgeIDs {
		beingDeleted[id] = struct{}{}
	}
	return beingDeleted
}

// nodeHasResidualRelationships reports whether a relationship other than
// those beingDeleted connects nodeID (connectingRelationships).
func nodeHasResidualRelationships(store storage.Engine, nodeID storage.NodeID, beingDeleted map[storage.EdgeID]struct{}) (bool, error) {
	connecting, err := connectingRelationships(store, nodeID)
	if err != nil {
		return false, err
	}
	for _, edge := range connecting {
		if _, deleting := beingDeleted[deleteEdgeLookupID(store, edge)]; !deleting {
			return true, nil
		}
	}
	return false, nil
}

// connectingRelationships returns the relationships that connect nodeID for
// a DELETE: those DETACH DELETE removes with the node, and those that keep a
// non-DETACH DELETE from removing it. A store that lists the relationships the
// visibility layer hides (storage.IncidentEdgeLister: a transaction) lists
// them too, since the node's delete removes them all the same; without them a
// non-DETACH DELETE removed a node whose only relationships were hidden, as
// in Neo4j it fails with DeleteConnectedNode for any relationship. Stores run
// without a transaction (composite and remote databases) list what their
// reads return.
func connectingRelationships(store storage.Engine, nodeID storage.NodeID) ([]*storage.Edge, error) {
	if lister, ok := store.(storage.IncidentEdgeLister); ok {
		return lister.IncidentEdges(nodeID)
	}
	return undirectedIncidentEdges(store, nodeID)
}

// residualRelationshipDeleteError builds the error returned when a
// non-DETACH DELETE targets a node that still has relationships. The
// wording mirrors Neo4j's own "still has relationships" DELETE error so
// clients that pattern-match on that message keep working against
// NornicDB.
func residualRelationshipDeleteError(nodeID storage.NodeID) error {
	message := localization.CypherTransactionsDeleteResidualRelationships(string(nodeID))
	return &classifiedCypherError{
		cause:  localizedError(message, nil),
		code:   "Neo.ClientError.Schema.ConstraintValidationFailed",
		detail: "DeleteConnectedNode",
	}
}

// staticDeleteTargetTypeError keeps known non-entity values as compile-time
// errors, while widened UNWIND map elements remain runtime checks. Strings
// and lists retain the existing NornicDB DELETE extensions.
func staticDeleteTargetTypeError(ctx context.Context, clause string, scope staticTypeScope) error {
	targets, _, _ := deleteClauseTargets(clause)
	// Undefined targets retain the existing DELETE scope error owner.
	scope.complete = false
	checker := staticOperatorChecker{scope: scope}
	for _, target := range targets {
		operand, err := checker.check(ctx, strings.TrimSpace(target))
		if err != nil {
			return err
		}
		// A string target is NornicDB's DELETE-by-id extension, and a list
		// deletes its elements: reject a target none of whose types is one.
		if operand.excludes(isDeleteTargetTypeName) {
			return typeNameMismatchError("Node, Path or Relationship", operand.typeName())
		}
	}
	return nil
}

package cypher

import (
	"context"
	"strconv"
	"strings"

	"github.com/orneryd/nornicdb/pkg/storage"
)

func (e *StorageExecutor) tryExecuteBoundRelationshipDelete(
	ctx context.Context,
	matchSegment string,
	cypher string,
	deleteVars string,
	detach bool,
) (*ExecuteResult, bool, error) {
	matchSegment = strings.TrimSpace(matchSegment)
	_, inTransactionWrapper := e.getStorage(ctx).(*transactionStorageWrapper)
	if detach || strings.Contains(deleteVars, ",") {
		return nil, false, nil
	}
	deleteVar := strings.TrimSpace(deleteVars)
	if deleteVar == "" {
		return nil, false, nil
	}
	limit := -1
	baseMatchSegment := matchSegment
	if !isSimpleBoundRelationshipDeleteMatchSegment(matchSegment) {
		limitedSegment, limitedRows, ok := parseBoundRelationshipDeleteWithLimitSegment(matchSegment, deleteVar)
		if !ok {
			return nil, false, nil
		}
		baseMatchSegment = limitedSegment
		limit = limitedRows
	}

	if !patternMapsAreConstant(baseMatchSegment) {
		return nil, false, nil
	}

	pseudo := baseMatchSegment + " RETURN __delete_probe__"
	returnIdx := findKeywordIndex(pseudo, "RETURN")
	if returnIdx <= 0 {
		return nil, false, nil
	}
	whereIdx := lastKeywordIndexBefore(pseudo, "WHERE", returnIdx)
	clauses := splitMatchClauses(pseudo, whereIdx, returnIdx)
	if len(clauses) != 2 {
		return nil, false, nil
	}

	sourcePattern, parseErr := readNodePattern(ctx, clauses[0], patternPropertyKeys)
	if parseErr != nil {
		return nil, true, parseErr
	}
	if sourcePattern.variable == "" {
		return nil, false, nil
	}
	relPatternText := strings.TrimSpace(clauses[1])
	relMatch := e.parseTraversalPatternStructure(ctx, relPatternText)
	if relMatch == nil || relMatch.IsChained {
		return nil, false, nil
	}
	if relMatch.StartNode.variable != sourcePattern.variable {
		return nil, false, nil
	}
	if relMatch.Relationship.Variable != deleteVar {
		return nil, false, nil
	}
	if relMatch.Relationship.MinHops != 1 || relMatch.Relationship.MaxHops != 1 {
		return nil, false, nil
	}
	if relMatch.Relationship.Direction != "outgoing" && relMatch.Relationship.Direction != "incoming" && relMatch.Relationship.Direction != "both" {
		return nil, false, nil
	}

	whereClause := ""
	if whereIdx > 0 && whereIdx < returnIdx {
		whereClause = strings.TrimSpace(pseudo[whereIdx+len("WHERE") : returnIdx])
	}

	rowCtx, sourceText, err := e.preparePatternRow(ctx, clauses[0], nil)
	if err != nil {
		return nil, true, err
	}
	sourcePattern, err = e.parseNodePattern(rowCtx, sourceText)
	if err != nil {
		return nil, true, err
	}
	sources, err := e.collectBoundRelationshipDeleteSources(rowCtx, sourcePattern, inTransactionWrapper)
	if err != nil {
		return nil, true, err
	}
	if len(sources) == 0 {
		result := &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}, Stats: &QueryStats{}}
		e.applyDeleteReturnProjection(result, cypher, deleteVar, singleDeleteProjectionInfo(deleteVar, deleteProjectionRelationship))
		return result, true, nil
	}

	typeSet := buildRelTypeSet(relMatch.Relationship.Types)
	store := e.getStorage(ctx)
	edgeIDs := make([]storage.EdgeID, 0)
	seen := make(map[storage.EdgeID]struct{})
	for _, source := range sources {
		if source == nil {
			continue
		}
		rowCtx, rowPattern, err := e.preparePatternRow(ctx, relPatternText, map[string]interface{}{sourcePattern.variable: source})
		if err != nil {
			return nil, true, err
		}
		rowMatch := e.parseTraversalPattern(rowCtx, rowPattern)
		if failure := getExpressionFailure(rowCtx); failure != nil {
			return nil, true, failure
		}
		if rowMatch == nil || !e.pipelineNodeMatchesPattern(source, rowMatch.StartNode) {
			continue
		}
		candidates, err := e.boundRelationshipDeleteCandidateEdges(store, source.ID, rowMatch.Relationship.Direction)
		if err != nil {
			return nil, true, err
		}
		for _, edge := range candidates {
			if edge == nil || !relationshipTypeAllowed(edge.Type, rowMatch.Relationship.Types, typeSet) {
				continue
			}
			if len(rowMatch.Relationship.Properties) > 0 && !e.edgeMatchesProps(edge, rowMatch.Relationship.Properties) {
				continue
			}
			target, ok, err := e.boundRelationshipDeleteTargetNode(store, source.ID, edge, rowMatch.Relationship.Direction)
			if err != nil {
				return nil, true, err
			}
			if !ok || !e.matchesEndPattern(target, &rowMatch.EndNode) {
				continue
			}
			if whereClause != "" {
				pathCtx := PathContext{
					nodes: map[string]*storage.Node{
						rowMatch.StartNode.variable: source,
					},
					rels: map[string]*storage.Edge{
						deleteVar: edge,
					},
				}
				if rowMatch.EndNode.variable != "" {
					pathCtx.nodes[rowMatch.EndNode.variable] = target
				}
				if !e.evaluateWhereOnPath(rowCtx, whereClause, pathCtx) {
					continue
				}
			}
			if _, exists := seen[edge.ID]; exists {
				continue
			}
			seen[edge.ID] = struct{}{}
			edgeIDs = append(edgeIDs, edge.ID)
			if limit > 0 && len(edgeIDs) >= limit {
				break
			}
		}
		if limit > 0 && len(edgeIDs) >= limit {
			break
		}
	}

	result := &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}, Stats: &QueryStats{}}
	if len(edgeIDs) > 0 {
		if err := store.BulkDeleteEdges(edgeIDs); err != nil {
			return nil, true, err
		}
		result.Stats.RelationshipsDeleted = len(edgeIDs)
		for _, edgeID := range edgeIDs {
			e.notifyEdgeMutated(string(edgeID))
		}
	}
	e.applyDeleteReturnProjection(result, cypher, deleteVar, singleDeleteProjectionInfo(deleteVar, deleteProjectionRelationship))
	return result, true, nil
}

func (e *StorageExecutor) collectBoundRelationshipDeleteSources(ctx context.Context, sourcePattern nodePatternInfo, inTransactionWrapper bool) ([]*storage.Node, error) {
	if !inTransactionWrapper {
		return e.collectNodesWithStreaming(ctx, sourcePattern.labels, sourcePattern.properties, sourcePattern.variable, "", -1)
	}

	store := e.getStorage(ctx)
	if txWrapper, ok := store.(*transactionStorageWrapper); !ok || !txWrapper.tx.HasPendingNodeMutations() {
		return e.collectNodesWithStreaming(ctx, sourcePattern.labels, sourcePattern.properties, sourcePattern.variable, "", -1)
	}

	var nodes []*storage.Node
	var err error
	if len(sourcePattern.labels) > 0 {
		nodes, err = storage.GetNodesByLabelWithContext(ctx, store, sourcePattern.labels[0])
	} else {
		nodes, err = storage.AllNodesWithContext(ctx, store)
	}
	if err != nil {
		return nil, err
	}

	filtered := make([]*storage.Node, 0, len(nodes))
	hideSystemNodes := shouldHideSystemNodes(store)
	for _, node := range nodes {
		if node == nil {
			continue
		}
		if hideSystemNodes && isSystemNode(node) {
			continue
		}
		if len(sourcePattern.labels) > 0 && !mergeNodeHasLabels(node, sourcePattern.labels) {
			continue
		}
		if len(sourcePattern.properties) > 0 && !e.nodeMatchesProps(node, sourcePattern.properties) {
			continue
		}
		filtered = append(filtered, node)
	}
	return filtered, nil
}

func (e *StorageExecutor) boundRelationshipDeleteCandidateEdges(store storage.Engine, nodeID storage.NodeID, direction string) ([]*storage.Edge, error) {
	var edges []*storage.Edge
	switch direction {
	case "outgoing":
		outgoing, err := store.GetOutgoingEdges(nodeID)
		if err != nil {
			return nil, err
		}
		edges = append(edges, outgoing...)
	case "incoming":
		incoming, err := store.GetIncomingEdges(nodeID)
		if err != nil {
			return nil, err
		}
		edges = append(edges, incoming...)
	case "both":
		outgoing, err := store.GetOutgoingEdges(nodeID)
		if err != nil {
			return nil, err
		}
		incoming, err := store.GetIncomingEdges(nodeID)
		if err != nil {
			return nil, err
		}
		edges = append(edges, outgoing...)
		edges = append(edges, incoming...)
	}
	return edges, nil
}

func parseBoundRelationshipDeleteWithLimitSegment(matchSegment, deleteVar string) (string, int, bool) {
	for _, blocked := range []string{"ORDER BY", "SKIP", "CALL", "UNWIND", "OPTIONAL MATCH"} {
		if containsKeywordOutsideStrings(matchSegment, blocked) {
			return "", 0, false
		}
	}
	withIdx := findKeywordIndex(matchSegment, "WITH")
	if withIdx <= 0 {
		return "", 0, false
	}
	baseMatch := strings.TrimSpace(matchSegment[:withIdx])
	if !isSimpleBoundRelationshipDeleteMatchSegment(baseMatch) {
		return "", 0, false
	}
	withPart := strings.TrimSpace(matchSegment[withIdx+len("WITH"):])
	limitIdx := findKeywordIndex(withPart, "LIMIT")
	if limitIdx <= 0 {
		return "", 0, false
	}
	withVar := strings.TrimSpace(withPart[:limitIdx])
	if withVar != deleteVar {
		return "", 0, false
	}
	limitLiteral := strings.TrimSpace(withPart[limitIdx+len("LIMIT"):])
	fields := strings.Fields(limitLiteral)
	if len(fields) != 1 {
		return "", 0, false
	}
	limitN, err := strconv.Atoi(fields[0])
	if err != nil || limitN <= 0 {
		return "", 0, false
	}
	return baseMatch, limitN, true
}

func isSimpleBoundRelationshipDeleteMatchSegment(matchSegment string) bool {
	if strings.TrimSpace(matchSegment) == "" {
		return false
	}
	for _, blocked := range []string{"WITH", "LIMIT", "SKIP", "ORDER BY", "CALL", "UNWIND", "OPTIONAL MATCH"} {
		if containsKeywordOutsideStrings(matchSegment, blocked) {
			return false
		}
	}
	return true
}

func (e *StorageExecutor) boundRelationshipDeleteTargetNode(
	store storage.Engine,
	sourceID storage.NodeID,
	edge *storage.Edge,
	direction string,
) (*storage.Node, bool, error) {
	var targetID storage.NodeID
	switch direction {
	case "outgoing":
		if edge.StartNode != sourceID {
			return nil, false, nil
		}
		targetID = edge.EndNode
	case "incoming":
		if edge.EndNode != sourceID {
			return nil, false, nil
		}
		targetID = edge.StartNode
	case "both":
		if edge.StartNode == sourceID {
			targetID = edge.EndNode
		} else if edge.EndNode == sourceID {
			targetID = edge.StartNode
		} else {
			return nil, false, nil
		}
	default:
		return nil, false, nil
	}
	target, err := e.getQueryNode(store, targetID)
	if err != nil || target == nil {
		return nil, false, nil
	}
	return target, true, nil
}

func relationshipTypeAllowed(edgeType string, allowed []string, allowedSet map[string]struct{}) bool {
	if len(allowed) == 0 {
		return true
	}
	if len(allowed) == 1 {
		return edgeType == allowed[0]
	}
	_, ok := allowedSet[edgeType]
	return ok
}

// Package cypher implements EXPLAIN and PROFILE query execution modes.
//
// EXPLAIN shows the query execution plan without executing the query.
// PROFILE executes the query and shows the plan with runtime statistics.
//
// # ELI12 (Explain Like I'm 12)
//
// Imagine you're planning a trip. EXPLAIN is like looking at the map and saying
// "I'll take this road, then that highway" without actually driving.
// PROFILE is like actually driving the route and noting "that road took 10 minutes,
// the highway took 20 minutes, I passed 50 cars."
//
// # Neo4j Compatibility
//
// This implementation matches Neo4j's execution modes:
// - EXPLAIN: Returns plan without execution
// - PROFILE: Returns plan with actual execution statistics
package cypher

import (
	"context"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/orneryd/nornicdb/pkg/localization"
)

// ExecutionMode represents how a query should be executed
type ExecutionMode string

const (
	ModeNormal  ExecutionMode = "normal"
	ModeExplain ExecutionMode = "EXPLAIN"
	ModeProfile ExecutionMode = "PROFILE"
)

// PlanOperator represents a single operator in the execution plan
type PlanOperator struct {
	// Operator type (e.g., "NodeByLabelScan", "Filter", "Expand")
	OperatorType string `json:"operatorType"`

	// Human-readable description
	Description string `json:"description"`

	// Operator-specific arguments
	Arguments map[string]interface{} `json:"arguments,omitempty"`

	// Variables introduced by this operator
	Identifiers []string `json:"identifiers,omitempty"`

	// Child operators (execution flows bottom-up)
	Children []*PlanOperator `json:"children,omitempty"`

	// Cost estimation (for EXPLAIN and PROFILE)
	EstimatedRows int64 `json:"estimatedRows"`

	// Actual statistics (only for PROFILE)
	ActualRows int64         `json:"rows,omitempty"`
	DBHits     int64         `json:"dbHits,omitempty"`
	Time       time.Duration `json:"time,omitempty"`
}

// ExecutionPlan represents the complete query execution plan
type ExecutionPlan struct {
	// Root operator of the plan
	Root *PlanOperator `json:"root"`

	// Query being explained/profiled
	Query string `json:"query"`

	// Execution mode (EXPLAIN or PROFILE)
	Mode ExecutionMode `json:"mode"`

	// Total statistics (only for PROFILE)
	TotalDBHits int64         `json:"totalDbHits,omitempty"`
	TotalTime   time.Duration `json:"totalTime,omitempty"`
	TotalRows   int64         `json:"totalRows,omitempty"`
}

// parseExecutionMode extracts EXPLAIN or PROFILE prefix from a query
func parseExecutionMode(query string) (ExecutionMode, string) {
	mode, statement, _ := readExecutionModes(query, ModeNormal)
	return mode, statement
}

// executeExplain returns the execution plan without executing the query
func (e *StorageExecutor) executeExplain(ctx context.Context, query string) (*ExecuteResult, error) {
	query, err := executionModeStatement(ModeExplain, query)
	if err != nil {
		return nil, err
	}
	if endsInFinish(ctx, query) {
		query += " FINISH"
	}
	// The execution option reader owns WITH EMBEDDING. Plan the same graph
	// statement that Execute admitted after consuming that option.
	scopeQuery, _ := stripWithEmbeddingSuffix(query)
	if err := validateQueryBodyComposition(ctx, scopeQuery); err != nil {
		return nil, err
	}
	columns, err := e.StatementResultColumnsContext(ctx, scopeQuery)
	if err != nil {
		return nil, err
	}
	if indexASCIIFold(query, "shortestpath") >= 0 {
		if err := e.validateMatchSemanticScopes(ctx, scopeQuery, cypherVersionFromContext(ctx) == "25"); err != nil {
			return nil, err
		}
	}
	plan, err := e.buildExecutionPlan(scopeQuery)
	if err != nil {
		return nil, localizedError(localization.CypherCoreExecutionPlanBuildFailed(err), err)
	}
	plan.Mode = ModeExplain
	result := &ExecuteResult{
		Columns: columns,
		Rows:    [][]interface{}{},
		Stats:   &QueryStats{},
	}
	return e.attachPlanMetadata(result, plan), nil
}

// executeProfile executes the query and returns the plan with statistics
func (e *StorageExecutor) executeProfile(ctx context.Context, query string) (*ExecuteResult, error) {
	query, err := executionModeStatement(ModeProfile, query)
	if err != nil {
		return nil, err
	}
	if endsInFinish(ctx, query) {
		query += " FINISH"
	}
	// Resolve participant signatures through the same owner as EXPLAIN and
	// planning. Incomplete metadata cannot authorize execution effects.
	scopeQuery, _ := stripWithEmbeddingSuffix(query)
	columns, err := e.StatementResultColumnsContext(ctx, scopeQuery)
	if err != nil {
		return nil, err
	}
	// Build the plan first
	plan, err := e.buildExecutionPlan(scopeQuery)
	if err != nil {
		return nil, localizedError(localization.CypherCoreExecutionPlanBuildFailed(err), err)
	}
	plan.Mode = ModeProfile

	// PROFILE's inner execution must bypass the result cache on both read and
	// write: Neo4j profiles actual execution, and a result object shared with
	// the cache would otherwise be mutated by attachPlanMetadata below,
	// leaking plan metadata into ordinary cached reads of the same query.
	ctx = context.WithValue(ctx, profileExecutionKey{}, true)

	// Execute the actual query to collect statistics
	startTime := time.Now()
	result, execErr := e.executeRouted(ctx, query, nil)
	totalTime := time.Since(startTime)

	// A statement that fails fails its PROFILE too, as in Neo4j: the error
	// is the statement's, not a plan row describing it.
	if execErr != nil {
		return nil, execErr
	}

	// Update plan with actual statistics
	plan.TotalTime = totalTime
	if result != nil {
		plan.TotalRows = int64(len(result.Rows))
		e.updatePlanWithStats(plan.Root, result)
	}

	// Calculate total DB hits (estimate based on operations)
	plan.TotalDBHits = e.estimateDBHits(plan.Root)

	// TRC-16: emit per-operator spans with estimated/actual rows.
	emitOperatorSpans(ctx, plan.Root)

	if result == nil {
		result = &ExecuteResult{
			Columns: []string{},
			Rows:    [][]interface{}{},
			Stats:   &QueryStats{},
		}
	}
	if err := verifyResultColumns(result.Columns, columns); err != nil {
		return nil, err
	}

	return e.attachPlanMetadata(result, plan), nil
}

// buildExecutionPlan creates an execution plan for a query
func (e *StorageExecutor) buildExecutionPlan(query string) (*ExecutionPlan, error) {
	plan := &ExecutionPlan{
		Query: query,
		Mode:  ModeNormal,
	}

	// Analyze query and build operator tree
	root, err := e.analyzeQuery(query)
	if err != nil {
		return nil, err
	}
	plan.Root = root

	return plan, nil
}

// analyzeQuery analyzes a Cypher query and builds the operator tree
func (e *StorageExecutor) analyzeQuery(query string) (*PlanOperator, error) {
	// Build operators in query clause order (Neo4j-style plan chain).
	type plannedClause struct {
		idx int
		op  *PlanOperator
	}
	clauses := make([]plannedClause, 0, 12)

	add := func(idx int, op *PlanOperator) {
		if idx >= 0 && op != nil {
			clauses = append(clauses, plannedClause{idx: idx, op: op})
		}
	}

	if idx := findKeywordIndex(query, "MATCH"); idx >= 0 {
		add(idx, e.analyzeMatchClause(query))
	}
	if idx := findKeywordIndex(query, "CALL"); idx >= 0 {
		add(idx, e.analyzeCallClause(query))
	}
	if idx := findKeywordIndex(query, "WHERE"); idx >= 0 {
		add(idx, e.analyzeWhereClause(query))
	}
	if idx := findKeywordIndex(query, "WITH"); idx >= 0 {
		add(idx, &PlanOperator{
			OperatorType:  "Projection",
			Description:   "Project intermediate results",
			EstimatedRows: 100,
		})
	}
	if idx := findKeywordIndex(query, "CREATE"); idx >= 0 {
		add(idx, &PlanOperator{
			OperatorType:  "Create",
			Description:   "Create nodes and relationships",
			EstimatedRows: 1,
		})
	}
	if idx := findKeywordIndex(query, "MERGE"); idx >= 0 {
		add(idx, &PlanOperator{
			OperatorType:  "Merge",
			Description:   "Merge (create if not exists)",
			EstimatedRows: 1,
		})
	}
	if idx := findKeywordIndex(query, "SET"); idx >= 0 {
		add(idx, &PlanOperator{
			OperatorType:  "Set",
			Description:   "Set properties",
			EstimatedRows: 100,
		})
	}
	if idx := findKeywordIndex(query, "REMOVE"); idx >= 0 {
		add(idx, &PlanOperator{
			OperatorType:  "Remove",
			Description:   "Remove labels/properties",
			EstimatedRows: 100,
		})
	}
	if idx := findKeywordIndex(query, "DETACH DELETE"); idx >= 0 {
		add(idx, e.analyzeDeleteClause(query, true))
	} else if idx := findKeywordIndex(query, "DELETE"); idx >= 0 {
		add(idx, e.analyzeDeleteClause(query, false))
	}
	if idx := findKeywordIndex(query, "ORDER BY"); idx >= 0 {
		add(idx, &PlanOperator{
			OperatorType:  "Sort",
			Description:   "Sort results",
			EstimatedRows: 100,
		})
	}
	if idx := findKeywordIndex(query, "LIMIT"); idx >= 0 {
		add(idx, e.analyzeLimitSkip(query))
	} else if idx := findKeywordIndex(query, "SKIP"); idx >= 0 {
		add(idx, e.analyzeLimitSkip(query))
	}
	if idx := findKeywordIndex(query, "RETURN"); idx >= 0 {
		add(idx, e.analyzeReturnClause(query))
	}

	sort.SliceStable(clauses, func(i, j int) bool {
		return clauses[i].idx < clauses[j].idx
	})

	operators := make([]*PlanOperator, 0, len(clauses))
	for _, c := range clauses {
		operators = append(operators, c.op)
	}

	// Build the operator tree (chain operators bottom-up)
	if len(operators) == 0 {
		return &PlanOperator{
			OperatorType:  "EmptyResult",
			Description:   "No operations",
			EstimatedRows: 0,
		}, nil
	}

	// Chain operators: each operator is a child of the next
	for i := len(operators) - 1; i > 0; i-- {
		operators[i].Children = []*PlanOperator{operators[i-1]}
	}

	return operators[len(operators)-1], nil
}

// analyzeMatchClause analyzes a MATCH clause and returns appropriate operators
func (e *StorageExecutor) analyzeMatchClause(query string) *PlanOperator {
	upper := upperASCII(query)

	// Check for shortestPath
	if strings.Contains(upper, "SHORTESTPATH") {
		return &PlanOperator{
			OperatorType:  "ShortestPath",
			Description:   "Find shortest path using BFS",
			EstimatedRows: 1,
			Arguments: map[string]interface{}{
				"algorithm": "BFS",
			},
		}
	}

	// Check for variable-length path
	if containsVariableLengthPathPattern(query) {
		return &PlanOperator{
			OperatorType:  "VarLengthExpand",
			Description:   "Variable length path expansion",
			EstimatedRows: 100,
		}
	}

	// Check for relationship pattern
	if containsRelationshipPattern(query) {
		return &PlanOperator{
			OperatorType:  "Expand",
			Description:   "Expand relationships",
			EstimatedRows: 100,
			Children: []*PlanOperator{
				e.analyzeNodeScan(query),
			},
		}
	}

	// Simple node scan
	return e.analyzeNodeScan(query)
}

// analyzeNodeScan determines the type of node scan needed.
// When the storage schema is available, it checks for actual index existence
// and reports index usage or rejection reasons in the plan arguments.
func (e *StorageExecutor) analyzeNodeScan(query string) *PlanOperator {
	// Check for label in pattern (n:Label)
	if label, ok := extractFirstNodeLabelFromQuery(query); ok {

		// Check for property filter (n:Label {prop: value})
		if strings.Contains(query, "{") {
			args := map[string]interface{}{
				"label": label,
			}
			// Check actual index availability from schema.
			e.annotateIndexDiagnostics(args, label, query)

			return &PlanOperator{
				OperatorType:  "NodeIndexSeek",
				Description:   fmt.Sprintf("Index seek on :%s", label),
				EstimatedRows: 10,
				Arguments:     args,
				Identifiers:   []string{"n"},
			}
		}

		args := map[string]interface{}{
			"label": label,
		}
		e.annotateIndexDiagnostics(args, label, query)

		return &PlanOperator{
			OperatorType:  "NodeByLabelScan",
			Description:   fmt.Sprintf("Scan all :%s nodes", label),
			EstimatedRows: 1000,
			Arguments:     args,
			Identifiers:   []string{"n"},
		}
	}

	// No label - full scan
	return &PlanOperator{
		OperatorType:  "AllNodesScan",
		Description:   "Scan all nodes",
		EstimatedRows: 10000,
		Identifiers:   []string{"n"},
	}
}

// annotateIndexDiagnostics adds index usage/rejection diagnostics to the plan
// operator arguments. This makes tuning deterministic by exposing whether an
// index was available, which properties are indexed, and why it was rejected.
func (e *StorageExecutor) annotateIndexDiagnostics(args map[string]interface{}, label, query string) {
	schema := e.storage.GetSchema()
	if schema == nil {
		args["indexStatus"] = "no_schema"
		return
	}

	// Collect all indexes for this label.
	indexes := schema.GetIndexes()
	var labelIndexes []string
	for _, raw := range indexes {
		idx, ok := raw.(map[string]interface{})
		if !ok {
			continue
		}
		idxLabel, _ := idx["label"].(string)
		if strings.TrimSpace(idxLabel) != label {
			continue
		}
		prop := ""
		if p, ok := idx["property"].(string); ok {
			prop = p
		}
		if prop == "" {
			if props, ok := idx["properties"].([]string); ok && len(props) > 0 {
				prop = strings.Join(props, ",")
			}
		}
		idxType, _ := idx["type"].(string)
		labelIndexes = append(labelIndexes, fmt.Sprintf("%s(%s)", idxType, prop))
	}

	if len(labelIndexes) == 0 {
		args["indexStatus"] = "no_index_for_label"
		return
	}

	args["indexStatus"] = "available"
	args["availableIndexes"] = labelIndexes

	// Check WHERE clause for predicate shapes that prevent index use.
	upper := upperASCII(query)
	if strings.Contains(upper, "COALESCE(") {
		args["indexRejectionRisk"] = "function_wrapping (coalesce)"
	}
	if strings.Contains(upper, "TOLOWER(") || strings.Contains(upper, "TOUPPER(") {
		args["indexRejectionRisk"] = "function_wrapping (toLower/toUpper)"
	}
}

// analyzeWhereClause analyzes WHERE conditions
func (e *StorageExecutor) analyzeWhereClause(query string) *PlanOperator {
	// Extract WHERE clause
	whereIdx := findKeywordIndex(query, "WHERE")
	if whereIdx < 0 {
		return nil
	}

	// Find end of WHERE clause
	endIdx := len(query)
	for _, keyword := range []string{"RETURN", "ORDER", "LIMIT", "SKIP", "WITH", "CREATE", "SET", "REMOVE", "DETACH DELETE", "DELETE"} {
		if idx := findKeywordIndex(query[whereIdx:], keyword); idx > 0 {
			if whereIdx+idx < endIdx {
				endIdx = whereIdx + idx
			}
		}
	}

	whereClause := strings.TrimSpace(query[whereIdx+5 : endIdx])

	return &PlanOperator{
		OperatorType:  "Filter",
		Description:   fmt.Sprintf("Filter: %s", truncate(whereClause, 50)),
		EstimatedRows: 100,
		Arguments: map[string]interface{}{
			"predicate": whereClause,
		},
	}
}

func (e *StorageExecutor) analyzeDeleteClause(query string, detach bool) *PlanOperator {
	startKeyword := "DELETE"
	operator := "Delete"
	if detach {
		startKeyword = "DETACH DELETE"
		operator = "DetachDelete"
	}
	deleteIdx := findKeywordIndex(query, startKeyword)
	if deleteIdx < 0 {
		return &PlanOperator{
			OperatorType:  operator,
			Description:   "Delete matched entities",
			EstimatedRows: 100,
		}
	}

	endIdx := len(query)
	for _, keyword := range []string{"RETURN", "WITH", "ORDER BY", "LIMIT", "SKIP"} {
		if idx := findKeywordIndex(query[deleteIdx:], keyword); idx > 0 {
			candidate := deleteIdx + idx
			if candidate < endIdx {
				endIdx = candidate
			}
		}
	}

	deleteClause := strings.TrimSpace(query[deleteIdx:endIdx])
	strip := startKeyword + " "
	if strings.HasPrefix(upperASCII(deleteClause), strip) {
		deleteClause = strings.TrimSpace(deleteClause[len(strip):])
	}
	desc := "Delete matched entities"
	if deleteClause != "" {
		desc = fmt.Sprintf("%s %s", operator, truncate(deleteClause, 50))
	}

	return &PlanOperator{
		OperatorType:  operator,
		Description:   desc,
		EstimatedRows: 100,
		Arguments: map[string]interface{}{
			"details": deleteClause,
		},
	}
}

// analyzeReturnClause analyzes the RETURN clause
func (e *StorageExecutor) analyzeReturnClause(query string) *PlanOperator {
	returnIdx := findKeywordIndex(query, "RETURN")
	if returnIdx < 0 {
		return nil
	}

	// Extract RETURN items
	returnClause := query[returnIdx+6:]
	// Trim ORDER BY, LIMIT, etc.
	for _, keyword := range []string{"ORDER BY", "LIMIT", "SKIP"} {
		if idx := findKeywordIndex(returnClause, keyword); idx > 0 {
			returnClause = returnClause[:idx]
		}
	}
	returnClause = strings.TrimSpace(returnClause)

	// Check for aggregations
	hasAggregation := containsAggregateFunc(returnClause)

	if hasAggregation {
		return &PlanOperator{
			OperatorType:  "EagerAggregation",
			Description:   "Aggregate results",
			EstimatedRows: 1,
			Arguments: map[string]interface{}{
				"expressions": returnClause,
			},
		}
	}

	// Check for DISTINCT
	if _, distinct := cutDistinct(returnClause); distinct {
		return &PlanOperator{
			OperatorType:  "Distinct",
			Description:   "Remove duplicates",
			EstimatedRows: 100,
		}
	}

	return &PlanOperator{
		OperatorType:  "ProduceResults",
		Description:   "Return results",
		EstimatedRows: 100,
		Arguments: map[string]interface{}{
			"columns": returnClause,
		},
	}
}

func containsVariableLengthPathPattern(query string) bool {
	for i := 0; i < len(query); i++ {
		if query[i] != '[' {
			continue
		}
		inside, _, ok := extractBracketSection(query[i:])
		if !ok {
			continue
		}
		inner := strings.TrimSpace(inside)
		if !strings.HasPrefix(inner, "*") {
			continue
		}
		rangeExpr := strings.TrimSpace(inner[1:])
		if rangeExpr == "" {
			return true // [*]
		}
		dotIdx := strings.Index(rangeExpr, "..")
		if dotIdx < 0 {
			continue
		}
		left := strings.TrimSpace(rangeExpr[:dotIdx])
		right := strings.TrimSpace(rangeExpr[dotIdx+2:])
		if (left == "" || isAllDigits(left)) && (right == "" || isAllDigits(right)) {
			return true // [*1..3], [*..5], [*1..]
		}
	}
	return false
}

func extractFirstNodeLabelFromQuery(query string) (string, bool) {
	for i := 0; i < len(query); i++ {
		if query[i] != '(' {
			continue
		}
		inside, _, ok := extractParenSection(query[i:])
		if !ok {
			continue
		}
		if label, ok := extractLabelFromNodeSection(inside); ok {
			return label, true
		}
	}
	return "", false
}

func extractLabelFromNodeSection(inside string) (string, bool) {
	s := strings.TrimSpace(inside)
	if s == "" {
		return "", false
	}
	if strings.HasPrefix(s, ":") {
		label, _, ok := parseIdentifierToken(strings.TrimSpace(s[1:]))
		return label, ok
	}
	if varName, rest, ok := parseIdentifierToken(s); ok {
		_ = varName
		rest = strings.TrimSpace(rest)
		if strings.HasPrefix(rest, ":") {
			label, _, ok := parseIdentifierToken(strings.TrimSpace(rest[1:]))
			return label, ok
		}
	}
	return "", false
}

func isAllDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

// analyzeLimitSkip analyzes LIMIT and SKIP clauses
func (e *StorageExecutor) analyzeLimitSkip(query string) *PlanOperator {
	upper := upperASCII(query)

	op := &PlanOperator{
		OperatorType: "Limit",
		Arguments:    make(map[string]interface{}),
	}

	// Extract LIMIT value
	if limit := ExtractLimitString(query); limit != "" {
		op.Arguments["limit"] = limit
		op.Description = fmt.Sprintf("Limit to %s rows", limit)
	}

	// Extract SKIP value
	if skip := ExtractSkipString(query); skip != "" {
		op.Arguments["skip"] = skip
		if op.Description != "" {
			op.Description += fmt.Sprintf(", skip %s", skip)
		} else {
			op.Description = fmt.Sprintf("Skip %s rows", skip)
		}
	}

	// Estimate rows based on limit
	if _, ok := op.Arguments["limit"]; ok {
		op.EstimatedRows = 10 // Use limit as estimate
	} else if strings.Contains(upper, "SKIP") {
		op.EstimatedRows = 100
	}

	return op
}

// analyzeCallClause analyzes CALL procedure invocations
func (e *StorageExecutor) analyzeCallClause(query string) *PlanOperator {
	procName := "unknown"
	if callIdx := keywordIndexFrom(query, "CALL", 0, defaultKeywordScanOpts()); callIdx >= 0 {
		callEnd, ok := keywordSpanAt(query, callIdx, "CALL")
		if ok {
			rest := strings.TrimSpace(query[callEnd:])
			if name, _, ok := parseProcedureNameToken(rest); ok {
				procName = name
			}
		}
	}

	return &PlanOperator{
		OperatorType:  "ProcedureCall",
		Description:   fmt.Sprintf("Call %s", procName),
		EstimatedRows: 100,
		Arguments: map[string]interface{}{
			"procedure": procName,
		},
	}
}

func parseProcedureNameToken(s string) (string, string, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return "", "", false
	}
	start := 0
	for start < len(s) {
		_, rest, ok := parseIdentifierToken(s[start:])
		if !ok {
			return "", "", false
		}
		start = len(s) - len(rest)
		if strings.HasPrefix(rest, ".") {
			start++
			continue
		}
		return s[:start], rest, true
	}
	return "", "", false
}

// updatePlanWithStats updates plan operators with actual execution statistics
func (e *StorageExecutor) updatePlanWithStats(op *PlanOperator, result *ExecuteResult) {
	if op == nil {
		return
	}

	// Update actual rows for leaf operators
	op.ActualRows = int64(len(result.Rows))

	// Recursively update children
	for _, child := range op.Children {
		e.updatePlanWithStats(child, result)
	}
}

// estimateDBHits estimates database hits based on the plan
func (e *StorageExecutor) estimateDBHits(op *PlanOperator) int64 {
	if op == nil {
		return 0
	}

	var hits int64

	// Estimate based on operator type
	switch op.OperatorType {
	case "AllNodesScan":
		hits = op.EstimatedRows * 2 // Read node + properties
	case "NodeByLabelScan":
		hits = op.EstimatedRows * 2
	case "NodeIndexSeek":
		hits = op.EstimatedRows + 1 // Index lookup + node reads
	case "Expand":
		hits = op.EstimatedRows * 3 // Node + relationships + target nodes
	case "Filter":
		hits = op.EstimatedRows // Property access for filter
	case "ShortestPath":
		hits = op.EstimatedRows * 10 // BFS traversal hits
	default:
		hits = op.EstimatedRows
	}

	// Add child hits
	for _, child := range op.Children {
		hits += e.estimateDBHits(child)
	}

	op.DBHits = hits
	return hits
}

// planToResult converts an execution plan to an ExecuteResult
func (e *StorageExecutor) attachPlanMetadata(result *ExecuteResult, plan *ExecutionPlan) *ExecuteResult {
	// Add plan as metadata
	if result.Metadata == nil {
		result.Metadata = make(map[string]interface{})
	}
	result.Metadata["planString"] = formatPlan(plan)
	result.Metadata["plan"] = plan
	result.Metadata["planType"] = string(plan.Mode)

	return result
}

// Neo4jPlanMap renders the plan tree in the shape Neo4j puts in Bolt SUCCESS
// metadata and HTTP results: each node carries operatorType, identifiers,
// args (with EstimatedRows), and children; the profile form adds rows and
// dbHits. Bolt and HTTP both deliver this map so plans reach clients (#744).
func Neo4jPlanMap(plan *ExecutionPlan, profile bool) map[string]any {
	if plan == nil {
		return nil
	}
	return neo4jPlanOperatorMap(plan.Root, profile)
}

// profileExecutionKey marks PROFILE's inner execution so it neither serves nor
// populates the result cache (#744): a cached result object would otherwise be
// mutated by attachPlanMetadata and hand plan metadata to ordinary cached
// reads of the same query.
type profileExecutionKey struct{}

func profileExecutionBypassesCache(ctx context.Context) bool {
	bypass, _ := ctx.Value(profileExecutionKey{}).(bool)
	return bypass
}

func neo4jPlanOperatorMap(op *PlanOperator, profile bool) map[string]any {
	if op == nil {
		return nil
	}
	node := make(map[string]any, 4)
	node["operatorType"] = op.OperatorType
	if len(op.Identifiers) > 0 {
		node["identifiers"] = op.Identifiers
	}
	args := make(map[string]interface{}, len(op.Arguments)+1)
	for key, value := range op.Arguments {
		args[key] = value
	}
	if op.EstimatedRows > 0 {
		args["EstimatedRows"] = op.EstimatedRows
	}
	if len(args) > 0 {
		node["args"] = args
	}
	if len(op.Children) > 0 {
		children := make([]map[string]any, 0, len(op.Children))
		for _, child := range op.Children {
			if childMap := neo4jPlanOperatorMap(child, profile); childMap != nil {
				children = append(children, childMap)
			}
		}
		node["children"] = children
	}
	if profile {
		node["rows"] = op.ActualRows
		node["dbHits"] = op.DBHits
	}
	return node
}

// formatPlan formats the execution plan as a string (tree visualization)
func formatPlan(plan *ExecutionPlan) string {
	var sb strings.Builder

	sb.WriteString(fmt.Sprintf("+-%s-+\n", strings.Repeat("-", 60)))
	sb.WriteString(fmt.Sprintf("| %-60s |\n", fmt.Sprintf("%s %s", plan.Mode, "Query Plan")))
	sb.WriteString(fmt.Sprintf("+-%s-+\n", strings.Repeat("-", 60)))

	if plan.Mode == ModeProfile {
		sb.WriteString(fmt.Sprintf("| Total Time: %-47s |\n", plan.TotalTime.String()))
		sb.WriteString(fmt.Sprintf("| Total Rows: %-47d |\n", plan.TotalRows))
		sb.WriteString(fmt.Sprintf("| Total DB Hits: %-44d |\n", plan.TotalDBHits))
		sb.WriteString(fmt.Sprintf("+-%s-+\n", strings.Repeat("-", 60)))
	}

	formatOperator(&sb, plan.Root, 0, plan.Mode == ModeProfile)

	sb.WriteString(fmt.Sprintf("+-%s-+\n", strings.Repeat("-", 60)))

	return sb.String()
}

// formatOperator formats a single operator in the plan tree
func formatOperator(sb *strings.Builder, op *PlanOperator, depth int, showStats bool) {
	if op == nil {
		return
	}

	indent := strings.Repeat("  ", depth)
	prefix := "+-"
	if depth > 0 {
		prefix = "|" + indent + "+-"
	}

	// Operator line
	line := fmt.Sprintf("%s %s", prefix, op.OperatorType)
	if op.Description != "" && op.Description != op.OperatorType {
		line += fmt.Sprintf(" (%s)", truncate(op.Description, 40))
	}

	sb.WriteString(fmt.Sprintf("| %-60s |\n", line))

	// Statistics line for PROFILE mode
	if showStats {
		statsLine := fmt.Sprintf("%s|   Est: %d, Actual: %d, Hits: %d",
			indent, op.EstimatedRows, op.ActualRows, op.DBHits)
		sb.WriteString(fmt.Sprintf("| %-60s |\n", statsLine))
	} else {
		// Just show estimates for EXPLAIN
		statsLine := fmt.Sprintf("%s|   Estimated Rows: %d", indent, op.EstimatedRows)
		sb.WriteString(fmt.Sprintf("| %-60s |\n", statsLine))
	}

	// Format children
	for _, child := range op.Children {
		formatOperator(sb, child, depth+1, showStats)
	}
}

// truncate truncates a string to maxLen characters
func truncate(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	return s[:maxLen-3] + "..."
}

package cypher

import (
	"context"
	"maps"
	"reflect"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
)

// validateListOperands rejects, before any route executes the statement, a
// list position whose operand has a static type that is not a list, as
// Neo4j's compile-time type check does ("Type mismatch: expected List<T> but
// was Integer"). A list position is the operand after IN: the IN operator,
// all / any / none / single, list comprehensions, reduce and FOREACH. The
// operands checked are a whole literal (number, string, boolean, map) and a
// whole parameter bound to a non-null value that is not a list ("Type
// mismatch for parameter 'p': …"); `$p.list`, `$p[0]`, `'a' + x` and
// variables are expressions whose type is only known per row, where a value
// that isn't a list is a list of that one value (coerceToUnwindItems). Variables
// bound to a node, relationship or path are checked with their scope
// (graphListOperandTypeError).
func validateListOperands(ctx context.Context, cypher string, params map[string]interface{}) error {
	return forEachListOperand(cypher, func(start, in int) error {
		// FOREACH (x IN 5 | …) runs once with x = 5 in Neo4j, not a type error.
		if foreachDeclaration(cypher, in) || forIterationDeclaration(cypher, in) {
			return nil
		}
		end, typeName, parameter := staticListOperand(ctx, cypher, start, params)
		if typeName == "" || !wholeListOperand(cypher, end) {
			return nil
		}
		message := localization.CypherCoreListOperandTypeMismatch(typeName)
		if parameter != "" {
			message = localization.CypherCoreListParameterTypeMismatch(parameter, typeName)
		}
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidArgumentType", message)
	})
}

// forEachListOperand calls visit with the offset of each list-position
// operand in text (the operand after an IN keyword outside quotes) and the
// offset of that IN, stopping at the first error.
func forEachListOperand(text string, visit func(start, in int) error) error {
	for i := 0; i < len(text); i++ {
		if end, quoted := skipCypherLexicalToken(text, i); quoted {
			i = end - 1
			continue
		}
		if (text[i] != 'I' && text[i] != 'i') || i+1 >= len(text) || (text[i+1] != 'N' && text[i+1] != 'n') || (i > 0 && (isIdentByte(text[i-1]) || text[i-1] == ':' || text[i-1] == '.')) ||
			i+2 >= len(text) || isIdentByte(text[i+2]) {
			continue
		}
		if err := visit(queryGapEnd(text, i+2), i); err != nil {
			return err
		}
	}
	return nil
}

// wholeListOperand reports whether the operand ending at end is the whole
// list-position operand, not the start of a longer expression (n.list,
// n[0], x + y).
func wholeListOperand(text string, end int) bool {
	next := queryGapEnd(text, end)
	return next >= len(text) || strings.IndexByte(")],}|", text[next]) >= 0 || isIdentByte(text[next])
}

// graphListOperandTypeError is Neo4j's compile-time SyntaxError for a list
// position given a variable bound to a node, relationship or path ("Type
// mismatch: expected List<T> but was Node"), whatever the data: `1 IN n`,
// `[x IN p | …]`, `any(x IN r WHERE …)`, in projections, WHERE, SET values
// and subquery bodies. FOREACH (x IN n | …) is not a type error in Neo4j (it
// runs once). A list element declaration (`[n IN list | …]`) is not itself
// an operand and cannot change the type of a separate `IN n` operand.
func graphListOperandTypeError(text string, scope matchSemanticScope) error {
	return staticListOperandTypeError(text, staticTypeScope{kinds: scope})
}

func staticListOperandTypeError(text string, scope staticTypeScope) error {
	if len(scope.kinds) == 0 && len(scope.values) == 0 {
		return nil
	}
	return forEachListOperand(text, func(start, in int) error {
		end := start
		for end < len(text) && isIdentByte(text[end]) {
			end++
		}
		if end == start || !wholeListOperand(text, end) {
			return nil
		}
		name := text[start:end]
		typeName := scope.typeOf(name)
		if typeName == "" || mayBeListType(typeName) {
			return nil
		}
		if foreachDeclaration(text, in) || forIterationDeclaration(text, in) || localVariableShadowsAt(text, start, name) {
			return nil
		}
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidArgumentType", localization.CypherCoreListOperandTypeMismatch(typeName))
	})
}

// mayBeListType reports whether a static type is a list or names one among
// its choices (a property value's type may be a List<T>).
func mayBeListType(typeName string) bool {
	// The owner's admission: a null alternative fits too.
	return typeName != "" && !typedOperand(typeName).proved().excludes(isListTypeName)
}

// foreachDeclaration reports whether the IN at offset in is FOREACH's own
// (`FOREACH (x IN …`).
func foreachDeclaration(text string, in int) bool {
	if !containsFold(text[:in], "FOREACH") {
		return false
	}
	opts := defaultKeywordScanOpts()
	opts.SkipParens = false
	opts.SkipBrackets = false
	for from := 0; from < in; {
		start := keywordIndexFrom(text, "FOREACH", from, opts)
		if start < 0 || start >= in {
			return false
		}
		open := queryGapEnd(text, start+len("FOREACH"))
		if open < len(text) && text[open] == '(' {
			_, end, ok := scanIdentifierToken(text, queryGapEnd(text, open+1))
			if ok && queryGapEnd(text, end) == in {
				return true
			}
		}
		from = start + len("FOREACH")
	}
	return false
}

// forIterationDeclaration reports whether the IN at offset in is a FOR
// iteration clause's own (`FOR x IN …`). FOR iterates like UNWIND, coercing a
// non-list operand to a single item, so its operand is not a list type error.
func forIterationDeclaration(text string, in int) bool {
	if !containsFold(text[:in], "FOR") {
		return false
	}
	opts := defaultKeywordScanOpts()
	opts.SkipParens = false
	opts.SkipBrackets = false
	for from := 0; from < in; {
		start := keywordIndexFrom(text, "FOR", from, opts)
		if start < 0 || start >= in {
			return false
		}
		nameStart := queryGapEnd(text, start+len("FOR"))
		if nameStart < in {
			if _, nameEnd, ok := scanIdentifierToken(text, nameStart); ok && queryGapEnd(text, nameEnd) == in {
				return true
			}
		}
		from = start + len("FOR")
	}
	return false
}

// localBinding is an expression that binds variables of its own, closing at
// text[close]: a list comprehension [v IN list WHERE … | …], a named pattern
// comprehension [p = (a)-->(b) WHERE … | …], all / any / none / single /
// filter (v IN list WHERE …) and reduce / allReduce (acc = initial,
// v IN list | step[, predicate]). It declares count names, each at its
// declared offset, visible from scope (the WHERE or | after the list, the
// pattern after a path's =) to close.
type localBinding struct {
	close, scope, count int
	names               [2]string
	declared            [2]int
	// source is the text span that types each name: the list an element
	// iterates (element), reduce's initial value for its accumulator; a
	// named path (path) is a Path.
	source  [2][2]int
	element [2]bool
	path    [2]bool
}

func (binding *localBinding) declare(name string, at, sourceStart, sourceEnd int, element, path bool) {
	index := binding.count
	binding.names[index], binding.declared[index] = name, at
	binding.source[index], binding.element[index], binding.path[index] = [2]int{sourceStart, sourceEnd}, element, path
	binding.count++
}

// localBindingAt reads the local binding that opens at text[open] ('[' or
// the '(' of a binding function), if one does. It is the one reader of
// these declarations: the names an expression binds (expressionLocalBindings)
// and where each is in scope (localVariableShadowsAt) both come from it, so
// x IN[…], x /* … */ IN … and p = (…) read alike everywhere.
func localBindingAt(text string, open int) (localBinding, bool) {
	var binding localBinding
	list := text[open] == '[' // else the '(' of a call: callers pass only these
	function := ""
	if !list {
		if function = bindingFunctionBeforeParen(text, open); function == "" {
			return binding, false
		}
	}
	closing := func() int {
		closeBy := ')'
		if list {
			closeBy = ']'
		}
		if close := findMatchingDelimiter(text, open, rune(text[open]), closeBy); close >= 0 {
			return close
		}
		return len(text)
	}
	if isReduceFormFunction(function) {
		binding.close = closing()
		if binding.close == len(text) {
			return binding, false
		}
		form, ok := parseReduceForm(function, text[open+1:binding.close])
		if !ok {
			return binding, false
		}
		comma := open + 1 + findTopLevelOperator(text[open+1:binding.close], ",", false, true)
		binding.scope = localScopeStart(text, comma+1, binding.close, true, false)
		accumulator := queryGapEnd(text, open+1)
		equals := open + 1 + strings.IndexByte(text[open+1:comma], '=')
		binding.declare(form.accumulator, accumulator, equals+1, comma, false, false)
		_, element, list, _ := bindingDeclaration(text, comma+1)
		binding.declare(form.variable, element, list, binding.scope, true, false)
		return binding, true
	}
	if name, declaration, listStart, declared := bindingDeclaration(text, open+1); declared {
		binding.close = closing()
		binding.scope = localScopeStart(text, listStart, binding.close, list, true)
		binding.declare(name, declaration, listStart, binding.scope, true, false)
		return binding, true
	}
	if !list {
		return binding, false
	}
	// [p = (a)-->(b) …]: a named pattern comprehension.
	if name, declaration, pattern, named := namedPathDeclaration(text, open+1); named {
		binding.close = closing()
		binding.declare(name, declaration, 0, 0, false, true)
		binding.scope = pattern
		return binding, true
	}
	return binding, false
}

// namedPathDeclaration reads a path variable declared at text[from] before
// its pattern: p = (a)-->(b), `p p` = (a)-->(b). It returns the name,
// where it is written and where the pattern starts. It is the one reader of
// a named pattern comprehension's head, for localBindingAt,
// patternComprehensionHead and the quoted-variable classifier.
func namedPathDeclaration(text string, from int) (name string, at, pattern int, ok bool) {
	at = queryGapEnd(text, from)
	name, end, ok := scanIdentifierToken(text, at)
	if !ok {
		return "", 0, 0, false
	}
	next := queryGapEnd(text, end)
	if next+1 >= len(text) || text[next] != '=' || text[next+1] == '~' {
		return "", 0, 0, false
	}
	pattern = queryGapEnd(text, next+1)
	if pattern >= len(text) || text[pattern] != '(' {
		return "", 0, 0, false
	}
	return name, at, pattern, true
}

// bindingDeclaration reads the declaration that opens a binding's arguments
// at text[from]: a name, then IN (x IN l, x IN[1], x /* … */ IN l). It
// returns the name, where it is written and where the list after IN starts.
// It is the one reader of that declaration, for the scope reader
// (localBindingAt) and the evaluators (parseListComprehension,
// parseQuantifierArguments).
func bindingDeclaration(text string, from int) (name string, at, list int, ok bool) {
	at = queryGapEnd(text, from)
	name, end, ok := scanIdentifierToken(text, at)
	if !ok {
		return "", 0, 0, false
	}
	next := queryGapEnd(text, end)
	if next+2 > len(text) || !strings.EqualFold(text[next:next+2], "IN") || next+2 < len(text) && isIdentByte(text[next+2]) {
		return "", 0, 0, false
	}
	return name, at, next + 2, true
}

// localScopeStart is where a binding's names come into scope in
// text[from:close]: its first top-level | (pipe) or WHERE (where), or close
// when it has neither ([v IN l] binds v nowhere).
func localScopeStart(text string, from, close int, pipe, where bool) int {
	depth := 0
	for index := from; index < close; index++ {
		switch c := text[index]; cypherLexicalByte(c) {
		case cypherQuoteClass:
			index = skipCypherQuotedText(text, index, c) - 1
			continue
		case '/':
			if end := queryCommentEnd(text, index); end >= 0 {
				index = end - 1
				continue
			}
		case '(', '[', '{':
			depth++
		case ')', ']', '}':
			depth--
		case '|':
			if pipe && depth == 0 {
				return index
			}
		}
		if where && depth == 0 && index+5 <= close && strings.EqualFold(text[index:index+5], "WHERE") &&
			!isIdentByte(text[index-1]) && (index+5 == len(text) || !isIdentByte(text[index+5])) {
			return index
		}
	}
	return close
}

// localVariableShadowsAt reports whether name, read at offset operand of
// text, is a variable an enclosing expression binds itself rather than the
// clause's (localBindingAt): a list comprehension's element in its WHERE and
// projection ([n IN l WHERE 1 IN n | n[0]]), a named pattern comprehension's
// path ([p = (a)-->(b) | length(p)]), the element of all / any / none /
// single in its predicate (all(n IN l WHERE n[0])), and reduce's
// accumulator and element in its step (reduce(acc = [], n IN l | acc + n)).
// The list a binding iterates and reduce's initial value are read outside
// it: in 1 IN n, [n IN [1] | n] the first n is the clause's. A binding's own
// declaration (the n of n IN, the acc of acc =) is the local too. It is the
// one reader of these scopes for the code that reads raw text: the static
// checks (list operands, subscripts, dynamic labels, function arguments,
// property accesses, subquery patterns; withoutLocalVariables), the
// reference scanners and the writing of a row's values into an expression
// (localOccurrences).
func localVariableShadowsAt(text string, operand int, name string) bool {
	_, _, ok := localBindingOf(text, operand, name)
	return ok
}

// localBindingOf is the innermost local binding that binds name where it is
// read at offset operand of text (localVariableShadowsAt), and the index of
// name among its declarations. A '[' or '(' whose first declared name isn't
// name (and isn't a reduce, which declares two) is passed over without
// being read whole.
func localBindingOf(text string, operand int, name string) (localBinding, int, bool) {
	var found localBinding
	foundIndex, ok := 0, false
	for open := 0; open < operand; {
		if !localBindingStepReads(text[open]) {
			open++
			continue
		}
		next, binding, bound := localBindingStep(text, open, name)
		open = next
		for index := 0; bound && index < binding.count; index++ {
			if binding.names[index] == name && (binding.declared[index] == operand || binding.scope <= operand && operand < binding.close) {
				// A binding opening later inside this one is inner.
				found, foundIndex, ok = binding, index, true
			}
		}
	}
	return found, foundIndex, ok
}

// localBindingStepReads reports whether localBindingStep reads more of text
// than the byte c at its offset; the walks step over any other byte
// themselves.
func localBindingStepReads(c byte) bool {
	return isCypherQuoteByte(c) || c == '/' || c == '[' || c == '('
}

// localBindingStep is one step of the walk that finds the bindings of name
// (localBindingOf, localOccurrences.keeps): the binding that opens at
// text[open] when it may declare name, and the offset the walk goes on
// from (past a quoted name, string or comment). A '[' or '(' whose first
// declared name isn't name (and isn't a reduce, which declares two) is
// passed over without being read whole. It is called only at a byte
// localBindingStepReads reads.
func localBindingStep(text string, open int, name string) (int, localBinding, bool) {
	switch cypherLexicalByte(text[open]) {
	case cypherQuoteClass:
		return skipCypherQuotedText(text, open, text[open]), localBinding{}, false
	case '/':
		if end := queryCommentEnd(text, open); end >= 0 {
			return end, localBinding{}, false
		}
		return open + 1, localBinding{}, false
	}
	// text[open] is '[' or '(': the walks step over the bytes
	// localBindingStepReads doesn't read themselves.
	if declared, _, named := scanIdentifierToken(text, queryGapEnd(text, open+1)); !named || declared != name {
		if text[open] != '(' || !isReduceFormFunction(bindingFunctionBeforeParen(text, open)) {
			return open + 1, localBinding{}, false
		}
	}
	binding, bound := localBindingAt(text, open)
	return open + 1, binding, bound
}

// localBindingOperand is the static type of the local name read at offset
// at of text (localBindingOf): a named path is a Path; an element is its
// list's element (listElementOperand: an Integer of [1], a node of [y]
// for a node y); reduce's accumulator is typed from its initial value as the
// deriver types it (reduceAccumulatorOperand). The
// source is typed in the scope at its own position, with the locals
// around it typed first (withLocalTypes): in
// all(x IN [y] WHERE all(r IN [x] WHERE …)) [x] holds the outer local's
// node. It is unknown when that type isn't known.
func localBindingOperand(ctx context.Context, text string, at int, name string, scope staticTypeScope) staticOperand {
	binding, index, ok := localBindingOf(text, at, name)
	if !ok {
		return staticOperand{}
	}
	if binding.path[index] {
		return provenOperand("Path")
	}
	span := binding.source[index]
	if span[0] <= 0 || span[1] <= span[0] || span[1] > len(text) {
		return staticOperand{}
	}
	source := strings.TrimSpace(text[span[0]:span[1]])
	inner := withLocalTypes(ctx, scope, text, span[0])
	types := typeScopeOf(inner)
	if binding.element[index] {
		return listElementOperand(ctx, types, inner, source)
	}
	// The one other local is reduce's accumulator.
	return reduceAccumulatorOperand(projectedOperand(ctx, types, inner, source))
}

// localBindingKind is localBindingOperand's binding kind.
func localBindingKind(ctx context.Context, text string, at int, name string, scope staticTypeScope) matchBindingKind {
	return localBindingOperand(ctx, text, at, name, scope).bindingKind()
}

// withLocalTypes is scope with each name a local binds around offset at of
// text in place of the outer variable of that name, typed as that local
// (localBindingOperand): in all(r IN [1] WHERE EXISTS { (r)-->() }) the r
// a subquery's pattern reads is an Integer, not the clause's relationship.
// The scope goes through typeScope, the one type of every variable.
func withLocalTypes(ctx context.Context, scope staticTypeScope, text string, at int) staticTypeScope {
	return boundExpressionTypeView(ctx, scope, text, at)
}

// bindingFunctionBeforeParen is the name of the function whose arguments
// open at text[open] when it binds variables of its own (all / any / none /
// single / filter, reduce / allReduce), as written; "" for any other.
func bindingFunctionBeforeParen(text string, open int) string {
	end := open
	for end > 0 && isWhitespace(text[end-1]) {
		end--
	}
	start := end
	for start > 0 && isIdentByte(text[start-1]) {
		start--
	}
	if start == end || start > 0 && isIdentByte(text[start-1]) {
		return ""
	}
	switch strings.ToLower(text[start:end]) {
	case "any", "all", "none", "single", "filter", "reduce", "allreduce":
		return text[start:end]
	default:
		return ""
	}
}

// localBindingNames caches the names a text binds itself
// (expressionLocalBindings), by text, for localOccurrences.
var localBindingNames = newBoundedCache[string, map[string]struct{}](1024, boundedCacheStringShardIndex)

// localOccurrences reads, for writing a row's values into text, which
// occurrences of a name read a variable an enclosing expression binds itself
// (localVariableShadowsAt) and keep their text. It is a value the caller
// keeps on its stack: the names text binds are read once per text
// (localBindingNames), when first asked, and the occurrences of a name in
// one input are read in one walk (keeps), so a row predicate costs one cache
// lookup and no allocation. (Not every binding form has an IN: a named
// pattern comprehension [p = (a)-->(b) | p] declares with =.)
type localOccurrences struct {
	// text is read, never changed: the names it binds are cached by text
	// (localBindingNames), shared and never written to.
	text   string
	read   bool
	locals map[string]struct{}

	// The walk of input for name (keeps): it has read the bindings that
	// open before walked, and holds those of name a later occurrence can
	// still read (scopes, then more once scopes is full).
	input, name string
	bound       bool
	walked      int
	scopes      [8]localOccurrenceScope
	open        int
	more        []localOccurrenceScope
}

// localOccurrenceScope is where one binding's local is read: at its
// declaration, and from scope up to close (localBindingOf).
type localOccurrenceScope struct{ declared, scope, close int }

// keeps reports whether the occurrence of name at offset at of input reads a
// local variable of that name (localVariableShadowsAt), so its text is
// kept. The replacers ask it for each occurrence of input in order: the
// bindings opening before at are read once for them all (localBindingStep),
// and an occurrence before the last one asked, another input or another
// name starts the walk again. A nil localOccurrences keeps nothing.
func (occurrences *localOccurrences) keeps(input, name string, at int) bool {
	if occurrences == nil {
		return false
	}
	if input != occurrences.input || name != occurrences.name || at < occurrences.walked {
		occurrences.input, occurrences.name, occurrences.walked = input, name, 0
		occurrences.open, occurrences.more = 0, occurrences.more[:0]
		occurrences.bound = occurrences.binds(name)
	}
	if !occurrences.bound {
		return false
	}
	for occurrences.walked < at {
		if !localBindingStepReads(input[occurrences.walked]) {
			occurrences.walked++
			continue
		}
		next, binding, bound := localBindingStep(input, occurrences.walked, name)
		occurrences.walked = next
		for index := 0; bound && index < binding.count; index++ {
			if binding.names[index] == name {
				occurrences.hold(localOccurrenceScope{declared: binding.declared[index], scope: binding.scope, close: binding.close})
			}
		}
	}
	// A binding that closes by at closes before every later occurrence
	// too: it is let go.
	kept, held := false, 0
	for _, scope := range occurrences.scopes[:occurrences.open] {
		if scope.close > at {
			kept = kept || scope.declared == at || scope.scope <= at
			occurrences.scopes[held] = scope
			held++
		}
	}
	occurrences.open, held = held, 0
	for _, scope := range occurrences.more {
		if scope.close > at {
			kept = kept || scope.declared == at || scope.scope <= at
			occurrences.more[held] = scope
			held++
		}
	}
	occurrences.more = occurrences.more[:held]
	return kept
}

func (occurrences *localOccurrences) hold(scope localOccurrenceScope) {
	if occurrences.open < len(occurrences.scopes) {
		occurrences.scopes[occurrences.open] = scope
		occurrences.open++
		return
	}
	occurrences.more = append(occurrences.more, scope)
}

// binds reports whether text binds a local named name.
func (occurrences *localOccurrences) binds(name string) bool {
	if !occurrences.read {
		occurrences.read = true
		// A clause's text is the same for every row: its names are read
		// once.
		locals, cached := localBindingNames.get(occurrences.text)
		if !cached {
			locals = expressionLocalBindings(occurrences.text)
			localBindingNames.put(occurrences.text, locals)
		}
		occurrences.locals = locals
	}
	_, bound := occurrences.locals[name]
	return bound
}

// localReader answers localVariableShadowsAt for one text, reading the
// names the text binds once (expressionLocalBindings), so a name no binding
// declares costs a map lookup. The reference scanners
// (semanticFreeReferences, expressionFreeVariables) ask it for each
// occurrence they read.
type localReader struct {
	text  string
	names map[string]struct{}
}

func newLocalReader(text string) localReader {
	return localReader{text: text, names: expressionLocalBindings(text)}
}

// shadows reports whether the occurrence of name at offset at of the text
// reads a local variable of that name.
func (reader localReader) shadows(name string, at int) bool {
	if _, declared := reader.names[name]; !declared {
		return false
	}
	return localVariableShadowsAt(reader.text, at, name)
}

// withoutTypes is types (static type names by variable) without the names
// a local binds around offset at, for a part checked as text of its own (a
// pattern comprehension, a subquery body); types itself when none is.
func (reader localReader) withoutTypes(types map[string]string, at int) map[string]string {
	var inner map[string]string
	for name := range reader.names {
		if _, typed := types[name]; !typed || !localVariableShadowsAt(reader.text, at, name) {
			continue
		}
		if inner == nil {
			inner = maps.Clone(types)
		}
		delete(inner, name)
	}
	if inner == nil {
		return types
	}
	return inner
}

// withoutLocalVariables is scope without the variables an enclosing
// expression binds around offset at of text (localVariableShadowsAt), and
// whether it bound any of scope's: in all(r IN [[true]] WHERE r[0]) the r
// read is the list's element, whatever the clause binds r to. The names
// come from expressionLocalBindings, read only when a check would fail.
func withoutLocalVariables(scope staticTypeScope, text string, at int) (staticTypeScope, bool) {
	var shadowed []string
	for name := range expressionLocalBindings(text) {
		if scope.bound(name) && localVariableShadowsAt(text, at, name) {
			shadowed = append(shadowed, name)
		}
	}
	if len(shadowed) == 0 {
		return scope, false
	}
	local := scope
	local.kinds, local.values, local.members = maps.Clone(scope.kinds), maps.Clone(scope.values), maps.Clone(scope.members)
	local.derived = maps.Clone(scope.derived)
	for _, name := range shadowed {
		delete(local.kinds, name)
		delete(local.values, name)
		delete(local.members, name)
		delete(local.derived, name)
	}
	return local, true
}

// staticListOperand reads the operand of a list position starting at start
// and returns where it ends and, when its type is static and not a list, that
// type's Neo4j name (with the parameter's name for a parameter).
func staticListOperand(ctx context.Context, cypher string, start int, params map[string]interface{}) (end int, typeName, parameter string) {
	if start >= len(cypher) {
		return start, "", ""
	}
	switch c := cypher[start]; {
	case c == '$':
		end = start + 1
		for end < len(cypher) && isIdentByte(cypher[end]) {
			end++
		}
		name := cypher[start+1 : end]
		value, bound := params[name]
		if name == "" || !bound || value == nil || isCypherListParameter(value) {
			return end, "", ""
		}
		typeName = cypherTypeName(value)
		if typeName == "Map" {
			// A map parameter can stand for a node or relationship.
			typeName = "Map, Node or Relationship"
		}
		return end, typeName, name
	case isCypherStringQuoteByte(c):
		end = start + 1
		for end < len(cypher) && (cypher[end] != c || isBackslashEscaped(cypher, end)) {
			end++
		}
		end++
	case c == '{':
		close := findMatchingDelimiter(cypher, start, '{', '}')
		if close < 0 {
			return start, "", ""
		}
		end = close + 1
	default:
		end = start
		for end < len(cypher) && (isIdentByte(cypher[end]) || cypher[end] == '.' || cypher[end] == '-' && end == start) {
			end++
		}
		// A whole call ([x IN vector(…) | x], 1 IN size(l)) is the operand.
		if c != '-' && c != '.' && (c < '0' || c > '9') {
			if open := queryGapEnd(cypher, end); open < len(cypher) && cypher[open] == '(' {
				if close := findMatchingParen(cypher, open); close > open {
					end = close + 1
				}
			}
		}
	}
	// The operator check types the operand (a variable or a property is
	// known per row); a list position rejects a type with no list or null
	// alternative.
	operand := (staticTypeScope{}).operandOf(ctx, cypher[start:end])
	if operand.typeName() == "" || !operand.excludes(isListTypeName) {
		return end, "", ""
	}
	return end, operand.typeName(), ""
}

func isCypherListParameter(value interface{}) bool {
	if _, isBytes := value.([]byte); isBytes {
		return false
	}
	kind := reflect.TypeOf(value).Kind()
	return kind == reflect.Slice || kind == reflect.Array
}

// validateStaticBooleanOperands rejects statically-known non-boolean operands
// before execution. Expressions whose type depends on a row remain subject to
// runtime validation by the row evaluator.
func (e *StorageExecutor) validateStaticBooleanOperands(ctx context.Context, expression string) error {
	expression = strings.TrimSpace(expression)
	if inner, ok := stripEnclosingExpressionParentheses(expression); ok {
		return e.validateStaticBooleanOperands(ctx, inner)
	}
	if hasPrefixFoldASCII(expression, "NOT ") {
		operand := strings.TrimSpace(expression[len("NOT "):])
		if err := e.validateStaticBooleanOperands(ctx, operand); err != nil {
			return err
		}
		value, known := e.staticBooleanOperandValue(ctx, operand)
		if !known || value == nil {
			return nil
		}
		if _, boolean := value.(bool); !boolean {
			return invalidBooleanOperandError(value)
		}
		return nil
	}
	for _, operator := range []string{" OR ", " XOR ", " AND "} {
		// Only the expression's own operators: not those inside a list, a
		// comprehension, a map or a CASE.
		left, right, found := splitByOperatorOutsideCase(expression, operator, true, true)
		if !found {
			continue
		}
		for _, operand := range []string{left, right} {
			if err := e.validateStaticBooleanOperands(ctx, operand); err != nil {
				return err
			}
			value, known := e.staticBooleanOperandValue(ctx, operand)
			if !known || value == nil {
				continue
			}
			if _, boolean := value.(bool); !boolean {
				return invalidBooleanOperandError(value)
			}
		}
		return nil
	}
	return nil
}

func (e *StorageExecutor) staticBooleanOperandValue(ctx context.Context, expression string) (interface{}, bool) {
	expression = strings.TrimSpace(expression)
	if inner, ok := stripEnclosingExpressionParentheses(expression); ok {
		expression = inner
	}
	if value, literal := parseLiteralValueFromComputedRow(expression); literal {
		return value, true
	}
	if len(expressionVariables(expression)) > 0 {
		return nil, false
	}
	if strings.HasPrefix(expression, "{") && strings.HasSuffix(expression, "}") {
		value, err := e.evaluateMapLiteralFromValues(ctx, expression, nil)
		recordExpressionFailure(ctx, err)
		return value, err == nil
	}
	for _, operator := range []string{" OR ", " XOR ", " AND ", "<=", ">=", "<>", "!=", "=", "<", ">"} {
		if _, _, found := splitByOperatorWithOptions(expression, operator, true, true); found {
			return true, true
		}
	}
	upper := upperASCII(expression)
	if strings.HasSuffix(upper, " IS NULL") || strings.HasSuffix(upper, " IS NOT NULL") || strings.HasPrefix(upper, "NOT ") {
		return true, true
	}
	value, defined := e.evaluateExpressionWithContextDefined(ctx, expression, nil, nil)
	if !defined {
		return nil, false
	}
	return value, true
}

// validateListComprehensionVariables rejects a property expression where
// Cypher requires a local iterator name, including nested projections.
func validateListComprehensionVariables(text string) error {
	for index := 0; index < len(text); index++ {
		if isCypherQuoteByte(text[index]) {
			index = skipCypherQuotedText(text, index, text[index]) - 1
			continue
		}
		if text[index] != '[' {
			continue
		}
		close := findMatchingBracket(text, index)
		if close < 0 {
			break
		}
		inner := text[index+1 : close]
		in := findListComprehensionToken(inner, " IN ")
		pipe := findListComprehensionToken(inner, "|")
		_, _, _, declared := bindingDeclaration(inner, 0)
		emptyIterator := matchKeywordAt(inner, queryGapEnd(inner, 0), "IN")
		if pipe >= 0 && (in >= 0 && pipe > in || emptyIterator) && !patternComprehensionHead(inner) && !declared {
			return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "a list comprehension iterator must be a variable")
		}
	}
	return nil
}

package cypher

import (
	"context"
	"fmt"

	"github.com/orneryd/nornicdb/pkg/storage"
)

// graphEntityReference is the sole reader of existing native graph node inputs.
// Its caller supplies the projection/engine ID domain for unscoped text IDs.
func graphEntityReference(value interface{}) (storage.EntityIdentity, bool) {
	switch node := value.(type) {
	case *storage.Node:
		if node != nil {
			return node.Identity(), true
		}
	case string:
		return storage.EntityIdentity{LocalID: node}, true
	default:
		if isIntegerProcedureValue(value) {
			return storage.EntityIdentity{LocalID: fmt.Sprint(value)}, true
		}
	}
	return storage.EntityIdentity{}, false
}

// graphEntityDisplayID renders the public value, before any graph-domain
// canonicalization. Internal keys must never be formatted in client messages.
func graphEntityDisplayID(value interface{}) (storage.NodeID, bool) {
	reference, ok := graphEntityReference(value)
	if !ok {
		return "", false
	}
	return storage.NodeID(reference.InDatabase("")), true
}

// identityGraphEngine preserves nil storage so existing graph builders return
// their established error. Wrapping nil would hide that contract from them.
func identityGraphEngine(engine storage.Engine, scopes ...*graphIdentityScope) storage.Engine {
	if engine == nil {
		return nil
	}
	return graphIdentityView(engine, scopes...)
}

// graphIdentityStorage is a read view for algorithms whose maps accept NodeID.
// Inside that view every node, edge and endpoint uses the canonical identity
// key. Native values are restored at the result boundary; no identity cache or
// graph-sized cross-stream seen set is retained by this adapter.
type graphIdentityStorage struct {
	storage.Engine
	scope *graphIdentityScope
}

func graphIdentityView(engine storage.Engine, scopes ...*graphIdentityScope) *graphIdentityStorage {
	if view, ok := engine.(*graphIdentityStorage); ok {
		return view
	}
	var scope *graphIdentityScope
	if len(scopes) > 0 {
		scope = scopes[0]
	}
	return &graphIdentityStorage{Engine: engine, scope: scope}
}

func (v *graphIdentityStorage) node(node *storage.Node) *storage.Node {
	if node == nil {
		return nil
	}
	copy := *node
	copy.ID = storage.NodeID(node.IdentityKey())
	copy.Database = ""
	return &copy
}

func graphIdentityNodeValue(node *storage.Node) *storage.Node {
	if node == nil {
		return nil
	}
	identity := storage.EntityIdentityFromKey(string(node.ID))
	copy := *node
	copy.ID, copy.Database = storage.NodeID(identity.LocalID), identity.Database
	return &copy
}

func graphIdentityEdgeValue(edge *storage.Edge) *storage.Edge {
	if edge == nil {
		return nil
	}
	identity := storage.EntityIdentityFromKey(string(edge.ID))
	start := storage.EntityIdentityFromKey(string(edge.StartNode))
	end := storage.EntityIdentityFromKey(string(edge.EndNode))
	copy := *edge
	copy.ID, copy.Database = storage.EdgeID(identity.LocalID), identity.Database
	copy.StartNode, copy.EndNode = storage.NodeID(start.LocalID), storage.NodeID(end.LocalID)
	return &copy
}

func graphIdentityPathValue(path PathResult) PathResult {
	copy := path
	copy.Nodes = make([]*storage.Node, len(path.Nodes))
	copy.Relationships = make([]*storage.Edge, len(path.Relationships))
	for i, node := range path.Nodes {
		copy.Nodes[i] = graphIdentityNodeValue(node)
	}
	for i, edge := range path.Relationships {
		copy.Relationships[i] = graphIdentityEdgeValue(edge)
	}
	return copy
}

func (e *StorageExecutor) graphIdentityExecutor(ctx context.Context) *StorageExecutor {
	engine := identityGraphEngine(e.getStorage(ctx), e.graphIdentityScope)
	if engine == nil {
		return e
	}
	return e.cloneForStorage(engine)
}

func (e *StorageExecutor) graphReadArguments(ctx context.Context, args []interface{}, nodeCount int) (*StorageExecutor, []interface{}) {
	graph := e.graphIdentityExecutor(ctx)
	view := graph.storage.(*graphIdentityStorage)
	input := append([]interface{}(nil), args...)
	for i := 0; i < nodeCount && i < len(input); i++ {
		switch value := input[i].(type) {
		case *storage.Node:
			input[i] = view.node(value)
		case string:
			if key, ok := view.inputKey(value); ok {
				input[i] = string(key)
			}
		}
	}
	return graph, input
}

func (v *graphIdentityStorage) outputPath(path []storage.NodeID) []storage.NodeID {
	result := make([]storage.NodeID, len(path))
	for i, id := range path {
		result[i] = storage.NodeID(v.outputID(id))
	}
	return result
}

func (v *graphIdentityStorage) edge(edge *storage.Edge) *storage.Edge {
	if edge == nil {
		return nil
	}
	copy := *edge
	copy.ID = storage.EdgeID(edge.IdentityKey())
	copy.StartNode = storage.NodeID(edge.StartIdentity().Key())
	copy.EndNode = storage.NodeID(edge.EndIdentity().Key())
	copy.Database = ""
	return &copy
}

func (v *graphIdentityStorage) nodes(nodes []*storage.Node) []*storage.Node {
	out, _ := v.nodesWithContext(context.Background(), nodes)
	return out
}

func (v *graphIdentityStorage) nodesWithContext(ctx context.Context, nodes []*storage.Node) ([]*storage.Node, error) {
	result := make([]*storage.Node, len(nodes))
	for i, node := range nodes {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		result[i] = v.node(node)
	}
	return result, nil
}

func (v *graphIdentityStorage) edges(edges []*storage.Edge, err error) ([]*storage.Edge, error) {
	if err != nil {
		return nil, err
	}
	result := make([]*storage.Edge, len(edges))
	for i, edge := range edges {
		result[i] = v.edge(edge)
	}
	return result, nil
}

func (v *graphIdentityStorage) GetNode(key storage.NodeID) (*storage.Node, error) {
	id, ok := storage.EntityIdentityFromKey(string(key)).NodeLookupID(v.Engine)
