package cypher

import (
	"context"
	"fmt"
	valueconvert "github.com/orneryd/nornicdb/pkg/convert"
	cypherantlr "github.com/orneryd/nornicdb/pkg/cypher/antlr"
	"maps"
	"strconv"
	"strings"

)

func extractProcedureInvocationArguments(ctx context.Context, spec ProcedureSpec, callCypher string) ([]interface{}, error) {
	if strings.Index(callCypher, "(") >= 0 {
		args, err := extractCallArguments(callCypher)
		if err != nil {
			return nil, err
		}
		if err := procedureArityFor(ctx, spec, len(args)); err != nil {
			return nil, err
		}
		return validateAndCoerceProcedureArguments(spec, args, explicitProcedureArgumentTexts(ctx, callCypher))
	}

	params := getParamsFromContext(ctx)
	args := make([]interface{}, 0, len(spec.Params))
	for index, parameter := range spec.Params {
		value, exists := params[parameter.Name]
		if !exists {
			if index >= spec.MinArgs && parameter.Optional {
				continue
			}
			return nil, newSemanticError(
				"Neo.ClientError.Statement.ParameterMissing",
				"MissingParameter",
				fmt.Sprintf("missing implicit procedure parameter %s", parameter.Name),
			)
		}
		args = append(args, value)
	}
	if err := procedureArityFor(ctx, spec, len(args)); err != nil {
		return nil, err
	}
	return validateAndCoerceProcedureArguments(spec, args, nil)
}

func (e *StorageExecutor) extractBoundProcedureInvocationArguments(ctx context.Context, spec ProcedureSpec, callCypher string) ([]interface{}, error) {
	ctx = withExpressionFailureSlot(ctx)
	bindings := valueBindingsFromContext(ctx)
	texts := explicitProcedureArgumentTexts(ctx, callCypher)
	if texts == nil {
		return extractProcedureInvocationArguments(ctx, spec, callCypher)
	}
	if bindings == nil {
		bindings = make(map[string]interface{})
		bindParameterRow(ctx, pipelineRow(bindings))
	}
	args := make([]interface{}, len(texts))
	if err := procedureArityFor(ctx, spec, len(args)); err != nil {
		return nil, err
	}
	for index, text := range texts {
		value, resolved := e.evaluateRowExpressionWithContext(ctx, text, pipelineRow(bindings))
		if !resolved {
			pipelineItemUnevaluable(ctx, text)
			return nil, getExpressionFailure(ctx)
		}
		if err := getExpressionFailure(ctx); err != nil {
			return nil, err
		}
		args[index] = value
	}
	return validateAndCoerceProcedureArguments(spec, args, texts)
}

func explicitProcedureArgumentTexts(ctx context.Context, source string) []string {
	clause, ok := canonicalQueryClause(ctx, source)
	if !ok {
		return nil
	}
	return procedureArgumentTextsFromSyntax(clause)
}

func procedureArgumentTextsFromSyntax(clause cypherantlr.SyntaxNode) []string {
	arguments := clause.ChildRule(cypherantlr.CypherParserRULE_parenExpressionChain)
	if !arguments.Valid() {
		return nil
	}
	expressions := arguments.ChildRule(cypherantlr.CypherParserRULE_expressionChain)
	texts := []string{}
	if expressions.Valid() {
		for i := 0; i < expressions.ChildCount(); i++ {
			expression := expressions.Child(i)
			if expression.Rule() == cypherantlr.CypherParserRULE_expression {
				texts = append(texts, expression.Code())
			}
		}
	}
	return texts
}
func validateAndCoerceProcedureArguments(spec ProcedureSpec, args []interface{}, explicitTexts []string) ([]interface{}, error) {
	coerced := append([]interface{}(nil), args...)
	for index := range coerced {
		if index >= len(spec.Params) {
			break
		}
		if explicitTexts != nil && index < len(explicitTexts) && !isStaticallyTypedProcedureArgument(explicitTexts[index]) {
			continue
		}

		parameter := spec.Params[index]
		value, ok := coerceProcedureArgument(parameter, coerced[index])
		if !ok {
			return nil, newSemanticError(
				"Neo.ClientError.Statement.SyntaxError",
				"InvalidArgumentType",
				fmt.Sprintf("procedure %s argument %s requires %s but received %s", spec.Name, parameter.Name, parameter.Type, cypherTypeSystemName(coerced[index])),
			)
		}
		coerced[index] = value
	}
	return coerced, nil
}

// staticProcedureArgumentTypeError is Neo4j's compile-time error for a
// procedure argument whose static type its parameter can't take: a literal, a
// variable bound to one by WITH, or a pattern variable (CALL
// db.resampleIndex(1.5), WITH 1.5 AS v CALL db.resampleIndex(v), MATCH (n)
// CALL db.resampleIndex(n)). Neo4j types a value bound by UNWIND only when the
// call runs, so those are left to the call. Only the parameter types the call
// itself checks (coerceProcedureArgument) are checked here: a NODE, MAP or
// LIST parameter also takes NornicDB's other forms (a node id, a label, a
// request's short form).
func staticProcedureArgumentTypeError(ctx context.Context, clause string, scope staticTypeScope, unwound map[string]struct{}) error {
	procedure, found := globalProcedureRegistry.Get(extractProcedureName(ctx, clause))
	if !found {
		return nil
	}
	texts := explicitProcedureArgumentTexts(ctx, clause)
	if len(texts) == 0 {
		return nil
	}
	if len(unwound) > 0 {
		// The whole binding is left to the call: its type name and its
		// derived operand alike.
		scope.values = maps.Clone(scope.values)
		scope.derived = maps.Clone(scope.derived)
		for name := range unwound {
			delete(scope.values, name)
			delete(scope.derived, name)
		}
	}
	for index, text := range texts {
		if index >= len(procedure.Spec.Params) {
			break
		}
		typeName := scope.staticExpressionType(ctx, text)
		if typeName == "" {
			continue
		}
		if expected, accepted := procedureParameterAcceptsStaticType(procedure.Spec.Params[index].Type, typeName); !accepted {
			return typeNameMismatchError(expected, procedureArgumentTypeName(typeName))
		}
	}
	return nil
}

// projectUnwoundValues returns which of the variables a WITH clause binds
// carry a type that came from UNWIND: an alias of such a variable, or the
// variable itself under WITH *.
func projectUnwoundValues(ctx context.Context, unwound map[string]struct{}, clause string) map[string]struct{} {
	if len(unwound) == 0 {
		return nil
	}
	body, _ := projectionSemanticBodyAndTail(clause, "WITH")
	var projected map[string]struct{}
	keep := func(name string) {
		if projected == nil {
			projected = make(map[string]struct{})
		}
		projected[name] = struct{}{}
	}
	for _, raw := range splitTopLevelComma(body) {
		expression, alias := parseProjectionExprAlias(ctx, strings.TrimSpace(raw))
		if expression == "*" {
			for name := range unwound {
				keep(name)
			}
			continue
		}
		variable := simpleSemanticIdentifier(expression)
		if _, fromUnwind := unwound[variable]; !fromUnwind || variable == "" {
			continue
		}
		if alias == "" {
			alias = variable
		}
		keep(alias)
	}
	return projected
}

// procedureParameterAcceptsStaticType reports whether a parameter of
// parameterType takes an argument of static type typeName (any one of its
// choices, for a type such as "Float, Integer or Number"), and the type
// Neo4j's error names as expected. An INTEGER is a FLOAT argument, as when the
// call runs.
func procedureParameterAcceptsStaticType(parameterType, typeName string) (string, bool) {
	var expected string
	var accepted []string
	switch upperASCII(strings.TrimSpace(parameterType)) {
	case "STRING":
		expected, accepted = "String", []string{"String"}
	case "BOOLEAN", "BOOL":
		expected, accepted = "Boolean", []string{"Boolean"}
	case "INTEGER":
		expected, accepted = "Integer", []string{"Integer", "Number"}
	case "FLOAT":
		expected, accepted = "Float", []string{"Float", "Integer", "Number"}
	case "NUMBER":
		expected, accepted = "Number", []string{"Number", "Float", "Integer"}
	default:
		return "", true
	}
	// The typing owner decides: one fitting alternative is enough.
	return expected, typeName != "" && !typedOperand(typeName).proved().excludes(typeNameIn(append(accepted, "Any")...))
}

func isStaticallyTypedProcedureArgument(text string) bool {
	text = strings.TrimSpace(text)
	if text == "" {
		return false
	}
	lower := lowerASCII(text)
	if lower == "null" || lower == "true" || lower == "false" {
		return true
	}
	if (strings.HasPrefix(text, "'") && strings.HasSuffix(text, "'")) ||
		(strings.HasPrefix(text, "\"") && strings.HasSuffix(text, "\"")) {
		return true
	}
	if _, err := strconv.ParseInt(text, 10, 64); err == nil {
		return true
	}
	if _, err := strconv.ParseFloat(text, 64); err == nil {
		return true
	}
	return false
}

// coerceProcedureArgument checks and converts one argument against its
// parameter's type. null is a value of every type, as in Neo4j: the call
// goes ahead and the procedure decides what null means (its own failure is
// ProcedureCallFailed).
func coerceProcedureArgument(parameter ProcedureParam, value interface{}) (interface{}, bool) {
	if value == nil {
		return nil, true
	}

	switch upperASCII(strings.TrimSpace(parameter.Type)) {
	case "", "ANY":
		return value, true
	case "STRING":
		_, ok := value.(string)
		return value, ok
	case "BOOLEAN", "BOOL":
		_, ok := value.(bool)
		return value, ok
	case "INTEGER":
		return value, isIntegerProcedureValue(value)
	case "FLOAT":
		if converted, ok := procedureFloat64(value); ok {
			return converted, true
		}
		return value, false
	case "NUMBER":
		return value, isIntegerProcedureValue(value) || isFloatProcedureValue(value)
	default:
		return value, true
	}
}

func procedureFloat64(value interface{}) (float64, bool) {
	return valueconvert.NumericFloat64(value)
}

func isIntegerProcedureValue(value interface{}) bool {
	return valueconvert.IsInteger(value)
}

func isFloatProcedureValue(value interface{}) bool {
	_, ok := valueconvert.FloatValue(value)
	return ok
}

// unknownProcedureError is the shared planning/execution terminal for a missing procedure.
func unknownProcedureError(name string) error {
	return newSemanticError("Neo.ClientError.Procedure.ProcedureNotFound", "ProcedureNotFound", fmt.Sprintf("There is no procedure with the name `%s` registered for this database instance. Please ensure you've spelled the procedure name correctly and that the procedure is properly deployed.", name))
}

package cypher

import (
	"context"
	"strconv"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// Quantified path patterns (Neo4j 5.9+, GQL; #907).
//
// A parenthesised path followed by a quantifier repeats it:
//
//	MATCH p = (a:Station)((x)-[r:LINK]->(y) WHERE r.open){1,3}(b:Station)
//
// Each repetition (iteration) is a match of the inner path whose first node
// is the previous iteration's last node; the node before the group is the
// first iteration's first node and the node after it the last iteration's
// last node (with zero iterations they are one node). A variable inside the
// group binds the list of its values, one per iteration; the inner WHERE
// applies to each iteration. No relationship repeats in the clause, unless
// it is a MATCH REPEATABLE ELEMENTS (repeatable_elements.go).
//
// The pipeline's MATCH step runs a pattern part with groups here: the part
// is a sequence of pieces, plain chains and groups, matched left to right
// from the bindings so far (pipelineMatchRows for each chain and each
// iteration). A clause with other parts reaches here one part at a time
// through the pattern product, which keeps relationships distinct across
// parts.

// quantifiedPathPiece is a piece of a pattern part: a chain of node and
// relationship patterns (chain), or a quantified group.
type quantifiedPathPiece struct {
	// chain is the pattern text, starting and ending with a node pattern;
	// for a group, the inner path's.
	chain string
	// first and last are the variables of chain's first and last node
	// patterns (generated for an anonymous one).
	first, last string
	group       bool
	// where is a group's own WHERE; min and max its quantifier's bounds
	// (max < 0: none).
	where    string
	min, max int
	// variables are the variables inside a group, which bind lists.
	variables []string
	// deferred is the part of a group's WHERE that reads variables the
	// pattern binds after the group: each iteration is checked against it
	// once the pattern is matched.
	deferred string
}

// quantifiedPathMatch is a MATCH pattern part with quantified groups.
type quantifiedPathMatch struct {
	pathVariable string
	pieces       []quantifiedPathPiece
	where        string
}

// hasQuantifiedGroup reports whether pattern has a quantified group: a
// parenthesised path followed by a quantifier.
func hasQuantifiedGroup(pattern string) bool {
	if !mayUseQuantifiedGroup(pattern) {
		return false
	}
	_, _, _, ok := nextQuantifiedGroup(pattern, 0)
	return ok
}

// mayUseQuantifiedGroup reports whether text may have a quantified group,
// well formed or not: a + * or { after a ')'. It never answers false for
// one.
func mayUseQuantifiedGroup(text string) bool {
	for i := strings.IndexByte(text, ')'); i >= 0; {
		if next := skipASCIISpaces(text, i+1, len(text)); next < len(text) && strings.IndexByte("+*{", text[next]) >= 0 {
			return true
		}
		following := strings.IndexByte(text[i+1:], ')')
		if following < 0 {
			return false
		}
		i += following + 1
	}
	return false
}

// nextQuantifiedGroup finds the first quantified group at or after
// pattern[from] at its own level: its parentheses (open, close) and
// quantifier (quantifiedGroupFrom).
func nextQuantifiedGroup(pattern string, from int) (int, int, relationshipQuantifier, bool) {
	return quantifiedGroupFrom(pattern, from, false)
}

// quantifiedGroupFrom is the one group finder: the first quantified group at
// or after pattern[from], skipping quoted text, lists and maps. A parenthesis
// that isn't a group is skipped whole, unless nested is set: then the groups
// inside it count too (shortestPath((a)((x)-[r]-(y))+(b)), the form SHORTEST
// k is read as).
func quantifiedGroupFrom(pattern string, from int, nested bool) (int, int, relationshipQuantifier, bool) {
	for i := from; i < len(pattern); i++ {
		switch c := pattern[i]; cypherLexicalByte(c) {
		case cypherQuoteClass:
			i = skipCypherQuotedText(pattern, i, c) - 1
		case '[', '{':
			closeBy := map[byte]byte{'[': ']', '{': '}'}[c]
			if close := findMatchingDelimiter(pattern, i, rune(c), rune(closeBy)); close > i {
				i = close
			}
		case '(':
			close := findMatchingParen(pattern, i)
			if close < 0 {
				return 0, 0, relationshipQuantifier{}, false
			}
			if parenthesisedPathAt(pattern, i, close) {
				if quantifier, ok := relationshipQuantifierAt(pattern, skipASCIISpaces(pattern, close+1, len(pattern)), len(pattern)); ok {
					return i, close, quantifier, true
				}
			}
			if !nested {
				i = close
			}
		}
	}
	return 0, 0, relationshipQuantifier{}, false
}

// parseQuantifiedPathMatch reads a MATCH body (pattern [WHERE …]) of one
// pattern part with quantified groups. ok is false for any other body.
func parseQuantifiedPathMatch(body string) (*quantifiedPathMatch, bool, error) {
	if !hasQuantifiedGroup(body) {
		return nil, false, nil
	}
	pattern, where := body, ""
	if index := topLevelKeywordIndex(body, "WHERE"); index >= 0 {
		pattern, where = strings.TrimSpace(body[:index]), strings.TrimSpace(body[index+len("WHERE"):])
	}
	if len(splitTopLevelComma(pattern)) != 1 || !hasQuantifiedGroup(pattern) {
		return nil, false, nil
	}
	m := &quantifiedPathMatch{where: where}
	if variable := extractPathAssignmentVariable(pattern); variable != "" {
		m.pathVariable = variable
		pattern = strings.TrimSpace(pattern[strings.IndexByte(pattern, '=')+1:])
	}
	generated := 0
	name := func() string {
		generated++
		return generatedVariablePrefix + "qpp" + strconv.Itoa(generated)
	}
	outside := map[string]bool{}
	for at := 0; at < len(pattern); at = skipASCIISpaces(pattern, at, len(pattern)) {
		open, close, quantifier, grouped := nextQuantifiedGroup(pattern, at)
		if grouped && open == at {
			inner := strings.TrimSpace(pattern[open+1 : close])
			piece := quantifiedPathPiece{group: true, min: quantifier.min, max: quantifier.max}
			if index := topLevelKeywordIndex(inner, "WHERE"); index >= 0 {
				inner, piece.where = strings.TrimSpace(inner[:index]), strings.TrimSpace(inner[index+len("WHERE"):])
			}
			piece.chain, piece.first, piece.last = nameChainEnds(inner, name)
			structure := matchPatternStructure(piece.chain)
			piece.variables = append(extractNodeVariables(structure), extractRelationshipVariables(structure)...)
			m.pieces = append(m.pieces, piece)
			at = quantifier.end
			continue
		}
		end := len(pattern)
		if grouped {
			end = open
		}
		chain := strings.TrimSpace(pattern[at:end])
		if !strings.HasPrefix(chain, "(") || !strings.HasSuffix(chain, ")") {
			return nil, true, localizedError(localization.CypherMatchingPathPatternInvalid(pattern), nil)
		}
		piece := quantifiedPathPiece{}
		piece.chain, piece.first, piece.last = nameChainEnds(chain, name)
		structure := matchPatternStructure(chain)
		for _, variable := range append(extractNodeVariables(structure), extractRelationshipVariables(structure)...) {
			outside[variable] = true
		}
		m.pieces = append(m.pieces, piece)
		at = end
	}
	for _, piece := range m.pieces {
		for _, variable := range piece.variables {
			if outside[variable] || variable == m.pathVariable {
				return nil, true, labelExpressionSyntaxError(localization.CypherMatchingQuantifiedPathVariableOutside(variable))
			}
		}
	}
	for index := range m.pieces {
		splitDeferredGroupWhere(m.pieces, index)
	}
	return m, true, nil
}

// splitDeferredGroupWhere moves the conjuncts of the group pieces[index]'s
// WHERE that read a variable a later piece binds to its deferred check.
func splitDeferredGroupWhere(pieces []quantifiedPathPiece, index int) {
	piece := &pieces[index]
	if !piece.group || piece.where == "" {
		return
	}
	var later []string
	for _, next := range pieces[index+1:] {
		structure := matchPatternStructure(next.chain)
		later = append(later, extractNodeVariables(structure)...)
		later = append(later, extractRelationshipVariables(structure)...)
	}
	var now, deferred []string
	for _, term := range splitTopLevelAndConjuncts(piece.where) {
		readsLater := false
		for _, variable := range later {
			readsLater = readsLater || referencesVariable(term, variable)
		}
		if readsLater {
			deferred = append(deferred, term)
		} else {
			now = append(now, term)
		}
	}
	piece.where, piece.deferred = strings.Join(now, " AND "), strings.Join(deferred, " AND ")
}

// nameChainEnds returns chain with a variable in its first and last node
// patterns (a generated one where it has none) and those variables.
func nameChainEnds(chain string, name func() string) (string, string, string) {
	lastOpen := lastNodePatternStart(chain)
	named := func(open int) (string, string) {
		variable, _, ok := scanSymbolicName(chain, skipASCIISpaces(chain, open+1, len(chain)))
		if ok {
			return chain, variable
		}
		variable = name()
		return chain[:open+1] + variable + chain[open+1:], variable
	}
	var last string
	if lastOpen > 0 {
		chain, last = named(lastOpen)
	}
	chain, first := named(0)
	if lastOpen <= 0 {
		last = first
	}
	return chain, first, last
}

// lastNodePatternStart is the index of the last top-level node pattern of
// chain, -1 when it has none.
func lastNodePatternStart(chain string) int {
	last := -1
	// A chain's top level holds patterns and arrows; quoted text is inside
	// brackets.
	for i := 0; i < len(chain); i++ {
		switch c := chain[i]; c {
		case '[', '{':
			closeBy := map[byte]byte{'[': ']', '{': '}'}[c]
			if close := findMatchingDelimiter(chain, i, rune(c), rune(closeBy)); close > i {
				i = close
			}
		case '(':
			last = i
			close := findMatchingParen(chain, i)
			if close < 0 {
				return last
			}
			i = close
		}
	}
	return last
}

// quantifiedPathState is the search's position: the bindings so far, the
// path so far, its end node, and the relationships it used.
type quantifiedPathState struct {
	row           pipelineRow
	nodes         []*storage.Node
	relationships []*storage.Edge
	used          map[storage.EdgeID]struct{}
	// checks are the iterations' deferred WHERE checks.
	checks []quantifiedDeferredCheck
}

// quantifiedDeferredCheck is a deferred group WHERE (where) and the
// iteration's values of the group's variables.
type quantifiedDeferredCheck struct {
	where  string
	values pipelineRow
}

// pipelineApplyQuantifiedPathMatch runs a pattern part with quantified
// groups for each row; an OPTIONAL MATCH is handled by its caller.
func (e *StorageExecutor) pipelineApplyQuantifiedPathMatch(ctx context.Context, rows []pipelineRow, m *quantifiedPathMatch) ([]pipelineRow, error) {
	var out []pipelineRow
	for _, row := range rows {
		state := quantifiedPathState{row: row, used: map[storage.EdgeID]struct{}{}}
		err := e.matchQuantifiedPieces(ctx, m, 0, state, func(done quantifiedPathState) error {
			bound := done.row
			if m.pathVariable != "" {
				bound[m.pathVariable] = e.pathToMap(PathResult{Nodes: done.nodes, Relationships: done.relationships, Length: len(done.relationships)})
			}
			for name := range bound {
				if strings.HasPrefix(name, generatedVariablePrefix+"qpp") {
					delete(bound, name)
				}
			}
			for _, check := range done.checks {
				iteration := copyPipelineRow(bound)
				for name, value := range check.values {
					iteration[name] = value
				}
				if !e.evaluateWithWhereCondition(ctx, check.where, map[string]interface{}(iteration)) {
					return getExpressionFailure(ctx)
				}
			}
			if m.where != "" && !e.evaluateWithWhereCondition(ctx, m.where, map[string]interface{}(bound)) {
				return getExpressionFailure(ctx)
			}
			out = append(out, bound)
			return nil
		})
		if err != nil {
			return nil, err
		}
	}
	return out, nil
}

// matchQuantifiedPieces matches m.pieces[index:] from state and calls emit
// for each complete match.
func (e *StorageExecutor) matchQuantifiedPieces(ctx context.Context, m *quantifiedPathMatch, index int, state quantifiedPathState, emit func(quantifiedPathState) error) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if index == len(m.pieces) {
		return emit(state)
	}
	piece := m.pieces[index]
	if !piece.group {
		return e.matchQuantifiedChain(ctx, piece.chain, piece.first, "", state, func(next quantifiedPathState, _ pipelineRow) error {
			return e.matchQuantifiedPieces(ctx, m, index+1, next, emit)
		})
	}
	lists := make(map[string][]interface{}, len(piece.variables))
	return e.matchQuantifiedIterations(ctx, m, index, piece, 0, state, lists, emit)
}

// matchQuantifiedIterations matches the group m.pieces[index] after
// iterations repetitions, with each inner variable's values so far in lists.
func (e *StorageExecutor) matchQuantifiedIterations(ctx context.Context, m *quantifiedPathMatch, index int, piece quantifiedPathPiece, iterations int, state quantifiedPathState, lists map[string][]interface{}, emit func(quantifiedPathState) error) error {
	if iterations >= piece.min {
		done := state
		done.row = copyPipelineRow(state.row)
		for _, variable := range piece.variables {
			values := lists[variable]
			if values == nil {
				values = []interface{}{}
			}
			done.row[variable] = append([]interface{}(nil), values...)
		}
		if iterations == 0 && len(state.nodes) == 0 {
			// Zero iterations before any node: the group is one node, any.
			anyNode := generatedVariablePrefix + "qpp_node"
			if err := e.matchQuantifiedChain(ctx, "("+anyNode+")", anyNode, "", done, func(next quantifiedPathState, _ pipelineRow) error {
				delete(next.row, anyNode)
				return e.matchQuantifiedPieces(ctx, m, index+1, next, emit)
			}); err != nil {
				return err
			}
		} else if err := e.matchQuantifiedPieces(ctx, m, index+1, done, emit); err != nil {
			return err
		}
	}
	if piece.max >= 0 && iterations >= piece.max {
		return nil
	}
	iteration := state
	iteration.row = copyPipelineRow(state.row)
	for _, variable := range piece.variables {
		delete(iteration.row, variable)
	}
	return e.matchQuantifiedChain(ctx, piece.chain, piece.first, piece.where, iteration, func(next quantifiedPathState, matched pipelineRow) error {
		extended := make(map[string][]interface{}, len(lists))
		for _, variable := range piece.variables {
			extended[variable] = append(append([]interface{}(nil), lists[variable]...), matched[variable])
		}
		next.row = copyPipelineRow(state.row)
		if piece.deferred != "" {
			values := make(pipelineRow, len(piece.variables))
			for _, variable := range piece.variables {
				values[variable] = matched[variable]
			}
			next.checks = append(append([]quantifiedDeferredCheck(nil), state.checks...), quantifiedDeferredCheck{where: piece.deferred, values: values})
		}
		return e.matchQuantifiedIterations(ctx, m, index, piece, iterations+1, next, extended, emit)
	})
}

// matchQuantifiedChain matches chain (with its own WHERE, where) from
// state: its first node is the path's end node, when the path has one. For
// each match, then gets the extended state and the chain's bindings.
func (e *StorageExecutor) matchQuantifiedChain(ctx context.Context, chain, first, where string, state quantifiedPathState, then func(quantifiedPathState, pipelineRow) error) error {
	row := copyPipelineRow(state.row)
	if len(state.nodes) > 0 {
		end := state.nodes[len(state.nodes)-1]
		if bound, exists := row[first]; exists {
			if node, ok := bound.(*storage.Node); !ok || node == nil || node.ID != end.ID {
				return nil
			}
		}
		row[first] = end
	}
	pathVariable := generatedVariablePrefix + "qpp_chain"
	clause := "MATCH " + pathVariable + " = " + chain
	if where != "" {
		clause += " WHERE " + where
	}
	matched, err := e.pipelineMatchRows(ctx, row, clause)
	if err != nil {
		return err
	}
	repeatable := repeatableElements(ctx)
	for _, result := range matched {
		// The chain's path value carries its PathResult (pathToMap), whose
		// nodes and relationships are storage entities.
		value, _ := result[pathVariable].(map[string]interface{})
		nodes, relationships, _, _ := pathValueParts(value)
		next := quantifiedPathState{row: result, used: state.used, checks: state.checks}
		next.nodes = append([]*storage.Node(nil), state.nodes...)
		next.relationships = append([]*storage.Edge(nil), state.relationships...)
		for i, item := range nodes {
			if i > 0 || len(state.nodes) == 0 {
				next.nodes = append(next.nodes, item.(*storage.Node))
			}
		}
		reused := false
		if !repeatable {
			next.used = make(map[storage.EdgeID]struct{}, len(state.used)+len(relationships))
			for id := range state.used {
				next.used[id] = struct{}{}
			}
		}
		for _, item := range relationships {
			edge := item.(*storage.Edge)
			if !repeatable {
				if _, exists := next.used[edge.ID]; exists {
					reused = true
					break
				}
				next.used[edge.ID] = struct{}{}
			}
			next.relationships = append(next.relationships, edge)
		}
		if reused {
			continue
		}
		delete(next.row, pathVariable)
		if err := then(next, result); err != nil {
			return err
		}
	}
	return nil
}

// copyPipelineRow returns a shallow copy of row.
func copyPipelineRow(row pipelineRow) pipelineRow {
	copied := make(pipelineRow, len(row)+4)
	for name, value := range row {
		copied[name] = value
	}
	return copied
}

// quantifiedGroupSpan is one quantified group of a pattern,
// pattern[open:close+1]: its predicates (its own WHERE and each element's
// inline WHERE, [r WHERE …] / (n WHERE …), each as the [start, end) of its
// WHERE keyword through its body) and the node and relationship variables
// it binds, each to one value per iteration.
type quantifiedGroupSpan struct {
	open, close          int
	predicates           [][2]int
	nodes, relationships []string
}

// quantifiedGroups lists pattern's quantified groups in order, including
// those inside another parenthesis (shortestPath((a)((x)-[r]-(y))+(b)), the
// form SHORTEST k is read as).
func quantifiedGroups(pattern string) []quantifiedGroupSpan {
	var groups []quantifiedGroupSpan
	for index := 0; index < len(pattern); index++ {
		open, close, _, found := quantifiedGroupFrom(pattern, index, true)
		if !found {
			return groups
		}
		group := quantifiedGroupSpan{open: open, close: close}
		elementsEnd := close
		if where := topLevelKeywordIndex(pattern[open+1:close], "WHERE"); where >= 0 {
			elementsEnd = open + 1 + where
			group.predicates = append(group.predicates, [2]int{elementsEnd, close})
		}
		group.predicates = append(group.predicates, elementPredicateSpans(pattern, open+1, elementsEnd)...)
		structure := []byte(pattern[open+1 : elementsEnd])
		for _, span := range group.predicates {
			for index := max(span[0], open+1); index < min(span[1], elementsEnd); index++ {
				structure[index-open-1] = ' '
			}
		}
		// Bound names, as the scope stores them: `x x` is x x.
		group.nodes = normalizedBindingNames(extractNodeVariables(string(structure)))
		group.relationships = normalizedBindingNames(extractRelationshipVariables(string(structure)))
		groups = append(groups, group)
		index = close
	}
	return groups
}

// elementPredicateSpans lists the inline WHERE of each node and relationship
// element in pattern[from:to] ((n WHERE …), [r WHERE …]) as the [start, end)
// of its WHERE keyword through its body.
func elementPredicateSpans(pattern string, from, to int) [][2]int {
	var spans [][2]int
	for index := from; index < to; index++ {
		switch c := pattern[index]; cypherLexicalByte(c) {
		case cypherQuoteClass:
			index = skipCypherQuotedText(pattern, index, c) - 1
		case '(', '[':
			closeBy := map[byte]byte{'(': ')', '[': ']'}[c]
			close := findMatchingDelimiter(pattern, index, rune(c), rune(closeBy))
			if close < 0 || close > to {
				return spans
			}
			if where := topLevelKeywordIndex(pattern[index+1:close], "WHERE"); where >= 0 {
				spans = append(spans, [2]int{index + 1 + where, close})
			}
			index = close
		}
	}
	return spans
}

// predicateTexts are the bodies of the group's predicates in pattern.
func (group quantifiedGroupSpan) predicateTexts(pattern string) []string {
	texts := make([]string, 0, len(group.predicates))
	for _, span := range group.predicates {
		if body := strings.TrimSpace(pattern[span[0]+len("WHERE") : span[1]]); body != "" {
			texts = append(texts, body)
		}
	}
	return texts
}

// maskQuantifiedGroupPredicates blanks each quantified group's predicates
// (its own WHERE and its elements' inline WHERE) so the pattern's
// structure is scanned without them: in
// ((a)-[r]-(b) WHERE size(kinds) = 0)+ neither (kinds) nor a $param map is
// a pattern element, and r there is one relationship, not the list the
// group binds outside it.
func maskQuantifiedGroupPredicates(pattern string) string {
	var masked []byte
	for _, group := range quantifiedGroups(pattern) {
		for _, span := range group.predicates {
			if masked == nil {
				masked = []byte(pattern)
			}
			for index := span[0]; index < span[1]; index++ {
				masked[index] = ' '
			}
		}
	}
	if masked == nil {
		return pattern
	}
	return string(masked)
}

// matchPatternStructure is the pattern of a MATCH body, clause or pattern
// part (the text before its WHERE) with every predicate in it blanked: each
// quantified group's (maskQuantifiedGroupPredicates) and each element's
// inline WHERE. It is the one text the variables a pattern binds are read
// from: in ((x WHERE x.k IN (l))-->(y))+ or the (x WHERE
// __nornic_haslabels(x, (l), false)) a dynamic label $(l) becomes, (l) is
// not a node.
func matchPatternStructure(body string) string {
	if where := topLevelKeywordIndex(body, "WHERE"); where >= 0 {
		body = body[:where]
	}
	body = maskQuantifiedGroupPredicates(body)
	// An element's inline WHERE outside a group ((n WHERE n.k IN (l))) is
	// an expression too.
	spans := elementPredicateSpans(body, 0, len(body))
	if len(spans) == 0 {
		return body
	}
	masked := []byte(body)
	for _, span := range spans {
		for index := span[0]; index < span[1]; index++ {
			masked[index] = ' '
		}
	}
	return string(masked)
}

// quantifiedGroupVariables returns the node and relationship variables
// inside pattern's quantified groups: each binds a list of its values.
func quantifiedGroupVariables(pattern string) (map[string]struct{}, map[string]struct{}) {
	var nodes, relationships map[string]struct{}
	for _, group := range quantifiedGroups(pattern) {
		if nodes == nil {
			nodes, relationships = map[string]struct{}{}, map[string]struct{}{}
		}
		for _, variable := range group.nodes {
			nodes[variable] = struct{}{}
		}
		for _, variable := range group.relationships {
			relationships[variable] = struct{}{}
		}
	}
	return nodes, relationships
}

// quantifiedGroupAt reports whether a quantifier follows the parenthesised
// path that closes at query[close].
func quantifiedGroupAt(query string, close, end int) bool {
	_, ok := relationshipQuantifierAt(query, skipASCIISpaces(query, close+1, end), end)
	return ok
}

// quantifiedGroup rewrites the quantified group query[open:close+1]: its
// elements' predicates (label expressions, element WHERE) join the group's
// own WHERE, which applies to each iteration, not the clause's.
func (r *labelExpressionRewriter) quantifiedGroup(open, close int) error {
	q := r.query
	patternEnd, whereBody := close, -1
	if where := topLevelKeywordIndex(q[open+1:close], "WHERE"); where >= 0 {
		patternEnd = open + 1 + where
		whereBody = skipASCIISpaces(q, patternEnd+len("WHERE"), close)
	}
	if err := quantifiedGroupError(q, open, close, patternEnd); err != nil {
		return err
	}
	var predicates []string
	if err := r.patternElements(open+1, patternEnd, labelPatternMatch, &predicates); err != nil {
		return err
	}
	if whereBody >= 0 {
		if err := r.expression(whereBody, close); err != nil {
			return err
		}
	}
	switch {
	case len(predicates) == 0:
	case whereBody >= 0:
		r.edit(whereBody, whereBody, strings.Join(predicates, " AND ")+" AND (")
		r.edit(trimRightIndex(q, whereBody, close), trimRightIndex(q, whereBody, close), ")")
	default:
		at := trimRightIndex(q, open+1, close)
		r.edit(at, at, " WHERE "+strings.Join(predicates, " AND "))
	}
	return nil
}

// quantifiedGroupQuantifierAt reports whether the + or * at s[at]
// quantifies a parenthesised path: it follows a ')' that closes one.
func quantifiedGroupQuantifierAt(s string, at int) bool {
	close := trimRightIndex(s, 0, at) - 1
	if close < 0 || s[close] != ')' {
		return false
	}
	depth := 0
	for open := close; open >= 0; open-- {
		switch s[open] {
		case ')':
			depth++
		case '(':
			if depth--; depth == 0 {
				return parenthesisedPathAt(s, open, close)
			}
		}
	}
	return false
}

// parenthesisedPathAt reports whether s[open:close+1] is a parenthesised
// path pattern: a node pattern, then a relationship arrow.
func parenthesisedPathAt(s string, open, close int) bool {
	inner := skipASCIISpaces(s, open+1, close)
	if inner >= close || s[inner] != '(' {
		return false
	}
	nodeEnd := findMatchingParen(s[:close], inner)
	if nodeEnd < 0 {
		return false
	}
	arrow := skipASCIISpaces(s, nodeEnd+1, close)
	return arrow+1 < close && (s[arrow] == '-' || s[arrow] == '<') && strings.IndexByte("-[>", s[arrow+1]) >= 0
}

// quantifiedGroupError is Neo4j's SyntaxError for the quantified group
// query[open:close+1] (its path ending at patternEnd), or nil: a group or
// quantifier inside it, a variable-length relationship in it, no
// relationship in it, or bounds that exclude every repetition count.
func quantifiedGroupError(q string, open, close, patternEnd int) error {
	inner := q[open+1 : patternEnd]
	if _, _, _, nested := nextQuantifiedGroup(inner, 0); nested || mayUseRelationshipQuantifier(inner) {
		return labelExpressionSyntaxError(localization.CypherMatchingQuantifiedPathNested())
	}
	if hasVariableLengthRelationship(q, open+1, patternEnd) {
		return labelExpressionSyntaxError(localization.CypherMatchingVariableLengthInQuantifiedPath())
	}
	if !patternHasRelationship(inner) && !strings.Contains(blankQuotedText(inner), "--") {
		return labelExpressionSyntaxError(localization.CypherMatchingQuantifiedPathNoRelationship())
	}
	quantifier, _ := relationshipQuantifierAt(q, skipASCIISpaces(q, close+1, len(q)), len(q))
	return quantifierBoundsError(quantifier)
}

// quantifierBoundsError is Neo4j's SyntaxError for a quantifier with an
// upper bound of 0 or below its lower bound, or nil.
func quantifierBoundsError(quantifier relationshipQuantifier) error {
	switch {
	case quantifier.max == 0:
		return labelExpressionSyntaxError(localization.CypherMatchingQuantifiedPathZeroLimit())
	case quantifier.max > 0 && quantifier.min > quantifier.max:
		return labelExpressionSyntaxError(localization.CypherMatchingQuantifierBoundsReversed())
	}
	return nil
}

// normalizedBindingNames rewrites each name as written (`x x`) to the name
// it binds (x x, normalizeProjectionColumnName), in place.
func normalizedBindingNames(names []string) []string {
	for index, name := range names {
		names[index] = normalizeProjectionColumnName(name)
	}
	return names
}

package cypher

import (
	"context"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// removeItem is one item of a REMOVE clause (parseRemoveItems): labels of a
// node (n:A:$(expr)), a property (n.p), or a dynamic property key (n[expr]).
type removeItem struct {
	variable string
	labels   []labelChainItem
	property string
	// key is the expression of n[expr]; its value names the property at run
	// time (dynamicPropertyKeyOf).
	key string
}

// parseRemoveItems splits a REMOVE body at its top-level commas into items.
// Labels are read by the one label-chain reader (setLabelChainItems), so a
// malformed chain is an error, as is text that is none of the item forms
// (REMOVE n): Neo4j's SyntaxError.
func parseRemoveItems(body string) ([]removeItem, error) {
	parts := splitTopLevelComma(body)
	items := make([]removeItem, 0, len(parts))
	for _, part := range parts {
		item := strings.TrimSpace(part)
		if item == "" {
			continue
		}
		if variable, chain, hasLabels := splitNodeHead(item); hasLabels && isValidIdentifier(variable) {
			labels, err := setLabelChainItems(chain)
			if err != nil {
				return nil, err
			}
			items = append(items, removeItem{variable: variable, labels: labels})
			continue
		}
		receiver, inner, subscript, ok := staticPostfixSplit(item)
		variable := ""
		if ok {
			variable, _, _ = parseSetAssignmentTarget(receiver)
		}
		if !isValidIdentifier(variable) || (subscript && strings.TrimSpace(inner) == "") {
			return nil, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidSyntax", localization.CypherMutationsRemoveItemInvalid(item))
		}
		if subscript {
			items = append(items, removeItem{variable: variable, key: strings.TrimSpace(inner)})
			continue
		}
		items = append(items, removeItem{variable: variable, property: normalizePropertyKey(inner)})
	}
	return items, nil
}

// pipelineApplyRemove applies a REMOVE clause to every row: each item's
// labels and dynamic keys are evaluated in the row's context
// (pipelineRowWriteContext), and each entity the clause names is stored once
// per row. A variable bound to null is skipped; a label item on a
// relationship is a TypeError (labelTargetTypeError). A removed property
// counts in properties_set when the entity had it, a removed label in
// labels_removed.
func (e *StorageExecutor) pipelineApplyRemove(ctx context.Context, rows []pipelineRow, clause string, result *ExecuteResult) error {
	items, err := parseRemoveItems(strings.TrimSpace(clause[len("REMOVE"):]))
	if err != nil {
		return err
	}
	store := e.getStorage(ctx)
	// Only a dynamic label or key reads the row's other values.
	dynamic := false
	for _, item := range items {
		dynamic = dynamic || item.key != ""
		for _, label := range item.labels {
			dynamic = dynamic || label.expression != ""
		}
	}
	touched := make([]interface{}, 0, len(items))
	for _, row := range rows {
		if err := ctx.Err(); err != nil {
			return err
		}
		rowCtx, nodes, rels := ctx, map[string]*storage.Node(nil), map[string]*storage.Edge(nil)
		if dynamic {
			rowCtx, nodes, rels = e.pipelineRowWriteContext(ctx, row)
		}
		touched = touched[:0]
		for _, item := range items {
			propertiesBefore, labelsBefore := result.Stats.PropertiesSet, result.Stats.LabelsRemoved
			switch entity := row[item.variable].(type) {
			case *storage.Node:
				if entity == nil {
					continue
				}
				if err := e.removeFromNode(rowCtx, store, entity, item, nodes, rels, result.Stats); err != nil {
					return err
				}
				if result.Stats.PropertiesSet != propertiesBefore || result.Stats.LabelsRemoved != labelsBefore {
					touched = appendTouchedEntity(touched, entity)
				}
			case *storage.Edge:
				if entity == nil {
					continue
				}
				if len(item.labels) > 0 {
					return labelTargetTypeError("Relationship")
				}
				if err := e.removeProperty(rowCtx, entity.Properties, item, nodes, rels, result.Stats); err != nil {
					return err
				}
				if result.Stats.PropertiesSet != propertiesBefore {
					touched = appendTouchedEntity(touched, entity)
				}
			}
		}
		for _, entity := range touched {
			switch typed := entity.(type) {
			case *storage.Node:
				if err := updateMutatedNode(ctx, store, typed); err != nil {
					return err
				}
				e.notifyNodeMutated(string(typed.ID))
			case *storage.Edge:
				if err := updateMutatedEdge(store, typed); err != nil {
					return err
				}
				e.notifyEdgeMutated(string(typed.ID))
			}
		}
	}
	return nil
}

// appendTouchedEntity appends entity to touched unless it is there already.
func appendTouchedEntity(touched []interface{}, entity interface{}) []interface{} {
	for _, existing := range touched {
		if existing == entity {
			return touched
		}
	}
	return append(touched, entity)
}

// removeFromNode applies one REMOVE item to node: its labels (checked
// against the label policies) or one property.
func (e *StorageExecutor) removeFromNode(ctx context.Context, store storage.Engine, node *storage.Node, item removeItem, nodes map[string]*storage.Node, rels map[string]*storage.Edge, stats *QueryStats) error {
	if len(item.labels) == 0 {
		return e.removeProperty(ctx, node.Properties, item, nodes, rels, stats)
	}
	labels, err := e.chainLabelNames(ctx, item.labels, nodes, rels)
	if err != nil {
		return err
	}
	before := node.Labels
	next, removed := removeNodeLabels(node.Labels, labels)
	if removed == 0 {
		return nil
	}
	node.Labels = next
	if err := validatePolicyOnLabelChange(store, node, before); err != nil {
		node.Labels = before
		return err
	}
	stats.LabelsRemoved += int(removed)
	return nil
}

// removeProperty removes the property one REMOVE item names (n.p, or the
// value of n[expr]) from properties.
func (e *StorageExecutor) removeProperty(ctx context.Context, properties map[string]interface{}, item removeItem, nodes map[string]*storage.Node, rels map[string]*storage.Edge, stats *QueryStats) error {
	name := item.property
	if item.key != "" {
		key, err := e.dynamicPropertyKeyOf(ctx, item.key, nodes, rels, true)
		if err != nil {
			return err
		}
		name = key
	}
	if _, exists := properties[name]; exists && name != "" {
		delete(properties, name)
		stats.PropertiesSet++
	}
	return nil
}

// pipelineRowWriteContext is the context a write clause (SET, REMOVE)
// evaluates a row's expressions in: the row's nodes and relationships as
// entity scopes, and its other values as variables. Request parameters keep
// their own namespace even when a row binds a variable with the same name.
func (e *StorageExecutor) pipelineRowWriteContext(ctx context.Context, row pipelineRow) (context.Context, map[string]*storage.Node, map[string]*storage.Edge) {
	nodes := make(map[string]*storage.Node)
	rels := make(map[string]*storage.Edge)
	var values map[string]interface{}
	for name, value := range row {
		switch entity := value.(type) {
		case *storage.Node:
			nodes[name] = entity
		case *storage.Edge:
			rels[name] = entity
		default:
			if values == nil {
				values = valueBindingsLayer(ctx, len(row))
			}
			values[name] = value
		}
	}
	rowCtx := ctx
	if values != nil {
		rowCtx = withValueBindings(rowCtx, values)
	}
	return rowCtx, nodes, rels
}

package cypher

import (
	"context"

	"github.com/orneryd/nornicdb/pkg/cypher/resultmetadata"
	"github.com/orneryd/nornicdb/pkg/localization"
)

// ResultColumns is the strict ordered-header view of the execution program.
// Unknown facts are an error, never an empty successful header.
func (e *StorageExecutor) ResultColumns(ctx context.Context, query string, incoming resultmetadata.Scope, cypher25 bool) ([]string, error) {
	var columns []string
	var failure error
	program := e.statementProjectionProgram(ctx, query, incoming, cypher25, nil)
	if !program.complete {
		if program.err != nil {
			return nil, program.err
		}
		return nil, unresolvedStatementError()
	}
	program.statement.Columns.Visit(func(known []string) { columns = known }, func() { failure = unresolvedStatementError() })
	return columns, failure
}

func unresolvedStatementError() error {
	return localizedStatusError("Neo.ClientError.Statement.FeatureNotSupported", "UnresolvedStatement", localization.CypherResultMetadataUnresolved())
}

// verifyResultColumns checks stream metadata against the established schema.
// Stream fields are observations; they never replace or reconstruct the owner.
func verifyResultColumns(actual, expected []string) error {
	return resultmetadata.KnownColumns(expected).Verify(actual)
}

func (e *StorageExecutor) resultIncomingScope() resultmetadata.Scope {
	names := make([]string, 0, len(e.fabricRecordBindings))
	for name := range e.fabricRecordBindings {
		names = append(names, name)
	}
	return resultmetadata.KnownScope(names)
}

// StatementColumns is the legacy names-only public view. A nil result denotes
// unresolved or invalid facts and must never be treated as a successful header.
// Execution and rewriting consumers use ResultColumns or StatementFacts.
func (e *StorageExecutor) StatementColumns(query string) []string {
	columns, err := e.StatementResultColumns(query)
	if err != nil {
		return nil
	}
	return columns
}

// StatementResultColumns is the strict public header view with this executor's
// incoming record scope. Rewriters and transaction adapters preserve its error.
func (e *StorageExecutor) StatementResultColumns(query string) ([]string, error) {
	return e.ResultColumns(context.Background(), query, e.resultIncomingScope(), cypherGrammarVersion(query) == "25")
}

// StatementResultColumnsContext is the public execution view, using the same
// participant-signature resolver as Fabric planning before any effects.
func (e *StorageExecutor) StatementResultColumnsContext(ctx context.Context, query string) ([]string, error) {
	var columns []string
	var failure error
	cypher25 := cypherVersionFromContext(ctx) == "25" || cypherGrammarVersion(query) == "25"
	e.statementProjectionProgram(ctx, query, e.resultIncomingScope(), cypher25, e.participantSchemaForStatement(ctx, query)).facts.Visit(func(statement resultmetadata.Statement) {
		statement.Columns.Visit(func(known []string) { columns = known }, func() { failure = unresolvedStatementError() })
	}, func() { failure = unresolvedStatementError() }, func(reason resultmetadata.Unresolved) { failure = reason.Err })
	return columns, failure
}

// knownResultColumns is an optional cached hint for row fast paths. A missing
// hint leaves actual execution responsible; this is not a result-schema source.
func knownResultColumns(names resultmetadata.Names) []string {
	var columns []string
	names.Visit(func(known []string) { columns = known }, func() { columns = nil })
	return columns
}

// CachedResultColumns is a legacy cache-only hint for the Fabric consumers
// being replaced by planned Facts. It never compiles or guesses a cold header.
func (e *StorageExecutor) CachedResultColumns(ctx context.Context, query string, incoming []string) resultmetadata.Names {
	cypher25 := cypherVersionFromContext(ctx) == "25" || cypherGrammarVersion(query) == "25"
	names := make(map[string]struct{}, len(incoming)+len(e.fabricRecordBindings))
	for _, name := range incoming {
		names[name] = struct{}{}
	}
	for name := range e.fabricRecordBindings {
		names[name] = struct{}{}
	}
	key := projectionKey(query, projectedMapNames(names), resultmetadata.Known(nil), cypher25)
	if facts, found := projectionFactsCache.get(key); found && facts.generation == globalProcedureRegistry.generation.Load() && facts.complete {
		names := resultmetadata.Unknown()
		facts.statement.Columns.Visit(func(header []string) { names = resultmetadata.Known(header) }, func() {})
		return names
	}
	return resultmetadata.Unknown()
}

// ResultProjection is the execution descriptor from the owner program. It
// never expands a compound wildcard from the statement's entry scope.
func (e *StorageExecutor) ResultProjection(ctx context.Context, query string, incoming []string) resultmetadata.Projection {
	var projection resultmetadata.Projection
	e.statementProjectionProgram(ctx, query, resultmetadata.KnownScope(incoming), cypherVersionFromContext(ctx) == "25" || cypherGrammarVersion(query) == "25", nil).facts.Visit(func(statement resultmetadata.Statement) {
		if len(statement.Branches) != 0 || len(statement.Clauses) == 0 {
			return
		}
		last := statement.Clauses[len(statement.Clauses)-1]
		if last.Kind == resultmetadata.ClauseReturn && last.Projection != nil {
			projection = *last.Projection
		}
	}, func() { projection = resultmetadata.Projection{} }, func(resultmetadata.Unresolved) { projection = resultmetadata.Projection{} })
	return projection
}

package cypher

import (
	"context"
	cypherantlr "github.com/orneryd/nornicdb/pkg/cypher/antlr"
	"github.com/orneryd/nornicdb/pkg/cypher/resultmetadata"
	"strings"
)

type boundScopeAdmission struct {
	graph     bool
	command   bool
	columns   resultmetadata.Columns
	program   *boundStatementProgram
	statement *resultmetadata.Statement
}

func (admission boundScopeAdmission) verifyColumns(actual []string) error {
	if admission.graph {
		return admission.columns.Verify(actual)
	}
	if admission.command {
		return nil
	} // The typed command continues in its command owner.
	return unresolvedStatementError()
}

// admitBoundStatement is execution's adapter into the shared scope program.
// Administrative commands have a typed command continuation; graph statements
// cannot decline binding or substitute successful empty facts.
func (e *StorageExecutor) admitBoundStatement(ctx context.Context, source string) (boundScopeAdmission, error) {
	// Extensions have a real command continuation with its own syntax and
	// result contract. The graph grammar must not reject them before routing.
	if isNornicExtensionStatement(source) || isSchemaCommandStatement(source) || isSystemCommandNoGraph(source) {
		return boundScopeAdmission{command: true}, nil
	}
	syntax, err := cypherantlr.ParseSyntax(ctx, source, cypherantlr.StatementEntry, cypherVersionFromContext(ctx) == "25")
	if err := ctx.Err(); err != nil {
		return boundScopeAdmission{}, err
	}
	if err != nil {
		// Non-graph commands retain their command owner's terminal diagnostic.
		if startsWithKeywordFold(strings.TrimSpace(source), "SHOW") || startsWithKeywordFold(strings.TrimSpace(source), "DROP") {
			return boundScopeAdmission{command: true}, nil
		}
		return boundScopeAdmission{}, syntaxAdmissionError(ctx, source, err, syntax)
	}
	query := statementSyntaxQuery(syntax)
	if !query.Valid() {
		return boundScopeAdmission{command: true}, nil
	}
	if !query.ChildRule(cypherantlr.CypherParserRULE_regularQuery).Valid() && !query.ChildRule(cypherantlr.CypherParserRULE_standaloneCall).Valid() {
		return boundScopeAdmission{command: true}, admitCommandProjectionItems(ctx, syntax)
	}
	incoming := make([]string, 0, len(e.fabricRecordBindings)+len(valueBindingsFromContext(ctx)))
	for name := range e.fabricRecordBindings {
		incoming = append(incoming, name)
	}
	for name := range valueBindingsFromContext(ctx) {
		incoming = append(incoming, name)
	}
	schema := e.participantSchemaForStatement(ctx, source)
	if schema == nil {
		var retained []string
		for name := range pipelineImports(ctx) {
			retained = append(retained, name)
		}
		program := e.projectedStatementScope(ctx, source, resultmetadata.Known(incoming), resultmetadata.Known(retained), cypherVersionFromContext(ctx) == "25", semanticBodyFromContext(ctx))
		if !program.complete {
			if program.err != nil {
				return boundScopeAdmission{}, program.err
			}
			return boundScopeAdmission{}, unresolvedStatementError()
		}
		return boundScopeAdmission{graph: true, columns: program.statement.Columns, program: program.bound, statement: program.statement}, nil
	}
	admission := boundScopeAdmission{}
	program := e.statementProjectionProgram(ctx, source, resultmetadata.KnownScope(incoming), cypherVersionFromContext(ctx) == "25", schema)
	if err := ctx.Err(); err != nil {
		return boundScopeAdmission{}, err
	}
	program.facts.Visit(func(statement resultmetadata.Statement) {
		admission = boundScopeAdmission{graph: true, columns: statement.Columns, statement: &statement, program: program.bound}
	}, func() { err = unresolvedStatementError() }, func(reason resultmetadata.Unresolved) { err = reason.Err })
	return admission, err
}

// Command schemas remain with the typed command owner. Its retained RETURN
// continuation admits ordered output declarations through the same constructor
// predicate as graph projections; this adapter builds no command namespace.
func admitCommandProjectionItems(ctx context.Context, syntax cypherantlr.StatementSyntax) error {
	names := quotedVariableNamesFor(ctx, syntax.Source())
	var failure error
	syntax.Walk(func(node cypherantlr.SyntaxNode) func() {
		if failure == nil && node.Rule() == cypherantlr.CypherParserRULE_returnSt {
			failure = (*semanticBodyScope)(nil).admitProjectionItems(projectionSemanticsForSyntax(node), pipelineClauseReturn, names)
		}
		return nil
	})
	if ctx.Err() != nil {
		return ctx.Err()
	}
	return failure
}

package cypher

import (
	"context"
	"slices"
	"strings"

	cypherantlr "github.com/orneryd/nornicdb/pkg/cypher/antlr"
	"github.com/orneryd/nornicdb/pkg/cypher/resultmetadata"
	"github.com/orneryd/nornicdb/pkg/localization"
)

type statementBindingID = resultmetadata.BindingID

func boundBindingScope(names resultmetadata.Names, ids map[string]statementBindingID) resultmetadata.Scope {
	scope := resultmetadata.UnknownScope()
	names.Visit(func(names []string) { scope = resultmetadata.KnownBindingScope(names, ids) }, func() {})
	return scope
}

type statementBinding struct {
	id         statementBindingID
	name       string
	start, end int
}
type statementBindingUse struct {
	binding                statementBindingID
	name                   string
	start, end             int
	clauseStart, clauseEnd int
}

// boundStatementProgram is immutable once published by the statement cache.
// Consumers use stable identities and original byte spans, never row positions.
type boundStatementProgram struct {
	syntax      cypherantlr.StatementSyntax
	bindings    []statementBinding
	uses        []statementBindingUse
	projections map[int]*returnProjectionPlan
	calls       map[int]*resultmetadata.Call
	scopes      map[int]resultmetadata.Clause
	bodies      map[int]*semanticBodyScope
	frames      map[int]*semanticBodyScope
	effects     map[int]pipelineClauseEffects
	scalars     map[int]scalarExpressionSyntax
	// Typing consumes these admitted source handles. It cannot construct a
	// second branch/clause schedule or choose names from operand maps.
	root        *boundBody
	clauses     map[int]*boundClause
	expressions map[int]resultmetadata.Scope
	nested      map[int]*boundBody
	nodes       map[int]cypherantlr.SyntaxNode
}

func cloneBindingIDs(input map[string]statementBindingID) map[string]statementBindingID {
	output := make(map[string]statementBindingID, len(input))
	for name, id := range input {
		output[name] = id
	}
	return output
}
func (compilation *boundCompilation) define(name string, start, end int) statementBindingID {
	id := statementBindingID(len(compilation.product.bindings) + 1)
	compilation.product.bindings = append(compilation.product.bindings, statementBinding{id: id, name: name, start: start, end: end})
	return id
}
func (compilation *boundCompilation) defineClause(clause *boundClause) {
	clause.beforeIDs = cloneBindingIDs(clause.branch.ids)
	clause.afterIDs = cloneBindingIDs(clause.beforeIDs)
	var names []string
	for name := range clause.after {
		names = append(names, name)
	}
	slices.Sort(names)
	projected := map[string]returnProjection{}
	if clause.plan != nil {
		for _, item := range clause.plan.projections {
			projected[item.alias] = item
		}
	}
	for _, name := range names {
		if clause.source.kind == pipelineClauseCall {
			if _, output := projectedNameMap(clause.outputs)[name]; output {
				start, end := syntaxDeclarationSpan(clause.source.syntax, name)
				clause.afterIDs[name] = compilation.define(name, start, end)
				continue
			}
		}
		if clause.fresh[name] {
			start, end := syntaxDeclarationSpan(clause.source.syntax, name)
			clause.afterIDs[name] = compilation.define(name, start, end)
			continue
		}
		if item, found := projected[name]; found && (!item.direct || item.variable != item.alias) {
			clause.afterIDs[name] = compilation.define(name, item.definitionStart, item.definitionEnd)
			continue
		}
		if clause.source.kind == pipelineClauseUnwind && name == syntaxSymbolName(clause.source.syntax.ChildRule(cypherantlr.CypherParserRULE_symbol)) {
			symbol := clause.source.syntax.ChildRule(cypherantlr.CypherParserRULE_symbol)
			start, end := symbol.Span()
			clause.afterIDs[name] = compilation.define(name, start, end)
			continue
		}
		if _, exists := clause.afterIDs[name]; !exists {
			start, end := syntaxDeclarationSpan(clause.source.syntax, name)
			clause.afterIDs[name] = compilation.define(name, start, end)
		}
	}
	for name := range clause.afterIDs {
		if _, visible := clause.after[name]; !visible {
			delete(clause.afterIDs, name)
		}
	}
}

func syntaxDeclarationSpan(clause cypherantlr.SyntaxNode, name string) (start, end int) {
	start, end = clause.Span()
	found := false
	clause.Walk(func(node cypherantlr.SyntaxNode) func() {
		if found {
			return nil
		}
		identity, symbol := node.Name()
		if !symbol || identity != name {
			return nil
		}
		if syntaxBindingDefinition(node) {
			start, end = node.Span()
			found = true
		}
		return nil
	})
	return
}

// variableSyntaxRead classifies a decoded symbol by its grammatical role.
// Identifiers used as labels, map/property keys, function names and aliases
// never become expression dependencies.
func variableSyntaxRead(node cypherantlr.SyntaxNode) bool {
	if node.Rule() != cypherantlr.CypherParserRULE_symbol {
		return false
	}
	// normalize's second argument is a grammar keyword, not a variable read.
	if name, named := node.Name(); named {
		if name != "" {
			for ancestor, ok := node.Parent(); ok; ancestor, ok = ancestor.Parent() {
				if ancestor.Rule() == cypherantlr.CypherParserRULE_functionInvocation {
					if invocation := ancestor.ChildRule(cypherantlr.CypherParserRULE_invocationName); invocation.Valid() && strings.EqualFold(invocation.QualifiedName(), "normalize") {
						chain := ancestor.ChildRule(cypherantlr.CypherParserRULE_expressionChain)
						argument := 0
						for index := 0; index < chain.ChildCount(); index++ {
							child := chain.Child(index)
							if child.Rule() != cypherantlr.CypherParserRULE_expression {
								continue
							}
							start, end := child.Span()
							at, until := node.Span()
							if argument == 1 && start == at && end == until {
								return false
							}
							argument++
						}
					}
					break
				}
			}
		}
	}
	parent, ok := node.Parent()
	if !ok {
		return false
	}
	switch parent.Rule() {
	case cypherantlr.CypherParserRULE_atom, cypherantlr.CypherParserRULE_mapProjection, cypherantlr.CypherParserRULE_mapProjectionItem,
		cypherantlr.CypherParserRULE_setItem, cypherantlr.CypherParserRULE_removeItem,
		cypherantlr.CypherParserRULE_nodePattern, cypherantlr.CypherParserRULE_relationDetail:
		return true
	default:
		return false
	}
}

func (compilation *boundCompilation) bindSymbol(ctx context.Context, clause *boundClause, node cypherantlr.SyntaxNode) {
	if !variableSyntaxRead(node) {
		return
	}
	name, _ := node.Name()
	start, end := node.Span()
	scope, identities, restricted := compilation.expressionBindings(clause, node)
	if _, found := scope[name]; !found {
		if _, previous := clause.before[name]; restricted && previous && !clause.branch.body.call {
			compilation.fail(resultmetadata.ReasonUndefinedVariable, start, localizedStatusError(
				"Neo.ClientError.Statement.SyntaxError", "UndefinedVariable", localization.CypherMatchingAggregationScopeVariable(name)))
			return
		}
		if !strings.HasPrefix(node.Text(), "`") {
			semantic := make(matchSemanticScope, len(scope))
			for variable := range scope {
				semantic[variable] = matchBindingUnknown
			}
			if undefinedExpressionVariable(ctx, semantic, node.Text()) == nil {
				return
			}
		}
		compilation.failUndefined(start, name)
		return
	}
	// The canonical expression checker remains the semantic error owner. The
	// CST role has already distinguished a quoted literal-word variable.
	semantic := make(matchSemanticScope, len(scope))
	for variable := range scope {
		semantic[variable] = matchBindingUnknown
	}
	if err := undefinedExpressionVariable(ctx, semantic, "`"+strings.ReplaceAll(name, "`", "``")+"`"); err != nil {
		compilation.failUndefined(start, name)
		return
	}
	id := identities[name]
	if clause.source.kind == pipelineClauseLet && clause.branch.bindings != nil {
		for _, read := range semanticScopeReads(clause.source.syntax) {
			if read.node.ID() == node.ID() {
				clause.branch.bindings.readEvent(read, clause.source.syntax, clause.branch.bindings.entry, nil)
				break
			}
		}
	}
	if clause.source.syntax.Rule() != cypherantlr.CypherParserRULE_useClause && id != 0 && id == clause.branch.input.ids[name] {
		clause.branch.dependencies.readIdentity(name, id)
	}
	if id != 0 {
		definition := compilation.product.bindings[int(id)-1]
		if definition.start == start && definition.end == end {
			return
		}
	}
	compilation.product.uses = append(compilation.product.uses, statementBindingUse{binding: id, name: name, start: start, end: end, clauseStart: clause.source.start, clauseEnd: clause.source.end})
}

func (compilation *boundCompilation) localBindingIdentity(name string, declaration int) statementBindingID {
	key := localIdentityKey{name: name, start: declaration}
	if id := compilation.locals[key]; id != 0 {
		return id
	}
	end := declaration
	for index := 0; index < compilation.product.syntax.TokenCount(); index++ {
		from, to := compilation.product.syntax.Token(index).Span()
		if from == declaration {
			end = to
			break
		}
	}
	id := compilation.define(name, declaration, end)
	compilation.locals[key] = id
	return id
}

type localIdentityKey struct {
	name  string
	start int
}

package cypher

import (
	"context"
	"errors"
	"slices"
	"strings"

	cypherantlr "github.com/orneryd/nornicdb/pkg/cypher/antlr"
	"github.com/orneryd/nornicdb/pkg/cypher/resultmetadata"
	"github.com/orneryd/nornicdb/pkg/localization"
)

// boundCompilation schedules scope transfers on the canonical CST. Binding and
// graph effects observe the same non-pruning traversal. Structure is never read
// again from rewritten fragments, and an effect-cache hit cannot bypass binding.
type boundCompilation struct {
	owner       *projectionCompilation
	events      map[int]*boundEvent
	current     *boundBranch
	clause      *boundClause
	failure     *projectedScopeFacts
	product     *boundStatementProgram
	locals      map[localIdentityKey]statementBindingID
	clauses     map[int]queryBodyClause
	readViews   map[string]resultmetadata.Scope
	localSyntax map[int][]syntaxLocalBinding
}
type boundEvent struct{ enter, leave []func() }

// A body composes branch outputs, never their binding contexts. Keeping every
// input/retained/identity snapshot on its branch prevents a sibling's imports
// from becoming an admission exception in another branch.
type boundBody struct {
	expressionKind string
	bindings       *semanticBodyScope
	dependencies   *semanticDependencyScope
	call           bool // CALL bodies retain their established undefined-read diagnostics.
	start, end     int
	graph          projectionGraph
	branches       []*boundBranch
	program        *projectedScopeFacts
	outputIDs      map[string]statementBindingID
}

// boundBranchSeed supplies candidate names/identities to the transition owner.
// It is not an admitted branch input.
type boundBranchSeed struct {
	incoming, retained resultmetadata.Names
	ids                map[string]statementBindingID
}

// boundBranchInput is a frozen result of semanticBodyScope entry and reads.
// Candidate inputs are supplied separately and never used as admitted facts.
type boundBranchInput struct {
	frame              *semanticBodyScope
	incoming, retained resultmetadata.Names
	ids                map[string]statementBindingID
}
type boundBranch struct {
	pendingUpdate string
	bindings     *semanticBodyScope
	dependencies *semanticDependencyScope

	body      *boundBody
	shape     queryBodyBranch
	input     boundBranchInput
	seed      boundBranchSeed
	scope     map[string]struct{}
	ids       map[string]statementBindingID
	outputs   resultmetadata.Names
	columns   resultmetadata.Columns
	graph     projectionGraph
	statement resultmetadata.Statement
}

func (branch *boundBranch) setInput(incoming, retained resultmetadata.Names, identities map[string]statementBindingID) {
	ids := cloneBindingIDs(identities)
	branch.seed = boundBranchSeed{incoming: incoming, retained: retained, ids: ids}
}

// Shared enclosing scope is seeded independently; subsequent projection
// transfers and CALL import rules can only change the selected branch.
func (body *boundBody) setInputs(incoming, retained resultmetadata.Names, identities map[string]statementBindingID) {
	for _, branch := range body.branches {
		branch.setInput(incoming, retained, identities)
	}
}

type boundClause struct {
	procedureArity      *boundProcedureArity
	fresh               map[string]bool
	branch              *boundBranch
	source              queryBodyClause
	step                resultmetadata.Clause
	before, after       map[string]struct{}
	localProjection     map[string]struct{}
	beforeIDs, afterIDs map[string]statementBindingID
	outputs             resultmetadata.Names
	plan                *returnProjectionPlan
	writtenPlan         *returnProjectionPlan
	projectionSyntax    []cypherantlr.SyntaxNode
	body                *boundBody
	expressionDepth     int
}

func (compiler *projectionCompilation) compileBound(ctx context.Context, incoming, retained resultmetadata.Names) *projectedScopeFacts {
	if compiler.cypher25 {
		ctx = context.WithValue(ctx, cypherVersionKey{}, "25")
	}
	syntax, err := cypherantlr.ParseSyntax(ctx, compiler.source, cypherantlr.StatementEntry, compiler.cypher25)
	if ctx.Err() != nil {
		return programFailure(resultmetadata.ReasonParserDecline, 0, ctx.Err())
	}
	if err != nil {
		return programFailure(resultmetadata.ReasonParserDecline, 0, syntaxAdmissionError(ctx, compiler.source, err, syntax))
	}
	compiler.syntax = syntax
	compiler.names = quotedVariableNamesFor(ctx, compiler.source)
	query := statementSyntaxQuery(syntax)
	if !query.Valid() {
		return programFailure(resultmetadata.ReasonParserDecline, 0, nil)
	}
	start, end := query.Span()
	if _, command, failure := parseProcedurePrivilegeCommand(compiler.source[start:end]); command {
		if failure != nil {
			return programFailure(resultmetadata.ReasonUnsupportedSyntax, start, failure)
		}
		scope := projectionScope(incoming)
		statement := resultmetadata.Statement{Start: start, End: end, Incoming: scope, Retained: projectionScope(retained), After: scope, Columns: resultmetadata.KnownColumns(nil), Command: &resultmetadata.Command{Text: compiler.source[start:end]}}
		return &projectedScopeFacts{after: incoming, outputs: resultmetadata.Known(nil), statement: &statement}
	}
	// These commands already declare their fixed schema in the typed SHOW
	// owner. EXPLAIN reads that declaration without enumerating users.
	show := query.ChildRule(cypherantlr.CypherParserRULE_showCommand)
	if show.Valid() && !show.ChildRule(cypherantlr.CypherParserRULE_showTail).Valid() &&
		(startsWithKeywords(show.Code(), "SHOW", "USERS") || startsWithKeywords(show.Code(), "SHOW", "CURRENT USER")) {
		names := resultmetadata.Known(showUsersColumns)
		scope := projectionScope(names)
		statement := resultmetadata.Statement{Start: start, End: end, Incoming: projectionScope(incoming), Retained: projectionScope(retained), After: scope, Columns: resultmetadata.KnownColumns(showUsersColumns), Command: &resultmetadata.Command{Text: compiler.source[start:end]}}
		return &projectedScopeFacts{after: names, outputs: names, statement: &statement}
	}
	compilation := &boundCompilation{owner: compiler, events: map[int]*boundEvent{}, product: &boundStatementProgram{syntax: syntax, projections: map[int]*returnProjectionPlan{}, scopes: map[int]resultmetadata.Clause{}, bodies: map[int]*semanticBodyScope{}, effects: map[int]pipelineClauseEffects{}, scalars: map[int]scalarExpressionSyntax{}, calls: map[int]*resultmetadata.Call{}}, locals: map[localIdentityKey]statementBindingID{}, clauses: map[int]queryBodyClause{}, localSyntax: map[int][]syntaxLocalBinding{}}
	compilation.product.clauses = make(map[int]*boundClause)
	compilation.product.expressions = make(map[int]resultmetadata.Scope)
	compilation.product.nested = make(map[int]*boundBody)
	compilation.product.nodes = make(map[int]cypherantlr.SyntaxNode)
	compilation.readViews = make(map[string]resultmetadata.Scope)
	body := compilation.prepareBody(ctx, queryBodyFromSyntax(query), query, start, end)
	compilation.product.root = body
	body.bindings = compiler.bindings
	if compiler.scalarKind != "" {
		body.expressionKind = compiler.scalarKind
		body.bindings = body.bindings.scalarChild(bindingTypes(projectedNameMap(incoming)))
	}
	if body.bindings == nil {
		body.bindings = &semanticBodyScope{entry: bindingTypes(projectedNameMap(incoming)), carried: bindingTypes(projectedNameMap(retained)), retained: bindingTypes(projectedNameMap(retained)), original: bindingTypes(projectedNameMap(retained))}
	}
	body.dependencies = newSemanticDependencies(body.bindings.visible(body.bindings.entry))
	incomingIDs := map[string]statementBindingID{}
	input := projectedNameMap(incoming)
	if input != nil && body.bindings != nil {
		for name := range body.bindings.visible(body.bindings.entry) {
			input[name] = struct{}{}
		}
	}
	var inputNames []string
	for name := range input {
		inputNames = append(inputNames, name)
	}
	slices.Sort(inputNames)
	for _, name := range inputNames {
		incomingIDs[name] = compilation.define(name, -1, -1)
	}
	body.setInputs(incoming, retained, incomingIDs)
	var effects pipelineClauseEffects
	syntax.Walk(compilation.visitor(ctx), compilation.metadataVisitor(&effects))
	if compilation.failure != nil {
		return compilation.failure
	}
	if body.program == nil {
		return programFailure(resultmetadata.ReasonParserDecline, start, nil)
	}
	if ctx.Err() != nil {
		return programFailure(resultmetadata.ReasonParserDecline, start, ctx.Err())
	}
	pipelineClauseEffectCache.put("\x00"+compiler.source, effects)
	body.program.bound = compilation.product
	return body.program
}

func (compilation *boundCompilation) event(node cypherantlr.SyntaxNode) *boundEvent {
	event := compilation.events[node.ID()]
	if event == nil {
		event = &boundEvent{}
		compilation.events[node.ID()] = event
	}
	return event
}
func (compilation *boundCompilation) fail(reason resultmetadata.UnresolvedReason, position int, err error) {
	if compilation.failure == nil {
		compilation.failure = programFailure(reason, position, err)
	}
}
func (compilation *boundCompilation) prepareBody(ctx context.Context, shape queryBody, root cypherantlr.SyntaxNode, start, end int) *boundBody {
	body := &boundBody{start: start, end: end}
	if shape.status != queryBodyRead || len(shape.branches) == 0 {
		err := error(nil)
		reason := resultmetadata.ReasonParserDecline
		if shape.status == queryBodyMixedUnion {
			reason = resultmetadata.ReasonUnsupportedSyntax
			err = unionMixedError()
		}
		compilation.event(root).enter = append(compilation.event(root).enter, func() { compilation.fail(reason, start, err) })
		return body
	}
	// Registered first: reverse-order leaves finish branches before their body.
	compilation.event(root).leave = append(compilation.event(root).leave, func() { compilation.finishBody(body) })
	for branchIndex, branchShape := range shape.branches {
		branch := &boundBranch{body: body, shape: branchShape}
		body.branches = append(body.branches, branch)
		first, last := root, root
		if len(branchShape.clauses) > 0 {
			first = branchShape.clauses[0].syntax
			last = branchShape.clauses[len(branchShape.clauses)-1].syntax
		}
		for _, use := range branchShape.useNodes() {
			useStart, _ := use.Span()
			firstStart, _ := first.Span()
			lastStart, _ := last.Span()
			if useStart < firstStart || len(branchShape.clauses) == 0 && first.ID() == root.ID() {
				first = use
			}
			if useStart > lastStart || len(branchShape.clauses) == 0 && last.ID() == root.ID() {
				last = use
			}
		}
		if branchShape.finished {
			last = branchShape.finishSyntax
			if len(branchShape.clauses) == 0 && !branchShape.useSyntax.Valid() {
				first = last
			}
		}
		var previousBranch *boundBranch
		var previousClause *boundClause
		compilation.event(first).enter = append(compilation.event(first).enter, func() {
			previousBranch, previousClause = compilation.current, compilation.clause
			compilation.current, compilation.clause = branch, nil
			branch.scope = projectedNameMap(branch.seed.incoming)
			if err := compilation.enterBodyScope(ctx, branch, branchIndex); err != nil {
				compilation.fail(resultmetadata.ReasonInvalidImport, branchShape.start, err)
				return
			}
			// Initial identities are immutable. Each clause's transfer creates
			// new before/after maps rather than modifying this snapshot.
			branch.ids = cloneBindingIDs(branch.input.ids)
			branch.graph = body.graph
			branch.outputs = resultmetadata.Known(nil)
			branch.columns = resultmetadata.KnownColumns(nil)
			branch.statement = resultmetadata.Statement{Start: branchShape.start, End: branchShape.end, Incoming: boundBindingScope(branch.input.incoming, branch.input.ids), Retained: boundBindingScope(branch.input.retained, branch.input.ids)}
			if branch.scope == nil || projectedNameMap(branch.input.retained) == nil {
				compilation.fail(resultmetadata.ReasonDynamicSchema, branchShape.start, nil)
			}
		})
		compilation.event(last).leave = append(compilation.event(last).leave, func() {
			if compilation.failure != nil {
				compilation.current, compilation.clause = previousBranch, previousClause
				return
			}
			branch.freezeInput()
			branch.statement.Entry = branch.input.frame.horizon(branch.input.ids, branch.input.ids, branch.dependencies)
			branch.statement.Exit = branch.bindings.horizon(branch.ids, branch.input.ids, branch.dependencies)
			branch.statement.After = boundBindingScope(projectedMapNames(branch.scope), branch.ids)
			branch.statement.Columns = branch.columns
			compileFragmentHorizons(&branch.statement)
			compilation.current, compilation.clause = previousBranch, previousClause
		})
		for _, use := range branchShape.useNodes() {
			compilation.prepareUse(ctx, branch, use)
		}
		if branchShape.finished {
			compilation.event(branchShape.finishSyntax).enter = append(compilation.event(branchShape.finishSyntax).enter, func() {
				scope := boundBindingScope(projectedMapNames(branch.scope), branch.ids)
				branch.statement.Clauses = append(branch.statement.Clauses, resultmetadata.Clause{Kind: resultmetadata.ClauseFinish, Start: branchShape.finishStart, End: branchShape.finishEnd, Before: scope, After: scope, Entry: branch.bindings.horizon(branch.ids, branch.input.ids, branch.dependencies), Exit: branch.bindings.horizon(branch.ids, branch.input.ids, branch.dependencies)})
				branch.outputs = resultmetadata.Known(nil)
				branch.columns = resultmetadata.KnownColumns(nil)
			})
		}
		for _, clause := range branchShape.clauses {
			compilation.prepareClause(ctx, branch, clause)
		}
	}
	return body
}

func (compilation *boundCompilation) prepareUse(ctx context.Context, branch *boundBranch, node cypherantlr.SyntaxNode) {
	var prior *boundClause
	compilation.event(node).enter = append(compilation.event(node).enter, func() {
		prior = compilation.clause
		start, end := node.Span()
		if !node.ChildRule(cypherantlr.CypherParserRULE_functionInvocation).Valid() && strings.EqualFold(node.QualifiedName(), "system") {
			if err := systemDatabaseStatementError(ctx, strings.TrimSpace(compilation.owner.source[end:branch.shape.end])); err != nil {
				compilation.fail(resultmetadata.ReasonUnsupportedSyntax, start, err)
				return
			}
		}
		branch.graph = projectionGraph{start: start, end: end, selected: true, outer: branch.body.graph.outer, outerIDs: branch.body.graph.outerIDs}
		if parent, ok := node.Parent(); ok && parent.Rule() == cypherantlr.CypherParserRULE_query {
			branch.body.graph = branch.graph
		}
		input := copyBindingNames(branch.scope)
		for name := range projectedNameMap(branch.body.graph.outer) {
			input[name] = struct{}{}
		}
		ids := cloneBindingIDs(branch.ids)
		for name, id := range branch.body.graph.outerIDs {
			if _, current := ids[name]; !current {
				ids[name] = id
			}
		}
		compilation.clause = &boundClause{branch: branch, source: queryBodyClause{pipelineClause: pipelineClause{syntax: node}}, before: input, after: input, beforeIDs: ids, afterIDs: ids}
		scope := boundBindingScope(projectedMapNames(branch.scope), branch.ids)
		branch.statement.Clauses = append(branch.statement.Clauses, resultmetadata.Clause{Kind: resultmetadata.ClauseUse, Start: start, End: end, Before: scope, After: scope, Routing: boundBindingScope(projectedMapNames(input), ids), Graph: boundGraphSelection(node), Entry: branch.bindings.horizon(branch.ids, branch.input.ids, branch.dependencies), Exit: branch.bindings.horizon(branch.ids, branch.input.ids, branch.dependencies)})
	})
	compilation.event(node).leave = append(compilation.event(node).leave, func() { compilation.clause = prior })
}

func (compilation *boundCompilation) prepareClause(ctx context.Context, branch *boundBranch, source queryBodyClause) {
	compilation.clauses[source.syntax.ID()] = source
	clause := &boundClause{branch: branch, source: source}
	compilation.product.clauses[source.syntax.ID()] = clause
	var prior *boundClause
	compilation.event(source.syntax).enter = append(compilation.event(source.syntax).enter, func() {
		prior = compilation.clause
		compilation.clause = clause
		if compilation.failure != nil {
			return
		}
		if source.kind == pipelineClauseReturn && strings.EqualFold(strings.TrimSpace(pipelineClauseBody(source.text, "RETURN")), "distinct") {
			tail := strings.TrimSpace(compilation.owner.source[source.end:])
			if startsWithKeywordFold(tail, "UNION") && !startsWithKeywordFold(strings.TrimSpace(tail[len("UNION"):]), "ALL") {
				// DISTINCT consumes UNION as its operand in Neo4j; it is
				// a variable reference here, rather than a composition boundary.
				compilation.fail(resultmetadata.ReasonUndefinedVariable, source.end, createUndefinedVariableError("UNION"))
				return
			}
		}
		compilation.enterClause(ctx, clause)
		compilation.defineClause(clause)
	})
	compilation.event(source.syntax).leave = append(compilation.event(source.syntax).leave, func() {
		if compilation.failure == nil {
			compilation.leaveClause(ctx, clause)
		}
		compilation.clause = prior
	})
	if source.kind == pipelineClauseCallSubquery {
		node := source.syntax.ChildRule(cypherantlr.CypherParserRULE_subqueryBody)
		start, end, _ := callClauseBody(ctx, source)
		clause.body = compilation.prepareBody(ctx, queryBodyFromSyntax(node), node, start, end)
		clause.body.call = true
	}
	if source.kind == pipelineClauseForeach {
		clause.body = compilation.prepareBody(ctx, queryBodyFromSyntax(source.syntax), source.syntax, source.start, source.end)
	}
	// Expression subqueries have an isolated projected scope. Their names do
	// not leak out of the expression, but every input read must still bind.
	source.syntax.Walk(func(node cypherantlr.SyntaxNode) func() {
		if node.ID() == source.syntax.ID() {
			return nil
		}
		switch node.Rule() {
		case cypherantlr.CypherParserRULE_existsSubquery, cypherantlr.CypherParserRULE_subqueryExist, cypherantlr.CypherParserRULE_countSubquery, cypherantlr.CypherParserRULE_collectSubquery:
		default:
			return nil
		}
		// Nested clause owners registered their bodies recursively. Header
		// expressions outside a CALL body (transaction batch/parameters) are
		// still owned here and must not disappear with the child-body cut.
		if compilation.product.nested[node.ID()] != nil {
			return nil
		}
		shape, bodyNode, found := queryExpressionBody(node)
		if !found {
			return nil
		}
		// Only the expression bodies owned by this clause. A nested CALL's
		// compiler registers its own expression bodies.
		for parent, ok := node.Parent(); ok && parent.ID() != source.syntax.ID(); parent, ok = parent.Parent() {
			if parent.Rule() == cypherantlr.CypherParserRULE_callSubquery || parent.Rule() == cypherantlr.CypherParserRULE_collectSubquery || parent.Rule() == cypherantlr.CypherParserRULE_countSubquery || parent.Rule() == cypherantlr.CypherParserRULE_existsSubquery || parent.Rule() == cypherantlr.CypherParserRULE_subqueryExist {
				return nil
			}
		}
		start, end := bodyNode.Span()
		nested := compilation.prepareBody(ctx, shape, bodyNode, start, end)
		compilation.product.nested[node.ID()] = nested
		switch node.Rule() {
		case cypherantlr.CypherParserRULE_existsSubquery, cypherantlr.CypherParserRULE_subqueryExist:
			nested.expressionKind = "EXISTS"
		case cypherantlr.CypherParserRULE_countSubquery:
			nested.expressionKind = "COUNT"
		case cypherantlr.CypherParserRULE_collectSubquery:
			nested.expressionKind = "COLLECT"
		}
		initialize := func() {
			scope, ids, _ := compilation.expressionBindings(clause, node)
			nested.setInputs(projectedMapNames(scope), projectedMapNames(scope), ids)
			nested.bindings = branch.bindings.scalarChild(bindingTypes(scope))
			compilation.scopeFrame(nested.start, nested.bindings)
			nested.dependencies = newSemanticDependencies(bindingTypes(scope))
			nested.dependencies.parent = branch.dependencies
			nested.graph = branch.graph
		}
		event := compilation.event(node)
		if bodyNode.ID() == node.ID() {
			event.enter = append([]func(){initialize}, event.enter...)
		} else {
			event.enter = append(event.enter, initialize)
		}
		return nil
	})
}

func copyBindingNames(scope map[string]struct{}) map[string]struct{} {
	copy := make(map[string]struct{}, len(scope))
	for name := range scope {
		copy[name] = struct{}{}
	}
	return copy
}

func (compilation *boundCompilation) enterClause(ctx context.Context, clause *boundClause) {
	branch, source := clause.branch, clause.source
	if previous := branch.statement.Clauses; len(previous) > 0 && previous[len(previous)-1].Kind == resultmetadata.ClauseReturn {
		token := strings.Fields(source.text)[0]
		compilation.fail(resultmetadata.ReasonUnsupportedSyntax, source.start, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", localization.CypherCoreInvalidInput(token)))
		return
	}
	if err := compilation.admitClauseTransition(clause); err != nil {
		compilation.fail(resultmetadata.ReasonUnsupportedSyntax, source.start, err)
		return
	}
	if class, _ := clauseAdmissionClass(clause); branch.body.expressionKind != "" && class.updating {
		compilation.fail(resultmetadata.ReasonUnsupportedSyntax, source.start, &classifiedCypherError{cause: localizedError(expressionBodyUpdatesMessages[branch.body.expressionKind](), nil), code: "Neo.ClientError.Statement.SyntaxError", detail: "InvalidClauseComposition"})
		return
	}
	if source.kind == pipelineClauseMatch || source.kind == pipelineClauseOptionalMatch {
		if err := branch.bindings.admitPatternDeclarations(ctx, source.pipelineClause); err != nil {
			compilation.fail(resultmetadata.ReasonInvalidImport, source.start, err)
			return
		}
	}
	if err := compilation.admitMutationClause(ctx, clause); err != nil {
		compilation.fail(resultmetadata.ReasonInvalidImport, source.start, err)
		return
	}
	compilation.beginBodyClause(ctx, clause)
	if body := branch.bindings; body != nil {
		compilation.product.bodies[source.syntax.ID()] = body.clone(body.entry)
	}
	clause.before = copyBindingNames(branch.scope)
	clause.after = copyBindingNames(branch.scope)
	clause.outputs = resultmetadata.Known(nil)
	clause.step = resultmetadata.Clause{Start: source.start, End: source.end, Before: projectionScope(projectedMapNames(clause.before))}
	switch source.kind {
	case pipelineClauseWith, pipelineClauseReturn:
		clause.step.Kind = resultmetadata.ClauseReturn
		if source.kind == pipelineClauseWith {
			clause.step.Kind = resultmetadata.ClauseWith
		}
		projectionRule := projectionSemanticsForSyntax(source.syntax)
		if err := branch.bindings.admitProjectionItems(projectionRule, source.kind, compilation.owner.names); err != nil {
			compilation.fail(resultmetadata.ReasonInvalidImport, source.start, err)
			return
		}
		plan := projectionPlanFromSemantics(projectionRule, func(expression cypherantlr.SyntaxNode) {
			clause.projectionSyntax = append(clause.projectionSyntax, expression)
		})
		if !plan.valid {
			compilation.fail(resultmetadata.ReasonParserDecline, source.start, nil)
			return
		}
		if branch.bindings != nil {
			clause.localProjection = projectionPlanScope(plan, bindingNames(branch.bindings.projection(branch.bindings.entry)))
		}
		clause.writtenPlan = plan
		writtenWildcard := plan.star
		if plan.star {
			current := bindingNames(branch.bindings.projection(branch.bindings.entry))
			if len(current) == 0 && source.kind == pipelineClauseReturn {
				compilation.fail(resultmetadata.ReasonUndefinedVariable, source.start, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "NoVariablesInScope", localization.CypherMatchingReturnStarNoVariables()))
				return
			}
			for name := range current {
				branch.dependencies.readIdentity(name, branch.ids[name])
			}
			plan = plan.withStarExpanded(pipelineScopeColumns(current))
		}
		for _, item := range plan.projections {
			if !item.direct || item.variable != item.alias {
				if err := branch.bindings.admitDeclaration(item.alias, "WITH"); err != nil {
					compilation.fail(resultmetadata.ReasonInvalidImport, source.start, err)
					return
				}
			}

		}
		clause.plan = plan
		clause.outputs = resultmetadata.Known(plan.columns)
		clause.after = projectionPlanScope(plan, clause.before)
		if source.kind == pipelineClauseWith {

			clause.outputs = resultmetadata.Known(nil)
		}
		projection := projectionDescriptor(plan)
		projection.WrittenWildcard = writtenWildcard
		var writtenNames []string
		projectionRule.eachItem(func(item projectionSemanticItem) {
			writtenNames = append(writtenNames, item.writtenName(compilation.owner.names))
		})
		projection.WrittenNames = resultmetadata.Known(writtenNames)
		projection.Standalone = len(branch.shape.clauses) == 1 && source.kind == pipelineClauseReturn
		clause.step.Projection = &projection
	case pipelineClauseMatch, pipelineClauseOptionalMatch, pipelineClauseCreate, pipelineClauseMerge:
		clause.step.Kind = resultmetadata.ClauseWrite
		if source.kind == pipelineClauseMatch {
			clause.step.Kind = resultmetadata.ClauseMatch
		}
		if source.kind == pipelineClauseOptionalMatch {
			clause.step.Kind = resultmetadata.ClauseOptionalMatch
		}
		addSyntaxPatternBindings(clause.after, source.syntax)
	case pipelineClauseUnwind:
		symbol := source.syntax.ChildRule(cypherantlr.CypherParserRULE_symbol)
		form := "UNWIND"
		if source.syntax.Rule() == cypherantlr.CypherParserRULE_forSt {
			form = "FOR"
		}
		if err := branch.bindings.admitDeclaration(syntaxSymbolName(symbol), form); err != nil {
			compilation.fail(resultmetadata.ReasonInvalidImport, source.start, err)
			return
		}
		clause.step.Kind = resultmetadata.ClauseUnwind
		if !symbol.Valid() {
			compilation.fail(resultmetadata.ReasonParserDecline, source.start, nil)
			return
		}
		name := syntaxSymbolName(symbol)
		clause.after[name] = struct{}{}
	case pipelineClauseLet:
		clause.step.Kind = resultmetadata.ClauseLet
	case pipelineClauseFilter:
		clause.step.Kind = resultmetadata.ClauseFilter
	case pipelineClauseCall:
		compilation.procedure(ctx, clause)
	case pipelineClauseCallSubquery:
		clause.step.Kind = resultmetadata.ClauseCallSubquery
		compilation.callImports(clause)
	case pipelineClauseForeach:
		clause.step.Kind = resultmetadata.ClauseWrite
		inner := copyBindingNames(clause.before)
		inner[syntaxSymbolName(source.syntax.ChildRule(cypherantlr.CypherParserRULE_symbol))] = struct{}{}
		identities := cloneBindingIDs(branch.ids)
		iterator := source.syntax.ChildRule(cypherantlr.CypherParserRULE_symbol)
		from, to := iterator.Span()
		identities[syntaxSymbolName(iterator)] = compilation.define(syntaxSymbolName(iterator), from, to)
		clause.body.setInputs(projectedMapNames(inner), resultmetadata.Known(nil), identities)
		clause.body.graph = branch.graph
		if branch.bindings != nil {
			clause.body.bindings = branch.bindings.localChild(syntaxSymbolName(iterator))
			clause.body.dependencies = branch.dependencies.nested()
		}
	case pipelineClauseDelete, pipelineClauseSet, pipelineClauseRemove:
		clause.step.Kind = resultmetadata.ClauseWrite
	default:
		compilation.fail(resultmetadata.ReasonUnsupportedSyntax, source.start, nil)
	}
}

func (compilation *boundCompilation) leaveClause(ctx context.Context, clause *boundClause) {
	// Reads are admitted first, preserving their release diagnostic precedence.
	if err := compilation.admitClauseSyntax(clause); err != nil {
		compilation.fail(resultmetadata.ReasonUnsupportedSyntax, clause.source.start, err)
		return
	}
	// Structural projection rules still run in this constructor, before any
	// clause facts or executable headers can be published.
	if clause.writtenPlan != nil {
		if err := clause.branch.bindings.admitScalarAggregation(clause.writtenPlan, compilation.owner.cypher25); err != nil {
			compilation.fail(resultmetadata.ReasonUnsupportedSyntax, clause.source.start, err)
			return
		}
		if err := validateProjectionAggregatePlan(clause.writtenPlan, clause.branch.bindings.aggregateConstants()); err != nil {
			compilation.fail(resultmetadata.ReasonUnsupportedSyntax, clause.source.start, err)
			return
		}
		projection := projectionSemanticsForSyntax(clause.source.syntax)
		order := projection.body.ChildRule(cypherantlr.CypherParserRULE_orderSt)
		if order.Valid() {
			if err := validateReturnOrderPlan(ctx, clause.writtenPlan, order.Code(), clause.branch.bindings.orderConstants()); err != nil {
				compilation.fail(resultmetadata.ReasonUnsupportedSyntax, clause.source.start, err)
				return
			}
		}
	}
	if clause.plan != nil {
		compilation.product.projections[clause.source.syntax.ID()] = clause.plan
	}
	if clause.source.kind == pipelineClauseCallSubquery {
		program := clause.body.program
		if program == nil || program.statement == nil {
			compilation.fail(resultmetadata.ReasonDynamicSchema, clause.source.start, nil)
			return
		}
		call := clause.step.Call
		if clause.body.bindings != nil && clause.body.bindings.bare {
			call.Imports = nil
			for name := range clause.body.dependencies.reads {
				call.Imports = append(call.Imports, name)
			}
			slices.Sort(call.Imports)
		}
		call.Statement = program.statement
		call.Routing = boundCallRouting(program.statement, boundBindingScope(projectedMapNames(clause.before), clause.beforeIDs))
		call.Kind = resultmetadata.CallUnit
		clause.outputs = resultmetadata.Known(nil)
		if statementHasReturningOperator(*program.statement) {
			call.Kind = resultmetadata.CallReturning
			clause.outputs = program.outputs
		}
		columns := scopeValues(projectionScope(clause.outputs))
		if err := clause.branch.bindings.admitExports(clause.branch.bindings.entry, columns, func(name string) bool {
			input := clause.beforeIDs[name]
			if input == 0 {
				return false
			}
			for _, branch := range clause.body.branches {
				if branch.ids[name] != input {
					return false
				}
			}
			return true
		}); err != nil {
			compilation.fail(resultmetadata.ReasonInvalidImport, clause.source.start, err)
			return
		}
		call.Body = projectionColumns(clause.outputs)
		for name := range projectedNameMap(clause.outputs) {
			clause.after[name] = struct{}{}
			clause.afterIDs[name] = clause.body.outputIDs[name]
		}
		call.After = boundBindingScope(projectedMapNames(clause.after), clause.afterIDs)
		if statementUsesParticipant(*program.statement) {
			call.Resolution = resultmetadata.ResolvedByParticipant
		}
		compilation.product.calls[clause.source.syntax.ID()] = call
	}
	clause.step.Entry = compilation.product.bodies[clause.source.syntax.ID()].horizon(clause.beforeIDs, clause.branch.input.ids, clause.branch.dependencies)
	compilation.finishBodyClause(ctx, clause)
	for name := range clause.after {
		if clause.afterIDs[name] == 0 {
			clause.afterIDs[name] = clause.beforeIDs[name]
		}
	}
	// Result membership can omit a readable retained binding (RETURN x).
	// Preserve its current value identity for every declared horizon.
	readableIDs := cloneBindingIDs(clause.beforeIDs)
	for name, id := range clause.afterIDs {
		readableIDs[name] = id
	}
	clause.step.Exit = clause.branch.bindings.horizon(readableIDs, clause.branch.input.ids, clause.branch.dependencies)
	clause.step.Before = boundBindingScope(projectedMapNames(clause.before), clause.beforeIDs)
	clause.step.After = boundBindingScope(projectedMapNames(clause.after), clause.afterIDs)
	if clause.source.kind == pipelineClauseWith {
		_, clause.step.Projection.ItemsEnd = projectionSemanticsForSyntax(clause.source.syntax).items.Span()
		projected := projectedNameMap(clause.step.Projection.Names)
		for _, name := range scopeValues(clause.branch.statement.Retained) {
			entry, _ := clause.branch.statement.Retained.Binding(name)
			current := clause.afterIDs[name]
			if _, output := projected[name]; !output && current != 0 && current != entry {
				clause.step.Projection.Retention = append(clause.step.Projection.Retention, resultmetadata.RetainedProjection{Name: name, Entry: entry, Aggregate: clause.plan.hasAggregate || clause.plan.distinct})
			}
		}
	}
	compilation.product.scopes[clause.source.syntax.ID()] = clause.step
	clause.branch.statement.Clauses = append(clause.branch.statement.Clauses, clause.step)
	compilation.advanceClauseAdmission(clause)
	clause.branch.scope, clause.branch.outputs = clause.after, clause.outputs
	clause.branch.columns = projectionColumns(clause.outputs)
	if clause.source.kind == pipelineClauseCall {
		node := clause.source.syntax
		proc, found := globalProcedureRegistry.Get(node.ChildRule(cypherantlr.CypherParserRULE_invocationName).QualifiedName())
		yield := yieldFromSyntax(node)
		if found && proc.Spec.ResultSchemas != nil && (yield == nil || yield.yieldAll) {
			clause.branch.columns = resultmetadata.KnownColumnAlternatives(proc.Spec.ResultSchemas())
		}
	}
	clause.branch.ids = readableIDs
}

func (compilation *boundCompilation) finishBody(body *boundBody) {
	if compilation.failure != nil {
		return
	}
	for _, branch := range body.branches {
		// NornicDB extension: a written terminal RETURN * is accepted when its
		// expanded result has exactly one column, including empty input. The
		// spelling alone is not a rejection; Cypher's one-column
		// COLLECT contract is admitted here once for RUN/EXPLAIN/PROFILE.
		if body.expressionKind == "COLLECT" && !body.call {

			if len(canonicalColumns(branch.columns)) != 1 || branch.shape.finished || len(branch.shape.clauses) == 0 || branch.shape.clauses[len(branch.shape.clauses)-1].kind != pipelineClauseReturn {
				compilation.fail(resultmetadata.ReasonUnsupportedSyntax, branch.shape.start, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "InvalidCollectSubquery", localization.CypherSubqueriesCollectSingleColumn(len(canonicalColumns(branch.columns)))))
				return
			}
		}
		if !body.call || branch.shape.finished || len(branch.shape.clauses) == 0 {
			continue
		}
		last := branch.shape.clauses[len(branch.shape.clauses)-1]
		keyword := queryBodyEndings[last.kind]
		if last.kind == pipelineClauseCallSubquery {
			if call := compilation.product.calls[last.syntax.ID()]; call != nil && call.Kind == resultmetadata.CallUnit {
				keyword = ""
			}
		}
		if keyword != "" {
			compilation.fail(resultmetadata.ReasonUnsupportedSyntax, last.start, &classifiedCypherError{cause: localizedError(localization.CypherMatchingQueryCannotConclude(keyword), nil), code: "Neo.ClientError.Statement.SyntaxError", detail: "InvalidClauseComposition"})
			return
		}
	}
	if len(body.branches) == 1 {
		branch := body.branches[0]
		body.program = &projectedScopeFacts{after: projectedMapNames(branch.scope), outputs: branch.outputs, statement: &branch.statement}
		body.outputIDs = cloneBindingIDs(branch.ids)
		return
	}
	// UNION's envelope owns only the joined output. The complete input and
	// retained scopes are on each Statement.Branches entry, never unioned here.
	statement := resultmetadata.Statement{Start: body.start, End: body.end, Incoming: resultmetadata.KnownScope(nil), Retained: resultmetadata.KnownScope(nil)}
	var columns []string
	hasFinish := false
	for _, branch := range body.branches {
		hasFinish = hasFinish || branch.shape.finished
	}
	for index, branch := range body.branches {
		var next []string
		branch.outputs.Visit(func(known []string) { next = known }, func() { compilation.fail(resultmetadata.ReasonDynamicSchema, branch.shape.start, nil) })
		if compilation.failure != nil {
			return
		}
		if index == 0 {
			columns = next
		} else {
			if _, same := unionColumnOrder(columns, next); !same {
				failure := unionColumnsError(columns, next)
				if hasFinish {
					// Preserve release's FINISH/header diagnostic, with both
					// column sets supplied by this construction rather than a
					// framing-time CALL/procedure output inference.
					failure = newSemanticError("Neo.ClientError.Statement.SyntaxError", "InvalidProjection", "All sub queries in an UNION must have the same return column names")
				}
				compilation.fail(resultmetadata.ReasonUnsupportedSyntax, branch.shape.start, failure)
				return
			}
			statement.UnionAll = append(statement.UnionAll, branch.shape.unionAll)
		}
		statement.Branches = append(statement.Branches, branch.statement)
	}
	names := resultmetadata.Known(columns)
	statement.Columns = projectionColumns(names)
	body.outputIDs = map[string]statementBindingID{}
	for _, name := range columns {
		identity := body.branches[0].ids[name]
		for _, branch := range body.branches[1:] {
			if branch.ids[name] != identity {
				identity = 0
				break
			}
		}
		if identity == 0 {
			identity = compilation.define(name, body.start, body.end)
		}
		body.outputIDs[name] = identity
	}
	statement.After = boundBindingScope(names, body.outputIDs)
	empty := resultmetadata.KnownScope(nil)
	statement.Entry = &resultmetadata.BindingHorizon{Readable: empty, Current: empty, Retained: empty, Weak: empty, Dependencies: empty}
	statement.Exit = &resultmetadata.BindingHorizon{Readable: statement.After, Current: statement.After, Retained: empty, Weak: empty, Dependencies: empty}
	body.program = &projectedScopeFacts{after: names, outputs: names, statement: &statement}
}

func (compilation *boundCompilation) callImports(clause *boundClause) {
	descriptor := scopeClauseFromSyntax(clause.source.syntax)
	parent := clause.branch.bindings
	imports, bindings, err := callBodyScope(descriptor.names, descriptor.scoped, parent.entry, parent, parent.scalar)
	if err != nil {
		compilation.fail(resultmetadata.ReasonInvalidImport, clause.source.start, err)
		return
	}
	clause.body.expressionKind = clause.branch.body.expressionKind
	clause.body.bindings = bindings
	clause.body.dependencies = newSemanticDependencies(imports)
	clause.body.dependencies.parent = clause.branch.dependencies
	var names []string
	for name := range imports {
		names = append(names, name)
		if descriptor.scoped {
			clause.branch.dependencies.readIdentity(name, clause.branch.ids[name])
		}
	}
	slices.Sort(names)
	clause.body.setInputs(resultmetadata.Known(names), projectedMapNames(bindingNames(bindings.retained)), clause.branch.ids)
	mode := resultmetadata.ImportNone
	if descriptor.scoped {
		mode = resultmetadata.ImportListed
		if descriptor.names == nil {
			mode = resultmetadata.ImportAll
		}
	}
	clause.body.graph = clause.branch.graph
	clause.body.graph.outer = projectedMapNames(clause.before)
	clause.body.graph.outerIDs = cloneBindingIDs(clause.branch.ids)
	clause.step.Call = &resultmetadata.Call{Mode: mode, Imports: names, Retained: boundBindingScope(projectedMapNames(bindingNames(bindings.retained)), clause.branch.ids), Optional: clause.source.optional}
	compilation.scopeFrame(clause.body.start, bindings)
}

func (compilation *boundCompilation) procedure(ctx context.Context, clause *boundClause) {
	clause.step.Kind = resultmetadata.ClauseProcedure
	node := clause.source.syntax
	name := node.ChildRule(cypherantlr.CypherParserRULE_invocationName).QualifiedName()
	procedure, found := globalProcedureRegistry.Get(name)
	yield := yieldFromSyntax(node)
	if err := compilation.admitProcedureInvocation(ctx, clause, procedure, found, yield); err != nil {
		compilation.fail(resultmetadata.ReasonInvalidImport, clause.source.start, err)
		return
	}
	if found {
		if arguments := procedureArgumentTextsFromSyntax(node); arguments != nil {
			proof, err := constructProcedureArity(procedure.Spec, len(arguments))
			if err != nil {
				compilation.fail(resultmetadata.ReasonInvalidImport, clause.source.start, err)
				return
			}
			clause.procedureArity = proof
		}
	}
	if err := clause.branch.bindings.admitYieldItems(yield, len(clause.branch.shape.clauses) > 1); err != nil {
		compilation.fail(resultmetadata.ReasonInvalidImport, clause.source.start, err)
		return
	}
	outputs := projectedProcedureNodeNames(node)
	if !found {
		if !clause.branch.graph.selected {
			compilation.fail(resultmetadata.ReasonUnknownProcedure, clause.source.start, unknownProcedureError(name))
			return
		}
		clause.step.ParticipantResolved = true
		if yield == nil || yield.yieldAll {
			if compilation.owner.schema == nil {
				compilation.fail(resultmetadata.ReasonDynamicSchema, clause.source.start, nil)
				return
			}
			graph := clause.branch.graph
			columns, err := compilation.owner.schema(resultmetadata.SchemaObligation{Procedure: name, Start: clause.source.start, End: clause.source.end, UseStart: graph.start, UseEnd: graph.end, Incoming: projectionScope(projectedMapNames(clause.before))})
			if err != nil {
				compilation.fail(resultmetadata.ReasonDynamicSchema, clause.source.start, err)
				return
			}
			columns.Visit(func(names []string) { outputs = resultmetadata.Known(names) }, func() { compilation.fail(resultmetadata.ReasonDynamicSchema, clause.source.start, nil) })
		}
	}
	if projectedNameMap(outputs) == nil {
		compilation.fail(resultmetadata.ReasonDynamicSchema, clause.source.start, nil)
		return
	}
	clause.outputs = outputs
	for name := range projectedNameMap(outputs) {
		clause.after[name] = struct{}{}
	}
	clause.step.Projection = &resultmetadata.Projection{Names: outputs}
}

func (compilation *boundCompilation) visitor(ctx context.Context) cypherantlr.SyntaxVisitor {
	return func(node cypherantlr.SyntaxNode) func() {
		event := compilation.events[node.ID()]
		if event != nil {
			for _, enter := range event.enter {
				enter()
			}
		}
		clause := compilation.clause
		if compilation.failure == nil && clause != nil {
			for _, local := range expressionLocalSyntax(node) {
				if !local.reuse {
					if err := clause.branch.bindings.admitDeclaration(syntaxSymbolName(local.symbol), "LEXICAL"); err != nil {
						compilation.fail(resultmetadata.ReasonInvalidImport, clause.source.start, err)
					}
				}
			}
			if boundOperandHandle(node) {
				scope, ids, _ := compilation.expressionBindings(clause, node)
				compilation.product.expressions[node.ID()] = compilation.freezeReadView(scope, ids)
				compilation.product.nodes[node.ID()] = node
			}
		}
		if compilation.failure == nil && clause != nil {
			if clause.source.kind == pipelineClauseLet && node.Rule() == cypherantlr.CypherParserRULE_letItem {
				symbol := node.ChildRule(cypherantlr.CypherParserRULE_symbol)
				if err := clause.branch.bindings.admitDeclaration(syntaxSymbolName(symbol), "LET"); err != nil {
					compilation.fail(resultmetadata.ReasonInvalidImport, clause.source.start, err)
					return nil
				}
				frame := clause.branch.bindings
				if frame == nil {
					frame = &semanticBodyScope{entry: bindingTypes(clause.after)}
				} else {
					frame = frame.clone(frame.entry)
				}
				start, _ := node.Span()
				compilation.scopeFrame(start, frame)
			}
			compilation.bindSymbol(ctx, clause, node)
		}
		return func() {
			if compilation.failure == nil {
				if err := admitLexicalSyntax(node); err != nil {
					start, _ := node.Span()
					compilation.fail(resultmetadata.ReasonUnsupportedSyntax, start, err)
				}
			}
			if compilation.failure == nil && clause != nil && node.Rule() == cypherantlr.CypherParserRULE_letItem {
				symbol := node.ChildRule(cypherantlr.CypherParserRULE_symbol)
				name := syntaxSymbolName(symbol)
				start, end := symbol.Span()
				clause.after[name] = struct{}{}
				clause.afterIDs[name] = compilation.define(name, start, end)
				if body := clause.branch.bindings; body != nil {
					body.declare(name, body.entry, clause.branch.dependencies, nil, false)
					body.bindCurrent(name, staticOperand{})
				}
			}
			if event != nil {
				for i := len(event.leave) - 1; i >= 0; i-- {
					event.leave[i]()
				}
			}
		}
	}
}

func (compilation *boundCompilation) failUndefined(position int, name string) {
	// Membership was decided above from the admitted identity view. Preserve
	// DELETE's existing target diagnostic instead of replacing it with the
	// generic variable renderer when admission runs before mutation checks.
	if clause := compilation.clause; clause != nil && clause.source.kind == pipelineClauseDelete {
		targets := clause.source.syntax.ChildRule(cypherantlr.CypherParserRULE_expressionChain)
		for index := 0; index < targets.ChildCount(); index++ {
			target := targets.Child(index)
			if target.Rule() != cypherantlr.CypherParserRULE_expression {
				continue
			}
			first, last := target.Span()
			if first <= position && position < last && deleteExpressionRootIdentifier(target.Code()) == name {
				compilation.fail(resultmetadata.ReasonUndefinedVariable, position, deleteUndefinedVariableError(target.Text()))
				return
			}
		}
	}
	compilation.fail(resultmetadata.ReasonUndefinedVariable, position, createUndefinedVariableError(name))
}

func (compilation *boundCompilation) expressionBindings(clause *boundClause, node cypherantlr.SyntaxNode) (map[string]struct{}, map[string]statementBindingID, bool) {
	input, ids := clause.before, clause.beforeIDs
	restricted := false
	switch clause.source.kind {
	case pipelineClauseMatch, pipelineClauseOptionalMatch, pipelineClauseCreate, pipelineClauseMerge, pipelineClauseLet:
		input, ids = clause.after, clause.afterIDs
	}
	if clause.plan != nil {
		switch (projectionSemantics{clause: clause.source.syntax}).readPhase(node) {
		case projectionProjected:
			input, ids, restricted = clause.projectionTailBindings(node)
		case projectionWindow:
			input, ids = clause.combinedBindings()
		}
	} else {
		for parent, ok := node.Parent(); ok && parent.ID() != clause.source.syntax.ID(); parent, ok = parent.Parent() {
			switch parent.Rule() {
			case cypherantlr.CypherParserRULE_yieldItems:
				input, ids = clause.after, clause.afterIDs
			case cypherantlr.CypherParserRULE_where:
				owner, direct := parent.Parent()
				if !direct || owner.ID() != clause.source.syntax.ID() {
					continue // A comprehension predicate reads its expression's input.
				}
				if clause.source.kind == pipelineClauseUnwind {
					input, ids = clause.after, clause.afterIDs
				}
			case cypherantlr.CypherParserRULE_orderSt:
				input, ids, restricted = clause.projectionTailBindings(node)
			case cypherantlr.CypherParserRULE_skipSt, cypherantlr.CypherParserRULE_limitSt:
				input, ids = clause.combinedBindings()
			}
		}
	}
	start, _ := node.Span()
	var ancestors []cypherantlr.SyntaxNode
	for parent, ok := node.Parent(); ok && parent.ID() != clause.source.syntax.ID(); parent, ok = parent.Parent() {
		ancestors = append(ancestors, parent)
	}
	copied := false
	for index := len(ancestors) - 1; index >= 0; index-- {
		parent := ancestors[index]
		bindings, found := compilation.localSyntax[parent.ID()]
		if !found {
			bindings = expressionLocalSyntax(parent)
			compilation.localSyntax[parent.ID()] = bindings
		}
		for _, binding := range bindings {
			if !binding.visible(start) {
				continue
			}
			name := syntaxSymbolName(binding.symbol)
			if binding.reuse {
				if _, visible := input[name]; visible {
					continue
				}
			}
			if !copied {
				input = copyBindingNames(input)
				ids = cloneBindingIDs(ids)
				copied = true
			}
			declaration, _ := binding.symbol.Span()
			input[name] = struct{}{}
			ids[name] = compilation.localBindingIdentity(name, declaration)
		}
	}
	return input, ids, restricted
}

// Commands own their signature and continuation admission separately from
// graph Facts. This syntax adapter asks the same constructor for nested CALL
// composition; it does not infer a command schema or publish partial scopes.
// Unavailable command inputs remain with the command owner; only its body's
// constructor-owned composition diagnostic is observed here.
func validateCommandBodyComposition(ctx context.Context, source string) error {
	syntax, err := cypherantlr.ParseSyntax(ctx, source, cypherantlr.StatementEntry, cypherVersionFromContext(ctx) == "25")
	if err != nil {
		return syntaxAdmissionError(ctx, source, err, syntax)
	}
	var failure error
	syntax.Walk(func(node cypherantlr.SyntaxNode) func() {
		if failure != nil || node.Rule() != cypherantlr.CypherParserRULE_callSubquery {
			return nil
		}
		compiler := projectionCompilation{executor: &StorageExecutor{}, source: node.Text(), cypher25: cypherVersionFromContext(ctx) == "25"}
		program := compiler.root(ctx, resultmetadata.Known(nil), resultmetadata.Known(nil))
		var detail interface{ BoltErrorDetail() string }
		if errors.As(program.err, &detail) && detail.BoltErrorDetail() == "InvalidClauseComposition" {
			failure = program.err
		}
		return nil
	})
	if err := ctx.Err(); err != nil {
		return err
	}
	return failure
}

package cypher

import (
	"context"

	"github.com/orneryd/nornicdb/pkg/cypher/resultmetadata"
)

type boundStatementProgramKey struct{}

// A scalar body continuation keeps the operation supplied by its caller. The
// constructor still decides all bindings; this source window prevents the
// operation from leaking into an independent nested statement or CALL.
type scalarCompilationKey struct{}
type scalarCompilationInput struct{ source, kind string }

func withScalarCompilation(ctx context.Context, source, kind string) context.Context {
	return context.WithValue(ctx, scalarCompilationKey{}, scalarCompilationInput{source, kind})
}
func scalarCompilationKind(ctx context.Context, source string) string {
	input, _ := ctx.Value(scalarCompilationKey{}).(scalarCompilationInput)
	if input.source == source {
		return input.kind
	}
	return ""
}

func withBoundStatementProgram(ctx context.Context, program *boundStatementProgram) context.Context {
	return context.WithValue(ctx, boundStatementProgramKey{}, program)
}

// bindPipelineProgram admits a pipeline through the owner before any operator
// executes. Public execution carries the already bound program. A direct
// pipeline entry supplies its declared incoming scope to the same compiler.
func (e *StorageExecutor) bindPipelineProgram(ctx context.Context, clauses []pipelineClause, incoming map[string]struct{}) (context.Context, error) {
	if len(clauses) == 0 {
		return ctx, nil
	}
	if !clauses[0].syntax.Valid() {
		return ctx, unresolvedStatementError()
	}
	source := clauses[0].syntax.Source()
	if program, ok := ctx.Value(boundStatementProgramKey{}).(*boundStatementProgram); ok && program != nil && program.syntax.Source() == source {
		return ctx, nil
	}
	var retained []string
	for name := range pipelineImports(ctx) {
		retained = append(retained, name)
	}
	names := make([]string, 0, len(incoming))
	for name := range incoming {
		if len(name) == 0 || name[0] != '$' {
			names = append(names, name)
		}
	}
	program := e.projectedStatementScope(ctx, source, resultmetadata.Known(names), resultmetadata.Known(retained), cypherVersionFromContext(ctx) == "25", semanticBodyFromContext(ctx))
	if !program.complete {
		if program.err != nil {
			return ctx, program.err
		}
		return ctx, unresolvedStatementError()
	}
	return withBoundStatementProgram(ctx, program.bound), nil
}

func executionClauseScope(ctx context.Context, clause pipelineClause, after bool) (map[string]struct{}, error) {
	program, ok := ctx.Value(boundStatementProgramKey{}).(*boundStatementProgram)
	if !ok || program == nil || !clause.syntax.Valid() || program.syntax.Source() != clause.syntax.Source() {
		return nil, unresolvedStatementError()
	}
	step, found := program.scopes[clause.syntax.ID()]
	if !found {
		return nil, unresolvedStatementError()
	}
	view := step.Before
	if after {
		view = step.After
	}
	var scope map[string]struct{}
	view.Visit(func(names []string) {
		scope = make(map[string]struct{}, len(names))
		for _, name := range names {
			scope[name] = struct{}{}
		}
	}, func() {})
	if scope == nil {
		return nil, unresolvedStatementError()
	}
	return scope, nil
}

func executionClauseEffects(ctx context.Context, clause pipelineClause) (pipelineClauseEffects, error) {
	if clause.syntax.Valid() {
		if program, ok := ctx.Value(boundStatementProgramKey{}).(*boundStatementProgram); ok && program != nil && program.syntax.Source() == clause.syntax.Source() {
			effects, found := program.effects[clause.syntax.ID()]
			if !found {
				return pipelineClauseEffects{}, unresolvedStatementError()
			}
			return effects, ctx.Err()
		}
		// Effect-only callers need no resolved scope. They observe this retained
		// syntax node; row execution has a separate mandatory binding admission.
		var effects pipelineClauseEffects
		clause.syntax.Walk(pipelineEffectVisitor(&effects))
		return effects, ctx.Err()
	}
	return pipelineClauseEffectsFor(ctx, clause.text)
}

func executionCallFacts(ctx context.Context, clause pipelineClause) *resultmetadata.Call {
	program, _ := ctx.Value(boundStatementProgramKey{}).(*boundStatementProgram)
	if program == nil || !clause.syntax.Valid() || program.syntax.Source() != clause.syntax.Source() {
		return nil
	}
	return program.calls[clause.syntax.ID()]
}

// A terminal procedure still has declared columns when its input is empty.
// This adapter reads the constructor's projection, never executed row keys.
func executionProcedureColumns(ctx context.Context, clause pipelineClause) ([]string, error) {
	program, _ := ctx.Value(boundStatementProgramKey{}).(*boundStatementProgram)
	if program == nil || !clause.syntax.Valid() || program.syntax.Source() != clause.syntax.Source() {
		return nil, unresolvedStatementError()
	}
	step, found := program.scopes[clause.syntax.ID()]
	if !found || step.Projection == nil {
		return nil, unresolvedStatementError()
	}
	var columns []string
	var failure error
	step.Projection.Names.Visit(func(names []string) { columns = append([]string{}, names...) }, func() { failure = unresolvedStatementError() })
	return columns, failure
}

// executionBranchFrame transports the original admitted entry into a local
// branch adapter. Rebinding source text consumes that frame, never row keys.
func executionBranchFrame(ctx context.Context, start int) *semanticBodyScope {
	program, _ := ctx.Value(boundStatementProgramKey{}).(*boundStatementProgram)
	if program == nil {
		return nil
	}
	return program.frames[start]
}

package cypher

import (
	"context"
	cypherantlr "github.com/orneryd/nornicdb/pkg/cypher/antlr"
	"github.com/orneryd/nornicdb/pkg/cypher/resultmetadata"
)

var _ resultmetadata.FactsProvider = (*StorageExecutor)(nil)

// StatementFacts exposes the one cached execution projection program. Scope,
// imports, classification and ordered columns are established together. The
// owner's answer is complete or a terminal error; it never declines execution.
func (e *StorageExecutor) StatementFacts(query string, incoming resultmetadata.Scope, cypher25 bool) resultmetadata.Facts {
	return e.StatementFactsWith(query, incoming, cypher25, nil)
}

// StatementFactsWith completes participant-owned signatures during compilation.
// Signature answers are not cached under query text: a participant may change
// its procedure registry independently of this executor's registry generation.
func (e *StorageExecutor) StatementFactsWith(query string, incoming resultmetadata.Scope, cypher25 bool, schema resultmetadata.ParticipantSchema) resultmetadata.Facts {
	return e.statementProjectionProgram(context.Background(), query, incoming, cypher25, schema).facts
}

func (e *StorageExecutor) statementProjectionProgram(ctx context.Context, query string, incoming resultmetadata.Scope, cypher25 bool, schema resultmetadata.ParticipantSchema) *projectedScopeFacts {
	ensureBuiltInProceduresRegistered()
	names := resultmetadata.Unknown()
	incoming.Visit(func(values []string) { names = resultmetadata.Known(values) }, func() { names = resultmetadata.Unknown() })
	var program *projectedScopeFacts
	if schema == nil {
		program = e.projectedStatementScope(ctx, query, names, resultmetadata.Known(nil), cypher25, semanticBodyFromContext(ctx))
	} else {
		compiler := projectionCompilation{executor: e, source: query, cypher25: cypher25, schema: schema, bindings: semanticBodyFromContext(ctx), scalarKind: scalarCompilationKind(ctx, query)}
		program = compiler.root(ctx, names, resultmetadata.Known(nil))
	}
	// Cached programs are immutable; participant-dependent compilation never
	// enters that cache. Both paths expose the same terminal Facts contract.
	if program.complete && ctx.Err() == nil {
		return program
	}
	immutable := *program
	if err := ctx.Err(); err != nil {
		immutable.complete, immutable.err = false, err
	}
	if immutable.err == nil && immutable.statement != nil {
		if facts, err := resultmetadata.KnownFacts(*immutable.statement); err == nil {
			immutable.complete, immutable.facts = true, facts
		}
	}
	if !immutable.complete {
		immutable.facts = resultmetadata.UnresolvedFacts(resultmetadata.Unresolved{Reason: immutable.reason, Position: immutable.position, Err: immutable.err})
	}
	return &immutable
}

func projectionScope(names resultmetadata.Names) resultmetadata.Scope {
	scope := resultmetadata.UnknownScope()
	names.Visit(func(values []string) { scope = resultmetadata.KnownScope(values) }, func() { scope = resultmetadata.UnknownScope() })
	return scope
}

func projectionColumns(names resultmetadata.Names) resultmetadata.Columns {
	columns := resultmetadata.UnknownColumns()
	names.Visit(func(values []string) { columns = resultmetadata.KnownColumns(values) }, func() { columns = resultmetadata.UnknownColumns() })
	return columns
}

func programFailure(reason resultmetadata.UnresolvedReason, position int, err error) *projectedScopeFacts {
	return &projectedScopeFacts{reason: reason, position: position, err: err}
}

// compileStatementProgram compiles the execution clause operators and their
// scope transfers. WITH and RETURN use the same cached projection plans that
// execute rows; CALL stores its nested program rather than re-inferring exports.
func (e *StorageExecutor) compileStatementProgram(ctx context.Context, source string, incoming, retained resultmetadata.Names, cypher25 bool, bodies ...*semanticBodyScope) *projectedScopeFacts {
	compiler := projectionCompilation{executor: e, source: source, cypher25: cypher25, scalarKind: scalarCompilationKind(ctx, source)}
	if len(bodies) != 0 {
		compiler.bindings = bodies[0]
	}
	return compiler.root(ctx, incoming, retained)
}

type projectionCompilation struct {
	names      *quotedVariableNames
	bindings   *semanticBodyScope
	scalarKind string

	executor *StorageExecutor
	source   string
	cypher25 bool
	schema   resultmetadata.ParticipantSchema
	syntax   cypherantlr.StatementSyntax
}

type projectionGraph struct {
	start, end int
	selected   bool
	outer      resultmetadata.Names
	outerIDs   map[string]statementBindingID
}

func (compiler *projectionCompilation) root(ctx context.Context, incoming, retained resultmetadata.Names) *projectedScopeFacts {
	return compiler.compileBound(ctx, incoming, retained)
}
func statementHasReturningOperator(statement resultmetadata.Statement) bool {
	if len(statement.Branches) > 0 {
		for _, branch := range statement.Branches {
			if statementHasReturningOperator(branch) {
				return true
			}
		}
		return false
	}
	return len(statement.Clauses) > 0 && statement.Clauses[len(statement.Clauses)-1].Kind == resultmetadata.ClauseReturn
}

func projectionDescriptor(plan *returnProjectionPlan) resultmetadata.Projection {
	expressions := make([]string, 0, len(plan.projections))
	passThrough := len(plan.projections) > 0
	for _, item := range plan.projections {
		expressions = append(expressions, item.expr)
		passThrough = passThrough && item.direct && item.variable == item.alias
	}
	return resultmetadata.Projection{Expressions: expressions, Names: resultmetadata.Known(plan.columns), Distinct: plan.distinct, Modifiers: plan.modifiers, PassThrough: passThrough}
}

func statementUsesParticipant(statement resultmetadata.Statement) bool {
	for _, clause := range statement.Clauses {
		if clause.ParticipantResolved || clause.Call != nil && clause.Call.Resolution == resultmetadata.ResolvedByParticipant {
			return true
		}
	}
	for _, branch := range statement.Branches {
		if statementUsesParticipant(branch) {
			return true
		}
	}
	return false
}

package cypher

import (
	"strings"

	cypherantlr "github.com/orneryd/nornicdb/pkg/cypher/antlr"
)

func (clause *boundClause) combinedBindings() (map[string]struct{}, map[string]statementBindingID) {
	names, ids := copyBindingNames(clause.before), cloneBindingIDs(clause.beforeIDs)
	for name := range clause.after {
		names[name] = struct{}{}
		ids[name] = clause.afterIDs[name]
	}
	return names, ids
}

// Projection predicates and ordering can read incoming expressions as well as
// output aliases. DISTINCT/aggregation restrict those reads to expressions the
// projection actually carries. This is a view of retained grammar nodes, not a
// second expression parser or a scope walk over rewritten text.
func (clause *boundClause) projectionTailBindings(read cypherantlr.SyntaxNode) (map[string]struct{}, map[string]statementBindingID, bool) {
	restricted := clause.plan != nil && (clause.plan.distinct || clause.plan.hasAggregate)
	if restricted {
		if name, symbol := read.Name(); symbol {
			if _, retained := projectedNameMap(clause.branch.input.retained)[name]; retained {
				names, ids := clause.combinedBindings()
				return names, ids, false
			}
		}
	}
	if !restricted {
		names, ids := clause.combinedBindings()
		return names, ids, false
	}
	if name, symbol := read.Name(); symbol {
		if _, projected := clause.after[name]; projected {
			return clause.after, clause.afterIDs, true
		}
	}
	for candidate := read; candidate.Valid() && candidate.ID() != clause.source.syntax.ID(); {
		for _, expression := range clause.projectionSyntax {
			if sameProjectionSyntax(candidate, expression) {
				names, ids := clause.combinedBindings()
				return names, ids, true
			}
		}
		parent, exists := candidate.Parent()
		if !exists {
			break
		}
		candidate = parent
	}
	return clause.after, clause.afterIDs, true
}

func projectionSyntaxCore(node cypherantlr.SyntaxNode) cypherantlr.SyntaxNode {
	return node.SemanticExpression()
}

// Compare grammatical expression structure. Symbol identities are already
// decoded by the lexical product; comments and whitespace are not CST edges.
// Built-in function spelling follows the existing function catalog, while
// variable identities and literal strings remain case-sensitive.
func sameProjectionSyntax(left, right cypherantlr.SyntaxNode) bool {
	left, right = projectionSyntaxCore(left), projectionSyntaxCore(right)
	if !left.Valid() || !right.Valid() || left.Rule() != right.Rule() {
		return false
	}
	if name, symbol := left.Name(); symbol {
		other, isSymbol := right.Name()
		return isSymbol && name == other
	}
	if left.Rule() == cypherantlr.CypherParserRULE_invocationName {
		name, other := left.QualifiedName(), right.QualifiedName()
		_, builtin := builtInCypherFunctions[lowerASCII(name)]
		return name == other || builtin && strings.EqualFold(name, other)
	}
	if left.Rule() < 0 {
		written, other := left.Text(), right.Text()
		if strings.HasPrefix(written, "'") || strings.HasPrefix(written, "\"") {
			return written == other
		}
		return strings.EqualFold(written, other)
	}
	if left.ChildCount() != right.ChildCount() {
		return false
	}
	for index := 0; index < left.ChildCount(); index++ {
		if !sameProjectionSyntax(left.Child(index), right.Child(index)) {
			return false
		}
	}
	return true
}

package cypher

import cypherantlr "github.com/orneryd/nornicdb/pkg/cypher/antlr"

// projectionSemantics is the one projection transfer rule. Every item reads
// the incoming scope; all outputs bind together after projectionItems; only
// then do predicates, ordering and windows observe the projected scope. The
// views retain the same grammar nodes used by the executable projection plan.
type projectionSemantics struct {
	clause, body, items cypherantlr.SyntaxNode
}

type projectionSemanticItem struct {
	node, expression, alias cypherantlr.SyntaxNode
}

func projectionSemanticsForSyntax(clause cypherantlr.SyntaxNode) projectionSemantics {
	body := clause.ChildRule(cypherantlr.CypherParserRULE_projectionBody)
	return projectionSemantics{clause: clause, body: body, items: body.ChildRule(cypherantlr.CypherParserRULE_projectionItems)}
}

func (projection projectionSemantics) eachItem(visit func(projectionSemanticItem)) bool {
	if !projection.items.Valid() {
		return false
	}
	for index := 0; index < projection.items.ChildCount(); index++ {
		node := projection.items.Child(index)
		if node.Rule() != cypherantlr.CypherParserRULE_projectionItem {
			continue
		}
		expression := node.ChildRule(cypherantlr.CypherParserRULE_expression)
		if !expression.Valid() {
			return false
		}
		visit(projectionSemanticItem{node: node, expression: expression, alias: node.ChildRule(cypherantlr.CypherParserRULE_symbol)})
	}
	return true
}

func (item projectionSemanticItem) output() (string, cypherantlr.SyntaxNode) {
	if item.alias.Valid() {
		return syntaxSymbolName(item.alias), item.alias
	}
	return projectionNameFromSyntax(item.expression), item.expression
}

func projectionOutputSymbol(node cypherantlr.SyntaxNode) bool {
	parent, exists := node.Parent()
	return exists && parent.Rule() == cypherantlr.CypherParserRULE_projectionItem && parent.ChildRule(cypherantlr.CypherParserRULE_symbol).ID() == node.ID()
}

// The existing generic traversal calls the leave action after ALL item inputs.
// Observers never publish an alias while a sibling expression still reads the
// incoming scope. Nested projections use the same boundary automatically.
func projectionOutputsOnLeave(node cypherantlr.SyntaxNode, bind func(string, cypherantlr.SyntaxNode)) func() {
	if node.Rule() != cypherantlr.CypherParserRULE_projectionItems {
		return nil
	}
	body, exists := node.Parent()
	if !exists {
		return nil
	}
	clause, exists := body.Parent()
	if !exists {
		return nil
	}
	projection := projectionSemanticsForSyntax(clause)
	if !projection.items.Valid() || projection.items.ID() != node.ID() {
		return nil
	}
	return func() {
		projection.eachItem(func(item projectionSemanticItem) { name, definition := item.output(); bind(name, definition) })
	}
}

type projectionReadPhase uint8

const (
	projectionIncoming projectionReadPhase = iota
	projectionProjected
	projectionWindow
)

func (projection projectionSemantics) readPhase(node cypherantlr.SyntaxNode) projectionReadPhase {
	for parent, exists := node.Parent(); exists && parent.ID() != projection.clause.ID(); parent, exists = parent.Parent() {
		switch parent.Rule() {
		case cypherantlr.CypherParserRULE_projectionItem:
			return projectionIncoming
		case cypherantlr.CypherParserRULE_where:
			if owner, ok := parent.Parent(); ok && owner.ID() == projection.clause.ID() {
				return projectionProjected
			}
		case cypherantlr.CypherParserRULE_orderSt:
			return projectionProjected
		case cypherantlr.CypherParserRULE_skipSt, cypherantlr.CypherParserRULE_limitSt:
			return projectionWindow
		}
	}
	return projectionIncoming
}

// writtenName consumes the lower naming owner's source-span provenance. Binding
// identity and executable aliases remain canonical; a complex unaliased column
// keeps its written expression, so quoting cannot merge distinct public names.
func (item projectionSemanticItem) writtenName(names *quotedVariableNames) string {
	name, _ := item.output()
	if names == nil {
		return name
	}
	if item.alias.Valid() {
		if original, ok := names.internal[name]; ok {
			return original.name
		}
		return name
	}
	if _, variable := projectionVariableFromSyntax(item.expression); variable {
		if original, ok := names.internal[name]; ok {
			return original.name
		}
		return name
	}
	start, end := item.expression.Span()
	return names.originalText(start, end)
}

package cypher

import (
	"context"
	cypherantlr "github.com/orneryd/nornicdb/pkg/cypher/antlr"
	"slices"
	"strconv"
	"strings"

	"github.com/orneryd/nornicdb/pkg/cypher/resultmetadata"
)

// projectedScopeFacts is an immutable execution projection program's result.
// Neither incomplete scope nor incomplete output has an accessible names payload.
type projectedScopeFacts struct {
	after      resultmetadata.Names
	outputs    resultmetadata.Names
	err        error
	generation uint64
	statement  *resultmetadata.Statement
	call       *resultmetadata.Call
	reason     resultmetadata.UnresolvedReason
	position   int
	complete   bool
	facts      resultmetadata.Facts
	bound      *boundStatementProgram
}

type projectionFactsKey struct {
	writtenSource                          string
	query, incoming, retained              string
	incomingKnown, retainedKnown, cypher25 bool
	body                                   *semanticBodyScope
	scalarKind                             string
}

var projectionFactsCache = newBoundedCache[projectionFactsKey, *projectedScopeFacts](4096, func(key projectionFactsKey) int {
	return boundedCacheStringShardIndex(key.query)
})

// ProjectedScopeAfterClause owns which variables are visible after a clause.
// Visit requires a policy for both known names (fresh, sorted) and unknown facts.
// USE selects a graph without binding a variable. CALL bodies contribute only
// their projected outputs; registry outputs include implicit CALL and YIELD *.
// This read-only API consumes the bound projection program without starting a
// semantic/type walk or depending on header consumers.
func (e *StorageExecutor) ProjectedScopeAfterClause(clause string, incoming []string, cypher25 bool) resultmetadata.Names {
	names := resultmetadata.Unknown()
	e.StatementFacts(clause, resultmetadata.KnownScope(incoming), cypher25).Visit(func(statement resultmetadata.Statement) {
		statement.After.Visit(func(known []string) { names = resultmetadata.Known(known) }, func() { names = resultmetadata.Unknown() })
	}, func() { names = resultmetadata.Unknown() }, func(resultmetadata.Unresolved) { names = resultmetadata.Unknown() })
	return names
}

func namesKey(names resultmetadata.Names) (text string, known bool) {
	names.Visit(func(values []string) {
		slices.Sort(values)
		escaped := false
		for _, value := range values {
			escaped = escaped || value == "" || strings.IndexByte(value, 0) >= 0
		}
		if escaped {
			// Empty identities are real variables. Length-prefix exceptional
			// names so they cannot share an empty-scope or separator key.
			var key strings.Builder
			key.WriteByte(0)
			for _, value := range values {
				key.WriteString(strconv.Itoa(len(value)))
				key.WriteByte(':')
				key.WriteString(value)
			}
			text = key.String()
		} else {
			text = strings.Join(values, "\x00")
		}
		known = true
	}, func() { text, known = "", false })
	return
}

// projectionFactsFor is the statement cache for execution's declared fields.
// Compilation reads the same clause, pattern-binding and projection plans as
// execution. It never invokes the semantic/type-validation walk or a handler.
func projectionKey(query string, incoming, retained resultmetadata.Names, cypher25 bool) projectionFactsKey {
	inputKey, inputKnown := namesKey(incoming)
	retainedKey, retainedKnown := namesKey(retained)
	return projectionFactsKey{query: query, incoming: inputKey, retained: retainedKey, incomingKnown: inputKnown, retainedKnown: retainedKnown, cypher25: cypher25}
}
func (e *StorageExecutor) projectionFactsFor(ctx context.Context, query string, incoming, retained resultmetadata.Names, cypher25 bool, bodies ...*semanticBodyScope) *projectedScopeFacts {
	if err := ctx.Err(); err != nil {
		return programFailure(resultmetadata.ReasonParserDecline, 0, err)
	}
	key := projectionKey(query, incoming, retained, cypher25)
	key.scalarKind = scalarCompilationKind(ctx, query)
	if names := quotedVariableNamesFor(ctx, query); names != nil {
		key.writtenSource = names.original
	}
	if len(bodies) != 0 {
		key.body = bodies[0]
	}
	generation := globalProcedureRegistry.generation.Load()
	if facts, found := projectionFactsCache.get(key); found && facts.generation == generation {
		return facts
	}
	facts := e.compileStatementProgram(ctx, query, incoming, retained, cypher25, key.body)
	if err := ctx.Err(); err != nil {
		return programFailure(resultmetadata.ReasonParserDecline, 0, err)
	}
	immutable := *facts
	immutable.generation = generation
	if immutable.statement != nil && immutable.err == nil {
		known, err := resultmetadata.KnownFacts(*immutable.statement)
		if err == nil {
			immutable.complete, immutable.facts = true, known
		} else {
			immutable.reason = resultmetadata.ReasonDynamicSchema
		}
	}
	facts = &immutable
	if generation == globalProcedureRegistry.generation.Load() {
		projectionFactsCache.put(key, facts)
	}
	return facts
}

func (e *StorageExecutor) projectedStatementScope(ctx context.Context, query string, incoming, retained resultmetadata.Names, cypher25 bool, bodies ...*semanticBodyScope) *projectedScopeFacts {
	return e.projectionFactsFor(ctx, query, incoming, retained, cypher25, bodies...)
}

func projectedNameMap(names resultmetadata.Names) map[string]struct{} {
	var result map[string]struct{}
	names.Visit(func(values []string) {
		result = make(map[string]struct{}, len(values))
		for _, name := range values {
			result[name] = struct{}{}
		}
	}, func() { result = nil })
	return result
}

func projectedMapNames(scope map[string]struct{}) resultmetadata.Names {
	if scope == nil {
		return resultmetadata.Unknown()
	}
	names := make([]string, 0, len(scope))
	for name := range scope {
		names = append(names, name)
	}
	slices.Sort(names)
	return resultmetadata.Known(names)
}

func addProjectedNames(incoming, added resultmetadata.Names) resultmetadata.Names {
	first, second := projectedNameMap(incoming), projectedNameMap(added)
	if first == nil || second == nil {
		return resultmetadata.Unknown()
	}
	for name := range second {
		first[name] = struct{}{}
	}
	return projectedMapNames(first)
}

func mergeProjectedNames(incoming, retained resultmetadata.Names) resultmetadata.Names {
	return addProjectedNames(incoming, retained)
}

func projectedProcedureNames(ctx context.Context, source string) resultmetadata.Names {
	clause, ok := canonicalQueryClause(ctx, source)
	if !ok {
		return resultmetadata.Unknown()
	}
	return projectedProcedureNodeNames(clause)
}

func projectedProcedureNodeNames(clause cypherantlr.SyntaxNode) resultmetadata.Names {
	if yield := yieldFromSyntax(clause); yield != nil && !yield.yieldAll {
		columns := make([]string, 0, len(yield.items))
		for _, item := range yield.items {
			columns = append(columns, item.column())
		}
		return resultmetadata.Known(columns)
	}
	name := clause.ChildRule(cypherantlr.CypherParserRULE_invocationName).QualifiedName()
	procedure, found := globalProcedureRegistry.Get(name)
	if !found {
		return resultmetadata.Unknown()
	}
	var columns []string
	for _, output := range procedureDeclaredReturns(procedure.Spec) {
		columns = append(columns, output.Name)
	}
	return resultmetadata.Known(columns)
}

package resultmetadata

import (
	"slices"

	"github.com/orneryd/nornicdb/pkg/localization"
)

// BindingID identifies one declaration within a compiled statement.
type BindingID uint32

// Scope is a set of visible, decoded variable identities. Its zero value is unknown.
type Scope struct {
	names    Names
	bindings map[string]BindingID
}

// KnownScope copies, sorts and deduplicates a scope; an empty scope is known.
func KnownScope(names []string) Scope {
	values := append([]string{}, names...)
	slices.Sort(values)
	return Scope{names: Known(slices.Compact(values))}
}

// KnownBindingScope freezes the compiler's identities at one scope horizon.
// Names-only scopes remain available for structural plans and external inputs.
func KnownBindingScope(names []string, identities map[string]BindingID) Scope {
	scope := KnownScope(names)
	scope.bindings = make(map[string]BindingID, len(names))
	for _, name := range names {
		if id, ok := identities[name]; ok {
			scope.bindings[name] = id
		}
	}
	return scope
}

// Binding returns the canonical declaration of name at this horizon, if known.
func (s Scope) Binding(name string) (BindingID, bool) {
	id, ok := s.bindings[name]
	return id, ok
}

// UnknownScope has no authoritative variable set.
func UnknownScope() Scope { return Scope{} }

// Visit exposes fresh sorted names or explicitly transfers unresolved handling.
func (s Scope) Visit(known func([]string), unknown func()) { s.names.Visit(known, unknown) }

// Columns is an ordered result schema, distinct from a variable scope.
type Columns struct {
	names        Names
	alternatives [][]string
}

// KnownColumns copies a header in projection order, including a known empty header.
func KnownColumns(names []string) Columns { return Columns{names: Known(names)} }

// KnownColumnAlternatives declares a closed set of ordered procedure headers.
// A value-dependent procedure can produce one declared shape, never an observed
// header that was absent from this contract. Single-header consumers remain unresolved.
func KnownColumnAlternatives(headers [][]string) Columns {
	if len(headers) == 1 {
		return KnownColumns(headers[0])
	}
	alternatives := make([][]string, len(headers))
	for i, header := range headers {
		alternatives[i] = append([]string{}, header...)
	}
	return Columns{alternatives: alternatives}
}

// UnknownColumns has no authoritative result schema.
func UnknownColumns() Columns { return Columns{} }

// Visit exposes a fresh ordered header or explicitly transfers unresolved handling.
func (c Columns) Visit(known func([]string), unknown func()) { c.names.Visit(known, unknown) }

// Verify checks actual stream fields against the established ordered schema.
// Unknown columns are terminal; observed fields never complete missing facts.
func (c Columns) Verify(actual []string) error {
	if len(c.alternatives) > 0 {
		for _, header := range c.alternatives {
			if slices.Equal(header, actual) {
				return nil
			}
		}
		return localization.NewLocalizedError("Neo.DatabaseError.Statement.ExecutionFailed", localization.CypherResultMetadataMismatch(), nil)
	}
	if !c.names.known {
		return unresolvedError()
	}
	if !slices.Equal(c.names.values, actual) {
		return localization.NewLocalizedError("Neo.DatabaseError.Statement.ExecutionFailed", localization.CypherResultMetadataMismatch(), nil)
	}
	return nil
}

// ClauseKind identifies an execution operator without reading its source again.
type ClauseKind uint8

const (
	ClauseOther ClauseKind = iota
	ClauseMatch
	ClauseOptionalMatch
	ClauseWith
	ClauseReturn
	ClauseUnwind
	ClauseCallSubquery
	ClauseProcedure
	ClauseUse
	ClauseWrite
	ClauseFinish
	ClauseLet
	ClauseFilter
)

// CallKind distinguishes exporting calls from unit calls independently of rows.
type CallKind uint8

const (
	CallUnit CallKind = iota + 1
	CallReturning
)

// ImportMode describes a scope clause; legacy WITH imports are not retained.
type ImportMode uint8

const (
	ImportNone ImportMode = iota
	ImportListed
	ImportAll
)

// BindingHorizon is one frozen semantic transition view. Current is wildcard
// membership; Readable also includes carried inputs. Weak may be shadowed by a
// declaration. Dependencies identifies entry values actually read, never rows.
type BindingHorizon struct {
	Readable, Current, Retained, Weak, Dependencies Scope
}

// StreamMode declares whether an operator consumes a complete input stream or
// invokes a nested query per input row. Empty input retains its declared schema.
type StreamMode uint8

const (
	CompleteStream StreamMode = iota + 1
	PerInputRow
)

// Clause carries execution's scope transfer and original-query byte span.
type Clause struct {
	Kind                ClauseKind
	Start, End          int
	Before, After       Scope
	Entry, Exit         *BindingHorizon
	Projection          *Projection
	Call                *Call
	ParticipantResolved bool
	// Routing is the enclosing horizon visible to a USE selector. It is not
	// the participant body's Before/After scope.
	Routing Scope
	Graph   *GraphSelection
}

// GraphSelection retains the admitted USE selector from the compiler's CST.
// Fabric owns its evaluation, participant lookup and access checks.
type GraphSelection struct {
	Name, Function string
	Arguments      []string
}

// Call resolves imports and exports once at the point the subquery stands in.
type Call struct {
	Mode       ImportMode
	Imports    []string
	Retained   Scope
	Body       Columns
	Kind       CallKind
	Optional   bool
	After      Scope
	Statement  *Statement
	Resolution Resolution
	// Routing is the canonical set of enclosing inputs needed by this CALL's
	// USE selectors, separate from participant-body imports.
	Routing Scope
}

// Resolution records which signature owner completed the procedure facts.
type Resolution uint8

const (
	ResolvedLocally Resolution = iota
	ResolvedByParticipant
)

// SchemaObligation is resolved synchronously by the participant selected by USE.
// All spans address the original query. Incoming supplies declared argument
// variables without making the transport infer them from procedure source text.
type SchemaObligation struct {
	Procedure        string
	Start, End       int
	UseStart, UseEnd int
	Incoming         Scope
}

// ParticipantSchema reads the participant's own signature/protocol metadata.
// An unknown answer or error is terminal before any statement effects.
type ParticipantSchema func(SchemaObligation) (Columns, error)

// Statement is a complete execution scope program, including nested statements.
// Every span addresses the original query, not a rewritten or USE-free copy.
type Statement struct {
	// Command is an admitted non-graph command's typed continuation. Its
	// participant owns its result; it has no query binding horizons.
	Command                   *Command
	Start, End                int
	Incoming, Retained, After Scope
	Clauses                   []Clause
	Branches                  []Statement
	UnionAll                  []bool
	Columns                   Columns
	// Routing preserves the selected USE horizon in a fragment view after
	// that routing clause has been consumed. Original programs keep it on USE.
	Routing Scope
	// Fragments is the compiler's lowering program. Query steps carry complete
	// horizons; USE and CALL steps refer to their canonical clause by index.
	Fragments   []BoundFragment
	Entry, Exit *BindingHorizon
}

// Command preserves the existing command-owner boundary when USE routes DDL or
// SHOW to a participant. It never stands in for unresolved graph-query facts.
type Command struct {
	Text  string
	Graph *GraphSelection
}

// BoundFragment is one compiler-owned fragment boundary. Fabric may serialize
// its source clauses and choose participants, but never reconstruct its scope,
// result schema, retained-value carriage or continuation multiplicity.
type BoundFragment struct {
	Kind                      ClauseKind
	First, End                int
	Incoming, Retained, After Scope
	Columns                   Columns
	// ParentInputs carry unchanged retained declarations from the CALL entry.
	// RowInputs carry current stream values, including rebound retained names.
	ParentInputs, RowInputs []string
	WholeStream             bool
	Multiplicity            StreamMode
	Entry, Exit             *BindingHorizon
	// Returning identifies an existing terminal RETURN to serialize as WITH
	// before adding hygienic transport exports. Prefixes have no RETURN.
	Returning bool
}

// UnresolvedReason is a typed explanation for a terminal owner failure.
type UnresolvedReason uint8

const (
	ReasonUnspecified UnresolvedReason = iota
	ReasonUndefinedVariable
	ReasonInvalidImport
	ReasonUnsupportedSyntax
	ReasonParserDecline
	ReasonUnknownProcedure
	ReasonDynamicSchema
)

// Unresolved cannot represent a successful or empty schema. Err is always set
// when delivered by Facts.Visit, including for a zero Facts value.
type Unresolved struct {
	Reason   UnresolvedReason
	Position int
	Err      error
}

// Facts is an immutable owner result. Its zero value is terminal unresolved.
type Facts struct {
	statement  *Statement
	declined   bool
	unresolved Unresolved
}

// FactsProvider is the scope and result-schema owner's exact neutral interface.
type FactsProvider interface {
	StatementFacts(query string, incoming Scope, cypher25 bool) Facts
}

// KnownFacts freezes a complete program. Unknown fields and cyclic subqueries
// are rejected, rather than becoming authoritative empty schemas.
func KnownFacts(statement Statement) (Facts, error) {
	if !completeStatement(&statement, make(map[*Statement]bool)) {
		return Facts{}, unresolvedError()
	}
	frozen := cloneStatement(statement)
	return Facts{statement: &frozen}, nil
}

// NotApplicableFacts is only an adapter's decline to an actual continuation.
// StatementFacts itself never returns this outcome.
func NotApplicableFacts() Facts { return Facts{declined: true} }

// UnresolvedFacts preserves a definite error or supplies a localized terminal
// error when the caller has not established one.
func UnresolvedFacts(unresolved Unresolved) Facts {
	if unresolved.Err == nil {
		unresolved.Err = unresolvedError()
	}
	return Facts{unresolved: unresolved}
}

// Visit requires separate handling for a known program, a continuation and a
// terminal error. The known callback receives a deep copy, never cached storage.
func (f Facts) Visit(known func(Statement), notApplicable func(), unresolved func(Unresolved)) {
	if f.statement != nil {
		known(cloneStatement(*f.statement))
	} else if f.declined {
		notApplicable()
	} else {
		reason := f.unresolved
		if reason.Err == nil {
			reason.Position = -1
			reason.Err = unresolvedError()
		}
		unresolved(reason)
	}
}

func unresolvedError() error {
	return localization.NewLocalizedError("Neo.ClientError.Statement.FeatureNotSupported", localization.CypherResultMetadataUnresolved(), nil)
}

func completeHorizon(horizon *BindingHorizon) bool {
	return horizon != nil && horizon.Readable.names.known && horizon.Current.names.known && horizon.Retained.names.known && horizon.Weak.names.known && horizon.Dependencies.names.known
}

func completeStatement(statement *Statement, visiting map[*Statement]bool) bool {
	if statement.Command != nil {
		return statement.Command.Text != "" && statement.Entry == nil && statement.Exit == nil && len(statement.Clauses) == 0 && len(statement.Branches) == 0 && len(statement.Fragments) == 0 && (statement.Columns.names.known || len(statement.Columns.alternatives) > 0)
	}
	if !completeHorizon(statement.Entry) || !completeHorizon(statement.Exit) {
		return false
	}
	if visiting[statement] || !statement.Incoming.names.known || !statement.Retained.names.known || !statement.After.names.known || !(statement.Columns.names.known || len(statement.Columns.alternatives) > 0) || len(statement.UnionAll) != max(0, len(statement.Branches)-1) {
		return false
	}
	visiting[statement] = true
	defer delete(visiting, statement)
	for _, fragment := range statement.Fragments {
		if !completeHorizon(fragment.Entry) || !completeHorizon(fragment.Exit) {
			return false
		}
		if fragment.First < 0 || fragment.End <= fragment.First || fragment.End > len(statement.Clauses) {
			return false
		}
		if fragment.Kind == ClauseOther && (!fragment.Incoming.names.known || !fragment.Retained.names.known || !fragment.After.names.known || !(fragment.Columns.names.known || len(fragment.Columns.alternatives) > 0)) {
			return false
		}
	}
	for _, clause := range statement.Clauses {
		if !completeHorizon(clause.Entry) || !completeHorizon(clause.Exit) {
			return false
		}
		if !clause.Before.names.known || !clause.After.names.known || (clause.Projection != nil && !clause.Projection.Names.known) {
			return false
		}
		if call := clause.Call; call != nil {
			if !call.Retained.names.known || !(call.Body.names.known || len(call.Body.alternatives) > 0) || !call.After.names.known || (call.Kind != CallUnit && call.Kind != CallReturning) || call.Statement == nil || !completeStatement(call.Statement, visiting) {
				return false
			}
		}
	}
	for index := range statement.Branches {
		if !completeStatement(&statement.Branches[index], visiting) {
			return false
		}
	}
	return true
}

func cloneHorizon(horizon *BindingHorizon) *BindingHorizon {
	if horizon == nil {
		return nil
	}
	copy := *horizon
	return &copy
}
func cloneStatement(statement Statement) Statement {
	statement.Entry, statement.Exit = cloneHorizon(statement.Entry), cloneHorizon(statement.Exit)
	if statement.Command != nil {
		command := *statement.Command
		if command.Graph != nil {
			graph := *command.Graph
			graph.Arguments = append([]string(nil), graph.Arguments...)
			command.Graph = &graph
		}
		statement.Command = &command
	}
	statement.Fragments = append([]BoundFragment(nil), statement.Fragments...)
	for index := range statement.Fragments {
		fragment := &statement.Fragments[index]
		fragment.Entry, fragment.Exit = cloneHorizon(fragment.Entry), cloneHorizon(fragment.Exit)
		fragment.ParentInputs = append([]string(nil), fragment.ParentInputs...)
		fragment.RowInputs = append([]string(nil), fragment.RowInputs...)
	}
	statement.Clauses = append([]Clause(nil), statement.Clauses...)
	for index := range statement.Clauses {
		clause := &statement.Clauses[index]
		clause.Entry, clause.Exit = cloneHorizon(clause.Entry), cloneHorizon(clause.Exit)
		if clause.Graph != nil {
			graph := *clause.Graph
			graph.Arguments = append([]string(nil), graph.Arguments...)
			clause.Graph = &graph
		}
		if clause.Projection != nil {
			projection := *clause.Projection
			projection.Expressions = append([]string(nil), projection.Expressions...)
			projection.Retention = append([]RetainedProjection(nil), projection.Retention...)
			clause.Projection = &projection
		}
		if clause.Call != nil {
			call := *clause.Call
			if call.Imports != nil {
				call.Imports = append([]string{}, call.Imports...)
			}
			if call.Statement != nil {
				body := cloneStatement(*call.Statement)
				call.Statement = &body
			}
			clause.Call = &call
		}
	}
	statement.Branches = append([]Statement(nil), statement.Branches...)
	for index := range statement.Branches {
		statement.Branches[index] = cloneStatement(statement.Branches[index])
	}
	statement.UnionAll = append([]bool(nil), statement.UnionAll...)
	return statement
}

// Schema command parsing and execution for Cypher.
//
// This file implements Neo4j schema management commands:
//   - CREATE CONSTRAINT
//   - CREATE INDEX
//   - CREATE RANGE INDEX
//   - CREATE FULLTEXT INDEX
//   - CREATE VECTOR INDEX
package cypher

import (
	"context"
	"errors"
	"fmt"
	"strconv"
	"strings"

	nerrors "github.com/orneryd/nornicdb/pkg/errors"
	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// isCompositeRoot returns true if the storage engine is a composite database root.
// Schema DDL and introspection commands must be rejected on composite roots —
// callers must target a specific constituent via USE <composite>.<alias>.
func isCompositeRoot(engine storage.Engine) bool {
	type compositeChecker interface {
		IsComposite() bool
	}
	if cc, ok := engine.(compositeChecker); ok {
		return cc.IsComposite()
	}
	return false
}

// isCompositeAllowedCommand returns true for system/admin commands that are
// valid at composite root level without requiring a constituent target.
func isCompositeAllowedCommand(cypher string) bool {
	upper := upperASCII(strings.TrimSpace(cypher))
	prefixes := []string{
		"SHOW DATABASE", "SHOW COMPOSITE", "SHOW CONSTITUENTS",
		"SHOW ALIASES", "SHOW LIMITS", "SHOW PROCEDURES", "SHOW FUNCTIONS", "SHOW SETTING",
		// Schema introspection/DDL commands pass through to their own handlers
		// which return more specific composite-root error messages.
		"SHOW INDEX", "SHOW FULLTEXT INDEX", "SHOW RANGE INDEX", "SHOW VECTOR INDEX", "SHOW LOOKUP INDEX",
		"SHOW CONSTRAINT",
		"CREATE INDEX", "CREATE RANGE INDEX", "CREATE FULLTEXT INDEX", "CREATE VECTOR INDEX", "CREATE LOOKUP INDEX", "CREATE TEXT INDEX", "CREATE POINT INDEX",
		"CREATE CONSTRAINT",
		"DROP INDEX", "DROP CONSTRAINT",
		"CREATE DATABASE", "DROP DATABASE",
		"CREATE COMPOSITE", "DROP COMPOSITE", "ALTER COMPOSITE",
		"CREATE ALIAS", "DROP ALIAS",
		"BEGIN", "COMMIT", "ROLLBACK",
	}
	for _, p := range prefixes {
		if strings.HasPrefix(upper, p) {
			return true
		}
	}
	return false
}

// executeSchemaCommand handles CREATE CONSTRAINT and CREATE INDEX commands.
func (e *StorageExecutor) executeSchemaCommand(ctx context.Context, cypher string) (*ExecuteResult, error) {
	if isCompositeRoot(e.storage) {
		return nil, localizedError(localization.CypherSchemaCompositeDDLNotAllowed(), nil)
	}
	if err := e.prepareSchemaTransaction(ctx); err != nil {
		return nil, err
	}
	if schema := e.storage.GetSchema(); schema != nil {
		release := schema.LockSchemaMutation()
		defer release()
	}
	resumeWrites, err := pauseAsyncWritesForSchemaDDL(e.storage)
	defer resumeWrites()
	if err != nil {
		return nil, err
	}

	upper := upperASCII(cypher)

	// Order matters: check more specific patterns first
	var run func(context.Context, string) (*ExecuteResult, error)
	if strings.Contains(upper, "CREATE CONSTRAINT") {
		run = e.executeCreateConstraint
	} else if strings.Contains(upper, "DROP CONSTRAINT") {
		run = e.executeDropConstraint
	} else if startsWithKeywords(cypher, "DROP", "INDEX") {
		run = e.executeDropIndex
	} else if strings.Contains(upper, "CREATE FULLTEXT INDEX") {
		run = e.executeCreateFulltextIndex
	} else if strings.Contains(upper, "CREATE VECTOR INDEX") {
		run = e.executeCreateVectorIndex
	} else if strings.Contains(upper, "CREATE RANGE INDEX") {
		run = e.executeCreateRangeIndex
	} else if startsWithKeywords(cypher, "CREATE", "TEXT INDEX") || startsWithKeywords(cypher, "CREATE", "POINT INDEX") {
		run = e.executeCreateTypedPropertyIndex
	} else if startsWithKeywords(cypher, "CREATE", "LOOKUP INDEX") {
		run = e.executeCreateLookupIndex
	} else if strings.Contains(upper, "CREATE INDEX") {
		run = e.executeCreateIndex
	} else {
		return nil, localizedError(localization.CypherSchemaUnknownCommand(cypher), nil)
	}
	result, err := e.countSchemaChanges(ctx, cypher, run)
	if err == nil {
		if wrapper, ok := e.storage.(*transactionStorageWrapper); ok {
			err = wrapper.tx.StageSchemaChanges()
		}
	}
	if err != nil && startsWithKeywords(cypher, "CREATE", "CONSTRAINT") {
		var violation *storage.ConstraintViolationError
		if errors.As(err, &violation) {
			return nil, &classifiedCypherError{cause: err, code: "Neo.DatabaseError.Schema.ConstraintCreationFailed", detail: "ConstraintCreationFailed"}
		}
	}

	// Invalidate query cache — cached SHOW INDEXES/CONSTRAINTS results are now stale.
	if err == nil && e.cache != nil {
		e.cache.Invalidate()
	}

	return result, err
}

// countSchemaChanges runs a schema command and reports the indexes and
// constraints it created or dropped in the result's counters, as Neo4j's
// summary does (#507): CREATE INDEX -> indexes_added 1, DROP CONSTRAINT ->
// constraints_removed 1, and nothing for an IF [NOT] EXISTS that did nothing.
// The counts are the difference in the schema's objects across the command
// (SchemaObjectCounts), so every CREATE / DROP form is counted the same way.
func (e *StorageExecutor) countSchemaChanges(ctx context.Context, cypher string, run func(context.Context, string) (*ExecuteResult, error)) (*ExecuteResult, error) {
	schema := e.storage.GetSchema()
	if schema == nil {
		return run(ctx, cypher)
	}
	indexesBefore, constraintsBefore := schema.SchemaObjectCounts()
	result, err := run(ctx, cypher)
	if err != nil || result == nil {
		return result, err
	}
	indexesAfter, constraintsAfter := schema.SchemaObjectCounts()
	if indexesAfter == indexesBefore && constraintsAfter == constraintsBefore {
		return result, nil
	}
	if result.Stats == nil {
		result.Stats = &QueryStats{}
	}
	result.Stats.IndexesAdded += max(indexesAfter-indexesBefore, 0)
	result.Stats.IndexesRemoved += max(indexesBefore-indexesAfter, 0)
	result.Stats.ConstraintsAdded += max(constraintsAfter-constraintsBefore, 0)
	result.Stats.ConstraintsRemoved += max(constraintsBefore-constraintsAfter, 0)
	return result, nil
}

// pauseAsyncWritesForSchemaDDL previously flushed and held every async write
// cache in the engine stack while a schema command validated stored data
// (#700). Writes now commit synchronously through their transactions, so
// there is no cached write to hold: a schema command observes every
// acknowledged write without a pause. The returned function is always safe to
// call.
func pauseAsyncWritesForSchemaDDL(_ storage.Engine) (func(), error) {
	return func() {}, nil
}

// executeCreateConstraint handles CREATE CONSTRAINT commands.
//
// Supported syntax (Neo4j 5.x):
//
//	CREATE CONSTRAINT constraint_name IF NOT EXISTS FOR (n:Label) REQUIRE n.property IS UNIQUE
//
// Supported syntax (Neo4j 4.x):
//
//	CREATE CONSTRAINT FOR (n:Label) REQUIRE (n.first, n.last) IS UNIQUE
func (e *StorageExecutor) executeCreateConstraint(ctx context.Context, cypher string) (*ExecuteResult, error) {
	onPosition := keywordIndexFrom(cypher, "ON", 0, defaultKeywordScanOpts())
	forPosition := keywordIndexFrom(cypher, "FOR", 0, defaultKeywordScanOpts())
	if onPosition >= 0 && (forPosition < 0 || onPosition < forPosition) {
		return nil, localizedError(localization.CypherSchemaInvalidSyntax("CREATE CONSTRAINT"), nil)
	}
	// Every spelling of a uniqueness or key requirement becomes the one the
	// shapes below read (canonicalConstraintRequirement).
	cypher, err := e.canonicalConstraintRequirement(cypher)
	if err != nil {
		return nil, err
	}
	if parsed, err := e.parseCreateConstraintForRequireDDL(cypher); err == nil {
		if kind, properties, ok := e.parseRelationshipKeyOrCompositeUniquePredicate(parsed.requireExpr); ok && kind == "unique" {
			seen := make(map[string]struct{}, len(properties))
			for _, property := range properties {
				if _, duplicate := seen[property]; duplicate {
					return nil, newSemanticError("Neo.ClientError.Schema.RepeatedPropertyInCompositeSchema", "RepeatedPropertyInCompositeSchema",
						"A composite schema cannot contain the same property more than once: "+property)
				}
				seen[property] = struct{}{}
			}
		}
	}
	// Detect IF NOT EXISTS to pass through to AddConstraint for duplicate-schema handling.
	ifNotExists := strings.Contains(upperASCII(cypher), "IF NOT EXISTS")
	if result, handled, err := e.executeCreateConstraintContract(ctx, cypher, ifNotExists); handled {
		return result, err
	}

	if parsed, err := e.parseCreateConstraintNodeKeyDDL(cypher); err == nil {
		if len(parsed.properties) == 0 {
			return nil, localizedError(localization.CypherSchemaConstraintPropertiesRequired("NODE KEY"), nil)
		}
		constraintName := parsed.name
		if constraintName == "" {
			constraintName = fmt.Sprintf("constraint_%s_%s_node_key", parsed.label, strings.Join(parsed.properties, "_"))
		}

		constraint := storage.Constraint{
			Name:       constraintName,
			Type:       storage.ConstraintNodeKey,
			Label:      parsed.label,
			Properties: parsed.properties,
		}

		if err := storage.ValidateConstraintOnCreationForEngineWithContext(ctx, e.storage, constraint); err != nil {
			return nil, err
		}
		if err := e.addSchemaConstraint(ctx, constraint, ifNotExists); err != nil {
			return nil, err
		}
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	}

	if parsed, err := e.parseCreateConstraintTemporalDDL(cypher); err == nil {
		if parsed.isRelationship {
			if len(parsed.properties) < 3 {
				return nil, localizedError(localization.CypherSchemaTemporalRelationshipArityRequired(), nil)
			}
			constraintName := parsed.name
			if constraintName == "" {
				constraintName = fmt.Sprintf("constraint_%s_%s_temporal", parsed.label, strings.Join(parsed.properties, "_"))
			}
			constraint := storage.Constraint{
				Name:       constraintName,
				Type:       storage.ConstraintTemporal,
				EntityType: storage.ConstraintEntityRelationship,
				Label:      parsed.label,
				Properties: parsed.properties,
			}
			if err := storage.ValidateConstraintOnCreationForEngineWithContext(ctx, e.storage, constraint); err != nil {
				return nil, err
			}
			if err := e.addSchemaConstraint(ctx, constraint, ifNotExists); err != nil {
				return nil, err
			}
			return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
		}

		// Like relationships: (key..., valid_from, valid_to) with a 1..n property grouping key.
		if len(parsed.properties) < 3 {
			return nil, localizedError(localization.CypherSchemaTemporalNodeArityRequired(), nil)
		}
		constraintName := parsed.name
		if constraintName == "" {
			constraintName = fmt.Sprintf("constraint_%s_%s_temporal", parsed.label, strings.Join(parsed.properties, "_"))
		}
		constraint := storage.Constraint{
			Name:       constraintName,
			Type:       storage.ConstraintTemporal,
			Label:      parsed.label,
			Properties: parsed.properties,
		}
		if err := storage.ValidateConstraintOnCreationForEngineWithContext(ctx, e.storage, constraint); err != nil {
			return nil, err
		}
		if err := e.addSchemaConstraint(ctx, constraint, ifNotExists); err != nil {
			return nil, err
		}
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	}

	if parsed, err := e.parseCreateConstraintDomainDDL(cypher); err == nil {
		allowedValues, err := parseDomainValueList(parsed.allowedRaw)
		if err != nil {
			return nil, localizedError(localization.CypherSchemaDomainValueListInvalid(err), err)
		}
		if len(allowedValues) == 0 {
			return nil, localizedError(localization.CypherSchemaDomainAllowedValueRequired(), nil)
		}
		constraintName := parsed.name
		if constraintName == "" {
			constraintName = fmt.Sprintf("constraint_%s_%s_domain", parsed.label, parsed.property)
		}
		constraint := storage.Constraint{
			Name:          constraintName,
			Type:          storage.ConstraintDomain,
			Label:         parsed.label,
			Properties:    []string{parsed.property},
			AllowedValues: allowedValues,
		}
		if parsed.isRelationship {
			constraint.EntityType = storage.ConstraintEntityRelationship
		}
		if err := storage.ValidateConstraintOnCreationForEngineWithContext(ctx, e.storage, constraint); err != nil {
			return nil, err
		}
		if err := e.addSchemaConstraint(ctx, constraint, ifNotExists); err != nil {
			return nil, err
		}
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	}

	if parsed, err := e.parseCreateConstraintSimplePropertyDDL(cypher); err == nil {
		if parsed.kind == "unique" {
			if parsed.isRelationship {
				constraintName := parsed.name
				if constraintName == "" {
					constraintName = fmt.Sprintf("constraint_%s_%s_unique", parsed.label, parsed.property)
				}
				constraint := storage.Constraint{
					Name:       constraintName,
					Type:       storage.ConstraintUnique,
					EntityType: storage.ConstraintEntityRelationship,
					Label:      parsed.label,
					Properties: []string{parsed.property},
				}
				if err := storage.ValidateConstraintOnCreationForEngineWithContext(ctx, e.storage, constraint); err != nil {
					return nil, err
				}
				if err := e.addSchemaConstraint(ctx, constraint, ifNotExists); err != nil {
					return nil, err
				}
				return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
			}

			constraintName := parsed.name
			if constraintName == "" {
				constraintName = fmt.Sprintf("constraint_%s_%s", parsed.label, parsed.property)
			}
			constraint := storage.Constraint{
				Name:       constraintName,
				Type:       storage.ConstraintUnique,
				Label:      parsed.label,
				Properties: []string{parsed.property},
			}
			if err := storage.ValidateConstraintOnCreationForEngineWithContext(ctx, e.storage, constraint); err != nil {
				return nil, err
			}
			schema := e.storage.GetSchema()
			if err := e.addSchemaConstraint(ctx, constraint, ifNotExists); err != nil {
				return nil, err
			}
			if err := storage.RefreshUniqueConstraintValuesForEngineWithContext(ctx, e.storage, schema); err != nil {
				return nil, err
			}
			return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
		}

		if parsed.kind == "exists" {
			constraintName := parsed.name
			if constraintName == "" {
				suffix := "exists"
				if parsed.isRelationship {
					constraintName = fmt.Sprintf("constraint_%s_%s_%s", parsed.label, parsed.property, suffix)
				} else {
					constraintName = fmt.Sprintf("constraint_%s_%s_%s", parsed.label, parsed.property, suffix)
				}
			}
			constraint := storage.Constraint{
				Name:       constraintName,
				Type:       storage.ConstraintExists,
				Label:      parsed.label,
				Properties: []string{parsed.property},
			}
			if parsed.isRelationship {
				constraint.EntityType = storage.ConstraintEntityRelationship
			}
			if err := storage.ValidateConstraintOnCreationForEngineWithContext(ctx, e.storage, constraint); err != nil {
				return nil, err
			}
			if err := e.addSchemaConstraint(ctx, constraint, ifNotExists); err != nil {
				return nil, err
			}
			return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
		}
	}

	if parsed, err := e.parseCreateConstraintTypeDDL(cypher); err == nil {
		constraintName := parsed.name
		if constraintName == "" {
			constraintName = fmt.Sprintf("constraint_%s_%s_type", parsed.label, parsed.property)
		}
		ptc := storage.PropertyTypeConstraint{
			Name:         constraintName,
			Label:        parsed.label,
			Property:     parsed.property,
			ExpectedType: parsed.expectedType,
		}
		opts := storage.PropertyTypeConstraintOptions{IfNotExists: ifNotExists}
		if parsed.isRelationship {
			ptc.EntityType = storage.ConstraintEntityRelationship
			opts.EntityType = storage.ConstraintEntityRelationship
		}
		if err := storage.ValidatePropertyTypeConstraintOnCreationForEngineWithContext(ctx, e.storage, ptc); err != nil {
			return nil, err
		}
		if err := e.storage.GetSchema().AddPropertyTypeConstraintWithOptions(constraintName, parsed.label, parsed.property, parsed.expectedType, opts); err != nil {
			return nil, err
		}
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	} else if startsWithKeywordFold(strings.TrimSpace(cypher), "CREATE CONSTRAINT") &&
		(strings.Contains(upperASCII(cypher), " IS ::") || strings.Contains(upperASCII(cypher), " IS TYPED")) &&
		strings.Contains(upperASCII(err.Error()), "UNSUPPORTED PROPERTY TYPE") {
		return nil, err
	}

	// Single-property UNIQUE/EXISTS branches are handled by parseCreateConstraintSimplePropertyDDL.

	// =========================================================================
	// Relationship constraint patterns
	// =========================================================================

	if parsed, err := e.parseCreateConstraintCardinalityDDL(cypher); err == nil {
		constraintName := parsed.name
		if constraintName == "" {
			directionSuffix := "outgoing"
			if parsed.direction == "INCOMING" {
				directionSuffix = "incoming"
			}
			constraintName = fmt.Sprintf("constraint_%s_max_%s_%d", parsed.relType, directionSuffix, parsed.maxCount)
		}
		constraint := storage.Constraint{
			Name:       constraintName,
			Type:       storage.ConstraintCardinality,
			EntityType: storage.ConstraintEntityRelationship,
			Label:      parsed.relType,
			MaxCount:   parsed.maxCount,
			Direction:  parsed.direction,
		}
		if err := storage.ValidateConstraintOnCreationForEngineWithContext(ctx, e.storage, constraint); err != nil {
			return nil, err
		}
		if err := e.addSchemaConstraint(ctx, constraint, ifNotExists); err != nil {
			return nil, err
		}
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	} else if startsWithKeywordFold(strings.TrimSpace(cypher), "CREATE CONSTRAINT") &&
		strings.Contains(upperASCII(cypher), "REQUIRE MAX COUNT") {
		return nil, err
	}

	if parsed, err := e.parseCreateConstraintPolicyDDL(cypher); err == nil {
		constraintName := parsed.name
		if constraintName == "" {
			constraintName = fmt.Sprintf("constraint_%s_%s_%s_%s", parsed.sourceLabel, parsed.relType, parsed.targetLabel, lowerASCII(parsed.policyMode))
		}
		constraint := storage.Constraint{
			Name:        constraintName,
			Type:        storage.ConstraintPolicy,
			EntityType:  storage.ConstraintEntityRelationship,
			Label:       parsed.relType,
			SourceLabel: parsed.sourceLabel,
			TargetLabel: parsed.targetLabel,
			PolicyMode:  parsed.policyMode,
		}
		if err := storage.ValidateConstraintOnCreationForEngineWithContext(ctx, e.storage, constraint); err != nil {
			return nil, err
		}
		if err := e.addSchemaConstraint(ctx, constraint, ifNotExists); err != nil {
			return nil, err
		}
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	} else if startsWithKeywordFold(strings.TrimSpace(cypher), "CREATE CONSTRAINT") &&
		(strings.Contains(upperASCII(cypher), "REQUIRE ALLOWED") || strings.Contains(upperASCII(cypher), "REQUIRE DISALLOWED")) {
		return nil, err
	}

	// Relationship temporal/domain branches are handled by parseCreateConstraintTemporalDDL and parseCreateConstraintDomainDDL.

	if parsed, err := e.parseCreateConstraintRelationshipKeyOrCompositeUniqueDDL(cypher); err == nil {
		if len(parsed.properties) == 0 {
			if parsed.kind == "rel_key" {
				return nil, localizedError(localization.CypherSchemaConstraintPropertiesRequired("RELATIONSHIP KEY"), nil)
			}
			return nil, localizedError(localization.CypherSchemaConstraintPropertiesRequired("UNIQUE"), nil)
		}

		constraint := storage.Constraint{
			Label:      parsed.label,
			Properties: parsed.properties,
		}
		if parsed.isRelationship {
			constraint.EntityType = storage.ConstraintEntityRelationship
		}
		if parsed.kind == "rel_key" {
			constraint.Type = storage.ConstraintRelationshipKey
			constraint.Name = parsed.name
			if constraint.Name == "" {
				constraint.Name = fmt.Sprintf("constraint_%s_%s_rel_key", parsed.label, strings.Join(parsed.properties, "_"))
			}
		} else {
			constraint.Type = storage.ConstraintUnique
			constraint.Name = parsed.name
			if constraint.Name == "" {
				constraint.Name = fmt.Sprintf("constraint_%s_%s_unique", parsed.label, strings.Join(parsed.properties, "_"))
			}
		}

		if err := storage.ValidateConstraintOnCreationForEngineWithContext(ctx, e.storage, constraint); err != nil {
			return nil, err
		}
		if err := e.addSchemaConstraint(ctx, constraint, ifNotExists); err != nil {
			return nil, err
		}
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	}

	// Relationship single-property UNIQUE/EXISTS branches are handled by parseCreateConstraintSimplePropertyDDL.

	// Relationship property type branches are handled by parseCreateConstraintTypeDDL.

	return nil, localizedError(localization.CypherSchemaInvalidSyntax("CREATE CONSTRAINT"), nil)
}

// executeDropIndex handles DROP INDEX commands.
//
// Supported syntax:
//
//	DROP INDEX index_name
//	DROP INDEX index_name IF EXISTS
func (e *StorageExecutor) executeDropIndex(ctx context.Context, cypher string) (*ExecuteResult, error) {
	if isCompositeRoot(e.storage) {
		return nil, localizedError(localization.CypherSchemaCompositeDDLNotAllowed(), nil)
	}

	rest := strings.TrimSpace(strings.TrimSpace(cypher)[len("DROP INDEX"):])
	if rest == "" {
		return nil, localizedError(localization.CypherSchemaNameRequired("DROP INDEX", "index"), nil)
	}
	name, ifExists, ok := parseDropSchemaName(rest)
	if !ok {
		return nil, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", localization.CypherSchemaInvalidSyntax("DROP INDEX"))
	}

	if err := e.dropIndexByName(name, ifExists); err != nil {
		return nil, err
	}
	return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
}

// parseDropSchemaName reads the rest of DROP INDEX / DROP CONSTRAINT: one
// name, plain or backtick-quoted, with IF EXISTS after it (Neo4j's form) or
// before it. Anything else is no such statement: Neo4j's SyntaxError for
// DROP INDEX name -> text (#528), where the text was read as part of the
// name.
func parseDropSchemaName(rest string) (name string, ifExists, ok bool) {
	at := 0
	if matchKeywordAt(rest, at, "IF") {
		if next := skipASCIISpaces(rest, at+len("IF"), len(rest)); matchKeywordAt(rest, next, "EXISTS") {
			ifExists, at = true, skipASCIISpaces(rest, next+len("EXISTS"), len(rest))
		}
	}
	written, end, scanned := scanSymbolicName(rest, at)
	if !scanned {
		return "", false, false
	}
	at = skipASCIISpaces(rest, end, len(rest))
	if !ifExists && matchKeywordAt(rest, at, "IF") {
		if next := skipASCIISpaces(rest, at+len("IF"), len(rest)); matchKeywordAt(rest, next, "EXISTS") {
			ifExists, at = true, skipASCIISpaces(rest, next+len("EXISTS"), len(rest))
		}
	}
	if at != len(rest) {
		return "", false, false
	}
	return symbolicNameValue(written), ifExists, true
}

// dropIndexByName removes the named index from the schema and tears down the
// in-memory data that belongs to it. It is the single drop path for DROP INDEX
// and the db.index.vector.drop / db.index.fulltext.drop procedures. A missing
// index is a Neo.DatabaseError.Schema.IndexDropFailed error unless ifExists is set.
func (e *StorageExecutor) dropIndexByName(name string, ifExists bool) error {
	// Look up the schema entry BEFORE dropping it so we can also tear down
	// any in-memory index data the schema entry was the only handle for.
	// Vector indexes carry their declared (label, property) — when the user
	// drops one we must also delete every "<nodeID>-prop-<property>" vector
	// from the search service, otherwise a recreate-from-scratch of the same
	// index inherits orphaned vectors that still match queries.
	var droppedVectorIndex *storage.VectorIndex
	if schema := e.storage.GetSchema(); schema != nil {
		if vi, ok := schema.GetVectorIndex(name); ok && vi != nil {
			copyVI := *vi
			droppedVectorIndex = &copyVI
		}
	}

	if err := e.storage.GetSchema().DropIndex(name); err != nil {
		var missing *localization.LocalizedError
		if errors.As(err, &missing) && missing.Message.ID == localization.MessageStorageSchemaIndexNotFound {
			if ifExists {
				return nil
			}
			return newSemanticError("Neo.DatabaseError.Schema.IndexDropFailed", "MissingIndex", err.Error())
		}
		return err
	}

	// Tear down the matching in-memory vector data after the schema entry
	// is gone so concurrent reads can't see a half-dropped index.
	if droppedVectorIndex != nil {
		e.afterSchemaCommit(context.Background(), func() {
			if svc := e.search(); svc != nil && droppedVectorIndex.Property != "" {
				svc.RemovePropertyVectorIndex(droppedVectorIndex.Property)
			}
			e.unregisterVectorSpace(name)
		})
	}

	// Invalidate query cache — cached SHOW INDEXES results are now stale.
	if e.cache != nil {
		e.cache.Invalidate()
	}
	return nil
}

// executeDropConstraint handles DROP CONSTRAINT commands.
func (e *StorageExecutor) executeDropConstraint(ctx context.Context, cypher string) (*ExecuteResult, error) {
	trimmed := strings.TrimSpace(cypher)
	upper := upperASCII(trimmed)
	if !strings.HasPrefix(upper, "DROP CONSTRAINT") {
		return nil, localizedError(localization.CypherSchemaInvalidSyntax("DROP CONSTRAINT"), nil)
	}

	rest := strings.TrimSpace(trimmed[len("DROP CONSTRAINT"):])
	if rest == "" {
		return nil, localizedError(localization.CypherSchemaInvalidSyntax("DROP CONSTRAINT"), nil)
	}

	name, ifExists, ok := parseDropSchemaName(rest)
	if !ok {
		return nil, localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", localization.CypherSchemaInvalidSyntax("DROP CONSTRAINT"))
	}

	if err := e.storage.GetSchema().DropConstraint(name); err != nil {
		var missing *localization.LocalizedError
		if errors.As(err, &missing) && missing.Message.ID == localization.MessageStorageSchemaConstraintNotFound {
			if ifExists {
				return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
			}
			return nil, newSemanticError("Neo.DatabaseError.Schema.ConstraintDropFailed", "MissingConstraint", err.Error())
		}
		return nil, err
	}

	if e.cache != nil {
		e.cache.Invalidate()
	}

	return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
}

// executeCreateIndex handles CREATE INDEX commands.
//
// Supported syntax:
//
//	CREATE INDEX index_name IF NOT EXISTS FOR (n:Label) ON (n.property)
//	CREATE INDEX index_name IF NOT EXISTS FOR (n:Label) ON (n.prop1, n.prop2)
//	CREATE INDEX IF NOT EXISTS FOR (n:Label) ON (n.prop1, n.prop2, n.prop3)
//
// Supports both single-property and composite (multi-property) indexes.
func (e *StorageExecutor) executeCreateIndex(ctx context.Context, cypher string) (*ExecuteResult, error) {
	if parsed, err := e.parseCreateIndexDDL(cypher, "CREATE INDEX"); err == nil {
		indexName := parsed.indexName
		if indexName == "" {
			propsJoined := strings.Join(parsed.properties, "_")
			entity := parsed.label
			if parsed.isRelationship {
				entity = parsed.relationshipType
			}
			indexName = fmt.Sprintf("index_%s_%s", entity, propsJoined)
		}

		entityType := storage.ConstraintEntityNode
		label := parsed.label
		if parsed.isRelationship {
			entityType = storage.ConstraintEntityRelationship
			label = parsed.relationshipType
		}
		create, err := e.admitIndexCreation(cypher, indexName, "RANGE", label, parsed.properties, entityType)
		if err != nil {
			return nil, err
		}
		if !create {
			return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
		}

		if parsed.isRelationship {
			// Relationship property indexes are persisted as relationship-scoped
			// range metadata (Neo4j-compatible SHOW INDEXES shape).
			if err := e.storage.GetSchema().AddRangeIndexForEntity(
				indexName,
				parsed.relationshipType,
				parsed.properties,
				storage.ConstraintEntityRelationship,
			); err != nil {
				return nil, err
			}
			return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
		}

		if err := e.addPropertyIndex(ctx, indexName, parsed.label, parsed.properties); err != nil {
			return nil, err
		}

		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	}

	// Neo4j legacy syntax: CREATE INDEX [name] ON :Label(prop[, prop2])
	if parsed, err := e.parseCreateIndexLegacyDDL(cypher); err == nil {
		indexName := parsed.indexName
		if indexName == "" {
			propsJoined := strings.Join(parsed.properties, "_")
			indexName = fmt.Sprintf("index_%s_%s", parsed.label, propsJoined)
		}
		if err := e.addPropertyIndex(ctx, indexName, parsed.label, parsed.properties); err != nil {
			return nil, err
		}
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	}

	return nil, localizedError(localization.CypherSchemaInvalidSyntax("CREATE INDEX"), nil)
}

// executeCreateRangeIndex handles CREATE RANGE INDEX. In Neo4j 5 a RANGE
// index is the default index CREATE INDEX makes, so the statement runs as
// CREATE INDEX: single or composite properties, node or relationship
// patterns, as SHOW INDEXES' createStatement writes it (#531, #530).
func (e *StorageExecutor) executeCreateRangeIndex(ctx context.Context, cypher string) (*ExecuteResult, error) {
	start := findMultiWordKeywordIndex(cypher, "CREATE", "RANGE INDEX")
	end, ok := keywordSpanAt(cypher, start, "CREATE RANGE INDEX")
	if start < 0 || !ok {
		return nil, localizedError(localization.CypherSchemaInvalidSyntax("CREATE RANGE INDEX"), nil)
	}
	return e.executeCreateIndex(ctx, "CREATE INDEX"+cypher[end:])
}

type parsedCreateIndexDDL struct {
	indexName        string
	label            string
	relationshipType string
	properties       []string
	isRelationship   bool
	optionsClause    string
}

func keywordSpanAt(s string, pos int, keyword string) (int, bool) {
	ks, ke := trimKeywordWSBounds(keyword)
	return keywordMatchAt(s, pos, keyword, ks, ke)
}

func parseOptionalDDLName(segment string) (string, error) {
	segment = strings.TrimSpace(segment)
	if segment == "" {
		return "", nil
	}

	ifPos := keywordIndexFrom(segment, "IF NOT EXISTS", 0, defaultKeywordScanOpts())
	if ifPos < 0 {
		if !isValidDDLIdentifierSegment(segment) {
			return "", localizedError(localization.CypherSchemaInvalidIdentifierSegment(), nil)
		}
		name := normalizeIdentifierToken(segment)
		if name == "" {
			return "", localizedError(localization.CypherSchemaInvalidIdentifierSegment(), nil)
		}
		return name, nil
	}

	ifEnd, ok := keywordSpanAt(segment, ifPos, "IF NOT EXISTS")
	if !ok || strings.TrimSpace(segment[ifEnd:]) != "" {
		return "", localizedError(localization.CypherSchemaInvalidIfNotExistsClause(), nil)
	}

	namePart := strings.TrimSpace(segment[:ifPos])
	if namePart == "" {
		return "", nil
	}
	if !isValidDDLIdentifierSegment(namePart) {
		return "", localizedError(localization.CypherSchemaInvalidIdentifierSegment(), nil)
	}
	name := normalizeIdentifierToken(namePart)
	if name == "" {
		return "", localizedError(localization.CypherSchemaInvalidIdentifierSegment(), nil)
	}
	return name, nil
}

func isValidDDLIdentifierSegment(s string) bool {
	s = strings.TrimSpace(s)
	if s == "" {
		return false
	}
	if strings.HasPrefix(s, "`") {
		if !strings.HasSuffix(s, "`") {
			return false
		}
		return normalizeIdentifierToken(s) != ""
	}
	return len(strings.Fields(s)) == 1
}

func extractIndexPropertiesSegment(onClause string) (string, string, error) {
	onClause = strings.TrimSpace(onClause)
	if onClause == "" {
		return "", "", localizedError(localization.CypherSchemaEmptyClause("ON"), nil)
	}

	if strings.HasPrefix(onClause, "(") {
		inside, rest, ok := extractParenSection(onClause)
		if !ok {
			return "", "", localizedError(localization.CypherSchemaInvalidClause("ON"), nil)
		}
		return strings.TrimSpace(inside), strings.TrimSpace(rest), nil
	}

	optionsPos := keywordIndexFrom(onClause, "OPTIONS", 0, defaultKeywordScanOpts())
	if optionsPos < 0 {
		return strings.TrimSpace(onClause), "", nil
	}
	return strings.TrimSpace(onClause[:optionsPos]), strings.TrimSpace(onClause[optionsPos:]), nil
}

func parseCreateIndexForPattern(forClause string) (label string, relationshipType string, isRelationship bool, err error) {
	forClause = strings.TrimSpace(forClause)
	if forClause == "" {
		return "", "", false, localizedError(localization.CypherSchemaEmptyClause("FOR"), nil)
	}

	if strings.Contains(forClause, "[") {
		bracketStart := strings.Index(forClause, "[")
		if bracketStart < 0 {
			return "", "", false, localizedError(localization.CypherSchemaInvalidClause("relationship FOR"), nil)
		}
		inside, rest, ok := extractBracketSection(forClause[bracketStart:])
		if !ok {
			return "", "", false, localizedError(localization.CypherSchemaInvalidClause("relationship FOR"), nil)
		}

		prefix := strings.TrimSpace(forClause[:bracketStart])
		suffix := strings.TrimSpace(rest)
		if !strings.Contains(prefix, "(") || !strings.Contains(suffix, "(") {
			return "", "", false, localizedError(localization.CypherSchemaInvalidClause("relationship FOR"), nil)
		}

		colon := strings.Index(inside, ":")
		if colon < 0 {
			return "", "", false, localizedError(localization.CypherSchemaInvalidClause("relationship FOR"), nil)
		}
		relRaw := strings.TrimSpace(inside[colon+1:])
		if relRaw == "" {
			return "", "", false, localizedError(localization.CypherSchemaInvalidClause("relationship FOR"), nil)
		}
		relType := normalizeIdentifierToken(relRaw)
		if relType == "" {
			return "", "", false, localizedError(localization.CypherSchemaInvalidClause("relationship FOR"), nil)
		}
		return "", relType, true, nil
	}

	inside, rest, ok := extractParenSection(forClause)
	if !ok || strings.TrimSpace(rest) != "" {
		return "", "", false, localizedError(localization.CypherSchemaInvalidClause("node FOR"), nil)
	}

	colon := strings.Index(inside, ":")
	if colon < 0 {
		return "", "", false, localizedError(localization.CypherSchemaInvalidClause("node FOR"), nil)
	}
	labelRaw := strings.TrimSpace(inside[colon+1:])
	label = normalizeIdentifierToken(labelRaw)
	if label == "" {
		return "", "", false, localizedError(localization.CypherSchemaInvalidClause("node FOR"), nil)
	}
	return label, "", false, nil
}

func (e *StorageExecutor) parseCreateIndexDDL(cypher string, prefixKeyword string) (parsedCreateIndexDDL, error) {
	q := strings.TrimSpace(cypher)
	if q == "" {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaEmptyStatement(), nil)
	}

	prefixPos := keywordIndexFrom(q, prefixKeyword, 0, defaultKeywordScanOpts())
	if prefixPos != 0 {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("prefix"), nil)
	}
	prefixEnd, ok := keywordSpanAt(q, 0, prefixKeyword)
	if !ok {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("prefix"), nil)
	}

	forPos := keywordIndexFrom(q, "FOR", prefixEnd, defaultKeywordScanOpts())
	if forPos < 0 {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaMissingKeyword("FOR"), nil)
	}
	forEnd, ok := keywordSpanAt(q, forPos, "FOR")
	if !ok {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("FOR"), nil)
	}

	onPos := keywordIndexFrom(q, "ON", forEnd, defaultKeywordScanOpts())
	if onPos < 0 {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaMissingKeyword("ON"), nil)
	}
	onEnd, ok := keywordSpanAt(q, onPos, "ON")
	if !ok {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("ON"), nil)
	}

	name, err := parseOptionalDDLName(q[prefixEnd:forPos])
	if err != nil {
		return parsedCreateIndexDDL{}, err
	}

	label, relType, isRelationship, err := parseCreateIndexForPattern(q[forEnd:onPos])
	if err != nil {
		return parsedCreateIndexDDL{}, err
	}

	propsSegment, tail, err := extractIndexPropertiesSegment(q[onEnd:])
	if err != nil {
		return parsedCreateIndexDDL{}, err
	}
	if tail != "" && !startsWithKeywordFold(tail, "OPTIONS") {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaInvalidTrailingSyntax(), nil)
	}
	// ON EACH [...] is fulltext-index syntax; for CREATE [RANGE|VECTOR] INDEX
	// every item must be a plain variable.property reference, otherwise the
	// leftover text (e.g. "p]") would be stored as the property name.
	if startsWithKeywordFold(propsSegment, "EACH") || strings.HasPrefix(propsSegment, "[") ||
		!qualifiedIndexPropertiesWellFormed(propsSegment) {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaInvalidClause("ON"), nil)
	}

	properties := e.parseQualifiedIndexProperties(propsSegment)
	if len(properties) == 0 {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaIndexPropertiesRequired(), nil)
	}

	return parsedCreateIndexDDL{
		indexName:        name,
		label:            label,
		relationshipType: relType,
		properties:       properties,
		isRelationship:   isRelationship,
		optionsClause:    tail,
	}, nil
}

func (e *StorageExecutor) parseCreateIndexLegacyDDL(cypher string) (parsedCreateIndexDDL, error) {
	q := strings.TrimSpace(cypher)
	if q == "" {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaEmptyStatement(), nil)
	}

	prefixPos := keywordIndexFrom(q, "CREATE INDEX", 0, defaultKeywordScanOpts())
	if prefixPos != 0 {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("prefix"), nil)
	}
	prefixEnd, ok := keywordSpanAt(q, 0, "CREATE INDEX")
	if !ok {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("prefix"), nil)
	}

	onPos := keywordIndexFrom(q, "ON", prefixEnd, defaultKeywordScanOpts())
	if onPos < 0 {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaMissingKeyword("ON"), nil)
	}
	onEnd, ok := keywordSpanAt(q, onPos, "ON")
	if !ok {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("ON"), nil)
	}

	name, err := parseOptionalDDLName(q[prefixEnd:onPos])
	if err != nil {
		return parsedCreateIndexDDL{}, err
	}

	onClause := strings.TrimSpace(q[onEnd:])
	if !strings.HasPrefix(onClause, ":") {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaInvalidClause("legacy ON"), nil)
	}
	onClause = strings.TrimSpace(onClause[1:])

	openParen := strings.Index(onClause, "(")
	if openParen < 0 {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaInvalidClause("legacy ON"), nil)
	}
	label := normalizeIdentifierToken(strings.TrimSpace(onClause[:openParen]))
	if label == "" {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaInvalidClause("legacy ON"), nil)
	}

	inside, tail, ok := extractParenSection(onClause[openParen:])
	if !ok {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaInvalidClause("legacy ON"), nil)
	}
	tail = strings.TrimSpace(tail)
	if tail != "" && !startsWithKeywordFold(tail, "OPTIONS") {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaInvalidTrailingSyntax(), nil)
	}

	properties := e.parseIndexProperties(inside)
	if len(properties) == 0 {
		return parsedCreateIndexDDL{}, localizedError(localization.CypherSchemaIndexPropertiesRequired(), nil)
	}

	return parsedCreateIndexDDL{
		indexName:      name,
		label:          label,
		properties:     properties,
		isRelationship: false,
		optionsClause:  tail,
	}, nil
}

func isVectorKeyBoundaryChar(b byte) bool {
	if b >= 'a' && b <= 'z' {
		return false
	}
	if b >= 'A' && b <= 'Z' {
		return false
	}
	if b >= '0' && b <= '9' {
		return false
	}
	return b != '_' && b != '.'
}

func extractVectorOptionValue(optionsClause, key string) (string, bool) {
	if optionsClause == "" || key == "" {
		return "", false
	}
	for index := 0; index < len(optionsClause); {
		name, end, ok := scanIdentifierToken(optionsClause, index)
		if !ok && isCypherStringQuoteByte(optionsClause[index]) {
			if quotedEnd, closed := scanCypherQuotedText(optionsClause, index, optionsClause[index]); closed {
				name, ok = decodeCypherQuotedString(optionsClause[index:quotedEnd])
				end = quotedEnd
			}
		}
		if !ok {
			index++
			continue
		}
		index = end
		if !strings.EqualFold(name, key) {
			continue
		}
		separator := queryGapEnd(optionsClause, end)
		if separator >= len(optionsClause) || optionsClause[separator] != ':' {
			continue
		}
		start := queryGapEnd(optionsClause, separator+1)
		if start >= len(optionsClause) {
			return "", false
		}
		if finish, closed := scanCypherQuotedText(optionsClause, start, optionsClause[start]); closed {
			if value, quoted := decodeCypherQuotedString(optionsClause[start:finish]); quoted {
				return strings.TrimSpace(value), true
			}
		}
		depth := 0
		for j := start; j < len(optionsClause); j++ {
			if finish, quoted := skipCypherLexicalToken(optionsClause, j); quoted {
				j = finish - 1
				continue
			}
			c := optionsClause[j]
			switch c {
			case '(', '[', '{':
				depth++
			case ')', ']', '}':
				if depth == 0 {
					return strings.TrimSpace(optionsClause[start:j]), true
				}
				depth--
			}
			if depth == 0 && (c == ',' || c == '\n' || c == '\r') {
				return strings.TrimSpace(optionsClause[start:j]), true
			}
		}
		return strings.TrimSpace(optionsClause[start:]), true
	}
	return "", false
}

func parseVectorOptions(optionsClause string, defaultDimensions int, defaultSimilarity string) (int, string) {
	dimensions := defaultDimensions
	similarity := defaultSimilarity

	if raw, ok := extractVectorOptionValue(optionsClause, "vector.dimensions"); ok {
		if dim, err := strconv.Atoi(strings.TrimSpace(raw)); err == nil {
			dimensions = dim
		}
	}

	if raw, ok := extractVectorOptionValue(optionsClause, "vector.similarity_function"); ok {
		raw = strings.TrimSpace(raw)
		if raw != "" {
			similarity = raw
		}
	}

	return dimensions, similarity
}

type parsedCreateFulltextIndexDDL struct {
	indexName         string
	label             string
	labels            []string
	relationshipTypes []string
	properties        []string
	isRelationship    bool
}

func parseCreateFulltextForPattern(forClause string) (label string, relationshipTypes []string, isRelationship bool, err error) {
	label, relTypeRaw, isRelationship, err := parseCreateIndexForPattern(forClause)
	if err != nil {
		// Neo4j compatibility: allow non-parenthesized node pattern `n:Label`.
		if !strings.Contains(forClause, "[") {
			parts := strings.SplitN(strings.TrimSpace(forClause), ":", 2)
			if len(parts) == 2 {
				compatLabel := normalizeIdentifierToken(strings.TrimSpace(parts[1]))
				if compatLabel != "" {
					return compatLabel, nil, false, nil
				}
			}
		}
		return "", nil, false, err
	}
	if !isRelationship {
		return label, nil, false, nil
	}
	relTypes, err := parseFulltextRelationshipTypes(relTypeRaw)
	if err != nil {
		return "", nil, false, err
	}
	return "", relTypes, true, nil
}

func extractFulltextPropertiesSegment(onClause string) (string, string, error) {
	onClause = strings.TrimSpace(onClause)
	if onClause == "" {
		return "", "", localizedError(localization.CypherSchemaEmptyClause("ON"), nil)
	}

	if startsWithKeywordFold(onClause, "EACH") {
		eachEnd, ok := keywordSpanAt(onClause, 0, "EACH")
		if !ok {
			return "", "", localizedError(localization.CypherSchemaInvalidClause("EACH"), nil)
		}
		onClause = strings.TrimSpace(onClause[eachEnd:])
	}

	if onClause == "" {
		return "", "", localizedError(localization.CypherSchemaEmptyClause("ON"), nil)
	}

	if strings.HasPrefix(onClause, "[") {
		inside, rest, ok := extractBracketSection(onClause)
		if !ok {
			return "", "", localizedError(localization.CypherSchemaInvalidClause("ON EACH"), nil)
		}
		return strings.TrimSpace(inside), strings.TrimSpace(rest), nil
	}

	if strings.HasPrefix(onClause, "(") {
		inside, rest, ok := extractParenSection(onClause)
		if !ok {
			return "", "", localizedError(localization.CypherSchemaInvalidClause("ON"), nil)
		}
		return strings.TrimSpace(inside), strings.TrimSpace(rest), nil
	}

	optionsPos := keywordIndexFrom(onClause, "OPTIONS", 0, defaultKeywordScanOpts())
	if optionsPos < 0 {
		return strings.TrimSpace(onClause), "", nil
	}
	return strings.TrimSpace(onClause[:optionsPos]), strings.TrimSpace(onClause[optionsPos:]), nil
}

func (e *StorageExecutor) parseCreateFulltextIndexDDL(cypher string) (parsedCreateFulltextIndexDDL, error) {
	q := strings.TrimSpace(cypher)
	if q == "" {
		return parsedCreateFulltextIndexDDL{}, localizedError(localization.CypherSchemaEmptyStatement(), nil)
	}

	prefixPos := keywordIndexFrom(q, "CREATE FULLTEXT INDEX", 0, defaultKeywordScanOpts())
	if prefixPos != 0 {
		return parsedCreateFulltextIndexDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("prefix"), nil)
	}
	prefixEnd, ok := keywordSpanAt(q, 0, "CREATE FULLTEXT INDEX")
	if !ok {
		return parsedCreateFulltextIndexDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("prefix"), nil)
	}

	forPos := keywordIndexFrom(q, "FOR", prefixEnd, defaultKeywordScanOpts())
	if forPos < 0 {
		return parsedCreateFulltextIndexDDL{}, localizedError(localization.CypherSchemaMissingKeyword("FOR"), nil)
	}
	forEnd, ok := keywordSpanAt(q, forPos, "FOR")
	if !ok {
		return parsedCreateFulltextIndexDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("FOR"), nil)
	}

	onPos := keywordIndexFrom(q, "ON", forEnd, defaultKeywordScanOpts())
	if onPos < 0 {
		return parsedCreateFulltextIndexDDL{}, localizedError(localization.CypherSchemaMissingKeyword("ON"), nil)
	}
	onEnd, ok := keywordSpanAt(q, onPos, "ON")
	if !ok {
		return parsedCreateFulltextIndexDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("ON"), nil)
	}

	name, err := parseOptionalDDLName(q[prefixEnd:forPos])
	if err != nil {
		return parsedCreateFulltextIndexDDL{}, err
	}
	if name == "" {
		return parsedCreateFulltextIndexDDL{}, localizedError(localization.CypherSchemaIndexNameRequired(), nil)
	}

	label, relationshipTypes, isRelationship, err := parseCreateFulltextForPattern(q[forEnd:onPos])
	if err != nil {
		return parsedCreateFulltextIndexDDL{}, err
	}
	var labels []string
	if !isRelationship {
		pattern := strings.TrimSpace(q[forEnd:onPos])
		if inside, _, ok := extractParenSection(pattern); ok {
			pattern = inside
		}
		_, targets, _ := strings.Cut(pattern, ":")
		labels, err = parseFulltextRelationshipTypes(targets)
		if err != nil {
			return parsedCreateFulltextIndexDDL{}, err
		}
	}

	propsSegment, tail, err := extractFulltextPropertiesSegment(q[onEnd:])
	if err != nil {
		return parsedCreateFulltextIndexDDL{}, err
	}
	if tail != "" && !startsWithKeywordFold(tail, "OPTIONS") {
		return parsedCreateFulltextIndexDDL{}, localizedError(localization.CypherSchemaInvalidTrailingSyntax(), nil)
	}

	properties := e.parseQualifiedIndexProperties(propsSegment)
	if len(properties) == 0 {
		return parsedCreateFulltextIndexDDL{}, localizedError(localization.CypherSchemaFulltextPropertiesRequired(), nil)
	}

	return parsedCreateFulltextIndexDDL{
		indexName:         name,
		label:             label,
		labels:            labels,
		relationshipTypes: relationshipTypes,
		properties:        properties,
		isRelationship:    isRelationship,
	}, nil
}

