			return parsedSimplePropertyConstraintDDL{}, err
		}

		label, _, isRelationship, err := parseCreateIndexForPattern(q[onEnd:assertPos])
		if err != nil || isRelationship {
			return parsedSimplePropertyConstraintDDL{}, localizedError(localization.CypherSchemaInvalidPattern("ASSERT"), nil)
		}

		predicateExpr, tail := splitDDLOptionsTail(q[assertEnd:])
		if tail != "" && !startsWithKeywordFold(tail, "OPTIONS") {
			return parsedSimplePropertyConstraintDDL{}, localizedError(localization.CypherSchemaInvalidTrailingSyntax(), nil)
		}
		kind, property, ok := parseConstraintPredicate(predicateExpr)
		if !ok {
			return parsedSimplePropertyConstraintDDL{}, localizedError(localization.CypherSchemaUnsupportedPredicate("constraint"), nil)
		}
		return parsedSimplePropertyConstraintDDL{name: name, label: label, property: property, kind: kind, isRelationship: false}, nil
	}

	return parsedSimplePropertyConstraintDDL{}, localizedError(localization.CypherSchemaUnsupportedCreateConstraintShape(), nil)
}

// parseIndexProperties parses property list from index ON clause.
//
// Handles both single and composite property syntax:
//   - "n.property"           -> ["property"]
//   - "n.prop1, n.prop2"     -> ["prop1", "prop2"]
//   - "n.a, n.b, n.c"        -> ["a", "b", "c"]
func (e *StorageExecutor) parseIndexProperties(propertiesStr string) []string {
	return e.parseIndexPropertiesWithMode(propertiesStr, true)
}

// addSchemaConstraint adds constraint and, when it is a single-property
// uniqueness or node key constraint, fills the property index it owns from
// the stored nodes (#875), as addPropertyIndex fills a new index: equality
// and IN seeks then use it inside transactions as they use an index of its
// own. A constraint whose fill fails is dropped again, since a half-filled
// index would make seeks drop rows.
func (e *StorageExecutor) addSchemaConstraint(ctx context.Context, constraint storage.Constraint, ifNotExists bool) error {
	schema := e.storage.GetSchema()
	_, existed := schema.ConstraintPropertyIndex(constraint.Name)
	registered := schema.HasConstraintNamed(constraint.Name)
	if err := schema.AddConstraint(constraint, ifNotExists); err != nil {
		return err
	}
	// A new temporal constraint's history index is authoritative when its
	// label is empty; over existing nodes it isn't until the next rebuild
	// (#1126). IF NOT EXISTS on an existing constraint changes nothing.
	if !registered && constraint.Type == storage.ConstraintTemporal {
		if err := storage.MarkNewTemporalConstraintsForEngineWithContext(ctx, e.storage, schema, []storage.Constraint{constraint}); err != nil {
			return err
		}
	}
	index, owned := schema.ConstraintPropertyIndex(constraint.Name)
	if existed || !owned {
		return nil
	}
	if err := e.backfillCompositeIndex(ctx, index.Name, index.Label, index.Properties); err != nil {
		_ = schema.DropConstraint(constraint.Name)
		return err
	}
	return nil
}

// addPropertyIndex creates an equality index (arity-1 or composite) and,
// when it didn't exist yet, fills it from the label's nodes. An existing
// index is left as it is: it is already maintained, and filling it again
// would list its nodes twice. A new index whose fill fails is dropped again:
// index lookups trust an index to hold every node with the value, so a
// half-filled one would drop rows.
func (e *StorageExecutor) addPropertyIndex(ctx context.Context, name, label string, properties []string) error {
	schema := e.storage.GetSchema()
	_, existed := schema.GetCompositeIndex(name)
	if err := schema.AddCompositeIndex(name, label, properties); err != nil {
		return err
	}
	if existed {
		return nil
	}
	if err := e.backfillCompositeIndex(ctx, name, label, properties); err != nil {
		_ = schema.DropIndex(name)
		return err
	}
	return nil
}

// backfillCompositeIndex fills a newly created equality index from the
// label's stored nodes, those the visibility layer hides from reads included:
// an index lookup finds them once they are shown again, and a NODE KEY check
// that trusts the index sees their values. A new index whose fill fails is
// dropped by addPropertyIndex / addSchemaConstraint, since index lookups
// trust an index to hold every matching node.
func (e *StorageExecutor) backfillCompositeIndex(ctx context.Context, name, label string, properties []string) error {
	schema := e.storage.GetSchema()
	if schema == nil {
		return nil
	}
	nodes, err := storage.GetStoredNodesByLabelWithContext(ctx, e.storage, label)
	if err != nil {
		return localizedError(localization.CypherSchemaBackfillIndexFailed(label, err), err)
	}
	entries := make(map[storage.NodeID]map[string]interface{}, len(nodes))
	for _, node := range nodes {
		if node == nil || node.Properties == nil {
			continue
		}
		entries[storage.EnsureNodeIDDatabasePrefixForEngine(e.storage, node.ID)] = node.Properties
	}
	if err := schema.BackfillCompositeIndex(name, entries); err != nil {
		property := ""
		if len(properties) > 0 {
			property = properties[0]
		}
		return localizedError(localization.CypherSchemaBackfillPropertyIndexFailed(label, property, err), err)
	}
	return nil
}

// qualifiedIndexPropertiesWellFormed reports whether every comma-separated item
// of an index ON clause is a variable.property reference whose two parts are
// identifiers or backtick-quoted names. An empty list is left to the caller's
// "properties required" error.
func qualifiedIndexPropertiesWellFormed(propertiesStr string) bool {
	if strings.TrimSpace(propertiesStr) == "" {
		return true
	}
	for _, part := range splitTopLevelComma(propertiesStr) {
		part = strings.TrimSpace(part)
		variable, property, ok := splitPostfixPropertyAccess(part)
		if !ok || !isPatternVariableName(strings.TrimSpace(variable)) || property == "" {
			return false
		}
	}
	return true
}

func (e *StorageExecutor) parseQualifiedIndexProperties(propertiesStr string) []string {
	return e.parseIndexPropertiesWithMode(propertiesStr, false)
}

func (e *StorageExecutor) parseIndexPropertiesWithMode(propertiesStr string, allowBare bool) []string {
	// Split by comma
	parts := strings.Split(propertiesStr, ",")
	var properties []string

	for _, part := range parts {
		part = strings.TrimSpace(part)
		// Extract property name after dot (e.g., "n.prop" -> "prop")
		if dotIdx := strings.LastIndex(part, "."); dotIdx >= 0 && dotIdx < len(part)-1 {
			propName := normalizeIdentifierToken(part[dotIdx+1:])
			if propName != "" {
				properties = append(properties, propName)
			}
		} else if allowBare {
			// Also support bare property names used by legacy syntax ON :Label(prop)
			propName := normalizeIdentifierToken(part)
			if propName != "" {
				properties = append(properties, propName)
			}
		}
	}

	return properties
}

func (e *StorageExecutor) parseConstraintProperties(propertiesStr string) []string {
	parts := strings.Split(propertiesStr, ",")
	properties := make([]string, 0, len(parts))
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if dotIdx := strings.LastIndex(part, "."); dotIdx >= 0 && dotIdx < len(part)-1 {
			propName := normalizeIdentifierToken(part[dotIdx+1:])
			if propName != "" {
				properties = append(properties, propName)
			}
		}
	}
	return properties
}

// executeCreateFulltextIndex handles CREATE FULLTEXT INDEX commands.
//
// Supported syntax:
//
//	CREATE FULLTEXT INDEX index_name [IF NOT EXISTS]
//	FOR (n:Label) ON EACH [n.prop1, n.prop2]
//
//	CREATE FULLTEXT INDEX index_name [IF NOT EXISTS]
//	FOR ()-[r:RelType]-() ON EACH [r.prop1, r.prop2]
//
// The relationship form binds an index to a relationship type (or
// types — Neo4j allows `:R1|R2`); the runtime then scopes
// db.index.fulltext.queryRelationships to those types instead of
// scanning every edge.
func (e *StorageExecutor) executeCreateFulltextIndex(ctx context.Context, cypher string) (*ExecuteResult, error) {
	schema := e.storage.GetSchema()
	if schema == nil {
		return nil, localizedError(localization.CypherSchemaManagerUnavailable(), nil)
	}

	parsed, err := e.parseCreateFulltextIndexDDL(cypher)
	if err != nil {
		return nil, err
	}

	entityType := storage.ConstraintEntityNode
	targets := parsed.labels
	if parsed.isRelationship {
		entityType = storage.ConstraintEntityRelationship
		targets = parsed.relationshipTypes
	}
	create, err := e.admitIndexCreationForTargets(cypher, parsed.indexName, "FULLTEXT", targets, parsed.properties, entityType)
	if err != nil {
		return nil, err
	}
	if !create {
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	}

	if parsed.isRelationship {
		if err := schema.AddFulltextRelationshipIndex(parsed.indexName, parsed.relationshipTypes, parsed.properties); err != nil {
			return nil, localizedError(localization.CypherSchemaAddFulltextRelationshipIndexFailed(err), err)
		}
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	}

	if err := schema.AddFulltextIndex(parsed.indexName, parsed.labels, parsed.properties); err != nil {
		return nil, localizedError(localization.CypherSchemaAddFulltextIndexFailed(err), err)
	}

	return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
}

// parseDomainValueList parses a comma-separated list of literal values from a domain constraint.
// Supports strings ('value' or "value"), integers, and floats.
func parseDomainValueList(raw string) ([]interface{}, error) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return nil, nil
	}

	var values []interface{}
	for _, item := range splitTopLevelComma(raw) {
		token := strings.TrimSpace(item)
		if token == "" {
			continue
		}
		if value, quoted := decodeCypherQuotedString(token); quoted {
			values = append(values, value)
		} else if isCypherStringQuoteByte(token[0]) {
			return nil, localizedError(localization.CypherSchemaUnterminatedString(token), nil)
		} else {
			// Numeric or boolean literal
			// Try integer
			if intVal, err := strconv.ParseInt(token, 10, 64); err == nil {
				values = append(values, intVal)
			} else if floatVal, err := strconv.ParseFloat(token, 64); err == nil {
				values = append(values, floatVal)
			} else if token == "true" {
				values = append(values, true)
			} else if token == "false" {
				values = append(values, false)
			} else {
				// Treat as bare string
				values = append(values, token)
			}
		}

	}

	return values, nil
}

func parseFulltextRelationshipTypes(raw string) ([]string, error) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return nil, nerrors.ErrInvalidFulltextRelationshipTypes
	}

	types := make([]string, 0, 2)
	var cur strings.Builder

	flush := func() error {
		part := normalizeIdentifierToken(strings.TrimSpace(cur.String()))
		cur.Reset()
		if part == "" {
			return nerrors.ErrInvalidFulltextRelationshipTypes
		}
		types = append(types, part)
		return nil
	}

	for index := 0; index < len(raw); index++ {
		if isCypherBacktickByte(raw[index]) {
			end, closed := scanCypherQuotedText(raw, index, raw[index])
			if !closed {
				return nil, nerrors.ErrInvalidFulltextRelationshipTypes
			}
			cur.WriteString(raw[index:end])
			index = end - 1
			continue
		}
		switch raw[index] {
		case '|':
			if err := flush(); err != nil {
				return nil, err
			}
		default:
			cur.WriteByte(raw[index])
		}
	}
	if err := flush(); err != nil {
		return nil, err
	}
	return types, nil
}

func normalizeIdentifierToken(v string) string {
	s := strings.TrimSpace(v)
	if len(s) >= 2 && strings.HasPrefix(s, "`") && strings.HasSuffix(s, "`") {
		s = s[1 : len(s)-1]
		s = strings.ReplaceAll(s, "``", "`")
	}
	return strings.TrimSpace(s)
}

// executeCreateVectorIndex handles CREATE VECTOR INDEX commands.
//
// Supported syntax:
//
//	CREATE VECTOR INDEX index_name IF NOT EXISTS
//	FOR (n:Label) ON (n.property)
//	OPTIONS {indexConfig: {`vector.dimensions`: 1024, `vector.similarity_function`: 'cosine'}}
func (e *StorageExecutor) executeCreateVectorIndex(ctx context.Context, cypher string) (*ExecuteResult, error) {
	parsed, err := e.parseCreateIndexDDL(cypher, "CREATE VECTOR INDEX")
	if err != nil {
		return nil, localizedError(localization.CypherSchemaInvalidSyntax("CREATE VECTOR INDEX"), nil)
	}
	if len(parsed.properties) != 1 || parsed.indexName == "" ||
		(!parsed.isRelationship && parsed.label == "") ||
		(parsed.isRelationship && parsed.relationshipType == "") {
		return nil, localizedError(localization.CypherSchemaInvalidSyntax("CREATE VECTOR INDEX"), nil)
	}

	indexName := parsed.indexName
	label := parsed.label
	if parsed.isRelationship {
		label = parsed.relationshipType
	}
	property := parsed.properties[0]

	// Parse OPTIONS if present - use configured default dimensions
	dimensions := e.GetDefaultEmbeddingDimensions()
	similarityFunc := "cosine" // Default

	dimensions, similarityFunc = parseVectorOptions(parsed.optionsClause, dimensions, similarityFunc)

	// Add vector index. The schema entry is recorded regardless of the
	// vector master switch so SHOW INDEXES still reflects operator intent
	// and DROP INDEX has something to remove. The actual in-memory vector
	// space is only registered when vector search is enabled — otherwise
	// the operator explicitly turned vector indexing off and we must not
	// allocate or warm any vector backend on their behalf.
	entityType := storage.ConstraintEntityNode
	if parsed.isRelationship {
		entityType = storage.ConstraintEntityRelationship
	}
	create, err := e.admitIndexCreation(cypher, indexName, "VECTOR", label, parsed.properties, entityType)
	if err != nil {
		return nil, err
	}
	if !create {
		return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
	}
	if err := e.storage.GetSchema().AddVectorIndexForEntity(indexName, label, property, dimensions, similarityFunc, entityType); err != nil {
		return nil, err
	}

	// Relationship vector indexes are consumed by relationship vector procedures
	// directly from relationship properties and schema metadata.
	// registerVectorSpace is node-vector specific; keep relationship indexes out.
	if svc := e.search(); !parsed.isRelationship && (svc == nil || svc.VectorEnabled()) {
		e.afterSchemaCommit(ctx, func() {
			e.registerVectorSpace(indexName, label, property, dimensions, similarityFunc)
		})
	}

	return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, nil
}

package cypher

import (
	"context"
	"fmt"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

type parsedCreateConstraintContractDDL struct {
	name        string
	entityType  storage.ConstraintEntityType
	variable    string
	labelOrType string
	body        string
}

func parseConstraintContractForClause(forClause string) (entityType storage.ConstraintEntityType, variable string, labelOrType string, ok bool) {
	forClause = strings.TrimSpace(forClause)
	if forClause == "" {
		return "", "", "", false
	}

	if strings.Contains(forClause, "[") {
		bracketStart := strings.Index(forClause, "[")
		if bracketStart < 0 {
			return "", "", "", false
		}
		inside, rest, ok := extractBracketSection(forClause[bracketStart:])
		if !ok {
			return "", "", "", false
		}
		prefix := strings.TrimSpace(forClause[:bracketStart])
		suffix := strings.TrimSpace(rest)
		if !strings.Contains(prefix, "(") || !strings.Contains(suffix, "(") {
			return "", "", "", false
		}
		colon := strings.Index(inside, ":")
		if colon < 0 {
			return "", "", "", false
		}
		variable = normalizeIdentifierToken(strings.TrimSpace(inside[:colon]))
		labelOrType = normalizeIdentifierToken(strings.TrimSpace(inside[colon+1:]))
		if labelOrType == "" {
			return "", "", "", false
		}
		return storage.ConstraintEntityRelationship, variable, labelOrType, true
	}

	inside, rest, ok := extractParenSection(forClause)
	if !ok || strings.TrimSpace(rest) != "" {
		return "", "", "", false
	}
	colon := strings.Index(inside, ":")
	if colon < 0 {
		return "", "", "", false
	}
	variable = normalizeIdentifierToken(strings.TrimSpace(inside[:colon]))
	labelOrType = normalizeIdentifierToken(strings.TrimSpace(inside[colon+1:]))
	if labelOrType == "" {
		return "", "", "", false
	}
	return storage.ConstraintEntityNode, variable, labelOrType, true
}

func parseCurlySection(s string) (inside string, rest string, ok bool) {
	s = strings.TrimSpace(s)
	if s == "" || s[0] != '{' {
		return "", s, false
	}
	closing := findMatchingDelimiter(s, 0, '{', '}')
	if closing < 0 {
		return "", s, false
	}
	return s[1:closing], strings.TrimSpace(s[closing+1:]), true
}

func (e *StorageExecutor) parseCreateConstraintContractDDL(cypher string) (parsedCreateConstraintContractDDL, error) {
	q := strings.TrimSpace(cypher)
	if q == "" {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaEmptyStatement(), nil)
	}
	prefixPos := keywordIndexFrom(q, "CREATE CONSTRAINT", 0, defaultKeywordScanOpts())
	if prefixPos != 0 {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("prefix"), nil)
	}
	prefixEnd, ok := keywordSpanAt(q, 0, "CREATE CONSTRAINT")
	if !ok {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("prefix"), nil)
	}
	forPos := keywordIndexFrom(q, "FOR", prefixEnd, defaultKeywordScanOpts())
	if forPos < 0 {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaMissingKeyword("FOR"), nil)
	}
	forEnd, ok := keywordSpanAt(q, forPos, "FOR")
	if !ok {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("FOR"), nil)
	}
	reqPos := keywordIndexFrom(q, "REQUIRE", forEnd, defaultKeywordScanOpts())
	if reqPos < 0 {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaMissingKeyword("REQUIRE"), nil)
	}
	reqEnd, ok := keywordSpanAt(q, reqPos, "REQUIRE")
	if !ok {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaInvalidKeyword("REQUIRE"), nil)
	}

	name, err := parseOptionalDDLName(q[prefixEnd:forPos])
	if err != nil {
		return parsedCreateConstraintContractDDL{}, err
	}

	entityType, variable, labelOrType, ok := parseConstraintContractForClause(q[forEnd:reqPos])
	if !ok {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaInvalidPattern("FOR"), nil)
	}

	body, tail, ok := parseCurlySection(q[reqEnd:])
	if !ok || tail != "" {
		return parsedCreateConstraintContractDDL{}, localizedError(localization.CypherSchemaInvalidClause("REQUIRE block"), nil)
	}

	if name == "" {
		name = fmt.Sprintf("constraint_%s_contract", labelOrType)
	}
	return parsedCreateConstraintContractDDL{
		name:        name,
		entityType:  entityType,
		variable:    variable,
		labelOrType: labelOrType,
		body:        body,
	}, nil
}

func (e *StorageExecutor) executeCreateConstraintContract(ctx context.Context, cypher string, ifNotExists bool) (*ExecuteResult, bool, error) {
	parsed, err := e.parseCreateConstraintContractDDL(cypher)
	if err != nil {
		return nil, false, nil
	}
	return e.createConstraintContractForTarget(ctx, cypher, parsed.name, parsed.entityType, parsed.variable, parsed.labelOrType, parsed.body, ifNotExists)
}

func (e *StorageExecutor) createConstraintContractForTarget(ctx context.Context, definition, name string, entityType storage.ConstraintEntityType, variable, labelOrType, body string, ifNotExists bool) (*ExecuteResult, bool, error) {
	entriesRaw, err := splitConstraintContractEntries(body)
	if err != nil {
		return nil, true, err
	}
	if len(entriesRaw) == 0 {
		return nil, true, localizedError(localization.CypherSchemaContractEntryRequired(), nil)
	}

	contract := storage.ConstraintContract{
		Name:              name,
		TargetEntityType:  string(entityType),
		TargetLabelOrType: labelOrType,
		Definition:        strings.TrimSpace(definition),
		Entries:           make([]storage.ConstraintContractEntry, 0, len(entriesRaw)),
	}
	compiledConstraints := make([]storage.Constraint, 0)
	compiledTypes := make([]storage.PropertyTypeConstraint, 0)

	for idx, rawEntry := range entriesRaw {
		entry, compiledConstraint, compiledType, err := e.parseConstraintContractEntry(rawEntry, variable, entityType, labelOrType, name, idx)
		if err != nil {
			return nil, true, err
		}
		contract.Entries = append(contract.Entries, entry)
		if compiledConstraint != nil {
			compiledConstraints = append(compiledConstraints, *compiledConstraint)
		}
		if compiledType != nil {
			compiledTypes = append(compiledTypes, *compiledType)
		}
	}

	for _, constraint := range compiledConstraints {
		if err := storage.ValidateConstraintOnCreationForEngineWithContext(ctx, e.storage, constraint); err != nil {
			return nil, true, err
		}
	}
	for _, constraint := range compiledTypes {
		if err := storage.ValidatePropertyTypeConstraintOnCreationForEngineWithContext(ctx, e.storage, constraint); err != nil {
			return nil, true, err
		}
	}
	if err := storage.ValidateConstraintContractOnCreationForEngineWithContext(ctx, e.storage, contract); err != nil {
		return nil, true, err
	}
	schema := e.storage.GetSchema()
	newTemporal := make([]storage.Constraint, 0)
	newNames := make([]string, 0, len(compiledConstraints))
	for _, constraint := range compiledConstraints {
		if schema.HasConstraintNamed(constraint.Name) {
			continue
		}
		newNames = append(newNames, constraint.Name)
		if constraint.Type == storage.ConstraintTemporal {
			newTemporal = append(newTemporal, constraint)
		}
	}
	if err := schema.AddConstraintContractBundle(contract, compiledConstraints, compiledTypes, ifNotExists); err != nil {
		return nil, true, err
	}
	// See addSchemaConstraint: new temporal entries are authoritative on an
	// empty label (#1126).
	if err := storage.MarkNewTemporalConstraintsForEngineWithContext(ctx, e.storage, schema, newTemporal); err != nil {
		return nil, true, err
	}
	// Fill the equality indexes the contract's UNIQUE / NODE KEY entries own,
	// as a standalone constraint's DDL does (addSchemaConstraint): until an
	// owned index is filled, validation and seeks fall back to scanning the
	// label.
	for _, name := range newNames {
		if index, owned := schema.ConstraintPropertyIndex(name); owned {
			if err := e.backfillCompositeIndex(ctx, index.Name, index.Label, index.Properties); err != nil {
				return nil, true, err
			}
		}
	}
	// Like a standalone UNIQUE constraint, a contract's IS UNIQUE entries need
	// their value cache built and marked complete; without it every write to
	// the label falls back to scanning all of its nodes (#1120).
	if err := storage.RefreshUniqueConstraintValuesForConstraintsForEngineWithContext(ctx, e.storage, schema, compiledConstraints); err != nil {
		return nil, true, err
	}

	return &ExecuteResult{Columns: []string{}, Rows: [][]interface{}{}}, true, nil
}

func splitConstraintContractEntries(body string) ([]string, error) {
	entries := make([]string, 0)
	var current strings.Builder
	braceDepth := 0
	bracketDepth := 0
	parenDepth := 0

	flush := func() {
		entry := strings.TrimSpace(current.String())
		if entry != "" {
			entries = append(entries, entry)
		}
		current.Reset()
	}

	for index := 0; index < len(body); index++ {
		if end, skipped := skipCypherLexicalToken(body, index); skipped {
			current.WriteString(body[index:end])
			index = end - 1
			continue
		}
		ch := body[index]
		switch {
		case ch == '{':
			braceDepth++
			current.WriteByte(ch)
		case ch == '}':
			if braceDepth == 0 {
				return nil, localizedError(localization.CypherSchemaMalformedRequireBlock(), nil)
			}
			braceDepth--
			current.WriteByte(ch)
		case ch == '[':
			bracketDepth++
			current.WriteByte(ch)
		case ch == ']':
			if bracketDepth > 0 {
				bracketDepth--
			}
			current.WriteByte(ch)
		case ch == '(':
			parenDepth++
			current.WriteByte(ch)
		case ch == ')':
			if parenDepth > 0 {
				parenDepth--
			}
			current.WriteByte(ch)
		case ch == '\n' || ch == ';':
			if braceDepth == 0 && bracketDepth == 0 && parenDepth == 0 {
				flush()
				continue
			}
			current.WriteByte(ch)
		default:
			current.WriteByte(ch)
		}
	}
	if braceDepth != 0 || bracketDepth != 0 || parenDepth != 0 {
		return nil, localizedError(localization.CypherSchemaMalformedRequireBlock(), nil)
	}
	flush()
	return entries, nil
}

func isNestedConstraintContractEntry(entryText string) bool {
	trimmed := strings.TrimSpace(entryText)
	if !matchKeywordAt(trimmed, 0, "FOR") {
		return false
	}
	return hasKeywordFollowedByBrace(trimmed, "REQUIRE")
}

func nestedConstraintContractEntryError(entryText string) error {
	return localizedError(localization.CypherSchemaNestedContractEntryUnsupported(strings.TrimSpace(entryText)), nil)
}

func (e *StorageExecutor) parseConstraintContractEntry(rawEntry, variable string, entityType storage.ConstraintEntityType, labelOrType, contractName string, index int) (storage.ConstraintContractEntry, *storage.Constraint, *storage.PropertyTypeConstraint, error) {
	entryText := strings.TrimSpace(rawEntry)
	if isNestedConstraintContractEntry(entryText) {
		return storage.ConstraintContractEntry{}, nil, nil, nestedConstraintContractEntryError(entryText)
	}

	entryName := storage.ConstraintContractEntryName(contractName, index)
	if compiledConstraint, contractEntry, ok, err := e.parseConstraintContractPrimitive(entryText, variable, entityType, labelOrType, entryName); ok || err != nil {
		return contractEntry, compiledConstraint, nil, err
	}
	if compiledType, contractEntry, ok, err := e.parseConstraintContractPropertyType(entryText, variable, entityType, labelOrType, entryName); ok || err != nil {
		return contractEntry, nil, compiledType, err
	}

	kind := storage.ConstraintContractKindBooleanNode
	if entityType == storage.ConstraintEntityRelationship {
		kind = storage.ConstraintContractKindBooleanRelationship
	}
	return storage.ConstraintContractEntry{Kind: kind, Expression: entryText}, nil, nil, nil
}

func (e *StorageExecutor) parseConstraintContractPrimitive(entryText, variable string, entityType storage.ConstraintEntityType, labelOrType, entryName string) (*storage.Constraint, storage.ConstraintContractEntry, bool, error) {
	if kind, property, ok := parseConstraintPredicate(entryText); ok {
		if kind == "unique" {
			constraint := &storage.Constraint{Name: entryName, Type: storage.ConstraintUnique, EntityType: entityType, Label: labelOrType, Properties: []string{property}}
			primitiveKind := storage.ConstraintContractKindPrimitiveNode
			if entityType == storage.ConstraintEntityRelationship {
				primitiveKind = storage.ConstraintContractKindPrimitiveRelationship
			}
			return constraint, storage.ConstraintContractEntry{Kind: primitiveKind, PrimitiveType: string(storage.ConstraintUnique), Property: property, Properties: []string{property}, Expression: entryText}, true, nil
		}
		if kind == "exists" {
			constraint := &storage.Constraint{Name: entryName, Type: storage.ConstraintExists, EntityType: entityType, Label: labelOrType, Properties: []string{property}}
			primitiveKind := storage.ConstraintContractKindPrimitiveNode
			if entityType == storage.ConstraintEntityRelationship {
				primitiveKind = storage.ConstraintContractKindPrimitiveRelationship
			}
			return constraint, storage.ConstraintContractEntry{Kind: primitiveKind, PrimitiveType: string(storage.ConstraintExists), Property: property, Properties: []string{property}, Expression: entryText}, true, nil
		}
	}

	if entityType == storage.ConstraintEntityNode {
		if properties, ok := e.parseNodeKeyPropertyList(entryText); ok {
			if len(properties) == 0 {
				return nil, storage.ConstraintContractEntry{}, true, localizedError(localization.CypherSchemaConstraintPropertiesRequired("NODE KEY"), nil)
			}
			constraint := &storage.Constraint{Name: entryName, Type: storage.ConstraintNodeKey, EntityType: entityType, Label: labelOrType, Properties: properties}
			return constraint, storage.ConstraintContractEntry{Kind: storage.ConstraintContractKindPrimitiveNode, PrimitiveType: string(storage.ConstraintNodeKey), Properties: properties, Expression: entryText}, true, nil
		}
		if properties, ok := e.parseTemporalConstraintPredicate(entryText); ok {
			if len(properties) < 3 {
				return nil, storage.ConstraintContractEntry{}, true, localizedError(localization.CypherSchemaTemporalNodeArityRequired(), nil)
			}
			constraint := &storage.Constraint{Name: entryName, Type: storage.ConstraintTemporal, EntityType: entityType, Label: labelOrType, Properties: properties}
			return constraint, storage.ConstraintContractEntry{Kind: storage.ConstraintContractKindPrimitiveNode, PrimitiveType: string(storage.ConstraintTemporal), Properties: properties, Expression: entryText}, true, nil
		}
	}

	if entityType == storage.ConstraintEntityRelationship {
		inside, rest, ok := extractParenSection(strings.TrimSpace(entryText))
		if ok {
			rest = strings.TrimSpace(rest)
			if idx := keywordIndexFrom(rest, "IS RELATIONSHIP KEY", 0, defaultKeywordScanOpts()); idx == 0 {
				end, spanOK := keywordSpanAt(rest, 0, "IS RELATIONSHIP KEY")
				if spanOK && strings.TrimSpace(rest[end:]) == "" {
					properties := e.parseConstraintProperties(inside)
					if len(properties) == 0 {
						return nil, storage.ConstraintContractEntry{}, true, localizedError(localization.CypherSchemaConstraintPropertiesRequired("RELATIONSHIP KEY"), nil)
					}
					constraint := &storage.Constraint{Name: entryName, Type: storage.ConstraintRelationshipKey, EntityType: entityType, Label: labelOrType, Properties: properties}
					return constraint, storage.ConstraintContractEntry{Kind: storage.ConstraintContractKindPrimitiveRelationship, PrimitiveType: string(storage.ConstraintRelationshipKey), Properties: properties, Expression: entryText}, true, nil
				}
			}
		}
	}

	return nil, storage.ConstraintContractEntry{}, false, nil
}

func (e *StorageExecutor) parseConstraintContractPropertyType(entryText, variable string, entityType storage.ConstraintEntityType, labelOrType, entryName string) (*storage.PropertyTypeConstraint, storage.ConstraintContractEntry, bool, error) {
	property, typeName, ok := parseConstraintTypePredicate(entryText)
	if !ok {
		return nil, storage.ConstraintContractEntry{}, false, nil
	}
	expectedType, err := parsePropertyType(typeName)
	if err != nil {
		return nil, storage.ConstraintContractEntry{}, true, err
	}
	kind := storage.ConstraintContractKindPrimitiveNode
	if entityType == storage.ConstraintEntityRelationship {
		kind = storage.ConstraintContractKindPrimitiveRelationship
	}
	constraint := &storage.PropertyTypeConstraint{Name: entryName, EntityType: entityType, Label: labelOrType, Property: property, ExpectedType: expectedType}
	return constraint, storage.ConstraintContractEntry{Kind: kind, PrimitiveType: string(storage.ConstraintPropertyType), Property: property, Properties: []string{property}, ExpectedType: string(expectedType), Expression: entryText}, true, nil
}

package cypher

import (
	"context"

	"github.com/orneryd/nornicdb/pkg/storage"
)

func isOrdinarySchemaDDL(query string) bool {
	for _, command := range []string{"INDEX", "RANGE INDEX", "TEXT INDEX", "POINT INDEX", "VECTOR INDEX", "FULLTEXT INDEX", "LOOKUP INDEX", "CONSTRAINT"} {
		if startsWithKeywords(query, "CREATE", command) {
			return true
		}
	}
	return startsWithKeywords(query, "DROP", "INDEX") || startsWithKeywords(query, "DROP", "CONSTRAINT")
}

func (e *StorageExecutor) prepareSchemaTransaction(ctx context.Context) error {
	wrapper, ok := e.getStorage(ctx).(*transactionStorageWrapper)
	if !ok {
		return nil
	}
	if err := wrapper.tx.SetNamespace(e.currentDatabaseName()); err != nil {
		return err
	}
	view, err := wrapper.tx.Schema()
	if err != nil {
		return err
	}
	wrapper.schema = view
	return nil
}

func (e *StorageExecutor) afterSchemaCommit(ctx context.Context, action func()) {
	if wrapper, ok := e.getStorage(ctx).(*transactionStorageWrapper); ok && wrapper.schema != nil {
		wrapper.schemaCommitActions = append(wrapper.schemaCommitActions, action)
		return
	}
	action()
}

func (e *StorageExecutor) mutateSchema(ctx context.Context, mutation func(*storage.SchemaManager) error) error {
	if err := e.prepareSchemaTransaction(ctx); err != nil {
		return err
	}
	schema := e.getStorage(ctx).GetSchema()
	release := schema.LockSchemaMutation()
	defer release()
	if err := mutation(schema); err != nil {
		return err
	}
	if wrapper, ok := e.getStorage(ctx).(*transactionStorageWrapper); ok {
		return wrapper.tx.StageSchemaChanges()
	}
	return nil
}

package cypher

import (
	"context"
	"fmt"
	"maps"
	"strings"

	"github.com/orneryd/nornicdb/pkg/localization"
)

// semanticBodyScope is the binding value of a CALL/scalar body. entry records
// ordinary body bindings; carried inputs remain readable after WITH. retained
// is the scoped CALL readability fact, separate from current wildcard columns.
// implicit tags #907 fallback imports: readable, but never declarations that
// can conflict with a name introduced by this body. Every declaration producer
// uses declare; consumers must not reconstruct provenance from row keys.
type semanticBodyScope struct {
	entry       typeScope
	carried     typeScope
	retained    typeScope
	original    typeScope
	implicit    typeScope
	caller      typeScope
	headerReads typeScope
	scalar      bool
	bare        bool
	entered     bool
	projected   *semanticBodyScope
	iteration   *semanticBodyScope
}

// A CALL wildcard requires a current body binding. Availability of an unread
// scoped import does not itself supply a wildcard column.
func returnStarScopeError(wildcard bool, columns int) error {
	if !wildcard || columns != 0 {
		return nil
	}
	return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "NoVariablesInScope", localization.CypherMatchingReturnStarNoVariables())
}

func (body *semanticBodyScope) clone(entry typeScope) *semanticBodyScope {
	if body == nil {
		return nil
	}
	return &semanticBodyScope{entry: maps.Clone(entry), carried: maps.Clone(body.carried), retained: maps.Clone(body.retained), original: maps.Clone(body.original), implicit: maps.Clone(body.implicit), caller: maps.Clone(body.caller), headerReads: maps.Clone(body.headerReads), scalar: body.scalar, bare: body.bare, entered: body.entered}
}

// reference records an explicit input read in this body's ordinary scope.
// Readability alone does not contribute columns. Nested scalar reads belong to
// the scalar; #907 weak inputs keep their fallback/declaration contract.
func (body *semanticBodyScope) reference(name string, local typeScope) {
	if body == nil || body.scalar || body.bare {
		return
	}
	if _, current := local[name]; current {
		return
	}
	if operand, imported := body.carried[name]; imported {
		local[name] = operand
	}
}

// A lexical update body adds its iterator without changing the enclosing CALL
// projection or import provenance. Both canonical binding and execution use it.
func (body *semanticBodyScope) localChild(name string) *semanticBodyScope {
	child := body.clone(body.entry)
	if child != nil {
		child.declare(name, child.entry, nil, nil, false)
		child.entry[name] = staticOperand{}
	}
	return child
}

// projection is the current clause membership. Carried scoped imports remain
// readable across WITH but enter this membership only through a direct read.
func (body *semanticBodyScope) projection(local typeScope) typeScope {
	if body != nil && body.scalar {
		// Scalar bodies carry their enclosing inputs through ordinary WITH.
		// Their wildcard expands that existing scope, regardless of row count.
		return body.visible(local)
	}
	return local
}

// A legacy importing WITH sees the caller's actual projection facts, including
// scoped retained imports, without importing scalar-only readable ancestors.
func (body *semanticBodyScope) legacyCurrent(local typeScope) typeScope {
	return local
}

func (body *semanticBodyScope) visible(local typeScope) typeScope {
	if body == nil {
		return local
	}
	return scopeVisibleTypes(local, body.carried)
}

func (body *semanticBodyScope) strong(local typeScope) typeScope {
	visible := body.visible(local)
	if body == nil || len(body.implicit) == 0 {
		return visible
	}
	strong := maps.Clone(visible)
	for name := range body.implicit {
		delete(strong, name)
	}
	return strong
}

// A scalar expression treats its enclosing values as constants. A CALL is a
// query body: a persistent import remains readable, but is not an implicit
// grouping key in an aggregate projection.
func (body *semanticBodyScope) aggregateConstants() typeScope {
	if body != nil && body.scalar {
		return body.visible(nil)
	}
	return nil
}

// ORDER BY can read a retained scoped import after DISTINCT without making
// that import an implicit grouping key in the aggregate projection itself.
func (body *semanticBodyScope) orderConstants() typeScope {
	if body == nil {
		return nil
	}
	return scopeVisibleTypes(body.aggregateConstants(), body.retained)
}

// declare is the single transition from weak input to a body binding. A prior
// read still requires the outer input at runtime, but cannot make it strong.
// An unscoped CALL declaration is a new local; if WITH drops that local, its
// same-name weak input must not become readable again.
func (body *semanticBodyScope) declare(name string, local typeScope, proof *semanticDependencyScope, result *semanticQueryScope, replaceInput bool) {
	if body != nil {
		if _, weak := body.implicit[name]; weak {
			delete(body.implicit, name)
			delete(body.carried, name)
			delete(body.retained, name)
			delete(body.original, name)
			if replaceInput {
				delete(local, name)
			}

		}
	}
	if proof != nil {
		delete(proof.active, name)
	}
}

// scalarChild preserves strong/weak identity across expression boundaries.
// Its carried ancestors retain their existing scalar wildcard membership.
func (body *semanticBodyScope) scalarChild(visible typeScope) *semanticBodyScope {
	child := &semanticBodyScope{entry: typeScope{}, carried: maps.Clone(visible), original: maps.Clone(visible), scalar: true}
	if body != nil {
		child.implicit = make(typeScope)
		for name, operand := range body.implicit {
			if _, exists := visible[name]; exists {
				child.implicit[name] = operand
			}
		}
	}
	return child
}

func (body *semanticBodyScope) pattern(name string, kind matchBindingKind, local typeScope, proof *semanticDependencyScope, result *semanticQueryScope) {
	if body != nil {
		if _, weak := body.implicit[name]; weak {
			body.declare(name, local, proof, result, true)
			return
		}
	}
	proof.read(name)
}

func (body *semanticBodyScope) runtimeCurrent(names []string) typeScope {
	if body != nil {
		return maps.Clone(body.entry)
	}
	current := semanticRuntimeInput(names)
	if body != nil && body.scalar {
		for name := range body.carried {
			if _, local := body.entry[name]; !local {
				delete(current, name)
			}
		}
	}
	return current
}

func withSemanticProjectedBody(ctx context.Context) context.Context {
	if body := semanticBodyFromContext(ctx); body != nil && body.projected != nil {
		return withSemanticBodyClause(ctx, body.projected)
	}
	return ctx
}

func (body *semanticBodyScope) project(ctx context.Context, before, after typeScope, clause string) {
	if body == nil {
		return
	}
	visible := body.visible(before)
	carried := maps.Clone(after)
	keyword := "WITH"
	if startsWithKeywordFold(strings.TrimSpace(clause), "RETURN") {
		keyword = "RETURN"
	}
	projection, _ := cutDistinct(projectionSemanticBody(clause, keyword))
	var empty typeScope
	if len(body.original) > 0 && pipelineProjectionHasOnlyAggregates(returnProjectionPlanFor(ctx, "RETURN "+projection).projections) {
		empty = maps.Clone(carried)
		carrySubqueryImports(empty, nil, body.original)
	}
	carrySubqueryImports(carried, visible, body.original)
	for name, operand := range empty {
		carried[name] = joinedOperand(carried[name], operand)
	}
	for name := range body.carried {
		if operand, exists := carried[name]; exists {
			body.carried[name] = operand
			if _, retained := body.retained[name]; retained {
				body.retained[name] = operand
			}
		}
	}
}

func (body *semanticBodyScope) projectionTail(ctx context.Context, merged, projected typeScope, clause string) *semanticBodyScope {
	if body == nil {
		return nil
	}
	tail := body.clone(merged)
	projected.forEachProjectedBinding(ctx, clause, func(name, expression, text string, inherited bool) {
		if !inherited && projectedSourceVariable(expression) != name {
			tail.declare(name, projected, nil, nil, false)
		}
	})
	tail.project(ctx, merged, projected, clause)
	body.projected = tail
	return tail
}

// callBodyScope is the shared import-form constructor for typed validation and
// the canonical statement binder. Neither consumer invents another scope from
// projected columns or runtime row values.
func callBodyScope(names []string, scoped bool, local typeScope, parent *semanticBodyScope, scalarParent bool) (typeScope, *semanticBodyScope, error) {
	outer := parent.visible(local)
	header := outer
	if scalarParent {
		header = local
	}
	imports := make(typeScope)
	if scoped {
		for _, name := range names {
			operand, exists := outer[name]
			if !exists {
				return nil, nil, createUndefinedVariableError(name)
			}
			imports[name] = operand
		}
		if names == nil {
			maps.Copy(imports, header)
		}
	} else {
		// NornicDB extension, diverging from Neo4j: a bare CALL may read
		// outer variables without an import clause. These inputs are weak;
		// a new local declaration shadows one and ordinary WITH can drop it.
		maps.Copy(imports, outer)
	}
	initial := maps.Clone(imports)
	if scoped {
		initial = typeScope{}
	}
	body := &semanticBodyScope{entry: initial, carried: maps.Clone(imports), original: maps.Clone(imports), caller: maps.Clone(parent.legacyCurrent(local)), bare: !scoped}
	if !scoped {
		body.implicit = maps.Clone(imports)
	} else {
		body.retained = maps.Clone(imports)
	}
	return imports, body, nil
}

// branchEntry is the per-import-form transition shared by every UNION branch.
// A leading importing WITH creates ordinary locals; only unselected caller
// locals retain #907 weak fallback. Scalar-only ancestors require a name.
func (body *semanticBodyScope) branchEntry(ctx context.Context, clauses []pipelineClause, branchIndex int, initial typeScope) (typeScope, error) {
	if body == nil || body.entered {
		return initial, nil
	}
	// Clause snapshots already passed this transition. Recompiling a fragment
	// must not reinterpret a later UNION branch as a new first branch.
	body.entered = true
	if !body.bare || len(clauses) == 0 || clauses[0].kind != pipelineClauseWith {
		return initial, nil
	}
	imports, importing := callWithImports(ctx, clauses[0].text, body.caller, initial)
	if !importing {
		return initial, nil
	}
	body.headerReads = maps.Clone(imports)
	projection, tail := projectionSemanticBodyAndTail(clauses[0].text, "WITH")
	if branchIndex == 0 && (strings.TrimSpace(tail) != "" || topLevelKeywordIndex(projection, "AS") >= 0) {
		return nil, newSemanticError("Neo.ClientError.Statement.SyntaxError", "InvalidVariableImport", "Importing WITH must contain only simple references to outside variables")
	}
	for name := range body.carried {
		_, local := body.caller[name]
		_, selected := imports[name]
		if !local || selected {
			delete(body.carried, name)
			delete(body.implicit, name)
		}
	}
	return imports, nil
}

type semanticBodyScopeKey struct{}
type semanticBodyInputKey struct{}

func semanticBodyFromContext(ctx context.Context) *semanticBodyScope {
	body, _ := ctx.Value(semanticBodyScopeKey{}).(*semanticBodyScope)
	return body
}

// Runtime consumes the immutable clause scope produced by the owner. Values
// stay request-local; neither the scope nor any cache stores a row value.
func withSemanticBodyClause(ctx context.Context, body *semanticBodyScope) context.Context {
	if body == nil {
		return ctx
	}
	ctx = context.WithValue(ctx, semanticBodyScopeKey{}, body)
	input, supplied := ctx.Value(semanticBodyInputKey{}).(pipelineRow)
	if !supplied {
		return ctx
	}
	carried := make(pipelineRow, len(body.carried))
	for name := range body.carried {
		if value, exists := input[name]; exists {
			carried[name] = value
		}
	}
	return withPipelineImports(ctx, carried)
}

// These transitions are the only writers of the body's current membership.
func (body *semanticBodyScope) bindCurrent(name string, operand staticOperand) {
	body.entry[name] = operand
}
func (body *semanticBodyScope) replaceCurrent(current typeScope) { body.entry = maps.Clone(current) }

// A nested export that preserves binding identity is a read/pass-through,
// rather than a declaration shadowing the caller's same-name weak candidate.
func (body *semanticBodyScope) export(name string, local typeScope, proof *semanticDependencyScope, result *semanticQueryScope, unchanged bool) {
	if !unchanged {
		body.declare(name, local, proof, result, false)
	}
}

// admitExports is shared by typed enrichment and bound identity construction.
// A strong caller binding may only be exported unchanged by every UNION branch.
func (body *semanticBodyScope) admitExports(local typeScope, columns []string, unchanged func(string) bool) error {
	strong := body.strong(local)
	for _, name := range columns {
		if _, bound := strong[name]; bound && !unchanged(name) {
			return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", localization.CypherCoreVariableDeclaredInOuterScope(name))
		}
	}
	return nil
}

// admitDeclaration is the constructor's declaration legality transition.
// Type checking may reject an operand's kind, never admit a new name itself.
func (body *semanticBodyScope) admitDeclaration(name string, form string) error {
	if body == nil {
		return nil
	}
	_, strong := body.strong(body.entry)[name]
	_, ancestor := body.strong(nil)[name]
	if body.scalar && ancestor {
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", localization.CypherCoreVariableDeclaredInOuterScope(name))
	}
	if form == "FOR" && body.readable(name, body.entry) || form == "LET" && strong {
		return newSemanticError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", "variable "+name+" is already declared")
	}
	if form == "YIELD" && strong {
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", localization.CypherCoreProcedureOutputShadowsVariable(name))
	}
	return nil
}

// Pattern declarations use the same strong/weak admission input as every
// other declaration form. Entity-kind compatibility is a later operand rule.
func (body *semanticBodyScope) admitPatternDeclarations(ctx context.Context, clause pipelineClause) error {
	strong := body.strong(body.entry)
	pattern := strings.TrimSpace(clause.text)
	for _, keyword := range []string{"OPTIONAL MATCH", "MATCH"} {
		if startsWithKeywordFold(pattern, keyword) {
			pattern = strings.TrimSpace(pattern[len(keyword):])
			break
		}
	}
	pattern = matchPatternStructure(pattern)
	if mergePatternUsesParameterPredicate(pattern) {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidParameterUse",
			"MATCH pattern predicates must use a property map, not a parameter map",
		)
	}
	if invalidRelationshipPattern(pattern) {
		return newSemanticError(
			"Neo.ClientError.Statement.SyntaxError",
			"InvalidRelationshipPattern",
			"invalid variable-length relationship pattern",
		)
	}

	nodes, relationships := quantifiedGroupVariables(pattern)
	for _, names := range []map[string]struct{}{nodes, relationships} {
		for name := range names {
			if _, bound := strong[name]; bound {
				return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", localization.CypherMatchingQuantifiedPathVariableBound(name))
			}
		}
	}
	for _, part := range splitTopLevelComma(pattern) {
		path := extractPathAssignmentVariable(strings.TrimSpace(part))
		if path == "" {
			continue
		}
		if _, bound := strong[path]; bound {
			return newSemanticError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", fmt.Sprintf("path variable %s is already bound", path))
		}
		entity := part
		if equals := strings.Index(part, "="); equals >= 0 {
			entity = part[equals+1:]
		}
		for _, name := range append(extractNodeVariables(entity), extractRelationshipVariables(entity)...) {
			if normalizeProjectionColumnName(name) == path {
				return newSemanticError("Neo.ClientError.Statement.SyntaxError", "VariableAlreadyBound", fmt.Sprintf("path variable %s is already bound", path))
			}
		}
	}
	return nil
}

// SET clause helpers for NornicDB Cypher.
//
// This file contains helper functions for processing SET clauses in Cypher queries.
// These functions handle property assignments, expression evaluation, and string
// operations used during SET operations.
//
// # SET Clause Syntax
//
// SET operations modify node and relationship properties:
//
//	SET n.name = 'Alice'           - Single property
//	SET n.name = 'Alice', n.age = 30  - Multiple properties
//	SET n += {name: 'Alice'}       - Map merge
//	SET n:Label                    - Add label
//
// # Expression Evaluation
//
// SET clauses can use various expressions:
//
//	SET n.id = randomUUID()                    - Function call
//	SET n.ts = timestamp()                     - Built-in function
//	SET n.name = 'prefix-' + toString(n.id)   - String concatenation
//	SET n.list = [1, 2, 3]                     - Array literal
//
// # ELI12
//
// Think of SET like filling out a form:
//
//	SET n.name = 'Alice'
//
// You're writing "Alice" in the "name" box on the form. These helper
// functions make sure the value goes in the right format:
//   - Strings stay as strings: 'hello' → "hello"
//   - Numbers become numbers: 42 → 42
//   - Arrays become lists: [1,2] → [1, 2]
//   - Functions run and give results: timestamp() → 1234567890
//
// # Neo4j Compatibility
//
// These helpers ensure SET clauses work identically to Neo4j.

package cypher

import (
	"context"
	"crypto/rand"
	"fmt"
	"strings"

	"github.com/orneryd/nornicdb/pkg/storage"
)

// applySetMapMergeToNode applies SET n += <expr>: every key of the map (or of
// the node / relationship) is written, and a null value removes the key.
// Row bindings from UNWIND / WITH are visible in the value scope.
// Non-map values are an error (setSourceMap).
func (e *StorageExecutor) applySetMapMergeToNode(ctx context.Context, node *storage.Node, varName string, rightExpr string, nodes map[string]*storage.Node, rels map[string]*storage.Edge, writes *setWrites) error {
	if node == nil {
		return nil
	}
	if err := requireSetParameter(ctx, rightExpr); err != nil {
		return err
	}
	props, err := e.setSourceMap(ctx, rightExpr, "+=", nodes, rels)
	if err != nil {
		return err
	}
	writes.mapEntries(node.Properties, props, false)
	for k, v := range props {
		setNodeProperty(node, k, v)
	}
	return nil
}

// setNodeProperty sets a property on a node.
//
// setNodeProperty sets a property on a node.
//
// The "embedding" property is treated like any other property — it is stored in
// node.Properties and indexed normally. Managed embeddings (from WITH EMBEDDING
// or the background worker) are stored separately in node.ChunkEmbeddings via
// ApplyManagedEmbedding; storage keeps or invalidates them when the node is
// updated, by whether the change touches the embedding source (#963).
//
// # Parameters
//
//   - node: The node to update
//   - propName: The property name
//   - value: The value to set
func setNodeProperty(node *storage.Node, propName string, value interface{}) {
	if node.Properties == nil {
		node.Properties = make(map[string]interface{})
	}
	value = copyStoredPropertyValue(value)
	if value == nil {
		delete(node.Properties, propName)
		return
	}
	node.Properties[propName] = value
}

func setRelationshipProperty(relationship *storage.Edge, propName string, value interface{}) {
	if relationship.Properties == nil {
		relationship.Properties = make(map[string]interface{})
	}
	value = copyStoredPropertyValue(value)
	if value == nil {
		delete(relationship.Properties, propName)
		return
	}
	relationship.Properties[propName] = value
}

func setPropertyMap(properties map[string]interface{}) map[string]interface{} {
	result := make(map[string]interface{}, len(properties))
	for key, value := range properties {
		if value != nil {
			result[key] = copyStoredPropertyValue(value)
		}
	}
	return result
}

// copyStoredPropertyValue gives a writer ownership of a generic property list.
// Its elements were already normalized and validated by storablePropertyValue;
// storage copies typed slices at its own boundary, as before.
func copyStoredPropertyValue(value interface{}) interface{} {
	if list, ok := value.([]interface{}); ok {
		copied := make([]interface{}, len(list))
		copy(copied, list)
		return copied
	}
	return value
}

// propertyMapForSetValue implements Cypher's entity-as-property-map semantics
// for SET target = source while keeping general map coercion strict elsewhere.
func propertyMapForSetValue(value interface{}) (map[string]interface{}, bool) {
	switch entity := value.(type) {
	case *storage.Node:
		if entity == nil {
			return nil, false
		}
		return entity.Properties, true
	case *storage.Edge:
		if entity == nil {
			return nil, false
		}
		return entity.Properties, true
	default:
		return toStringAnyMap(value)
	}
}

func parseSetAssignmentTarget(target string) (variable string, property string, hasProperty bool) {
	target = strings.TrimSpace(target)
	if base, prop, ok := splitPostfixPropertyAccess(target); ok {
		for {
			inner, wrapped := stripEnclosingExpressionParentheses(base)
			if !wrapped {
				break
			}
			base = strings.TrimSpace(inner)
		}
		return strings.TrimSpace(base), prop, true
	}
	for {
		inner, wrapped := stripEnclosingExpressionParentheses(target)
		if !wrapped {
			break
		}
		target = strings.TrimSpace(inner)
	}
	return target, "", false
}

// splitSetAssignments splits a SET clause into individual assignments,
// respecting quotes and nesting in (), [] and {} (function calls, list literals
// such as embeddings, and map literals).
//
// # Parameters
//
//   - setClause: The SET clause string (without "SET" keyword)
//
// # Returns
//
//   - Slice of individual assignments
//
// # Example
//
//	splitSetAssignments("n.name = 'Alice', n.age = 30")
//	// Returns: ["n.name = 'Alice'", "n.age = 30"]
//
//	splitSetAssignments("n.name = concat('a', 'b'), n.x = 1")
//	// Returns: ["n.name = concat('a', 'b')", "n.x = 1"]
//
//	splitSetAssignments("n.embedding = [0.1, 0.2], n.dim = 4")
//	// Returns: ["n.embedding = [0.1, 0.2]", "n.dim = 4"]
func splitSetAssignments(setClause string) []string {
	return splitTopLevelCommaKeepEmpty(setClause)
}

// hasConcatOperator checks if the expression has a + operator outside of quotes.
// This prevents infinite recursion when property values contain " + " in text.
//
// # Parameters
//
//   - expr: The expression to check
//
// # Returns
//
//   - true if + operator exists at top level
func (e *StorageExecutor) hasConcatOperator(expr string) bool {
	parenDepth := 0

	for i := 0; i < len(expr); i++ {
		if end, quoted := skipCypherLexicalToken(expr, i); quoted {
			i = end - 1
			continue
		}
		c := rune(expr[i])
		switch {
		case c == '(':
			parenDepth++
		case c == ')':
			parenDepth--
		case c == '+' && parenDepth == 0:
			// Check for space before and after (to avoid matching ++ or += etc)
			hasBefore := i > 0 && expr[i-1] == ' '
			hasAfter := i < len(expr)-1 && expr[i+1] == ' '
			if hasBefore && hasAfter {
				return true
			}
		}
	}
	return false
}

// splitFunctionArgs splits a function call's argument text at its top-level
// commas with the shared splitter (splitTopLevelComma): a comma inside
// quotes, a quoted name or a (), [] or {} group belongs to its argument, so
// a map literal with several keys is one argument. The arguments are
// trimmed; an empty last one is dropped.
func (e *StorageExecutor) splitFunctionArgs(args string) []string {
	return splitTopLevelComma(args)
}

// generateUUID generates a simple UUID-like string.
//
// Uses crypto/rand for cryptographically secure random bytes.
//
// # Returns
//
//   - A UUID-formatted string
func (e *StorageExecutor) generateUUID() string {
	// Use crypto/rand for proper UUID
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:])
}

// persistSetEntities stores the entities a SET clause wrote (applySetRuns)
// and counts what it wrote in stats (which may be nil): every route stores
// SET's writes this one way. An entity the clause left as it was isn't
// stored, though its writes count (Neo4j counts writes, not changes); a
// node whose labels changed is checked against the label policies first.
// On an error the entity is restored and the error is wrapped by its caller
// (wrap).
func (e *StorageExecutor) persistSetEntities(ctx context.Context, store storage.Engine, states []setEntityState, stats *QueryStats, wrap func(state setEntityState, err error) error) error {
	for index := range states {
		state := &states[index]
		if stats != nil {
			stats.PropertiesSet += state.written
		}
		if node := state.node; node != nil {
			labelsAdded := addedLabelCount(state.labels, node.Labels)
			if labelsAdded == 0 && changedPropertyCount(state.properties, node.Properties) == 0 {
				continue
			}
			restore := func() {
				node.Properties = state.properties
				node.Labels = state.labels
			}
			if labelsAdded > 0 {
				if err := validatePolicyOnLabelChange(store, node, state.labels); err != nil {
					restore()
					return err
				}
			}
			if stats != nil {
				stats.LabelsAdded += labelsAdded
			}
			if err := updateMutatedNode(ctx, store, node); err != nil {
				restore()
				return wrap(*state, err)
			}
			e.notifyNodeMutated(string(node.ID))
			continue
		}
		relationship := state.relationship
		if changedPropertyCount(state.properties, relationship.Properties) == 0 {
			continue
		}
		if err := updateMutatedEdge(store, relationship); err != nil {
			relationship.Properties = state.properties
			return wrap(*state, err)
		}
		e.notifyEdgeMutated(string(relationship.ID))
	}
	return nil
}

// setRun is a stretch of a SET clause: its consecutive assignments that
// name one variable (text). The per-entity appliers apply a stretch with
// Neo4j's runs inside it (setPropertyRun); stretches apply in order.
type setRun struct {
	variable string
	text     string
}

// appendSetClauseRuns appends the stretches of a SET body to runs (a
// caller's buffer), in order. Neo4j applies a SET clause's items in order, a
// run of property assignments to one variable at once (setPropertyRun):
// SET n.a = 1, m.b = n.a reads the new n.a, while SET n.a = 1, n.b = n.a
// reads the old one (#907). A chained SET clause (SET a SET b) starts new
// stretches. A stretch's text is a slice of the body. assignments, when not nil, are body's assignments already split
// (splitSetAssignments): they are used when body is one SET clause.
func appendSetClauseRuns(runs []setRun, body string, assignments []string) []setRun {
	for segment, next, ok := nextChainedSetClause(body, 0); ok; segment, next, ok = nextChainedSetClause(body, next) {
		open := false
		start, searchFrom := 0, 0
		items := assignments
		if items == nil || next < len(body) || segment != strings.TrimSpace(body) {
			items = splitSetAssignments(segment)
		}
		for _, assignment := range items {
			assignment = strings.TrimSpace(assignment)
			if assignment == "" {
				continue
			}
			at := searchFrom
			if found := strings.Index(segment[searchFrom:], assignment); found >= 0 {
				at = searchFrom + found
			}
			searchFrom = at + len(assignment)
			target, _, _, _ := splitSetAssignment(assignment)
			if open && runs[len(runs)-1].variable == target {
				runs[len(runs)-1].text = segment[start:searchFrom]
				continue
			}
			runs = append(runs, setRun{variable: target, text: assignment})
			start, open = at, true
		}
	}
	return runs
}

// setEntityState is an entity a SET clause wrote: its properties and
// labels before the clause, and the properties the clause wrote (setWrites).
type setEntityState struct {
	variable     string
	node         *storage.Node
	relationship *storage.Edge
	properties   map[string]interface{}
	labels       []string
	written      int
}

// applySetRuns applies a SET clause's runs (appendSetClauseRuns) in order to the
// nodes and relationships they name, and returns the entities written,
// first written first, appended to states (a caller's buffer). A run on a variable bound to null does nothing; a
// run on a variable that names no entity reports ok false. On an error,
// every entity is restored to its state before the clause.
func (e *StorageExecutor) applySetRuns(ctx context.Context, runs []setRun, nodes map[string]*storage.Node, rels map[string]*storage.Edge, isNull func(variable string) bool, states []setEntityState) ([]setEntityState, bool, error) {
	for _, run := range runs {
		node, relationship := nodes[run.variable], rels[run.variable]
		if node == nil && relationship == nil {
			if isNull(run.variable) {
				continue
			}
			restoreSetEntities(states)
			return nil, false, nil
		}
		target := -1
		for index := range states {
			if states[index].variable == run.variable {
				target = index
				break
			}
		}
		if target < 0 {
			state := setEntityState{variable: run.variable, node: node, relationship: relationship}
			if node != nil {
				state.properties = cloneStringAnyMap(node.Properties)
				state.labels = append([]string(nil), node.Labels...)
			} else {
				state.properties = cloneStringAnyMap(relationship.Properties)
			}
			states = append(states, state)
			target = len(states) - 1
		}
		var written int
		var err error
		if node != nil {
			written, err = e.applySetToNodeWithContext(ctx, node, run.variable, run.text, nodes, rels)
		} else {
			written, err = e.applySetToRelationshipWithContext(ctx, relationship, run.variable, run.text, nodes, rels)
		}
		states[target].written += written
		if err != nil {
			restoreSetEntities(states)
			return nil, true, err
		}
	}
	return states, true, nil
}

// restoreSetEntities puts the entities a SET clause wrote back as they were
// before it.
func restoreSetEntities(states []setEntityState) {
	for _, written := range states {
		if written.node != nil {
			written.node.Properties = written.properties
			written.node.Labels = written.labels
		} else {
			written.relationship.Properties = written.properties
		}
	}
}

package cypher

import (
	"context"
	"fmt"
	"strings"

	nornicerrors "github.com/orneryd/nornicdb/pkg/errors"
	"github.com/orneryd/nornicdb/pkg/localization"
)

func (e *StorageExecutor) validateStatementFraming(ctx context.Context, cypher string) error {
	multiple, unclosed := inspectOutsideStrings(cypher, ";")
	if unclosed >= 0 {
		return unclosedCommentError(cypher, unclosed, ModeNormal)
	}
	if multiple {
		statements := e.splitBySemicolon(cypher)
		return localizedStatusError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax",
			localization.CypherCommandRoutingMultipleStatements(len(statements)))
	}
	mode, body, conflict := statementExecutionModes(cypher)
	if mode != ModeNormal && queryGapEnd(body, 0) == len(body) {
		return emptyStatementError()
	}
	if conflict {
		return executionModeConflictError()
	}
	// Graph composition and declared UNION headers are admitted by compileBound.
	return nil
}

// Statement framing helpers: Neo4j 5 statement preamble (CYPHER … groups),
// the FINISH clause terminator, and the EXPLAIN/PROFILE exclusivity rule.

// cypherClauseStarts are the keywords that end a CYPHER preamble group and
// start the actual statement. Matched case-insensitively at a token boundary.
var cypherClauseStarts = [...]string{
	"MATCH", "CREATE", "MERGE", "DELETE", "DETACH", "CALL", "RETURN", "WITH",
	"UNWIND", "OPTIONAL", "DROP", "SHOW", "FOREACH", "LOAD", "EXPLAIN",
	"PROFILE", "ALTER", "USE", "BEGIN", "COMMIT", "ROLLBACK", "TERMINATE",
	"UNION", "CYPHER", "FINISH", "LET", "FILTER", "FOR", "WHEN",
}

// startsWithClauseKeyword reports whether a clause keyword, or a brace that
// opens a query part ({ RETURN 1 } UNION …), starts s.
func startsWithClauseKeyword(s string) bool {
	if strings.HasPrefix(s, "{") {
		return true
	}
	for _, keyword := range cypherClauseStarts {
		if matchKeywordAt(s, 0, keyword) {
			return true
		}
	}
	return false
}

// stripCypherPreamble removes leading CYPHER groups: the keyword CYPHER, an
// optional version number, and option tokens (ident, ident=value, or a quoted
// string) until a clause keyword starts the statement. Neo4j accepts any
// number of such groups (`CYPHER 5 runtime=slotted CYPHER RETURN 1`).
var cypherPreambleOptionValues = map[string]string{
	"runtime":                  "interpreted, legacy, parallel, pipelined, slotted",
	"planner":                  "cost, dp, idp",
	"expressionengine":         "compiled, interpreted, only_when_hot",
	"operatorengine":           "compiled, interpreted",
	"interpretedpipesfallback": "all, disabled, whitelisted_plans_only",
	"replan":                   "force, skip",
	"updatestrategy":           "default, eager",
	"connectcomponentsplanner": "greedy, idp",
	"eageranalyzer":            "ir, lp",
	"inferschemaparts":         "most_selective_label, off",
	"parallelruntimesupport":   "all, disabled",
	"debug":                    "ast, disableexistssubquerycaching, disablepropertycaching, generate_java_source, graphviz, inverse_cost, logcostcomparisons, logicalplan, logicalplanbuilder, mermaid, printcostcomparisons, querygraph, rawcardinalities, renderdistinctness, semanticstate, show_bytecode, show_java_source, tostring, verboseeagernessreasons, visualizepipelines, warnoncompilationerrors",
}

func validateCypherPreamble(query string) error {
	rest := strings.TrimSpace(query)
	restOffset := strings.Index(query, rest)
	argumentError := func(message string) error {
		return nornicerrors.MarkCompileTime(newSemanticError("Neo.ClientError.Statement.ArgumentError", "InvalidArgument", message))
	}
	consumeGap := func(index int) error {
		end, unclosed := readQueryGap(rest, index)
		if unclosed >= 0 {
			return unclosedCommentError(query, restOffset+unclosed, ModeNormal)
		}
		restOffset += end
		rest = rest[end:]
		return nil
	}
	var seenVersion string
	for rest != "" {
		if mode, inner := executionModePrefix(rest); mode != ModeNormal {
			restOffset += len(rest) - len(inner)
			rest = inner
			continue
		}
		if !matchKeywordAt(rest, 0, "CYPHER") {
			return nil
		}
		if err := consumeGap(len("CYPHER")); err != nil {
			return err
		}
		if len(rest) > 0 && rest[0] >= '0' && rest[0] <= '9' {
			end := 0
			for end < len(rest) && ((rest[end] >= '0' && rest[end] <= '9') || rest[end] == '.') {
				end++
			}
			version := rest[:end]
			if version != "5" && version != "25" {
				return argumentError(fmt.Sprintf("%s is not a valid option for cypher version. Valid options are: 5, 25", version))
			}
			if seenVersion != "" && seenVersion != version {
				return argumentError("Can't specify multiple conflicting values for cypher version")
			}
			seenVersion = version
			if err := consumeGap(end); err != nil {
				return err
			}
		}
		// Comments between the preamble and its body are still source text.
		// Admit their terminator while consuming this existing prefix gap,
		// before option parsing can misreport an unfinished comment as syntax.
		if err := consumeGap(0); err != nil {
			return err
		}
		for rest != "" && !startsWithClauseKeyword(rest) {
			end := 0
			for end < len(rest) && isIdentByte(rest[end]) {
				end++
			}
			name := strings.ToLower(rest[:end])
			if err := consumeGap(end); err != nil {
				return err
			}
			if end == 0 || rest == "" || rest[0] != '=' {
				return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "invalid CYPHER option: expected name=value")
			}
			if err := consumeGap(1); err != nil {
				return err
			}
			end = 0
			for end < len(rest) && isIdentByte(rest[end]) {
				end++
			}
			if end == 0 {
				return newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", "invalid CYPHER option: expected a value")
			}
			value := strings.ToLower(rest[:end])
			if err := consumeGap(end); err != nil {
				return err
			}
			allowed, known := cypherPreambleOptionValues[name]
			if !known {
				return argumentError("Unsupported options: " + name)
			}
			valid := false
			for _, candidate := range strings.Split(allowed, ", ") {
				if value == candidate {
					valid = true
					break
				}
			}
			if !valid {
				return argumentError(fmt.Sprintf("%s is not a valid option for %s. Valid options are: %s", value, name, allowed))
			}
		}
	}
	return nil
}

func stripCypherPreamble(query string) (string, bool) {
	rest := query
	changed := false
	var modes []string
	for {
		trimmed := strings.TrimSpace(rest)
		if mode, inner := executionModePrefix(trimmed); mode != ModeNormal {
			modes = append(modes, string(mode))
			rest = inner
			continue
		}
		if !matchKeywordAt(trimmed, 0, "CYPHER") {
			break
		}
		changed = true
		rest = strings.TrimSpace(trimmed[queryGapEnd(trimmed, len("CYPHER")):])
		// Optional version number (e.g. CYPHER 5, CYPHER 25).
		if len(rest) > 0 && rest[0] >= '0' && rest[0] <= '9' {
			i := 0
			for i < len(rest) && rest[i] >= '0' && rest[i] <= '9' {
				i++
			}
			rest = strings.TrimSpace(rest[queryGapEnd(rest, i):])
		}
		// Option tokens until the next clause keyword starts the statement.
		for rest != "" && !startsWithClauseKeyword(rest) {
			if isCypherStringQuoteByte(rest[0]) {
				end := skipCypherQuotedText(rest, 0, rest[0])
				rest = strings.TrimSpace(rest[queryGapEnd(rest, end):])
				continue
			}
			i := 0
			for i < len(rest) && !isASCIISpace(rest[i]) && queryCommentEnd(rest, i) < 0 {
				i++
			}
			rest = strings.TrimSpace(rest[queryGapEnd(rest, i):])
		}
		if rest == "" {
			break
		}
	}
	if changed {
		if len(modes) > 0 {
			return strings.Join(modes, " ") + " " + strings.TrimSpace(rest), true
		}
		return strings.TrimSpace(rest), true
	}
	return query, false
}

// finishProhibitedClauses are the clause keywords a statement may not end
// with before FINISH. Neo4j 5.26 rejects FINISH only after RETURN ("RETURN can
// only be used at the end of the query"); after WITH or YIELD it ends the
// statement like after any other clause and returns no rows (#907). A
// prohibited trailing FINISH stays in the text so validation rejects it.
var finishProhibitedClauses = map[string]bool{
	"RETURN": true,
}

// trailingBareFinish reports whether the statement ends with a standalone
// FINISH keyword outside quotes and comments. A trailing `finish` where a
// name or an expression is read (RETURN finish, x AS finish, DELETE finish,
// m.finish) is a variable, not the clause: FINISH is not a reserved word in
// Neo4j (#958).
func trailingBareFinish(cypher string) (string, bool) {
	last := lastLiveByte(cypher, len(cypher))
	if last < 0 || !isIdentByte(cypher[last]) {
		return "", false
	}
	end := last + 1
	start := end
	for start > 0 && isIdentByte(cypher[start-1]) {
		start--
	}
	if !strings.EqualFold(cypher[start:end], "FINISH") {
		return "", false
	}
	remainder := strings.TrimSpace(cypher[:start])
	// A FINISH with nothing before it is the whole statement, the clause.
	if remainder != "" && clauseKeywordUsedAsName(cypher, start, end, "FINISH") {
		return "", false
	}
	return remainder, true
}

// stripTrailingFinish removes a trailing FINISH clause terminator (Neo4j 5.19+:
// FINISH ends a query without returning rows). FINISH counts unless the
// preceding top-level clause is RETURN (finishProhibitedClauses); a trailing
// FINISH after RETURN stays in the text so validation rejects it. The
// preceding clause comes from the shared name-aware scanner
// lastTopLevelClauseWord (validator_strictness.go): one clause scanner for
// both the FINISH position and the dangling-UNWIND rule.
func stripTrailingFinish(cypher string) (string, bool) {
	remainder, ok := trailingBareFinish(cypher)
	if !ok {
		return cypher, false
	}
	if finishProhibitedClauses[lastTopLevelClauseWord(remainder)] {
		return cypher, false
	}
	return remainder, true
}

type finishedStatementKey struct{}

// withFinishedStatement records that statement (the text left after its
// trailing FINISH was stripped) ended in FINISH. A CALL … YIELD with WHERE,
// ORDER BY, SKIP or LIMIT that is the whole statement is then not a
// standalone call: FINISH is the clause after it, as in Neo4j (#907).
func withFinishedStatement(ctx context.Context, statement string) context.Context {
	return context.WithValue(ctx, finishedStatementKey{}, strings.Join(strings.Fields(statement), " "))
}

// endsInFinish reports whether statement is the one withFinishedStatement
// recorded, compared with whitespace normalized: a CALL a subquery or a
// procedure runs inside the statement is not.
func endsInFinish(ctx context.Context, statement string) bool {
	finished, _ := ctx.Value(finishedStatementKey{}).(string)
	return finished != "" && finished == strings.Join(strings.Fields(statement), " ")
}

// topLevelUnionCut returns the offset of the first top-level UNION keyword
// (outside quotes, comments and nested delimiters), or -1.
func topLevelUnionCut(s string) int {
	parenDepth, bracketDepth, braceDepth := 0, 0, 0
	for i := 0; i < len(s); i++ {
		if end, quoted := skipCypherLexicalToken(s, i); quoted {
			i = end - 1
			continue
		}
		c := s[i]
		switch c {
		case '(':
			parenDepth++
		case ')':
			parenDepth--
		case '[':
			bracketDepth++
		case ']':
			bracketDepth--
		case '{':
			braceDepth++
		case '}':
			braceDepth--
		}
		if parenDepth == 0 && bracketDepth == 0 && braceDepth == 0 &&
			matchKeywordAt(s, i, "UNION") {
			return i
		}
	}
	return -1
}

// stripUnionBranchFinishes strips a trailing FINISH from each UNION branch of
// the statement. If no branch ends in FINISH the text is unchanged.
func stripUnionBranchFinishes(ctx context.Context, cypher string) (string, bool) {
	cut := topLevelUnionCut(cypher)
	if cut < 0 {
		return stripTrailingFinish(cypher)
	}
	before := strings.TrimSpace(cypher[:cut])
	after := strings.TrimSpace(cypher[cut:])
	// Consume UNION and an optional ALL.
	wordEnd := 0
	for wordEnd < len(after) && !isASCIISpace(after[wordEnd]) {
		wordEnd++
	}
	unionWord := after[:wordEnd]
	tail := strings.TrimSpace(after[wordEnd:])
	if nextWord, ok := firstWordUpper(tail); ok && nextWord == "ALL" {
		unionWord += " ALL"
		tail = strings.TrimSpace(tail[len("ALL"):])
	}
	right, rightStripped := stripUnionBranchFinishes(ctx, tail)
	left, leftStripped := stripTrailingFinish(before)
	if !leftStripped && !rightStripped {
		return cypher, false
	}
	if leftStripped && rightStripped && left == "" && right == "" {
		if _, _, mixed, _ := parseTopLevelUnionBranches(ctx, cypher); !mixed {
			return "", true
		}
		return cypher, false
	}
	return strings.TrimSpace(left + " " + unionWord + " " + right), true
}

func firstWordUpper(s string) (string, bool) {
	i := 0
	for i < len(s) && !isASCIISpace(s[i]) {
		i++
	}
	if i == 0 {
		return "", false
	}
	return upperASCII(s[:i]), true
}

func explainProfileConflict(cypher string) bool {
	_, statement, conflict := statementExecutionModes(cypher)
	return conflict && queryGapEnd(statement, 0) < len(statement)
}

// completeFinishedResult applies FINISH before the declared schema is checked.
// Internal and public execution share this terminal projection.
func completeFinishedResult(result *ExecuteResult) {
	if result != nil {
		result.Columns = nil
		result.Rows = nil
	}
}

package cypher

import (
	"context"
	"time"

	"github.com/orneryd/nornicdb/pkg/storage"
)

type temporalViewportKeyType struct{}

var temporalViewportKey = temporalViewportKeyType{}

type TemporalViewportMode int

const (
	TemporalViewportLive TemporalViewportMode = iota
	TemporalViewportAsOf
)

type TemporalViewport struct {
	Mode TemporalViewportMode
	AsOf time.Time
}

func CurrentTemporalViewport() TemporalViewport {
	return TemporalViewport{Mode: TemporalViewportLive}
}

func AsOfTemporalViewport(asOf time.Time) TemporalViewport {
	return TemporalViewport{Mode: TemporalViewportAsOf, AsOf: asOf.UTC()}
}

func (v TemporalViewport) Enabled() bool {
	return v.Mode == TemporalViewportAsOf && !v.AsOf.IsZero()
}

func WithTemporalViewport(ctx context.Context, viewport TemporalViewport) context.Context {
	return context.WithValue(ctx, temporalViewportKey, viewport)
}

func TemporalViewportFromContext(ctx context.Context) (TemporalViewport, bool) {
	viewport, ok := ctx.Value(temporalViewportKey).(TemporalViewport)
	return viewport, ok
}

type temporalCurrentNodeChecker interface {
	IsCurrentTemporalNode(node *storage.Node, asOf time.Time) (bool, error)
}

func filterNodesByTemporalViewport(nodes []*storage.Node, viewport TemporalViewport, checker temporalCurrentNodeChecker) ([]*storage.Node, error) {
	if !viewport.Enabled() || checker == nil {
		return nodes, nil
	}
	filtered := make([]*storage.Node, 0, len(nodes))
	for _, node := range nodes {
		if node == nil {
			continue
		}
		visible, err := checker.IsCurrentTemporalNode(node, viewport.AsOf)
		if err != nil {
			return nil, err
		}
		if !visible {
			continue
		}
		filtered = append(filtered, node)
	}
	return filtered, nil
}

func nodeVisibleInTemporalViewport(node *storage.Node, viewport TemporalViewport, checker temporalCurrentNodeChecker) (bool, error) {
	if !viewport.Enabled() || checker == nil || node == nil {
		return true, nil
	}
	return checker.IsCurrentTemporalNode(node, viewport.AsOf)
}

func filterNodesByRequiredLabels(nodes []*storage.Node, labels []string) []*storage.Node {
	if len(labels) <= 1 {
		return nodes
	}
	filtered := make([]*storage.Node, 0, len(nodes))
	for _, node := range nodes {
		if mergeNodeHasLabels(node, labels) {
			filtered = append(filtered, node)
		}
	}
	return filtered
}

func (e *StorageExecutor) loadNodesWithTemporalViewport(ctx context.Context, labels []string) ([]*storage.Node, error) {
	return e.loadPatternNodes(ctx, labels, nil)
}

// loadPatternNodes returns the nodes of a node pattern (labels, inline
// properties) visible in the temporal viewport. Traversal seeds use the same
// label-indexed, viewport-aware streaming collector as node MATCH, which
// avoids a second physical scan path that materialises GetNodesByLabel inside
// explicit transactions. Passing the properties lets a pattern without labels
// take the projected scan instead of decoding every node (#857).
func (e *StorageExecutor) loadPatternNodes(ctx context.Context, labels []string, properties map[string]interface{}) ([]*storage.Node, error) {
	return e.collectNodesWithStreaming(ctx, labels, properties, "", "", -1)
}

// Package cypher - Transaction support for Cypher queries.
//
// Implements BEGIN/COMMIT/ROLLBACK for Neo4j-compatible transaction control.
package cypher

import (
	"context"
	"errors"
	"fmt"
	"regexp"
	"strings"
	"time"
	"unicode"

	nornicerrors "github.com/orneryd/nornicdb/pkg/errors"
	"github.com/orneryd/nornicdb/pkg/fabric"
	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

type transactionStatementOriginKey struct{}

// WithClientStatement marks text supplied as a client statement, not protocol transaction control.
func WithClientStatement(ctx context.Context) context.Context {
	return context.WithValue(ctx, transactionStatementOriginKey{}, true)
}

// WithTransactionControl permits a transaction owner to issue its lifecycle command.
func WithTransactionControl(ctx context.Context) context.Context {
	return context.WithValue(ctx, transactionStatementOriginKey{}, false)
}

// clientTransactionCommand is Neo4j's SyntaxError for a client statement that
// is a bare BEGIN, COMMIT or ROLLBACK (optionally followed by TRANSACTION):
// Cypher has no transaction statements, and a client statement runs on an
// executor the client doesn't own for longer than the statement, so it must
// not leave that executor inside a transaction. The one-statement script form
// (BEGIN … COMMIT in one text) and embedded callers without a client mark keep
// working.
func clientTransactionCommand(ctx context.Context, query string) error {
	if ctx.Value(transactionStatementOriginKey{}) != true {
		return nil
	}
	if word := bareTransactionCommand(query); word != "" {
		message := localization.CypherTransactionsCommandNotStatement(word)
		return localizedError(message, newSemanticError("Neo.ClientError.Statement.SyntaxError", "UnexpectedSyntax", message.Fallback))
	}
	return nil
}

var firstUseGraphPattern = regexp.MustCompile(`(?is)\bUSE\s+([A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)?)`)

// TransactionContext holds the active transaction for a Cypher session.
type TransactionContext struct {
	// Captured at BEGIN, independent of user-editable tx.setMetaData values.
	coordinatorOwned bool
	tx               interface{}    // *storage.BadgerTransaction (MemoryEngine now wraps BadgerEngine)
	engine           storage.Engine // Engine owning this transaction's commit.
	storageWrapper   *transactionStorageWrapper
	active           bool
	wal              *storage.WAL
	walSeqStart      uint64
	database         string
	txID             string
	fabricRemoteExe  *fabric.RemoteFragmentExecutor
	// running is the transaction's SHOW TRANSACTIONS entry (#718).
	running *runningTransaction

	// fabricLocalTxExec holds, per local constituent (shard name), the
	// executor of this transaction's sub-transaction on it. Every statement
	// of the transaction runs there, so it sees earlier statements' writes
	// and COMMIT / ROLLBACK ends all of them.
	fabricLocalTxExec map[string]*StorageExecutor
	// failed is the error of the first statement that failed in the
	// transaction. A failed transaction stays open so ROLLBACK discards what
	// it wrote; any other statement is refused and COMMIT rolls it back, as in
	// Neo4j (#683).
	failed error
	// storageRolledBack records early cleanup after a memory failure. The
	// protocol transaction stays failed until its owner receives COMMIT or
	// ROLLBACK, while staged storage and its budget are released immediately.
	storageRolledBack bool

	// statementKind keeps administration commands apart from data statements.
	statementKind string
}

// failTransaction records err as the active explicit transaction's failure
// and returns err. The first failure wins: it is the cause COMMIT reports. It
// is the one rule for a statement that fails inside a transaction, whether it
// ran through Execute or an inline transaction script (#683). A composite
// transaction's participants end their part with it: each local one fails
// with the same cause, and each remote sub-transaction is rolled back. ctx is
// the failed statement's context, whose deadline bounds the remote rollbacks.
func (e *StorageExecutor) failTransaction(ctx context.Context, err error) error {
	if tx := e.txContext; err != nil && tx != nil && tx.active && tx.failed == nil {
		tx.failed = err
		if code, _ := nornicerrors.Neo4jStatus(err); code == transactionMemoryLimitCode || code == memoryPoolOutOfMemoryCode {
			if storageTx, ok := tx.tx.(*storage.BadgerTransaction); ok {
				if rollbackErr := storageTx.Rollback(); rollbackErr == nil {
					tx.storageRolledBack = true
					if tx.running != nil {
						tx.running.releaseMemory()
					}
				}
			}
		}
		// The transaction can no longer commit: the MERGE key locks it holds,
		// itself or through a participant's sub-transaction, must not keep
		// other transactions' MERGEs of those keys waiting until the client
		// rolls it back. Local keys are released first: they never wait on a
		// remote.
		if releaser, ok := tx.tx.(interface{ ReleaseMergeKeys() }); ok {
			releaser.ReleaseMergeKeys()
		}
		for _, participant := range tx.fabricLocalTxExec {
			participant.failTransaction(ctx, err)
		}
		if tx.fabricRemoteExe != nil {
			// A remote participant records its own rollback error (a
			// deadline included); the transaction keeps reporting err.
			rollbackCtx, cancel := remoteFailureRollbackContext(ctx)
			_ = tx.fabricRemoteExe.RollbackParticipants(rollbackCtx)
			cancel()
		}
	}
	return err
}

// remoteFailureRollbackContext bounds a failed transaction's remote
// rollbacks: by the statement's deadline (its transaction or statement
// timeout), and never longer than the remote client's request timeout. It
// isn't cancelled with the statement, which already failed.
func remoteFailureRollbackContext(ctx context.Context) (context.Context, context.CancelFunc) {
	if ctx == nil {
		ctx = context.Background()
	}
	deadline := time.Now().Add(storage.RemoteRequestTimeout)
	if statementDeadline, ok := ctx.Deadline(); ok && statementDeadline.Before(deadline) {
		deadline = statementDeadline
	}
	return context.WithDeadline(context.WithoutCancel(ctx), deadline)
}

// abortTransaction fails the active transaction with err and ends it: what an
// inline transaction script (BEGIN … COMMIT in one request) does when its
// statement fails, since no later ROLLBACK can reach it. It returns err.
func (e *StorageExecutor) abortTransaction(ctx context.Context, err error) error {
	e.failTransaction(ctx, err)
	_, _ = e.handleRollback()
	return err
}

// queryOnFailedTransactionError is the error of a statement sent to a
// transaction a previous statement failed in.
func queryOnFailedTransactionError(cause error) error {
	return newSemanticError("Neo.TransientError.Transaction.QueryExecutionFailedOnTransaction", "QueryExecutionFailedOnTransaction",
		"The transaction was marked as failed because a query failed: "+cause.Error())
}

// bareTransactionCommand returns the command word, as typed, when cypher is exactly a
// bare transaction command (BEGIN, COMMIT or ROLLBACK, optionally followed by
// TRANSACTION), else "".
func bareTransactionCommand(cypher string) string {
	// Allocation-free: it runs for every client statement.
	text := strings.TrimSpace(cypher)
	word, rest := text, ""
	if i := strings.IndexFunc(text, unicode.IsSpace); i >= 0 {
		word, rest = text[:i], strings.TrimSpace(text[i:])
	}
	if rest != "" && !strings.EqualFold(rest, "TRANSACTION") {
		return ""
	}
	if strings.EqualFold(word, "BEGIN") || strings.EqualFold(word, "COMMIT") || strings.EqualFold(word, "ROLLBACK") {
		// As typed: Neo4j's SyntaxError quotes the input ('begin').
		return word
	}
	return ""
}

// parseTransactionStatement checks if query is BEGIN/COMMIT/ROLLBACK.
func (e *StorageExecutor) parseTransactionStatement(ctx context.Context, cypher string) (*ExecuteResult, error) {
	upper := upperASCII(strings.TrimSpace(cypher))

	switch {
	case upper == "BEGIN" || upper == "BEGIN TRANSACTION":
		return e.handleBegin()
	case upper == "COMMIT" || upper == "COMMIT TRANSACTION":
		return e.handleCommit(ctx)
	case upper == "ROLLBACK" || upper == "ROLLBACK TRANSACTION":
		return e.handleRollback()
	default:
		return nil, nil // Not a transaction statement
	}
}

// handleBegin starts a new explicit transaction.
func (e *StorageExecutor) handleBegin() (*ExecuteResult, error) {
	if e.txContext != nil && e.txContext.active {
		return nil, localizedError(localization.CypherTransactionsAlreadyActive(), nil)
	}

	// Establish the acknowledged-write visibility boundary before opening the
	// underlying snapshot. Writes are committed synchronously by their
	// statements, so a snapshot opened here observes every acknowledged write.

	// Unwrap engine wrappers (WAL/Namespaced) recursively.
	engine := e.storage
	namespaceHint := ""
	visited := map[storage.Engine]bool{}
	for engine != nil && !visited[engine] {
		visited[engine] = true
		if namespacedEngine, ok := engine.(*storage.NamespacedEngine); ok {
			if namespaceHint == "" {
				namespaceHint = namespacedEngine.Namespace()
			}
		}
		if wrapper, ok := engine.(storage.EngineUnwrapper); ok {
			engine = wrapper.GetInnerEngine()
			continue
		}
		break
	}

	// Composite engines use FabricTransaction coordinator semantics.
	// This supports explicit BEGIN/COMMIT/ROLLBACK at API level for composite routes.
	if _, ok := engine.(*storage.CompositeEngine); ok {
		var fabricTx *fabric.FabricTransaction
		openSnapshot := func() error {
			fabricTx = fabric.NewFabricTransaction(fmt.Sprintf("fabtx-%d", time.Now().UnixNano()))
			return nil
		}
		if err := openSnapshot(); err != nil {
			return nil, localizedError(localization.CypherTransactionsStartFailed(err), err)
		}
		e.txContext = &TransactionContext{
			tx:     fabricTx,
			engine: engine,
			active: true,
		}
		return &ExecuteResult{
			Columns: []string{"status"},
			Rows:    [][]interface{}{{"Transaction started"}},
		}, nil
	}

	// Start transaction for any engine that supports BeginTransaction.
	txEngine, ok := engine.(interface {
		BeginTransaction() (*storage.BadgerTransaction, error)
	})
	if !ok {
		return nil, localizedError(localization.CypherTransactionsEngineUnsupported(), nil)
	}
	if namespaceHint != "" {
		if primer, ok := txEngine.(interface{ EnsureNamespaceMVCC(string) error }); ok {
			if err := primer.EnsureNamespaceMVCC(namespaceHint); err != nil {
				return nil, localizedError(localization.CypherTransactionsPrimeNamespaceFailed(err), err)
			}
		}
	}
	// With write-behind buffering, drain acknowledged autocommit writes so
	// the explicit snapshot observes every acknowledged statement.
	if drainer, ok := engine.(interface{ FlushWriteBehind() error }); ok {
		if err := drainer.FlushWriteBehind(); err != nil {
			return nil, localizedError(localization.CypherTransactionsStartFailed(err), err)
		}
	}
	tx, err := beginTransactionSnapshot(txEngine)
	if err != nil {
		return nil, localizedError(localization.CypherTransactionsStartFailed(err), err)
	}
	if namespaceHint != "" {
		if err := tx.SetNamespace(namespaceHint); err != nil {
			_ = tx.Rollback()
			return nil, localizedError(localization.CypherTransactionsPinNamespaceFailed(err), err)
		}
	}
	// An explicit transaction checks each write against the constraints
	// when its statement runs, as Neo4j does: the statement that breaks a
	// constraint fails with ConstraintValidationFailed (and fails the
	// transaction), not the COMMIT (#700). COMMIT checks again under the
	// constraint keys' locks, against what other writers committed since.
	if err := tx.SetDeferredConstraintValidation(false); err != nil {
		_ = tx.Rollback()
		return nil, localizedError(localization.CypherTransactionsConfigureFailed(err), err)
	}
	txCtx := &TransactionContext{
		tx:     tx,
		engine: e.storage,
		active: true,
		txID:   tx.ID,
	}
	if wal, dbName := e.resolveWALAndDatabase(); wal != nil {
		walSeq, walErr := wal.AppendTxBegin(dbName, tx.ID, nil)
		if walErr != nil {
			_ = tx.Rollback()
			return nil, localizedError(localization.CypherTransactionsWALBeginFailed(walErr), walErr)
		}
		txCtx.wal = wal
		txCtx.walSeqStart = walSeq
		txCtx.database = dbName
	}
	e.txContext = txCtx

	return &ExecuteResult{
		Columns: []string{"status"},
		Rows:    [][]interface{}{{"Transaction started"}},
	}, nil
}

// handleCommit commits the active transaction.
func (e *StorageExecutor) handleCommit(ctx context.Context) (*ExecuteResult, error) {
	if e.txContext == nil || !e.txContext.active {
		return nil, localizedError(localization.CypherTransactionsNoActive(), nil)
	}
	// A transaction TERMINATE TRANSACTIONS ended doesn't commit (#718).
	if e.txContext.running != nil && e.txContext.running.terminated.Load() {
		_, _ = e.handleRollback()
		return nil, transactionTerminatedError()
	}
	// A transaction a statement failed in can't commit: it is rolled back.
	if cause := e.txContext.failed; cause != nil {
		if _, err := e.handleRollback(); err != nil {
			return nil, err
		}
		return nil, newSemanticError("Neo.ClientError.Transaction.TransactionMarkedAsFailed", "TransactionMarkedAsFailed",
			"The transaction was rolled back because a statement in it failed: "+cause.Error())
	}
	// Commit based on transaction type
	// All engines now use BadgerTransaction (MemoryEngine wraps BadgerEngine)
	var (
		err     error
		receipt *storage.Receipt
		opCount int
	)
	switch tx := e.txContext.tx.(type) {
	case *storage.BadgerTransaction:
		opCount = tx.OperationCount()
		err = e.commitStorageTransaction(ctx, tx)
	case *fabric.FabricTransaction:
		err = tx.Commit(nil, nil)
		if err == nil {
			publishStatementCommit(ctx)
		}
	default:
		return nil, localizedError(localization.CypherTransactionsUnknownType(), nil)
	}

	wal := e.txContext.wal
	walSeqStart := e.txContext.walSeqStart
	txID := e.txContext.txID
	dbName := e.txContext.database

	if err == nil && wal != nil && walSeqStart > 0 {
		commitSeq, walErr := wal.AppendTxCommit(dbName, txID, opCount)
		if walErr == nil {
			receipt, _ = storage.NewReceipt(
				txID,
				walSeqStart,
				commitSeq,
				dbName,
				time.Now().UTC(),
			)
		}
	}

	if err != nil {
		if wal != nil && walSeqStart > 0 {
			_, _ = wal.AppendTxAbort(dbName, txID, err.Error())
		}
		if e.txContext.fabricRemoteExe != nil {
			_ = e.txContext.fabricRemoteExe.Close()
			e.txContext.fabricRemoteExe = nil
		}
		_, localTx := e.txContext.tx.(*storage.BadgerTransaction)
		e.txContext.active = false
		runningTransactions.end(e.txContext.running)
		e.txContext = nil
		// Wire contract: substring "commit failed" is matched by downstream Bolt classifiers.
		// See docs/plans/consumer-pinned-error-contract-plan.md §2.1.
		failure := localizedError(localization.CypherTransactionsCommitFailed(err), err)
		if commitFailureWroteNothing(localTx, err) {
			failure = nornicerrors.MarkCommitRolledBack(failure)
		}
		return nil, failure
	}
	if e.txContext.storageWrapper != nil {
		txExec := e.cloneWithStorage(e.txContext.storageWrapper)
		txExec.promoteNodeLookupCacheTo(e)
		for _, action := range e.txContext.storageWrapper.schemaCommitActions {
			action()
		}
		txExec.refreshSearchAfterCommit(e.txContext.storageWrapper)
	}

	if e.txContext.fabricRemoteExe != nil {
		_ = e.txContext.fabricRemoteExe.Close()
		e.txContext.fabricRemoteExe = nil
	}
	e.txContext.active = false
	runningTransactions.end(e.txContext.running)
	e.txContext = nil

	result := &ExecuteResult{
		Columns: []string{"status"},
		Rows:    [][]interface{}{{"Transaction committed"}},
	}
	if receipt != nil {
		result.Metadata = map[string]interface{}{
			"receipt": receipt,
		}
	}
	return result, nil
}

// commitFailureWroteNothing reports whether a failed COMMIT left nothing of
// the transaction stored, so its outcome is known (the Bolt session keeps its
// connection). A local transaction (BadgerTransaction.Commit) fails before
// it writes anything on:
//   - a constraint violation, checked before the write;
//   - a transaction over the store's size limit (storage.IsTransactionTooBig),
//     raised while its writes are staged in the one Badger transaction, which
//     is then discarded.
//
// A fabric transaction may fail after some constituents committed, so its
// failures are never marked.
func commitFailureWroteNothing(localTx bool, err error) bool {
	if !localTx {
		return false
	}
	var violation *storage.ConstraintViolationError
	return errors.As(err, &violation) || storage.IsTransactionTooBig(err)
}

// handleRollback rolls back the active transaction.
func (e *StorageExecutor) handleRollback() (*ExecuteResult, error) {
	if e.txContext == nil || !e.txContext.active {
		return nil, localizedError(localization.CypherTransactionsNoActive(), nil)
	}
	// Rollback based on transaction type
	// All engines now use BadgerTransaction (MemoryEngine wraps BadgerEngine)
	var err error
	switch tx := e.txContext.tx.(type) {
	case *storage.BadgerTransaction:
		if !e.txContext.storageRolledBack {
			err = tx.Rollback()
		}
	case *fabric.FabricTransaction:
		// If already rolled back, treat as idempotent rollback success.
		if tx.State() != "open" {
			err = nil
		} else {
			err = tx.Rollback(nil)
		}
	default:
		return nil, localizedError(localization.CypherTransactionsUnknownType(), nil)
	}

	if e.txContext.wal != nil && e.txContext.walSeqStart > 0 {
		_, _ = e.txContext.wal.AppendTxAbort(e.txContext.database, e.txContext.txID, "rollback")
	}
	if e.txContext.fabricRemoteExe != nil {
		_ = e.txContext.fabricRemoteExe.Close()
		e.txContext.fabricRemoteExe = nil
	}

	e.txContext.active = false
	runningTransactions.end(e.txContext.running)
	e.txContext = nil

	if err != nil {
		return nil, localizedError(localization.CypherTransactionsRollbackFailed(err), err)
	}

	return &ExecuteResult{
		Columns: []string{"status"},
		Rows:    [][]interface{}{{"Transaction rolled back"}},
	}, nil
}

// executeInTransaction executes a query within the active transaction.
// Uses the same transactionStorageWrapper pattern as implicit transactions,
// routing writes through the transaction for atomicity and rollback support.
func (e *StorageExecutor) executeInTransaction(ctx context.Context, cypher string, upperQuery string) (*ExecuteResult, error) {
	parsedCypher, inlineEmbeddingEnabled := stripWithEmbeddingSuffix(cypher)
	if inlineEmbeddingEnabled {
		cypher = parsedCypher
		upperQuery = upperASCII(cypher)
	}

	if ftx, ok := e.txContext.tx.(*fabric.FabricTransaction); ok {
		if looksLikeWriteQuery(cypher) {
			if graph := extractFirstUseGraph(cypher); graph != "" {
				if _, err := ftx.GetOrOpen(graph, true); err != nil {
					return nil, err
				}
			}
		}
		// For composite/fabric transactions, route through shared fabric gateway when
		// query has multi-graph CALL { USE ... } patterns so write-shard constraints are
		// enforced across statements within the same explicit transaction.
		params := getParamsFromContext(ctx)
		if e.shouldUseFabricPlanner(cypher) {
			return e.executeViaFabricWithTx(ctx, cypher, params, ftx, false)
		}
		// Non-fabric-shaped queries still run on the scoped engine in explicit tx session.
		return e.executeWithoutTransaction(ctx, cypher, upperQuery)
	}

	// All engines now use BadgerTransaction (MemoryEngine wraps BadgerEngine)
	tx, ok := e.txContext.tx.(*storage.BadgerTransaction)
	if !ok {
		return nil, localizedError(localization.CypherTransactionsUnknownType(), nil)
	}

	// Recursive execution paths, such as UNWIND ... MATCH ... MERGE fallback
	// routing, can re-enter Execute while the transaction wrapper is already in
	// context. Reuse it so database namespace metadata is not lost by wrapping
	// the same Badger transaction a second time. Only reuse the wrapper that
	// belongs to the active explicit transaction; stale wrappers from reused
	// contexts must fall back to a fresh wrapper for the current tx.
	if txWrapper, ok := ctx.Value(ctxKeyTxStorage).(*transactionStorageWrapper); ok &&
		txWrapper != nil &&
		txWrapper.tx == tx {
		txExec := e.cloneWithStorage(txWrapper)
		result, err := txExec.executeQueryAgainstStorage(ctx, cypher, upperQuery)
		if err != nil {
			return result, err
		}
		if inlineEmbeddingEnabled {
			mutated := txWrapper.snapshotMutatedNodeIDs()
			if err := txExec.applyInlineEmbeddingMutations(ctx, mutated); err != nil {
				return nil, err
			}
			txWrapper.clearMutatedNodeIDs(mutated)
		}
		return result, nil
	}

	// Reuse one storage adapter for the explicit transaction lifetime. Besides
	// preserving namespace and mutation state, this prevents every statement
	// (including RETURN literals) from allocating and reseeding a 1000-entry
	// transaction lookup cache.
	txWrapper := e.transactionStorageFor(tx)

	// Pass the wrapper through context (same pattern as implicit transactions)
	// This is thread-safe and allows getStorage() to automatically use the transaction
	txCtx := context.WithValue(ctx, ctxKeyTxStorage, txWrapper)
	txExec := e.cloneWithStorage(txWrapper)

	// Execute the query - getStorage() will automatically use the transaction wrapper
	result, err := txExec.executeQueryAgainstStorage(txCtx, cypher, upperQuery)
	if err != nil {
		return result, err
	}
	if inlineEmbeddingEnabled {
		mutated := txWrapper.snapshotMutatedNodeIDs()
		if err := txExec.applyInlineEmbeddingMutations(txCtx, mutated); err != nil {
			return nil, err
		}
		txWrapper.clearMutatedNodeIDs(mutated)
	}
	return result, nil
}

// transactionStorageFor is the transaction's sole storage-adapter owner.
// Runtime Fabric promotion and ordinary explicit execution reuse this adapter;
// neither creates another transaction or terminal lifecycle.
func (e *StorageExecutor) transactionStorageFor(tx *storage.BadgerTransaction) *transactionStorageWrapper {
	if wrapper := e.txContext.storageWrapper; wrapper != nil && wrapper.tx == tx {
		return wrapper
	}
	engines := e.resolveImplicitTxEngines()
	separator := ":"
	if engines.namespace == "" {
		separator = ""
	}
	wrapper := &transactionStorageWrapper{
		tx: tx, underlying: e.storage, namespace: engines.namespace, separator: separator,
		mutatedNodeIDs: make(map[string]struct{}),
	}
	wrapper.initNamespacePrefix()
	e.txContext.storageWrapper = wrapper
	return wrapper
}

func looksLikeWriteQuery(cypher string) bool {
	upper := upperASCII(classificationText(cypher))
	return strings.Contains(upper, "CREATE") ||
		strings.Contains(upper, "MERGE") ||
		strings.Contains(upper, "DELETE") ||
		strings.Contains(upper, "SET ") ||
		strings.Contains(upper, "REMOVE ")
}

func extractFirstUseGraph(cypher string) string {
	m := firstUseGraphPattern.FindStringSubmatch(cypher)
	if len(m) < 2 {
		return ""
	}
	return strings.TrimSpace(m[1])
}

// executeQueryAgainstStorage executes query with current storage context.
func (e *StorageExecutor) executeQueryAgainstStorage(ctx context.Context, cypher string, upperQuery string) (*ExecuteResult, error) {
	e.decayMismatchLogged = false
	// Single router: the transaction only changes which storage view e.storage is.
	return e.executeWithoutTransaction(ctx, cypher, upperQuery)
}

package cypher

import (
	"context"
	"errors"
	"strings"
	"sync"

	"github.com/orneryd/nornicdb/pkg/localization"
	"github.com/orneryd/nornicdb/pkg/storage"
)

// propertyIndexLookup is the one lookup of label's property = value in a
// property index, as engine sees it. The index describes committed state, so
// inside a transaction the transaction's own node writes are merged in
// (storage.BadgerTransaction.MergePendingPropertyMatches): nodes it created
// or changed are listed by their current values, nodes it changed or deleted
// lose their committed entries (#809). The lookup stays an index lookup: a
// transaction that reads by an indexed property doesn't scan the label.
func propertyIndexLookup(ctx context.Context, engine storage.Engine, schema *storage.SchemaManager, label, property string, value interface{}) ([]storage.NodeID, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	ids, err := schema.PropertyIndexLookupWithContext(ctx, label, property, value)
	if err != nil {
		return nil, err
	}
	if wrapper, transactional := engine.(*transactionStorageWrapper); transactional {
		return wrapper.tx.MergePendingPropertyMatchesWithContext(ctx, ids, label, property, value)
	}
	return ids, ctx.Err()
}

// compositeIndexLookup is the composite-index counterpart of
// propertyIndexLookup: a full or prefix lookup against committed state, with
// the transaction's own pending node writes merged in. full selects LookupFull
// (all index properties equal) over LookupPrefix (leading properties equal).
func compositeIndexLookup(ctx context.Context, engine storage.Engine, idx *storage.CompositeIndex, values []interface{}, full bool) ([]storage.NodeID, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	var ids []storage.NodeID
	var err error
	if full {
		ids, err = idx.LookupFullWithContext(ctx, values...)
	} else {
		ids, err = idx.LookupPrefixWithContext(ctx, values...)
	}
	if err != nil {
		return nil, err
	}
	if wrapper, transactional := engine.(*transactionStorageWrapper); transactional {
		return wrapper.tx.MergePendingCompositeMatchesWithContext(ctx, ids, idx.Label, idx.Properties, values)
	}
	return ids, ctx.Err()
}

// labellessPropertyIndexUsable reports whether a pattern without a label may
// take its candidates from the property indexes read through engine. The
// indexes are per label, so their union for a property lists only the nodes
// that carry an indexed label. A committed lookup is complete only when an
// indexed label covers the namespace; transaction reads use the merged scan.
func labellessPropertyIndexUsable(ctx context.Context, engine storage.Engine, labels ...string) bool {
	if _, transactional := engine.(*transactionStorageWrapper); transactional {
		return false
	}
	stats, supported := engine.(storage.LabelStatsEngine)
	if !supported || len(labels) == 0 {
		return false
	}
	total, err := engine.NodeCount()
	if err != nil {
		return false
	}
	for _, label := range labels {
		count, err := storage.NodeCountByLabelWithContext(ctx, stats, label)
		if err == nil && count == total {
			return true
		}
	}
	return false
}

// orderedPropertyIndexSchema returns the schema whose property indexes can
// answer an ordered or not-null index scan through engine, or nil when they
// can't: inside a transaction that has written nodes, the order of the
// committed index isn't the transaction's order, so those scans read the
// transaction's merged label scan instead. A transaction that has written no
// nodes reads the index, as an auto-commit statement does.
func orderedPropertyIndexSchema(engine storage.Engine) *storage.SchemaManager {
	if wrapper, transactional := engine.(*transactionStorageWrapper); transactional && wrapper.tx.HasPendingNodeMutations() {
		return nil
	}
	return engine.GetSchema()
}

// transactionStorageWrapper wraps a BadgerTransaction to implement storage.Engine
// for use in implicit transaction execution. It routes writes through the transaction
// (for atomicity/rollback) and reads through the underlying engine (for performance).
type transactionStorageWrapper struct {
	tx                  *storage.BadgerTransaction
	underlying          storage.Engine // For read operations not supported by transaction
	schema              *storage.SchemaManager
	schemaCommitActions []func()
	namespace           string
	separator           string
	namespacePrefix     string
	namespacePrefixOnce sync.Once
	mutatedNodeIDs      map[string]struct{}
	mutatedNodeIDsMu    sync.Mutex

	// searchNodeRefreshes and searchEdgeRefreshes are what the transaction
	// changed for search. Search reads them back once the commit makes them
	// visible (refreshSearchAfterCommit), and never after a rollback.
	searchRefreshMu     sync.Mutex
	searchNodeRefreshes map[storage.NodeID]struct{}
	searchEdgeRefreshes map[storage.EdgeID]struct{}

	// txNodeLookupCache scopes the executor's MERGE/MATCH lookup cache to
	// this single transaction. Concurrent transactions get distinct
	// wrappers — and therefore distinct caches — so a peer's uncommitted
	// node-ID mapping cannot leak into this transaction's read set via
	// store.GetNode(...) inside tx.badgerTx (which would otherwise put
	// the peer's node key into Badger's SSI read set and convert a
	// constraint violation into a generic Transaction Conflict). Within
	// a single transaction the cache is shared across re-entries that
	// reuse the same wrapper, so multi-clause queries still benefit
	// from the cross-clause speedup.
	txNodeLookupCache   map[string]*storage.Node
	txNodeLookupCacheMu *sync.RWMutex
}

// PropertyKeyKnown reports whether a write in the transaction's database has
// stored a value under name (storage.PropertyKeyLookup), from the engine the
// transaction reads through.
func (w *transactionStorageWrapper) PropertyKeyKnown(name string) bool {
	if lookup, ok := w.underlying.(storage.PropertyKeyLookup); ok {
		return lookup.PropertyKeyKnown(name)
	}
	registry, ok := w.underlying.(storage.PropertyKeyRegistry)
	return ok && registry.PropertyKeyKnownInNamespace(w.namespace, name)
}

func (w *transactionStorageWrapper) Namespace() string {
	if w == nil {
		return ""
	}
	return w.namespace
}

func (w *transactionStorageWrapper) initNamespacePrefix() {
	w.namespacePrefixOnce.Do(func() {
		if w.namespace != "" {
			w.namespacePrefix = w.namespace + w.separator
		}
	})
}

// ensureNodeLookupCacheLocked lazily initializes the wrapper's MERGE/MATCH
// lookup cache, seeding it once from the parent executor's committed
// entries. The cache exists for the lifetime of the transaction; on
// commit, executor code drains it back into the parent executor via
// promoteNodeLookupCacheTo, on rollback the wrapper is discarded and the
// cache with it. Subsequent calls (e.g. recursive Execute re-entry on
// the same wrapper) are no-ops, so the in-tx state survives across
// multi-clause queries.
func (w *transactionStorageWrapper) ensureNodeLookupCacheLocked(seedFrom *StorageExecutor) {
	if w.txNodeLookupCacheMu != nil && w.txNodeLookupCache != nil {
		return
	}
	w.txNodeLookupCacheMu = &sync.RWMutex{}
	// Lazy-sized map: autocommit transactions rarely touch more than a
	// handful of nodes, and an eager 1000-bucket table was ~5% of TCK
	// allocation space per statement (#48).
	w.txNodeLookupCache = make(map[string]*storage.Node)
	if seedFrom == nil {
		return
	}
	srcMu := seedFrom.nodeLookupCacheLock()
	srcMu.RLock()
	for k, v := range seedFrom.nodeLookupCache {
		w.txNodeLookupCache[k] = v
	}
	srcMu.RUnlock()
}

func (w *transactionStorageWrapper) GetInnerEngine() storage.Engine {
	if w == nil {
		return nil
	}
	return w.underlying
}

func (w *transactionStorageWrapper) markMutatedNodeID(id storage.NodeID) {
	if id == "" || w.mutatedNodeIDs == nil {
		return
	}
	w.mutatedNodeIDsMu.Lock()
	w.mutatedNodeIDs[string(id)] = struct{}{}
	w.mutatedNodeIDsMu.Unlock()
}

func (w *transactionStorageWrapper) deferSearchRefresh(node storage.NodeID, edge storage.EdgeID) {
	w.searchRefreshMu.Lock()
	defer w.searchRefreshMu.Unlock()
	if node != "" {
		if w.searchNodeRefreshes == nil {
			w.searchNodeRefreshes = make(map[storage.NodeID]struct{})
		}
		w.searchNodeRefreshes[node] = struct{}{}
	}
	if edge != "" {
		if w.searchEdgeRefreshes == nil {
			w.searchEdgeRefreshes = make(map[storage.EdgeID]struct{})
		}
		w.searchEdgeRefreshes[edge] = struct{}{}
	}
}

func (w *transactionStorageWrapper) takeSearchRefreshes() (map[storage.NodeID]struct{}, map[storage.EdgeID]struct{}) {
	w.searchRefreshMu.Lock()
	defer w.searchRefreshMu.Unlock()
	nodes, edges := w.searchNodeRefreshes, w.searchEdgeRefreshes
	w.searchNodeRefreshes, w.searchEdgeRefreshes = nil, nil
	return nodes, edges
}

func (w *transactionStorageWrapper) snapshotMutatedNodeIDs() map[string]struct{} {
	if len(w.mutatedNodeIDs) == 0 {
		return nil
	}
	w.mutatedNodeIDsMu.Lock()
	defer w.mutatedNodeIDsMu.Unlock()
	out := make(map[string]struct{}, len(w.mutatedNodeIDs))
	for id := range w.mutatedNodeIDs {
		out[id] = struct{}{}
	}
	return out
}

func (w *transactionStorageWrapper) clearMutatedNodeIDs(processed map[string]struct{}) {
	if len(processed) == 0 || len(w.mutatedNodeIDs) == 0 {
		return
	}
	w.mutatedNodeIDsMu.Lock()
	for id := range processed {
		delete(w.mutatedNodeIDs, id)
	}
	w.mutatedNodeIDsMu.Unlock()
}

